-- Generated FCPS-1 Medicine & Allied MCQ import.
-- Source: /home/ameerhamza.exe/Documents/Projects/FCPS MCQ Library
create temporary table fcps_mcq_stage (
  id uuid primary key, subject_name text not null, chapter_name text not null,
  question text not null, options jsonb not null, correct_answer text not null, explanation text not null
) on commit drop;


do $$
declare v_stage integer; v_matched integer; v_chapters integer;
begin
  select count(*) into v_stage from fcps_mcq_stage;
  select count(*), count(distinct c.id) into v_matched, v_chapters
  from fcps_mcq_stage x join public.subjects s on lower(s.name)=lower(
    case
      when x.subject_name='Anatomy Histology Embryology (Paper 1)' and x.chapter_name like '%Histology - %' then 'Histology (Paper 1)'
      when x.subject_name='Anatomy Histology Embryology (Paper 1)' then 'Embryology (Paper 1)'
      when x.subject_name='Anatomy Histology Embryology (Paper 2)' then 'Anatomy (Paper 2)'
      else x.subject_name
    end)
  join public.chapters c on c.subject_id=s.id and (lower(c.name)=lower(x.chapter_name) or lower(to_jsonb(c)->>'original_name')=lower(x.chapter_name))
  where s.year='medicine_allied' and s.institutes=to_jsonb(array['fcps_part_1']::text[]);
  if v_stage<>30772 or v_matched<>30772 or v_chapters<>117 then
    raise exception 'FCPS import mapping failed: stage=%, matched=%, chapters=%', v_stage, v_matched, v_chapters;
  end if;
end $$;

select x.id, x.question, x.options, x.correct_answer, x.explanation, 'fcps1_medicine_allied_2026', c.id, s.name, 'FCPS Part 1'
from fcps_mcq_stage x
join public.subjects s on lower(s.name)=lower(
  case
    when x.subject_name='Anatomy Histology Embryology (Paper 1)' and x.chapter_name like '%Histology - %' then 'Histology (Paper 1)'
    when x.subject_name='Anatomy Histology Embryology (Paper 1)' then 'Embryology (Paper 1)'
    when x.subject_name='Anatomy Histology Embryology (Paper 2)' then 'Anatomy (Paper 2)'
    else x.subject_name
  end)
join public.chapters c on c.subject_id=s.id and (lower(c.name)=lower(x.chapter_name) or lower(to_jsonb(c)->>'original_name')=lower(x.chapter_name))
where s.year='medicine_allied' and s.institutes=to_jsonb(array['fcps_part_1']::text[])
on conflict (id) do update set
  question=excluded.question, options=excluded.options, correct_answer=excluded.correct_answer,
  explanation=excluded.explanation, category=excluded.category, chapter_id=excluded.chapter_id,
  subject=excluded.subject, difficulty=excluded.difficulty;

do $$
declare v_total integer; v_null_year integer; v_wrong_scope integer; v_chapters integer;
begin
  select count(*), count(distinct c.id),
    count(*) filter (where s.year is null),
    count(*) filter (where s.year<>'medicine_allied' or s.institutes<>to_jsonb(array['fcps_part_1']::text[]))
  into v_total, v_chapters, v_null_year, v_wrong_scope
  from public.mcqs m join public.chapters c on c.id=m.chapter_id join public.subjects s on s.id=c.subject_id
  where m.category='fcps1_medicine_allied_2026';
  if v_total<>30772 or v_chapters<>117 or v_null_year<>0 or v_wrong_scope<>0 then
    raise exception 'FCPS import verification failed: total=%, chapters=%, null_year=%, wrong_scope=%', v_total, v_chapters, v_null_year, v_wrong_scope;
  end if;
end $$;
