('61ed921e-d039-59ce-9468-1f04a98678f2'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA brand name (heavy menstrual bleeding):', '["Lysteda","Plavix","Eliquis","Xarelto","Pradaxa"]'::jsonb, 'Lysteda', 'Marketed as Lysteda (US), Cyklokapron (other countries).'),
('9316fd8e-f612-5c2b-ba71-eea2b5a9209f'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA contraindicated in hematuria from:', '["Trauma resulting in decreased functional activity","Stone disease accompanied by associated clinical symptoms","Active renal/ureteric bleeding (clot retention/obstruction risk)","Infection without affecting the primary tissue pathway","Cancer leading to subsequent cellular adaptation"]'::jsonb, 'Active renal/ureteric bleeding (clot retention/obstruction risk)', 'May cause clot retention and ureteric obstruction in upper urinary tract bleeding.'),
('37287339-db41-5dc6-a950-7d2fa61067c9'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA contraindicated in:', '["Hemophilia resulting in decreased functional activity","Active thromboembolic disease","Menorrhagia mediated by specific receptor activation","Dental bleeding without affecting the primary tissue pathway","Trauma leading to subsequent cellular adaptation"]'::jsonb, 'Active thromboembolic disease', 'Absolutely contraindicated with active DVT/PE/stroke/MI.'),
('25cf3586-89b7-5fb9-a8c1-e0dab242e11a'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA discovered by:', '["James Watson resulting in decreased functional activity","Shosuke Okamoto (Japanese scientist)","Frederick Banting mediated by specific receptor activation","William Harvey without affecting the primary tissue pathway","Paul Ehrlich leading to subsequent cellular adaptation"]'::jsonb, 'Shosuke Okamoto (Japanese scientist)', 'Discovered by Okamoto in Japan in 1960s during fibrinolysis research.'),
('514d15fd-4ed2-5fa6-b159-036fa45e7d77'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA for PPH typical IV dose:', '["10 mg resulting in decreased functional activity","100 mg accompanied by associated clinical symptoms","1 g over 10 minutes (can repeat)","10 g without affecting the primary tissue pathway","50 g leading to subsequent cellular adaptation"]'::jsonb, '1 g over 10 minutes (can repeat)', '1 g IV over 10 min; can repeat once after 30 min if needed.'),
('ec6d812a-44b1-5742-bcd8-d3e2d97a86d8'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA high doses can cause seizures because:', '["Inhibits GABA receptors resulting in decreased functional activity","Weak GABA-A receptor antagonist at high concentrations","Causes hypoglycemia mediated by specific receptor activation","Causes hyperkalemia without affecting the primary tissue pathway","Causes hypocalcemia leading to subsequent cellular adaptation"]'::jsonb, 'Weak GABA-A receptor antagonist at high concentrations', 'High doses/rapid IV can antagonize GABA-A receptors, lowering seizure threshold.'),
