('f0774d3b-35d9-532b-a805-b66b1be94e24'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA mouthwash safe in anticoagulated patients because:', '["Absorbed systemically resulting in decreased functional activity","Minimal systemic absorption when used topically","Not effective mediated by specific receptor activation","Only for oral use without affecting the primary tissue pathway","Replaces anticoagulation leading to subsequent cellular adaptation"]'::jsonb, 'Minimal systemic absorption when used topically', 'Minimal systemic absorption from topical oral use.'),
('ad5ffbb7-4e13-5e05-bd82-0a814b4a351e'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'TXA on WHO Essential Medicines List for:', '["Cancer treatment resulting in decreased functional activity","Preventing/treating life-threatening hemorrhage worldwide","Hypertension mediated by specific receptor activation","Diabetes without affecting the primary tissue pathway","Antibiotic therapy leading to subsequent cellular adaptation"]'::jsonb, 'Preventing/treating life-threatening hemorrhage worldwide', 'Critical role in reducing death from hemorrhage globally.'),
