('bc29817a-0c28-587f-91b5-983e03072105'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin narrow therapeutic index important because:', '["Wide index resulting in decreased functional activity","Small level changes cause efficacy/toxicity changes","Long t1/2 only mediated by specific receptor activation","Short t1/2 only without affecting the primary tissue pathway","No interactions leading to subsequent cellular adaptation"]'::jsonb, 'Small level changes cause efficacy/toxicity changes', 'Small changes in levels can cause bleeding or thrombosis.'),
('446599d3-0380-5e09-9715-942ce5a81862'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin narrow therapeutic index means:', '["Very safe resulting in decreased functional activity","Small dose changes cause significant INR changes","Very effective mediated by specific receptor activation","No side effects without affecting the primary tissue pathway","Expensive leading to subsequent cellular adaptation"]'::jsonb, 'Small dose changes cause significant INR changes', 'Narrow: small dose changes = disproportionate INR changes.'),
('42da1354-2cdd-505e-8673-1138455076f8'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin onset delayed because:', '["Poor bioavailability resulting in decreased functional activity","Inhibits new factor synthesis; existing factors must clear","Rapid metabolism mediated by specific receptor activation","Adipose storage without affecting the primary tissue pathway","Needs gastric acid leading to subsequent cellular adaptation"]'::jsonb, 'Inhibits new factor synthesis; existing factors must clear', 'Existing factors must be cleared (factor II t1/2 60-72h explains 3-5 day delay).'),
('4eaad799-70a0-510a-b7c5-d13fc703a840'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin originally developed as:', '["Rat poison/pesticide","Antibiotic","Antiviral","Analgesic","Antihypertensive"]'::jsonb, 'Rat poison/pesticide', 'First developed as rodenticide before clinical use.'),
('dfc23bd8-8c89-5987-87c9-91b918c162ab'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin skin necrosis most common in:', '["Protein C deficiency","Normal protein C","Factor VIII deficiency","Platelet disorders","Liver disease"]'::jsonb, 'Protein C deficiency', 'Protein C deficiency (short t1/2) creates prothrombotic state when started without heparin bridge.'),
('da0c2611-290c-50ad-933d-6cd36ddf129b'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin skin necrosis occurs days:', '["1-2","3-8","14-21","30-60","After 6 months"]'::jsonb, '3-8', 'Days 3-8 when protein C depleted but procoagulant factors remain.'),
('584da046-5ea4-5694-8bfc-3069b2bde8f7'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin skin necrosis typically involves:', '["Face only resulting in decreased functional activity","Extremities and fatty areas (breasts, thighs, buttocks)","Internal organs only mediated by specific receptor activation","Scalp without affecting the primary tissue pathway","Eyes only leading to subsequent cellular adaptation"]'::jsonb, 'Extremities and fatty areas (breasts, thighs, buttocks)', 'Affects extremities and fatty areas where microvascular thrombosis occurs.'),
('b9182ba0-4480-5a63-a248-5c7f6f7c7df6'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin tablet colors indicate:', '["Only white resulting in decreased functional activity","Multiple colors representing different doses","Only blue mediated by specific receptor activation","Only green without affecting the primary tissue pathway","Colorless leading to subsequent cellular adaptation"]'::jsonb, 'Multiple colors representing different doses', 'Color-coded by dose (1mg pink, 2mg lavender, 2.5mg green, 5mg peach, 7.5mg blue, 10mg teal).'),
('2644e8fa-2d3f-5e03-91ff-05cdb010a819'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Warfarin teratogenicity most severe:', '["Weeks 1-5","Weeks 6-12","Weeks 13-27","Weeks 28-40","All equal"]'::jsonb, 'Weeks 6-12', 'Weeks 6-12: nasal hypoplasia, stippled epiphyses, CNS abnormalities.'),
('58777bdc-0e29-53ee-a075-0c03fe82e695'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Which decreases oral iron absorption?', '["Vitamin C","Meat proteins","Calcium and tannins","Fructose","Betaine"]'::jsonb, 'Calcium and tannins', 'Calcium, tannins (tea/coffee), antacids impair iron absorption.'),
('c3e5df43-d84b-5f62-950e-acb65a9f0602'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'Which vitamin enhances oral iron absorption?', '["Vitamin A","Vitamin B12","Vitamin C (ascorbic acid)","Vitamin D","Vitamin E"]'::jsonb, 'Vitamin C (ascorbic acid)', 'Vitamin C reduces Fe3+ to Fe2+ (absorbable form).'),
('2b7d38f8-4fb2-545c-abcb-cb443181a329'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'aPTT measures:', '["Extrinsic pathway resulting in decreased functional activity","Intrinsic pathway (XII, XI, IX, VIII, X, V, II, I)","Common only mediated by specific receptor activation","Platelets without affecting the primary tissue pathway","Fibrinolysis leading to subsequent cellular adaptation"]'::jsonb, 'Intrinsic pathway (XII, XI, IX, VIII, X, V, II, I)', 'Measures intrinsic and common pathways; used for heparin monitoring.'),
('085c5ff4-af47-5e11-a0dd-4260fd225425'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'aPTT most sensitive to deficiency of:', '["Factors VII and V resulting in decreased functional activity","Factors XII, XI, IX, VIII (intrinsic pathway)","Factors II and I only mediated by specific receptor activation","All equally without affecting the primary tissue pathway","Platelet count leading to subsequent cellular adaptation"]'::jsonb, 'Factors XII, XI, IX, VIII (intrinsic pathway)', 'Most sensitive to intrinsic pathway factors XII, XI, IX, VIII.'),
('2d6c0aa7-70c6-53cd-a9ce-8aec7472d4c4'::uuid, 'Pharmacology (Paper 2)', 'Hematologic Coagulation - Hematologic Drugs', 'aPTT prolonged with heparin because heparin enhances:', '["Factor VII resulting in decreased functional activity","Antithrombin III (inhibiting XII, XI, IX, VIII, X, V, II)","Protein C mediated by specific receptor activation","Protein S without affecting the primary tissue pathway","Vitamin K leading to subsequent cellular adaptation"]'::jsonb, 'Antithrombin III (inhibiting XII, XI, IX, VIII, X, V, II)', 'Enhances AT III activity inhibiting intrinsic pathway factors.'),
('e20d925e-fc3e-5b43-8610-dd7561e40325'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine primarily acts by inhibiting which enzyme?', '["Tyrosine kinase","Calcineurin","Phosphodiesterase","Adenylyl cyclase","Protein kinase C"]'::jsonb, 'Calcineurin', 'Cyclosporine binds cyclophilin and the complex inhibits calcineurin, preventing IL-2 transcription and T-cell activation.'),
('494175fa-464d-5c86-8a41-871ebb52e473'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine is most commonly used for prophylaxis of which type of rejection?', '["Hyperacute rejection","Acute cellular rejection","Chronic vascular rejection","Antibody-mediated rejection","Accelerated rejection"]'::jsonb, 'Acute cellular rejection', 'Cyclosporine is a cornerstone of immunosuppressive regimens for preventing acute cellular rejection in organ transplantation.'),
('71851394-164c-521b-b124-fada529cb66b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is a major dose-limiting adverse effect of cyclosporine?', '["Bone marrow suppression","Nephrotoxicity","Hepatotoxicity","Pulmonary fibrosis","Pancreatitis"]'::jsonb, 'Nephrotoxicity', 'Cyclosporine causes dose-dependent nephrotoxicity due to afferent arteriolar vasoconstriction and chronic tubulointerstitial damage.'),
('55659cd3-3b5d-570e-b49e-6a787b400afa'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine increases the risk of which metabolic complication?', '["Hypoglycemia","Hypocalcemia","Hyperlipidemia","Hypokalemia","Metabolic acidosis"]'::jsonb, 'Hyperlipidemia', 'Cyclosporine commonly causes hyperlipidemia and hypertension as metabolic side effects.'),
('cf749705-99a2-594a-a3a9-07c053e0bff0'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine should be used cautiously with which of the following drugs due to increased nephrotoxicity?', '["Metformin","NSAIDs","Amoxicillin","Paracetamol","Omeprazole"]'::jsonb, 'NSAIDs', 'NSAIDs reduce renal prostaglandin synthesis and when combined with cyclosporine significantly increase nephrotoxicity risk.'),
('fce79aed-cce5-584f-98c8-6031c1177e40'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is a clinical use of cyclosporine other than transplantation?', '["Type 1 diabetes","Severe rheumatoid arthritis","Hypertension","Osteoporosis","Gout"]'::jsonb, 'Severe rheumatoid arthritis', 'Cyclosporine is approved as a disease-modifying agent for severe rheumatoid arthritis refractory to other treatments.'),
('a7abbc7f-23bb-5ab2-a39f-e3188b9dd221'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine is contraindicated in which of the following?', '["Rheumatoid arthritis","Psoriasis","Uncontrolled hypertension","Nephrotic syndrome","Ulcerative colitis"]'::jsonb, 'Uncontrolled hypertension', 'Cyclosporine causes hypertension as a side effect and is therefore contraindicated in patients with uncontrolled hypertension.'),
('62a2967d-1d70-5e6d-986e-fffc55ee509c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine therapeutic drug monitoring primarily measures which form?', '["Free cyclosporine only","Trough whole blood levels","Peak plasma levels","Urinary concentration","Salivary concentration"]'::jsonb, 'Trough whole blood levels', 'Cyclosporine trough whole blood levels are routinely monitored to ensure therapeutic efficacy and minimize toxicity.'),
('b6b8284a-bfac-5db7-8534-833582b22813'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which antifungal drug increases cyclosporine levels by inhibiting CYP3A4?', '["Amphotericin B","Fluconazole","Griseofulvin","Nystatin","Terbinafine"]'::jsonb, 'Fluconazole', 'Azole antifungals including fluconazole inhibit CYP3A4, increasing cyclosporine levels and risk of toxicity.'),
('fe5a127f-feb1-579d-8279-bdeacf4e00d7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Gingival hyperplasia is a recognized side effect of which immunosuppressant?', '["Azathioprine","Mycophenolate mofetil","Cyclosporine","Sirolimus","Tacrolimus"]'::jsonb, 'Cyclosporine', 'Gingival hyperplasia and hirsutism are characteristic side effects of cyclosporine therapy.'),
('eee91fce-faff-5988-aafe-d1601138e477'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine is metabolized primarily by which cytochrome P450 enzyme?', '["CYP1A2","CYP2C9","CYP2D6","CYP3A4","CYP2E1"]'::jsonb, 'CYP3A4', 'Cyclosporine is extensively metabolized by CYP3A4 in the liver and intestinal wall.'),
('bbef20b3-fc8d-50cb-89d0-96187fe2d1b4'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the half-life of cyclosporine?', '["6-8 hours","10-14 hours","19-27 hours","30-40 hours","60-70 hours"]'::jsonb, '19-27 hours', 'Cyclosporine has a half-life of approximately 19-27 hours, prolonged in hepatic impairment.'),
('61338b76-0a7e-5620-8343-69150d08ebad'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine nephrotoxicity can be differentiated from rejection by:', '["Serum creatinine level","Trough drug levels and renal biopsy","Blood pressure measurement","Urine output","Patient symptoms only"]'::jsonb, 'Trough drug levels and renal biopsy', 'Elevated cyclosporine trough levels suggest drug nephrotoxicity, while biopsy shows different histological patterns.'),
('c8c3e4a8-4ac6-5981-9405-7a050d599217'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cyclosporine ophthalmic emulsion (Restasis) is used for:', '["Glaucoma","Chronic dry eye disease","Conjunctivitis","Cataracts","Macular degeneration"]'::jsonb, 'Chronic dry eye disease', 'Cyclosporine ophthalmic emulsion increases tear production in chronic dry eye disease by reducing ocular surface inflammation.'),
('aefc69f2-45e6-5962-99c5-a9bb0ade0a1e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tacrolimus binds to which intracellular immunophilin?', '["Cyclophilin","FKBP12","Calmodulin","14-3-3 protein","Heat shock protein 90"]'::jsonb, 'FKBP12', 'Tacrolimus (FK506) binds FKBP12 and the complex inhibits calcineurin, blocking T-cell activation.'),
('83943c38-5ffb-54b8-8e2c-c0144d1b2070'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Compared to cyclosporine, tacrolimus is approximately how many times more potent?', '["2 times","5 times","10-100 times","1000 times","Equal potency"]'::jsonb, '10-100 times', 'Tacrolimus is 10-100 times more potent than cyclosporine as an immunosuppressant.'),
('d50e5127-0259-5935-aaeb-654ddb402872'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is a common adverse effect of tacrolimus that differs from cyclosporine?', '["Gingival hyperplasia","Hirsutism","New-onset diabetes mellitus","Hyperkalemia","Hyperuricemia"]'::jsonb, 'New-onset diabetes mellitus', 'Tacrolimus is diabetogenic and can cause new-onset diabetes after transplant (NODAT), unlike cyclosporine.'),
('49a4732f-48e1-5ff4-8459-2c6b8fc9c1cf'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tacrolimus shares which dose-limiting toxicity with cyclosporine?', '["Hepatotoxicity","Pulmonary toxicity","Nephrotoxicity","Cardiotoxicity","Neurotoxicity"]'::jsonb, 'Nephrotoxicity', 'Both tacrolimus and cyclosporine cause nephrotoxicity through renal vasoconstriction and chronic tubulointerstitial damage.'),
('d3e3ef69-9a7c-521b-9ea3-4d446221bb99'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which neurotransmitter-like side effect is more common with tacrolimus than cyclosporine?', '["Seizures","Tremor and headache","Coma","Peripheral neuropathy","Paralysis"]'::jsonb, 'Tremor and headache', 'Tacrolimus more commonly causes neurotoxicity including tremor, headache, and insomnia compared to cyclosporine.'),
('a0232acd-cbfc-516d-96ce-693f557846a8'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tacrolimus is metabolized primarily by which cytochrome P450 enzyme?', '["CYP1A2","CYP2C9","CYP2D6","CYP3A4","CYP2E1"]'::jsonb, 'CYP3A4', 'Tacrolimus is extensively metabolized by CYP3A4 in the liver and intestinal wall.'),
('cb3b8ada-3b16-53fe-9399-559f71fce852'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which macrolide antibiotic increases tacrolimus levels?', '["Azithromycin","Clarithromycin","Erythromycin","Both B and C","None of the above"]'::jsonb, 'Both B and C', 'Clarithromycin and erythromycin are potent CYP3A4 inhibitors that significantly increase tacrolimus levels.'),
('e3d27b44-d84f-53ba-ab3f-1f91174bbd7a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the main advantage of tacrolimus over cyclosporine in kidney transplantation?', '["Lower cost","No nephrotoxicity","Lower incidence of acute rejection episodes","No drug interactions","Better oral bioavailability"]'::jsonb, 'Lower incidence of acute rejection episodes', 'Tacrolimus-based regimens show lower rates of acute rejection compared to cyclosporine-based regimens.'),
('5096d57c-85f2-5804-8663-89dacea3c7d7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tacrolimus ointment (Protopic) is used topically for which condition?', '["Psoriasis","Atopic dermatitis","Seborrheic dermatitis","Contact dermatitis","Fungal infection"]'::jsonb, 'Atopic dermatitis', 'Tacrolimus ointment is a topical calcineurin inhibitor approved for moderate-to-severe atopic dermatitis.'),
('869a7951-c92e-5a30-a20b-666d293c700d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which topical calcineurin inhibitor is available for atopic dermatitis?', '["Cyclosporine ointment","Tacrolimus ointment","Sirolimus cream","MMF gel","Azathioprine cream"]'::jsonb, 'Tacrolimus ointment', 'Tacrolimus (Protopic) and pimecrolimus (Elidel) are topical calcineurin inhibitors for atopic dermatitis.'),
('328986ce-8c0b-5db6-8bc1-f37e3e8ae520'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Mycophenolate mofetil (MMF) inhibits which enzyme in purine synthesis?', '["Adenosine deaminase","Inosine monophosphate dehydrogenase (IMPDH)","Hypoxanthine-guanine phosphoribosyltransferase","Xanthine oxidase","Ribonucleotide reductase"]'::jsonb, 'Inosine monophosphate dehydrogenase (IMPDH)', 'MMF is a prodrug of mycophenolic acid which selectively inhibits IMPDH type II, blocking de novo guanine nucleotide synthesis in lymphocytes.'),
('9d174257-0adf-5144-ae12-8500de2d3fd0'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'MMF is selectively toxic to lymphocytes because they rely primarily on which pathway for purine synthesis?', '["Salvage pathway","De novo pathway","Pentose phosphate pathway","Glycolysis","Krebs cycle"]'::jsonb, 'De novo pathway', 'Lymphocytes depend almost exclusively on the de novo purine synthesis pathway, making them uniquely susceptible to IMPDH inhibition.'),
('b9d39f23-cb91-5cc5-a740-306e345d083f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is the most common dose-limiting adverse effect of MMF?', '["Nephrotoxicity","Hepatotoxicity","Gastrointestinal disturbances","Cardiotoxicity","Pulmonary fibrosis"]'::jsonb, 'Gastrointestinal disturbances', 'GI side effects including diarrhea, nausea, and abdominal pain are the most common adverse effects limiting MMF dose.'),
('17a04736-1211-5bf9-b584-ec088344538b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'MMF is used in combination with which of the following as part of standard triple immunosuppression?', '["Cyclosporine or tacrolimus plus corticosteroids","Azathioprine alone accompanied by associated clinical symptoms","Sirolimus alone mediated by specific receptor activation","Belimumab without affecting the primary tissue pathway","Alemtuzumab leading to subsequent cellular adaptation"]'::jsonb, 'Cyclosporine or tacrolimus plus corticosteroids', 'Standard triple immunosuppression consists of a calcineurin inhibitor, MMF, and corticosteroids.'),
('c41fcc59-8cac-51f8-b67a-d5a01902bb39'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'MMF is contraindicated in which condition?', '["Diabetes mellitus","Pregnancy","Hypertension","Hypothyroidism","Asthma"]'::jsonb, 'Pregnancy', 'MMF is teratogenic (FDA category D) and is contraindicated in pregnancy due to risk of first trimester pregnancy loss and congenital malformations.'),
('5f48c3b0-776b-5648-a513-5c024e18284c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'MMF can be replaced by which alternative for patients with GI intolerance?', '["Enteric-coated mycophenolate sodium","Azathioprine accompanied by associated clinical symptoms","Cyclophosphamide mediated by specific receptor activation","Leflunomide without affecting the primary tissue pathway","Methotrexate leading to subsequent cellular adaptation"]'::jsonb, 'Enteric-coated mycophenolate sodium', 'Enteric-coated mycophenolate sodium (myfortic) releases drug in the intestine, reducing upper GI side effects.'),
('6a4eb8a7-b9f7-56a3-be2e-4db6a328540e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which laboratory value should be monitored in patients on MMF?', '["Serum creatinine only","Complete blood count","Liver function tests only","Lipid profile only","Blood glucose only"]'::jsonb, 'Complete blood count', 'MMF causes bone marrow suppression leading to leukopenia, anemia, and thrombocytopenia, requiring regular CBC monitoring.'),
('65b0e7ed-ea0e-51fe-8fe1-00df00a29279'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'MMF should be taken with food to:', '["Increase absorption","Reduce GI side effects","Decrease metabolism","Increase bioavailability","Prevent nausea"]'::jsonb, 'Reduce GI side effects', 'Taking MMF with food reduces peak plasma levels and decreases GI side effects.'),
('0dcfe9a2-9ba8-54ed-be36-b63963b2c049'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Mycophenolate mofetil is a prodrug of which active compound?', '["6-mercaptopurine","Mycophenolic acid","Azathioprine","Leflunomide active metabolite","Sirolimus"]'::jsonb, 'Mycophenolic acid', 'MMF is hydrolyzed to mycophenolic acid, the active IMPDH inhibitor.'),
('e770d4ac-9630-5f06-8f31-3e5f425d779a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which immunosuppressant is considered teratogenic and should be stopped before conception?', '["Tacrolimus","Mycophenolate mofetil","Azathioprine","Prednisolone","Cyclosporine"]'::jsonb, 'Mycophenolate mofetil', 'MMF is teratogenic (FDA Category D) and must be discontinued at least 6 weeks before conception.'),
('1ab64a26-4403-5aab-85ac-ec91bcdb4c67'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Azathioprine is a prodrug converted to which active metabolite?', '["6-mercaptopurine (6-MP)","6-thioguanine","Methotrexate","Mycophenolic acid","Leflunomide"]'::jsonb, '6-mercaptopurine (6-MP)', 'Azathioprine is non-enzymatically converted to 6-MP, which inhibits purine synthesis via TIMP.'),
('0b7b7b87-9ceb-5f62-a05c-537c514aeb99'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Patients with which genetic polymorphism are at increased risk of severe azathioprine toxicity?', '["CYP2D6 poor metabolizer","TPMT deficiency","CYP3A4 rapid metabolizer","NAT2 slow acetylator","UGT1A1*28"]'::jsonb, 'TPMT deficiency', 'TPMT metabolizes thiopurines. TPMT-deficient patients accumulate toxic 6-thioguanine nucleotides, causing severe myelosuppression.'),
('1a2df097-2ea4-51fe-9d5d-274c46a8bbaa'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following drugs should NOT be given with azathioprine?', '["Allopurinol","Omeprazole","Metformin","Amlodipine","Atorvastatin"]'::jsonb, 'Allopurinol', 'Allopurinol inhibits xanthine oxidase which metabolizes 6-MP. Combined use causes severe myelosuppression; azathioprine dose must be reduced by 75%.'),
('dc56b95f-e721-59c6-aa3e-698e5160dabc'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Azathioprine belongs to which class of immunosuppressants?', '["Calcineurin inhibitors","mTOR inhibitors","Antimetabolites","Corticosteroids","Biological agents"]'::jsonb, 'Antimetabolites', 'Azathioprine is a purine antimetabolite that inhibits DNA and RNA synthesis in rapidly dividing cells including lymphocytes.'),
('bbc8fed3-4e64-519b-8de1-dcb59e0577dc'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is an indication for azathioprine besides transplantation?', '["SLE with renal involvement","Hypertension","Type 1 diabetes","Osteoarthritis","COPD"]'::jsonb, 'SLE with renal involvement', 'Azathioprine is a steroid-sparing agent used in SLE, autoimmune hepatitis, myasthenia gravis, and inflammatory bowel disease.'),
('94f0050d-2215-5157-922b-ec673aaaaece'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the most serious hematologic toxicity of azathioprine?', '["Iron deficiency anemia","Megaloblastic anemia","Pancytopenia","Polycythemia","Thrombocytosis"]'::jsonb, 'Pancytopenia', 'Azathioprine can cause dose-dependent bone marrow suppression manifesting as pancytopenia, especially in TPMT-deficient patients.'),
('e0d94b67-bb41-5efd-8b56-d960a17f813c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which enzyme converts azathioprine to 6-mercaptopurine?', '["CYP3A4","Xanthine oxidase","Glutathione S-transferase","Non-enzymatic cleavage","TPMT"]'::jsonb, 'Non-enzymatic cleavage', 'Azathioprine is converted to 6-MP by non-enzymatic cleavage of the imidazole ring.'),
('81ae350d-47c5-590c-ab0c-a878b01adc0a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which laboratory monitoring is essential for patients on azathioprine?', '["Serum drug levels","Complete blood count and TPMT genotyping","Liver function tests only","Lipid profile","Coagulation profile"]'::jsonb, 'Complete blood count and TPMT genotyping', 'CBC monitoring for myelosuppression and TPMT genotyping before initiation are essential for safe azathioprine use.'),
('2645d1ee-00a9-59a0-b344-8785d3c86e7d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which drug interaction is important when using azathioprine with warfarin?', '["Increased warfarin effect","Decreased warfarin effect","No interaction","Increased azathioprine levels","Decreased azathioprine levels"]'::jsonb, 'Decreased warfarin effect', 'Azathioprine may decrease the anticoagulant effect of warfarin, requiring INR monitoring.'),
('302abaf6-1b07-57ff-a2db-b6157ae9d236'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Sirolimus inhibits which intracellular signaling pathway?', '["JAK-STAT pathway","NF-kB pathway","mTOR pathway","MAP kinase pathway","PI3K-Akt pathway"]'::jsonb, 'mTOR pathway', 'Sirolimus binds FKBP12 and this complex inhibits mTOR, blocking cytokine-driven T-cell proliferation.'),
('acd104d4-ebd0-5aae-ae3f-4aec02ee2d41'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Unlike calcineurin inhibitors, sirolimus acts at which phase of the cell cycle?', '["G0 to G1 transition","G1 to S phase transition","S to G2 phase transition","G2 to M phase transition","M phase"]'::jsonb, 'G1 to S phase transition', 'Sirolimus blocks the progression from G1 to S phase by inhibiting mTOR-mediated ribosomal protein synthesis.'),
('c48009db-6750-58d5-b3e6-ae39150cfab8'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which side effect is more common with sirolimus than with calcineurin inhibitors?', '["Nephrotoxicity","Hyperlipidemia","Neurotoxicity","Diabetes","Hypertension"]'::jsonb, 'Hyperlipidemia', 'Sirolimus causes significant hyperlipidemia (elevated triglycerides and cholesterol), which is dose-dependent.'),
('1d67520c-8ee1-5594-add2-fd884ec3eee7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Sirolimus has which advantage over calcineurin inhibitors in transplantation?', '["Greater potency","No nephrotoxicity","Lower cost","Fewer drug interactions","Better oral bioavailability"]'::jsonb, 'No nephrotoxicity', 'Sirolimus is not nephrotoxic and may even be renoprotective when used as CNI-sparing agent.'),
('a482ce2b-f47f-5c9b-9135-94bc145062e9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Sirolimus impairs which of the following healing processes?', '["Wound healing","Bone healing","Both A and B","Neither A nor B","Neural healing"]'::jsonb, 'Both A and B', 'Sirolimus impairs wound and bone healing due to inhibition of mTOR-mediated cell proliferation and angiogenesis.'),
('5d796a1e-4bd8-57a3-a7b5-cc9e03753726'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Sirolimus is used in drug-eluting stents to prevent which complication?', '["Stent thrombosis","In-stent restenosis","Coronary spasm","Arterial dissection","Aneurysm formation"]'::jsonb, 'In-stent restenosis', 'Drug-eluting stents coated with sirolimus inhibit smooth muscle cell proliferation, preventing in-stent restenosis.'),
('cf03df51-8d25-5ff8-8d88-9496eb8fefb0'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Sirolimus is more commonly associated with which pulmonary complication?', '["Pulmonary embolism","Drug-induced pneumonitis","Pulmonary edema","Pulmonary fibrosis","Bronchospasm"]'::jsonb, 'Drug-induced pneumonitis', 'Sirolimus can cause interstitial pneumonitis, which is an important and potentially serious pulmonary adverse effect.'),
('61e53201-04ff-5632-b610-754efc33e719'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the loading dose strategy for sirolimus in transplantation?', '["No loading dose needed","Single large loading dose followed by maintenance","Gradual dose titration only","High dose for 3 days then stop","Loading dose is contraindicated"]'::jsonb, 'Single large loading dose followed by maintenance', 'Due to sirolimus''s long half-life (62 hours), a loading dose is often given to achieve therapeutic levels quickly.'),
('399c2728-294c-5f9d-ac38-ea0ee225931e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Sirolimus combined with cyclosporine can worsen which toxicity?', '["Hepatotoxicity","Nephrotoxicity","Pulmonary toxicity","Neurotoxicity","Cardiotoxicity"]'::jsonb, 'Nephrotoxicity', 'The combination of sirolimus and cyclosporine is synergistically nephrotoxic.'),
('8725b21e-cd2a-5337-8299-b6f8e56da3e4'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which combination in transplantation is specifically avoided due to increased nephrotoxicity?', '["Tacrolimus + MMF","Cyclosporine + sirolimus","Tacrolimus + prednisolone","Cyclosporine + prednisolone","MMF + prednisolone"]'::jsonb, 'Cyclosporine + sirolimus', 'Cyclosporine and sirolimus together cause synergistic nephrotoxicity.'),
('f8e01e9c-9f1c-57dc-a972-6166d955c1b9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Corticosteroids suppress the immune system primarily by inhibiting which transcription factor?', '["NFAT","NF-kB and AP-1","STAT3","HIF-1alpha","FOXO1"]'::jsonb, 'NF-kB and AP-1', 'Corticosteroids inhibit NF-kB and AP-1, reducing transcription of pro-inflammatory cytokines.'),
('0d3c0bed-44d0-588e-9faa-a612b6b04f3a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'In transplantation, what is the typical role of corticosteroids?', '["Used alone for maintenance","Induction and maintenance immunosuppression","Used only for rejection episodes","Contraindicated","Used only in liver transplantation"]'::jsonb, 'Induction and maintenance immunosuppression', 'Corticosteroids are used both for induction (pulse therapy) and as part of maintenance immunosuppression.'),
('bec9890b-aaca-50ff-ae2e-1301a1788781'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is the most common metabolic side effect of chronic corticosteroid use?', '["Hyperthyroidism","Osteoporosis","Hypoglycemia","Hypocalcemia","Hyperkalemia"]'::jsonb, 'Osteoporosis', 'Chronic corticosteroid use causes osteoporosis through decreased osteoblast activity, increased osteoclast activity, and decreased calcium absorption.'),
('0f4e1499-4acd-508b-bb29-7e4e8e910129'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Pulse methylprednisolone therapy for acute rejection typically uses what dose?', '["5-10 mg/day","20-30 mg/day","500-1000 mg IV for 3 days","100 mg PO daily","10 mg IV weekly"]'::jsonb, '500-1000 mg IV for 3 days', 'Pulse methylprednisolone (500-1000 mg IV daily for 3 days) is the standard treatment for acute cellular rejection.'),
('824d2693-8781-5814-9ef1-b1b8a5974826'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Corticosteroids cause which electrolyte abnormality?', '["Hypokalemia and metabolic alkalosis","Hyperkalemia and metabolic acidosis","Hypocalcemia","Hyponatremia","Hyperphosphatemia"]'::jsonb, 'Hypokalemia and metabolic alkalosis', 'Corticosteroids have mineralocorticoid activity causing sodium retention, potassium wasting, and metabolic alkalosis.'),
('51c4881d-987a-542f-b528-deae3013d7b5'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is NOT a side effect of long-term corticosteroid therapy?', '["Cushing syndrome","Adrenal suppression","Peptic ulcers","Hypoglycemia","Proximal myopathy"]'::jsonb, 'Hypoglycemia', 'Corticosteroids cause hyperglycemia (not hypoglycemia) through gluconeogenesis and insulin resistance.'),
('71edc479-25d5-59f0-b348-d2157d5c51e5'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Steroid-sparing agents are added to corticosteroid regimens to achieve which goal?', '["Increase immunosuppression","Reduce steroid dose and associated toxicity","Replace steroids entirely","Increase infection risk","Improve absorption"]'::jsonb, 'Reduce steroid dose and associated toxicity', 'Steroid-sparing agents allow reduction of corticosteroid dose, minimizing long-term metabolic and bone complications.'),
('d5358c25-09c9-57bc-9edc-184da141da16'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'In which condition is dexamethasone a first-line treatment due to its immunosuppressive effect?', '["Mild asthma","Cerebral edema from brain tumors","Seasonal allergic rhinitis","Contact dermatitis","Rheumatoid arthritis"]'::jsonb, 'Cerebral edema from brain tumors', 'Dexamethasone is the corticosteroid of choice for cerebral edema due to brain tumors because it has minimal mineralocorticoid effect and good CNS penetration.'),
('5362c4df-766d-55d2-b076-d49f50663feb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Corticosteroids increase risk of which opportunistic fungal infection?', '["Tinea corporis","Pneumocystis jirovecii pneumonia","Aspergillosis and mucormycosis","Onychomycosis","Candidiasis only"]'::jsonb, 'Aspergillosis and mucormycosis', 'High-dose corticosteroids impair cell-mediated immunity, increasing risk of invasive fungal infections.'),
('fc745732-955f-53f2-a30e-606b1ad40b33'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Corticosteroids should be given in the morning to mimic which physiological rhythm?', '["Aldosterone rhythm","Cortisol circadian rhythm","Thyroxine rhythm","Growth hormone rhythm","Melatonin rhythm"]'::jsonb, 'Cortisol circadian rhythm', 'Morning dosing mimics the natural cortisol circadian rhythm, minimizing HPA axis suppression.'),
('5921c428-eaa2-56db-abb7-36c9b73055c7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Corticosteroid withdrawal syndrome (adrenal insufficiency) occurs when steroids are stopped abruptly after:', '["1 week of use","2-3 weeks of use","1 day of use","Only after years","Never occurs"]'::jsonb, '2-3 weeks of use', 'HPA axis suppression can occur after 2-3 weeks of corticosteroid use, causing adrenal insufficiency if stopped abruptly.'),
('d45afede-b8bf-56cd-9bc8-c4359ad6cf7a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which antifungal drug interaction is important with cyclosporine?', '["Nystatin increases cyclosporine levels","Fluconazole increases cyclosporine levels","Terbinafine decreases cyclosporine levels","Griseofulvin has no interaction","Amphotericin B decreases cyclosporine levels"]'::jsonb, 'Fluconazole increases cyclosporine levels', 'Fluconazole and other azoles inhibit CYP3A4, increasing cyclosporine levels and risk of nephrotoxicity.'),
('b192321e-897d-5fc1-b79c-e3ee2352cc31'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which macrolide antibiotic is safe to use with cyclosporine?', '["Erythromycin","Clarithromycin","Azithromycin","Roxithromycin","Telithromycin"]'::jsonb, 'Azithromycin', 'Azithromycin has minimal CYP3A4 inhibition and is the safest macrolide to use with cyclosporine or tacrolimus.'),
('9c1a2e68-1af4-53e0-b5dc-efc1470d5c7f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Infliximab is a monoclonal antibody of which class?', '["Fully human IgG1","Chimeric (mouse/human) IgG1","Humanized IgG4","Murine IgG2a","Rabbit IgG"]'::jsonb, 'Chimeric (mouse/human) IgG1', 'Infliximab is a chimeric monoclonal antibody consisting of mouse variable regions fused to human IgG1 constant regions.'),
('d6ef49df-ad8a-54cb-8c04-ef5e9370177f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Infliximab binds to which cytokine?', '["IL-1","IL-6","TNF-alpha","IL-17","IL-23"]'::jsonb, 'TNF-alpha', 'Infliximab is a TNF-alpha inhibitor that binds both soluble and transmembrane forms of TNF-alpha.'),
('1eae30ac-8747-54ea-9b12-5e35f648aeaf'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is an indication for infliximab?', '["Osteoarthritis","Crohn disease","Gout","Hypertension","Diabetes"]'::jsonb, 'Crohn disease', 'Infliximab is approved for Crohn disease, ulcerative colitis, rheumatoid arthritis, ankylosing spondylitis, psoriatic arthritis, and plaque psoriasis.'),
('2d36af5f-8cbf-5150-9b9e-5a2675a5cf9f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Before starting infliximab, which infection must be screened for?', '["Hepatitis A","Tuberculosis","Influenza","Chlamydia","Malaria"]'::jsonb, 'Tuberculosis', 'TNF-alpha is critical for granuloma formation. Anti-TNF therapy can reactivate latent TB, so screening is mandatory.'),
('c326eee6-95e0-57cd-abc7-36025333ed51'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Adalimumab differs from infliximab in which way?', '["Adalimumab is chimeric","Adalimumab is fully human","Adalimumab targets IL-6","Adalimumab is given IV only","Adalimumab targets CD20"]'::jsonb, 'Adalimumab is fully human', 'Adalimumab is a fully human IgG1 monoclonal anti-TNF antibody, resulting in lower immunogenicity compared to chimeric infliximab.'),
('98a7095a-277f-5d31-af9e-a3684e6ec3a1'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Etanercept differs from infliximab in its molecular structure because etanercept is:', '["A chimeric antibody","A soluble TNF receptor fusion protein","A humanized antibody","A PEGylated Fab fragment","A small molecule"]'::jsonb, 'A soluble TNF receptor fusion protein', 'Etanercept is a fusion protein of two extracellular domains of TNFR2 (p75) linked to the Fc portion of human IgG1.'),
('942ccf5d-8ee0-5207-8883-751e0dcafc59'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which anti-TNF agent is effective in granulomatous infections like Crohn disease?', '["Etanercept","Infliximab","Both A and B equally","Neither","Certolizumab only"]'::jsonb, 'Infliximab', 'Infliximab is effective in Crohn disease while etanercept is not, likely because infliximab induces apoptosis of TNF-producing macrophages.'),
('98bdf4a5-93a4-5fbc-b7cd-a1aa8f2b8b47'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Rituximab targets which cell surface antigen?', '["CD3 on T cells","CD20 on B cells","CD4 on helper T cells","CD8 on cytotoxic T cells","CD56 on NK cells"]'::jsonb, 'CD20 on B cells', 'Rituximab is a chimeric anti-CD20 monoclonal antibody that depletes B cells through CDC and ADCC.'),
('91177e48-2d11-558a-a0d6-005562aeaf75'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Rituximab is used in which of the following autoimmune conditions?', '["Rheumatoid arthritis","Granulomatosis with polyangiitis","Both A and B","Type 1 diabetes","Osteoarthritis"]'::jsonb, 'Both A and B', 'Rituximab is approved for both rheumatoid arthritis and granulomatosis with polyangiitis (Wegener granulomatosis).'),
('897f3c4f-d090-5d1d-8abc-2a1449225662'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Abatacept (CTLA4-Ig) inhibits T-cell activation by blocking which interaction?', '["CD40-CD40L","CD80/CD86-CD28 costimulation","CTLA-4-B7","PD-1-PD-L1","LFA-1-ICAM-1"]'::jsonb, 'CD80/CD86-CD28 costimulation', 'Abatacept is a CTLA-4-Ig fusion protein that binds CD80/CD86, preventing costimulatory signal to T cells via CD28.'),
('8e74124c-fdcf-5793-99a1-007ccc4d2f3a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which monoclonal antibody is PEGylated and has no Fc-mediated effector functions?', '["Infliximab","Adalimumab","Certolizumab pegol","Rituximab","Golimumab"]'::jsonb, 'Certolizumab pegol', 'Certolizumab pegol is a PEGylated Fab fragment that lacks the Fc region, so it has no complement fixation or ADCC activity.'),
('749428b3-f214-547a-9a4e-a855d7490916'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'All TNF inhibitors share which major risk?', '["Hepatotoxicity resulting in decreased functional activity","Increased risk of serious infections including TB reactivation","Nephrotoxicity mediated by specific receptor activation","Pancreatitis without affecting the primary tissue pathway","Cardiomyopathy leading to subsequent cellular adaptation"]'::jsonb, 'Increased risk of serious infections including TB reactivation', 'All TNF inhibitors increase risk of serious bacterial, fungal, and opportunistic infections, including reactivation of latent tuberculosis.'),
('b1d7579d-192c-593a-87ed-cd07b413bd33'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following biologics is administered as an IV infusion?', '["Adalimumab","Etanercept","Infliximab","Abatacept SC","Certolizumab"]'::jsonb, 'Infliximab', 'Infliximab is administered as an IV infusion at 0, 2, and 6 weeks, then every 8 weeks.'),
('ca3c04fa-a23e-5ed4-b0d6-2ad2d068d088'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Rituximab adverse effects include which infusion-related reaction?', '["Anaphylaxis only resulting in decreased functional activity","Cytokine release syndrome with fever, chills, hypotension","Rash only mediated by specific receptor activation","Headache only without affecting the primary tissue pathway","No infusion reactions occur leading to subsequent cellular adaptation"]'::jsonb, 'Cytokine release syndrome with fever, chills, hypotension', 'Rituximab commonly causes infusion reactions including fever, chills, rigors, hypotension, and bronchospasm.'),
('76d667d9-b9f7-5813-9249-64e21888d395'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which serious viral infection can reactivate with rituximab therapy?', '["Hepatitis B","Influenza","Rhinovirus","Adenovirus","RSV"]'::jsonb, 'Hepatitis B', 'Rituximab causes B-cell depletion and can lead to hepatitis B reactivation. HBV screening before initiation is essential.'),
('52ba0ca9-c000-56a9-97a2-f55e87e4435e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is NOT an anti-TNF biologic?', '["Infliximab","Adalimumab","Rituximab","Etanercept","Golimumab"]'::jsonb, 'Rituximab', 'Rituximab targets CD20 on B cells, not TNF-alpha. All other options are TNF inhibitors.'),
('c717c90e-5312-59ff-b06b-ad28e156e20b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent is contraindicated in active hepatitis B infection?', '["Adalimumab","Rituximab","Both A and B","Etanercept","Abatacept"]'::jsonb, 'Both A and B', 'Both anti-TNF agents and rituximab carry risk of hepatitis B reactivation.'),
('f2ce7924-4d7c-5ffa-b553-249235f8b46c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent carries risk of progressive multifocal leukoencephalopathy (PML)?', '["Adalimumab","Rituximab","Etanercept","Abatacept","Infliximab"]'::jsonb, 'Rituximab', 'Rituximab carries a risk of PML due to JC virus reactivation in the setting of B-cell depletion.'),
('0ac72e4f-75d5-5789-9ab8-60104ff8f95f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which anti-TNF agent is available as a subcutaneous injection every 4 weeks?', '["Infliximab","Adalimumab","Etanercept","Golimumab","All of the above"]'::jsonb, 'Golimumab', 'Golimumab is a fully human anti-TNF given SC monthly (every 4 weeks).'),
('4800f5d5-a7b7-5a1e-b912-2b4dc1802df6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Combining a biologic with an immunomodulator (e.g., azathioprine with infliximab) reduces:', '["Infection risk resulting in decreased functional activity","Immunogenicity (anti-drug antibody formation)","Drug levels mediated by specific receptor activation","Side effects without affecting the primary tissue pathway","Cost leading to subsequent cellular adaptation"]'::jsonb, 'Immunogenicity (anti-drug antibody formation)', 'Concomitant immunomodulator use reduces anti-drug antibody formation against infliximab and adalimumab.'),
('678499e2-15e2-5805-936e-5c32a184bb4e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which anti-TNF agent does NOT require concomitant immunomodulator to reduce immunogenicity?', '["Infliximab","Adalimumab","Certolizumab pegol","Golimumab","Both A and B"]'::jsonb, 'Certolizumab pegol', 'Certolizumab pegol (PEGylated Fab) has lower immunogenicity and does not require concomitant immunomodulator.'),
('6df5764a-fb7c-5086-bfe0-b3914720825c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Infliximab dosing for ulcerative colitis induction is typically:', '["1 mg/kg","5 mg/kg at weeks 0, 2, and 6","10 mg/kg weekly","50 mg SC weekly","25 mg SC twice weekly"]'::jsonb, '5 mg/kg at weeks 0, 2, and 6', 'Infliximab induction for UC uses 5 mg/kg IV at weeks 0, 2, and 6, same as for Crohn disease.'),
('fed1262d-0238-54e9-bf1f-447da04627fd'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Infliximab for Crohn disease is typically given at which induction schedule?', '["Single dose","5 mg/kg at weeks 0, 2, and 6","10 mg/kg weekly","1 mg/kg daily","25 mg SC weekly"]'::jsonb, '5 mg/kg at weeks 0, 2, and 6', 'Infliximab induction for Crohn disease uses 5 mg/kg IV at weeks 0, 2, and 6, then maintenance every 8 weeks.'),
('495b90c6-fbb4-55ac-b3d2-4cc349eff320'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'The half-life of infliximab is approximately:', '["2 days","8-10 days","20 days","30 days","60 days"]'::jsonb, '8-10 days', 'Infliximab has a terminal half-life of approximately 8-10 days, allowing dosing every 8 weeks.'),
('045069e7-8c21-54a3-b2db-11967d0d6410'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Infliximab is categorized as which class of drug by biosimilar nomenclature?', '["-ximab (chimeric)","-zumab (humanized)","-umab (human)","-cept (fusion protein)","-mab (monoclonal)"]'::jsonb, '-ximab (chimeric)', 'The suffix -ximab denotes a chimeric monoclonal antibody (mouse variable + human constant regions).'),
('da359fe4-139c-5716-802e-1f2ecff10626'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Adalimumab biosimilars share which property with the reference product?', '["Different mechanism of action","Same amino acid sequence and similar glycosylation","Different route of administration","Different target","No similarity required"]'::jsonb, 'Same amino acid sequence and similar glycosylation', 'Biosimilars must demonstrate similar amino acid sequence, structure, and glycosylation to the reference biologic.'),
('4984fef9-86f8-5e56-ba79-debf9bfb42b3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic drug was the first monoclonal antibody approved for a non-oncologic condition?', '["Trastuzumab","Infliximab","Rituximab","Bevacizumab","Cetuximab"]'::jsonb, 'Infliximab', 'Infliximab (approved 1998) was among the first monoclonal antibodies approved for autoimmune/inflammatory conditions.'),
('b3270920-d84c-50b8-8a2b-0c433af07192'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent can cause drug-induced lupus?', '["Infliximab","Adalimumab","Both A and B","Rituximab","Tocilizumab"]'::jsonb, 'Both A and B', 'Anti-TNF agents including infliximab and adalimumab can rarely cause drug-induced lupus with anti-histone antibodies.'),
('89bdf4e3-2a12-5c9a-bff4-d3935ba91894'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biosimilar to infliximab has been available the longest?', '["CT-P13 (Remsima/Inflectra)","SB2 (Remicade biosimilar)","Both became available simultaneously","No biosimilars for infliximab","GP1111"]'::jsonb, 'CT-P13 (Remsima/Inflectra)', 'CT-P13 was the first infliximab biosimilar approved globally.'),
('8a0e1e81-9f26-5bba-a7ba-de7a3029c794'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Adalimumab biosimilar adalimumab-adaz (Hyrimoz) is available at approximately what discount to the reference product?', '["5%","15-35%","No discount","50-70%","90%"]'::jsonb, '15-35%', 'Adalimumab biosimilars typically offer 15-35% discounts off the reference product list price.'),
('d2f96d85-fe9c-5cfc-bea0-70cc9ef418b2'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which monoclonal antibody is used for moderate-to-severe plaque psoriasis and also for Crohn disease?', '["Secukinumab","Ustekinumab","Adalimumab","Both B and C","Rituximab"]'::jsonb, 'Both B and C', 'Both ustekinumab and adalimumab are approved for both plaque psoriasis and Crohn disease.'),
('657b48b5-084e-5c98-8121-53d57e882c3e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent is effective for ulcerative colitis but NOT Crohn disease?', '["Infliximab","Adalimumab","Vedolizumab","All are effective for both","Golimumab"]'::jsonb, 'Golimumab', 'Golimumab is approved for ulcerative colitis but has not demonstrated efficacy in Crohn disease clinical trials.'),
('efb9c4e9-cfa0-5337-bb42-d3f65e4e631e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Secukinumab differs from ustekinumab in that secukinumab targets:', '["IL-12/IL-23","IL-17A directly","TNF-alpha","IL-6","CD20"]'::jsonb, 'IL-17A directly', 'Secukinumab targets IL-17A directly, while ustekinumab targets the p40 subunit shared by IL-12 and IL-23.'),
('7c7529ec-7596-5d4a-8623-f21dfe5e2204'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent is used for relapsing polychondritis?', '["Infliximab","Adalimumab","Tocilizumab","Rituximab","All of the above"]'::jsonb, 'Tocilizumab', 'Tocilizumab (anti-IL-6R) has shown efficacy in relapsing polychondritis.'),
('d457ff62-4cad-57f4-bb15-486b30ec068c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tocilizumab is also used for which rheumatologic condition as monotherapy?', '["Osteoarthritis","Giant cell arteritis","Gout","Fibromyalgia","Scleroderma"]'::jsonb, 'Giant cell arteritis', 'Tocilizumab is approved for giant cell arteritis, either as monotherapy or with corticosteroids.'),
('aa033d1d-2f36-5b9c-8ec7-663fbe5c6a55'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent is used for chronic spontaneous urticaria unresponsive to antihistamines?', '["Dupilumab","Omalizumab","Rituximab","Mepolizumab","Benralizumab"]'::jsonb, 'Omalizumab', 'Omalizumab (anti-IgE) is approved for chronic spontaneous urticaria inadequately controlled by H1 antihistamines.'),
('a0125899-d90e-528f-aa07-e6350226e603'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic is indicated for eosinophilic esophagitis?', '["Omalizumab","Dupilumab","Mepolizumab","Benralizumab","Rituximab"]'::jsonb, 'Dupilumab', 'Dupilumab (anti-IL-4Ralpha) is approved for eosinophilic esophagitis in patients aged 1 year and older.'),
('4e72c873-a4dc-5209-9827-5818692b3dca'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic is indicated for chronic rhinosinusitis with nasal polyps?', '["Dupilumab","Omalizumab","Mepolizumab","Rituximab","All of the above"]'::jsonb, 'Dupilumab', 'Dupilumab is approved for chronic rhinosinusitis with nasal polyps in adults inadequately controlled with nasal corticosteroids.'),
('12fb6eb0-e200-5a5a-b43e-8eb2d83ae481'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent is used for moderate-to-severe hidradenitis suppurativa?', '["Infliximab","Adalimumab","Secukinumab","Ustekinumab","Rituximab"]'::jsonb, 'Adalimumab', 'Adalimumab is the only biologic currently approved for moderate-to-severe hidradenitis suppurativa.'),
('5a8a1825-86bc-5af3-9670-9eb945f3fde0'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent is used for hereditary angioedema prophylaxis?', '["Omalizumab","Lanadelumab","Dupilumab","Mepolizumab","Rituximab"]'::jsonb, 'Lanadelumab', 'Lanadelumab is a monoclonal antibody targeting plasma kallikrein, used for prophylaxis of hereditary angioedema attacks.'),
('d9681f86-747d-5719-8bea-f0cba0016449'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ecallantide is used for acute attacks of which condition?', '["Anaphylaxis","Hereditary angioedema","Asthma exacerbation","Urticaria","Gout flare"]'::jsonb, 'Hereditary angioedema', 'Ecallantide is a plasma kallikrein inhibitor used for acute treatment of hereditary angioedema attacks.'),
('b4ddb973-565c-5c30-8930-00eef1c84caa'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Icatibant is a bradykinin B2 receptor antagonist used for:', '["Anaphylaxis resulting in decreased functional activity","Acute hereditary angioedema attacks","Chronic urticaria mediated by specific receptor activation","Asthma without affecting the primary tissue pathway","Rhinitis leading to subsequent cellular adaptation"]'::jsonb, 'Acute hereditary angioedema attacks', 'Icatibant competitively blocks bradykinin B2 receptors, providing rapid relief of acute HAE attacks.'),
('14f73796-4496-5693-a265-cefde1142b95'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'C1 esterase inhibitor concentrate is used for:', '["Anaphylaxis resulting in decreased functional activity","Hereditary angioedema treatment and prophylaxis","Sepsis mediated by specific receptor activation","Pancreatitis without affecting the primary tissue pathway","Transplant rejection leading to subsequent cellular adaptation"]'::jsonb, 'Hereditary angioedema treatment and prophylaxis', 'C1-INH concentrate replaces deficient C1 esterase inhibitor in HAE for both acute treatment and prophylaxis.'),
('671bb1f2-fa91-5d60-950c-7e85a3ddaa6f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is a complement inhibitor used for PNH?', '["Infliximab","Eculizumab","Rituximab","Adalimumab","Abatacept"]'::jsonb, 'Eculizumab', 'Eculizumab is a monoclonal antibody that inhibits terminal complement component C5, used for paroxysmal nocturnal hemoglobinuria.'),
('9dea610d-7b70-5317-a83c-bb8a572750b8'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Eculizumab increases the risk of which serious infection?', '["Tuberculosis","Neisseria meningitidis","Hepatitis B","CMV","Pneumocystis"]'::jsonb, 'Neisseria meningitidis', 'Terminal complement inhibition increases risk of Neisseria meningitidis infection. Vaccination before starting is required.'),
('4bab4ead-4adf-5e57-9c5c-1cf219d3ea33'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Eculizumab and ravulizumab both inhibit which complement component?', '["C3","C5","C1q","Factor D","Factor B"]'::jsonb, 'C5', 'Both eculizumab and ravulizumab are anti-C5 monoclonal antibodies that prevent formation of the membrane attack complex.'),
('2beeb4ef-badf-5d1c-9ade-a4c8a9207796'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ravulizumab differs from eculizumab primarily in:', '["Different target resulting in decreased functional activity","Longer half-life allowing less frequent dosing","Different route mediated by specific receptor activation","Lower potency without affecting the primary tissue pathway","Oral formulation leading to subsequent cellular adaptation"]'::jsonb, 'Longer half-life allowing less frequent dosing', 'Ravulizumab has an engineered longer half-life (50 days vs 11 days), allowing dosing every 8 weeks vs every 2 weeks.'),
('313c8d65-6744-5b55-a9a0-d5a893bd4e7d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which anti-complement drug is used for generalized myasthenia gravis?', '["Rituximab","Eculizumab","Infliximab","Adalimumab","Tocilizumab"]'::jsonb, 'Eculizumab', 'Eculizumab is approved for generalized myasthenia gravis in patients who are anti-AChR antibody-positive.'),
('40d12ca5-a5ab-5ffa-a2c2-6028dc4f68eb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Avacopan is an oral drug used with which biologic for ANCA-associated vasculitis?', '["Rituximab","Infliximab","Adalimumab","Tocilizumab","Belimumab"]'::jsonb, 'Rituximab', 'Avacopan is a C5a receptor antagonist used in combination with rituximab for ANCA-associated vasculitis.'),
('16eba83f-f8da-55e2-8b53-ad99cbd420b2'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which oral drug is a C5a receptor antagonist?', '["Eculizumab","Ravulizumab","Avacopan","Rituximab","Infliximab"]'::jsonb, 'Avacopan', 'Avacopan is an oral C5a receptor antagonist that reduces complement-mediated inflammation in ANCA vasculitis.'),
('3a8eef8e-5124-52ba-9c4e-f41d3e37637b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which monoclonal antibody is used for prevention of migraine headaches?', '["Erenumab","Omalizumab","Dupilumab","Secukinumab","Ustekinumab"]'::jsonb, 'Erenumab', 'Erenumab is a monoclonal antibody targeting the CGRP receptor, approved for prevention of episodic and chronic migraine.'),
('bff999a8-ddcd-5017-9c0f-355cddeb2927'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Erenumab targets which neuropeptide receptor?', '["Substance P receptor resulting in decreased functional activity","CGRP (calcitonin gene-related peptide) receptor","VIP receptor mediated by specific receptor activation","Oxytocin receptor without affecting the primary tissue pathway","Bradykinin receptor leading to subsequent cellular adaptation"]'::jsonb, 'CGRP (calcitonin gene-related peptide) receptor', 'Erenumab blocks the CGRP receptor, preventing CGRP-mediated vasodilation and pain signaling in migraine.'),
('50f6b172-8a7b-525d-8415-a13493ed4088'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic is used for prevention of cluster headaches?', '["Erenumab","Fremanezumab","Galcanezumab","All of the above","None of the above"]'::jsonb, 'Galcanezumab', 'Galcanezumab (anti-CGRP) is approved for prevention of both episodic and chronic cluster headaches.'),
('9b0327ca-a52e-5a84-83f6-86c6c7c2a3ad'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Fremanezumab targets which molecule?', '["CGRP receptor","CGRP ligand directly","IL-17","TNF-alpha","IL-5"]'::jsonb, 'CGRP ligand directly', 'Fremanezumab binds the CGRP ligand (not the receptor), preventing it from activating CGRP receptors.'),
('caaa68ed-99ce-52db-b23c-39b588974569'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Galcanezumab is administered by which route?', '["Oral","IV infusion","Subcutaneous injection","Intranasal","Intramuscular"]'::jsonb, 'Subcutaneous injection', 'Galcanezumab is given as a monthly subcutaneous injection for migraine prevention.'),
('c201789f-c803-5670-9426-8dd43e1a468e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which drug class do the -mab CGRP inhibitors belong to?', '["Small molecule","Biologic monoclonal antibody","Peptide","Oligonucleotide","Recombinant protein"]'::jsonb, 'Biologic monoclonal antibody', 'Erenumab, fremanezumab, and galcanezumab are all monoclonal antibodies targeting the CGRP pathway.'),
('c3af3f03-ef1b-516c-a250-a9e85dee5018'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Anakinra is a recombinant form of which natural molecule?', '["IL-1 receptor antagonist","TNF receptor","IL-6 receptor","IL-17 receptor","IL-23 receptor"]'::jsonb, 'IL-1 receptor antagonist', 'Anakinra is a recombinant human IL-1 receptor antagonist used for RA, cryopyrin-associated syndromes, and Still disease.'),
('57629130-f189-584f-93ac-bccb7fb3814b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'In which autoimmune condition is rituximab used as first-line biologic?', '["Rheumatoid arthritis resulting in decreased functional activity","Granulomatosis with polyangiitis (GPA)","Osteoarthritis mediated by specific receptor activation","Gout without affecting the primary tissue pathway","Fibromyalgia leading to subsequent cellular adaptation"]'::jsonb, 'Granulomatosis with polyangiitis (GPA)', 'Rituximab is first-line for GPA and is non-inferior to cyclophosphamide for induction of remission.'),
('1ea29114-dbf6-52bc-86b5-4ee12dd36427'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Abatacept is indicated for which autoimmune disease?', '["Crohn disease","Rheumatoid arthritis","Ankylosing spondylitis","Psoriasis","Ulcerative colitis"]'::jsonb, 'Rheumatoid arthritis', 'Abatacept is approved for moderate-to-severe rheumatoid arthritis in patients who have failed DMARDs or anti-TNF agents.'),
('6ff65b3f-846f-5255-ab1a-25236497af85'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Belimumab is indicated for which autoimmune disease?', '["Rheumatoid arthritis","Systemic lupus erythematosus (SLE)","Psoriasis","Crohn disease","Multiple sclerosis"]'::jsonb, 'Systemic lupus erythematosus (SLE)', 'Belimumab (anti-BLyS/BAFF) is approved for active SLE, reducing disease activity and steroid requirements.'),
('85cf2324-85d9-5416-9f1b-bb668de0193a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent was first to receive FDA approval for both psoriasis and Crohn disease?', '["Adalimumab","Infliximab","Ustekinumab","Secukinumab","Rituximab"]'::jsonb, 'Infliximab', 'Infliximab was the first biologic approved for both Crohn disease (1998) and plaque psoriasis (2006).'),
('fb121941-0a82-50d3-a1f6-43ecf5bbd777'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Rituximab in combination with which drug is standard for follicular lymphoma?', '["CHOP","CVP","Bendamustine","All of the above","None of the above"]'::jsonb, 'All of the above', 'Rituximab is combined with CHOP, CVP, or bendamustine for follicular lymphoma depending on stage and risk.'),
('189dbdac-84bc-547f-b264-e7ee569a0d0f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which monoclonal antibody is used for immunosuppression in ABO-incompatible kidney transplantation?', '["Infliximab","Rituximab","Adalimumab","Etanercept","Abatacept"]'::jsonb, 'Rituximab', 'Rituximab is used for B-cell depletion in ABO-incompatible kidney transplantation protocols.'),
('0a8fd8e6-0700-5d04-a74c-8941ccf10c24'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Rituximab is contraindicated in which infection?', '["Active tuberculosis","Active hepatitis B","Influenza","Common cold","Urinary tract infection"]'::jsonb, 'Active hepatitis B', 'Rituximab should be used with extreme caution or avoided in active hepatitis B due to risk of fatal reactivation.'),
('6f6ca591-c3bd-55f7-9d40-b78d8d886ce4'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic was the first approved for prevention of organ transplant rejection?', '["Rituximab","Basiliximab","Infliximab","Adalimumab","Abatacept"]'::jsonb, 'Basiliximab', 'Basiliximab (anti-CD25) was the first biologic approved specifically for induction immunosuppression in kidney transplantation.'),
('63003916-f2d9-5fdd-8eff-71907f1eaf2d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which immunosuppressant should be avoided with live vaccines?', '["All of the listed immunosuppressants","Only corticosteroids","Only calcineurin inhibitors","Only MMF","None"]'::jsonb, 'All of the listed immunosuppressants', 'All immunosuppressants impair vaccine responses and live vaccines are generally contraindicated during immunosuppressive therapy.'),
('47f82d01-24a2-5bc2-99b3-06188c195a90'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'First-generation H1 antihistamines cross the blood-brain barrier because they are:', '["Highly polar","Lipophilic","Protein-bound","Large molecules","Ionized at physiological pH"]'::jsonb, 'Lipophilic', 'First-generation H1 antihistamines are lipophilic, allowing CNS penetration and causing sedation.'),
('ba823c5c-1719-5bf8-a66a-9415ba34eb3a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which first-generation H1 antihistamine is commonly used as a nighttime sedative?', '["Cetirizine","Loratadine","Diphenhydramine","Fexofenadine","Desloratadine"]'::jsonb, 'Diphenhydramine', 'Diphenhydramine is a first-generation H1 antihistamine with strong sedative properties.'),
('a3742cc2-9075-55c8-b869-3796f809e361'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Second-generation H1 antihistamines are preferred for allergic rhinitis because they:', '["Are more potent","Cause less sedation","Are cheaper","Have shorter half-lives","Are available IV"]'::jsonb, 'Cause less sedation', 'Second-generation antihistamines are less lipophilic, poorly penetrate the CNS, and cause minimal sedation.'),
('d647c070-9120-588e-95e6-b59568283f28'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'H1 antihistamines act as inverse agonists at which receptor?', '["H2 receptor","H3 receptor","H1 histamine receptor","Muscarinic receptor","Serotonin receptor"]'::jsonb, 'H1 histamine receptor', 'H1 antihistamines are inverse agonists at the H1 receptor, stabilizing it in inactive conformation.'),
('f46749f3-2119-57e4-8f16-99fa23118167'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which H2 receptor antagonist is used to suppress gastric acid secretion?', '["Diphenhydramine","Cimetidine","Cetirizine","Loratadine","Fexofenadine"]'::jsonb, 'Cimetidine', 'Cimetidine is an H2 receptor antagonist that reduces gastric acid secretion, used for peptic ulcer disease and GERD.'),
('947b7e7b-faea-5ea1-ab13-4bf2c9671e98'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which H2 blocker inhibits CYP450 enzymes and has numerous drug interactions?', '["Ranitidine","Famotidine","Cimetidine","Nizatidine","All equally"]'::jsonb, 'Cimetidine', 'Cimetidine is a potent CYP450 inhibitor, causing significant drug interactions.'),
('89dfc40e-4742-5a45-b90e-bb73676b7b0f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Fexofenadine is the active metabolite of which antihistamine?', '["Cetirizine","Terfenadine","Loratadine","Acrivastine","Bilastine"]'::jsonb, 'Terfenadine', 'Fexofenadine is the active carboxyl metabolite of terfenadine, developed after terfenadine was withdrawn due to cardiotoxicity.'),
('05c160b2-7ea4-583e-8e94-072b88314d8a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Anticholinergic effects of first-generation antihistamines include:', '["Tachycardia and diarrhea","Dry mouth, urinary retention, blurred vision","Hypotension and bradycardia","Increased gastric acid","Miosis"]'::jsonb, 'Dry mouth, urinary retention, blurred vision', 'First-generation antihistamines have antimuscarinic effects causing dry mouth, urinary retention, blurred vision, and constipation.'),
('5677ad72-f8a5-5972-bfd7-792aae20d105'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cetirizine is the active metabolite of which drug?', '["Loratadine","Hydroxyzine","Fexofenadine","Terfenadine","Acrivastine"]'::jsonb, 'Hydroxyzine', 'Cetirizine is the active carboxylated metabolite of hydroxyzine.'),
('7cfcfd04-c1da-5fb3-869e-7f7c0577b681'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'H2 receptor antagonists reduce gastric acid by blocking histamine effects on which cells?', '["Parietal cells","Chief cells","G cells","Mucous cells","D cells"]'::jsonb, 'Parietal cells', 'H2 receptors on parietal cells mediate acid secretion. H2 blockers competitively inhibit histamine at these receptors.'),
('da2da82f-3ae8-55c1-aa5c-d74a206afc48'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which second-generation antihistamine has the least potential for cardiac arrhythmias?', '["Terfenadine","Astemizole","Fexofenadine","Both A and B","None"]'::jsonb, 'Fexofenadine', 'Fexofenadine (and other second-generation agents) have no significant cardiac QT prolongation risk.'),
('602f09e2-f060-5a89-99f1-86055dd3f8bd'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'First-generation antihistamines are used as antiemetics because they block which receptors?', '["H1 receptors in the CTZ","H2 receptors in the stomach","Muscarinic receptors","Dopamine receptors","Serotonin receptors"]'::jsonb, 'H1 receptors in the CTZ', 'First-generation antihistamines block H1 receptors in the chemoreceptor trigger zone, providing antiemetic effect.'),
('e56d24de-16e3-5ccc-a51a-c48b6b1dd67a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Dimenhydrinate is primarily used for which condition?', '["Allergic rhinitis","Motion sickness","Peptic ulcer","Hypertension","Asthma"]'::jsonb, 'Motion sickness', 'Dimenhydrinate is an antihistamine widely used for prevention and treatment of motion sickness and vertigo.'),
('ca7b451e-4fd7-523a-b488-6cee6d19d094'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Promethazine is a phenothiazine antihistamine used for:', '["Allergic rhinitis only","Nausea, vomiting, and sedation","Hypertension","Diabetes","Hyperlipidemia"]'::jsonb, 'Nausea, vomiting, and sedation', 'Promethazine has antihistaminic, antiemetic, and sedative properties.'),
('8aa026c8-9d6f-54bb-a83a-6cd2848c362e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which second-generation antihistamine is least sedating?', '["Cetirizine","Loratadine","Fexofenadine","Desloratadine","Levocetirizine"]'::jsonb, 'Fexofenadine', 'Fexofenadine has the lowest CNS penetration among second-generation antihistamines.'),
('73a1c06d-59f3-514b-b048-f1f68189acfb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Intranasal corticosteroids are considered first-line therapy for which condition?', '["Viral rhinitis resulting in decreased functional activity","Moderate-to-severe persistent allergic rhinitis","Bacterial sinusitis mediated by specific receptor activation","Nasal polyps only without affecting the primary tissue pathway","Common cold leading to subsequent cellular adaptation"]'::jsonb, 'Moderate-to-severe persistent allergic rhinitis', 'Intranasal corticosteroids are the most effective treatment for moderate-to-severe persistent allergic rhinitis.'),
('b8ed73f7-5e21-58b9-b8a0-0a51222d141a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which intranasal corticosteroid has the lowest systemic bioavailability?', '["Beclomethasone dipropionate","Fluticasone furoate","Triamcinolone acetonide","Budesonide","Mometasone furoate"]'::jsonb, 'Fluticasone furoate', 'Fluticasone furoate has very low oral bioavailability (<2%) and high first-pass metabolism.'),
('790e0d8e-137d-5b46-8e62-d4e08a32774b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ipratropium bromide nasal spray is most effective for which symptom of allergic rhinitis?', '["Sneezing","Itching","Rhinorrhea","Nasal congestion","Eye symptoms"]'::jsonb, 'Rhinorrhea', 'Ipratropium bromide (anticholinergic) is most effective for watery rhinorrhea (runny nose).'),
('ca69c695-47ac-5927-b8ae-f11245482747'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Montelukast is a leukotriene receptor antagonist that blocks which receptor?', '["CysLT1 receptor","CysLT2 receptor","BLT1 receptor","LTD4 receptor only","LTC4 receptor only"]'::jsonb, 'CysLT1 receptor', 'Montelukast selectively blocks the CysLT1 receptor, inhibiting cysteinyl leukotriene-mediated bronchoconstriction and inflammation.'),
('a757c0f3-b261-50be-ba4d-5a7517910385'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'In allergic rhinitis, which mediator causes nasal congestion?', '["Histamine only","Leukotrienes and histamine","Prostaglandin D2 only","Bradykinin only","Substance P only"]'::jsonb, 'Leukotrienes and histamine', 'Nasal congestion is caused by both histamine and leukotrienes acting on nasal vasculature.'),
('9b6e727c-0ee1-572a-a178-ce3a3e3aa378'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is NOT a symptom of allergic rhinitis treated by antihistamines?', '["Sneezing","Rhinorrhea","Nasal congestion","Itching","Ocular itching"]'::jsonb, 'Nasal congestion', 'Antihistamines are less effective for nasal congestion. Intranasal corticosteroids are superior for congestion.'),
('5ae73118-adec-5505-8dc2-5f5b4dae3ccb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Azelastine is which type of nasal antihistamine?', '["Oral antihistamine","Intranasal antihistamine","Ophthalmic antihistamine","Inhaled antihistamine","Topical antihistamine"]'::jsonb, 'Intranasal antihistamine', 'Azelastine is an intranasal antihistamine that provides rapid relief with minimal systemic absorption.'),
('50efb576-6361-5b42-8908-528d77795240'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Intranasal corticosteroids should be administered by aiming the spray toward which structure?', '["Nasal septum","Nasal floor and lateral wall","Nasal bridge","Nasopharynx directly","Cribriform plate"]'::jsonb, 'Nasal floor and lateral wall', 'The spray should be aimed laterally toward the nasal floor and lateral wall to maximize drug distribution.'),
('23d46e52-1a29-527f-994c-f2349725ac62'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cromolyn sodium for allergic rhinitis works by which mechanism?', '["H1 receptor blockade","Mast cell stabilization","Leukotriene inhibition","Corticosteroid effect","Alpha-adrenergic agonist"]'::jsonb, 'Mast cell stabilization', 'Cromolyn sodium stabilizes mast cell membranes, preventing degranulation and release of histamine and other mediators.'),
('9aef188b-46fa-5f87-a876-c3f75415f23e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which intranasal corticosteroid is available over-the-counter in many countries?', '["Fluticasone propionate","Fluticasone furoate","Budesonide","Mometasone furoate","Beclomethasone"]'::jsonb, 'Fluticasone propionate', 'Fluticasone propionate nasal spray (Flonase) is widely available OTC for allergic rhinitis.'),
('7cb1a4c4-1f7c-5273-b5b5-0c8cf089bc3c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the onset of action of intranasal corticosteroids for allergic rhinitis?', '["Immediate (within minutes)","12-24 hours for full effect","7-14 days for full therapeutic effect","1 hour","Immediate full effect"]'::jsonb, '7-14 days for full therapeutic effect', 'Intranasal corticosteroids require 7-14 days for maximum therapeutic benefit.'),
('8d2606e6-d10a-551b-ac39-d75a7b3e23b9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which intranasal corticosteroid is considered safest for long-term use in children?', '["Fluticasone propionate","Fluticasone furoate","Budesonide","Mometasone furoate","Beclomethasone"]'::jsonb, 'Budesonide', 'Budesonide has extensive safety data in pediatric patients and is considered one of the safest for long-term use in children.'),
('db39e4f0-7394-5094-aeb0-c1f7d26b2090'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Olopatadine nasal spray is classified as which type of drug?', '["Corticosteroid","Intranasal antihistamine","Decongestant","Anticholinergic","Mast cell stabilizer"]'::jsonb, 'Intranasal antihistamine', 'Olopatadine is a second-generation H1 antihistamine available as a nasal spray.'),
('4fa156a5-98cd-56f5-b700-dde915d2ae8a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Azelastine nasal spray has which advantage over oral antihistamines?', '["Lower cost resulting in decreased functional activity","Faster onset with direct topical action on nasal mucosa","Longer duration mediated by specific receptor activation","Less expensive without affecting the primary tissue pathway","No prescription needed leading to subsequent cellular adaptation"]'::jsonb, 'Faster onset with direct topical action on nasal mucosa', 'Intranasal azelastine provides rapid symptom relief through direct topical action on nasal mast cells and sensory nerves.'),
('b60f033a-6b7d-5d5f-8967-f02a4629ab36'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Montelukast has a boxed warning regarding which psychiatric side effect?', '["Depression resulting in decreased functional activity","Suicidal thoughts and behavior","Psychosis mediated by specific receptor activation","Anxiety without affecting the primary tissue pathway","Insomnia leading to subsequent cellular adaptation"]'::jsonb, 'Suicidal thoughts and behavior', 'The FDA issued a boxed warning for montelukast regarding neuropsychiatric events including suicidal thoughts and behavior.'),
('8d7c5de2-7ced-5afd-aa1e-f4f67a8df8b4'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ranitidine was withdrawn from many markets due to contamination with:', '["Lead resulting in decreased functional activity","NDMA (N-nitrosodimethylamine)","Mercury mediated by specific receptor activation","Arsenic without affecting the primary tissue pathway","Cadmium leading to subsequent cellular adaptation"]'::jsonb, 'NDMA (N-nitrosodimethylamine)', 'Ranitidine was recalled due to formation of NDMA, a probable human carcinogen.'),
('0c0bc01e-734a-50c9-944f-7e8e5616139a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which H2 blocker is available over-the-counter for heartburn relief?', '["Cimetidine","Ranitidine","Famotidine","Nizatidine","All of the above"]'::jsonb, 'Famotidine', 'Famotidine (Pepcid AC) is widely available OTC for heartburn relief.'),
('bd1faa68-9cf1-5a46-9e83-9e22f0900bba'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Epinephrine is the first-line treatment for anaphylaxis because it:', '["Blocks histamine at H1 receptors resulting in decreased functional activity","Causes bronchodilation and vasoconstriction via alpha and beta adrenergic receptors","Stabilizes mast cells mediated by specific receptor activation","Blocks leukotriene receptors without affecting the primary tissue pathway","Inhibits complement activation leading to subsequent cellular adaptation"]'::jsonb, 'Causes bronchodilation and vasoconstriction via alpha and beta adrenergic receptors', 'Epinephrine acts on alpha-1 (vasoconstriction), beta-1 (increased cardiac output), and beta-2 (bronchodilation, mast cell stabilization).'),
('975128ee-55c9-5880-90ac-750770da69a9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the recommended dose of epinephrine for adult anaphylaxis?', '["0.01 mg IM resulting in decreased functional activity","0.3-0.5 mg (1:1000) IM into anterolateral thigh","1 mg IV mediated by specific receptor activation","0.05 mg sublingual without affecting the primary tissue pathway","5 mg nebulized leading to subsequent cellular adaptation"]'::jsonb, '0.3-0.5 mg (1:1000) IM into anterolateral thigh', 'Adult dose is 0.3-0.5 mg of 1:1000 solution given IM into the anterolateral thigh. Repeat every 5-15 minutes if needed.'),
('030eb653-b6e5-50d2-943f-f65f4d6590d6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Why is the anterolateral thigh preferred for epinephrine injection in anaphylaxis?', '["Larger muscle mass resulting in decreased functional activity","Faster absorption due to rich blood supply","Less painful mediated by specific receptor activation","Patient preference without affecting the primary tissue pathway","Cheaper supplies leading to subsequent cellular adaptation"]'::jsonb, 'Faster absorption due to rich blood supply', 'The anterolateral thigh has a rich blood supply, allowing faster absorption and more reliable peak plasma levels.'),
('86d9736f-c743-5d28-ba89-9af1378506a8'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Delayed administration of epinephrine in anaphylaxis is associated with:', '["Better outcomes","Increased risk of biphasic reaction","Lower risk of cardiac arrest","No difference in outcomes","Reduced mortality"]'::jsonb, 'Increased risk of biphasic reaction', 'Delayed epinephrine is associated with increased risk of biphasic reactions, treatment failure, and death.'),
('7d4fa123-c185-5e3e-a6e1-377c4f5096d6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is contraindicated as first-line treatment for anaphylaxis?', '["Epinephrine IM","Diphenhydramine IV","Albuterol nebulizer","Normal saline bolus","Methylprednisolone IV"]'::jsonb, 'Methylprednisolone IV', 'Corticosteroids have a delayed onset (4-6 hours) and are never first-line for anaphylaxis.'),
('ca6cc98e-c165-5caf-9dc7-5885c896614c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Epinephrine auto-injectors should be stored at:', '["Room temperature","Refrigerated 2-8C","Frozen","Protected from light at 20-25C","Any temperature"]'::jsonb, 'Protected from light at 20-25C', 'Epinephrine auto-injectors should be stored at 20-25C, protected from light and extreme temperatures.'),
('6f19b0f0-3239-515d-a3a4-71607b7e64ca'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the pediatric dose of epinephrine for anaphylaxis?', '["0.01 mg/kg IM (max 0.3 mg for children, 0.5 mg for adolescents)","Same as adult dose regardless of weight accompanied by associated clinical symptoms","Half the adult dose mediated by specific receptor activation","0.5 mg IM without affecting the primary tissue pathway","0.05 mg IV leading to subsequent cellular adaptation"]'::jsonb, '0.01 mg/kg IM (max 0.3 mg for children, 0.5 mg for adolescents)', 'Pediatric dose is 0.01 mg/kg of 1:1000 IM, with maximum of 0.3 mg for children and 0.5 mg for adolescents.'),
('959e1d1b-92da-58e6-92c7-89738f260690'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'IV epinephrine for anaphylaxis should be administered as:', '["Bolus injection","Continuous infusion in dilute concentration","Subcutaneous injection","Intrathecal injection","Intracardiac injection"]'::jsonb, 'Continuous infusion in dilute concentration', 'IV epinephrine should only be given as a continuous infusion (1:10,000 dilution) for refractory anaphylaxis, never as a bolus.'),
('7dd82175-7fc2-5fe6-a128-f4f5e1045c90'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Biphasic anaphylaxis refers to:', '["Reaction occurring twice in lifetime","Recurrence of symptoms hours after initial resolution without re-exposure","Two different allergens causing anaphylaxis","Initial and late phase of same reaction","Reaction in two body systems"]'::jsonb, 'Recurrence of symptoms hours after initial resolution without re-exposure', 'Biphasic anaphylaxis is a recurrence of symptoms 1-72 hours after initial resolution without re-exposure, occurring in up to 20% of cases.'),
('6c09d506-ac3b-5a2f-b62f-34f1f49b691d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Epinephrine auto-injector should be checked for expiration because expired epinephrine:', '["Is more effective resulting in decreased functional activity","May have reduced potency and be less effective in anaphylaxis","Is safer mediated by specific receptor activation","Has no change in efficacy without affecting the primary tissue pathway","Is more concentrated leading to subsequent cellular adaptation"]'::jsonb, 'May have reduced potency and be less effective in anaphylaxis', 'Expired epinephrine loses potency through oxidation and may not provide adequate therapeutic effect.'),
('9f8af215-8f3f-517c-b7dc-b963a330e521'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'After epinephrine for anaphylaxis, what is the next most important intervention?', '["Antihistamine injection","IV fluid resuscitation","Corticosteroid injection","Oxygen only","Nebulized albuterol"]'::jsonb, 'IV fluid resuscitation', 'After epinephrine, aggressive IV fluid resuscitation (1-2L normal saline) is critical for distributive shock.'),
('7074ad53-610b-578e-b9a4-878ca7e1ea0e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Epinephrine in anaphylaxis acts on beta-2 adrenergic receptors to cause:', '["Vasoconstriction resulting in decreased functional activity","Bronchodilation and mast cell stabilization","Increased heart rate mediated by specific receptor activation","Increased blood pressure without affecting the primary tissue pathway","Mydriasis leading to subsequent cellular adaptation"]'::jsonb, 'Bronchodilation and mast cell stabilization', 'Beta-2 receptor activation causes bronchodilation, inhibits further mediator release from mast cells.'),
('1557b768-1286-54b6-902e-f9d64936a12e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Epinephrine acts on alpha-1 receptors in anaphylaxis to cause:', '["Bronchodilation resulting in decreased functional activity","Vasoconstriction and increased blood pressure","Increased heart rate mediated by specific receptor activation","Decreased blood pressure without affecting the primary tissue pathway","Pupil dilation leading to subsequent cellular adaptation"]'::jsonb, 'Vasoconstriction and increased blood pressure', 'Alpha-1 receptor activation causes peripheral vasoconstriction, reducing edema and raising blood pressure.'),
('1e8cd9d5-b9ec-58bd-ada3-59881d193b0d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is the correct sequence of steps in anaphylaxis management?', '["Antihistamines then Epinephrine then Steroids","Epinephrine then Call emergency services then IV fluids","IV fluids then Antihistamines then Epinephrine","Steroids then Epinephrine then Antihistamines","Oxygen then Steroids then Epinephrine"]'::jsonb, 'Epinephrine then Call emergency services then IV fluids', 'Epinephrine IM is always first, then activate emergency services, then IV fluid resuscitation.'),
('8c3eab1f-bee3-5b70-b3f7-6d5852163ff7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Methotrexate inhibits which enzyme in folate metabolism?', '["Dihydrofolate reductase (DHFR)","Thymidylate synthase","Glutamine synthetase","Xanthine oxidase","Ribonucleotide reductase"]'::jsonb, 'Dihydrofolate reductase (DHFR)', 'Methotrexate competitively inhibits DHFR, preventing conversion of dihydrofolate to tetrahydrofolate.'),
('62ffdac9-98c6-5e58-91d4-b5f08c743613'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'In rheumatoid arthritis, methotrexate is given in low doses weekly because:', '["Weekly dosing is more convenient","Daily dosing would be too toxic","It only works once per week","The drug accumulates in joints","It has a very long half-life"]'::jsonb, 'Daily dosing would be too toxic', 'Weekly dosing provides adequate efficacy while minimizing bone marrow suppression, hepatotoxicity, and GI toxicity.'),
('b4d716c5-fb40-5a0b-b706-3e7be47b0eb6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which vitamin supplement should be co-prescribed with methotrexate?', '["Vitamin B12","Folic acid","Vitamin D","Vitamin C","Vitamin A"]'::jsonb, 'Folic acid', 'Folic acid supplementation (1-5 mg daily or weekly) reduces methotrexate side effects including stomatitis and hepatotoxicity.'),
('8e3e0d23-1665-5ec8-ba58-fb9834bd1269'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Methotrexate can cause which serious pulmonary complication?', '["Pulmonary embolism","Methotrexate pneumonitis","Pulmonary fibrosis only","Bronchospasm","Pulmonary hypertension"]'::jsonb, 'Methotrexate pneumonitis', 'Methotrexate can cause an idiosyncratic hypersensitivity pneumonitis at any time during therapy, requiring immediate discontinuation.'),
('d369205f-e32f-528c-aee7-33ca5aa19e0b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Leflunomide inhibits which enzyme in pyrimidine synthesis?', '["DHFR","Dihydroorotate dehydrogenase (DHODH)","IMPDH","Thymidylate synthase","Orotate phosphoribosyltransferase"]'::jsonb, 'Dihydroorotate dehydrogenase (DHODH)', 'Leflunomide inhibits DHODH, blocking de novo pyrimidine synthesis. Activated lymphocytes depend on this pathway.'),
('ad80a016-bdbb-59e2-ae07-973c485e1bbe'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Leflunomide is contraindicated in which condition?', '["Rheumatoid arthritis","Psoriatic arthritis","Pregnancy","Osteoarthritis","Fibromyalgia"]'::jsonb, 'Pregnancy', 'Leflunomide is teratogenic and absolutely contraindicated in pregnancy.'),
('db6ac805-bd81-58b0-b2f1-99d4c7fdc116'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Hydroxychloroquine in SLE reduces which immunological marker?', '["TNF-alpha","Anti-dsDNA antibodies","IL-6","Complement C3","IL-17"]'::jsonb, 'Anti-dsDNA antibodies', 'Hydroxychloroquine reduces anti-dsDNA antibody levels, decreases disease flares, and improves survival in SLE.'),
('6077ff20-133a-5bf2-97d1-7f75b44ebbea'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which ocular complication requires regular screening in patients on hydroxychloroquine?', '["Cataracts resulting in decreased functional activity","Glaucoma accompanied by associated clinical symptoms","Retinal toxicity (bull''s eye maculopathy)","Conjunctivitis without affecting the primary tissue pathway","Keratitis leading to subsequent cellular adaptation"]'::jsonb, 'Retinal toxicity (bull''s eye maculopathy)', 'Hydroxychloroquine can cause irreversible retinal toxicity with characteristic bull''s eye maculopathy. Annual screening recommended after 5 years.'),
('dbd1068f-1ada-5e12-976f-b1bc8f834f59'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Hydroxychloroquine dose should not exceed which daily amount to minimize retinal toxicity?', '["100 mg/day resulting in decreased functional activity","200 mg/day accompanied by associated clinical symptoms","5 mg/kg actual body weight per day","500 mg/day without affecting the primary tissue pathway","1000 mg/day leading to subsequent cellular adaptation"]'::jsonb, '5 mg/kg actual body weight per day', 'The recommended maximum dose is 5 mg/kg actual body weight per day to minimize retinal toxicity risk.'),
('d11c4ced-5072-55ee-b1bd-ce6eae333af3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Hydroxychloroquine has which additional metabolic benefit in SLE patients?', '["Lowers blood glucose resulting in decreased functional activity","Reduces lipid levels and improves glucose metabolism","Reduces potassium levels mediated by specific receptor activation","Increases calcium absorption without affecting the primary tissue pathway","Lowers blood pressure leading to subsequent cellular adaptation"]'::jsonb, 'Reduces lipid levels and improves glucose metabolism', 'Hydroxychloroquine has beneficial effects on lipid profile and glucose metabolism, reducing cardiovascular risk in SLE patients.'),
('f7a37be7-dd6b-544b-8e10-a8e20e7294ad'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Methotrexate is teratogenic. What is the recommended washout period before conception?', '["1 week","1 month","At least 3 months","6 months","1 year"]'::jsonb, 'At least 3 months', 'Methotrexate should be discontinued at least 3 months before conception in both men and women.'),
('c905f623-2161-50a3-96a7-3a66c2e30a76'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Methotrexate hepatotoxicity is monitored by:', '["Serum methotrexate levels resulting in decreased functional activity","Liver function tests and periodic liver biopsy","Renal function tests mediated by specific receptor activation","Chest X-ray without affecting the primary tissue pathway","Ophthalmologic exam leading to subsequent cellular adaptation"]'::jsonb, 'Liver function tests and periodic liver biopsy', 'LFTs should be checked regularly and liver biopsy considered in patients with persistent abnormalities.'),
('2d44fb8d-902c-5b07-9957-e817d0ac049d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Methotrexate should be avoided with which of the following due to increased bone marrow toxicity?', '["Metformin resulting in decreased functional activity","Trimethoprim-sulfamethoxazole","Paracetamol mediated by specific receptor activation","Ibuprofen without affecting the primary tissue pathway","Omeprazole leading to subsequent cellular adaptation"]'::jsonb, 'Trimethoprim-sulfamethoxazole', 'TMP-SMX and methotrexate both inhibit folate metabolism, synergistically increasing myelosuppression risk.'),
('2d16d570-d990-5ca0-9497-850f957fcff2'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Methotrexate in low weekly doses for RA acts primarily as an:', '["Antibiotic resulting in decreased functional activity","Immunosuppressant and anti-inflammatory agent","Analgesic mediated by specific receptor activation","Antiviral without affecting the primary tissue pathway","Antifungal leading to subsequent cellular adaptation"]'::jsonb, 'Immunosuppressant and anti-inflammatory agent', 'Low-dose methotrexate in RA acts through anti-inflammatory mechanisms including adenosine release, not just cytotoxicity.'),
('b44a96d0-6823-57f6-8c50-28b8bae2d435'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which type of rejection occurs within minutes to hours after transplantation?', '["Acute cellular rejection","Hyperacute rejection","Chronic rejection","Delayed graft function","Antibody-mediated rejection"]'::jsonb, 'Hyperacute rejection', 'Hyperacute rejection occurs within minutes to hours due to preformed donor-specific antibodies causing complement activation and graft thrombosis.'),
('8f8816d9-1c9e-5b63-8d0d-9d677ceb5563'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Hyperacute rejection can be prevented by:', '["Increasing immunosuppression","ABO blood group and HLA crossmatch compatibility","Corticosteroid pulse","Plasma exchange","Antithymocyte globulin"]'::jsonb, 'ABO blood group and HLA crossmatch compatibility', 'Pre-transplant ABO compatibility and negative lymphocyte crossmatch prevent hyperacute rejection.'),
('0c8d29ca-3b70-5255-8ae1-a0391951b8f9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Induction immunosuppression in transplantation typically uses which agents?', '["MMF and steroids only resulting in decreased functional activity","Antilymphocyte antibodies (ATG) or basiliximab","Azathioprine alone mediated by specific receptor activation","Sirolimus only without affecting the primary tissue pathway","Cyclosporine only leading to subsequent cellular adaptation"]'::jsonb, 'Antilymphocyte antibodies (ATG) or basiliximab', 'Induction therapy uses lymphocyte-depleting agents (ATG, alemtuzumab) or IL-2 receptor antagonists (basiliximab).'),
('1ebe0ae4-e0d5-5505-883c-e2df3709e38f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Standard maintenance triple immunosuppression after kidney transplant consists of:', '["Cyclosporine + azathioprine + steroids","Tacrolimus + MMF + corticosteroids","Sirolimus + MMF + cyclosporine","Tacrolimus + sirolimus + steroids","Cyclosporine + tacrolimus + MMF"]'::jsonb, 'Tacrolimus + MMF + corticosteroids', 'The current standard for kidney transplant is tacrolimus + MMF + corticosteroids.'),
('2fa0066c-129a-5e51-8d26-3ad7ecaf5292'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which HLA mismatch is most important to avoid in kidney transplantation?', '["HLA-DQ mismatch","HLA-DR mismatch","HLA-B mismatch","HLA-A mismatch","All mismatches equally important"]'::jsonb, 'HLA-DR mismatch', 'HLA-DR mismatching has the strongest association with acute rejection and graft loss.'),
('3b62b25d-8903-50b0-bf0e-3368df9ac299'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the most common cause of late graft loss in kidney transplantation?', '["Hyperacute rejection","Chronic antibody-mediated rejection","Acute cellular rejection","Drug toxicity","Surgical complications"]'::jsonb, 'Chronic antibody-mediated rejection', 'Chronic antibody-mediated rejection with transplant glomerulopathy and IF/TA is the leading cause of late graft loss.'),
('5ebbd95d-e2a8-5f87-8dbc-d3d04ab39366'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Banff classification is used to grade which pathological finding in transplants?', '["Drug toxicity","Allograft rejection","Infection","Malignancy","Vascular disease"]'::jsonb, 'Allograft rejection', 'The Banff classification is the international standard for grading renal allograft rejection based on histopathological findings.'),
('cfde42aa-fb19-5212-a9da-0bef61180677'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which test is used to detect donor-specific antibodies before transplantation?', '["ELISA resulting in decreased functional activity","Luminex single antigen bead assay","Western blot mediated by specific receptor activation","Immunofluorescence without affecting the primary tissue pathway","PCR leading to subsequent cellular adaptation"]'::jsonb, 'Luminex single antigen bead assay', 'Luminex single antigen bead assay is the most sensitive method for detecting and characterizing donor-specific HLA antibodies.'),
('bee3e1b1-d9a7-5cce-b47d-287c8068aa33'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Protocol biopsies in transplantation are performed to detect:', '["Drug nephrotoxicity","Subclinical rejection","Infection","Malignancy","Recurrence of original disease"]'::jsonb, 'Subclinical rejection', 'Protocol biopsies detect subclinical rejection and early chronic changes that would be missed by clinical monitoring alone.'),
('25560225-d0ba-5fa6-95cd-af1dad6addf9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which drug is used for desensitization in highly sensitized transplant recipients?', '["Azathioprine","Rituximab and plasmapheresis","Methotrexate","Leflunomide","Hydroxychloroquine"]'::jsonb, 'Rituximab and plasmapheresis', 'Rituximab combined with plasmapheresis and IVIG is used to reduce preformed donor-specific antibodies in sensitized patients.'),
('2a92d855-c74d-5eee-ba2b-15bf51d19c9c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Donor-specific antibodies in transplantation are of which immunoglobulin class?', '["IgM only","IgG","IgA","IgE","IgD"]'::jsonb, 'IgG', 'Donor-specific antibodies (DSA) that cause antibody-mediated rejection are predominantly IgG.'),
('2d882add-b759-5465-a91c-6ffa0a2033af'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Complement-fixing donor-specific antibodies are most associated with which outcome?', '["Better graft function","Graft rejection and loss","No effect on graft","Increased graft survival","Reduced immunosuppression needs"]'::jsonb, 'Graft rejection and loss', 'Complement-fixing DSA (IgG1, IgG3) activate the classical complement pathway, causing endothelial damage and graft loss.'),
('b8b25459-7cbc-5a2e-9d5d-4493448c37b3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which class of HLA antibodies is most relevant for pre-transplant crossmatching?', '["Class I (HLA-A, B, C)","Class II (HLA-DR, DQ, DP)","Both Class I and Class II","Only HLA-DQ","Only HLA-A"]'::jsonb, 'Both Class I and Class II', 'Both HLA Class I and Class II antibodies can cause hyperacute and acute rejection.'),
('6834697a-35cc-5710-a9c9-26db582091d0'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'ATG (antithymocyte globulin) is used for which type of rejection?', '["Hyperacute rejection","Steroid-resistant acute rejection","Chronic rejection","Antibody-mediated rejection only","Prevention of hyperacute rejection"]'::jsonb, 'Steroid-resistant acute rejection', 'ATG is the treatment of choice for steroid-resistant acute cellular rejection.'),
('0654fedd-4912-59e5-aef8-b4326b3784f7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which drug is used to treat antibody-mediated rejection in transplantation?', '["Methotrexate","Plasmapheresis and IVIG","Leflunomide","Hydroxychloroquine","Sirolimus"]'::jsonb, 'Plasmapheresis and IVIG', 'Antibody-mediated rejection is treated with plasmapheresis combined with IVIG and sometimes rituximab.'),
('3409478f-3c1c-52e4-ad90-1e23cd3762f6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'BK virus nephropathy in kidney transplant is managed by:', '["Increasing immunosuppression","Reducing immunosuppression","Antiviral therapy with cidofovir","Both B and C","Plasmapheresis"]'::jsonb, 'Both B and C', 'BK virus nephropathy is managed by reducing immunosuppression and optionally adding antiviral therapy.'),
('a460b2e5-8e43-50ce-9ccb-b44758197875'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which viral infection is most problematic in the first month after kidney transplantation?', '["BK virus","CMV","EBV","JC virus","Hepatitis B"]'::jsonb, 'BK virus', 'BK virus reactivation is most common in the first 3-6 months post-transplant when immunosuppression is highest.'),
('61d4836a-fe05-5bd7-af38-10dcbc07b409'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'CMV prophylaxis in transplant recipients is typically given for how long?', '["1 month","3-6 months","12 months","Lifetime","No prophylaxis needed"]'::jsonb, '3-6 months', 'CMV prophylaxis (valganciclovir) is typically given for 3-6 months post-transplant.'),
('88bfae58-daca-5cc9-a7cc-3d2f5733594c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which condition is characterized by antibody-mediated transplant glomerulopathy?', '["Acute cellular rejection","Chronic antibody-mediated rejection","Drug nephrotoxicity","BK virus nephropathy","Recurrent FSGS"]'::jsonb, 'Chronic antibody-mediated rejection', 'Transplant glomerulopathy with double contours on GBM is pathognomonic of chronic antibody-mediated rejection.'),
('bb508443-383f-5cbf-97d3-f06b548cb69d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'The most important donor factor affecting kidney transplant outcome is:', '["Donor age","Donor HLA match and kidney quality","Donor blood type only","Donor gender","Donor ethnicity"]'::jsonb, 'Donor HLA match and kidney quality', 'HLA matching, kidney quality (KDPI score), and donor factors collectively determine transplant outcomes.'),
('4949ec95-e206-5888-826f-b6b07b132328'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Protocol biopsy findings of borderline changes in a kidney transplant are managed by:', '["Immediate ATG treatment resulting in decreased functional activity","Enhanced immunosuppression or close monitoring","Graft nephrectomy mediated by specific receptor activation","No action needed without affecting the primary tissue pathway","IVIG treatment leading to subsequent cellular adaptation"]'::jsonb, 'Enhanced immunosuppression or close monitoring', 'Borderline changes may represent early rejection; management involves enhanced immunosuppression or close surveillance.'),
('255ef997-3d8c-5201-a6f6-394382e1b1ba'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Immunosuppression in liver transplant differs from kidney transplant in that:', '["No immunosuppression is needed","Lower rates of acute rejection occur","Higher doses of CNIs are required","Steroids are contraindicated","No HLA matching is done"]'::jsonb, 'Lower rates of acute rejection occur', 'The liver is considered a relatively tolerogenic organ with lower rates of acute rejection.'),
('da87fbd5-a0d6-54ec-88a0-8cccb587007b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which transplant has the highest rate of chronic rejection?', '["Kidney","Liver","Heart","Lung","Pancreas"]'::jsonb, 'Lung', 'Lung transplants have the highest rates of both acute and chronic rejection (bronchiolitis obliterans syndrome).'),
('27c36dec-458e-587a-8bf0-210b177279b3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Chronic lung allograft dysfunction is characterized by which pathological process?', '["Transplant glomerulopathy","Bronchiolitis obliterans","Cardiac allograft vasculopathy","Graft cirrhosis","Pancreatic fibrosis"]'::jsonb, 'Bronchiolitis obliterans', 'Bronchiolitis obliterans (constrictive bronchiolitis) is the hallmark of chronic lung allograft dysfunction.'),
('2a48d179-a9ab-58f6-ba83-ca9244b6bba8'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cardiac allograft vasculopathy is the leading cause of late death after heart transplant because it:', '["Only affects large coronary arteries","Involves diffuse intimal hyperplasia of all coronary vessels","Is identical to native atherosclerosis","Only affects graft muscle","Only causes arrhythmias"]'::jsonb, 'Involves diffuse intimal hyperplasia of all coronary vessels', 'Cardiac allograft vasculopathy involves concentric diffuse intimal thickening of entire coronary vasculature.'),
('1bf7f235-d25d-52b2-86bf-e0bbfbb6393c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which factor is most important in determining the choice of immunosuppressive regimen after kidney transplantation?', '["Cost only resulting in decreased functional activity","Immunological risk profile and patient characteristics","Physician preference mediated by specific receptor activation","Drug availability without affecting the primary tissue pathway","Insurance coverage leading to subsequent cellular adaptation"]'::jsonb, 'Immunological risk profile and patient characteristics', 'Regimen selection is individualized based on immunological risk, age, and comorbidities.'),
('6a859b07-6952-5001-9758-4a81e4916446'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Donor-derived cell-free DNA (dd-cfDNA) testing is used for:', '["Pre-transplant crossmatching resulting in decreased functional activity","Non-invasive detection of graft injury and rejection","HLA typing mediated by specific receptor activation","Infection screening without affecting the primary tissue pathway","Drug level monitoring leading to subsequent cellular adaptation"]'::jsonb, 'Non-invasive detection of graft injury and rejection', 'dd-cfDNA in recipient blood serves as a biomarker for graft injury, helping detect rejection non-invasively.'),
('80156ed5-91f0-50fc-8b26-44ba3636164f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which immunosuppressant is safe during pregnancy among those used in transplantation?', '["Mycophenolate mofetil","Sirolimus","Tacrolimus","Leflunomide","Methotrexate"]'::jsonb, 'Tacrolimus', 'Tacrolimus is considered relatively safe in pregnancy (Category C) and is preferred over teratogenic drugs.'),
('8e233a42-0ccd-5bf8-a22b-e5ce0cb2ab13'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is a mechanical barrier contraceptive required with mycophenolate?', '["Oral contraceptive pill only","IUD only","Barrier method (condom) or IUD","No contraception needed","Only abstinence"]'::jsonb, 'Barrier method (condom) or IUD', 'Women of childbearing age on MMF must use highly effective contraception due to teratogenicity.'),
('49c29f32-647e-59b8-84c6-183318e4598b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Infliximab drug levels and anti-drug antibodies are measured to:', '["Monitor for TB reactivation","Assess therapeutic response and guide dosing","Screen for hepatitis B","Check for anaphylaxis risk","Monitor liver function"]'::jsonb, 'Assess therapeutic response and guide dosing', 'Therapeutic drug monitoring of infliximab trough levels and anti-drug antibodies helps optimize dosing.'),
('8c3f9d05-cf8e-5e40-ad2e-e8ed29f61690'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Loss of response to infliximab may be managed by:', '["Switching to another anti-TNF","Dose escalation","Adding immunomodulator","All of the above","Stopping all biologics"]'::jsonb, 'All of the above', 'Secondary loss of response can be managed by dose escalation, adding immunomodulator, or switching classes.'),
('4d5b6e27-fc29-5d6b-bd94-5daa89b41829'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Belatacept is a fusion protein that blocks which costimulatory pathway?', '["CD40-CD40L","CD80/CD86-CD28","PD-1-PD-L1","CTLA-4-B7","LFA-1-ICAM-1"]'::jsonb, 'CD80/CD86-CD28', 'Belatacept is a CTLA4-Ig fusion protein that blocks CD80/CD86-CD28 costimulation in kidney transplantation.'),
('edb56fb8-ad38-5cc6-9686-53a8b6ee2c35'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the main advantage of belatacept over calcineurin inhibitors?', '["Lower cost resulting in decreased functional activity","No nephrotoxicity and better long-term graft survival","Oral administration mediated by specific receptor activation","No drug interactions without affecting the primary tissue pathway","Fewer infections leading to subsequent cellular adaptation"]'::jsonb, 'No nephrotoxicity and better long-term graft survival', 'Belatacept is not nephrotoxic and has demonstrated better long-term GFR and graft survival.'),
('d77551ee-d256-5b8d-9c25-ff97be3ef4c1'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is a significant limitation of belatacept?', '["Nephrotoxicity","Higher rate of acute rejection","Bone marrow suppression","Hyperlipidemia","Gingival hyperplasia"]'::jsonb, 'Higher rate of acute rejection', 'Belatacept is associated with a higher rate of acute cellular rejection and risk of PTLD.'),
('f1c9a64c-a04a-5da7-8a4b-be04481ca8bc'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Steroid avoidance protocols in kidney transplantation have been developed to minimize:', '["Rejection only resulting in decreased functional activity","Long-term metabolic and bone complications of steroids","Drug interactions mediated by specific receptor activation","Infection risk only without affecting the primary tissue pathway","Cost leading to subsequent cellular adaptation"]'::jsonb, 'Long-term metabolic and bone complications of steroids', 'Steroid avoidance protocols aim to reduce metabolic syndrome, diabetes, osteoporosis, and cardiovascular risk.'),
('e297201e-ed13-5bf6-9190-c3413b3755d0'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which agent is most commonly used for steroid avoidance in kidney transplantation?', '["Azathioprine","Belatacept","MMF only","Sirolimus","None"]'::jsonb, 'Belatacept', 'Belatacept-based regimens allow more successful steroid avoidance due to potent costimulation blockade without nephrotoxicity.'),
('49b99790-99f9-5450-b6be-9ffd103ab2f3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Graft-versus-host disease (GVHD) occurs when donor T cells attack which tissues?', '["Only the transplanted organ","Recipient skin, liver, and GI tract","Only the bone marrow","Only the lungs","Only the kidneys"]'::jsonb, 'Recipient skin, liver, and GI tract', 'Acute GVHD classically affects skin (rash), liver (jaundice), and GI tract (diarrhea, vomiting).'),
('034ecdde-3a5a-5291-945e-092c8c28531f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which grade of acute GVHD is life-threatening with severe organ damage?', '["Grade I","Grade II","Grade III","Grade IV","All grades"]'::jsonb, 'Grade IV', 'Grade IV acute GVHD involves severe involvement of skin (>80% BSA or bullae), liver (bilirubin >10 mg/dL), and GI tract, carrying high mortality.'),
('f1e24317-fc2d-5aa6-99e1-892f4b99bf51'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'First-line treatment for acute GVHD is:', '["Cyclosporine","High-dose corticosteroids","Methotrexate","Rituximab","Infliximab"]'::jsonb, 'High-dose corticosteroids', 'High-dose methylprednisolone (2 mg/kg/day) is the standard first-line treatment for acute GVHD.'),
('86725bf3-12d5-5a32-adb1-fe7fe28d1214'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which calcineurin inhibitor is used for GVHD prophylaxis?', '["Tacrolimus","Sirolimus","Mycophenolate","Azathioprine","Cyclophosphamide"]'::jsonb, 'Tacrolimus', 'Tacrolimus (with or without methotrexate) is the most common regimen for GVHD prophylaxis after allogeneic HSCT.'),
('b467f682-eb05-5e82-8e72-78bbd46517e7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Chronic GVHD commonly affects which organ system first?', '["Lungs resulting in decreased functional activity","Eyes and mouth (sicca syndrome)","Kidneys mediated by specific receptor activation","Heart without affecting the primary tissue pathway","Pancreas leading to subsequent cellular adaptation"]'::jsonb, 'Eyes and mouth (sicca syndrome)', 'Chronic GVHD often presents with sicca-like syndrome (dry eyes, dry mouth) resembling Sjogren syndrome.'),
('2f042fce-fa28-577a-8a3f-a58318cab1e4'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Extracorporeal photopheresis is used to treat which type of GVHD?', '["Acute GVHD only","Chronic GVHD","Hyperacute GVHD","None","Prevention of GVHD"]'::jsonb, 'Chronic GVHD', 'Extracorporeal photopheresis is effective for steroid-refractory chronic GVHD, particularly with skin involvement.'),
('c312c95c-4838-52e2-9f3d-51cc8597dce7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ruxolitinib is approved for treatment of which type of GVHD?', '["Acute GVHD","Chronic GVHD","Both acute and chronic GVHD","Hyperacute GVHD","None"]'::jsonb, 'Both acute and chronic GVHD', 'Ruxolitinib (JAK1/JAK2 inhibitor) is FDA-approved for both steroid-refractory acute and chronic GVHD.'),
('4690da2d-44a6-5cc7-afc3-a4bab4b366df'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which donor type has the lowest risk of GVHD?', '["Haploidentical donor","Mismatched unrelated donor","HLA-matched sibling donor","Umbilical cord blood","Mismatched family donor"]'::jsonb, 'HLA-matched sibling donor', 'HLA-matched sibling donors have the lowest risk of GVHD due to HLA identity.'),
('f47905a2-a937-56cd-8b1b-a97a71c50eac'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Post-transplant cyclophosphamide is used to prevent GVHD in which transplant setting?', '["Solid organ transplant","Haploidentical bone marrow transplant","Kidney transplant","Liver transplant","Heart transplant"]'::jsonb, 'Haploidentical bone marrow transplant', 'Post-transplant cyclophosphamide selectively eliminates alloreactive T cells in haploidentical HSCT.'),
('f481a7c7-fb24-5c0d-98ac-944b4797e690'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'The graft-versus-leukemia effect is mediated by which cells?', '["Donor B cells","Donor T cells and NK cells","Recipient T cells","Donor dendritic cells","Recipient NK cells"]'::jsonb, 'Donor T cells and NK cells', 'The graft-versus-leukemia effect is primarily mediated by donor CD8+ cytotoxic T cells and NK cells.'),
('4e7d1592-0a46-5c4d-a7f5-945673f7a448'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which cytokine is most elevated during acute GVHD?', '["IL-10","IL-2","TNF-alpha and IL-2","TGF-beta","IL-4"]'::jsonb, 'TNF-alpha and IL-2', 'Acute GVHD is characterized by elevated TNF-alpha and IL-2 produced by donor T cells.'),
('f96b4b84-1031-5c45-b4f7-2f2b8262a422'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which type of GVHD is associated with scleroderma-like skin changes?', '["Acute GVHD","Chronic GVHD","Hyperacute GVHD","Late acute GVHD","Overlap syndrome"]'::jsonb, 'Chronic GVHD', 'Chronic GVHD can cause scleroderma-like skin fibrosis, lichenoid changes, and sicca syndrome.'),
('2c415ccb-e0f9-570e-a898-fbf057fe26b1'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which type of GVHD affects the eyes with keratoconjunctivitis sicca?', '["Acute GVHD","Chronic GVHD","Both equally","Hyperacute GVHD","Neither"]'::jsonb, 'Chronic GVHD', 'Keratoconjunctivitis sicca (dry eyes) is a classic manifestation of chronic GVHD.'),
('73873643-920c-511d-87b1-1b8341a54cc9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'What is the standard first-line treatment for chronic GVHD?', '["Methotrexate resulting in decreased functional activity","Corticosteroids plus calcineurin inhibitor","Rituximab mediated by specific receptor activation","Sirolimus without affecting the primary tissue pathway","Cyclophosphamide leading to subsequent cellular adaptation"]'::jsonb, 'Corticosteroids plus calcineurin inhibitor', 'Corticosteroids (prednisolone) combined with a calcineurin inhibitor is standard first-line for chronic GVHD.'),
('33a3a1f8-0c9e-5eb8-a4e4-f7dca0443517'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Antithymocyte globulin (ATG) is produced in which animal?', '["Mouse","Rabbit or horse","Goat","Sheep","Monkey"]'::jsonb, 'Rabbit or horse', 'ATG is produced by immunizing rabbits (thymoglobulin) or horses (ATGAM) with human thymocytes.'),
('ce71fb95-9bbb-54ca-ad1f-9aa93c0a53bc'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'ATG (antithymocyte globulin) works by:', '["Inhibiting calcineurin resulting in decreased functional activity","Depleting T lymphocytes via complement-dependent lysis","Blocking IL-2 receptor mediated by specific receptor activation","Inhibiting mTOR without affecting the primary tissue pathway","Blocking TNF-alpha leading to subsequent cellular adaptation"]'::jsonb, 'Depleting T lymphocytes via complement-dependent lysis', 'ATG is a polyclonal antibody that depletes T cells through complement-dependent cytotoxicity and opsonization.'),
('f6cd1d03-b2ea-5ab2-9cb1-8120cf8733bb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Basiliximab is a monoclonal antibody that targets which receptor?', '["CD20 resulting in decreased functional activity","CD52 accompanied by associated clinical symptoms","CD25 (IL-2 receptor alpha chain)","CD3 without affecting the primary tissue pathway","CD4 leading to subsequent cellular adaptation"]'::jsonb, 'CD25 (IL-2 receptor alpha chain)', 'Basiliximab is a chimeric anti-CD25 monoclonal antibody that blocks IL-2-mediated T-cell activation.'),
('63e30552-5d9d-52ac-9099-5c2671fb19e3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Alemtuzumab targets which antigen on lymphocytes?', '["CD20","CD52","CD25","CD3","CD4"]'::jsonb, 'CD52', 'Alemtuzumab is a humanized anti-CD52 monoclonal antibody that causes profound and prolonged T and B cell depletion.'),
('2f31e971-5b79-55c2-9de5-8dd994f30ef7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Alemtuzumab in transplantation is typically used for:', '["Maintenance therapy","Induction therapy in high-immunological-risk patients","Treatment of chronic rejection","Treatment of infection","Prevention of hyperacute rejection"]'::jsonb, 'Induction therapy in high-immunological-risk patients', 'Alemtuzumab provides profound lymphocyte depletion and is used as induction therapy in high-risk transplant recipients.'),
('7d86d3ac-6534-55ad-80e9-cfc02963a8ac'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which cytokine storm complication can occur with CAR-T cell therapy?', '["Cytokine release syndrome (CRS)","Tumor lysis syndrome","Graft-versus-host disease","Hyperacute rejection","Serum sickness"]'::jsonb, 'Cytokine release syndrome (CRS)', 'CAR-T cell therapy can cause severe CRS due to massive activation and cytokine release from engineered T cells.'),
('0ae93d03-61eb-56d6-8f8f-9211767ffb2d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tocilizumab is used for which transplant-related complication?', '["Acute rejection","Chronic rejection","CAR-T cell cytokine release syndrome","Hyperacute rejection","GVHD prevention"]'::jsonb, 'CAR-T cell cytokine release syndrome', 'Tocilizumab (anti-IL-6R) is FDA-approved for treatment of CAR-T cell-induced cytokine release syndrome.'),
('56d2fabe-4060-5476-a0ae-1f2ac38b977d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Interferon-alpha primarily activates which immune cells?', '["B lymphocytes resulting in decreased functional activity","NK cells and cytotoxic T lymphocytes","Platelets mediated by specific receptor activation","Erythrocytes without affecting the primary tissue pathway","Neutrophils leading to subsequent cellular adaptation"]'::jsonb, 'NK cells and cytotoxic T lymphocytes', 'IFN-alpha enhances NK cell cytotoxicity and promotes CTL-mediated killing of virus-infected and tumor cells.'),
('7856e3c0-fa21-568f-b9f5-84c776bc79f6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which interferon is primarily used for chronic hepatitis C treatment (historically)?', '["Interferon-beta","Interferon-gamma","Pegylated interferon-alpha","Interferon-lambda","Interferon-omega"]'::jsonb, 'Pegylated interferon-alpha', 'Pegylated IFN-alpha was the backbone of hepatitis C therapy before direct-acting antivirals.'),
('7ce45a63-ea40-560c-98b5-027a27c419f9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Interferon-beta is used in the treatment of which autoimmune disease?', '["Rheumatoid arthritis resulting in decreased functional activity","Relapsing-remitting multiple sclerosis","Crohn disease mediated by specific receptor activation","Lupus nephritis without affecting the primary tissue pathway","Psoriasis leading to subsequent cellular adaptation"]'::jsonb, 'Relapsing-remitting multiple sclerosis', 'IFN-beta reduces relapse rate and disability progression in relapsing-remitting MS.'),
('02540611-7c0d-5a61-b075-9c73b5aadda6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Interferon-gamma is used to treat which immunodeficiency?', '["X-linked agammaglobulinemia","Chronic granulomatous disease","Severe combined immunodeficiency","DiGeorge syndrome","Common variable immunodeficiency"]'::jsonb, 'Chronic granulomatous disease', 'IFN-gamma enhances macrophage oxidative burst and is approved for reducing infection frequency in CGD.'),
('f04700e6-8261-5f25-90f0-c1b5d48e0a77'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Common side effects of interferon therapy include:', '["Weight gain and hyperglycemia resulting in decreased functional activity","Flu-like symptoms, fatigue, and depression","Hypertension mediated by specific receptor activation","Constipation without affecting the primary tissue pathway","Increased appetite leading to subsequent cellular adaptation"]'::jsonb, 'Flu-like symptoms, fatigue, and depression', 'Interferon therapy commonly causes flu-like symptoms, fatigue, depression, and cytopenias.'),
('f4f166c6-adb5-57d7-99e9-b1bb66595dfd'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Thalidomide is used in the treatment of which condition?', '["Rheumatoid arthritis","Erythema nodosum leprosum","Asthma","Hypertension","Diabetes"]'::jsonb, 'Erythema nodosum leprosum', 'Thalidomide is approved for ENL and multiple myeloma. It has anti-TNF, antiangiogenic, and immunomodulatory properties.'),
('2137ab4a-fa02-57b4-a00d-d65cfb4cead9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Thalidomide''s mechanism in ENL involves which action?', '["Directly killing bacteria","Inhibiting TNF-alpha production by monocytes","Stimulating antibody production","Activating complement","Increasing NK cell activity"]'::jsonb, 'Inhibiting TNF-alpha production by monocytes', 'Thalidomide inhibits TNF-alpha production by monocytes, suppressing ENL reactions.'),
('d7c3a17b-fe7a-5092-8333-a7e4be030724'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following is a major teratogenic effect of thalidomide?', '["Down syndrome","Phocomelia (limb malformations)","Cleft palate only","Heart defects only","Spina bifida"]'::jsonb, 'Phocomelia (limb malformations)', 'Thalidomide causes severe limb malformations (phocomelia), ear abnormalities, and internal organ defects in pregnancy.'),
('2a5edbb1-d127-5604-b093-2111b26a583f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Lenalidomide differs from thalidomide in which way?', '["Lenalidomide is less potent resulting in decreased functional activity","Lenalidomide has additional immunomodulatory effects and is more potent","Lenalidomide is safer in pregnancy mediated by specific receptor activation","Lenalidomide has no teratogenicity without affecting the primary tissue pathway","Lenalidomide is only for ENL leading to subsequent cellular adaptation"]'::jsonb, 'Lenalidomide has additional immunomodulatory effects and is more potent', 'Lenalidomide is a more potent analog of thalidomide with enhanced immunomodulatory, anti-angiogenic, and anti-myeloma activity.'),
('facfb9c2-ff25-586c-b6bb-9a6d06199cb4'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Lenalidomide is particularly effective in myeloma with which cytogenetic abnormality?', '["t(4;14)","Deletion 5q","t(11;14)","Gain 1q","Del(17p)"]'::jsonb, 'Deletion 5q', 'Lenalidomide is particularly effective in MDS with del(5q) and in multiple myeloma.'),
('f5bf458f-3ac0-542a-9af4-837845e7e927'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Thalidomide REMS program requires which of the following?', '["Monthly blood tests only resulting in decreased functional activity","Two forms of contraception and regular pregnancy testing","Hospitalization mediated by specific receptor activation","Only prescription without affecting the primary tissue pathway","No special requirements leading to subsequent cellular adaptation"]'::jsonb, 'Two forms of contraception and regular pregnancy testing', 'Due to severe teratogenicity, thalidomide requires REMS enrollment with two forms of contraception and pregnancy tests.'),
('3f900c90-c944-5ace-b7fb-5a1dfe881409'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Baricitinib for rheumatoid arthritis inhibits which kinases?', '["JAK1 and JAK2","JAK3 only","TYK2 only","All JAKs","ERK and JNK"]'::jsonb, 'JAK1 and JAK2', 'Baricitinib is a selective JAK1/JAK2 inhibitor used for moderate-to-severe rheumatoid arthritis.'),
('5dbacbed-14dc-5e67-8786-985f078ecafe'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tofacitinib for RA primarily inhibits which JAK?', '["JAK1","JAK2","JAK3","JAK1 and JAK3","TYK2"]'::jsonb, 'JAK1 and JAK3', 'Tofacitinib primarily inhibits JAK1 and JAK3, with some JAK2 activity.'),
('421c6705-1f33-52de-845f-407ede648037'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Upadacitinib is a selective inhibitor of which JAK?', '["JAK1","JAK2","JAK3","TYK2","All JAKs"]'::jsonb, 'JAK1', 'Upadacitinib is a selective JAK1 inhibitor approved for RA, psoriatic arthritis, atopic dermatitis, and ulcerative colitis.'),
('f83eea7b-90ad-5bea-9373-b86a656ac26d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Filgotinib is a selective inhibitor of which JAK?', '["JAK1","JAK2","JAK3","TYK2","All JAKs"]'::jsonb, 'JAK1', 'Filgotinib is a selective JAK1 inhibitor approved for rheumatoid arthritis.'),
('22923b61-be94-546d-b359-b61c74df6139'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which JAK inhibitor has a boxed warning for cardiovascular events, malignancy, and thrombosis?', '["All JAK inhibitors equally","Tofacitinib only","Baricitinib only","Upadacitinib only","No JAK inhibitors have this warning"]'::jsonb, 'All JAK inhibitors equally', 'All JAK inhibitors carry boxed warnings for MACE, malignancy, thrombosis, and mortality based on ORAL Surveillance trial.'),
('450c0d5c-d360-55b9-8ff8-854647111db9'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Deucravacitinib is a selective inhibitor of which JAK family member?', '["JAK1","JAK2","JAK3","TYK2","All JAKs"]'::jsonb, 'TYK2', 'Deucravacitinib is a selective TYK2 inhibitor approved for moderate-to-severe plaque psoriasis.'),
('666478f5-033d-5aad-bc90-6c90060feab2'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'TYK2 inhibition primarily affects which cytokine signaling pathways?', '["IL-6 only resulting in decreased functional activity","IL-12, IL-23, and Type I interferons","TNF-alpha only mediated by specific receptor activation","IL-4 only without affecting the primary tissue pathway","IL-17 only leading to subsequent cellular adaptation"]'::jsonb, 'IL-12, IL-23, and Type I interferons', 'TYK2 mediates signaling of IL-12, IL-23, and Type I interferons, making it relevant for psoriasis and autoimmune conditions.'),
('5dc66d5a-7099-575d-aef4-70b8458f128c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which oral JAK inhibitor is available for ulcerative colitis?', '["Tofacitinib","Baricitinib","Upadacitinib","Filgotinib","All of the above"]'::jsonb, 'All of the above', 'Tofacitinib, filgotinib, and upadacitinib are all approved for moderate-to-severe ulcerative colitis.'),
('ef353499-877d-5eef-92bc-2dabd6a7ec54'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Peficitinib is a JAK inhibitor approved in which country for RA?', '["United States","Japan","United Kingdom","Germany","Australia"]'::jsonb, 'Japan', 'Peficitinib is a pan-JAK inhibitor approved in Japan for rheumatoid arthritis.'),
('e703d819-7948-5b48-997f-38b96ee8df0d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which of the following drugs inhibits JAK1/JAK2 and is used for GVHD?', '["Tofacitinib","Ruxolitinib","Baricitinib","Upadacitinib","Filgotinib"]'::jsonb, 'Ruxolitinib', 'Ruxolitinib is a JAK1/JAK2 inhibitor approved for treatment of acute and chronic GVHD.'),
('f5020d74-f554-5351-9a9a-4e972038e655'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which immunomodulatory drug is used for relapsing-remitting multiple sclerosis?', '["Dimethyl fumarate","Teriflunomide","Fingolimod","All of the above","None of the above"]'::jsonb, 'All of the above', 'Dimethyl fumarate, teriflunomide, and fingolimod are all oral disease-modifying therapies for relapsing-remitting MS.'),
('7b6089aa-862b-58d2-8c3f-d916b006b08d'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Fingolimod works by which mechanism?', '["JAK inhibition resulting in decreased functional activity","Sphingosine-1-phosphate (S1P) receptor modulation","CD20 depletion mediated by specific receptor activation","TNF-alpha inhibition without affecting the primary tissue pathway","Calcineurin inhibition leading to subsequent cellular adaptation"]'::jsonb, 'Sphingosine-1-phosphate (S1P) receptor modulation', 'Fingolimod is an S1P receptor modulator that sequesters lymphocytes in lymph nodes, preventing CNS infiltration.'),
('8f6b41f8-aa19-5778-9f5b-dcf8ca37a6da'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Natalizumab, used in MS, blocks which integrin?', '["LFA-1","Alpha-4 integrin (VLA-4)","Alpha-L integrin","Alpha-M integrin","Alpha-X integrin"]'::jsonb, 'Alpha-4 integrin (VLA-4)', 'Natalizumab blocks alpha-4 integrin on lymphocytes, preventing migration across the blood-brain barrier.'),
('ee4ed524-e0ec-5e76-97af-9bbe23c1aa5f'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which infection risk is specifically associated with natalizumab?', '["Tuberculosis resulting in decreased functional activity","Progressive multifocal leukoencephalopathy (PML)","Hepatitis B reactivation mediated by specific receptor activation","Cytomegalovirus without affecting the primary tissue pathway","Pneumocystis pneumonia leading to subsequent cellular adaptation"]'::jsonb, 'Progressive multifocal leukoencephalopathy (PML)', 'Natalizumab carries a significant risk of PML due to JC virus reactivation, especially with prolonged use.'),
('53503009-c355-5db0-8030-3aad150246b0'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Vedolizumab differs from natalizumab in that vedolizumab is gut-selective because it targets:', '["Alpha-4 integrin","Alpha-4-beta-7 integrin","LFA-1","CD20","TNF-alpha"]'::jsonb, 'Alpha-4-beta-7 integrin', 'Vedolizumab selectively blocks alpha-4-beta-7 integrin, preventing lymphocyte homing specifically to the gut.'),
('3ad60c55-4621-5130-b920-2e9f2a65cf2e'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Vedolizumab is indicated for which gastrointestinal condition?', '["GERD","Ulcerative colitis and Crohn disease","Celiac disease","Irritable bowel syndrome","Peptic ulcer disease"]'::jsonb, 'Ulcerative colitis and Crohn disease', 'Vedolizumab is a gut-selective integrin inhibitor approved for moderate-to-severe ulcerative colitis and Crohn disease.'),
('42b10a05-d742-5a35-8d31-440c8421b5cb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Natalizumab is contraindicated in patients who are:', '["HLA-B51 positive resulting in decreased functional activity","JC virus antibody positive with prior immunosuppression","EBV seronegative mediated by specific receptor activation","CMV positive without affecting the primary tissue pathway","HIV positive leading to subsequent cellular adaptation"]'::jsonb, 'JC virus antibody positive with prior immunosuppression', 'Natalizumab is contraindicated in JC virus-positive patients with prior immunosuppression due to high PML risk.'),
('5c4169cf-6b43-5ec4-891c-75d78c187a20'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ocrelizumab is used for which form of MS?', '["Relapsing-remitting MS only","Primary progressive MS and relapsing-remitting MS","Secondary progressive MS only","Clinically isolated syndrome only","Neuromyelitis optica"]'::jsonb, 'Primary progressive MS and relapsing-remitting MS', 'Ocrelizumab (anti-CD20) is approved for both relapsing-remitting MS and primary progressive MS.'),
('90bbdfed-7517-501d-8eaa-80e2a80dd45a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ocrelizumab differs from rituximab in that ocrelizumab is:', '["Chimeric resulting in decreased functional activity","Humanized (higher human content than rituximab)","Fully human mediated by specific receptor activation","Small molecule without affecting the primary tissue pathway","Fusion protein leading to subsequent cellular adaptation"]'::jsonb, 'Humanized (higher human content than rituximab)', 'Ocrelizumab is a humanized anti-CD20 antibody with >90% human protein content, compared to 65% for rituximab.'),
('c23460a0-c817-5c6b-adb0-7a6e7815791c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Interferon beta-1a is available in which formulations?', '["IM and SC injection","Only IV","Oral only","Inhalation","Topical"]'::jsonb, 'IM and SC injection', 'Interferon beta-1a (Avonex) is given IM weekly and (Rebif) is given SC three times weekly.'),
('7da8d49c-ce08-5af4-8128-9d9bda5bb42b'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which interferon for MS causes the most injection site reactions?', '["Interferon beta-1a IM","Interferon beta-1b SC","Peginterferon beta-1a","Interferon alpha","Interferon gamma"]'::jsonb, 'Interferon beta-1b SC', 'Subcutaneous interferon beta-1b (Betaseron) causes more injection site reactions than intramuscular formulations.'),
('b6fe24ff-fb30-5fc8-ba61-5e731e984917'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Teriflunomide is contraindicated in which condition due to teratogenicity?', '["Diabetes","Pregnancy","Hypertension","Asthma","Thyroid disease"]'::jsonb, 'Pregnancy', 'Teriflunomide is teratogenic (FDA Category X) and absolutely contraindicated in pregnancy.'),
('68db34aa-01e9-5e9f-ae87-89a37bb324a4'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Dimethyl fumarate should be monitored for which hematological complication?', '["Thrombocytosis","Lymphopenia","Polycythemia","Neutrophilia","Eosinophilia"]'::jsonb, 'Lymphopenia', 'Dimethyl fumarate can cause lymphopenia, which should be monitored; severe lymphopenia increases PML risk.'),
('769eb161-ab74-5718-b15c-90260d33fd12'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Alemtuzumab for MS carries risk of which autoimmune complication?', '["Type 1 diabetes resulting in decreased functional activity","Secondary autoimmune conditions including thyroid disorders","Rheumatoid arthritis mediated by specific receptor activation","Lupus without affecting the primary tissue pathway","Psoriasis leading to subsequent cellular adaptation"]'::jsonb, 'Secondary autoimmune conditions including thyroid disorders', 'Alemtuzumab carries a risk of secondary autoimmunity, particularly thyroid disease, requiring monitoring.'),
('efc5cdae-3c72-555c-8922-19444221cd48'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Cladribine for MS works by which mechanism?', '["CD20 depletion resulting in decreased functional activity","Selective purine analog toxic to lymphocytes","S1P modulation mediated by specific receptor activation","TNF inhibition without affecting the primary tissue pathway","JAK inhibition leading to subsequent cellular adaptation"]'::jsonb, 'Selective purine analog toxic to lymphocytes', 'Cladribine is a purine analog selectively taken up by lymphocytes, causing DNA damage and apoptosis.'),
('66adb7a5-9eb4-55c3-9a80-90cb539def94'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which drug is an anti-CD19 monoclonal antibody?', '["Rituximab","Ocrelizumab","Belimumab","Inebilizumab","Ofatumumab"]'::jsonb, 'Inebilizumab', 'Inebilizumab is an anti-CD19 monoclonal antibody approved for neuromyelitis optica spectrum disorder.'),
('4065ce91-1847-58c7-8b6f-4dc83f811c2c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Inebilizumab for neuromyelitis optica works by depleting which cells?', '["CD20+ B cells","CD19+ B cells","CD8+ T cells","NK cells","Neutrophils"]'::jsonb, 'CD19+ B cells', 'Inebilizumab depletes CD19+ B cells, including plasmablasts that produce pathogenic aquaporin-4 antibodies.'),
('b2177181-8b40-5b42-87e0-7239ac525610'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Satralizumab for NMOSD targets which cytokine receptor?', '["IL-5 receptor","IL-6 receptor","IL-17 receptor","IL-4 receptor","IL-23 receptor"]'::jsonb, 'IL-6 receptor', 'Satralizumab is an anti-IL-6 receptor monoclonal antibody approved for NMOSD in aquaporin-4 antibody-positive patients.'),
('eb19d9f1-6991-50ec-82df-6a63d0e61269'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent targets CD19 for autoimmune conditions?', '["Rituximab","Inebilizumab","Belimumab","Ocrelizumab","Ofatumumab"]'::jsonb, 'Inebilizumab', 'Inebilizumab targets CD19 on B cells, which has broader B-cell coverage than CD20-targeted rituximab.'),
('c1c6ad2a-0255-54b7-adc5-35d60fb27e91'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Obinutuzumab is a glycoengineered anti-CD20 antibody that differs from rituximab in:', '["Different target resulting in decreased functional activity","Enhanced ADCC and direct cell death induction","Oral formulation mediated by specific receptor activation","Different isotype without affecting the primary tissue pathway","No difference leading to subsequent cellular adaptation"]'::jsonb, 'Enhanced ADCC and direct cell death induction', 'Obinutuzumab is glycoengineered for enhanced Fc-mediated effector functions and increased direct cell death.'),
('8dbb9b29-2676-5989-b15d-99f31f25f3de'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ofatumumab is a fully human anti-CD20 monoclonal antibody used for:', '["RA only resulting in decreased functional activity","Chronic lymphocytic leukemia and relapsing MS","Psoriasis mediated by specific receptor activation","Asthma without affecting the primary tissue pathway","Lupus leading to subsequent cellular adaptation"]'::jsonb, 'Chronic lymphocytic leukemia and relapsing MS', 'Ofatumumab is approved for CLL and as a self-injected SC therapy for relapsing MS.'),
('12364699-38e3-525d-9e85-256bdf2c0139'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Natalizumab use is restricted by which risk management program?', '["REMS for thalidomide","TOUCH prescribing program","REMS for isotretinoin","No restricted program","REMS for clozapine"]'::jsonb, 'TOUCH prescribing program', 'The TOUCH (Tysabri Outreach: Unified Commitment to Health) program monitors for PML risk with natalizumab.'),
('0109dcfa-8854-54b0-a22b-3c9262d00ef3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic is effective in both plaque psoriasis and psoriatic arthritis?', '["Adalimumab","Secukinumab","Ustekinumab","All of the above","Rituximab"]'::jsonb, 'All of the above', 'Adalimumab, secukinumab, and ustekinumab are all approved for both plaque psoriasis and psoriatic arthritis.'),
('59fd423e-0c8a-52eb-afc0-733182d49a00'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which monoclonal antibody targets IL-5 for severe eosinophilic asthma?', '["Omalizumab","Mepolizumab","Dupilumab","Rituximab","Tocilizumab"]'::jsonb, 'Mepolizumab', 'Mepolizumab is a humanized anti-IL-5 monoclonal antibody that reduces eosinophil-mediated inflammation.'),
('d7e6f626-7fcd-5974-8d34-63982f4e367a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Reslizumab for severe asthma differs from mepolizumab in that reslizumab is given by:', '["Subcutaneous injection","IV infusion","Oral","Inhalation","Intramuscular injection"]'::jsonb, 'IV infusion', 'Reslizumab (anti-IL-5) is given as an IV infusion every 4 weeks, unlike mepolizumab which is SC.'),
('95454c8a-c17d-5e0f-a609-d1be78b1f192'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Benralizumab for severe asthma depletes eosinophils by targeting which receptor?', '["IL-5 receptor alpha","IL-4 receptor","IL-13 receptor","CD20","IgE receptor"]'::jsonb, 'IL-5 receptor alpha', 'Benralizumab binds IL-5Ralpha and induces direct apoptosis of eosinophils and basophils through enhanced ADCC.'),
('a5d634e9-f437-5666-a416-fc2620f358fe'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tezepelumab targets which epithelial-derived cytokine for severe asthma?', '["IL-25 resulting in decreased functional activity","IL-33 accompanied by associated clinical symptoms","TSLP (thymic stromal lymphopoietin)","IL-1beta without affecting the primary tissue pathway","TNF-alpha leading to subsequent cellular adaptation"]'::jsonb, 'TSLP (thymic stromal lymphopoietin)', 'Tezepelumab blocks TSLP, an alarmin released by airway epithelial cells, reducing Type 2 inflammation.'),
('33f6897c-c1d1-5cf2-baf0-4ccff5f7d990'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Omalizumab is a monoclonal antibody that targets which molecule?', '["IgE","IL-5","IL-4","TNF-alpha","CD20"]'::jsonb, 'IgE', 'Omalizumab is an anti-IgE monoclonal antibody that binds free IgE, preventing it from binding to mast cells and basophils.'),
('632755eb-74c3-5d6c-bd8e-4cc12425ef63'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Omalizumab is indicated for which conditions?', '["Allergic asthma and chronic idiopathic urticaria","COPD accompanied by associated clinical symptoms","Bronchiectasis mediated by specific receptor activation","Pneumonia without affecting the primary tissue pathway","Pulmonary fibrosis leading to subsequent cellular adaptation"]'::jsonb, 'Allergic asthma and chronic idiopathic urticaria', 'Omalizumab is approved for moderate-to-severe allergic asthma and chronic spontaneous urticaria.'),
('1dae779c-7159-593f-b959-d4adbaad1269'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Secukinumab is a monoclonal antibody targeting which cytokine?', '["IL-1","IL-6","IL-12","IL-17A","IL-23"]'::jsonb, 'IL-17A', 'Secukinumab is a human monoclonal antibody that selectively binds and neutralizes IL-17A.'),
('986e50d1-e430-5fd2-8315-141e452e79d5'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ustekinumab targets which cytokine subunits?', '["IL-1 and IL-6","IL-12 and IL-23 (p40 subunit)","TNF-alpha and IL-17","IL-4 and IL-13","IL-5 and IL-33"]'::jsonb, 'IL-12 and IL-23 (p40 subunit)', 'Ustekinumab binds the p40 subunit shared by IL-12 and IL-23, inhibiting Th1 and Th17 cell differentiation.'),
('f1b854f1-42c4-55cf-8591-5dde549564d6'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic agent targets IL-17A for psoriasis treatment?', '["Adalimumab","Secukinumab","Ustekinumab","Rituximab","Tocilizumab"]'::jsonb, 'Secukinumab', 'Secukinumab is a human anti-IL-17A monoclonal antibody highly effective for moderate-to-severe plaque psoriasis.'),
('c1cfe6f9-6241-50e4-8ab8-6b80b4e36dd3'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ixekizumab is a monoclonal antibody targeting which cytokine?', '["TNF-alpha","IL-23","IL-17A","IL-6","IL-1"]'::jsonb, 'IL-17A', 'Ixekizumab is an anti-IL-17A monoclonal antibody used for plaque psoriasis, psoriatic arthritis, and ankylosing spondylitis.'),
('ca7b1f99-018a-5bbf-893e-f7827358018c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Guselkumab targets which subunit of IL-23?', '["p19 subunit","p40 subunit","p35 subunit","p12 subunit","p22 subunit"]'::jsonb, 'p19 subunit', 'Guselkumab selectively targets the p19 subunit of IL-23.'),
('1abbb793-2aa0-5a49-9f7e-2a37532baed8'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Brodalumab targets which component of the IL-17 pathway?', '["IL-17A directly","IL-17 receptor A (IL-17RA)","IL-17F","IL-23 receptor","IL-6 receptor"]'::jsonb, 'IL-17 receptor A (IL-17RA)', 'Brodalumab blocks IL-17 receptor A, preventing signaling from IL-17A, IL-17F, and IL-17E.'),
('e9b8524b-ba37-5fc8-a498-723560eceff7'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Apremilast is an oral drug for psoriasis that inhibits which enzyme?', '["PDE4 (phosphodiesterase 4)","COX-2 accompanied by associated clinical symptoms","JAK1 mediated by specific receptor activation","DHFR without affecting the primary tissue pathway","CYP3A4 leading to subsequent cellular adaptation"]'::jsonb, 'PDE4 (phosphodiesterase 4)', 'Apremilast inhibits PDE4, increasing intracellular cAMP and reducing inflammatory cytokine production.'),
('30deed21-5dbc-5577-a2f8-d937587b5cb2'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Dupilumab for atopic dermatitis blocks which cytokine receptor?', '["IL-4 receptor alpha resulting in decreased functional activity","IL-13 receptor accompanied by associated clinical symptoms","Both IL-4 and IL-13 signaling via IL-4Ralpha","IL-31 receptor without affecting the primary tissue pathway","IL-33 receptor leading to subsequent cellular adaptation"]'::jsonb, 'Both IL-4 and IL-13 signaling via IL-4Ralpha', 'Dupilumab blocks IL-4Ralpha, inhibiting both IL-4 and IL-13 signaling, the key Th2 cytokines driving atopic dermatitis.'),
('7941f552-00fc-5767-ab8e-07a7886a6bd2'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which IL-23 inhibitor is most effective for scalp psoriasis?', '["Adalimumab","Secukinumab","Guselkumab","Ustekinumab","All equally effective"]'::jsonb, 'Guselkumab', 'IL-23 inhibitors like guselkumab have shown excellent efficacy for scalp psoriasis specifically.'),
('5a70638a-d618-5971-a808-43b915d7b8fb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tildrakizumab is a monoclonal antibody targeting which cytokine?', '["IL-17A","IL-23 p19","IL-12/23 p40","TNF-alpha","IL-6"]'::jsonb, 'IL-23 p19', 'Tildrakizumab selectively targets the p19 subunit of IL-23.'),
('182abf4c-e52d-5349-ab2c-ba06a2ee70e2'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Risankizumab is a monoclonal antibody targeting which cytokine?', '["IL-17A","IL-23 p19","IL-12/23 p40","TNF-alpha","IL-6"]'::jsonb, 'IL-23 p19', 'Risankizumab selectively targets the p19 subunit of IL-23.'),
('47403ee7-879f-5c14-a765-410c49be6a10'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Secukinumab for psoriasis is given as which dosing schedule?', '["Weekly injections","Monthly injections","Every 2 weeks","Every 3 months after loading","Daily tablets"]'::jsonb, 'Every 3 months after loading', 'Secukinumab is given weekly for 5 weeks (loading), then every 4 weeks (300 mg SC).'),
('5115f94b-ba62-5d1a-8b96-b5440b4890a1'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Ixekizumab dosing for plaque psoriasis involves which schedule?', '["Monthly SC injection","Every 2 weeks after loading","Every 4 weeks from start","Weekly oral","IV infusion"]'::jsonb, 'Every 2 weeks after loading', 'Ixekizumab is given at weeks 0, 1, 2, 3, 4, then every 2 weeks (80 mg SC).'),
('03eb3b55-2de2-5000-b5f7-a6a42c75e485'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Brodalumab for psoriasis has a unique dosing of:', '["Monthly injection","Every 2 weeks","Every 4 weeks","Weekly for 12 weeks then monthly","Every 12 weeks"]'::jsonb, 'Every 2 weeks', 'Brodalumab is given at weeks 0, 1, 2, then every 2 weeks (210 mg SC).'),
('a6ed9b65-3dd1-5779-8d70-bb9dac51eacb'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Guselkumab for psoriasis is dosed at:', '["100 mg every 4 weeks from start","100 mg at weeks 0 and 4, then every 8 weeks","200 mg monthly","Weekly injections","Every 2 weeks"]'::jsonb, '100 mg at weeks 0 and 4, then every 8 weeks', 'Guselkumab is given at weeks 0 and 4, then every 8 weeks (100 mg SC).'),
('6dd8ef95-4530-57df-b1ee-7365a43686ca'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Risankizumab for psoriasis is dosed at:', '["Weekly for 4 weeks resulting in decreased functional activity","150 mg at weeks 0 and 4, then every 12 weeks","Monthly injection mediated by specific receptor activation","Every 2 weeks without affecting the primary tissue pathway","Every 8 weeks from start leading to subsequent cellular adaptation"]'::jsonb, '150 mg at weeks 0 and 4, then every 12 weeks', 'Risankizumab is given at weeks 0 and 4, then every 12 weeks (150 mg SC).'),
('a9baab13-1fd5-597f-bf5d-9c74d17fc60c'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Tildrakizumab for psoriasis is dosed at:', '["Weekly injection resulting in decreased functional activity","100 mg at weeks 0 and 4, then every 12 weeks","Every 2 weeks mediated by specific receptor activation","Monthly without affecting the primary tissue pathway","Every 8 weeks leading to subsequent cellular adaptation"]'::jsonb, '100 mg at weeks 0 and 4, then every 12 weeks', 'Tildrakizumab is given at weeks 0 and 4, then every 12 weeks (100 mg SC).'),
('5ba3c2af-3ddc-514a-97b3-2259a9772457'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Crisaborole topical for atopic dermatitis belongs to which drug class?', '["Corticosteroid","Calcineurin inhibitor","PDE4 inhibitor","Antihistamine","Antibiotic"]'::jsonb, 'PDE4 inhibitor', 'Crisaborole is a topical benzoxaborole PDE4 inhibitor for mild-to-moderate atopic dermatitis in patients aged 3 months and older.'),
('57e8a618-231d-58ab-9943-1cdca99b7e6a'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'The black box warning for topical calcineurin inhibitors relates to:', '["Nephrotoxicity resulting in decreased functional activity","Risk of lymphoma with long-term use","Skin cancer mediated by specific receptor activation","Infection without affecting the primary tissue pathway","Allergic reaction leading to subsequent cellular adaptation"]'::jsonb, 'Risk of lymphoma with long-term use', 'There is a theoretical concern about lymphoma risk with long-term topical calcineurin inhibitor use, though evidence is limited.'),
('fec5304b-a1a4-5727-bf94-680e265a3bc8'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which topical drug is a PDE4 inhibitor for atopic dermatitis?', '["Tacrolimus","Pimecrolimus","Crisaborole","Methotrexate","Hydrocortisone"]'::jsonb, 'Crisaborole', 'Crisaborole is a topical PDE4 inhibitor that reduces inflammation in mild-to-moderate atopic dermatitis.'),
('45fead4d-a4c4-5806-a6ec-3637c39bfd87'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Secukinumab is administered by which route?', '["Oral","IV infusion","Subcutaneous injection","Intramuscular injection","Topical"]'::jsonb, 'Subcutaneous injection', 'Secukinumab is administered as a subcutaneous injection for plaque psoriasis and psoriatic arthritis.'),
('a4b43ffd-fb69-58dc-b91c-c5bf78e58b03'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Golimumab for ulcerative colitis is administered by which route?', '["IV infusion","Subcutaneous injection","Oral","Intramuscular injection","Topical"]'::jsonb, 'Subcutaneous injection', 'Golimumab for UC is given as a subcutaneous injection every 2 weeks after induction dosing.'),
('9946f84b-bb9e-5aae-8444-9ec82c221815'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which interleukin is targeted by secukinumab?', '["IL-1","IL-6","IL-12","IL-17A","IL-23"]'::jsonb, 'IL-17A', 'Secukinumab is a human monoclonal antibody that selectively binds and neutralizes IL-17A.'),
('d1d43765-6954-510c-9fcf-24267349ae00'::uuid, 'Pharmacology (Paper 2)', 'Immunopharmacology - Immunopharmacology', 'Which biologic drug first received FDA approval for both psoriasis and Crohn disease?', '["Adalimumab","Infliximab","Ustekinumab","Secukinumab","Rituximab"]'::jsonb, 'Infliximab', 'Infliximab was the first biologic approved for both Crohn disease (1998) and plaque psoriasis (2006).'),
('8b7fea13-ffeb-5e5d-805b-e2d69c537ea1'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vitamin is a coenzyme for carboxylase reactions involving biotin?', '["Thiamine","Riboflavin","Biotin","Niacin","Pantothenic acid"]'::jsonb, 'Biotin', 'Biotin acts as a coenzyme for carboxylase reactions such as pyruvate carboxylase, acetyl-CoA carboxylase, and propionyl-CoA carboxylase. It is involved in gluconeogenesis, fatty acid synthesis, and amino acid catabolism.'),
('f3249c2c-05d4-59ac-99f4-9d1398c0d3fe'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'A patient presents with night blindness, xerophthalmia, and follicular hyperkeratosis. Which vitamin deficiency is most likely?', '["Vitamin D","Vitamin A","Vitamin C","Vitamin E","Vitamin K"]'::jsonb, 'Vitamin A', 'Vitamin A deficiency causes night blindness (nyctalopia), xerophthalmia, and follicular hyperkeratosis. Vitamin A is essential for rhodopsin synthesis in retinal photoreceptors and for epithelial cell differentiation.'),
('b42de5c4-40fa-5561-8c7f-010c4600b39a'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which fat-soluble vitamin is essential for the gamma-carboxylation of glutamic acid residues in clotting factors II, VII, IX, and X?', '["Vitamin A","Vitamin D","Vitamin E","Vitamin K","Folic acid"]'::jsonb, 'Vitamin K', 'Vitamin K is required for the gamma-carboxylation of glutamic acid residues to gamma-carboxyglutamic acid (Gla) in clotting factors II, VII, IX, and X, as well as proteins C, S, and Z. This carboxylation is essential for calcium-mediated binding to phospholipid surfaces.'),
('5ca6eff9-4d2f-5b8e-9fe3-d7eb1ef72bd8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Scurvy is caused by deficiency of which vitamin?', '["Vitamin A","Vitamin B1","Vitamin B12","Vitamin C","Vitamin D"]'::jsonb, 'Vitamin C', 'Vitamin C (ascorbic acid) deficiency causes scurvy. Vitamin C is a cofactor for prolyl hydroxylase and lysyl hydroxylase, which are essential for collagen synthesis. Deficiency leads to impaired collagen formation causing bleeding gums, poor wound healing, and petechiae.'),
('59b7cd0f-6b10-57ee-9303-48674f8b7bb5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vitamin deficiency causes beriberi?', '["Vitamin B1 (Thiamine)","Vitamin B2 (Riboflavin)","Vitamin B3 (Niacin)","Vitamin B6 (Pyridoxine)","Vitamin B12 (Cobalamin)"]'::jsonb, 'Vitamin B1 (Thiamine)', 'Thiamine (Vitamin B1) deficiency causes beriberi. Thiamine is a coenzyme for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase. Wet beriberi involves high-output cardiac failure; dry beriberi involves peripheral neuropathy.'),
('182d2ba0-c206-5965-9952-d562752ecdcd'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'A patient on long-term warfarin presents with ecchymoses. Which vitamin would reverse the anticoagulant effect?', '["Vitamin A","Vitamin C","Vitamin D","Vitamin E","Vitamin K"]'::jsonb, 'Vitamin K', 'Vitamin K (phytonadione) reverses the anticoagulant effect of warfarin. Warfarin inhibits vitamin K epoxide reductase (VKORC1), preventing recycling of vitamin K. Administering vitamin K replenishes the active hydroquinone form needed for clotting factor carboxylation.'),
('ef206e0a-8727-5304-a48e-f909f2188dfb'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Pellagra is characterized by the triad of dermatitis, diarrhea, and dementia. It is caused by deficiency of which vitamin?', '["Thiamine","Riboflavin","Niacin (Vitamin B3)","Pyridoxine","Folic acid"]'::jsonb, 'Niacin (Vitamin B3)', 'Pellagra is caused by niacin (Vitamin B3) deficiency and is classically characterized by the 3 Ds: dermatitis, diarrhea, and dementia. If untreated, it leads to death (the 4th D). Niacin is a precursor of NAD and NADP, essential for oxidation-reduction reactions.'),
('d4d34d29-7775-5400-9612-cf060cf74bb6'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vitamin is used therapeutically in the treatment of megaloblastic anemia due to folate deficiency?', '["Vitamin B1","Vitamin B6","Vitamin B12","Folic acid (Vitamin B9)","Vitamin C"]'::jsonb, 'Folic acid (Vitamin B9)', 'Folic acid (Vitamin B9) is used to treat megaloblastic anemia caused by folate deficiency. Folate is essential for thymidylate synthesis and DNA synthesis. Deficiency leads to impaired DNA synthesis and megaloblastic changes in rapidly dividing cells.'),
('c2cc4579-cf14-5112-a3ab-fd7ebb0826b1'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Vitamin D deficiency in children causes which condition?', '["Scurvy","Rickets","Osteomalacia","Beriberi","Pellagra"]'::jsonb, 'Rickets', 'Vitamin D deficiency in children causes rickets, characterized by impaired mineralization of growth plates and osteoid. Features include bowed legs, rachitic rosary, craniotabes, and delayed fontanelle closure. In adults, the same deficiency causes osteomalacia.'),
('b39a81f1-1930-5e2e-80a2-c268f7c7b7d0'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a fat-soluble vitamin?', '["Vitamin B1","Vitamin B12","Vitamin C","Vitamin D","Folic acid"]'::jsonb, 'Vitamin D', 'Vitamins A, D, E, and K are fat-soluble vitamins. They are absorbed with dietary fats via lymphatic system and can be stored in liver and adipose tissue. Water-soluble vitamins (B complex and C) are not stored significantly and excess is excreted in urine.'),
('b648922d-2d4a-5ec9-a5d4-164c3f2ec5cf'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'A patient on isoniazid therapy develops peripheral neuropathy. Which vitamin supplement should be given?', '["Vitamin A","Vitamin B6 (Pyridoxine)","Vitamin B12","Vitamin C","Vitamin K"]'::jsonb, 'Vitamin B6 (Pyridoxine)', 'Isoniazid (INH) interferes with pyridoxine (Vitamin B6) metabolism by inhibiting pyridoxal phosphate-dependent enzymes. This can cause peripheral neuropathy. Pyridoxine supplementation (10-25 mg daily) is given prophylactically with INH therapy.'),
('a65086df-d1e5-5b6c-bb3b-f245f398a40b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Vitamin E functions primarily as which of the following?', '["Anticoagulant","Antioxidant","Procoagulant","Calcium regulator","Iron chelator"]'::jsonb, 'Antioxidant', 'Vitamin E (alpha-tocopherol) is the major lipid-soluble antioxidant in cell membranes. It protects polyunsaturated fatty acids from peroxidation by free radicals. Deficiency causes hemolytic anemia, spinocerebellar ataxia, and myopathy.'),
('3ef2d777-aa9b-56ca-bd22-6671aff94220'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following vitamins has the highest risk of toxicity due to storage in the liver?', '["Vitamin B1","Vitamin B6","Vitamin C","Vitamin A","Vitamin B12"]'::jsonb, 'Vitamin A', 'Vitamin A is fat-soluble and stored in the liver, making it prone to hypervitaminosis. Chronic excess causes raised intracranial pressure, hepatotoxicity, dry skin, alopecia, and teratogenicity. Acute toxicity causes headache, nausea, and papilledema.'),
('8c725f3b-28b5-5df9-822b-860b944eec7c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vitamin is essential for the conversion of homocysteine to methionine?', '["Vitamin B1","Vitamin B6","Vitamin B12 and Folic acid","Vitamin C","Vitamin K"]'::jsonb, 'Vitamin B12 and Folic acid', 'Both Vitamin B12 (cobalamin) and folic acid are required for the conversion of homocysteine to methionine. Folic acid provides the methyl group (as 5-methyl THF) and Vitamin B12 acts as a cofactor for methionine synthase. Deficiency of either leads to hyperhomocysteinemia.'),
('9243725a-e15f-5efb-b359-c857b709a5b8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Megaloblastic anemia with neurological symptoms (subacute combined degeneration) is characteristic of deficiency of:', '["Iron","Folic acid","Vitamin B12","Vitamin B6","Vitamin C"]'::jsonb, 'Vitamin B12', 'Vitamin B12 deficiency causes megaloblastic anemia AND neurological manifestations including subacute combined degeneration of the spinal cord (posterior and lateral columns). Folate deficiency causes megaloblastic anemia but NOT neurological symptoms. B12 is essential for myelin synthesis.'),
('211ee664-a52f-5185-ad39-0a3fa1774809'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is NOT a water-soluble vitamin?', '["Thiamine","Riboflavin","Vitamin K","Niacin","Ascorbic acid"]'::jsonb, 'Vitamin K', 'Vitamin K is a fat-soluble vitamin along with Vitamins A, D, and E. Thiamine (B1), Riboflavin (B2), Niacin (B3), and Ascorbic acid (Vitamin C) are all water-soluble vitamins.'),
('341f3d04-2857-533d-812c-bbc890b3228c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Rickets in children is best prevented by supplementation with:', '["Vitamin A","Vitamin B12","Vitamin C","Vitamin D","Vitamin E"]'::jsonb, 'Vitamin D', 'Vitamin D (cholecalciferol) promotes intestinal calcium and phosphate absorption and is essential for bone mineralization. The recommended supplementation is 400 IU/day for infants. Deficiency causes rickets in children and osteomalacia in adults.'),
('6408f9db-859d-55c2-83fb-17ffb8277d77'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vitamin deficiency causes megaloblastic anemia but NO neurological manifestations?', '["Vitamin B12","Vitamin B6","Folic acid","Iron","Vitamin C"]'::jsonb, 'Folic acid', 'Folic acid deficiency causes megaloblastic anemia identical to B12 deficiency but does NOT cause neurological manifestations. This is an important distinguishing feature. B12 deficiency causes both megaloblastic anemia and subacute combined degeneration of the spinal cord.'),
('604e701b-a451-58c2-999f-bf3eb147fa20'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which IV potassium preparation is available for clinical use?', '["Potassium chloride","Potassium sulfate","Potassium phosphate","Potassium citrate","Potassium carbonate"]'::jsonb, 'Potassium chloride', 'Potassium chloride (KCl) is the standard IV potassium preparation. It is always administered in normal saline (not glucose, which causes insulin release and K+ shift intracellularly). Maximum peripheral IV rate is 10 mEq/hour; central line allows up to 40 mEq/hour.'),
('b52065f5-170d-5c75-a778-bf2115451e9b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The normal serum potassium level is:', '["2.5-3.5 mEq/L","3.5-5.0 mEq/L","5.0-6.5 mEq/L","6.5-8.0 mEq/L","1.5-2.5 mEq/L"]'::jsonb, '3.5-5.0 mEq/L', 'Normal serum potassium is 3.5-5.0 mEq/L. Hypokalemia (<3.5 mEq/L) causes muscle weakness, cardiac arrhythmias (U waves), and ileus. Hyperkalemia (>5.0 mEq/L) causes peaked T waves, widened QRS, and cardiac arrest.'),
('ae7aa8c0-02cc-5c93-8f59-e223ece74714'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Treatment of acute hyperkalemia with ECG changes includes all EXCEPT:', '["IV calcium gluconate","IV insulin with glucose","Sodium bicarbonate","Oral potassium supplements","Nebulized salbutamol"]'::jsonb, 'Oral potassium supplements', 'Oral potassium supplements are contraindicated in hyperkalemia. Acute management includes: IV calcium gluconate (membrane stabilizer), IV insulin+glucose (shifts K+ intracellularly), sodium bicarbonate (corrects acidosis), nebulized salbutamol (beta-2 agonist shifts K+ intracellularly), and Kayexalate (removes K+ from body).'),
('5102d09c-29e9-53fd-97b9-845ddac5b679'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used to treat hypercalcemia?', '["Calcium gluconate","Normal saline infusion","Vitamin D","Thiazide diuretics","Calcitonin only"]'::jsonb, 'Normal saline infusion', 'Normal saline infusion is the first-line treatment for acute hypercalcemia. Saline promotes calciuresis by expanding volume and increasing renal calcium excretion. Loop diuretics (furosemide) may be added after hydration. Calcitonin and bisphosphonates are also used.'),
('43569b55-4f13-5b11-aa0a-47e3de45fe3c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The normal serum calcium level is:', '["6.0-8.0 mg/dL","8.5-10.5 mg/dL","11.0-13.0 mg/dL","13.0-15.0 mg/dL","5.0-7.0 mg/dL"]'::jsonb, '8.5-10.5 mg/dL', 'Normal total serum calcium is 8.5-10.5 mg/dL (2.1-2.6 mmol/L). Hypocalcemia causes Chvostek''s sign (facial twitch) and Trousseau''s sign (carpopedal spasm). Hypercalcemia causes ''stones, bones, groans, and psychiatric moans.'''),
('10493c86-4640-5953-b811-76d1264b0d3c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Chvostek''s sign and Trousseau''s sign are seen in:', '["Hypercalcemia","Hypocalcemia","Hyperkalemia","Hypokalemia","Hypermagnesemia"]'::jsonb, 'Hypocalcemia', 'Chvostek''s sign (twitching of facial muscles on tapping the facial nerve) and Trousseau''s sign (carpopedal spasm induced by inflating BP cuff above systolic for 3 minutes) are classic signs of hypocalcemia. They result from increased neuromuscular excitability due to low ionized calcium.'),
('ba989921-21a3-5010-bcd2-191faa4e8d82'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used to treat acute magnesium toxicity?', '["Calcium gluconate IV","Sodium bicarbonate","Normal saline","Insulin with glucose","Kayexalate"]'::jsonb, 'Calcium gluconate IV', 'IV calcium gluconate is the antidote for magnesium toxicity. Calcium antagonizes the effects of magnesium at the neuromuscular junction and cardiac conduction system. This is important in managing magnesium toxicity from eclampsia treatment or renal failure.'),
('f97d3032-dcc2-5776-b002-0f543e51a7f7'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which electrolyte abnormality causes peaked T waves on ECG?', '["Hypokalemia","Hyperkalemia","Hypocalcemia","Hypercalcemia","Hypomagnesemia"]'::jsonb, 'Hyperkalemia', 'Hyperkalemia causes peaked (tall, narrow) T waves, flattened P waves, widened QRS complex, and eventually a sine wave pattern leading to cardiac arrest. Peaked T waves are the earliest ECG manifestation of hyperkalemia.'),
('dcfa4d05-c50b-5a7e-9687-dfd5868482f5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which electrolyte abnormality causes U waves on ECG?', '["Hyperkalemia","Hypokalemia","Hypercalcemia","Hypocalcemia","Hypermagnesemia"]'::jsonb, 'Hypokalemia', 'Hypokalemia causes flattened T waves, ST depression, and prominent U waves on ECG. U waves are small deflections after the T wave. Severe hypokalemia predisposes to ventricular arrhythmias including torsades de pointes.'),
('a7e168cf-f106-59eb-adc9-433dbce00ea0'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Oral rehydration solution (ORS) contains which of the following as the primary osmotic agent?', '["Sodium chloride","Potassium chloride","Glucose","Sodium bicarbonate","Calcium chloride"]'::jsonb, 'Glucose', 'Glucose is the primary osmotic agent in ORS. It promotes sodium and water absorption in the small intestine via the sodium-glucose cotransporter (SGLT1). The WHO reduced-osmolarity ORS contains 75 mmol/L sodium, 75 mmol/L glucose, 20 mmol/L potassium, 10 mmol/L citrate.'),
('ee568859-f829-57c7-9ef3-3efe82946e0f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'IV magnesium sulfate is used in the management of:', '["Diabetes mellitus","Eclampsia","Hypertension","Asthma","Heart failure"]'::jsonb, 'Eclampsia', 'IV magnesium sulfate is the drug of choice for prevention and treatment of eclamptic seizures. It acts as an anticonvulsant by blocking NMDA receptors and as a vasodilator. Therapeutic level is 4-7 mg/dL. Toxicity causes loss of deep tendon reflexes, respiratory depression, and cardiac arrest.'),
('5efe09af-b90c-54bc-bf68-2cf4b8d8997d'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The treatment of choice for digoxin-induced hyperkalemia is:', '["Sodium bicarbonate","Calcium gluconate","Insulin with glucose","Kayexalate","Dialysis"]'::jsonb, 'Kayexalate', 'Kayexalate (sodium polystyrene sulfonate) is used for digoxin-induced hyperkalemia. Calcium is relatively contraindicated as it may worsen digoxin toxicity (though recent evidence suggests it may be used cautiously). Insulin+glucose shifts K+ intracellularly but doesn''t remove it. Dialysis is reserved for refractory cases.'),
('da3ac0ee-961c-5776-83ae-4d0c15e9a05a'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Normal saline (0.9% NaCl) has a sodium concentration of:', '["90 mEq/L","154 mEq/L","54 mEq/L","308 mEq/L","200 mEq/L"]'::jsonb, '154 mEq/L', 'Normal saline (0.9% NaCl) contains 154 mEq/L of sodium and 154 mEq/L of chloride, making it slightly hypotonic to plasma. It is isotonic in terms of osmolality (308 mOsm/L). It is used for fluid resuscitation and as a vehicle for IV medications.'),
('79fc37aa-50f6-5c90-be63-ce7f7f79c498'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which IV fluid is most appropriate for a patient with diabetic ketoacidosis?', '["Normal saline","Dextrose 5%","Ringer''s lactate","0.45% normal saline","Dextrose 10%"]'::jsonb, 'Normal saline', 'Initial fluid resuscitation in DKA uses normal saline (0.9% NaCl). After initial bolus, fluids are typically switched to 0.45% NaCl when serum sodium is normal or high. Dextrose is added when blood glucose falls below 200-300 mg/dL to prevent hypoglycemia while continuing insulin.'),
('d6562b69-31fa-5fbe-a8d1-086148821072'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a component of Ringer''s lactate solution?', '["Sodium, potassium, calcium, chloride, lactate","Sodium, chloride, glucose","Sodium, potassium, chloride only","Sodium, calcium, bicarbonate","Potassium, magnesium, chloride"]'::jsonb, 'Sodium, potassium, calcium, chloride, lactate', 'Ringer''s lactate (Hartmann''s solution) contains sodium 130 mEq/L, potassium 4 mEq/L, calcium 3 mEq/L, chloride 109 mEq/L, and lactate 28 mEq/L. Lactate is converted to bicarbonate in the liver. It is preferred over normal saline for trauma and surgery to avoid hyperchloremic metabolic acidosis.'),
('87889247-db84-5e5b-8c5b-c6120104417d'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Hypomagnesemia commonly causes which other electrolyte abnormality?', '["Hyperkalemia resulting in decreased functional activity","Hypercalcemia accompanied by associated clinical symptoms","Refractory hypokalemia and hypocalcemia","Hypernatremia without affecting the primary tissue pathway","Hyperphosphatemia leading to subsequent cellular adaptation"]'::jsonb, 'Refractory hypokalemia and hypocalcemia', 'Hypomagnesemia causes refractory hypokalemia and hypocalcemia. Magnesium is needed for proper PTH secretion and action, and for renal potassium conservation. Hypokalemia and hypocalcemia that do not correct with supplementation should prompt checking magnesium levels.'),
('64308d2d-2f9b-53de-929d-dc38fa7c5239'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which diuretic is most likely to cause hypokalemia?', '["Spironolactone","Amiloride","Furosemide","Triamterene","Eplerenone"]'::jsonb, 'Furosemide', 'Loop diuretics (furosemide) and thiazides cause hypokalemia by increasing sodium delivery to the distal tubule, enhancing potassium secretion. Potassium-sparing diuretics (spironolactone, amiloride, triamterene) do not cause hypokalemia.'),
('6149b93b-9c7b-5583-a1c3-4eb41938dee9'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'IV calcium is given slowly over at least 10 minutes to prevent:', '["Hypotension resulting in decreased functional activity","Severe bradycardia and cardiac arrest","Hyperkalemia mediated by specific receptor activation","Seizures without affecting the primary tissue pathway","Nausea and vomiting leading to subsequent cellular adaptation"]'::jsonb, 'Severe bradycardia and cardiac arrest', 'IV calcium should be given slowly over at least 10 minutes (preferably 20-30 minutes) to prevent severe bradycardia and cardiac arrest. Rapid IV calcium can cause cardiac arrest. The usual dose is 10 mL of 10% calcium gluconate over 10-20 minutes.'),
('3ec3ba69-94b0-5561-9a5c-1dc2248b3e94'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Hydroxychloroquine is commonly used in the treatment of:', '["Tuberculosis resulting in decreased functional activity","Rheumatoid arthritis and systemic lupus erythematosus","Asthma mediated by specific receptor activation","Diabetes mellitus without affecting the primary tissue pathway","Heart failure leading to subsequent cellular adaptation"]'::jsonb, 'Rheumatoid arthritis and systemic lupus erythematosus', 'Hydroxychloroquine is a disease-modifying antirheumatic drug (DMARD) used in rheumatoid arthritis and SLE. It inhibits toll-like receptor signaling and antigen presentation. Long-term use requires monitoring for retinal toxicity (annual eye exam after 5 years).'),
('b6dcb6ed-a5b1-5c54-92ec-7994818a6432'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following DMARDs requires regular monitoring of FBC and LFTs due to risk of bone marrow suppression and hepatotoxicity?', '["Hydroxychloroquine","Sulfasalazine","Penicillamine","Leflunomide","All of the above"]'::jsonb, 'All of the above', 'All DMARDs (hydroxychloroquine, sulfasalazine, penicillamine, leflunomide, methotrexate) require regular monitoring of FBC and LFTs. They can cause bone marrow suppression, hepatotoxicity, and other serious adverse effects. Regular monitoring allows early detection and management.'),
('95a345e9-f256-5473-b072-fe278e87730f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Methotrexate toxicity is reversed by administering:', '["Vitamin B12","Folinic acid (Leucovorin)","Vitamin K","N-acetylcysteine","Vitamin C"]'::jsonb, 'Folinic acid (Leucovorin)', 'Folinic acid (leucovorin) is the rescue agent for methotrexate toxicity. It provides tetrahydrofolate bypassing the block at DHFR. It is also used to reduce toxicity in high-dose methotrexate chemotherapy. Folic acid supplementation is given routinely with low-dose methotrexate.'),
('c7b5fee3-b2de-59f5-8f68-d43d9e761d02'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Sulfasalazine is used in the treatment of:', '["Only rheumatoid arthritis","Inflammatory bowel disease and rheumatoid arthritis","Only ulcerative colitis","Only Crohn''s disease","Systemic lupus erythematosus only"]'::jsonb, 'Inflammatory bowel disease and rheumatoid arthritis', 'Sulfasalazine is used in both inflammatory bowel disease (ulcerative colitis and Crohn''s) and rheumatoid arthritis. It is cleaved by colonic bacteria into sulfapyridine (active in IBD) and 5-aminosalicylic acid (anti-inflammatory). It is a DMARD for RA.'),
('0808f414-78d8-53ae-aeeb-7ad1227b9dd9'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which biologic DMARD is a TNF-alpha inhibitor used in rheumatoid arthritis?', '["Rituximab","Etanercept","Tocilizumab","Abatacept","Anakinra"]'::jsonb, 'Etanercept', 'Etanercept is a TNF-alpha inhibitor (fusion protein of TNF receptor and IgG1 Fc) used in rheumatoid arthritis. Other TNF inhibitors include infliximab, adalimumab, golimumab, and certolizumab. They are used when conventional DMARDs fail.'),
('b9927926-d5fc-5fe5-b4b5-1bfadf57afb4'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Rituximab is a monoclonal antibody directed against which antigen?', '["TNF-alpha","CD20 on B cells","IL-6 receptor","CD4 on T cells","CTLA-4"]'::jsonb, 'CD20 on B cells', 'Rituximab is a chimeric monoclonal antibody against CD20, a surface marker on B lymphocytes. It depletes B cells and is used in rheumatoid arthritis, non-Hodgkin lymphoma, and ANCA-associated vasculitis. It causes B-cell depletion for 6-12 months.'),
('926ef1ef-a63a-56fa-b52f-8bdccc6bdb1a'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a JAK inhibitor used in rheumatoid arthritis?', '["Tofacitinib","Etanercept","Rituximab","Abatacept","Tocilizumab"]'::jsonb, 'Tofacitinib', 'Tofacitinib is a Janus kinase (JAK) inhibitor used in rheumatoid arthritis. It blocks JAK1/JAK3 signaling, inhibiting cytokine-mediated immune responses. It is an oral DMARD used when biologics fail. Side effects include infections, herpes zoster, and thromboembolism.'),
('873a56b1-c679-524c-83cb-93b5a311edc2'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Azathioprine is metabolized to which active compound?', '["Methotrexate","6-mercaptopurine","Mycophenolate","Cyclosporine","Tacrolimus"]'::jsonb, '6-mercaptopurine', 'Azathioprine is a prodrug converted to 6-mercaptopurine (6-MP) by glutathione and other sulfhydryl-containing compounds. 6-MP is further metabolized by HGPRT to active thioguanine nucleotides that inhibit purine synthesis. TPMT deficiency increases toxicity risk.'),
('c1d4268a-8c43-53c3-ae27-f970fdf4c05f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Cyclosporine acts by inhibiting which enzyme?', '["Dihydrofolate reductase","Calcineurin","Xanthine oxidase","Phosphodiesterase","ACE"]'::jsonb, 'Calcineurin', 'Cyclosporine binds to cyclophilin, and this complex inhibits calcineurin, a phosphatase needed for T-cell activation. This prevents IL-2 transcription and T-cell proliferation. It is used in organ transplantation and autoimmune diseases. Nephrotoxicity is a major side effect.'),
('cb7b653a-32ee-57d2-bac4-b56dce9c45cb'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is NOT a biologic DMARD?', '["Infliximab","Adalimumab","Leflunomide","Etanercept","Rituximab"]'::jsonb, 'Leflunomide', 'Leflunomide is a synthetic (non-biologic) DMARD that inhibits dihydroorotate dehydrogenase, blocking pyrimidine synthesis in lymphocytes. Infliximab, adalimumab, etanercept, and rituximab are all biologic DMARDs (monoclonal antibodies or fusion proteins).'),
('28dbb41d-6233-5bb1-83d0-511585349e40'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Mycophenolate mofetil is used in transplant rejection prophylaxis. It inhibits which enzyme?', '["Dihydrofolate reductase resulting in decreased functional activity","Inosine monophosphate dehydrogenase","Calcineurin mediated by specific receptor activation","Xanthine oxidase without affecting the primary tissue pathway","ACE leading to subsequent cellular adaptation"]'::jsonb, 'Inosine monophosphate dehydrogenase', 'Mycophenolate mofetil inhibits inosine monophosphate dehydrogenase (IMPDH), the rate-limiting enzyme in de novo purine synthesis in lymphocytes. Lymphocytes are uniquely dependent on this pathway (unlike other cells that use salvage pathways), making the drug selectively immunosuppressive.'),
('a83465b9-12b2-559b-a92a-96ea8fe2befc'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following biologic agents is an IL-6 receptor antagonist?', '["Infliximab","Tocilizumab","Adalimumab","Etanercept","Rituximab"]'::jsonb, 'Tocilizumab', 'Tocilizumab is a humanized monoclonal antibody against the IL-6 receptor. IL-6 is a key cytokine in RA pathogenesis promoting inflammation and joint destruction. Tocilizumab is used in RA and systemic juvenile idiopathic arthritis.'),
('d4da1d04-8bfa-518b-af85-21234ff470a3'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Infliximab is a chimeric monoclonal antibody against:', '["CD20","TNF-alpha","IL-1","CD4","CTLA-4"]'::jsonb, 'TNF-alpha', 'Infliximab is a chimeric (mouse/human) monoclonal antibody against TNF-alpha. It binds soluble and membrane-bound TNF-alpha, neutralizing its pro-inflammatory effects. Used in RA, Crohn''s disease, ankylosing spondylitis, and psoriatic arthritis.'),
('a4e601ce-7d40-54e6-887f-dac608d8f8ef'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Hydroxychloroquine should be discontinued if which ocular toxicity is detected?', '["Cataracts resulting in decreased functional activity","Retinal toxicity (bull''s eye maculopathy)","Glaucoma mediated by specific receptor activation","Conjunctivitis without affecting the primary tissue pathway","Keratoconus leading to subsequent cellular adaptation"]'::jsonb, 'Retinal toxicity (bull''s eye maculopathy)', 'Hydroxychloroquine can cause retinal toxicity (bull''s eye maculopathy) with chronic use. Risk increases after 5 years of use or cumulative dose >1000g. Annual screening with OCT and visual field testing is recommended. Early detection is crucial as damage may be irreversible.'),
('3fcbad0a-dc64-532a-b28c-c41e96f89aba'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is the most potent topical corticosteroid?', '["Hydrocortisone 1%","Betamethasone valerate","Clobetasol propionate","Triamcinolone acetonide","Fluticasone propionate"]'::jsonb, 'Clobetasol propionate', 'Clobetasol propionate (Group I) is the most potent topical corticosteroid available. It is used for severe, resistant dermatoses. Potency ranking: clobetasol > betamethasone > triamcinolone > hydrocortisone. Potent steroids should not be used on face, groin, or axillae.'),
('559282bd-cc4e-53cf-8eb2-0c3e9d458826'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Topical corticosteroids should be avoided on the face for prolonged periods due to risk of:', '["Contact dermatitis resulting in decreased functional activity","Steroid rosacea and skin atrophy","Vitiligo mediated by specific receptor activation","Psoriasis without affecting the primary tissue pathway","Eczema leading to subsequent cellular adaptation"]'::jsonb, 'Steroid rosacea and skin atrophy', 'Prolonged use of potent topical corticosteroids on the face causes steroid rosacea, perioral dermatitis, skin atrophy, telangiectasia, and striae. The face has thin skin with high absorption. Mild steroids (hydrocortisone) are preferred for facial use.'),
('f9cc2a0c-4997-517b-b93f-7d4dcc4b9f32'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which retinoid is used topically for acne vulgaris?', '["Isotretinoin","Tretinoin","Acitretin","Bexarotene","Alitretinoin"]'::jsonb, 'Tretinoin', 'Tretinoin (all-trans retinoic acid) is a topical retinoid used for acne vulgaris. It normalizes follicular keratinization, prevents comedone formation, and has anti-inflammatory effects. Side effects include local irritation, dryness, and photosensitivity (teratogenic).'),
('cec85a70-60d4-5fd9-8e47-f3985bf592c4'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which oral retinoid is used for severe nodulocystic acne?', '["Tretinoin","Adapalene","Isotretinoin","Tazarotene","Acitretin"]'::jsonb, 'Isotretinoin', 'Isotretinoin (13-cis retinoic acid) is the treatment of choice for severe nodulocystic acne unresponsive to other therapies. It reduces sebum production by 80%, shrinks sebaceous glands, and has anti-inflammatory and comedolytic effects. Major side effect: teratogenicity.'),
('cd5cba3f-be91-5272-9568-418c584c3036'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used topically for fungal skin infections?', '["Mupirocin","Clotrimazole","Betamethasone","Retinoids","Salicylic acid"]'::jsonb, 'Clotrimazole', 'Clotrimazole is an azole antifungal used topically for dermatophyte infections (tinea), candidiasis, and pityriasis versicolor. It inhibits ergosterol synthesis by inhibiting 14-alpha demethylase. Other topical antifungals include miconazole, terbinafine, and ketoconazole.'),
('a695559a-6d87-53ae-ade9-74b87456fb9e'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Permethrin is used in the treatment of:', '["Acne","Scabies and head lice","Psoriasis","Fungal infections","Viral warts"]'::jsonb, 'Scabies and head lice', 'Permethrin (5% cream) is the first-line treatment for scabies. It is a synthetic pyrethroid that causes paralysis and death of mites. For head lice, 1% permethrin lotion is used. It acts on sodium channels in parasites causing spastic paralysis.'),
('56889801-6b00-59c5-81ef-c2469a7a6b2b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Salicylic acid is used as a keratolytic agent in which condition?', '["Acne","Psoriasis and warts","Fungal infections","Eczema","Rosacea"]'::jsonb, 'Psoriasis and warts', 'Salicylic acid is a keratolytic agent that softens and dissolves keratin. It is used in psoriasis (removes scales), warts (debrides lesion), corns, and calluses. Available in various concentrations (0.5-30%). It works by disrupting desmosomes and reducing corneocyte cohesion.'),
('dcd54661-8a1a-5e7b-aee8-3bef68ea722c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following antifungal agents is available as oral therapy for onychomycosis?', '["Clotrimazole","Terbinafine","Mupirocin","Bacitracin","Polymyxin B"]'::jsonb, 'Terbinafine', 'Terbinafine is available orally for onychomycosis (fungal nail infection). It inhibits squalene epoxidase, blocking ergosterol synthesis. It is fungicidal against dermatophytes. Treatment duration is 6 weeks for fingernails and 12 weeks for toenails.'),
('7db7fa84-2e44-5551-9bbf-2a0ef4264c04'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Tacrolimus ointment is used for which dermatological condition?', '["Psoriasis","Atopic dermatitis","Acne","Fungal infections","Scabies"]'::jsonb, 'Atopic dermatitis', 'Tacrolimus ointment (0.03% and 0.1%) is a calcineurin inhibitor used for atopic dermatitis. It is a steroid-sparing agent that does not cause skin atrophy, making it suitable for face and flexures. Pimecrolimus cream is another option for mild-moderate atopic dermatitis.'),
('3ffefb6f-3a34-559c-8e54-abbf244b0dd3'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in the treatment of psoriasis?', '["Topical calcipotriol","Topical mupirocin","Topical permethrin","Topical acyclovir","Topical metronidazole"]'::jsonb, 'Topical calcipotriol', 'Calcipotriol (calcipotriene) is a vitamin D analogue used topically for plaque psoriasis. It inhibits keratinocyte proliferation and promotes differentiation. It can be combined with topical corticosteroids (calcipotriol/betamethasone). Other treatments: coal tar, dithranol, phototherapy.'),
('960e9238-039c-5606-a616-a4018f0cb412'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Mupirocin is used topically for:', '["Fungal infections resulting in decreased functional activity","Bacterial skin infections (impetigo)","Viral infections mediated by specific receptor activation","Psoriasis without affecting the primary tissue pathway","Eczema leading to subsequent cellular adaptation"]'::jsonb, 'Bacterial skin infections (impetigo)', 'Mupirocin is a topical antibiotic used for impetigo and other superficial staphylococcal and streptococcal skin infections. It inhibits bacterial protein synthesis by binding to isoleucyl-tRNA synthetase. Resistance can develop with prolonged use.'),
('6571436b-a827-5422-80f9-505d639466c3'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The vehicle of a topical steroid preparation affects its potency. Which vehicle provides the highest potency?', '["Lotion","Cream","Ointment","Gel","Powder"]'::jsonb, 'Ointment', 'Ointments provide the highest potency because they are occlusive, enhancing drug penetration. The potency order is: ointment > cream > lotion > gel. Ointments are best for dry, thickened lesions. Creams are better for weeping or intertriginous areas.'),
('abb5b8f5-fcb6-501b-b85f-01a41d2ebc8d'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Timolol is used in the treatment of glaucoma. It works by:', '["Increasing aqueous humor production","Decreasing aqueous humor production","Increasing aqueous humor outflow","Constricting the pupil","Dilating the pupil"]'::jsonb, 'Decreasing aqueous humor production', 'Timolol is a non-selective beta-blocker that reduces intraocular pressure by decreasing aqueous humor production by the ciliary body. It is first-line therapy for open-angle glaucoma. It should be avoided in asthma and heart failure patients.'),
('50d6fd3c-2783-58f0-b5e4-f9cf8119d501'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Pilocarpine is used in glaucoma. It works by:', '["Decreasing aqueous humor production","Increasing aqueous humor outflow by constricting the pupil","Blocking beta receptors","Inhibiting carbonic anhydrase","Blocking alpha receptors"]'::jsonb, 'Increasing aqueous humor outflow by constricting the pupil', 'Pilocarpine is a muscarinic agonist (miotic) that constricts the pupil, opening the trabecular meshwork and increasing aqueous humor outflow. It is used in acute angle-closure glaucoma and chronic open-angle glaucoma. Side effects include miosis and brow ache.'),
('4d4fb927-fe53-5c6e-8e52-330b5e52387f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Acetazolamide is used in glaucoma. It works by:', '["Blocking beta receptors","Inhibiting carbonic anhydrase in the ciliary body","Constricting the pupil","Increasing uveoscleral outflow","Blocking alpha receptors"]'::jsonb, 'Inhibiting carbonic anhydrase in the ciliary body', 'Acetazolamide is a carbonic anhydrase inhibitor that reduces aqueous humor production by inhibiting bicarbonate secretion in the ciliary body. It is used for acute angle-closure glaucoma and preoperative lowering of IOP. Side effects include paresthesias, metabolic acidosis, and hypokalemia.'),
('388de479-ed77-503a-a3cd-2a2cbf5ce1a1'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Latanoprost is used in glaucoma. It works by:', '["Decreasing aqueous humor production","Increasing uveoscleral outflow","Constricting the pupil","Blocking beta receptors","Inhibiting carbonic anhydrase"]'::jsonb, 'Increasing uveoscleral outflow', 'Latanoprost is a prostaglandin F2-alpha analogue that increases intraocular pressure by enhancing uveoscleral outflow. It is a first-line agent for open-angle glaucoma. Side effects include iris pigmentation changes, eyelash growth, and conjunctival hyperemia.'),
('682860f1-2291-5145-9d53-350e97a138a4'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which class of drugs is contraindicated in patients with angle-closure glaucoma?', '["Timolol","Pilocarpine","Mydriatics (e.g., atropine)","Latanoprost","Dorzolamide"]'::jsonb, 'Mydriatics (e.g., atropine)', 'Mydriatics (atropine, tropicamide) are contraindicated in angle-closure glaucoma because they dilate the pupil, which can block the trabecular meshwork and precipitate an acute attack. In angle-closure, the iris physically blocks aqueous humor drainage.'),
('60b8a994-be3a-5e4f-8303-283f34e9bc83'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Ranibizumab is an anti-VEGF agent used in the treatment of:', '["Glaucoma resulting in decreased functional activity","Wet age-related macular degeneration","Cataracts mediated by specific receptor activation","Conjunctivitis without affecting the primary tissue pathway","Keratoconus leading to subsequent cellular adaptation"]'::jsonb, 'Wet age-related macular degeneration', 'Ranibizumab is a monoclonal antibody fragment that inhibits VEGF-A. It is used for wet (neovascular) age-related macular degeneration (AMD). It is given by intravitreal injection monthly. Other anti-VEGF agents include bevacizumab and aflibercept.'),
('3f34ab59-5bc5-5083-9a36-e229090ea13c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used as an eye drop for glaucoma and causes pupil constriction?', '["Timolol","Latanoprost","Pilocarpine","Dorzolamide","Brimonidine"]'::jsonb, 'Pilocarpine', 'Pilocarpine is a miotic agent that constricts the pupil (miosis) and contracts the ciliary muscle. This opens the trabecular meshwork and increases aqueous humor outflow. It is used in acute angle-closure glaucoma (to break the attack) and chronic glaucoma.'),
('f52e56f2-7d13-5f26-a633-36f682302970'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Brimonidine is used in glaucoma. It works by:', '["Blocking beta receptors","Alpha-2 adrenergic agonist decreasing aqueous production","Inhibiting carbonic anhydrase","Prostaglandin analogue increasing outflow","Muscarinic agonist constricting pupil"]'::jsonb, 'Alpha-2 adrenergic agonist decreasing aqueous production', 'Brimonidine is a selective alpha-2 adrenergic agonist that reduces aqueous humor production and increases uveoscleral outflow. It is used in open-angle glaucoma. Side effects include allergic conjunctivitis and CNS depression (contraindicated in children).'),
('189309a1-b2ce-549a-8446-234fdbd8d1b4'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Prednisolone eye drops are used for:', '["Glaucoma only resulting in decreased functional activity","Inflammatory eye conditions (uveitis, keratitis)","Bacterial conjunctivitis mediated by specific receptor activation","Dry eyes without affecting the primary tissue pathway","Myopia leading to subsequent cellular adaptation"]'::jsonb, 'Inflammatory eye conditions (uveitis, keratitis)', 'Prednisolone acetate 1% eye drops are potent topical corticosteroids used for inflammatory eye conditions including anterior uveitis, keratitis, and post-operative inflammation. They should not be used in untreated bacterial/fungal/viral infections as they can worsen infection.'),
('3ef933b2-636c-51ce-a835-8ccc76479b3c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following glaucoma drugs can cause darkening of the iris?', '["Timolol","Latanoprost","Pilocarpine","Acetazolamide","Brimonidine"]'::jsonb, 'Latanoprost', 'Prostaglandin analogues (latanoprost, bimatoprost, travoprost) can cause irreversible iris pigmentation changes, particularly in patients with heterochromatic (brown) irides. This is due to increased melanin production in iris melanocytes. The effect is permanent even after discontinuation.'),
('bdf79c99-ebc8-5076-b409-6a99a397b283'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Dorzolamide is used in glaucoma. It works by:', '["Blocking beta receptors","Inhibiting carbonic anhydrase in the ciliary body","Increasing uveoscleral outflow","Constricting the pupil","Blocking alpha receptors"]'::jsonb, 'Inhibiting carbonic anhydrase in the ciliary body', 'Dorzolamide is a topical carbonic anhydrase inhibitor that reduces aqueous humor production. It is used as monotherapy or in combination with timolol. Side effects include bitter taste and superficial punctate keratopathy.'),
('55767433-52cc-5d7a-82ba-08e0376b0858'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'N-acetylcysteine (NAC) is the antidote for which poisoning?', '["Opioid overdose","Paracetamol (acetaminophen) overdose","Benzodiazepine overdose","Organophosphate poisoning","Iron poisoning"]'::jsonb, 'Paracetamol (acetaminophen) overdose', 'N-acetylcysteine is the antidote for paracetamol overdose. It replenishes glutathione stores, which are depleted by the toxic metabolite NAPQI (N-acetyl-p-benzoquinone imine). NAC is most effective within 8-10 hours of ingestion. It can be given IV or orally.'),
('638b48fe-115a-5ecc-9137-c7a59af60584'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Flumazenil is the antidote for which drug overdose?', '["Opioids","Benzodiazepines","Tricyclic antidepressants","Aspirin","Paracetamol"]'::jsonb, 'Benzodiazepines', 'Flumazenil is a competitive benzodiazepine receptor antagonist that reverses the CNS depression caused by benzodiazepines. It is given IV. Contraindications include chronic benzodiazepine use (precipitates withdrawal seizures) and co-ingestion with tricyclic antidepressants.'),
('437bf935-24d4-5338-a730-47d907dd85b4'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Naloxone is the antidote for which poisoning?', '["Benzodiazepine overdose","Opioid overdose","Paracetamol overdose","Aspirin overdose","Organophosphate poisoning"]'::jsonb, 'Opioid overdose', 'Naloxone is a competitive opioid receptor antagonist that reverses respiratory depression from opioid overdose. It has a shorter duration of action (30-90 minutes) than most opioids, so repeated doses may be needed. It can precipitate withdrawal in opioid-dependent patients.'),
('d700f1e4-dda8-5d56-a5cf-ced3b564af92'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in organophosphate poisoning?', '["Naloxone","Flumazenil","Atropine and pralidoxime","N-acetylcysteine","Deferoxamine"]'::jsonb, 'Atropine and pralidoxime', 'Organophosphate poisoning is treated with atropine (muscarinic antagonist for cholinergic excess) and pralidoxime (reactivates phosphorylated acetylcholinesterase). Atropine controls SLUDGE symptoms and bronchospasm. Pralidoxime must be given before ''aging'' of the enzyme-phosphate complex.'),
('8f364e08-dfb5-5a67-8eb5-33100dda519e'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Deferoxamine is the antidote for which poisoning?', '["Lead poisoning","Iron poisoning","Copper poisoning","Arsenic poisoning","Mercury poisoning"]'::jsonb, 'Iron poisoning', 'Deferoxamine (desferrioxamine) is an iron chelator used in acute iron poisoning. It binds free iron to form ferrioxamine, which is excreted renally. It is given IV or IM. Urine turns orange-red (vin rosé) indicating iron excretion.'),
('3c4e0ef0-4875-5b02-a0f9-a20eca4a4ecc'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Activated charcoal is most effective when given within how many hours of ingestion?', '["1 hour","2 hours","4 hours","6 hours","12 hours"]'::jsonb, '1 hour', 'Activated charcoal is most effective when given within 1 hour of ingestion. It adsorbs most drugs in the GI tract, reducing absorption. Dose is 1g/kg (usually 50-100g) mixed with water. Contraindications include altered consciousness (aspiration risk), bowel obstruction, and ingestion of corrosives.'),
('954f3fc4-671c-5bce-a694-198e0fbd9209'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Whole bowel irrigation is indicated in poisoning with:', '["Paracetamol resulting in decreased functional activity","Iron tablets and sustained-release preparations","Benzodiazepines mediated by specific receptor activation","Opioids without affecting the primary tissue pathway","Aspirin leading to subsequent cellular adaptation"]'::jsonb, 'Iron tablets and sustained-release preparations', 'Whole bowel irrigation (WBI) with polyethylene glycol solution is indicated for ingestion of iron, sustained-release/enteric-coated preparations, and body packers. It flushes the drug through the GI tract before absorption. It is not effective for drugs already absorbed.'),
('3ca72101-baf6-5636-b33a-0f8cd1dcb509'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Physostigmine is used as an antidote in poisoning with:', '["Opioids resulting in decreased functional activity","Organophosphates accompanied by associated clinical symptoms","Anticholinergic drugs (atropine, TCAs)","Benzodiazepines without affecting the primary tissue pathway","Paracetamol leading to subsequent cellular adaptation"]'::jsonb, 'Anticholinergic drugs (atropine, TCAs)', 'Physostigmine is a centrally acting acetylcholinesterase inhibitor used to reverse anticholinergic toxicity (from atropine, TCAs, antihistamines). It crosses the blood-brain barrier unlike neostigmine. It should be given slowly IV to avoid cholinergic crisis.'),
('705ef2ba-ea0a-5f64-8ac8-add3c958dec6'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Vitamin K (phytonadione) is the antidote for which poisoning?', '["Aspirin overdose","Warfarin overdose","Heparin overdose","Paracetamol overdose","Iron overdose"]'::jsonb, 'Warfarin overdose', 'Vitamin K (phytonadione) reverses warfarin toxicity. Warfarin inhibits vitamin K epoxide reductase, preventing clotting factor carboxylation. Vitamin K replenishes the active hydroquinone form. For serious bleeding, IV vitamin K and prothrombin complex concentrate (PCC) are given.'),
('d558a6cf-7d1f-523a-baa4-fda535884bfb'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Protamine sulfate is used as an antidote for:', '["Warfarin overdose","Heparin overdose","Aspirin overdose","Paracetamol overdose","Opioid overdose"]'::jsonb, 'Heparin overdose', 'Protamine sulfate is a positively charged protein that binds to negatively charged heparin, neutralizing its anticoagulant effect. It is given IV slowly. 1 mg protamine neutralizes 100 units of heparin. Excess protamine itself has anticoagulant properties.'),
('e8c57afa-1e06-5e15-9996-6c8314378841'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Dimercaprol (BAL) is used in poisoning with:', '["Iron resulting in decreased functional activity","Arsenic, lead, mercury, gold","Paracetamol mediated by specific receptor activation","Opioids without affecting the primary tissue pathway","Benzodiazepines leading to subsequent cellular adaptation"]'::jsonb, 'Arsenic, lead, mercury, gold', 'Dimercaprol (British Anti-Lewisite/BAL) is a chelating agent used in heavy metal poisoning including arsenic, lead, mercury, and gold. It forms stable water-soluble complexes with metals. It is given IM in oily base. Contraindicated in iron, cadmium, and selenium poisoning.'),
('4d16bc38-0e4b-5c97-9d33-ab0377b9bf63'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'D-penicillamine is used as a chelating agent in:', '["Iron poisoning","Wilson''s disease (copper)","Paracetamol poisoning","Organophosphate poisoning","Opioid overdose"]'::jsonb, 'Wilson''s disease (copper)', 'D-penicillamine is a chelating agent used in Wilson''s disease to remove excess copper. It forms a penicillamine-copper complex excreted in urine. It is also used in lead and mercury poisoning. Side effects include nephrotic syndrome and lupus-like syndrome.'),
('7777b9e0-c9bb-5790-89c0-b8f5c3558062'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Sodium nitrite is used in the management of which poisoning?', '["Organophosphate poisoning","Cyanide poisoning","Opioid overdose","Lead poisoning","Iron poisoning"]'::jsonb, 'Cyanide poisoning', 'Sodium nitrite is used in cyanide poisoning. It oxidizes hemoglobin to methemoglobin, which binds cyanide to form cyanmethemoglobin, reducing free cyanide levels. It is followed by sodium thiosulfate to convert cyanide to thiocyanate for renal excretion.'),
('f399d87d-b408-563c-b541-1d65b0f9718f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'N-acetylcysteine (NAC) works in paracetamol overdose by:', '["Blocking hepatic uptake of paracetamol","Replenishing glutathione and conjugating NAPQI","Inhibiting CYP2E1","Increasing renal excretion of paracetamol","Directly neutralizing NAPQI"]'::jsonb, 'Replenishing glutathione and conjugating NAPQI', 'NAC replenishes hepatic glutathione stores, which conjugate the toxic metabolite NAPQI (N-acetyl-p-benzoquinone imine). NAPQI is normally detoxified by glutathione conjugation. In overdose, glutathione is depleted and NAPQI causes hepatocyte necrosis. NAC is most effective within 8-10 hours.'),
('59ee9b29-0adf-52f4-ac92-8680615e40a8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in methanol poisoning?', '["N-acetylcysteine","Fomepizole or ethanol","Naloxone","Flumazenil","Deferoxamine"]'::jsonb, 'Fomepizole or ethanol', 'Methanol poisoning is treated with fomepizole (competitive alcohol dehydrogenase inhibitor) or ethanol. Both block the conversion of methanol to toxic metabolites (formaldehyde and formic acid) by alcohol dehydrogenase. Fomepizole is preferred as it has fewer side effects.'),
('5d9c6cdc-17de-5e42-8ff4-0e48b10b0d00'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following drugs is absolutely contraindicated in pregnancy?', '["Paracetamol","Isotretinoin","Amoxicillin","Ondansetron","Insulin"]'::jsonb, 'Isotretinoin', 'Isotretinoin is absolutely contraindicated in pregnancy (FDA Category X). It is a potent teratogen causing craniofacial, cardiac, and CNS defects. Women of childbearing age must use two forms of contraception and have pregnancy tests before, during, and after treatment.'),
('ce029268-5410-5f01-b1a8-20244b5ef87e'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which antibiotic is considered safe in pregnancy?', '["Tetracycline","Fluoroquinolones","Penicillins","Aminoglycosides","Sulfonamides"]'::jsonb, 'Penicillins', 'Penicillins are considered safe in pregnancy (FDA Category B). They have a long safety record and do not cause teratogenic effects. Tetracyclines cause tooth discoloration and bone growth inhibition. Fluoroquinolones damage cartilage. Aminoglycosides are ototoxic and nephrotoxic.'),
('8e91cb70-385c-5db6-9296-9c7159310c69'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Warfarin is contraindicated in the first trimester of pregnancy because it causes:', '["Fetal renal agenesis resulting in decreased functional activity","Fetal warfarin syndrome (nasal hypoplasia, stippled epiphyses)","Fetal goiter mediated by specific receptor activation","Fetal deafness without affecting the primary tissue pathway","Fetal cardiac defects leading to subsequent cellular adaptation"]'::jsonb, 'Fetal warfarin syndrome (nasal hypoplasia, stippled epiphyses)', 'Warfarin crosses the placenta and causes fetal warfarin syndrome in the first trimester (weeks 6-12), characterized by nasal hypoplasia, stippled epiphyses, and CNS abnormalities. Heparin (which does not cross the placenta) is preferred in pregnancy.'),
('edf0a592-a982-5ced-8da5-dcaf3aa6598e'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is safe for use during breastfeeding?', '["Tetracycline","Ciprofloxacin","Amoxicillin","Lithium","Methotrexate"]'::jsonb, 'Amoxicillin', 'Amoxicillin is safe during breastfeeding as it is excreted in small amounts in breast milk and is generally well tolerated by infants. Lithium, methotrexate, tetracyclines, and fluoroquinolones are contraindicated or used with caution during breastfeeding.'),
('b10d4f89-d761-591a-a2af-91b36cd282c8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is the safest analgesic in pregnancy?', '["Aspirin","Ibuprofen","Paracetamol","Indomethacin","Naproxen"]'::jsonb, 'Paracetamol', 'Paracetamol (acetaminophen) is the safest analgesic in pregnancy. It is used for mild-moderate pain and fever. NSAIDs (ibuprofen, naproxen) are contraindicated in the third trimester (risk of premature closure of ductus arteriosus). Aspirin in low dose is used for pre-eclampsia prevention.'),
('8d69e2d1-d574-5c86-856c-ea689c9b6a67'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Folic acid supplementation in pregnancy is recommended to prevent:', '["Down syndrome","Neural tube defects","Cardiac defects","Cleft palate","Club foot"]'::jsonb, 'Neural tube defects', 'Folic acid (400-800 mcg daily) supplementation before and during early pregnancy prevents neural tube defects (spina bifida, anencephaly). It should ideally be started at least 1 month before conception and continued through the first trimester.'),
('1f87d22e-9d04-5b68-b2a5-2660c4238fde'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Metformin in pregnancy is used for:', '["Hypertension","Gestational diabetes and PCOS","Asthma","Epilepsy","Thyroid disorders"]'::jsonb, 'Gestational diabetes and PCOS', 'Metformin is used in pregnancy for gestational diabetes (when lifestyle measures fail) and in PCOS patients seeking fertility. It crosses the placenta in small amounts. Insulin is generally preferred as first-line for gestational diabetes.'),
('c459bab7-baac-50da-9f11-f8b21aa39ebb'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'ACE inhibitors are contraindicated in pregnancy because they cause:', '["Fetal warfarin syndrome","Fetal renal dysgenesis and oligohydramnios","Fetal goiter","Fetal cardiac defects","Fetal neural tube defects"]'::jsonb, 'Fetal renal dysgenesis and oligohydramnios', 'ACE inhibitors are contraindicated in the second and third trimesters of pregnancy. They cross the placenta and cause fetal renal dysgenesis, oligohydramnios, and neonatal hypotension. They are also teratogenic in the first trimester (cardiovascular and CNS defects).'),
('e663f0d4-37d1-54e7-9116-cf03d1e81479'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which drug is used to prevent preterm labor?', '["Oxytocin resulting in decreased functional activity","Nifedipine (calcium channel blocker)","Misoprostol mediated by specific receptor activation","Ergometrine without affecting the primary tissue pathway","Methyldopa leading to subsequent cellular adaptation"]'::jsonb, 'Nifedipine (calcium channel blocker)', 'Nifedipine is a calcium channel blocker used as a tocolytic to delay preterm labor. It inhibits uterine contractions by blocking calcium entry into myometrial cells. Other tocolytics include ritodrine (beta-2 agonist) and magnesium sulfate.'),
('f16de7ee-2456-56ff-b637-d55a873f8fe0'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Oxytocin is used for:', '["Prevention of preterm labor","Induction and augmentation of labor","Treatment of postpartum hemorrhage only","Treatment of hypertension","Treatment of asthma"]'::jsonb, 'Induction and augmentation of labor', 'Oxytocin is used for induction and augmentation of labor, and for control of postpartum hemorrhage. It stimulates uterine contractions by acting on oxytocin receptors. Contraindications include cephalopelvic disproportion, placenta previa, and previous classical cesarean section.'),
('d8661909-227e-5f87-8ae9-7b3a4c7e4757'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Magnesium sulfate in pregnancy is used for:', '["Preterm labor","Pre-eclampsia and eclampsia","Gestational diabetes","Threatened miscarriage","Hyperemesis gravidarum"]'::jsonb, 'Pre-eclampsia and eclampsia', 'Magnesium sulfate is the drug of choice for prevention and treatment of eclamptic seizures. It acts as an anticonvulsant by blocking NMDA receptors. Therapeutic level is 4-7 mg/dL. Deep tendon reflexes, respiratory rate, and urine output must be monitored.'),
('0742c230-4fd0-5cb7-9504-9f9aafb5fcfc'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is safe in pregnancy for the treatment of hypothyroidism?', '["Methimazole","Levothyroxine","Carbimazole","Radioactive iodine","Propylthiouracil is safer than methimazole"]'::jsonb, 'Levothyroxine', 'Levothyroxine is safe in pregnancy for hypothyroidism. The dose often needs to be increased by 30-50%. For hyperthyroidism, propylthiouracil (PTU) is preferred in the first trimester (methimazole is associated with aplasia cutis and choanal atresia).'),
('636618c4-4367-598f-9678-623e61a24c28'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which antiepileptic drug is relatively safe in pregnancy?', '["Valproic acid","Carbamazepine","Phenytoin","Topiramate","Lamotrigine"]'::jsonb, 'Lamotrigine', 'Lamotrigine is considered relatively safe in pregnancy among antiepileptics. Valproic acid has the highest teratogenic risk (neural tube defects, neurodevelopmental delay). Folic acid (5mg daily) supplementation is recommended for all women on antiepileptics.'),
('7373f0f4-dd43-552b-901c-d769c71eda00'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Lithium is contraindicated in pregnancy because it causes:', '["Neural tube defects","Ebstein''s anomaly (tricuspid valve)","Cleft palate","Cardiac septal defects","Renal agenesis"]'::jsonb, 'Ebstein''s anomaly (tricuspid valve)', 'Lithium crosses the placenta and is associated with Ebstein''s anomaly (apical displacement of tricuspid valve) particularly when used in the first trimester. The risk is approximately 1 in 1000. If lithium must be continued, lowest effective dose with monitoring is recommended.'),
('488a8675-cb82-5322-8ff6-e22d9df76c07'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following drugs requires dose reduction in renal impairment?', '["Metformin","Gabapentin","Amlodipine","Omeprazole","Metoprolol"]'::jsonb, 'Gabapentin', 'Gabapentin is renally excreted and requires dose adjustment in renal impairment. Other drugs requiring renal dose adjustment include aminoglycosides, vancomycin, digoxin, lithium, metformin (contraindicated in severe renal impairment), and DOACs.'),
('28ed12ca-8c55-5526-a441-0f8fe056d37f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Metformin is contraindicated in which stage of chronic kidney disease?', '["Stage 1 (GFR >90)","Stage 2 (GFR 60-89)","Stage 3 (GFR 30-59)","Stage 4 (GFR 15-29)","Stage 5 (GFR <15) and dialysis"]'::jsonb, 'Stage 4 (GFR 15-29)', 'Metformin is contraindicated when GFR <30 mL/min (Stage 4 CKD) due to risk of lactic acidosis. Dose should be reduced at GFR 30-45 and discontinued at GFR <30. Regular monitoring of renal function is required in patients on metformin.'),
('40214ba6-aa50-5cdf-b0f2-b2b134d21482'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following analgesics should be avoided in renal impairment?', '["Paracetamol","NSAIDs","Tramadol","Codeine","Morphine (with caution)"]'::jsonb, 'NSAIDs', 'NSAIDs should be avoided in renal impairment. They inhibit prostaglandin-mediated afferent arteriolar vasodilation, reducing GFR and potentially causing acute kidney injury. They also cause sodium and water retention, worsening hypertension and heart failure.'),
('2c1dc047-be74-5608-8bb8-f6b86dd178d3'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which antibiotic is safe to use in renal impairment without dose adjustment?', '["Gentamicin","Vancomycin","Azithromycin","Amikacin","Colistin"]'::jsonb, 'Azithromycin', 'Azithromycin does not require dose adjustment in renal impairment as it is primarily hepatically metabolized and excreted in bile. Aminoglycosides (gentamicin, amikacin), vancomycin, and colistin require dose adjustment based on renal function.'),
('8418e99a-e0c1-58e9-891f-27f11ff39498'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used to lower potassium in an emergency?', '["Oral potassium supplements","IV calcium gluconate","Spironolactone","Triamterene","Amiloride"]'::jsonb, 'IV calcium gluconate', 'IV calcium gluconate is used in emergency hyperkalemia to stabilize the cardiac membrane. It does not lower potassium but protects the heart. Potassium-lowering measures include IV insulin+glucose, salbutamol, sodium bicarbonate, and dialysis.'),
('c1ffb4e9-ca2d-507c-a8b3-1b00c8abb2df'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Drugs that are primarily hepatically metabolized may require dose adjustment in:', '["Renal impairment only","Hepatic impairment","Cardiac failure","Respiratory failure","None of the above"]'::jsonb, 'Hepatic impairment', 'Drugs primarily hepatically metabolized (e.g., morphine, diazepam, propranolol, lidocaine) may accumulate in hepatic impairment due to reduced first-pass metabolism and decreased clearance. Child-Pugh score is used to assess hepatic impairment severity.'),
('7b129070-f771-5a64-93f0-42be03850f0b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The Child-Pugh score is used to assess:', '["Renal function","Hepatic function and cirrhosis severity","Cardiac function","Pulmonary function","Hematological function"]'::jsonb, 'Hepatic function and cirrhosis severity', 'The Child-Pugh score assesses hepatic function and prognosis in cirrhosis. It includes bilirubin, albumin, INR, ascites, and encephalopathy. Class A (5-6) is well-compensated, Class B (7-9) is significant compromise, Class C (10-15) is decompensated.'),
('2ba17f1c-c850-591f-bdc4-9092e82d476e'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which drug is contraindicated in hepatic encephalopathy?', '["Lactulose","Rifaximin","Opioid analgesics","Spironolactone","Furosemide"]'::jsonb, 'Opioid analgesics', 'Opioid analgesics should be avoided in hepatic encephalopathy as they can worsen CNS depression. Even at standard doses, opioids can precipitate or worsen encephalopathy. Paracetamol should also be used with caution (reduced dose) in liver disease.'),
('16c6e3c6-f38d-5f73-bef6-c29b1a0b66dd'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Renally cleared drugs accumulate in renal failure, leading to:', '["Decreased drug effect","Increased drug toxicity","No change in drug levels","Increased drug metabolism","Enhanced drug excretion"]'::jsonb, 'Increased drug toxicity', 'Renally cleared drugs accumulate in renal failure due to decreased glomerular filtration and tubular secretion. This leads to increased drug levels and risk of toxicity. Examples include aminoglycosides, digoxin, lithium, and vancomycin. Dose reduction is necessary.'),
('fc9ec020-df84-5c89-9531-8dc46a928f16'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'In dialysis patients, drugs with which property are more efficiently removed?', '["High molecular weight resulting in decreased functional activity","Low molecular weight, low protein binding, water-soluble","High protein binding, lipid-soluble mediated by specific receptor activation","Large volume of distribution without affecting the primary tissue pathway","Both A and C leading to subsequent cellular adaptation"]'::jsonb, 'Low molecular weight, low protein binding, water-soluble', 'Hemodialysis is most effective at removing drugs with low molecular weight (<500 Da), low protein binding (<80%), and water solubility. Examples: lithium, theophylline, salicylates, methotrexate. Drugs with high protein binding or large Vd are poorly dialyzed.'),
('8d68dc05-6574-568d-adf5-c362427842ec'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Gentamicin is primarily eliminated by:', '["Hepatic metabolism","Renal excretion (glomerular filtration)","Biliary excretion","Pulmonary excretion","Sweat excretion"]'::jsonb, 'Renal excretion (glomerular filtration)', 'Gentamicin is an aminoglycoside that is almost entirely eliminated by glomerular filtration without hepatic metabolism. It has a narrow therapeutic index and requires therapeutic drug monitoring (TDM). Levels: peak 5-10 mcg/mL, trough <2 mcg/mL.'),
('8045bc5f-e0ac-5db1-bad7-fcacdff3f1a1'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Paracetamol dose should be reduced in severe hepatic impairment because:', '["It is absorbed faster resulting in decreased functional activity","Reduced glutathione stores increase risk of hepatotoxicity","It is metabolized faster mediated by specific receptor activation","It is excreted faster without affecting the primary tissue pathway","It has no hepatotoxic metabolites leading to subsequent cellular adaptation"]'::jsonb, 'Reduced glutathione stores increase risk of hepatotoxicity', 'In hepatic impairment, glutathione stores are already depleted, increasing susceptibility to NAPQI toxicity. The maximum recommended dose in severe hepatic impairment is 2g/day (normal 4g/day). Regular LFT monitoring is essential.'),
('84ef41eb-f986-5eb2-b0cd-db596f0c35de'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a live attenuated vaccine?', '["Hepatitis B","MMR (Measles, Mumps, Rubella)","DPT (Diphtheria, Pertussis, Tetanus)","Hib","Pneumococcal"]'::jsonb, 'MMR (Measles, Mumps, Rubella)', 'MMR is a live attenuated vaccine. Other live vaccines include BCG, oral polio (OPV), varicella, yellow fever, rotavirus, and nasal flu. Live vaccines are contraindicated in immunocompromised patients and pregnancy.'),
('7d349ea8-2bdd-5dd9-81f9-43cf381833b1'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vaccine is given at birth in the Expanded Programme on Immunization (EPI)?', '["BCG","OPV-0","Hepatitis B (birth dose)","All of the above","None of the above"]'::jsonb, 'All of the above', 'BCG, OPV-0 (oral polio at birth), and Hepatitis B birth dose are all given at birth in the EPI schedule. BCG is given intradermally, OPV-0 orally, and HepB intramuscularly in the anterolateral thigh.'),
('c119a82d-29aa-5639-94b5-e78485863453'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The MMR vaccine is a combination vaccine protecting against:', '["Measles, Mumps, and Rubella","Measles, Malaria, and Rotavirus","Mumps, Measles, and Rabies","Measles, Mumps, and Typhoid","Rubella, Rotavirus, and Measles"]'::jsonb, 'Measles, Mumps, and Rubella', 'MMR is a live attenuated vaccine against Measles, Mumps, and Rubella. First dose is given at 9-12 months, second dose at 15-18 months. It is contraindicated in pregnancy and immunocompromised individuals. Febrile seizures may occur 7-10 days after vaccination.'),
('613b0951-d79d-5817-ace3-94688acb9a9a'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The BCG vaccine provides protection against:', '["Hepatitis B","Tuberculosis","Poliomyelitis","Diphtheria","Tetanus"]'::jsonb, 'Tuberculosis', 'BCG (Bacillus Calmette-Guerin) is a live attenuated Mycobacterium bovis vaccine that provides protection against severe forms of tuberculosis in children (TB meningitis, miliary TB). It is given at birth as a single intradermal dose.'),
('87d65818-867a-5a91-add1-39b4e36a1f64'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a contraindication to live vaccines?', '["Pregnancy","Immunosuppression","Active chemotherapy","All of the above","None of the above"]'::jsonb, 'All of the above', 'Live vaccines are contraindicated in pregnancy, immunosuppression (HIV with CD4 <200, organ transplant recipients), and active chemotherapy. Live vaccines should be given 3-6 months after stopping immunosuppressive therapy. Inactivated vaccines are safe in these situations.'),
('a574d082-514d-5718-8a21-5634cdc96730'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The oral polio vaccine (OPV) contains:', '["Inactivated poliovirus","Live attenuated poliovirus","Polysaccharide antigen","Conjugated antigen","Toxoid"]'::jsonb, 'Live attenuated poliovirus', 'OPV (Sabin vaccine) contains live attenuated poliovirus (types 1, 2, 3). It is given orally and provides gut immunity. IPV (Salk vaccine) contains inactivated poliovirus given IM. OPV can rarely cause vaccine-associated paralytic polio (VAPP).'),
('1b4153f5-a14d-5363-ad32-62b6f6c12437'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a toxoid vaccine?', '["MMR","Hepatitis B","Tetanus toxoid","BCG","OPV"]'::jsonb, 'Tetanus toxoid', 'Tetanus toxoid and diphtheria toxoid are toxoid vaccines made from inactivated bacterial toxins. They are conjugated to aluminum adjuvant. The DTaP vaccine contains diphtheria and tetanus toxoids plus acellular pertussis component.'),
('59bad3e3-1528-5d71-8c9f-eb0a18295f75'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Hepatitis B vaccine is given at which time points in the EPI schedule?', '["Birth, 6 weeks, 10 weeks","Birth, 6 weeks, 14 weeks","6 weeks, 10 weeks, 14 weeks","Birth, 6 weeks, 14 weeks, 9 months","Birth, 2 months, 4 months"]'::jsonb, 'Birth, 6 weeks, 14 weeks', 'In the EPI schedule, Hepatitis B is given at birth, 6 weeks, and 14 weeks. The birth dose is important for preventing mother-to-child transmission. It is a recombinant subunit vaccine given intramuscularly.'),
('cc69f43a-b1fe-5089-8c61-d6904d6e2ed8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is NOT a routine childhood vaccine?', '["MMR","Pentavalent (DPT+HepB+Hib)","Pneumococcal conjugate","Yellow fever","Rotavirus"]'::jsonb, 'Yellow fever', 'Yellow fever vaccine is not part of the routine childhood schedule. It is given to travelers to endemic areas and residents of endemic regions. The others (MMR, pentavalent, pneumococcal, rotavirus) are routine childhood vaccines.'),
('28251c42-9ed0-5d0f-8f34-a238e7ffd5f6'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Adverse effects of the MMR vaccine include all EXCEPT:', '["Febrile seizures resulting in decreased functional activity","Measles-like rash accompanied by associated clinical symptoms","Arthritis mediated by specific receptor activation","Anaphylaxis without affecting the primary tissue pathway","None of the above (all are possible)"]'::jsonb, 'None of the above (all are possible)', 'All listed reactions can occur with MMR: febrile seizures (1 in 3000, usually 7-10 days post-vaccine), measles-like rash, transient arthritis (in adult women post-rubella component), and anaphylaxis (very rare, 1 in 1,000,000).'),
('5215e850-5a1c-5dd4-8f64-0a01cef83c0c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vaccine is given intradermally?', '["Hepatitis B","BCG","MMR","OPV","DPT"]'::jsonb, 'BCG', 'BCG is given as a single intradermal dose (0.1 mL) in the left upper arm. It should produce a wheal of 6-8 mm. Most other vaccines are given intramuscularly (HepB, DPT, MMR) or orally (OPV, rotavirus).'),
('8c9dbda9-4363-588c-8492-c3c7762c7319'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The pentavalent vaccine in the EPI schedule protects against:', '["DPT, Hepatitis B, and Hib","MMR, DPT, and Hib","DPT, Hepatitis B, and Polio","DPT, Hib, and Pneumococcal","DPT, Hepatitis B, and Rotavirus"]'::jsonb, 'DPT, Hepatitis B, and Hib', 'The pentavalent vaccine combines DPT (Diphtheria, Pertussis, Tetanus) with Hepatitis B and Hib (Haemophilus influenzae type b). It is given at 6, 10, and 14 weeks. This reduces the number of injections needed.'),
('f606bcf8-b3e4-5d7e-bb22-9ad5bcfbaf28'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'A patient on methotrexate can receive which type of vaccine?', '["Live attenuated vaccine","Inactivated vaccine","Both live and inactivated","Neither live nor inactivated","Only toxoid vaccines"]'::jsonb, 'Inactivated vaccine', 'Patients on immunosuppressive therapy (methotrexate) should receive inactivated vaccines, not live vaccines. Inactivated vaccines are safe but may have reduced immunogenicity. Live vaccines are contraindicated during immunosuppression and for 3 months after stopping.'),
('e3a24f95-ad21-52e8-863a-a1c0cc8cdddc'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The pneumococcal conjugate vaccine (PCV13) is recommended for:', '["Adults over 65 only","All children as part of routine immunization","Only immunocompromised patients","Only pregnant women","Only healthcare workers"]'::jsonb, 'All children as part of routine immunization', 'PCV13 is part of the routine childhood immunization schedule, given at 2, 4, 6, and 12-15 months. It is also recommended for adults over 65, immunocompromised individuals, and those with chronic diseases. It protects against 13 serotypes of S. pneumoniae.'),
('4f6eabc5-d74b-5a4a-8179-69220fd2ca61'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following vaccines is recommended annually?', '["MMR","BCG","Influenza","Hepatitis B","DPT"]'::jsonb, 'Influenza', 'Influenza vaccine is recommended annually because the circulating viral strains change each year (antigenic drift). The vaccine composition is updated annually by WHO. It is recommended for high-risk groups: elderly, healthcare workers, chronic disease patients, and pregnant women.'),
('f76ac99a-9983-5a62-8790-3a56a4a645a4'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'IVIG (Intravenous Immunoglobulin) is used in all the following EXCEPT:', '["Primary immunodeficiency","Kawasaki disease","Immune thrombocytopenic purpura","Active bacterial infection","Guillain-Barre syndrome"]'::jsonb, 'Active bacterial infection', 'IVIG provides passive immunity and immunomodulation. It is used in immunodeficiencies, Kawasaki disease, ITP, GBS, and myasthenia gravis. It is NOT used to treat active infections directly (antibiotics are needed). It may be used adjunctively in severe sepsis.'),
('275a4afe-3ba5-5140-8c64-3be1bc9a3aed'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Anti-D immunoglobulin is given to:', '["All pregnant women resulting in decreased functional activity","Rh-negative mothers to prevent Rh isoimmunization","Rh-positive mothers mediated by specific receptor activation","All newborns without affecting the primary tissue pathway","Only male patients leading to subsequent cellular adaptation"]'::jsonb, 'Rh-negative mothers to prevent Rh isoimmunization', 'Anti-D immunoglobulin (RhoGAM) is given to Rh-negative mothers at 28 weeks and within 72 hours of delivery of an Rh-positive baby. It prevents Rh isoimmunization by destroying any fetal Rh-positive red cells before the mother''s immune system responds.'),
('5ab5b2f4-ace1-5eec-9858-0af4b61eed35'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Tetanus immunoglobulin (TIG) is given in:', '["Tetanus prevention (vaccination)","Active tetanus infection (tetanus-prone wounds)","Post-exposure prophylaxis only","Only in children","Only in pregnant women"]'::jsonb, 'Active tetanus infection (tetanus-prone wounds)', 'TIG provides immediate passive immunity in tetanus-prone wounds and active tetanus. It is given IM (250-500 units) along with tetanus toxoid and antibiotics. It is also given in wound management when vaccination status is incomplete.'),
('62a7b147-7501-5d3a-ac63-fa076303a9f5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which immunoglobulin is used for post-exposure prophylaxis of hepatitis B?', '["IVIG","Hepatitis B immunoglobulin (HBIG)","Anti-D immunoglobulin","Tetanus immunoglobulin","Rabies immunoglobulin"]'::jsonb, 'Hepatitis B immunoglobulin (HBIG)', 'HBIG provides passive immunity against hepatitis B after needlestick injuries, sexual exposure, or birth to HBsAg-positive mothers. It should be given within 24 hours (ideally within 12 hours) along with the first dose of hepatitis B vaccine.'),
('64a22f5d-15eb-5a5a-9ede-c50920a7bf7f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Rabies immunoglobulin is given:', '["Only for prevention","Into and around the wound along with rabies vaccine","Only intravenously","Only intramuscularly at a distant site","Only for category I exposures"]'::jsonb, 'Into and around the wound along with rabies vaccine', 'Rabies immunoglobulin (RIG) is infiltrated into and around the wound to provide local passive immunity. The remainder is given IM at a distant site from the vaccine. It is given with the first dose of rabies vaccine for category II and III exposures.'),
('6c3e2876-c3ac-536e-87ab-4f652c648c5a'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a side effect of IVIG infusion?', '["Anaphylaxis in IgA-deficient patients","Headache and fever","Aseptic meningitis","Thromboembolic events","All of the above"]'::jsonb, 'All of the above', 'IVIG side effects include infusion reactions (headache, fever, chills), aseptic meningitis, thromboembolic events, renal dysfunction, and anaphylaxis in IgA-deficient patients (IVIG contains trace IgA). It should be infused slowly and monitored.'),
('fee171bb-f665-5484-abe9-a040def91561'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The half-life of immunoglobulin G (IgG) is approximately:', '["1 week","3-4 weeks","3-4 months","1 year","2-3 days"]'::jsonb, '3-4 weeks', 'The half-life of IgG is approximately 21-28 days (3-4 weeks). This is why IVIG is typically given every 4 weeks in immunodeficiency patients. IgA has a shorter half-life (about 6 days), and IgM has a half-life of about 5 days.'),
('384b5fb7-d745-5442-8121-a25772b5ad11'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'In which condition is IVIG specifically used to reduce mortality?', '["Common cold","Kawasaki disease","Mild asthma","Uncomplicated UTI","Seasonal allergic rhinitis"]'::jsonb, 'Kawasaki disease', 'IVIG (2g/kg single dose) given within 10 days of illness onset reduces the risk of coronary artery aneurysms in Kawasaki disease. It is combined with high-dose aspirin. This is one of the most important uses of IVIG in pediatric practice.'),
('9c5b18e1-8f7d-50a7-a8a9-073f0ddcd9d2'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Anti-D immunoglobulin can also be used therapeutically in:', '["Immune thrombocytopenic purpura (ITP)","Hemophilia A","Sickle cell disease","Thalassemia","Von Willebrand disease"]'::jsonb, 'Immune thrombocytopenic purpura (ITP)', 'Anti-D immunoglobulin is used therapeutically in ITP (immune thrombocytopenic purpura) in Rh-positive patients who have not had a splenectomy. It works by Fc receptor blockade in the reticuloendothelial system, reducing platelet destruction.'),
('07fd9163-169b-5b07-9820-1da07e735e2d'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following provides passive immunity?', '["MMR vaccine","Tetanus toxoid","IV immunoglobulin","Hepatitis B vaccine","BCG vaccine"]'::jsonb, 'IV immunoglobulin', 'Passive immunity is provided by preformed antibodies (immunoglobulins). Active immunity is provided by vaccines (which stimulate the body''s own immune response). Passive immunity is immediate but short-lived (weeks to months). Active immunity takes weeks to develop but is long-lasting.'),
('0e37b482-e527-5906-9861-eb29d4a1562b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Technetium-99m (Tc-99m) is most commonly used in which diagnostic procedure?', '["PET scan resulting in decreased functional activity","Gamma camera imaging (SPECT)","MRI scan mediated by specific receptor activation","CT scan without affecting the primary tissue pathway","Ultrasound leading to subsequent cellular adaptation"]'::jsonb, 'Gamma camera imaging (SPECT)', 'Tc-99m is the most widely used radionuclide in diagnostic nuclear medicine for SPECT (Single Photon Emission Computed Tomography) imaging. It has a half-life of 6 hours and emits 140 keV gamma rays, ideal for gamma camera detection.'),
('b935fc03-05a8-5ddc-b9ce-68095ca9bd64'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Iodine-131 is used therapeutically for:', '["Hypothyroidism resulting in decreased functional activity","Hyperthyroidism and thyroid cancer","Diabetes mellitus mediated by specific receptor activation","Hypertension without affecting the primary tissue pathway","Asthma leading to subsequent cellular adaptation"]'::jsonb, 'Hyperthyroidism and thyroid cancer', 'Iodine-131 is used therapeutically for hyperthyroidism (Graves'' disease) and thyroid cancer (ablation of residual thyroid tissue). It emits beta particles that destroy thyroid cells. Patients become hypothyroid and require levothyroxine replacement.'),
('7b3e5a87-ecae-567a-bc72-1fbf7a6aa41b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The half-life of Technetium-99m is approximately:', '["6 hours","24 hours","3 days","8 days","60 days"]'::jsonb, '6 hours', 'Tc-99m has a physical half-life of 6 hours, which is ideal for diagnostic imaging. It is long enough to complete procedures but short enough to limit radiation exposure. It emits gamma rays of 140 keV, optimal for gamma camera imaging.'),
('bd70b72a-56be-5e08-baba-5855fb89badd'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which radiopharmaceutical is used for bone scans to detect metastases?', '["Iodine-131 resulting in decreased functional activity","Technetium-99m MDP (methylene diphosphonate)","Gallium-67 mediated by specific receptor activation","Thallium-201 without affecting the primary tissue pathway","Indium-111 leading to subsequent cellular adaptation"]'::jsonb, 'Technetium-99m MDP (methylene diphosphonate)', 'Tc-99m MDP (methylene diphosphonate) is used for bone scans. It accumulates in areas of active bone formation (increased osteoblastic activity), which occur in metastases, fractures, and infections. It is the most common nuclear medicine procedure.'),
('e595e84d-15bc-5d50-857a-8b186c7d64a8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Iodine-123 is used for:', '["Therapeutic thyroid ablation","Diagnostic thyroid imaging","Bone scans","Cardiac imaging","Brain scans"]'::jsonb, 'Diagnostic thyroid imaging', 'Iodine-123 is used for diagnostic thyroid imaging and uptake studies. Unlike I-131, it emits gamma rays only (no beta particles) and has a shorter half-life (13 hours), resulting in lower radiation dose. I-131 is reserved for therapeutic purposes.'),
('b533c8f2-107c-5b3f-bdfa-451157f0333b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which radionuclide is used in PET (Positron Emission Tomography) scanning?', '["Technetium-99m","Fluorine-18 (FDG)","Iodine-131","Gallium-67","Thallium-201"]'::jsonb, 'Fluorine-18 (FDG)', 'Fluorine-18 fluorodeoxyglucose (F-18 FDG) is the most commonly used radiopharmaceutical in PET scanning. It is a glucose analogue taken up by metabolically active cells (cancer, brain, heart). It has a half-life of 110 minutes.'),
('cdddc465-5377-5de9-9188-888d58be24a6'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'What is the primary radiation safety precaution when handling radiopharmaceuticals?', '["Wearing gloves only","Time, distance, and shielding","Working in a closed room","Using hand sanitizer","Wearing a mask"]'::jsonb, 'Time, distance, and shielding', 'The three principles of radiation protection are: Time (minimize exposure time), Distance (maximize distance from source - inverse square law), and Shielding (use lead containers, syringe shields, and protective barriers). These apply to all radiation workers.'),
('42008fc8-ba90-5942-8e19-64b547952739'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which radiopharmaceutical is used to evaluate kidney function (renal scan)?', '["Iodine-131","Technetium-99m DTPA","Gallium-67","Thallium-201","Fluorine-18 FDG"]'::jsonb, 'Technetium-99m DTPA', 'Tc-99m DTPA (diethylenetriaminepentaacetic acid) is used for renal scans to assess GFR and renal perfusion. Tc-99m MAG3 is used for tubular function and excretion. Tc-99m DMSA is used for cortical imaging and scarring.'),
('7b13706f-b451-5b6c-bd47-707fafbf7fa6'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Gallium-67 scan is used to detect:', '["Thyroid disease only","Inflammation, infection, and certain tumors","Bone fractures only","Cardiac disease only","Liver disease only"]'::jsonb, 'Inflammation, infection, and certain tumors', 'Gallium-67 accumulates in areas of inflammation, infection, and certain tumors (lymphomas, hepatocellular carcinoma). It binds to transferrin and lactoferrin. It is also used to detect Kaposi''s sarcoma and fever of unknown origin.'),
('5fb9aaa6-3a84-5fb5-85d6-0901e3cdd42c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The ALARA principle in radiation protection stands for:', '["Always Leave After Radioactive Administration","As Low As Reasonably Achievable","Avoid Long Acting Radiation Agents","Apply Lead Around Radioactive Areas","Assess Low Activity Radiation Areas"]'::jsonb, 'As Low As Reasonably Achievable', 'ALARA (As Low As Reasonably Achievable) is a fundamental principle of radiation protection. It means making every reasonable effort to keep radiation exposures as far below dose limits as practical. It applies to patients, workers, and the public.'),
('26b81138-e64f-5ee1-9c3f-cd3bcacc22a5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Iodine-131 has a half-life of approximately:', '["6 hours","8 days","13 hours","60 days","110 minutes"]'::jsonb, '8 days', 'Iodine-131 has a physical half-life of approximately 8 days. It emits both beta particles (therapeutic) and gamma rays (diagnostic). This makes it useful for both imaging and therapy of thyroid conditions.'),
('44fecf69-d79e-5395-83da-b18af19c40da'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Thallium-201 is used in which type of scan?', '["Thyroid scan resulting in decreased functional activity","Myocardial perfusion (cardiac) scan","Bone scan mediated by specific receptor activation","Liver scan without affecting the primary tissue pathway","Brain scan leading to subsequent cellular adaptation"]'::jsonb, 'Myocardial perfusion (cardiac) scan', 'Thallium-201 is used for myocardial perfusion imaging to detect coronary artery disease. It is a potassium analogue taken up by viable myocardial cells. Areas of reduced uptake indicate ischemia or infarction. Tc-99m sestamibi is now preferred.'),
('36f65526-bdbf-50b1-bfc8-02c33e7ebaa3'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Adrenaline (epinephrine) is the first-line treatment for:', '["Asthma only","Anaphylactic shock","Hypertension","Diabetes","Bradycardia only"]'::jsonb, 'Anaphylactic shock', 'Adrenaline (epinephrine) is the first-line treatment for anaphylaxis. It is given IM (0.5mg of 1:1000 for adults, 0.01mg/kg for children) in the anterolateral thigh. It counteracts vasodilation, bronchospasm, and increased vascular permeability.'),
('9b30f062-b662-57be-8fa2-efea10c05da4'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'In cardiopulmonary resuscitation (CPR), the recommended dose of IV adrenaline is:', '["1 mg every 5-10 minutes","5 mg every 5-10 minutes","10 mg every 5-10 minutes","0.5 mg every minute","0.1 mg every minute"]'::jsonb, '1 mg every 5-10 minutes', 'In cardiac arrest, IV adrenaline is given 1 mg (10 mL of 1:10,000) every 5-10 minutes during CPR. It is given after the third shock in non-shockable rhythms or after the first shock in shockable rhythms. It acts on alpha and beta receptors.'),
('2aa566e2-cc51-5ced-bb23-bc054f2ce164'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Amiodarone is used in cardiac arrest for which rhythm?', '["Asystole resulting in decreased functional activity","Pulseless ventricular tachycardia and ventricular fibrillation","Bradycardia mediated by specific receptor activation","Supraventricular tachycardia only without affecting the primary tissue pathway","First-degree heart block leading to subsequent cellular adaptation"]'::jsonb, 'Pulseless ventricular tachycardia and ventricular fibrillation', 'Amiodarone is the antiarrhythmic of choice for shock-resistant VF/pulseless VT. First dose: 300 mg IV bolus, second dose: 150 mg. It blocks sodium, potassium, and calcium channels and has beta-blocking properties.'),
('831c446b-e5fb-59ab-ac6d-2fa5d104a50b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which drug is used for cardioversion of SVT (supraventricular tachycardia)?', '["Amiodarone","Adenosine","Lidocaine","Digoxin","Verapamil"]'::jsonb, 'Adenosine', 'Adenosine is the drug of choice for acute termination of SVT. It is given as a rapid IV bolus (6 mg, then 12 mg if needed). It acts on A1 receptors, causing transient AV block. It has a very short half-life (seconds).'),
('f261d315-52ce-5d1f-8b94-98e9f1e5a9ae'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Naloxone is used in opioid overdose. Its duration of action is:', '["Shorter than most opioids","Longer than most opioids","Same as most opioids","Depends on the route of administration only","Permanent"]'::jsonb, 'Shorter than most opioids', 'Naloxone''s duration of action (30-90 minutes) is shorter than most opioids (especially long-acting ones like methadone). Repeated doses or a naloxone infusion may be needed. This is why patients may re-narcotize after initial naloxone reversal.'),
('c59bf56e-8566-5a86-a42f-813b195c2db5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Sodium bicarbonate is indicated in which emergency?', '["Hyperkalemia-induced cardiac arrest resulting in decreased functional activity","Metabolic acidosis (severe) and tricyclic antidepressant overdose","Hypoglycemia mediated by specific receptor activation","Asthma attack without affecting the primary tissue pathway","Hypertensive emergency leading to subsequent cellular adaptation"]'::jsonb, 'Metabolic acidosis (severe) and tricyclic antidepressant overdose', 'Sodium bicarbonate is used in severe metabolic acidosis (pH <7.1) and in TCA overdose with QRS widening and acidosis. It raises blood pH, stabilizes cardiac membranes, and enhances sodium channel blockade reversal. It is also used in hyperkalemia.'),
('4c533b74-7b1b-5f3e-88a3-9da349feb900'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Glucagon is used as an antidote for:', '["Opioid overdose","Beta-blocker overdose","Benzodiazepine overdose","Paracetamol overdose","Organophosphate poisoning"]'::jsonb, 'Beta-blocker overdose', 'Glucagon is used in beta-blocker and calcium channel blocker overdose. It bypasses the blocked beta receptor by directly stimulating adenylyl cyclase, increasing intracellular cAMP. It is given IV (3-10 mg bolus).'),
('1120487b-466c-5ff6-8542-02ae108b8a12'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'What is the initial step in managing any emergency patient?', '["Order investigations resulting in decreased functional activity","Administer medications accompanied by associated clinical symptoms","Assess and secure airway, breathing, circulation (ABC)","Take detailed history without affecting the primary tissue pathway","Admit to hospital leading to subsequent cellular adaptation"]'::jsonb, 'Assess and secure airway, breathing, circulation (ABC)', 'The initial step in emergency management is assessment and stabilization of Airway, Breathing, and Circulation (ABC). This follows the ATLS/APLS approach. Life-threatening conditions must be identified and treated immediately before detailed evaluation.'),
('91b09395-bf31-57da-88d5-d6b84fcc6f03'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The recommended first shock energy for defibrillation in an adult is:', '["50-100 joules (biphasic)","200-360 joules (monophasic)","50-100 joules (monophasic)","360 joules (biphasic)","50 joules only"]'::jsonb, '50-100 joules (biphasic)', 'For biphasic defibrillators (most modern), the recommended first shock is 120-200J (some use 150-200J). For monophasic, it is 360J. Subsequent shocks may use escalating energies. Biphasic waveforms are more effective at lower energies.'),
('9e3657c8-1afe-5ab2-80d9-2159893f96ce'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in status epilepticus when benzodiazepines fail?', '["Paracetamol","Phenytoin or levetiracetam","Aspirin","Metformin","Omeprazole"]'::jsonb, 'Phenytoin or levetiracetam', 'If benzodiazepines (first-line) fail to stop status epilepticus, second-line agents include IV phenytoin, levetiracetam, or valproate. If these fail, general anesthesia with thiopental or propofol is used (third-line). This follows the established treatment algorithm.'),
('b1d1deeb-b5f0-5531-8536-e0a688ffe9e5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Oxygen is used in the management of:', '["Carbon monoxide poisoning","Cardiac arrest","Respiratory failure","All of the above","None of the above"]'::jsonb, 'All of the above', 'Oxygen is used in all these emergencies: CO poisoning (high-flow 100% O2 via non-rebreather), cardiac arrest (100% O2 during CPR), and respiratory failure (titrated to SpO2 94-98%). In COPD, target SpO2 is 88-92% to avoid CO2 retention.'),
('42e2134d-7502-5330-ae47-0a9900b5edb0'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Atropine is used in the management of:', '["Tachycardia resulting in decreased functional activity","Organophosphate poisoning and symptomatic bradycardia","Hypertension mediated by specific receptor activation","Hyperkalemia without affecting the primary tissue pathway","Hypercalcemia leading to subsequent cellular adaptation"]'::jsonb, 'Organophosphate poisoning and symptomatic bradycardia', 'Atropine is a muscarinic antagonist used in symptomatic bradycardia (0.5mg IV every 3-5 minutes, max 3mg) and organophosphate/carbamate poisoning (2mg IV initially, titrated to atropinization). It blocks the effects of excess acetylcholine.'),
('3bbf1366-9841-55c4-9b4d-19e5284d97d3'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in acute severe asthma (status asthmaticus)?', '["IV adrenaline resulting in decreased functional activity","Nebulized salbutamol and IV magnesium sulfate","Oral steroids only mediated by specific receptor activation","Antibiotics without affecting the primary tissue pathway","Antihistamines leading to subsequent cellular adaptation"]'::jsonb, 'Nebulized salbutamol and IV magnesium sulfate', 'Acute severe asthma is treated with repeated nebulized salbutamol (beta-2 agonist), IV magnesium sulfate (bronchodilator), and systemic corticosteroids (hydrocortisone/prednisolone). IV adrenaline is reserved for life-threatening cases unresponsive to standard treatment.'),
('b1d4e93f-24d2-5295-8ec6-20f780d71216'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Activated charcoal is given in oral poisoning by:', '["Giving 50-100g mixed with water via NG tube or orally","Giving 500g as a single dose","Giving it 24 hours after ingestion","Giving it only with syrup of ipecac","Giving it intravenously"]'::jsonb, 'Giving 50-100g mixed with water via NG tube or orally', 'Activated charcoal (50-100g for adults, 1g/kg for children) is given as a slurry mixed with water. It is most effective within 1 hour of ingestion. It adsorbs drugs in the GI tract. It should not be given with syrup of ipecac (which is no longer recommended).'),
('e3439710-2757-5392-9132-8ee3609ee61d'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The Heimlich maneuver (abdominal thrusts) is used for:', '["Cardiac arrest resulting in decreased functional activity","Foreign body airway obstruction (choking)","Seizures mediated by specific receptor activation","Hypoglycemia without affecting the primary tissue pathway","Anaphylaxis leading to subsequent cellular adaptation"]'::jsonb, 'Foreign body airway obstruction (choking)', 'The Heimlich maneuver (abdominal thrusts) is used for foreign body airway obstruction in conscious adults and children >1 year. For infants, back blows and chest thrusts are used. For unconscious patients, direct laryngoscopy and Magill forceps are used.'),
('11da8881-3b72-52d8-a4e2-d807f795037f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Transthoracic pacing is indicated in:', '["Ventricular tachycardia","Symptomatic bradycardia unresponsive to atropine","Ventricular fibrillation","Supraventricular tachycardia","Atrial fibrillation"]'::jsonb, 'Symptomatic bradycardia unresponsive to atropine', 'Transcutaneous pacing is indicated for symptomatic bradycardia unresponsive to atropine and before transvenous pacing. Pacing pads are placed anteriorly and posteriorly. It is a temporary bridge measure.'),
('e0e7bec3-f4a6-5cb8-99fc-2cba48d8a801'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which drug is used to treat torsades de pointes?', '["Amiodarone","IV magnesium sulfate","Lidocaine","Verapamil","Adenosine"]'::jsonb, 'IV magnesium sulfate', 'IV magnesium sulfate is the treatment of choice for torsades de pointes (polymorphic VT with QT prolongation). It is given as 2g IV over 5-20 minutes. Isoproterenol or temporary pacing can increase heart rate and shorten QT. Amiodarone may worsen QT prolongation.'),
('73e33585-bec4-540b-83a5-637942889f7e'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Calcium gluconate is preferred over calcium chloride for peripheral IV because:', '["It is more effective resulting in decreased functional activity","It causes less tissue necrosis if extravasation occurs","It is cheaper mediated by specific receptor activation","It acts faster without affecting the primary tissue pathway","It has fewer side effects leading to subsequent cellular adaptation"]'::jsonb, 'It causes less tissue necrosis if extravasation occurs', 'Calcium gluconate is preferred for peripheral IV because it contains less elemental calcium and causes less tissue necrosis if extravasated. Calcium chloride (3x more elemental calcium) should be given via central line only as extravasation causes severe tissue necrosis.'),
('baab8892-1d1e-5847-a711-ad78e252a3c7'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'In massive blood transfusion, which complication is most likely?', '["Hyperkalemia resulting in decreased functional activity","Hypocalcemia (due to citrate toxicity)","Hypernatremia mediated by specific receptor activation","Hyperglycemia without affecting the primary tissue pathway","Hypomagnesemia leading to subsequent cellular adaptation"]'::jsonb, 'Hypocalcemia (due to citrate toxicity)', 'Massive blood transfusion causes hypocalcemia due to citrate toxicity. Citrate in stored blood chelates calcium. Treatment is IV calcium gluconate. Other complications include hyperkalemia, hypothermia, dilutional coagulopathy, and metabolic acidosis.'),
('c34f0aca-dc38-5c8e-9f32-5c765dde6708'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in acute methanol or ethylene glycol poisoning?', '["N-acetylcysteine resulting in decreased functional activity","Fomepizole (alcohol dehydrogenase inhibitor)","Naloxone mediated by specific receptor activation","Flumazenil without affecting the primary tissue pathway","Deferoxamine leading to subsequent cellular adaptation"]'::jsonb, 'Fomepizole (alcohol dehydrogenase inhibitor)', 'Fomepizole (or ethanol) inhibits alcohol dehydrogenase, preventing conversion of methanol/ethylene glycol to toxic metabolites (formaldehyde/formic acid from methanol; oxalic acid from ethylene glycol). Fomepizole is preferred as it has fewer side effects than ethanol.'),
('25fbe3be-4e28-5141-ae2c-8abe2564367b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The Glasgow Coma Scale (GCS) scores range from:', '["0-10","3-15","1-20","5-25","10-30"]'::jsonb, '3-15', 'The Glasgow Coma Scale scores from 3 (deep coma) to 15 (fully alert and oriented). It assesses Eye opening (1-4), Verbal response (1-5), and Motor response (1-6). GCS ≤8 indicates severe brain injury and need for intubation.'),
('a0693948-8e13-5aed-bfbe-eed58afd11dc'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Vitamin B12 deficiency causes megaloblastic anemia with which distinguishing neurological feature?', '["Peripheral neuropathy only","Subacute combined degeneration of spinal cord","Isolated cognitive impairment","Isolated hearing loss","Isolated visual impairment"]'::jsonb, 'Subacute combined degeneration of spinal cord', 'Vitamin B12 deficiency causes subacute combined degeneration of the spinal cord affecting posterior columns (vibration/proprioception loss), lateral columns (spasticity), and peripheral nerves. Folate deficiency causes megaloblastic anemia but NOT neurological features.'),
('b9eb66e8-5695-5858-b1e7-6f0e5d6f75b9'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'IV magnesium sulfate therapeutic range is:', '["1-3 mg/dL","4-7 mg/dL","8-12 mg/dL","12-15 mg/dL","15-20 mg/dL"]'::jsonb, '4-7 mg/dL', 'The therapeutic range for IV magnesium sulfate in eclampsia is 4-7 mg/dL. Loss of deep tendon reflexes occurs at 8-10 mg/dL, respiratory depression at 10-12 mg/dL, and cardiac arrest at >15 mg/dL. Calcium gluconate is the antidote.'),
('d1f72e9c-e3e4-5e7e-9a13-9d543200c0ff'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used to treat hyperphosphatemia?', '["Calcium gluconate resulting in decreased functional activity","Phosphate binders (sevelamer, calcium acetate)","Vitamin D mediated by specific receptor activation","Loop diuretics without affecting the primary tissue pathway","Thiazide diuretics leading to subsequent cellular adaptation"]'::jsonb, 'Phosphate binders (sevelamer, calcium acetate)', 'Phosphate binders (sevelamer, calcium acetate, lanthanum) are given with meals to bind dietary phosphate in the GI tract and prevent absorption. They are used in chronic kidney disease with hyperphosphatemia. Calcium-based binders can cause hypercalcemia.'),
('4ff6b52d-ce01-59d4-a459-23b252a32ab8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which topical agent is used for treatment of cutaneous warts?', '["Clotrimazole resulting in decreased functional activity","Salicylic acid or cryotherapy (liquid nitrogen)","Mupirocin mediated by specific receptor activation","Permethrin without affecting the primary tissue pathway","Tacrolimus leading to subsequent cellular adaptation"]'::jsonb, 'Salicylic acid or cryotherapy (liquid nitrogen)', 'Cutaneous warts are treated with salicylic acid (keratolytic) or cryotherapy with liquid nitrogen. Salicylic acid works by dissolving keratin in the wart. Cryotherapy causes tissue necrosis and blistering under the wart. Both may require repeated applications.'),
('15088ced-866e-5b27-b095-1483d2bd0641'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which drug is used for acute angle-closure glaucoma to rapidly lower intraocular pressure?', '["Timolol resulting in decreased functional activity","Pilocarpine and IV acetazolamide","Latanoprost mediated by specific receptor activation","Brimonidine without affecting the primary tissue pathway","Dorzolamide leading to subsequent cellular adaptation"]'::jsonb, 'Pilocarpine and IV acetazolamide', 'Acute angle-closure glaucoma is an emergency treated with pilocarpine (constricts pupil, opens trabecular meshwork), IV acetazolamide (reduces aqueous production), topical timolol, and IV mannitol. Pilocarpine is most effective when IOP is <50 mmHg.'),
('ae805a15-44af-57f9-9fe0-51efe40ecd57'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'At what GFR level should metformin be discontinued?', '["GFR <60 mL/min","GFR <45 mL/min","GFR <30 mL/min","GFR <15 mL/min","GFR <90 mL/min"]'::jsonb, 'GFR <30 mL/min', 'Metformin should be discontinued when GFR falls below 30 mL/min due to increased risk of lactic acidosis. Dose reduction is recommended at GFR 30-45 mL/min. Regular monitoring of renal function is required in all patients on metformin.'),
('77b0e3aa-4fb5-5fd1-852c-6a18f98961ab'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a feature of vitamin K deficiency?', '["Prolonged PT and normal aPTT","Prolonged PT and aPTT","Normal PT and prolonged aPTT","Normal PT and normal aPTT","Prolonged bleeding time only"]'::jsonb, 'Prolonged PT and aPTT', 'Vitamin K deficiency causes prolonged PT (factors II, VII, IX, X) and prolonged aPTT (factors II, IX, X). Factor VII has the shortest half-life so PT is prolonged first. This pattern is also seen with warfarin therapy.'),
('7cae9f5e-c56c-58a6-b7d7-992ab8a82ed5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Ciclesonide is an inhaled corticosteroid that is a prodrug. It is activated by:', '["Hepatic metabolism","Esterases in the lungs","Bacterial enzymes in the gut","Hepatic CYP450 enzymes","Renal metabolism"]'::jsonb, 'Esterases in the lungs', 'Ciclesonide is a prodrug activated by esterases in the lungs to its active metabolite des-ciclesonide. This lung-specific activation minimizes systemic side effects and oropharyngeal candidiasis. It has high lung deposition and low oral bioavailability.'),
('68e707c4-8462-5a30-bdb0-834d9cad7034'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following drugs can cause drug-induced lupus?', '["Penicillin","Hydralazine and isoniazid","Paracetamol","Omeprazole","Metformin"]'::jsonb, 'Hydralazine and isoniazid', 'Drug-induced lupus is commonly caused by hydralazine, isoniazid, procainamide, quinidine, and minocycline. It presents with arthralgia, myalgia, serositis, and anti-histone antibodies. Symptoms resolve after stopping the offending drug.'),
('2600bfae-30f3-5358-95cf-9e6d1a902434'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Benzoyl peroxide is used topically for:', '["Fungal infections","Acne vulgaris","Psoriasis","Eczema","Scabies"]'::jsonb, 'Acne vulgaris', 'Benzoyl peroxide is a topical agent used for acne vulgaris. It has bactericidal activity against Cutibacterium acnes, mild comedolytic effects, and anti-inflammatory properties. It causes bleaching of fabrics. Resistance does not develop.'),
('f0c6aa5e-36b2-58e1-923b-052fd13fe48e'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Calcium channel blockers in the eye are used for:', '["Treating glaucoma only","No ophthalmic use","Treating age-related macular degeneration","Treating conjunctivitis","Treating cataracts"]'::jsonb, 'No ophthalmic use', 'Calcium channel blockers have no direct ophthalmic use. Systemic CCBs can cause visual disturbances but are not used to treat eye diseases. For glaucoma, beta-blockers, prostaglandin analogues, alpha-agonists, and CAIs are used.'),
('098ba4ee-612f-5a62-a1d2-657de34bb00c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which vaccine is contraindicated in egg allergy?', '["MMR resulting in decreased functional activity","Yellow fever accompanied by associated clinical symptoms","Influenza (some formulations)","Hepatitis B without affecting the primary tissue pathway","BCG leading to subsequent cellular adaptation"]'::jsonb, 'Influenza (some formulations)', 'Some influenza vaccines are produced in eggs and may contain trace egg proteins. In severe egg allergy, egg-free formulations or recombinant vaccines should be used. Yellow fever vaccine is produced in eggs and is contraindicated in severe egg allergy. MMR is safe in egg allergy.'),
('f51bc6cf-c42f-59d7-862f-84e184486eb5'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Nebulized salbutamol in acute asthma is given every:', '["30 minutes resulting in decreased functional activity","20 minutes for 1 hour then as needed","4 hours mediated by specific receptor activation","Once only without affecting the primary tissue pathway","Every 6 hours leading to subsequent cellular adaptation"]'::jsonb, '20 minutes for 1 hour then as needed', 'In acute severe asthma, nebulized salbutamol (2.5-5mg) is given every 20 minutes for the first hour, then every 1-4 hours as needed. Alternatively, continuous nebulization may be used. This aggressive approach helps reverse severe bronchospasm.'),
('e57048db-1ccb-58f3-b997-f62ada7d0003'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in the management of digoxin toxicity?', '["Calcium gluconate resulting in decreased functional activity","Digoxin-specific antibody fragments (Digibind/DigiFab)","Flumazenil mediated by specific receptor activation","Naloxone without affecting the primary tissue pathway","Physostigmine leading to subsequent cellular adaptation"]'::jsonb, 'Digoxin-specific antibody fragments (Digibind/DigiFab)', 'Digoxin-specific antibody fragments (Digibind/DigiFab) are the definitive treatment for life-threatening digoxin toxicity. They bind free digoxin forming inactive complexes excreted by the kidneys. Calcium is relatively contraindicated (may worsen toxicity).'),
('edbfb6e5-ca48-5abb-a66c-62fbce676054'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Normal serum sodium level is:', '["120-130 mEq/L","135-145 mEq/L","150-160 mEq/L","160-170 mEq/L","110-120 mEq/L"]'::jsonb, '135-145 mEq/L', 'Normal serum sodium is 135-145 mEq/L. Hyponatremia (<135 mEq/L) can cause seizures and cerebral edema. Hypernatremia (>145 mEq/L) causes cellular dehydration. Treatment should correct sodium slowly (max 10-12 mEq/L per 24 hours).'),
('61527b4f-581e-5033-96fb-91f0525ed465'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Leflunomide acts by inhibiting which enzyme?', '["Dihydrofolate reductase","Dihydroorotate dehydrogenase","Calcineurin","ACE","Cyclooxygenase"]'::jsonb, 'Dihydroorotate dehydrogenase', 'Leflunomide inhibits dihydroorotate dehydrogenase (DHODH), the rate-limiting enzyme in de novo pyrimidine synthesis in activated lymphocytes. This selectively inhibits rapidly dividing lymphocytes. Active metabolite: teriflunomide. Hepatotoxicity is a concern.'),
('c5164ca1-56b7-5a2e-9681-e98f6cd7f675'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is an adverse effect of systemic corticosteroids?', '["Osteoporosis","Hyperglycemia","Adrenal suppression","All of the above","None of the above"]'::jsonb, 'All of the above', 'Systemic corticosteroids have numerous adverse effects including osteoporosis, hyperglycemia, adrenal suppression, Cushing''s syndrome, increased infection risk, peptic ulcers, cataracts, skin thinning, and growth retardation in children.'),
('89c27b5d-c2b6-54fe-8bca-f7014c4da48b'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Pegfilgrastim is used to:', '["Treat anemia","Prevent chemotherapy-induced neutropenia","Treat thrombocytopenia","Prevent infection directly","Treat leukopenia only"]'::jsonb, 'Prevent chemotherapy-induced neutropenia', 'Pegfilgrastim is a long-acting pegylated G-CSF analogue used to prevent chemotherapy-induced febrile neutropenia. It stimulates neutrophil production in bone marrow. It is given as a single subcutaneous injection 24-48 hours after chemotherapy.'),
('f7791abf-4a53-5216-9775-8cfd8d41562f'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in the treatment of acute gout?', '["Allopurinol acutely resulting in decreased functional activity","Colchicine or NSAIDs or corticosteroids","Methotrexate mediated by specific receptor activation","Warfarin without affecting the primary tissue pathway","Statins leading to subsequent cellular adaptation"]'::jsonb, 'Colchicine or NSAIDs or corticosteroids', 'Acute gout is treated with colchicine (most effective within 12 hours), NSAIDs, or intra-articular corticosteroids. Allopurinol should NOT be started acutely as it can worsen the attack by mobilizing urate. Prophylaxis with colchicine is started when allopurinol is initiated.'),
('423b8267-d9f8-5e81-8875-6515280b60c8'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Sodium valproate is contraindicated in pregnancy because it causes:', '["Cleft palate only resulting in decreased functional activity","Neural tube defects and neurodevelopmental delay","Cardiac defects only mediated by specific receptor activation","Renal agenesis only without affecting the primary tissue pathway","Limb defects only leading to subsequent cellular adaptation"]'::jsonb, 'Neural tube defects and neurodevelopmental delay', 'Sodium valproate has the highest teratogenic risk among antiepileptics (6-10% risk of neural tube defects, especially spina bifida). It also causes neurodevelopmental delay and reduced IQ. Folic acid 5mg daily should be supplemented before conception.'),
('86300689-fd4c-5ecf-8512-9424aabcea1c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'The correct technique for administering intramuscular injection in adults is to inject into which area?', '["Anterior thigh (vastus lateralis)","Deltoid muscle","Ventrogluteal site","Any of the above depending on volume","Dorsogluteal site only"]'::jsonb, 'Any of the above depending on volume', 'IM injections can be given in the ventrogluteal (preferred for larger volumes), deltoid (small volumes, vaccines), and vastus lateralis sites. The dorsogluteal site is avoided due to sciatic nerve injury risk. Maximum volumes: deltoid 1-2mL, ventrogluteal 3-5mL.'),
('41ea352d-a3d6-5913-bbf0-064824c556c7'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is true about adrenaline (epinephrine) in anaphylaxis?', '["It is given IV routinely","IM into anterolateral thigh is the preferred route","It is contraindicated in children","It should be given after antihistamines","Subcutaneous route is preferred over IM"]'::jsonb, 'IM into anterolateral thigh is the preferred route', 'In anaphylaxis, adrenaline is given IM into the anterolateral thigh (0.5mg of 1:1000 for adults, 0.01mg/kg for children). IV route is reserved for cardiac arrest or refractory anaphylaxis. IM absorption is faster than subcutaneous.'),
('5afb7791-bc3d-500a-8389-320fc9a12673'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which drug is used for emergency contraception?', '["Levonorgestrel","Metformin","Levothyroxine","Paracetamol","Omeprazole"]'::jsonb, 'Levonorgestrel', 'Levonorgestrel (emergency contraceptive pill) is used within 72 hours of unprotected intercourse. It inhibits ovulation. Ulipristal acetate is effective up to 120 hours. Copper IUD is the most effective emergency contraception (within 5 days).'),
('0999d636-d6f7-575d-b2ba-3f32a801a8ad'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Proton pump inhibitors (PPIs) reduce the absorption of which vitamin?', '["Vitamin A","Vitamin B12","Vitamin C","Vitamin D","Vitamin K"]'::jsonb, 'Vitamin B12', 'Long-term PPI use reduces absorption of vitamin B12 by reducing gastric acid needed to release B12 from food proteins. It can also reduce calcium and magnesium absorption. Periodic B12 monitoring is recommended in long-term PPI users.'),
('090c0295-6a17-5847-b653-71008d274e89'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is the most appropriate fluid for resuscitation in severe burns?', '["Dextrose 5% resulting in decreased functional activity","Ringer''s lactate (Hartmann''s solution)","Normal saline only mediated by specific receptor activation","Colloids only without affecting the primary tissue pathway","Hypertonic saline leading to subsequent cellular adaptation"]'::jsonb, 'Ringer''s lactate (Hartmann''s solution)', 'Ringer''s lactate is the preferred fluid for burn resuscitation. The Parkland formula calculates 4mL x kg body weight x %TBSA burned in the first 24 hours (half in first 8 hours). It provides balanced electrolytes and avoids hyperchloremic acidosis.'),
('561d3c9b-ebd0-5b58-98f7-f9b16f6e74a2'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Heparin-induced thrombocytopenia (HIT) is diagnosed by:', '["Platelet count <150,000/μL resulting in decreased functional activity","Platelet count <100,000/μL or >50% drop from baseline after 5-10 days of heparin","Platelet count <50,000/μL mediated by specific receptor activation","Platelet count <200,000/μL without affecting the primary tissue pathway","Platelet count normal leading to subsequent cellular adaptation"]'::jsonb, 'Platelet count <100,000/μL or >50% drop from baseline after 5-10 days of heparin', 'HIT is diagnosed by a platelet count <100,000/μL or >50% fall from baseline, occurring 5-10 days after starting heparin. It is caused by antibodies against heparin-PF4 complex. Treatment: stop heparin, start argatroban or bivalirudin.'),
('57a6f064-485a-58e9-a6d4-b7dd1d676e9a'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is a water-soluble vitamin with a role in collagen synthesis?', '["Vitamin A","Vitamin D","Vitamin C","Vitamin E","Vitamin K"]'::jsonb, 'Vitamin C', 'Vitamin C (ascorbic acid) is a water-soluble vitamin essential for collagen synthesis as a cofactor for prolyl hydroxylase and lysyl hydroxylase. It also enhances non-heme iron absorption, acts as an antioxidant, and supports immune function.'),
('5e9b5da6-761f-5972-a9b3-8532f537c306'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is an indication for IV immunoglobulin (IVIG) in neurology?', '["Epilepsy","Guillain-Barre syndrome","Stroke","Migraine prophylaxis","Alzheimer''s disease"]'::jsonb, 'Guillain-Barre syndrome', 'IVIG is used in Guillain-Barre syndrome (GBS) as first-line treatment along with plasma exchange. It provides passive immunity and immunomodulation. Other neurological indications include myasthenia gravis, chronic inflammatory demyelinating polyneuropathy, and dermatomyositis.'),
('9193eff3-3b23-5b8b-ae49-f22a74e68e34'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Acyclovir is effective against which virus?', '["HIV resulting in decreased functional activity","Herpes simplex virus (HSV) and Varicella-zoster virus (VZV)","Hepatitis B mediated by specific receptor activation","Influenza without affecting the primary tissue pathway","Epstein-Barr virus only leading to subsequent cellular adaptation"]'::jsonb, 'Herpes simplex virus (HSV) and Varicella-zoster virus (VZV)', 'Acyclovir is a nucleoside analogue effective against HSV-1, HSV-2, and VZV. It is phosphorylated by viral thymidine kinase to its active form, inhibiting viral DNA polymerase. It is used for herpes labialis, genital herpes, shingles, and herpes encephalitis.'),
('933b2cea-60f6-5085-b143-e702168043bd'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following electrolyte abnormalities can cause digoxin toxicity?', '["Hypernatremia","Hypokalemia","Hypercalcemia","Hypomagnesemia","Both B and D"]'::jsonb, 'Both B and D', 'Hypokalemia and hypomagnesemia predispose to digoxin toxicity. Hypokalemia increases digoxin binding to Na+/K+ ATPase. Hypomagnesemia is often associated with hypokalemia. Hypercalcemia also increases digoxin toxicity risk.'),
('77835468-e16b-5044-991f-96e240535b69'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is an appropriate treatment for iron deficiency anemia in pregnancy?', '["Iron given on empty stomach with vitamin C","IV iron if oral iron not tolerated or ineffective","Blood transfusion only","Folic acid alone","Vitamin B12 injections"]'::jsonb, 'IV iron if oral iron not tolerated or ineffective', 'Iron deficiency anemia in pregnancy is treated with oral iron (ferrous sulfate 325mg daily or alternate day dosing). IV iron (ferric carboxymaltose, iron sucrose) is used if oral iron is not tolerated, ineffective, or in severe anemia near term.'),
('a3ae63ac-dbaa-5c79-bfa1-1d498d4a8f2c'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is the treatment for warfarin over-anticoagulation with bleeding?', '["Vitamin K alone resulting in decreased functional activity","Prothrombin complex concentrate (PCC) and vitamin K","Fresh frozen plasma only mediated by specific receptor activation","Tranexamic acid without affecting the primary tissue pathway","Protamine sulfate leading to subsequent cellular adaptation"]'::jsonb, 'Prothrombin complex concentrate (PCC) and vitamin K', 'Life-threatening warfarin bleeding is treated with PCC (provides immediate clotting factors) and IV vitamin K (restores endogenous factor production). FFP can be used if PCC is not available. PCC is preferred as it works faster and in smaller volume.'),
('c702364a-0cd4-51e6-97e6-9a352d5b3c6a'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Theophylline toxicity can be precipitated by which drug?', '["Cimetidine","Rifampicin","Both A and B","Neither A nor B","Paracetamol"]'::jsonb, 'Both A and B', 'Theophylline is metabolized by CYP1A2. Cimetidine inhibits CYP enzymes, increasing theophylline levels. Rifampicin induces CYP enzymes, decreasing theophylline levels. Both can alter theophylline levels significantly. Therapeutic range: 10-20 mcg/mL.'),
('44766aa9-d96c-5827-86e9-8ce5aa8be3a9'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is the preferred antibiotic for prophylaxis in splenectomy patients?', '["Amoxicillin","Penicillin V (or amoxicillin)","Ciprofloxacin","Metronidazole","Cephalexin"]'::jsonb, 'Penicillin V (or amoxicillin)', 'Asplenic patients are at risk for overwhelming infection with encapsulated organisms (S. pneumoniae, H. influenzae, N. meningitidis). Lifelong penicillin prophylaxis (or amoxicillin) is recommended. Vaccination against these organisms is also essential.'),
('baa1d9e2-6e37-5b1e-bac3-3ba846ec1d47'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Calcitonin is used therapeutically in:', '["Hypocalcemia resulting in decreased functional activity","Paget''s disease of bone and acute hypercalcemia","Osteoporosis prevention only mediated by specific receptor activation","Vitamin D deficiency without affecting the primary tissue pathway","Hypophosphatemia leading to subsequent cellular adaptation"]'::jsonb, 'Paget''s disease of bone and acute hypercalcemia', 'Calcitonin inhibits osteoclast activity and reduces bone resorption. It is used in Paget''s disease, acute hypercalcemia, and postpartum breast engorgement. In osteoporosis, bisphosphonates are preferred. Calcitonin also has a modest analgesic effect in bone pain.'),
('05a08000-dc72-54a5-9b9c-20276538c746'::uuid, 'Pharmacology (Paper 1)', 'Miscellaneous - Miscellaneous', 'Which of the following is used in the treatment of lead poisoning?', '["Deferoxamine","Succimer (DMSA) or EDTA","Dimercaprol (BAL)","Both B and C","N-acetylcysteine"]'::jsonb, 'Both B and C', 'Lead poisoning is treated with succimer (DMSA, oral) or CaNa2EDTA (IV). Dimercaprol (BAL) is used in severe lead poisoning (encephalopathy) in combination with EDTA. Deferoxamine is for iron poisoning, not lead.'),
('aae61f7b-5900-5ee4-9117-b62928245548'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which is the hallmark of reversible cell injury?', '["Cellular swelling","Nuclear pyknosis","Karyolysis","Apoptosis","Necrosis"]'::jsonb, 'Cellular swelling', 'Cellular swelling is the earliest morphologic manifestation of reversible cell injury, resulting from failure of the plasma membrane sodium pump with influx of water.'),
('ba1db366-ccca-5cce-a924-c1e6a324cb15'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Cellular swelling is primarily due to failure of which pump?', '["Mg2 ATPase","H+ pump","Proton pump","Ca2 ATPase","Na/K ATPase"]'::jsonb, 'Na/K ATPase', 'Hypoxia depletes ATP so the plasma membrane Na+/K+-ATPase fails; sodium and water then enter the cell, producing cellular swelling.'),
('d843f1b9-3659-5427-98d6-f6abbf3b6846'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fatty change (steatosis) is most commonly seen in which organ?', '["Spleen","Brain","Kidney","Liver","Heart"]'::jsonb, 'Liver', 'Steatosis most commonly affects the liver because hepatocytes are the principal site of fat metabolism and are exposed to alcohol, toxins and metabolic overload.'),
('5b398d44-a645-5682-b906-83ef4ee6b132'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which stain is used to demonstrate fatty change on frozen sections?', '["Masson trichrome","Congo red","Oil red O","PAS","Prussian blue"]'::jsonb, 'Oil red O', 'Oil red O stains neutral lipid in frozen sections; routine paraffin processing dissolves fat, so frozen tissue is required.'),
('85ff1a5a-0760-5cb5-9544-25a64a5962de'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hydropic change refers to accumulation of:', '["Water in the cytoplasm","Protein","Pigment","Lipid","Glycogen"]'::jsonb, 'Water in the cytoplasm', 'Hydropic change (cellular swelling) is caused by cytoplasmic accumulation of water secondary to membrane pump failure.'),
('a6b86d7b-3134-5c67-9d13-d89c003cdca3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Metastatic calcification occurs in:', '["Hyperparathyroidism, vitamin D excess, malignancy","Normal calcium levels accompanied by associated clinical symptoms","Hypocalcemia mediated by specific receptor activation","Hypoparathyroidism without affecting the primary tissue pathway","Vitamin D deficiency leading to subsequent cellular adaptation"]'::jsonb, 'Hyperparathyroidism, vitamin D excess, malignancy', 'Metastatic calcification occurs in normal tissues when serum calcium is elevated, as in hyperparathyroidism, vitamin D excess and malignant bone destruction.'),
('de42c74a-1737-5f2f-866f-d6a28aa1d878'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fatty change (steatosis) of liver is caused by:', '["Alcohol, obesity, diabetes, starvation","Infection accompanied by associated clinical symptoms","Autoimmune disease mediated by specific receptor activation","Trauma without affecting the primary tissue pathway","Neoplasia leading to subsequent cellular adaptation"]'::jsonb, 'Alcohol, obesity, diabetes, starvation', 'Steatosis reflects an imbalance between lipid accumulation and disposal; alcohol, obesity, diabetes and starvation all produce fatty liver.'),
('9ea3d468-e2ec-54a8-829e-9b0651d6c498'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Caseous necrosis is characteristic of:', '["Tuberculosis","Myocardial infarction","Brain infarct","Fat necrosis","Gangrene"]'::jsonb, 'Tuberculosis', 'Caseous necrosis, with its soft, cheesy granular appearance, is the hallmark of tuberculous infection (mycobacterial).'),
('7890de47-9e41-51fb-8ff7-8f21829643f6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fat necrosis with chalky-white, soapy (saponified) areas in the peripancreatic fat is a classic finding in which condition?', '["Surgery","Breast trauma","Traumatic fat injury","Acute pancreatitis","Subcutaneous injection"]'::jsonb, 'Acute pancreatitis', 'In acute pancreatitis, lipase digests fat, releasing free fatty acids that combine with calcium to form soaps (saponification), producing chalky-white fat necrosis.'),
('6883f277-be04-5712-a926-845ace2637e1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fibrinoid necrosis is typically seen in:', '["Myocardial infarction","Fat necrosis","Polyarteritis nodosa","Tuberculosis","Acute pancreatitis"]'::jsonb, 'Polyarteritis nodosa', 'Fibrinoid necrosis of vessel walls is characteristic of immune-mediated vasculitides such as polyarteritis nodosa.'),
('73887aac-54ed-52b8-8acc-53f2cba8510e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which enzyme is localized within the mitochondria and is therefore the most useful mitochondrial marker of cell injury?', '["Troponin resulting in decreased functional activity","AST accompanied by associated clinical symptoms","Succinate dehydrogenase","LDH without affecting the primary tissue pathway","CK-MB leading to subsequent cellular adaptation"]'::jsonb, 'Succinate dehydrogenase', 'Succinate dehydrogenase is bound to the inner mitochondrial membrane, whereas troponin, AST, LDH and CK-MB are cytosolic or myofibrillar.'),
('140147aa-68f4-5b56-b92d-85f79d19b48a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Apoptosis is characterized by all EXCEPT:', '["Inflammatory response","Cell shrinkage","Membrane blebbing","Caspase activation","DNA laddering"]'::jsonb, 'Inflammatory response', 'Apoptosis is a programmed, non-inflammatory cell death; the inflammatory response is conspicuously absent, unlike necrosis.'),
('9940e21e-3096-543d-a4de-8e8d05d55773'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which caspase is the initiator in the intrinsic/mitochondrial pathway?', '["Caspase 8","Caspase 1","Caspase 9","Caspase 3","Caspase 12"]'::jsonb, 'Caspase 9', 'Caspase 9 is the initiator of the intrinsic (mitochondrial) pathway, activated by cytochrome c released from mitochondria.'),
('3836d07c-2439-531b-b93e-7a6966045e0c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'From a pathophysiological standpoint regarding Cell Injury Inflammation: Type III hypersensitivity involves:', '["Immune complex deposition (antigen-antibody complexes)","IgE-mediated degranulation accompanied by associated clinical symptoms","Antibody-mediated cytotoxicity mediated by specific receptor activation","T cell-mediated cytotoxicity without affecting the primary tissue pathway","None leading to subsequent cellular adaptation"]'::jsonb, 'Immune complex deposition (antigen-antibody complexes)', 'Complement activation and neutrophil recruitment.'),
('4385a0a3-6803-5aeb-8b4f-41c5e3ac4dcd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which protein is anti-apoptotic?', '["Bax","Bcl-2","Bak","Bid","Bad"]'::jsonb, 'Bcl-2', 'Bcl-2 is an anti-apoptotic protein that localizes to the mitochondrial membrane and inhibits cytochrome c release; Bax, Bak, Bid and Bad are pro-apoptotic.'),
('6219320b-5dd9-5764-b189-88c06a35bbdf'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which apoptosis-regulating protein, acting in opposition to the survival factors of its family, promotes programmed cell death?', '["Bcl-2","Bcl-xL","A1","Mcl-1","Bax"]'::jsonb, 'Bax', 'Bax is pro-apoptotic; Bcl-2, Bcl-xL, A1 and Mcl-1 are anti-apoptotic members of the family.'),
('c087b21d-ea3a-55b2-b085-7db7a3996e77'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'p53 induces apoptosis by transcriptionally activating:', '["Caspase 8","Bcl-2","Bax and Bak","Bcl-xL","Ras"]'::jsonb, 'Bax and Bak', 'p53 transcriptionally upregulates the pro-apoptotic proteins Bax and Bak, which permeabilize the mitochondrial membrane to release cytochrome c.'),
('58a8839c-bebc-5502-9d50-e7b0d1f15a47'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Executioner caspases in apoptosis include:', '["Caspase 10 and 12","Caspase 1 and 4","Caspase 8 and 9","Caspase 3 and 7","Caspase 2 and 5"]'::jsonb, 'Caspase 3 and 7', 'Caspases 3 and 7 are the executioner caspases that cleave cellular substrates and produce the morphologic features of apoptosis.'),
('da72d721-0c33-5f51-8626-ffa47bc3a468'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Apoptotic cells are recognized by phagocytes through:', '["Complement receptor resulting in decreased functional activity","Mannose receptor binding accompanied by associated clinical symptoms","Phosphatidylserine exposure on outer membrane","LPS recognition without affecting the primary tissue pathway","Fc receptor binding leading to subsequent cellular adaptation"]'::jsonb, 'Phosphatidylserine exposure on outer membrane', 'During apoptosis, phosphatidylserine is externalized on the plasma membrane and serves as an ''eat-me'' signal for phagocytes.'),
('d1b2f298-b3e5-52d8-b28b-6f8229be0f79'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Infection with which virus characteristically produces midzonal (zone 2) coagulative necrosis of hepatocytes?', '["Alcoholic hepatitis","Viral hepatitis","Ischemic hepatitis","Drug-induced liver injury","Yellow fever"]'::jsonb, 'Yellow fever', 'Yellow fever virus causes midzonal necrosis of hepatocytes, a distinctive pattern not typical of the other listed liver injuries.'),
('1f21bc42-8f24-5abc-b512-48e60889f493'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Shrinkage of an organ resulting from reduced workload or loss of innervation is due to which cellular change?', '["Change in cell type","Increase in cell size","Increase in cell number","Decrease in cell size and/or number","Disordered growth"]'::jsonb, 'Decrease in cell size and/or number', 'Atrophy is a decrease in cell size and/or number that causes shrinkage of the affected organ.'),
('d4a75c27-0350-5483-b320-c79c0910969f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hypertrophy refers to an increase in:', '["Cell number","Nuclear number","Cell size","Both cell size and number","Extracellular matrix"]'::jsonb, 'Cell size', 'Hypertrophy is an increase in cell size (and organ size); an increase in cell number is hyperplasia.'),
('9ef15017-9901-50e9-93ad-379cdf5b5ff1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Physiologic hypertrophy is best exemplified by:', '["Thyroid enlargement in Graves","Uterine enlargement during pregnancy","Endometrial hyperplasia","Prostatic hyperplasia in BPH","LVH in hypertension"]'::jsonb, 'Uterine enlargement during pregnancy', 'Hormonal stimulation enlarges uterine smooth-muscle cells during pregnancy, a classic example of physiologic hypertrophy.'),
('802f66ec-e853-5d53-9519-213659d50366'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Pathologic hypertrophy is seen in:', '["Uterus in pregnancy","Myocardium in hypertension","Breast during lactation","Skeletal muscle in athletes","Bone marrow in anemia"]'::jsonb, 'Myocardium in hypertension', 'Chronic pressure overload in hypertension drives pathologic cardiac myocyte hypertrophy (LVH).'),
('dd9b1a51-609e-57f1-8c1b-61212a6ca90f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Autophagy is:', '["Self-eating process for recycling damaged organelles","Cell division accompanied by associated clinical symptoms","Cell growth mediated by specific receptor activation","Inflammation without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Self-eating process for recycling damaged organelles', 'Autophagy is the lysosome-mediated ''self-eating'' pathway that degrades and recycles damaged intracellular organelles.'),
('11ff464d-c5c2-5fad-bff1-8ff681ec9c40'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Pathologic hyperplasia carries risk of malignant transformation in:', '["Endometrium","Parathyroid","Breast","Prostate","Thyroid"]'::jsonb, 'Endometrium', 'Endometrial hyperplasia, especially atypical hyperplasia, is the classic example of pathologic hyperplasia that carries malignant potential.'),
('3a99b5e0-eaf1-5759-b280-617a45a3eef8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Metaplasia is best defined as:', '["Increase in cell number","Replacement of one adult cell type by another","Disordered growth with atypia","Increase in cell size","Programmed cell death"]'::jsonb, 'Replacement of one adult cell type by another', 'Metaplasia is the reversible replacement of one differentiated adult cell type by another, often in response to chronic irritation.'),
('a788ee4d-b6a5-569d-8cb9-2c6e95acb3f4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Squamous metaplasia of bronchial epithelium is most commonly caused by:', '["HPV infection","Vitamin A deficiency","Radiation exposure","Asbestos","Chronic smoking"]'::jsonb, 'Chronic smoking', 'Chronic smoking is the most common stimulus for replacement of bronchial pseudostratified ciliated columnar epithelium by stratified squamous epithelium.'),
('0ca0e7a8-e3ce-52ec-b784-3f28b4b4b11e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Barrett esophagus, which results from chronic gastroesophageal reflux, is an example of which change?', '["Columnar metaplasia (intestinal metaplasia)","Dysplasia accompanied by associated clinical symptoms","Hyperplasia mediated by specific receptor activation","Squamous metaplasia without affecting the primary tissue pathway","Atrophy leading to subsequent cellular adaptation"]'::jsonb, 'Columnar metaplasia (intestinal metaplasia)', 'Chronic acid reflux transforms squamous esophageal epithelium into columnar intestinal-type epithelium—a columnar (intestinal) metaplasia.'),
('8d56a7cb-e232-5b7a-a46f-b74d39afa6b6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Dysplasia is characterized by:', '["Uniform cells with normal maturation","Pleomorphism hyperchromasia and disordered maturation","Lack of mitotic figures","Normal nuclear-cytoplasmic ratio","Reversible change without atypia"]'::jsonb, 'Pleomorphism hyperchromasia and disordered maturation', 'Dysplasia is a proliferative lesion showing pleomorphism, hyperchromasia, loss of polarity and disordered maturation without basement-membrane invasion.'),
('bfb01399-a181-58be-a607-f38c4e399a17'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Calcification in damaged tissues is:', '["Dystrophic calcification (in dead/dying tissue)","Metastatic calcification (normal tissue)","Physiologic calcification","Pathologic resorption","Physiologic resorption"]'::jsonb, 'Dystrophic calcification (in dead/dying tissue)', 'Deposition of calcium salts in dead or degenerating tissue is dystrophic calcification; it occurs despite normal serum calcium.'),
('f7f78583-9a3a-5e90-9914-8dcd13a7d0a3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Selectins mediate which step of leukocyte migration?', '["Firm adhesion","Transmigration","Rolling","Phagocytosis","Chemotaxis"]'::jsonb, 'Rolling', 'Selectins mediate the initial rolling of leukocytes along endothelium, the first step before firm adhesion and transmigration.'),
('07e62484-fafd-515c-b94e-0b58b4e9d5e0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The major chemotactic factor for neutrophils is:', '["IL-6","LTB4","IL-1","IL-8 (CXCL8)","TNF-alpha"]'::jsonb, 'IL-8 (CXCL8)', 'IL-8 (CXCL8) is the major chemokine that attracts and activates neutrophils at sites of acute inflammation.'),
('7506ba72-4db5-55ae-b4e2-98cdd5c9c453'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which complement activation product is the principal opsonin that coats microbes for phagocytosis?', '["C4b","C3a","C5a","C5b","C3b"]'::jsonb, 'C3b', 'C3b binds covalently to microbial surfaces and is the major opsonin, whereas C3a and C5a are anaphylatoxins.'),
('98687c99-a9ca-5881-996d-c3056127fd1b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'C3a and C5a, which trigger mast cell degranulation and increased vascular permeability, are examples of which group of complement products?', '["Anaphylatoxins","Opsonins","Convertases","Membrane attack complex components","Chemotaxins"]'::jsonb, 'Anaphylatoxins', 'C3a, C4a and C5a are anaphylatoxins that cause mast cell degranulation and increased vascular permeability.'),
('ade9e118-5e78-5957-83f1-aaba733e47c4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'C1 esterase inhibitor deficiency causes:', '["Recurrent pyogenic infections","Systemic lupus erythematosus","Hereditary angioedema","Lupus-like syndrome","Meningococcal infections"]'::jsonb, 'Hereditary angioedema', 'C1 esterase inhibitor deficiency allows unopposed complement and kinin activation, producing episodic attacks of angioedema.'),
('70c4b461-e07f-53a8-9151-d882821f853a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The classical complement pathway is initiated by:', '["Properdin","C1q binding to IgG or IgM","MBL binding to mannose","C3 convertase","Factor B"]'::jsonb, 'C1q binding to IgG or IgM', 'The classical pathway is triggered when C1q binds the Fc region of antigen-antibody complexes (IgG or IgM).'),
('b987991c-d24b-5242-937c-a68d961b1ae9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The lectin complement pathway is initiated by:', '["C3b binding resulting in decreased functional activity","Factor D accompanied by associated clinical symptoms","C5 mediated by specific receptor activation","C1q without affecting the primary tissue pathway","MBL binding to mannose residues"]'::jsonb, 'MBL binding to mannose residues', 'Mannose-binding lectin (MBL) recognizes mannose residues on microbial surfaces and initiates the lectin pathway without antibody.'),
('d831d5e3-5e0a-5896-8cf3-9782bac360d5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Histamine is primarily stored in:', '["Neutrophils","Lymphocytes","Eosinophils","Monocytes","Mast cells and basophils"]'::jsonb, 'Mast cells and basophils', 'Histamine is stored in granules of mast cells and basophils and is released during immediate inflammatory reactions.'),
('950e4d4b-a15a-5831-a6aa-12f8347ccf12'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which inflammatory mediators are generated by the cyclooxygenase pathway of arachidonic acid metabolism?', '["Prostaglandins and thromboxanes","LTB4 accompanied by associated clinical symptoms","HETEs mediated by specific receptor activation","Lipoxins without affecting the primary tissue pathway","Leukotrienes leading to subsequent cellular adaptation"]'::jsonb, 'Prostaglandins and thromboxanes', 'The cyclooxygenase pathway produces prostaglandins and thromboxanes; the lipoxygenase pathway yields leukotrienes and lipoxins.'),
('36497c39-a5ad-5e0d-9ea5-d263564cb5b1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Leukotrienes are produced via which enzyme pathway?', '["Epoxygenase","5-Lipoxygenase","Phospholipase A2","Cytochrome P450","Cyclooxygenase"]'::jsonb, '5-Lipoxygenase', 'Leukotrienes are synthesized from arachidonic acid through the 5-lipoxygenase pathway.'),
('a8d22fa3-62b3-51a9-b247-e3a155c67618'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which prostaglandin predominantly mediates pain and fever during the inflammatory response?', '["PGI2","PGF2-alpha","PGD2","PGE2","TXA2"]'::jsonb, 'PGE2', 'PGE2 sensitizes peripheral pain receptors and resets the hypothalamic set point, driving pain and fever.'),
('7b37b52c-75d5-5880-878c-9e767de2a515'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Thromboxane A2, a potent promoter of platelet aggregation and vasoconstriction, is produced chiefly by which cells?', '["Platelets","Mast cells","Endothelial cells","Neutrophils","Macrophages"]'::jsonb, 'Platelets', 'Platelets are the main source of thromboxane A2, which promotes aggregation and vasoconstriction.'),
('78764fe3-a6d2-55c3-a90d-54f731d9a7ce'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Prostacyclin (PGI2) is produced by:', '["Neutrophils","Endothelial cells","Platelets","Mast cells","Macrophages"]'::jsonb, 'Endothelial cells', 'Prostacyclin (PGI2), a vasodilator and inhibitor of platelet aggregation, is produced by vascular endothelial cells.'),
('042c20c1-8edb-5094-a15f-0c742a55785c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'TNF-alpha is also known as:', '["Cachectin","Transforming growth factor","Interferon","Interleukin-2","Lymphotoxin"]'::jsonb, 'Cachectin', 'TNF-α was independently discovered as cachectin, the mediator of cachexia in chronic inflammatory states.'),
('10318811-7f11-5879-93e1-4c463fa06a3a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'IL-6 is primarily responsible for:', '["Opsonization resulting in decreased functional activity","Fever accompanied by associated clinical symptoms","Vascular permeability mediated by specific receptor activation","Acute phase protein synthesis in the liver","Neutrophil chemotaxis leading to subsequent cellular adaptation"]'::jsonb, 'Acute phase protein synthesis in the liver', 'IL-6, released by activated macrophages and other cells, is the principal stimulus for hepatic synthesis of acute-phase proteins (CRP, fibrinogen).'),
('dc2ae341-67e5-57c4-b71e-86ccd45c21f3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cytokine is anti-inflammatory?', '["IL-10","IL-6","IL-1","IL-8","TNF-alpha"]'::jsonb, 'IL-10', 'IL-10 is an anti-inflammatory cytokine that suppresses cytokine production by macrophages and T cells.'),
('a66d953d-43da-5e19-b32b-8161a290bbac'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'IL-12 promotes cell-mediated immunity by stimulating which cells to secrete IFN-γ?', '["Th2 cells","B cells","Neutrophils","Eosinophils","Th1 cells and NK cells"]'::jsonb, 'Th1 cells and NK cells', 'IL-12 activates NK cells and Th1 cells to produce IFN-γ, enhancing macrophage killing and cellular immunity.'),
('9dec652a-ec76-59e5-8a9c-c85b2b744af5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cell type is the dominant effector cell of chronic inflammation?', '["Mast cell","Neutrophil","Macrophage","Eosinophil","Basophil"]'::jsonb, 'Macrophage', 'Chronic inflammation is characterized by mononuclear infiltration; activated macrophages are the dominant effector cells.'),
('cf38940f-62d6-5326-ab11-271b6886bbee'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Ischaemia-reperfusion injury involves:', '["Generation of reactive oxygen species (ROS)","Decreased ATP production only","Protein denaturation only","DNA damage only","Membrane disruption only"]'::jsonb, 'Generation of reactive oxygen species (ROS)', 'Restoration of blood flow triggers generation of ROS and a neutrophilic inflammatory response that paradoxically injures the tissue.'),
('cb7b66f0-e7d4-5355-bc17-cf074f8ea561'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Langhans giant cells are characterized by:', '["Multiple cytoplasmic vacuoles","Peripheral horseshoe-shaped arrangement of nuclei","Central single nucleus","Homogeneous eosinophilic cytoplasm","Randomly scattered nuclei"]'::jsonb, 'Peripheral horseshoe-shaped arrangement of nuclei', 'Langhans giant cells, seen in tuberculous granulomas, have nuclei arranged as a horseshoe ring at the periphery.'),
('00b28ab0-60c2-5685-91dd-facaeb7d21b8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Free radical injury mechanism:', '["Lipid peroxidation of cell membranes","Protein synthesis stimulation","DNA repair enhancement","Increased glucose uptake","Glycogen synthesis"]'::jsonb, 'Lipid peroxidation of cell membranes', 'Free radicals damage cells mainly by lipid peroxidation of membranes, oxidative modification of proteins and DNA damage.'),
('f7f0007e-6122-5748-b36f-375423a60e84'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Wound healing by primary intention occurs in:', '["Chronic diabetic ulcers resulting in decreased functional activity","Clean surgical incisions with apposed edges","Infected wounds mediated by specific receptor activation","Pressure ulcers without affecting the primary tissue pathway","Burn wounds leading to subsequent cellular adaptation"]'::jsonb, 'Clean surgical incisions with apposed edges', 'Primary intention healing occurs when wound edges are approximated, as in clean surgical incisions, producing minimal scar.'),
('c87e9331-6ff3-5c65-beb2-c069a7ed9f61'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Wound healing by secondary intention involves:', '["Clean edges with minimal scarring","Surgical incision with sutures","Wound contraction with more granulation tissue","Minimal granulation tissue","Healing without granulation tissue"]'::jsonb, 'Wound contraction with more granulation tissue', 'Secondary intention healing of large, gaping wounds requires abundant granulation tissue and significant wound contraction.'),
('08eee447-e61f-52b1-8f7a-83cc1bc43359'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The most important growth factor for angiogenesis is:', '["FGF","PDGF","EGF","VEGF","TGF-beta"]'::jsonb, 'VEGF', 'VEGF is the most important growth factor driving endothelial proliferation and new blood vessel formation.'),
('8e367017-0b8a-53c9-a463-8a2bba2bc078'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Myofibroblasts are responsible for:', '["Angiogenesis","Collagen synthesis","Phagocytosis","Wound contraction","Epithelialization"]'::jsonb, 'Wound contraction', 'Myofibroblasts, with features of smooth muscle and fibroblasts, contract the wound edges during healing.'),
('f1e87f9d-9fd6-547f-a1ec-f9a0d5498fb3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Vitamin C is required as a cofactor for which enzyme step during wound healing?', '["Epithelial migration resulting in decreased functional activity","Granulation tissue formation accompanied by associated clinical symptoms","Collagen cross-linking via prolyl hydroxylase","Wound contraction without affecting the primary tissue pathway","Angiogenesis leading to subsequent cellular adaptation"]'::jsonb, 'Collagen cross-linking via prolyl hydroxylase', 'Prolyl hydroxylase requires vitamin C to hydroxylate proline residues, enabling collagen triple-helix stability and cross-linking.'),
('78969ea3-b361-5e5f-aeab-68fa9c00470a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Keloids differ from hypertrophic scars by:', '["Remaining within wound boundaries","Being less common in darker skin","Less collagen deposition","Extending beyond original wound margins","Spontaneous regression over time"]'::jsonb, 'Extending beyond original wound margins', 'Keloids extend beyond the original wound margins, whereas hypertrophic scars remain confined to them.'),
('f88af251-e81b-5fd1-a5a5-c93607da9141'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fibrinoid necrosis is seen in:', '["Malignant hypertension and vasculitis","Myocardial infarction","Brain infarct","Liver cirrhosis","Renal infarct"]'::jsonb, 'Malignant hypertension and vasculitis', 'Fibrinoid necrosis of vessel walls is characteristic of malignant hypertension and immune-mediated vasculitides.'),
('c8ccc710-7364-540f-9240-8a04e8aceaa8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'An exudate differs from a transudate by having:', '["Low specific gravity","Clear appearance","Low protein content","High protein and cellular content","Non-inflammatory origin"]'::jsonb, 'High protein and cellular content', 'An exudate is inflammatory fluid rich in protein and cells; a transudate is a low-protein, cell-poor fluid.'),
('0ffde8f1-0301-5cbb-8cd5-a18f4924b240'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Pus consists primarily of:', '["Macrophages and fibroblasts","Red blood cells and fibrin","Eosinophils and basophils","Lymphocytes and plasma cells","Dead neutrophils and necrotic debris"]'::jsonb, 'Dead neutrophils and necrotic debris', 'Pus is largely composed of dead (autolyzed) neutrophils and necrotic tissue debris in suppurative inflammation.'),
('698c362a-9afe-50e1-8d1f-ebf763040808'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'NADPH oxidase is the key enzyme in:', '["Chemotaxis","Phagocytosis recognition","Opsonization","Oxygen-independent killing","Oxygen-dependent respiratory burst"]'::jsonb, 'Oxygen-dependent respiratory burst', 'NADPH oxidase generates superoxide during the oxygen-dependent respiratory burst; its absence causes chronic granulomatous disease.'),
('7912d67a-fc6d-50b0-a291-9348b47a9e79'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Bradykinin is a potent mediator of:', '["Fever resulting in decreased functional activity","Pain and increased vascular permeability","Vasoconstriction mediated by specific receptor activation","Chemotaxis without affecting the primary tissue pathway","Opsonization leading to subsequent cellular adaptation"]'::jsonb, 'Pain and increased vascular permeability', 'Bradykinin, generated from kininogen by kallikrein, is a potent mediator of pain, vasodilation and increased vascular permeability.'),
('092cc814-9599-54e7-9b02-0069e595d689'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fibrinous inflammation typically occurs on:', '["Skin surfaces resulting in decreased functional activity","Cartilage accompanied by associated clinical symptoms","Bone mediated by specific receptor activation","Serosal surfaces (pericardium pleura)","Brain parenchyma leading to subsequent cellular adaptation"]'::jsonb, 'Serosal surfaces (pericardium pleura)', 'Fibrinous inflammation characteristically involves serosal membranes such as the pericardium and pleura.'),
('05e4c8b7-131f-5e38-9fc6-9b4cf79aac14'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Gangrenous necrosis is:', '["Coagulative necrosis with superimposed putrefaction","Liquefactive necrosis only accompanied by associated clinical symptoms","Caseous necrosis only mediated by specific receptor activation","Fat necrosis only without affecting the primary tissue pathway","Fibrinoid necrosis only leading to subsequent cellular adaptation"]'::jsonb, 'Coagulative necrosis with superimposed putrefaction', 'Gangrene is coagulative necrosis of a limb or tissue with superimposed bacterial putrefaction.'),
('a605a7a9-83f1-5408-bb5d-1f6eb47ec5f4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fibrosis is characterized by:', '["Formation of new blood vessels","Restoration of normal tissue architecture","Epithelial regeneration","Excessive collagen and extracellular matrix deposition","Minimal scarring"]'::jsonb, 'Excessive collagen and extracellular matrix deposition', 'Fibrosis is the excessive deposition of collagen and extracellular matrix, causing scarring and loss of normal architecture.'),
('7886fb2d-4a13-549d-9436-9fec985ccf1b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Granulation tissue consists primarily of:', '["Epithelial cells and glands","Mature collagen and elastin","Adipose tissue","Fibroblasts and new blood vessels","Nerve fibers"]'::jsonb, 'Fibroblasts and new blood vessels', 'Granulation tissue is composed of proliferating fibroblasts and delicate new blood vessels (angiogenesis) within a loose ECM.'),
('34c8ce11-82e0-5476-a661-74d8045ccda3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'In which setting does dystrophic calcification characteristically occur?', '["Kidney only","Normal tissues with hypercalcemia","Bone only","Damaged or necrotic tissues","Metastatic tumors only"]'::jsonb, 'Damaged or necrotic tissues', 'Dystrophic calcification deposits calcium in damaged or necrotic tissue despite normal serum calcium levels.'),
('cada9abf-7a1e-5fab-938e-a255ab06121f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Metastatic calcification occurs due to:', '["Hypercalcemia from any cause","Infection","Necrosis without hypercalcemia","Inflammation","Local tissue damage without hypercalcemia"]'::jsonb, 'Hypercalcemia from any cause', 'Metastatic calcification deposits calcium in normal tissues as a consequence of hypercalcemia.'),
('f0cb08e3-06cf-546a-9f94-db665dd58d76'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Lipofuscin is also known as:', '["Carbon pigment","Iron pigment","Formalin pigment","Bile pigment","Wear-and-tear pigment"]'::jsonb, 'Wear-and-tear pigment', 'Lipofuscin, a brown pigment accumulating with age in lysosomes, is called the ''wear-and-tear'' pigment.'),
('cc4979e3-d792-5bbf-880b-7aaf0da8791c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Anthracosis, seen in coal workers'' pneumoconiosis, results from accumulation of which substance in the lungs?', '["Calcium in lungs","Hemosiderin in lungs","Bilirubin in lungs","Carbon pigment (coal dust) in lungs","Melanin in lungs"]'::jsonb, 'Carbon pigment (coal dust) in lungs', 'Inhaled carbon pigment (coal dust) accumulates in alveolar macrophages and interstitial tissues, producing anthracosis.'),
('f05d44c6-74b5-5d84-9562-53e9e6d1fd2a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Mallory hyaline bodies are characteristically found in which liver disorder?', '["Hemochromatosis","Hepatocellular carcinoma","Alcoholic liver disease","Wilson disease","Primary biliary cirrhosis"]'::jsonb, 'Alcoholic liver disease', 'Mallory-Denk bodies are eosinophilic cytoplasmic keratin aggregates that are a hallmark of alcoholic liver disease, especially alcoholic hepatitis.'),
('c8c2f3d3-c80d-50d0-9762-456a774edaa6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Lewy bodies are characteristic of:', '["Amyotrophic lateral sclerosis","Huntington disease","Parkinson disease","Alzheimer disease","Multiple sclerosis"]'::jsonb, 'Parkinson disease', 'Eosinophilic intracytoplasmic Lewy bodies in dopaminergic neurons are the pathologic hallmark of Parkinson disease.'),
('15f792ec-53c4-52ba-95a4-04ee1c8f4030'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Congo red stain of amyloid demonstrates:', '["Red fluorescence","Purple granular staining","Yellow autofluorescence","Blue staining under routine light","Apple-green birefringence under polarized light"]'::jsonb, 'Apple-green birefringence under polarized light', 'Congo red-stained amyloid shows apple-green birefringence when viewed under polarized light.'),
('74976cb8-c9c2-59f1-bf0c-447f4e8d7ad0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which combination of features best describes necrosis as opposed to apoptosis?', '["Phagocytosis of intact cells","Cellular swelling membrane rupture and inflammation","Endogenous nucleases producing DNA laddering","Programmed cell death with ATP requirement","Apoptotic body formation"]'::jsonb, 'Cellular swelling membrane rupture and inflammation', 'Necrosis is characterized by cellular swelling, membrane rupture and secondary inflammation, whereas apoptosis is an orderly, non-inflammatory programmed death.'),
('8de2635d-d711-5f5b-8072-6b7944b62b63'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A 45-year-old patient suffers prolonged hypotension during surgery, producing irreversible ischemic cell injury. Which morphologic nuclear change most specifically indicates this irreversible injury?', '["Membrane blebbing","Nuclear pyknosis and karyolysis","Reduced ATP","Mitochondrial swelling","Cellular swelling"]'::jsonb, 'Nuclear pyknosis and karyolysis', 'Prolonged ischemia causes irreversible cell death; the characteristic nuclear changes of necrosis—pyknosis, karyorrhexis and karyolysis—are definitive.'),
('2df12aa2-c291-525d-a8ae-2753a431463c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which term best describes a preinvasive neoplastic proliferation of the full epithelial thickness that remains confined by the basement membrane?', '["Invasive carcinoma limited to the mucosa resulting in decreased functional activity","Metastatic carcinoma accompanied by associated clinical symptoms","Mild dysplasia with minimal atypia mediated by specific receptor activation","Benign tumor with malignant potential without affecting the primary tissue pathway","Severe dysplasia involving full epithelial thickness without BM invasion"]'::jsonb, 'Severe dysplasia involving full epithelial thickness without BM invasion', 'Carcinoma in situ (CIS) is severe dysplasia involving the full epithelial thickness without invasion through the basement membrane.'),
('dbe3f846-dd27-534e-b078-83d2e04ec8ca'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cytokine, released by activated macrophages, acts on the hypothalamus as the principal endogenous pyrogen to produce fever?', '["IL-1","IL-5","IL-4","IL-10","IL-2"]'::jsonb, 'IL-1', 'IL-1 is the classic endogenous pyrogen that resets the hypothalamic thermoregulatory set point, producing fever.'),
('67fe1d5e-9910-53fd-9f01-cf564a96f727'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which peripheral blood finding is expected in the setting of an acute pyogenic bacterial infection?', '["Increased monocytes","Decreased neutrophils","Increased eosinophils","Increased lymphocytes","Increased band neutrophils"]'::jsonb, 'Increased band neutrophils', 'Acute bacterial infection produces a left shift with increased circulating band (immature) neutrophils.'),
('5e2bb2eb-3458-54f0-a8a1-3533c75634d9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which process characterizes the cellular response that dominates chronic inflammation?', '["Complement activation","Neutrophil chemotaxis","Type IV hypersensitivity","Increased vascular permeability","Macrophage activation"]'::jsonb, 'Macrophage activation', 'Chronic inflammation is dominated by mononuclear cells; activation of macrophages and their conversion to epithelioid cells are central.'),
('f53d46c1-c11f-596c-827f-6a3f65a1252c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Histamine and serotonin, stored in mast cells and platelets, both act on the microvasculature to produce which early inflammatory change?', '["Increased vascular permeability","Type IV hypersensitivity","Complement activation","Macrophage activation","Neutrophil chemotaxis"]'::jsonb, 'Increased vascular permeability', 'Vasoactive amines such as histamine and serotonin cause endothelial cell contraction and gap formation, increasing vascular permeability.'),
('2405f4a8-002d-59dc-926f-17c7aff6f6cc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which vascular process is directly responsible for the escape of protein-rich fluid (exudate) into tissues in acute inflammation?', '["Macrophage activation","Increased vascular permeability","Complement activation","Type IV hypersensitivity","Neutrophil chemotaxis"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability at postcapillary venules allows protein-rich plasma to escape, producing the exudate of acute inflammation.'),
('07058d46-4fae-5b70-a4f5-b16e60163eeb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fat necrosis occurs in:', '["Acute pancreatitis and breast trauma","Myocardial infarction","Brain infarct","Liver cirrhosis","Renal infarct"]'::jsonb, 'Acute pancreatitis and breast trauma', 'Fat necrosis results from enzymatic lipolysis with saponification; it is classically seen in acute pancreatitis and breast trauma.'),
('bd7ecb87-e7ac-5476-bf11-f8839267e25e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which enzyme generates hypochlorous acid (HOCl) from hydrogen peroxide and chloride during the respiratory burst?', '["NADPH oxidase","Myeloperoxidase","Catalase","Superoxide dismutase","Glutathione peroxidase"]'::jsonb, 'Myeloperoxidase', 'Myeloperoxidase in neutrophil azurophilic granules converts H2O2 and Cl- to hypochlorous acid, the most potent bactericidal oxidant.'),
('57a4437f-72de-5bf0-a11d-33c1a20f5745'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Contractile cells with smooth-muscle features that appear during granulation tissue and approximate wound edges are known as?', '["Lymphocytes","Myofibroblasts","Endothelial cells","Plasma cells","Mast cells"]'::jsonb, 'Myofibroblasts', 'Myofibroblasts, hybrid cells with features of smooth muscle and fibroblasts, are responsible for wound contraction during healing.'),
('e61952b0-ca8e-5922-b2d8-e0525851d904'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fibrinoid necrosis of vessel walls is defined microscopically by deposits composed predominantly of which material?', '["Amyloid","Collagen","Fibrin","Hemosiderin","Calcium"]'::jsonb, 'Fibrin', 'Fibrinoid necrosis shows deposition of fibrin and plasma proteins, giving a brightly eosinophilic (''fibrinoid'') appearance in vessel walls.'),
('10c0c629-520c-52ae-962a-217f97794ea5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A chemoattractant gradient generated at a focus of tissue injury elicits which directed response in marginated leukocytes?', '["Macrophage activation","Increased vascular permeability","Complement activation","Neutrophil chemotaxis","Type IV hypersensitivity"]'::jsonb, 'Neutrophil chemotaxis', 'Chemotaxis is the directional movement of leukocytes along a chemical gradient toward the focus of injury.'),
('422d397e-896e-5282-9047-641e5a08efe6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Vitamin C and vitamin E are grouped together as which class of cellular protective agents against free radical injury?', '["Antioxidants","Cytochromes","Oxidases","Peroxidases","Lipases"]'::jsonb, 'Antioxidants', 'Vitamin C (water-soluble) and vitamin E (lipid-soluble) are antioxidant scavengers that neutralize free radicals and protect cell membranes.'),
('51814ceb-0e50-5f8b-b176-84bef4a24cec'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Granulomatous inflammation is characterised by which cellular process?', '["Macrophage activation","Type IV hypersensitivity","Increased vascular permeability","Complement activation","Neutrophil chemotaxis"]'::jsonb, 'Macrophage activation', 'Granulomas form when activated macrophages transform into epithelioid cells and multinucleated giant cells.'),
('53d989f0-f402-593c-a808-208f3b0f6d74'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cellular stress is the principal trigger for p53-dependent apoptosis?', '["DNA damage","Growth factor withdrawal","Death-receptor ligation","Unfolded protein response","Complement attack"]'::jsonb, 'DNA damage', 'DNA damage activates the ''guardian of the genome'' p53, which arrests the cell cycle and, if damage is irreparable, induces apoptosis.'),
('12313e71-eb59-553a-8bee-5f9195707ce9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Epithelioid cells and Langhans giant cells arise predominantly through which mechanism?', '["Macrophage activation","Complement activation","Type IV hypersensitivity","Neutrophil chemotaxis","Increased vascular permeability"]'::jsonb, 'Macrophage activation', 'Activated macrophages differentiate into epithelioid cells and fuse to form Langhans giant cells within granulomas.'),
('bc7324e3-da27-58ae-8074-430f868a2fbd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Keloids most characteristically develop at which body site after skin injury?', '["Earlobes","Palms","Soles","Oral mucosa","Scalp"]'::jsonb, 'Earlobes', 'Keloids, exuberant scars extending beyond wound margins, occur most often at predisposed sites such as the earlobes and sternum.'),
('c60a897b-f721-5a7c-86c8-0d8522ee60a0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cytokine promotes B-cell differentiation into antibody-secreting plasma cells?', '["IL-6","IL-2","IL-8","TNF-alpha","IFN-gamma"]'::jsonb, 'IL-6', 'IL-6 drives the final differentiation of B cells into plasma cells that secrete immunoglobulins, in addition to driving acute-phase protein synthesis.'),
('add521c3-3f27-5d88-9c6d-8110c79272a8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cascade, when activated, generates C3b, C5a and C5b-9?', '["Neutrophil chemotaxis","Increased vascular permeability","Complement activation","Macrophage activation","Type IV hypersensitivity"]'::jsonb, 'Complement activation', 'Complement activation generates C3b (opsonin), C5a (chemotaxin and anaphylatoxin) and the C5b-9 membrane attack complex.'),
('bdec7865-ef58-50ce-bcae-7423588ba014'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Bradykinin contributes to the acute inflammatory response chiefly by causing:', '["Fever","Vasoconstriction and platelet aggregation","Pain and increased vascular permeability","Neutrophil chemotaxis","Opsonization"]'::jsonb, 'Pain and increased vascular permeability', 'Bradykinin is a potent mediator of pain and increased vascular permeability, reinforcing vasodilation and exudation.'),
('88b7d463-53db-579c-ba7e-eddbec3a151a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Leukocyte integrins binding to endothelial ICAM-1 chiefly mediate which step of the emigration cascade?', '["Rolling","Firm adhesion","Margination","Chemotaxis","Phagocytosis"]'::jsonb, 'Firm adhesion', 'After selectin-mediated rolling, leukocyte integrins (LFA-1) bind ICAM-1 to achieve firm adhesion before transmigration.'),
('5f82bc68-cd8d-5254-a325-2db53a3a01b7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Recurrent pyogenic infections, particularly with encapsulated organisms, may result from a defect in which effector system?', '["Increased vascular permeability","Complement activation","Neutrophil chemotaxis","Macrophage activation","Type IV hypersensitivity"]'::jsonb, 'Complement activation', 'C3 deficiency impairs opsonization and deprives the host of complement-mediated defense, predisposing to recurrent pyogenic and encapsulated-bacterial infections.'),
('d3ea006b-03ac-518e-a50e-2eab029f2210'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which hypersensitivity reaction is delayed and mediated by T cells?', '["Complement activation","Neutrophil chemotaxis","Type IV hypersensitivity","Macrophage activation","Increased vascular permeability"]'::jsonb, 'Type IV hypersensitivity', 'Type IV hypersensitivity (DTH) is cell-mediated by sensitized T cells and activated macrophages, developing over 24-72 hours.'),
('ab662c42-699b-596c-8af9-30b41576f82a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which mechanism immediately underlies the cellular swelling seen in early reversible cell injury?', '["Influx of sodium and water after Na/K ATPase failure","Loss of all mitochondrial membrane potential","Lysosomal enzyme leakage","Nuclear fragmentation","Membrane attack complex deposition"]'::jsonb, 'Influx of sodium and water after Na/K ATPase failure', 'ATP depletion impairs the Na+/K+-ATPase, causing sodium and water to enter the cell with resulting swelling (hydropic change).'),
('a6db5ebf-4834-5f68-ab84-6cc68aefdb29'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The transformation of recruited blood monocytes into tissue phagocytes is the essence of which process?', '["Complement activation","Neutrophil chemotaxis","Increased vascular permeability","Type IV hypersensitivity","Macrophage activation"]'::jsonb, 'Macrophage activation', 'Circulating monocytes differentiate into tissue macrophages, whose activation underlies granuloma formation and chronic inflammation.'),
('89b3c13d-9da4-5b4b-b744-47a787c41fbc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Cheese-like granular necrotic debris within tuberculous granulomas is classically seen in which infection?', '["Tuberculosis","Myocardial infarction","Brain infarct","Fat necrosis","Gangrene"]'::jsonb, 'Tuberculosis', 'Caseous necrosis, with its soft cheesy appearance, is the characteristic necrosis of tuberculous infection.'),
('68c2afe3-5c2c-574b-8fa9-2990fa33bd5d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Enlargement of the endometrium under the influence of estrogen in the proliferative phase of the cycle is an example of which change?', '["Physiologic hyperplasia","Physiologic hypertrophy","Metaplasia","Dysplasia","Atrophy"]'::jsonb, 'Physiologic hyperplasia', 'Hormone-driven proliferation producing an increase in cell number is physiologic hyperplasia, as in the estrogen-stimulated endometrium.'),
('a0e43813-8f15-5238-b838-6caeb5ddd784'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'In a patient with dystrophic calcification, the serum calcium level is most likely to be:', '["Normal","Raised","Low","Undetectable","Severely elevated"]'::jsonb, 'Normal', 'Dystrophic calcification deposits calcium in dead or damaged tissue despite normal serum calcium, unlike metastatic calcification.'),
('eaf1bd0b-9ffc-5d6e-bc0c-6fa651efaf18'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Barrett esophagus with intestinal metaplasia is clinically important mainly because it predisposes to which complication?', '["Adenocarcinoma of the esophagus","Squamous cell carcinoma","Sarcoma","Lymphoma","Small-cell carcinoma"]'::jsonb, 'Adenocarcinoma of the esophagus', 'Intestinal metaplasia in Barrett esophagus is a precursor lesion carrying an increased risk of esophageal adenocarcinoma.'),
('c3ebd7f3-1e98-5c4b-87f9-33b57b78313c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Cervical intraepithelial neoplasia (CIN) grades I-III represent which type of cellular change?', '["Dysplasia","Metaplasia","Hyperplasia","Hypertrophy","Atrophy"]'::jsonb, 'Dysplasia', 'CIN is a dysplastic spectrum characterized by nuclear atypia and disordered maturation; CIN III approximates carcinoma in situ.'),
('6b10e3ba-d4cc-5a8a-a3eb-20685c688085'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Contact dermatitis and the tuberculin reaction are classic examples of which hypersensitivity?', '["Complement activation","Neutrophil chemotaxis","Increased vascular permeability","Macrophage activation","Type IV hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Both reactions are delayed, T-cell-mediated (type IV) hypersensitivity responses.'),
('08d5c702-5751-583c-a1b9-203ad53d1c79'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemoattractants such as leukotriene B4 and bacterial formyl peptides direct which leukocyte process?', '["Macrophage activation","Complement activation","Increased vascular permeability","Neutrophil chemotaxis","Type IV hypersensitivity"]'::jsonb, 'Neutrophil chemotaxis', 'LTB4 and bacterial formyl peptides are chemoattractants that direct directional movement (chemotaxis) of neutrophils.'),
('8a02493c-5f93-5ab6-85e9-2b3c0fa59982'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Opsonization, anaphylatoxin generation and lysis of targets by the membrane attack complex are all consequences of which cascade?', '["Complement activation","Neutrophil chemotaxis","Increased vascular permeability","Macrophage activation","Type IV hypersensitivity"]'::jsonb, 'Complement activation', 'The complement cascade opsonizes microbes, generates anaphylatoxins and assembles the C5b-9 membrane attack complex that lyses targets.'),
('1c38c7c1-c94f-52fa-ab57-9792f1afe2ec'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which organ, after partial surgical resection, has the greatest capacity to regenerate its lost tissue?', '["Liver","Pancreas","Myocardium","Brain","Skeletal muscle"]'::jsonb, 'Liver', 'The liver is a labile/stable organ with remarkable regenerative capacity, as shown by regrowth after partial hepatectomy.'),
('f93c3be1-1fff-5881-bb92-d094a8d19756'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Prostaglandins chiefly contribute to which local signs of acute inflammation?', '["Pain and fever","Chemotaxis","Opsonization","Neutrophil activation","Vascular lysis"]'::jsonb, 'Pain and fever', 'Prostaglandins, especially PGE2, sensitize pain receptors and reset the hypothalamic set point, producing pain and fever.'),
('11282821-9281-5413-b667-c2af665cc415'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which process degrades and recycles damaged intracellular organelles through the lysosome?', '["Self-eating process for recycling damaged organelles","Cell division accompanied by associated clinical symptoms","Cell growth mediated by specific receptor activation","Inflammation without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Self-eating process for recycling damaged organelles', 'Autophagy is the lysosomal ''self-eating'' pathway that recycles damaged organelles and supports cell survival during stress.'),
('92f29ad5-d5e8-5e15-94e3-c1aee81da6e6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which process is the directional migration of leukocytes along a chemical concentration gradient?', '["Increased vascular permeability","Macrophage activation","Neutrophil chemotaxis","Type IV hypersensitivity","Complement activation"]'::jsonb, 'Neutrophil chemotaxis', 'Chemotaxis is the directed movement of leukocytes toward chemoattractants along a chemical gradient.'),
('351c5541-64ea-5405-8c6d-6efda48c327b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fatty change (steatosis) visible as yellow, greasy cut surface is due to accumulation of which substance within parenchymal cells?', '["Triglycerides","Cholesterol","Phospholipids","Ceroid","Glycogen"]'::jsonb, 'Triglycerides', 'Steatosis is the accumulation mainly of triglycerides in hepatocytes, producing a yellow, greasy, fatty organ.'),
('d80e9883-f0ac-5cf7-9548-3fb92c189806'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The classical, lectin and alternative pathways all converge to activate which effector system?', '["Macrophage activation","Neutrophil chemotaxis","Complement activation","Increased vascular permeability","Type IV hypersensitivity"]'::jsonb, 'Complement activation', 'All three complement pathways converge on cleavage of C3 and formation of C5b-9, activating the complement effector system.'),
('a908c78b-0ae1-5776-a3bd-096f6bed769b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Wasting of lean body mass (cachexia) in chronic inflammatory and malignant disease is attributed chiefly to which cytokine?', '["TNF-alpha","IL-10","IL-4","TGF-beta","IL-5"]'::jsonb, 'TNF-alpha', 'TNF-α (cachectin) suppresses appetite, induces muscle wasting and mediates the cachexia of chronic disease.'),
('497659e7-0a65-51b2-aa7c-d960b5af281d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A hypersensitivity reaction that peaks at 24-72 hours and is mediated by sensitized T lymphocytes is classified as:', '["Increased vascular permeability","Type IV hypersensitivity","Neutrophil chemotaxis","Complement activation","Macrophage activation"]'::jsonb, 'Type IV hypersensitivity', 'Delayed-type hypersensitivity is T-cell-mediated, developing 24-72 hours after antigen exposure.'),
('ffb0abbc-3168-5f91-9586-fbd67b15f9c1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A chemical gradient released by injured tissue promotes which leukocyte response at the inflammatory focus?', '["Complement activation","Increased vascular permeability","Neutrophil chemotaxis","Macrophage activation","Type IV hypersensitivity"]'::jsonb, 'Neutrophil chemotaxis', 'Chemoattractants such as C5a, LTB4 and bacterial products direct neutrophils along a concentration gradient (chemotaxis).'),
('5a497956-cf86-5175-ad41-bcf79da139b9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Deficiency of which system, with impaired opsonization and inability to lyse microbes, classically presents with recurrent pyogenic infections?', '["Complement activation","Neutrophil chemotaxis","Increased vascular permeability","Type IV hypersensitivity","Macrophage activation"]'::jsonb, 'Complement activation', 'Complement defects impair opsonization and lysis of encapsulated bacteria, causing recurrent pyogenic infections.'),
('168e678f-f5b1-5499-967b-67c3da272f7c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which leukocyte function is prompted by chemical mediators diffusing from damaged tissue?', '["Complement activation","Neutrophil chemotaxis","Type IV hypersensitivity","Increased vascular permeability","Macrophage activation"]'::jsonb, 'Neutrophil chemotaxis', 'Chemical mediators diffusing from injured tissue create a gradient that attracts neutrophils by chemotaxis.'),
('965086d3-83a5-5788-91ae-a3586a8c13a5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Apoptosis features include:', '["Cell shrinkage, membrane blebbing, apoptotic bodies","Cell swelling, membrane rupture accompanied by associated clinical symptoms","Inflammation mediated by specific receptor activation","Necrosis without affecting the primary tissue pathway","Fibrosis leading to subsequent cellular adaptation"]'::jsonb, 'Cell shrinkage, membrane blebbing, apoptotic bodies', 'Apoptotic cells shrink, bleb and fragment into apoptotic bodies, with no inflammatory reaction.'),
('574f0f1e-22d5-5d43-91f6-3251564119cd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Restoration of injured tissue by proliferation of cells identical to those lost, such as hepatocytes after partial hepatectomy, is termed:', '["Regeneration","Fibrosis","Granulation tissue formation","Organization","Metaplasia"]'::jsonb, 'Regeneration', 'Regeneration replaces damaged cells with cells of the same type, restoring normal structure and function.'),
('73e40d38-cff5-5ef7-b467-c998f80938cd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A transudate (low-protein, cell-poor effusion) is characteristically produced in which clinical setting?', '["Congestive heart failure","Acute bacterial pleurisy","Tuberculosis","Malignant pleural effusion","Rheumatoid pleuritis"]'::jsonb, 'Congestive heart failure', 'Transudates result from altered hydrostatic or oncotic pressure without inflammation, as in congestive heart failure.'),
('e2415dbf-c825-5997-bce5-b7b8e2d9d26e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Metastatic calcification is characteristically a consequence of which underlying state?', '["Hyperparathyroidism, vitamin D excess, malignancy","Normal calcium levels accompanied by associated clinical symptoms","Hypocalcemia mediated by specific receptor activation","Hypoparathyroidism without affecting the primary tissue pathway","Vitamin D deficiency leading to subsequent cellular adaptation"]'::jsonb, 'Hyperparathyroidism, vitamin D excess, malignancy', 'Metastatic calcification of normal tissues follows hypercalcemia from hyperparathyroidism, vitamin D excess or malignancy.'),
('7a422e1b-2c10-5819-a9e6-318d510711c5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A multinucleated giant cell with nuclei arranged as a peripheral horseshoe ring, seen in tuberculous granulomas, is which cell?', '["Langhans giant cell","Touton giant cell","Foreign body giant cell","Reed-Sternberg cell","Aschoff cell"]'::jsonb, 'Langhans giant cell', 'Langhans giant cells have a peripheral horseshoe-shaped nuclear arrangement and are characteristic of tuberculous (caseating) granulomas.'),
('02b2fa63-5d18-5296-80ab-19a58ada0173'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Carcinoma in situ differs from invasive carcinoma by which essential feature?', '["Absence of invasion through the basement membrane","Presence of distant metastasis","Full-thickness atypia with invasion","Perineural spread","Lymphovascular invasion"]'::jsonb, 'Absence of invasion through the basement membrane', 'Carcinoma in situ is a preinvasive lesion: malignant cells fill the full epithelial thickness but remain confined by the basement membrane.'),
('139e4c27-44a1-51a0-846e-423739be71a7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A cell-mediated immune reaction that peaks 24-72 hours after antigen exposure corresponds to which type of hypersensitivity?', '["Type IV hypersensitivity","Complement activation","Increased vascular permeability","Macrophage activation","Neutrophil chemotaxis"]'::jsonb, 'Type IV hypersensitivity', 'The 24-72 hour latency and dependence on sensitized T cells identify this as type IV (delayed-type) hypersensitivity.'),
('c0b4bca6-d8f1-59e5-95f1-b6d1f76bd3b8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Keloids are most commonly observed in which group of individuals?', '["Darker-skinned individuals","Albinos","Fair-skinned individuals","Neonates","Elderly only"]'::jsonb, 'Darker-skinned individuals', 'Keloids show a racial predilection, occurring more commonly in individuals with darker skin.'),
('c638b62a-5da2-5543-ae14-efe2c7f5fe46'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Councilman bodies, small hyaline eosinophilic globules seen in yellow fever and viral hepatitis, represent which process?', '["Apoptotic hepatocytes","Suppurative necrotic hepatocytes","Fatty hepatocytes","Viral inclusion bodies","Vacuolated hepatocytes"]'::jsonb, 'Apoptotic hepatocytes', 'Councilman (acidophil) bodies are shrunken, deeply eosinophilic hepatocytes undergoing apoptosis.'),
('76db567e-e7b3-5090-b390-5c89fbccc89e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Directed movement of leukocytes toward a bacterial peptide gradient is the essence of which process?', '["Complement activation","Macrophage activation","Type IV hypersensitivity","Increased vascular permeability","Neutrophil chemotaxis"]'::jsonb, 'Neutrophil chemotaxis', 'Chemotaxis is directional locomotion of leukocytes toward chemical attractants such as bacterial peptides.'),
('69aa44a8-f95f-57ae-803c-c27cb2803265'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cellular mechanism underlies the swelling seen in early reversible cell injury?', '["Failure of the plasma membrane Na+/K+ ATPase with sodium and water influx","Lysosomal enzyme leakage accompanied by associated clinical symptoms","Mitochondrial calcium overload mediated by specific receptor activation","Nuclear fragmentation without affecting the primary tissue pathway","Membrane attack complex deposition leading to subsequent cellular adaptation"]'::jsonb, 'Failure of the plasma membrane Na+/K+ ATPase with sodium and water influx', 'ATP depletion fails the Na+/K+-ATPase, so sodium and water enter the cell, producing hydropic swelling.'),
('e4b395b0-7536-5a76-bfb1-71be5762e399'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Deposition of calcium salts in dead or degenerating tissue despite normal serum calcium is termed:', '["Dystrophic calcification (in dead/dying tissue)","Metastatic calcification (normal tissue)","Physiologic calcification","Pathologic resorption","Physiologic resorption"]'::jsonb, 'Dystrophic calcification (in dead/dying tissue)', 'Dystrophic calcification occurs in necrotic or degenerating tissue with normal calcium metabolism.'),
('2ee74815-0f16-57a1-b470-f01d43b8cdbf'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which vascular change is chiefly responsible for the protein-rich fluid of an inflammatory exudate?', '["Neutrophil chemotaxis","Complement activation","Macrophage activation","Increased vascular permeability","Type IV hypersensitivity"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability is the hallmark microvascular event of acute inflammation, underlying exudation and swelling.'),
('9b1ca132-07cd-5d50-ba11-99722fe7e4cf'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', '''Self-eating'' of cytoplasmic contents destined for lysosomal degradation is the definition of which process?', '["Self-eating process for recycling damaged organelles","Cell division accompanied by associated clinical symptoms","Cell growth mediated by specific receptor activation","Inflammation without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Self-eating process for recycling damaged organelles', 'Autophagy literally means ''self-eating''; it is the lysosomal pathway that recycles organelles and debris.'),
('45142862-303b-5791-a357-468fc8604357'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cascade produces opsonization (C3b), anaphylatoxins (C3a, C5a) and the C5b-9 lytic complex?', '["Type IV hypersensitivity","Increased vascular permeability","Macrophage activation","Complement activation","Neutrophil chemotaxis"]'::jsonb, 'Complement activation', 'Complement activation generates C3b, anaphylatoxins and C5b-9, coupling microbial lysis with amplification of inflammation.'),
('0f4f3d75-87a8-5db8-8f98-1b55883bc418'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Directional movement of neutrophils toward a chemical attractant is termed:', '["Chemotaxis","Diapedesis","Margination","Phagocytosis","Opsonization"]'::jsonb, 'Chemotaxis', 'Chemotaxis is the directed migration of leukocytes along a chemical concentration gradient toward the inflammatory focus.'),
('9c7d97f5-5d81-5d18-a4a3-b921a67482ea'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cellular response dominates chronic inflammation and culminates in epithelioid cells and multinucleated giant cells?', '["Neutrophil chemotaxis","Complement activation","Increased vascular permeability","Macrophage activation","Type IV hypersensitivity"]'::jsonb, 'Macrophage activation', 'Chronic inflammation is dominated by activated macrophages, which form epithelioid cells and multinucleated giant cells in granulomas.'),
('c184f7e0-6d48-5542-b56d-9ab91bf0990a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The alternative complement pathway is initiated by which event?', '["Spontaneous hydrolysis of C3 with C3b deposition on microbial surfaces","C1q binding to antibody-antigen complexes accompanied by associated clinical symptoms","MBL binding to mannose residues mediated by specific receptor activation","Properdin binding to IgG without affecting the primary tissue pathway","Factor H binding to sialic acid leading to subsequent cellular adaptation"]'::jsonb, 'Spontaneous hydrolysis of C3 with C3b deposition on microbial surfaces', 'Low-grade spontaneous C3 hydrolysis (''tickover'') deposits C3b on microbial surfaces, initiating the alternative pathway without antibody.'),
('329c416b-08cc-5155-83df-defd30ad5c21'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A gradient of chemoattractants generated at a focus of tissue damage triggers which response in leukocytes?', '["Complement activation","Type IV hypersensitivity","Neutrophil chemotaxis","Macrophage activation","Increased vascular permeability"]'::jsonb, 'Neutrophil chemotaxis', 'Chemoattractant gradients drive chemotaxis, recruiting neutrophils to the site of damage.'),
('ecdb7dad-cfd7-534c-89bc-c739c0e85592'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Leakage of plasma protein and fluid into tissue, the basis of inflammatory edema, results from which process?', '["Increased vascular permeability","Macrophage activation","Type IV hypersensitivity","Complement activation","Neutrophil chemotaxis"]'::jsonb, 'Increased vascular permeability', 'Endothelial gap formation increases vascular permeability, allowing protein-rich fluid to leak into tissues as inflammatory edema.'),
('88c6b1c8-f3bc-5112-9562-2486756bd433'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Release of chemotactic factors from an inflamed site causes which directional leukocyte response?', '["Type IV hypersensitivity","Macrophage activation","Complement activation","Neutrophil chemotaxis","Increased vascular permeability"]'::jsonb, 'Neutrophil chemotaxis', 'Chemotactic factors diffuse from the lesion and attract neutrophils by chemotaxis.'),
('6c63f7b4-6d5d-572d-8702-29bbe1a55561'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Calcium accumulating at sites of old necrosis, such as an organized thrombus or old tuberculous focus, is an example of:', '["Dystrophic calcification (in dead/dying tissue)","Metastatic calcification (normal tissue)","Physiologic calcification","Pathologic resorption","Physiologic resorption"]'::jsonb, 'Dystrophic calcification (in dead/dying tissue)', 'Deposition of calcium in previous necrotic tissue with normal serum calcium is dystrophic calcification.'),
('7f4317d1-b90b-5c03-8025-34193e8e699c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Metastatic calcification of normal tissues is most commonly encountered in which condition?', '["Chronic renal failure with secondary hyperparathyroidism","Chronic alcoholism accompanied by associated clinical symptoms","Atherosclerosis mediated by specific receptor activation","Tuberculosis without affecting the primary tissue pathway","Old myocardial infarction leading to subsequent cellular adaptation"]'::jsonb, 'Chronic renal failure with secondary hyperparathyroidism', 'Chronic renal failure produces hyperphosphatemia with secondary hyperparathyroidism, a common cause of hypercalcemia and metastatic calcification.'),
('d1103093-bebf-568a-938b-28b96586ce37'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'C1 inhibitor (C1 esterase inhibitor) directly regulates which cascade by inactivating C1r and C1s?', '["Classical complement pathway","Lectin pathway","Alternative pathway","Coagulation cascade","Fibrinolytic cascade"]'::jsonb, 'Classical complement pathway', 'C1 inhibitor inactivates activated C1r and C1s, controlling the classical complement pathway (it also inhibits kallikrein, FXIIa and plasmin).'),
('deca5730-d74e-5d3d-b63d-d8df5a872f6b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Epithelioid cells and Langhans giant cells in chronic inflammation develop through which mechanism?', '["Neutrophil chemotaxis","Increased vascular permeability","Macrophage activation","Type IV hypersensitivity","Complement activation"]'::jsonb, 'Macrophage activation', 'Activated macrophages transform into epithelioid cells and fuse to form Langhans giant cells in granulomatous inflammation.'),
('b846a47d-6852-545e-bb6a-ae2272884f4d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Histamine and serotonin act on vascular endothelium to produce which change?', '["Type IV hypersensitivity","Complement activation","Neutrophil chemotaxis","Increased vascular permeability","Macrophage activation"]'::jsonb, 'Increased vascular permeability', 'These vasoactive amines induce endothelial contraction at postcapillary venules, increasing vascular permeability.'),
('bcfd5b5e-b5a3-55e9-ae30-033b6d563852'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which nuclear change of necrosis is defined as shrinkage and increased basophilia of the nucleus?', '["Pyknosis","Karyorrhexis","Karyolysis","Mitosis","Apoptosis"]'::jsonb, 'Pyknosis', 'Pyknosis is characterized by nuclear shrinkage and condensation into a small hyperchromatic mass; karyorrhexis is fragmentation and karyolysis is dissolution.'),
('75b75f37-8159-5a4c-9b1d-60444f1127d8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Myocardial infarction, caused by coronary artery occlusion, produces which pattern of necrosis?', '["Coagulative necrosis","Liquefactive necrosis","Caseous necrosis","Fat necrosis","Fibrinoid necrosis"]'::jsonb, 'Coagulative necrosis', 'Ischemia of solid organs such as the heart produces coagulative necrosis, with preservation of the tissue architecture (ghost cells).'),
('f242cf2c-3ecb-502f-aeb8-555d7c31d6d6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which microvascular alteration underlies exudation in acute inflammation?', '["Macrophage activation","Complement activation","Increased vascular permeability","Neutrophil chemotaxis","Type IV hypersensitivity"]'::jsonb, 'Increased vascular permeability', 'Mediators such as histamine cause endothelial contraction and gap formation, increasing vascular permeability and fluid exudation.'),
('a7618abd-27f7-50e8-a4d5-4cc22a250562'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Loss of fluid and protein into tissue during acute inflammation is the direct consequence of which vascular event?', '["Complement activation","Increased vascular permeability","Type IV hypersensitivity","Neutrophil chemotaxis","Macrophage activation"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability allows protein-rich fluid to escape into the interstitium, producing exudation and edema.'),
('ae77bb25-8814-54b1-b438-b1cfcbdfa3c5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemotactic factors recruit neutrophils to the inflammatory focus by stimulating which process?', '["Complement activation","Increased vascular permeability","Macrophage activation","Type IV hypersensitivity","Neutrophil chemotaxis"]'::jsonb, 'Neutrophil chemotaxis', 'Chemotactic factors direct neutrophils to migrate directionally (chemotaxis) to the site of inflammation.'),
('1891a831-4b4b-5a21-af67-1c31a9f667c9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which process best describes the mononuclear phagocyte response that characterises chronic inflammation?', '["Neutrophil chemotaxis","Type IV hypersensitivity","Complement activation","Macrophage activation","Increased vascular permeability"]'::jsonb, 'Macrophage activation', 'The mononuclear infiltrate of chronic inflammation reflects recruitment and activation of macrophages.'),
('78e7c771-2314-564f-8153-b112018f36a4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Sustained pathologic cardiac hypertrophy, although initially compensatory, ultimately predisposes to which complication?', '["Heart failure","Emphysema","Renal failure","Cirrhosis","Stroke"]'::jsonb, 'Heart failure', 'When hypertrophy can no longer compensate for overload, the myocardium decompensates and heart failure ensues.'),
('3456bc71-3e82-55ff-ae47-62b5839f532f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The principal opsonins that coat microbes to promote phagocytosis are:', '["C3b and IgG","C5a and C3a","IgM and C1q","LTB4 and IL-8","TNF-alpha and IFN-gamma"]'::jsonb, 'C3b and IgG', 'C3b and IgG coat microorganisms and are recognized by complement and Fc receptors on phagocytes, enhancing uptake (opsonization).'),
('9412e75b-d594-54f4-954a-529f8a007fdc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Activation of which system lyses microbes and simultaneously generates mediators that amplify inflammation?', '["Type IV hypersensitivity","Increased vascular permeability","Complement activation","Neutrophil chemotaxis","Macrophage activation"]'::jsonb, 'Complement activation', 'Complement both lyses microbes via C5b-9 and generates C3a/C5a anaphylatoxins that amplify the inflammatory response.'),
('9f088d58-10fb-5db0-8718-a74f664b79d7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hydropic change (cellular swelling) is a morphologic feature of which phase of cell injury?', '["Reversible cell injury","Irreversible cell injury (necrosis)","Apoptosis","Autophagy","Metaplasia"]'::jsonb, 'Reversible cell injury', 'Cellular swelling is the earliest morphologic hallmark of reversible cell injury, before nuclear changes of irreversible damage appear.');
insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('5f29f0cd-0095-5d85-8c2b-c17ad82dbc19'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Endothelial contraction at postcapillary venules leads to which immediate inflammatory event?', '["Neutrophil chemotaxis","Macrophage activation","Type IV hypersensitivity","Complement activation","Increased vascular permeability"]'::jsonb, 'Increased vascular permeability', 'Immediate transient endothelial contraction creates gaps at postcapillary venules, increasing vascular permeability.'),
('a744dce6-07fd-5fe9-852b-ae35096b81eb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The granulomas of sarcoidosis are best described morphologically as:', '["Non-caseating (tight, naked) granulomas","Caseating granulomas","Microabscesses","Suppurative granulomas","Plasma cell granulomas"]'::jsonb, 'Non-caseating (tight, naked) granulomas', 'Sarcoidosis produces well-formed non-caseating granulomas with epithelioid cells and multinucleated giant cells, with minimal necrosis.'),
('715b0fc0-0952-5856-8359-465bcd6bc668'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Serotonin is chiefly released from which source during the acute inflammatory response?', '["Platelets","Eosinophils","Lymphocytes","Macrophages","Neutrophils"]'::jsonb, 'Platelets', 'Serotonin is stored in platelet dense granules and mast cells and is released at sites of inflammation and platelet aggregation.'),
('ce704d82-a456-533e-936b-8915ec753162'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which mediator produces an immediate, transient increase in vascular permeability by inducing endothelial cell contraction?', '["Histamine","Leukotriene B4","IL-1","TNF-alpha","IFN-gamma"]'::jsonb, 'Histamine', 'Histamine from mast cells acts on H1 receptors to contract endothelial cells, producing immediate (transient) gap formation and increased permeability.'),
('1bfea36e-73f4-535b-8e54-e4951cc4a6c3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Gangrene of a limb with arterial obstruction, uninfected, producing a dry black mummified appearance, is termed:', '["Dry gangrene","Wet gangrene","Gas gangrene","Necrotizing fasciitis","Fournier gangrene"]'::jsonb, 'Dry gangrene', 'Dry gangrene is coagulative necrosis with mummification due to arterial occlusion, usually without significant bacterial infection.'),
('317de60d-adec-5aaf-8afc-395523602fd0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Granulomatous inflammation provoked by persistent intracellular pathogens reflects which immune reaction?', '["Increased vascular permeability","Neutrophil chemotaxis","Macrophage activation","Complement activation","Type IV hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Granulomas arise from cell-mediated (type IV) immunity against persistent intracellular organisms such as mycobacteria.'),
('621df0e3-696a-5788-90bb-60a2b6a5f750'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Contractile cells that form in granulation tissue and are responsible for approximating wound edges are:', '["Myofibroblasts","Lymphocytes","Endothelial cells","Mast cells","Plasma cells"]'::jsonb, 'Myofibroblasts', 'Myofibroblasts combine features of fibroblasts and smooth muscle and contract wounds during healing.'),
('9f7c7237-dd42-592b-a8da-6a8f671708b7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The ''onion-skin'' lesion with concentric intimal fibrosis and fibrinoid necrosis of splenic arterioles is classically seen in which disease?', '["Systemic lupus erythematosus","Tuberculosis","Myocardial infarction","Acute pancreatitis","Cirrhosis"]'::jsonb, 'Systemic lupus erythematosus', 'The onion-skin arteriolar lesion with fibrinoid necrosis is a distinctive vascular lesion of systemic lupus erythematosus.'),
('ac33a618-a29b-5a0c-b7dd-d55dda93e8e4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which microscopic finding most reliably distinguishes apoptosis from necrosis?', '["Apoptotic bodies with absent inflammatory response","Neutrophil-rich necrotic debris accompanied by associated clinical symptoms","Suppurative exudate mediated by specific receptor activation","Granulation tissue without affecting the primary tissue pathway","Fibrous scar leading to subsequent cellular adaptation"]'::jsonb, 'Apoptotic bodies with absent inflammatory response', 'Apoptosis produces apoptotic bodies without surrounding inflammation, whereas necrosis elicits an acute inflammatory reaction.'),
('f4e365b8-275d-5944-b67a-82bdc654ef92'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Vitamin C deficiency (scurvy) impairs wound healing primarily because the vitamin is required for:', '["Hydroxylation of proline and lysine during collagen synthesis","Wound contraction accompanied by associated clinical symptoms","Epithelial cell mitosis mediated by specific receptor activation","Fibrin clot formation without affecting the primary tissue pathway","Angiogenesis leading to subsequent cellular adaptation"]'::jsonb, 'Hydroxylation of proline and lysine during collagen synthesis', 'Vitamin C is a cofactor for prolyl/lysyl hydroxylases; deficiency prevents normal collagen maturation and cross-linking.'),
('015dc566-d074-53dc-838b-23d499633979'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Loss of normal p53 function promotes tumorigenesis mainly because p53 normally:', '["Induces cell-cycle arrest and apoptosis after DNA damage","Activates telomerase accompanied by associated clinical symptoms","Repairs DNA directly mediated by specific receptor activation","Suppresses cellular senescence without affecting the primary tissue pathway","Promotes angiogenesis leading to subsequent cellular adaptation"]'::jsonb, 'Induces cell-cycle arrest and apoptosis after DNA damage', 'p53 (''guardian of the genome'') halts the cell cycle and triggers apoptosis in response to DNA damage, preventing mutant cell survival.'),
('df77cb81-f5eb-5e77-a306-a07f64977cf9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The protein-rich fluid (exudate) that accompanies acute inflammation forms as a direct result of which vascular change?', '["Increased vascular permeability","Neutrophil chemotaxis","Type IV hypersensitivity","Complement activation","Macrophage activation"]'::jsonb, 'Increased vascular permeability', 'Exudation follows increased vascular permeability, which allows protein-rich fluid to escape into the tissues.'),
('b1891854-00f8-5342-a734-d59f17e79b24'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Transudation of protein-rich plasma into tissues during acute inflammation is due to which process?', '["Complement activation","Type IV hypersensitivity","Macrophage activation","Increased vascular permeability","Neutrophil chemotaxis"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability is the hallmark microvascular event that permits plasma proteins to enter the tissues.'),
('3e208cf8-fdb0-567e-96b3-257d83c223e3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Recruited blood monocytes becoming differentiated tissue phagocytes exemplifies which process of chronic inflammation?', '["Complement activation","Increased vascular permeability","Macrophage activation","Neutrophil chemotaxis","Type IV hypersensitivity"]'::jsonb, 'Macrophage activation', 'Monocytes emigrate into tissues and differentiate into macrophages, whose activation is central to chronic inflammation.'),
('e2264699-9009-5cfc-9ea9-289cfa176146'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which vascular change chiefly allows plasma proteins to escape into the interstitium, generating an inflammatory exudate?', '["Type IV hypersensitivity","Neutrophil chemotaxis","Complement activation","Increased vascular permeability","Macrophage activation"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability is the key microvascular change underlying exudate formation in acute inflammation.'),
('f62c9bc5-8230-53d6-93bb-e363c667f82c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which mediator-generating system, activated from kininogens by kallikrein, produces bradykinin?', '["Kinin system","Complement system","Coagulation cascade","Arachidonic acid pathway","Cytokine cascade"]'::jsonb, 'Kinin system', 'The kinin system generates bradykinin from high-molecular-weight kininogen by the action of kallikrein.'),
('de8bd0ad-d78b-514c-869f-523246ef4b3a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'After firm adhesion, leukocytes leave the vessel by squeezing between endothelial cells. This step is termed:', '["Transmigration (diapedesis)","Rolling","Tethering","Margination","Phagocytosis"]'::jsonb, 'Transmigration (diapedesis)', 'Transmigration (diapedesis) is the emigration of leukocytes between endothelial cells, following firm adhesion and preceding chemotaxis.'),
('041d01f6-e091-5bc7-881f-84052f7e2ca1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which hypersensitivity reaction involves T cell-mediated delayed inflammation?', '["Neutrophil chemotaxis","Increased vascular permeability","Complement activation","Type IV hypersensitivity","Macrophage activation"]'::jsonb, 'Type IV hypersensitivity', 'Type IV hypersensitivity is T-cell-mediated and produces delayed inflammation, as in contact dermatitis and the tuberculin test.'),
('35189bc2-fa07-5279-81ea-7d19c229f88b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Lysosome-mediated degradation of the cell''s own organelles, promoting survival during starvation, is known as:', '["Self-eating process for recycling damaged organelles","Cell division accompanied by associated clinical symptoms","Cell growth mediated by specific receptor activation","Inflammation without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Self-eating process for recycling damaged organelles', 'Autophagy recycles damaged organelles and macromolecules through lysosomes, sustaining cells during nutrient deprivation.'),
('47fdcc7d-28cf-523e-88ed-b2863af53f9c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The morphologic hallmark of reversible cell injury that appears within minutes of ischemia is:', '["Cellular swelling","Nuclear pyknosis","Karyolysis","Membrane rupture","Apoptotic body formation"]'::jsonb, 'Cellular swelling', 'Cellular swelling is the earliest morphologic manifestation of reversible injury, appearing soon after ATP depletion.'),
('a2032fd4-eb6f-5090-b848-cf70fda9ab42'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Eosinophilic intracytoplasmic neuronal inclusions called Lewy bodies are characteristic of which disease?', '["Parkinson disease","Alzheimer disease","Multiple sclerosis","Huntington disease","Amyotrophic lateral sclerosis"]'::jsonb, 'Parkinson disease', 'Lewy bodies are eosinophilic intracytoplasmic inclusions in substantia nigra neurons, the hallmark of Parkinson disease.'),
('ff415532-978f-514e-9b17-077374ca3294'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cell type is the principal producer of collagen during wound repair?', '["Fibroblast","Neutrophil","Platelet","Mast cell","Eosinophil"]'::jsonb, 'Fibroblast', 'Fibroblasts and myofibroblasts synthesize the collagen of granulation tissue and scar during wound healing.'),
('d59cb5d3-c60f-57f5-9b1d-223f1270f04b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hyperplasia is defined as an increase in which parameter?', '["Cell number","Cell size","Programmed cell death","Cell differentiation","Extracellular matrix only"]'::jsonb, 'Cell number', 'Hyperplasia is an increase in the number of cells; hypertrophy is an increase in cell size.'),
('925a3ff8-1d6d-52b3-b877-a3ca53d66c7e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'What is the typical microscopic appearance of dystrophic calcification?', '["Basophilic granular deposits in necrotic tissue","Apple-green birefringent material","Golden-brown pigment granules","Yellow refractile globules","Refractile pink needle crystals"]'::jsonb, 'Basophilic granular deposits in necrotic tissue', 'Dystrophic calcification appears as blue (basophilic) granular or amorphous calcium deposits within dead tissue.'),
('51ac72d8-c2ab-5fe7-995b-03d6e9822f3c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The intestinal-type columnar epithelium that replaces squamous mucosa in Barrett esophagus is an example of:', '["Columnar metaplasia (intestinal metaplasia)","Squamous metaplasia accompanied by associated clinical symptoms","Dysplasia mediated by specific receptor activation","Hypertrophy without affecting the primary tissue pathway","Hyperplasia leading to subsequent cellular adaptation"]'::jsonb, 'Columnar metaplasia (intestinal metaplasia)', 'In Barrett esophagus, chronic acid reflux converts squamous epithelium into columnar intestinal-type epithelium—a columnar metaplasia.'),
('436d4eaf-1307-5c71-af6d-ef6d9edbeb24'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Persistent infection with which virus underlies the development of cervical intraepithelial neoplasia?', '["High-risk human papillomavirus (HPV)","Epstein-Barr virus","Herpes simplex virus","Cytomegalovirus","Hepatitis B virus"]'::jsonb, 'High-risk human papillomavirus (HPV)', 'Persistent infection with high-risk HPV, especially types 16 and 18, drives cervical intraepithelial neoplasia.'),
('7c15f240-dfd7-5562-84f8-70fe9311c814'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cascade both lyses microbes and generates inflammatory mediators, a combination fundamental to acute inflammation?', '["Increased vascular permeability","Complement activation","Type IV hypersensitivity","Neutrophil chemotaxis","Macrophage activation"]'::jsonb, 'Complement activation', 'Complement activation lyses microbes through C5b-9 and simultaneously generates C3a/C5a anaphylatoxins that amplify inflammation.'),
('8f88e68f-d8fb-5c2d-8995-1ca9e41ed60a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A chemoattractant gradient at a site of injury recruits marginated leukocytes by stimulating which process?', '["Macrophage activation","Type IV hypersensitivity","Complement activation","Neutrophil chemotaxis","Increased vascular permeability"]'::jsonb, 'Neutrophil chemotaxis', 'Chemoattractant gradients drive chemotaxis, the directed migration of leukocytes to the injury site.'),
('d2df9dc3-337a-549b-ab06-2a33f51c5600'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Wound contraction is of greatest importance in healing by which intention?', '["Secondary intention","Primary intention","Regeneration only","Resolution","No healing"]'::jsonb, 'Secondary intention', 'Large gaping wounds healing by secondary intention contract significantly through myofibroblast activity.'),
('917cb7c2-2a44-5d54-992e-723aa4b74d42'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Graft rejection and contact dermatitis, mediated by T cells rather than antibody, represent which hypersensitivity?', '["Increased vascular permeability","Macrophage activation","Neutrophil chemotaxis","Type IV hypersensitivity","Complement activation"]'::jsonb, 'Type IV hypersensitivity', 'T-cell-mediated reactions such as graft rejection and contact dermatitis are type IV hypersensitivity.'),
('b711cfab-c288-5d32-8d09-ab86ac4d8aed'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Fat necrosis with saponification (soap formation) and chalky-white deposits is classically seen in which settings?', '["Acute pancreatitis and breast trauma","Myocardial infarction","Brain infarct","Liver cirrhosis","Renal infarct"]'::jsonb, 'Acute pancreatitis and breast trauma', 'Enzymatic fat necrosis with calcium soap formation occurs in acute pancreatitis and traumatic injury to fatty tissue such as the breast.'),
('b9a7bd11-c2fd-57ad-9349-c58dcfd5843c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Inflammatory edema arises from which vascular alteration?', '["Neutrophil chemotaxis","Complement activation","Increased vascular permeability","Type IV hypersensitivity","Macrophage activation"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability allows protein-rich fluid to leak into tissues, producing inflammatory edema.'),
('f1fd6b55-d223-59ef-9259-358c28b817bb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which of the following is a classic example of physiologic atrophy?', '["Post-menopausal atrophy of the endometrium","Left ventricular hypertrophy in athletes","Graves thyroid enlargement","Benign prostatic hyperplasia","Bronchial squamous metaplasia"]'::jsonb, 'Post-menopausal atrophy of the endometrium', 'Loss of estrogen stimulation after menopause causes physiologic atrophy of the endometrium.'),
('070d1ec8-5b42-5bc2-93e0-26917002fb50'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cytokine mediates tumor necrosis and macrophage activation and is identical to cachectin?', '["TNF-alpha","IL-4","IL-10","TGF-beta","IL-5"]'::jsonb, 'TNF-alpha', 'TNF-α (cachectin) causes hemorrhagic tumor necrosis, activates macrophages and mediates cachexia.'),
('5b9d3d47-a380-5f18-919a-c9027da3da5f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The principal mechanism by which free radicals damage cell membranes is:', '["Lipid peroxidation of cell membranes","Protein synthesis stimulation","DNA repair enhancement","Increased glucose uptake","Glycogen synthesis"]'::jsonb, 'Lipid peroxidation of cell membranes', 'Free radicals initiate peroxidation of membrane polyunsaturated fatty acids, disrupting membrane integrity and function.'),
('1641aba0-599e-5552-81d4-ad668700f87a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'IL-10 exerts its anti-inflammatory effect chiefly by which action?', '["Suppressing macrophage and T-cell cytokine production","Activating the complement cascade","Stimulating neutrophil chemotaxis","Increasing vascular permeability","Promoting histamine release"]'::jsonb, 'Suppressing macrophage and T-cell cytokine production', 'IL-10 is an anti-inflammatory cytokine that inhibits cytokine production by macrophages and T cells.'),
('e243958c-7aba-5fae-a859-4cb9ba0b94b4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Liquefactive necrosis, with softening and cavitation, is the characteristic pattern produced by infarction of which organ?', '["Brain","Myocardium","Kidney","Liver","Skeletal muscle"]'::jsonb, 'Brain', 'The brain liquefies after ischemic necrosis because of its high content of hydrolytic enzymes and lipids, producing liquefactive necrosis.'),
('2af8e192-d6c6-5c06-812a-052234c6ae2b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which serum marker is the most specific and sensitive for myocardial infarction in the current era?', '["Troponin I","C-reactive protein","Gamma-glutamyl transferase","Alkaline phosphatase","Transferrin"]'::jsonb, 'Troponin I', 'Cardiac troponins are highly specific and sensitive markers of myocardial necrosis, rising within hours and remaining elevated for days.'),
('57a46b4a-96d5-53c1-bdcc-0a62f32cb12b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Restitution of skin and gastrointestinal epithelium after injury is possible because these epithelia consist of:', '["Labile, continuously dividing cells","Stable cells","Permanent cells","Terminally differentiated neurons","Resting G0 cells"]'::jsonb, 'Labile, continuously dividing cells', 'Labile cells (skin, GI mucosa, marrow) divide continuously and readily regenerate, allowing rapid restitution after injury.'),
('6db344f0-e4ac-5260-a9f7-9b18805f93d1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'H1-receptor-mediated endothelial contraction induced by histamine in early acute inflammation produces which effect?', '["Increased vascular permeability","Neutrophil chemotaxis","Complement activation","Type IV hypersensitivity","Macrophage activation"]'::jsonb, 'Increased vascular permeability', 'Histamine contracts endothelial cells, opening gaps at postcapillary venules and increasing vascular permeability.'),
('d8ee1e82-651d-5b3e-b47e-0eb09de9bd33'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Escape of plasma proteins from venules during acute inflammation reflects which change in the microvasculature?', '["Macrophage activation","Neutrophil chemotaxis","Type IV hypersensitivity","Increased vascular permeability","Complement activation"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability allows plasma proteins to escape through endothelial gaps, producing an exudate.'),
('f0c603bb-3ce6-5854-bd6f-847536e6cc4a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Epithelioid cell granulomas containing Langhans giant cells are the histologic hallmark of which type of inflammation?', '["Granulomatous inflammation","Suppurative inflammation","Serous inflammation","Fibrinous inflammation","Catarrhal inflammation"]'::jsonb, 'Granulomatous inflammation', 'Granulomatous inflammation is defined by epithelioid macrophage granulomas, often with Langhans giant cells.'),
('6b20ae5f-30b0-5102-bde2-0b5324b23a65'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Cervical squamous cell carcinoma is most strongly associated with which HPV types?', '["HPV types 16 and 18","HPV types 6 and 11","HPV types 1 and 2","HPV types 53 and 54","HPV types 40 and 42"]'::jsonb, 'HPV types 16 and 18', 'High-risk HPV genotypes 16 and 18 account for most cervical cancers; types 6 and 11 cause benign condylomas.'),
('c9eb52e5-8c5b-533f-88ab-b4f05771024b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Histologically, a keloid is composed predominantly of which material?', '["Dense collagen fibers","Elastin fibers","Adipose tissue","Smooth muscle","Cartilage"]'::jsonb, 'Dense collagen fibers', 'Keloids consist of broad, dense bands of collagen that extend beyond the original wound margins.'),
('ae7b3b40-1f60-52de-9a39-341a45e16970'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which laboratory technique detects the internucleosomal DNA fragmentation characteristic of apoptosis?', '["TUNEL assay","Gram stain","Ziehl-Neelsen stain","Perl Prussian blue stain","Periodic acid-Schiff stain"]'::jsonb, 'TUNEL assay', 'The TUNEL assay labels the free 3''-OH ends of fragmented DNA, identifying the DNA laddering of apoptotic cells.'),
('03a8f7b1-72d4-5a1b-93ac-f66edbfd3bed'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemical mediators diffusing from a focus of necrosis act principally on leukocytes to stimulate which function?', '["Neutrophil chemotaxis","Macrophage activation","Complement activation","Increased vascular permeability","Type IV hypersensitivity"]'::jsonb, 'Neutrophil chemotaxis', 'Chemoattractants from necrotic tissue recruit neutrophils by directional migration (chemotaxis).'),
('eec3946e-338f-5e2f-a07c-ee4936925f2b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A localized collection of pus within a newly formed cavity in tissue, such as a peritonsillar collection, is termed:', '["Abscess","Phlegmon","Empyema","Granuloma","Ulcer"]'::jsonb, 'Abscess', 'An abscess is a localized collection of pus (dead neutrophils and debris) within a tissue cavity formed by suppurative inflammation.'),
('73130530-2bbe-5492-b55d-b1374c505602'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Redness (rubor) and warmth (calor), cardinal signs of acute inflammation, are chiefly produced by which vascular event?', '["Vasodilation with increased blood flow","Increased vascular permeability","Fibrin deposition","Leukocyte emigration","Lymphatic obstruction"]'::jsonb, 'Vasodilation with increased blood flow', 'Vasodilation of arterioles increases blood flow, producing erythema and warmth; together with edema they give the cardinal signs of inflammation.'),
('8a9c4547-f65b-5049-932e-638b539de939'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A tuberculin-type reaction, peaking at 48-72 hours and mediated by sensitized T cells, is classified as which hypersensitivity?', '["Neutrophil chemotaxis","Complement activation","Type IV hypersensitivity","Increased vascular permeability","Macrophage activation"]'::jsonb, 'Type IV hypersensitivity', 'The tuberculin reaction is aT-cell-mediated delayed hypersensitivity (type IV) response.'),
('cdc84198-1443-525a-b8ed-8dd6039f4def'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which complement fragment is a potent chemoattractant for neutrophils?', '["C5a","C3b","C4a","C1q","iC3b"]'::jsonb, 'C5a', 'C5a is both an anaphylatoxin and a potent neutrophil chemoattractant; C3b is an opsonin and C3a/C4a are mainly anaphylatoxins.'),
('deb05455-f771-5297-a623-1f9c00dfa984'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which feature distinguishes the alternative complement pathway from the classical pathway?', '["It is activated directly on microbial surfaces without antibody","It requires C1q binding to antibody","It is initiated by mannose-binding lectin","It always requires antigen-antibody complexes","It only damages host cells"]'::jsonb, 'It is activated directly on microbial surfaces without antibody', 'The alternative pathway is activated by C3b deposition on microbial surfaces without a requirement for antibody.'),
('e4716da3-0672-51e2-8b00-6ce7dc1a4947'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The lectin pathway of complement differs from the classical pathway because it is initiated by:', '["Mannose-binding lectin recognizing microbial sugars without antibody","C1q requiring antibody accompanied by associated clinical symptoms","Spontaneous C3 hydrolysis mediated by specific receptor activation","Factor D cleavage without affecting the primary tissue pathway","Properdin stabilization alone leading to subsequent cellular adaptation"]'::jsonb, 'Mannose-binding lectin recognizing microbial sugars without antibody', 'Mannose-binding lectin (MBL) directly binds mannose residues on microbes, activating complement without antibody, unlike the classical pathway.'),
('affc8e0c-fa6e-5261-88f3-be829ce814a0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Delayed-type hypersensitivity, as exemplified by the contact sensitivity to poison ivy, is classified as which type?', '["Complement activation","Increased vascular permeability","Type IV hypersensitivity","Macrophage activation","Neutrophil chemotaxis"]'::jsonb, 'Type IV hypersensitivity', 'Poison ivy contact dermatitis is a classic T-cell-mediated delayed (type IV) hypersensitivity reaction.'),
('564b8e62-8677-5597-afbc-0dbd1e40689e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The tense fluid-filled blisters that form after a thermal burn are the result of which type of inflammation?', '["Serous inflammation","Fibrinous inflammation","Suppurative inflammation","Hemorrhagic inflammation","Necrotizing inflammation"]'::jsonb, 'Serous inflammation', 'Serous inflammation, marked by a watery, protein-poor effusion derived from plasma or serosal secretion, produces burn blisters.'),
('b629f42d-eda5-52e9-881f-010f1b16dcc2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hereditary angioedema resulting from C1 inhibitor deficiency is attributed to which pathogenetic mechanism?', '["Unregulated activation of classical complement and kinin systems","Defective C3 convertase","Excessive membrane attack complex formation","Loss of the alternative pathway only","Increased C4 levels"]'::jsonb, 'Unregulated activation of classical complement and kinin systems', 'C1 inhibitor deficiency leaves C1r/C1s and kallikrein unchecked, producing bradykinin and angioedema during attacks.'),
('167bcf27-96b8-53e1-918a-490681ae46b3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Opsonization, anaphylatoxin production and membrane attack complex formation are all functions of which cascade?', '["Macrophage activation","Increased vascular permeability","Type IV hypersensitivity","Neutrophil chemotaxis","Complement activation"]'::jsonb, 'Complement activation', 'Complement activation generates C3b (opsonin), C3a/C5a (anaphylatoxins) and C5b-9 (membrane attack complex).'),
('9d711a49-78ed-5420-bd14-116a4d54568d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Leukotriene B4 and bacterial formyl peptides, both chemoattractants, act primarily on which leukocyte process?', '["Increased vascular permeability","Macrophage activation","Complement activation","Type IV hypersensitivity","Neutrophil chemotaxis"]'::jsonb, 'Neutrophil chemotaxis', 'LTB4 and bacterial formyl peptides are potent chemoattractants directing neutrophil chemotaxis.'),
('9a6fa645-fe35-5e83-bf21-31c02aa787b7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Steatosis of hepatocytes is most commonly associated with which group of conditions?', '["Alcohol, obesity, diabetes, starvation","Infection accompanied by associated clinical symptoms","Autoimmune disease mediated by specific receptor activation","Trauma without affecting the primary tissue pathway","Neoplasia leading to subsequent cellular adaptation"]'::jsonb, 'Alcohol, obesity, diabetes, starvation', 'Alcohol, obesity, diabetes and starvation all disturb hepatic lipid handling, causing accumulation of triglycerides.'),
('8af4c691-5ff4-5897-9ae2-84d03b9c6d1b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The sprouting of new blood vessels in granulation tissue is accomplished chiefly by proliferation of which cell type?', '["Endothelial cells","Myofibroblasts","Keratinocytes","Platelets","Lymphocytes"]'::jsonb, 'Endothelial cells', 'Angiogenesis is driven by endothelial cell proliferation and migration, stimulated by VEGF.'),
('c4066d9f-178c-5540-88f0-6a55542615c2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The intrinsic (mitochondrial) pathway of apoptosis is triggered chiefly by which stimuli?', '["DNA damage and growth-factor/cytokine withdrawal","TNF binding to its receptor","Fas ligand binding to Fas","Perforin and granzyme release","Complement activation"]'::jsonb, 'DNA damage and growth-factor/cytokine withdrawal', 'The intrinsic pathway is initiated by intracellular insults such as DNA damage and lack of survival signals, releasing cytochrome c to activate caspase 9.'),
('3589d80d-0ae3-5af9-ad14-54e6f694a7ef'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The morphologic changes of apoptosis, including cell shrinkage and DNA fragmentation, are executed by which enzymes?', '["Executioner caspases 3 and 7","Initiator caspases 8 and 9","Inflammatory caspases 1 and 11","Caspase 2 and 5","Caspase 12 and 14"]'::jsonb, 'Executioner caspases 3 and 7', 'After activation by initiator caspases, executioner caspases 3 and 7 cleave substrates, producing the structural changes of apoptosis.'),
('0361269e-4ddb-5586-8be8-ad58279aa864'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Cardiac myocyte hypertrophy characteristically develops in response to which stimulus?', '["Increased mechanical workload (pressure overload)","Hormonal deficiency accompanied by associated clinical symptoms","Aging alone mediated by specific receptor activation","Viral infection without affecting the primary tissue pathway","Toxin exposure leading to subsequent cellular adaptation"]'::jsonb, 'Increased mechanical workload (pressure overload)', 'Hypertrophy is an adaptation to increased functional demand; in the heart, chronic pressure overload (e.g., hypertension) enlarges myocytes.'),
('2fa0a443-d3aa-5094-9e53-3d3f15e79468'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which type of hypersensitivity is cell-mediated and requires sensitized T lymphocytes rather than antibodies?', '["Increased vascular permeability","Complement activation","Type IV hypersensitivity","Macrophage activation","Neutrophil chemotaxis"]'::jsonb, 'Type IV hypersensitivity', 'Type IV hypersensitivity is mediated by T cells and activated macrophages, not by antibody.'),
('6a6abe39-105c-5159-8fc4-64dbb773d29e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The hallmark vascular event of acute inflammation that permits fluid and protein to enter tissues is:', '["Complement activation","Macrophage activation","Type IV hypersensitivity","Neutrophil chemotaxis","Increased vascular permeability"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability at postcapillary venules is the hallmark microvascular event of acute inflammation.'),
('d1478f78-55c9-58e6-9c81-7932768aeec1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemokines, a major class of small cytokines, principally function to:', '["Recruit and activate leukocytes (chemotaxis)","Fix complement accompanied by associated clinical symptoms","Release histamine mediated by specific receptor activation","Coagulate blood without affecting the primary tissue pathway","Carry oxygen leading to subsequent cellular adaptation"]'::jsonb, 'Recruit and activate leukocytes (chemotaxis)', 'Chemokines are chemoattractant cytokines that recruit and activate leukocytes at sites of inflammation.'),
('9ed23fee-84be-577c-804c-89621350cc45'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which anti-apoptotic protein is overexpressed in follicular lymphoma as a result of the t(14;18) translocation?', '["Bcl-2","Bax","Bak","Bad","Bid"]'::jsonb, 'Bcl-2', 't(14;18) places BCL-2 under the immunoglobulin heavy-chain promoter, leading to Bcl-2 overexpression and prolonged lymphocyte survival in follicular lymphoma.'),
('4fbc0fb4-d70e-5d21-abc1-ca0d7e2c4fff'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Tuberculous granulomas characteristically show which additional morphologic feature not seen in sarcoidosis?', '["Central caseous necrosis","Absence of necrosis","Touton giant cells","Asbestos bodies","Plasma cell cuffing only"]'::jsonb, 'Central caseous necrosis', 'Tuberculous granulomas typically have central caseous necrosis, whereas sarcoid granulomas are non-caseating.'),
('63bdd27d-540b-5455-809e-552fc4f1298b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Serotonin and histamine both contribute to which early vascular event of acute inflammation?', '["Increased vascular permeability","Leukocyte rolling","Phagocytosis","Opsonization","Complement lysis"]'::jsonb, 'Increased vascular permeability', 'Both vasoactive amines contract endothelial cells and increase vascular permeability in the Early phase of acute inflammation.'),
('a1097858-4cfe-535d-8659-b5c63e5dff3f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Increased vascular permeability in acute inflammation is mediated predominantly by contraction of which structures?', '["Endothelial cells of postcapillary venules","Arteriolar smooth muscle","Pericytes of capillaries","Venous valves","Lymphatic endothelium"]'::jsonb, 'Endothelial cells of postcapillary venules', 'Histamine and related mediators contract endothelial cells of postcapillary venules, opening interendothelial gaps.'),
('dc4e308e-eef3-54cd-830a-c59fb27c8a2f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which organism most commonly causes caseating granulomatous inflammation?', '["Mycobacterium tuberculosis","Streptococcus pyogenes","Escherichia coli","Staphylococcus aureus","Neisseria meningitidis"]'::jsonb, 'Mycobacterium tuberculosis', 'Mycobacterium tuberculosis is the classic cause of caseating granulomas (e.g., in the lungs).'),
('2fb80d7a-72c4-52ae-8bc7-5082aac8dc36'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The escape of protein-rich fluid into the interstitial space producing inflammatory edema is due to:', '["Macrophage activation","Type IV hypersensitivity","Complement activation","Increased vascular permeability","Neutrophil chemotaxis"]'::jsonb, 'Increased vascular permeability', 'Protein-rich fluid leaks from postcapillary venules through endothelial gaps because of increased vascular permeability.'),
('ea890955-7d62-5f3a-accd-d6403634e8c7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A gradient of chemoattractants at a focus of tissue injury elicits which effect on marginated neutrophils?', '["Neutrophil chemotaxis","Type IV hypersensitivity","Complement activation","Increased vascular permeability","Macrophage activation"]'::jsonb, 'Neutrophil chemotaxis', 'Chemoattractant gradients cause directional migration (chemotaxis) of neutrophils to the injury site.'),
('cc8b347e-14f9-5b2e-bd0b-edfd816c6358'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemotactic stimuli released from damaged tissue prompt which response in circulating leukocytes?', '["Macrophage activation","Type IV hypersensitivity","Complement activation","Increased vascular permeability","Neutrophil chemotaxis"]'::jsonb, 'Neutrophil chemotaxis', 'Leukocytes migrate toward chemical attractants released from damaged tissue, a process termed chemotaxis.'),
('8b46d40b-b1d0-5bc5-a9bf-6d5a370dea42'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Coating of microbes with C3b, which enhances their uptake by phagocytes, is an example of:', '["Opsonization","Chemotaxis","Anaphylaxis","Cytolysis","Agglutination"]'::jsonb, 'Opsonization', 'Opsonization is the coating of microbes with opsonins (C3b, IgG) that promotes recognition and phagocytosis.'),
('d83abe02-58ca-589e-8eef-f719754d40d0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which hypersensitivity reaction is mediated by sensitized T cells and is not dependent on antibodies?', '["Complement activation","Macrophage activation","Type IV hypersensitivity","Neutrophil chemotaxis","Increased vascular permeability"]'::jsonb, 'Type IV hypersensitivity', 'Type IV (delayed-type) hypersensitivity is mediated by T cells and activated macrophages rather than antibody.'),
('132a56b5-8e7a-5571-bf00-ce8c63c32222'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'IL-8 (CXCL8) chiefly functions as which type of mediator in acute inflammation?', '["Neutrophil chemoattractant","B-cell growth factor","Eosinophil growth factor","Antiviral cytokine","Mast cell growth factor"]'::jsonb, 'Neutrophil chemoattractant', 'IL-8 is the principal chemokine that recruits and activates neutrophils at sites of infection and inflammation.'),
('32f395a9-4a15-5b07-8c25-496c3a711866'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which hypersensitivity is responsible for granulomatous inflammation and renal/transplant rejection?', '["Macrophage activation","Neutrophil chemotaxis","Increased vascular permeability","Complement activation","Type IV hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Granulomas and graft rejection are immune reactions mediated by T cells, i.e., type IV hypersensitivity.'),
('9c235409-a146-5c65-8435-06fe30890530'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Vasoactive amines released early in acute inflammation act on postcapillary venules to produce:', '["Type IV hypersensitivity","Neutrophil chemotaxis","Complement activation","Macrophage activation","Increased vascular permeability"]'::jsonb, 'Increased vascular permeability', 'Early-released histamine and serotonin increase venular permeability through endothelial contraction.'),
('abcdabec-c275-5d42-8749-2474c0640819'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chronic elevation of IL-6 contributes to anemia of chronic disease chiefly by stimulating hepatic production of which peptide?', '["Hepcidin","Erythropoietin","Transferrin","Bilirubin","Ferritin only"]'::jsonb, 'Hepcidin', 'IL-6 stimulates hepatocytes to produce hepcidin, which traps iron in macrophages and reduces absorption, causing anemia of chronic disease.'),
('1af05110-b27c-599c-b434-81c84fd6dbd6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The acute phase response (fever, leukocytosis and hepatic protein synthesis) is triggered chiefly by which cytokines?', '["IL-1, IL-6 and TNF-alpha","IL-4, IL-5 and IL-13","C5a and C3a","Histamine and serotonin","Bradykinin and fibrinogen"]'::jsonb, 'IL-1, IL-6 and TNF-alpha', 'IL-1, IL-6 and TNF-α released by activated macrophages orchestrate fever, leukocytosis and acute-phase protein synthesis.'),
('5bdad1a8-88fa-5914-82d5-778dc2bb8cc8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Firm adhesion and transmigration of neutrophils across the endothelium are mediated chiefly by:', '["Integrins (LFA-1) binding to ICAM-1","Selectins binding to sialyl Lewis X","Cadherin homophilic binding","Mucin-receptor interactions","Fibrinogen receptor ligation"]'::jsonb, 'Integrins (LFA-1) binding to ICAM-1', 'Leukocyte integrins (LFA-1) bind endothelial ICAM-1 to achieve firm adhesion, which is required before diapedesis.'),
('6e8bcc1d-1ea0-51ba-97d0-21d4ed206852'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Formation of a stable collagen triple helix requires hydroxylation of which amino acids?', '["Proline and lysine","Glycine and alanine","Valine and leucine","Tyrosine and phenylalanine","Serine and threonine"]'::jsonb, 'Proline and lysine', 'Prolyl and lysyl hydroxylases modify proline and lysine residues, which is essential for stable collagen cross-linking.'),
('9e165b3e-4d45-5f11-be3d-2dca96fe49f4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The ''self-eating'' lysosomal pathway that recycles damaged organelles and sustains cells during stress is:', '["Self-eating process for recycling damaged organelles","Cell division accompanied by associated clinical symptoms","Cell growth mediated by specific receptor activation","Inflammation without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Self-eating process for recycling damaged organelles', 'Autophagy degrades and recycles damaged organelles via lysosomes, allowing cells to survive nutrient deprivation.'),
('1ff18234-d54f-5a53-9138-598c227b6603'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The earliest light-microscopic change of cell injury, seen as pale, vacuolated cytoplasm, is:', '["Cellular swelling (hydropic change)","Nuclear pyknosis","Fatty change","Apoptotic body formation","Glycogen depletion"]'::jsonb, 'Cellular swelling (hydropic change)', 'Cellular swelling is the earliest morphologic change of cell injury, with clear vacuolated cytoplasm due to water accumulation.'),
('54815e38-632d-562c-8556-162196623cef'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Lewy bodies are composed chiefly of which protein?', '["Alpha-synuclein","Beta-amyloid","Tau","TDP-43","Prion protein"]'::jsonb, 'Alpha-synuclein', 'Lewy bodies are aggregates of misfolded alpha-synuclein within dopaminergic neurons in Parkinson disease.'),
('7e4f759e-3d81-53e2-bb47-cb1255fc1c9d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Wound healing after surgery is delayed in patients with poorly controlled diabetes mainly because of:', '["Impaired neovascularization and increased infection","Excess vitamin C accompanied by associated clinical symptoms","Excess zinc intake mediated by specific receptor activation","Hypercoagulability without affecting the primary tissue pathway","Excess growth factor release leading to subsequent cellular adaptation"]'::jsonb, 'Impaired neovascularization and increased infection', 'Diabetes impairs angiogenesis and immune defenses, predisposing to infection and delaying wound repair.'),
('dab9c2c4-94f8-5ecc-884d-14c1a2b6ce7c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Tuberculin-type induration developing 48-72 hours after antigen injection is an example of which hypersensitivity?', '["Type IV hypersensitivity","Complement activation","Increased vascular permeability","Macrophage activation","Neutrophil chemotaxis"]'::jsonb, 'Type IV hypersensitivity', 'The delayed 48-72 hour T-cell-mediated response is characteristic of type IV (delayed-type) hypersensitivity.'),
('210b6f51-f072-5c33-ab95-7fc9e256b4d0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Barrett esophagus results from chronic injury to the lower esophagus by which agent?', '["Chronic gastroesophageal acid reflux","HPV infection accompanied by associated clinical symptoms","Helicobacter pylori mediated by specific receptor activation","Radiation without affecting the primary tissue pathway","Smoking alone leading to subsequent cellular adaptation"]'::jsonb, 'Chronic gastroesophageal acid reflux', 'Chronic reflux of gastric acid and bile injures the squamous mucosa, provoking columnar (intestinal) metaplasia.'),
('9fef9e6c-84d5-5fa6-8e58-d144a99b8026'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which proliferation is regarded as the immediate precursor of carcinoma in situ?', '["Severe dysplasia","Squamous metaplasia","Adenomatous hyperplasia","Lipofuscin accumulation","Granulation tissue"]'::jsonb, 'Severe dysplasia', 'Severe dysplasia involving the full epithelial thickness approximates carcinoma in situ, the immediate precursor of invasive cancer.'),
('d0faf2fc-a559-5f50-a8e6-9de9174661e2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'C5a possesses which combined roles in the inflammatory response?', '["Anaphylatoxin and chemoattractant","Opsonin only","Membrane attack component only","Convertase activity only","Anti-inflammatory mediator"]'::jsonb, 'Anaphylatoxin and chemoattractant', 'C5a is both a potent anaphylatoxin (mast cell degranulation, increased permeability) and a chemoattractant for neutrophils.'),
('485ddb90-32da-5654-aad7-9720e21eeeb2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The slow-reacting substance of anaphylaxis (SRS-A), which causes sustained bronchoconstriction in asthma, comprises which mediators?', '["Leukotrienes C4, D4 and E4","Prostaglandins and thromboxanes","Histamine only","Platelet-activating factor only","C3a and C5a"]'::jsonb, 'Leukotrienes C4, D4 and E4', 'LTC4, LTD4 and LTE4, synthesized from arachidonic acid via 5-lipoxygenase, constitute SRS-A and cause bronchoconstriction.'),
('6ddd4a48-de56-5c27-9f56-17e536b16cb4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Whether a tissue repairs by regeneration or by fibrosis is determined chiefly by:', '["The regenerative capacity of the tissue and the extent of ECM damage","Severity of pain accompanied by associated clinical symptoms","Patient gender mediated by specific receptor activation","Presence of fever without affecting the primary tissue pathway","Peripheral leukocyte count leading to subsequent cellular adaptation"]'::jsonb, 'The regenerative capacity of the tissue and the extent of ECM damage', 'Labile/stable tissues regenerate readily, but if the extracellular matrix scaffold is destroyed or the tissue is non-regenerating, fibrosis (scar) results.'),
('edb5d4bf-4efb-5366-a82b-964aaed82dfc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which class of drugs produces antipyretic and analgesic effects by inhibiting prostaglandin synthesis via cyclooxygenase inhibition?', '["NSAIDs","Corticosteroids","Antihistamines","Beta-blockers","Diuretics"]'::jsonb, 'NSAIDs', 'NSAIDs inhibit cyclooxygenase, blocking prostaglandin synthesis and thereby reducing fever and pain.'),
('41d2d5e6-8f4c-5377-b18e-5ec364ede121'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Transient endothelial cell contraction at the level of postcapillary venules is the mechanism of which early vascular response?', '["Macrophage activation","Increased vascular permeability","Complement activation","Type IV hypersensitivity","Neutrophil chemotaxis"]'::jsonb, 'Increased vascular permeability', 'Endothelial contraction opens interendothelial gaps at postcapillary venules, transiently increasing vascular permeability.'),
('ed9feba1-952a-54ba-9bd3-c4afdf3a09c8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Lipofuscin, the golden-brown ''wear-and-tear'' pigment, is derived from which process?', '["Peroxidation of unsaturated lipids within lysosomes","Bilirubin accumulation accompanied by associated clinical symptoms","Iron accumulation mediated by specific receptor activation","Melanin synthesis without affecting the primary tissue pathway","Carbon ingestion leading to subsequent cellular adaptation"]'::jsonb, 'Peroxidation of unsaturated lipids within lysosomes', 'Lipofuscin results from peroxidation of unsaturated membrane lipids and undigested material accumulating in lysosomes with aging.'),
('a0e995fe-8290-5eba-a7d5-4ee06038065d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Accumulation of triglycerides in hepatocytes in ethanol-induced liver injury results chiefly from:', '["An imbalance between lipid uptake, synthesis, utilization and export","Increased lysosomal autophagy accompanied by associated clinical symptoms","Decreased fatty acid synthesis mediated by specific receptor activation","Increased glucose transport without affecting the primary tissue pathway","Reduced apoptosis leading to subsequent cellular adaptation"]'::jsonb, 'An imbalance between lipid uptake, synthesis, utilization and export', 'Steatosis arises when lipid accumulation exceeds utilization/export; ethanol impairs fatty-acid oxidation and VLDL secretion.'),
('51d9f191-27ec-559a-97a3-19c23df8ab82'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Atrophy of an organ results from:', '["A decrease in cell size and/or number","An increase in cell number","An increase in cell size","A change of one cell type to another","Disordered proliferation"]'::jsonb, 'A decrease in cell size and/or number', 'Atrophy is a decrease in cell size and/or number leading to shrinkage of the organ.'),
('3dc70356-23b9-5909-a7c2-f43e7b743c08'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemical mediators diffusing from damaged tissue elicit which directional response in circulating leukocytes?', '["Increased vascular permeability","Type IV hypersensitivity","Macrophage activation","Complement activation","Neutrophil chemotaxis"]'::jsonb, 'Neutrophil chemotaxis', 'Chemical mediators from injured tissue form a gradient that directs neutrophil chemotaxis to the site.'),
('334e805a-3c48-5460-91bf-ad37375a461a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which leukocyte is the predominant cell recruited to the site in acute inflammation?', '["Neutrophils","Lymphocytes","Eosinophils","Plasma cells","Basophils"]'::jsonb, 'Neutrophils', 'Neutrophils are the dominant leukocytes in acute inflammatory exudates, arriving within hours in response to chemoattractants.'),
('bb97dc4e-4a23-5b14-96a2-da3e8f84e2e6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The classical, lectin and alternative complement pathways all converge at which step?', '["Complement activation","Macrophage activation","Neutrophil chemotaxis","Type IV hypersensitivity","Increased vascular permeability"]'::jsonb, 'Complement activation', 'All three pathways converge at C3 cleavage and assembly of C5b-9, i.e., activation of the complement effector system.'),
('f612fa93-6cc2-53f7-930f-38a8ba15f355'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemotactic factors attract neutrophils to the site of infection by stimulating directional movement, a process known as:', '["Increased vascular permeability","Complement activation","Neutrophil chemotaxis","Macrophage activation","Type IV hypersensitivity"]'::jsonb, 'Neutrophil chemotaxis', 'Chemotactic factors (e.g., C5a, LTB4, IL-8) recruit neutrophils by chemotaxis, their directional migration.'),
('3c82cc61-c755-50d9-9804-415359c29f36'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Plasma protein and fluid escape into tissues, causing inflammatory edema, as a result of which mechanism?', '["Type IV hypersensitivity","Complement activation","Macrophage activation","Increased vascular permeability","Neutrophil chemotaxis"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability at postcapillary venules underlies protein-rich exudation and inflammatory edema.'),
('9653c435-c854-570b-a249-6b9a3d269338'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A transudate characteristically has which composition?', '["Low protein and low cellular content","High protein and high cellular content","High fibrinogen with clotting","High lactic dehydrogenase","Milky chylous fluid"]'::jsonb, 'Low protein and low cellular content', 'Transudates are non-inflammatory fluids with low protein and low cell content, resulting from altered hydrostatic/oncotic pressures.'),
('75112b21-0977-5143-80d1-42263fed6d7f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Epithelioid cells and multinucleated giant cells within granulomas are derived from which precursor cell type?', '["Activated macrophages","Proliferating fibroblasts","Endothelial sprouts","Infiltrating lymphocytes","Circulating neutrophils"]'::jsonb, 'Activated macrophages', 'Activated macrophages transform into epithelioid cells and fuse to form multinucleated giant cells.'),
('055a879c-9f1b-54a7-9fde-015cde90eca8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A carcinoma that has breached the basement membrane and invaded the underlying stroma is termed:', '["Invasive carcinoma","Carcinoma in situ","Severe dysplasia","Benign tumor","Metastatic carcinoma"]'::jsonb, 'Invasive carcinoma', 'Once malignant epithelium invades through the basement membrane into stroma, the lesion is invasive carcinoma.'),
('66dbed81-834f-5088-b3a5-3fcb9b285ccd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Chemoattractants such as leukotriene B4 and bacterial formyl peptides principally direct which leukocyte process?', '["Complement activation","Type IV hypersensitivity","Neutrophil chemotaxis","Increased vascular permeability","Macrophage activation"]'::jsonb, 'Neutrophil chemotaxis', 'LTB4 and bacterial formyl peptides are chemoattractants that direct directional neutrophil migration.'),
('16996eb2-e762-5c3a-99ff-30d43f122a92'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hepatocyte apoptosis in chronic viral hepatitis is mediated predominantly by which pathway?', '["Fas-FasL (extrinsic death receptor) pathway","Intrinsic mitochondrial pathway","Perforin-granzyme release","Membrane attack complex","Autophagy"]'::jsonb, 'Fas-FasL (extrinsic death receptor) pathway', 'Cytotoxic T cells in chronic viral hepatitis kill hepatocytes largely through Fas-FasL engagement activating the extrinsic (caspase 8) pathway.'),
('ba809396-6aac-5fd3-8f4d-0b4831359121'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The membrane attack complex C5b-9 destroys target microbes by which mechanism?', '["Inserting into lipid bilayers to form transmembrane pores","Coating microbial surfaces","Stimulating phagocyte chemotaxis","Binding to Fc receptors","Accelerating C3 convertase"]'::jsonb, 'Inserting into lipid bilayers to form transmembrane pores', 'C5b-9 assembles into a transmembrane pore in the target membrane, causing osmotic lysis of the microbe.'),
('7ffcd331-b3cc-5460-bec5-3fb0b3691de5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Reperfusion of an ischemic tissue causes additional injury chiefly through which mechanism?', '["Generation of reactive oxygen species and inflammation","Suppression of complement accompanied by associated clinical symptoms","Reduced inflammation mediated by specific receptor activation","Increased ATP production without affecting the primary tissue pathway","Reduced calcium flux leading to subsequent cellular adaptation"]'::jsonb, 'Generation of reactive oxygen species and inflammation', 'Restoration of blood flow generates ROS and recruits neutrophils, paradoxically worsening the injury.'),
('efadab41-3fd7-5489-a2a0-4b8a5b5e28dc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Granuloma formation triggered by persistent intracellular organisms is classified as which type of hypersensitivity?', '["Type IV (cell-mediated)","Type I (anaphylactic)","Type II (cytotoxic)","Type III (immune complex)","Type V (stimulatory)"]'::jsonb, 'Type IV (cell-mediated)', 'Granulomas are a morphologic expression of type IV cell-mediated immunity against persistent intracellular pathogens.'),
('09057542-987c-522f-ad24-0796e3e1320c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which combination of conditions classically produces fatty liver (steatosis)?', '["Alcohol, obesity, diabetes, starvation","Infection accompanied by associated clinical symptoms","Autoimmune disease mediated by specific receptor activation","Trauma without affecting the primary tissue pathway","Neoplasia leading to subsequent cellular adaptation"]'::jsonb, 'Alcohol, obesity, diabetes, starvation', 'These conditions disturb hepatic lipid metabolism, producing accumulation of triglycerides in hepatocytes.'),
('7a6ba246-0f8a-58d2-8d71-c86dba6a9211'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Emigration of blood monocytes and their maturation into tissue phagocytes is central to which process?', '["Complement activation","Increased vascular permeability","Type IV hypersensitivity","Macrophage activation","Neutrophil chemotaxis"]'::jsonb, 'Macrophage activation', 'Monocytes leave the blood, differentiate into macrophages and become activated—a defining feature of chronic inflammation.'),
('3caf6f06-c59f-592b-9935-c8b0ce057a18'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which complement fragment together with leukotriene B4 are the most potent endogenous chemoattractants for neutrophils?', '["C5a and LTB4","C3b and C4b","IgG and IgA","PGE2 and PGI2","TXA2 and PGF2-alpha"]'::jsonb, 'C5a and LTB4', 'C5a and LTB4 are potent neutrophil chemoattractants (together with IL-8 and bacterial peptides).'),
('390e98aa-2061-51e5-b52a-0c3cde5df372'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The delayed induration of the tuberculin skin test and allergic contact dermatitis are both examples of which hypersensitivity?', '["Neutrophil chemotaxis","Type IV hypersensitivity","Macrophage activation","Increased vascular permeability","Complement activation"]'::jsonb, 'Type IV hypersensitivity', 'Both reactions are T-cell-mediated delayed hypersensitivity (type IV).'),
('f1b58e73-af70-5d97-9a7c-bc158355477a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which system, when activated, yields the opsonin C3b, the anaphylatoxin C5a and the lytic C5b-9 complex?', '["Complement activation","Type IV hypersensitivity","Increased vascular permeability","Neutrophil chemotaxis","Macrophage activation"]'::jsonb, 'Complement activation', 'Complement activation generates C3b, C5a and C5b-9, coupling opsonization, inflammation and microbial lysis.'),
('fc4e4469-4c07-5ab8-9e0e-303f6f314097'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which cells are the principal source of IFN-gamma, the key activator of macrophages?', '["Th1 cells and NK cells","B cells","Eosinophils","Basophils","Th2 cells"]'::jsonb, 'Th1 cells and NK cells', 'Th1 CD4+ cells and NK cells secrete IFN-γ, which activates macrophages for cell-mediated (granulomatous) immunity.'),
('5973899d-2eb9-5263-b2d1-8641c1e6ab27'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which form of membrane damage is the hallmark of free radical injury?', '["Lipid peroxidation of cell membranes","Protein synthesis stimulation","DNA repair enhancement","Increased glucose uptake","Glycogen synthesis"]'::jsonb, 'Lipid peroxidation of cell membranes', 'Free radicals attack polyunsaturated fatty acids in membranes, causing lipid peroxidation and membrane disruption.'),
('c1d0788e-a305-5ee5-941e-b1ecfd834f7d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Recurrent angioedema with a low serum C4 but normal C3, inherited as an autosomal dominant trait, is caused by deficiency of:', '["C1 inhibitor","C3","C5","Mannose-binding lectin","Factor H"]'::jsonb, 'C1 inhibitor', 'C1 inhibitor deficiency causes hereditary angioedema with characteristic low C4 (classical pathway consumption) and normal C3.'),
('ec585e4b-420a-59a3-a366-5c4061d2bbe3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Gas gangrene, a rapidly progressive necrotizing infection of muscle with gas formation, is caused by which organism?', '["Clostridium perfringens","Clostridium tetani","Clostridium botulinum","Streptococcus pyogenes","Escherichia coli"]'::jsonb, 'Clostridium perfringens', 'Clostridium perfringens produces toxins and gas (CO2/H2) causing myonecrosis, i.e., gas gangrene.'),
('c1bfde2f-615a-5e18-a3af-43824a850ba4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'During ischemia, which plasma membrane pump fails first, allowing sodium and water to enter the cell and cause swelling?', '["Mg2 ATPase","H+ pump","Proton pump","Ca2 ATPase","Na/K ATPase"]'::jsonb, 'Na/K ATPase', 'ATP depletion causes failure of the Na+/K+-ATPase, with influx of sodium and water producing cellular swelling.'),
('c21f8e70-ff28-5e36-a3a1-0c9c3cd669a7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The energy-dependent membrane pump whose failure produces cellular swelling in the early phase of cell injury is:', '["Mg2 ATPase","H+ pump","Proton pump","Ca2 ATPase","Na/K ATPase"]'::jsonb, 'Na/K ATPase', 'Failure of the plasma membrane Na+/K+-ATPase from reduced ATP allows sodium and water influx, the basis of hydropic swelling.'),
('5e179e56-5a53-5249-8f31-e0e9630e0d33'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Loss of aerobic ATP production in cell injury impairs which membrane pump, leading to cell swelling?', '["Mg2 ATPase","H+ pump","Proton pump","Ca2 ATPase","Na/K ATPase"]'::jsonb, 'Na/K ATPase', 'Reduced ATP fails the Na+/K+-ATPase so sodium accumulates intracellularly and water follows, causing swelling.'),
('7469803b-b84e-58e9-810e-8c92c48e695d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'The pump whose dysfunction is directly responsible for cellular (hydropic) swelling after hypoxic injury is:', '["Mg2 ATPase","H+ pump","Proton pump","Ca2 ATPase","Na/K ATPase"]'::jsonb, 'Na/K ATPase', 'Hypoxia depletes ATP and the membrane Na+/K+-ATPase fails, letting sodium and water into the cell (hydropic change).'),
('2eefddb3-64a0-5377-821b-22d4c5e75879'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which membrane pump, when it fails, permits intracellular sodium accumulation and water influx characteristic of reversible injury?', '["Mg2 ATPase","H+ pump","Proton pump","Ca2 ATPase","Na/K ATPase"]'::jsonb, 'Na/K ATPase', 'Failure of the Na+/K+-ATPase secondary to ATP depletion produces sodium and water influx and cellular swelling.'),
('bbc7f296-a6c9-5cdb-b062-2fb845cdae5a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Intracellular accumulation of which substance characterizes hydropic change in injured cells?', '["Water in the cytoplasm","Protein","Pigment","Lipid","Glycogen"]'::jsonb, 'Water in the cytoplasm', 'Hydropic change is the cytoplasmic accumulation of water following membrane pump failure.'),
('a4d9c37b-c842-5ee6-81d2-9916e96185e6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hydropic degeneration of cells following injury is a marker of accumulation of which material?', '["Water in the cytoplasm","Protein","Pigment","Lipid","Glycogen"]'::jsonb, 'Water in the cytoplasm', 'Hydropic degeneration is caused by accumulation of water (and sodium) in the cytoplasm.'),
('40d18eec-2a07-5382-97e8-dae5a78ec8a9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Clear, vacuolated cytoplasm in hydropic change results from entry of which substance into the cell?', '["Water in the cytoplasm","Protein","Pigment","Lipid","Glycogen"]'::jsonb, 'Water in the cytoplasm', 'Water entering the cell after sodium pump failure produces the clear cytoplasmic vacuoles of hydropic change.'),
('935dc91f-3f94-5367-90e5-baabbb3312ae'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which substance accumulates in the cytoplasm in the hydropic form of reversible cell injury?', '["Water in the cytoplasm","Protein","Pigment","Lipid","Glycogen"]'::jsonb, 'Water in the cytoplasm', 'Hydropic change is due to cytoplasmic water accumulation, seen as cells with pale, swollen cytoplasm.'),
('8a0fd7fb-121b-514f-b90b-149618d0e520'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Hydropic change results from the accumulation of which within the injured cell?', '["Water in the cytoplasm","Protein","Pigment","Lipid","Glycogen"]'::jsonb, 'Water in the cytoplasm', 'Hydropic change (cellular swelling) follows intracellular accumulation of water.'),
('a6b9ab22-0e41-50e7-974b-36cd7913d1f3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which lysosomal mechanism degrades and recycles damaged organelles, sustaining cells during nutrient deprivation?', '["Self-eating process for recycling damaged organelles","Cell division accompanied by associated clinical symptoms","Cell growth mediated by specific receptor activation","Inflammation without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Self-eating process for recycling damaged organelles', 'Autophagy is the lysosomal self-eating pathway that recycles organelles and macromolecules during starvation and stress.'),
('ef1fb18a-d6e1-5f8c-897b-16cf59cad99f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'A 70-year-old female presents with acute chest pain. Ischemic death of which organ is the most likely cause?', '["Adrenal","Spleen","Heart","Brain","Kidney"]'::jsonb, 'Heart', 'Acute chest pain with ischemic cell death most commonly reflects myocardial infarction, i.e., coagulative necrosis of the heart.'),
('553970e6-7eee-503a-a79e-492fb8df8dfa'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Ischemic infarction of which organ characteristically produces liquefactive necrosis?', '["Adrenal","Spleen","Heart","Brain","Kidney"]'::jsonb, 'Brain', 'The brain undergoes liquefactive necrosis after infarction because of its high content of hydrolytic enzymes and lipids.'),
('950619a7-ae53-599a-9f8a-421de7652802'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Recycling of damaged mitochondria and other organelles through lysosomes, a survival response to stress, is termed:', '["Self-eating process for recycling damaged organelles","Cell division accompanied by associated clinical symptoms","Cell growth mediated by specific receptor activation","Inflammation without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Self-eating process for recycling damaged organelles', 'Autophagy degrades and recycles damaged organelles via lysosomes, sustaining the cell during stress.'),
('e36dcdf8-e7d6-56f3-86cb-2b0f7528e5f5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - Cell Injury Inflammation', 'Which nuclear change, defined as complete dissolution of the nucleus, indicates irreversible cell death?', '["Karyolysis","Pyknosis","Karyorrhexis","Mitosis","Apoptosis"]'::jsonb, 'Karyolysis', 'Karyolysis is the dissolution of the nucleus by DNAse activity, one of the nuclear changes of necrosis; pyknosis is shrinkage and karyorrhexis is fragmentation.'),
('cdf79176-af0b-5064-860c-dbde303c2b54'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Complement deficiency predisposes to:', '["Neisseria infections (terminal complement deficiency)","Staphylococcal infections accompanied by associated clinical symptoms","Streptococcal infections mediated by specific receptor activation","Viral infections without affecting the primary tissue pathway","Fungal infections leading to subsequent cellular adaptation"]'::jsonb, 'Neisseria infections (terminal complement deficiency)', 'C5-C9 deficiency -> increased Neisseria susceptibility.'),
('6c10b161-921f-57e9-8584-d51b4b8a6cdb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A 25-year-old female with diabetes presents with stroke. What is the primary source of this pathology?', '["Diabetes","Obesity","Hypertension","Smoking","Hyperlipidemia"]'::jsonb, 'Hyperlipidemia', 'Hyperlipidemia is the definition or term that matches this concept.'),
('5deb3745-17cb-5c92-bcba-345d7d551756'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which lipoprotein is most atherogenic?', '["VLDL","IDL","LDL","HDL","Chylomicrons"]'::jsonb, 'LDL', 'LDL carries the bulk of cholesterol to the tissues; when oxidized it is taken up by arterial macrophages to form foam cells, which is why LDL is the most atherogenic lipoprotein.'),
('2a1a707f-7835-5ce3-b5e8-4c01a941d15f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A 40-year-old male with hyperlipidemia presents with stroke. Which anatomical region is most commonly implicated?', '["Macrophages","Lymphocytes","Endothelial cells","Platelets","Smooth muscle cells"]'::jsonb, 'Macrophages', 'Macrophages engulf oxidized LDL through scavenger receptors and transform into foam cells, the hallmark cell of the fatty streak and the atherosclerotic plaque.'),
('501c8c4a-6eda-58f0-87bf-6160495e5acf'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which component is NOT part of the fibrous plaque?', '["Collagen","Smooth muscle cells","Foam cells","Lipid core","Elastin"]'::jsonb, 'Lipid core', 'Lipid core is the exception because it does not share the feature common to the other options.'),
('c2227ac1-75ed-56f1-8b7f-27cf5458fcd7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The fibrous cap of an atheroma is composed mainly of:', '["Macrophages","Smooth muscle cells and collagen","Endothelial cells","Foam cells","T lymphocytes"]'::jsonb, 'Smooth muscle cells and collagen', 'The fibrous cap of an atheroma is composed mainly of Smooth muscle cells and collagen.'),
('3c4ade7a-d2b0-5c47-bcf2-adc3e6dc3bcc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Type II hypersensitivity is:', '["Antibody-mediated cytotoxic (IgG/IgG against cell surface antigens)","Immune complex-mediated accompanied by associated clinical symptoms","IgE-mediated mediated by specific receptor activation","T cell-mediated without affecting the primary tissue pathway","None of the above leading to subsequent cellular adaptation"]'::jsonb, 'Antibody-mediated cytotoxic (IgG/IgG against cell surface antigens)', 'IgG/IgM against cell surface or matrix antigens.'),
('e1dfb5b0-d84d-54ef-aee5-53899cbfad3c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common site for atherosclerotic aneurysm is:', '["Thoracic aorta","Renal arteries","Cerebral arteries","Abdominal aorta","Coronary arteries"]'::jsonb, 'Abdominal aorta', 'The most common site for atherosclerotic aneurysm is Abdominal aorta.'),
('55363975-7c1d-5af6-af23-16af71453afb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Cystic medial degeneration, the essential lesion of many aortic dissections, is confined to which layer of the arterial wall?', '["Tunica media","Capillaries","All layers","Tunica adventitia","Tunica intima"]'::jsonb, 'Tunica media', 'The tunica media is the middle muscular coat of the artery; cystic medial degeneration and Monckeberg medial calcific sclerosis both involve this layer, weakening it and predisposing to dissection or calcification.'),
('ed9cd30d-aa9a-5664-b13b-d502f6d514d8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is a complication of atherosclerosis?', '["All","Hemorrhage","Aneurysm","Embolism","Thrombosis"]'::jsonb, 'All', 'Complicated atherosclerotic plaques may ulcerate, hemorrhage, calcify and thrombose, and these events can produce aneurysm, embolism and thrombosis - all recognized complications.'),
('208abd42-303a-5c8b-9c29-67340aca7ae4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which alteration is regarded as the initiating event in atherogenesis?', '["Platelet aggregation","Monocyte infiltration","Lipid accumulation","Endothelial dysfunction","Smooth muscle proliferation"]'::jsonb, 'Endothelial dysfunction', 'Endothelial injury or dysfunction is the first step that permits LDL entry, monocyte adhesion and platelet interaction, thereby launching the entire atherogenic cascade.'),
('a15e9354-04d6-502e-961d-931b92bbd9c3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Rb gene (retinoblastoma) encodes:', '["A tumour suppressor (regulates E2F transcription factors)","An oncogene accompanied by associated clinical symptoms","A growth factor mediated by specific receptor activation","A signalling protein without affecting the primary tissue pathway","A structural protein leading to subsequent cellular adaptation"]'::jsonb, 'A tumour suppressor (regulates E2F transcription factors)', 'Rb phosphorylation releases E2F, promoting S phase entry.'),
('657171e3-1412-5d31-b534-7b958c23593f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Oxidized LDL is taken up by macrophages via:', '["VLDL receptor","LDL receptor","Scavenger receptor","Complement receptor","Fc receptor"]'::jsonb, 'Scavenger receptor', 'Oxidized LDL is taken up by macrophages via Scavenger receptor.'),
('6330d4ff-da19-54d9-b108-25b08442894d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which growth factor stimulates smooth muscle cell proliferation in atheroma?', '["TGF-beta","VEGF","FGF","EGF","PDGF"]'::jsonb, 'PDGF', 'Platelet-derived growth factor, released mainly by platelets and macrophages, is the principal mitogen driving smooth muscle cell migration and proliferation within the atheroma.'),
('83c8031a-e108-54db-aac6-ca30cd1ce78a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common cause of death from atherosclerosis is:', '["MI","Peripheral gangrene","Stroke","Renal failure","Aneurysm rupture"]'::jsonb, 'MI', 'The most common cause of death from atherosclerosis is MI.'),
('cf093d48-b0b9-578f-94ef-99caec849678'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is the strongest predictor of cardiovascular risk?', '["Triglycerides","LDL/HDL ratio","LDL","Total cholesterol","HDL"]'::jsonb, 'LDL/HDL ratio', 'The LDL/HDL ratio expresses the balance between atherogenic and protective cholesterol fractions and correlates more strongly with cardiovascular risk than total cholesterol or either fraction alone.'),
('d77d1117-9f31-5657-bbd9-b7401186e37a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Lipoprotein(a) is an independent risk factor because it:', '["Increases HDL","Increases LDL","Inhibits fibrinolysis","Promotes vasodilation","Decreases VLDL"]'::jsonb, 'Inhibits fibrinolysis', 'Lipoprotein(a) is an independent risk factor because it Inhibits fibrinolysis.'),
('1af58bb4-77a7-596a-a869-edec84e3df44'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Atherosclerotic plaques most commonly occur at:', '["Lymphatics","Straight segments of arteries","Capillaries","Veins","Branch points"]'::jsonb, 'Branch points', 'Low and turbulent shear stress at arterial branch points and bifurcations injures the endothelium, so these sites are where atherosclerotic plaques preferentially develop.'),
('2363218d-3261-5b8c-bfc9-58562086a4eb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'p53 gene encodes:', '["A tumour suppressor protein (guardian of the genome)","An oncogene accompanied by associated clinical symptoms","A growth factor receptor mediated by specific receptor activation","A DNA repair enzyme without affecting the primary tissue pathway","A cell cycle promoter leading to subsequent cellular adaptation"]'::jsonb, 'A tumour suppressor protein (guardian of the genome)', 'p53 induces apoptosis and cell cycle arrest in response to DNA damage.'),
('f706408f-c8a1-55a5-971e-5fc7d4ed6e24'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The lipid core of an atheroma contains:', '["Phospholipids","All","Foam cells","Necrotic debris","Cholesterol crystals"]'::jsonb, 'All', 'The lipid core of an atheroma is composed of extracellular cholesterol and cholesterol crystals, phospholipids, necrotic debris and lipid-laden foam cells together.'),
('a6153662-47fe-53c3-8b74-5bca7b503173'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which is a feature of the complicated plaque?', '["Ulceration","Hemorrhage","Calcification","All","Thrombosis"]'::jsonb, 'All', 'An advanced plaque is called complicated when it ulcerates, hemorrhages, calcifies or becomes thrombosed; these changes underlie acute ischemic events.'),
('ea074e8f-691b-539f-ab2e-e96cd2af8096'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Extrinsic apoptosis pathway is triggered by:', '["Death receptor ligation (Fas, TNF-R1)","Mitochondrial damage accompanied by associated clinical symptoms","DNA damage mediated by specific receptor activation","Hypoxia without affecting the primary tissue pathway","ER stress leading to subsequent cellular adaptation"]'::jsonb, 'Death receptor ligation (Fas, TNF-R1)', 'FasL/Fas or TNF/TNF-R1 activates caspase-8.'),
('28e29e1a-9f91-5707-88c6-08a071bc9d13'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Amyloid is characterised by:', '["Beta-pleated sheet protein aggregation","Alpha-helical protein aggregation","Lipid accumulation","Glycogen accumulation","Calcium deposits"]'::jsonb, 'Beta-pleated sheet protein aggregation', 'Misfolded proteins forming insoluble fibrils.'),
('7140c82a-2ffd-59d6-8a1a-68dfd6a4cc4d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Cholesterol embolism typically arises from:', '["Coronary arteries","Renal veins","Pulmonary arteries","Carotid arteries","Aorta"]'::jsonb, 'Aorta', 'Cholesterol atheroemboli are shed from disrupted ulcerated plaques, and the aorta, as the largest plaque-bearing vessel, is the most frequent source.'),
('383892bc-e32f-5b8e-8015-1af19aea743b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The earliest microscopic change in atherosclerosis is:', '["Necrosis","Ulceration","Fibrous cap formation","Calcification","Foam cell accumulation"]'::jsonb, 'Foam cell accumulation', 'The earliest microscopic change in atherosclerosis is Foam cell accumulation.'),
('9324486f-7e79-5ffd-8b3b-f0186f7d62af'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which cytokine is pro-atherogenic?', '["TGF-beta","IL-4","IL-6","IL-10","IL-13"]'::jsonb, 'IL-6', 'IL-6 is a pro-inflammatory cytokine that amplifies endothelial activation, leukocyte recruitment and the hepatic acute-phase response, promoting atherosclerotic progression.'),
('2706f21a-f368-5ed5-a688-b291b6fa7995'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Shear stress protects against atherosclerosis by:', '["Promoting thrombosis","Increasing LDL uptake","Reducing HDL","Increasing NO production","Activating platelets"]'::jsonb, 'Increasing NO production', 'Laminar shear stress upregulates endothelial nitric oxide synthase; the NO released relaxes the vessel wall and inhibits platelet adhesion, leukocyte adhesion and smooth muscle growth.'),
('de8d4844-1932-57ec-9642-ef667888c8c2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which lesion is considered an advanced or type IV lesion?', '["Atheroma","Fibroatheroma","Fibrous plaque","Fatty streak","Complicated plaque"]'::jsonb, 'Atheroma', 'The atheroma, with its established lipid core, is the type IV (advanced) lesion; fatty streaks are early lesions and fibrous plaques are later, fibrotic stages.'),
('ddf22c4e-60a0-5280-afe4-a4ec6222c0dd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Neoplasia: most commonly mutated TSG in sporadic CRC:', '["APC","RB","p53","BRCA1","WT1"]'::jsonb, 'APC', 'Mutated in 80% of sporadic CRC, initiates adenoma-carcinoma sequence.'),
('f1b5eb6f-4755-5699-a19c-7cd13236b970'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common cause of renovascular hypertension is:', '["Fibromuscular dysplasia","Atherosclerosis","Takayasu arteritis","Polyarteritis nodosa","Aortic dissection"]'::jsonb, 'Atherosclerosis', 'The most common cause of renovascular hypertension is Atherosclerosis.'),
('adb5048d-df91-5f4e-91a3-c1061a8e4646'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'BRCA1/2 mutations increase risk of:', '["Breast and ovarian cancer","Lung cancer","Colon cancer","Prostate cancer","Leukaemia"]'::jsonb, 'Breast and ovarian cancer', 'Hereditary breast-ovarian cancer syndrome.'),
('9b13febe-1f13-54f4-83cf-234baba04368'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which type of myocardial infarction is transmural?', '["Focal necrosis","Subendocardial","NSTEMI","Non-Q wave","STEMI"]'::jsonb, 'STEMI', 'STEMI follows total occlusion of a large epicardial coronary artery and produces full-thickness (transmural) necrosis; subendocardial and non-Q-wave infarcts spare the outer ventricular wall.'),
('157eec61-6c03-5940-bdd7-7a851d191243'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which coronary artery is most commonly occluded in MI?', '["LCX","RCA","Posterior descending","LAD","Left main"]'::jsonb, 'LAD', 'The left anterior descending artery supplies the anterior left ventricular wall and the septum and is the coronary vessel most frequently occluded in myocardial infarction.'),
('85c76f7c-326a-571f-9a79-eae53d5b4266'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'CK-MB peaks after MI at:', '["48-72 hours","4-6 hours","12-24 hours","5-7 days","24-36 hours"]'::jsonb, '12-24 hours', 'After acute MI, CK-MB begins to rise in 3-6 hours, reaches its peak at 12-24 hours and returns to normal by 48-72 hours.'),
('c6d92153-0ce9-5257-b378-bba730a79801'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Serum CK-MB first becomes measurable above its normal range at approximately what time after the onset of acute myocardial infarction?', '["4-6 hours","12-24 hours","2-4 hours","6-12 hours","1-2 hours"]'::jsonb, '4-6 hours', 'CK-MB leaks from necrotic myocytes early in infarction; it is detectable from about 4-6 hours and peaks at 12-24 hours.'),
('85c6334d-e7c8-5dd3-8100-f0af5efa2eb8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which serum biomarker is the most cardiospecific and is the investigation of choice for confirming acute myocardial infarction?', '["LDH","Troponin I","AST","Myoglobin","CK-MB"]'::jsonb, 'Troponin I', 'Cardiac troponin is released only from injured myocardial cells, giving it superior specificity, and it is now the preferred diagnostic marker for myocyte necrosis.'),
('f823f04a-4f05-5aaf-bef2-7b8f0cd22ad4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Coagulative necrosis of the heart after MI is replaced by fibrosis at:', '["6 months","1 week","2-3 weeks","4-6 weeks","8-12 weeks"]'::jsonb, '4-6 weeks', 'Coagulative necrosis of the heart after MI is replaced by fibrosis at 4-6 weeks.'),
('3a6753ac-f724-51f9-84a4-2577c6d58c60'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which complication of MI is most common?', '["Pericarditis","Cardiac rupture","Heart failure","Ventricular aneurysm","Arrhythmia"]'::jsonb, 'Arrhythmia', 'Arrhythmia is the association with the highest frequency in this setting.'),
('9c77855d-1923-5498-9c28-dee21cca4448'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is an immune-mediated complication developing weeks to months after myocardial infarction, with fever and pericardial pain?', '["Cardiac rupture","Autoimmune pericarditis","Septal rupture","Ventricular aneurysm","Papillary muscle rupture"]'::jsonb, 'Autoimmune pericarditis', 'Dressler syndrome is the post-infarction autoimmune pericarditis that appears weeks to months after MI, in contrast to the earlier purely mechanical complications.'),
('ba595b91-c780-5e04-b41b-af770b5bafd8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Papillary muscle rupture after MI most commonly affects:', '["Mitral valve","All","Pulmonary valve","Tricuspid valve","Aortic valve"]'::jsonb, 'Mitral valve', 'The posteromedial papillary muscle, which has a single coronary blood supply, ruptures most often, and its failure produces acute severe mitral regurgitation.'),
('d5e652f2-272d-5f4f-af0d-f2d34070ea42'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Thromboembolic complications that may develop after acute myocardial infarction, particularly from a left ventricular mural thrombus, include:', '["Pulmonary embolism","Renal infarction","Systemic embolism","Stroke","All"]'::jsonb, 'All', 'A left ventricular mural thrombus can embolize to the brain, kidneys and other systemic sites, while prolonged immobility predisposes to pulmonary embolism; all are potential complications of MI.'),
('ef26005c-fd8c-5a2d-b398-2a22f8e4a5ed'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Ventricular free wall rupture after MI occurs most often at:', '["3-7 days","2-4 weeks",">1 month","7-14 days","1-3 days"]'::jsonb, '3-7 days', 'Left ventricular free-wall rupture characteristically occurs 3-7 days after infarction, when the necrotic wall is softened by lytic neutrophils before fibrous scar has formed.'),
('64f8c1d0-ddbd-5272-a2a6-dbf8c2bbd863'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which anginal pattern features predictable chest pain brought on by exertion and promptly relieved by rest or sublingual nitroglycerin?', '["Silent ischemia","Prinzmetal angina","Microvascular angina","Stable angina","Unstable angina"]'::jsonb, 'Stable angina', 'Stable angina results from a fixed atherosclerotic stenosis that restricts coronary flow only when myocardial demand rises; the pain is reproducible with effort and resolves at rest.'),
('ef3615fc-76c6-56a7-a98c-d8268793834c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Unstable angina is characterized by:', '["Coronary spasm resulting in decreased functional activity","Plaque rupture with non-occlusive thrombus","Complete occlusion mediated by specific receptor activation","Microvascular disease without affecting the primary tissue pathway","Normal coronaries leading to subsequent cellular adaptation"]'::jsonb, 'Plaque rupture with non-occlusive thrombus', 'Unstable angina is characterized by Plaque rupture with non-occlusive thrombus.'),
('c4b5171f-aad6-5204-a318-21af02157e25'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Prinzmetal (variant) angina is due to:', '["Vasculitis","Plaque rupture","Coronary artery spasm","Fixed stenosis","Embolism"]'::jsonb, 'Coronary artery spasm', 'Prinzmetal (variant) angina is due to Coronary artery spasm.'),
('dbcc5c7e-8e83-596e-ac12-8b85c864719e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which ECG finding is characteristic of transmural MI?', '["Pathologic Q waves","ST elevation","T wave inversion","ST depression","Peaked T waves"]'::jsonb, 'ST elevation', 'Acute transmural ischemia produces ST-segment elevation, the electrocardiographic hallmark of STEMI, as injured epicardial muscle alters the current of injury.'),
('5670add4-afee-5f91-89bc-9f185209745f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The ''wavefront phenomenon'' of MI refers to:', '["Reversible injury only","Alternating bands of necrosis","Necrosis spreading from subendocardium to epicardium","Multiple small infarcts","Necrosis spreading from epicardium to subendocardium"]'::jsonb, 'Necrosis spreading from subendocardium to epicardium', 'The ''wavefront phenomenon'' of MI refers to Necrosis spreading from subendocardium to epicardium.'),
('17a35c64-7cb2-5f98-b8b0-62969ac9960a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Rupture of the cardiac free wall after transmural infarction most commonly involves which structure?', '["Right ventricle free wall","Atria","Interventricular septum","Left ventricle free wall","Papillary muscle"]'::jsonb, 'Left ventricle free wall', 'Free-wall rupture is a key fatal mechanical complication of MI and almost always involves the free wall of the left ventricle, the chamber bearing the highest systolic wall stress.'),
('1bd0bce1-52b3-584d-a159-a9eff175e6dc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A 30-year-old male with hypertension presents with sudden severe back pain. Imaging reveals an aortic aneurysm. Which etiological factor is primarily responsible?', '["Early reperfusion","Pericarditis","Scar thinning","Cardiac rupture","Arrhythmia"]'::jsonb, 'Scar thinning', 'A ventricular aneurysm forms when infarcted myocardium is replaced by a thin fibrous scar that bulges outward under systolic pressure; progressive scar thinning is the primary mechanism.'),
('9f2631d9-fe18-5072-b134-a0f93f92b30c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which complication of acute myocardial infarction abruptly destroys the subvalvular support of the mitral apparatus and causes acute severe regurgitation?', '["Leaflet perforation","Papillary muscle rupture","Annular dilation","Chordae rupture","All"]'::jsonb, 'Papillary muscle rupture', 'Rupture of the infarcted posteromedial papillary muscle uncouples the mitral valve apparatus, producing sudden, severe mitral regurgitation with pulmonary edema.'),
('570210ee-9518-5a48-9493-960084336c54'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which test is best for diagnosing myocardial viability?', '["PET scan","Troponin","ECG","Echocardiography","CK-MB"]'::jsonb, 'PET scan', 'PET with fluorodeoxyglucose shows metabolically active but dysfunctional myocytes, so it is the best non-invasive method for distinguishing viable from non-viable (scarred) myocardium.'),
('32f10841-de2b-5941-a5e5-dd97ba338eff'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which term best describes the prolonged myocardial contractile failure that follows transient ischemia but is fully reversible once coronary blood flow is restored?', '["Myocardial fibrosis","Stunned myocardium","Irreversible necrosis","Reversible contractile dysfunction","Acute ischemia"]'::jsonb, 'Reversible contractile dysfunction', 'This is reversible contractile dysfunction: the myocytes remain viable (as in stunned or hibernating myocardium), so contractile function returns completely after revascularization.'),
('d332493c-1129-5540-a39b-dea201f4e5f0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Stunned myocardium recovers after:', '["Digitalis","Beta-blockers","Revascularization","Prolonged bed rest","Antiplatelet therapy"]'::jsonb, 'Revascularization', 'Stunned myocardium is viable; restoring coronary blood flow through revascularization re-establishes contractile function completely.'),
('29ee84fa-5b5b-5f54-b71f-33ba777d47c7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which is a late complication of MI?', '["Papillary muscle rupture","Ventricular aneurysm","Cardiac rupture","Dressler syndrome","Arrhythmia"]'::jsonb, 'Ventricular aneurysm', 'A ventricular aneurysm appears weeks to months after infarction, when the healed scar thins and bulges outward, making it a late complication.'),
('d3846c7e-f8a6-5fe7-a6f0-7b1abd84ae42'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which cardiac biomarker combines the highest sensitivity and specificity for detecting minor as well as major myocardial necrosis?', '["Myoglobin","AST","LDH","CK-MB","Troponin"]'::jsonb, 'Troponin', 'Cardiac troponin rises within hours, stays elevated for days and is the most sensitive and specific marker of myocyte necrosis, making it the standard biomarker.'),
('892bb9c8-45d3-5da2-b724-e8e44886a22e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Myocardial ischemia lasting 20-40 minutes causes:', '["Apoptosis","Irreversible injury","Reversible injury","Necrosis","Fibrosis"]'::jsonb, 'Reversible injury', 'Ischemia of up to about 20-40 minutes causes reversible injury; beyond that duration, ATP depletion and membrane damage become irreversible and myocytes undergo necrosis.'),
('0767b79b-41d7-57cf-9075-62c33d98528a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which enzyme is most sensitive early after MI (2-4 hours)?', '["AST","LDH","Myoglobin","CK-MB","Troponin"]'::jsonb, 'Myoglobin', 'Myoglobin leaks from damaged muscle within 1-2 hours of infarction, making it the most sensitive early marker, although it lacks cardiac specificity.'),
('3b15a038-7f0c-55c0-a909-4bd45c57313c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Hypoxia-inducible factor (HIF-1alpha) is stabilised by:', '["Hypoxia (low oxygen conditions)","Normoxia accompanied by associated clinical symptoms","Hyperoxia mediated by specific receptor activation","Acidosis without affecting the primary tissue pathway","Alkalosis leading to subsequent cellular adaptation"]'::jsonb, 'Hypoxia (low oxygen conditions)', 'HIF-1alpha stabilised in low O2, promotes angiogenesis (VEGF).'),
('85aee8cc-4fe2-5b3a-8fcc-8c04e648bb44'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Reperfusion injury after MI is mediated by:', '["Free radicals","Complement activation","Neutrophil infiltration","All","Calcium overload"]'::jsonb, 'All', 'Reperfusion injury after MI is mediated by All.'),
('edc5e190-257c-5a2d-bd0c-5df6edafed34'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'No-reflow phenomenon after MI is due to:', '["Embolism","Plaque rupture","Coronary spasm","Thrombosis","Microvascular obstruction"]'::jsonb, 'Microvascular obstruction', 'No-reflow phenomenon after MI is due to Microvascular obstruction.'),
('51a12583-07a4-5c14-8d22-1db09ab1544b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Apoptosis (intrinsic pathway) is initiated by:', '["Mitochondrial outer membrane permeabilisation (MOMP)","Death receptor ligation accompanied by associated clinical symptoms","Complement activation mediated by specific receptor activation","Neutrophil degranulation without affecting the primary tissue pathway","Platelet aggregation leading to subsequent cellular adaptation"]'::jsonb, 'Mitochondrial outer membrane permeabilisation (MOMP)', 'Cytochrome c release activates caspase-9.'),
('b3d1b5e4-aa6d-5221-96d1-ea76f24f3161'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which coagulation factor is deficient in hemophilia B (Christmas disease)?', '["Factor XII","Factor XI","Factor X","Factor VIII","Factor IX"]'::jsonb, 'Factor IX', 'Hemophilia B is an X-linked disorder caused by deficiency of factor IX, whereas hemophilia A reflects deficiency of factor VIII.'),
('9c2baad6-56d2-5ee6-b041-bdb872b38a60'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Hemophilia A and hemophilia B are both transmitted by which pattern of inheritance?', '["Mitochondrial","Autosomal dominant","X-linked dominant","X-linked recessive","Autosomal recessive"]'::jsonb, 'X-linked recessive', 'The genes for factor VIII and factor IX are located on the X chromosome, so both hemophilias are inherited as X-linked recessive traits that predominantly affect males.'),
('a78b8117-eee7-5cfc-81c9-c823b40c9627'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which lab finding is characteristic of hemophilia A?', '["Prolonged PT","Prolonged aPTT","Low platelet count","Low fibrinogen","Prolonged bleeding time"]'::jsonb, 'Prolonged aPTT', 'Factor VIII deficiency impairs the intrinsic coagulation pathway, so hemophilia A characteristically prolongs the aPTT while the prothrombin time, platelet count and fibrinogen remain normal.'),
('e1c127d5-870c-5b7a-b421-b85090d8fa8b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The mainstay of treatment for hemophilia A is:', '["Fresh frozen plasma","Platelet transfusion","Factor VIII concentrate","Desmopressin","Cryoprecipitate"]'::jsonb, 'Factor VIII concentrate', 'The mainstay of treatment for hemophilia A is Factor VIII concentrate.'),
('108d9fcd-0519-57a4-bc6d-aea9607a7fe4'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A male with a bleeding disorder has mildly reduced factor VIII activity and bleeds mainly after dental extraction or surgery. Which diagnosis is most likely?', '["von Willebrand disease type 3","Mild hemophilia A","Hemophilia B","Severe hemophilia A","Hemophilia A with inhibitors"]'::jsonb, 'Mild hemophilia A', 'Mild hemophilia A retains 5-40% of normal factor VIII activity, so spontaneous bleeding does not occur and hemorrhage follows only trauma, surgery or dental procedures.'),
('0fa020b7-a6e9-51b2-a0f9-605bb6d76cff'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Inhibitors (antibodies) against factor VIII develop in hemophilia A patients:', '["Always","In up to 30%","In 100%","Only in acquired hemophilia","Rarely"]'::jsonb, 'In up to 30%', 'Neutralizing antibodies against factor VIII (inhibitors) develop in up to about 30% of patients with severe hemophilia A, usually after repeated factor replacement.'),
('524dedf9-237c-5bfa-bd7f-a242a10b80c1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'von Willebrand disease is due to:', '["Deficiency of vWF","Deficiency of factor IX","Deficiency of factor XI","Deficiency of factor VIII","Platelet defect"]'::jsonb, 'Deficiency of vWF', 'von Willebrand disease is due to Deficiency of vWF.'),
('44e98b0d-ed96-5e86-adf6-593e56bda0a9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which lab finding is MOST characteristic of von Willebrand disease?', '["Low platelet count","Prolonged aPTT","Prolonged PT","Prolonged bleeding time","Low factor VIII"]'::jsonb, 'Prolonged bleeding time', 'von Willebrand factor is required for platelet adhesion to exposed subendothelium, so its deficiency primarily prolongs the bleeding time; platelet count and prothrombin time remain normal.'),
('d615e230-a90b-5e2a-9d22-ee70cab88cb1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common type of von Willebrand disease is:', '["Type 1","Type 2A","Type 3","Type 2B","Type 2M"]'::jsonb, 'Type 1', 'The most common type of von Willebrand disease is Type 1.'),
('8276eab8-223b-5c97-936f-d642983f9e05'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Type 2B von Willebrand disease is characterized by:', '["Increased platelet binding","Normal multimers","Decreased synthesis","Loss of high molecular weight multimers","Absent vWF"]'::jsonb, 'Increased platelet binding', 'Type 2B von Willebrand disease is characterized by Increased platelet binding.'),
('6cb894a2-0572-56cd-8911-3be3182f98ca'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Type 3 von Willebrand disease is:', '["Acquired","Moderate","Only in females","Mild","Severe with absent vWF"]'::jsonb, 'Severe with absent vWF', 'Type 3 von Willebrand disease is Severe with absent vWF.'),
('931ca013-3208-51d5-aed8-eefe70b17127'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which test differentiates vWD from hemophilia A?', '["PT","Ristocetin cofactor assay","Bleeding time","Platelet count","Fibrinogen"]'::jsonb, 'Ristocetin cofactor assay', 'The ristocetin cofactor assay measures the functional activity of von Willebrand factor in supporting platelet aggregation; it is reduced in von Willebrand disease but normal in hemophilia A.'),
('be21070e-ce2b-5bf1-9c34-00606bef1142'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The inheritance of von Willebrand disease is:', '["X-linked dominant","Autosomal recessive","X-linked recessive","Mitochondrial","Autosomal dominant"]'::jsonb, 'Autosomal dominant', 'The inheritance of von Willebrand disease is Autosomal dominant.'),
('cc714632-0406-5267-8c92-3f230ef9fc38'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Immune thrombocytopenic purpura (ITP) is characterized by:', '["Marrow failure","Anti-platelet antibodies","Splenic hypofunction","Increased platelet production","Decreased platelet destruction"]'::jsonb, 'Anti-platelet antibodies', 'Immune thrombocytopenic purpura (ITP) is characterized by Anti-platelet antibodies.'),
('6b364193-36b6-5b37-a200-a8492f7a1b07'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Primary ITP in children is typically:', '["Refractory","Acute and self-limited","Chronic","Drug-induced","Associated with SLE"]'::jsonb, 'Acute and self-limited', 'Primary ITP in children is typically Acute and self-limited.'),
('acc6a76a-475a-5734-954e-8964caa17759'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In adults, immune thrombocytopenic purpura (ITP) most typically follows which clinical course?', '["Chronic","Acute","Mild","Post-viral","Self-limiting"]'::jsonb, 'Chronic', 'Adult ITP begins insidiously and is usually chronic, lasting more than 6 months; childhood ITP, in contrast, is typically acute, post-viral and self-limiting.'),
('4912b7c4-fa6c-5b0c-b611-9d4c2556cbd1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Immune thrombocytopenic purpura is mediated by autoantibodies directed against which cell target?', '["Anti-factor VIII","Anti-neutrophil antibody","Anti-RBC antibody","Anti-platelet antibody","Anti-dsDNA"]'::jsonb, 'Anti-platelet antibody', 'ITP is caused by autoantibodies, usually against platelet glycoprotein IIb/IIIa, that coat platelets and mark them for Fc-receptor-mediated destruction in the spleen.'),
('6e77a9d5-3069-52a9-9deb-39046ad433b1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The first-line treatment for ITP is:', '["Corticosteroids","Rituximab","Platelet transfusion","IVIG","Splenectomy"]'::jsonb, 'Corticosteroids', 'The first-line treatment for ITP is Corticosteroids.'),
('b7a8570a-06a7-57ef-8c7d-50e2e83c103b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Thrombotic thrombocytopenic purpura (TTP) is characterized by all EXCEPT:', '["Fever","Thrombocytopenia","Microangiopathic hemolytic anemia","Prolonged PT/aPTT","Renal failure"]'::jsonb, 'Prolonged PT/aPTT', 'Thrombotic thrombocytopenic purpura (TTP) is characterized by all EXCEPT Prolonged PT/aPTT.'),
('052877b5-cf4c-5565-9fd7-4d9a36fe2dd0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'TTP is caused by deficiency of:', '["Factor VIII","Plasminogen","ADAMTS13","vWF","Protein C"]'::jsonb, 'ADAMTS13', 'TTP is caused by deficiency of ADAMTS13.'),
('12bd7de6-b393-545d-b81f-bdfd2dc888bd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The classic pentad of TTP includes all EXCEPT:', '["Renal dysfunction","Splenomegaly","Thrombocytopenia","Fever","Microangiopathic hemolytic anemia"]'::jsonb, 'Splenomegaly', 'The classic pentad of thrombotic thrombocytopenic purpura is thrombocytopenia, microangiopathic hemolytic anemia, fever, renal dysfunction and neurologic signs; splenomegaly is not a component.'),
('da297de4-bae3-57d4-93cb-0c7a5ae2b1d8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Treatment of choice for TTP is:', '["Rituximab","Corticosteroids","Splenectomy","Plasma exchange","IVIG"]'::jsonb, 'Plasma exchange', 'Treatment of choice for TTP is Plasma exchange.'),
('a943b894-ea7a-51a2-ad54-49143f157ca3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Hemolytic uremic syndrome (HUS) is characterized by:', '["Thrombocytopenia","Acute renal failure","All","Neurologic symptoms","Microangiopathic hemolytic anemia"]'::jsonb, 'All', 'Hemolytic uremic syndrome (HUS) is characterized by All.'),
('c44970bd-254c-5f7d-8d28-5a56a0ecb9c8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In children, which organism most commonly triggers the classic (epidemic) form of the hemolytic-uremic syndrome?', '["HIV","Shigella","Streptococcus pneumoniae","E. coli O157:H7","Drugs"]'::jsonb, 'E. coli O157:H7', 'Shiga-toxin-producing E. coli O157:H7, usually acquired from contaminated food, is the leading cause of typical childhood hemolytic-uremic syndrome.'),
('123f1004-5ac9-5b4a-a75c-0082121a645a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The hemolytic-uremic syndrome that recurs or occurs without a preceding diarrheal illness (atypical HUS) is most often due to:', '["Complement dysregulation","Drugs accompanied by associated clinical symptoms","Shiga toxin mediated by specific receptor activation","HIV without affecting the primary tissue pathway","Pregnancy leading to subsequent cellular adaptation"]'::jsonb, 'Complement dysregulation', 'Atypical HUS results from inherited or acquired dysregulation of the alternative complement pathway, with consequent endothelial injury, rather than from Shiga toxin.'),
('a29c8cf3-8cd9-5923-ae66-8a56357261dc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Necrosis is characterised by:', '["Cell swelling, membrane rupture, inflammation","Cell shrinkage, chromatin condensation","Membrane blebbing","Apoptotic body formation","No inflammation"]'::jsonb, 'Cell swelling, membrane rupture, inflammation', 'Uncontrolled cell death causing inflammation.'),
('9bf67127-f545-5157-b0b7-371708d49767'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which combination of laboratory findings is characteristic of disseminated intravascular coagulation?', '["Prolonged PT","Thrombocytopenia","Prolonged aPTT","Elevated D-dimer","All"]'::jsonb, 'All', 'DIC consumes platelets and clotting factors and simultaneously elicits fibrinolysis, so thrombocytopenia, prolonged PT and aPTT, and an elevated D-dimer are all expected.'),
('887f9a4d-38c1-540c-b550-f3cfb6b75a05'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common cause of acute DIC is:', '["Obstetric complications","Snake bite","Malignancy","Trauma","Sepsis"]'::jsonb, 'Sepsis', 'The most common cause of acute DIC is Sepsis.'),
('ee113e67-eb32-5fff-aab8-395a0fc8229d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which is a cause of chronic DIC?', '["Trauma","Heat stroke","Solid tumors","Snake bite","Sepsis"]'::jsonb, 'Solid tumors', 'Chronic, low-grade DIC is the pattern typical of malignancy, especially mucin-secreting adenocarcinomas, whereas sepsis, trauma and obstetric catastrophe produce acute DIC.'),
('f5958b36-95ff-5875-bb83-aa437b3544c2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'An elevated D-dimer in disseminated intravascular coagulation reflects which process?', '["Platelet activation","Coagulation factor deficiency","Thrombosis","Secondary fibrinolysis","Primary fibrinolysis"]'::jsonb, 'Secondary fibrinolysis', 'D-dimer is a fibrin degradation product, and the fibrinolysis occurring in DIC is secondary to widespread intraluminal fibrin formation; this distinguishes it from primary fibrinolysis.'),
('bdcb8ddd-72d9-584a-83f6-58b7398ca7cd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Bites by which type of snake characteristically cause a hemorrhagic diathesis with disseminated intravascular coagulation?', '["Sea snake","Cobra","Viper","Krait","Coral snake"]'::jsonb, 'Viper', 'Viper (Viperidae) venoms contain clotting activators and proteases that generate a consumptive coagulopathy, making viper bites the classic snakebite cause of DIC.'),
('c1348b85-f81f-5828-bf4a-168e4bed2da7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Treatment of DIC primarily involves:', '["Antifibrinolytics","Platelet transfusion","Heparin","FFP and cryoprecipitate","Treat underlying cause"]'::jsonb, 'Treat underlying cause', 'The definitive treatment of DIC is to remove the underlying cause; blood components and coagulation factors are given only as secondary, supportive measures.'),
('16e0a67f-e0da-5c04-8d2d-c2226ee1e295'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which factor is consumed in DIC?', '["Platelets","All","Factor V","Fibrinogen","Factor VIII"]'::jsonb, 'All', 'Diffuse microvascular thrombosis in DIC consumes platelets, fibrinogen and factors V and VIII simultaneously, so depletion of all of these is characteristic.'),
('187470a9-019e-58e8-b97a-e77beabe6398'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Schistocytes on peripheral smear are characteristic of:', '["TTP/HUS","DIC","vWD","ITP","Hemophilia"]'::jsonb, 'TTP/HUS', 'Schistocytes on peripheral smear are characteristic of TTP/HUS.'),
('f7defb3a-5515-5269-a5c7-01c11128ec1c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Bleeding time is prolonged in:', '["Hemophilia A","ITP","Factor VIII deficiency","DIC (early)","Factor IX deficiency"]'::jsonb, 'ITP', 'Bleeding time is prolonged in ITP.'),
('08092651-e0cb-5f43-8f40-12f2fd45f931'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which factor deficiency causes bleeding with normal aPTT and PT?', '["Factor VIII","Factor XI","Factor XIII","Factor IX","von Willebrand factor"]'::jsonb, 'Factor XIII', 'Factor XIII cross-links fibrin polymers to stabilize the clot; its deficiency permits clot destabilization and delayed bleeding while the PT, aPTT and platelet count are all normal.'),
('8d3327ce-7d21-5942-84b9-dc3c05bbbecb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Hemophilia B (Christmas disease) is produced by a functional deficiency of which clotting factor?', '["Factors VIII","XI","Factors VII","X","IX"]'::jsonb, 'IX', 'Factor IX is the protein deficient in hemophilia B, an X-linked disorder that is clinically indistinguishable from hemophilia A except by specific factor assay.'),
('ecfc8f09-035d-5f16-b659-d0c381b06217'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which disorder has isolated prolongation of aPTT with normal PT?', '["DIC","Vitamin K deficiency","Liver disease","Hemophilia A","Warfarin therapy"]'::jsonb, 'Hemophilia A', 'Hemophilia A is a defect of the intrinsic pathway (factor VIII deficiency) that selectively prolongs the aPTT while the prothrombin time stays normal.'),
('8b0e7e35-4750-501b-b2cc-9c900748f891'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Hemophilia A is caused by a congenital deficiency of which coagulation factor?', '["Factor II","Factor VIII","Factor X","Factor VII","Factor IX"]'::jsonb, 'Factor VIII', 'Hemophilia A results from deficiency of factor VIII (the antihemophilic factor), which is inherited as an X-linked recessive trait.'),
('fde4a5de-56a5-5249-9614-4713ce2374d6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The normal leukocyte count in adults is:', '["000-11","000","4","1","000-4"]'::jsonb, '000-4', 'The normal leukocyte count in adults is 000-4.'),
('aafc7451-dd8c-55cf-8c61-184397f4e202'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Leukocytosis is defined as WBC count greater than:', '["6","000","9","11","None of the above"]'::jsonb, '9', 'Leukocytosis is defined as WBC count greater than 9.'),
('635bcf43-baa5-5851-bbb6-c32be441af28'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common cause of neutrophilic leukocytosis is:', '["Steroid use","Parasitic infection","Fungal infection","Viral infection","Bacterial infection"]'::jsonb, 'Bacterial infection', 'The most common cause of neutrophilic leukocytosis is Bacterial infection.'),
('ccab2da4-5f3c-5bec-bde6-4c217a57ec52'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Reactive lymphocytosis in the peripheral blood is most commonly triggered by which category of infection?', '["Viral infections","Bacterial infections","Fungal infections","Parasitic infections","Allergic reactions"]'::jsonb, 'Viral infections', 'Viral illnesses such as infectious mononucleosis and cytomegalovirus infection drive expansion of circulating lymphocytes, the classic cause of reactive lymphocytosis.'),
('72db21d5-d43b-5dd1-8a40-d24b1f34f7aa'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Eosinophilia is most commonly associated with:', '["Viral infections","Fungal infections","Bacterial infections","Parasitic infections","Neutropenia"]'::jsonb, 'Parasitic infections', 'Eosinophilia is most commonly associated with Parasitic infections.'),
('6a6f1257-83c4-506f-8a0e-ae4190831b5e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Basophilia is associated with:', '["Bacterial infection","CML","Allergic rhinitis","Parasitic infection","Viral infection"]'::jsonb, 'CML', 'Basophilia is associated with CML.'),
('b43611a4-1f6c-59cc-b6a0-ee75250c22ed'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Leukopenia is most commonly caused by:', '["Chemotherapy","Bacterial infection","Radiation","Autoimmune","Viral infection"]'::jsonb, 'Chemotherapy', 'Leukopenia is most commonly caused by Chemotherapy.'),
('5849d9fb-30fe-56d5-8d90-929b6004113d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which peripheral blood picture is characteristic of a leukemoid reaction?', '["Leukopenia","Blast cells","Eosinophilia","Leukocytosis with immature cells","Atypical lymphocytes"]'::jsonb, 'Leukocytosis with immature cells', 'A leukemoid reaction shows a striking leukocytosis, often above 50,000 cells per microliter, accompanied by a left shift with immature granulocytes; it is a reactive, not leukaemic, phenomenon.'),
('6cdbdab5-20e7-5905-b5c7-42e8c2d5a459'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which laboratory parameter best distinguishes a leukemoid reaction from chronic myeloid leukemia?', '["High LAP score","WBC count","Low LAP score","Splenomegaly","Presence of blasts"]'::jsonb, 'High LAP score', 'Leukocyte alkaline phosphatase is increased in reactive (leukemoid) conditions and markedly reduced in CML, so the LAP score is the key discriminating test.'),
('ee1f69c0-adb7-5b68-a843-45f9b850b01e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Leukemoid reaction has high leukocyte alkaline phosphatase (LAP) because:', '["It is monoclonal","It has blasts","It has Philadelphia chromosome","It is a reactive process","It is a malignancy"]'::jsonb, 'It is a reactive process', 'The LAP is high in a leukemoid reaction because the leukocytosis is a reactive, non-clonal response, whereas in CML the leukemic clone has low LAP activity.'),
('7ecd314d-1e63-5c02-938b-6a516301f81b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most frequent cause of a neutrophilic leukocytosis is:', '["Hemorrhage","Malignancy","Hemolysis","Infection","Drug reaction"]'::jsonb, 'Infection', 'Bacterial infection is the commonest stimulus for a reactive neutrophilia; hemorrhage, hemolysis, malignancy and drug reactions are much less frequent causes.'),
('8da12c80-ab89-5ae2-8588-68a45520417e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Infectious mononucleosis is caused by which virus?', '["CMV","HIV","HSV","EBV","HHV-6"]'::jsonb, 'EBV', 'Epstein-Barr virus is the etiologic agent of infectious mononucleosis, producing fever, pharyngitis, lymphadenopathy and atypical lymphocytosis.'),
('ec78cbce-7cab-585a-a6be-24839db94e42'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The characteristic cells in infectious mononucleosis are:', '["Reactive lymphocytes (Downey cells)","Neutrophils accompanied by associated clinical symptoms","Blasts mediated by specific receptor activation","Atypical monocytes without affecting the primary tissue pathway","Eosinophils leading to subsequent cellular adaptation"]'::jsonb, 'Reactive lymphocytes (Downey cells)', 'The characteristic cells in infectious mononucleosis are Reactive lymphocytes (Downey cells).'),
('9639f3ef-6662-5c7a-8d30-cbae9926eb17'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which serologic finding is the classic laboratory hallmark of infectious mononucleosis?', '["Sheep RBCs","CMV","Monkey RBCs","Heterophile antibodies","EBV"]'::jsonb, 'Heterophile antibodies', 'The Paul-Bunnell heterophile antibodies, detected by their agglutination of horse or sheep red cells, are the traditional serologic marker of infectious mononucleosis.'),
('430af459-0cc9-5a74-809f-3c8237b7b85a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In the modern Monospot test for infectious mononucleosis the heterophile antibody is detected by agglutination of which cells?', '["Human RBCs","Bovine RBCs","Goat RBCs","Sheep RBCs","Horse RBCs"]'::jsonb, 'Horse RBCs', 'The Monospot uses horse erythrocytes, which give greater sensitivity for the heterophile antibody of infectious mononucleosis than the sheep cells of the original Paul-Bunnell test.'),
('6dd18c38-6733-595a-950d-99948f3464b2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Rupture is the most dangerous complication of infectious mononucleosis; it most often affects which organ?', '["Meningitis","Splenic rupture","Hemolytic anemia","Airway obstruction","Hepatitis"]'::jsonb, 'Splenic rupture', 'Massive splenic enlargement in infectious mononucleosis predisposes to splenic rupture, a rare but potentially fatal event, particularly during exertion.'),
('11a1f09e-8f4c-5a6c-8f0c-7ceaf78f6424'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Agranulocytosis is defined as:', '["Absent neutrophils","WBC < 2000","Absent lymphocytes","Monocytes < 100","Neutrophils < 500"]'::jsonb, 'Neutrophils < 500', 'Agranulocytosis is defined as Neutrophils < 500.'),
('e7a5b9f6-b37a-504f-876e-121f83288621'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Drug-induced agranulocytosis is commonly caused by:', '["Aspirin","Acetaminophen","Penicillin","Clozapine","Omeprazole"]'::jsonb, 'Clozapine', 'Drug-induced agranulocytosis is commonly caused by Clozapine.'),
('f19f815c-378b-575d-a376-739e9b372f08'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which infection is most common in agranulocytosis?', '["Viral","Fungal","Bacterial","Protozoal","Parasitic"]'::jsonb, 'Bacterial', 'Bacterial is the association with the highest frequency in this setting.'),
('2e6111ee-957a-5d41-ae7f-ffa40b0ff0bf'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Neutropenia is defined as neutrophil count less than:', '["1500","500","1000","2000","2500"]'::jsonb, '1500', 'Neutropenia is defined as neutrophil count less than 1500.'),
('e356557f-5f87-53df-aa7e-140af288b416'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Atherosclerosis: foam cells are derived from:', '["Macrophages accumulating oxidised LDL","Smooth muscle cells","Endothelial cells","Fibroblasts","T lymphocytes"]'::jsonb, 'Macrophages accumulating oxidised LDL', 'Scavenger receptors on macrophages take up modified LDL.'),
('a9254df9-51b4-55df-801c-371293d97276'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Lymphopenia is commonly associated with:', '["EBV infection","Allergic reaction","Whooping cough","CMV infection","HIV infection"]'::jsonb, 'HIV infection', 'Lymphopenia is commonly associated with HIV infection.'),
('2e1ed3b6-872d-5acb-a3e3-511896d3c35a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which is a cause of reactive neutrophilia?', '["All","Stress","Smoking","Exercise","Infection"]'::jsonb, 'All', 'Neutrophilic leukocytosis is often reactive: infection, physical stress, cigarette smoking and exercise are each recognized triggers that raise the circulating neutrophil count.'),
('ccd4a3f3-73c3-553e-bcd6-28ea849d4817'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A ''left shift'' in the peripheral blood film, typical of acute bacterial infection, is reflected by an increase in which cell type?', '["Eosinophilia","Basophilia","Hyposegmented neutrophils","Hypersegmented neutrophils","Atypical lymphocytes"]'::jsonb, 'Hyposegmented neutrophils', 'Left shift denotes release of immature neutrophils (bands and metamyelocytes) from the marrow, cells that are hyposegmented compared with mature neutrophils.'),
('bf63e701-6bba-58d2-9189-747b45739777'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'May-Hegglin anomaly involves:', '["All","Giant platelets","Neutrophil inclusion bodies","Thrombocytopenia","Dohle bodies"]'::jsonb, 'All', 'May-Hegglin anomaly is a benign disorder combining autosomal dominant thrombocytopenia with giant platelets and Dohle-like basophilic inclusions within neutrophils.'),
('5d419466-85e0-5af2-86a7-5feda56e14cb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Granulomatous inflammation is characteristic of:', '["Tuberculosis and sarcoidosis","Acute appendicitis","Viral hepatitis","Pneumonia","Pyogenic abscess"]'::jsonb, 'Tuberculosis and sarcoidosis', 'Epithelioid histiocytes and multinucleated giant cells.'),
('48e3d50b-0dd2-57c5-be76-e7e56a3d1fc8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which anemia is associated with kwashiorkor?', '["Microcytic anemia","Iron deficiency","Hemolytic anemia","Normocytic anemia","Megaloblastic anemia"]'::jsonb, 'Megaloblastic anemia', 'Protein-energy malnutrition as in kwashiorkor is commonly complicated by folate deficiency, which produces a megaloblastic anemia.'),
('b67be543-4281-5dde-aab5-ae8a37157dce'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following best describes the striking clinical feature of marasmus?', '["Growth retardation","Severe wasting of all tissues","Fatty liver","Edema","Muscle wasting (spared)"]'::jsonb, 'Severe wasting of all tissues', 'Marasmus reflects total calorie deficiency and shows severe wasting of subcutaneous fat and somatic muscle; unlike kwashiorkor it does not feature edema or fatty liver.'),
('402dd20c-8597-5c6a-a526-99d6c60c1e05'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Kwashiorkor is characteristically accompanied by which physical finding?', '["Edema","Normal weight","Normal growth","Fatty liver","Severe muscle wasting"]'::jsonb, 'Severe muscle wasting', 'Kwashiorkor reflects protein deficiency, so muscle protein is catabolized and severe muscle wasting develops while subcutaneous fat and edema are typically preserved.'),
('9fdd5a9b-b11e-5745-a08c-8b28088c9c27'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The difference between kwashiorkor and marasmus is that kwashiorkor has:', '["Edema","Normal albumin","skin changes","Normal growth","Severe wasting"]'::jsonb, 'Edema', 'The difference between kwashiorkor and marasmus is that kwashiorkor has Edema.'),
('edb895bc-3dfa-51d9-a226-03aae3953193'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Kwashiorkor most characteristically develops at which age, when breast milk is replaced by a protein-poor diet?', '["In elderly","In diet after weaning (1-3 years)","In adolescents","In diet before 6 months","In adults"]'::jsonb, 'In diet after weaning (1-3 years)', 'Kwashiorkor usually appears after weaning, between 1 and 3 years of age, when a starchy, protein-deficient diet cannot meet protein needs.'),
('3dd9113e-9a9a-50b2-8cf7-2c6d1fd62e07'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Marasmus most characteristically occurs during which period of life?', '["Infants < 1 year","Elderly","Children 1-3 years","Adults","Adolescents"]'::jsonb, 'Infants < 1 year', 'Marasmus is a total-calorie deficiency seen mainly in the first year of life, when early weaning and recurrent infections produce severe wasting.'),
('a8e8224a-0704-5481-a563-2bdefc456550'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Fatty change of the liver in kwashiorkor is caused principally by:', '["Decreased apolipoprotein synthesis","Decreased fatty acid oxidation","Increased VLDL synthesis","Increased carbohydrate intake","Increased lipolysis"]'::jsonb, 'Decreased apolipoprotein synthesis', 'In protein deficiency, reduced hepatic synthesis of apolipoproteins impairs the export of triglycerides in VLDL, so fat accumulates within hepatocytes and fatty liver results.'),
('7e924385-4300-5b08-9e30-e67846ccf9a1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'What pathological process involves excess fluid accumulation in interstitial spaces?', '["Growth retardation","Hair changes","Edema","Subcutaneous fat loss","Muscle wasting"]'::jsonb, 'Edema', 'Edema, a hallmark of kwashiorkor, is caused by hypoalbuminemia; the low plasma oncotic pressure allows fluid to accumulate in the interstitial spaces.'),
('157faec7-27f0-5916-9758-236e1d127299'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Obesity is defined as BMI of:>= 25', '[">= 30",">= 40","1×",">= 35",">= 45"]'::jsonb, '>= 35', 'The relevant association is >= 35, which identifies the feature being tested.'),
('75025d27-4ae8-5788-8d8c-60cfe7d01571'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A patient with excess abdominal fat, elevated blood pressure, abnormal lipid levels and raised fasting glucose belongs to which diagnostic category?', '["Hypertension","Dyslipidemia","All","Diabetes","Metabolic syndrome"]'::jsonb, 'All', 'This cluster - central obesity, hypertension, dyslipidemia and impaired glucose handling - is the hallmark of the metabolic syndrome, so all the listed states coexist in the syndrome.'),
('7e71b669-fd79-5aae-845a-60e4f0488b87'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is NOT one of the diagnostic criteria of the metabolic syndrome?', '["Hypertension","Hyperglycemia","Central obesity","Low HDL","High LDL"]'::jsonb, 'High LDL', 'The metabolic syndrome is defined by central obesity, raised blood pressure, hypertriglyceridemia, low HDL and elevated fasting glucose; a high LDL is not among the defining criteria.'),
('51996cb5-af2f-56f7-b771-42e60c4aadf6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The satiety-regulating hormone leptin is synthesized and secreted mainly by which tissue?', '["Muscle","Adipose tissue","Liver","Pancreas","Brain"]'::jsonb, 'Adipose tissue', 'Leptin is produced predominantly by adipocytes; its circulating level reflects fat stores, and it acts on hypothalamic centers to suppress appetite.'),
('f9299bc2-6767-59f7-b18a-dfebeddbe390'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Leptin deficiency causes:', '["Anorexia","Cachexia","Obesity","Diabetes","Thyroid dysfunction"]'::jsonb, 'Obesity', 'Leptin deficiency removes the central brake on feeding, so affected children and animals become hyperphagic and obese.'),
('8a131985-f1f6-572d-9e8a-9f08f9bde7f0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which adipokine is anti-inflammatory and insulin-sensitizing?', '["Resistin","TNF-alpha","Adiponectin","Leptin","IL-6"]'::jsonb, 'Adiponectin', 'Adiponectin improves insulin sensitivity, promotes fatty-acid oxidation and is anti-inflammatory, and its levels fall in obesity.'),
('5be88622-49c8-5a38-896f-9b45cfc99ea0'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Type I hypersensitivity (allergic) is mediated by:', '["IgE antibodies","IgG antibodies","IgM antibodies","T cells","Complement"]'::jsonb, 'IgE antibodies', 'IgE binds mast cell FcεRI, cross-linking triggers degranulation.'),
('190d6ad9-6fe5-52f4-bd76-1ef210895dd9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which metabolite of vitamin A mediates most of the vitamin''s effects on gene expression and cell differentiation?', '["Retinol","Retinal","Retinoic acid","Beta-carotene","All"]'::jsonb, 'Retinoic acid', 'Retinol is oxidized to retinal and then to retinoic acid, which binds nuclear receptors to regulate gene transcription controlling cellular differentiation and growth.'),
('010a3a15-1067-5da3-8113-1bf40281b173'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which cell type is affected in vitamin A deficiency causing night blindness?', '["Pigment epithelium","Rod cells","Ganglion cells","Bipolar cells","Cone cells"]'::jsonb, 'Rod cells', 'Night blindness in vitamin A deficiency reflects impaired rhodopsin regeneration within rod cells, since the light-sensitive pigment requires 11-cis-retinal.'),
('7ce1e70a-ee58-517b-b379-54b5fe4c042b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Vitamin A toxicity (hypervitaminosis A) causes:', '["Hepatotoxicity","All","Teratogenicity","Pseudotumor cerebri","Bone pain"]'::jsonb, 'All', 'Excess vitamin A is toxic to the liver and skeleton and is teratogenic; it also raises intracranial pressure, producing pseudotumor cerebri.'),
('1a232ecf-38eb-55e0-a0be-37776aa53e5c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Beriberi is caused by deficiency of:', '["Vitamin B1 (thiamine)","Vitamin B12","Vitamin B2","Vitamin B6","Vitamin B3"]'::jsonb, 'Vitamin B1 (thiamine)', 'Beriberi is caused by deficiency of Vitamin B1 (thiamine).'),
('b191f590-02b7-5904-8d2c-2be8edfb5a1e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Wet beriberi primarily affects the:', '["Cardiovascular system","Bones","Nervous system","Skin","Blood"]'::jsonb, 'Cardiovascular system', 'Wet (cardiac) beriberi is thiamine deficiency manifesting as biventricular high-output heart failure with peripheral vasodilatation and edema.'),
('30929188-8ea0-563e-9140-e7ddc84218e2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Dry beriberi primarily affects the:', '["Heart","Skin","Eyes","Peripheral nerves","Bones"]'::jsonb, 'Peripheral nerves', 'Dry beriberi is the neuropathic form of thiamine deficiency, with a symmetric distal sensorimotor peripheral neuropathy.'),
('0123e554-c435-59e9-b8bc-3c1e1b3f334b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Wernicke encephalopathy is due to thiamine deficiency and features:', '["Ophthalmoplegia","All","Ataxia","Confusion","Nystagmus"]'::jsonb, 'All', 'Wernicke encephalopathy is due to thiamine deficiency and features All.'),
('716e5c73-5a46-52e9-8920-af5a6a42e544'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Korsakoff psychosis is characterized by:', '["Amnesia","Memory loss","Hallucinations","All","Confabulation"]'::jsonb, 'All', 'Korsakoff psychosis is characterized by All.'),
('0dfa2f94-7026-5544-9b2a-2c4775ecda41'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The enzyme requiring thiamine as cofactor is:', '["Pyruvate dehydrogenase","Alpha-ketoglutarate dehydrogenase","All","Transketolase","Branched-chain ketoacid dehydrogenase"]'::jsonb, 'All', 'The enzyme requiring thiamine as cofactor is All.'),
('697a4c9e-4680-5537-bf77-ed331e73d866'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Pellagra is caused by a deficiency of which vitamin?', '["Vitamin B6","Vitamin B1","Vitamin B3 (niacin)","Vitamin B12","Vitamin B2"]'::jsonb, 'Vitamin B3 (niacin)', 'Pellagra results from niacin (vitamin B3) deficiency and is classically seen with corn-based, low-tryptophan diets.'),
('b6c7c61b-cde6-5a32-82a1-a520d6c4472e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which neuropsychiatric feature completes the classic clinical triad of pellagra?', '["dementia","dermatitis","None of the above","diarrhea","No"]'::jsonb, 'dementia', 'Pellagra is remembered by the three Ds - dermatitis, diarrhea and dementia (death being the fourth) - all consequences of niacin deficiency.'),
('e6c8c846-dc8c-515a-9e63-cffa159e8baf'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Niacin can be synthesized from which amino acid?', '["Methionine","Tryptophan","Tyrosine","Phenylalanine","Lysine"]'::jsonb, 'Tryptophan', 'Tryptophan is metabolized into niacin, so diets low in both tryptophan and niacin, such as those based on corn, predispose to pellagra.'),
('e0126037-0a0c-5e1e-be7e-1d67b4cbb03a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Vitamin B6 (pyridoxine) deficiency can be caused by:', '["All","Oral contraceptives","Alcoholism","INH therapy","Cycloserine"]'::jsonb, 'All', 'Pyridoxine is antagonized by isoniazid and cycloserine, depleted by oral contraceptives and disturbed by chronic alcoholism, so all of these can cause vitamin B6 deficiency.'),
('d7b74f8d-f6c2-5c5b-bb65-37879752587b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Pyridoxine is a cofactor for:', '["Homocysteine metabolism","Heme synthesis","All","Transamination","Neurotransmitter synthesis"]'::jsonb, 'All', 'Pyridoxine is a cofactor for All.'),
('f02215f6-f147-5018-b468-89f73fb7b797'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Vitamin B12 is essential for:', '["RBC maturation","All","Myelination","Homocysteine metabolism","DNA synthesis"]'::jsonb, 'All', 'Vitamin B12 is essential for All.'),
('df5ed551-2e51-540e-9bc9-e7e332e38dc5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Pernicious anemia is caused by:', '["Ileal resection","Dietary B12 deficiency","Vegan diet","Fish tapeworm","Lack of intrinsic factor"]'::jsonb, 'Lack of intrinsic factor', 'Pernicious anemia is caused by Lack of intrinsic factor.'),
('41717472-d17b-5762-b1b0-bc78fadf6c96'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which laboratory finding is elevated specifically in vitamin B12 deficiency but not in pure folate deficiency, thus distinguishing the two states?', '["Macrocytosis","Low RBC folate","High homocysteine","Hypersegmented neutrophils","High methylmalonic acid"]'::jsonb, 'High methylmalonic acid', 'B12 is required to isomerize methylmalonyl-CoA to succinyl-CoA; with B12 deficiency, methylmalonic acid accumulates, whereas it remains normal in pure folate deficiency.'),
('ff548019-3ea9-5157-9a09-832c3bbdc454'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Subacute combined degeneration of the spinal cord is due to:', '["B1 deficiency","B3 deficiency","B6 deficiency","B12 deficiency","Folate deficiency"]'::jsonb, 'B12 deficiency', 'Subacute combined degeneration of the spinal cord is due to B12 deficiency.'),
('ab52ea9b-f3f0-52a5-b16c-047c654e3f4b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The earliest sign of scurvy (vitamin C deficiency) is:', '["Bleeding gums","Impaired wound healing","Joint pain","Easy bruising","Perifollicular hemorrhages"]'::jsonb, 'Perifollicular hemorrhages', 'The earliest sign of scurvy (vitamin C deficiency) is Perifollicular hemorrhages.'),
('493f130e-f0ea-525c-a85c-60575c711d35'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Vitamin C is a cofactor for:', '["All","Prolyl hydroxylase","Collagen synthesis","Dopamine beta-hydroxylase","Lysyl hydroxylase"]'::jsonb, 'All', 'Vitamin C is a cofactor for All.'),
('649f08d5-415c-5297-9c68-fe90e2eb3c57'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which manifestation of vitamin C deficiency is especially characteristic of the infantile form (Barlow disease)?', '["Poor wound healing","Subperiosteal hemorrhage","Joint pain","Bleeding gums","Corkscrew hair"]'::jsonb, 'Subperiosteal hemorrhage', 'In infantile scurvy, defective collagen synthesis weakens periosteal vessels, so subperiosteal hemorrhage and impaired bone growth dominate; adult scurvy features bleeding gums and perifollicular hemorrhage.'),
('397fbcd4-bba5-593c-ad03-d501db66f3dd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Rickets in children is due to vitamin D deficiency causing:', '["Rachitic rosary","Bowed legs","Osteomalacia","Craniotabes","All"]'::jsonb, 'All', 'Rickets in children is due to vitamin D deficiency causing All.'),
('125a05a0-4a76-5081-b249-46e84616d973'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Osteomalacia in adults presents with:', '["All","Bone pain","Looser zones (pseudofractures)","Muscle weakness","Soft bones"]'::jsonb, 'All', 'Osteomalacia in adults causes bone pain, proximal muscle weakness and soft, deformable bones with Looser zones (pseudofractures) on radiography.'),
('9ebe1582-567f-5475-9f07-6f922ada3bb2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Vitamin D is synthesized in the skin upon exposure to:', '["Infrared","Visible light","UVB","UVC","UVA"]'::jsonb, 'UVB', 'Vitamin D is synthesized in the skin upon exposure to UVB.'),
('b7ef9934-e703-5333-9bcb-e8b1c1744703'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Hydroxylation at which position of vitamin D, carried out by 1-alpha-hydroxylase in the kidney, produces the biologically active hormone calcitriol?', '["1","25(OH)2D3","Vitamin D2","25(OH)D3","7-dehydrocholesterol"]'::jsonb, '1', 'Calcitriol, 1,25-dihydroxyvitamin D3, is formed when the kidney adds a hydroxyl group at carbon 1; this is the step that generates the active hormonal form.'),
('2efe28db-14c8-5a4e-8fad-e30923443ba9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Vitamin K is essential for which physiological process?', '["Bone mineralization","Collagen synthesis","Antioxidant function","Blood coagulation","DNA synthesis"]'::jsonb, 'Blood coagulation', 'Vitamin K-dependent gamma-carboxylation activates clotting factors II, VII, IX and X and proteins C and S, so the vitamin is indispensable for normal blood coagulation.'),
('9d41143d-5a4a-5146-811f-76d793dc3730'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In early vitamin K deficiency the prothrombin time is prolonged while the activated partial thromboplastin time characteristically remains:', '["Prolonged BT","Prolonged PT","Thrombocytopenia","normal aPTT","Prolonged PT and aPTT"]'::jsonb, 'normal aPTT', 'Of the vitamin K-dependent factors, factor VII has the shortest half-life, so the PT prolongs first; the aPTT becomes abnormal only when the other vitamin K-dependent factors are also depleted.'),
('e85e1f77-d310-5d8a-8054-204791fdc417'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Bleeding in the first days of life due to vitamin K deficiency, preventable by prophylactic administration soon after birth, is termed:', '["ITP resulting in decreased functional activity","TTP accompanied by associated clinical symptoms","Hemorrhagic disease of newborn","DIC without affecting the primary tissue pathway","Hemophilia leading to subsequent cellular adaptation"]'::jsonb, 'Hemorrhagic disease of newborn', 'Hemorrhagic disease of the newborn results from transient vitamin K deficiency caused by a sterile gut and low hepatic stores; it is prevented by intramuscular vitamin K.'),
('f7748a55-8168-5a11-82d7-1fb064328fed'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Warfarin exerts its anticoagulant effect principally by inhibiting which enzyme?', '["Prothrombin","Factor X","Vitamin K absorption","Vitamin K epoxide reductase","Platelet aggregation"]'::jsonb, 'Vitamin K epoxide reductase', 'Warfarin inhibits the recycling enzyme vitamin K epoxide reductase, so reduced vitamin K is unavailable for the gamma-carboxylation of the procoagulant factors.'),
('fda3d4fb-aef5-5388-827e-c6788a2b5c99'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Vitamin B12 deficiency characteristically produces which morphologic type of anemia?', '["Aplastic anemia","Hemolytic anemia","Megaloblastic anemia","Microcytic anemia","Sideroblastic anemia"]'::jsonb, 'Megaloblastic anemia', 'Cobalamin is needed for DNA synthesis; its deficiency produces megaloblastic erythropoiesis with macrocytic red cells and hypersegmented neutrophils.'),
('eb2878c6-8686-5db1-bef5-01ba4869c9c1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which drug causes folate deficiency by inhibiting dihydrofolate reductase?', '["Oral contraceptives","Trimethoprim","Sulfonamides","Methotrexate","Phenytoin"]'::jsonb, 'Methotrexate', 'Methotrexate is the option that best fits the therapeutic indication described.'),
('09c9bd9e-86f5-57a6-8a26-f78b6cd10e81'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Periconceptional supplementation of which micronutrient reduces the risk of neural tube defects?', '["Iron","Vitamin D","Folic acid","Vitamin B12","Vitamin C"]'::jsonb, 'Folic acid', 'Folate is required for nucleotide synthesis, and folic acid begun before and continued through early pregnancy markedly lowers the incidence of neural tube defects.'),
('405eb55a-8799-5ff2-9adc-5b4b9ca96418'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common dietary iron deficiency anemia is:', '["Chronic blood loss","Malabsorption","Pregnancy","Poor diet","Menorrhagia"]'::jsonb, 'Menorrhagia', 'The most common dietary iron deficiency anemia is Menorrhagia.'),
('abf318b3-8f33-550f-be6f-1f2ae4c37602'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'SLE is characterised by:', '["Anti-dsDNA and anti-Smith antibodies","Anti-CCP antibodies","Rheumatoid factor","Anti-centromere antibodies","ANCA"]'::jsonb, 'Anti-dsDNA and anti-Smith antibodies', 'Autoantibodies against nuclear antigens.'),
('6b5d6902-79d6-5556-ac6d-32554300a2e8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which histochemical stain is used to demonstrate hemosiderin (ferric iron) deposits in tissue sections?', '["HE stain","Masson trichrome","Giemsa stain","Periodic acid-Schiff","Prussian blue stain"]'::jsonb, 'Prussian blue stain', 'The Prussian blue (Perls) reaction stains ferric iron blue and is the standard method for demonstrating hemosiderin in iron overload.'),
('2201288e-9dd3-50b5-a4b7-348e7db3fe37'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Severe iodine deficiency during pregnancy and early childhood may result in which constellation of findings?', '["Cretinism","Goiter","Hypothyroidism","All","Weight gain"]'::jsonb, 'All', 'Iodine is required for thyroid hormone synthesis; dietary deficiency causes goiter and hypothyroidism (with weight gain) and, during development, cretinism.'),
('be73b7fc-f140-5ee2-a75a-4462a313db53'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Cretinism due to iodine deficiency presents with:', '["Growth retardation","Mental retardation","Deaf-mutism","Neurologic defects","All"]'::jsonb, 'All', 'Cretinism due to iodine deficiency presents with All.'),
('db945865-c205-5672-ad5d-f62a52ee3042'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Scleroderma (systemic sclerosis) features:', '["Anti-Scl-70 (diffuse) or anti-centromere (limited)","Anti-dsDNA accompanied by associated clinical symptoms","Anti-CCP mediated by specific receptor activation","Rheumatoid factor without affecting the primary tissue pathway","ANCA leading to subsequent cellular adaptation"]'::jsonb, 'Anti-Scl-70 (diffuse) or anti-centromere (limited)', 'Autoantibodies against topoisomerase I or centromere.'),
('dd824e47-3d39-5781-b49a-a980bbea9ef9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which trace element deficiency classically produces acrodermatitis-like periorificial skin lesions, alopecia, diarrhea and growth retardation?', '["Iodine deficiency","Selenium deficiency","Iron deficiency","Zinc deficiency","Copper deficiency"]'::jsonb, 'Zinc deficiency', 'Impaired zinc absorption (acrodermatitis enteropathica) or dietary deficiency causes dermatitis, hair loss, diarrhea, immune dysfunction and stunted growth.'),
('fa6bea77-8435-5da6-a769-be5437e52e53'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Kinky (pill torti) hair, severe neurodegeneration and growth failure characterize which inherited disorder of intestinal copper handling?', '["Zinc deficiency","Copper malabsorption","Selenium toxicity","Copper deficiency","Iron overload"]'::jsonb, 'Copper malabsorption', 'Menkes disease is an X-linked defect of intestinal copper transport (ATP7A), causing systemic copper deficiency with characteristic hair changes and cerebral degeneration.'),
('d8cf6552-ce6b-5909-8541-6faf36426911'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Accumulation of which metal in the liver and basal ganglia underlies Wilson disease (hepatolenticular degeneration)?', '["Zinc deficiency","Copper deficiency","Selenium deficiency","Copper accumulation","Iron overload"]'::jsonb, 'Copper accumulation', 'In Wilson disease, defective biliary copper excretion leads to progressive copper accumulation in the liver and brain, producing cirrhosis and extrapyramidal signs.'),
('12c9472d-ead8-58b2-a089-9c50e35bb27a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The Kayser-Fleischer ring seen at the limbus of the cornea in Wilson disease represents:', '["Lipid deposition in retina","Iron deposition in cornea","Copper deposition in cornea","Calcium deposition in cornea","Pigment in retina"]'::jsonb, 'Copper deposition in cornea', 'The Kayser-Fleischer ring is a golden-brown band of copper deposited in Descemet membrane at the corneal periphery, a diagnostically important sign of Wilson disease.'),
('405e7ddc-115f-57d5-be59-df6be4df4341'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Selenium is a cofactor for:', '["Xanthine oxidase","Catalase","Superoxide dismutase","Glutathione peroxidase","Cytochrome oxidase"]'::jsonb, 'Glutathione peroxidase', 'Selenium is a cofactor for Glutathione peroxidase.'),
('c519a442-8c29-59e0-9c77-d855655875da'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Keshan disease is due to:', '["Zinc deficiency","Selenium deficiency","Copper deficiency","Iodine deficiency","Iron deficiency"]'::jsonb, 'Selenium deficiency', 'Keshan disease is due to Selenium deficiency.'),
('cfaa4664-3420-5d5d-9347-a7b13e9be906'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In Goodpasture syndrome, the circulating autoantibody binds to basement membrane type IV collagen in which two locations?', '["Alveolar basement membrane","Glomerular basement membrane","Both GBM and alveolar BM","Platelet membrane","RBC membrane"]'::jsonb, 'Both GBM and alveolar BM', 'Anti-GBM antibody targets the alpha-3 chain of type IV collagen, present in both the glomerular and alveolar basement membranes, causing nephritis together with pulmonary hemorrhage.'),
('d7192ddf-c1fb-5b01-8642-7309c3c7b452'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which air pollutant is most strongly linked to COPD?', '["Ozone","Nitrogen dioxide","Sulfur dioxide","Carbon monoxide","Particulate matter (PM2.5)"]'::jsonb, 'Particulate matter (PM2.5)', 'Fine particulate matter (PM2.5) reaches the distal airways and drives chronic inflammation and oxidative injury, so it is the air pollutant most strongly linked to COPD.'),
('97e4f7e5-d9ec-5eb2-86c6-453533157d26'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which pollutant causes bronchoconstriction and increased asthma attacks?', '["PM10","Sulfur dioxide","Nitrogen dioxide","Lead","Ozone"]'::jsonb, 'Sulfur dioxide', 'Sulfur dioxide is a soluble irritant gas that triggers reflex bronchoconstriction and worsens asthma, particularly in sensitive individuals.'),
('b85c4b57-b84b-58a3-bf36-adeaf81f5385'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', '''Which type of emphysema is associated with alpha-1 antitrypsin deficiency?', '["Irregular","Panacinar","Centriacinar","Paraseptal","Bullous"]'::jsonb, 'Panacinar', 'Alpha-1 antitrypsin deficiency removes the protective inhibition of neutrophil elastase, causing panacinar emphysema that characteristically predominates in the lower zones.'),
('b4c7dabc-4c8e-50bb-ac9e-f08c911c8099'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Emphysema is produced chiefly by the action of which enzyme that degrades alveolar elastin when its circulating inhibitor is deficient?', '["Neutrophil elastase","Collagenase","Chymotrypsin","Trypsin","Cathepsin"]'::jsonb, 'Neutrophil elastase', 'Neutrophil elastase digests elastin in the alveolar wall; normally it is kept in check by alpha-1-antitrypsin, and when that inhibitor is deficient the enzyme acts unopposed, producing panacinar emphysema.'),
('496ee310-e63f-5bea-ab69-a90ac220dfbb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Type III hypersensitivity involves:', '["Immune complex deposition (antigen-antibody complexes)","IgE-mediated degranulation accompanied by associated clinical symptoms","Antibody-mediated cytotoxicity mediated by specific receptor activation","T cell-mediated cytotoxicity without affecting the primary tissue pathway","None leading to subsequent cellular adaptation"]'::jsonb, 'Immune complex deposition (antigen-antibody complexes)', 'Complement activation and neutrophil recruitment.'),
('6c525c71-71b2-5b62-8ad5-926e8e468b0c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Smoking is the leading risk factor for which lung cancer type?', '["Small cell carcinoma","Adenocarcinoma","Squamous cell carcinoma","Large cell carcinoma","Carcinoid"]'::jsonb, 'Squamous cell carcinoma', 'Squamous cell carcinoma of the bronchus is the classic smoking-related lung cancer, arising from squamous metaplasia in central airways after chronic irritation.'),
('246d703b-6ea0-5295-9a97-eb9cf7b0701c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is NOT caused by smoking?', '["Prostate cancer","Bladder cancer","Cervical cancer","Lung cancer","Pancreatic cancer"]'::jsonb, 'Prostate cancer', 'Prostate cancer is the mechanism or cause responsible for the finding described.'),
('b232995f-9875-5171-87cf-af1421239d1e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The fetal alcohol syndrome comprises a pattern of congenital defects that includes:', '["Neurodevelopmental delay","All","Cardiac defects","Growth retardation","Facial dysmorphism"]'::jsonb, 'All', 'Prenatal alcohol exposure produces growth retardation, characteristic facial dysmorphism, cardiac defects and neurodevelopmental delay, so all the listed features are part of the syndrome.'),
('8eca27ec-74a5-55c8-baf0-2de816896bb6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Alcoholic liver disease progresses in which order?', '["Cirrhosis -> hepatitis -> steatosis","Hepatitis -> cirrhosis -> steatosis","Hepatitis -> steatosis -> cirrhosis","Steatosis -> cirrhosis -> hepatitis","Steatosis -> hepatitis -> cirrhosis"]'::jsonb, 'Steatosis -> hepatitis -> cirrhosis', 'Alcoholic liver disease progresses in sequence through fatty change (steatosis), alcoholic hepatitis, and finally cirrhosis with irreversible fibrosis.'),
('2ce8bd24-01c2-526e-94da-3b91222bccb9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Mallory-Denk bodies are seen in:', '["Hemochromatosis","Viral hepatitis","Autoimmune hepatitis","NAFLD","Alcoholic hepatitis"]'::jsonb, 'Alcoholic hepatitis', 'Mallory-Denk bodies are seen in Alcoholic hepatitis.'),
('571bb6fa-e0bb-5f2d-87d2-b00fc12c5358'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Acute radiation syndrome after whole-body irradiation affects:', '["Skin","All","Hematopoietic system","GI tract","CNS"]'::jsonb, 'All', 'Whole-body irradiation injures the skin, bone marrow, gut and brain in parallel, so acute radiation syndrome affects all the listed systems, with the most rapidly dividing tissues damaged first.'),
('42146098-5366-53ac-b3eb-798bf5710bd1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most radiosensitive cells are:', '["Liver cells","Lymphocytes","Neurons","Bone cells","Muscle cells"]'::jsonb, 'Lymphocytes', 'The most radiosensitive cells are Lymphocytes.'),
('bc16be22-6154-5f08-9a25-d3bb28e9d95a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which type of radiation causes the most DNA damage?', '["Beta particles","X-rays","Gamma rays","Neutron radiation","Alpha particles"]'::jsonb, 'Neutron radiation', 'Neutron radiation is high-LET radiation that deposits dense ionizing energy and produces more double-strand DNA breaks, causing the greatest per-dose biological damage.'),
('8253ac85-56dc-5996-a7d6-efe46621ad94'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Clinically significant bone marrow (hematopoietic) depression after whole-body irradiation first appears at approximately what absorbed dose?', '["200 rad (2 Gy)","1000 rad (10 Gy)","500 rad (5 Gy)","100 rad (1 Gy)","2000 rad (20 Gy)"]'::jsonb, '200 rad (2 Gy)', 'The hematopoietic syndrome becomes manifest at whole-body doses of about 2 Gy, as rapidly dividing marrow stem cells are depleted; GI and CNS syndromes require much higher doses.'),
('2fbc54bf-34f9-5724-a546-07a677724882'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Radiation fibrosis is due to:', '["Vascular damage","All","Collagen deposition","Fibroblast proliferation","TGF-beta activation"]'::jsonb, 'All', 'Radiation fibrosis is due to All.'),
('26b75efa-c3b4-5bdc-ba06-c1c08f7c4c7d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'What malignant proliferation involves blood-forming cells?', '["Thyroid cancer","Skin cancer","Lung cancer","Breast cancer","Leukemia"]'::jsonb, 'Leukemia', 'Leukemia is a malignant proliferation of hematopoietic stem cells in the bone marrow, unlike the epithelial tumors listed among the options.'),
('ceb91838-5574-5c40-90f6-103a81a32000'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Chemical injury from carbon tetrachloride primarily affects:', '["Heart","Liver","Brain","Kidney","Lung"]'::jsonb, 'Liver', 'Carbon tetrachloride is bioactivated by hepatic cytochrome P450 to a reactive trichloromethyl radical, so the liver is the principal target and shows centrilobular necrosis.'),
('d6fdb391-1b80-5b44-bb5a-10fc87e3554f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Acetaminophen overdose causes:', '["Centrilobular hepatic necrosis","Pulmonary fibrosis","Pancreatitis","Renal necrosis","Myocardial necrosis"]'::jsonb, 'Centrilobular hepatic necrosis', 'Overdose of acetaminophen generates the reactive metabolite NAPQI, which depletes glutathione and produces centrilobular (zone 3) hepatic necrosis.'),
('048aa4b3-b480-5424-9828-e95b39fe9705'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which agent is the specific antidote for acetaminophen (paracetamol) overdose?', '["N-acetylcysteine","Penicillamine","Vitamin K","Methylene blue","Dimercaprol"]'::jsonb, 'N-acetylcysteine', 'N-acetylcysteine replenishes hepatic glutathione, allowing detoxification of the toxic NAPQI metabolite; it is most effective when begun within 8-10 hours.'),
('2b127f88-16ae-519c-afc5-1ebef8548df7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which pleural tumor is etiologically linked most strongly to asbestos exposure?', '["Carcinoid","Adenocarcinoma","Mesothelioma","Squamous cell carcinoma","Small cell carcinoma"]'::jsonb, 'Mesothelioma', 'Malignant mesothelioma of the pleura is the hallmark asbestos-related neoplasm, appearing decades after occupational exposure to the fibers.'),
('5677931c-a39e-54d4-a78e-d027505fccd3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which inhaled mineral fiber, widely used in insulation, is responsible for pleural disease and interstitial pulmonary fibrosis as well as lung cancer and mesothelioma?', '["Asbestos exposure","Silica exposure","Iron dust","Coal dust exposure","Talc exposure"]'::jsonb, 'Asbestos exposure', 'Asbestos fibers inhaled into the lung cause asbestosis (interstitial fibrosis), pleural plaques and effusions, and raise the risk of bronchogenic carcinoma and mesothelioma.'),
('445129ec-9b4c-5b72-a9a4-68d67ceb686a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Silicosis is caused by inhalation of:', '["Coal dust","Cotton dust","Iron dust","Asbestos","Silica (SiO2)"]'::jsonb, 'Silica (SiO2)', 'Silicosis is caused by inhalation of Silica (SiO2).'),
('3cefa91d-0033-5491-93d4-7d66ecc90f98'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which occupation is associated with silicosis?', '["Construction","Mining","Glass manufacturing","All","Sandblasting"]'::jsonb, 'All', 'Crystalline silica dust is encountered in mining, sandblasting, construction and glass manufacture, so workers in all of these trades are at risk of silicosis.'),
('75d0e27f-781b-580d-9cc4-f4e400dbadf8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Coal workers pneumoconiosis is characterized by:', '["Dyspnea","Caplan syndrome","All","Progressive massive fibrosis","Coal macules"]'::jsonb, 'All', 'Coal workers pneumoconiosis is characterized by All.'),
('c59ded73-57fc-55f7-85e6-9373ce0d7d7e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Byssinosis (''brown lung''), with Monday-morning chest tightness in textile workers, is caused by inhalation of:', '["Silica","Cotton dust","Iron","Asbestos","Coal dust"]'::jsonb, 'Cotton dust', 'Byssinosis results from inhaled cotton dust (and flax or hemp) in textile mills, producing bronchospasm and chronic airflow obstruction distinct from the pneumoconioses.'),
('15153515-7efe-5847-8587-af11bd9664de'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Lead poisoning causes:', '["Microcytic anemia","Neuropathy","All","Basophilic stippling","Abdominal colic"]'::jsonb, 'All', 'Lead poisoning inhibits heme synthesis and damages nerves and the gut, causing microcytic anemia with basophilic stippling, peripheral neuropathy and abdominal colic.'),
('1d607324-b1ea-51b8-a869-65c49f56c2eb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Basophilic stippling in RBCs is characteristic of:', '["Iron deficiency","Thalassemia","B12 deficiency","Lead poisoning","Folate deficiency"]'::jsonb, 'Lead poisoning', 'Basophilic stippling in RBCs is characteristic of Lead poisoning.'),
('424f2e22-e8d4-5da2-94ce-2ff4c4fc0b76'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The definitive management of symptomatic lead poisoning is:', '["Vitamin C","Chelation therapy","N-acetylcysteine","Methylene blue","Dimercaprol"]'::jsonb, 'Chelation therapy', 'Chelating agents such as DMSA or calcium disodium EDTA bind lead and increase its urinary excretion; they are the specific treatment for lead intoxication.'),
('9c0e4f81-d5a6-53f4-8443-8cf8b27b3907'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Arsenic poisoning causes:', '["Peripheral neuropathy","Vascular disease","Mees lines (white nail bands)","All","Skin hyperkeratosis"]'::jsonb, 'All', 'Chronic arsenic poisoning produces skin hyperkeratosis, Mees lines, peripheral neuropathy and vascular disease, as well as skin and visceral cancers.'),
('959690db-ef6e-50aa-8086-3ba9530ae3eb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Chronic arsenic exposure is implicated in the causation of which of the following cancers?', '["Liver cancer","Lung cancer","Skin cancer","All","Bladder cancer"]'::jsonb, 'All', 'Arsenic is a carcinogen associated with skin, lung, bladder and liver cancers, in addition to its vascular and neurologic toxicity.'),
('e8cae599-6b7f-558e-87e8-09dfb4d47692'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Mercury poisoning (Minamata disease) primarily affects:', '["Liver","Lungs","Kidneys","Bone marrow","Nervous system"]'::jsonb, 'Nervous system', 'Organic mercury poisoning (Minamata disease) preferentially damages the nervous system, causing ataxia, dysarthria, visual-field constriction and peripheral sensory loss.'),
('468d4c0a-ad2d-5f61-a4b4-73643694f439'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The first-degree burn involves:', '["Bone","Subcutaneous tissue","Muscle","Dermis","Epidermis only"]'::jsonb, 'Epidermis only', 'A first-degree burn is confined to the epidermis, producing erythema and pain without blistering or tissue loss.'),
('33bbaa8b-0377-5b90-afda-6b8b06cc3035'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A partial-thickness (second-degree) burn characteristically involves which tissue layers?', '["Muscle","Epidermis only","Subcutaneous tissue","Full skin","Epidermis and dermis"]'::jsonb, 'Epidermis and dermis', 'Second-degree burns destroy the epidermis and extend into the dermis, producing painful blisters; healing proceeds from residual dermal appendages.'),
('6aefa8a4-0c37-58c0-bd3e-40a6233daaec'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Third-degree (full thickness) burn destroys:', '["Dermis","Muscle","Subcutaneous tissue","Epidermis","All skin layers"]'::jsonb, 'All skin layers', 'Third-degree (full-thickness) burns destroy the entire epidermis and dermis and often deeper structures, producing a painless, charred, leathery surface.'),
('50c6c2bd-4e30-529a-ae0d-f55d73b349dc'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In electrical injuries, which is the usual mechanism of death?', '["Cardiac arrhythmia","Skin necrosis","Infection","Neurologic damage","Renal failure"]'::jsonb, 'Cardiac arrhythmia', 'Electric current passing through the heart precipitates ventricular fibrillation, the leading cause of death in electrical accidents.'),
('02f26799-d7d2-5bb3-b4d5-97a86cea9cc8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The severity and pattern of an electrical injury are determined jointly by:', '["All","Current","Pathway through body","Duration of contact","Voltage"]'::jsonb, 'All', 'Electrical injury severity depends on current strength, voltage, the pathway through the body, the duration of contact and tissue resistance - so all the factors listed.'),
('8e8faa4d-9239-5965-8f4e-de6fac2c3aa6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Lightning strike most commonly causes:', '["Hearing loss","Skin burns","Blunt trauma","Neurologic damage","Cardiac arrest"]'::jsonb, 'Cardiac arrest', 'Lightning delivers a massive direct current that depolarizes the myocardium, and cardiac arrest is the most common fatal event; it is often reversible with prompt resuscitation.'),
('82d71b1d-d836-5a6e-9c75-b072600f4731'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The rule of nines for burns assigns what percentage to each arm?', '["9%","4.5%","18%","1%","3%"]'::jsonb, '9%', 'According to the rule of nines, each upper limb represents 9% of the total body surface area, the head 9%, the trunk 36%, each lower limb 18% and the perineum 1%.'),
('78439d44-78cf-5317-af76-957ab4a00c93'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common cause of death in burn patients is:', '["Respiratory failure","Shock","Renal failure","Infection and sepsis","Fluid imbalance"]'::jsonb, 'Infection and sepsis', 'The most common cause of death in burn patients is Infection and sepsis.'),
('2323df0b-cde4-5ba9-b670-01164d01d9a2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Thermal burns cause which type of necrosis?', '["Fat necrosis","Caseous necrosis","Fibrinoid necrosis","Coagulative necrosis","Liquefactive necrosis"]'::jsonb, 'Coagulative necrosis', 'Heat denatures cellular proteins, so thermal burns characteristically produce coagulative necrosis of the skin.'),
('0d13e5f9-bd11-5db4-aade-3e161765eaa9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which combination of clinical features may be produced by carbon monoxide poisoning?', '["All","Cherry-red skin","Lactic acidosis","Confusion","Headache"]'::jsonb, 'All', 'CO occupies the oxygen-binding sites on hemoglobin, producing tissue hypoxia with headache, confusion and lactic acidosis; classic cherry-red skin may accompany severe poisoning.'),
('0437262c-fe03-579f-9c89-b7351cd7845c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Carbon monoxide binds to hemoglobin with approximately how many times the affinity of oxygen?', '["200","50","100","250","300"]'::jsonb, '250', 'The affinity of hemoglobin for carbon monoxide is about 200-250 times its affinity for oxygen, so exposure to CO rapidly displaces oxygen carriage.'),
('b7782448-5053-5b7b-a249-0e53f1037988'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In severe carbon monoxide poisoning (coma, neurologic deficit, or pregnancy), which treatment is recommended?', '["Hyperbaric oxygen","Chelation","100% oxygen","Methylene blue","N-acetylcysteine"]'::jsonb, 'Hyperbaric oxygen', 'Hyperbaric oxygen rapidly displaces CO and shortens the carboxyhemoglobin half-life to about 20 minutes, reducing delayed neurologic injury; 100% oxygen suffices for milder cases.'),
('63ee2e1e-fc22-5109-a217-a5eedb3da04d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which organ is most sensitive to radiation injury?', '["GI tract","Lung","Skin","Bone marrow","Kidney"]'::jsonb, 'Bone marrow', 'Bone marrow is the most radiosensitive organ because its continuously dividing stem cells are destroyed at low doses, dominating the acute radiation syndrome.'),
('7a537cc1-d995-597c-ae08-91bfe7fefc76'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Acute radiation syndrome with GI symptoms occurs at:', '["4-6 Gy","6-8 Gy","> 10 Gy","2-4 Gy","1-2 Gy"]'::jsonb, '4-6 Gy', 'At whole-body doses of about 4-6 Gy, gastrointestinal symptoms such as vomiting and diarrhoea dominate as the rapidly dividing gut epithelium is denuded.'),
('a898dbbc-d4be-5d4d-b6ed-6c4eea9c51df'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The LD50 for whole-body radiation without treatment is about:', '["4.5 Gy","2.5 Gy","8 Gy","6 Gy","1 Gy"]'::jsonb, '4.5 Gy', 'The LD50 for whole-body radiation without treatment is about 4.5 Gy.'),
('2ba5d2f7-6e16-542a-bf13-7dad6277e636'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Radiation pneumonitis following thoracic irradiation most commonly develops at which interval?', '["6-12 months","1-3 months","1-2 weeks","2 years","2-4 weeks"]'::jsonb, '1-3 months', 'Acute radiation pneumonitis typically peaks 2-3 months after thoracic irradiation; pulmonary fibrosis appears later, over months to years.'),
('fb8044db-e1de-59bb-800a-f496b3dcb3a9'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is a radiosensitizer?', '["Vitamin C","Oxygen","Vitamin E","Beta-carotene","Glutathione"]'::jsonb, 'Oxygen', 'Oxygen is the key radiosensitizer: molecular oxygen fixes radiation-induced radical damage to DNA, so oxygenated cells are more sensitive to a given radiation dose than hypoxic cells.'),
('15a74e87-c34f-5358-95d2-075650b65f92'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The oxygen enhancement ratio, the factor by which the radiation dose must be increased for hypoxic cells to show the same effect as oxygenated cells, is approximately:', '["1.5-2","3.5-4","2.5-3","4.5-5","5.5-6"]'::jsonb, '2.5-3', 'Hypoxic cells are about 2.5-3 times more radioresistant than fully oxygenated cells, the oxygen enhancement ratio that underlies fractionated radiotherapy.'),
('7f08122d-a70b-5261-b41c-84232e18da2c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which type of radiation burn is caused by UV radiation?', '["Fourth-degree","First-degree","Third-degree","Radiation dermatitis","Second-degree"]'::jsonb, 'Radiation dermatitis', 'Radiation dermatitis is the mechanism or cause responsible for the finding described.'),
('abe5c9ec-a011-55d1-9237-efd70e5a723d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Megaloblastic anemia in chronic alcoholics is most often attributable to deficiency of which micronutrient?', '["B6","Folic acid","B1","A","B12"]'::jsonb, 'Folic acid', 'Alcohol impairs folate absorption, storage and metabolism, so folate deficiency is the usual cause of megaloblastic anemia in alcohol-dependent patients.'),
('7327120c-8755-5281-8a7c-9f00bc23ac4f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Cigarette smoking increases risk of all EXCEPT:', '["Ovarian cancer","Lung cancer","Bladder cancer","Pancreatic cancer","Cervical cancer"]'::jsonb, 'Ovarian cancer', 'Cigarette smoking raises the risk of lung, bladder, pancreatic and cervical cancers, but ovarian cancer is not among the neoplasms causally related to smoking.'),
('f59f003a-ba5b-59ea-b820-a4104063abd8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which alcohol-related liver disease has the worst prognosis?', '["Cirrhosis","Alcoholic hepatitis","Fatty liver","Fibrosis","All equal"]'::jsonb, 'Cirrhosis', 'Cirrhosis is the end stage of alcoholic liver disease with irreversible fibrosis and loss of function, so it carries the worst prognosis of the listed stages.'),
('c92e8373-01a1-5c6e-8740-f88500e55f59'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Among patients with established alcoholic cirrhosis, which is the most frequent cause of death?', '["Trauma","Cardiomyopathy","Pancreatitis","Liver failure","Cancer"]'::jsonb, 'Liver failure', 'Hepatic decompensation with liver failure is the leading terminal event in cirrhosis, although variceal hemorrhage and hepatocellular carcinoma also contribute.'),
('f9aecaa8-2845-5fab-9373-f06efd8d0191'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Wernicke-Korsakoff syndrome, presenting with ataxia, ophthalmoplegia and a confusional state in alcoholics, results from deficiency of:', '["Thiamine (B1)","Niacin (B3)","B12","Vitamin C","Folate"]'::jsonb, 'Thiamine (B1)', 'Wernicke encephalopathy and its Korsakoff residue are caused by thiamine (vitamin B1) deficiency, common in alcoholism because of poor diet and impaired absorption.'),
('f9fcd731-4822-519a-b40f-2282673e1601'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Pellagra developing in chronic alcoholics reflects deficiency of:', '["Folate","B6","B12","B3 (niacin)","B1"]'::jsonb, 'B3 (niacin)', 'Niacin deficiency in drinkers with poor, monotonous diets underlies pellagra, with its dermatitis, diarrhea and dementia.'),
('a6e2928c-80d0-58ae-b07d-4e822a783db7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Rheumatoid arthritis is characterised by:', '["Anti-CCP and rheumatoid factor (IgM anti-IgG)","Anti-dsDNA accompanied by associated clinical symptoms","Anti-Smith mediated by specific receptor activation","Anti-centromere without affecting the primary tissue pathway","ANCA leading to subsequent cellular adaptation"]'::jsonb, 'Anti-CCP and rheumatoid factor (IgM anti-IgG)', 'Anti-CCP is most specific for RA.'),
('31637849-1330-52c8-931b-ff5eb6bf75a5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which hepatitis virus most frequently establishes chronic infection that progresses to cirrhosis and hepatocellular carcinoma?', '["EBV","Hepatitis B","Hepatitis C","HIV","CMV"]'::jsonb, 'Hepatitis C', 'Hepatitis C virus becomes chronic in 70-85% of infected persons and is a leading cause of cirrhosis and hepatocellular carcinoma.'),
('85fd2905-70fa-5766-a19c-36d72c8c6732'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Hepatocellular carcinoma risk is increased by:', '["All","Hemochromatosis","Alcohol","Hepatitis B","Aflatoxin"]'::jsonb, 'All', 'Hepatocellular carcinoma risk is increased by All.'),
('e464c3c3-fc57-58bd-bf14-b56cc5d7eada'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Aflatoxin, one of the most potent dietary hepatocarcinogens, is a product of which fungus that contaminates stored grain?', '["Aspergillus flavus","Penicillium","Candida","Cryptococcus","Fusarium"]'::jsonb, 'Aspergillus flavus', 'Aspergillus flavus (and A. parasiticus) elaborates aflatoxin B1, which after hepatic bioactivation is a major risk factor for hepatocellular carcinoma.'),
('fb7baad7-eed3-5fed-bc07-d8b6c2abd8e6'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Nonalcoholic fatty liver disease, steatohepatitis and their progression toward cirrhosis are most strongly driven by:', '["Iron deficiency","Obesity","Vitamin A deficiency","Marasmus","Kwashiorkor"]'::jsonb, 'Obesity', 'Obesity is the principal driver of nonalcoholic fatty liver disease; obesity-related insulin resistance promotes steatohepatitis and progressive fibrosis.'),
('e3f8c56d-eea0-5dd3-8943-d40c98d74d23'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Type IV hypersensitivity (delayed) is mediated by:', '["T cells (Th1 and macrophages)","IgE accompanied by associated clinical symptoms","IgG mediated by specific receptor activation","IgM without affecting the primary tissue pathway","Complement leading to subsequent cellular adaptation"]'::jsonb, 'T cells (Th1 and macrophages)', 'Tuberculin skin test is a classic example.'),
('4b4623e1-fd2f-55b6-98da-93093dbe1279'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which laboratory abnormality is NOT one of the defining criteria of the metabolic syndrome?', '["High fasting glucose","High triglycerides","Hypertension","Central obesity","High LDL"]'::jsonb, 'High LDL', 'The metabolic syndrome is defined by central obesity, elevated fasting glucose, hypertriglyceridemia, low HDL and hypertension; a high LDL is not a defining criterion.'),
('f385a24b-04ea-539b-8b27-9528a443eadd'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Adipose tissue is an endocrine organ secreting:', '["IL-6","TNF-alpha","Adiponectin","Leptin","All"]'::jsonb, 'All', 'Adipose tissue is an endocrine organ secreting All.'),
('c61524e8-2eec-5b91-ab5b-f9e2d38f7012'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In the study of General Pathology Pt1, Granulomatous inflammation is characteristic of:', '["Tuberculosis and sarcoidosis","Acute appendicitis","Viral hepatitis","Pneumonia","Pyogenic abscess"]'::jsonb, 'Tuberculosis and sarcoidosis', 'Epithelioid histiocytes and multinucleated giant cells.'),
('3818754a-76c4-5e1c-89ce-7c39da6939a8'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'From a pathophysiological standpoint regarding General Pathology Pt1: Type I hypersensitivity (allergic) is mediated by:', '["IgE antibodies","IgG antibodies","IgM antibodies","T cells","Complement"]'::jsonb, 'IgE antibodies', 'IgE binds mast cell FcεRI, cross-linking triggers degranulation.'),
('2889ea8f-f2f1-5db4-9032-6ac02639c144'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Homozygous familial hypercholesterolemia presents with:', '["Aortic stenosis","Arcus corneae","CAD in childhood","Xanthomas","All"]'::jsonb, 'All', 'Homozygous familial hypercholesterolemia presents in childhood with tendon xanthomas, arcus corneae, premature coronary artery disease and supravalvular aortic stenosis.'),
('d2ded0bd-50b4-556d-8163-8494c4171bcf'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which is the strongest risk factor for venous thrombosis?', '["Protein C deficiency","Antithrombin deficiency","Prothrombin G20210A","Factor V Leiden","Protein S deficiency"]'::jsonb, 'Factor V Leiden', 'Factor V Leiden, which renders factor Va resistant to activated protein C, is the most frequent inherited thrombophilia and the commonest genetic cause of venous thrombosis.'),
('99db3955-e9b7-5272-82a5-43904bb5059d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The hallmark clinical event of the antiphospholipid syndrome is:', '["ITP","Bleeding","DIC","Thrombosis","Hemophilia"]'::jsonb, 'Thrombosis', 'Antiphospholipid syndrome is dominated by arterial and venous thrombosis (and recurrent pregnancy loss), so thrombosis is its central clinical manifestation.'),
('181dbed3-691b-5b98-907b-e53bb6fa8faa'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Clinical and laboratory features of the antiphospholipid syndrome include:', '["Pregnancy loss","Recurrent thrombosis","Prolonged aPTT","Livedo reticularis","All"]'::jsonb, 'All', 'The antiphospholipid syndrome shows recurrent thrombosis, pregnancy loss, livedo reticularis and a prolonged aPTT from the lupus anticoagulant, so all the listed findings occur.'),
('d4c07fad-bd8c-599a-9e65-8619d84e8156'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which antibody is associated with antiphospholipid syndrome?', '["Anti-cardiolipin","Anti-dsDNA","Lupus anticoagulant","All","Anti-beta2 glycoprotein I"]'::jsonb, 'All', 'Antiphospholipid syndrome is defined by antibodies to cardiolipin and beta2-glycoprotein I and by the lupus anticoagulant, all of which are phospholipid-dependent antibodies.'),
('a2363953-9aea-52f5-8571-797e2546d2ac'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which single inherited disorder is the most common cause of a congenital bleeding tendency?', '["Hemophilia B","ITP","von Willebrand disease","Factor XI deficiency","Hemophilia A"]'::jsonb, 'von Willebrand disease', 'Von Willebrand disease, with a prevalence of about 1%, is the most common inherited bleeding disorder, reflecting defective platelet adhesion with or without low factor VIII.'),
('c0573e5f-2c36-5c54-8831-16d3a885ae2a'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which factor deficiency is common in Ashkenazi Jews?', '["Factor XI","Factor IX","Factor XII","vWF","Factor VIII"]'::jsonb, 'Factor XI', 'Factor XI deficiency (hemophilia C) is inherited as an autosomal recessive trait that is particularly common in persons of Ashkenazi Jewish descent.'),
('e124db14-a0b6-5f9e-ad68-2100768ab692'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In Hageman (factor XII) deficiency, the coagulation screening profile characteristically shows:', '["Both prolonged aPTT and bleeding","Prolonged aPTT without bleeding","Bleeding","Thrombosis","Normal labs"]'::jsonb, 'Prolonged aPTT without bleeding', 'Factor XII deficiency prolongs the aPTT via the intrinsic pathway but is not accompanied by clinical bleeding, because factor XII is not required for in vivo hemostasis.'),
('92df53e3-8857-55f0-a687-af68c71e7b3d'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Ethanol is metabolized in the body through which of the following enzyme systems?', '["CYP2E1","Alcohol dehydrogenase","All","Catalase","Aldehyde dehydrogenase"]'::jsonb, 'All', 'Alcohol is oxidized by alcohol dehydrogenase, the microsomal CYP2E1 (MEOS) and catalase to acetaldehyde, which aldehyde dehydrogenase then clears; all the listed enzymes participate.'),
('8370f9dd-46b9-53c8-a0b6-3dd2070a1bc1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Long-term alcohol excess damages cells and tissues through which combination of mechanisms?', '["Collagen deposition","All","Mitochondrial damage","Protein adduct formation","Fatty liver"]'::jsonb, 'All', 'Chronic alcohol causes intrahepatic steatosis, acetaldehyde-protein adduct formation, mitochondrial damage and collagen accumulation (fibrosis), so all the listed mechanisms operate.'),
('46203fee-3021-5531-ae21-08757b537769'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The most common cause of acute pancreatitis is:', '["Hypertriglyceridemia","Alcohol","Trauma","Drugs","Gallstones"]'::jsonb, 'Gallstones', 'The most common cause of acute pancreatitis is Gallstones.'),
('f9624ef8-9ec5-560e-af15-35acb362fec5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Alcoholic cardiomyopathy is characterized by:', '["Dilated cardiomyopathy","Arrhythmogenic cardiomyopathy","Hypertrophic cardiomyopathy","Restrictive cardiomyopathy","Takotsubo cardiomyopathy"]'::jsonb, 'Dilated cardiomyopathy', 'Alcoholic cardiomyopathy is characterized by Dilated cardiomyopathy.'),
('e8eb98dc-84ba-511a-b9ff-fa1181cc784e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The beriberi that presents with a painful peripheral neuropathy (dry form) or high-output heart failure (wet form) is caused by deficiency of:', '["B12","B6","Folate","Niacin","B1"]'::jsonb, 'B1', 'Thiamine (vitamin B1) deficiency causes beriberi in its neurologic (dry) and cardiac (wet) forms as well as the Wernicke-Korsakoff syndrome.'),
('5d42ad1e-9522-597e-a0b6-dc2d05cc8730'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Sideroblastic anemia can be caused by:', '["Alcohol","Copper deficiency","Vitamin B6 deficiency","All","Lead poisoning"]'::jsonb, 'All', 'Sideroblastic anemia follows interference with heme synthesis by alcohol, isoniazid, lead poisoning and vitamin B6 or copper deficiency, so all the listed causes apply.'),
('f9d90486-f05b-5c5a-9d04-ca1bc4d32512'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The ring sideroblasts seen in sideroblastic anemia arise because of:', '["Iron deficiency","Folate deficiency","B12 deficiency","Anemia of chronic disease","Impaired heme synthesis"]'::jsonb, 'Impaired heme synthesis', 'A defect in heme synthesis leaves iron that cannot be incorporated into protoporphyrin, so it accumulates in mitochondria around the nucleus, producing ring sideroblasts.'),
('38cf0730-4010-5b8d-a42a-aa1046d9d108'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The megaloblastic anemia complicating cobalamin malabsorption and the megaloblastic anemia of pregnancy are both corrected when adequate supplies of which micronutrients are provided?', '["Zinc","Vitamin A","Vitamin C","B12 and folate","Iron"]'::jsonb, 'B12 and folate', 'Both vitamin B12 and folate are required for DNA synthesis, so deficiencies of either produce megaloblastic anemia; both must be replenished.'),
('50fe1730-2138-567c-8e3f-ac115bd78d95'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'During therapeutic management, Amyloid is characterised by:', '["Beta-pleated sheet protein aggregation","Alpha-helical protein aggregation","Lipid accumulation","Glycogen accumulation","Calcium deposits"]'::jsonb, 'Beta-pleated sheet protein aggregation', 'Misfolded proteins forming insoluble fibrils.'),
('73de591c-15a4-5e66-a1bc-538b2df8ba54'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The bone marrow in untreated megaloblastic anemia characteristically shows:', '["Increased apoptosis","All","Nuclear-cytoplasmic asynchrony","Giant metamyelocytes","Megaloblasts"]'::jsonb, 'All', 'The megaloblastic marrow contains megaloblastic erythroid precursors, giant metamyelocytes, nuclear-cytoplasmic asynchrony and increased apoptosis due to ineffective hematopoiesis, so all the features are present.'),
('c7057db8-31d9-5861-98e5-994b31f6cbdb'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which antioxidant enzyme is selenium dependent and catalytically reduces hydrogen peroxide and organic peroxides?', '["Cytochrome c oxidase","Catalase","Glutathione peroxidase","Alcohol dehydrogenase","Superoxide dismutase"]'::jsonb, 'Glutathione peroxidase', 'Glutathione peroxidase is a selenoenzyme that reduces hydrogen peroxide and lipid peroxides, which explains the antioxidant function of selenium.'),
('7ec6114a-63b6-5fc4-96d6-015431069515'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Zinc finger proteins are involved in:', '["Cell signaling","All","Apoptosis","Transcription regulation","DNA binding"]'::jsonb, 'All', 'Zinc finger proteins are involved in All.'),
('281e7b64-fa07-515f-be38-1769e7e3bba7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Copper is a cofactor for:', '["Tyrosinase","Superoxide dismutase","Cytochrome c oxidase","Lysyl oxidase","All"]'::jsonb, 'All', 'Copper is a cofactor for All.'),
('b1d4d4c1-f688-5a1d-bb25-48be8f43aca5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Iodine is essential for synthesis of:', '["Triiodothyronine (T3)","Calcitonin","TSH","Thyroxine (T4)","TRH"]'::jsonb, 'Triiodothyronine (T3)', 'Iodine is essential for synthesis of Triiodothyronine (T3).'),
('63317cae-ca71-51d3-b4c0-a5b65e04ad8f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The morphologic spectrum of endemic (iodine-deficiency) goiter from early to late stages includes:', '["Diffuse hyperplasia","Colloid accumulation","Papillary growth","All","Nodularity"]'::jsonb, 'All', 'Iodine-deficient goiter evolves from diffuse follicular hyperplasia, through colloid accumulation, to a nodular goiter with papillary projections, so all the listed patterns are seen.'),
('1782a829-858e-54fb-9483-86ab8fcfe559'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is the earliest clinical manifestation of vitamin A deficiency?', '["Keratomalacia","Xerophthalmia","Night blindness","Bitot spots","Follicular hyperkeratosis"]'::jsonb, 'Night blindness', 'Depleted vitamin A impairs rhodopsin regeneration first, causing impaired dark adaptation (night blindness) before any conjunctival or corneal changes appear.'),
('8941f119-329b-5320-a656-a441790b6e7f'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'From a pathophysiological standpoint, Rheumatoid arthritis is characterised by:', '["Anti-CCP and rheumatoid factor (IgM anti-IgG)","Anti-dsDNA accompanied by associated clinical symptoms","Anti-Smith mediated by specific receptor activation","Anti-centromere without affecting the primary tissue pathway","ANCA leading to subsequent cellular adaptation"]'::jsonb, 'Anti-CCP and rheumatoid factor (IgM anti-IgG)', 'Anti-CCP is most specific for RA.'),
('a0a4f8f3-f397-5d7d-a0f6-4563fe8ff5b3'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The ''rachitic rosary'' of rickets refers clinically to:', '["Beading of costochondral joints","Harrison sulcus","Wrist widening","Frontal bossing","Bowing of legs"]'::jsonb, 'Beading of costochondral joints', 'Enlargement of the costochondral junctions produces the palpable beading of the ribs known as the rachitic rosary in rickets.'),
('774fd30a-34e8-5ad7-a687-db631decc1f2'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The soft, thin cranial bones that indent on pressure in infantile rickets are described as craniotabes and represent:', '["Suture separation","Depressed fontanelles","Skull asymmetry","Enlarged skull","Softening of skull bones"]'::jsonb, 'Softening of skull bones', 'Craniotabes is the localized softening of the skull bones in rickets, as undermineralized calvaria yields to pressure.'),
('12776d96-2186-5c15-aba5-ed4ac472d716'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Defective mineralization of otherwise normal osteoid in adults, due to vitamin D deficiency, is termed:', '["Paget disease","Osteomalacia","Renal osteodystrophy","Rickets","Osteoporosis"]'::jsonb, 'Osteomalacia', 'Osteomalacia is the adult counterpart of rickets: osteoid is laid down but fails to mineralize, causing soft, painful bones with pseudofractures.'),
('8dc2d639-f7a4-50d2-8f85-e3269a9769ae'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'A 50-year-old female presents with a wound that is erythematous, warm, and has purulent drainage. What is the primary source of this pathology?', '["Angiogenesis","Collagen synthesis","Wound contraction","Matrix deposition","Epithelialization"]'::jsonb, 'Collagen synthesis', 'Collagen synthesis is the definition or term that matches this concept.'),
('ce9f9c45-c8fe-52a6-a72d-c68d53a38dde'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following is a feature of scurvy?', '["Gingival hyperplasia","All","Impaired bone growth","Perifollicular hemorrhages","Ecchymoses"]'::jsonb, 'All', 'Vitamin C deficiency (scurvy) impairs collagen synthesis, causing perifollicular hemorrhages, ecchymoses, gingival hyperplasia and impaired bone growth.'),
('6bae796b-ce92-5d65-8be0-48f874e8fbba'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Concerning diagnostic evaluations: BRCA1/2 mutations increase risk of:', '["Breast and ovarian cancer","Lung cancer","Colon cancer","Prostate cancer","Leukaemia"]'::jsonb, 'Breast and ovarian cancer', 'Hereditary breast-ovarian cancer syndrome.'),
('64e67a0f-f47a-556c-bfa9-65bd735f31a7'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Xerophthalmia with dryness of the conjunctiva and cornea is caused by deficiency of which vitamin?', '["Vitamin A","Vitamin B12","Vitamin C","Folate","Vitamin D"]'::jsonb, 'Vitamin A', 'Conjunctival and corneal dryness (xerophthalmia) reflects vitamin A deficiency and advances to Bitot spots and keratomalacia when severe.'),
('269c9b31-1ecb-543b-9897-a74c49b10eec'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which sequence correctly represents the progressive ocular changes of vitamin A deficiency?', '["Night blindness -> keratomalacia resulting in decreased functional activity","Keratomalacia -> xerophthalmia -> night blindness accompanied by associated clinical symptoms","Night blindness -> conjunctival xerosis -> Bitot spots -> corneal xerosis -> keratomalacia","Conjunctivitis -> keratitis without affecting the primary tissue pathway","Conjunctival xerosis -> Bitot spots -> night blindness leading to subsequent cellular adaptation"]'::jsonb, 'Night blindness -> conjunctival xerosis -> Bitot spots -> corneal xerosis -> keratomalacia', 'Vitamin A-deficient eye disease advances from night blindness to conjunctival xerosis, Bitot spots, corneal xerosis and finally keratomalacia.'),
('057a71d2-51c0-578e-a61f-9ed77bcbcdba'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The toxicity of carbon monoxide is due primarily to its:', '["Decreasing 2","3-BPG","Competitive binding to hemoglobin","Inhibiting cytochrome c oxidase","Forming methemoglobin"]'::jsonb, 'Competitive binding to hemoglobin', 'Carbon monoxide competes with oxygen for binding to heme, forming carboxyhemoglobin with much higher affinity and shifting the oxyhemoglobin dissociation curve to impair oxygen delivery.'),
('6c646430-f15c-53d5-97b8-7882bfb54aed'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which of the following can oxidize ferrous hemoglobin iron and thereby cause methemoglobinemia?', '["Benzocaine","Aniline dyes","Dapsone","All","Nitrates"]'::jsonb, 'All', 'Nitrates, benzocaine, dapsone and aniline dyes can oxidize the ferrous iron of hemoglobin to the ferric state, producing methemoglobinemia with impaired oxygen carriage.'),
('55dc859d-fe9e-5584-b781-b59afa23c9ae'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The established treatment for symptomatic methemoglobinemia is:', '["N-acetylcysteine","Vitamin C","Hyperbaric oxygen","Chelation","Methylene blue"]'::jsonb, 'Methylene blue', 'Methylene blue is reduced to leukomethylene blue, which converts methemoglobin back to functional hemoglobin; it is avoided in glucose-6-phosphate dehydrogenase deficiency.'),
('83e9c06a-b80e-5ee2-8e1b-59a5d982670e'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Antidotes that may be used in the treatment of cyanide poisoning include:', '["All","Sodium thiosulfate","Hydroxocobalamin","Dicobalt edetate","Amyl nitrite"]'::jsonb, 'All', 'Cyanide poisoning is treated with nitrites (amyl nitrite), hydroxocobalamin, dicobalt edetate and sodium thiosulfate; the choice depends on availability and severity.'),
('63a6c7ce-7c1d-5517-98c7-ecb8c66410b1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Cyanide inhibits which enzyme?', '["Succinate dehydrogenase","Alcohol dehydrogenase","Cytochrome P450","Catalase","Cytochrome c oxidase"]'::jsonb, 'Cytochrome c oxidase', 'Cyanide binds to the ferric iron of cytochrome c oxidase in complex IV of the respiratory chain, blocking oxidative phosphorylation and producing cytotoxic (histotoxic) hypoxia.'),
('52affb56-5c41-5dde-88bb-03cad6f0f3d5'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The brown fumes released from fresh silage cause an acute chemical pneumonitis known as silo filler''s disease. Which gas is responsible?', '["Carbon monoxide","Ammonia","Sulfur dioxide","Nitrogen dioxide","Ozone"]'::jsonb, 'Nitrogen dioxide', 'Nitrogen dioxide generated in freshly filled silos is inhaled to produce acute chemical pneumonitis and pulmonary edema, the basis of silo filler''s disease.'),
('a9f31d21-7046-580a-8f26-65d5ab1763ae'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Byssinosis is also known as:', '["Brown lung","Bird fanciers lung","Farmer lung","White lung","Black lung"]'::jsonb, 'Brown lung', 'Byssinosis is also known as Brown lung.'),
('a0221b85-4ad1-5a24-a587-d96eb9fe0d7b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Farmer''s lung, a hypersensitivity pneumonitis from working with moldy hay, is provoked by spores of which organism?', '["Asbestos","Silica","Aspergillus species","Thermophilic actinomycetes","Cotton dust"]'::jsonb, 'Thermophilic actinomycetes', 'Thermophilic actinomycetes growing in damp, moldy hay provide the antigens that cause farmer''s lung, an immune-mediated hypersensitivity pneumonitis.'),
('9780f466-6c35-5b92-aa33-c483fa5fd402'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which is a cause of hypersensitivity pneumonitis?', '["All","Humidifier fever","Bird fanciers lung","Farmers lung","Bagassosis"]'::jsonb, 'All', 'Hypersensitivity pneumonitis includes farmer''s lung (thermophilic actinomycetes), bird fancier''s lung, bagassosis from moldy sugar cane and humidifier fever, so all the listed forms qualify.'),
('813e6dde-6e80-52a6-8f94-6b94d94c40ce'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'The association of cigarette smoking with malignancy is strongest for which tumor?', '["Bladder cancer","Skin cancer","Mesothelioma","Lung cancer","Leukemia"]'::jsonb, 'Lung cancer', 'Lung cancer is the smoking-associated tumor with the highest relative risk - roughly 90% of cases are attributable to smoking - exceeding bladder and skin cancers.'),
('3806386c-30c0-54a2-9e18-c7634b67ba63'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Underground miners exposed to radon decay products are at increased risk of which malignancy?', '["Mesothelioma","Lung cancer","Leukemia","Skin cancer","Brain tumor"]'::jsonb, 'Lung cancer', 'Radon, an alpha-emitting decay product of uranium, is a well-established cause of lung cancer, with the risk greatly amplified by concurrent smoking.'),
('e982c829-571a-588e-93c3-48e7837c3db1'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Which burn classification requires skin grafting?', '["First-degree","Third-degree","Both second-degree deep and third-degree","Second-degree deep","Second-degree superficial"]'::jsonb, 'Both second-degree deep and third-degree', 'Deep partial-thickness (deep second-degree) and full-thickness (third-degree) burns have destroyed the dermal elements that would regenerate epithelium, so they require skin grafting; superficial burns heal spontaneously.'),
('d607afd0-e24e-5e52-a1a6-21ff2e8f195c'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'In the initial management of a major burn, rehydration during which period is most critical for preventing hypovolemic burn shock?', '["Time to antibiotic administration","First hour of fluid resuscitation","Time to intubation","Surgical debridement timing","First hour after injury"]'::jsonb, 'First hour of fluid resuscitation', 'Aggressive fluid resuscitation begun within the first hour restores circulating volume and prevents burn shock and acute kidney injury; diagnostic or other delays markedly worsen outcome.'),
('48d6a8a0-6c9c-5da1-8f6c-97b17662041b'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'According to the Parkland formula, crystalloid resuscitation in the first 24 hours after a burn should be administered at a rate of:', '["6 mL/kg/% burn","2 mL/kg/% burn","10 mL/kg/% burn","8 mL/kg/% burn","4 mL/kg/% burn"]'::jsonb, '4 mL/kg/% burn', 'The Parkland formula delivers 4 mL of Ringer''s lactate per kilogram per percent of total body surface area burned in the first 24 hours, half given in the initial 8 hours.'),
('97bf1b8e-149d-5efd-a0e7-925189614c44'::uuid, 'General Pathology Microbiology Immunology (Paper 1)', 'General Pathology - General Pathology Part 1', 'Massive crush of skeletal muscle, as occurs in severe burns or a crush injury, characteristically predisposes to which electrolyte disturbance?', '["Hyponatremia","Hyperkalemia","Hypernatremia","Hypercalcemia","Hypokalemia"]'::jsonb, 'Hyperkalemia', 'Bulk cell lysis releases intracellular potassium, and concurrent oliguric renal failure impairs its excretion, so hyperkalemia - with its arrhythmic risk - is the characteristic emergency.'),
('8b5f56c7-07d8-56d0-a65c-20d31408095c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Edema is defined as:', '["Increased fluid in interstitial space","Increased fluid in vascular compartment","Decreased plasma volume","Cellular swelling","Hemorrhage into tissues"]'::jsonb, 'Increased fluid in interstitial space', 'Edema is an abnormal accumulation of fluid in the interstitial (extracellular) tissue spaces, resulting from an imbalance in the Starling forces across the capillary wall.'),
('f1c0d015-dc78-5371-bfab-a92f696abed1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Anasarca refers to:', '["Severe generalized edema","Pitting edema of ankles","Cerebral edema","Pulmonary edema","Swelling of one limb"]'::jsonb, 'Severe generalized edema', 'Anasarca is severe, generalized edema affecting the subcutaneous tissues and often body cavities, seen in advanced heart, liver, or renal failure.'),
('f0e95edf-73dc-5724-a11f-1c63e22ca962'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pitting edema of the lower limbs is most characteristic of which cause?', '["Filariasis","Lymphatic obstruction","Cardiac failure","Lymphedema","Myxedema"]'::jsonb, 'Cardiac failure', 'Pitting edema reflects low-protein interstitial fluid typical of increased hydrostatic pressure, as in cardiac failure; myxedema and lymphedema are characteristically non-pitting.'),
('c4a1a376-b084-533c-9121-32a1103adf62'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Non-pitting edema is characteristic of:', '["Deep vein thrombosis","Nephrotic syndrome","Congestive heart failure","Cirrhosis","Myxedema and lymphedema"]'::jsonb, 'Myxedema and lymphedema', 'Myxedema (mucinous material) and lymphedema (protein-rich fluid) resist displacement on pressure, so they do not pit; heart failure and nephrotic edema are low-protein and pitting.'),
('7a201c63-c0f5-51f2-809d-8e06feded8c0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pulmonary edema most commonly results from:', '["Malnutrition","Right ventricular failure","Renal failure","Cirrhosis","Left ventricular failure"]'::jsonb, 'Left ventricular failure', 'Left ventricular failure raises pulmonary venous and capillary pressures, forcing fluid into alveolar walls and airspaces; this hemodynamic (cardiogenic) mechanism is the most common cause of pulmonary edema.'),
('8e07b647-c0f1-5562-a16d-6f202cc7193b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hyperemia refers to:', '["Decreased blood flow to a tissue","Active increase in blood flow due to arteriolar dilation","Lack of oxygen","Hemorrhage into tissues","Passive accumulation of blood due to impaired outflow"]'::jsonb, 'Active increase in blood flow due to arteriolar dilation', 'Hyperemia is an active process in which arteriolar dilation increases blood inflow into a tissue (e.g., inflammation, exercise); congestion is the passive form caused by impaired venous outflow.'),
('2dc1a5b5-d84a-51ab-9b24-9e1a8f20c89f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Passive congestion of an organ is caused by:', '["Impaired venous outflow causing passive blood pooling","Active arteriolar dilation accompanied by associated clinical symptoms","Ischemia mediated by specific receptor activation","Decreased blood flow without affecting the primary tissue pathway","Necrosis leading to subsequent cellular adaptation"]'::jsonb, 'Impaired venous outflow causing passive blood pooling', 'Congestion is passive; impaired venous drainage raises capillary and venular pressures, distending the vessels and pooling blood, as in chronic heart failure.'),
('e202518b-2a3e-582c-898a-e5a5d6a77ebf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which combination of histologic findings is the characteristic hallmark of a chronically congested lung in chronic left-sided cardiac decompensation?', '["Emphysematous changes resulting in decreased functional activity","Heart failure cells in alveoli accompanied by associated clinical symptoms","Fibrotic lung parenchyma mediated by specific receptor activation","Brown induration of the lung without affecting the primary tissue pathway","Engorged septal capillaries with hemosiderin-laden macrophages"]'::jsonb, 'Engorged septal capillaries with hemosiderin-laden macrophages', 'Chronic passive congestion of the lung distends and engorges alveolar septal capillaries, and repeated small hemorrhages leave hemosiderin-laden macrophages; together these are the hallmark histologic findings.'),
('68e13f9a-c675-500b-9710-3320f6a0ffde'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Chronic passive congestion of the lungs over many years, with repeated small hemorrhages, produces a firm organ with a rusty-brown color. Which term best names this outcome?', '["Pulmonary edema alone","Brown induration","Honeycomb lung","Gray hepatization","Red hepatization"]'::jsonb, 'Brown induration', 'Repeated episodes of congestion and hemorrhage deposit hemosiderin and induce interstitial fibrosis, leaving the lung firm and rusty brown—the brown induration of chronic passive congestion.'),
('5217837b-0dc2-5a0f-94d5-2b0caff11358'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A patient with long-standing right-sided heart failure has an enlarged, congested liver whose cut surface shows a mottled red-and-tan “nutmeg” pattern. Which diagnosis best describes this liver?', '["Chronic passive congestion of the liver","Acute hepatitis accompanied by associated clinical symptoms","Budd-Chiari syndrome mediated by specific receptor activation","Cirrhosis without affecting the primary tissue pathway","Alcoholic hepatitis leading to subsequent cellular adaptation"]'::jsonb, 'Chronic passive congestion of the liver', 'Right heart failure raises hepatic venous pressure, congesting centrilobular sinusoids; centrilobular atrophy with periportal steatosis produces the mottled “nutmeg” cut surface.'),
('1cfdc515-439d-5d20-bc06-9bcc190602e9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hemorrhage into the pleural cavity is called:', '["Hemothorax","Petechiae","Hemarthrosis","Hemopericardium","Hemoperitoneum"]'::jsonb, 'Hemothorax', 'Hemothorax is blood in the pleural cavity; the prefixes name the cavity, so pleural, pericardial, peritoneal, and joint hemorrhages are respectively hemothorax, hemopericardium, hemoperitoneum, and hemarthrosis.'),
('d792eebe-14da-5176-8b88-9d1a86b4d7f2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pinpoint skin hemorrhages occurring without an external wound are most characteristic of which of the following?', '["Arterial rupture resulting in decreased functional activity","Trauma accompanied by associated clinical symptoms","Low platelet count or defective platelet function","Increased venous pressure without affecting the primary tissue pathway","Vitamin K deficiency leading to subsequent cellular adaptation"]'::jsonb, 'Low platelet count or defective platelet function', 'Petechiae (1–2 mm) are spontaneous hemorrhages that occur when thrombocytopenia or a qualitative platelet defect fails to seal small breaks in the microcirculation.'),
('93c6739c-1d4b-5295-9bf0-1ff32e242572'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Purpuric hemorrhages, larger than petechiae but smaller than ecchymoses, characteristically measure which range?', '["3-10 mm","1-2 mm",">1 cm","<1 mm",">2 cm"]'::jsonb, '3-10 mm', 'Hemorrhages are graded by size: petechiae 1–2 mm, purpura roughly 3–10 mm, and ecchymoses greater than about 1 cm.'),
('eeeadef1-a500-52cd-b74c-f1e00926d545'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hemorrhages exceeding which minimum diameter are conventionally categorized as ecchymoses?', '["5 mm","5 cm","3 cm","1 cm","2 cm"]'::jsonb, '1 cm', 'Ecchymoses are defined as hemorrhages larger than about 1 cm, the threshold that separates them from the smaller purpura.'),
('8d50e0b9-f6f5-5eee-a190-6da083f1ef7d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The most frequent cause of accumulation of blood in the pericardial cavity is:', '["Cardiac tamponade resulting in decreased functional activity","Pericarditis accompanied by associated clinical symptoms","Trauma mediated by specific receptor activation","Aortic dissection without affecting the primary tissue pathway","Myocardial infarction with rupture"]'::jsonb, 'Myocardial infarction with rupture', 'Rupture of a transmural myocardial infarct, usually within the first week, spills blood into the pericardial sac and produces cardiac tamponade that is often rapidly fatal.'),
('96e665f8-5890-55d3-b6b6-e60baa2d5a1e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A thrombus is best defined as:', '["A clot that dislodges and travels resulting in decreased functional activity","A foreign body in blood accompanied by associated clinical symptoms","An embolus mediated by specific receptor activation","A blood clot that forms within the cardiovascular system","A clot that forms in a test tube leading to subsequent cellular adaptation"]'::jsonb, 'A blood clot that forms within the cardiovascular system', 'A thrombus is an in vivo mass of blood constituents in the intact heart or vessels, distinguishing it from a clot that forms after death or in a test tube; an embolus is a detached traveling mass.'),
('68b1b96f-35c2-5e3f-8dcf-6d2e6d90752e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The most important factor in Virchow triad is:', '["Turbulence","Abnormal blood flow","Hypercoagulability","Stasis","Endothelial injury"]'::jsonb, 'Endothelial injury', 'Endothelial injury is the dominant determinant of arterial and cardiac thrombosis and is generally regarded as the most important element of Virchow''s triad.'),
('054c5b0e-32bf-5fe9-8270-34a961c2b128'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Arterial thrombi most commonly occur at sites of:', '["Immobilization","Sites of turbulence (vessel bifurcations)","Factor V Leiden mutation","Atrial fibrillation","Venous stasis"]'::jsonb, 'Sites of turbulence (vessel bifurcations)', 'Arterial thrombi form under rapid flow where turbulence at bifurcations injures the endothelium and creates local stasis, whereas venous thrombosis is dominated by stasis.'),
('e53fc2ca-95d4-5e4e-aeb5-6b1619c10c0d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Thrombi that form in the heart or large arteries, where blood flow is rapid, characteristically display which histologic arrangement?', '["White platelet-rich composition","Calcification","Attachment to arterial wall","Lamination of red cells and fibrin (lines of Zahn)","High platelet content"]'::jsonb, 'Lamination of red cells and fibrin (lines of Zahn)', 'Rapid laminar flow in the heart and arteries produces lines of Zahn, alternating layers of pale platelets/fibrin and dark red cells, indicating an antemortem thrombus.'),
('e913992c-b320-5377-bc4d-4b79c0f47dcc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Lines of Zahn are produced by:', '["Laminar blood flow","Thrombocytopenia","Platelet aggregation","Alternating layers of RBCs and fibrin","Endothelial injury"]'::jsonb, 'Alternating layers of RBCs and fibrin', 'Lines of Zahn consist of alternating pale layers of platelets and fibrin with darker layers of red blood cells, the hallmark of an antemortem arterial or cardiac thrombus.'),
('c4a3b2e1-cde0-50f6-8818-60e07128a0ee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Mural thrombi are most commonly found in:', '["Small arterioles","Cardiac chambers and aorta","Splenic sinusoids","Capillaries","Veins of the leg"]'::jsonb, 'Cardiac chambers and aorta', 'Mural thrombi attach to the walls of the heart chambers and aorta, forming over abnormal endocardium, atherosclerotic plaques, or in turbulent (e.g., atrial fibrillation) flow.'),
('b547edc1-f866-59f9-9127-c8272f0a1ed4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Vegetations on heart valves are a type of:', '["Infective or non-infective thrombotic deposits","Venous thrombus accompanied by associated clinical symptoms","Red thrombus mediated by specific receptor activation","Laminated thrombus without affecting the primary tissue pathway","Mural thrombus leading to subsequent cellular adaptation"]'::jsonb, 'Infective or non-infective thrombotic deposits', 'Valvular vegetations are thrombi on valve surfaces that may be infective (endocarditis) or non-infective (marantic, Libman-Sacks), composed of fibrin, platelets, and bacteria or inflammatory cells.'),
('cb99e9bf-47a8-5f54-8daf-806c879e2279'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Virchow''s triad for thrombosis includes:', '["Stasis, endothelial injury, hypercoagulability","Hypertension, hyperlipidemia, diabetes","Infection, inflammation, immunity","Trauma, haemorrhage, shock","Dehydration, alkalosis, hypoxia"]'::jsonb, 'Stasis, endothelial injury, hypercoagulability', 'Virchow''s triad comprises endothelial injury, abnormal blood flow (stasis or turbulence), and hypercoagulability, the three predisposing factors for thrombus formation.'),
('77679656-cfe9-52b4-abe9-b89dfd6ff063'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Cerebral oedema can be caused by:', '["Trauma, ischaemia, tumour, infection","Dehydration accompanied by associated clinical symptoms","Hypoglycaemia mediated by specific receptor activation","Anaemia without affecting the primary tissue pathway","Hyperglycaemia leading to subsequent cellular adaptation"]'::jsonb, 'Trauma, ischaemia, tumour, infection', 'Head trauma, ischemia, neoplasms, and infection all raise intracranial pressure through vasogenic, cytotoxic, or interstitial cerebral edema.'),
('92b30dbd-86f6-5e38-a11f-14b90521971c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Fat embolism is most commonly associated with:', '["Decompression sickness resulting in decreased functional activity","Pancreatitis accompanied by associated clinical symptoms","Long bone fractures and orthopedic surgery","Liposuction without affecting the primary tissue pathway","Burns leading to subsequent cellular adaptation"]'::jsonb, 'Long bone fractures and orthopedic surgery', 'Fracture of a long bone or intramedullary orthopedic surgery releases marrow fat into veins; fat globules then embolize to the lungs and, via shunts, the brain.'),
('82ee4d84-c2d6-5f34-bbd9-4d5e98b568df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Septic shock is characterised by:', '["Vasodilation and increased capillary permeability from infection","Pure hypovolaemia accompanied by associated clinical symptoms","Cardiac pump failure mediated by specific receptor activation","Anaphylaxis without affecting the primary tissue pathway","Neurogenic causes leading to subsequent cellular adaptation"]'::jsonb, 'Vasodilation and increased capillary permeability from infection', 'Endotoxin and cytokines cause widespread vasodilation and endothelial damage with increased capillary permeability, the defining hemodynamic features of septic shock.'),
('5e630c0d-4473-5dd2-aee3-aad0b55a665c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Inadvertent injection of a large air bolus into a central venous catheter causes sudden circulatory collapse. This occurs because:', '["Stroke resulting in decreased functional activity","Myocardial infarction accompanied by associated clinical symptoms","Air lock in the right ventricular outflow tract","Renal failure without affecting the primary tissue pathway","Pulmonary edema only leading to subsequent cellular adaptation"]'::jsonb, 'Air lock in the right ventricular outflow tract', 'A large air bolus collects in the right ventricle and pulmonary outflow tract, forming an air lock that blocks blood from entering the pulmonary circulation.'),
('197f9aec-0dc0-50e1-b859-4899f0bfcee3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Rapid ascent from a deep-sea dive causing disabling joint pains and neurologic symptoms is attributed to which mechanism?', '["Air embolism from lung barotrauma","Helium narcosis","CO2 retention","Oxygen toxicity","Nitrogen gas bubbles forming in tissues"]'::jsonb, 'Nitrogen gas bubbles forming in tissues', 'The abrupt fall in ambient pressure makes nitrogen come out of solution as gas bubbles that occlude small vessels, producing the joint, pulmonary, and neurologic symptoms of decompression sickness.'),
('e0392537-81d3-505c-8f33-b4f6f08b5bf2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The most common type of infarct is:', '["Bland infarct","Red hemorrhagic infarct","Venous infarct","Septic infarct","White anemic infarct"]'::jsonb, 'White anemic infarct', 'White (anemic) infarcts are the most common type, occurring in solid organs with a single end-arterial supply such as the heart, kidney, and spleen.'),
('f856c518-94ef-517d-ad4d-6a59b5684052'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hemorrhagic (red) infarcts are most common in:', '["Lungs and intestine","Heart","Kidney","Brain","Spleen"]'::jsonb, 'Lungs and intestine', 'The lung and intestine have a dual blood supply, so backflow through collateral vessels bleeds into the necrotic zone, making these infarcts red and hemorrhagic.'),
('95ec0554-7c46-520e-8327-127590e2df24'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Cardiogenic shock is caused by:', '["Pump failure (myocardial infarction, severe arrhythmia)","Sepsis accompanied by associated clinical symptoms","Haemorrhage mediated by specific receptor activation","Anaphylaxis without affecting the primary tissue pathway","Neurogenic causes leading to subsequent cellular adaptation"]'::jsonb, 'Pump failure (myocardial infarction, severe arrhythmia)', 'Cardiogenic shock results from myocardial pump failure, most often massive myocardial infarction or a severe arrhythmia that cannot maintain cardiac output.'),
('3e881d8e-51c6-56f4-8f8a-3fdf4025e724'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The additional cell injury suffered when ischemic tissue is reperfused is attributed to which combination of processes?', '["Calcium overload","Reactive oxygen species","Both ROS and calcium overload","Loss of ATP","Complement activation"]'::jsonb, 'Both ROS and calcium overload', 'Restoring blood flow delivers oxygen that fuels production of reactive oxygen species and causes intracellular calcium overload, reactivating damaged mitochondria and destructive enzymes.'),
('a2a81b27-20f6-5b9b-a835-c43a0cc51c92'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Xanthine oxidase contributes to reperfusion injury by generating:', '["Hydrogen peroxide","Nitric oxide","Superoxide anion","Peroxynitrite","Hydroxyl radical"]'::jsonb, 'Superoxide anion', 'Xanthine oxidase accumulated in ischemic tissue converts hypoxanthine to urate while reducing molecular oxygen to superoxide anion, the principal oxidant it generates during reperfusion.'),
('8b5a81d9-4c83-59eb-98e8-162fddccf28e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'ARDS (acute respiratory distress syndrome) is characterised by:', '["Non-cardiogenic pulmonary oedema with damaged alveolar-capillary membrane","Cardiogenic pulmonary oedema accompanied by associated clinical symptoms","Pneumonia only mediated by specific receptor activation","Pulmonary fibrosis only without affecting the primary tissue pathway","Bronchiectasis leading to subsequent cellular adaptation"]'::jsonb, 'Non-cardiogenic pulmonary oedema with damaged alveolar-capillary membrane', 'ARDS is increased-permeability (non-cardiogenic) pulmonary edema caused by diffuse alveolar-capillary membrane damage, yielding protein-rich alveolar fluid without left heart failure.'),
('14b473ff-76d8-5784-9256-8ece5f78797a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The most common type of shock is:', '["Neurogenic shock","Septic shock","Hypovolemic shock","Anaphylactic shock","Cardiogenic shock"]'::jsonb, 'Hypovolemic shock', 'Hypovolemic shock from hemorrhage, burns, or severe fluid loss is the most common form of shock because it represents a reduction in circulating blood volume.'),
('2003998d-9852-5103-80cd-a69812096a3c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Septic shock is most commonly caused by:', '["Gram-negative bacteria endotoxin","Parasites accompanied by associated clinical symptoms","Viruses mediated by specific receptor activation","Fungi without affecting the primary tissue pathway","Gram-positive bacteria leading to subsequent cellular adaptation"]'::jsonb, 'Gram-negative bacteria endotoxin', 'Endotoxin (lipopolysaccharide) of gram-negative bacilli is the commonest trigger of septic shock, activating macrophages to release TNF and IL-1 with vasodilation.'),
('60faba6d-6c7b-5759-b14f-3dd8d9921107'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In the initial compensatory stage of shock the kidney:', '["Undergoes papillary necrosis","Produces concentrated urine","Produces large volumes of dilute urine","Becomes anuric","Undergoes acute tubular necrosis"]'::jsonb, 'Produces concentrated urine', 'In early shock renal blood flow is only modestly reduced, so aldosterone and antidiuretic hormone conserve water and the kidney produces concentrated urine; oliguria and ATN mark the progressive stage.'),
('332b5f3e-3808-5c08-8b83-a6fd013f6030'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Disseminated intravascular coagulation is a complication of:', '["Hypertension resulting in decreased functional activity","Diabetes accompanied by associated clinical symptoms","Septic shock and obstetric complications","Atherosclerosis without affecting the primary tissue pathway","Hyperlipidemia leading to subsequent cellular adaptation"]'::jsonb, 'Septic shock and obstetric complications', 'DIC is a complication of septic shock, obstetric emergencies (placental abruption, amniotic fluid embolism), advanced malignancy, and massive trauma through widespread activation of coagulation.'),
('cdcbece8-0dd5-53fd-abb3-e0a71bc76fa9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In DIC the peripheral smear shows:', '["Schistocytes (RBC fragments)","Target cells","Sickle cells","Spherocytes","Increased platelets"]'::jsonb, 'Schistocytes (RBC fragments)', 'Fibrin strands deposited in the microvasculature in DIC shear passing red cells into fragments (schistocytes), together with thrombocytopenia from platelet consumption.'),
('2db84190-f5cd-5aee-9f3a-80abaa99b2f0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Warfarin belongs to which category of anticoagulant drugs?', '["Vitamin K antagonist","Fibrinolytic agent","Direct thrombin inhibitor","Factor Xa inhibitor","Platelet inhibitor"]'::jsonb, 'Vitamin K antagonist', 'Warfarin blocks the vitamin K-dependent gamma-carboxylation of clotting factors II, VII, IX, and X (and proteins C and S), so it is a vitamin K antagonist.'),
('050d118b-413d-5605-a3f1-dac1afdab41b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Heparin inhibits the coagulation cascade through which primary mechanism?', '["Inhibiting vitamin K","Inhibiting thrombin only","Inhibiting factor Xa directly","Promoting fibrinolysis","Binding to antithrombin III"]'::jsonb, 'Binding to antithrombin III', 'Heparin binds antithrombin III and accelerates its inactivation of thrombin and factor Xa, rather than acting directly on the enzymes.'),
('17136474-6fd4-5234-9fff-deb227155ef2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Factor V Leiden mutation causes:', '["Vitamin K deficiency resulting in decreased functional activity","Liver disease accompanied by associated clinical symptoms","Bleeding disorder mediated by specific receptor activation","Factor V deficiency without affecting the primary tissue pathway","Resistance to activated protein C leading to thrombosis"]'::jsonb, 'Resistance to activated protein C leading to thrombosis', 'The factor V Leiden point mutation makes factor Va resistant to cleavage by activated protein C, sustaining thrombin generation and producing venous thrombosis.'),
('56517191-4de0-5086-a1f3-d952ca5a1a0e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The most common inherited thrombophilia is:', '["Protein S deficiency","Antithrombin III deficiency","Factor V Leiden mutation","Prothrombin gene mutation","Protein C deficiency"]'::jsonb, 'Factor V Leiden mutation', 'Factor V Leiden is the most common inherited hypercoagulable disorder, present in about 5% of whites and found in many patients with venous thrombosis.'),
('25eb1d38-1e9b-5579-970c-74dd036ed651'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Antiphospholipid syndrome causes:', '["Venous and arterial thrombosis with recurrent pregnancy loss","Hemophilia accompanied by associated clinical symptoms","Von Willebrand disease mediated by specific receptor activation","Bleeding due to thrombocytopenia without affecting the primary tissue pathway","Disseminated intravascular coagulation leading to subsequent cellular adaptation"]'::jsonb, 'Venous and arterial thrombosis with recurrent pregnancy loss', 'Antiphospholipid antibodies produce a prothrombotic state with venous and arterial thrombosis and recurrent pregnancy loss, largely by disrupting the protein C/protein S system.'),
('906a3ca5-9a1b-5662-9bb2-46360f5bc2bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The classic cause of hemolytic-uremic syndrome in children, following a diarrheal illness, is:', '["Streptococcal infection resulting in decreased functional activity","Malaria accompanied by associated clinical symptoms","E coli O157:H7 causing microangiopathic hemolytic anemia","Autoimmune hemolytic anemia without affecting the primary tissue pathway","Viral hepatitis leading to subsequent cellular adaptation"]'::jsonb, 'E coli O157:H7 causing microangiopathic hemolytic anemia', 'Escherichia coli O157:H7 elaborates a Shiga-like toxin that injures renal endothelium, producing microangiopathic hemolytic anemia, thrombocytopenia, and acute renal failure.'),
('fe194dc4-39bd-5ba9-a0b7-14e08ec72274'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Thrombotic thrombocytopenic purpura is characterized by:', '["Chronic anemia resulting in decreased functional activity","Splenomegaly accompanied by associated clinical symptoms","Deep vein thrombosis mediated by specific receptor activation","Fever, neurologic symptoms, microangiopathic hemolytic anemia, and renal involvement","Leukocytosis leading to subsequent cellular adaptation"]'::jsonb, 'Fever, neurologic symptoms, microangiopathic hemolytic anemia, and renal involvement', 'TTP shows the classic pentad of fever, neurologic changes, microangiopathic hemolytic anemia, and renal involvement (plus thrombocytopenia), driven by ADAMTS13 deficiency.'),
('587b200a-8b17-5d19-af3b-4c10d8b25217'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A 34-year-old woman with no liver disease develops congestive hepatomegaly, ascites, and centrilobular necrosis caused by obstruction of the hepatic veins. Which syndrome is this?', '["Portal vein thrombosis","Reye syndrome","Banti syndrome","Nutmeg liver","Budd-Chiari syndrome"]'::jsonb, 'Budd-Chiari syndrome', 'Budd-Chiari syndrome is hepatic vein obstruction producing severe congestion, centrilobular sinusoidal dilation, and a ''nutmeg'' liver with ascites and hepatomegaly.'),
('d2beb6b4-ea48-5d5c-b85e-92936023556f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which of the following can damage the lining of blood vessels and thereby predispose to local thrombus formation?', '["Stasis","Inflammation","Endothelial injury","Abnormal blood flow","Hypercoagulability"]'::jsonb, 'Inflammation', 'Inflammation injures and activates endothelium through microbial products and mediators, exposing tissue factor and promoting local thrombosis; the other options are consequences rather than causes of vessel wall damage.'),
('9c2d63e1-259e-5c59-a429-0c495aca6e28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Lymphedema most commonly results from:', '["Hypothyroidism resulting in decreased functional activity","Lymphatic obstruction (filariasis, tumors, surgery)","Congestive heart failure mediated by specific receptor activation","Nephrotic syndrome without affecting the primary tissue pathway","Cirrhosis leading to subsequent cellular adaptation"]'::jsonb, 'Lymphatic obstruction (filariasis, tumors, surgery)', 'Acquired blockage of the lymphatic channels by filariasis, tumor infiltration, or surgical interruption leaves protein-rich fluid in the affected part.'),
('4adb7570-142e-5080-a8a0-f8df5805e862'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Central nervous system edema can be:', '["All of the above","Hydrocephalic","Interstitial","Cytotoxic","Vasogenic"]'::jsonb, 'All of the above', 'Cerebral edema takes three forms: vasogenic (blood-brain barrier disruption), cytotoxic (cellular swelling from ischemia or toxins), and interstitial (periventricular, as in hydrocephalus).'),
('cb3b58a0-4410-5360-aaa5-93233c06f7bd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Right heart failure raises the pressure in the systemic veins and capillaries, pushing fluid into the tissues of the legs. Which mechanism of edema best accounts for this?', '["Increased vascular permeability","Lymphatic obstruction","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Sodium and water retention"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Raised venous and capillary pressures increase the hydrostatic filtration force, overwhelming the forces that reabsorb fluid and producing low-protein pitting edema.'),
('ae05276c-61a9-59fd-94cc-73e4b242c5d7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A child with nephrotic syndrome has massive proteinuria and a serum albumin of 1.8 g/dL with generalized pitting edema. Which mechanism is most important in producing this edema?', '["Decreased plasma oncotic pressure","Increased capillary hydrostatic pressure","Increased vascular permeability","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Decreased plasma oncotic pressure', 'Albumin loss lowers plasma colloid osmotic (oncotic) pressure, weakening the force that reabsorbs interstitial fluid into capillaries, so generalized edema results.'),
('4fa33e17-6536-5b45-b8d2-bff4da6d87ee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Within minutes of an angioedema reaction, the lips and eyelids swell with protein-rich fluid. Which mechanism is responsible?', '["Increased vascular permeability","Sodium and water retention","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Lymphatic obstruction"]'::jsonb, 'Increased vascular permeability', 'Anaphylactic mediators such as histamine open gaps between endothelial cells, increasing vascular permeability so that protein-rich fluid escapes into tissues.'),
('ff5afc11-2708-5e2c-96ed-16dadab231c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A leg becomes swollen after a deep vein thrombosis interrupts venous drainage. The acute swelling is chiefly driven by which mechanism?', '["Sodium and water retention","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Increased vascular permeability","Lymphatic obstruction"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Venous obstruction raises capillary hydrostatic pressure distal to the block, increasing net filtration of fluid out of the microvessels.'),
('7b9370dd-16b8-56d5-a3ae-6fc62ed2fec1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In heart failure and renal disease, reduced renal perfusion activates the renin-angiotensin-aldosterone system and the kidneys conserve sodium and water, expanding total body fluid. The resulting edema is attributed to which mechanism?', '["Decreased plasma oncotic pressure","Increased vascular permeability","Lymphatic obstruction","Sodium and water retention","Increased capillary hydrostatic pressure"]'::jsonb, 'Sodium and water retention', 'Conserved sodium obligates water, expanding the extracellular volume and raising capillary pressures; this primarily represents primary sodium and water retention by the kidney.'),
('54e435ce-8b03-507b-b0d7-9189029d8d5d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'After axillary lymph node dissection for breast cancer, a woman develops firm, non-pitting swelling of the arm containing protein-rich fluid. Which mechanism causes this edema?', '["Lymphatic obstruction","Increased vascular permeability","Increased capillary hydrostatic pressure","Sodium and water retention","Decreased plasma oncotic pressure"]'::jsonb, 'Lymphatic obstruction', 'Interruption of lymphatics prevents clearance of filtered protein and fluid from the interstitium, producing a protein-rich edema that is typically non-pitting.'),
('2a924af9-b0e0-5ca4-b3df-30c6a059d6d9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A patient with burns over 40% of the body develops generalized edema within hours of injury. Which mechanism of edema predominates?', '["Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Sodium and water retention","Lymphatic obstruction","Increased vascular permeability"]'::jsonb, 'Increased vascular permeability', 'Global capillary leakage is characteristic of burns; heat-damaged endothelium allows protein-rich fluid to escape into the tissues.'),
('eb8b05dc-39fc-5aef-95c7-85149a33f207'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Cirrhosis reduces hepatic synthesis of albumin, and the falling plasma protein concentration allows fluid to accumulate in the peritoneum and limbs. Which mechanism is responsible?', '["Decreased plasma oncotic pressure","Sodium and water retention","Increased vascular permeability","Increased capillary hydrostatic pressure","Lymphatic obstruction"]'::jsonb, 'Decreased plasma oncotic pressure', 'Reduced synthesis of albumin lowers plasma colloid osmotic pressure, decreasing reabsorption of interstitial fluid and producing edema and ascites.'),
('6ca18571-4873-57d0-a090-aa464a6a8ce2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In constrictive pericarditis the systemic venous pressure rises markedly and peripheral edema develops. Which mechanism best explains this edema?', '["Lymphatic obstruction","Increased vascular permeability","Decreased plasma oncotic pressure","Increased capillary hydrostatic pressure","Sodium and water retention"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Elevated systemic venous pressure transmits to the capillaries, increasing hydrostatic filtration; constrictive pericarditis causes this by impairing filling of the right heart.'),
('8e769a42-1ee9-5f75-8c20-58d0e02d2d33'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Chronic filarial infection of the lower limb produces permanent, non-pitting swelling. Which mechanism is primarily responsible?', '["Sodium and water retention","Increased vascular permeability","Lymphatic obstruction","Decreased plasma oncotic pressure","Increased capillary hydrostatic pressure"]'::jsonb, 'Lymphatic obstruction', 'Wuchereria bancrofti obstructs the lymphatics, preventing drainage of interstitial protein and fluid and causing the irreversible elephantiasis of filariasis.'),
('2a3610f8-d574-5250-9b50-1fd743e7dd36'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Arterial thrombi typically form where blood flow is rapid and disturbed, as at vessel bifurcations. The most important local factor is:', '["Stasis","Hypercoagulability","Turbulence at vessel bifurcations","Platelet dysfunction","Increased fibrinolysis"]'::jsonb, 'Turbulence at vessel bifurcations', 'Turbulent flow at bifurcations injures endothelium and creates local zones of stasis; this is the dominant site for the formation of arterial and cardiac thrombi.'),
('301364f1-ce79-5d33-8d5d-920878112720'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In the second week after a large transmural anterior myocardial infarction, a patient suddenly develops hypotension, distended neck veins, and muffled heart sounds. What is the most likely complication?', '["Cerebral embolism resulting in decreased functional activity","Cardiac tamponade from myocardial rupture","Pulmonary embolism mediated by specific receptor activation","Pericarditis without affecting the primary tissue pathway","Aortic dissection leading to subsequent cellular adaptation"]'::jsonb, 'Cardiac tamponade from myocardial rupture', 'Rupture of the free wall hemorrhages into the pericardial sac, producing cardiac tamponade; it typically occurs days to about two weeks after a transmural infarct.'),
('ced2cf72-164b-5b71-9f9b-52598169eaf9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A young man sustains a closed fracture of the femur and within 48 hours develops dyspnea, confusion, and a petechial rash over the chest. Which condition is most likely?', '["Fat embolism","Air embolism","Thromboembolism","Amniotic fluid embolism","Septic embolism"]'::jsonb, 'Fat embolism', 'Marrow fat released from a fractured long bone embolizes to the lungs and brain, causing hypoxia, neurologic signs, and a characteristic petechial rash.'),
('346ae982-fee8-5fb4-b1ad-a2f7e8005c14'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Sudden cardiorespiratory collapse and disseminated intravascular coagulation during labor or shortly after delivery classically result from:', '["Amniotic fluid embolism","Air embolism","Fat embolism","Septic embolism","Tumor embolism"]'::jsonb, 'Amniotic fluid embolism', 'Amniotic fluid and fetal squamous cells entering the maternal circulation during labor cause abrupt cardiorespiratory collapse and DIC.'),
('2da972f8-34cf-5080-882a-08c510b2e294'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The most common emboli in clinical practice are:', '["Thrombi","Fat globules","Air bubbles","Amniotic fluid","Tumor fragments"]'::jsonb, 'Thrombi', 'More than 90% of emboli are detached thrombi (thromboemboli), most arising from deep veins of the lower extremities.'),
('11923a0c-a75a-5d5d-b344-7a400a7efdc4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pulmonary embolism most frequently originates from thrombi in:', '["Deep veins of the lower limbs","Left atrium","Hepatic veins","Brachial arteries","Splenic vein"]'::jsonb, 'Deep veins of the lower limbs', 'About 90% of pulmonary emboli arise from deep venous thrombi of the lower extremities, which travel to the right heart and lodge in the pulmonary arteries.'),
('2ddfe2c3-ae0c-5025-9e05-3c7752155590'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Multiple septic infarcts in the brain, kidney, and spleen of a febrile patient most likely arise from embolization of vegetations originating in:', '["Infective endocarditis of the mitral valve","Left atrial mural thrombus","Dilated cardiomyopathy","Atrial flutter","Myocardial scar"]'::jsonb, 'Infective endocarditis of the mitral valve', 'Infective vegetations on heart valves shed septic emboli that cause abscesses and infarcts in the brain, kidney, spleen, and myocardium.'),
('bfe3e6a7-9229-54aa-84de-962fcef2f9ee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pale (white) infarcts due to occlusion of an end-artery most typically occur in:', '["Heart, kidney, and spleen","Lung and intestine","Skin and lung","Brain and liver","Testis and ovary"]'::jsonb, 'Heart, kidney, and spleen', 'Solid organs with a single arterial supply and sparse collaterals, such as the heart, kidney, and spleen, develop white anemic infarcts.'),
('930322ea-222a-5fb6-a8f2-7156389f9aeb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Red (hemorrhagic) infarcts characteristically occur in organs with a dual blood supply, such as:', '["Lung and intestine","Heart and kidney","Spleen and brain","Kidney and spleen","Brain and heart"]'::jsonb, 'Lung and intestine', 'The lung and intestine have dual circulations; backflow through collateral vessels bleeds into the necrotic zone, making the infarct red and hemorrhagic.'),
('1a1b6833-43fa-5016-be75-6351edc2e8c7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A 60-year-old man with an irregularly irregular pulse develops an embolic stroke. The most likely source of the embolus is:', '["Atrial fibrillation with left atrial mural thrombus","Chronic obstructive pulmonary disease","Essential hypertension","Hyperthyroidism","Peptic ulcer disease"]'::jsonb, 'Atrial fibrillation with left atrial mural thrombus', 'Atrial fibrillation causes stasis in the left atrium and appendage, forming mural thrombi that embolize to the systemic circulation, including the brain.'),
('2b4ec8b8-aa34-5fa4-871e-f6a29e630e21'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Shock is best defined as:', '["Generalized inadequate tissue perfusion leading to cellular hypoxia","Hypertension with bradycardia accompanied by associated clinical symptoms","Polycythemia with hyperviscosity mediated by specific receptor activation","Hypervolemia with edema without affecting the primary tissue pathway","Hypocapnia with alkalosis leading to subsequent cellular adaptation"]'::jsonb, 'Generalized inadequate tissue perfusion leading to cellular hypoxia', 'The unifying feature of all shock types is hypoperfusion of tissues with impaired oxygen delivery, producing cellular hypoxia and ultimately organ failure.'),
('e88fc459-380b-5875-8598-04da3fdeea5c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which of the following most directly causes hypovolemic shock?', '["Severe hemorrhage","Gram-negative sepsis","Myocardial infarction","High spinal anesthesia","Anaphylactic reaction"]'::jsonb, 'Severe hemorrhage', 'Hypovolemic shock follows a reduction in circulating blood volume from hemorrhage, burns, or severe fluid loss; it is the most common form of shock.'),
('75def7bd-3885-51d9-ab17-0071215ef84b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Neurogenic shock most characteristically results from:', '["Loss of sympathetic tone (spinal cord injury, high spinal anesthesia)","Massive blood loss accompanied by associated clinical symptoms","Endotoxin release mediated by specific receptor activation","Impaired cardiac contractility without affecting the primary tissue pathway","IgE-mediated mast cell degranulation leading to subsequent cellular adaptation"]'::jsonb, 'Loss of sympathetic tone (spinal cord injury, high spinal anesthesia)', 'Loss of sympathetic vasomotor tone causes systemic vasodilation and pooling of blood with relative hypovolemia, as occurs in spinal cord injury or high spinal anesthesia.'),
('a659c9d5-bf66-5da7-921d-bf0f046c2b02'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Anaphylactic shock is initiated by:', '["IgE-mediated mast cell degranulation with histamine release","Acute myocardial infarction accompanied by associated clinical symptoms","Gram-negative bacteremia mediated by specific receptor activation","Hemorrhage without affecting the primary tissue pathway","Sympathetic blockade leading to subsequent cellular adaptation"]'::jsonb, 'IgE-mediated mast cell degranulation with histamine release', 'Anaphylaxis is a type I hypersensitivity reaction; mast cell degranulation releases histamine, causing vasodilation and increased vascular permeability with circulatory collapse.'),
('9516e0aa-8135-57e3-aea0-760ec0a42844'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Early (warm) septic shock characteristically shows:', '["Warm, flushed skin with bounding pulse and fever","Cold, clammy skin with absent pulses accompanied by associated clinical symptoms","Dry mucous membranes mediated by specific receptor activation","Bradycardia without affecting the primary tissue pathway","Polycythemia leading to subsequent cellular adaptation"]'::jsonb, 'Warm, flushed skin with bounding pulse and fever', 'The hyperdynamic phase of septic shock features vasodilation with warm flushed skin, bounding pulse, and fever before decompensating to cold, poorly-perfused shock.'),
('85572034-8502-57ba-89a5-d59d02afd857'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Cardiogenic shock most commonly follows:', '["Myocardial infarction with pump failure","Massive hemorrhage","Neurogenic loss of vascular tone","Anaphylaxis","Dehydration"]'::jsonb, 'Myocardial infarction with pump failure', 'Cardiogenic shock is pump failure, most often caused by a massive myocardial infarction in which the left ventricle cannot maintain cardiac output.'),
('1af23f6d-735e-5e7e-9394-4b49fdfc6489'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which obstetric complication is classically complicated by disseminated intravascular coagulation?', '["Placental abruption or retained dead fetus","Uncomplicated normal delivery accompanied by associated clinical symptoms","Ovarian cyst mediated by specific receptor activation","Endometriosis without affecting the primary tissue pathway","Uterine fibroids leading to subsequent cellular adaptation"]'::jsonb, 'Placental abruption or retained dead fetus', 'Placental abruption and retained dead fetus release thromboplastin material into the maternal circulation, activating the clotting cascade and producing DIC.'),
('7ec3cd13-9793-599f-aaaa-e895777e894f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which laboratory profile best confirms disseminated intravascular coagulation?', '["Prolonged PT and aPTT, low fibrinogen, high D-dimer, thrombocytopenia","Normal PT and aPTT with high fibrinogen accompanied by associated clinical symptoms","Prolonged bleeding time only mediated by specific receptor activation","Elevated platelets with low D-dimer without affecting the primary tissue pathway","Low PT with high fibrinogen leading to subsequent cellular adaptation"]'::jsonb, 'Prolonged PT and aPTT, low fibrinogen, high D-dimer, thrombocytopenia', 'Consumption of clotting factors and platelets with secondary fibrinolysis yields prolonged PT/aPTT, hypofibrinogenemia, elevated D-dimer, and thrombocytopenia in DIC.'),
('698bb928-08c4-593d-9cae-d314a831c197'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Early warfarin therapy occasionally causes skin necrosis, attributed to:', '["Early decline in protein C activity","Inhibition of platelet cyclooxygenase","Direct thrombin inhibition","Factor Xa blockade","Fibrinogen depletion"]'::jsonb, 'Early decline in protein C activity', 'Warfarin rapidly lowers protein C (short half-life), creating a transient prothrombotic state in some patients that can cause microvascular thrombosis and skin necrosis.'),
('67097384-2df2-5c48-9ffc-5182a611d448'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A patient receiving intravenous heparin for 7 days develops falling platelets and a new venous thrombosis. The most likely diagnosis is:', '["Heparin-induced thrombocytopenia (HIT)","Vitamin K deficiency","Immune thrombocytopenic purpura","Dilutional thrombocytopenia","Bone marrow aplasia"]'::jsonb, 'Heparin-induced thrombocytopenia (HIT)', 'HIT is an immune reaction to heparin-platelet factor 4 complexes that activates platelets, causing thrombocytopenia and paradoxical venous or arterial thrombosis.'),
('ca91fb2d-a6a2-53e7-9c75-644ae163db4c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which of the following is a hereditary prothrombotic (thrombophilia) state?', '["Factor V Leiden","Anti-retroviral therapy","Chronic liver disease","Sickle cell trait","Immobilization only"]'::jsonb, 'Factor V Leiden', 'Factor V Leiden, protein C or S deficiency, antithrombin deficiency, and prothrombin G20210A are inherited thrombophilias predisposing to venous thrombosis.'),
('a0753ef1-1d50-5cc9-b947-95498f59a17b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A young woman has recurrent deep vein thromboses and three first-trimester miscarriages, with a prolonged aPTT that does not correct on mixing. Which disorder is most likely?', '["Venous and arterial thrombosis with recurrent pregnancy loss","Hemophilia A accompanied by associated clinical symptoms","Von Willebrand disease mediated by specific receptor activation","Thrombocytopenia alone without affecting the primary tissue pathway","Hyperfibrinolysis leading to subsequent cellular adaptation"]'::jsonb, 'Venous and arterial thrombosis with recurrent pregnancy loss', 'Antiphospholipid syndrome produces arterial and venous thrombosis and recurrent pregnancy loss, with a lupus anticoagulant pattern on coagulation testing.'),
('458505ed-0a57-5b2e-8d74-f57855aab6ef'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In the chronically congested lung of long-standing left heart failure, the alveolar spaces contain:', '["Heart failure cells (hemosiderin-laden alveolar macrophages)","Foamy macrophages accompanied by associated clinical symptoms","Epithelioid granulomas mediated by specific receptor activation","Mallory bodies without affecting the primary tissue pathway","Lipofuscin-laden hepatocytes leading to subsequent cellular adaptation"]'::jsonb, 'Heart failure cells (hemosiderin-laden alveolar macrophages)', 'Repeated hemorrhages in chronic passive congestion leave hemosiderin within intra-alveolar macrophages, which are termed heart failure cells.'),
('315d3b00-8951-536a-9cce-fb22c9bd4704'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In chronic passive congestion of the liver the cut surface is ''nutmeg'' because of:', '["Centrilobular (zone 3) congestion with hepatocyte atrophy","Periportal fibrosis with bile ductular proliferation","Diffuse bridging fibrosis","Steatotic cords throughout the lobule","Expanding regenerative nodules"]'::jsonb, 'Centrilobular (zone 3) congestion with hepatocyte atrophy', 'High hepatic venous pressure most affects the centrilobular (zone 3) sinusoids, congesting them and causing atrophy of the hepatocytes in that zone.'),
('26c8d9f7-391b-5cc1-8cf9-021daf9a8080'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The redness and warmth of an acutely inflamed site result from:', '["Active arteriolar dilation with increased inflow (hyperemia)","Passive pooling from impaired outflow (congestion)","Hemorrhage into the tissue","Thrombotic occlusion","Collateral bypass"]'::jsonb, 'Active arteriolar dilation with increased inflow (hyperemia)', 'Inflammation produces hyperemia: arteriolar dilation increases blood inflow, giving the redness and warmth; congestion, by contrast, is the passive form of engorgement.'),
('c81039e6-b57c-57f2-bc96-025236ee97f7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Dependent edema after standing for many hours is chiefly due to:', '["Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Lymphatic obstruction","Increased vascular permeability","Sodium and water retention"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Gravity raises venous and capillary pressures in the lower limbs, redistributing blood downward and increasing filtration of fluid out of the vessels.'),
('f4dce637-3316-59b5-a113-e877691cb311'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In cirrhosis, portal hypertension distends the hepatic sinusoids and splanchnic capillaries, favoring loss of fluid into the peritoneum. Which mechanism predominates in this ascites?', '["Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Lymphatic obstruction","Increased vascular permeability","Sodium and water retention"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Portal venous hypertension raises the hydrostatic pressure in splanchnic capillaries, driving plasma filtrate into the peritoneal cavity and causing ascites.'),
('6c3a3d84-13e6-5f6d-8cf1-b68063f4400c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Worsening heart failure activates the renin-angiotensin-aldosterone axis so that the kidney retains salt and water. Which mechanism of edema is thereby reinforced?', '["Decreased plasma oncotic pressure","Increased vascular permeability","Increased capillary hydrostatic pressure","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Sodium and water retention', 'Aldosterone-driven conservation of sodium expands extracellular volume and raises capillary pressures; this renal sodium and water retention reinforces the edema of heart failure.'),
('70a0e42b-fca8-5823-96c2-750d5ab2c2f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Acute venous obstruction by a tourniquet-like band produces marked swelling of a dependent limb. The swelling arises chiefly from:', '["Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Sodium and water retention","Lymphatic obstruction","Increased vascular permeability"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Venous obstruction distal to the band raises capillary hydrostatic pressure, forcing fluid out of the microvessels and producing edema.'),
('045bd38e-7193-5b1f-9e37-7e87c6677aff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'An inflammatory exudate is rich in protein, distinguishing it from a transudate. This protein-rich character of the exudate is due to:', '["Increased vascular permeability","Lymphatic obstruction","Decreased plasma oncotic pressure","Sodium and water retention","Increased capillary hydrostatic pressure"]'::jsonb, 'Increased vascular permeability', 'Increased vascular permeability lets plasma proteins escape with fluid through gaps between endothelial cells, producing a high-protein inflammatory exudate.'),
('c3c1a55e-16ed-5550-9eb9-ece707d0c631'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Restoration of blood flow to previously ischemic myocardium can paradoxically worsen cell injury through which mechanisms?', '["Reactive oxygen species and calcium overload","Carbon monoxide poisoning","Lactic acidosis only","Loss of ATP alone","Complement deficiency"]'::jsonb, 'Reactive oxygen species and calcium overload', 'Reflow supplies oxygen that fuels production of reactive oxygen species and causes calcium overload in reoxygenated mitochondria, aggravating injury in reperfusion.'),
('bcd9ae26-dbb3-5225-a0fd-072434f0a0d8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'During reperfusion of ischemic tissue, xanthine oxidase contributes to injury chiefly by generating:', '["Superoxide anion","Hydrogen peroxide only","Hydroxyl radical","Nitric oxide","Singlet oxygen"]'::jsonb, 'Superoxide anion', 'Xanthine oxidase reduces molecular oxygen to superoxide anion while converting hypoxanthine to urate, providing the initial oxidant in reperfusion injury.'),
('beb5c8f5-8900-5e8c-b087-a12b88126407'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A thrombus showing alternating layers of pale platelets/fibrin and dark red cells (lines of Zahn) formed in vivo where blood flow was:', '["Rapid laminar flow (arteries and heart)","Venous stasis with slow flow","Postmortem clotting","Capillary bed hemoconcentration","Splenic sinusoids"]'::jsonb, 'Rapid laminar flow (arteries and heart)', 'Lines of Zahn reflect laminar flow and indicate an antemortem arterial or cardiac thrombus; venous and postmortem thrombi lack this layering.'),
('07ae20ce-c064-5c64-915a-903958616211'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which statement about thrombi is TRUE?', '["Venous thrombi are red, occlusive, and form in stasis","Arterial thrombi are red and gelatinous","Venous thrombi contain lines of Zahn","Arterial thrombi rarely cause embolism","Postmortem clots contain lines of Zahn"]'::jsonb, 'Venous thrombi are red, occlusive, and form in stasis', 'Venous thrombi are red (RBC-rich), gelatinous, and occlusive, forming under stasis; arterial thrombi are pale, mural, and show lines of Zahn.'),
('26f35162-4d00-565e-b0e5-43ba475dd7f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Warfarin, which blocks the gamma-carboxylation of clotting factors II, VII, IX, and X, is best classified as:', '["Vitamin K antagonist","Direct thrombin inhibitor","Tissue plasminogen activator","Platelet glycoprotein IIb/IIIa inhibitor","ADP receptor antagonist"]'::jsonb, 'Vitamin K antagonist', 'Warfarin prevents vitamin K-dependent carboxylation of factors II, VII, IX, and X (and proteins C and S), so it is a vitamin K antagonist.'),
('4b056cd6-0435-582e-8d28-e09a53bb7733'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Heparin exerts its anticoagulant effect primarily by:', '["Accelerating antithrombin III inhibition of thrombin and factor Xa","Blocking vitamin K reductase accompanied by associated clinical symptoms","Displacing calcium ions mediated by specific receptor activation","Degrading fibrin without affecting the primary tissue pathway","Inhibiting platelet ADP release leading to subsequent cellular adaptation"]'::jsonb, 'Accelerating antithrombin III inhibition of thrombin and factor Xa', 'Heparin binds antithrombin III and accelerates its inactivation of thrombin and factor Xa by about a thousandfold.'),
('ab62fa7e-0714-5a7c-868a-f398833e2000'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The single most common inherited cause of venous thrombosis is:', '["Factor V Leiden","Antithrombin III deficiency","Protein C deficiency","Prothrombin gene mutation","Protein S deficiency"]'::jsonb, 'Factor V Leiden', 'Factor V Leiden is far more prevalent than the other inherited thrombophilias and is the commonest genetic cause of venous thrombosis.'),
('d90dd821-b778-5a71-ad95-e2cb7903c4c0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Lysis of a fresh coronary artery thrombus in acute myocardial infarction is achieved by:', '["Plasminogen activator (streptokinase or tPA)","Aspirin accompanied by associated clinical symptoms","Warfarin mediated by specific receptor activation","Heparin without affecting the primary tissue pathway","Desmopressin leading to subsequent cellular adaptation"]'::jsonb, 'Plasminogen activator (streptokinase or tPA)', 'Fibrinolytics such as streptokinase and tissue plasminogen activator activate plasminogen to plasmin, which digests fibrin and lyses fresh thrombi.'),
('a5452c23-033c-5c62-8203-75269e2eba66'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Aspirin prevents arterial thrombosis mainly by:', '["Cyclooxygenase inhibition reducing thromboxane A2","Activating protein C accompanied by associated clinical symptoms","Blocking factor Xa mediated by specific receptor activation","Potentiating antithrombin III without affecting the primary tissue pathway","Stabilizing fibrin leading to subsequent cellular adaptation"]'::jsonb, 'Cyclooxygenase inhibition reducing thromboxane A2', 'Low-dose aspirin irreversibly acetylates platelet cyclooxygenase-1, decreasing thromboxane A2 synthesis and thereby inhibiting platelet aggregation.'),
('7ffceb6d-54ed-5526-9677-01cca8bcbb70'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which feature distinguishes a transudate from an exudate?', '["A transudate is protein-poor with low specific gravity","An exudate is protein-poor","A transudate indicates capillary damage","An exudate has very few cells","Both are protein-rich"]'::jsonb, 'A transudate is protein-poor with low specific gravity', 'Transudates are protein-poor ultrafiltrates resulting from hydrostatic or oncotic imbalance, whereas exudates are protein- and cell-rich fluids from increased vascular permeability.'),
('6eeae506-6a1b-58a3-a9ab-7048e71391e6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pinpoint petechiae on the skin of a febrile patient with gum bleeding most likely indicate:', '["Thrombocytopenia","Factor VIII deficiency","Vitamin K deficiency","Liver disease alone","Hypercoagulability"]'::jsonb, 'Thrombocytopenia', 'Petechiae result from spontaneous microvascular bleeding when platelets are low or defective; infections and marrow failure are common causes of thrombocytopenia.'),
('adf34490-5606-5351-9a39-fdc1ca2a30d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A hemorrhage measuring about 5 mm in diameter is best classified as:', '["Purpura","Petechiae","Ecchymosis","Hematoma","Angioma"]'::jsonb, 'Purpura', 'Petechiae are up to 2 mm, purpura roughly 3–10 mm, and ecchymoses exceed about 1 cm, so a 5 mm hemorrhage is purpura.'),
('b2096b40-4f2e-565d-9bea-c8e261916c65'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A bruise-like hemorrhage in the skin larger than 1 cm is termed:', '["Ecchymosis","Petechiae","Purpura","Telangiectasia","Spider angioma"]'::jsonb, 'Ecchymosis', 'Ecchymosis is a hemorrhage larger than about 1 cm; smaller ones are classified as purpura or petechiae.'),
('22736d94-43bc-5524-b870-7430647982d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Coughing up blood from the airways is called:', '["Hemoptysis","Hematemesis","Melena","Epistaxis","Hematuria"]'::jsonb, 'Hemoptysis', 'Hemoptysis is expectoration of blood from the respiratory tract, whereas hematemesis is the vomiting of blood from the upper gastrointestinal tract.'),
('086512dc-115c-5940-aa4d-86ce267c92cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Vomiting of blood is termed:', '["Hematemesis","Melena","Hemoptysis","Epistaxis","Metrorrhagia"]'::jsonb, 'Hematemesis', 'Hematemesis is the vomiting of blood, usually from an upper gastrointestinal source such as a bleeding peptic ulcer or esophageal varices.'),
('862a63b5-7ff0-5daf-9595-5518b28ab51c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Black, tarry stools resulting from bleeding in the proximal gastrointestinal tract are called:', '["Melena","Hematochezia","Steatorrhea","Acholic stool","Hematuria"]'::jsonb, 'Melena', 'Melena is the black, tarry stool produced by digestion of blood, typical of bleeding above the colon, whereas hematochezia is bright red rectal bleeding.'),
('a9d2b966-0804-57fd-bfec-5c46970c6557'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Blood in the urine is termed:', '["Hematuria","Hemoptysis","Melena","Hematemesis","Menorrhagia"]'::jsonb, 'Hematuria', 'Hematuria is blood in the urine, encountered in glomerular disease, urinary stones, tumors, and infections.'),
('3f49d9a3-7353-5800-afcf-eea5a006f01e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Excessive or prolonged uterine bleeding occurring at regular menstrual intervals is called:', '["Menorrhagia","Metrorrhagia","Menometrorrhagia","Dysmenorrhea","Amenorrhea"]'::jsonb, 'Menorrhagia', 'Menorrhagia is heavy, prolonged menstrual bleeding at regular intervals; metrorrhagia is intermenstrual bleeding, and menometrorrhagia combines both.'),
('846a5209-5876-54ca-a231-4689c751f58e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Uterine bleeding occurring at irregular intervals between expected menses is termed:', '["Metrorrhagia","Menorrhagia","Amenorrhea","Dysmenorrhea","Oligomenorrhea"]'::jsonb, 'Metrorrhagia', 'Metrorrhagia is irregular, acyclic intermenstrual bleeding, whereas menorrhagia describes heavy but cyclic menstrual bleeding.'),
('e9dd5453-e189-5d59-b006-ecf8bd44aa84'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Recurrent nosebleeds in a hypertensive patient most likely reflect:', '["Rupture of small vessels in the nasal mucosa","Thrombocytopenia","Lymphatic obstruction","Low plasma oncotic pressure","Disseminated intravascular coagulation"]'::jsonb, 'Rupture of small vessels in the nasal mucosa', 'Epistaxis usually arises from the Kiesselbach plexus of the nasal septum; hypertension and mucosal irritation/drying predispose to recurrent nosebleeds.'),
('1fe4d200-fb84-59d7-b115-db7351df50b9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hypertensive intracerebral hemorrhage most characteristically occurs in which site?', '["Basal ganglia (putamen)","Cerebellum","Pons","Occipital cortex","Midbrain"]'::jsonb, 'Basal ganglia (putamen)', 'Hypertension ruptures penetrating arterioles most often in the basal ganglia (putamen), then the thalamus, pons, and cerebellum.'),
('3e0d0514-9cc6-5c3a-9e65-913dbc63cef8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A young adult with sudden thunderclap headache and subarachnoid hemorrhage most likely has:', '["Berry (saccular) aneurysm rupture","Arteriovenous malformation trauma","Hypertensive hemorrhage","Amyloid angiopathy","Mycotic emboli"]'::jsonb, 'Berry (saccular) aneurysm rupture', 'Rupture of a saccular (berry) aneurysm at a circle of Willis branch point is the classic cause of non-traumatic subarachnoid hemorrhage in young adults.'),
('db97b4a9-c505-53fa-b1b6-d7691946f401'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Epidural hematoma most classically results from:', '["Fracture of the temporal bone tearing the middle meningeal artery","Rupture of bridging veins accompanied by associated clinical symptoms","Hypertensive arteriolar rupture mediated by specific receptor activation","Amyloid angiopathy without affecting the primary tissue pathway","Posterior communicating aneurysm leading to subsequent cellular adaptation"]'::jsonb, 'Fracture of the temporal bone tearing the middle meningeal artery', 'Temporal bone fracture tears the middle meningeal artery, producing a biconvex epidural hematoma that often follows a lucid interval.'),
('bf6296dd-deb0-5fda-9171-21bf03dc5e01'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Subdural hematoma in an elderly anticoagulated patient most typically follows:', '["Stretching and tearing of the bridging veins","Middle meningeal artery tear","Hypertensive hemorrhage","Berry aneurysm rupture","Lobar amyloid angiopathy"]'::jsonb, 'Stretching and tearing of the bridging veins', 'Minor trauma in the elderly, alcoholics, and anticoagulated patients tears the bridging veins, causing a crescentic subdural hematoma.'),
('02f71ca4-e294-5272-81d9-ec40440437e7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Sudden lower abdominal pain and collapse in a woman of reproductive age with a positive pregnancy test most likely reflect rupture of a:', '["Tubal ectopic pregnancy with hemoperitoneum","Ovarian cyst with ascites accompanied by associated clinical symptoms","Uterine fibroid mediated by specific receptor activation","Endometrioma without affecting the primary tissue pathway","Molar pregnancy leading to subsequent cellular adaptation"]'::jsonb, 'Tubal ectopic pregnancy with hemoperitoneum', 'Rupture of a tubal ectopic pregnancy bleeds into the peritoneal cavity, causing acute pain, hypovolemic collapse, and hemoperitoneum.'),
('31dc62b7-c6b5-59f4-a849-d871ea4ca55c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Recurrent hemarthrosis of the knees in a male child is most characteristic of:', '["Hemophilia (factor VIII or IX deficiency)","Iron deficiency anemia","Polycythemia","Sickle cell disease","Thrombotic thrombocytopenic purpura"]'::jsonb, 'Hemophilia (factor VIII or IX deficiency)', 'Deficiency of factor VIII or IX in hemophilia predisposes to bleeding into joints (hemarthrosis) and deep soft tissues after trivial trauma.'),
('718d520d-5c44-539e-b218-d1f32a810a40'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Accumulation of blood in the pericardial sac is termed:', '["Hemopericardium","Hemothorax","Hemoperitoneum","Hemarthrosis","Hematemesis"]'::jsonb, 'Hemopericardium', 'Blood in the pericardial cavity is hemopericardium; if it compresses the heart it produces cardiac tamponade.'),
('9f4af4bf-ac1c-54e5-82ff-8774e1e7e5df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Distended jugular veins, hepatic congestion, and dependent edema are most characteristic of:', '["Right-sided heart failure","Left-sided heart failure","Coarctation of the aorta","Aortic valve stenosis alone","Pericarditis alone"]'::jsonb, 'Right-sided heart failure', 'Right heart failure impedes venous return, causing systemic venous congestion with jugular venous distention, hepatomegaly, and dependent edema, whereas left heart failure causes pulmonary congestion.'),
('6de1b5a0-fd42-565a-b18a-dd79a1b4a904'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A patient with left heart failure develops orthopnea and paroxysmal nocturnal dyspnea because of:', '["Pulmonary capillary congestion with increased hydrostatic pressure","Systemic venous distension accompanied by associated clinical symptoms","Primary lymphatic obstruction mediated by specific receptor activation","Hypoalbuminemia without affecting the primary tissue pathway","Renal salt wasting leading to subsequent cellular adaptation"]'::jsonb, 'Pulmonary capillary congestion with increased hydrostatic pressure', 'In left heart failure blood pools in the pulmonary veins, raising pulmonary capillary hydrostatic pressure and producing breathlessness, especially on lying flat.'),
('c2ae4a6c-696a-5178-981f-7ce9b9219dd9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which clinical situation produces edema through a fall in plasma colloid osmotic pressure?', '["Malnutrition with low serum albumin","Deep vein thrombosis","Congestive heart failure","Lymphatic filariasis","Primary aldosteronism"]'::jsonb, 'Malnutrition with low serum albumin', 'Low serum albumin (malnutrition, nephrotic syndrome, cirrhosis, protein-losing enteropathy) lowers plasma oncotic pressure and reduces reabsorption of interstitial fluid.'),
('56acae76-9bf7-54fc-901b-92fac1c71cab'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Bacterial sepsis causes leakage of plasma proteins into tissues because of:', '["Endothelial injury with increased vascular permeability","Dilated arterioles alone accompanied by associated clinical symptoms","Elevated venous pressure mediated by specific receptor activation","Decreased albumin synthesis without affecting the primary tissue pathway","Lymphatic obstruction leading to subsequent cellular adaptation"]'::jsonb, 'Endothelial injury with increased vascular permeability', 'In sepsis, endotoxin and cytokines damage endothelium and open inter-endothelial gaps, letting plasma proteins and fluid escape into the tissues.'),
('bbfa945f-bd06-5e95-808b-3f894e6eb7a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which finding best indicates lymphatic obstruction as the cause of edema?', '["Non-pitting, protein-rich swelling in the distribution of interrupted lymphatics","Pitting pretibial edema with elevated jugular venous pressure","Acute generalized anasarca from heart failure","Pulmonary crackles with gallop rhythm","Dependent edema that worsens overnight"]'::jsonb, 'Non-pitting, protein-rich swelling in the distribution of interrupted lymphatics', 'Lymphatic obstruction (filariasis, surgery, tumor, irradiation) leaves protein-rich fluid that resists displacement, giving firm, non-pitting swelling of the affected part.'),
('e2b8a22a-6c47-5bc3-ac15-aaec7a9dfcca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Edema accompanied by weight gain and a positive sodium balance, as in advanced renal failure, is principally mediated by:', '["Sodium and water retention","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Increased vascular permeability","Lymphatic obstruction"]'::jsonb, 'Sodium and water retention', 'Failing kidneys cannot excrete sodium and water, expanding the extracellular volume and producing edema; this is primary renal sodium and water retention.'),
('d11e9977-a22f-5636-8cd7-d3bb13fe2d2c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Thrombosis in a recumbent cancer patient with a central venous catheter best illustrates:', '["Hypercoagulability (with stasis and endothelial injury)","A pure platelet defect accompanied by associated clinical symptoms","Primary fibrinolysis mediated by specific receptor activation","Vitamin K excess without affecting the primary tissue pathway","Isolated lymphatic failure leading to subsequent cellular adaptation"]'::jsonb, 'Hypercoagulability (with stasis and endothelial injury)', 'Malignancy is a hypercoagulable state that, combined with the stasis of recumbency and catheter-related endothelial injury, reproduces all of Virchow''s triad.'),
('cafee3e7-d3a0-52ab-9e36-c05f7c080eb2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which setting most strongly favors deep vein thrombosis through venous stasis?', '["Prolonged immobility after surgery","Daily brisk walking","Chronic anticoagulation","Moderate aerobic exercise","Normal ambulation"]'::jsonb, 'Prolonged immobility after surgery', 'Immobilization abolishes the calf muscle pump, slowing venous flow and favoring deep vein thrombosis; mobility reverses this effect.'),
('ba79234f-4d80-56a9-b06a-b07b00c7adfa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Compared with a true antemortem thrombus, a postmortem clot characteristically:', '["Is gelatinous, dark red, and lacks lines of Zahn","Shows distinct lines of Zahn","Adheres firmly to the vessel wall","Is pale and platelet-rich","Contains cholesterol clefts"]'::jsonb, 'Is gelatinous, dark red, and lacks lines of Zahn', 'Postmortem clots are soft, gelatinous, and dark red, do not adhere to the vessel wall, and lack the laminations (lines of Zahn) of a true thrombus.'),
('54f05267-656b-50d9-8f7d-ea2f4d617c18'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pale gray-white thrombi composed largely of platelets and fibrin form in which setting?', '["Rapid arterial or cardiac flow","Venous stasis","The postmortem circulation","Septicemia","Disseminated intravascular coagulation"]'::jsonb, 'Rapid arterial or cardiac flow', 'White thrombi consist mainly of platelets and fibrin and form under rapid flow in arteries and heart, where they are often mural.'),
('9e9c42ee-d3ac-54ef-bda0-df39607072d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Red thrombi, consisting mostly of red cells enmeshed in fibrin, characteristically occur:', '["In veins where stasis prevails","In arteries at bifurcations","In the ventricular apex","On heart valves","At aortic atheromata"]'::jsonb, 'In veins where stasis prevails', 'Red thrombi are RBC-rich and form under venous stasis; they propagate in the direction of flow and are typically occlusive.'),
('a50566d2-c649-547a-a3c3-cfc5e3e39d03'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The propagating tail of a venous thrombus is composed mostly of:', '["Fibrin and red cells (red thrombus)","Platelets and fibrin","Cholesterol and foam cells","Fibroblasts and collagen","Calcified debris"]'::jsonb, 'Fibrin and red cells (red thrombus)', 'The occlusive, propagating portion of a venous thrombus is a red thrombus of fibrin and red cells; the pale head of platelets and fibrin is at the point of attachment.'),
('bcffd7ed-0a1e-57e7-a093-7268704f3f1e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A venous thrombus of the lower limb most commonly embolizes to:', '["Pulmonary arteries","Coronary arteries","Cerebral arteries","Renal artery","Hepatic artery"]'::jsonb, 'Pulmonary arteries', 'Fragments of a lower-limb deep vein thrombus travel through the right heart into the pulmonary arteries, causing pulmonary embolism.'),
('2f082ecc-7964-5181-a152-aaaa98acc274'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Paradoxical (crossed) embolism to the systemic circulation occurs when a venous embolus passes through:', '["A patent foramen ovale (right-to-left shunt)","The aortic valve","Pulmonary capillaries","Hepatic sinusoids","Arteriovenous malformations in the brain"]'::jsonb, 'A patent foramen ovale (right-to-left shunt)', 'A paradoxical embolus traverses a right-to-left intracardiac shunt such as a patent foramen ovale to gain access to the systemic circulation.'),
('2f5e7bd3-ffe1-5d17-b540-aff6c60579c1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A large embolus lodging at the bifurcation of the main pulmonary artery and causing sudden death is termed:', '["Saddle embolus","Miliary emboli","Paradoxical embolus","Septic embolus","Fat embolus"]'::jsonb, 'Saddle embolus', 'A saddle embolus straddles the pulmonary artery bifurcation, occluding both main branches and causing acute right heart failure with sudden death.'),
('5c172701-0a5a-502a-b447-1e81a7ae76e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which triad of findings classically characterizes the fat embolism syndrome?', '["Respiratory insufficiency, neurologic changes, petechial rash","Fever, jaundice, hematuria","Arthritis, rash, carditis","Anemia, thrombocytosis, splenomegaly","Polyuria, bradycardia, hypothermia"]'::jsonb, 'Respiratory insufficiency, neurologic changes, petechial rash', 'Fat embolism syndrome comprises pulmonary insufficiency, neurologic changes, and a petechial rash, typically appearing 1–3 days after a long-bone fracture.'),
('282ca850-c876-59bd-8329-4988df3de1af'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Air can be aspirated into the venous system during which procedure, causing collapse?', '["Central venous catheterization during inspiration","Routine peripheral cannula placement","Subcutaneous injection","Topical antiseptic application","Oral drug administration"]'::jsonb, 'Central venous catheterization during inspiration', 'With negative intrathoracic pressure during inspiration, air can be drawn into a large-caliber central venous catheter and form an air lock in the right ventricle.'),
('cec00e1a-fe21-515f-badf-40901fcc8a4e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Amniotic fluid embolism classically produces all of the following EXCEPT:', '["Chronic hypertension","Sudden cardiorespiratory collapse","Disseminated intravascular coagulation","Pulmonary hypertension","Hypoxemia"]'::jsonb, 'Chronic hypertension', 'Amniotic fluid embolism causes abrupt collapse, hypoxemia, pulmonary hypertension, and DIC; chronic hypertension is unrelated to the acute event.'),
('bbc1e257-fa2a-5b41-96f3-8b9ba65b11dd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'An infected embolus that produces an abscess at its destination is characteristic of:', '["Septic emboli from infective endocarditis","Bland thrombus from atrial fibrillation","Fat emboli from a long-bone fracture","Air emboli","Myxoma fragments"]'::jsonb, 'Septic emboli from infective endocarditis', 'Septic emboli from infected valves carry bacteria to distant sites, causing infarction with suppuration (abscess formation) in the brain, kidney, or spleen.'),
('6b4212f8-430f-5e6c-9f73-a4e8053e8ce0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The most common source of major systemic (arterial) emboli is:', '["Mural thrombi in the left heart","Right iliac vein thrombus","Deep calf vein thrombus","Hepatic vein thrombus","Splenic vein thrombus"]'::jsonb, 'Mural thrombi in the left heart', 'Most systemic emboli arise from left-sided cardiac mural thrombi (post-infarct or in atrial fibrillation) or from atheromatous debris in the aorta.'),
('befbf5dc-cb0f-5a67-a7e1-03d818d6e8ad'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pale, softened myocardium in myocardial infarction first becomes grossly apparent after approximately:', '["12-24 hours","Minutes","1 week","1 month","3 months"]'::jsonb, '12-24 hours', 'Coagulative necrosis changes the gross appearance of the infarcted myocardium within about 12–24 hours; histologic features are evident within the first day.'),
('d1c188a7-4bdb-5358-87a0-1db6123caa13'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Infarcts of the brain characteristically undergo which type of necrosis?', '["Liquefactive necrosis","Coagulative necrosis","Caseous necrosis","Fat necrosis","Fibrinoid necrosis"]'::jsonb, 'Liquefactive necrosis', 'Glial cells release hydrolytic enzymes, so cerebral infarcts soften into a liquid-filled cystic cavity in the process of liquefactive (colliquative) necrosis.'),
('ae9005c8-5e33-56e5-9e40-11bc799d0722'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A wedge-shaped, pale infarct with its apex at the occluded vessel is classically seen in the:', '["Kidney and spleen","Lung","Liver","Intestine","Skin"]'::jsonb, 'Kidney and spleen', 'Occlusion of an end artery in the solid organs kidney or spleen produces a wedge-shaped white infarct pointing toward the occluded vessel.'),
('32a1f73d-b1f9-52c1-ac98-ac239a1bdd1a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Dry gangrene of a toe in a diabetic is characterized by:', '["Coagulative necrosis with a well-demarcated line of separation","Liquefactive necrosis with infection","Bacterial superinfection with edema","Extensive gas formation","Suppuration and cellulitis"]'::jsonb, 'Coagulative necrosis with a well-demarcated line of separation', 'Dry gangrene is coagulative necrosis of a distal limb, usually with a sharp line of demarcation and little bacterial infection.'),
('b891c63e-363f-5c57-9582-a8dcda5c3c9e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Wet gangrene, in contrast to dry gangrene, is characterized by:', '["Superimposed bacterial infection with liquefaction and edema","Absence of infection accompanied by associated clinical symptoms","Sharp demarcation mediated by specific receptor activation","Minimal tissue swelling without affecting the primary tissue pathway","Slow, dry mummification leading to subsequent cellular adaptation"]'::jsonb, 'Superimposed bacterial infection with liquefaction and edema', 'Wet gangrene combines necrosis with putrefactive bacterial infection, producing moist, swollen, foul-smelling tissue; it characteristically affects internal organs such as the bowel.'),
('a4cfc6c5-885d-549c-a088-509d28c569c4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which hemodynamic pattern is characteristic of cardiogenic shock?', '["Low cardiac output with elevated filling pressures","Low cardiac output with flat neck veins","High output with bounding pulses","Normal output with hypotension","Polycythemia with high viscosity"]'::jsonb, 'Low cardiac output with elevated filling pressures', 'In cardiogenic shock the failing pump lowers cardiac output while left- and right-sided filling pressures rise, giving distended neck veins and pulmonary edema.'),
('e2cbbdc8-9769-507a-9dd5-fab30001a587'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which finding favors hypovolemic rather than cardiogenic shock?', '["Flat neck veins with low central venous pressure","Jugular venous distension","Pulmonary crackles on auscultation","Muffled heart sounds","Warm flushed extremities"]'::jsonb, 'Flat neck veins with low central venous pressure', 'Blood volume is depleted in hypovolemic shock, so neck veins are flat and central venous pressure is low, unlike cardiogenic shock where filling pressures are high.'),
('ea3d0281-bd87-517a-9abf-5686799b24d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In the late (cold) phase of septic shock, the patient characteristically develops:', '["Cold, clammy skin with worsening hypotension and lactic acidosis","Warm flushed skin with bounding pulse accompanied by associated clinical symptoms","Polyuria mediated by specific receptor activation","Bradycardia without affecting the primary tissue pathway","Hyperventilation only leading to subsequent cellular adaptation"]'::jsonb, 'Cold, clammy skin with worsening hypotension and lactic acidosis', 'With decompensation septic shock becomes a low-output state with cold extremities, worsening hypotension, and lactic acidosis from tissue hypoxia.'),
('abfff206-8e36-5956-8a23-1b8571b7383e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Acute tubular necrosis of the kidneys is a feature of which stage of shock?', '["Refractory (end-stage) shock","Initial compensatory phase","Mild compensated phase","Early hyperdynamic phase","Recovery phase"]'::jsonb, 'Refractory (end-stage) shock', 'Prolonged renal hypoperfusion during progressive and refractory shock causes acute tubular necrosis with oliguric renal failure.'),
('e9f445ec-0b0b-5eaf-94aa-8c04f8740d81'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Diffuse alveolar damage with hyaline membranes is the hallmark of which shock complication?', '["ARDS (shock lung)","Fat embolism","Pulmonary thromboembolism","Pneumonia","Bronchiolitis"]'::jsonb, 'ARDS (shock lung)', 'In shock and sepsis, diffuse alveolar damage produces hyaline membranes and alveolar flooding, the defining features of ARDS (''shock lung'').'),
('5ec65488-0ec8-517c-bc4b-63ba6cb2578d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Disseminated intravascular coagulation is best characterized by:', '["Widespread microvascular thrombosis with paradoxical bleeding","Isolated arterial thrombosis","Persistent thrombocytosis","Selective platelet dysfunction","Primary fibrinolysis without clot formation"]'::jsonb, 'Widespread microvascular thrombosis with paradoxical bleeding', 'DIC paradoxically combines widespread microvascular thrombi with a bleeding tendency, because clotting factors and platelets are consumed in the thrombi.'),
('7b1c7135-70d7-591a-b494-83309a719b64'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Purpuric skin lesions and acral ischemia in a septic patient most likely result from:', '["DIC with microvascular thrombosis","Simple contusion","Vitamin C deficiency","Hereditary telangiectasia","Thrombocytosis"]'::jsonb, 'DIC with microvascular thrombosis', 'Microvascular thrombi of DIC occlude skin vessels, producing purpura and necrosis of the digits in severe sepsis.'),
('710a36e0-221c-5854-84b6-617882a4bd52'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Thrombocytopenia in disseminated intravascular coagulation results from:', '["Consumption in widespread microvascular thrombi","Bone marrow aplasia","Autoantibody attack on platelets","Splenic sequestration alone","Chronic liver disease alone"]'::jsonb, 'Consumption in widespread microvascular thrombi', 'In DIC the platelets are trapped and consumed in platelet-fibrin thrombi throughout the microvasculature, causing the characteristic thrombocytopenia.'),
('9f717962-466e-5e0e-93f5-ba0a1bf57318'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Oral warfarin anticoagulation is best monitored by:', '["Prothrombin time (INR)","Activated partial thromboplastin time (aPTT)","Platelet count","Bleeding time","D-dimer"]'::jsonb, 'Prothrombin time (INR)', 'Warfarin lowers the vitamin K-dependent factors, so the prothrombin time (INR), which tests the extrinsic pathway, is the monitoring test.'),
('933e2547-86c3-58f5-9b33-73e89cb7e56f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Intravenous unfractionated heparin therapy is monitored using:', '["Activated partial thromboplastin time (aPTT)","Prothrombin time (INR) accompanied by associated clinical symptoms","Thrombin time only mediated by specific receptor activation","Fibrinogen level without affecting the primary tissue pathway","Platelet count leading to subsequent cellular adaptation"]'::jsonb, 'Activated partial thromboplastin time (aPTT)', 'Heparin prolongs the aPTT through antithrombin III, and this test is used for dose adjustment; low-molecular-weight heparin is monitored with an anti-factor Xa assay when needed.'),
('6e434c66-17c6-595e-8fc2-e80a6230f66f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'When monitoring of low-molecular-weight heparin is required (e.g., in renal impairment), the test of choice is:', '["Anti-factor Xa assay","aPTT","INR","Bleeding time","Fibrinogen"]'::jsonb, 'Anti-factor Xa assay', 'Low-molecular-weight heparin inhibits factor Xa more than thrombin and may not prolong the aPTT, so an anti-factor Xa assay is used when monitoring is necessary.'),
('4d24cb7b-5720-5cde-bca1-69ffc763bd49'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Resistance of factor Va to inactivation by activated protein C is the laboratory signature of:', '["Factor V Leiden","Antithrombin deficiency","Protein C deficiency","Prothrombin gene mutation","Plasminogen deficiency"]'::jsonb, 'Factor V Leiden', 'Resistance to activated protein C defines factor V Leiden, the most common inherited thrombophilia predisposing to venous thrombosis.'),
('1158be09-c928-5fd9-9425-fcc0eac4e733'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which immune-mediated reaction complicates heparin therapy with thrombocytopenia and thrombosis?', '["Heparin-induced thrombocytopenia (HIT)","Immune thrombocytopenic purpura","Thrombotic thrombocytopenic purpura","Hemolytic-uremic syndrome","Von Willebrand disease"]'::jsonb, 'Heparin-induced thrombocytopenia (HIT)', 'Antibodies to heparin-platelet factor 4 complexes activate platelets, causing thrombocytopenia and paradoxical venous or arterial thrombosis in HIT.'),
('590a226a-ad82-56b6-9184-99d993228fa2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A prolonged aPTT due to a lupus anticoagulant that paradoxically predisposes to thrombosis characterizes:', '["Antiphospholipid syndrome","Hemophilia B","Von Willebrand disease","Vitamin K deficiency","Disseminated intravascular coagulation"]'::jsonb, 'Antiphospholipid syndrome', 'The lupus anticoagulant prolongs the aPTT in vitro yet creates a prothrombotic state with arterial and venous thrombosis; this defines antiphospholipid syndrome.'),
('0747dc83-813a-5024-9872-674611f5e75f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Brown, firm lungs in chronic congestive heart failure result from:', '["Hemosiderin deposition and fibrosis","Emphysematous destruction","Mucus plugging","Anthracotic pigment","Amyloid deposition"]'::jsonb, 'Hemosiderin deposition and fibrosis', 'Repeated congestion with small hemorrhages deposits hemosiderin and stimulates interstitial fibrosis, giving firm, rusty-brown lungs (brown induration).'),
('b4cd1428-58bc-5010-aedf-b101bd7ef07d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Intra-alveolar macrophages containing golden-brown hemosiderin pigment are characteristic of:', '["Chronic passive congestion of the lungs","Emphysema accompanied by associated clinical symptoms","Acute pneumonia mediated by specific receptor activation","Tuberculosis without affecting the primary tissue pathway","Asthma leading to subsequent cellular adaptation"]'::jsonb, 'Chronic passive congestion of the lungs', 'Hemosiderin-laden alveolar macrophages (heart failure cells) indicate old pulmonary hemorrhage, as in chronic passive congestion.'),
('100429dc-09bf-5ce3-a07e-76c9a7d26ab8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The ''nutmeg'' appearance of the congested liver results from:', '["Red centrilobular congestion against tan periportal parenchyma","Diffuse yellow steatosis accompanied by associated clinical symptoms","Black melanin deposits mediated by specific receptor activation","Green bile staining without affecting the primary tissue pathway","White fibrous septa leading to subsequent cellular adaptation"]'::jsonb, 'Red centrilobular congestion against tan periportal parenchyma', 'Centrilobular congestion (red) against fatty periportal zones (tan) gives the mottled nutmeg pattern of chronic passive congestion.'),
('ae4d99ba-b078-5a8d-bfb5-7858e818d99c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Chronic passive congestion of the liver is best explained by:', '["Elevated hepatic venous pressure from right heart failure","Reduced hepatic arterial flow","Portal vein thrombus","Biliary obstruction","Hepatic vein neoplastic invasion alone"]'::jsonb, 'Elevated hepatic venous pressure from right heart failure', 'Right heart failure raises hepatic vein pressure, congesting the centrilobular sinusoids; this is the classic cause of chronic passive congestion.'),
('207d66ed-b100-527e-9d08-a4fcd7394dd7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Chronic passive congestion in portal hypertension causes the spleen to become:', '["Enlarged, firm, and fibrotic (congestive splenomegaly)","Shrunken and calcified accompanied by associated clinical symptoms","Necrotic and hemorrhagic mediated by specific receptor activation","Cystic without affecting the primary tissue pathway","Normal in size leading to subsequent cellular adaptation"]'::jsonb, 'Enlarged, firm, and fibrotic (congestive splenomegaly)', 'Long-standing portal hypertension congests and progressively fibroses the spleen, producing a firm, enlarged organ (chronic congestive splenomegaly).'),
('10511bae-8cef-5723-8885-99c829ec8c0c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Edema in advanced chronic kidney disease is chiefly due to:', '["Sodium and water retention","Increased vascular permeability","Lymphatic obstruction","Decreased capillary hydrostatic pressure","Elevated plasma oncotic pressure"]'::jsonb, 'Sodium and water retention', 'Failing kidneys cannot excrete sodium and water, expanding the extracellular volume and producing edema; hypoalbuminemia contributes secondarily.'),
('25eebabd-62b1-587a-a824-ad290796fe32'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which feature is most characteristic of lymphedema rather than hydrostatic edema?', '["Protein-rich fluid that fails to pit on pressure","Low-protein fluid that pits readily","Rapid resolution on leg elevation","Associated pulmonary crackles","Central distribution affecting both eyelids"]'::jsonb, 'Protein-rich fluid that fails to pit on pressure', 'Lymphatic obstruction leaves protein-rich interstitial fluid that resists displacement (non-pitting), whereas hydrostatic edema is low-protein and pits easily.'),
('488a3159-e9e4-5960-9624-674314a5f2e6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Non-pitting edema of hypothyroidism is caused by accumulation of:', '["Mucinous (mucopolysaccharide) ground substance","Free water only accompanied by associated clinical symptoms","Lipid droplets mediated by specific receptor activation","Amyloid without affecting the primary tissue pathway","Hemosiderin leading to subsequent cellular adaptation"]'::jsonb, 'Mucinous (mucopolysaccharide) ground substance', 'Hypothyroidism deposits mucopolysaccharides (hyaluronic acid) in the dermis, producing the firm, waxy, non-pitting edema of myxedema.'),
('136417a5-66ed-5756-807a-74964af60899'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Severe generalized edema involving the entire body is termed:', '["Anasarca","Ascites","Hydrothorax","Peripheral lymphedema","Angioedema"]'::jsonb, 'Anasarca', 'Anasarca is diffuse severe edema of the subcutaneous tissues, often with cavity effusions, seen in advanced cardiac, renal, or hepatic failure.'),
('ea46b832-0fab-5c85-8d24-155ba98a81a2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Accumulation of fluid in the peritoneal cavity is called:', '["Ascites","Anasarca","Pleural effusion","Hemothorax","Pericardial effusion"]'::jsonb, 'Ascites', 'Ascites is fluid in the peritoneal cavity, a transudate in portal hypertension and a protein-rich exudate in peritonitis or carcinomatosis.'),
('58d387a1-be85-5684-b2de-cda673c9f613'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A transudative pleural effusion is classically associated with:', '["Congestive heart failure","Pneumonia","Tuberculosis","Malignant mesothelioma","Pulmonary infarction"]'::jsonb, 'Congestive heart failure', 'Transudative effusions reflect increased hydrostatic pressure or low oncotic pressure, as in heart failure, cirrhosis, and nephrotic syndrome; infection and malignancy cause exudates.'),
('e1083762-a9e0-5dac-a4d8-9f61ed94f56f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'An exudative effusion with high protein content is classically due to:', '["Pneumonia or malignancy with increased permeability","Congestive heart failure accompanied by associated clinical symptoms","Nephrotic syndrome mediated by specific receptor activation","Cirrhosis without affecting the primary tissue pathway","Hypothyroidism leading to subsequent cellular adaptation"]'::jsonb, 'Pneumonia or malignancy with increased permeability', 'Exudates are protein- and cell-rich fluids formed by increased vascular permeability (pneumonia, malignancy, tuberculosis), whereas heart, liver, and renal disease produce transudates.'),
('bcce1d50-3d6a-556d-859b-065f5f04e3d7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Vasogenic cerebral edema is characterized by:', '["Breakdown of the blood-brain barrier with protein-rich fluid spreading in the white matter","Pure intracellular swelling of all cell types accompanied by associated clinical symptoms","Periventricular fluid in hydrocephalus mediated by specific receptor activation","No actual brain swelling without affecting the primary tissue pathway","Selective involvement of grey matter only leading to subsequent cellular adaptation"]'::jsonb, 'Breakdown of the blood-brain barrier with protein-rich fluid spreading in the white matter', 'Vasogenic edema follows disruption of the blood-brain barrier (tumors, abscess, trauma), with protein-rich fluid spreading preferentially through the white matter.'),
('cbffedfa-4d2f-5803-97a0-c579fb9e4843'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Cytotoxic cerebral edema, as in ischemia or toxin exposure, results from:', '["Direct swelling of neurons, glia, and endothelial cells due to membrane pump failure","Breakdown of the blood-brain barrier accompanied by associated clinical symptoms","Obstructive hydrocephalus mediated by specific receptor activation","Venous congestion without affecting the primary tissue pathway","Meningeal inflammation leading to subsequent cellular adaptation"]'::jsonb, 'Direct swelling of neurons, glia, and endothelial cells due to membrane pump failure', 'Cytotoxic edema is intracellular swelling caused by failure of membrane ion pumps (Na+/K+-ATPase) during ischemia, hypoxia, or toxins, without primary barrier breakdown.'),
('05ccb638-5042-5079-be99-f852c64154ac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The periventricular interstitial edema of hydrocephalus is due to:', '["Transependymal passage of CSF under raised pressure","Blood-brain barrier breakdown","Cytotoxic injury from hypoxia","Inflammatory exudate","Venous thrombosis"]'::jsonb, 'Transependymal passage of CSF under raised pressure', 'In hydrocephalus, raised CSF pressure forces fluid across the ependyma into the periventricular white matter, producing interstitial edema.'),
('49b4d821-efd6-5197-950c-2d878550f544'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Repeated and prolonged hemorrhage into the deep subcutaneous tissue produces which lesion?', '["Hematoma","Petechiae","Purpura","Telangiectasia","Ecchymotic streak"]'::jsonb, 'Hematoma', 'A hematoma is a large, localized collection of blood in the tissues, in contrast to the flat petechiae, purpura, and ecchymoses.'),
('af34fbc6-cb2d-5078-9ed8-e7001e4587d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Administration of concentrated albumin to a hypoalbuminemic patient reduces edema by:', '["Raising plasma oncotic pressure and drawing fluid into the vessels","Increasing capillary hydrostatic pressure","Blocking lymphatic channels","Decreasing renal sodium excretion","Increasing vascular permeability"]'::jsonb, 'Raising plasma oncotic pressure and drawing fluid into the vessels', 'Albumin raises plasma colloid osmotic pressure, increasing the reabsorption of interstitial fluid back into the circulation.'),
('efff4563-eeae-5f7a-a352-a2ac564dae7e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Chronic venous insufficiency with varicose veins produces ankle edema through:', '["Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Lymphatic obstruction","Increased vascular permeability","Sodium and water retention"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Incompetent venous valves raise venous and capillary pressures in the leg, increasing filtration of fluid out of the vessels.'),
('99542482-29f4-59f2-8446-4f186764ff29'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Radiation fibrosis causing arm edema after treatment for breast cancer causes:', '["Lymphatic obstruction","Increased capillary hydrostatic pressure","Increased vascular permeability","Decreased plasma oncotic pressure","Sodium and water retention"]'::jsonb, 'Lymphatic obstruction', 'Radiation scars the axillary lymphatic channels, blocking drainage of interstitial fluid and causing protein-rich arm edema.'),
('14223f88-120e-541c-804c-1f291edd61e9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Capillary leak syndrome in severe sepsis produces edema by:', '["Increased vascular permeability","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Sodium and water retention","Lymphatic obstruction"]'::jsonb, 'Increased vascular permeability', 'Sepsis damages endothelium and increases the leak of protein and fluid into tissues, the basis of capillary leak syndrome.'),
('76e547da-be71-527e-bee5-831d0af2d24f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Edema in protein-losing enteropathy follows a fall in:', '["Plasma oncotic pressure","Capillary hydrostatic pressure","Vascular permeability","Lymphatic drainage","Renal sodium excretion"]'::jsonb, 'Plasma oncotic pressure', 'Gastrointestinal protein loss lowers serum albumin and plasma colloid osmotic pressure, reducing reabsorption of interstitial fluid.'),
('e6b2ca72-dc61-5cd5-be27-b2ea127f898c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The generalized edema of the nephrotic syndrome results chiefly from:', '["Decreased plasma oncotic pressure plus secondary sodium retention","Isolated lymphatic obstruction accompanied by associated clinical symptoms","Primary arteriolar dilation mediated by specific receptor activation","Congestive heart failure without affecting the primary tissue pathway","Pulmonary hypertension leading to subsequent cellular adaptation"]'::jsonb, 'Decreased plasma oncotic pressure plus secondary sodium retention', 'Heavy proteinuria lowers plasma oncotic pressure, while the resulting hypovolemia secondarily stimulates renal sodium retention; both generate generalized edema.'),
('b05fcb99-3c2f-55e6-82fb-2066ce6e79d7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pulmonary edema in ARDS results from:', '["Increased alveolar-capillary membrane permeability","Elevated left atrial pressure accompanied by associated clinical symptoms","Lymphatic obstruction mediated by specific receptor activation","Hypoalbuminemia without affecting the primary tissue pathway","Right heart failure leading to subsequent cellular adaptation"]'::jsonb, 'Increased alveolar-capillary membrane permeability', 'ARDS is permeability (non-cardiogenic) pulmonary edema: the alveolar-capillary membrane leaks protein-rich fluid without elevated left atrial pressure.'),
('6a326eca-fa4d-5e82-b5f8-cdcf8653d3da'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'After a long airline flight, ankle swelling in a healthy traveler results mainly from:', '["Increased capillary hydrostatic pressure in dependent veins","Lymphatic obstruction accompanied by associated clinical symptoms","Low plasma oncotic pressure mediated by specific receptor activation","Increased vascular permeability without affecting the primary tissue pathway","Primary sodium retention leading to subsequent cellular adaptation"]'::jsonb, 'Increased capillary hydrostatic pressure in dependent veins', 'Prolonged dependency raises venous and capillary pressures in the legs, favoring filtration of fluid; mild venous stasis contributes as well.'),
('8aef36ae-afe7-5a8d-a194-e8a85592f670'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Kwashiorkor-type malnutrition causes edema because of:', '["Decreased plasma oncotic pressure from hypoalbuminemia","Increased vascular permeability","Increased capillary hydrostatic pressure","Lymphatic obstruction","Renal salt overload"]'::jsonb, 'Decreased plasma oncotic pressure from hypoalbuminemia', 'Severe protein deficiency lowers serum albumin and plasma oncotic pressure, producing the edema and ascites characteristic of kwashiorkor.'),
('2d79241c-4f55-53c8-a3e7-19eed1f9e2ad'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which two forces combine to produce ascites in cirrhosis?', '["Portal hypertension (hydrostatic) and hypoalbuminemia (oncotic)","Increased permeability alone","Lymphatic obstruction alone","Portal hypotension and hyperalbuminemia","Sodium wasting with hypovolemia"]'::jsonb, 'Portal hypertension (hydrostatic) and hypoalbuminemia (oncotic)', 'Portal venous hypertension raises filtration pressure while low albumin reduces reabsorption; together they generate cirrhotic ascites, reinforced by secondary sodium retention.'),
('b6563253-2500-5864-b108-706cc6155e46'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A pelvic tumor obstructing the iliac lymphatics produces leg edema via:', '["Lymphatic obstruction","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Increased vascular permeability","Sodium and water retention"]'::jsonb, 'Lymphatic obstruction', 'Tumor occluding the lymphatics prevents clearance of interstitial fluid and protein, causing unilateral, often non-pitting leg edema.'),
('ac37133f-cc4f-5e7b-b9f9-29dabef13b5a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Primary hyperaldosteronism contributes to edema mainly through:', '["Sodium and water retention","Increased vascular permeability","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Lymphatic obstruction"]'::jsonb, 'Sodium and water retention', 'Excess aldosterone drives renal tubular sodium conservation with obligated water, expanding the extracellular volume and producing edema.'),
('6ffd97b3-ff90-500d-b7f1-48d7a9b15364'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The protein-rich fluid of acute inflammation is produced by:', '["Increased vascular permeability","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Increased vascular permeability', 'Inflammatory mediators open gaps between endothelial cells, letting protein and fluid into the tissues and generating an exudate.'),
('cf28dac2-fc05-558f-aff4-5b4dc4efe745'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Bleeding into a joint space is called:', '["Hemarthrosis","Hemoptysis","Hematemesis","Hematuria","Hematochezia"]'::jsonb, 'Hemarthrosis', 'Hemarthrosis is blood in a joint cavity, most classically seen in hemophilia and trauma.'),
('9ec80ba9-4c58-5d10-8ce1-cd7d687d2e4a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Melena most often indicates bleeding from the:', '["Upper gastrointestinal tract","Lower gastrointestinal tract only","Lungs","Kidney","Skin"]'::jsonb, 'Upper gastrointestinal tract', 'The black, tarry stool of melena reflects digestion of blood, typically from a bleeding site proximal to the colon.'),
('557117f4-c601-516b-8b02-4acdad88ff98'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Bleeding from the nasal mucosa is termed:', '["Epistaxis","Hemoptysis","Hematemesis","Melena","Hematuria"]'::jsonb, 'Epistaxis', 'Epistaxis is nosebleed, usually from the vascular plexus of the nasal septum; it is common in hypertension, nasal trauma, and mucosal drying.'),
('0ce1c4bf-a3cc-5db5-afbb-f207e71b8b8c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hemoptysis (coughing blood) classically originates from bleeding in the:', '["Bronchi or lungs","Stomach","Nasal cavities","Renal pelvis","Colon"]'::jsonb, 'Bronchi or lungs', 'Hemoptysis is blood arising from the tracheobronchial tree or lung parenchyma, as in bronchiectasis, tuberculosis, and lung cancer.'),
('09995682-1703-59d3-bdc2-72b5c707852b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hematemesis represents bleeding from the:', '["Upper gastrointestinal tract (vomited blood)","Lower respiratory tract accompanied by associated clinical symptoms","Urinary tract mediated by specific receptor activation","Nasopharynx only without affecting the primary tissue pathway","Peripheral arteries leading to subsequent cellular adaptation"]'::jsonb, 'Upper gastrointestinal tract (vomited blood)', 'Hematemesis is the vomiting of blood from the esophagus, stomach, or duodenum, as with varices, peptic ulcers, and Mallory-Weiss tears.'),
('1d17c878-dcd6-566a-b798-cef2f1974309'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Petechiae characteristically occur with bleeding due to:', '["Thrombocytopenia or platelet dysfunction","Isolated deficiency of factor VIII","Vitamin K deficiency alone","Hepatic sinusoidal congestion","High plasma oncotic pressure"]'::jsonb, 'Thrombocytopenia or platelet dysfunction', 'Pinpoint petechial hemorrhages are the hallmark of platelet disorders; coagulation factor deficiencies more typically cause larger ecchymoses and hematomas.'),
('b7d28125-bb66-534f-990c-4393c104a076'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Von Willebrand disease is characterized by defective:', '["Platelet adhesion due to abnormal von Willebrand factor","Fibrin cross-linking accompanied by associated clinical symptoms","Prothrombin activation mediated by specific receptor activation","Antithrombin function without affecting the primary tissue pathway","Plasminogen activation leading to subsequent cellular adaptation"]'::jsonb, 'Platelet adhesion due to abnormal von Willebrand factor', 'Von Willebrand factor mediates platelet adhesion to exposed subendothelium via glycoprotein Ib; its deficiency causes mucocutaneous bleeding.'),
('ffec2f3d-4093-5ed6-9806-525d1fabba44'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Platelet adhesion to von Willebrand factor at sites of vascular injury is mediated by the platelet receptor:', '["Glycoprotein Ib","Glycoprotein IIb/IIIa","Glycoprotein IIa","Integrin alpha-V beta-3","CD44"]'::jsonb, 'Glycoprotein Ib', 'Platelet adherence depends on glycoprotein Ib binding to von Willebrand factor on the exposed matrix; the subsequent aggregation step uses GPIIb/IIIa with fibrinogen.'),
('99b30e3f-c12f-5bff-8769-83c4bf341301'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Platelet aggregation (platelet-platelet bridging by fibrinogen) requires which receptor?', '["Glycoprotein IIb/IIIa","Glycoprotein Ib","Glycoprotein Ia","P-selectin","Factor VII receptor"]'::jsonb, 'Glycoprotein IIb/IIIa', 'Activated glycoprotein IIb/IIIa binds fibrinogen, cross-linking platelets into aggregates; Glanzmann thrombasthenia lacks this receptor.'),
('78d09a5a-32ea-585a-b10c-a763384cd581'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Retraction of a mature blood clot is performed by:', '["Platelets (contractile proteins)","Red cells accompanied by associated clinical symptoms","Neutrophils mediated by specific receptor activation","Eosinophils without affecting the primary tissue pathway","Lymphocytes leading to subsequent cellular adaptation"]'::jsonb, 'Platelets (contractile proteins)', 'Contractile platelet proteins (thrombosthenin) retract the clot, which is why clot retraction is defective in platelet disorders.'),
('f17227e1-2479-5e32-a358-67acc98b5eee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Conversion of fibrinogen to fibrin by thrombin occurs in which step of coagulation?', '["Final common pathway","Extrinsic pathway initiation","Intrinsic pathway amplification","Contact activation","Fibrinolysis"]'::jsonb, 'Final common pathway', 'Thrombin cleaves fibrinogen to fibrin in the final common pathway, and factor XIIIa then cross-links the fibrin into a stable mesh.'),
('c036473f-5dc7-5ca9-af83-2d1503c3f3aa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The extrinsic pathway of coagulation is initiated by:', '["Tissue factor (factor III) from damaged vessels","Factor XIIa accompanied by associated clinical symptoms","Platelet phospholipid alone mediated by specific receptor activation","Factor VIIIa without affecting the primary tissue pathway","Plasmin leading to subsequent cellular adaptation"]'::jsonb, 'Tissue factor (factor III) from damaged vessels', 'The extrinsic pathway begins when tissue factor (factor III) exposed on damaged vessels binds factor VIIa; the intrinsic pathway starts with factor XII contact activation.'),
('74e6651d-fb5b-537f-a9d4-7c2f49fad786'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The intrinsic pathway of coagulation begins with activation of factor:', '["XII (Hageman factor)","VII accompanied by associated clinical symptoms","II mediated by specific receptor activation","IX without affecting the primary tissue pathway","X leading to subsequent cellular adaptation"]'::jsonb, 'XII (Hageman factor)', 'Contact activation of factor XII starts the intrinsic pathway, which is subsequently amplified by factors VIII, IX, and XI before converging at factor X.'),
('01955dfa-6eac-51ec-b0da-1f96bb3f56ff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Both the intrinsic and extrinsic pathways of coagulation converge at the activation of which factor?', '["Factor X","Factor XII","Factor VII","Factor VIII","Factor XI"]'::jsonb, 'Factor X', 'Factor X activation is the convergence point (final common pathway), after which prothrombinase generates thrombin and then fibrin.'),
('f8c7376a-e03f-5583-9b4f-2663c55d3e10'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The fibrinolytic system dissolves a clot through:', '["Plasmin cleavage of fibrin","Thrombin activation","Factor XIII cross-linking","Platelet contraction","Fibrinogen synthesis"]'::jsonb, 'Plasmin cleavage of fibrin', 'Plasmin, formed from plasminogen by tPA or urokinase, cleaves fibrin into degradation products and dissolves the clot; D-dimer reflects such degradation.'),
('cdde59ce-2138-56d0-a9df-117496221c71'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Acute pulmonary edema with pink frothy sputum during acute left ventricular failure is driven by:', '["Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Increased vascular permeability","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Increased capillary hydrostatic pressure', 'Acute left heart failure raises pulmonary capillary hydrostatic pressure, flooding the alveoli with low-protein fluid and occasionally red cells producing pink froth.'),
('c72ee68a-7153-5042-8aa6-d6b72b8e0a6d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hepatic synthetic failure with a serum albumin below 2.0 g/dL causes peripheral edema and ascites predominantly through:', '["Decreased plasma oncotic pressure","Increased capillary hydrostatic pressure","Increased vascular permeability","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Decreased plasma oncotic pressure', 'The failing liver cannot synthesize albumin, so plasma oncotic pressure falls and less interstitial fluid is reabsorbed into the vessels.'),
('001de9a0-7a62-5475-b310-0787ed490a5b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Generalized capillary leak during severe dengue produces edema via:', '["Increased vascular permeability","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Increased vascular permeability', 'Viral infection damages endothelium and opens inter-endothelial gaps, letting protein-rich plasma leak into the tissues.'),
('9e5a194f-7dde-5714-82eb-fa6fbf6719e3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Non-pitting leg swelling after pelvic lymphadenectomy for cervical cancer is due to:', '["Lymphatic obstruction","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Increased vascular permeability","Sodium and water retention"]'::jsonb, 'Lymphatic obstruction', 'Surgical removal of pelvic lymphatics blocks drainage of interstitial fluid and protein, giving persistent uni- or bilateral leg lymphedema.'),
('ec14edb4-a21d-564f-a278-947563c98f8a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Refractory heart-failure edema worsens when aldosterone makes the kidneys retain salt and water. The pivotal mechanism is:', '["Sodium and water retention","Increased vascular permeability","Increased capillary hydrostatic pressure","Lymphatic obstruction","Decreased plasma oncotic pressure"]'::jsonb, 'Sodium and water retention', 'Aldosterone-driven conservation of sodium and water expands extracellular volume, progressively aggravating the edema of heart failure.'),
('eea0e6df-82d0-5df2-8f28-970887bb116d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In the nephrotic syndrome, massive proteinuria lowers the serum albumin; the resultant edema is chiefly due to:', '["Decreased plasma oncotic pressure","Increased capillary hydrostatic pressure","Increased vascular permeability","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Decreased plasma oncotic pressure', 'Urinary albumin loss lowers plasma colloid osmotic pressure, reducing reabsorption of fluid from the interstitium and producing generalized edema.'),
('6f4b19bc-87c8-5530-9945-cd8ad4f8d0f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Edema developing rapidly after extensive superficial burns is attributed mainly to:', '["Increased vascular permeability","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Sodium and water retention","Lymphatic obstruction"]'::jsonb, 'Increased vascular permeability', 'Thermal injury damages the endothelium widely, acutely increasing vascular permeability and letting protein-rich fluid into the tissues.'),
('c0118651-3d0b-524e-8a42-76b620c42e4a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In Budd-Chiari syndrome the ascites results chiefly from:', '["Increased hepatic sinusoidal hydrostatic pressure","Decreased plasma oncotic pressure","Increased vascular permeability","Primary sodium wasting","Lymphatic obstruction"]'::jsonb, 'Increased hepatic sinusoidal hydrostatic pressure', 'Hepatic vein obstruction raises sinusoidal (hydrostatic) pressure in the liver, driving fluid into the peritoneal cavity as ascites.'),
('74ce891d-c5d4-543c-81cc-3000f912ed35'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The swelling of lymphedema is characteristically non-pitting because the interstitial fluid is rich in:', '["Protein","Sodium chloride","Free water","Lipids","Calcium"]'::jsonb, 'Protein', 'Lymphatic obstruction leaves protein-rich fluid that resists displacement, whereas low-protein hydrostatic edema pits easily.'),
('ea70f649-3fa4-549b-bf52-4c3495ade208'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The waxy, non-pitting edema of hypothyroidism results from deposition of:', '["Mucinous (mucopolysaccharide) ground substance","Free interstitial water accompanied by associated clinical symptoms","Hemosiderin mediated by specific receptor activation","Amyloid fibrils without affecting the primary tissue pathway","Fat globules leading to subsequent cellular adaptation"]'::jsonb, 'Mucinous (mucopolysaccharide) ground substance', 'Myxedema reflects accumulation of mucopolysaccharides (hyaluronan) in the dermis, giving a firm, doughy, non-pitting swelling.'),
('70dffba6-7ebf-58a5-8539-fdbcb3bd92ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'At the venous end of a capillary, fluid tends to be reabsorbed because of:', '["Plasma colloidal oncotic pressure exceeding local hydrostatic pressure","Elevated capillary hydrostatic pressure accompanied by associated clinical symptoms","Lymphatic back-pressure mediated by specific receptor activation","Increased vascular permeability without affecting the primary tissue pathway","Sodium influx leading to subsequent cellular adaptation"]'::jsonb, 'Plasma colloidal oncotic pressure exceeding local hydrostatic pressure', 'At the venous end oncotic pressure exceeds the (falling) hydrostatic pressure, so fluid is drawn back into the capillary; any imbalance produces edema.'),
('6e9281ff-b4da-5ced-8938-52dd4015f369'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hematuria accompanied by red cell casts points to bleeding from the:', '["Glomeruli (as in glomerulonephritis)","Urethra after trauma","Bladder stone","Prostatic bed","Renal pelvis"]'::jsonb, 'Glomeruli (as in glomerulonephritis)', 'Dysmorphic red cells and casts in the urine indicate glomerular bleeding, as in the nephritic syndromes.'),
('4be15913-c8cc-59d4-a72b-22bcaaa46e7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Passage of bright red blood per rectum usually indicates bleeding in the:', '["Lower gastrointestinal tract","Upper gastrointestinal tract","Lungs","Urinary tract","Vagina"]'::jsonb, 'Lower gastrointestinal tract', 'Bright red rectal bleeding (hematochezia) originates in the distal bowel, whereas slower proximal bleeding produces melena.'),
('90a6a176-b4d3-58d1-92cf-a5f9e8b116d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Cardiac tamponade produces hypotension primarily by:', '["Impaired diastolic filling of the heart","Decreased systemic vascular resistance","Bradycardia","Peripheral vasodilation","Increased cardiac contractility"]'::jsonb, 'Impaired diastolic filling of the heart', 'Pericardial blood or fluid compresses the heart, impairs diastolic filling, lowering stroke volume and cardiac output.'),
('4a2f0149-759b-5205-a15b-be36f8b5a02c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Common causes of the pericardial effusion that produces cardiac tamponade include:', '["Uremia and malignant pericardial effusion","Fungal pericarditis","Cholesterol pericarditis","Pericardial cyst","Normal variant physiology"]'::jsonb, 'Uremia and malignant pericardial effusion', 'Uremic and malignant pericardial effusions are frequent causes of tamponade, in addition to the acute hemorrhagic effusion of myocardial rupture.'),
('27821f1a-f192-5966-9358-72c0408e75c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which hospitalized patient best illustrates all three components of Virchow''s triad?', '["Immobilized cancer patient with a central venous catheter","Healthy marathon runner","Patient on aspirin for arthritis","Patient with hemophilia","Patient with isolated polycythemia"]'::jsonb, 'Immobilized cancer patient with a central venous catheter', 'Immobility produces stasis, cancer is a hypercoagulable state, and the catheter causes endothelial injury—together reproducing all three components of Virchow''s triad.'),
('cf65e48c-1cc0-5eb7-8bbc-6ca4919f18f7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which clinical setting predisposes to thrombosis chiefly through endothelial injury?', '["Ruptured atherosclerotic plaque (acute myocardial infarction)","Prolonged bed rest accompanied by associated clinical symptoms","Oral contraceptive use mediated by specific receptor activation","Antiphospholipid syndrome without affecting the primary tissue pathway","Factor V Leiden leading to subsequent cellular adaptation"]'::jsonb, 'Ruptured atherosclerotic plaque (acute myocardial infarction)', 'Plaque rupture exposes thrombogenic subendothelium and tissue factor; this endothelial injury is the key thrombogenic element for arterial thrombosis.'),
('81060646-7f1a-52cc-969b-888e1491c9a2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which setting predisposes to thrombosis predominantly through venous stasis?', '["Prolonged immobilization after hip surgery","Turbulence at an atherosclerotic bifurcation","Heparin-induced thrombocytopenia","Polycythemia vera","Malignant tumor"]'::jsonb, 'Prolonged immobilization after hip surgery', 'Immobility abolishes the calf muscle pump and slows venous flow, making stasis the dominant Virchow factor.'),
('c71c2f5e-932d-588d-95dc-f21e7177e325'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Venous thrombosis after starting an estrogen-containing oral contraceptive is best attributed to:', '["Hypercoagulability","Stasis","Endothelial injury","Turbulence","Platelet dysfunction"]'::jsonb, 'Hypercoagulability', 'Estrogens increase hepatic synthesis of clotting factors, a hypercoagulable state that raises the risk of venous thromboembolism.'),
('11fcf207-f031-5821-8a7a-ce9602a8397a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The standard pharmacologic prophylaxis against deep vein thrombosis in a postoperative patient is:', '["Low-molecular-weight heparin","Aspirin","Warfarin","Tissue plasminogen activator","Desmopressin"]'::jsonb, 'Low-molecular-weight heparin', 'Low-molecular-weight heparin is the standard thromboprophylaxis when bleeding risk allows; it prevents both deep vein thrombosis and pulmonary embolism.'),
('5114db7b-443a-5e9a-9987-ee79c859e25b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which anticoagulant can be safely given to a pregnant patient who requires long-term anticoagulation?', '["Low-molecular-weight heparin","Warfarin accompanied by associated clinical symptoms","Rivaroxaban mediated by specific receptor activation","Dabigatran without affecting the primary tissue pathway","Aspirin leading to subsequent cellular adaptation"]'::jsonb, 'Low-molecular-weight heparin', 'Warfarin and the direct oral anticoagulants are teratogenic or cross the placenta; low-molecular-weight heparin does not cross the placenta and is the anticoagulant of choice in pregnancy.'),
('d6750739-cdef-59c7-8569-4e86bc46d6b4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Dabigatran is classified as a:', '["Direct oral thrombin inhibitor","Vitamin K antagonist","Fibrinolytic agent","Platelet ADP receptor antagonist","Low-molecular-weight heparin"]'::jsonb, 'Direct oral thrombin inhibitor', 'Dabigatran directly inhibits thrombin, whereas rivaroxaban and apixaban inhibit factor Xa; all are direct oral anticoagulants that do not require INR monitoring.'),
('29f72663-8480-5fd9-b85c-861a31ef630f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which agent reduces arterial thrombotic events by blocking platelet thromboxane production?', '["Aspirin","Warfarin","Heparin","Fondaparinux","Urokinase"]'::jsonb, 'Aspirin', 'Aspirin irreversibly acetylates platelet cyclooxygenase-1, reducing thromboxane A2 and platelet aggregation, which reduces arterial thrombotic events.'),
('29a6370f-57ca-5818-9d29-9067d257f81c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which condition is a classic trigger of disseminated intravascular coagulation?', '["Gram-negative septicemia","Essential hypertension","Osteoarthritis","Peptic ulcer disease","Asthma"]'::jsonb, 'Gram-negative septicemia', 'Sepsis, especially with gram-negative organisms, is one of the most important triggers of DIC through massive activation of the coagulation cascade.'),
('3a2b276b-e5d5-50eb-b422-3d2aa941e01f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Disseminated intravascular coagulation in a patient with mucin-secreting pancreatic carcinoma most likely results from:', '["Release of procoagulant substances from tumor cells","Marantic endocarditis accompanied by associated clinical symptoms","Polycythemia mediated by specific receptor activation","Cholesterol emboli without affecting the primary tissue pathway","Amyloid deposition leading to subsequent cellular adaptation"]'::jsonb, 'Release of procoagulant substances from tumor cells', 'Adenocarcinomas release tissue factor and cancer procoagulants that chronically activate coagulation, causing a low-grade DIC.'),
('21b50b30-dfc9-5f72-a75c-55d7cd6df0ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Disseminated intravascular coagulation complicating placental abruption is triggered by release into the maternal circulation of:', '["Tissue thromboplastin","Amniotic fluid gas","Fetal hemoglobin","Decidual estrogens","Lactate"]'::jsonb, 'Tissue thromboplastin', 'Thromboplastin (tissue factor) released from the disrupted placenta activates the extrinsic pathway, generating the DIC of placental abruption.'),
('9ae14269-d74f-59ba-b17c-dc96a15467af'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In disseminated intravascular coagulation, bleeding results mainly from:', '["Consumption of platelets and clotting factors","Excess circulating prothrombin","Increased platelet production","Vitamin K excess","Decreased plasminogen"]'::jsonb, 'Consumption of platelets and clotting factors', 'Widespread microvascular thrombi consume platelets and clotting factors, leaving too few for hemostasis, so DIC paradoxically presents with bleeding.'),
('2202d1ab-d5df-5cf2-b810-f768a523fff0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which organ suffers most rapid irreversible damage when its blood flow is completely arrested?', '["Brain","Skin","Adipose tissue","Skeletal muscle","Bone"]'::jsonb, 'Brain', 'The brain has a high oxygen demand and no meaningful glycogen reserve, so it suffers irreversible damage within minutes of circulatory arrest.'),
('47da4ca2-a6f0-5658-927e-d833bd3d1f8b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Elevated serum lactate in shock reflects:', '["Anaerobic metabolism from tissue hypoxia","Compensated aerobic metabolism","Reduced renal clearance alone","Hyperventilation","Polycythemia"]'::jsonb, 'Anaerobic metabolism from tissue hypoxia', 'When oxygen delivery cannot meet demand, cells switch to anaerobic glycolysis and lactate rises; it is a marker of the severity of tissue hypoxia in shock.'),
('556416df-430d-58ce-89c0-6273dcad0339'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Narrowing of the pulse pressure in early hypovolemic shock indicates:', '["Reduced stroke volume with compensatory vasoconstriction","Widened pulse pressure with vasodilation accompanied by associated clinical symptoms","Bradycardia mediated by specific receptor activation","Polycythemia without affecting the primary tissue pathway","Fluid overload leading to subsequent cellular adaptation"]'::jsonb, 'Reduced stroke volume with compensatory vasoconstriction', 'Falling stroke volume with peripheral vasoconstriction narrows the pulse pressure, an early warning sign before frank hypotension develops.'),
('ffc5570e-93a6-51de-86cf-821de596cc29'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The early tachycardia of acute hemorrhage is caused by:', '["Sympathetic (baroreceptor) reflex to falling arterial pressure","Vagal overactivity accompanied by associated clinical symptoms","Direct myocardial injury mediated by specific receptor activation","Hypothermia without affecting the primary tissue pathway","Polycythemia leading to subsequent cellular adaptation"]'::jsonb, 'Sympathetic (baroreceptor) reflex to falling arterial pressure', 'Baroreceptors detect the falling arterial pressure and trigger sympathetic discharge, raising the heart rate and systemic vascular resistance early in shock.'),
('b7383ee2-2529-5fdc-8e4b-d9d0778e4d57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Multiple organ dysfunction syndrome in late shock most directly results from:', '["Protracted tissue hypoperfusion with release of inflammatory mediators","Direct trauma to each individual organ accompanied by associated clinical symptoms","Disseminated cancer mediated by specific receptor activation","Autoimmune attack without affecting the primary tissue pathway","Malnutrition leading to subsequent cellular adaptation"]'::jsonb, 'Protracted tissue hypoperfusion with release of inflammatory mediators', 'Sustained hypoperfusion, reperfusion injury, and circulating inflammatory mediators damage the lungs, kidneys, liver, and heart in the end stage of shock.'),
('b6ecb4d7-92a8-59a4-9e1d-4ac5d9996fe4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which renal lesion underlies the acute renal failure of prolonged shock?', '["Acute tubular necrosis","Papillary necrosis","Cortical infarction","Membranous nephropathy","Proliferative glomerulonephritis"]'::jsonb, 'Acute tubular necrosis', 'Prolonged renal hypoperfusion causes ischemic acute tubular necrosis with oliguric renal failure and muddy-brown granular casts.'),
('18a8b2a1-c8df-5e2b-810a-12ff76a3bdd7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'ARDS can be triggered by all of the following EXCEPT:', '["Congestive heart failure","Sepsis","Aspiration of gastric contents","Major trauma","Acute pancreatitis"]'::jsonb, 'Congestive heart failure', 'ARDS is non-cardiogenic; sepsis, aspiration, trauma, and pancreatitis damage the alveolar-capillary membrane, whereas left heart failure produces hydrostatic (cardiogenic) edema.'),
('10912dce-3f4b-53af-b64d-8d4b5b90719e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which finding helps distinguish cardiogenic (hydrostatic) pulmonary edema from ARDS?', '["Elevated jugular venous pressure and high wedge pressure with crackles","Fever without crackles accompanied by associated clinical symptoms","Normal jugular venous pressure with quiet lungs mediated by specific receptor activation","Hypotension with bounding pulse without affecting the primary tissue pathway","Polycythemia leading to subsequent cellular adaptation"]'::jsonb, 'Elevated jugular venous pressure and high wedge pressure with crackles', 'Cardiogenic edema is driven by raised left atrial filling pressures (high JVP/wedge), whereas ARDS is a low-filling-pressure, increased-permeability edema.'),
('0f416725-79b0-5bd5-934e-12ffb40beb47'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Blue toes, livedo reticularis, and worsening renal function shortly after angiography most likely reflect:', '["Cholesterol crystal emboli from an ulcerated atherosclerotic plaque","Air embolism accompanied by associated clinical symptoms","Fat embolism mediated by specific receptor activation","Amniotic fluid embolism without affecting the primary tissue pathway","Venous thromboembolism leading to subsequent cellular adaptation"]'::jsonb, 'Cholesterol crystal emboli from an ulcerated atherosclerotic plaque', 'Angiography can dislodge cholesterol crystals from an aortic plaque; atheroemboli occlude small distal vessels, causing blue toes, livedo, and renal ischemia.'),
('76314a9d-7aed-544b-b91b-55cc874091cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A renal cell carcinoma invading the inferior vena cava may shower tumor emboli primarily to the:', '["Lungs","Liver","Spleen","Abdominal wall","Gallbladder"]'::jsonb, 'Lungs', 'Tumor emboli from a renal cell carcinoma travel through the inferior vena cava and right heart into the pulmonary arteries.'),
('fbae2094-ae73-55bf-bba4-9d9206e19307'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A wandering, detached mass that travels in the bloodstream and obstructs a distant vessel is termed:', '["Embolus","Thrombus","Infarct","Aneurysm","Atheroma"]'::jsonb, 'Embolus', 'An embolus is a detached intravascular mass (thrombus fragment, fat, air, amniotic fluid, or tumor) carried by the blood to lodge in a distant vessel.'),
('7407eeee-f75e-599f-ac5a-a301a7cc6c18'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The ischemic death of tissue that follows occlusion of its blood supply by an embolus or thrombus is termed:', '["Infarction","Congestion","Hemorrhage","Hyperemia","Stasis"]'::jsonb, 'Infarction', 'Infarction is the ischemic necrosis of tissue resulting from occlusion of its arterial (or, rarely, venous) supply.'),
('b3772754-3751-552e-b554-8222520231f1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'White (anemic) infarcts of the heart, kidney, and spleen typically arise when:', '["An end artery is occluded and collateral backflow is negligible","A dual circulation refills the necrotic zone","Thrombocytopenia prevents bleeding","Venous thrombosis dominates","Bacterial superinfection occurs"]'::jsonb, 'An end artery is occluded and collateral backflow is negligible', 'Those solid organs have single end-arterial supply with few collaterals, so the necrotic zone stays pale instead of being refilled with blood.'),
('e9a7e71f-a320-59eb-b3b0-1384fec7ae97'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pulmonary infarcts are often red because of:', '["Dual bronchial and pulmonary arterial circulation with back-bleeding","Thrombocytopenia accompanied by associated clinical symptoms","Low oxygen tension alone mediated by specific receptor activation","Bacterial superinfection without affecting the primary tissue pathway","Venous thrombosis alone leading to subsequent cellular adaptation"]'::jsonb, 'Dual bronchial and pulmonary arterial circulation with back-bleeding', 'The lung has both bronchial and pulmonary arterial supply, so blood from the patent bronchial arteries refills and hemorrhages into the necrotic area.'),
('2a14c9f7-9e05-5ce4-98c2-8ad10b4e3b40'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which statement about infarction is TRUE?', '["Red infarcts occur in organs with a dual blood supply (lung, intestine)","White infarcts occur in the lung and intestine","Venous infarcts are always pale","Hypertensive hemorrhage is an infarct","All infarcts are septic"]'::jsonb, 'Red infarcts occur in organs with a dual blood supply (lung, intestine)', 'Red (hemorrhagic) infarcts form where dual or rich collaterals allow back-bleeding, as in the lung and intestine; white infarcts affect end-arterial organs.'),
('a847ec6a-95b1-5728-bcba-b644950cf600'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which injury may paradoxically occur when blood flow is restored to an ischemic limb or myocardium?', '["Reperfusion injury with reactive oxygen species and calcium overload","Complete resolution of all damaged tissue accompanied by associated clinical symptoms","Rapid functional recovery mediated by specific receptor activation","Bacterial superinfection without affecting the primary tissue pathway","Fat embolism leading to subsequent cellular adaptation"]'::jsonb, 'Reperfusion injury with reactive oxygen species and calcium overload', 'Reoxygenation of ischemic tissue generates reactive oxygen species and produces intracellular calcium overload, which can extend the original injury.'),
('2a0a91c3-25f2-5f0b-a6a0-021d8bc2d186'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Gangrene is best defined as:', '["Necrosis with superadded putrefaction of the tissue","Simple coagulative necrosis accompanied by associated clinical symptoms","Edema of the limb mediated by specific receptor activation","Chronic inflammation without affecting the primary tissue pathway","A mature fibrotic scar leading to subsequent cellular adaptation"]'::jsonb, 'Necrosis with superadded putrefaction of the tissue', 'Gangrene is ischemic necrosis complicated by putrefaction—dry (mummified, little infection) or wet (infected, liquefactive).'),
('3601bb0e-8066-55ad-9815-9cfffbdffc37'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Dry gangrene most commonly affects which part?', '["Toes and feet of diabetics with arterial occlusion","The tongue accompanied by associated clinical symptoms","The colon mediated by specific receptor activation","The small intestine without affecting the primary tissue pathway","The lung leading to subsequent cellular adaptation"]'::jsonb, 'Toes and feet of diabetics with arterial occlusion', 'Dry gangrene typically affects the distal extremities (toes, feet) in diabetic or arteriosclerotic vascular disease, with mummification and a line of demarcation.'),
('c9d69c85-9c0a-58b2-9c69-655d1c58ec57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Wet gangrene characteristically occurs in:', '["Internal organs such as the bowel, or in moist tissues with venous/mixed occlusion","The toes of a well-perfused diabetic accompanied by associated clinical symptoms","An appendage undergoing dry mummification mediated by specific receptor activation","Skin with minimal moisture without affecting the primary tissue pathway","Healthy, fully perfused limbs leading to subsequent cellular adaptation"]'::jsonb, 'Internal organs such as the bowel, or in moist tissues with venous/mixed occlusion', 'Wet gangrene affects moist, often internal tissues (bowel) or limbs with venous/mixed occlusion and bacterial infection, producing liquefactive, foul tissue.'),
('bb4f6f24-cdfc-597a-9b99-29ab91d82857'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which of the following is NOT a recognized mechanism of edema formation?', '["Increased plasma oncotic pressure","Increased capillary hydrostatic pressure","Decreased plasma oncotic pressure","Increased vascular permeability","Lymphatic obstruction"]'::jsonb, 'Increased plasma oncotic pressure', 'A rise in plasma colloid osmotic pressure would draw fluid into the vessels and reduce edema; the recognized mechanisms are hydrostatic, oncotic, permeability, lymphatic, and sodium retention.'),
('a0310102-c573-53fd-bf3b-6ad53a3aab76'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which clinical scenario produces edema by increased capillary hydrostatic pressure?', '["Deep vein thrombosis with venous obstruction","Nephrotic syndrome accompanied by associated clinical symptoms","Cirrhosis mediated by specific receptor activation","Severe burns without affecting the primary tissue pathway","Lymphatic filariasis leading to subsequent cellular adaptation"]'::jsonb, 'Deep vein thrombosis with venous obstruction', 'Venous obstruction raises capillary hydrostatic pressure; nephrotic syndrome and cirrhosis act through low oncotic pressure, burns through permeability, and filariasis through lymphatic obstruction.'),
('2a1b98ec-0a0b-5334-8ce6-7baaf35f1bcf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which clinical scenario produces edema by decreased plasma oncotic pressure?', '["Nephrotic syndrome","Acute deep vein thrombosis","Congestive heart failure","Tourniquet on a limb","Acute urticaria"]'::jsonb, 'Nephrotic syndrome', 'Heavy proteinuria lowers serum albumin and oncotic pressure; deep vein thrombosis and heart failure act hydrostatically, and urticaria by increased permeability.'),
('43ae1ebe-0a66-59c0-96cb-221bf3aa39ec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which clinical scenario produces edema by increased vascular permeability?', '["Acute urticarial allergic reaction","Prolonged standing","Congestive heart failure","Lymphatic obstruction","Primary aldosteronism"]'::jsonb, 'Acute urticarial allergic reaction', 'Urticaria and angioedema reflect mast-cell histamine increasing vascular permeability; standing and heart failure act through hydrostatic pressures.'),
('c8da0f7f-cdb0-5735-b9a1-8e5d3807519e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which clinical scenario produces edema by lymphatic obstruction?', '["Filariasis of the lower limb","Malnutrition","Right heart failure","Advanced renal failure","Severe burns"]'::jsonb, 'Filariasis of the lower limb', 'Wuchereria bancrofti blocks the lymphatics; malnutrition acts through low oncotic pressure, heart failure hydrostatically, and burns through permeability.'),
('8ee0a5a3-38f2-5c71-9e46-aff18718a54b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which clinical scenario produces edema primarily by sodium and water retention?', '["Advanced oliguric renal failure","Acute pericarditis","Deep vein thrombosis","Lymphatic obstruction","Extensive burns"]'::jsonb, 'Advanced oliguric renal failure', 'Anuric or oliguric renal failure cannot excrete sodium and water, expanding extracellular volume; the other scenarios act through hydrostatic, permeability, or lymphatic mechanisms.'),
('3c8a5251-243a-50bf-abdf-3f2885fc22ee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The three-part description of the factors predisposing to thrombosis is known as:', '["Virchow''s triad","The Monro-Kellie doctrine","Starling''s law","The Cushing reflex","Laplace''s law"]'::jsonb, 'Virchow''s triad', 'Virchow''s triad names endothelial injury, abnormal blood flow, and hypercoagulability as the factors predisposing to thrombus formation.'),
('b48e7a35-85d0-555c-8cf9-3d053a4287a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A mural thrombus over a healing apical myocardial infarct most likely produces:', '["Systemic emboli (brain, spleen, kidney, extremities)","Pulmonary emboli accompanied by associated clinical symptoms","Portal vein thrombosis mediated by specific receptor activation","Hepatic vein thrombosis without affecting the primary tissue pathway","Cerebral venous sinus thrombosis leading to subsequent cellular adaptation"]'::jsonb, 'Systemic emboli (brain, spleen, kidney, extremities)', 'Intracardiac left-ventricular mural thrombi enter the systemic circulation and embolize to the brain, kidneys, spleen, bowel, and limbs.'),
('49a7021f-2ebe-52a3-b035-07fd22e77b2f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Massive pulmonary embolism produces which hemodynamic change?', '["Acute right heart strain with pulmonary hypertension","Left atrial volume overload accompanied by associated clinical symptoms","Systemic hypertension mediated by specific receptor activation","Bradycardia without affecting the primary tissue pathway","Hypovolemia leading to subsequent cellular adaptation"]'::jsonb, 'Acute right heart strain with pulmonary hypertension', 'Obstruction of the pulmonary arteries raises pulmonary vascular resistance, acutely straining the right ventricle (acute cor pulmonale).'),
('653c23c1-c219-5c74-b4b8-dfca767f21b5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Sudden death from massive pulmonary embolism results most often from:', '["Acute right heart failure when a large fraction of the pulmonary bed is occluded","Left ventricular free-wall rupture accompanied by associated clinical symptoms","Pulmonary fibrosis mediated by specific receptor activation","Chronic atrial fibrillation without affecting the primary tissue pathway","Myocardial infarction leading to subsequent cellular adaptation"]'::jsonb, 'Acute right heart failure when a large fraction of the pulmonary bed is occluded', 'When emboli occlude a large portion (typically more than 60%) of the pulmonary circulation, acute right ventricular failure and circulatory collapse occur.'),
('5818126e-510f-5317-8818-ec06feef1508'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The onset of fat embolism syndrome after a long-bone fracture is usually:', '["1-3 days after injury","Within minutes of injury","After 2 weeks","After 1 month","At 6 months"]'::jsonb, '1-3 days after injury', 'Fat embolism syndrome typically begins 24–72 hours after a fracture, with respiratory, neurologic, and petechial features.'),
('5a4bf1b6-dc56-5a38-83c0-1dd168794c23'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'During which procedure is air embolism a recognized hazard requiring careful positioning?', '["Neurosurgery with the patient in the sitting position","Routine blood sampling accompanied by associated clinical symptoms","Dental extraction mediated by specific receptor activation","Laparoscopic cholecystectomy in head-down tilt without affecting the primary tissue pathway","Cystoscopy leading to subsequent cellular adaptation"]'::jsonb, 'Neurosurgery with the patient in the sitting position', 'In the sitting position, gravity produces negative pressure in open dural venous sinuses, allowing air to be aspirated and cause venous air embolism.'),
('439f3f9c-5525-5c05-866d-796cd5c0368f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Amniotic fluid embolism is strongly suggested by the autopsy finding of fetal squamous cells in:', '["Maternal pulmonary capillaries","Fetal blood","Amniotic fluid","The placenta","The umbilical artery"]'::jsonb, 'Maternal pulmonary capillaries', 'Amniotic fluid and fetal debris embolize to the maternal lungs; autopsy shows fetal squamous cells and debris in the maternal pulmonary capillaries.'),
('f4c66503-c697-5d4b-9a9c-133952432031'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Sudden onset ''worst headache of my life'' with neck stiffness in a previously well patient points to:', '["Subarachnoid hemorrhage","Epidural hematoma","Hypertensive deep hemorrhage","Chronic subdural hematoma","Cerebral infarction"]'::jsonb, 'Subarachnoid hemorrhage', 'Subarachnoid hemorrhage typically presents with a thunderclap headache and meningism, classically from rupture of a saccular (berry) aneurysm.'),
('9a7364d1-1feb-53d8-83fc-165758c14a84'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Chronic subdural hematoma in an elderly patient on aspirin, presenting with gradual confusion, is due to:', '["Slow accumulation of blood from recurrent trivial tears of the bridging veins","Acute arterial hemorrhage accompanied by associated clinical symptoms","Spontaneous tumor bleeding mediated by specific receptor activation","Amyloid angiopathy rupture without affecting the primary tissue pathway","Arteriovenous malformation rupture leading to subsequent cellular adaptation"]'::jsonb, 'Slow accumulation of blood from recurrent trivial tears of the bridging veins', 'Minor, often unnoticed trauma tears the bridging veins and bleeds slowly into the subdural space, expanding over weeks in the elderly and anticoagulated.'),
('6d017fb8-8574-5773-874e-464973155a4a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The classic lucid interval followed by rapid deterioration is most characteristic of:', '["Epidural hematoma","Chronic subdural hematoma","Subarachnoid hemorrhage","Basal ganglia hemorrhage","Cerebral infarction"]'::jsonb, 'Epidural hematoma', 'After a traumatic epidural hematoma, a lucid interval often precedes rapid deterioration as the swiftly accumulating arterial clot compresses the brain.'),
('9234b347-e079-5174-bd2e-53f08b8dd7b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Spontaneous bleeding into the joints is a hallmark of:', '["Hemophilia A (factor VIII deficiency)","Polycythemia vera","Iron deficiency anemia","Thrombocytosis","Mild prolonged aPTT from lupus anticoagulant"]'::jsonb, 'Hemophilia A (factor VIII deficiency)', 'Factor VIII deficiency in hemophilia A causes recurrent hemarthrosis and deep soft-tissue bleeding after trivial trauma.'),
('228aa8f6-b970-5c52-894c-417706b24abc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Mucocutaneous bleeding (epistaxis, menorrhagia, easy bruising) with a prolonged bleeding time suggests:', '["Von Willebrand disease","Hemophilia B","Protein C deficiency","Factor V Leiden","Antithrombin deficiency"]'::jsonb, 'Von Willebrand disease', 'Von Willebrand disease impairs platelet adhesion and presents with mucocutaneous bleeding and a prolonged bleeding time, whereas hemophilia causes joint and muscle bleeds.'),
('246f9a89-eaa4-56d6-9623-52a21775eebd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Large bruises after trivial trauma in a patient with decompensated liver disease reflect:', '["Defective hepatic synthesis of clotting factors","Isolated thrombocytopenia from consumption","Increased vascular permeability","Lymphatic obstruction","Hypercoagulability"]'::jsonb, 'Defective hepatic synthesis of clotting factors', 'The liver synthesizes most clotting factors; hepatic failure lowers their levels, prolongs the PT, and causes ecchymoses with easy bruising.'),
('f6640eec-0d76-5b07-bb9a-1da2a1fc4c3d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pinpoint, non-palpable petechiae are most closely associated with:', '["Thrombocytopenia","Coagulation factor deficiency","Vitamin K deficiency alone","Liver failure alone","Hyperfibrinolysis"]'::jsonb, 'Thrombocytopenia', 'Petechiae are the typical bleeding manifestation of thrombocytopenia or platelet dysfunction; coagulation factor defects more often produce larger ecchymoses or hematomas.'),
('35021b29-7fbf-594c-8246-7f35dbfd977c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Qualitative platelet dysfunction, as in uremia, characteristically causes:', '["Mucocutaneous bleeding (easy bruising, petechiae, epistaxis)","Deep muscle hematomas accompanied by associated clinical symptoms","Hemarthrosis alone mediated by specific receptor activation","Venous thrombosis without affecting the primary tissue pathway","Cerebral arterial occlusion leading to subsequent cellular adaptation"]'::jsonb, 'Mucocutaneous bleeding (easy bruising, petechiae, epistaxis)', 'Platelet disorders cause mucosal and skin bleeding, whereas deep joint and muscle bleeding characterizes coagulation factor defects.'),
('3a73c39f-ec1f-5a70-a34a-86a1eb07aba6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Sustained hypertension most typically causes which type of intracranial hemorrhage?', '["Intracerebral hemorrhage of the basal ganglia","Subarachnoid hemorrhage","Epidural hematoma","Chronic subdural hematoma","Traumatic pontine laceration"]'::jsonb, 'Intracerebral hemorrhage of the basal ganglia', 'Hypertension ruptures small penetrating arteries, causing intracerebral hemorrhage most often in the basal ganglia, thalamus, pons, or cerebellum.'),
('45589464-636a-5963-b176-994f032013d1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Cerebral infarction after embolic or thrombotic occlusion undergoes which type of necrosis?', '["Liquefaction (colliquative) necrosis","Caseous necrosis","Fat necrosis","Coagulative necrosis with preserved architecture","Fibrinoid necrosis"]'::jsonb, 'Liquefaction (colliquative) necrosis', 'Brain infarcts undergo liquefactive necrosis because glial cells release hydrolytic enzymes, softening the tissue into a fluid-filled cavity.'),
('ce4101b2-aa0b-533e-95ab-90d67408afaa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A left-sided cardiac embolus (e.g., from infective endocarditis) most commonly produces infarction of the:', '["Brain, kidney, spleen, or extremities","Lungs","Left ventricle","Portal venous system","Cerebral venous sinuses"]'::jsonb, 'Brain, kidney, spleen, or extremities', 'Systemic emboli from the left heart lodge in end-arterial organs such as the brain, kidney, spleen, and limbs.'),
('534f7155-cf77-5d16-89eb-76b0fc9a53b7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Tissue factor (factor III) activates the extrinsic pathway of coagulation by binding which factor?', '["Factor VII","Factor XII","Factor VIII","Factor V","Factor II"]'::jsonb, 'Factor VII', 'Tissue factor exposed on damaged vessels binds factor VIIa, and the tissue factor-VIIa complex activates factor X, starting the extrinsic pathway.'),
('b9b16cb1-07eb-5b81-ae7d-c1fbfaa61a27'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The final common pathway of coagulation generates which enzyme?', '["Thrombin (factor IIa)","Factor XIIa","Factor VIIa","Factor VIIIa","Plasmin"]'::jsonb, 'Thrombin (factor IIa)', 'Factor Xa with factor Va forms prothrombinase, which converts prothrombin to thrombin; thrombin then makes fibrin and amplifies the cascade.'),
('b2005cc5-c553-55a7-a1b7-3a23330715ac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The insoluble fibrin mesh of a blood clot is formed when thrombin cleaves:', '["Fibrinogen","Prothrombin","Factor XIII","Von Willebrand factor","Tissue factor"]'::jsonb, 'Fibrinogen', 'Thrombin cleaves fibrinogen to fibrin monomers, which factor XIIIa then cross-links into a stable, insoluble clot.'),
('5e0fd402-b3b7-504f-ab5a-56e7ee95e1f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which degradation product of cross-linked fibrin indicates recent clot formation and its breakdown?', '["D-dimer","Fibrinogen","Prothrombin","Factor VIII","Antithrombin III"]'::jsonb, 'D-dimer', 'Plasmin degradation of cross-linked fibrin releases D-dimer, which is elevated in DIC, venous thromboembolism, and the postoperative state.'),
('d48c64e8-5444-5a28-91ed-ae6830566f3c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which medication is an oral direct factor Xa inhibitor?', '["Rivaroxaban","Warfarin","Unfractionated heparin","Tissue plasminogen activator","Aspirin"]'::jsonb, 'Rivaroxaban', 'Rivaroxaban (and apixaban) directly inhibit activated factor X; dabigatran inhibits thrombin, warfarin blocks vitamin K, and heparin works through antithrombin III.'),
('8a0adbdb-5739-51b5-993e-f59f418dbd8d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A swollen, warm, erythematous calf in early deep vein thrombosis should first be attributed to:', '["Increased capillary hydrostatic pressure from venous obstruction","Lymphatic obstruction accompanied by associated clinical symptoms","Decreased plasma oncotic pressure mediated by specific receptor activation","Increased vascular permeability without affecting the primary tissue pathway","Sodium and water retention leading to subsequent cellular adaptation"]'::jsonb, 'Increased capillary hydrostatic pressure from venous obstruction', 'DVT raises venous pressure behind the obstruction, increasing hydrostatic filtration; secondary inflammation may add permeability changes.'),
('df100127-2607-598a-97eb-59c0591a98b7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hypoalbuminemia from nephrotic syndrome or cirrhosis causes edema through:', '["Decreased plasma oncotic pressure","Increased capillary hydrostatic pressure","Increased vascular permeability","Lymphatic obstruction","Sodium and water retention"]'::jsonb, 'Decreased plasma oncotic pressure', 'Low serum albumin reduces the plasma colloid osmotic pressure, decreasing the reabsorption of interstitial fluid into capillaries.'),
('cf1045c3-ac6a-5af6-86b6-452f75f89887'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In anaphylactic shock, the massive fluid shift into the tissues results from:', '["Increased vascular permeability associated with histamine release","Increased capillary hydrostatic pressure accompanied by associated clinical symptoms","Decreased plasma oncotic pressure mediated by specific receptor activation","Lymphatic obstruction without affecting the primary tissue pathway","Sodium and water retention leading to subsequent cellular adaptation"]'::jsonb, 'Increased vascular permeability associated with histamine release', 'Histamine from mast cells increases vascular permeability, causing rapid loss of fluid and protein into the tissues with hypotension.'),
('242e5616-309b-5808-ad1c-bbf3373f5d0d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which phenomenon is characteristic of lymphedema rather than other forms of edema?', '["Non-pitting skin because of protein-rich interstitial fluid","Rapid pitting of ankle swelling","Associated pulmonary crackles","Central obesity with striae","Dependent edema that resolves overnight"]'::jsonb, 'Non-pitting skin because of protein-rich interstitial fluid', 'Protein-rich fluid in lymphedema resists displacement, so the skin does not pit; hydrostatic edema is low-protein and pits readily.'),
('4cc50887-d9d2-5ffe-9b82-da572c469813'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Edema associated with primary hyperaldosteronism is mediated predominantly by:', '["Sodium and water retention","Decreased plasma oncotic pressure","Increased vascular permeability","Lymphatic obstruction","Increased capillary hydrostatic pressure"]'::jsonb, 'Sodium and water retention', 'Excess aldosterone promotes renal sodium retention with obligated water, expanding the extracellular volume and producing edema.'),
('ad2204ab-8b43-56ac-9bc0-65da02d80fd4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Pink, frothy sputum in acute pulmonary edema indicates:', '["Fluid and some red cells transudating under high hydrostatic pressure","Purulent exudate accompanied by associated clinical symptoms","Pure mucus mediated by specific receptor activation","Fungal debris without affecting the primary tissue pathway","Bile reflux leading to subsequent cellular adaptation"]'::jsonb, 'Fluid and some red cells transudating under high hydrostatic pressure', 'Alveolar flooding under high capillary pressure, with minor hemorrhage, gives the pink frothy sputum of acute left heart failure.'),
('1f8239b4-c113-59fb-98d7-74babf292eac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which condition reduces the plasma oncotic pressure responsible for keeping fluid in vessels?', '["Hypoalbuminemia (nephrotic syndrome, cirrhosis, malnutrition)","Hyperalbuminemia accompanied by associated clinical symptoms","Venous obstruction mediated by specific receptor activation","Acute inflammation without affecting the primary tissue pathway","Lymphatic obstruction leading to subsequent cellular adaptation"]'::jsonb, 'Hypoalbuminemia (nephrotic syndrome, cirrhosis, malnutrition)', 'Low serum albumin lowers plasma colloid osmotic pressure and favors edema; the other listed states operate through hydrostatic, permeability, or lymphatic mechanisms.'),
('9bbdc0e6-6ebb-5c01-9399-b2e3b4797288'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Venous obstruction (for example, a deep vein thrombus) generates edema chiefly by raising the:', '["Capillary hydrostatic pressure","Plasma oncotic pressure","Interstitial oncotic pressure","Endothelial permeability","Antidiuretic hormone level"]'::jsonb, 'Capillary hydrostatic pressure', 'Obstructed venous drainage raises venular and capillary pressures, so more fluid is forced out of the microvessels.'),
('d0ba4d7e-a6c3-50e4-b91b-5ff09ba16cc3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The edema of burns and trauma is protein-rich because of:', '["Increased vascular permeability","Elevated hydrostatic pressure","Hypoalbuminemia","Renal sodium retention","Lymphatic blockage"]'::jsonb, 'Increased vascular permeability', 'Heat- or injury-damaged endothelium allows plasma proteins to cross the vessel wall, so burn and traumatic edema is a protein-rich exudate.'),
('b6284336-dbd1-5f42-a76e-a3510960618f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Blockage of the lymphatics by tumor, surgery, or filariasis is the mechanism of which edema?', '["Lymphedema","Cardiac edema","Renal edema","Hepatic ascites","Acute inflammatory edema"]'::jsonb, 'Lymphedema', 'Lymphatic obstruction prevents clearance of interstitial fluid and protein, producing the firm, non-pitting swelling of lymphedema.'),
('f9f5b3b0-f87f-5d93-a651-9a99ee2f8b34'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Conservation of sodium and water by the failing kidney contributes to edema through:', '["Sodium and water retention","Increased vascular permeability","Elevated capillary hydrostatic pressure alone","Decreased plasma oncotic pressure alone","Lymphatic obstruction"]'::jsonb, 'Sodium and water retention', 'Renal retention of sodium and water expands the extracellular volume; this primary sodium retention is a major driver of edema in cardiac and renal failure.'),
('4a938167-f759-52dd-a87b-80beda52ae56'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'A young woman develops oliguria, fever, confusion, and a petechial rash after starting ticlopidine; the smear shows schistocytes. The most likely diagnosis is:', '["Thrombotic thrombocytopenic purpura","Typical hemolytic-uremic syndrome","Immune thrombocytopenic purpura","Disseminated intravascular coagulation","Heparin-induced thrombocytopenia"]'::jsonb, 'Thrombotic thrombocytopenic purpura', 'Drug-related TTP shows microangiopathic hemolytic anemia with schistocytes, thrombocytopenia, fever, renal, and neurologic findings due to ADAMTS13 deficiency.'),
('ad8d8a22-6585-555b-81c7-43e8ec3782d1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Typical hemolytic-uremic syndrome after a bloody diarrheal illness is linked to:', '["Shiga toxin of Escherichia coli O157:H7","Clostridium difficile toxin","Salmonella invasion","Campylobacter lipopolysaccharide","Helicobacter pylori urease"]'::jsonb, 'Shiga toxin of Escherichia coli O157:H7', 'E. coli O157:H7 elaborates Shiga toxin, which damages microvascular endothelium and produces HUS with microangiopathic anemia, thrombocytopenia, and renal failure.'),
('742bcec3-ae72-5ab6-b7b3-fa59cdd6d845'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Compared with typical hemolytic-uremic syndrome, thrombotic thrombocytopenic purpura characteristically has more prominent:', '["Neurologic involvement","Bloody diarrhea as a prodrome","Predominance in children","Absence of fever","Favorable outcome without treatment"]'::jsonb, 'Neurologic involvement', 'TTP usually lacks a diarrheal prodrome, affects adults, and features neurologic findings; typical HUS follows bloody diarrhea in children and chiefly involves the kidneys.'),
('681fec64-e465-5cf3-a05f-49bbe5fffcc7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Microangiopathic hemolytic anemia in DIC results from:', '["Mechanical fragmentation of red cells by microvascular fibrin","Immune-mediated hemolysis accompanied by associated clinical symptoms","Iron deficiency mediated by specific receptor activation","Membrane protein defect without affecting the primary tissue pathway","Parasitic infection leading to subsequent cellular adaptation"]'::jsonb, 'Mechanical fragmentation of red cells by microvascular fibrin', 'Fibrin strands in the microvasculature shear red cells into schistocytes, the basis of microangiopathic hemolytic anemia in DIC, HUS, and TTP.'),
('c837b3cb-a662-5ffd-bab8-6cc18f4e49e3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which laboratory value is elevated in DIC as a product of the fibrinolysis of cross-linked fibrin?', '["D-dimer","Fibrinogen","Platelet count","Prothrombin","Factor XIII"]'::jsonb, 'D-dimer', 'Plasmin degradation of cross-linked fibrin releases D-dimer; in DIC, secondary fibrinolysis produces a markedly elevated D-dimer.'),
('c675e068-003f-5520-b824-6c9927fdce2c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'The shared end-result of all forms of shock is:', '["Inadequate tissue perfusion and cellular hypoxia","Hypertension with vasoconstriction accompanied by associated clinical symptoms","Polycythemia mediated by specific receptor activation","Hyperglycemia without affecting the primary tissue pathway","Fluid overload leading to subsequent cellular adaptation"]'::jsonb, 'Inadequate tissue perfusion and cellular hypoxia', 'Whatever the initiating cause, shock universally produces hypoperfusion of tissues with impaired oxygen delivery and cellular hypoxia.'),
('f49fc08d-a1ca-54a4-b330-0c497d78a6d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Hypovolemic shock is produced by all of the following EXCEPT:', '["Acute myocardial infarction","Hemorrhage","Severe burns","Vomiting and diarrhea","Ruptured aortic aneurysm"]'::jsonb, 'Acute myocardial infarction', 'Myocardial infarction causes cardiogenic (pump-failure) shock; the other options deplete circulating blood volume and cause hypovolemic shock.'),
('106c63da-eaff-5806-a76b-89599048496e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which form of shock follows anaphylaxis with vasodilation and capillary leak?', '["Anaphylactic (distributive) shock","Cardiogenic shock","Hypovolemic shock","Obstructive shock","Neurogenic shock"]'::jsonb, 'Anaphylactic (distributive) shock', 'Anaphylactic shock is distributive: histamine causes peripheral vasodilation and increased permeability, rapidly reducing the effective circulatory volume.'),
('d04afa15-2944-5a43-9707-6b990a0bb69b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Obstructive shock is exemplified by:', '["Cardiac tamponade or massive pulmonary embolism","Hemorrhage accompanied by associated clinical symptoms","Sepsis mediated by specific receptor activation","Spinal anesthesia without affecting the primary tissue pathway","Anaphylaxis leading to subsequent cellular adaptation"]'::jsonb, 'Cardiac tamponade or massive pulmonary embolism', 'Obstructive shock is caused by physical obstruction of cardiac filling or outflow, as in cardiac tamponade and massive pulmonary embolism.'),
('28c0402d-60d4-5348-8dd7-1ff66c8b95b8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Distributive shock is classically caused by all of the following EXCEPT:', '["Acute hemorrhage","Anaphylaxis","Sepsis","Spinal cord transection","High spinal anesthesia"]'::jsonb, 'Acute hemorrhage', 'Distributive shock (sepsis, anaphylaxis, neurogenic) involves vasodilation and blood redistribution; acute hemorrhage depletes volume and causes hypovolemic shock.'),
('6b8f1600-8951-5db4-8d3a-6fd6605fd71f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'In compensated shock, blood pressure may be maintained because of:', '["Sympathetic vasoconstriction and tachycardia","Generalized vasodilation accompanied by associated clinical symptoms","Bradycardia mediated by specific receptor activation","Volume overload without affecting the primary tissue pathway","Cardiac hypertrophy leading to subsequent cellular adaptation"]'::jsonb, 'Sympathetic vasoconstriction and tachycardia', 'Baroreceptor reflexes activate the sympathetic system, raising heart rate and peripheral resistance to hold the blood pressure until decompensation occurs.'),
('3c7984e7-3a5e-5eba-ac4e-533f53344dea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'End-stage (refractory) shock is characterized by:', '["Irreversible organ damage despite correction of the initiating cause","Prompt reversibility with fluid resuscitation accompanied by associated clinical symptoms","Mild tachycardia only mediated by specific receptor activation","Normal urine output without affecting the primary tissue pathway","Recovery without any therapy leading to subsequent cellular adaptation"]'::jsonb, 'Irreversible organ damage despite correction of the initiating cause', 'In refractory shock, organ injury (acute tubular necrosis, ARDS) persists or worsens even after the initiating cause is corrected, and therapy usually fails.'),
('db2f3e2c-886a-563f-95bb-8a31b03b119f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which finding suggests decompensated (progressive) rather than compensated shock?', '["Falling blood pressure with oliguria and lactic acidosis","Tachycardia with a normal pulse pressure accompanied by associated clinical symptoms","Mild tachypnea mediated by specific receptor activation","Normal urine output without affecting the primary tissue pathway","Warm, well-perfused skin leading to subsequent cellular adaptation"]'::jsonb, 'Falling blood pressure with oliguria and lactic acidosis', 'Progressive shock shows worsening hypotension, oliguria, and rising lactate as compensatory mechanisms are overwhelmed and organs are compromised.'),
('f4c25409-4531-51fb-8e42-95eb24e1678e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Hemodynamic Disorders', 'Which statement about edema is TRUE?', '["Edema is the accumulation of excess fluid in the interstitial tissue spaces","Edema always indicates increased hydrostatic pressure","Edema fluid is always protein-poor","Edema never affects the body cavities","Anasarca refers to localized swelling of one limb"]'::jsonb, 'Edema is the accumulation of excess fluid in the interstitial tissue spaces', 'Edema means excess interstitial fluid due to any Starling imbalance; anasarca is severe generalized edema, and edema may involve the body cavities.'),
('acec0787-3f69-5d99-8c1a-0f1dff092f9d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following best describes the primary function of the immune system?', '["Susceptibility to infection resulting in decreased functional activity","Protection from infectious disease and foreign agents","Inflammatory response mediated by specific receptor activation","Antibody production only without affecting the primary tissue pathway","Cellular resistance leading to subsequent cellular adaptation"]'::jsonb, 'Protection from infectious disease and foreign agents', 'The immune system recognizes and eliminates infectious agents and foreign substances, protecting the host from disease while distinguishing self from non-self.'),
('ddae76d1-e054-5280-910e-29fbcff4a875'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Humoral immunity is mediated primarily by which of the following?', '["Phagocytic cells","Skin and mucous membranes","Complement system","Antibodies","Natural killer cells"]'::jsonb, 'Antibodies', 'Humoral immunity is carried out by soluble antibodies (immunoglobulins) produced by plasma cells, which form the effector arm of the B-cell response.'),
('e283613a-d36a-567b-8f04-f6c58415ffb2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following is the defining characteristic of adaptive immunity?', '["Memory","Immediate response without memory","Specificity and memory","Non-specific response","Same response to all pathogens"]'::jsonb, 'Specificity and memory', 'Adaptive immunity is distinguished by antigen-specific recognition and immunologic memory, allowing a faster and stronger response on re-exposure.'),
('2f6e5a5d-d049-572f-a8ea-678298a7731c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Humoral immunity is mediated by which of the following?', '["T lymphocytes","Dendritic cells","Macrophages","B lymphocytes and antibodies","NK cells"]'::jsonb, 'B lymphocytes and antibodies', 'B lymphocytes differentiate into plasma cells that secrete antibodies, the soluble effectors of humoral immunity against extracellular microbes.'),
('80cf5804-1e01-570f-bfbf-8ca6e65d487f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Cell-mediated immunity is mediated primarily by which of the following?', '["B cells and antibodies","Eosinophils","T lymphocytes","NK cells","Neutrophils"]'::jsonb, 'T lymphocytes', 'Cell-mediated immunity, which protects against intracellular pathogens and tumors, is chiefly mediated by T lymphocytes.'),
('fda682b3-005a-5ef4-9e02-8defcf899b9b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which immunoglobulin is the most abundant in serum?', '["IgA","IgD","IgG","IgE","IgM"]'::jsonb, 'IgG', 'IgG constitutes about 75% of total serum immunoglobulin, making it the most abundant antibody class in serum.'),
('52d80c53-916e-5099-82c5-7e097f377cdd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which immunoglobulin is the first to be produced during a primary immune response?', '["IgG","IgE","IgM","IgA","IgD"]'::jsonb, 'IgM', 'IgM is the first immunoglobulin class produced during a primary immune response and the earliest antibody to appear after infection or immunization.'),
('901117c2-d753-5aa9-86d5-dfda7fa4acb8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which immunoglobulin is involved in mucosal immunity?', '["IgM","Secretory IgA","IgD","IgG","IgE"]'::jsonb, 'Secretory IgA', 'Secretory IgA is the principal immunoglobulin of mucosal surfaces (gastrointestinal and respiratory tracts, saliva, tears, breast milk), protecting against local infections.'),
('b528cfd1-450e-5cdc-ad8e-df8879e8b8c5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which immunoglobulin mediates Type I hypersensitivity?', '["IgE","IgM","IgA","IgG","IgD"]'::jsonb, 'IgE', 'IgE binds to mast cells and basophils and, when cross-linked by allergen, triggers degranulation, producing Type I (immediate) hypersensitivity.'),
('4d9110b0-1529-53bf-b2a5-e7d6d05b914c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which immunoglobulin is capable of crossing the placenta to provide passive immunity to the neonate?', '["IgE","IgG","IgA","IgD","IgM"]'::jsonb, 'IgG', 'IgG is the only immunoglobulin class that crosses the placenta, providing passive immunity to the fetus and neonate.'),
('747cd49a-6b67-5b70-acf9-57af3218f606'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'MHC class I molecules present antigen to which of the following cells?', '["Macrophages","CD8+ cytotoxic T cells","NK cells","B cells","CD4+ helper T cells"]'::jsonb, 'CD8+ cytotoxic T cells', 'MHC class I molecules, expressed on all nucleated cells, present endogenous peptides to CD8+ cytotoxic T cells, enabling detection of infected or abnormal cells.'),
('3d4d9e7f-d5fc-54c6-8a4d-6cbd6c7aa385'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'MHC class II molecules present peptide antigens to which of the following cells?', '["Dendritic cells","Neutrophils","NK cells","CD8+ cytotoxic T cells","CD4+ helper T cells"]'::jsonb, 'CD4+ helper T cells', 'MHC class II molecules on antigen-presenting cells present exogenous peptides to CD4+ helper T cells, the central orchestrators of the adaptive immune response.'),
('d4d1c3d5-a393-5ff3-a379-33e332595ea0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'T cell receptors (TCR) recognize which of the following?', '["Antigen presented by MHC molecules","Complement-bound antigen","Lipid antigens","Free antigen","Antibody-bound antigen"]'::jsonb, 'Antigen presented by MHC molecules', 'The T-cell receptor recognizes antigen only when it is presented as a peptide bound to an MHC molecule (the peptide-MHC complex), not as free antigen.'),
('cf4064d6-7976-5baf-87ad-1055c331657e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which major histocompatibility molecule is characteristically expressed on professional antigen-presenting cells and presents exogenous peptides to helper T cells?', '["MHC class II","MHC class I","CD19","CD8","CD3"]'::jsonb, 'MHC class II', 'MHC class II is constitutively expressed on professional antigen-presenting cells (dendritic cells, macrophages, B cells) and presents exogenous peptides to CD4+ T cells.'),
('35985b2b-7b27-5de6-932b-16d93e3a52a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which major histocompatibility molecule, expressed on virtually all nucleated cells, presents endogenous (cytosolic) peptides to cytotoxic T cells?', '["CD28","CD40","MHC class I","CD4","MHC class II"]'::jsonb, 'MHC class I', 'MHC class I is expressed on virtually all nucleated cells and presents endogenous (cytosolic) peptides to CD8+ cytotoxic T cells.'),
('3091308b-6b1f-5368-bcd5-3e085e19f70f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Th1 cells produce mainly which of the following?', '["IL-4 IL-5 IL-13","IL-10","IL-17","TGF-beta","IFN-gamma and IL-2"]'::jsonb, 'IFN-gamma and IL-2', 'Th1 cells characteristically secrete IFN-gamma and IL-2, which activate macrophages and promote cell-mediated immunity.'),
('1232324a-3a04-578c-8f7d-c7c4cdf70515'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A helper T cell subset promotes IgE class switching, eosinophil recruitment, and mast cell responses. Which group of signature cytokines does this subset predominantly secrete?', '["IL-17","IFN-gamma","IL-4 IL-5 IL-13","TNF-alpha","IL-1"]'::jsonb, 'IL-4 IL-5 IL-13', 'Th2 cells are defined by their secretion of IL-4, IL-5, and IL-13, which drive IgE production, eosinophil recruitment, and mast cell responses.'),
('fac1a77d-5c42-5f60-90b0-5202f633f84d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Th17 cells produce which of the following signature cytokines?', '["IFN-gamma","TGF-beta","IL-10","IL-17","IL-4"]'::jsonb, 'IL-17', 'Th17 cells are distinguished by their production of IL-17, a pro-inflammatory cytokine that recruits neutrophils.'),
('6339b694-0295-5e1e-a23b-c71cac798868'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Regulatory T cells suppress self-reactive lymphocytes and maintain self-tolerance. Which combination of surface markers and transcription factor identifies these cells?', '["CD4 and CD40","CD4 CD25 and FoxP3","CD19 and CD20","CD8 and CD28","CD56 and CD16"]'::jsonb, 'CD4 CD25 and FoxP3', 'Regulatory T cells (Tregs) are identified by expression of CD4, CD25, and the transcription factor FoxP3, and they suppress autoreactive lymphocytes to maintain self-tolerance.'),
('1d93813a-f149-5c58-b46f-2e835cf20fb9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Inhibitory receptors on natural killer cells recognize which of the following to keep NK cells from attacking the body''s own normal cells?', '["Complement-coated cells","Peptide-MHC complex","MHC class II","MHC class I","Antibody-opsonized cells"]'::jsonb, 'MHC class I', 'The killer immunoglobulin-like receptors on NK cells recognize MHC class I molecules; engagement delivers an inhibitory signal that prevents NK-mediated killing of normal cells.'),
('76b1176b-cb03-5414-b335-46ffc5f9d93a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Killer immunoglobulin-like receptors (KIRs) on NK cells do which of the following?', '["Inhibit NK cells when they recognize MHC class I","Bind to antibodies accompanied by associated clinical symptoms","Induce apoptosis mediated by specific receptor activation","Activate NK cells without affecting the primary tissue pathway","Recognize viral proteins leading to subsequent cellular adaptation"]'::jsonb, 'Inhibit NK cells when they recognize MHC class I', 'Binding of inhibitory KIRs to self MHC class I delivers a negative signal that suppresses NK-cell activation, so cells that have lost MHC class I become susceptible to NK killing.'),
('98048705-527d-553c-a940-af52bbf9dab3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Type I hypersensitivity is mediated by which of the following?', '["IgE and mast cells","T cells","IgM","Immune complexes","IgG and complement"]'::jsonb, 'IgE and mast cells', 'Type I (immediate) hypersensitivity results from allergen cross-linking of IgE bound to mast cells, triggering release of histamine and other mediators.'),
('549aff69-b849-5702-8e2d-4d668b79b630'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'In medical practice, BRCA1/2 mutations increase risk of:', '["Breast and ovarian cancer","Lung cancer","Colon cancer","Prostate cancer","Leukaemia"]'::jsonb, 'Breast and ovarian cancer', 'Hereditary breast-ovarian cancer syndrome.'),
('c265903a-158c-515d-b3db-8a4a940506c6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A 70-year-old man develops anaphylaxis within minutes of an insect sting. Which effector mechanism is directly responsible for this immediate reaction?', '["Antibodies directed against cell surface or extracellular matrix antigens","IgE and mast cells","T cell-mediated cytotoxicity","Complement only","Immune complexes"]'::jsonb, 'IgE and mast cells', 'Anaphylaxis is Type I (immediate) hypersensitivity in which allergen cross-links mast cell-bound IgE, triggering rapid degranulation and release of histamine.'),
('83b9433a-4e08-50cb-abeb-c5aded2e9f3b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'In Goodpasture syndrome, antibodies that produce glomerulonephritis and pulmonary hemorrhage react with a constituent of basement membranes. Which of the following is that target antigen?', '["Epidermal desmoglein resulting in decreased functional activity","Acetylcholine receptor accompanied by associated clinical symptoms","Islet cells mediated by specific receptor activation","Thyroglobulin without affecting the primary tissue pathway","Glomerular basement membrane collagen type IV"]'::jsonb, 'Glomerular basement membrane collagen type IV', 'The principal target antigen in Goodpasture syndrome is type IV collagen of the glomerular (and alveolar) basement membrane, against which pathogenic autoantibodies are directed.'),
('5ca3e0d6-d286-5e96-be23-6d88258178b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Myasthenia gravis is caused by which of the following?', '["Autoantibodies to calcium channels resulting in decreased functional activity","Type IV hypersensitivity accompanied by associated clinical symptoms","Type III hypersensitivity mediated by specific receptor activation","Type I hypersensitivity without affecting the primary tissue pathway","Type II hypersensitivity with anti-acetylcholine receptor antibodies"]'::jsonb, 'Type II hypersensitivity with anti-acetylcholine receptor antibodies', 'Myasthenia gravis is a Type II (antibody-mediated) disorder in which antibodies against the acetylcholine receptor block transmission at the neuromuscular junction.'),
('5835e8d5-e54d-5e2d-8d07-74a5d7dc21bb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Type III hypersensitivity is mediated by which of the following?', '["IgE and mast cells","Immune complex deposition","Antibody alone","NK cells","T cells"]'::jsonb, 'Immune complex deposition', 'Type III hypersensitivity results from deposition of antigen-antibody (immune) complexes in tissues, where they activate complement and recruit neutrophils.'),
('83298e67-8796-5353-aa5d-5624098b4606'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which hypersensitivity reaction is caused by immune-complex deposition?', '["Type IV hypersensitivity","Type III hypersensitivity","Type I hypersensitivity","Immediate hypersensitivity","Type II hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Immune-complex deposition with complement activation and neutrophil-mediated inflammation is the hallmark of Type III hypersensitivity.'),
('0a111363-5b77-5107-a4f4-e35f0b920732'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'An antigen injected into the skin of a previously immunized person produces, within a few hours, erythema and edema with hemorrhage from local antigen-antibody complex deposition in vessel walls. Which reaction is this?', '["Type II cytotoxic reaction","Systemic Type I reaction","Granulomatous reaction","Localized Type III hypersensitivity","Type IV delayed reaction"]'::jsonb, 'Localized Type III hypersensitivity', 'The Arthus reaction is a localized immune-complex (Type III) reaction in which antigen-antibody complexes deposited in local vessel walls activate complement and produce acute vasculitis within hours.'),
('908eec09-b6ca-5b37-92b8-8448f516235b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Systemic lupus erythematosus is a classic example of which of the following?', '["Combined immunodeficiency","Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity immune complex disease"]'::jsonb, 'Type III hypersensitivity immune complex disease', 'Systemic lupus erythematosus is a classic Type III (immune-complex) disease, with complexes depositing in the kidneys, skin, joints, and vessels.'),
('f3b0eb11-0707-5433-bd36-c6ea1d68a741'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Delayed-type skin reactions and granulomatous inflammation share which of the following as their principal mediator?', '["Antibodies","Mast cells","Complement","Immune complexes","Sensitized T lymphocytes"]'::jsonb, 'Sensitized T lymphocytes', 'Delayed-type and granulomatous reactions are mediated by sensitized T lymphocytes, which release cytokines that recruit and activate macrophages at the site of antigen deposition.'),
('340c1b81-2a71-50f5-a073-1fcb104ff420'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Regarding clinical cases: Type I hypersensitivity (allergic) is mediated by:', '["IgE antibodies","IgG antibodies","IgM antibodies","T cells","Complement"]'::jsonb, 'IgE antibodies', 'IgE binds mast cell FcεRI, cross-linking triggers degranulation.'),
('1c190f8b-10b6-54bf-bbd3-28ef66999bf5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which hypersensitivity reaction is mediated by T cells and develops over 24 to 72 hours?', '["Anaphylaxis","Type IV hypersensitivity","Type II hypersensitivity","Type III hypersensitivity","Immediate hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Type IV (cell-mediated) reactions, such as contact dermatitis and granulomatous inflammation, peak 24-72 hours after antigen exposure.'),
('b99e1596-f071-5c7c-a30d-43241620c6e1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Graft-versus-host disease, a complication of bone marrow transplantation, results primarily from which of the following?', '["Host immune response against graft","Granuloma formation","Antibody-mediated rejection","Immune complex deposition","Donor T cells attacking host tissues"]'::jsonb, 'Donor T cells attacking host tissues', 'Graft-versus-host disease occurs when immunocompetent donor T lymphocytes in the graft recognize the recipient''s tissues as foreign and attack them.'),
('252541c0-891e-502a-b179-1b76b80cd225'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Hyperacute graft rejection occurs within which of the following time periods?', '["Months","Weeks","Years","Minutes to hours","Days"]'::jsonb, 'Minutes to hours', 'Hyperacute rejection is caused by preformed recipient antibodies to donor antigens and occurs within minutes to hours, producing immediate graft thrombosis.'),
('d2aaacc9-4829-5e1f-a826-bd99054ff701'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Acute cellular rejection of a solid-organ transplant is mediated predominantly by which effector cells?', '["Eosinophils","Preformed antibodies","T cells","NK cells","Immune complexes"]'::jsonb, 'T cells', 'Acute cellular rejection of a transplanted organ is mediated mainly by recipient T lymphocytes that recognize donor histocompatibility antigens expressed on graft cells.'),
('9f78f780-38d6-5f52-b08a-304d0e8f52b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Chronic graft rejection is characterized by which morphologic change?', '["Necrosis","Granuloma formation","Mononuclear infiltrate","Vascular thickening and fibrosis","Neutrophil infiltration"]'::jsonb, 'Vascular thickening and fibrosis', 'Chronic rejection is characterized by progressive vascular intimal thickening, luminal narrowing, interstitial fibrosis, and eventual ischemic atrophy of the graft.'),
('b6bf6b49-ffd2-5c9e-b1d1-200b051128d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Severe combined immunodeficiency (SCID) affects which cell populations?', '["Only B cells","Only NK cells","Only T cells","Both T and B cells","Only macrophages"]'::jsonb, 'Both T and B cells', 'SCID results from defects that abolish both T- and B-cell development or function, leaving the infant profoundly susceptible to infections.'),
('36d800d4-e5d4-53c2-85b0-90e7494c1648'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Adenosine deaminase (ADA) deficiency causes which of the following?', '["DiGeorge syndrome","Hyper-IgM syndrome","SCID","Bruton agammaglobulinemia","CVID"]'::jsonb, 'SCID', 'ADA deficiency allows toxic deoxyadenosine metabolites to accumulate in lymphocytes, causing severe T- and B-cell deficiency (SCID).'),
('63bfe657-95c9-5010-80b1-d9b1cd49bbc4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'X-linked agammaglobulinemia, presenting in infancy with recurrent pyogenic infections and very low serum immunoglobulins, is caused by which of the following?', '["Defect in B cell maturation","Defect in T cell function","Phagocyte defect","Complement deficiency","Combined T and B deficiency"]'::jsonb, 'Defect in B cell maturation', 'Bruton X-linked agammaglobulinemia results from defective B-cell maturation (BTK mutation), causing absence of mature B cells and immunoglobulins and recurrent pyogenic infections from infancy.'),
('a219dd5d-4deb-5a3a-849a-191280620f2f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'DiGeorge syndrome results from which of the following?', '["NK cell deficiency","Complement C3 deficiency","T cell deficiency due to thymic aplasia","B cell maturation defect","Phagocyte adhesion defect"]'::jsonb, 'T cell deficiency due to thymic aplasia', 'DiGeorge syndrome is caused by a 22q11 microdeletion affecting the third and fourth pharyngeal pouches, leading to thymic aplasia or hypoplasia with consequent T-cell deficiency.'),
('635901cb-965e-511b-8dc9-c71f2968bd64'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Transfer of maternal IgG across the placenta to the developing fetus is mediated by which of the following receptors?', '["Fc receptor (FcRn)","T cell receptor","B cell receptor","MHC class I","CD4"]'::jsonb, 'Fc receptor (FcRn)', 'The neonatal Fc receptor (FcRn) transports maternal IgG across the placenta, providing passive humoral immunity to the fetus and newborn.'),
('e47cdaef-d104-519a-ae88-8473fca13c6c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Leukocyte adhesion deficiency (LAD) is due to which of the following defects?', '["Defective CD18 integrin","Myeloperoxidase deficiency","T cell deficiency","Complement deficiency","NADPH oxidase deficiency"]'::jsonb, 'Defective CD18 integrin', 'Leukocyte adhesion deficiency type 1 results from defective CD18-containing beta-2 integrins, impairing leukocyte adhesion and emigration into tissues.'),
('4034b93f-1f19-51ea-88ed-9098c6baf7d8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Chediak-Higashi syndrome is characterized by which of the following?', '["T cell deficiency resulting in decreased functional activity","Defective NADPH oxidase accompanied by associated clinical symptoms","Complement C3 deficiency mediated by specific receptor activation","Defective CD18 without affecting the primary tissue pathway","Partial albinism, recurrent infections, and giant lysosomal granules"]'::jsonb, 'Partial albinism, recurrent infections, and giant lysosomal granules', 'Autosomal recessive LYST mutation causes defective organelle trafficking, producing partial albinism, recurrent infections, and characteristic giant lysosomal granules in leukocytes.'),
('f3b600ac-83a4-5561-9ab0-d1d49a725ec1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which autoantibody is most characteristically associated with diffuse systemic sclerosis (scleroderma)?', '["Anti-nuclear antibody","Anti-Smith (Sm)","Anti-dsDNA","Anti-histone","Anti-Scl-70"]'::jsonb, 'Anti-Scl-70', 'Anti-Scl-70 (anti-topoisomerase I) antibody is the disease marker most characteristic of diffuse cutaneous systemic sclerosis.'),
('482eda25-3458-5ab9-97ec-89ce2c31c227'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A minority of patients with systemic lupus erythematosus carry an autoantibody that is especially valuable diagnostically because it is essentially never found in other rheumatic diseases. How is this antibody best characterized?', '["Associated with limited scleroderma","Highly specific for SLE","Associated with RA","Associated with Sjogren syndrome","Associated with DM/PM"]'::jsonb, 'Highly specific for SLE', 'Anti-Smith (Sm) antibody is found in only about 20% of SLE patients but is highly specific for the disease because it is almost never present in other autoimmune conditions.'),
('d51b7f1b-5baa-5e54-89bb-539d12abf0d7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Anti-Smith (Sm) antibody is specific for which of the following diseases?', '["Systemic sclerosis","SLE","Sjogren syndrome","Rheumatoid arthritis","Polymyositis"]'::jsonb, 'SLE', 'Anti-Smith (Sm) antibody is highly specific for systemic lupus erythematosus and is essentially never found in other rheumatic diseases.'),
('d387466b-2251-5153-b605-66e895751a54'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A woman with rapidly progressive thickening and tightening of the skin of the trunk and proximal extremities, Raynaud phenomenon, interstitial lung fibrosis, and positive anti-topoisomerase I antibody has which of the following conditions?', '["Sjogren syndrome","Rheumatoid arthritis","Systemic sclerosis (diffuse)","Polymyositis","SLE"]'::jsonb, 'Systemic sclerosis (diffuse)', 'Anti-Scl-70 (anti-topoisomerase I) antibodies are strongly associated with the diffuse cutaneous form of systemic sclerosis, which causes widespread skin tightening and visceral involvement.'),
('c8e11aec-bfa9-5a82-b701-6b52521768c9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Anti-centromere antibody is associated with which of the following?', '["Diffuse systemic sclerosis","SLE","Limited systemic sclerosis (CREST)","Sjogren syndrome","Rheumatoid arthritis"]'::jsonb, 'Limited systemic sclerosis (CREST)', 'Anti-centromere antibody is characteristic of limited cutaneous systemic sclerosis (CREST), in contrast to anti-Scl-70 in the diffuse form.'),
('5ab61c2b-8965-56dc-85cc-282d17c6594e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Anti-CCP antibody is highly specific for which of the following diseases?', '["Rheumatoid arthritis","Polymyositis","SLE","Systemic sclerosis","Sjogren syndrome"]'::jsonb, 'Rheumatoid arthritis', 'Anti-cyclic citrullinated peptide (anti-CCP) antibody is highly specific for rheumatoid arthritis and appears early in the disease.'),
('b21e834f-1a67-59c9-a08d-7dec8ca41a7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'What immune complex hypersensitivity involves antigen-antibody deposition in tissues?', '["Autoimmune reaction","Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Immune-complex (Type III) hypersensitivity is triggered by deposition of antigen-antibody complexes in tissues, where they activate complement and recruit neutrophils.'),
('5d3ae606-c02d-5d87-8dec-e4d60856208c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which hypersensitivity reaction is caused by antibodies directed against cell-surface or matrix antigens?', '["Autoimmune reaction","Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Type II (antibody-mediated) hypersensitivity results when antibodies bind cell-surface or extracellular-matrix antigens and fix complement or recruit effector cells.'),
('2ba7a636-5e62-5f8b-b0a6-8ac8e7424b05'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Human immunodeficiency virus (HIV) causes profound depletion of which cell population, leading to AIDS?', '["CD4+ helper T cells","CD8+ cytotoxic T cells","B lymphocytes","Natural killer cells","Neutrophils"]'::jsonb, 'CD4+ helper T cells', 'HIV primarily infects and destroys CD4+ helper T cells, producing the progressive cell-mediated immunodeficiency characteristic of AIDS.'),
('909225e8-1989-5cfe-957e-0f0876bd48d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Class switching of immunoglobulin isotypes in B cells is driven mainly by signals from which of the following?', '["Helper T cells via CD40 ligand and cytokines","Antigen alone accompanied by associated clinical symptoms","Complement components mediated by specific receptor activation","Natural killer cells without affecting the primary tissue pathway","Mast cells leading to subsequent cellular adaptation"]'::jsonb, 'Helper T cells via CD40 ligand and cytokines', 'CD40 ligand on activated helper T cells plus T-helper cytokines direct B-cell class switching to IgG, IgA, or IgE while preserving antigen specificity.'),
('507cdef5-b4bf-5887-a351-8498efdea4a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'An indurated, erythematous skin reaction appears 48 hours after intradermal injection of tuberculin in a person previously infected with tuberculosis. Which immunologic mechanism is responsible?', '["Type II hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type IV hypersensitivity', 'The tuberculin skin test is a Type IV (delayed-type) reaction: sensitized memory T cells react with the injected antigen, recruit macrophages, and produce induration at 24-72 hours.'),
('a6253a8b-db2d-5bf7-81f5-20265dfdb87b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'In Goodpasture syndrome, antibodies bind the glomerular basement membrane and cause tissue injury through which hypersensitivity mechanism?', '["Type II hypersensitivity","Type I hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type II hypersensitivity', 'Goodpasture syndrome is a Type II (antibody-mediated) reaction: autoantibodies to type IV collagen bind basement membranes and fix complement, causing nephritis and pulmonary hemorrhage.'),
('149cd8ba-799d-5968-9837-d9c1a0e63469'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which combination of properties most clearly distinguishes adaptive immunity from innate immunity?', '["Specificity and immunologic memory","Rapid response without memory","Identical response to all pathogens","Bypasses antigen recognition","Restricted to the skin and mucosa"]'::jsonb, 'Specificity and immunologic memory', 'Adaptive immunity is defined by exquisite antigen specificity and immunologic memory, allowing faster and stronger responses on re-exposure, unlike innate immunity.'),
('60d2abd8-15c5-51af-a83c-91dec7386606'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A defect in self-tolerance that permits the immune system to attack the body''s own tissues is best described by which term?', '["Autoimmune reaction","Type II hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Breakdown of self-tolerance allows lymphocytes to recognize and attack host tissues, a process defined as an autoimmune reaction.'),
('36a885f0-c0eb-5ca9-b541-3877625674fb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A patient who receives a renal transplant is placed on immunosuppression to prevent graft rejection. Rejection mediated by recipient T lymphocytes attacking donor cells is best classified as which reaction?', '["Type IV hypersensitivity","Type II hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Solid-organ graft rejection is chiefly a Type IV (cell-mediated) reaction in which recipient T lymphocytes recognize and attack donor histocompatibility antigens.'),
('3cd42509-8391-54f1-93fd-1092d6be3483'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A child with recurrent catalase-positive bacterial and fungal infections has an impaired oxidative (respiratory) burst of phagocytes. Which primary immunodeficiency is most likely?', '["Chronic granulomatous disease","DiGeorge syndrome","Severe combined immunodeficiency","X-linked agammaglobulinemia","Chediak-Higashi syndrome"]'::jsonb, 'Chronic granulomatous disease', 'Chronic granulomatous disease results from defective NADPH oxidase and a deficient respiratory burst, causing recurrent catalase-positive bacterial and fungal infections.'),
('7900a5f2-cc07-5916-bfc2-6d14e06df8d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Sjogren syndrome, with dry eyes and dry mouth, is best characterized by which of the following?', '["Lymphocytic destruction of salivary and lacrimal glands with anti-Ro/anti-La antibodies","Immune-complex deposition in glomeruli accompanied by associated clinical symptoms","IgE-mediated mast cell degranulation mediated by specific receptor activation","Antibody-mediated lysis of red blood cells without affecting the primary tissue pathway","T-cell destruction of pancreatic beta cells leading to subsequent cellular adaptation"]'::jsonb, 'Lymphocytic destruction of salivary and lacrimal glands with anti-Ro/anti-La antibodies', 'In Sjogren syndrome, lymphocytes infiltrate and destroy the salivary and lacrimal glands, and autoantibodies to Ro (SSA) and La (SSB) are characteristic.'),
('4f3e9454-979e-5e1f-91b0-280bd7fac410'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A group O recipient accidentally receives group A blood and develops fever, back pain, and hemoglobinuria. Which immunologic mechanism is responsible for the hemolysis?', '["Autoimmune reaction","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'The hemolytic transfusion reaction is Type II (cytotoxic) hypersensitivity: preformed antibodies bind ABO antigens on donor red cells and activate complement, causing intravascular hemolysis.'),
('1d3da25e-3e06-5090-9433-7fd9ff69eabd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A 40-year-old man develops contact dermatitis after skin exposure to an allergen. What is this phenomenon called?', '["Type I hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type IV hypersensitivity', 'Contact dermatitis is a Type IV (delayed-type) reaction in which sensitized T lymphocytes react with the haptenated antigen in the skin, producing a rash over 24-72 hours.'),
('a499e360-c5a1-58fe-86a5-ce37997b3557'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The most common form of asthma, typically triggered by inhaled allergens, is mediated by which mechanism?', '["Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type I hypersensitivity', 'Most asthma is atopic (extrinsic) and reflects Type I hypersensitivity, with allergen-specific IgE on mast cells triggering acute bronchoconstriction.'),
('872fca9d-8cb0-557e-933c-ad77d9781cfa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Chronic graft rejection in which host T lymphocytes infiltrate and damage the vasculature and parenchyma of a transplanted kidney is best explained by which immunologic process?', '["Type II hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Autoimmune reaction","Type I hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Chronic graft rejection is a Type IV (cell-mediated) reaction in which recipient T lymphocytes attack the graft vasculature and parenchyma, producing progressive fibrosis.'),
('e3814bd8-b2ec-5016-9dfc-1221a87d0d78'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Damage to skeletal muscle fibers in polymyositis is mediated chiefly by which effector cells?', '["Cytotoxic T lymphocytes","Neutrophils","Eosinophils","Mast cells","Platelets"]'::jsonb, 'Cytotoxic T lymphocytes', 'Polymyositis is aT-cell-mediated autoimmune disorder in which CD8+ cytotoxic T lymphocytes invade and destroy muscle fibers.'),
('71c000b5-12b2-5af4-b111-64b854c7efaa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following is a requirement for Hardy-Weinberg equilibrium to be maintained in a population?', '["Random mating","High mutation rate","Strong natural selection","Small population size","Non-random mating"]'::jsonb, 'Random mating', 'Hardy-Weinberg equilibrium assumes random mating, no mutation, no selection, an infinitely large population, and no gene flow.'),
('fee9bae9-e973-5d41-a86b-8b62161ca7f7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'When a microbial antigen structurally resembles a host antigen and triggers a cross-reactive immune response that damages host tissues, the outcome is best classified under which process?', '["Type IV hypersensitivity","Type III hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type II hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Molecular mimicry, in which microbial and self antigens cross-react, can trigger an immune response that damages host tissues - an autoimmune mechanism.'),
('ba646d28-f417-58e6-940c-8d4d12210ec0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The classical complement pathway is activated primarily by which of the following?', '["Antibody (IgM/IgG) bound to antigen","Mannose residues on microbial surfaces","Spontaneous C3 hydrolysis","Factor B and properdin","Bacterial lipopolysaccharide alone"]'::jsonb, 'Antibody (IgM/IgG) bound to antigen', 'C1q binds the Fc region of antibody in immune complexes, initiating the classical complement cascade - hence its link to antibody (Type II) injury.'),
('14c0f770-15d6-5c9f-be28-8910a898a893'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'What delayed-type hypersensitivity involves T cell-mediated inflammation?', '["Type III hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Delayed-type hypersensitivity is a Type IV, cell-mediated reaction in which sensitized T lymphocytes secrete cytokines that recruit and activate macrophages over 24-72 hours.'),
('908dd4b3-1091-5b8d-bde7-f12a8240a5ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Several weeks after onset of hepatitis B, a patient develops urticaria, arthralgia, and a maculopapular rash caused by circulating antigen-antibody complexes. Which immune mechanism is involved?', '["Type III hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type II hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'The serum sickness-like syndrome of hepatitis B is Type III (immune-complex) hypersensitivity: circulating complexes deposit in skin and joints, activate complement, and cause urticaria and arthralgia.'),
('9014fe78-257d-596b-a374-304da37d48a6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Perforin-and-granzyme-mediated contact killing of virus-infected cells is performed by which of the following?', '["Cytotoxic T lymphocytes and NK cells","B lymphocytes accompanied by associated clinical symptoms","Mast cells mediated by specific receptor activation","Neutrophils without affecting the primary tissue pathway","Eosinophils leading to subsequent cellular adaptation"]'::jsonb, 'Cytotoxic T lymphocytes and NK cells', 'CD8+ cytotoxic T cells and NK cells release perforin and granzymes to induce apoptosis of infected or abnormal target cells.'),
('2a8b0167-2818-5b69-9af6-d38ebdf0d848'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A 20-year-old man develops generalized urticaria, wheezing, and hypotension within minutes of being stung by a bee. Which immunologic mechanism best accounts for this reaction?', '["Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Type III hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type I hypersensitivity', 'The bee-sting reaction is Type I (immediate) hypersensitivity: allergen cross-links mast cell-bound IgE, releasing histamine that causes urticaria, bronchospasm, and hypotension.'),
('ba7c64bf-68d3-5d37-a145-b7c475d6c39c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following pairs most efficiently opsonizes bacteria for phagocytosis?', '["C3b and IgG","IgE and histamine","Perforin and granzyme","IFN-gamma and IL-2","C5a and leukotrienes"]'::jsonb, 'C3b and IgG', 'C3b (from complement) and IgG (antibody) coat bacteria and bind phagocyte receptors, greatly enhancing ingestion and killing.'),
('3f473d4c-c1db-5b3d-a363-1b44ec9cc7e9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A contact dermatitis rash develops over the skin that touched poison ivy resin two days earlier. Which immune mechanism causes this eruption?', '["Type I hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Poison-ivy contact dermatitis is a Type IV (delayed) reaction: sensitized T lymphocytes respond to the resin haptens in the skin, producing a vesicular eruption 24-72 hours after contact.'),
('90980a00-fe85-59bd-b8fa-df7e696cfb92'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following is TRUE of interleukins and other cytokines?', '["They are short-lived local mediators that regulate immune responses","They are stored preformed in cytoplasmic granules","They act only as long-range circulating hormones","Each cytokine acts on a single cell type","They are exclusively produced by T cells"]'::jsonb, 'They are short-lived local mediators that regulate immune responses', 'Cytokines act in an autocrine or paracrine manner, are produced transiently, and orchestrate proliferation, differentiation, and inflammation.'),
('58f1ea74-4bdc-50e7-b04d-f76bbb695a20'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The Th2 cytokine IL-4, which promotes IgE production, is especially important for defense against which type of pathogen?', '["Helminth (parasitic worm) infections","Intracellular viruses","Extracellular encapsulated bacteria","All fungi","Slow-growing mycobacteria"]'::jsonb, 'Helminth (parasitic worm) infections', 'The Th2 response (IL-4, IL-5, IL-13) drives IgE and eosinophils, the principal defenses against helminth parasites.'),
('a89a6190-4f38-5d27-9b4b-d4079df5462d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Every spring, a college student develops sneezing, nasal itching, rhinorrhea, and watery conjunctival injection triggered by grass pollen. Which immune process underlies his symptoms?', '["Autoimmune reaction","Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Seasonal pollen allergy is an atopic Type I reaction in which allergen-specific IgE on mast cells triggers degranulation and histamine release in the nasal and conjunctival mucosa.'),
('b2d621d3-78bb-55aa-8bee-9310705ceae7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which combination of cytokines is most important in driving IgE-mediated Type I hypersensitivity?', '["IL-4, IL-5, IL-13","IFN-gamma","TGF-beta","IL-10","IL-2"]'::jsonb, 'IL-4, IL-5, IL-13', 'Th2 cytokines IL-4, IL-5, and IL-13 promote IgE class switching, eosinophilia, and mast-cell sensitization underlying Type I reactions.'),
('0b77ad46-7053-5e79-a51c-7cb2370eac8c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'What immune complex hypersensitivity involves antigen-antibody deposition?', '["Type I hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type II hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Immune-complex (Type III) hypersensitivity is mediated by tissue deposition of antigen-antibody complexes, complement activation, and neutrophil recruitment.'),
('fd8a03aa-abcf-5ae4-a494-5a8e5b0df335'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'IL-6, a key driver of the acute-phase response and fever, is produced mainly by which of the following?', '["Macrophages and other activated leukocytes","Erythrocytes accompanied by associated clinical symptoms","Platelets mediated by specific receptor activation","Eosinophils without affecting the primary tissue pathway","Mast cells leading to subsequent cellular adaptation"]'::jsonb, 'Macrophages and other activated leukocytes', 'IL-6 is secreted chiefly by macrophages and other activated leukocytes and induces hepatic acute-phase protein synthesis, fever, and B-cell maturation.'),
('1843b52a-b1ee-542a-b519-7f8bd64e4446'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The signature cytokine IL-17 produced by Th17 cells is best known for which function?', '["Recruiting neutrophils to promote acute inflammation","Suppressing regulatory T cells","Inducing IgE class switching","Directly activating cytotoxic CD8 T cells","Inhibiting the complement cascade"]'::jsonb, 'Recruiting neutrophils to promote acute inflammation', 'IL-17 recruits and activates neutrophils, driving acute inflammation and contributing to autoimmune tissue injury.'),
('c3f69bec-6664-5035-917b-fddcfb1ff5a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Immunoglobulin class switching in B cells is regulated chiefly by signals through which of the following?', '["CD40 ligand on helper T cells interacting with CD40 on B cells","Surface IgM cross-linking alone accompanied by associated clinical symptoms","Complement receptor CR2 mediated by specific receptor activation","Fc receptors for IgE without affecting the primary tissue pathway","Toll-like receptor sequences leading to subsequent cellular adaptation"]'::jsonb, 'CD40 ligand on helper T cells interacting with CD40 on B cells', 'Contact-dependent CD40-CD40L interaction plus T-helper cytokines directs B cells to switch from IgM to IgG, IgA, or IgE.'),
('8768e00c-6372-5e53-af44-3bf9da6d0cf3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Recurrent disseminated Neisseria (meningococcal) infections characteristically result from deficiency of which complement components?', '["C5-C9 (terminal membrane attack complex)","C1q and C4 accompanied by associated clinical symptoms","C2 alone mediated by specific receptor activation","Factor B without affecting the primary tissue pathway","C1 inhibitor leading to subsequent cellular adaptation"]'::jsonb, 'C5-C9 (terminal membrane attack complex)', 'Deficiency of the terminal complement components C5-C9 impairs bactericidal lysis of Neisseria and predisposes to recurrent meningococcemia.'),
('854f696d-96ae-5543-9714-09b6e47d2ea6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A newborn develops jaundice and anemia because maternal antibodies that crossed the placenta are destroying his red cells. Which type of immune injury is this?', '["Type IV hypersensitivity","Type II hypersensitivity","Type I hypersensitivity","Type III hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type II hypersensitivity', 'Hemolytic disease of the newborn is Type II hypersensitivity: transplacental maternal antibodies bind fetal red-cell antigens and cause complement-mediated hemolysis.'),
('69a41c91-d4c0-5a0c-af52-e852ad8da190'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A patient with autoimmune hemolytic anemia has antibodies that bind to her own red cells, which are then phagocytosed in the spleen. Which immune mechanism is operative?', '["Type II hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type III hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Autoimmune hemolytic anemia is a Type II reaction in which autoantibodies coat red cells, which are then opsonized and phagocytosed, mainly in the spleen.'),
('14f1d5b1-63c0-5c22-a7ac-1a6e043cd4a4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Activation of macrophages for intracellular killing of microbes is driven chiefly by which Th1 cytokine?', '["IFN-gamma","IL-4","IL-5","IL-10","IL-13"]'::jsonb, 'IFN-gamma', 'IFN-gamma from Th1 cells and NK cells is the principal macrophage-activating factor, enhancing phagocytosis and microbicidal activity.'),
('933273d3-82bb-544e-956e-1a0205aa4e65'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'IFN-gamma released by Th1 and NK cells is most important for which function?', '["Activating macrophages to kill intracellular pathogens","Promoting IgE synthesis","Triggering mast cell degranulation","Recruiting eosinophils against helminths","Platelet aggregation"]'::jsonb, 'Activating macrophages to kill intracellular pathogens', 'IFN-gamma is the key macrophage-activating factor and promotes the cell-mediated responses that combat intracellular pathogens.'),
('37a096cb-4fb0-5cf2-833c-adb63658a29c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'TNF-alpha is a major mediator of which of the following?', '["Acute inflammation, fever, cachexia, and septic shock","IgE-mediated allergic reactions","Complement-mediated hemolysis","Specific immunologic memory","Maintenance of immunologic tolerance"]'::jsonb, 'Acute inflammation, fever, cachexia, and septic shock', 'TNF-alpha produced by activated macrophages and T cells drives the systemic acute-phase reaction and is central to the pathogenesis of septic shock.'),
('e5a7c6f3-4cca-5115-a1c4-362286549674'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'What immediate hypersensitivity involves IgE and mast cell degranulation?', '["Type II hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Immediate (Type I) hypersensitivity is caused by allergen cross-linking of IgE on mast cells, leading to rapid degranulation and release of vasoactive mediators.'),
('c28d1422-8f77-597d-9368-563807a26d70'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Shortly after eating a shrimp dish, an adult experiences acute urticaria, swelling of the lips, and difficulty breathing. Which immunologic process is responsible?', '["Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type I hypersensitivity', 'Acute urticaria and dyspnea after food ingestion represent Type I hypersensitivity, with IgE-mediated mast-cell degranulation releasing histamine within minutes of allergen exposure.'),
('f43c6d35-3e04-5cc0-94d1-5206a87180c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A child develops hematuria, hypertension, and periorbital edema about 2 weeks after a streptococcal throat infection, with immune complexes deposited in the glomeruli. Which mechanism explains this nephritis?', '["Type IV hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type II hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Post-streptococcal glomerulonephritis is a Type III reaction: immune complexes deposited in the glomeruli activate complement and recruit neutrophils, causing nephritis.'),
('2b5c8c60-5f6b-54e3-9ac2-fa953dfa9a73'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Prominent neutrophil infiltration driven by immune-complex deposition and complement activation is the histologic hallmark of which reaction?', '["Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type III hypersensitivity', 'In Type III reactions, immune complexes activate complement and recruit neutrophils, which release enzymes that damage vessel walls and tissues.'),
('64d1ae2f-3954-532a-9e41-955cad3af993'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which surface marker is present on virtually all mature T lymphocytes as part of the T-cell receptor complex?', '["CD3","CD19","CD20","CD56","CD14"]'::jsonb, 'CD3', 'CD3 is the signaling component of the T-cell receptor complex and is a pan-T-cell marker, present on all mature T lymphocytes.'),
('27b90ccd-5f47-58b7-b917-81e2069d87fd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Local deposition of antigen-antibody complexes in dermal vessel walls with acute complement-mediated vasculitis is the hallmark of which immunologic process?', '["Type II hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type I hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Deposition of immune complexes in vessel walls with complement activation and acute vasculitis is the pathognomonic mechanism of Type III (immune-complex) hypersensitivity.'),
('15835e2e-fdfb-50b3-a64e-8877d71eb2a4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A patient with allergic asthma develops bronchospasm within minutes of inhaling a triggering allergen. Which mechanism best explains this rapid response?', '["Type II hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Allergen-triggered bronchospasm within minutes of exposure is Type I (immediate) hypersensitivity, produced by IgE-mediated mast-cell degranulation and release of bronchoconstrictor mediators.'),
('474f58d2-e3b0-51a4-a7b1-7b210d91975f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A young woman develops malar rash, photosensitivity, arthritis, serositis, and antinuclear antibodies, with immune damage to multiple organs. Which process best explains this disease?', '["Type IV hypersensitivity","Type II hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type I hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'SLE is a systemic autoimmune disease: loss of self-tolerance leads to autoantibodies and immune complexes that damage the skin, joints, kidneys, and serous membranes.'),
('d8ae695c-6615-5cbc-92a4-b8ba93bd4617'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Rheumatoid arthritis, with chronic destructive inflammation of the joints caused by immune attack on synovial tissue, is best classified as which type of process?', '["Type III hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type II hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Rheumatoid arthritis is an autoimmune disease in which the immune system attacks self antigens in the joint synovium, producing chronic destructive inflammation.'),
('b76a28cb-785c-56e7-ada4-0ce1081b3fd2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Anaphylaxis is a potentially fatal systemic manifestation of which hypersensitivity reaction?', '["Type II hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type III hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Anaphylaxis is a systemic Type I (immediate) reaction caused by widespread IgE-mediated mast-cell and basophil degranulation.'),
('b95c48a8-59bf-5482-b3e9-f9e067a0dabb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Minutes after an intravenous infusion of a radiocontrast agent, a sensitized patient develops flushing, a rapid fall in blood pressure, and laryngeal edema. Which effector mechanism is chiefly responsible?', '["Type I hypersensitivity","Type III hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type IV hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'The rapid cardiovascular collapse and laryngeal edema after a sensitizing agent reflect Type I (anaphylactic) hypersensitivity mediated by mast-cell and basophil degranulation.'),
('f1d6347d-e93c-5d4a-a161-dfd0f8bdcbd2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which infection can be complicated by immune-complex (Type III) disease such as polyarteritis nodosa or glomerulonephritis?', '["Hepatitis B virus","Respiratory syncytial virus","Varicella-zoster virus","Rotavirus","Measles virus"]'::jsonb, 'Hepatitis B virus', 'Hepatitis B virus commonly triggers Type III immune-complex complications, including serum sickness-like syndrome and PAN-like vasculitis.'),
('22ab942b-394e-5ed4-99fc-9538986d075c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'MHC class II molecules are expressed constitutively on which of the following cells?', '["Dendritic cells, macrophages, and B lymphocytes","All nucleated cells","Red blood cells and platelets","Resting T lymphocytes","Eosinophils only"]'::jsonb, 'Dendritic cells, macrophages, and B lymphocytes', 'MHC class II is expressed on professional antigen-presenting cells (dendritic cells, macrophages, B cells), which present peptides to CD4+ helper T cells.'),
('795c3fbe-bc41-5ff5-ad1e-4d9c891a492c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'IL-12 secreted by dendritic cells and macrophages promotes differentiation of naive CD4+ T cells into which subset?', '["Th1 cells","Th2 cells","Th17 cells","Regulatory T cells","B cells"]'::jsonb, 'Th1 cells', 'IL-12 drives Th1 differentiation and IFN-gamma production, promoting cell-mediated immunity against intracellular pathogens.'),
('7a1d808d-ac32-588b-b570-3a9a67bea18c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A 6-month-old boy with recurrent pyogenic infections has markedly reduced serum immunoglobulins, absent B cells, but normal T-cell function. What is the most likely diagnosis?', '["X-linked agammaglobulinemia","DiGeorge syndrome","Chronic granulomatous disease","Wiskott-Aldrich syndrome","Severe combined immunodeficiency"]'::jsonb, 'X-linked agammaglobulinemia', 'Bruton X-linked agammaglobulinemia is aB-cell maturation defect (BTK mutation) with very low immunoglobulins and absent B cells, presenting when maternal antibody wanes.'),
('853d9d1f-997b-53ad-80a8-1ca88a90ba49'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'High-dose IL-2 is used in cancer immunotherapy chiefly because it does which of the following?', '["Expands and activates T lymphocytes and NK cells","Neutralizes circulating tumor antigens","Activates complement against tumors","Suppresses graft-versus-host disease","Recruits eosinophils"]'::jsonb, 'Expands and activates T lymphocytes and NK cells', 'IL-2 is a major T-cell growth factor; high doses expand cytotoxic lymphocytes and NK cells and are used in melanoma and renal-cell carcinoma.'),
('ac448fa7-60f5-5bcb-8538-e3532a7b57fa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Mixed connective tissue disease is best characterized by which of the following?', '["Autoimmune reaction with high-titer anti-U1 RNP antibodies","Type II hypersensitivity with anti-ACh receptor antibodies","IgE-mediated mast cell degranulation","Immune-complex deposition in glomeruli","Complement-mediated hemolysis"]'::jsonb, 'Autoimmune reaction with high-titer anti-U1 RNP antibodies', 'Mixed connective tissue disease is an autoimmune syndrome characterized by high-titer anti-U1 RNP antibodies and clinical features overlapping SLE, scleroderma, and polymyositis.'),
('b8dac880-c10d-518f-8735-1eeae6978d06'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following most accurately describes inheritance in classic autosomal recessive disorders such as cystic fibrosis?', '["Affected individuals are homozygous; unaffected parents of an affected child are carriers","Affected individuals are heterozygous accompanied by associated clinical symptoms","Only males are affected mediated by specific receptor activation","All sons of an affected male are affected without affecting the primary tissue pathway","The trait appears in every generation leading to subsequent cellular adaptation"]'::jsonb, 'Affected individuals are homozygous; unaffected parents of an affected child are carriers', 'In autosomal recessive inheritance, a mutant allele must be inherited from both parents; unaffected carriers (heterozygotes) have a 25% risk of an affected child.'),
('8c9b81c2-8412-5e8a-8861-6dbac0a056b5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which transcription factor is essential for Th17 cell differentiation?', '["ROR-gamma-t","T-bet","GATA-3","FoxP3","STAT6"]'::jsonb, 'ROR-gamma-t', 'ROR-gamma-t is the master transcription factor for Th17 differentiation, while T-bet and GATA-3 define Th1 and Th2 cells respectively.'),
('900be7f8-9995-5476-acd1-07e1aa45f83e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Type 1 diabetes mellitus results when the immune system destroys the pancreatic beta cells. Which immunologic process is responsible for this organ damage?', '["Type I hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Type 1 diabetes is an autoimmune disease caused by immune-mediated destruction of pancreatic beta cells after loss of self-tolerance.'),
('aeaa2d76-b3bd-55c9-8c42-a3c3a6174c24'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Patients with subacute bacterial endocarditis can develop proliferative glomerulonephritis from complexes of bacterial antigens and antibody that collect in the glomerular capillaries. Which immunologic mechanism is at work?', '["Type III hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Endocarditis-associated glomerulonephritis is Type III hypersensitivity, in which immune complexes of bacterial antigens and antibody deposit in glomeruli and trigger inflammation.'),
('623f2e94-61ac-502a-b192-ef1d703d5cc1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Allergic rhinitis is best classified as which type of hypersensitivity reaction?', '["Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Allergic rhinitis is a Type I (immediate) reaction: allergen cross-links mast cell-bound IgE in the nasal mucosa, releasing histamine and other mediators.'),
('5c733738-1f71-5649-a451-b18acd266fc6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A child who is allergic to penicillin develops a widespread itchy, red rash with periorbital swelling shortly after starting the antibiotic. Which immunologic mechanism is involved?', '["Type I hypersensitivity","Type IV hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Penicillin allergy presenting as acute urticaria is a Type I reaction: drug-specific IgE cross-links on mast cells, causing rapid release of histamine and vasoactive mediators.'),
('11c48e2f-24f5-548a-a89c-2b85eac83eba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Rejection of a solid-organ transplant and delayed-type skin reactions are mediated chiefly by which immunologic mechanism?', '["Autoimmune reaction","Type II hypersensitivity","Type I hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Both transplant rejection and delayed-type hypersensitivity are Type IV (cell-mediated) reactions driven by sensitized T lymphocytes.'),
('1d7e9777-c1a2-5196-9906-78ea2ad66556'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Graft-versus-host disease, a complication of allogeneic bone marrow transplantation, is mediated primarily by which of the following?', '["Autoimmune reaction","Type II hypersensitivity","Type III hypersensitivity","Type I hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'GVHD is a Type IV (cell-mediated) reaction in which donor T lymphocytes attack host tissues, producing skin, gut, and liver injury.'),
('994390e7-4889-57be-85a8-5a1dfad0bc1d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Deficiency of which complement component is central to opsonization and immune-complex clearance, and predisposes to recurrent pyogenic infections and immune-complex disease?', '["C3","C1q","C5","C9","Factor D"]'::jsonb, 'C3', 'C3 is pivotal to all complement pathways, opsonization, and immune-complex clearance; its deficiency causes recurrent pyogenic infections and immune-complex disease.'),
('05e3608d-2d62-5d0e-bf0a-042baa34c056'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Antibodies directed against the acetylcholine receptor at the neuromuscular junction block transmission and cause ptosis and muscle weakness. Which immunologic process explains this disorder?', '["Type IV hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type III hypersensitivity","Type I hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Myasthenia gravis is a Type II (antibody-mediated) disorder: antibodies against the acetylcholine receptor block neuromuscular transmission and cause fatigable weakness.'),
('e1fcd11c-36f2-56a0-ab99-b93ae401706d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which inheritance pattern is characteristic of autosomal dominant disorders such as Huntington disease and neurofibromatosis?', '["A single mutant allele from an affected parent suffices, with 50% risk to offspring of an affected heterozygote","Only homozygous individuals are affected accompanied by associated clinical symptoms","Two unaffected heterozygous parents can never produce an affected child mediated by specific receptor activation","Disease passes only through the maternal line without affecting the primary tissue pathway","Only males are affected leading to subsequent cellular adaptation"]'::jsonb, 'A single mutant allele from an affected parent suffices, with 50% risk to offspring of an affected heterozygote', 'In autosomal dominant disease, one mutant allele is sufficient; each child of an affected heterozygote has a 50% chance of inheriting the disorder.'),
('ac09e464-82e7-57f9-bc4b-b1c5a23c1437'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The pathogenesis of SLE involves which of the following?', '["Type II hypersensitivity","Type I hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type IV hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Systemic lupus erythematosus is a prototypical autoimmune disease caused by loss of self-tolerance, with autoantibody and immune-complex damage to multiple organs.'),
('91fea8b0-6082-5208-bf74-d6ed7273349f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'After antibody binds a target cell, the classical pathway forms C3 convertase and deposits C3 on that cell. Which immunologic process does this describe?', '["Autoimmune reaction","Type III hypersensitivity","Type II hypersensitivity","Type I hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'In antibody-mediated (Type II) injury, bound antibody activates the classical complement pathway, forming C3 convertase and depositing C3 on the target cell.'),
('50f5f6ca-d9dd-5354-98de-0ee38bed7f12'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The alternative complement pathway is activated by which of the following?', '["Microbial cell surfaces in the absence of antibody","Antibody bound to antigen","Mannose-binding lectin on mannose residues","C-reactive protein on phosphocholine","IgE cross-linking on mast cells"]'::jsonb, 'Microbial cell surfaces in the absence of antibody', 'The alternative pathway is triggered by microbial surfaces that promote C3b deposition and amplification, independent of antibody.'),
('e54a8572-0700-5132-9a25-77b74551ccd2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Recipient T lymphocytes that recognize donor MHC molecules are the principal effectors in which type of graft rejection?', '["Acute cellular and chronic rejection","Hyperacute rejection","Antibody-mediated rejection alone","Immediate hypersensitivity reactions","Type III immune-complex rejection"]'::jsonb, 'Acute cellular and chronic rejection', 'Acute cellular and chronic rejection are driven by recipient T cells reacting to donor histocompatibility antigens, a Type IV (cell-mediated) response.'),
('83a49dde-91f2-54e9-9ec0-d5e5183f9cd6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Affinity maturation, the progressive increase in antibody affinity during an immune response, is achieved by which process?', '["Somatic hypermutation with selection of high-affinity B-cell clones in germinal centers","Clonal deletion of autoreactive B cells accompanied by associated clinical symptoms","Receptor editing in the bone marrow mediated by specific receptor activation","Alternative splicing of immunoglobulin genes without affecting the primary tissue pathway","Complement-mediated lysis of low-affinity clones leading to subsequent cellular adaptation"]'::jsonb, 'Somatic hypermutation with selection of high-affinity B-cell clones in germinal centers', 'During germinal center reactions, somatic hypermutation of immunoglobulin genes generates variants, and antigen selects the high-affinity B cells, increasing antibody affinity.'),
('1dc13592-138b-5ac3-a380-065dc4cce81b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following are professional antigen-presenting cells capable of priming naive CD4+ T cells?', '["Dendritic cells, macrophages, and B lymphocytes","Red blood cells and platelets","Neutrophils and eosinophils","Natural killer cells and mast cells","Hepatocytes and myocardial fibers"]'::jsonb, 'Dendritic cells, macrophages, and B lymphocytes', 'Dendritic cells, macrophages, and B cells express MHC class II and costimulatory molecules, allowing them to present antigen to and activate helper T cells.'),
('d5dca39e-ac3a-50da-88d3-e2ed63e80c85'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'T-cell clonal anergy, a form of peripheral tolerance, results from which of the following?', '["Antigen recognition without adequate costimulation","Positive selection in the thymus","Deletion of autoreactive clones in the bone marrow","Engagement of the T-cell receptor alone by free antigen","Somatic hypermutation"]'::jsonb, 'Antigen recognition without adequate costimulation', 'When aT cell recognizes peptide-MHC without costimulation (signal 2), it becomes functionally unresponsive (anergic), a key peripheral-tolerance mechanism.'),
('1255112d-4d53-5ed3-9387-426497d6a98a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which immunoglobulin is the most efficient activator of the classical complement pathway and is the first antibody produced in a primary response?', '["IgM","IgG","IgA","IgE","IgD"]'::jsonb, 'IgM', 'IgM, a pentamer, binds antigen with high avidity and is the most potent complement activator of the immunoglobulin classes.'),
('bba2e504-520e-5ebb-8a17-f352ee8e9a32'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'What cytotoxic hypersensitivity involves antibody-mediated cell destruction?', '["Autoimmune reaction","Type II hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity","Type I hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Cytotoxic (Type II) hypersensitivity occurs when antibodies bind cell-surface antigens and cause destruction through complement activation, opsonization, and phagocytosis.'),
('6edaa114-9428-5f85-be8a-546878408a1d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'In hemolytic disease of the newborn, maternal anti-D immunoglobulins crossing the placenta cause fetal red cell destruction. Which mechanism of tissue damage is involved?', '["Autoimmune reaction","Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Hemolytic disease of the newborn is a Type II (cytotoxic) reaction in which maternal anti-D antibodies cross the placenta, bind fetal red cells, and trigger their destruction.'),
('bca326dc-fc28-59a8-912c-7d08e9933f4f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A patient given an experimental antiserum develops fever, arthralgias, urticaria, and lymphadenopathy about a week later as soluble immune complexes deposit in tissues. Which mechanism is responsible?', '["Type II hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Serum sickness is a Type III reaction in which soluble immune complexes deposit in vessels, joints, and tissues, causing fever, rash, and arthralgias one week or more after exposure.'),
('5cb8bc6d-8fa6-514d-b9f9-958a72a43f5e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Th1 cells, which secrete IFN-gamma and activate macrophages, are the pivotal effectors of which hypersensitivity reaction?', '["Type I hypersensitivity","Type IV hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Type IV (delayed-type) hypersensitivity is driven by Th1 cells that release IFN-gamma and activate macrophages.'),
('d4993750-5994-500e-ad37-a96ad275de93'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The lectin complement pathway is triggered when mannose-binding lectin binds to which of the following?', '["Mannose residues on microbial surfaces","Antibody-antigen immune complexes","Lipid A of bacterial lipopolysaccharide","C3b on activating surfaces","C-reactive protein bound to phosphocholine"]'::jsonb, 'Mannose residues on microbial surfaces', 'Mannose-binding lectin recognizes terminal mannose residues on microbial surfaces and activates complement through MASPs, independent of antibody.'),
('84037571-4870-5626-8d3c-8b428657113c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The membrane attack complex, which lyses antibody- or complement-coated cells, is formed from which components?', '["C5b, C6, C7, C8, and C9","C1q, C1r, and C1s","C3b and factor B","C4a and C4b","Factor D and properdin"]'::jsonb, 'C5b, C6, C7, C8, and C9', 'Assembly of C5b-C9 creates a pore in the target membrane (MAC), causing osmotic lysis of antibody- or complement-coated cells.'),
('ce5700af-a696-5ecc-a96a-47912cbd19ab'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The concept of immune surveillance holds that the immune system recognizes and eliminates which of the following?', '["Malignant (tumor) cells","Nutritionally deficient cells","Senescent erythrocytes","Fat-laden macrophages","Denatured proteins"]'::jsonb, 'Malignant (tumor) cells', 'Immune surveillance proposes that cytotoxic lymphocytes and NK cells continually identify and destroy malignant cells before they grow into tumors.'),
('7cd26273-2bf3-5f0d-827f-6417c6a460ea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A patient with Graves disease has circulating immunoglobulins that bind the thyrotropin receptor and stimulate hormone release. Which immunologic mechanism is at work?', '["Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Graves disease is a Type II (antibody-mediated) disorder in which stimulatory antibodies against the thyrotropin receptor drive excess thyroid hormone production.'),
('1b06b60a-4c84-515e-a87b-23c72025b008'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which statement best describes immunoglobulin D (IgD)?', '["Serves with IgM as a membrane receptor on mature naive B cells and has a limited secreted role","Is the most abundant antibody in serum accompanied by associated clinical symptoms","Is the principal immunoglobulin of secretions mediated by specific receptor activation","Is the first antibody produced during a primary response without affecting the primary tissue pathway","Mediates immediate hypersensitivity leading to subsequent cellular adaptation"]'::jsonb, 'Serves with IgM as a membrane receptor on mature naive B cells and has a limited secreted role', 'IgD is expressed as a membrane-bound immunoglobulin together with IgM on mature naive B cells; its secreted form has no clear effector function.'),
('4961b110-d299-553d-8288-8df56aa69d2a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Hashimoto thyroiditis, with lymphocytic infiltration and destruction of the thyroid gland by the immune system, represents which immunologic process?', '["Type II hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Hashimoto thyroiditis is an autoimmune reaction in which lymphocytes and autoantibodies progressively destroy the thyroid gland.'),
('b7448212-5605-5761-9da7-4aadfb9703a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Granulomatous inflammation with epithelioid cells and multinucleated giant cells, as seen in tuberculosis, is driven primarily by which immunologic process?', '["Type II hypersensitivity","Type I hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type IV hypersensitivity', 'Granuloma formation requires a Type IV (cell-mediated) immune response, in which sensitized T lymphocytes activate macrophages that transform into epithelioid and giant cells.'),
('1268dfb3-b2b1-5b45-81d6-aa4c540e9bf7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'IL-1, a major pyrogen, is produced principally by which of the following cell types?', '["Activated macrophages","Erythrocytes","Platelets","Resting natural killer cells","Mast cells"]'::jsonb, 'Activated macrophages', 'Activated macrophages are the principal source of IL-1, which induces fever and the acute-phase response.'),
('7035bab7-0526-5082-ad56-bbd590f1d587'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Adjuvants enhance vaccine immunogenicity chiefly by which mechanism?', '["Activating antigen-presenting cells and promoting costimulation and cytokine release","Directly neutralizing circulating antibodies accompanied by associated clinical symptoms","Lysing infected host cells mediated by specific receptor activation","Strengthening the blood-brain barrier without affecting the primary tissue pathway","Accelerating allergen-specific IgE production leading to subsequent cellular adaptation"]'::jsonb, 'Activating antigen-presenting cells and promoting costimulation and cytokine release', 'Adjuvants such as alum or Freund''s adjuvant activate antigen-presenting cells, enhance antigen uptake and presentation, and promote the costimulation needed for a robust adaptive response.'),
('2c951f72-6a4e-5294-b9bc-892d4f6573aa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Antibodies that coat donor red blood cells during a hemolytic transfusion reaction recruit complement and trigger intravascular lysis. Which type of immune reaction is this?', '["Type IV hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type II hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Antibody binding to donor red cells with complement activation and intravascular lysis during a transfusion reaction is the signature of Type II (cytotoxic) hypersensitivity.'),
('dc64c11c-de8d-59ee-a80e-91013846c729'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Loss of central or peripheral immune tolerance, allowing immune cells to react against self antigens, underlies which class of immune disorder?', '["Type III hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Autoimmune disease arises when central and peripheral tolerance mechanisms fail and self-reactive lymphocytes attack host tissues.'),
('1340fc64-7ebf-5305-abbd-55bcc143b372'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A 45-year-old woman receives a kidney transplant and is placed on immunosuppression to prevent graft rejection. Rejection here is best classified as which type of reaction?', '["Type IV hypersensitivity","Type III hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type II hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Graft rejection is mediated chiefly by recipient T lymphocytes against donor histocompatibility antigens, a Type IV (cell-mediated) reaction; immunosuppression is given to prevent it.'),
('29641f86-4a38-5076-a949-e23a6f67bd86'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'X-linked (Bruton) agammaglobulinemia is caused by a mutation in which of the following genes?', '["Bruton tyrosine kinase (BTK)","Adenosine deaminase (ADA)","CD40 ligand (CD40L)","Wiskott-Aldrich syndrome protein (WASP)","NEMO"]'::jsonb, 'Bruton tyrosine kinase (BTK)', 'A BTK mutation blocks early B-cell maturation, causing absent mature B cells, agammaglobulinemia, and recurrent pyogenic infections in boys.'),
('338d3056-b666-539a-aae6-cf1363fe4d0e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Immune privilege refers to which of the following phenomena?', '["Certain sites (e.g., anterior chamber of the eye, brain) tolerate foreign grafts with a blunted immune response","Rapid destruction of all foreign antigens in the skin accompanied by associated clinical symptoms","Selective depletion of complement in lymph nodes mediated by specific receptor activation","Absence of antigen-presenting cells throughout the body without affecting the primary tissue pathway","Enhanced rejection of MHC-mismatched grafts leading to subsequent cellular adaptation"]'::jsonb, 'Certain sites (e.g., anterior chamber of the eye, brain) tolerate foreign grafts with a blunted immune response', 'Immune-privileged sites suppress or deviate immune responses, so foreign tissue grafts survive there with minimal inflammation; mechanisms include FasL and TGF-beta.'),
('bb2f98dd-fbf3-5961-8aa1-635888cc601d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A nurse who develops itchy, vesicular dermatitis on the hands after repeated contact with nickel in instruments reflects which immunologic process?', '["Type I hypersensitivity","Autoimmune reaction","Type II hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Nickel contact dermatitis is a Type IV (delayed-type) hypersensitivity mediated by hapten-sensitized T lymphocytes that produce a vesicular skin eruption.'),
('a3ac2e1c-1fc8-5300-808e-71fa51b4c708'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which autoantibody is most characteristically associated with polymyositis and interstitial lung disease (antisynthetase syndrome)?', '["Anti-Jo-1 (anti-histidyl-tRNA synthetase)","Anti-Scl-70 (anti-topoisomerase I) accompanied by associated clinical symptoms","Anti-centromere mediated by specific receptor activation","Anti-dsDNA without affecting the primary tissue pathway","Anti-CCP leading to subsequent cellular adaptation"]'::jsonb, 'Anti-Jo-1 (anti-histidyl-tRNA synthetase)', 'Anti-Jo-1 is the most common antisynthetase antibody in polymyositis and correlates with interstitial lung disease.'),
('85745168-db47-58b1-a13e-786ae1c38442'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A 35-year-old woman presents with joint pain and a malar rash. What is the most likely underlying process?', '["Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'The combination of joint pain and malar rash is characteristic of SLE, a systemic autoimmune disease caused by immune attack on self tissues.'),
('b05e8717-a1be-5b31-ab68-a6beabf286b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Tuberculoid leprosy lesions contain large numbers of lymphocytes and macrophages but few bacilli. Which immune mechanism underlies the host response that controls this infection?', '["Type II hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type III hypersensitivity","Type I hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'The strong cell-mediated (Type IV) immune response in tuberculoid leprosy contains the bacilli, producing few organisms but many epithelioid-cell granulomas.'),
('4d880755-6a58-5ed5-973f-be17a7f3db2e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Antibodies in most patients with myasthenia gravis are directed against which of the following?', '["Nicotinic acetylcholine receptor at the neuromuscular junction","Myelin basic protein accompanied by associated clinical symptoms","Cardiac beta-1 receptor mediated by specific receptor activation","Calcium channels at the motor terminal without affecting the primary tissue pathway","Desmoglein 3 leading to subsequent cellular adaptation"]'::jsonb, 'Nicotinic acetylcholine receptor at the neuromuscular junction', 'Antibodies against the postsynaptic nicotinic acetylcholine receptor reduce receptor number and block transmission, causing fatigable weakness.'),
('c3ce74d1-c04b-5a02-a1ef-d673eb43c966'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Multiple endocrine organs destroyed by the immune response in a single patient, as with type 1 diabetes and Addison disease together, best illustrate which process?', '["Type III hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Autoimmune reaction"]'::jsonb, 'Autoimmune reaction', 'The coexistence of type 1 diabetes and Addison disease reflects a generalized autoimmune tendency, in which the immune system attacks multiple self organs.'),
('f02c95be-1854-5144-9f37-905f0948563e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The Arthus reaction, which produces localized vasculitis within hours of subcutaneous antigen injection, is an example of which hypersensitivity type?', '["Type III hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type IV hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'The Arthus reaction is a localized Type III (immune-complex) reaction producing acute complement-mediated vasculitis within hours of antigen injection.'),
('7aa5720e-8dfa-51c5-a074-922b40f30b5a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following is the major function of the cytokine IL-4?', '["Promoting IgE class switching in B cells and Th2 differentiation","Activating macrophages to kill intracellular bacteria","Recruiting neutrophils to sites of infection","Suppressing effector immune responses","Driving NK-cell cytotoxicity"]'::jsonb, 'Promoting IgE class switching in B cells and Th2 differentiation', 'IL-4, the signature Th2 cytokine, directs B-cell class switching to IgE and drives differentiation toward the Th2 phenotype.'),
('9644854f-4a4c-52b5-a466-23532319d4ac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A male infant with eczema, severe thrombocytopenia, and recurrent infections has which X-linked combined immunodeficiency?', '["Wiskott-Aldrich syndrome","DiGeorge syndrome","X-linked agammaglobulinemia","Chronic granulomatous disease","Leukocyte adhesion deficiency"]'::jsonb, 'Wiskott-Aldrich syndrome', 'Wiskott-Aldrich syndrome is an X-linked defect of the WASP gene causing eczema, thrombocytopenia with small platelets, and combined T/B-cell deficiency.'),
('4602f482-7800-545c-8dca-38561347d4f9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Serum sickness is a systemic illness caused by which immunologic mechanism?', '["Type II hypersensitivity","Type I hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type IV hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Serum sickness is a Type III (immune-complex) reaction produced when soluble immune complexes deposit in vessels, joints, and kidneys days after foreign serum administration.'),
('3a526842-bf7c-59f5-8c06-26c03e421389'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'An adult with recurrent sinopulmonary infections has very low serum IgG, IgA, and IgM yet reasonable T-cell numbers. Which primary immunodeficiency is most likely?', '["Common variable immunodeficiency (CVID)","X-linked agammaglobulinemia","DiGeorge syndrome","Chronic granulomatous disease","Hyper-IgM syndrome"]'::jsonb, 'Common variable immunodeficiency (CVID)', 'CVID presents in adults with low immunoglobulin levels, recurrent sinopulmonary infections, and increased risk of autoimmune disease and lymphoma.'),
('defe69c3-58e4-5b77-8f34-3f0b466499fc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'IL-17 is the signature cytokine product of which T-helper subset?', '["Th17 cells","Th1 cells","Th2 cells","Regulatory T cells","Naive B cells"]'::jsonb, 'Th17 cells', 'Th17 cells are defined by their production of IL-17, which recruits neutrophils and promotes acute inflammation.'),
('becedcce-736e-5932-b345-b178b355c3a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Class switching is aB-cell process that changes which immunoglobulin element while preserving antigen specificity?', '["Heavy-chain constant (Fc) region","Variable region of the heavy chain","Light-chain variable region","CDR3 loops","Antigen-binding pocket"]'::jsonb, 'Heavy-chain constant (Fc) region', 'During class switching, the heavy-chain constant region is exchanged (e.g., IgM to IgG, IgA, or IgE) while the antigen-binding V region is retained.'),
('3a585a52-ac23-586a-bb0a-ee216aad7955'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Systemic lupus erythematosus nephritis is driven largely by immune complexes that lodge in the glomerular capillary walls and activate complement. Which kind of immunologic injury does this represent?', '["Type II hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity","Type I hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type III hypersensitivity', 'Lupus nephritis is mediated by Type III (immune-complex) hypersensitivity: immune complexes lodged in the glomerular capillary walls activate complement and recruit inflammatory cells.'),
('854bff86-c388-5092-9e9b-35b05d0b747a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'All of the following are actions of TNF-alpha EXCEPT:', '["Promoting septic shock","Inducing cachexia and wasting","Stimulating the acute-phase response at low doses","Mediating cytolysis via the membrane attack complex","Activating endothelium and leukocytes"]'::jsonb, 'Mediating cytolysis via the membrane attack complex', 'Complement MAC, not TNF, mediates membrane lysis; TNF acts through NF-kB-mediated vascular and leukocyte activation, fever, cachexia, and septic shock.'),
('15ea3da0-eee8-502b-b52a-7527a31b1fd0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The cytokines secreted by Th2 cells are most important for which effector response?', '["Stimulating IgE production and eosinophil-mediated defense against helminths","Activating macrophages to kill intracellular mycobacteria","Recruiting neutrophils to pyogenic infections","Suppressing allergic and asthmatic responses","Promoting CD8+ cytotoxic killing"]'::jsonb, 'Stimulating IgE production and eosinophil-mediated defense against helminths', 'Th2 cytokines (IL-4, IL-5, IL-13) drive IgE production and eosinophilia, defending against helminths and mediating allergic disease.'),
('7c2a9977-547c-5970-aba9-e859e930fc07'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'MHC class I molecules are expressed on which of the following?', '["Virtually all nucleated cells","Only professional antigen-presenting cells","Only red blood cells","Only thymic epithelial cells","Only B lymphocytes"]'::jsonb, 'Virtually all nucleated cells', 'MHC class I is expressed on virtually all nucleated cells, presenting endogenous peptides to CD8+ cytotoxic T cells.'),
('b564f100-8ae1-51aa-8022-d83c42f07a41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'When viral or bacterial antigens share structural similarity with host molecules and trigger a response that cross-reacts with self tissues, the outcome is best classified under which process?', '["Type IV hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type II hypersensitivity","Type I hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Molecular mimicry, in which a microbial antigen resembles a self antigen, can trigger a cross-reactive immune response that damages host tissues - a classic autoimmune mechanism.'),
('536fe8b4-bcae-5a63-80b2-595cf9e92e65'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'IL-8 (CXCL8) functions chiefly as which of the following?', '["A chemokine that recruits neutrophils","A macrophage-activating cytokine","AB-cell growth factor","An inhibitor of inflammation","A mast-cell degranulator"]'::jsonb, 'A chemokine that recruits neutrophils', 'IL-8 is a CXC chemokine that acts as a potent chemoattractant and activator of neutrophils at sites of inflammation.'),
('bac69a05-442e-5aa5-800a-2a64158db626'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'An inherited deficiency of the beta-2 integrin chain CD18 is the molecular basis of which disorder?', '["Leukocyte adhesion deficiency type 1","Chronic granulomatous disease","Chediak-Higashi syndrome","Hyper-IgM syndrome","Severe combined immunodeficiency"]'::jsonb, 'Leukocyte adhesion deficiency type 1', 'Leukocyte adhesion deficiency type 1 results from defective CD18-containing integrins, impairing leukocyte adhesion and emigration, with marked leukocytosis and recurrent infections.'),
('ed7a2892-939f-5740-98e8-b1f4c1674a8c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The rejection of skin and other solid-organ grafts is mediated chiefly by T lymphocytes that respond to donor histocompatibility antigens. Which immunologic mechanism is at work?', '["Type III hypersensitivity","Type I hypersensitivity","Type IV hypersensitivity","Autoimmune reaction","Type II hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Solid-organ graft rejection is chiefly Type IV (cell-mediated) hypersensitivity: recipient T lymphocytes recognize donor MHC antigens and destroy graft tissue.'),
('4af2a1a9-a2e1-5eb0-988c-55a02dd2c6d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A positive tuberculin skin test 2 to 3 days after injection in a previously sensitized person reflects activation of which immune mechanism?', '["Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Autoimmune reaction","Type I hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'The positive tuberculin reaction, read at 48-72 hours, is produced by Type IV (delayed-type) hypersensitivity mediated by sensitized T cells and activated macrophages.'),
('14d81070-9bf8-5196-8727-2ee49c6be3a6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Multiple sclerosis, in which sensitized T lymphocytes damage central nervous system myelin, is an example of which immunologic process?', '["Type III hypersensitivity","Type IV hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type II hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Multiple sclerosis is driven by sensitized T lymphocytes that cross the blood-brain barrier and attack central nervous system myelin, a Type IV (cell-mediated) reaction.'),
('b544e0fd-1912-5ebd-8f01-c8131d4fc83e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Pemphigus vulgaris blisters result from autoantibodies that bind and disrupt the desmoglein adhesion molecules of epidermal cells. Which immunologic mechanism causes these lesions?', '["Autoimmune reaction","Type II hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity","Type I hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Pemphigus vulgaris is a Type II (antibody-mediated) reaction: autoantibodies against desmogleins disrupt keratinocyte adhesion, causing acantholysis and blister formation.'),
('fe5bdb76-854c-5c52-b4b4-e85bf2d9559f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Disorders such as myasthenia gravis and Graves disease arise because antibodies are produced against the patient''s own tissues. Which broad category best describes this phenomenon?', '["Type I hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type II hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'In myasthenia gravis and Graves disease, the immune system produces antibodies against the body''s own tissues - an autoimmune reaction.'),
('1285d897-837c-50b6-9d10-56f94c4aacec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Exposure to cat dander causes a person with atopy to develop violent sneezing, an itchy nose, and lacrimation. Which type of immune reaction produces this picture?', '["Autoimmune reaction","Type III hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Atopic symptoms provoked by allergen contact, including sneezing and lacrimation, result from Type I hypersensitivity mediated by mast cell-bound IgE degranulation.'),
('f9e3a53e-9d28-5730-bce6-81cfbb1a319f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A pharmaceutical worker who becomes sensitized to latex glove powder develops urticaria and wheezing on exposure. Which immunologic mechanism is most likely responsible?', '["Type III hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Occupational latex allergy with urticaria and wheezing is a Type I (immediate) hypersensitivity reaction in which IgE-coated mast cells degranulate on allergen exposure.'),
('464bf1ba-8391-5bfd-8f8f-2e04ae38876f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Central tolerance is established chiefly by which process?', '["Clonal deletion of self-reactive lymphocytes in the thymus and bone marrow","Anergy of all mature T cells","Somatic hypermutation in germinal centers","Complement-mediated elimination of self-reactive B cells","Recruitment of eosinophils to the thymus"]'::jsonb, 'Clonal deletion of self-reactive lymphocytes in the thymus and bone marrow', 'During central tolerance, self-reactive thymocytes and immature B cells recognize self antigens with high avidity and are deleted by apoptosis.'),
('680cc6a0-eca0-5e23-818c-85f460aefb8a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Hereditary angioedema results from deficiency of which protein, causing episodic mucosal and subcutaneous swelling?', '["C1 inhibitor","C3","C5","Factor B","Properdin"]'::jsonb, 'C1 inhibitor', 'C1-inhibitor deficiency permits uncontrolled activation of complement and the contact system, producing episodes of angioedema related to bradykinin excess.'),
('8496fce0-bb62-559f-b7f8-1fffe5c259b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Severe combined immunodeficiency caused by adenosine deaminase deficiency results from accumulation of which toxic metabolite?', '["Deoxyadenosine (dATP)","Ornithine","Homocysteine","Tryptophan","Galactose-1-phosphate"]'::jsonb, 'Deoxyadenosine (dATP)', 'ADA deficiency leads to accumulation of deoxyadenosine and its nucleotide, which are toxic to lymphocytes and cause severe T- and B-cell immunodeficiency.'),
('87243db5-cbe9-587e-86ee-11142153a370'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following normally acts at birth, providing immediate, non-specific defense?', '["Phagocytosis and the complement cascade","Antigen-specific memory T cells","Antibody production by plasma cells","Class switching and affinity maturation","Cytotoxic killing by sensitized CD8 T cells"]'::jsonb, 'Phagocytosis and the complement cascade', 'Innate immunity includes barriers, phagocytes, NK cells, and complement, acting immediately and non-selectively without immunologic memory.'),
('44589a29-f7a4-505e-b4b0-e6ec5ad92dc8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The symptoms of allergic rhinitis are caused chiefly by which mediator released from mast cells?', '["Histamine","Perforin","Granzyme B","Membrane attack complex","Tumor necrosis factor only"]'::jsonb, 'Histamine', 'Histamine released from sensitized mast cells causes vasodilation, increased vascular permeability, and mucus secretion, producing the symptoms of allergic rhinitis.'),
('d71db679-f168-5a5f-b194-6f5549d1a6de'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Job (hyper-IgE) syndrome is most characteristically associated with which of the following?', '["Recurrent boils (skin abscesses), eczema, pneumonia, and a very high serum IgE","Absence of B cells accompanied by associated clinical symptoms","Thymic aplasia mediated by specific receptor activation","Deficiency of membrane attack complement components without affecting the primary tissue pathway","Defective CD18 integrins leading to subsequent cellular adaptation"]'::jsonb, 'Recurrent boils (skin abscesses), eczema, pneumonia, and a very high serum IgE', 'Hyper-IgE (Job) syndrome is a STAT3-defect disorder causing eczema, recurrent staphylococcal skin and lung abscesses, and markedly elevated IgE.'),
('8a5dd02b-b537-50f2-9709-ce99246d2a55'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A 25-year-old woman develops anaphylaxis after exposure to an allergen. Which reaction best describes this condition?', '["Type II hypersensitivity","Autoimmune reaction","Type III hypersensitivity","Type I hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type I hypersensitivity', 'Anaphylaxis is a systemic immediate (Type I) hypersensitivity reaction caused by IgE-mediated mast-cell and basophil degranulation.'),
('e2bba65c-55ca-50af-a1df-5ffca19b4cc5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Trisomy 21 (Down syndrome) is most often caused by which of the following chromosomal events?', '["Meiotic nondisjunction producing an extra chromosome 21","Deletion of the short arm of chromosome 5","Balanced translocation inherited only from the father","Loss of an X chromosome","Trisomy of chromosome 18"]'::jsonb, 'Meiotic nondisjunction producing an extra chromosome 21', 'Down syndrome usually results from maternal meiotic nondisjunction, giving three copies of chromosome 21 in about 95% of cases.'),
('eac45773-94ff-5c38-91df-38c0240bf09b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Primary (genetic) immunodeficiencies most often manifest with which recurring clinical pattern?', '["Recurrent, severe, or unusual infections","A single isolated autoantibody","Anaphylaxis to a single allergen","Completely uneventful vaccinations","Adult-onset diabetes"]'::jsonb, 'Recurrent, severe, or unusual infections', 'Primary immunodeficiencies are inborn errors of immunity that typically present with recurrent, severe, or opportunistic infections in infancy or childhood.'),
('680be43f-e410-5a63-af49-5050ae006eb2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The tissue damage of lupus nephritis is mediated mainly by which mechanism?', '["Type I hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Lupus nephritis results from immune-complex (Type III) deposition in glomeruli, activating complement and recruiting inflammatory cells.'),
('0af55eaa-0617-5502-868d-07e4296d4fba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A patient develops symmetric polyarthritis with morning stiffness and anti-cyclic citrullinated peptide antibodies, with an immune reaction against her own joints. Which process is responsible?', '["Type I hypersensitivity","Autoimmune reaction","Type II hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Symmetric inflammatory polyarthritis with anti-CCP antibodies is rheumatoid arthritis, an autoimmune disease driven by loss of self-tolerance.'),
('4db8da94-af01-5816-a6fb-fa986ab9ba59'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which cells are the principal effectors that release mediators during anaphylaxis?', '["Mast cells and basophils","Red blood cells and platelets","CD8+ cytotoxic T cells","Macrophages and dendritic cells","Eosinophils only"]'::jsonb, 'Mast cells and basophils', 'Anaphylaxis is caused by massive degranulation of sensitized mast cells and basophils, which release histamine and other vasoactive mediators.'),
('50151d3a-6c26-50d8-8988-e187574fc6da'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'An infant with severe combined immunodeficiency has neither T nor B cells but has preserved NK cells. Which genetic defect is most likely?', '["RAG1/RAG2 (recombinase-activating gene) deficiency","X-linked (common gamma chain) SCID","Adenosine deaminase deficiency","DiGeorge syndrome","Hyper-IgM syndrome"]'::jsonb, 'RAG1/RAG2 (recombinase-activating gene) deficiency', 'RAG1/RAG2 mediate V(D)J recombination; their deficiency abolishes T- and B-cell development while NK cells, which do not rearrange receptors, are preserved.'),
('6fdbc4ef-d292-5d55-9b5b-2f0ff38bdb50'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which disorder arises from a defect in the fucosylation of selectin ligands, causing failure of leukocyte rolling, absence of pus, and recurrent infections (plus mental retardation)?', '["Leukocyte adhesion deficiency type 2 (fucose transporter defect)","Leukocyte adhesion deficiency type 1 (CD18) accompanied by associated clinical symptoms","Chronic granulomatous disease mediated by specific receptor activation","Hyper-IgM syndrome without affecting the primary tissue pathway","Myeloperoxidase deficiency leading to subsequent cellular adaptation"]'::jsonb, 'Leukocyte adhesion deficiency type 2 (fucose transporter defect)', 'LAD type 2 results from a fucose-transport defect that disrupts selectin-ligand synthesis, impairing leukocyte rolling and causing recurrent infections without pus.'),
('1b73c305-eae6-5427-b601-be4d318ba3e2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Farmer''s lung develops after repeated inhalation of moldy hay dust, when inhaled fungal antigens form complexes with antibody in the lung tissue. Which immunologic mechanism produces the alveolitis?', '["Type I hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Type II hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type III hypersensitivity', 'Farmer''s lung is a Type III (immune-complex) reaction: inhaled fungal antigens form complexes with antibody in lung tissue, causing complement-mediated alveolitis.'),
('11ddfb7a-907b-5268-a508-fc3486113bd5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Sarcoidosis non-caseating granulomas, formed from activated macrophages and CD4 T cells, are the expression of which immune mechanism?', '["Autoimmune reaction","Type III hypersensitivity","Type II hypersensitivity","Type I hypersensitivity","Type IV hypersensitivity"]'::jsonb, 'Type IV hypersensitivity', 'Non-caseating granulomas of sarcoidosis are formed by activated CD4 T cells and macrophages - the hallmark of a Type IV (cell-mediated) immune response.'),
('a87435f5-7396-5177-9081-c60a2cd8361b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which transcription factor is the master regulator of Th1 cell differentiation?', '["T-bet","GATA-3","ROR-gamma-t","FoxP3","STAT6"]'::jsonb, 'T-bet', 'T-bet drives the differentiation of naive CD4 cells into IFN-gamma-producing Th1 cells, the effector subset of Type IV (cell-mediated) reactions.'),
('37cd2c11-3799-5c54-ab43-3bdff9bcf9ab'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The immune surveillance hypothesis is most strongly supported by the increased incidence of which of the following in immunodeficient and immunosuppressed patients?', '["Cancers such as lymphomas, Kaposi sarcoma, and cervical cancer","Allergic rhinitis accompanied by associated clinical symptoms","Autoimmune hemolytic anemia mediated by specific receptor activation","Contact dermatitis without affecting the primary tissue pathway","Drug anaphylaxis leading to subsequent cellular adaptation"]'::jsonb, 'Cancers such as lymphomas, Kaposi sarcoma, and cervical cancer', 'Immunodeficient and immunosuppressed patients show increased virus-associated cancers, supporting immune surveillance as a defense against malignant cells.'),
('8255d004-1d3b-5e81-b88e-ed32cab8f653'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A vasculitis characterized by fibrinoid necrosis of vessel walls, produced by antigen-antibody complexes formed in slight antigen excess, best matches which mechanism?', '["Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type III hypersensitivity', 'Fibrinoid necrosis of vessel walls produced by immune complexes formed in slight antigen excess is characteristic of Type III (immune-complex) hypersensitivity.'),
('03a180b9-a6af-5641-8034-95966d978018'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following statements is TRUE about the immunoglobulins?', '["IgE mediates immediate hypersensitivity and defense against helminths","IgA crosses the placenta","IgM is found mainly in mucosal secretions","IgG is the first antibody produced in primary responses","IgD is the most abundant serum antibody"]'::jsonb, 'IgE mediates immediate hypersensitivity and defense against helminths', 'IgE binds mast cells and basophils to mediate anaphylaxis while also contributing to immunity against parasites; the other pairings are reversed or false.'),
('958e5d6a-e62b-5a39-9722-6afa13bb6958'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following is NOT typical of common variable immunodeficiency (CVID)?', '["Absence of all T cells in a young child","Recurrent sinopulmonary infections with low serum immunoglobulins","Increased risk of autoimmune disease","Response to intravenous immunoglobulin therapy","Increased risk of lymphoma"]'::jsonb, 'Absence of all T cells in a young child', 'CVID is a predominantly antibody deficiency in which T-cell numbers are usually preserved, so T-cell absence is not characteristic; infections, autoimmunity, and lymphoma are.'),
('d85cd6ab-6907-5344-bec9-bb83329067c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A middle-aged woman with sicca symptoms has lymphocytic destruction of the salivary and lacrimal glands by her own immune system. Which immunologic process underlies this dryness?', '["Type IV hypersensitivity","Type I hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type III hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Sjogren syndrome is an autoimmune reaction in which lymphocytes destroy the salivary and lacrimal glands, causing dry eyes and dry mouth.'),
('9497861e-437e-5160-a6cf-297b5189f564'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Serum sickness and the lesions it produces depend on circulating immune complexes that deposit in vessels, joints, and kidneys. Which type of immune injury is involved?', '["Autoimmune reaction","Type II hypersensitivity","Type I hypersensitivity","Type IV hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Serum sickness and its Arthus-like lesions are Type III reactions produced by circulating immune complexes that deposit in vessels, joints, and kidneys.'),
('c7667a96-6176-5c5e-9dd7-2685dc6307f5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A patient with immune thrombocytopenia produces antibodies against platelet surface glycoproteins, and the coated platelets are then destroyed in the spleen. Which immune process is responsible?', '["Type I hypersensitivity","Type II hypersensitivity","Type III hypersensitivity","Type IV hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type II hypersensitivity', 'Immune thrombocytopenia is a Type II (antibody-mediated) disorder in which antiplatelet antibodies opsonize platelets, which are then destroyed by splenic macrophages.'),
('1b5e112d-c668-55a1-88ac-5ee4d0a669fc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The cellular basis of adaptive immunity resides in which cell populations?', '["T and B lymphocytes","Neutrophils and eosinophils","Red blood cells and platelets","Monocytes and mast cells","Basophils and dendritic cells alone"]'::jsonb, 'T and B lymphocytes', 'Adaptive immunity is mediated by lymphocytes: B cells produce antibodies (humoral) and T cells mediate cellular immunity, with specificity and memory.'),
('eabcf925-0b8e-5bdb-bcd5-8424cc1bea17'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'In transplantation immunology, the principal target recognized by recipient T cells on donor cells is which of the following?', '["Donor MHC (HLA) molecules","Blood glucose","Complement receptors","Fc receptors","Secretory IgA"]'::jsonb, 'Donor MHC (HLA) molecules', 'Recipient T cells recognize donor HLA (MHC) molecules as foreign, driving graft rejection; HLA matching therefore improves graft survival.'),
('55751e02-3286-547d-92b2-6141dcf2b174'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Somatic hypermutation and affinity maturation of B cells occur within which anatomic structure?', '["Germinal centers of secondary lymphoid follicles","Bone marrow sinusoids accompanied by associated clinical symptoms","Thymic cortex mediated by specific receptor activation","Peyer''s patches only without affecting the primary tissue pathway","Splenic red pulp leading to subsequent cellular adaptation"]'::jsonb, 'Germinal centers of secondary lymphoid follicles', 'In germinal centers, activated B cells undergo somatic hypermutation and class switching, with antigen-driven selection of high-affinity clones.'),
('b98ef576-f7f6-5722-8ae8-731c13260220'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'A polyarteritis nodosa-like necrotizing vasculitis in which complexes of hepatitis B surface antigen and antibody deposit in small arteries reflects which immunologic mechanism?', '["Type III hypersensitivity","Type IV hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type I hypersensitivity"]'::jsonb, 'Type III hypersensitivity', 'Hepatitis B-associated polyarteritis nodosa is a Type III reaction in which immune complexes of viral antigen and antibody deposit in small arteries, causing necrotizing vasculitis.'),
('28121f43-215a-5214-b227-d4a401f114e7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Acute cellular rejection of a liver transplant, in which host cytotoxic T lymphocytes attack the donor hepatocytes, reflects which immunologic mechanism?', '["Type I hypersensitivity","Type IV hypersensitivity","Type II hypersensitivity","Type III hypersensitivity","Autoimmune reaction"]'::jsonb, 'Type IV hypersensitivity', 'Acute cellular rejection, with host cytotoxic T lymphocytes destroying donor hepatocytes, represents Type IV (cell-mediated) hypersensitivity.'),
('ec110183-d055-5868-8055-fbedc27a5216'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Antibodies characteristic of Sjogren syndrome, which can cause congenital heart block when present in pregnancy, include which of the following?', '["Anti-Ro/SSA and anti-La/SSB","Anti-Scl-70","Anti-centromere","Anti-dsDNA","Anti-CCP"]'::jsonb, 'Anti-Ro/SSA and anti-La/SSB', 'Anti-Ro (SSA) and anti-La (SSB) are the serologic hallmarks of Sjogren syndrome; anti-Ro crosses the placenta and can cause fetal congenital heart block.'),
('4c4ced44-cd89-5627-8ae4-d5bc8b6e9fe9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Adenosine deaminase (ADA) deficiency produces severe combined immunodeficiency by which mechanism?', '["Accumulation of toxic deoxyadenosine metabolites that kill lymphocytes","Failure of formation of the thymus accompanied by associated clinical symptoms","Defective CD18 integrins mediated by specific receptor activation","Lack of C3 and terminal complement without affecting the primary tissue pathway","Antibody-mediated lysis of B cells leading to subsequent cellular adaptation"]'::jsonb, 'Accumulation of toxic deoxyadenosine metabolites that kill lymphocytes', 'ADA deficiency accumulates deoxyadenosine and its nucleotides, which are toxic to developing lymphocytes, causing profound T- and B-cell deficiency.'),
('d9b7c42d-ddd8-573f-87f2-072693393fb8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Type III (immune-complex) hypersensitivity tissue injury is mediated chiefly by which cells?', '["Neutrophils recruited by complement C5a","Mast cells and basophils","CD8+ cytotoxic T lymphocytes","Eosinophils alone","Platelets only"]'::jsonb, 'Neutrophils recruited by complement C5a', 'In Type III reactions, immune complexes activate complement and generate C5a, which recruits neutrophils that release proteolytic enzymes damaging tissues.'),
('4e82b4f6-8bea-57b6-ae3f-d0bdb47a2191'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'C5 convertase formation ultimately leads to assembly of which of the following structures?', '["Membrane attack complex (C5b-9)","IgE-mediated degranulation","Granuloma formation","Immune-complex nephritis","Preformed T-cell receptor"]'::jsonb, 'Membrane attack complex (C5b-9)', 'C5 convertase cleaves C5 to C5b, initiating assembly of the membrane attack complex C5b-9, which lyses antibody- or complement-coated target cells.'),
('79dc383c-6b5c-551d-a3a9-dfff1d214f09'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following most accurately describes an X-linked recessive disorder?', '["Affected males are usually the sons of carrier (heterozygous) mothers","Only females can be carriers","Affected males transmit the trait to all their sons","Daughters of affected males are always unaffected","Males cannot be affected"]'::jsonb, 'Affected males are usually the sons of carrier (heterozygous) mothers', 'In X-linked recessive inheritance, hemizygous males are affected and typically inherit the mutant allele from carrier mothers; affected males do not transmit it to sons.'),
('e54196ac-5a18-5f26-88da-e7dc3d5fee79'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Antibodies directed against cell-surface antigens cause complement-mediated lysis, as occurs when transplacental maternal antibodies damage fetal cells. Which category of immune injury does this represent?', '["Type III hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune reaction","Type II hypersensitivity"]'::jsonb, 'Type II hypersensitivity', 'Antibody binding to cell-surface antigens with complement-mediated lysis, as in transplacental antibody disease, defines Type II (cytotoxic) hypersensitivity.'),
('e6c6c799-d4df-53ed-9ea5-6452a2417b92'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The B-cell receptor, which is surface immunoglobulin, recognizes which of the following?', '["Native (free) antigen","Only peptide-MHC complexes","CD1-presented lipid antigens","Superantigens cross-linking TCR V-beta","Complement proteins"]'::jsonb, 'Native (free) antigen', 'Unlike the T-cell receptor, the B-cell receptor (surface immunoglobulin) recognizes native, unprocessed antigen directly, including conformational epitopes.'),
('1307cdb1-24ec-5ee4-bb79-e1438210f959'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Recurrent, severe herpesvirus infections may reflect defective killing by which cells?', '["Natural killer cells","Neutrophils","B lymphocytes","Memory CD4+ T cells","Eosinophils"]'::jsonb, 'Natural killer cells', 'NK cells are a first line of defense against herpesviruses and provide early killing of infected cells; NK-cell deficiency causes severe viral infections.'),
('116f3192-6872-54fc-9a75-c8350cb56c7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Scleroderma with widespread fibrosis appears after the immune system produces antibodies against the body''s own connective tissue. Which mechanism best describes the underlying disorder?', '["Type I hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type II hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Scleroderma is an autoimmune disease in which the immune system targets self connective-tissue antigens, producing widespread fibrosis and vasculopathy.'),
('ac5ccf50-3267-5bf7-9c69-0c381456778d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which triad classically characterizes Wiskott-Aldrich syndrome?', '["Eczema, thrombocytopenia, and recurrent infections","Cafe-au-lait spots, polyostotic fibrous dysplasia, precocious puberty","Recurrent abscesses, coarse facies, and high IgE","Recurrent Neisseria infections and complement deficiency","Hepatosplenomegaly, jaundice, and neonatal sepsis"]'::jsonb, 'Eczema, thrombocytopenia, and recurrent infections', 'Wiskott-Aldrich syndrome (WASP mutation) classically presents with the triad of eczema, thrombocytopenia (small defective platelets), and recurrent infections.'),
('c26da1ea-ab5f-58a4-bed4-083d35e7c139'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which cells are the principal producers of the interleukins that orchestrate immune responses?', '["Lymphocytes and macrophages","Erythrocytes","Keratocytes","Hepatocytes","Adipocytes"]'::jsonb, 'Lymphocytes and macrophages', 'Lymphocytes (especially T helper cells) and macrophages are the major sources of interleukins that regulate the growth, differentiation, and activation of immune cells.'),
('c67a56e2-c606-5b03-a5ab-96b023d5330e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Hyper-IgM syndrome, with very low IgG and IgA but elevated IgM, is most often caused by a defect in which of the following?', '["CD40 ligand on T cells","Bruton tyrosine kinase (BTK)","Common gamma chain","MHC class II","Adenosine deaminase"]'::jsonb, 'CD40 ligand on T cells', 'In X-linked hyper-IgM syndrome, defective CD40L prevents T-cell help and class switching, so B cells produce only IgM.'),
('7980c815-5d6f-5341-b70f-918241263896'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Polymyositis and dermatomyositis, in which lymphocytes invade the patient''s own skeletal muscle, best illustrate which immunologic process?', '["Type IV hypersensitivity","Type II hypersensitivity","Autoimmune reaction","Type I hypersensitivity","Type III hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Polymyositis and dermatomyositis are autoimmune diseases in which cytotoxic T lymphocytes invade and damage the patient''s own skeletal muscle.'),
('62f16be6-34ed-5caa-9407-2108d9ef0596'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Immune responses directed against self antigens, whether through molecular mimicry, loss of tolerance, or polyclonal activation, produce what type of disease process?', '["Type I hypersensitivity","Type III hypersensitivity","Autoimmune reaction","Type IV hypersensitivity","Type II hypersensitivity"]'::jsonb, 'Autoimmune reaction', 'Autoimmune disease results when the immune system attacks the body''s own tissues through mechanisms such as molecular mimicry, loss of tolerance, or polyclonal activation.'),
('dec65543-fb45-5d09-9906-102cc717290b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'IL-10 is best characterized as which of the following?', '["A major anti-inflammatory cytokine that suppresses effector T-cell responses","A pyrogen that induces fever accompanied by associated clinical symptoms","A potent neutrophil chemoattractant mediated by specific receptor activation","A mast-cell-activating factor without affecting the primary tissue pathway","A complement component leading to subsequent cellular adaptation"]'::jsonb, 'A major anti-inflammatory cytokine that suppresses effector T-cell responses', 'IL-10, produced by regulatory T cells and macrophages, dampens inflammation and limits tissue damage by suppressing cytokine production.'),
('c1aa3be2-d546-5c41-82c5-26f4264991ca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Selective IgA deficiency, the most common primary immunodeficiency, most characteristically presents with which of the following?', '["Mild recurrent sinopulmonary and gastrointestinal infections, sometimes with transfusion reactions","Severe opportunistic infections at birth accompanied by associated clinical symptoms","Chronic granulomatous abscesses mediated by specific receptor activation","Recurrent herpes zoster without affecting the primary tissue pathway","Intractable pruritus leading to subsequent cellular adaptation"]'::jsonb, 'Mild recurrent sinopulmonary and gastrointestinal infections, sometimes with transfusion reactions', 'Selective IgA deficiency is usually mild or asymptomatic but can cause sinopulmonary/GI infections; anti-IgA antibodies can provoke anaphylactic transfusion reactions.'),
('83e2824d-5819-5371-a5cd-155c14649c68'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following correctly explains the increased susceptibility to infection in patients with DiGeorge syndrome?', '["T-cell deficiency from thymic aplasia or hypoplasia","B-cell deficiency from a BTK mutation","Phagocyte NADPH oxidase failure","Complement C5-C9 deficiency","Defective CD18 integrin"]'::jsonb, 'T-cell deficiency from thymic aplasia or hypoplasia', 'DiGeorge syndrome (22q11 deletion) disrupts third and fourth pharyngeal pouch development, causing thymic hypoplasia with consequent T-cell immunodeficiency.'),
('e3a81eb0-31ea-5dd0-9f68-f06aa7bb6b3e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Adaptive immunity is characterized by which of the following?', '["Memory","Immediate response without memory","Specificity and memory","Non-specific response","Same response to all pathogens"]'::jsonb, 'Specificity and memory', 'Adaptive immunity is defined by antigen specificity and immunologic memory, enabling rapid, stronger responses on re-exposure.'),
('cf017dcc-974c-5195-9a6b-b5da7d1e3594'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following is the defining characteristic of the adaptive immune response?', '["Memory","Immediate response without memory","Specificity and memory","Non-specific response","Same response to all pathogens"]'::jsonb, 'Specificity and memory', 'Adaptive immunity is distinguished by antigen-specific recognition and immunologic memory, allowing a faster and stronger response on re-exposure.'),
('e20e128d-833f-541b-873d-2c1f9ba324bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Adaptive immunity differs from innate immunity chiefly in which of the following respects?', '["Memory","Immediate response without memory","Specificity and memory","Non-specific response","Same response to all pathogens"]'::jsonb, 'Specificity and memory', 'The key differences between adaptive and innate immunity are antigen specificity and immunologic memory, hallmarks of the adaptive response.'),
('d74a79b2-ab61-561b-ad52-8353d8128665'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which combination of properties best characterizes adaptive immunity?', '["Memory","Immediate response without memory","Specificity and memory","Non-specific response","Same response to all pathogens"]'::jsonb, 'Specificity and memory', 'Adaptive immunity is built on specificity for individual antigens and memory of prior exposures, giving faster and stronger secondary responses.'),
('d13b1203-5bb1-5202-b65a-741987a024f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The immune response that improves with each exposure because of recall is best characterized by which of the following?', '["Memory","Immediate response without memory","Specificity and memory","Non-specific response","Same response to all pathogens"]'::jsonb, 'Specificity and memory', 'Repeated exposure produces progressively stronger, faster responses because adaptive immunity retains specific memory of past antigens.'),
('b110f08a-e304-5b0c-ad16-9d52e68ce129'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which component mediates the humoral arm of the immune response?', '["T lymphocytes","Dendritic cells","Macrophages","B lymphocytes and antibodies","NK cells"]'::jsonb, 'B lymphocytes and antibodies', 'Humoral immunity is carried out by B lymphocytes that differentiate into plasma cells secreting antibodies.'),
('4f5ff4c8-67cb-5510-a88f-b33b44e05a42'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The antibody arm of the immune system, called humoral immunity, is carried out chiefly by which of the following?', '["T lymphocytes","Dendritic cells","Macrophages","B lymphocytes and antibodies","NK cells"]'::jsonb, 'B lymphocytes and antibodies', 'Antibodies (immunoglobulins) produced by B-lymphocyte-derived plasma cells are the mediators of humoral immunity.'),
('d054d2c3-3f7c-5524-9b90-8336346ce028'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'B-cell-mediated immunity, which protects against extracellular microbes, is mediated by which of the following?', '["T lymphocytes","Dendritic cells","Macrophages","B lymphocytes and antibodies","NK cells"]'::jsonb, 'B lymphocytes and antibodies', 'Extracellular microbes are neutralized by antibodies secreted by plasma cells derived from B lymphocytes - the humoral immune response.'),
('a50fdb4a-5de1-5788-ba09-56befbdc1812'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which of the following effectors mediate humoral immunity?', '["T lymphocytes","Dendritic cells","Macrophages","B lymphocytes and antibodies","NK cells"]'::jsonb, 'B lymphocytes and antibodies', 'Humoral immunity is mediated by B lymphocytes and the antibodies (immunoglobulins) they produce.'),
('0eb4b1cc-f0fe-58dd-a986-c120b6aa01c2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Anaphylaxis, allergic rhinitis, and asthma share which mediator cells and molecules?', '["IgE and mast cells","T cells","IgM","Immune complexes","IgG and complement"]'::jsonb, 'IgE and mast cells', 'Allergic (Type I) diseases depend on allergen-specific IgE bound to mast cells and basophils, which degranulate and release vasoactive mediators.'),
('e4aaf0f2-b7d8-585a-8bff-b57dccdb54f3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'The immediate, anaphylactic reaction is mediated by which of the following?', '["IgE and mast cells","T cells","IgM","Immune complexes","IgG and complement"]'::jsonb, 'IgE and mast cells', 'Anaphylaxis results from allergen cross-linking of mast cell- and basophil-bound IgE, causing rapid release of histamine and other mediators.'),
('5e9361f9-df75-5c66-8947-b51d0ef5b77a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Mast cell- and IgE-dependent hypersensitivity corresponds to which of the following combinations?', '["IgE and mast cells","T cells","IgM","Immune complexes","IgG and complement"]'::jsonb, 'IgE and mast cells', 'The pairing of allergen-specific IgE with mast cells (and basophils) is the defining feature of immediate Type I hypersensitivity.'),
('4ee6794e-8feb-584e-9d25-0687b97ea45f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which effector pair is responsible for the immediate wheal-and-flare reaction?', '["IgE and mast cells","T cells","IgM","Immune complexes","IgG and complement"]'::jsonb, 'IgE and mast cells', 'Cross-linking of IgE on mast cells triggers degranulation and release of histamine, producing the immediate wheal-and-flare response.'),
('9227a1e5-0963-52a5-85f5-9b0799325569'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which reaction occurs within minutes of allergen exposure and involves IgE on mast cells?', '["Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune disease"]'::jsonb, 'Type I hypersensitivity', 'Type I (immediate) hypersensitivity develops within minutes because pre-formed IgE on mast cells degranulates rapidly upon allergen cross-linking.'),
('85096172-82e4-5ec3-86c0-fc608ff3de0c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which type of hypersensitivity is characterized by rapid mast-cell degranulation after allergen exposure?', '["Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune disease"]'::jsonb, 'Type I hypersensitivity', 'Immediate (Type I) hypersensitivity is driven by allergen-induced degranulation of mast cells and basophils bearing specific IgE.'),
('f040bb93-61d9-5131-bf9b-ee89a52dd70b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which reaction produces the immediate wheal-and-flare response after intradermal allergen challenge?', '["Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune disease"]'::jsonb, 'Type I hypersensitivity', 'Histamine released from mast cells during Type I reactions causes local vasodilation and edema, producing the immediate wheal-and-flare response.'),
('904754ec-1c8c-518c-9fc9-8eea5cfa8873'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Immunopathology Genetics', 'Which hypersensitivity is mediated by allergen cross-linking of IgE on the surface of mast cells?', '["Type III hypersensitivity","Type II hypersensitivity","Type IV hypersensitivity","Type I hypersensitivity","Autoimmune disease"]'::jsonb, 'Type I hypersensitivity', 'In Type I (immediate) hypersensitivity, allergen cross-links mast cell-bound IgE, triggering degranulation and mediator release within minutes.'),
('402f60b3-496b-5f8a-9d72-7b43487628b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A neoplasm is best defined as:', '["An autonomous monoclonal proliferation of cells with genetic abnormality","A reactive polyclonal increase in cell number","Normal tissue present in an abnormal location","Physiologic regeneration after injury","A reversible adaptive cellular response"]'::jsonb, 'An autonomous monoclonal proliferation of cells with genetic abnormality', 'Neoplasms arise from a single transformed cell whose genome has been altered; they proliferate autonomously and escape normal growth control. The reactive, polyclonal and reversible processes listed lack this genetic-autonomous basis.'),
('2a4e8c87-01a3-5fae-ac3d-f1050dfc3a8c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which feature most reliably distinguishes a malignant tumor from a benign one?', '["Invasion of neighboring tissues and metastasis","Rapid rate of growth","Onset in older age","Large size of the mass","Presence of a fibrous capsule"]'::jsonb, 'Invasion of neighboring tissues and metastasis', 'Invasion and metastasis are the defining attributes of malignancy. Benign tumors are usually well circumscribed and never metastasize, regardless of size, growth rate, or the patient''s age.'),
('d957293b-6e0b-5785-915a-81312440ae50'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'All of the following are characteristic of benign tumors EXCEPT:', '["Well-circumscribed growth","Slow growth with a low mitotic rate","Absence of metastasis","Production of a fibrous capsule","Invasion of blood vessels"]'::jsonb, 'Invasion of blood vessels', 'Invasion of vessels is a sign of malignancy. Benign tumors grow expansively, remain localized, are often encapsulated and do not metastasize.'),
('f843d3ba-48fc-5fe3-a9fc-903c4a1d917a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A benign epithelial tumor arising from glandular epithelium is called a(n):', '["Adenoma","Carcinoma","Sarcoma","Hamartoma","Blastoma"]'::jsonb, 'Adenoma', 'Adenoma denotes a benign neoplasm of glandular epithelium. Carcinoma and sarcoma are malignant, while a hamartoma is a localized overgrowth of mature tissue and blastoma implies embryonic tissue.'),
('6bd76549-da0f-5a71-b79b-ea8fbf0b6519'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A malignant tumor of connective tissue origin is best termed a:', '["Sarcoma","Carcinoma","Adenocarcinoma","Lymphoma","Leukemia"]'::jsonb, 'Sarcoma', 'Malignant tumors of connective tissue are sarcomas. Carcinomas and adenocarcinomas arise from epithelium, lymphomas from lymphoid tissue, and leukemia from bone-marrow hematopoietic cells.'),
('4663f3b6-ac07-5fdf-b541-886e7471e3e2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A benign epithelial tumor that grows as a finger-like projection from a surface is a:', '["Papilloma","Polyp","Adenoma","Cystadenoma","Choristoma"]'::jsonb, 'Papilloma', 'A papilloma is a benign epithelial neoplasm with a finger-like (papillary) growth pattern on a stromal stalk. A polyp is a gross description, and cystadenoma forms cysts.'),
('fb9bae9c-4fce-54ca-a2cb-43e6bf34e766'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A malignant tumor of glandular epithelium is correctly called:', '["Adenocarcinoma","Squamous carcinoma","Transitional cell carcinoma","Adenoid cystic carcinoma","Serous carcinoma"]'::jsonb, 'Adenocarcinoma', 'Adenocarcinoma is the malignant counterpart of glandular epithelium. The other terms denote specific epithelial subtypes rather than a general definition of glandular malignancy.'),
('69563b20-76aa-53c5-91fc-37beda30c8fb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The suffix ''-oma'' in tumor nomenclature classically denotes:', '["A benign tumor (with important exceptions)","A malignant tumor accompanied by associated clinical symptoms","A dysplastic lesion mediated by specific receptor activation","An inflammatory mass without affecting the primary tissue pathway","A hamartoma leading to subsequent cellular adaptation"]'::jsonb, 'A benign tumor (with important exceptions)', 'Most tumors named with ''-oma'' are benign, but notable malignant exceptions (lymphoma, melanoma, seminoma, hepatoma) must be memorized. The suffix itself does not imply inflammation or dysplasia.'),
('8705ca95-ece1-58ae-8d8e-61e54cd98769'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which cytologic feature is characteristic of anaplastic malignant cells?', '["Nuclear pleomorphism with hyperchromasia","Small uniform nuclei","Low nuclear-to-cytoplasmic ratio","Prominent basement membrane","Differentiation toward adult tissue"]'::jsonb, 'Nuclear pleomorphism with hyperchromasia', 'Anaplastic cells show marked variation in nuclear size and shape, hyperchromatic nuclei, large nucleoli, and high nuclear-to-cytoplasmic ratio. Uniform small nuclei and differentiation are features of benign or well-differentiated cells.'),
('5cbad680-81d5-524f-848f-bc6225ce727b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Anaplasia is best defined as:', '["Lack of differentiation toward a mature cell type","Loss of apoptosis accompanied by associated clinical symptoms","Excess gland formation mediated by specific receptor activation","Reversible adaptive growth without affecting the primary tissue pathway","Polyclonal expansion leading to subsequent cellular adaptation"]'::jsonb, 'Lack of differentiation toward a mature cell type', 'Anaplasia literally means ''backward forming'' and represents lack of differentiation, the cytologic hallmark of malignancy. It is irreversible and unrelated to a single mechanism such as apoptosis.'),
('3df6375f-3e25-5be8-8361-cf6eb9e703e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The retinoblastoma (RB) gene product exerts its tumor-suppressive effect by:', '["Blocking the G1-to-S transition of the cell cycle","Repairing double-strand DNA breaks","Inhibiting telomerase","Degrading p53","Promoting angiogenesis"]'::jsonb, 'Blocking the G1-to-S transition of the cell cycle', 'RB in its hypophosphorylated state sequesters E2F transcription factors and halts the cell at the G1 checkpoint; phosphorylation by cyclin-CDK releases E2F and allows S-phase entry. RB does not repair DNA or degrade p53.'),
('45288384-be45-50df-b8b5-353f7f5a0ff9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'p53 is called the ''guardian of the genome'' because it:', '["Arrests the cell cycle or triggers apoptosis after DNA damage","Repairs DNA directly as an enzyme accompanied by associated clinical symptoms","Prevents telomere shortening mediated by specific receptor activation","Activates oncogenes without affecting the primary tissue pathway","Promotes angiogenesis leading to subsequent cellular adaptation"]'::jsonb, 'Arrests the cell cycle or triggers apoptosis after DNA damage', 'After DNA damage p53 induces G1 arrest, DNA repair, or apoptosis, preserving genomic integrity and eliminating potentially malignant cells. It is a transcription factor, not a repair enzyme or telomerase inhibitor.'),
('d9f327a3-961b-52f1-b19c-217c8672b4e7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which statement about TP53 mutations in human cancer is correct?', '["They are loss-of-function mutations found in over half of common cancers","They are inherited in nearly all sporadic cancers","They produce constitutive tyrosine kinase activity","They always confer response to targeted therapy","They are limited to a single tumor type"]'::jsonb, 'They are loss-of-function mutations found in over half of common cancers', 'TP53 is the most commonly mutated gene in human cancer; most are missense loss-of-function mutations accumulating late in tumor progression. The alterations are usually somatic, not inherited, and are not targetable by a simple kinase inhibitor.'),
('551914bc-ad48-55d5-8fce-037d426f46e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most commonly mutated oncogene across human cancers is:', '["RAS (KRAS)","MYC","HER2","BRAF","RET"]'::jsonb, 'RAS (KRAS)', 'Activating point mutations of RAS family genes, especially KRAS, occur in roughly 30% of human tumors including pancreas, colon, and lung. It is the most frequently mutated oncogene overall.'),
('55dcabed-6a6c-5a68-b42f-5dba58710ade'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The BCR-ABL fusion gene characteristic of chronic myeloid leukemia results from:', '["A balanced translocation between chromosomes 9 and 22","A point mutation in the ABL gene","Amplification of chromosome 22","Deletion of chromosome 9q","Promoter hypermethylation of BCR"]'::jsonb, 'A balanced translocation between chromosomes 9 and 22', 't(9;22), the Philadelphia chromosome, fuses BCR to the ABL tyrosine kinase, producing a constitutively active chimeric kinase. It is the hallmark cytogenetic event of CML.'),
('9c293e0a-d38e-5ba1-af9e-303daf36f045'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'HER2/neu (ERBB2) amplification in breast cancer predicts a favorable response to:', '["Trastuzumab (HER2-directed therapy)","Tamoxifen accompanied by associated clinical symptoms","Aromatase inhibitors mediated by specific receptor activation","Imatinib without affecting the primary tissue pathway","Radiotherapy alone leading to subsequent cellular adaptation"]'::jsonb, 'Trastuzumab (HER2-directed therapy)', 'HER2-amplified breast cancers respond to trastuzumab, a monoclonal antibody against HER2. Tamoxifen targets the estrogen receptor and imatinib targets BCR-ABL and KIT.'),
('b27b3989-d4bb-5783-a4d9-b58ba6125480'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'HER2/neu amplification is most characteristic of which malignancy?', '["Breast cancer","Colon cancer","Melanoma","Osteosarcoma","Glioblastoma"]'::jsonb, 'Breast cancer', 'HER2 (ERBB2) amplification occurs in about 20-25% of invasive breast cancers and predicts response to trastuzumab. It is not characteristic of colon cancer, melanoma, or glioblastoma.'),
('ef880269-1aea-5f60-bf27-f4e67001b543'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'An activating BRAF V600E point mutation is the hallmark molecular lesion of:', '["Melanoma","Medullary thyroid carcinoma","Chronic myeloid leukemia","Follicular lymphoma","Small cell lung carcinoma"]'::jsonb, 'Melanoma', 'BRAF V600E, in the RAS-MAP kinase pathway, is found in roughly half of cutaneous melanomas and is the target of vemurafenib. CML and follicular lymphoma are defined by translocations, not BRAF.'),
('5fafaa05-22b1-5886-9400-8da4ac925094'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Imatinib mesylate exerts its antileukemic effect by inhibiting:', '["The constitutively active BCR-ABL tyrosine kinase","VEGF receptor signaling accompanied by associated clinical symptoms","The HER2 receptor mediated by specific receptor activation","BRAF kinase without affecting the primary tissue pathway","Cyclin-dependent kinase 4 leading to subsequent cellular adaptation"]'::jsonb, 'The constitutively active BCR-ABL tyrosine kinase', 'Imatinib binds and blocks the BCR-ABL tyrosine kinase produced by t(9;22), producing remissions in CML. Its off-target activities also inhibit KIT and PDGF receptors.'),
('ebe2af33-430d-5a54-9744-fd731094b9ea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'RAS proteins are switched off by:', '["Intrinsic GTPase activity stimulated by GAPs","Phosphorylation by tyrosine kinases","Ubiquitin-mediated degradation","Acetylation of lysine residues","Binding to heat-shock proteins"]'::jsonb, 'Intrinsic GTPase activity stimulated by GAPs', 'RAS cycles between an active GTP-bound and inactive GDP-bound form; GTPase-activating proteins (GAPs) accelerate intrinsic GTP hydrolysis. Oncogenic RAS mutations impair this GTPase activity.'),
('9feb6e3b-ded8-5bc6-aa2b-a42df1ad226f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The translocation t(8;14), which places MYC under the control of an immunoglobulin enhancer, is characteristic of:', '["Burkitt lymphoma","Follicular lymphoma","Mantle cell lymphoma","Chronic lymphocytic leukemia","Chronic myeloid leukemia"]'::jsonb, 'Burkitt lymphoma', 'In Burkitt lymphoma t(8;14) juxtaposes the MYC oncogene with the immunoglobulin heavy-chain locus, driving MYC overexpression. Follicular (14;18) and mantle cell (11;14) lymphomas carry different translocations.'),
('27f44a65-79aa-572d-a2c4-f306712c6294'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'At(14;18) translocation causing BCL-2 overexpression is the defining genetic event of:', '["Follicular lymphoma","Burkitt lymphoma","Anaplastic large cell lymphoma","Mantle cell lymphoma","Acute promyelocytic leukemia"]'::jsonb, 'Follicular lymphoma', 't(14;18) brings BCL-2 under immunoglobulin enhancer control, protecting follicular lymphoma cells from apoptosis. Burkitt lymphoma is defined by MYC and mantle cell lymphoma by cyclin D1.'),
('249b8293-1d51-59a9-a733-482feda235e0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Overexpression of cyclin D1 due to t(11;14) characterizes:', '["Mantle cell lymphoma","Ewing sarcoma","Burkitt lymphoma","Osteosarcoma","Small cell lung carcinoma"]'::jsonb, 'Mantle cell lymphoma', 't(11;14) places the CCND1/cyclin D1 gene under the immunoglobulin heavy-chain enhancer, causing cyclin D1 overexpression and uncontrolled G1-S transit in mantle cell lymphoma.'),
('9723baf2-d0d8-582b-8243-e8143874c1ae'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Anaplastic large cell lymphoma is defined by a translocation involving:', '["ALK (t(2;5))","BCL-2","MYC","RAS","EGFR"]'::jsonb, 'ALK (t(2;5))', 'The t(2;5) translocation fuses ALK with a nucleophosmin partner, creating a constitutively active ALK kinase in anaplastic large cell lymphoma. This is detected by ALK immunostaining.'),
('f689e225-5138-5f98-922c-c4c34210797c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A balanced translocation fusing EWSR1 with an ETS-family transcription-factor gene is the characteristic molecular abnormality of:', '["Ewing sarcoma","Osteosarcoma","Synovial sarcoma","Rhabdomyosarcoma","Leiomyosarcoma"]'::jsonb, 'Ewing sarcoma', 'About 85-90% of Ewing sarcomas carry t(11;22) producing the EWSR1-FLI1 fusion protein. Osteosarcoma and rhabdomyosarcoma are not defined by this translocation.'),
('419c40e5-3570-5b9f-a4f0-ffef2c0e4545'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Gain-of-function mutations of KIT (c-kit) are typical of:', '["Gastrointestinal stromal tumors (GIST)","Colorectal adenocarcinoma","Pancreatic ductal carcinoma","Hepatocellular carcinoma","Renal cell carcinoma"]'::jsonb, 'Gastrointestinal stromal tumors (GIST)', 'About 85% of GISTs show activating KIT mutations, making them responsive to imatinib. The other listed tumors are not driven by KIT mutation.'),
('efd49719-3323-5624-ab9a-dabb5d44b514'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Germline point mutations of the RET proto-oncogene predispose most strongly to:', '["Multiple endocrine neoplasia types 2A and 2B","Familial adenomatous polyposis","Li-Fraumeni syndrome","Cowden syndrome","Neurofibromatosis type 1"]'::jsonb, 'Multiple endocrine neoplasia types 2A and 2B', 'Activating germline RET mutations cause MEN 2 (medullary thyroid carcinoma, pheochromocytoma, and in 2B mucosal neuromas). The other syndromes arise from mutations of tumor suppressor genes.'),
('c6faf8f1-177c-57b2-85c6-1741d7e1961e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The APC tumor suppressor controls the WNT signaling pathway by:', '["Promoting proteasomal degradation of beta-catenin","Activating RAS accompanied by associated clinical symptoms","Sequestering p53 mediated by specific receptor activation","Inhibiting telomerase without affecting the primary tissue pathway","Phosphorylating EGFR leading to subsequent cellular adaptation"]'::jsonb, 'Promoting proteasomal degradation of beta-catenin', 'APC is part of the destruction complex that targets cytoplasmic beta-catenin for degradation. Loss of APC stabilizes beta-catenin, which translocates to the nucleus and activates MYC and cyclin D1.'),
('c4e18fe0-c4b6-57e2-b267-2520926a1a1f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Familial adenomatous polyposis is caused by a germline mutation in:', '["The APC gene","The TP53 gene","The RB1 gene","A DNA mismatch-repair gene","The NF1 gene"]'::jsonb, 'The APC gene', 'FAP results from germline APC mutations on chromosome 5q21, producing hundreds of colonic adenomas that uniformly progress to carcinoma. The other genes cause different hereditary syndromes.'),
('3d9c0d35-19a8-5432-8252-1efaeb2c968c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Lynch syndrome (hereditary nonpolyposis colorectal cancer) results from germline mutation of:', '["DNA mismatch-repair genes (e.g., MLH1, MSH2)","The APC gene accompanied by associated clinical symptoms","The TP53 gene mediated by specific receptor activation","The BRCA1 gene without affecting the primary tissue pathway","The WT1 gene leading to subsequent cellular adaptation"]'::jsonb, 'DNA mismatch-repair genes (e.g., MLH1, MSH2)', 'Lynch syndrome is caused by germline mutations in mismatch-repair genes (MLH1, MSH2, MSH6, PMS2) that produce microsatellite instability. APC mutation instead causes FAP.'),
('2b6fecdb-b75d-53b5-a189-fddefd43a61f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Tumors arising in Lynch syndrome characteristically show:', '["Microsatellite instability","Intact mismatch repair","Gain-of-function TP53 mutation","HER2 amplification","BCR-ABL translocation"]'::jsonb, 'Microsatellite instability', 'Loss of mismatch-repair function in Lynch syndrome yields microsatellite instability, a molecular signature readily detected in the tumor. The other findings are unrelated to DNA mismatch repair.'),
('399d0592-4da6-5445-b026-a66e56fb8d86'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Germline mutations of BRCA1 and BRCA2 strongly predispose to:', '["Breast and ovarian carcinoma","Colorectal carcinoma","Melanoma","Gastric carcinoma","Hepatocellular carcinoma"]'::jsonb, 'Breast and ovarian carcinoma', 'BRCA genes are DNA double-strand-break repair proteins; their germline loss produces genomic instability and a high lifetime risk of breast and ovarian cancer. Other tumors are not the signature cancers.'),
('03601cbd-4efe-5734-9237-fe461c9c7ec4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'BRCA1 and BRCA2 function principally in:', '["Homologous-recombination repair of double-strand DNA breaks","Nucleotide excision repair accompanied by associated clinical symptoms","Base excision repair mediated by specific receptor activation","Mismatch repair without affecting the primary tissue pathway","O6-methylguanine repair leading to subsequent cellular adaptation"]'::jsonb, 'Homologous-recombination repair of double-strand DNA breaks', 'BRCA proteins participate in homologous recombination, the error-free repair of double-strand breaks. Their loss causes genomic instability and sensitivity to PARP inhibition.');
insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('59c6f514-8789-5794-9d08-efd5638909ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Li-Fraumeni syndrome is caused by a germline mutation in:', '["TP53","APC","RB1","BRCA1","MSH2"]'::jsonb, 'TP53', 'Li-Fraumeni syndrome is an autosomal-dominant germline mutation of TP53 producing early-onset sarcomas, breast cancer, brain tumors, and leukemia. The other genes define different syndromes.'),
('3beb9985-2832-5219-b0c5-6b27c28691d6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The tumor spectrum of Li-Fraumeni syndrome classically includes:', '["Sarcomas, breast cancer, brain tumors, and leukemia","Colon and endometrial carcinoma","Medullary thyroid carcinoma and pheochromocytoma","Renal carcinoma and hemangioblastoma","Neurofibromas and schwannomas"]'::jsonb, 'Sarcomas, breast cancer, brain tumors, and leukemia', 'Loss of germline p53 predisposes to a broad spectrum including sarcomas, breast cancer, brain tumors, leukemia, and adrenocortical carcinoma, all at unusually young ages.'),
('79daeafc-2e25-5914-b714-29b396840c4f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Knudson''s ''two-hit'' hypothesis of tumorigenesis was derived from studies of:', '["Retinoblastoma","Breast cancer","Colon cancer","Melanoma","Lung cancer"]'::jsonb, 'Retinoblastoma', 'Knudson proposed that retinoblastoma requires inactivation of both RB1 alleles: in hereditary cases the first hit is inherited and the second occurs somatically; in sporadic cases both hits are somatic.'),
('f3e21089-96d5-5ac1-8066-904c08585c3d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Compared with sporadic retinoblastoma, the hereditary form characteristically:', '["Is bilateral, multiple, and occurs at a younger age","Is unilateral and solitary","Lacks RB1 mutation","Has a uniformly fatal outcome","Spreads by transcoelomic seeding"]'::jsonb, 'Is bilateral, multiple, and occurs at a younger age', 'Because the first hit is already present in every cell, hereditary retinoblastoma is usually bilateral, multifocal, and earlier in onset. Sporadic disease requires two somatic events.'),
('20893f8f-c4ea-5797-aae1-353966b169d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which tumor suppressor is frequently inactivated by promoter hypermethylation in a wide range of cancers?', '["p16 (CDKN2A/INK4a)","MYC accompanied by associated clinical symptoms","RAS mediated by specific receptor activation","BCL-2 without affecting the primary tissue pathway","HER2 leading to subsequent cellular adaptation"]'::jsonb, 'p16 (CDKN2A/INK4a)', 'Silencing of p16 by CpG-island promoter methylation is common in many cancers, functioning like mutation of the gene. MYC, RAS, and HER2 are proto-oncogenes and BCL-2 is an antiapoptotic gene.'),
('5508e014-aa3a-5e06-b000-8953120eca57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Reactivation of telomerase in cancer cells principally:', '["Endows cells with unlimited replicative capacity","Repairs DNA adducts","Suppresses angiogenesis","Blocks cell-cycle arrest","Induces differentiation"]'::jsonb, 'Endows cells with unlimited replicative capacity', 'Telomerase maintains telomere length so that chromosomes do not shorten with each division, conferring cellular immortality, an essential goal for tumor progression.'),
('408cf1e9-dd12-524c-bc1c-e1a1ddc4f032'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Microsatellite instability arises from defective:', '["Mismatch repair of replication errors","Homologous-recombination repair","Nucleotide excision repair","Base excision repair","Nonhomologous end joining"]'::jsonb, 'Mismatch repair of replication errors', 'Microsatellites are short repeat sequences that slip during DNA replication; mismatch-repair (MMR) proteins correct these errors. When MMR fails, repeat lengths change, producing microsatellite instability.'),
('23a1a38a-4717-5ee0-a6d2-7ac5efe843f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Microsatellite instability is most characteristic of which cancer?', '["Colorectal carcinoma arising in Lynch syndrome","Small cell lung carcinoma accompanied by associated clinical symptoms","Prostate adenocarcinoma mediated by specific receptor activation","Osteosarcoma without affecting the primary tissue pathway","Hodgkin lymphoma leading to subsequent cellular adaptation"]'::jsonb, 'Colorectal carcinoma arising in Lynch syndrome', 'Mismatch-repair deficiency defines the Lynch syndrome colorectal tumors, which show high-level microsatellite instability. The other tumors are not linked to this defect.'),
('3102bea6-5ce3-53c2-83ae-7e43d2cbf4df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which virus encodes E6 and E7 proteins that collaborate to transform cells?', '["Human papillomavirus","Epstein-Barr virus","Hepatitis B virus","HTLV-1","HIV"]'::jsonb, 'Human papillomavirus', 'High-risk HPV E6 and E7 oncoproteins inactivate p53 and RB respectively, cooperating to immortalize and transform keratinocytes and initiate cervical carcinoma.'),
('cb8b48e9-6406-574e-ae33-c14545eed7f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The HPV E6 oncoprotein contributes to transformation primarily by:', '["Targeting p53 for ubiquitin-mediated degradation","Inactivating RB","Blocking p16","Directly activating RAS","Inhibiting matrix metalloproteinases"]'::jsonb, 'Targeting p53 for ubiquitin-mediated degradation', 'E6 binds p53 and promotes its ubiquitin-proteasome destruction, eliminating the cell''s DNA-damage checkpoint and apoptosis response. E7 independently inactivates RB.'),
('45d8447c-5d7b-5b51-bc10-4dde422a4579'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The HPV E7 oncoprotein promotes transformation primarily by:', '["Inactivating the RB tumor suppressor","Degrading p53","Activating RAS","Blocking apoptosis via BCL-2","Activating mismatch repair"]'::jsonb, 'Inactivating the RB tumor suppressor', 'E7 binds and inactivates RB, releasing E2F and forcing cells into S phase, which combined with E6-mediated p53 loss drives genomic instability and transformation.'),
('ea7916d1-e0ea-54a7-be48-b7e150d7475e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Persistent infection with high-risk HPV is etiologically linked to:', '["Cervical carcinoma","Hepatocellular carcinoma","Adult T-cell leukemia/lymphoma","Kaposi sarcoma","Nasopharyngeal carcinoma"]'::jsonb, 'Cervical carcinoma', 'HPV 16/18 infections are the central cause of cervical carcinoma via E6/E7 inactivation of p53 and RB. HCC is linked to HBV/HCV, ATLL to HTLV-1, Kaposi to HHV-8, and NPC to EBV.'),
('91c554a3-2b43-5a48-922a-faf8128a337e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Endemic (African) Burkitt lymphoma is strongly associated with:', '["Epstein-Barr virus","Human papillomavirus","HTLV-1","HHV-8","Hepatitis C virus"]'::jsonb, 'Epstein-Barr virus', 'In equatorial Africa nearly all Burkitt lymphomas carry EBV genomes, which cooperate with the t(8;14) MYC translocation. Sporadic Burkitt lymphoma is much less often EBV-positive.'),
('3e11c329-4730-5e60-a2f0-76483c57227b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which malignant neoplasm, endemic in southern China, is strongly EBV-associated?', '["Nasopharyngeal carcinoma","Gastric adenocarcinoma","Hepatocellular carcinoma","Cervical carcinoma","Colorectal carcinoma"]'::jsonb, 'Nasopharyngeal carcinoma', 'Undifferentiated nasopharyngeal carcinoma is consistently EBV-associated and is endemic in southern China. EBV also contributes to endemic Burkitt lymphoma and Hodgkin lymphoma.'),
('0437ce10-4bce-53fe-a7be-148fb541e2d6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Chronic infection with hepatitis B and hepatitis C viruses is a well-established risk factor for:', '["Hepatocellular carcinoma","Bladder carcinoma","Esophageal squamous carcinoma","Colon carcinoma","Lung carcinoma"]'::jsonb, 'Hepatocellular carcinoma', 'Both HBV (through integration and chronic hepatitis) and HCV (through cirrhosis, inflammation, and oxidative damage) drive hepatocarcinogenesis. HCC is among the most common cancers worldwide.'),
('7a0f92dc-f20e-5395-84c5-676aa3fffaf3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'HTLV-1 infection causes which malignancy?', '["Adult T-cell leukemia/lymphoma","Burkitt lymphoma","Hodgkin lymphoma","Multiple myeloma","Hairy cell leukemia"]'::jsonb, 'Adult T-cell leukemia/lymphoma', 'The retrovirus HTLV-1, endemic in Japan and the Caribbean, causes adult T-cell leukemia/lymphoma after decades of latent infection via the Tax oncoprotein. The other tumors have different etiologies.'),
('ddd0d20c-82a7-57ce-ad82-c681ff6e067e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Kaposi sarcoma is etiologically linked to infection with:', '["Human herpesvirus 8 (KSHV)","Epstein-Barr virus","Human papillomavirus","Hepatitis C virus","HTLV-1"]'::jsonb, 'Human herpesvirus 8 (KSHV)', 'Kaposi sarcoma is caused by HHV-8 (KSHV), a gammaherpesvirus, and develops in HIV/AIDS, transplant, and endemic settings. It is not caused by EBV, HPV, or HTLV-1.'),
('2704c7ce-1863-508c-8b15-8aa53e455aa0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The proliferating cell in Kaposi sarcoma is of:', '["Endothelial (vascular) origin","Lymphocyte origin","Epithelial origin","Melanocyte origin","Mast-cell origin"]'::jsonb, 'Endothelial (vascular) origin', 'Despite the ''sarcoma'' name, Kaposi sarcoma is a neoplasm of HHV-8-infected endothelial (spindle) cells with a prominent angiomatous component.'),
('86a4ecf6-d05f-57b2-8a5b-e248c6fed87c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Aflatoxin B1, which contaminates stored grains and nuts, is most strongly associated with:', '["Hepatocellular carcinoma","Bladder carcinoma","Mesothelioma","Acute leukemia","Angiosarcoma of the liver"]'::jsonb, 'Hepatocellular carcinoma', 'Aflatoxin B1 is a fungal metabolite that, after P-450 activation, binds DNA and induces a characteristic TP53 mutation; it is a major cause of HCC in Africa and Asia.'),
('587583f9-5ad0-5fe1-9f3b-295d105b460d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Aflatoxin B1 characteristically induces which mutation in the TP53 gene?', '["AG-to-T transversion at codon 249","AC-to-T transition at a CpG site","A frameshift deletion","A chromosomal translocation","Promoter hypermethylation"]'::jsonb, 'AG-to-T transversion at codon 249', 'The aflatoxin-induced DNA adduct at guanine produces the signature arg249-to-ser p53 transversion found in HCC from aflatoxin-endemic regions.'),
('eb3b1e0c-7d5a-5d29-a42f-31c7193d901b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Exposure to vinyl chloride gas in PVC manufacturing is classically linked to:', '["Angiosarcoma of the liver","Cervical carcinoma","Gastric carcinoma","Ovarian carcinoma","Thyroid carcinoma"]'::jsonb, 'Angiosarcoma of the liver', 'Vinyl chloride monomer is a direct-acting hepatic carcinogen causing angiosarcoma of the liver. It is a classic occupational carcinogen taught with asbestos and aromatic amines.'),
('d026a299-3d02-5a11-8e9d-d3790a7440b4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Chronic benzene exposure increases the risk of:', '["Acute myeloid leukemia","Hepatocellular carcinoma","Bladder carcinoma","Mesothelioma","Colon carcinoma"]'::jsonb, 'Acute myeloid leukemia', 'Benzene, an organic solvent, is a known leukemogen causing especially acute myeloid leukemia and myelodysplastic syndrome. It does not cause the other listed tumors.'),
('3c01c383-eafd-5fc9-a90e-e45a948e6d88'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Occupational asbestos exposure is most closely associated with which tumor?', '["Mesothelioma","Squamous carcinoma of the cervix","Hepatocellular carcinoma","Cholangiocarcinoma","Renal cell carcinoma"]'::jsonb, 'Mesothelioma', 'Asbestos fibers cause mesothelioma, particularly with prolonged heavy exposure, and also increase the risk of lung carcinoma. The other tumors have unrelated etiologies.'),
('f71ce07a-a477-50b7-b50b-5afbda2215c6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Aromatic amines such as benzidine and beta-naphthylamine predispose to:', '["Bladder carcinoma","Lung carcinoma","Gastric carcinoma","Malignant melanoma","Bone sarcoma"]'::jsonb, 'Bladder carcinoma', 'Aromatic amine dyes are classic bladder carcinogens, acting after hepatic conjugation and urinary concentration of the carcinogen. They are an important occupational cause of urothelial cancer.'),
('907f76cf-6490-5fd3-9287-581117901ccc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Among histologic types of lung cancer, cigarette smoking shows the strongest association with:', '["Squamous cell carcinoma","Adenocarcinoma","Bronchioloalveolar carcinoma","Typical carcinoid tumor","Malignant mesothelioma"]'::jsonb, 'Squamous cell carcinoma', 'Squamous cell carcinoma of the lung has the closest historical link to heavy smoking and declined in relative frequency when smoking fell; the others are weaker or unrelated associations.'),
('1a4eb5c8-ee66-5799-86fb-1f899daaf806'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'N-nitrosamines, formed from dietary nitrites, are implicated in the pathogenesis of:', '["Gastric carcinoma","Malignant melanoma","Osteosarcoma","Glioblastoma","Multiple myeloma"]'::jsonb, 'Gastric carcinoma', 'Nitrite preservatives in cured meats convert to N-nitrosamines in the stomach, contributing to gastric cancer, especially intestinal-type. The other tumors are not nitrosamine-associated.'),
('286e7ed7-ff46-5aab-8e3c-e500b408269f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Ultraviolet radiation causes skin cancer by generating:', '["Pyrimidine (thymine) dimers in DNA","Double-strand breaks in DNA","Mismatch-repair errors","Telomere elongation","Histone hyperacetylation"]'::jsonb, 'Pyrimidine (thymine) dimers in DNA', 'UV-B produces thymine dimers that, if unrepaired by nucleotide excision repair, cause C-to-T transition mutations, the signature mutations of UV-induced skin cancer.'),
('176f9658-90ab-5bd9-a70b-0d52244b71dd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Whole-body exposure to ionizing radiation classically increases the risk of:', '["Leukemia (especially acute myeloid leukemia)","Prostate carcinoma accompanied by associated clinical symptoms","Malignant melanoma mediated by specific receptor activation","Follicular lymphoma without affecting the primary tissue pathway","Cervical carcinoma leading to subsequent cellular adaptation"]'::jsonb, 'Leukemia (especially acute myeloid leukemia)', 'Ionizing radiation damages DNA directly and via free radicals; survivors of atomic bombs and radiation accidents show increased leukemias and certain solid tumors. Leukemia has the shortest latency.'),
('5c2b4d7d-a9a9-56ca-971d-a028bb079939'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Radon exposure in underground miners predisposes most strongly to:', '["Lung cancer","Bladder cancer","Bone sarcoma","Hepatic angiosarcoma","Leukemia"]'::jsonb, 'Lung cancer', 'Radon, an alpha-emitting gas that accumulates in uranium mines and homes, is the second leading cause of lung cancer after smoking. It is not linked to bone or hepatic tumors.'),
('9f5cfab6-da85-51bb-94c2-4af3c8b111f7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Childhood exposure of the head and neck to ionizing radiation classically leads to:', '["Papillary thyroid carcinoma","Ovarian carcinoma","Testicular seminoma","Hepatocellular carcinoma","Multiple myeloma"]'::jsonb, 'Papillary thyroid carcinoma', 'The pediatric thyroid is very radiosensitive; historical irradiation and Chernobyl fallout increased papillary thyroid carcinoma. The other tumors are not radiation-driven thyroid effects.'),
('c18cfd5b-6f15-5390-ae0e-6e987b8ae64a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The classic sequence of mutation in colorectal carcinogenesis is:', '["APC, then RAS, then TP53 and losses on chromosome 18q","TP53, then RAS, then APC accompanied by associated clinical symptoms","RAS, then APC, then TP53 mediated by specific receptor activation","BRCA, then APC, then RAS without affecting the primary tissue pathway","MYC, then APC, then RB leading to subsequent cellular adaptation"]'::jsonb, 'APC, then RAS, then TP53 and losses on chromosome 18q', 'The adenoma-carcinoma sequence begins with APC loss, adds KRAS activation, and culminates in TP53 mutation and DCC/SMAD4 loss on 18q, yielding invasive carcinoma.'),
('e8ee7d77-4126-5020-901a-88e2d49da6a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In chemical carcinogenesis, ''initiation'' is best defined as:', '["An irreversible somatic DNA mutation","A reversible epigenetic change","A growth-promoting hormonal effect","Formation of a metastasis","Activation of the immune response"]'::jsonb, 'An irreversible somatic DNA mutation', 'Initiation permanently alters DNA (for example, mutating RAS or a tumor suppressor) and is irreversible; a single initiating event renders the cell capable of neoplastic growth. Promotion then expands initiated cells.'),
('c2474845-c24a-5e27-b8dc-9aaec0358dc2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The ''promotion'' stage of chemical carcinogenesis is characterized by:', '["Reversible expansion of initiated cells that requires continued exposure","Irreversible DNA damage accompanied by associated clinical symptoms","Cell death of transformed clones mediated by specific receptor activation","Loss of the initiating mutation without affecting the primary tissue pathway","Immediate metastasis to regional nodes leading to subsequent cellular adaptation"]'::jsonb, 'Reversible expansion of initiated cells that requires continued exposure', 'Promoters are non-mutagenic agents that stimulate proliferation of already-initiated cells; the effect is reversible if exposure stops. They do not mutate DNA directly.'),
('869075d8-5ff8-5989-928c-15b875862ecc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'An agent that can both initiate and promote tumorigenesis on its own is called a:', '["Complete carcinogen","Cocarcinogen","Tumor promoter","Pure mutagen","Anticarcinogen"]'::jsonb, 'Complete carcinogen', 'Complete carcinogens (e.g., tobacco smoke, aflatoxin) possess both initiating (mutagenic) and promoting activity. Cocarcinogens only enhance an unrelated carcinogen and promoters act after initiation.'),
('68eeab1e-0bfb-5f17-aaf0-856ad51f79b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Genomic instability in cancer is best reflected by:', '["Progressive accumulation of mutations within a tumor clone","A uniform diploid karyotype","Absence of telomerase activity","Single-hit transformation","A purely polyclonal lesion"]'::jsonb, 'Progressive accumulation of mutations within a tumor clone', 'Rigging of DNA repair, checkpoints, and apoptosis lets cancer clones accumulate successive mutations and chromosomal abnormalities. This mutation burden drives heterogeneity and progression.'),
('92af4a04-b732-5d22-85f4-abc98ba7fc3b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In Vogelstein''s terminology, ''caretaker'' genes encode products that:', '["Maintain genomic integrity through DNA repair","Directly control cell proliferation","Regulate physiologic cell death","Act as growth factors","Metabolize carcinogens"]'::jsonb, 'Maintain genomic integrity through DNA repair', 'Caretaker genes (e.g., MMR, BRCA, NER genes) preserve the genome by repairing DNA; their loss produces high mutation rates. Gatekeeper genes such as APC directly control cell growth.'),
('1ce3b0c6-2576-58c4-9005-ba7e2140311c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'APC is classically cited as a ''gatekeeper'' gene because its function:', '["Directly regulates cell birth and death in the colonic crypt","Repairs DNA mismatches accompanied by associated clinical symptoms","Maintains telomere length mediated by specific receptor activation","Controls proteolytic degradation of p53 without affecting the primary tissue pathway","Blocks immune recognition leading to subsequent cellular adaptation"]'::jsonb, 'Directly regulates cell birth and death in the colonic crypt', 'Gatekeeper genes directly govern cell proliferation and apoptosis in a tissue; APC loss deregulates WNT signaling and initiates adenoma formation. Caretaker genes instead safeguard the genome.'),
('4898626a-777a-5724-bb3e-0d1bbf1db8ed'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Oncogenes are considered ''dominant'' because:', '["A mutation in a single allele can promote transformation","Both alleles must be inactivated","They are inherited in a recessive pattern","They act only in the germline","They silence tumor suppressors"]'::jsonb, 'A mutation in a single allele can promote transformation', 'A gain-of-function change in one allele of a proto-oncogene suffices to push the cell toward growth, so oncogenes act dominantly. Tumor suppressor genes require biallelic loss.'),
('cf810623-0987-5a1a-a391-c00d69446e85'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A proto-oncogene is best defined as:', '["A normal cellular gene that promotes growth when activated","A viral gene that causes cancer","A mutated tumor suppressor gene","A gene that repairs DNA","A gene controlling apoptosis only"]'::jsonb, 'A normal cellular gene that promotes growth when activated', 'Proto-oncogenes are normal genes whose products promote proliferation; when activated by mutation, amplification, or translocation they become cancer-causing oncogenes.'),
('8b4514eb-eb29-509c-89a1-dc05a05d05a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The c-ErbB2 (HER2/neu) gene encodes:', '["A transmembrane receptor tyrosine kinase of the EGFR family","A GTPase that brakes cell growth","A cytoplasmic serine/threonine kinase","A transcription factor promoting differentiation","A cell-adhesion molecule"]'::jsonb, 'A transmembrane receptor tyrosine kinase of the EGFR family', 'HER2 (ERBB2) is a receptor tyrosine kinase of the epidermal growth factor receptor family; amplification of this gene drives a subset of breast cancers.'),
('f286f4c9-61b7-5cf1-a9c5-a31a521c8925'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'When RB is phosphorylated by cyclin-CDK complexes it releases:', '["E2F transcription factors, allowing S-phase entry","p53 for ubiquitination","Caspases to induce apoptosis","VEGF to promote angiogenesis","Cyclin-dependent kinase inhibitors"]'::jsonb, 'E2F transcription factors, allowing S-phase entry', 'Hypophosphorylated RB holds E2F inactive; cyclin-CDK phosphorylation frees E2F, which transcribes S-phase genes. This is how RB loss or CDK overactivity drives proliferation.'),
('9ff65425-9814-52ce-bf47-f4f3eee71ee1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which protein negatively regulates p53 by marking it for degradation?', '["MDM2","E2F","p16","BCL-2","Cyclin D1"]'::jsonb, 'MDM2', 'MDM2 binds p53, ubiquitinates it, and sends it to the proteasome; MDM2 amplification or p53 inactivation are alternative ways to disable the p53 checkpoint.'),
('2b61256b-4899-591a-b29c-6c0e4e8dafe3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'p16 (INK4a) exerts its tumor-suppressive action by inhibiting:', '["CDK4/6-cyclin D kinase activity","Telomerase reverse transcriptase","Matrix metalloproteinase secretion","HER2 dimerization","p53 ubiquitination"]'::jsonb, 'CDK4/6-cyclin D kinase activity', 'p16 blocks cyclin D-CDK4/6 phosphorylation of RB, keeping E2F sequestered and cells in G1. Loss of p16 (mutation or methylation) removes this brake.'),
('6bbb0cc9-12ab-5523-8d02-3d88270af469'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Overexpression of which protein confers apoptosis resistance on follicular lymphoma cells?', '["BCL-2","p53","BAX","Caspase-9","Fas"]'::jsonb, 'BCL-2', 'BCL-2 is an antiapoptotic protein; its overexpression in t(14;18) follicular lymphoma protects cells from programmed cell death, permitting their accumulation.'),
('b31634ac-ce01-5c43-88e1-c03dd53086f5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Epithelial-mesenchymal transition (EMT) is characterized by:', '["Loss of E-cadherin with acquisition of mesenchymal proteins","Gain of E-cadherin expression","Upregulation of desmosomes","Increased hemidesmosome adhesion","Retention of polarity and adhesion"]'::jsonb, 'Loss of E-cadherin with acquisition of mesenchymal proteins', 'During EMT cells lose E-cadherin-mediated adhesion and polarity and gain vimentin and other mesenchymal features, acquiring motility needed for invasion and metastasis.'),
('d0961ebe-acff-587f-93eb-f4fe5e673684'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Tumor invasion through the extracellular matrix is mediated chiefly by:', '["Matrix metalloproteinases (MMPs)","Cyclin-dependent kinases","E-cadherin","Histone deacetylases","Adrenal corticosteroids"]'::jsonb, 'Matrix metalloproteinases (MMPs)', 'Malignant cells secrete MMPs (e.g., collagenase, gelatinase) that degrade basement membrane and stroma, permitting invasion. Cell-cycle or epigenetic enzymes do not degrade matrix.'),
('f56a31a3-8f48-5497-9c16-fea48b3dc20f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Hypoxia stimulates tumor angiogenesis primarily through:', '["HIF-1alpha-mediated upregulation of VEGF","Inactivation of telomerase","Downregulation of PDGF","Increased p53 expression","Loss of MMP activity"]'::jsonb, 'HIF-1alpha-mediated upregulation of VEGF', 'Low oxygen stabilizes HIF-1alpha, which transcriptionally upregulates VEGF and other angiogenic factors, recruiting new vessels to the growing tumor.'),
('362cc46c-804f-5a39-8572-4abffbf5ddbb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which growth factor is the principal driver of tumor angiogenesis?', '["Vascular endothelial growth factor (VEGF)","Epidermal growth factor (EGF)","Transforming growth factor-alpha","Platelet-derived growth factor","Insulin-like growth factor"]'::jsonb, 'Vascular endothelial growth factor (VEGF)', 'VEGF is the most important pro-angiogenic factor, secreted by hypoxic tumor cells and targeting endothelial cells to form new vessels; it is the target of bevacizumab.'),
('180a2a78-c39f-5ed3-be56-febd92051fa4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Bevacizumab is a humanized monoclonal antibody that blocks:', '["VEGF signaling","HER2 signaling","EGFR signaling","BCR-ABL kinase","BRAF kinase"]'::jsonb, 'VEGF signaling', 'Bevacizumab neutralizes VEGF, inhibiting tumor angiogenesis. HER2 (trastuzumab), EGFR (cetuximab), BCR-ABL (imatinib), and BRAF (vemurafenib) have different inhibitors.'),
('4b242bc5-3ecc-5514-9d88-2955496a552e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A tumor that is vimentin-positive and cytokeratin-negative on immunohistochemistry is most consistent with:', '["Mesenchymal (sarcomatous) origin","Epithelial origin","Lymphoid origin","Melanocytic origin","Germ-cell origin"]'::jsonb, 'Mesenchymal (sarcomatous) origin', 'Vimentin is the intermediate filament of mesenchymal cells while cytokeratin marks epithelia; a CK-negative, vimentin-positive tumor is sarcomatous. Lymphomas instead express LCA (CD45).'),
('66fa1f0b-58cb-5a2c-a597-9d07984ada85'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Positive immunohistochemical staining for cytokeratin supports a diagnosis of:', '["Carcinoma (epithelial origin)","Sarcoma accompanied by associated clinical symptoms","Lymphoma mediated by specific receptor activation","Melanoma without affecting the primary tissue pathway","Glioma leading to subsequent cellular adaptation"]'::jsonb, 'Carcinoma (epithelial origin)', 'Cytokeratins are the intermediate filaments of epithelial cells, so positivity indicates epithelial (carcinomatous) differentiation. Sarcomas and lymphomas are typically negative.'),
('4e98070c-cac2-5e09-b40a-d92f5a15a770'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Positivity for LCA (CD45) on immunostaining establishes the tumor as:', '["Hematolymphoid in origin","Epithelial in origin","Melanocytic in origin","Neural in origin","Endothelial in origin"]'::jsonb, 'Hematolymphoid in origin', 'CD45 (leukocyte common antigen) is expressed on all nucleated hematopoietic cells; LCA positivity identifies lymphomas and leukemias and is routinely used to exclude carcinoma.'),
('160c2fb8-f63f-52a1-a7bf-aa2eae3e76b9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which immunostain is the most sensitive marker for melanoma?', '["S-100","Cytokeratin","CD20","Chromogranin","Vimentin"]'::jsonb, 'S-100', 'S-100 is the most sensitive marker of melanoma (though not specific, also staining nerve sheath and neural tumors); HMB-45 and Melan-A/MART-1 are more specific markers.'),
('37597c7c-6fbe-5584-91cf-c107192b007b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Expression of CD20 identifies a lymphoma cell as:', '["B-cell lineage","T-cell lineage","A Reed-Sternberg cell","A natural killer cell","A tissue macrophage"]'::jsonb, 'B-cell lineage', 'CD20 is a pan-B-cell antigen, so CD20 positivity confirms B-cell derivation and enables rituximab therapy. T cells express CD3 and NK cells CD56.'),
('c0c114c6-a151-5c18-b09a-7a02a43e4b73'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Terminal deoxynucleotidyl transferase (TdT) staining is characteristic of:', '["Lymphoblasts of acute lymphoblastic leukemia","Mature B lymphocytes accompanied by associated clinical symptoms","Plasma cells mediated by specific receptor activation","Reed-Sternberg cells without affecting the primary tissue pathway","Mature granulocytes leading to subsequent cellular adaptation"]'::jsonb, 'Lymphoblasts of acute lymphoblastic leukemia', 'TdT is expressed in immature B and T precursor cells and therefore marks lymphoblasts of ALL. Mature lymphoid and myeloid cells are TdT-negative.'),
('ea8c7e45-3ce1-594d-a42d-eb5449eb107e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The Ki-67 (MIB-1) labeling index in a tumor measures its:', '["Growth fraction (proliferation rate)","Chromosomal ploidy","Hormone-receptor status","Metastatic burden","Degree of differentiation"]'::jsonb, 'Growth fraction (proliferation rate)', 'Ki-67 is expressed in all cycling phases of the cell cycle but not in resting G0 cells, so its index reflects the proliferating (growth) fraction. It correlates with tumor aggressiveness.'),
('aa0443fa-e7a1-53ad-a987-04df6fe6390f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Estrogen-receptor positivity in breast carcinoma predicts response to:', '["Hormonal therapy such as tamoxifen","Trastuzumab","Imatinib","Alkylating chemotherapy","Radiotherapy alone"]'::jsonb, 'Hormonal therapy such as tamoxifen', 'ER-positive breast cancers respond to tamoxifen and aromatase inhibitors. Trastuzumab is for HER2-positive and imatinib is for BCR-ABL/KIT-driven tumors.'),
('55c3e312-e4e3-5645-b671-ee7598e9d41f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Carcinoembryonic antigen (CEA) is most useful for monitoring:', '["Colorectal carcinoma","Prostate carcinoma","Ovarian carcinoma","Thyroid carcinoma","Hepatocellular carcinoma"]'::jsonb, 'Colorectal carcinoma', 'CEA is an oncofetal antigen elevated in colorectal carcinoma and used to follow treatment response and detect recurrence. It is not specific enough for cancer screening.'),
('8e06af05-431c-5bc3-a843-dec85eb345b7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Elevated serum alpha-fetoprotein is most characteristic of:', '["Hepatocellular carcinoma and yolk-sac tumor","Colorectal carcinoma accompanied by associated clinical symptoms","Malignant melanoma mediated by specific receptor activation","Multiple myeloma without affecting the primary tissue pathway","Follicular lymphoma leading to subsequent cellular adaptation"]'::jsonb, 'Hepatocellular carcinoma and yolk-sac tumor', 'AFP is produced by hepatocellular carcinoma and yolk-sac (endodermal sinus) germ-cell tumors. CEA marks colorectal and CA-125 ovarian cancer instead.'),
('672a218b-1300-58dc-b785-ff33c3c93d6f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Prostate-specific antigen is a tumor marker used to:', '["Screen for and monitor prostate carcinoma","Diagnose germ-cell tumors","Monitor colorectal cancer","Detect hepatocellular carcinoma","Assess medullary thyroid cancer"]'::jsonb, 'Screen for and monitor prostate carcinoma', 'PSA is secreted by prostatic epithelium; elevated levels are used in screening, risk assessment, and monitoring of prostate cancer. Its specificity is limited by benign prostatic hyperplasia.'),
('ace3ac4d-9946-59eb-92ce-bb0ad6217433'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'CA-125 is a serum marker most associated with:', '["Ovarian carcinoma","Pancreatic carcinoma","Gastric carcinoma","Bladder carcinoma","Seminoma"]'::jsonb, 'Ovarian carcinoma', 'CA-125, a high-molecular-weight glycoprotein, is the classical serum marker for monitoring epithelial ovarian carcinoma, though it can be elevated in benign pelvic conditions.'),
('2d002a01-d420-5c1d-ad88-847ca872197f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'CA 19-9 is used mainly for monitoring:', '["Pancreatic and biliary carcinoma","Breast carcinoma","Prostate carcinoma","Lung adenocarcinoma","Melanoma"]'::jsonb, 'Pancreatic and biliary carcinoma', 'CA 19-9 is a sialylated Lewis blood-group antigen elevated in pancreatic and biliary cancers, useful for monitoring response and recurrence. It is not a marker of breast, lung, or prostate cancer.'),
('f3f0fb35-b1ce-5b2a-ad43-2348fe229b67'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Elevated serum calcitonin is a sensitive marker of:', '["Medullary thyroid carcinoma","Papillary thyroid carcinoma","Follicular thyroid carcinoma","Anaplastic thyroid carcinoma","Parathyroid adenoma"]'::jsonb, 'Medullary thyroid carcinoma', 'Calcitonin is secreted by the parafollicular C cells that give rise to medullary thyroid carcinoma, making serum calcitonin a sensitive tumor marker for this neoplasm.'),
('5121c3eb-7dbe-5f01-b415-4fff7fe2d7a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Elevation of serum alkaline phosphatase accompanies:', '["Osteosarcoma and osteoblastic bone metastases","Prostate-specific surveillance only","Pancreatic endocrine tumors","Neuroendocrine tumors of the gut","Chronic lymphocytic leukemia"]'::jsonb, 'Osteosarcoma and osteoblastic bone metastases', 'Alkaline phosphatase is produced by osteoblasts; high levels are seen in osteosarcoma and osteoblastic metastases such as those of prostate carcinoma. The listed other tumors do not raise it.'),
('b610eca3-ec5d-502a-8917-82291aa8d497'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Beta-hCG is secreted at high levels by:', '["Choriocarcinoma and other germ-cell tumors","Adenocarcinoma of the colon","Ductal carcinoma of the breast","Small cell lung carcinoma","Follicular lymphoma"]'::jsonb, 'Choriocarcinoma and other germ-cell tumors', 'Syncytiotrophoblast produces beta-hCG, so choriocarcinomas and germ-cell tumors with trophoblastic elements secrete large amounts. hCG also causes gynecomastia in men with such tumors.'),
('6fd9ef74-0ee0-5270-8c6a-06a2dc295241'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Neuron-specific enolase (NSE) is elevated in:', '["Small cell lung carcinoma","Squamous cell lung carcinoma","Pleural mesothelioma","Appendiceal carcinoid tumor","Papillary thyroid carcinoma"]'::jsonb, 'Small cell lung carcinoma', 'NSE, a glycolytic enzyme of neuroendocrine cells, is a serum and tissue marker elevated in small cell lung carcinoma and other neuroendocrine tumors.'),
('0a1d1b67-7d82-5c2f-ad24-febeb005bc14'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Tumor markers are most valuable clinically for:', '["Monitoring therapy response and detecting recurrence","Primary population-wide screening","Establishing a tissue diagnosis","Determining histologic grade","Replacing the need for biopsy"]'::jsonb, 'Monitoring therapy response and detecting recurrence', 'Because most markers lack specificity, their main role is serial measurement to follow response and pick up recurrence. Diagnosis always requires tissue (histology and radiology).'),
('bd8cc427-8cfd-51ee-8d24-05447e856431'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A major limitation of most tumor markers is:', '["Elevation in benign conditions and lack of specificity","Absence of any measurable serum test","Inability to detect circulating proteins","Poor correlation with tumor burden","Inability to be measured by immunoassay"]'::jsonb, 'Elevation in benign conditions and lack of specificity', 'Most tumor markers are also elevated in benign, inflammatory, or physiologic states, so they cannot diagnose cancer in isolation and are used mainly for monitoring.'),
('95ec4958-a177-5c18-81da-889def1b7e7a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A tumor marker is best defined as:', '["A biomolecule detectable in tissues or body fluids that reflects the presence or behavior of a tumor","A hereditary mutation present in every body cell accompanied by associated clinical symptoms","A protein elaborated only by benign tumors mediated by specific receptor activation","A marker of physiologic apoptosis without affecting the primary tissue pathway","An autoantibody causing paraneoplastic disease leading to subsequent cellular adaptation"]'::jsonb, 'A biomolecule detectable in tissues or body fluids that reflects the presence or behavior of a tumor', 'Tumor markers are gene products of tumors or host responses measurable in blood or tissue that indicate tumor presence, type, or activity. They are neither purely hereditary nor limited to benign lesions.'),
('985c2bc4-2298-5ce6-af7d-34124df31d63'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Histologic tumor grading is assigned on the basis of:', '["Degree of differentiation and mitotic activity","Extent of lymph node spread","Presence of distant metastasis","Patient age and sex","Tumor size on imaging"]'::jsonb, 'Degree of differentiation and mitotic activity', 'Grade reflects how closely tumor cells resemble the tissue of origin, assessed microscopically with mitotic activity and pleomorphism. Spread and size belong to staging, not grading.'),
('3c13a591-7382-558c-aaeb-c72768cc66eb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Tumor staging is based primarily on the:', '["Anatomic extent of disease according to TNM criteria","Degree of cytologic differentiation","Number of mitoses per high-power field","Presence of tumor necrosis","Growth fraction by Ki-67"]'::jsonb, 'Anatomic extent of disease according to TNM criteria', 'Staging quantifies the anatomic spread of a tumor including primary tumor size (T), nodal involvement (N), and metastasis (M). Histologic features determine grade, not stage.'),
('7bcff04c-899a-57a0-acbc-6275e70acc94'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which statement comparing grade and stage is correct?', '["Stage reflects extent of spread and is generally the stronger predictor of outcome","Grade measures extent of spread accompanied by associated clinical symptoms","Grade and stage are mutually exclusive mediated by specific receptor activation","Stage is determined solely by microscopy without affecting the primary tissue pathway","Grade never changes during disease leading to subsequent cellular adaptation"]'::jsonb, 'Stage reflects extent of spread and is generally the stronger predictor of outcome', 'Stage describes how far a tumor has spread and, for most cancers, is the best predictor of prognosis. Grade reflects microscopic differentiation and can change with progression.'),
('c0fe8c69-d0a6-5a24-b0b6-181fd571bf30'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In the TNM system, the notation ''M0'' indicates:', '["No detectable distant metastasis","Distant metastasis present","Extensive nodal involvement","Invasion of adjacent organs","An in situ lesion"]'::jsonb, 'No detectable distant metastasis', 'The M component records metastasis: M0 means no distant spread while M1 means distant metastases are present. T and N denote primary tumor and nodes separately.'),
('e39ad39c-d4f0-5033-ab84-7c8e04150669'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Gleason scoring is the grading system used for:', '["Prostate carcinoma","Breast carcinoma","Colorectal carcinoma","Renal cell carcinoma","Ovarian carcinoma"]'::jsonb, 'Prostate carcinoma', 'The Gleason score grades prostate cancer by architectural pattern (5-10), correlating strongly with prognosis. The other tumors use their own grading systems.'),
('3470de1a-f546-5a36-b284-c8ea18322e60'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The Dukes classification is employed for:', '["Colorectal carcinoma","Gastric carcinoma","Lung carcinoma","Prostate carcinoma","Cervical carcinoma"]'::jsonb, 'Colorectal carcinoma', 'Dukes staging describes depth of bowel penetration and nodal spread of colorectal carcinoma and historically correlated with prognosis; modern staging also uses TNM.'),
('bcc2801a-d700-5a02-9908-2142fbf3458b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Dysplasia is best defined as:', '["A disordered, preneoplastic proliferation with cytologic atypia","A fully differentiated benign tumor","Invasion of the basement membrane","Metastatic spread of a tumor","A proliferation identical to carcinoma"]'::jsonb, 'A disordered, preneoplastic proliferation with cytologic atypia', 'Dysplasia is a proliferation with loss of uniformity, abnormal maturation, and cellular atypia that falls short of carcinoma and is generally reversible if the stimulus is removed.'),
('1732f4ca-19ab-52bd-81d7-14977b349457'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Carcinoma in situ is characterized by:', '["Full-thickness dysplasia without invasion of the basement membrane","Invasion into the submucosa accompanied by associated clinical symptoms","Lymph node metastasis mediated by specific receptor activation","Well-differentiated benign proliferation without affecting the primary tissue pathway","Reversible metaplasia leading to subsequent cellular adaptation"]'::jsonb, 'Full-thickness dysplasia without invasion of the basement membrane', 'Carcinoma in situ is an intraepithelial neoplasm in which atypical cells occupy the full thickness of the epithelium but have not penetrated the basement membrane, so it is preinvasive.'),
('60d95b4e-7a80-5d5b-9f0e-de29334bcdb4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Cervical intraepithelial neoplasia grade III (CIN III) is equivalent to:', '["Carcinoma in situ","Mild dysplasia","Superficially invasive carcinoma","Lymph node metastasis","Chronic cervicitis"]'::jsonb, 'Carcinoma in situ', 'CIN III denotes full-thickness neoplastic involvement of the cervical epithelium without stromal invasion, i.e., carcinoma in situ. CIN I and II represent lesser degrees of dysplasia.'),
('effdd12c-7ea5-5c71-bf0c-2db47715a15d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which statement about dysplasia is correct?', '["It is generally reversible if the inciting stimulus is removed, but may progress to carcinoma","It is always irreversible and inevitably malignant accompanied by associated clinical symptoms","It never shows cytologic atypia mediated by specific receptor activation","It is identical to invasive carcinoma without affecting the primary tissue pathway","It occurs only in the elderly leading to subsequent cellular adaptation"]'::jsonb, 'It is generally reversible if the inciting stimulus is removed, but may progress to carcinoma', 'Dysplasia occupies a middle ground: removal of the stimulus often permits regression, but persistent dysplasia can progress to carcinoma in situ and invasive cancer.'),
('2792bbd4-5142-53f2-bbd4-9486a138dc1c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In medical practice, Type II hypersensitivity is:', '["Antibody-mediated cytotoxic (IgG/IgG against cell surface antigens)","Immune complex-mediated accompanied by associated clinical symptoms","IgE-mediated mediated by specific receptor activation","T cell-mediated without affecting the primary tissue pathway","None of the above leading to subsequent cellular adaptation"]'::jsonb, 'Antibody-mediated cytotoxic (IgG/IgG against cell surface antigens)', 'IgG/IgM against cell surface or matrix antigens.'),
('b1b0c3fe-0b0d-5d6b-b49f-98f3d7a20913'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Intestinal metaplasia in Barrett esophagus is clinically significant because it:', '["Predisposes to adenocarcinoma of the esophagus","Predicts a benign lymphoproliferative disorder","Guarantees a benign outcome","Causes achalasia","Increases gastric acid secretion"]'::jsonb, 'Predisposes to adenocarcinoma of the esophagus', 'In Barrett esophagus the squamous esophageal lining is replaced by intestinal-type columnar epithelium; dysplastic progression in this metaplastic mucosa gives rise to esophageal adenocarcinoma.'),
('33921bb8-1e8d-53f3-be7e-7a30fedfdcff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The usual sequence of progression in cervical carcinogenesis is:', '["Metaplasia, then dysplasia, then carcinoma in situ, then invasive carcinoma","Dysplasia, then metaplasia, then invasive carcinoma, then carcinoma in situ","Carcinoma in situ, then metaplasia, then dysplasia","Invasive carcinoma, then carcinoma in situ, then dysplasia","Hyperplasia, then anaplasia, then metaplasia"]'::jsonb, 'Metaplasia, then dysplasia, then carcinoma in situ, then invasive carcinoma', 'High-risk HPV drives cervical progression stepwise from immature metaplasia through increasing dysplasia (CIN) to carcinoma in situ and finally invasive carcinoma.'),
('ecc5125a-a9ab-5758-a5d8-0e584e7c82d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Carcinomas most characteristically disseminate by:', '["Lymphatic spread to regional nodes","Hematogenous spread to the skeleton","Transcoelomic spread to serosal surfaces","Intraepithelial spread only","Perineural spread only"]'::jsonb, 'Lymphatic spread to regional nodes', 'Carcinomas usually metastasize first by lymphatics to the tumor-draining nodes, whereas sarcomas more often spread hematogenously, classically to the lungs.'),
('d27e11c4-e3ec-595e-9161-0e74251fd452'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Sarcomas preferentially spread by the:', '["Hematogenous route, often to the lungs","Lymphatic route to regional nodes","Transcoelomic route","Intraepithelial route","Perineural route"]'::jsonb, 'Hematogenous route, often to the lungs', 'Sarcomas and other connective-tissue tumors enter the bloodstream early and hematogenous spread to the lungs is their classic pattern. Carcinomas instead favor lymphatics.'),
('6c929c63-6696-5911-8bca-7c082737cc32'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The sentinel lymph node is defined as:', '["The first regional node that drains the primary tumor","The largest node in the region","The node closest to the heart","Any node containing tumor cells","The node showing sinus histiocytosis"]'::jsonb, 'The first regional node that drains the primary tumor', 'Tumor cells travel to the sentinel node first, so its biopsy accurately predicts regional nodal status in breast cancer and melanoma, sparing unnecessary node dissection.'),
('ca954949-f6eb-56c2-8cd1-9a750b7daf8a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Transcoelomic spread (implantation on peritoneal surfaces) is most characteristic of:', '["Ovarian carcinoma","Squamous carcinoma of the skin","Medulloblastoma","Osteosarcoma","Papillary thyroid carcinoma"]'::jsonb, 'Ovarian carcinoma', 'Ovarian carcinoma exfoliates cells onto the peritoneal cavity, seeding the peritoneum and producing ascites. The other tumors do not spread by this route.'),
('a9b6fa57-0377-5bc9-91d1-8e655657b354'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Hematogenous spread of colorectal carcinoma occurs most often to the:', '["Liver (via the portal vein)","Brain accompanied by associated clinical symptoms","Bone mediated by specific receptor activation","Spleen without affecting the primary tissue pathway","Mediastinal nodes leading to subsequent cellular adaptation"]'::jsonb, 'Liver (via the portal vein)', 'The colon''s venous drainage enters the portal circulation, so colorectal carcinoma metastasizes to the liver first. The other sites are later or less frequent destinations.'),
('9be28d98-5b32-5d93-983e-53c70d60975c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which carcinoma classically produces osteoblastic (sclerotic) bone metastases?', '["Prostate carcinoma","Renal cell carcinoma","Thyroid carcinoma","Hepatocellular carcinoma","Choriocarcinoma"]'::jsonb, 'Prostate carcinoma', 'Prostate carcinoma characteristically gives sclerotic, osteoblastic bone lesions (hence elevated alkaline phosphatase). Renal, thyroid, and hepatocellular carcinoma produce lytic lesions.'),
('52dabab3-a5a3-5377-9bc0-d74caa999962'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which tumor characteristically produces purely osteolytic bone metastases?', '["Renal cell and thyroid carcinoma","Prostate carcinoma","Medulloblastoma","Typical carcinoid of the appendix","Follicular lymphoma"]'::jsonb, 'Renal cell and thyroid carcinoma', 'Renal cell and thyroid carcinomas classically produce lytic bone metastases that destroy bone without new bone formation. Prostate carcinoma is the prototype of blastic metastases.'),
('b6985ef5-2711-5edc-b468-a333f350664e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Malignant melanoma has a striking tendency to metastasize to the:', '["Brain","Spleen","Appendix","Skin of the palms only","Thyroid gland"]'::jsonb, 'Brain', 'Melanoma is notorious for early hematogenous brain metastasis and can spread almost anywhere. This propensity dictates imaging surveillance in advanced disease.'),
('f1d2dbe2-ec92-52af-b945-118278cd3387'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which tumor undergoes early and massive hematogenous dissemination to the lungs?', '["Choriocarcinoma","Basal cell carcinoma","Follicular lymphoma","Carcinoid of the appendix","Dermatofibroma"]'::jsonb, 'Choriocarcinoma', 'Choriocarcinoma invades vascular sinuses aggressively and produces early, large pulmonary metastases despite its trophoblastic origin. Basal cell carcinoma and dermatofibroma almost never metastasize.'),
('f5d02fa1-5354-520a-b50b-bb571203c1e1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Enlargement of the left supraclavicular (Virchow) lymph node points to metastasis from:', '["Gastric or abdominal tumors","Intrinsic brain tumors","Skin melanoma only","Parotid carcinoma","Breast cancer only"]'::jsonb, 'Gastric or abdominal tumors', 'The Virchow node drains lymph from the thorax and abdomen via the thoracic duct, so its enlargement classically signals metastasis from gastric or other abdominal carcinoma.'),
('c6273585-7e59-599e-ad4f-fd7ed3a1e331'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A Krukenberg tumor is a metastatic ovarian deposit from:', '["Gastric signet-ring cell carcinoma","Breast ductal carcinoma","Colonic adenocarcinoma","Lung adenocarcinoma","Pancreatic ductal carcinoma"]'::jsonb, 'Gastric signet-ring cell carcinoma', 'Krukenberg tumors are bilateral ovarian metastases containing signet-ring cells, classically from diffuse gastric carcinoma and spread transcoelomically or via lymphatics.'),
('3901e846-0b18-56a1-817a-8adaa1943fec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Metastatic brain tumors in adults most often arise from a primary in the:', '["Lung and breast","Prostate and testis","Stomach and colon","Thyroid and parathyroid","Bone marrow"]'::jsonb, 'Lung and breast', 'Lung and breast carcinoma are the most common sources of brain metastases in adults; metastatic brain lesions actually outnumber primary brain tumors.'),
('e88d785e-0166-5a4b-8ab9-206d32c2349d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Osteosarcoma characteristically arises in the:', '["Metaphysis of the distal femur or proximal tibia","Diaphysis of the radius accompanied by associated clinical symptoms","Epiphysis of the humerus mediated by specific receptor activation","Vertebral body without affecting the primary tissue pathway","Flat bones of the skull leading to subsequent cellular adaptation"]'::jsonb, 'Metaphysis of the distal femur or proximal tibia', 'Osteosarcoma arises at the metaphysis around the knee, where longitudinal bone growth is greatest, typically in adolescents. This is a classic age-site relationship in bone tumors.'),
('00a4927a-8f9a-5165-84e3-d051b8a8750c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common malignancy of childhood overall is:', '["Acute lymphoblastic leukemia","Neuroblastoma","Wilms tumor","Osteosarcoma","Hodgkin lymphoma"]'::jsonb, 'Acute lymphoblastic leukemia', 'ALL is the most common pediatric malignancy, with its peak at 2-5 years of age. Neuroblastoma is the most common extracranial solid tumor and Wilms the most common renal tumor of children.'),
('f47bfdbc-4e5e-5d8a-9981-814b50960368'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common extracranial solid tumor of childhood is:', '["Neuroblastoma","Wilms tumor","Rhabdomyosarcoma","Retinoblastoma","Osteosarcoma"]'::jsonb, 'Neuroblastoma', 'Neuroblastoma of the adrenal medulla or sympathetic chain is the most common extracranial solid tumor of childhood. Wilms tumor is the most common renal tumor and retinoblastoma the most common intraocular one.'),
('70adbcdb-1a1f-5be3-8029-6e231f613469'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common acute leukemia of adults is:', '["Acute myeloid leukemia","Acute lymphoblastic leukemia","Chronic myelogenous leukemia","Hairy cell leukemia","Prolymphocytic leukemia"]'::jsonb, 'Acute myeloid leukemia', 'AML predominates in adults and accounts for the majority of acute leukemias in that age group, whereas ALL dominates in children. The chronic leukemias are separate entities.'),
('4f29e3c0-cacb-5c1b-b542-99d22eb149c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common leukemia in adults in Western countries is:', '["Chronic lymphocytic leukemia","Acute myeloid leukemia","Chronic myeloid leukemia","Acute lymphoblastic leukemia","Multiple myeloma"]'::jsonb, 'Chronic lymphocytic leukemia', 'CLL is the most common leukemia of adults in the West, usually occurring after age 60 and following an indolent course. AML is the most common acute leukemia of adults.'),
('e84f66e7-c406-5f96-b33e-bf1658bf3a24'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Reed-Sternberg cells are the diagnostic hallmark of:', '["Hodgkin lymphoma","Burkitt lymphoma","Follicular lymphoma","Mantle cell lymphoma","Multiple myeloma"]'::jsonb, 'Hodgkin lymphoma', 'Reed-Sternberg cells are large binucleate or multinucleate cells with prominent eosinophilic nucleoli (owl-eye appearance), required for the diagnosis of Hodgkin lymphoma.'),
('6c65bcae-1c4e-5a5e-bd6a-3f46b442688c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common histologic subtype of Hodgkin lymphoma is:', '["Nodular sclerosis","Lymphocyte-depleted","Mixed cellularity","Lymphocyte-rich classic","Nodular lymphocyte-predominant"]'::jsonb, 'Nodular sclerosis', 'Nodular sclerosis is the most frequent Hodgkin subtype in young adults, classically affecting cervical/mediastinal nodes in women and showing lacunar Reed-Sternberg variants.'),
('6c99c73d-1327-5b90-91ba-5ef386dbbfae'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common aggressive non-Hodgkin lymphoma in adults is:', '["Diffuse large B-cell lymphoma","Follicular lymphoma","Burkitt lymphoma","Marginal zone lymphoma","Small lymphocytic lymphoma"]'::jsonb, 'Diffuse large B-cell lymphoma', 'DLBCL is the most common aggressive non-Hodgkin lymphoma, presenting as rapidly enlarging nodal masses in older adults. Follicular and small lymphocytic lymphoma are indolent.'),
('1f243c17-3001-505d-a73c-c909de6b1a59'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Mycosis fungoides is a malignant neoplasm of:', '["Cutaneous CD4-positive T lymphocytes","Cutaneous B lymphocytes","Epidermal Langerhans cells","Dermal fibroblasts","Melanocytes"]'::jsonb, 'Cutaneous CD4-positive T lymphocytes', 'Mycosis fungoides is a cutaneous T-cell lymphoma of neoplastic CD4-positive helper T cells producing plaque and tumor skin lesions; leukemic involvement is the Sezary syndrome.'),
('57d6c1cd-88b6-5de6-8997-ae781d66d413'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Gastric MALT lymphoma characteristically regresses after:', '["Eradication of Helicobacter pylori","Resection of the adjacent stomach only","Chemotherapy for gastric ulcers","Radiotherapy to the jejunum","Hormonal therapy"]'::jsonb, 'Eradication of Helicobacter pylori', 'Most gastric MALT lymphomas are driven by chronic H. pylori antigenic stimulation; antibiotic eradication of the organism causes regression of the lymphoma in most cases.'),
('e069a9ea-89de-5608-9cf9-2768d195f9ed'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Multiple myeloma involves malignant proliferation of:', '["Plasma cells","Mature B cells","T lymphocytes","Monocytes","Erythroid precursors"]'::jsonb, 'Plasma cells', 'Myeloma is a tumor of antibody-secreting plasma cells, producing a monoclonal immunoglobulin (M protein), lytic bone lesions, renal damage, and marrow failure.'),
('2527c3b7-8ad6-587d-8da0-054d10c8651e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The monoclonal immunoglobulin spike of multiple myeloma is detected as:', '["A sharp band (M-spike) on serum protein electrophoresis","Increased polyclonal IgM","An elevated C-reactive protein","High serum alkaline phosphatase","Low serum calcium"]'::jsonb, 'A sharp band (M-spike) on serum protein electrophoresis', 'Myeloma plasma cells secrete a single homogeneous immunoglobulin or light chain, which appears as a narrow, tall M-spike on serum protein electrophoresis with suppression of other immunoglobulins.'),
('0e4a3ba7-0700-5754-b3e8-f7494cf0ca14'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Bence Jones protein in the urine of a myeloma patient consists of:', '["Monoclonal free immunoglobulin light chains","Whole monoclonal IgG molecules","Albumin and prealbumin","Beta-2 microglobulin only","Light and heavy chain heterodimers"]'::jsonb, 'Monoclonal free immunoglobulin light chains', 'Bence Jones protein is free monoclonal light chains (kappa or lambda) filtered through the kidney; their detection and quantification are central to myeloma monitoring.'),
('f2c67986-cbbe-5801-a755-7ed7c05f1fdf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In males, the most commonly diagnosed noncutaneous cancer is:', '["Prostate carcinoma","Lung carcinoma","Colorectal carcinoma","Bladder carcinoma","Gastric carcinoma"]'::jsonb, 'Prostate carcinoma', 'Prostate carcinoma is the most common non-skin cancer diagnosed in men, although lung cancer causes more male cancer deaths. This is standard epidemiologic teaching.'),
('49bc9b19-7b3e-503f-850a-8ea092bda96f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common noncutaneous cancer in women is:', '["Breast carcinoma","Lung carcinoma","Cervical carcinoma","Colorectal carcinoma","Ovarian carcinoma"]'::jsonb, 'Breast carcinoma', 'Breast carcinoma is the most common non-skin malignancy in women worldwide, and cervical or lung cancer may surpass it only in high-risk regions.'),
('4fc0cbc9-1654-523d-bdd9-8d61053296d8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The leading cause of cancer-related death worldwide is:', '["Lung carcinoma","Breast carcinoma","Colorectal carcinoma","Prostate carcinoma","Gastric carcinoma"]'::jsonb, 'Lung carcinoma', 'Lung cancer is the leading cause of cancer death in men and women globally because of its poor survival and the widespread prevalence of smoking.'),
('d6b0250f-dca1-5684-8ab1-5b768b36582f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common malignant neoplasm of the skin is:', '["Basal cell carcinoma","Squamous cell carcinoma","Malignant melanoma","Merkel cell carcinoma","Kaposi sarcoma"]'::jsonb, 'Basal cell carcinoma', 'Basal cell carcinoma is the most common skin cancer and the most common cancer overall, driven largely by cumulative sun exposure. Melanoma is the most dangerous.'),
('81b22d35-57d2-5ebc-8ddd-26efa2c535c6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Basal cell carcinoma is best characterized as:', '["Locally invasive but very rarely metastatic","Highly metastatic at presentation","A tumor always fatal if untreated","The leading cause of metastatic brain disease","An epidermal neuroendocrine neoplasm"]'::jsonb, 'Locally invasive but very rarely metastatic', 'BCC grows and invades locally, causing tissue destruction, but metastasizes only exceptionally rarely. It is thus ''malignant'' by invasion yet almost never spreads.'),
('21c089f5-10b5-5cb3-a05f-6fd7331fb942'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The single most important determinant of prognosis in cutaneous melanoma is:', '["Breslow thickness (depth of invasion)","Patient sex accompanied by associated clinical symptoms","Tumor color mediated by specific receptor activation","Presence of itching without affecting the primary tissue pathway","Age at diagnosis leading to subsequent cellular adaptation"]'::jsonb, 'Breslow thickness (depth of invasion)', 'Breslow thickness, measured vertically in millimeters from the granular layer, best predicts melanoma outcome and guides sentinel-node staging. Color and itching carry no prognostic weight.'),
('9d4a50f5-faff-5512-9296-cae3b6114800'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common histologic type of breast carcinoma is:', '["Infiltrating ductal carcinoma (no special type)","Infiltrating lobular carcinoma","Medullary carcinoma","Mucinous carcinoma","Papillary carcinoma"]'::jsonb, 'Infiltrating ductal carcinoma (no special type)', 'Invasive ductal carcinoma NST accounts for the majority of breast cancers. Lobular and the special types (medullary, mucinous, papillary) are much less frequent.'),
('ba0f3042-2d8d-58fa-ad2a-d00e8128c140'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Loss of E-cadherin expression is a characteristic finding in:', '["Invasive lobular carcinoma of the breast","Infiltrating ductal carcinoma","Medullary carcinoma","Inflammatory carcinoma","Paget disease of the nipple"]'::jsonb, 'Invasive lobular carcinoma of the breast', 'Loss of E-cadherin-mediated cell adhesion underlies the single-file, discobesive growth pattern of invasive lobular carcinoma. This molecular distinction also separates lobular from ductal carcinoma.'),
('f2be0d96-638f-57eb-8866-579bebffec75'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Paget disease of the nipple is caused by:', '["Intraepidermal spread of malignant cells from an underlying ductal carcinoma","Metastasis from the contralateral ovary accompanied by associated clinical symptoms","Direct inoculation by a papovavirus mediated by specific receptor activation","Proliferation of melanocytes without affecting the primary tissue pathway","Sebaceous gland hyperplasia leading to subsequent cellular adaptation"]'::jsonb, 'Intraepidermal spread of malignant cells from an underlying ductal carcinoma', 'Paget cells are large clear malignant glandular cells that extend within the nipple epidermis from an underlying ductal carcinoma in situ or invasive cancer, producing eczematous change.'),
('34cb614a-3825-532c-b9db-efeb26d559f9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Despite a poorly differentiated histologic appearance, medullary carcinoma of the breast is associated with:', '["A relatively favorable prognosis and prominent lymphocytic infiltrate","Rapidly fatal outcome in every case accompanied by associated clinical symptoms","Absence of any inflammatory reaction mediated by specific receptor activation","Universal HER2 amplification without affecting the primary tissue pathway","Origin from myoepithelial cells leading to subsequent cellular adaptation"]'::jsonb, 'A relatively favorable prognosis and prominent lymphocytic infiltrate', 'Medullary carcinoma shows syncytial sheets of anaplastic cells with a heavy lymphoplasmacytic infiltrate yet carries a better prognosis than ordinary ductal carcinoma, likely reflecting immune response to the tumor.'),
('fceb95cb-4b06-5ae3-a808-cec887c0edda'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Prolonged unopposed estrogen exposure predisposes to:', '["Endometrioid adenocarcinoma of the endometrium","Squamous carcinoma of the cervix","Choriocarcinoma of the uterus","Ovarian germ cell tumor","Vulvar melanoma"]'::jsonb, 'Endometrioid adenocarcinoma of the endometrium', 'Chronic estrogen stimulation of the endometrium, without progesterone opposition, drives hyperplasia and then endometrioid adenocarcinoma. The other tumors are not estrogen-driven in this way.'),
('06435665-0d27-554b-85cd-c908331dbb41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common histologic type of cervical cancer is:', '["Squamous cell carcinoma","Adenocarcinoma","Small cell carcinoma","Carcinoid tumor","Clear cell carcinoma"]'::jsonb, 'Squamous cell carcinoma', 'About 70-80% of cervical cancers are squamous cell carcinomas arising from high-risk HPV infection at the transformation zone. Adenocarcinoma of the endocervix is the main minority type.'),
('859b7b0c-412b-5e0f-a5ab-11150590e5f2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common malignant ovarian neoplasm is:', '["High-grade serous carcinoma","Mature cystic teratoma","Serous cystadenoma","Thecoma","Brenner tumor"]'::jsonb, 'High-grade serous carcinoma', 'High-grade serous carcinoma is the most common malignant ovarian tumor. Mature teratoma and serous cystadenoma are benign, and thecoma and Brenner tumor are uncommon.'),
('3be05644-7317-5a51-8dcf-89f457c0cee4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Undescended testis (cryptorchidism) is a well-established risk factor for:', '["Testicular germ cell tumors","Prostate adenocarcinoma","Bladder carcinoma","Penile carcinoma","Renal cell carcinoma"]'::jsonb, 'Testicular germ cell tumors', 'Cryptorchidism, even after orchidopexy, increases the risk of seminoma and other germ cell tumors several-fold, particularly if the testis was intra-abdominal.'),
('956aae53-8971-5be6-9124-961583a2c964'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Placental alkaline phosphatase (PLAP) is a serum and tissue marker for:', '["Seminoma and other germ cell tumors","Choriocarcinoma only","Mature teratoma only","Acute leukemia","Follicular lymphoma"]'::jsonb, 'Seminoma and other germ cell tumors', 'PLAP is expressed by seminoma and other germ cell tumors and was historically used as a tissue marker; most seminomas also produce the soluble isoform detectable in serum.'),
('d200042a-b3b8-5d7d-ae55-f7b890fb4d02'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Elevated serum alpha-fetoprotein in a testicular germ cell tumor specifically indicates:', '["The presence of yolk-sac tumor (or embryonal carcinoma)","Pure seminoma accompanied by associated clinical symptoms","Mature teratoma mediated by specific receptor activation","Sertoli-cell tumor without affecting the primary tissue pathway","Leydig-cell tumor leading to subsequent cellular adaptation"]'::jsonb, 'The presence of yolk-sac tumor (or embryonal carcinoma)', 'AFP is produced by yolk-sac tumor and to a lesser degree embryonal carcinoma elements, so a raised AFP rules out a pure seminoma, which does not synthesize AFP.'),
('e5c6034a-3daa-547a-8ea1-d2f096d63624'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Gynecomastia in a man with a testicular germ cell tumor suggests secretion of:', '["Beta-hCG by a choriocarcinoma component","Alpha-fetoprotein accompanied by associated clinical symptoms","Lactate dehydrogenase mediated by specific receptor activation","PLAP without affecting the primary tissue pathway","Inhibin leading to subsequent cellular adaptation"]'::jsonb, 'Beta-hCG by a choriocarcinoma component', 'Syncytiotrophoblastic elements secrete beta-hCG, which stimulates estradiol production and causes gynecomastia. AFP, LDH, and PLAP do not produce this hormonal effect.'),
('aa2af092-b775-531d-823f-1d77b7682dff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A mature cystic teratoma (dermoid cyst) of the ovary is:', '["A benign germ cell tumor containing mature derivatives of all three germ layers","A definite malignancy in adults accompanied by associated clinical symptoms","A metastasis from colonic carcinoma mediated by specific receptor activation","A functional steroid-secreting tumor without affecting the primary tissue pathway","A trophoblastic neoplasm leading to subsequent cellular adaptation"]'::jsonb, 'A benign germ cell tumor containing mature derivatives of all three germ layers', 'Mature teratoma consists of well-differentiated tissues from ectoderm, mesoderm, and endoderm (hair, teeth, skin) and is benign in postpubertal women. The immature form is malignant.'),
('24b656c2-9344-53b6-b04f-10d7ddf3d88e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Pleomorphic adenoma (''mixed tumor'') arises most commonly in the:', '["Parotid gland","Sublingual gland","Minor glands of the lip only","Lacrimal gland","Pancreas"]'::jsonb, 'Parotid gland', 'Pleomorphic adenoma is the most common salivary gland tumor and most often involves the parotid; it contains a mixture of epithelial and myxochondroid stromal elements and can recur if incompletely excised.'),
('921748ff-1016-5c56-8900-ef8842eeefdf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Carcinoid tumors arise from:', '["Neuroendocrine (enterochromaffin) cells","Columnar absorptive cells","Mucus-secreting goblet cells","Smooth-muscle cells","Submucosal macrophages"]'::jsonb, 'Neuroendocrine (enterochromaffin) cells', 'Carcinoid tumors derive from gut neuroendocrine (Kulchitsky) cells, usually behave in an indolent fashion, and produce serotonin and other amines.'),
('b59a8949-8acc-5946-8b51-daafcedd8b00'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common primary site of carcinoid tumor in surgical series is the:', '["Appendix","Stomach","Proximal colon","Pancreas","Bronchus"]'::jsonb, 'Appendix', 'Appendiceal carcinoids are the most commonly encountered carcinoid tumors and, when small and confined, are cured by appendectomy. Ileal carcinoids more often cause the syndrome when they metastasize.'),
('33bc1389-9a57-51c8-8153-9bffa799ab22'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The carcinoid syndrome (flushing, diarrhea, cardiac fibrosis) arises when a carcinoid tumor:', '["Metastasizes to the liver, allowing serotonin to bypass hepatic degradation","Is confined to the appendix accompanied by associated clinical symptoms","Produces no serotonin at all mediated by specific receptor activation","Is acutely inflamed without affecting the primary tissue pathway","Involves only the stomach leading to subsequent cellular adaptation"]'::jsonb, 'Metastasizes to the liver, allowing serotonin to bypass hepatic degradation', 'Serotonin released into the portal circulation is normally inactivated by the liver; only when hepatic metastases release serotonin directly into the systemic circulation does the syndrome appear.'),
('cd233cdb-cfd9-5058-a29a-d1e9d9de513b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Urinary 5-HIAA, the serotonin metabolite, is measured specifically to monitor:', '["Carcinoid tumor","Pheochromocytoma","Medullary thyroid carcinoma","Insulinoma","Gastrinoma"]'::jsonb, 'Carcinoid tumor', 'Serotonin is metabolized to 5-hydroxyindoleacetic acid, excreted in urine; elevated 5-HIAA supports the diagnosis and monitoring of carcinoid tumors. The other tumors use different markers.'),
('a64b9ce2-38c3-5220-aa90-86385ae0acf3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which tumor is classically described by the ''rule of tens'' (10% bilateral, 10% malignant, 10% extra-adrenal)?', '["Pheochromocytoma","Parathyroid adenoma","Appendiceal carcinoid","Insulinoma","Hepatocellular carcinoma"]'::jsonb, 'Pheochromocytoma', 'The ''rule of tens'' (10% bilateral, 10% malignant, 10% extra-adrenal, 10% in children) is the classic teaching for pheochromocytoma; bilateral disease suggests MEN 2 or VHL.'),
('8c56b7cc-9e7b-5137-940a-f9428b74b401'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Multiple endocrine neoplasia type 2A characteristically includes:', '["Medullary thyroid carcinoma, pheochromocytoma, and parathyroid hyperplasia","Parathyroid, pituitary, and pancreatic islet tumors","Gastric carcinoids and pulmonary adenomas","Renal carcinoma and hemangioblastoma","Neurofibromas and acoustic neuromas"]'::jsonb, 'Medullary thyroid carcinoma, pheochromocytoma, and parathyroid hyperplasia', 'MEN 2A comprises medullary thyroid carcinoma, pheochromocytoma, and parathyroid hyperplasia. The parathyroid-pituitary-pancreatic constellation defines MEN 1.'),
('0cca38ea-9635-520e-a5ae-2a7a51d3a58c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Medullary thyroid carcinoma arises from:', '["Parafollicular C cells that secrete calcitonin","Follicular epithelial cells that secrete thyroxine","Parathyroid chief cells","Thyroglossal duct remnants","Intrathyroidal macrophages"]'::jsonb, 'Parafollicular C cells that secrete calcitonin', 'Medullary carcinoma arises from calcitonin-secreting parafollicular C cells, so serum calcitonin is its marker; sporadic cases and the MEN 2-related (RET) forms both occur.'),
('6ca1ed6e-1d12-5ca9-a1cc-f89395ab1c46'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The RET/PTC rearrangement (a translocation) is characteristically found in:', '["Papillary thyroid carcinoma","Follicular thyroid carcinoma","Medullary thyroid carcinoma","Anaplastic thyroid carcinoma","Parathyroid adenoma"]'::jsonb, 'Papillary thyroid carcinoma', 'RET/PTC chimeric oncogenes, induced by ionizing radiation, are seen in a fraction of papillary thyroid carcinomas, which otherwise carry BRAF V600E mutations. Follicular tumors instead have RAS or PAX8-PPAR-gamma changes.'),
('6fabe54f-da11-5668-9692-17b0a0eb8861'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common intraocular malignant tumor of childhood is:', '["Retinoblastoma","Optic nerve glioma","Uveal melanoma","Lacrimal gland adenoid cystic carcinoma","Conjunctival lymphoma"]'::jsonb, 'Retinoblastoma', 'Retinoblastoma is the most common intraocular malignancy of children, with hereditary (RB1 germline) and sporadic forms. Uveal melanoma occurs in adults.'),
('d71aa084-5f16-55d5-b38f-cec71fa39e81'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common primary malignant brain tumor in adults is:', '["Glioblastoma (IDH-wildtype)","Meningioma","Medulloblastoma","Oligodendroglioma","Ependymoma"]'::jsonb, 'Glioblastoma (IDH-wildtype)', 'Glioblastoma is both the most common and most malignant primary brain tumor of adults, arising in the cerebral hemispheres. Medulloblastoma is a pediatric posterior fossa tumor.'),
('dd5cacab-301d-5916-8d2e-cb17711ef0d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Most intracranial neoplasms in adults are:', '["Metastatic (largely from lung and breast)","Primary gliomas","Meningiomas only","Pituitary adenomas only","Medulloblastomas"]'::jsonb, 'Metastatic (largely from lung and breast)', 'Metastases to the brain outnumber primary brain tumors, and in adults the most frequent sources are lung and breast carcinoma, usually as multiple lesions.'),
('3504d2bd-2e97-5fbb-9ffd-4b5e5b9a2494'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Neuroblastoma arises from:', '["Primitive neural crest cells of the adrenal medulla and sympathetic chain","Renal blastemal cells accompanied by associated clinical symptoms","Cerebellar granule cells mediated by specific receptor activation","Skeletal myoblasts without affecting the primary tissue pathway","Optic vesicle cells leading to subsequent cellular adaptation"]'::jsonb, 'Primitive neural crest cells of the adrenal medulla and sympathetic chain', 'Neuroblastoma is a tumor of primitive sympathogonia (neural crest) that arises in the adrenal medulla or paravertebral sympathetic ganglia, usually in children under 5 years.'),
('cb3a90fc-f8d3-5169-a780-7ea707faec9d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Elevated urinary catecholamines with VMA and HVA are markers of:', '["Neuroblastoma","Wilms tumor","Osteosarcoma","Retinoblastoma","Ewing sarcoma"]'::jsonb, 'Neuroblastoma', 'Neuroblastoma cells synthesize catecholamines; urinary vanillylmandelic acid (VMA) and homovanillic acid (HVA) are elevated in most cases and are used for diagnosis and follow-up.'),
('bbf09747-a149-5ab4-ad52-362e4d1c310e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Nephroblastoma (Wilms tumor) most commonly presents at age:', '["2-5 years","Adolescence","35-50 years","Over 60 years","In utero only"]'::jsonb, '2-5 years', 'Wilms tumor is a childhood embryonal renal neoplasm peaking between 2 and 5 years; it may be associated with WT1 mutations and syndromes such as WAGR and Beckwith-Wiedemann.'),
('bc5d6f0e-acd1-53a8-b899-16836f81e5bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Clear cell renal cell carcinoma arises from:', '["Proximal convoluted tubule epithelium","Glomerular mesangial cells","Podocytes and epithelial cells of the tuft","Urothelial cells of the renal pelvis","Loop of Henle cells"]'::jsonb, 'Proximal convoluted tubule epithelium', 'Renal cell carcinoma, especially the clear cell type, derives from the proximal tubular epithelium and is linked to VHL loss or germline VHL syndrome.'),
('4f5d9f79-3c48-56f5-a208-8d29d25fe7f7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The classic clinical triad of renal cell carcinoma is:', '["Hematuria, flank pain, and a palpable mass","Dysuria, frequency, and urgency","Fever, pruritus, and arthralgia","Hypertension, headache, and sweating","Dyspnea, cough, and hemoptysis"]'::jsonb, 'Hematuria, flank pain, and a palpable mass', 'The classic triad of hematuria, flank pain, and palpable mass occurs in a minority of renal cell carcinoma patients, many of whom instead present with paraneoplastic or incidental findings.'),
('6ae38d01-5d05-549c-8ee3-5bef2231b6e2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Renal cell carcinoma may secrete which hormone, causing polycythemia?', '["Erythropoietin","Parathyroid hormone-related protein","Calcitonin","Gastrin","Beta-hCG"]'::jsonb, 'Erythropoietin', 'Ectopic erythropoietin secretion by renal cell carcinoma produces erythrocytosis; the same phenomenon occurs in cerebellar hemangioblastoma and hepatocellular carcinoma.'),
('2ab0095b-ed60-568b-8587-4feb1fb8878e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Inactivation of the VHL tumor suppressor gene predisposes to:', '["Clear cell renal cell carcinoma and hemangioblastoma","Medullary thyroid carcinoma accompanied by associated clinical symptoms","Colorectal carcinoma mediated by specific receptor activation","Chronic lymphocytic leukemia without affecting the primary tissue pathway","Cervical carcinoma leading to subsequent cellular adaptation"]'::jsonb, 'Clear cell renal cell carcinoma and hemangioblastoma', 'VHL syndrome and somatic VHL loss cause clear cell renal carcinoma through stabilization of HIF-1alpha and increased VEGF; hemangioblastomas of the retina and cerebellum also occur.'),
('f580b8ff-56ce-55a1-91d0-bcb40efbfd58'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Squamous cell carcinoma of the lung characteristically arises:', '["Centrally near the hilum","In the lung periphery","At the pleural surface","Diffusely through both lungs","Within a mediastinal cyst"]'::jsonb, 'Centrally near the hilum', 'Squamous cell carcinoma of the lung is typically a central, hilar tumor that cavitates and is strongly associated with smoking. Adenocarcinoma tends to be peripheral.'),
('d4efdea9-1ccd-5017-be77-6a22c9ec778d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Adenocarcinoma is currently the most common lung cancer type among:', '["Nonsmokers and women","Underground miners","Male heavy smokers only","Young adolescents","Patients with asbestosis"]'::jsonb, 'Nonsmokers and women', 'Lung adenocarcinoma has become the most common type and predominates in nonsmokers and women; it is frequently peripheral and often carries EGFR or ALK alterations.'),
('95b72974-ced5-53f4-a056-0615dbdf0c02'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A superior sulcus (Pancoast) lung tumor may produce Horner syndrome by invading the:', '["Sympathetic chain and stellate ganglion","Recurrent laryngeal nerve","Phrenic nerve","Vagus nerve","Brachial plexus roots only"]'::jsonb, 'Sympathetic chain and stellate ganglion', 'Pancoast tumors at the lung apex invade the cervical sympathetic chain, causing ipsilateral miosis, ptosis, and anhidrosis (Horner syndrome), with shoulder pain from brachial plexus and rib involvement.'),
('bb66eda3-7416-5d93-9fdf-ecf5ac4aa665'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which lung cancer has the strongest association with paraneoplastic syndromes?', '["Small cell carcinoma","Squamous cell carcinoma","Adenocarcinoma","Large cell carcinoma","Typical bronchial carcinoid"]'::jsonb, 'Small cell carcinoma', 'Small cell lung carcinoma is intimately linked with paraneoplastic syndromes including ectopic ACTH, SIADH, and Lambert-Eaton syndrome, reflecting its neuroendocrine derivation.'),
('39b8cd5a-08ff-5011-9f12-b1fd52989159'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Cushing syndrome from ectopic ACTH is classically associated with:', '["Small cell lung carcinoma","Renal cell carcinoma","Medullary thyroid carcinoma","Colorectal adenocarcinoma","Hepatocellular carcinoma"]'::jsonb, 'Small cell lung carcinoma', 'Small cell carcinoma secretes ectopic ACTH, producing Cushing syndrome, often with hypokalemic alkalosis. This is one of the best-known paraneoplastic endocrinopathies.'),
('b6fb294a-176e-54ef-a388-57a7fb628c1c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Hypercalcemia in squamous cell lung carcinoma is mediated by:', '["Parathyroid hormone-related protein (PTHrP)","Ectopic parathyroid hormone itself","Calcitonin excess","Osteoclast-inhibiting factor","Hypervitaminosis D"]'::jsonb, 'Parathyroid hormone-related protein (PTHrP)', 'Humoral hypercalcemia of malignancy in squamous cell (and other) carcinomas is due to tumor secretion of PTHrP, which mimics PTH and mobilizes calcium from bone. SCC lung rarely secretes true PTH.'),
('5ce29171-53ca-5cd0-960b-ba67da501eba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Syndrome of inappropriate antidiuretic hormone secretion (SIADH) is a paraneoplastic feature of:', '["Small cell lung carcinoma","Papillary thyroid carcinoma","Follicular lymphoma","Osteosarcoma","Meningioma"]'::jsonb, 'Small cell lung carcinoma', 'Small cell carcinoma ectopically secretes ADH, causing euvolemic hyponatremia with inappropriately concentrated urine. This is a classic paraneoplastic presentation of SCLC.'),
('7779a6ce-5523-5a97-8e26-6ad43e82798a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Lambert-Eaton myasthenic syndrome is a paraneoplastic disorder associated with:', '["Small cell lung carcinoma","Breast carcinoma","Colorectal carcinoma","Prostate carcinoma","Renal cell carcinoma"]'::jsonb, 'Small cell lung carcinoma', 'Antibodies against presynaptic voltage-gated calcium channels in SCLC cause Lambert-Eaton syndrome, with proximal weakness that improves on exertion and areflexia.'),
('e99398a0-0be2-546a-a8ad-86ea4392e0b4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Acanthosis nigricans as a paraneoplastic manifestation is classically seen with:', '["Gastric adenocarcinoma","Testicular seminoma","Medullary thyroid carcinoma","Cervical carcinoma","Retinoblastoma"]'::jsonb, 'Gastric adenocarcinoma', 'Malignant acanthosis nigricans, velvety hyperpigmentation of flexural skin, is classically associated with gastric adenocarcinoma, presumably through tumor-derived growth factors.'),
('f67f4c96-0e53-59e2-8b79-59c246fe9d2f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Dermatomyositis presenting in adulthood should prompt investigation for occult:', '["Ovarian or lung carcinoma","Peutz-Jeghers polyposis","Pheochromocytoma","Meningioma","Vitiligo"]'::jsonb, 'Ovarian or lung carcinoma', 'Adult-onset dermatomyositis is a paraneoplastic phenomenon in a substantial proportion of patients, classically associated with ovarian, lung, breast, and gastric cancer.'),
('bec41051-c438-5dc6-abf4-2b0cdf0e49c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Cancer cachexia and systemic wasting are mediated chiefly by:', '["Tumor necrosis factor-alpha, IL-6, and proteolysis-inducing factor","Insulin-like growth factor-1 accompanied by associated clinical symptoms","VEGF alone mediated by specific receptor activation","Cortisol deficiency without affecting the primary tissue pathway","Thyroid hormone excess leading to subsequent cellular adaptation"]'::jsonb, 'Tumor necrosis factor-alpha, IL-6, and proteolysis-inducing factor', 'Tumor- and host-derived cytokines, notably TNF-alpha, IL-6, and proteolysis-inducing factor, drive skeletal-muscle wasting, anorexia, and weight loss characteristic of cancer cachexia.'),
('6151ef48-7e86-5c35-9b43-fef025ee003d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Trousseau syndrome (recurrent migratory thrombophlebitis) is a thrombotic manifestation of:', '["Mucin-secreting adenocarcinomas","Squamous carcinoma of the cervix","Basal cell carcinoma","Thyroid adenoma","Glioblastoma"]'::jsonb, 'Mucin-secreting adenocarcinomas', 'Mucin-producing adenocarcinomas, classically pancreatic and gastric, trigger chronic low-grade disseminated intravascular coagulation and recurrent venous thrombosis, termed Trousseau syndrome.'),
('bd3fa6c2-18bd-5f4f-aa1c-0dc884d9e4c4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A paraneoplastic syndrome is best defined as:', '["A systemic disorder caused by tumor products or immune reactions remote from the primary tumor and its metastases","Direct infiltration of adjacent organs by the tumor accompanied by associated clinical symptoms","A complication of radiotherapy mediated by specific receptor activation","An opportunistic infection in a cancer patient without affecting the primary tissue pathway","A nutritional deficiency from anorexia leading to subsequent cellular adaptation"]'::jsonb, 'A systemic disorder caused by tumor products or immune reactions remote from the primary tumor and its metastases', 'Paraneoplastic syndromes are remote effects produced by secreted hormones, growth factors, or immune responses, extending beyond the site of the tumor (e.g., ectopic ACTH, hypercalcemia, cachexia).'),
('53917dda-a42d-5c12-9789-c996f3d051c0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Cancer immune surveillance relies chiefly on:', '["Cytotoxic T lymphocytes and natural killer cells","Neutrophils and complement accompanied by associated clinical symptoms","Mast cells only mediated by specific receptor activation","Eosinophils only without affecting the primary tissue pathway","Platelet-derived factors leading to subsequent cellular adaptation"]'::jsonb, 'Cytotoxic T lymphocytes and natural killer cells', 'CD8-positive cytotoxic T cells recognize tumor antigens presented on MHC class I, while NK cells kill cells that lose MHC expression; both are the main effectors of immune surveillance.'),
('a5de2daa-bb87-5c13-bb1b-bdf8c92c648a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which childhood tumor is notorious for occasional spontaneous regression or maturation?', '["Neuroblastoma (especially stage 4S)","Wilms tumor accompanied by associated clinical symptoms","Retinoblastoma mediated by specific receptor activation","Ewing sarcoma without affecting the primary tissue pathway","Osteosarcoma leading to subsequent cellular adaptation"]'::jsonb, 'Neuroblastoma (especially stage 4S)', 'Stage 4S neuroblastoma (localized primary with skin, liver, and marrow deposits in infants) frequently undergoes spontaneous regression or differentiation into benign ganglioneuroma.'),
('023ed521-8baf-5691-9ffa-bd3ced10a4b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Besides colorectal cancer, Lynch syndrome predisposes strongly to:', '["Endometrial (and ovarian) carcinoma","Prostate carcinoma","Lung carcinoma","Malignant melanoma","Hodgkin lymphoma"]'::jsonb, 'Endometrial (and ovarian) carcinoma', 'Lynch syndrome is an extracolonic cancer syndrome: endometrial carcinoma is the second most common malignancy, with increased ovarian, gastric, and urothelial risk.'),
('0ffb5dd9-8c66-5741-bcbf-2572d3bbafb9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In untreated familial adenomatous polyposis, colorectal carcinoma characteristically develops by:', '["The fourth decade in nearly 100% of patients","Age 80 in about 10%","Never without metastasis","Puberty in every patient","Menopause in women only"]'::jsonb, 'The fourth decade in nearly 100% of patients', 'FAP produces hundreds to thousands of adenomas, and without prophylactic colectomy essentially all affected individuals develop colorectal cancer by around age 40, following the APC-driven pathway.'),
('8c9161c6-999f-501a-9a83-fc5ae9a39b7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'MEN 1 (Wermer) syndrome characteristically features:', '["Parathyroid, pancreatic islet, and pituitary tumors","Medullary thyroid carcinoma and pheochromocytoma","Mucosal neuromas and a marfanoid habitus","Renal cysts and hemangioblastomas","Colonic adenomatous polyposis"]'::jsonb, 'Parathyroid, pancreatic islet, and pituitary tumors', 'MEN 1 is caused by menin gene mutation and classically involves the parathyroid (hyperplasia), pancreatic islet (gastrinoma, insulinoma), and pituitary (prolactinoma). The medullary-pheo pair defines MEN 2.'),
('64cae50e-1f08-5cca-b97e-347c5abf8031'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which combination of findings is characteristic of von Hippel-Lindau syndrome?', '["Retinal and cerebellar hemangioblastomas with clear cell renal carcinoma","Colonic adenomas with desmoid tumors","Multiple lipomas and angiofibromas","Bilateral acoustic neuromas and meningiomas","Cafe-au-lait spots with optic glioma"]'::jsonb, 'Retinal and cerebellar hemangioblastomas with clear cell renal carcinoma', 'VHL syndrome is a germline tumor suppressor defect involving the VHL gene, causing hemangioblastomas of retina and cerebellum, clear cell renal carcinoma, and pheochromocytoma.'),
('d2299e5d-94d7-556d-9ffc-a7ba73acbb37'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Neurofibromatosis type 1 results from mutation of:', '["The NF1 gene encoding neurofibromin","The NF2 gene encoding merlin accompanied by associated clinical symptoms","TP53 mediated by specific receptor activation","APC without affecting the primary tissue pathway","RB1 leading to subsequent cellular adaptation"]'::jsonb, 'The NF1 gene encoding neurofibromin', 'NF1 is caused by loss of neurofibromin, a GTPase-activating protein for RAS; its loss leaves RAS constitutively active and predisposes to neurofibromas, cafe-au-lait spots, and malignant peripheral nerve sheath tumors.'),
('5b4618cf-53b1-54df-b57d-3a4e217c89a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Neurofibromatosis type 2 is best characterized by:', '["Bilateral vestibular schwannomas (acoustic neuromas)","Multiple cafe-au-lait spots accompanied by associated clinical symptoms","Optic pathway gliomas mediated by specific receptor activation","Colonic polyposis without affecting the primary tissue pathway","Medullary thyroid carcinoma leading to subsequent cellular adaptation"]'::jsonb, 'Bilateral vestibular schwannomas (acoustic neuromas)', 'NF2 is defined by bilateral acoustic neuromas from loss of the NF2 (merlin) gene, with meningiomas and ependymomas also common. Cafe-au-lait spots and optic gliomas belong to NF1.'),
('33dbf62d-b181-5d5a-988f-1a0c6990c57c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Cowden syndrome, caused by PTEN mutation, is characterized by:', '["Multiple hamartomas and high risk of breast, thyroid, and endometrial cancer","Osteomas of the jaw accompanied by associated clinical symptoms","Bilateral acoustic neuromas mediated by specific receptor activation","Retinal hemangioblastomas without affecting the primary tissue pathway","Cafe-au-lait macules leading to subsequent cellular adaptation"]'::jsonb, 'Multiple hamartomas and high risk of breast, thyroid, and endometrial cancer', 'Germline PTEN loss (Cowden syndrome) produces hamartomatous lesions, trichilemmomas, and substantially increased breast, thyroid, and endometrial cancer risk.'),
('ff24efe9-a15a-5770-b02d-28692bc78fd9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Peutz-Jeghers syndrome is characterized by hamartomatous gastrointestinal polyps and:', '["Mucocutaneous melanin pigmentation, with STK11 (LKB1) mutation","Bilateral acoustic neuromas","Osteomas of the jaw and skin tumors","Cafe-au-lait macules only","Telangiectasias of skin and mucosa"]'::jsonb, 'Mucocutaneous melanin pigmentation, with STK11 (LKB1) mutation', 'Peutz-Jeghers syndrome pairs hamartomatous polyposis with perioral and buccal melanin spots and carries germline STK11/LKB1 mutations plus elevated risk of intestinal and extraintestinal cancers.'),
('e57317d1-3563-54de-b632-850994f45149'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Xeroderma pigmentosum, which predisposes to skin cancers, results from a defect in:', '["Nucleotide excision repair of UV-induced DNA damage","Mismatch repair of replication errors","Homologous-recombination repair","Base excision repair","Apoptotic signaling"]'::jsonb, 'Nucleotide excision repair of UV-induced DNA damage', 'Xeroderma pigmentosum is caused by defective nucleotide excision repair of UV-induced pyrimidine dimers, so patients develop massive numbers of skin cancers in sun-exposed areas.'),
('5f86caf8-f262-53b5-a8df-be301c9f2ced'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Ataxia-telangiectasia results from a defect in ATM, causing:', '["Radiosensitivity with predisposition to leukemia and lymphoma","Selective loss of humoral immunity only accompanied by associated clinical symptoms","Colonic polyposis mediated by specific receptor activation","Hyperpigmentation of the skin only without affecting the primary tissue pathway","Bone overgrowth leading to subsequent cellular adaptation"]'::jsonb, 'Radiosensitivity with predisposition to leukemia and lymphoma', 'ATM is a kinase that senses double-strand breaks; its loss causes cerebellar ataxia, telangiectasias, extreme radiosensitivity, and a high risk of lymphoid and other hematologic neoplasms.'),
('7adeab18-5a80-5dba-9ea7-fc1628f673e2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Bloom syndrome is due to mutation of:', '["The BLM DNA helicase gene","The RB1 gene","The APC gene","Mismatch-repair genes","The telomerase gene"]'::jsonb, 'The BLM DNA helicase gene', 'Bloom syndrome results from defective BLM helicase, producing chromosomal instability, sister-chromatid exchanges, and predisposition to a wide range of cancers, especially leukemia and lymphoma.'),
('0b9f169f-ae2b-5805-8023-ca7274e13430'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Fanconi anemia, characterized by chromosomal fragility, predisposes to:', '["Acute myeloid leukemia","Cervical carcinoma","Prostatic carcinoma","Malignant melanoma","Thyroid carcinoma"]'::jsonb, 'Acute myeloid leukemia', 'Fanconi anemia is an inherited DNA crosslink-repair disorder with bone marrow failure and a markedly increased risk of AML. Its genes also increase squamous carcinoma risk.'),
('92f160ea-33f2-5d71-b64a-569a9504fa97'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Multiple endocrine neoplasia type 2B includes the distinctive feature of:', '["Mucosal neuromas and a marfanoid habitus","Osteomas of the jaw","Lentigines of the lips","Retinal telangiectasias","Cafe-au-lait macules"]'::jsonb, 'Mucosal neuromas and a marfanoid habitus', 'MEN 2B combines medullary thyroid carcinoma, pheochromocytoma, mucosal ganglioneuromas, and a marfanoid body habitus, all from RET mutation at codon 918, with more aggressive behavior than MEN 2A.'),
('6a951f47-4b39-564b-86e6-6625c46989cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Tumor suppressor genes are characterized by the requirement that:', '["Both alleles must usually be inactivated for loss of function","A single mutated allele suffices","They act through gain-of-function changes","They are activated by translocation","They are deleted only in the germline"]'::jsonb, 'Both alleles must usually be inactivated for loss of function', 'Most tumor suppressor genes behave recessively at the cellular level: because one normal allele can still supply function, both alleles must be lost by mutation, deletion, or methylation for the cell to be transformed.'),
('257ef6ca-ad0d-542b-9e63-0e19ccb8c4d1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The shared final common mechanism of chemical, radiation, and viral carcinogens is:', '["Damage to DNA (a mutagenic action)","Uniform activation of telomerase","Direct stimulation of mitosis only","Production of growth factors only","Suppression of immune cells only"]'::jsonb, 'Damage to DNA (a mutagenic action)', 'All classes of carcinogens ultimately mutate DNA; chemicals form adducts, radiation breaks DNA, and oncogenic viruses introduce oncogenes or inactivate tumor suppressors.'),
('a60aab71-8d55-5dba-bce5-a9149296ccc7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which of the following is a direct-acting carcinogen that needs no metabolic activation?', '["Alkylating agents such as cyclophosphamide and mustards","Polycyclic aromatic hydrocarbons accompanied by associated clinical symptoms","Aflatoxin B1 mediated by specific receptor activation","Dimethylnitrosamine without affecting the primary tissue pathway","Vinyl chloride leading to subsequent cellular adaptation"]'::jsonb, 'Alkylating agents such as cyclophosphamide and mustards', 'Alkylating chemotherapy agents are inherently reactive and directly damage DNA without needing P-450 activation, which is why they themselves carry a leukemia risk. The aromatic hydrocarbons, aflatoxin, nitrosamines, and vinyl chloride require metabolic activation.'),
('f3ad9f41-6b88-5105-8719-8b8d80af7b0b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Procarcinogens such as benzo(a)pyrene require metabolic activation by:', '["Cytochrome P-450 enzymes to become reactive ultimate carcinogens","DNA polymerases accompanied by associated clinical symptoms","Ribosomes mediated by specific receptor activation","Membrane receptors without affecting the primary tissue pathway","Histone acetyltransferases leading to subsequent cellular adaptation"]'::jsonb, 'Cytochrome P-450 enzymes to become reactive ultimate carcinogens', 'Polycyclic aromatic hydrocarbons in tobacco smoke are inert until hepatic P-450 enzymes convert them to reactive epoxides that form DNA adducts; this is why induction of these enzymes can increase risk.'),
('f492daa1-3f81-505d-bdf6-d3c79ae90975'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Phorbol esters promote tumorigenesis by:', '["Activating protein kinase C, a signal that drives proliferation","Methylating tumor suppressor promoters accompanied by associated clinical symptoms","Inducing double-strand breaks mediated by specific receptor activation","Directly mutating RAS without affecting the primary tissue pathway","Inhibiting ribosome assembly leading to subsequent cellular adaptation"]'::jsonb, 'Activating protein kinase C, a signal that drives proliferation', 'Phorbol esters mimic diacylglycerol and activate protein kinase C, stimulating proliferation of initiated cells without mutating DNA; they are classic tumor promoters.'),
('ba288a54-d870-5aa0-9aa4-82337c6d4e87'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Classic hereditary cancer syndromes due to tumor suppressor genes are inherited in which pattern?', '["Autosomal dominant","Autosomal recessive in all cases","Sex-linked","Mitochondrial","X-linked dominant"]'::jsonb, 'Autosomal dominant', 'Because one germline hit already predisposes and the second occurs somatically, hereditary cancer syndromes such as FAP, retinoblastoma, and Li-Fraumeni follow autosomal-dominant inheritance.'),
('efa9792c-191b-50f5-b6cc-293de6186b04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which cancer predisposition syndrome is inherited as an autosomal recessive disorder?', '["Xeroderma pigmentosum","Familial adenomatous polyposis","Li-Fraumeni syndrome","Hereditary retinoblastoma","Multiple endocrine neoplasia 1"]'::jsonb, 'Xeroderma pigmentosum', 'Xeroderma pigmentosum requires biallelic defects in nucleotide-excision-repair genes and is autosomal recessive, unlike the dominant syndromes (FAP, Li-Fraumeni, retinoblastoma, MEN).'),
('4c98044e-2a8c-5674-b7a5-4f4036594893'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In hereditary cancer syndromes, the ''first hit'' that was classically described by Knudson is:', '["Present in the germline and therefore in every cell","Acquired only in the tumor","Caused by chemotherapy","Restricted to the bone marrow","Present only in mitochondria"]'::jsonb, 'Present in the germline and therefore in every cell', 'Knudson''s first hit in hereditary retinoblastoma is an inherited mutation in the germline, present in every cell; the second hit is a somatic event that inactivates the remaining allele within the tumor.'),
('7fe47c59-be18-543f-b62c-6e9f8b549f15'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Detection of loss of heterozygosity (LOH) at a tumor suppressor locus indicates that:', '["Both alleles of the gene have been inactivated in the tumor","One allele of an oncogene has been gained","A growth factor gene has been amplified","A balanced translocation has occurred","Telomeres have been shortened"]'::jsonb, 'Both alleles of the gene have been inactivated in the tumor', 'LOH is a manifestation of the two-hit model: one allele is already mutated (first hit) and the remaining wild-type allele is lost by deletion, so a comparison of residual heterozygosity confers evidence of biallelic gene inactivation.'),
('b66e6c25-11aa-598f-b2f1-b6b00333633f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Fluorescence in situ hybridization (FISH) is most useful for:', '["Detecting gene amplification and translocations","Measuring serum tumor-marker levels","Grading tumor differentiation","Estimating hormone concentrations","Screening for germline polyposis"]'::jsonb, 'Detecting gene amplification and translocations', 'FISH detects copy-number gain and structural rearrangements, so it is used to document HER2 amplification, BCR-ABL, and MYC translocations. Serum markers and histologic grading use other techniques.'),
('41a3b80e-14c1-50a2-a715-0167ec2183d6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', '''Field cancerization'' refers to:', '["Multiple independent premalignant or malignant lesions within an epithelial field exposed to a carcinogen","Metastasis to a single regional node accompanied by associated clinical symptoms","Expansion of a single transformed clone mediated by specific receptor activation","A reactive inflammatory change without affecting the primary tissue pathway","A germline chromosomal translocation leading to subsequent cellular adaptation"]'::jsonb, 'Multiple independent premalignant or malignant lesions within an epithelial field exposed to a carcinogen', 'Chronic exposure of an entire mucosal or epidermal surface (e.g., oral mucosa, bladder, lung) produces multiple, genetically independent foci of dysplasia or carcinoma arising across the field.'),
('69ddf754-40de-548f-88e3-c69063ba93eb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which lesion of the oral cavity is regarded as premalignant?', '["Leukoplakia","Aphthous ulcer","Herpes labialis","Denture fibroma","Pyogenic granuloma"]'::jsonb, 'Leukoplakia', 'Oral leukoplakia is a white plaque with significant risk of progression to squamous cell carcinoma, especially when dysplastic. The other lesions are reactive or inflammatory and not premalignant.'),
('d75f9639-c431-5f9b-8a3b-c8c80811a924'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which colonic polyp carries the greatest risk of malignant transformation?', '["Villous adenoma","Tubular adenoma","Hyperplastic polyp","Inflammatory polyp","Hamartomatous polyp"]'::jsonb, 'Villous adenoma', 'Villous and especially large sessile villous adenomas have the highest carcinoma risk among polyps, whereas hyperplastic, inflammatory, and hamartomatous polyps are not premalignant.'),
('19ec15c7-3036-528f-953a-402998632de4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Chronic ulcerative colitis of long duration predisposes to:', '["Colorectal adenocarcinoma","Small-bowel carcinoid only","Appendiceal mucocele","Anal melanoma","Diverticulitis"]'::jsonb, 'Colorectal adenocarcinoma', 'Pancolitis of 10 or more years'' duration markedly raises colorectal carcinoma risk through chronic inflammation-dysplasia-carcinoma progression, independent of the familial polyposis pathway.'),
('4440df31-1144-5529-accf-615c6b608c59'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Chronic atrophic gastritis of the pernicious-anemia type predisposes to:', '["Gastric adenocarcinoma","Crohn disease","Celiac disease","Gallstones","Acute pancreatitis"]'::jsonb, 'Gastric adenocarcinoma', 'Autoimmune atrophic gastritis causes hypochlorhydria, bacterial overgrowth, and intestinal metaplasia, predisposing to gastric adenocarcinoma; nitrosamines formed in the hypochlorhydric stomach also contribute.'),
('8ef77599-25af-54b0-9e0d-df6a80912b46'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Long-standing celiac disease predisposes to:', '["Enteropathy-associated T-cell lymphoma","Gastric adenocarcinoma","Colon carcinoma","Hepatocellular carcinoma","Pancreatic carcinoma"]'::jsonb, 'Enteropathy-associated T-cell lymphoma', 'Celiac disease, caused by gluten sensitivity, carries an increased risk of enteropathy-associated T-cell lymphoma of the small intestine, a rare but aggressive complication.'),
('09bc49b1-72f3-5481-bb7e-7f3e46c0ea6a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which combination of tumors is characteristically increased in HIV/AIDS patients?', '["Kaposi sarcoma and high-grade B-cell lymphomas","Colon carcinoma and melanoma","Prostate carcinoma and renal carcinoma","Osteosarcoma and thyroid carcinoma","Meningioma and pituitary adenoma"]'::jsonb, 'Kaposi sarcoma and high-grade B-cell lymphomas', 'HIV-related immunosuppression permits HHV-8-driven Kaposi sarcoma, EBV-driven lymphomas, and HPV-driven cervical carcinoma; these define the AIDS-defining cancers.'),
('235e28d8-b979-52e7-b5b8-05afe87ec474'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Post-transplant lymphoproliferative disorders are attributable largely to:', '["EBV-driven proliferation of B cells under immunosuppression","HTLV-1 infection accompanied by associated clinical symptoms","HPV reactivation mediated by specific receptor activation","Cytomegalovirus only without affecting the primary tissue pathway","Bacterial superantigens leading to subsequent cellular adaptation"]'::jsonb, 'EBV-driven proliferation of B cells under immunosuppression', 'Loss of T-cell control after transplantation allows latently EBV-infected B cells to proliferate, producing polyclonal then monoclonal lymphomas that may regress when immunosuppression is reduced.'),
('e91e13b6-416e-51db-9501-ab710dd028ea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which of the following is a hamartoma (a localized overgrowth of mature tissue)?', '["Pulmonary hamartoma with cartilage","Adenocarcinoma of the lung","Metastatic carcinoma","Seminoma","Follicular lymphoma"]'::jsonb, 'Pulmonary hamartoma with cartilage', 'A pulmonary hamartoma is a benign overgrowth of cartilage, fat, and connective tissue, not a true monoclonal neoplasm. Carcinomas, seminomas, and lymphomas are genuine malignant tumors.'),
('3866d161-46e6-595c-86d7-981edef0e0a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A choristoma is best defined as:', '["A mass of normal tissue present in an abnormal location","A benign glandular tumor accompanied by associated clinical symptoms","An invasive cancer mediated by specific receptor activation","A cartilage-containing pulmonary lesion without affecting the primary tissue pathway","A germ-cell tumor leading to subsequent cellular adaptation"]'::jsonb, 'A mass of normal tissue present in an abnormal location', 'Choristomas are heterotopic rests of normal tissue in a foreign site (e.g., pancreatic tissue in the stomach). Hamartomas, by contrast, are disorganized tissue in a normal location.'),
('9ba759fe-db85-5f9c-a47a-cad5fdd3f8f2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The growth fraction of a tumor refers to the:', '["Proportion of cells in the proliferating (cycling) pool","Rate of cell death only accompanied by associated clinical symptoms","Tumor doubling time mediated by specific receptor activation","Number of chromosomes per cell without affecting the primary tissue pathway","Size of the necrotic core leading to subsequent cellular adaptation"]'::jsonb, 'Proportion of cells in the proliferating (cycling) pool', 'Growth fraction is the fraction of tumor cells actively cycling at any time; rapidly growing tumors have a high growth fraction, which is exploited by cell-cycle-specific chemotherapy.'),
('7a4212ba-8216-5111-84c1-76f3c6875770'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Central necrosis of rapidly growing tumors occurs because:', '["Blood supply fails to keep pace with tumor growth","Excess immunologic killing of tumor cells","Accumulation of p53","Apoptosis of the surrounding stroma","Lymphatic obstruction"]'::jsonb, 'Blood supply fails to keep pace with tumor growth', 'As tumors outgrow their vasculature, the ischemic core undergoes coagulative necrosis; this is later excused by the fact that tumor vessels are leaky and poorly organized.'),
('85185c2f-8b52-5b8e-9d80-89c00e841d04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which benign precursor lesion may give rise to malignant melanoma?', '["Dysplastic (atypical) nevus","Seborrheic keratosis","Dermatofibroma","Epidermal cyst","Blue nevus of all types"]'::jsonb, 'Dysplastic (atypical) nevus', 'Dysplastic nevi show disordered architecture and atypia and confer an increased melanoma risk, particularly in familial dysplastic nevus syndrome. Seborrheic keratosis and dermatofibroma are not premalignant.'),
('87d110ae-e241-5fd9-bc7e-594c68c60a3b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Clinical staging of a tumor relies on:', '["Imaging, surgical exploration, and histologic assessment of resected nodes","Serum tumor markers alone accompanied by associated clinical symptoms","Family history alone mediated by specific receptor activation","Tumor size estimated by palpation alone without affecting the primary tissue pathway","Biopsy of the primary tumor only leading to subsequent cellular adaptation"]'::jsonb, 'Imaging, surgical exploration, and histologic assessment of resected nodes', 'Staging integrates clinical examination, radiologic extent of disease, findings at surgery, and pathology of resected tissue and nodes; serum markers cannot stage a tumor.'),
('0be84902-f120-5d20-92d0-1b6f3c23a12f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In TNM grouping, stage I disease indicates:', '["A small tumor limited to the primary site without nodal or distant metastasis","Distant metastasis at presentation accompanied by associated clinical symptoms","Extensive regional nodal involvement mediated by specific receptor activation","Invasion recognized only microscopically without affecting the primary tissue pathway","A tumor of any size with M1 leading to subsequent cellular adaptation"]'::jsonb, 'A small tumor limited to the primary site without nodal or distant metastasis', 'Stage I denotes localized disease not yet involving nodes or distant organs, usually carrying the best prognosis and permitting surgical cure in many sites.'),
('641406eb-5cc2-5c0a-8088-3a33700ba384'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Constitutive activation of RAS in human cancer most often results from:', '["A point mutation that impairs the intrinsic GTPase activity","Gene amplification alone","Promoter deletion","A balanced translocation","Overexpression of the wild-type protein alone"]'::jsonb, 'A point mutation that impairs the intrinsic GTPase activity', 'Mutant RAS at codons 12, 13, or 61 hydrolyzes GTP poorly and stays in the active GTP-bound state, constitutively signaling through downstream raf/MAPK and PI3K pathways.'),
('e33d62c3-72c6-5e46-bfab-e7a7505afd54'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The MYC oncoprotein functions as:', '["A nuclear transcription factor that drives cell proliferation","A membrane receptor tyrosine kinase accompanied by associated clinical symptoms","A cytoplasmic GTPase mediated by specific receptor activation","A cell-cycle checkpoint kinase without affecting the primary tissue pathway","A protease degrading p53 leading to subsequent cellular adaptation"]'::jsonb, 'A nuclear transcription factor that drives cell proliferation', 'MYC is a nuclear transcription factor that dimerizes with MAX and transactivates genes promoting growth and cell-cycle progression; translocation or amplification drives many lymphomas and solid tumors.'),
('e2a83370-ffa8-5793-9aa0-d88a1323b46c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The SRC gene encodes:', '["A non-receptor (cytoplasmic) tyrosine kinase","A nuclear hormone receptor","A GTP-binding protein","A DNA-repair enzyme","An immunoglobulin molecule"]'::jsonb, 'A non-receptor (cytoplasmic) tyrosine kinase', 'SRC is the prototype cytoplasmic (non-receptor) tyrosine kinase that relays growth signals from membrane receptors to intracellular pathways; it was the first oncogene to be characterized in a retrovirus.'),
('e56f3cad-d440-587f-b67e-28f46fa15cd0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Autocrine secretion of platelet-derived growth factor (PDGF) and its receptor stimulates growth of:', '["Astrocytic tumors (glioblastoma) and osteosarcomas","Follicular lymphomas accompanied by associated clinical symptoms","Hodgkin lymphoma mediated by specific receptor activation","Pancreatic islet-cell tumors without affecting the primary tissue pathway","Choriocarcinomas leading to subsequent cellular adaptation"]'::jsonb, 'Astrocytic tumors (glioblastoma) and osteosarcomas', 'Glioblastomas and osteosarcomas co-express PDGF and the PDGF receptor, creating an autocrine loop that continuously drives proliferation; platelet-derived growth factor is also released from platelets at injury sites.'),
('067046a9-e4a1-5d5a-b9c1-ceb2ffe8b76d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Autocrine growth stimulation means that a tumor cell:', '["Secretes and simultaneously responds to the same growth factor","Responds only to a distant endocrine hormone","Is completely unresponsive to growth signals","Secretes proteases instead of growth factors","Depends on neighboring stroma for every growth signal"]'::jsonb, 'Secretes and simultaneously responds to the same growth factor', 'In autocrine stimulation the tumor makes its own growth factor and expresses the corresponding receptor, creating self-sustaining proliferation, as seen with PDGF in glioblastoma or TGF-alpha in some carcinomas.'),
('fa8baa14-46ae-559b-9d68-ef9a8c600a07'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Activating EGFR mutations are a therapeutic target in which cancer?', '["Non-small-cell lung adenocarcinoma","Prostate carcinoma","Hepatocellular carcinoma","Follicular lymphoma","Medulloblastoma"]'::jsonb, 'Non-small-cell lung adenocarcinoma', 'EGFR tyrosine-kinase domain mutations (del19, L858R) in lung adenocarcinoma predict response to erlotinib/gefitinib/osimertinib. The other tumors are not driven by sensitizing EGFR mutations.'),
('31728bfb-760f-5975-afd9-03bf32afba82'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The EML4-ALK fusion gene is the target of crizotinib in:', '["Lung adenocarcinoma","Colon carcinoma","Melanoma","Chronic myeloid leukemia","Gastric carcinoma"]'::jsonb, 'Lung adenocarcinoma', 'Inversion of chromosome 2 produces the EML4-ALK fusion kinase in a subset of lung adenocarcinomas (often young nonsmokers), which respond to the ALK inhibitor crizotinib.'),
('4bae6914-855b-5dad-a014-ed9b1a737894'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Cetuximab is a monoclonal antibody directed against:', '["EGFR","HER2","VEGF","CD20","BRAF"]'::jsonb, 'EGFR', 'Cetuximab blocks the epidermal growth factor receptor and is used in colorectal and head-and-neck cancer, whereas trastuzumab targets HER2, bevacizumab targets VEGF, and rituximab targets CD20.'),
('942cd759-8350-5483-a4d4-b99a3d73619a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Vemurafenib acts as a specific inhibitor of:', '["Mutant BRAF (V600E) kinase","BCR-ABL kinase","EGFR kinase","ALK kinase","VEGFR kinase"]'::jsonb, 'Mutant BRAF (V600E) kinase', 'Vemurafenib selectively inhibits the V600E-mutant BRAF kinase in melanoma, interrupting the overactive MAPK pathway. Imatinib and crizotinib target BCR-ABL/ALK instead.'),
('ec7684b1-2701-5656-b979-f9c8bbe8334f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Rituximab, an anti-CD20 monoclonal antibody, is widely used to treat:', '["B-cell non-Hodgkin lymphomas","Small cell lung carcinoma","Colorectal carcinoma","Ovarian carcinoma","Malignant melanoma"]'::jsonb, 'B-cell non-Hodgkin lymphomas', 'Because CD20 is expressed by nearly all mature B-cell lymphomas, rituximab depletes the malignant B cells and is a cornerstone of DLBCL and follicular lymphoma therapy.'),
('d8916b4e-2844-5527-a13b-04f24e31d983'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In tumor grading, the degree of differentiation refers to:', '["How closely tumor cells resemble their tissue of origin","The extent of nodal spread accompanied by associated clinical symptoms","The size of the primary tumor mediated by specific receptor activation","The time to recurrence without affecting the primary tissue pathway","The serum marker level leading to subsequent cellular adaptation"]'::jsonb, 'How closely tumor cells resemble their tissue of origin', 'Grading is a microscopic assessment of how much a tumor reproduces the structure and cytology of its tissue of origin; well-differentiated tumors recapitulate their tissue and are lower grade.'),
('c4fa2073-3cc6-5e27-8c46-efda60961443'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A well-differentiated tumor is one that:', '["Closely resembles its normal tissue of origin","Shows no resemblance to any normal tissue","Has metastasized widely","Is inevitably benign","Is always high stage"]'::jsonb, 'Closely resembles its normal tissue of origin', 'Well-differentiated tumors recapitulate the architecture and cytology of the parent tissue (e.g., well-formed glands in adenocarcinoma). Poorly differentiated tumors show little resemblance and are higher grade.'),
('0e6ab93d-a466-540e-a0bd-b3f3b7b2a041'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which of the following is NOT a criterion used in histologic tumor grading?', '["Presence of a paraneoplastic syndrome","Degree of differentiation","Nuclear pleomorphism","Mitotic rate","Tumor necrosis"]'::jsonb, 'Presence of a paraneoplastic syndrome', 'Grading assesses differentiation, pleomorphism, mitoses, and necrosis on histology. Paraneoplastic syndromes are clinical remote effects of the tumor and contribute neither to grade nor stage.'),
('66b8959b-c7db-5f6e-8bdd-491e78d0997f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Compared with tumor grade, the stage of a cancer is generally:', '["A more accurate predictor of outcome because it quantifies extent of disease","Irrelevant to treatment decisions accompanied by associated clinical symptoms","Determined solely by light microscopy mediated by specific receptor activation","Unavailable for all solid tumors without affecting the primary tissue pathway","Identical to the grade leading to subsequent cellular adaptation"]'::jsonb, 'A more accurate predictor of outcome because it quantifies extent of disease', 'Because stage measures how far the tumor has actually spread, it correlates more strongly with cure and survival than grade in most cancers; grade describes differentiation, not the extent of disease.'),
('76da4296-8dd0-5518-8a36-7c5e2feb3669'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which of the following is locally aggressive yet almost never metastasizes?', '["Basal cell carcinoma","Invasive ductal carcinoma","Malignant melanoma","Osteosarcoma","Small cell carcinoma"]'::jsonb, 'Basal cell carcinoma', 'Basal cell carcinoma invades and destroys tissue locally but metastasizes only in exceptional cases, unlike ductal carcinoma, melanoma, osteosarcoma, and small cell carcinoma, which spread readily.'),
('e383b4c3-1daf-5942-a9c6-19e5f687d73d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Overall, the most frequent sites of carcinoma metastasis are, in order:', '["Liver, lung, and bone","Bone, brain, and spleen","Lung, spleen, and kidney","Brain, adrenal, and bowel","Skin, muscle, and cartilage"]'::jsonb, 'Liver, lung, and bone', 'Carcinomas metastasize most often to the liver (via portal or systemic flow), the lungs (via the right heart), and bone, reflecting the high blood flow and sinusoidal architecture of these organs.'),
('f3055704-d314-5d67-80cf-4b17877f7010'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The adrenal gland is a common site of metastasis from:', '["Lung and renal cell carcinoma","Prostate and testis only","Bowel and appendix","Thyroid and larynx","Uterus and vulva"]'::jsonb, 'Lung and renal cell carcinoma', 'The highly vascular adrenal medulla is a frequent target of hematogenous metastasis, classically from lung and renal cell carcinoma, sometimes producing adrenal insufficiency when bilateral.'),
('56f2ac35-06bc-5b6b-bcba-eafec0a7d38c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Prostatic carcinoma metastasizes to the axial skeleton via the:', '["Vertebral venous (Batson) plexus","Thoracic duct alone","Portal venous system","Direct implantation","Brachial plexus"]'::jsonb, 'Vertebral venous (Batson) plexus', 'The valveless epidural/vertebral Batson plexus provides a low-pressure route that shunts prostate (and breast) carcinoma cells directly to the spine and pelvis, explaining the axial distribution of its bone metastases.'),
('518d4189-f9c8-5f70-9b98-1152f8d9b84d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Osteosarcoma most often metastasizes first to the:', '["Lungs","Liver","Brain","Contralateral femur","Axillary lymph nodes"]'::jsonb, 'Lungs', 'Osteosarcoma spreads hematogenously, and the lungs are the first and most common site of metastasis; pulmonary surveillance imaging is therefore routine in follow-up.'),
('18e31350-c5b2-5f13-8df6-76659f3fd912'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The ''starry-sky'' histologic appearance of Burkitt lymphoma is produced by:', '["Scattered tingible-body macrophages among a sea of medium-size lymphoma cells","Numerous Reed-Sternberg cells accompanied by associated clinical symptoms","Whorls of spindle cells mediated by specific receptor activation","Psammoma bodies without affecting the primary tissue pathway","Multinucleated osteoclast-like giant cells leading to subsequent cellular adaptation"]'::jsonb, 'Scattered tingible-body macrophages among a sea of medium-size lymphoma cells', 'The dark ''sky'' of closely packed highly proliferative (MYC-driven) Burkitt cells is interrupted by pale ''stars'' of macrophages that have ingested apoptotic debris, producing the starry-sky pattern.'),
('ce0ca2ec-6f2f-50c1-ac13-e91d9c46eb5f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Reed-Sternberg cells classically express:', '["CD15 and CD30","CD20 only","CD3","TdT","CD138"]'::jsonb, 'CD15 and CD30', 'Classic Reed-Sternberg cells are CD15-positive and CD30-positive but usually CD20-negative, distinguishing them from most other large-cell lymphomas.'),
('145d5cbd-5c69-5c8a-a009-c41ee5d3ef9b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Lymphocyte-depleted Hodgkin lymphoma is classically seen in:', '["HIV-infected patients","Children under 5 years","Post-menopausal women","Patients with celiac disease","Adolescent athletes"]'::jsonb, 'HIV-infected patients', 'The lymphocyte-depleted subtype of Hodgkin lymphoma is rare overall but characteristic in immunosuppressed HIV patients, where it is associated with a poor prognosis.'),
('a18b3238-bd3f-5144-b77f-3531fac76cbe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The bone lesions of multiple myeloma are best described as:', '["Punched-out, purely osteolytic lesions with no reactive new bone","Osteoblastic sclerotic lesions","Subperiosteal cysts","Pathologic fractures with exuberant callus","Onion-skin periosteal layering"]'::jsonb, 'Punched-out, purely osteolytic lesions with no reactive new bone', 'Myeloma plasma cells produce RANKL and suppress osteoblasts, giving sharply punched-out lytic skull lesions without new bone formation and a propensity for fracture and hypercalcemia.'),
('9a2d73ca-a6f2-571a-8d99-654124e50984'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Periosteal ''onion-skin'' reactive bone on imaging is classic for:', '["Ewing sarcoma","Osteosarcoma","Chondrosarcoma","Giant cell tumor","Fibrous dysplasia"]'::jsonb, 'Ewing sarcoma', 'Laminated periosteal new bone (''onion skin'') and the sunburst pattern of osteosarcoma are classic radiographic markers of these malignant bone tumors; Ewing''s shows onion-skin layering.'),
('94e41feb-526e-5117-8673-6cdddd13b443'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Giant cell tumor of bone characteristically arises in the:', '["Epiphysis of long bones near the knee","Diaphysis of the femur","Ribs and sternum","Skull vault","Metacarpals only"]'::jsonb, 'Epiphysis of long bones near the knee', 'Giant cell tumor is an epiphyseal tumor of young adults classically around the knee (distal femur, proximal tibia). Osteosarcoma instead arises in the metaphysis and Ewing''s in the diaphysis.'),
('b707a8ad-6459-5997-a068-e7354b1c9a6e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Ewing sarcoma most commonly presents in:', '["Adolescents and young adults (about 5-20 years)","Infants under 1 year accompanied by associated clinical symptoms","Adults aged 40-60 mediated by specific receptor activation","Elderly patients over 70 without affecting the primary tissue pathway","Pregnant women leading to subsequent cellular adaptation"]'::jsonb, 'Adolescents and young adults (about 5-20 years)', 'Ewing sarcoma is the second most common bone tumor of childhood and adolescence, usually presenting in the second decade with pain and swelling in the diaphysis of long bones.'),
('ab4efd83-fd6b-5240-9de1-4e41ee67d731'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most common soft-tissue sarcoma of childhood is:', '["Rhabdomyosarcoma","Liposarcoma","Leiomyosarcoma","Synovial sarcoma","Malignant peripheral nerve sheath tumor"]'::jsonb, 'Rhabdomyosarcoma', 'Rhabdomyosarcoma, a tumor of skeletal muscle lineage, is the most common soft-tissue sarcoma of children, with embryonal, alveolar, pleomorphic, and spindle variants.'),
('f14a0c77-71af-5bed-8e5a-707a67e70a0b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Liposarcoma most commonly arises in the:', '["Deep soft tissues of the retroperitoneum and thigh","Skin of the trunk accompanied by associated clinical symptoms","Bones of the hands mediated by specific receptor activation","Peripheral lymph nodes without affecting the primary tissue pathway","Peritoneal cavity alone leading to subsequent cellular adaptation"]'::jsonb, 'Deep soft tissues of the retroperitoneum and thigh', 'Liposarcoma is one of the most common sarcomas of adults and typically arises in deep soft tissue of the retroperitoneum and thigh, growing large before detection.'),
('b528a19d-5047-50f1-b013-be2592bc1673'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A leiomyoma is a benign tumor of:', '["Smooth muscle","Striated skeletal muscle","Adipose tissue","Cartilage","Peripheral nerve sheath"]'::jsonb, 'Smooth muscle', 'Leiomyomas are benign smooth-muscle tumors, most commonly uterine fibroids; rhabdomyomas consist of striated muscle and lipomas of adipose tissue.'),
('d7d01073-8227-5adf-b2e1-5e512f3b0eb0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Fibroadenoma of the breast is composed of:', '["Both epithelial and stromal components","Smooth muscle only","Adipose tissue only","Cartilage only","Neural tissue only"]'::jsonb, 'Both epithelial and stromal components', 'Fibroadenoma is a benign ''mixed'' tumor with proliferating glands and fibrous stroma, the most common breast tumor of young women and responsive to estrogen.'),
('e7e143c2-de64-5b6d-8054-e8d889a9cdaa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A capillary hemangioma is:', '["A benign vascular tumor common in infants","A malignant endothelial neoplasm","A lymphatic malformation","A neural-crest tumor","A blood coagulation disorder"]'::jsonb, 'A benign vascular tumor common in infants', 'Capillary (juvenile) hemangiomas are benign proliferations of endothelium that appear in infancy and usually regress spontaneously. Hemangiosarcomas are the malignant endothelial tumors.'),
('49be7c9c-c6c4-5633-b8f6-b86e70466fe6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Meningiomas arise from:', '["Meningothelial (arachnoid cap) cells","Astrocytes","Oligodendrocytes","Choroid plexus epithelium","Ventricular ependyma"]'::jsonb, 'Meningothelial (arachnoid cap) cells', 'Meningiomas derive from the meningothelial cells of the arachnoid membrane, are usually benign and slow-growing, and typically present as extra-axial dural-based mass lesions in adults.'),
('c543e69e-34e4-5040-9fe7-951496fd76a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A schwannoma is a benign tumor of:', '["Peripheral nerve sheath (Schwann cells)","Smooth muscle accompanied by associated clinical symptoms","Adipose tissue mediated by specific receptor activation","Bone without affecting the primary tissue pathway","Blood vessels leading to subsequent cellular adaptation"]'::jsonb, 'Peripheral nerve sheath (Schwann cells)', 'Schwannomas are benign encapsulated tumors of Schwann cells that often arise on the eighth nerve (acoustic neuroma); both acoustic neuromas are seen in neurofibromatosis type 2.'),
('e9d80325-2e74-55b8-a80c-33e3f371c9d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Glioblastoma (IDH-wildtype) characteristically shows amplification of:', '["EGFR, often with PTEN loss","MYC accompanied by associated clinical symptoms","BCR-ABL mediated by specific receptor activation","BCL-2 without affecting the primary tissue pathway","c-KIT leading to subsequent cellular adaptation"]'::jsonb, 'EGFR, often with PTEN loss', 'The canonical genetic events in IDH-wildtype glioblastoma are EGFR amplification, loss of PTEN, and inactivation of TP53 and CDKN2A, distinguishing it from IDH-mutant astrocytomas.'),
('1fc0962f-2341-578b-bbc3-0748c2d03c1a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The RB1 gene is located on chromosome:', '["13q14","17p13","5q21","18q21","9p21"]'::jsonb, '13q14', 'RB1 maps to the long arm of chromosome 13 (13q14); deletion or mutation of this locus underlies both hereditary and sporadic retinoblastoma.'),
('fe9dc606-153e-503b-8743-55ecf92edfa6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The TP53 gene is located on chromosome:', '["17p13","13q14","5q21","18q21","9p21"]'::jsonb, '17p13', 'TP53 maps to the short arm of chromosome 17 (17p13); loss of 17p is a frequent event in colorectal and many other cancers, inactivating the p53 tumor suppressor.'),
('2722027d-13aa-5ff5-a6e4-49c9a4cd1ac7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The APC gene is located on chromosome:', '["5q21","17p13","13q14","9p21","11p13"]'::jsonb, '5q21', 'APC maps to 5q21, and germline loss underlies familial adenomatous polyposis while somatic loss initiates most sporadic colorectal adenomas.'),
('36b0370f-6a7e-525b-a428-1355608268f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The WT1 gene, mutated in some Wilms tumors, maps to chromosome:', '["11p13","13q14","5q21","17p13","9p21"]'::jsonb, '11p13', 'WT1, a transcription factor critical to renal and gonadal development, is located at 11p13; its germline deletion causes the WAGR syndrome of Wilms tumor, aniridia, genitourinary anomalies, and retardation.'),
('f44f54e0-17ab-5b16-8dd7-f812d7d0e5bc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In hereditary retinoblastoma, the ''second hit'' is:', '["A somatic event (mutation or LOH) that inactivates the remaining normal RB1 allele","Inherited from the father accompanied by associated clinical symptoms","Always a chromosomal translocation mediated by specific receptor activation","The loss of p53 without affecting the primary tissue pathway","A methylation of TP53 leading to subsequent cellular adaptation"]'::jsonb, 'A somatic event (mutation or LOH) that inactivates the remaining normal RB1 allele', 'The inherited germline RB1 mutation is the first hit present in all cells; a somatic second event in a retinal cell, such as loss of heterozygosity or a new mutation, completes biallelic inactivation.'),
('55d1d613-8610-5e82-a127-cb9d3f1a15b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A pancreatic islet tumor that secretes insulin and produces hypoglycemia is a(n):', '["Insulinoma","Gastrinoma","Glucagonoma","Somatostatinoma","VIPoma"]'::jsonb, 'Insulinoma', 'Insulinomas are functional beta-cell tumors that cause fasting hypoglycemia with elevated insulin levels; the other islet tumors cause distinct syndromes (Zollinger-Ellison, diabetes and rash, watery diarrhea).'),
('19de4c4a-7346-5185-ac7a-f95530809faf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Neurofibromin, the product of NF1, normally functions as:', '["A GTPase-activating protein (GAP) for RAS","A receptor tyrosine kinase","A cyclin-dependent kinase","A DNA methylase","A transcriptional repressor"]'::jsonb, 'A GTPase-activating protein (GAP) for RAS', 'Neurofibromin accelerates RAS GTP hydrolysis, damping RAS signaling; loss of neurofibromin in NF1 leaves RAS persistently active, promoting Schwann cell and melanocyte tumors.'),
('5ae0f324-8ba1-58c6-ab60-938d9cf48139'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The PTEN tumor suppressor inhibits growth by:', '["Dephosphorylating PIP3 to oppose PI3K/AKT signaling","Activating RAS accompanied by associated clinical symptoms","Inhibiting p53 mediated by specific receptor activation","Repairing DNA damage without affecting the primary tissue pathway","Blocking telomerase leading to subsequent cellular adaptation"]'::jsonb, 'Dephosphorylating PIP3 to oppose PI3K/AKT signaling', 'PTEN is a lipid phosphatase that converts PIP3 back to PIP2, turning off the PI3K-AKT survival pathway; its loss (Cowden syndrome or somatically) hyperactivates AKT and drives cancer.'),
('76b914ae-883e-5154-ab54-14f98e3995e0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The NF2 product merlin belongs to which protein family?', '["The ezrin-radixin-moesin (ERM) family that links the membrane to the actin cytoskeleton","The collagen family accompanied by associated clinical symptoms","The proteoglycan family mediated by specific receptor activation","The immunoglobulin superfamily without affecting the primary tissue pathway","The HLA antigens leading to subsequent cellular adaptation"]'::jsonb, 'The ezrin-radixin-moesin (ERM) family that links the membrane to the actin cytoskeleton', 'Merlin is an ERM-family protein that anchors membrane proteins to the cytoskeleton and regulates cell contact-dependent growth; its loss underlies neurofibromatosis type 2.'),
('327082d1-fca6-5d7e-ab7d-ff2676179d5b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Under normoxic conditions, the VHL protein targets which factor for degradation?', '["HIF-1alpha","p53","RAS","c-MYC","Cyclin D1"]'::jsonb, 'HIF-1alpha', 'In the presence of oxygen, VHL ubiquitinates and degrades HIF-1alpha; when VHL is lost, HIF-1alpha accumulates even in normoxia and drives a pseudo-hypoxic transcriptional program.'),
('fae64cf5-8753-5c43-aa05-ae57e89bcdde'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Loss of VHL with accumulation of HIF-1alpha leads to:', '["Increased expression of VEGF, PDGF, and erythropoietin","Suppression of all angiogenic factors","Degradation of E-cadherin","Activation of mismatch repair","Only immune evasion"]'::jsonb, 'Increased expression of VEGF, PDGF, and erythropoietin', 'HIF-1alpha transactivates angiogenic and erythropoietic genes (VEGF, PDGF, EPO), explaining the hypervascularity of clear cell renal cell carcinoma and the erythrocytosis it may cause.'),
('7ad75df3-84dc-5391-b97d-a3cb3f3012e2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Constitutive WNT-beta-catenin signaling from APC loss upregulates which downstream targets?', '["c-MYC and cyclin D1","BCL-2 only","TP53 production","RAS phosphatases","erbB receptors"]'::jsonb, 'c-MYC and cyclin D1', 'Stabilized beta-catenin translocates to the nucleus and, with TCF/LEF, transcribes growth-promoting genes such as c-MYC and cyclin D1, connecting APC loss to oncogene-driven proliferation.'),
('cdc25161-4463-5a11-ad3c-ef659935f5b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Loss of which component of TGF-beta signaling is common in colorectal carcinoma?', '["SMAD2/SMAD4 on chromosome 18q","RAS activation of GTPase","p16 expression","RB phosphorylation","E2F transcription"]'::jsonb, 'SMAD2/SMAD4 on chromosome 18q', 'Deletion of 18q removes the SMAD2/SMAD4 mediators of TGF-beta''s growth-inhibitory signal (along with DCC), so colon cancers escape TGF-beta suppression as part of the adenoma-carcinoma sequence.'),
('0db1e8da-cd89-5784-ba7d-5d6aec9dd4ff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which chromosomal arm, harboring DCC and SMAD4, is commonly lost in colorectal and pancreatic carcinoma?', '["18q","5q","13q","17p","9p"]'::jsonb, '18q', 'Loss of the long arm of chromosome 18 deletes the DCC and SMAD4 genes; SMAD4 loss perturbs TGF-beta signaling and is frequent in both colorectal and pancreatic carcinoma.'),
('eeb34ee8-017f-55e6-8bd8-4e3f9ce0d123'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The combination of alcohol and tobacco has a multiplicative synergistic effect in causing:', '["Esophageal (squamous) and laryngeal carcinoma","Breast carcinoma accompanied by associated clinical symptoms","Renal cell carcinoma mediated by specific receptor activation","Malignant melanoma without affecting the primary tissue pathway","Thyroid carcinoma leading to subsequent cellular adaptation"]'::jsonb, 'Esophageal (squamous) and laryngeal carcinoma', 'Alcohol and tobacco together act synergistically to cause squamous carcinoma of the esophagus, larynx, and oral cavity, with the combination multiplying risk beyond each agent alone.'),
('972f2e9d-be38-5b77-8ceb-521357538991'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Chewing betel quid (areca nut) is a strong risk factor for:', '["Oral squamous cell carcinoma","Cervical carcinoma","Gastric lymphoma","Bladder carcinoma","Lung adenocarcinoma"]'::jsonb, 'Oral squamous cell carcinoma', 'Areca nut and betel-leaf chewing are major causes of oral submucous fibrosis and oral squamous cell carcinoma in South Asia, where oral cancer is common.'),
('cdd99384-e292-5ab1-9eeb-73e31881e119'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A long-standing calcified (porcelain) gallbladder predisposes to:', '["Gallbladder carcinoma","Pancreatic carcinoma","Cholangiocarcinoma of the duct only","Ampullary carcinoma","Hepatocellular carcinoma"]'::jsonb, 'Gallbladder carcinoma', 'Chronic cholecystitis leading to a diffusely calcified (porcelain) gallbladder carries a substantial risk of gallbladder adenocarcinoma, making prophylactic cholecystectomy reasonable.'),
('3c053a5c-ca08-53ee-bb8b-50d800dfb7e2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Primary sclerosing cholangitis is a well-established risk factor for:', '["Cholangiocarcinoma","Gallbladder carcinoma only","Hepatocellular carcinoma only","Pancreatic endocrine tumor","Gastric carcinoid"]'::jsonb, 'Cholangiocarcinoma', 'PSC, an inflammatory stricturing disease of the bile ducts often associated with ulcerative colitis, markedly increases the risk of cholangiocarcinoma, which may be detected during surveillance.'),
('5d0b7838-acf1-502d-abb5-928b13e0f2b7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Schistosoma haematobium infection is classically linked to:', '["Squamous cell carcinoma of the urinary bladder","Transitional cell carcinoma of the renal pelvis only","Prostate adenocarcinoma","Urethral carcinoma","Renal cell carcinoma"]'::jsonb, 'Squamous cell carcinoma of the urinary bladder', 'In endemic regions, chronic S. haematobium cystitis predisposes to squamous cell carcinoma of the bladder, whereas tobacco and aromatic amines cause transitional cell carcinoma.'),
('c8460fca-4d53-5667-bcd8-a29051a9334b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Squamous cell carcinoma may arise in:', '["Chronically draining sinus tracts (e.g., chronic osteomyelitis)","Normal gastric mucosa accompanied by associated clinical symptoms","Normal synovium mediated by specific receptor activation","The ureter without inflammation without affecting the primary tissue pathway","Myocardium leading to subsequent cellular adaptation"]'::jsonb, 'Chronically draining sinus tracts (e.g., chronic osteomyelitis)', 'Long-standing inflammation in sinus tracts from chronic osteomyelitis or burns can give rise to squamous cell carcinoma, reflecting persistent irritation and repair predisposing to malignancy.'),
('f993ef99-dff9-5c2e-a440-8ace2b061f4f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A carcinoma arising in a chronic burn scar (Marjolin ulcer) is classically a:', '["Well-differentiated squamous cell carcinoma","Malignant melanoma accompanied by associated clinical symptoms","Basal cell carcinoma mediated by specific receptor activation","Merkel cell carcinoma without affecting the primary tissue pathway","Kaposi sarcoma leading to subsequent cellular adaptation"]'::jsonb, 'Well-differentiated squamous cell carcinoma', 'Marjolin ulcer is a squamous cell carcinoma that develops decades after a burn injury, growing within the scar and carrying a worse prognosis than sun-related skin cancer.'),
('28d03a2b-42b1-5394-a9c7-bc6d82ec6108'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'HPV-16 infection is an emerging major cause of oropharyngeal carcinoma in:', '["Nonsmoking younger adults, especially of the tonsil and base of tongue","Elderly heavy smokers accompanied by associated clinical symptoms","Children under 10 mediated by specific receptor activation","Women with cervical cancer without affecting the primary tissue pathway","Nasopharyngeal-endemic populations leading to subsequent cellular adaptation"]'::jsonb, 'Nonsmoking younger adults, especially of the tonsil and base of tongue', 'HPV-related oropharyngeal squamous carcinoma is increasing in younger, nonsmoking adults and differs biologically and prognostically (better survival) from tobacco-associated disease.'),
('b67a9015-2e82-5121-8e97-6ebdb9400f13'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'EBV-associated gastric adenocarcinoma is characterized by:', '["Prominent lymphocytic infiltration and a hypermethylated phenotype","Psammoma bodies and calcification","Keratin pearls and intercellular bridges","Small cell neuroendocrine morphology","Extensive sarcomatous change"]'::jsonb, 'Prominent lymphocytic infiltration and a hypermethylated phenotype', 'About 10% of gastric cancers are EBV-associated and show dense lymphocytic infiltration, PD-L1 expression, and CpG-island hypermethylation, features linked to a good prognosis.'),
('c6f90130-c1d4-59c0-901f-b4b9d82519ac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Compared with small cell carcinoma, a typical carcinoid tumor is:', '["Well-differentiated, slow-growing, and far less aggressive","Highly proliferative with a very high Ki-67","Centrally necrotic and metastasizes quickly","Always associated with ectopic ACTH","Anaplastic with marked nuclear atypia"]'::jsonb, 'Well-differentiated, slow-growing, and far less aggressive', 'Typical carcinoid tumors are well-differentiated neuroendocrine neoplasms with a low proliferative index and excellent prognosis, in contrast to the highly aggressive small cell carcinoma.'),
('f26c1cf8-fe1d-5f03-89c3-abf3164fcad0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'In MEN type 2, medullary thyroid carcinoma is driven by an activating germline mutation of:', '["RET","RAS","BRAF","EGFR","VHL"]'::jsonb, 'RET', 'Germline gain-of-function RET mutations cause medullary thyroid carcinoma in MEN 2A and 2B, with prophylactic thyroidectomy guided by RET testing in affected families.'),
('97170246-f572-5d48-a5d6-d72ad3f194f1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'A carotid body tumor (chemodectoma) is a:', '["Paraganglioma of neuroendocrine origin","Salivary gland tumor","Smooth-muscle tumor","Vascular malformation","B-cell lymphoma"]'::jsonb, 'Paraganglioma of neuroendocrine origin', 'The carotid body paraganglioma is a neuroendocrine (chemodectoma) tumor related to pheochromocytoma of the adrenal medulla and may be functional, secreting catecholamines.'),
('6bc0fe64-1d77-5b32-80e2-f788afd71037'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Positive staining for chromogranin and synaptophysin identifies tumors with:', '["Neuroendocrine differentiation","Squamous differentiation","Mucin production","Melanogenesis","Striated muscle differentiation"]'::jsonb, 'Neuroendocrine differentiation', 'Chromogranin and synaptophysin are markers of neurosecretory granules, so their positivity confirms neuroendocrine differentiation (carcinoid, small cell carcinoma, pheochromocytoma).'),
('a8a437ef-d732-5a93-99fb-cfcc0fdcd5d7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Keratin pearls and intercellular bridges on histology are diagnostic features of:', '["Squamous differentiation (squamous cell carcinoma)","Glandular differentiation accompanied by associated clinical symptoms","Neuroendocrine tumors mediated by specific receptor activation","Clear cell tumors without affecting the primary tissue pathway","Signet-ring cell tumors leading to subsequent cellular adaptation"]'::jsonb, 'Squamous differentiation (squamous cell carcinoma)', 'Well-differentiated squamous cell carcinoma shows keratin pearls and desmosomal intercellular bridges, features of squamous differentiation, seen in skin, lung, esophagus, and cervix.'),
('0623d1c1-bfad-5ea2-af29-d50fb2056a8d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Signet-ring cells are characteristic of:', '["Diffuse gastric carcinoma and lobular breast carcinoma","Squamous cell carcinoma accompanied by associated clinical symptoms","Follicular lymphoma mediated by specific receptor activation","Jurkat-like T-cell lymphoma without affecting the primary tissue pathway","Osteosarcoma leading to subsequent cellular adaptation"]'::jsonb, 'Diffuse gastric carcinoma and lobular breast carcinoma', 'Signet-ring cells are cells with a large mucin vacuole displacing the nucleus to the rim; they define diffuse (limits plastica) gastric carcinoma and are classically seen in lobular breast carcinoma with E-cadherin loss.'),
('ef6a23dc-c1d8-50a2-8841-181f839ace7a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Scrotal carcinoma in chimney sweeps was historically important because it was:', '["The first recognized occupational chemical carcinogen (soot and polyaromatic hydrocarbons)","The first recognized viral tumor accompanied by associated clinical symptoms","An inherited neoplastic disorder mediated by specific receptor activation","A radiation-induced tumor without affecting the primary tissue pathway","A purely dietary tumor leading to subsequent cellular adaptation"]'::jsonb, 'The first recognized occupational chemical carcinogen (soot and polyaromatic hydrocarbons)', 'Percival Pott''s description of scrotal cancer in chimney sweeps in 1775 established the concept of occupational chemical carcinogenesis, later traced to polyaromatic hydrocarbons in soot.'),
('6fa2ba44-81f7-5a4a-902f-746724cea803'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Cytotoxic chemotherapy with alkylating agents can cause a therapy-related:', '["Acute myeloid leukemia, often with losses of chromosomes 5 and 7","Hodgkin lymphoma accompanied by associated clinical symptoms","Malignant melanoma mediated by specific receptor activation","Basal cell carcinoma without affecting the primary tissue pathway","Gastric carcinoid leading to subsequent cellular adaptation"]'::jsonb, 'Acute myeloid leukemia, often with losses of chromosomes 5 and 7', 'Alkylating agents damage DNA and can produce therapy-related AML with characteristic deletions of chromosomes 5 and 7, appearing 5-10 years or more after treatment.'),
('f5668112-ae66-5f6a-bac9-8c58978663cc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Desmoid-type fibromatosis is best described as:', '["A locally aggressive, non-metastasizing fibrous neoplasm","A high-grade sarcoma with frequent metastases","A benign lipoma","A reactive hypertrophic scar","A lymphatic malformation"]'::jsonb, 'A locally aggressive, non-metastasizing fibrous neoplasm', 'Desmoid tumors invade and recur locally but never metastasize, occupying a biologic middle ground between benign fibrous proliferations and fibrosarcoma.'),
('d2189669-3092-5c84-af6e-963a3828af51'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The distinction between leukemia and lymphoma rests on:', '["Diffuse bone-marrow involvement (leukemia) versus tissue-based masses (lymphoma)","Epithelial versus mesenchymal origin accompanied by associated clinical symptoms","Melanocytic versus neural origin mediated by specific receptor activation","Bone-forming versus blood-forming tissue without affecting the primary tissue pathway","Endocrine versus exocrine origin leading to subsequent cellular adaptation"]'::jsonb, 'Diffuse bone-marrow involvement (leukemia) versus tissue-based masses (lymphoma)', 'Leukemias are disseminated marrow-based neoplasms of hematopoietic cells that enter peripheral blood, whereas lymphomas present as solid masses; once lymphoma cells spread widely in blood it is called leukemic phase.'),
('4c7c1f62-bec0-5fd4-be2c-2b3fafa2c7f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Which of the following entities is by its very nature benign?', '["A true hamartoma","Osteosarcoma","Hodgkin lymphoma","Malignant melanoma","Adenocarcinoma"]'::jsonb, 'A true hamartoma', 'Hamartomas are non-neoplastic, disorganized overgrowths of mature tissue and never behave malignantly, unlike carcinoma, sarcoma, melanoma, and lymphoma.'),
('66e3cbcd-8d6c-5126-874c-806371c28e84'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'Adenomas differ from adenocarcinomas chiefly by:', '["The absence of invasion and metastasis","Their location within the lung","A papillary growth pattern","The production of mucin","The age of the patient"]'::jsonb, 'The absence of invasion and metastasis', 'Both are glandular tumors; only the adenocarcinoma invades basement membrane and metastasizes, which is the operational distinction between a benign adenoma and a malignant glandular cancer.'),
('49b7572a-8f73-5a6f-8b87-c9673289b79e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'General Pathology - Neoplasia', 'The most reliable evidence of malignancy in a biopsy is:', '["Invasion through the basement membrane or the presence of metastasis","Cellular enlargement of individual cells accompanied by associated clinical symptoms","Nuclear hyperchromasia alone mediated by specific receptor activation","Frequent mitotic figures without affecting the primary tissue pathway","A papillary architectural pattern leading to subsequent cellular adaptation"]'::jsonb, 'Invasion through the basement membrane or the presence of metastasis', 'Invasive growth and metastasis are the absolute criteria of malignancy. Nuclear atypia, hyperchromasia, and mitoses occur in dysplasia and some reactive processes and are not by themselves diagnostic.'),
('8101c2f9-60e0-581e-acdb-e14aa9a02932'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Bacillus anthracis is best described as a(n):', '["Gram-negative rod","Gram-positive spore-forming rod","Gram-positive coccus","Acid-fast bacillus","Spiral bacterium"]'::jsonb, 'Gram-positive spore-forming rod', 'B. anthracis is a large Gram-positive rod that forms resistant endospores; it is non-motile and non-hemolytic.'),
('aa61479d-23fc-5140-8475-782f55a7cee9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which toxin is responsible for the pathogenesis of Bacillus anthracis?', '["Cholera toxin","Anthrax toxin (PA LF EF)","Tetanus toxin","Botulinum toxin","Diphtheria toxin"]'::jsonb, 'Anthrax toxin (PA LF EF)', 'The tripartite anthrax toxin consists of protective antigen (PA), lethal factor (LF) and edema factor (EF); LF and EF enter host cells only after binding to PA.'),
('8f31988d-d5d1-522a-b34a-0d8c16ed7ad3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The hallmark lesion of cutaneous anthrax is:', '["Painless black eschar","Painful ulcer","Vesicular rash","Necrotizing fasciitis","Petechial rash"]'::jsonb, 'Painless black eschar', 'Cutaneous anthrax begins as a painless papule that vesiculates and ulcerates into a black eschar (''malignant pustule'') with surrounding edema; painlessness distinguishes it from staphylococcal lesions.'),
('668b620b-16d1-53fb-af54-b1546f776973'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Inhalational anthrax characteristically presents with:', '["Community-acquired pneumonia resulting in decreased functional activity","Hemorrhagic mediastinitis with widened mediastinum","Lung abscess mediated by specific receptor activation","Pleural effusion alone without affecting the primary tissue pathway","Bronchitis leading to subsequent cellular adaptation"]'::jsonb, 'Hemorrhagic mediastinitis with widened mediastinum', 'Inhaled spores are transported to mediastinal lymph nodes where toxin release causes hemorrhagic mediastinitis and widening of the mediastinum, rather than a true primary pneumonia.'),
('385328eb-e074-5991-8ecc-279809456f38'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A single Gram-positive spore-forming bacillus causes two foodborne syndromes: a short-incubation vomiting illness and a longer-incubation watery diarrheal illness. Which entity encompasses both presentations?', '["Anthrax resulting in decreased functional activity","Pseudomembranous colitis accompanied by associated clinical symptoms","Tetanus mediated by specific receptor activation","Gas gangrene without affecting the primary tissue pathway","Food poisoning (emetic and diarrheal forms)"]'::jsonb, 'Food poisoning (emetic and diarrheal forms)', 'B. cereus causes an emetic form (cereulide toxin, 1-6 h incubation) and a diarrheal form (heat-labile enterotoxin, 8-16 h), the two presentations of its food poisoning.'),
('c88649a2-7fbc-5121-b9d2-02c0f413c8a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The emetic toxin of Bacillus cereus is best characterized as a(n):', '["Superantigen","Lipopolysaccharide","Heat-stable preformed toxin","Neurotoxin","Heat-labile enterotoxin"]'::jsonb, 'Heat-stable preformed toxin', 'Cereulide is a heat-stable dodecadepsipeptide preformed in food, so it survives reheating and acts rapidly after ingestion to cause vomiting.'),
('fef0d96a-1e4e-52f8-8670-b7e2ed1a405b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which morphologic feature is most characteristic of Clostridium tetani?', '["Branching filamentous resulting in decreased functional activity","Acid-fast bacillus accompanied by associated clinical symptoms","Gram-negative rod mediated by specific receptor activation","Gram-positive spore-forming rod with drumstick appearance","Gram-positive coccus leading to subsequent cellular adaptation"]'::jsonb, 'Gram-positive spore-forming rod with drumstick appearance', 'C. tetani is a Gram-positive rod with a strictly terminal spherical spore that gives the cell a drumstick (tennis-racket) appearance.'),
('35f31f33-3bad-558e-bddd-a59874aaa694'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tetanospasmin (tetanus toxin) produces its paralytic effect by:', '["Stimulating ACh release","Blocking Na channels","Blocking inhibitory neurotransmitters (GABA glycine)","Depolarizing muscle membranes","Blocking ACh release at neuromuscular junction"]'::jsonb, 'Blocking inhibitory neurotransmitters (GABA glycine)', 'Tetanospasmin blocks presynaptic release of GABA and glycine in the spinal cord, removing inhibition of alpha motor neurons and causing unopposed muscle contraction (spastic paralysis).'),
('20c8b873-54ab-54fd-bdf2-0f4ce13ad1ce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tetanus toxin reaches the central nervous system via:', '["Hematogenous route","Direct extension","Lymphatic spread","Retrograde axonal transport","Across the blood-brain barrier"]'::jsonb, 'Retrograde axonal transport', 'The toxin binds presynaptic terminals at the neuromuscular junction and is carried retrogradely along motor axons to the spinal cord and brainstem.'),
('74ba295c-1210-5392-9af2-4bc3df0af923'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'All of the following are features of generalized tetanus EXCEPT:', '["Flaccid paralysis","Risus sardonicus","Muscle rigidity","Opisthotonos","Trismus (lockjaw)"]'::jsonb, 'Flaccid paralysis', 'Tetanus produces spastic hypertonic paralysis (trismus, risus sardonicus, opisthotonos); flaccid paralysis is the hallmark of botulism, not tetanus.'),
('31bbffef-4b45-5c72-8056-48ef234e8b2a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Foodborne botulism results from ingestion of:', '["Preformed botulinum toxin in the food","Live vegetative C. botulinum cells","C. botulinum spores alone","Bacterial endotoxin","D-glutamate capsule"]'::jsonb, 'Preformed botulinum toxin in the food', 'In foodborne botulism the neurotoxin is produced in the food before ingestion; because the toxin is heat-labile, adequate heating of the food prevents disease.'),
('2f22d41e-9e6f-508c-a59d-5de4bcbcbf2c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Botulinum toxin causes paralysis by:', '["Blocking ACh release at neuromuscular junction","Blocking GABA receptors","Blocking Ca channels","Blocking Na channels","Stimulating glycine release"]'::jsonb, 'Blocking ACh release at neuromuscular junction', 'The toxin is a zinc metalloprotease that cleaves SNARE proteins, preventing presynaptic release of acetylcholine at the motor end-plate and producing flaccid paralysis.'),
('9592ef61-6e72-59d6-882d-cb6a418cd4bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Infant botulism develops through which mechanism?', '["Inhalation of spores resulting in decreased functional activity","Ingestion of spores that germinate in the gut","Ingestion of preformed toxin mediated by specific receptor activation","Injection without affecting the primary tissue pathway","Wound contamination leading to subsequent cellular adaptation"]'::jsonb, 'Ingestion of spores that germinate in the gut', 'In infants, ingested C. botulinum spores germinate in the immature colon and produce toxin in vivo (often from honey), causing constipation and hypotonia.'),
('cb0e49f6-1f9c-5b86-b6bc-cd18ba26a2ad'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Foodborne botulism classically presents with:', '["Paraesthesia resulting in decreased functional activity","Hemiplegia accompanied by associated clinical symptoms","Descending flaccid paralysis with no sensory loss","Ascending flaccid paralysis with paresthesia without affecting the primary tissue pathway","Spastic paralysis leading to subsequent cellular adaptation"]'::jsonb, 'Descending flaccid paralysis with no sensory loss', 'Cranial nerve palsies (diplopia, dysphagia) are followed by symmetric descending flaccid paralysis; sensation, consciousness and fever are characteristically unaffected.'),
('0e6cb99e-ffc4-5a95-aa2a-6d8c5a537dac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Clostridium perfringens is the most common cause of:', '["Gas gangrene (myonecrosis)","Anthrax","Pseudomembranous colitis","Botulism","Tetanus"]'::jsonb, 'Gas gangrene (myonecrosis)', 'C. perfringens proliferates in devascularized anaerobic tissue and, via its alpha toxin (phospholipase C), produces the extensive myonecrosis of gas gangrene.'),
('e9924742-f71d-5b80-9da2-2898e42f522f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The toxin chiefly responsible for the tissue destruction of clostridial gas gangrene is:', '["Botulinum toxin resulting in decreased functional activity","Neurotoxin accompanied by associated clinical symptoms","Tetanospasmin mediated by specific receptor activation","Alpha toxin (lecithinase/phospholipase C)","Enterotoxin leading to subsequent cellular adaptation"]'::jsonb, 'Alpha toxin (lecithinase/phospholipase C)', 'Alpha toxin hydrolyzes membrane lecithin (phospholipase C activity), destroying cell membranes and producing the muscle necrosis and gas seen in gas gangrene.'),
('3f1f95a5-2169-5f87-863b-398cec8e53eb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which toxin is a lecithinase (phospholipase C) that destroys cell membranes and is the principal virulence factor of clostridial gas gangrene?', '["Botulinum toxin","Diphtheria toxin","Tetanus toxin","Enterotoxin of C. difficile","Alpha toxin of C. perfringens"]'::jsonb, 'Alpha toxin of C. perfringens', 'The alpha toxin of C. perfringens is a phospholipase C/lecithinase that hydrolyzes membrane lecithin and drives the tissue destruction and spread of gas gangrene.'),
('b30ee423-67ad-5417-abc4-b23adec33c3a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A patient develops watery, non-bloody stools for 24-48 hours beginning about 8-16 hours after a meat meal, without fever or vomiting. Which presentation is described?', '["Paralytic ileus","Neurologic symptoms","Hemorrhagic colitis","Self-limited watery diarrhea","Bloody diarrhea"]'::jsonb, 'Self-limited watery diarrhea', 'Watery non-bloody diarrhea with an 8-16 h incubation, without fever or vomiting, characterizes the diarrheal form of B. cereus or C. perfringens food poisoning.'),
('b0689f9b-5036-5181-a2c0-2257e981a23a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A hospitalized patient develops fever and profuse watery diarrhea after two weeks of broad-spectrum antibiotics, and colonoscopy shows raised yellow-white plaques. Which condition is this?', '["Gas gangrene resulting in decreased functional activity","Tetanus accompanied by associated clinical symptoms","Botulism mediated by specific receptor activation","Food poisoning without affecting the primary tissue pathway","Antibiotic-associated pseudomembranous colitis"]'::jsonb, 'Antibiotic-associated pseudomembranous colitis', 'Antibiotic suppression of the normal colonic flora allows C. difficile to overgrow; its toxins A and B damage the colonic epithelium and generate the characteristic pseudomembranes.'),
('f41a6783-bd15-534e-bfd3-0803e28ae85e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Clostridium difficile produces which exotoxins?', '["Alpha toxin and beta toxin","Tetanospasmin and botulinum","Diphtheria toxin and exotoxin A","Exotoxin A and exotoxin S","Toxin A (enterotoxin) and Toxin B (cytotoxin)"]'::jsonb, 'Toxin A (enterotoxin) and Toxin B (cytotoxin)', 'C. difficile elaborates toxin A (enterotoxin) and toxin B (cytotoxin); toxin B causes most of the mucosal injury in pseudomembranous colitis.'),
('b2073402-e154-56bf-ae18-0e2ef1871998'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The drug of choice for C. difficile colitis is:', '["Clindamycin resulting in decreased functional activity","Metronidazole or vancomycin (oral)","Ceftriaxone mediated by specific receptor activation","Ciprofloxacin without affecting the primary tissue pathway","Amoxicillin leading to subsequent cellular adaptation"]'::jsonb, 'Metronidazole or vancomycin (oral)', 'Oral vancomycin (or fidaxomicin) is preferred; oral metronidazole is an option for mild disease. The offending antibiotic must also be stopped.'),
('d6ef71db-273d-5a59-a9a7-5ce4fe3e412c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin blocks acetylcholine release by cleaving SNARE proteins, producing descending flaccid paralysis?', '["Clostridium botulinum","Clostridium tetani","Bacillus anthracis","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Clostridium botulinum', 'Botulinum toxin is a zinc metalloprotease that cleaves SNARE proteins (SNAP-25, VAMP), so ACh cannot be released and muscle becomes paralyzed.'),
('6cb7a6bc-9e01-59d9-be87-9cd094528431'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Botulism from home-canned food is best prevented by:', '["Adequate food canning and heating","Boiling water","Avoiding soil exposure","Vaccination","Hand washing"]'::jsonb, 'Adequate food canning and heating', 'Proper pressure canning destroys C. botulinum spores and adequate heating inactivates the heat-labile toxin; these are the main preventive measures against botulism.'),
('37858b27-48d1-5674-aa1a-1957a131dc82'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tetanus is prevented by immunization with:', '["Oral polio vaccine","Hepatitis B vaccine","BCG vaccine","MMR vaccine","Tetanus toxoid vaccine"]'::jsonb, 'Tetanus toxoid vaccine', 'Tetanus toxoid (formalin-inactivated tetanospasmin) induces protective antitoxin; immunity requires a booster every 10 years.'),
('019cc043-0413-5731-b822-57ed4c6fcf09'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which morphologic feature is characteristic of Corynebacterium diphtheriae?', '["Gram-negative rod","Acid-fast bacillus","Spiral bacterium","Gram-positive club-shaped rod","Gram-positive coccus"]'::jsonb, 'Gram-positive club-shaped rod', 'C. diphtheriae is a non-spore-forming Gram-positive rod with clubbed ends, often arranged in V and palisade (Chinese-letter) formations.'),
('3403515f-9e59-58e5-bb42-c0a13e572738'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Diphtheria toxin is encoded by:', '["Transposon resulting in decreased functional activity","Beta-phage (lysogenic bacteriophage)","Integron mediated by specific receptor activation","Bacterial chromosome without affecting the primary tissue pathway","Plasmid leading to subsequent cellular adaptation"]'::jsonb, 'Beta-phage (lysogenic bacteriophage)', 'The tox gene resides on a lysogenic beta-corynephage; only lysogenized strains of C. diphtheriae can produce the toxin.'),
('abfa1d54-6b40-5faf-9661-9c36f82e300a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Diphtheria toxin acts by:', '["Cleaving SNARE proteins","ADP-ribosylating elongation factor-2 (EF-2)","Activating adenylate cyclase","Blocking ACh release","Blocking GABA receptors"]'::jsonb, 'ADP-ribosylating elongation factor-2 (EF-2)', 'The A fragment ADP-ribosylates and inactivates EF-2, halting peptide-chain elongation and cellular protein synthesis.'),
('c089e4bd-8faf-560f-8fb0-36be3ae4104c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The most common site of diphtheria infection is:', '["Conjunctiva resulting in decreased functional activity","Genital tract accompanied by associated clinical symptoms","Blood mediated by specific receptor activation","Nasopharynx (mucous membranes)","Skin leading to subsequent cellular adaptation"]'::jsonb, 'Nasopharynx (mucous membranes)', 'Diphtheria typically colonizes the upper respiratory tract (nasopharynx/tonsils), where the toxin produces the characteristic pseudomembrane.'),
('6049b3ff-8a7f-52fa-92a2-1b0bea893a80'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The pseudomembrane of diphtheria is composed of:', '["Pus and mucus","Granulation tissue","Fibrin dead tissue and bacteria","Fibrous tissue only","Epithelial cells"]'::jsonb, 'Fibrin dead tissue and bacteria', 'Toxin-induced necrosis with a fibrin-rich exudate and abundant organisms forms the gray, tightly adherent pseudomembrane; attempted stripping causes bleeding.'),
('b94524f3-21cc-54cd-b345-cd563c3b9aa6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Listeria monocytogenes is best described as a(n):', '["Gram-positive rod","Gram-positive coccus","Gram-negative rod","Yeast","Acid-fast bacillus"]'::jsonb, 'Gram-positive rod', 'L. monocytogenes is a small Gram-positive, non-spore-forming, facultatively intracellular rod.'),
('89340593-fc8a-5f7f-9ef2-6a05b14e4cc6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Listeria monocytogenes is an important cause of:', '["Neonatal meningitis and sepsis","Respiratory infection","Wound infection","UTI","Osteomyelitis"]'::jsonb, 'Neonatal meningitis and sepsis', 'Listeria causes neonatal sepsis and meningitis (granulomatosis infantiseptica) via transplacental or intrapartum transmission.'),
('eb1aa62f-c25a-58d4-bcaa-0d59ae98d999'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which motility pattern is characteristic of Listeria monocytogenes at 25 degrees C?', '["Non-motile","Swarming motility","Corkscrew motility","Tumbling motility at 25 degrees C","Flagellar motility"]'::jsonb, 'Tumbling motility at 25 degrees C', 'Peritrichous flagella are expressed at low temperature, giving rapid tumbling (end-over-end) motility at 25 degrees C that is reduced at 37 degrees C.'),
('1115998c-e937-5ece-a6f8-618d8d902f18'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Erysipelothrix rhusiopathiae causes:', '["Swine erysipelas","Erysipelas in children","Scarlet fever","Erysipeloid in humans (hand infection)","Cutaneous anthrax"]'::jsonb, 'Erysipeloid in humans (hand infection)', 'Erysipeloid is a painful violaceous hand lesion in fish handlers and butchers, caused by E. rhusiopathiae and distinct from streptococcal erysipelas.'),
('a2c14443-655a-5176-a90e-e8c8da83748e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Nocardia species are best described as:', '["Gram-positive cocci resulting in decreased functional activity","Gram-negative rods accompanied by associated clinical symptoms","Fungi mediated by specific receptor activation","Gram-positive branching filamentous rods (partially acid-fast)","Acid-fast bacilli leading to subsequent cellular adaptation"]'::jsonb, 'Gram-positive branching filamentous rods (partially acid-fast)', 'Nocardia are aerobic Gram-positive branching filamentous rods that are partially acid-fast (modified Kinyoun positive), unlike the strongly acid-fast mycobacteria.'),
('07b6956f-2968-5778-9a7e-17a2537d16b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which manifestation is most characteristic of Nocardia asteroides, a partially acid-fast filamentous Gram-positive organism acquired by inhalation?', '["Gastroenteritis resulting in decreased functional activity","Pulmonary infection in immunocompromised","UTI mediated by specific receptor activation","Meningitis without affecting the primary tissue pathway","Cutaneous infection leading to subsequent cellular adaptation"]'::jsonb, 'Pulmonary infection in immunocompromised', 'Inhaled Nocardia chiefly causes chronic pulmonary infection, with cerebral abscesses and skin disease in patients with impaired cell-mediated immunity.'),
('2ce5bbf8-ce3d-5a84-8a8f-ec0c195f545e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Actinomyces israelii is best characterized as a(n):', '["Anaerobic Gram-positive branching filamentous rod","Aerobic Gram-positive rod accompanied by associated clinical symptoms","Acid-fast bacillus mediated by specific receptor activation","Virus without affecting the primary tissue pathway","Gram-negative rod leading to subsequent cellular adaptation"]'::jsonb, 'Anaerobic Gram-positive branching filamentous rod', 'A. israelii is an anaerobic, non-acid-fast, branching Gram-positive rod that is part of the normal oral flora.'),
('9e4340f1-50d9-514c-89af-9334a1582123'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Actinomycosis is classically characterized by:', '["Gas in tissues","Pseudomembrane","Sulfur granules in pus","Necrotizing granulomas","Black eschar"]'::jsonb, 'Sulfur granules in pus', 'Granules of intertwined actinomycotic filaments plus host debris (''sulfur granules'') appear in the pus of draining sinuses.'),
('3c410eae-32c4-5e62-8e6c-c6aedac4732c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Actinomycosis typically follows which predisposing event?', '["Dental infections and trauma","Lung abscess","GI surgery","Diabetes","IV drug use"]'::jsonb, 'Dental infections and trauma', 'Disruption of oral mucosa by tooth extraction or facial trauma lets the commensal A. israelii enter tissue and establish a chronic suppurative infection.'),
('a6b93d43-f68b-563b-ae94-8f20c82dd7b1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which microbial description best fits the lactobacilli that protect the normal vaginal flora?', '["Spirochetes","Gram-positive rods that produce H2O2","Gram-positive cocci","Acid-fast bacilli","Gram-negative rods"]'::jsonb, 'Gram-positive rods that produce H2O2', 'Lactobacilli are Gram-positive rods whose hydrogen peroxide production inhibits vaginal pathogens and maintains a protective flora.'),
('b6edd53b-4bfe-5878-a233-27afb4608b32'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Bacillus (Geobacillus) stearothermophilus is used as a:', '["Biocontrol agent resulting in decreased functional activity","Biological indicator for autoclave testing","Probiotic mediated by specific receptor activation","Vaccine vector without affecting the primary tissue pathway","Food additive leading to subsequent cellular adaptation"]'::jsonb, 'Biological indicator for autoclave testing', 'Its heat-resistant endospores verify that steam sterilization (121 degrees C) was effective when the spores fail to grow.'),
('36ac0b78-603b-5528-ab5b-5e15d7e69933'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'After a pork feast in Papua New Guinea, children develop necrotizing jejunitis caused by Clostridium perfringens type C. Which condition is this?', '["Gas gangrene resulting in decreased functional activity","Tetanus accompanied by associated clinical symptoms","Botulism mediated by specific receptor activation","Food poisoning without affecting the primary tissue pathway","Enteritis necroticans (pigbel)"]'::jsonb, 'Enteritis necroticans (pigbel)', 'Pigbel (enteritis necroticans) follows a high-protein pork meal in protein-malnourished children; the beta toxin of C. perfringens type C causes segmental jejunal necrosis.'),
('f8e14444-ed52-5ada-896e-8e15c86be97a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Botulinum toxin is the most potent known:', '["Endotoxin","Cytotoxin","Neurotoxin","Superantigen","Enterotoxin"]'::jsonb, 'Neurotoxin', 'Botulinum neurotoxin is the most potent biological toxin known; nanogram quantities can be lethal to humans.'),
('ad68e922-7994-51fc-ba21-5d1914a6ddce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Botulinum toxin blocks the presynaptic release of which neurotransmitter at the motor end-plate?', '["Acetylcholine","GABA and glycine","Dopamine","Serotonin","Norepinephrine"]'::jsonb, 'Acetylcholine', 'Botulinum toxin cleaves SNARE proteins so synaptic vesicles cannot fuse with the membrane, preventing acetylcholine release and causing flaccid paralysis.'),
('76a11bde-15c8-5a45-a3d8-b7f6c7633e57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The Schick test is used to test immunity against:', '["Diphtheria immunity","Tetanus immunity","Tuberculosis immunity","Botulism immunity","Anthrax immunity"]'::jsonb, 'Diphtheria immunity', 'Intradermal diphtheria toxin produces an erythematous reaction in individuals lacking antitoxin (positive reaction); a negative reaction indicates immunity.'),
('071479e0-5112-58b0-8b79-ab209852ef57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Listeriosis outbreaks have been traced to which transmission route?', '["Blood transfusion resulting in decreased functional activity","Respiratory droplets accompanied by associated clinical symptoms","Contaminated dairy products and ready-to-eat meats","Fecal-oral route without affecting the primary tissue pathway","Insect bites leading to subsequent cellular adaptation"]'::jsonb, 'Contaminated dairy products and ready-to-eat meats', 'L. monocytogenes is foodborne via unpasteurized dairy, soft cheeses and refrigerated deli meats; its cold tolerance favors this transmission route.'),
('b94b43af-d969-52d7-b15e-aa571f4c1b3e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Anthrax vaccine is recommended for:', '["Pregnant women resulting in decreased functional activity","Healthcare workers accompanied by associated clinical symptoms","All children mediated by specific receptor activation","Elderly without affecting the primary tissue pathway","Military personnel and at-risk laboratory workers"]'::jsonb, 'Military personnel and at-risk laboratory workers', 'Persons with occupational exposure to anthrax spores (military personnel, laboratory and livestock workers) receive the protective-antigen-based vaccine.'),
('e00a3168-2498-5e78-8518-850e51873af5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Bacillus anthracis spores can survive:', '["Boiling","Years in soil","UV light","Pasteurization","Autoclaving"]'::jsonb, 'Years in soil', 'Elevated endospores of B. anthracis persist for years in contaminated soil, sustaining both the zoonotic cycle and the bioterrorism threat.'),
('7b2b8664-a527-5c26-9d9d-80e5997dda58'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Corynebacterium diphtheriae is classically grown on:', '["Lowenstein-Jensen medium","Loeffler medium and tellurite agar","Sabouraud agar","MacConkey agar","Chocolate agar"]'::jsonb, 'Loeffler medium and tellurite agar', 'Loeffler''s serum medium enriches C. diphtheriae and tellurite agar selects it; the organism reduces tellurite, forming black colonies.'),
('5632514d-d63d-58b9-bf30-486817bb6468'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Toxigenic strains of Corynebacterium diphtheriae elaborate their toxin only after lysogeny with a beta-phage. Which toxin is being described?', '["Diphtheria toxin production","Enterotoxin","Alpha toxin","Tetanus toxin","Botulinum toxin"]'::jsonb, 'Diphtheria toxin production', 'The tox gene of the lysogenic beta-corynephage encodes diphtheria toxin, so only lysogenized strains of C. diphtheriae produce the toxin.'),
('758bc0b9-41ef-5189-aeaf-730f0c959686'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces the most potent biological toxin known, one that blocks presynaptic acetylcholine release by cleaving SNARE proteins?', '["Clostridium tetani","Clostridium perfringens","Clostridium botulinum","Bacillus anthracis","Bacillus cereus"]'::jsonb, 'Clostridium botulinum', 'C. botulinum secretes the most lethal toxin known; it cleaves SNARE proteins to block ACh release, causing the descending flaccid paralysis of botulism.'),
('c6a7a66e-7c4a-5f72-99b5-caca034ff2ed'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism causes clostridial myonecrosis (gas gangrene) with rapidly spreading muscle destruction and gas in tissues?', '["Bacillus cereus","Clostridium tetani","Clostridium botulinum","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Clostridium perfringens', 'With a generation time near 12 minutes and the membrane-destroying alpha toxin (phospholipase C), C. perfringens produces explosive myonecrosis and gas.'),
('f3da3617-7a34-5ce3-b199-17bae483da95'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is selectively isolated and identified on tellurite agar?', '["Corynebacterium diphtheriae","Clostridium tetani","Bacillus cereus","Staphylococcus aureus","Pseudomonas aeruginosa"]'::jsonb, 'Corynebacterium diphtheriae', 'Tellurite agar selects corynebacteria, and C. diphtheriae reduces tellurite to form characteristic black colonies.'),
('477656b1-8b5d-59b6-a0ce-94d399d42d15'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'An intracellular, foodborne, Gram-positive rod with tumbling motility at 25 degrees C that causes neonatal meningitis is:', '["Listeria monocytogenes","Bacillus cereus","Corynebacterium diphtheriae","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Listeria monocytogenes', 'L. monocytogenes is a psychrotolerant, facultatively intracellular rod; tumbling motility at 25 degrees C and neonatal CNS disease are its signatures.'),
('c5f0a282-a2fa-50f5-bd75-488833784b4a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which antibiotic(s), together with antitoxin, is/are used to eliminate Corynebacterium diphtheriae?', '["Erythromycin or penicillin","Metronidazole","Vancomycin","Gentamicin","Ciprofloxacin"]'::jsonb, 'Erythromycin or penicillin', 'Erythromycin (or penicillin) eradicates the organism and stops toxin production, while antitoxin neutralizes the already-formed systemic toxin.'),
('e8cc277c-6593-5976-bd6d-972a0ffeebcb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A non-hemolytic, non-motile, encapsulated Gram-positive spore-former whose colonies have a ''medusa head'' edge is:', '["Clostridium botulinum","Clostridium perfringens","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Bacillus anthracis', 'B. anthracis is non-hemolytic and non-motile, with ''medusa head''/curled-hair colony edges and a ''string of pearls'' reaction in penicillin media.'),
('181dd99c-2ff9-5e87-9995-da5240268e14'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive rod with a drumstick (terminal spore) appearance on Gram stain is:', '["Bacillus anthracis","Clostridium tetani","Clostridium botulinum","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Clostridium tetani', 'The large spherical terminal spore of C. tetani gives the Gram-positive rod its characteristic drumstick (tennis-racket) appearance.'),
('0e3a30e8-435b-530c-b978-d362cd377451'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'An anaerobic foodborne pathogen that secretes a preformed neurotoxin into contaminated food and causes descending flaccid paralysis is:', '["Bacillus cereus","Clostridium tetani","Bacillus anthracis","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Clostridium botulinum', 'C. botulinum produces its neurotoxin in anaerobic food; the ingested toxin blocks acetylcholine release, causing the descending flaccid paralysis of botulism.'),
('17b543ca-f4af-52e2-9e60-9082c257458e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is identified by modified acid-fast (partially acid-fast) staining of branching filamentous forms?', '["Nocardia asteroides","Bacillus anthracis","Clostridium tetani","Listeria monocytogenes","Erysipelothrix rhusiopathiae"]'::jsonb, 'Nocardia asteroides', 'Nocardia filaments are stained by the modified Kinyoun method (partially acid-fast), unlike true mycobacteria, which are strongly acid-fast.'),
('c181238a-7043-5fd9-8d5a-e15f0e1d56b8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Watery diarrhea occurring 8-16 hours after reheated meat dishes, from an enterotoxin released during sporulation, is caused by:', '["Clostridium perfringens","Clostridium tetani","Bacillus cereus","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Clostridium perfringens', 'C. perfringens type A produces a heat-labile enterotoxin during sporulation in the gut, causing watery diarrhea 8-16 h after contaminated meat dishes.'),
('5f09c5f5-3dcd-5d7f-853b-86960185322d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'An infant develops constipation and progressive hypotonia after being fed honey. Which organism is implicated?', '["Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium botulinum', 'C. botulinum spores in honey germinate in the infant colon and produce toxin in vivo, causing constipation and progressive hypotonia (floppy baby syndrome).'),
('d25b8bfb-35ce-5726-8fa5-66abfb1926b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A wounded patient develops rapidly spreading myonecrosis with crepitus and foul-smelling gas. Which organism is the classic cause?', '["Clostridium botulinum","Bacillus anthracis","Clostridium tetani","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Clostridium perfringens', 'C. perfringens multiplies rapidly in devascularized anaerobic tissue; its alpha toxin destroys muscle and its fermentative metabolism produces tissue gas.'),
('8dbe9ad8-5c79-5f0f-986a-1b2581b9e9d6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A rapidly fatal necrotizing infection in a neutropenic patient, classically associated with colonic carcinoma and WITHOUT an obvious wound, is caused by:', '["Clostridium septicum","Clostridium perfringens","Clostridium tetani","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium septicum', 'C. septicum causes nontraumatic myonecrosis and neutropenic enterocolitis (typhlitis) and is classically associated with colorectal malignancy.'),
('4b82cbde-b15f-50d7-b831-5f1349381bc8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'After home-canned vegetables, a patient develops diplopia and dysphagia followed by symmetric descending weakness with intact sensation. Which organism is responsible?', '["Bacillus anthracis","Clostridium tetani","Clostridium perfringens","Clostridium botulinum","Bacillus cereus"]'::jsonb, 'Clostridium botulinum', 'Preformed botulinum toxin in inadequately processed canned food blocks acetylcholine release, giving cranial nerve palsies and symmetric descending flaccid paralysis.'),
('03641d53-bd2d-54ca-b71a-806c8f18940e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Honey ingestion in infancy can cause constipation and hypotonia because ingested spores germinate in the gut and produce toxin in vivo. Which organism is responsible?', '["Clostridium perfringens","Bacillus cereus","Bacillus anthracis","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Clostridium botulinum', 'The immature infant colon allows ingested C. botulinum spores to germinate and elaborate toxin in vivo, producing infant (floppy baby) botulism.'),
('0a4b92be-5eed-5955-84c2-3befb4077a37'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'After a contaminated puncture wound, a patient develops progressive jaw stiffness that becomes lockjaw. Which organism is implicated?', '["Bacillus anthracis","Clostridium botulinum","Clostridium tetani","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Clostridium tetani', 'C. tetani spores germinate in anaerobic wounds; tetanospasmin blocks inhibitory transmission and masseter spasm (trismus/lockjaw) appears first.'),
('ece32bc4-358c-5ed0-8ddc-3d342ce559ec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin blocks GABA and glycine release in the spinal cord, causing spastic paralysis?', '["Bacillus cereus","Clostridium tetani","Clostridium perfringens","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Clostridium tetani', 'Tetanospasmin prevents presynaptic release of GABA and glycine, abolishing inhibition of alpha motor neurons so they fire continuously, producing spastic paralysis.'),
('8a593cf0-bce8-5f5c-b092-b52fb16a6fca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'In vitro detection of toxigenicity using immunoprecipitation with antitoxin (the Elek test) applies to which organism?', '["Corynebacterium diphtheriae","Clostridium tetani","Bacillus cereus","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Corynebacterium diphtheriae', 'In the Elek test, lines of precipitation form where diphtheria toxin diffusing from a culture meets antitoxin, confirming toxigenic C. diphtheriae.'),
('f0c3ab15-affe-522f-9a48-328be9388657'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism classically causes the emetic illness that follows ingestion of reheated fried rice?', '["Clostridium tetani","Clostridium botulinum","Clostridium perfringens","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Bacillus cereus', 'Heat-stable cereulide preformed in warm rice survives reheating; vomiting begins 1-6 hours after the meal (emetic food poisoning).'),
('c64c5698-9cf2-5ace-b906-ebb33f5351aa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Antibiotic-associated pseudomembranous colitis with yellow-white plaques on the mucosa is caused by:', '["Clostridioides difficile","Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Clostridioides difficile', 'Antibiotic disruption of the colonic flora permits C. difficile (Clostridioides difficile) overgrowth; its toxins A and B produce the pseudomembranous colitis.'),
('f903e3d7-9e69-56f7-be3f-a5eb9233d81e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A double zone of hemolysis on blood agar is classically produced by which gas-forming anaerobe?', '["Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium perfringens', 'Theta toxin creates an inner complete zone of hemolysis while alpha toxin creates an outer partial zone - the characteristic double zone of C. perfringens.'),
('85f84c33-be4b-5582-87bb-633212b7cc48'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which feature explains why Bacillus and Clostridium species survive boiling water and harsh chemicals for long periods?', '["Formation of endospores","Production of beta-lactamase","Polypeptide capsule","Slime layer","Teichoic acid"]'::jsonb, 'Formation of endospores', 'Endospores are metabolically dormant, dehydrated structures with dipicolinic acid that resist heat, desiccation and disinfectants; autoclaving is required to kill them.'),
('b4f08e45-666e-558e-aa0c-ba1f7bee89cb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Rapid tumbling (end-over-end) motility at 25 degrees C is characteristic of which organism?', '["Listeria monocytogenes","Bacillus cereus","Clostridium perfringens","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Listeria monocytogenes', 'Listeria expresses peritrichous flagella at 25 degrees C, giving rapid tumbling motility that is reduced at 37 degrees C; this aids its laboratory identification.'),
('48d643ca-e6e6-5d48-9582-26b41aef0931'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A patient develops muscle rigidity, risus sardonicus and opisthotonos days after a contaminated wound. The disease is:', '["Tetanus","Botulism","Gas gangrene","Anthrax","Food poisoning"]'::jsonb, 'Tetanus', 'Loss of spinal inhibition from tetanospasmin produces the sustained muscle spasms of tetanus: trismus, risus sardonicus and opisthotonos.'),
('d103c79b-06b2-58ed-9c1e-a773700e39f9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces cereulide, a heat-stable, plasmid-encoded toxin that survives reheating and causes vomiting within 1-6 hours?', '["Clostridium tetani","Clostridium botulinum","Bacillus anthracis","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'Cereulide, the emetic toxin of B. cereus, is a heat-stable dodecadepsipeptide encoded on the ces plasmid; it is preformed in food and resists reheating.'),
('1cb17a9c-e1ba-574c-b7b8-200d03125b2b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A soldier with a deep contaminated wound develops crepitant myonecrosis with gas tracking along fascial planes. Which organism is the classic isolate?', '["Clostridium botulinum","Clostridium perfringens","Bacillus anthracis","Clostridium tetani","Bacillus cereus"]'::jsonb, 'Clostridium perfringens', 'C. perfringens infiltrates muscle along fascial planes, and its alpha toxin destroys cell membranes, producing rapidly progressive crepitant myonecrosis.'),
('b69a1455-ad0c-5c58-b2dc-536669b4401a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'An elderly patient eating reheated meat stew develops watery diarrhea and cramps 10 hours later, without fever. Which organism is most likely responsible?', '["Bacillus cereus","Clostridium perfringens","Clostridium botulinum","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Clostridium perfringens', 'C. perfringens type A food poisoning presents with watery diarrhea 8-16 hours after meat dishes, from a heat-labile enterotoxin formed during sporulation.'),
('12086045-5c81-5c45-a88a-2ff84ad0e872'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism elaborates the most potent biological toxin known, a neurotoxin that cleaves SNARE proteins?', '["Bacillus cereus","Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Clostridium botulinum', 'The neurotoxin of C. botulinum is the most potent toxin known; it cleaves SNARE proteins to block acetylcholine release and cause flaccid paralysis.'),
('f8e1807f-6067-5287-907c-f367f51c2681'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive rod with terminal drumstick spores causes risus sardonicus and generalized rigidity. The organism is:', '["Clostridium botulinum","Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Bacillus cereus"]'::jsonb, 'Clostridium tetani', 'The terminal spherical spore of C. tetani gives the drumstick shape, and its toxin produces risus sardonicus and rigidity by blocking inhibitory spinal transmission.'),
('8291c7bf-9e1f-5df6-80aa-6a599080877c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive anaerobe with a drumstick appearance on Gram stain, the cause of spastic paralysis, is:', '["Clostridium botulinum","Clostridium tetani","Bacillus anthracis","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Clostridium tetani', 'The large spherical terminal spore of C. tetani creates the drumstick (tennis-racket) morphology used to identify the organism.'),
('4365e00c-0318-545d-aa29-0170e0f9b51d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Each of the following toxins acts by ADP-ribosylation EXCEPT:', '["EF-2 (diphtheria toxin)","EF-2 (Pseudomonas exotoxin A)","Gs alpha (cholera toxin)","Gi alpha (pertussis toxin)","SNARE proteins (botulinum toxin)"]'::jsonb, 'SNARE proteins (botulinum toxin)', 'Diphtheria and Pseudomonas toxins ADP-ribosylate EF-2, cholera toxin modifies Gs and pertussis toxin modifies Gi; botulinum toxin is a zinc metalloprotease that cleaves SNARE proteins rather than ADP-ribosylating them.'),
('5fe3176e-b7f2-59b8-bf79-4bbed9a5acfd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A non-hemolytic, non-motile spore-former with ''curled hair'' colony edges and a ''string of pearls'' effect in penicillin is:', '["Bacillus cereus","Clostridium tetani","Bacillus anthracis","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'B. anthracis is non-hemolytic and non-motile; in penicillin it forms chains of coccoid cells (''string of pearls''), a distinctive identifying feature.'),
('c7ccca18-cea9-5168-b9b2-e7f704672af2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin is heat-labile, yet its spores survive boiling, explaining disease after consumption of inadequately processed canned food?', '["Clostridium botulinum","Clostridium tetani","Bacillus anthracis","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Clostridium botulinum', 'Botulinum toxin is destroyed by heating, but the spores survive boiling; inadequate canning allows germination and in-food toxin production.'),
('527fc41b-0725-5e75-a91c-face958865c0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A motile, beta-hemolytic, large Gram-positive spore-former causes watery diarrhea 8-16 hours after contaminated meat or vegetable dishes. This is:', '["Clostridium botulinum","Clostridium perfringens","Bacillus anthracis","Bacillus cereus","Clostridium tetani"]'::jsonb, 'Bacillus cereus', 'The diarrheal form of B. cereus food poisoning results from a heat-labile enterotoxin formed in the intestine, giving watery diarrhea 8-16 hours after the meal.'),
('b62ab75d-baf9-5b61-a4c2-1d15c3630d56'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin is taken up at the neuromuscular junction and travels retrograde to the spinal cord, where it prevents release of GABA and glycine?', '["Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium perfringens","Clostridium tetani"]'::jsonb, 'Clostridium tetani', 'Tetanospasmin binds presynaptically at the neuromuscular junction, is transported retrogradely to the spinal cord, and blocks the release of glycine and GABA from inhibitory neurons.'),
('9dcbbf67-3d31-513b-8f64-20814664c970'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The tripartite toxin of which organism requires protective antigen to deliver its lethal and edema factors into host cells?', '["Clostridium perfringens","Clostridium botulinum","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Bacillus anthracis', 'Protective antigen (PA) is the cell-binding component of the B. anthracis tripartite toxin; lethal factor and edema factor enter host cells only after attaching to PA.'),
('79f4fc31-f8a3-578e-b0c0-a4be170e0213'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism, a contaminant of boiled-then-held rice, causes short-incubation vomiting when the rice is later reheated?', '["Clostridium perfringens","Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium botulinum"]'::jsonb, 'Bacillus cereus', 'B. cereus spores survive the initial boiling of rice; cereulide accumulates while the rice is held warm and is not destroyed by later reheating.'),
('7b548129-48fa-5c46-a504-e5e698c41fa7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which strongly proteolytic clostridial species is among the histotoxic clostridia that participate in gas gangrene?', '["Clostridium histolyticum","Clostridium botulinum","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Clostridium histolyticum', 'C. histolyticum, C. novyi and C. septicum are histotoxic clostridia that, together with C. perfringens, can cause gas gangrene and myonecrosis.'),
('57462a54-4d77-5bd2-8200-2ddfd5303dc1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Symmetric descending flaccid paralysis beginning with diplopia and dysphagia, with intact sensation, is caused by which organism?', '["Clostridium tetani","Bacillus anthracis","Bacillus cereus","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Clostridium botulinum', 'Botulinum toxin blocks cholinergic transmission; cranial nerve palsies progress to symmetric descending flaccid paralysis without sensory loss.'),
('d6eec257-1ded-5db7-a29b-17cddf668039'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which media are used to isolate Corynebacterium diphtheriae?', '["Loeffler medium and tellurite agar","Lowenstein-Jensen medium","Sabouraud agar","MacConkey agar","Thayer-Martin agar"]'::jsonb, 'Loeffler medium and tellurite agar', 'Loeffler''s medium enriches C. diphtheriae and tellurite agar selects it (black colonies from tellurite reduction by the organism).'),
('9e5540fd-6931-51d0-82dd-04846cccbab9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A worker handling imported animal hides develops a painless ulcer with a black eschar on the forearm and marked surrounding edema. Which organism is implicated?', '["Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'Cutaneous anthrax from animal-hide exposure begins as a painless papule that becomes a black eschar with edema; it is the most common form of anthrax.'),
('e399e14d-7b86-5247-9e8d-c92be57142bb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is responsible for cutaneous anthrax and its ''malignant pustule'' eschar?', '["Bacillus anthracis","Clostridium botulinum","Bacillus cereus","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'B. anthracis enters through skin abrasions; local action of edema and lethal factors produces the painless black eschar (''malignant pustule'').'),
('cf67cf34-87b4-5ddd-9156-673972ad7646'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'All of the following are features of inhalational anthrax EXCEPT:', '["Widened mediastinum on chest radiograph","Hemorrhagic mediastinal lymphadenitis","Rapid progression to sepsis and death","Copious purulent sputum production","Fever, malaise and nonproductive cough initially"]'::jsonb, 'Copious purulent sputum production', 'Inhalational anthrax spares the lung parenchyma and produces hemorrhagic mediastinitis rather than a productive pneumonia; purulent sputum is not characteristic.'),
('8b214736-13b9-5518-9aaa-49714f7d5259'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'After injection of black tar heroin, a patient develops wound botulism with descending flaccid paralysis. Which organism is responsible?', '["Clostridium perfringens","Clostridium botulinum","Bacillus cereus","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Clostridium botulinum', 'Toxin formed within the contaminated wound (often after black tar heroin injection) blocks acetylcholine release, causing descending flaccid paralysis.'),
('f967637d-4a12-5add-9cd2-90446946679d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Reliable sterilization that destroys resistant endospores requires:', '["Autoclaving at 121 degrees C with steam under pressure","Boiling at 100 degrees C accompanied by associated clinical symptoms","Pasteurization at 63 degrees C mediated by specific receptor activation","UV irradiation without affecting the primary tissue pathway","Ethanol disinfection leading to subsequent cellular adaptation"]'::jsonb, 'Autoclaving at 121 degrees C with steam under pressure', 'Only autoclaving (steam under pressure at 121 degrees C) reliably kills endospores; boiling, pasteurization and UV irradiation do not.'),
('9bd4827e-d170-5510-beb2-5af3fe24db29'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which usually harmless soil organism causes a rapidly destructive fulminant endophthalmitis after penetrating eye trauma?', '["Bacillus anthracis","Clostridium tetani","Clostridium botulinum","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'B. cereus is the classic cause of fulminant post-traumatic (and postsurgical) panophthalmitis, requiring urgent vitrectomy and intravitreal antibiotics.'),
('6fa2df18-f875-55a1-bc66-559c180c45ca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism can contaminate intravascular lines and blood products, causing bacteremia and pneumonia mainly in immunocompromised patients?', '["Clostridium perfringens","Bacillus anthracis","Bacillus cereus","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Bacillus cereus', 'B. cereus contaminates intravascular catheters and blood products, causing catheter-related bacteremia and transfusion-associated sepsis chiefly in the immunocompromised.'),
('2cf7507f-1967-5994-9df8-1f78fbe0873f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces a tripartite toxin of protective antigen, lethal factor and edema factor and is a Category A bioterrorism agent?', '["Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Bacillus anthracis', 'The PA-LF-EF toxin, with LF a zinc metalloprotease and EF an adenylate cyclase, is unique to B. anthracis, a CDC Category A bioterrorism agent.'),
('9a1961f9-f0e6-5532-9608-bcbc2d45eb7b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism most commonly contaminates devascularized deep wounds and proliferates rapidly under anaerobic conditions to cause extensive myonecrosis?', '["Bacillus cereus","Bacillus anthracis","Clostridium perfringens","Clostridium tetani","Clostridium botulinum"]'::jsonb, 'Clostridium perfringens', 'With a generation time near 12 minutes and alpha toxin, C. perfringens proliferates explosively in devascularized anaerobic wounds, producing extensive myonecrosis and gas.'),
('b2bb20a6-cb56-52f7-9276-a99e81acd143'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Branching, partially acid-fast, filamentous Gram-positive organisms causing pulmonary and cerebral infection in immunocompromised hosts are treated with:', '["Trimethoprim-sulfamethoxazole","Penicillin G","Metronidazole","Clindamycin","Vancomycin"]'::jsonb, 'Trimethoprim-sulfamethoxazole', 'Nocardia (a partially acid-fast filamentous rod) is treated with sulfonamides such as trimethoprim-sulfamethoxazole, unlike Actinomyces, which requires penicillin.'),
('c4db9ef7-b7d0-5b89-93a3-931121f8a1c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s heat-stable cereulide toxin causes vomiting 1-6 hours after ingestion of reheated rice?', '["Bacillus cereus","Clostridium botulinum","Clostridium perfringens","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Bacillus cereus', 'Cereulide preformed in warm rice is the heat-stable emetic toxin of B. cereus, producing vomiting within 1-6 hours of ingestion.'),
('ba1e44ad-1eed-52a8-b645-1176c5af616a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Loeffler''s coagulated serum medium and tellurite agar are used to selectively grow which organism?', '["Corynebacterium diphtheriae","Neisseria meningitidis","Haemophilus influenzae","Mycobacterium tuberculosis","Clostridium tetani"]'::jsonb, 'Corynebacterium diphtheriae', 'Loeffler medium enriches C. diphtheriae and tellurite agar selects it; the organism reduces tellurite to form black colonies.'),
('75496323-6954-5490-9720-7bb78925966e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive anaerobe whose terminal spherical spore produces a drumstick appearance is:', '["Clostridium botulinum","Bacillus cereus","Clostridium tetani","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Clostridium tetani', 'The large spherical terminal spore of C. tetani gives the Gram-positive rod its drumstick (tennis-racket) morphology.'),
('6d79c4cb-1bc9-507b-8e11-e207116fa68d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which test assesses immunity to diphtheria by intradermal injection of diphtheria toxin?', '["Schick test","Elek test","Mantoux test","CAMP test","Nagler reaction"]'::jsonb, 'Schick test', 'Intradermal diphtheria toxin produces erythema in persons lacking antitoxin (positive reaction) and no reaction in immune persons.'),
('37fa70c7-8f77-5f3b-b73e-e7b31206ac64'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which gas-forming anaerobe classically gives a double zone of hemolysis on blood agar?', '["Bacillus anthracis","Clostridium tetani","Bacillus cereus","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Clostridium perfringens', 'Theta toxin produces an inner zone of complete hemolysis while alpha toxin produces an outer partial zone - the double zone characteristic of C. perfringens.'),
('34ebb9e8-d8fb-597f-89ea-af6a0291a1c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A non-immune neonate develops generalized spasms after the umbilical cord was cut with an unsterile instrument. Which organism is responsible?', '["Clostridium botulinum","Clostridium perfringens","Bacillus cereus","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Clostridium tetani', 'Neonatal tetanus follows contamination of the umbilical stump; tetanospasmin blocks inhibitory spinal transmission and produces generalized spasms.'),
('a9a97c08-aad8-5a9c-82bd-ed128cb8bd10'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'An exposed worker presents with hemorrhagic mediastinitis and a widened mediastinum after inhaling spores. Which organism is the cause?', '["Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Bacillus anthracis', 'Inhalational anthrax follows inhalation of B. anthracis spores, which are carried to mediastinal nodes; toxin release there causes hemorrhagic mediastinitis and widening.'),
('7d3c155f-072e-5701-b4c0-1464adc7194a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is a major cause of gas gangrene?', '["Bacillus anthracis","Clostridium tetani","Bacillus cereus","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Clostridium perfringens', 'Gas gangrene (clostridial myonecrosis) is most commonly caused by C. perfringens, whose alpha toxin (phospholipase C) destroys muscle.'),
('d7ab0e10-4dc9-509e-8531-c40e9c63ddc2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is the leading cause of gas gangrene?', '["Bacillus cereus","Clostridium botulinum","Bacillus anthracis","Clostridium perfringens","Clostridium tetani"]'::jsonb, 'Clostridium perfringens', 'C. perfringens is the leading cause of gas gangrene: its rapid anaerobic growth and alpha toxin produce extensive muscle necrosis and gas.'),
('6b498e44-29c6-50ce-a674-1b8057674715'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Toxin A (enterotoxin) and toxin B (cytotoxin), detected by enzyme immunoassay, are the diagnostic toxins of which cause of antibiotic-associated colitis?', '["Clostridioides difficile","Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Clostridioides difficile', 'C. difficile (Clostridioides difficile) produces toxins A and B, which are the basis of the enzyme immunoassay for antibiotic-associated colitis.'),
('3369ed4d-3f93-5140-9e1c-f4fc27eedb28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces its major exotoxin only when lysogenized by a bacteriophage (beta-corynephage) carrying the tox gene?', '["Corynebacterium diphtheriae","Streptococcus pyogenes","Bacillus anthracis","Clostridium tetani","Clostridium botulinum"]'::jsonb, 'Corynebacterium diphtheriae', 'The tox gene of the lysogenic beta-corynephage encodes diphtheria toxin, so only lysogenized C. diphtheriae can produce the toxin.'),
('410cff2d-fc41-561e-b05d-4deef0146fe2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism synthesizes a zinc-metalloprotease neurotoxin with eight serotypes, three of which (A, B, E) cause most human disease?', '["Clostridium tetani","Clostridium perfringens","Bacillus cereus","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Clostridium botulinum', 'Botulinum neurotoxins (types A-G, H) are zinc metalloproteases that cleave SNARE proteins; types A, B and E cause most human botulism.'),
('2992f4f7-eddc-55a0-9d31-6b9b2604d1e1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism causes the classic ''fried rice syndrome'' in which vomiting begins 1-6 hours after the meal?', '["Bacillus cereus","Clostridium perfringens","Clostridium botulinum","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Bacillus cereus', '''Fried rice syndrome'' is the emetic form of B. cereus food poisoning; cereulide preformed in unrefrigerated rice produces vomiting 1-6 hours later.'),
('17aa69c7-99c3-5fab-9a63-28422c579e20'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which component of Clostridioides difficile is chiefly responsible for the colonic mucosal injury in pseudomembranous colitis?', '["Toxin B (cytotoxin)","Toxin A (enterotoxin)","Alpha toxin","Cereulide","Tetanospasmin"]'::jsonb, 'Toxin B (cytotoxin)', 'C. difficile toxin B (cytotoxin) accounts for most of the epithelial injury; both toxins A and B are detected in clinical assays.'),
('21648a6a-e64b-500e-81d4-f56698d30a41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s spores are used as a biological indicator to validate autoclave (steam sterilization) efficacy?', '["Geobacillus stearothermophilus","Bacillus anthracis","Clostridium perfringens","Clostridium tetani","Bacillus cereus"]'::jsonb, 'Geobacillus stearothermophilus', 'The heat-resistant spores of Geobacillus (formerly Bacillus) stearothermophilus verify that steam sterilization was effective because they are killed only by adequate autoclaving.'),
('5887d425-6d1d-53e8-8352-70d2ae6a1c35'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A partially acid-fast, filamentous Gram-positive bacillus causes chronic pulmonary infection in immunocompromised hosts and is treated with trimethoprim-sulfamethoxazole. The organism is:', '["Nocardia asteroides","Actinomyces israelii","Bacillus anthracis","Clostridium perfringens","Mycobacterium tuberculosis"]'::jsonb, 'Nocardia asteroides', 'N. asteroides is a partially acid-fast, branching filamentous Gram-positive rod that causes pulmonary nocardiosis and is treated with sulfonamides.'),
('c3890896-75d3-5a1f-a699-07170c966725'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Opalescence on egg-yolk agar that is inhibited by specific antitoxin (Nagler reaction) identifies the alpha toxin (lecithinase) of which organism?', '["Clostridium perfringens","Bacillus cereus","Clostridium tetani","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Clostridium perfringens', 'The Nagler reaction detects the lecithinase (alpha toxin) of C. perfringens: opalescence on egg-yolk agar is halted by specific antitoxin.'),
('848811a6-cb48-571b-8631-903c3c8893a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Non-hemolytic colonies with a ''medusa head'' edge and a ''string of pearls'' appearance in penicillin are characteristic of:', '["Clostridium tetani","Bacillus anthracis","Clostridium perfringens","Clostridium botulinum","Bacillus cereus"]'::jsonb, 'Bacillus anthracis', 'B. anthracis forms non-hemolytic, non-motile colonies with medusa-head edges and, under penicillin, chains of coccoid forms (''string of pearls'').'),
('b3e1a6b4-a068-5178-9987-c5e38f3ea1ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism remains localized at the wound while its toxin travels to the CNS, so antitoxin (tetanus immune globulin) must be given early to neutralize unbound toxin?', '["Clostridium tetani","Bacillus cereus","Clostridium perfringens","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Clostridium tetani', 'C. tetani stays at the wound while tetanospasmin travels to the CNS; TIG neutralizes only circulating, unbound toxin and therefore must be given early.'),
('0cb64889-f4cb-5ea3-9dda-ed9fdb00e2e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which toxin-mechanism pairing is correct?', '["Botulinum toxin — cleaves SNARE proteins","Diphtheria toxin — activates adenylate cyclase","Cholera toxin — ADP-ribosylates EF-2","Tetanus toxin — increases intracellular cAMP","Anthrax edema factor — blocks protein synthesis"]'::jsonb, 'Botulinum toxin — cleaves SNARE proteins', 'Botulinum toxin cleaves SNARE proteins; diphtheria toxin ADP-ribosylates EF-2, cholera toxin modifies Gs, tetanus toxin blocks GABA/glycine, and anthrax edema factor is an adenylate cyclase.'),
('a02d5327-3102-5432-8deb-1494d4c7daa5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin includes edema factor, a calmodulin-dependent adenylate cyclase?', '["Bacillus anthracis","Clostridium botulinum","Clostridium tetani","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'Edema factor is a calmodulin-dependent adenylate cyclase component of the B. anthracis toxin that raises cAMP and produces massive edema.'),
('3aeb9506-8995-55b2-943b-233fc94dc80c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Neonatal meningitis is classically caused by Group B streptococcus, E. coli and which foodborne, facultatively intracellular Gram-positive rod?', '["Listeria monocytogenes","Bacillus anthracis","Clostridium perfringens","Corynebacterium diphtheriae","Bacillus cereus"]'::jsonb, 'Listeria monocytogenes', 'L. monocytogenes, along with Group B streptococcus and E. coli, is a classic cause of neonatal meningitis and sepsis.'),
('1147ac28-b4cd-5cc9-95e8-2b33a593ffcb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Non-bloody watery diarrhea with cramps beginning 8-16 hours after a meat dish, mimicking clostridial food poisoning, is the diarrheal form of which organism?', '["Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium perfringens","Clostridium tetani"]'::jsonb, 'Bacillus cereus', 'The diarrheal syndrome of B. cereus follows contaminated meat or vegetable dishes and closely mimics C. perfringens food poisoning, with an 8-16 hour incubation.'),
('aba5f897-4c56-5001-8aac-746d543578b7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which anaerobic Gram-positive rod is non-motile and boxcar-shaped, and characteristically gives a double zone of hemolysis on blood agar?', '["Clostridium tetani","Clostridium botulinum","Bacillus cereus","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Clostridium perfringens', 'C. perfringens is non-motile, encapsulated and boxcar-shaped, and its theta and alpha toxins generate the double zone of hemolysis on blood agar.'),
('f66cdf8d-7cac-575a-b240-1967361bda41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tetanus toxoid immunization protects against the heat-labile exotoxin of which organism?', '["Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Clostridium tetani', 'Tetanus toxoid is the formalin-inactivated, non-toxic tetanospasmin; immunization induces antitoxin to C. tetani''s heat-labile exotoxin.'),
('5e0d95a7-bf28-512b-b514-a35edcec5606'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces the sustained contraction of opposing muscle groups responsible for opisthotonos and risus sardonicus?', '["Clostridium tetani","Bacillus cereus","Clostridium perfringens","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Clostridium tetani', 'By blocking GABA and glycine release, tetanospasmin causes unopposed motor firing; simultaneous contraction of opposing muscles produces opisthotonos and risus sardonicus.'),
('7aa889dd-13c3-5b8c-8b9e-1833753e793b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Lecithinase (phospholipase C) activity detected by egg-yolk agar opalescence in the Nagler reaction is a feature of:', '["Clostridium perfringens","Clostridium botulinum","Bacillus cereus","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Clostridium perfringens', 'The alpha toxin of C. perfringens is a lecithinase/phospholipase C that opacifies egg-yolk agar (Nagler reaction), inhibited by specific antitoxin.'),
('db163c2d-48a1-5368-9559-c617be5c3071'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Spasms that begin near a contaminated wound and then become generalized are due to which organism''s paralysis of spinal inhibition?', '["Bacillus cereus","Bacillus anthracis","Clostridium perfringens","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Clostridium tetani', 'Loss of spinal inhibition caused by tetanospasmin produces spasms that begin near the wound and generalize, characteristic of C. tetani infection.'),
('fd1ee16f-4c76-5bca-9273-de6ed72d9340'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tetanospasmin produces spastic paralysis by:', '["Blocking presynaptic release of GABA and glycine","Cleaving SNARE proteins at the neuromuscular junction","ADP-ribosylating EF-2","Activating adenylate cyclase","Blocking ACh release"]'::jsonb, 'Blocking presynaptic release of GABA and glycine', 'Tetanospasmin prevents presynaptic release of GABA and glycine, abolishing inhibition of alpha motor neurons and causing spastic paralysis.'),
('ca5e736c-16bd-5dbc-9543-2ea9c6f42363'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive rod with a drumstick appearance on Gram stain identifies which anaerobic bacillus?', '["Bacillus cereus","Clostridium tetani","Clostridium perfringens","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Clostridium tetani', 'The terminal spherical spore of C. tetani produces the drumstick (tennis-racket) appearance on Gram stain.'),
('8ffc88e2-00fd-5447-9103-5ab1c2bde759'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism characteristically shows ''Chinese-letter'' (palisade) arrangements, metachromatic granules and growth on tellurite media?', '["Corynebacterium diphtheriae","Listeria monocytogenes","Bacillus anthracis","Clostridium tetani","Erysipelothrix rhusiopathiae"]'::jsonb, 'Corynebacterium diphtheriae', 'C. diphtheriae is a club-shaped rod in palisade (Chinese-letter) arrangements with metachromatic granules, growing on Loeffler and tellurite media.'),
('c80da59c-d006-59e6-8bcd-6cf52bff5e9d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Trismus (lockjaw) in tetanus results from:', '["Rigid spasm of the masseters from loss of inhibitory spinal transmission","Flaccid paralysis of masticatory muscles","Inflammation of the temporomandibular joint","Edema of the pharynx","Cleavage of SNARE proteins in jaw muscles"]'::jsonb, 'Rigid spasm of the masseters from loss of inhibitory spinal transmission', 'Tetanospasmin blocks inhibitory (GABA/glycine) transmission, so the masseters contract stiffly, causing trismus (lockjaw).'),
('5b70ebf9-0689-56a1-a560-a04e324a85f9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism classically causes emetic food poisoning after reheated rice?', '["Clostridium botulinum","Clostridium perfringens","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Bacillus cereus', 'Emetic food poisoning after reheated rice is caused by the heat-stable, preformed cereulide toxin of B. cereus.'),
('cfa9d8f8-b4eb-50ac-88fa-39fded2d064b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which non-spore-forming, psychrotrophic foodborne rod causes neonatal meningitis and grows at 4 degrees C (cold enrichment)?', '["Listeria monocytogenes","Bacillus anthracis","Clostridium perfringens","Bacillus cereus","Clostridium tetani"]'::jsonb, 'Listeria monocytogenes', 'L. monocytogenes is a non-spore-forming psychrotroph that grows at refrigeration temperature (cold enrichment) and causes neonatal meningitis.'),
('edcf5cbd-d8b3-5cc0-a1b2-1acab06a6710'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which statement about bacterial food-poisoning toxins is correct?', '["Botulinum toxin is heat-stable and resists boiling","Cereulide is heat-labile and destroyed by reheating","Cereulide is heat-stable, so reheated rice still causes vomiting","C. difficile toxin B is heat-stable for decades on surfaces","Clostridial spores are destroyed by boiling"]'::jsonb, 'Cereulide is heat-stable, so reheated rice still causes vomiting', 'Cereulide, the emetic toxin of B. cereus, is heat-stable and preformed, so leftover refried rice still produces vomiting.'),
('3830e600-a041-589d-ae55-2e921ef32a46'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which spore-forming organism produces two food-poisoning enterotoxins - a heat-stable one causing vomiting and a heat-labile one causing watery diarrhea?', '["Clostridium botulinum","Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'B. cereus makes heat-stable cereulide (emetic form) and heat-labile enterotoxins (diarrheal form), giving two distinct food-poisoning syndromes.'),
('b4ad1f95-de24-59e9-8808-86e4491034de'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Vaccination with toxoid and administration of tetanus immune globulin after wounds provide protection against the exotoxin of which organism?', '["Clostridium tetani","Clostridium perfringens","Clostridium botulinum","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Clostridium tetani', 'Protection against tetanus depends on circulating antitoxin to tetanospasmin; both active (toxoid) and passive (TIG) immunization provide this humoral immunity.'),
('52671778-4ad8-5571-8112-f2dac25371fc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s disease is confirmed by the mouse bioassay (mouse protection test) and treated with trivalent antitoxin effective against types A, B and E?', '["Bacillus cereus","Clostridium tetani","Clostridium botulinum","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Clostridium botulinum', 'Botulism is confirmed by the mouse bioassay, in which toxin is neutralized by specific antitoxin; treatment is trivalent (A/B/E) antitoxin plus supportive care.'),
('4ef514f0-70d4-56ae-ae8b-5976d8db6a91'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Partially acid-fast, branching, filamentous Gram-positive organisms that cause pulmonary and CNS infection in immunocompromised patients are:', '["Nocardia species","Actinomyces species","Clostridium species","Bacillus species","Listeria species"]'::jsonb, 'Nocardia species', 'Partial acid-fastness identifies Nocardia; these filamentous branching rods cause pulmonary and cerebral infection, chiefly with impaired cell-mediated immunity.'),
('ed865f17-78ed-5fe8-987e-ea460ccd2c04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Each of the following causes an enterotoxin-mediated diarrheal illness EXCEPT:', '["Clostridium perfringens","Bacillus cereus","Clostridioides difficile","Vibrio cholerae","Clostridium tetani"]'::jsonb, 'Clostridium tetani', 'C. tetani causes tetanus through a neurotoxin (tetanospasmin), not a diarrheal enterotoxin; the other listed organisms produce enterotoxin-mediated diarrhea.'),
('71329e75-1c08-55fe-b1c4-814ca3597140'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s tripartite exotoxin includes protective antigen, lethal factor and edema factor?', '["Clostridium botulinum","Bacillus cereus","Clostridium tetani","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Bacillus anthracis', 'B. anthracis secretes the tripartite exotoxin PA-LF-EF, in which protective antigen delivers lethal and edema factors into host cells.'),
('4f3b8e53-66b7-5ab1-99bb-69e05f2432f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The Elek immunoprecipitation test is used to confirm in vitro toxigenicity of which organism?', '["Corynebacterium diphtheriae","Clostridium botulinum","Clostridium perfringens","Bacillus anthracis","Vibrio cholerae"]'::jsonb, 'Corynebacterium diphtheriae', 'The Elek test demonstrates precipitation lines where diphtheria toxin meets antitoxin, confirming toxigenic strains of C. diphtheriae.'),
('0a0a2cec-24c5-581e-9ce2-432df0169ab0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which ubiquitous soil and food organism produces cereulide and a diarrheal enterotoxin, and also causes traumatic endophthalmitis and catheter-related bacteremia in the immunocompromised?', '["Bacillus anthracis","Clostridium botulinum","Bacillus cereus","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'B. cereus causes emetic (cereulide) and diarrheal food poisoning, post-traumatic endophthalmitis, and catheter-related bacteremia in compromised hosts.'),
('a346718c-ebec-5d34-aa64-17618c544b51'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'An anaerobic Gram-positive branching rod causing cervicofacial infection with draining sinus tracts and sulfur granules after dental trauma is:', '["Actinomyces israelii","Nocardia asteroides","Lactobacillus","Clostridium perfringens","Erysipelothrix rhusiopathiae"]'::jsonb, 'Actinomyces israelii', 'A. israelii, an anaerobic branching Gram-positive rod, causes cervicofacial actinomycosis with draining sinuses and sulfur granules after dental trauma.'),
('bff3e0a5-76b9-530e-9176-bdd87c3c2b0a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism causes infant botulism?', '["Clostridium perfringens","Clostridium botulinum","Clostridium tetani","Bacillus anthracis","Bacillus cereus"]'::jsonb, 'Clostridium botulinum', 'C. botulinum causes infant botulism: spores ingested from honey germinate in the infant colon and produce toxin in vivo.'),
('07d97670-326c-5778-bad0-d92c13dd969d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is responsible for a diarrheal food poisoning beginning 8-16 hours after contaminated meat or vegetable dishes, closely mimicking the common clostridial food-poisoning syndrome?', '["Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Clostridium botulinum","Bacillus cereus"]'::jsonb, 'Bacillus cereus', 'The diarrheal syndrome of B. cereus follows contaminated meat or vegetable dishes and mimics C. perfringens food poisoning, producing watery diarrhea 8-16 hours after ingestion.'),
('4a3b27c6-e0e7-562a-80b9-6e9e8dc08a7c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Cold enrichment at 4 degrees C, used before selective isolation, exploits the psychrotrophic growth of which organism?', '["Listeria monocytogenes","Clostridium botulinum","Bacillus cereus","Clostridium perfringens","Corynebacterium diphtheriae"]'::jsonb, 'Listeria monocytogenes', 'L. monocytogenes grows at 4 degrees C, so cold enrichment over weeks increases its yield in food/clinical specimens.'),
('e5c12951-9046-599f-aa38-da02470f75b4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Diphtheria toxin inactivates host protein synthesis by ADP-ribosylating which target?', '["Elongation factor-2 (EF-2)","SNARE proteins","Gs alpha subunit","70S ribosome","DNA gyrase"]'::jsonb, 'Elongation factor-2 (EF-2)', 'Diphtheria toxin ADP-ribosylates EF-2, blocking peptide-chain elongation and halting cell protein synthesis.'),
('aa37ea32-d045-54b2-968e-3b83a42630c2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Erysipeloid, a painful violaceous skin lesion on the hands of fish handlers, is caused by:', '["Erysipelothrix rhusiopathiae","Listeria monocytogenes","Bacillus anthracis","Clostridium perfringens","Staphylococcus aureus"]'::jsonb, 'Erysipelothrix rhusiopathiae', 'E. rhusiopathiae enters through skin abrasions in fish handlers and butchers, producing the localized violaceous lesion of erysipeloid.'),
('d7d53286-2f28-5911-beea-170dd7f3caf9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Pseudomembranous colitis follows antibiotic disruption of the colonic flora because which toxins damage the colonic epithelium?', '["Toxins A and B of C. difficile","Alpha toxin of C. perfringens","Cereulide of B. cereus","Tetanospasmin","Shiga toxin"]'::jsonb, 'Toxins A and B of C. difficile', 'Toxins A (enterotoxin) and B (cytotoxin) of C. difficile damage the colonic epithelium and produce the pseudomembranes of antibiotic-associated colitis.'),
('51e16db2-4ce2-5d3c-ad12-3110d477d15f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is the target of post-exposure prophylaxis with ciprofloxacin or doxycycline after a suspected bioterrorism-related spore release?', '["Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'Post-exposure prophylaxis for inhalational anthrax uses ciprofloxacin or doxycycline against B. anthracis, a Category A bioterrorism agent.'),
('ea06acca-a8ae-5207-b2c2-5742e76b4b5e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which bacterial structures are the most resistant to heat and chemicals, surviving boiling and requiring autoclaving for destruction?', '["Endospores","Capsules","Exotoxins","Plasmids","Lipid A"]'::jsonb, 'Endospores', 'Endospores of Bacillus and Clostridium species are the most resistant structures in nature to heat, drying and chemicals; autoclaving is required to kill them.'),
('beed4ad8-cf02-5c30-ab8c-e1ae008b5636'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is motile, strongly beta-hemolytic and lecithinase-positive, in contrast to the non-motile, non-hemolytic species of the same genus?', '["Clostridium tetani","Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Bacillus cereus', 'B. cereus is motile, strongly beta-hemolytic and lecithinase-positive, whereas B. anthracis is non-motile and non-hemolytic - the key distinction between the two Bacillus species.'),
('74622661-e505-5564-930f-79ad5ece4170'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which feature of Corynebacterium diphtheriae on a stained smear supports the diagnosis - slender rods with clubbed ends arranged in palisades and V forms?', '["Chinese-letter (palisade) arrangement","Drumstick spores","Medusa head colonies","Tumbling motility","Sulfur granules"]'::jsonb, 'Chinese-letter (palisade) arrangement', 'C. diphtheriae forms palisades and V-shaped arrangements (''Chinese letters'') because daughter cells snap apart at division.'),
('82a2433a-3073-51a8-a292-88824f8f3209'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces a heat-labile enterotoxin that causes watery diarrhea 8-16 hours after eating meat or poultry dishes?', '["Clostridium tetani","Bacillus cereus","Clostridium botulinum","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Clostridium perfringens', 'C. perfringens type A food poisoning occurs 8-16 hours after meat or poultry dishes; a heat-labile enterotoxin released during sporulation causes watery diarrhea.'),
('8682816c-3d69-518d-930b-d4a986b6ab57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Yellow ''sulfur granules'' in the pus of a chronic draining sinus are characteristic of infection caused by which organism?', '["Actinomyces israelii","Nocardia asteroides","Clostridium perfringens","Bacillus anthracis","Streptococcus pyogenes"]'::jsonb, 'Actinomyces israelii', 'The dense sulfur granules of Actinomyces appear in pus from draining sinuses, a hallmark of actinomycosis.'),
('be49d5c4-7fe4-5349-b4bd-9609e75d619b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism secretes a potent zinc-metalloprotease neurotoxin that cleaves SNARE proteins and blocks acetylcholine release?', '["Bacillus cereus","Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Clostridium botulinum', 'C. botulinum produces a zinc-metalloprotease neurotoxin that cleaves SNARE proteins, preventing ACh release and causing the paralysis of botulism.'),
('d4f40ce8-71b1-52db-835f-18a1801bc956'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s two food-poisoning syndromes are separated by incubation times of 1-6 hours versus 8-16 hours, reflecting two different toxins?', '["Bacillus anthracis","Clostridium botulinum","Clostridium perfringens","Clostridium tetani","Bacillus cereus"]'::jsonb, 'Bacillus cereus', 'The two B. cereus syndromes differ by incubation time - 1-6 h for the cereulide emetic form versus 8-16 h for the enterotoxin diarrheal form.'),
('057a5f72-25ac-59ce-92bc-6e3f0b5cd326'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A violaceous, painful skin lesion on the hand of a fish handler, known as erysipeloid, is caused by:', '["Erysipelothrix rhusiopathiae","Listeria monocytogenes","Bacillus anthracis","Clostridium perfringens","Staphylococcus aureus"]'::jsonb, 'Erysipelothrix rhusiopathiae', 'Erysipeloid follows handling of contaminated fish, shellfish or meat; E. rhusiopathiae enters through skin abrasions and produces the classic hand lesion.'),
('4971267f-8a4f-5911-a022-7f2b26b7fa4d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Of the following, which organism forms yellow sulfur granules in tissue and draining sinuses, distinguishing it from the acid-fast Nocardia?', '["Actinomyces israelii","Nocardia asteroides","Bacillus anthracis","Clostridium tetani","Bacillus cereus"]'::jsonb, 'Actinomyces israelii', 'Actinomyces (''ray fungus'') forms sulfur granules and is non-acid-fast, unlike the partially acid-fast filamentous Nocardia.'),
('3a57cb7e-e6a9-591c-a497-ee96e2459091'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is the classic cause of emetic food poisoning after reheated rice?', '["Bacillus cereus","Clostridium tetani","Clostridium perfringens","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Bacillus cereus', 'Reheated rice with vomiting beginning 1-6 hours later is the emetic form of B. cereus food poisoning, due to heat-stable cereulide.'),
('f9c2f3e9-e9bf-50bc-baf4-6443356c4d6e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Nocardia asteroides is identified by which staining feature?', '["Partially acid-fast with modified Kinyoun stain","Acid-fast with Ziehl-Neelsen stain","Gram-negative on Gram stain","Periodic acid-Schiff positive","Methenamine silver positive"]'::jsonb, 'Partially acid-fast with modified Kinyoun stain', 'Nocardia is partially acid-fast (positive on modified Kinyoun staining but negative on full Ziehl-Neelsen), a key feature distinguishing it from mycobacteria.'),
('803ec39b-397d-5b94-ba1a-b4f2b989aa18'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A non-hemolytic Gram-positive spore-former with ''medusa head'' colony edges identifies:', '["Clostridium botulinum","Clostridium perfringens","Bacillus anthracis","Clostridium tetani","Bacillus cereus"]'::jsonb, 'Bacillus anthracis', 'B. anthracis is non-hemolytic and non-motile; its colonies have ''medusa head''/''curled hair'' edges and a ''string of pearls'' reaction to penicillin.'),
('356b4890-7aa9-5b4a-be29-bccce8e308aa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Severe abdominal pain, bloody diarrhea and hemorrhagic mesenteric lymphadenitis after ingesting undercooked contaminated meat are features of which form of anthrax?', '["Gastrointestinal anthrax","Cutaneous anthrax","Inhalational anthrax","Injection anthrax","Meningeal anthrax"]'::jsonb, 'Gastrointestinal anthrax', 'Gastrointestinal anthrax follows ingestion of contaminated meat and presents with abdominal pain, bloody diarrhea and hemorrhagic mesenteric lymphadenitis.'),
('8af24e3f-b0f4-5284-9c34-c638fe4b7b97'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Actinomycosis is caused by which organism?', '["Actinomyces israelii","Nocardia asteroides","Bacillus anthracis","Clostridium perfringens","Clostridium tetani"]'::jsonb, 'Actinomyces israelii', 'Actinomycosis is caused by the non-spore-forming anaerobic rod Actinomyces israelii, a commensal that invades after mucosal disruption.'),
('a6507cb1-b03e-5d25-9c68-b6e5deb59f46'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s disease is mediated by protective antigen, the cell-binding component of its tripartite toxin?', '["Clostridium tetani","Bacillus anthracis","Clostridium botulinum","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'Protective antigen is part of the B. anthracis tripartite toxin; it binds host cells and delivers lethal and edema factors.'),
('09d6f637-d177-5ca8-adbe-fa5a9196b77a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Several diners develop vomiting 2-4 hours after eating Chinese takeaway fried rice. Which organism is the likely cause?', '["Clostridium perfringens","Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium tetani"]'::jsonb, 'Bacillus cereus', 'Fried rice held warm for hours supports cereulide production by B. cereus; refrying does not destroy the heat-stable toxin, so diners vomit within hours.'),
('9b421670-0b62-5337-9dc8-44e889e4e191'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A strongly proteolytic clostridium that is one of the histotoxic species found in gas gangrene is:', '["Clostridium histolyticum","Clostridium botulinum","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Clostridium histolyticum', 'C. histolyticum is a strongly proteolytic histotoxic clostridium that participates, with C. perfringens, C. novyi and C. septicum, in gas gangrene.'),
('e27fee2e-e718-5cbb-9313-a059c20fe51a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Descending flaccid paralysis with early cranial nerve palsies and no fever or sensory loss is the hallmark of which organism''s intoxication?', '["Clostridium perfringens","Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium tetani"]'::jsonb, 'Clostridium botulinum', 'Botulinum toxin blocks cholinergic transmission; the resulting cranial nerve palsies and descending flaccid paralysis occur without fever or sensory loss.'),
('796e07af-f081-5d25-99a0-36eeafcab97c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces cereulide, a heat-stable dodecadepsipeptide that damages host mitochondria and causes acute vomiting?', '["Bacillus cereus","Clostridium tetani","Bacillus anthracis","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'Cereulide, the B. cereus emetic toxin, is a heat-stable dodecadepsipeptide that uncouples mitochondrial function and induces acute vomiting.'),
('5645db51-4944-5f98-9b5d-7a6d8c3c83ac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism causes a painless papule surmounted by a black eschar with surrounding edema, known as a malignant pustule?', '["Clostridium perfringens","Bacillus anthracis","Clostridium botulinum","Clostridium tetani","Bacillus cereus"]'::jsonb, 'Bacillus anthracis', 'Cutaneous anthrax by B. anthracis begins as a painless papule that vesiculates and forms a black eschar (''malignant pustule'') with surrounding edema.'),
('5af97a44-3723-56d8-b8bd-1945dd8558c7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is responsible for cutaneous anthrax?', '["Clostridium tetani","Bacillus cereus","Clostridium perfringens","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Bacillus anthracis', 'B. anthracis entering through skin abrasions produces the painless black eschar of cutaneous anthrax.'),
('ef5dacb9-e06b-598b-acc1-fe6b645b2f65'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive rod with a terminal spore that looks like a drumstick on Gram stain is:', '["Bacillus cereus","Bacillus anthracis","Clostridium botulinum","Clostridium perfringens","Clostridium tetani"]'::jsonb, 'Clostridium tetani', 'The strictly terminal spherical spore of C. tetani gives the drumstick (tennis-racket) appearance on Gram stain.'),
('f940c00a-aee5-54db-8de3-3eb667dbdeca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is the source of cereulide, a heat-stable emetic toxin?', '["Bacillus cereus","Bacillus anthracis","Clostridium botulinum","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'Cereulide, the heat-stable emetic toxin, is produced by B. cereus in food held at room temperature for long periods.'),
('65fcf545-64e4-502a-94dd-070b17e5bf92'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-variable small rod associated with bacterial vaginosis, recognized by ''clue cells'' on saline microscopy, is:', '["Gardnerella vaginalis","Lactobacillus","Streptococcus agalactiae","Haemophilus influenzae","Bacillus cereus"]'::jsonb, 'Gardnerella vaginalis', 'Gardnerella vaginalis adheres to exfoliated epithelial cells to form the ''clue cells'' diagnostic of bacterial vaginosis.'),
('b651eaab-e49c-5dee-8325-19229fd6e617'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s neurotoxin, which cleaves SNARE proteins, causes botulism?', '["Bacillus cereus","Clostridium tetani","Clostridium botulinum","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Clostridium botulinum', 'Botulism is caused by the C. botulinum neurotoxin, which cleaves SNARE proteins and blocks presynaptic acetylcholine release.'),
('e4038799-f46b-5c6c-8a5d-83586608dab8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Type E botulism following ingestion of improperly preserved fish products is caused by which organism?', '["Bacillus cereus","Bacillus anthracis","Clostridium tetani","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Clostridium botulinum', 'Type E botulism follows ingestion of improperly preserved fish or marine mammal products containing preformed C. botulinum type E toxin.'),
('44b1b9a8-2280-5998-a30c-9f056d928b5f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which non-hemolytic, non-motile Gram-positive spore-former shows a ''string of pearls'' pattern in penicillin?', '["Bacillus cereus","Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Bacillus anthracis', 'In penicillin, B. anthracis cells become rounded coccoid forms in chains, the ''string of pearls'' reaction used in identification.'),
('7d9b91dd-2ef1-50d3-b050-237755770697'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The emetic toxin cereulide of B. cereus is distinguished by which property?', '["Heat-stable, preformed in food","Heat-labile, formed in the gut","ADP-ribosylates EF-2","Cleaves SNARE proteins","Binds GABA receptors"]'::jsonb, 'Heat-stable, preformed in food', 'Cereulide is synthesized in food, is heat-stable and survives reheating, producing vomiting within 1-6 hours of ingestion.'),
('008ad036-4100-5904-8a89-520fba826238'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'In a neutropenic patient, blood culture growth of which organism points to contaminated intravascular catheters or blood products?', '["Clostridium tetani","Bacillus anthracis","Bacillus cereus","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'B. cereus is a common contaminant of catheters and blood products; it causes catheter-related and transfusion-associated bacteremia in neutropenic patients.'),
('9ad46b07-9985-53a4-a76e-d1435b18a38a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The Schick test, using intradermal toxin, tests immunity against which disease?', '["Diphtheria","Tetanus","Botulism","Anthrax","Scarlet fever"]'::jsonb, 'Diphtheria', 'The Schick test injects minute amounts of diphtheria toxin; erythema indicates susceptibility (lack of antitoxin).'),
('55c8ac2e-c77c-50a7-87ee-dc095aee3c26'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which structure of Clostridium and Bacillus species is stained by the malachite-green spore stain?', '["Endospore","Capsule","Flagellum","Glycocalyx","Mycobacterial cell wall"]'::jsonb, 'Endospore', 'Endospores take up malachite green (resisting decolorization) in the spore stain, appearing green against pink vegetative cells.'),
('080345d7-9bf3-5f97-a540-b80124349019'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which histotoxic clostridial species is associated with gas gangrene along with C. perfringens and C. septicum?', '["Clostridium novyi","Clostridium botulinum","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Clostridium novyi', 'C. novyi is one of the histotoxic clostridia (with C. perfringens, C. septicum and C. histolyticum) implicated in gas gangrene.'),
('cbd9b647-b83b-5192-b29c-ae51f815e295'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism has aD-glutamate polypeptide capsule, is non-motile, and requires protective antigen to deliver its other two toxin components into host cells?', '["Clostridium botulinum","Bacillus cereus","Clostridium tetani","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'B. anthracis has aD-glutamate polypeptide capsule that resists phagocytosis and is non-motile; lethal and edema factors enter cells only when bound to protective antigen.'),
('7c159f29-c318-5236-8bed-87d264281516'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The Nagler reaction, used in the diagnosis of gas gangrene, detects which activity on egg-yolk agar?', '["Lecithinase (alpha toxin) of C. perfringens","Urease of H. pylori","Catalase of staphylococci","Coagulase of S. aureus","CAMP factor"]'::jsonb, 'Lecithinase (alpha toxin) of C. perfringens', 'The alpha toxin (lecithinase) of C. perfringens opacifies egg-yolk agar; the opalescence is inhibited by specific antitoxin (Nagler reaction).'),
('083fa661-ed88-5e6c-b836-ee0c80247ff3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxins A and B are the basis of enzyme immunoassay (EIA) testing for antibiotic-associated diarrhea?', '["Clostridioides difficile","Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Clostridioides difficile', 'EIA detection of toxins A and B confirms C. difficile (Clostridioides difficile) as the cause of antibiotic-associated colitis.'),
('04567327-a93e-557c-864c-ca52dd1c25a4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The tox gene carried on a lysogenic beta-corynephage encodes which toxin?', '["Diphtheria toxin","Botulinum toxin","Tetanus toxin","Alpha toxin","Cereulide"]'::jsonb, 'Diphtheria toxin', 'The tox gene of the lysogenic beta-corynephage encodes diphtheria toxin; only lysogenized strains of C. diphtheriae are toxigenic.'),
('c44ebd68-d208-5768-84d1-4d9d057d204f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which gas-forming anaerobe is identified on blood agar by a double zone of hemolysis?', '["Clostridium tetani","Bacillus cereus","Clostridium botulinum","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Clostridium perfringens', 'The combined activity of theta toxin (inner complete hemolysis) and alpha toxin (outer partial hemolysis) gives C. perfringens its double zone.'),
('1361e0c8-64c0-5c1c-9f92-32ff29ed3e23'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which bacterial toxin exerts its effect by ADP-ribosylating elongation factor-2, halting protein synthesis?', '["Diphtheria toxin","Cholera toxin","Pertussis toxin","Botulinum toxin","Tetanus toxin"]'::jsonb, 'Diphtheria toxin', 'Diphtheria toxin ADP-ribosylates EF-2, inactivating it and stopping peptide-chain elongation and protein synthesis.'),
('a1d9b4a4-00db-5068-92aa-20b89febb6f1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which presentation best fits botulism rather than tetanus?', '["Descending flaccid paralysis with cranial nerve palsies","Spastic paralysis with trismus accompanied by associated clinical symptoms","Risus sardonicus mediated by specific receptor activation","Opisthotonos without affecting the primary tissue pathway","Autonomic overactivity with hypertension leading to subsequent cellular adaptation"]'::jsonb, 'Descending flaccid paralysis with cranial nerve palsies', 'Botulism causes descending flaccid paralysis with early cranial nerve involvement; tetanus causes spastic paralysis with trismus, risus sardonicus and opisthotonos.'),
('ebaa5a52-e32f-5584-8951-f17e741019d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A double zone of hemolysis on blood agar is the classic appearance of which gas-forming anaerobe?', '["Clostridium tetani","Bacillus anthracis","Clostridium botulinum","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Clostridium perfringens', 'Double-zone hemolysis, from the combined theta and alpha toxins of C. perfringens, is the classic blood-agar appearance of the gas gangrene organism.'),
('fcd24232-2f91-50cd-9ec9-6a2454827159'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin produces symmetric descending flaccid paralysis with autonomic signs and intact sensation, findings unusual for any other cause?', '["Clostridium perfringens","Bacillus cereus","Clostridium tetani","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Clostridium botulinum', 'Botulinum toxin blocks peripheral cholinergic transmission, producing symmetric descending flaccid weakness with autonomic signs (dry mouth, dilated pupils, constipation) while sensation and consciousness are preserved.'),
('c23ebfd1-0ae6-5a76-b6fe-9ba95d536e30'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'In which organism''s emetic form of poisoning is the heat-stable toxin preformed in food, so bacterial multiplication in the host is not required?', '["Clostridium perfringens","Clostridium botulinum","Clostridium tetani","Bacillus anthracis","Bacillus cereus"]'::jsonb, 'Bacillus cereus', 'In the emetic form, B. cereus cereulide is preformed in the food, so the ingested toxin acts quickly and bacterial growth in the host is not required.'),
('d323a58d-550a-5af8-b1cf-712381683ef2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A diabetic farmer pricks a finger while removing a contaminated thorn; within days he develops painful cellulitis, crepitus and rapidly spreading myonecrosis along fascial planes. Which organism is implicated?', '["Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium perfringens', 'A contaminated deep wound with crepitant, rapidly progressive myonecrosis points to clostridial gas gangrene, most often caused by C. perfringens.'),
('98891042-7905-51b9-bf45-06f99f4f3802'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which component of the B. anthracis toxin is a calmodulin-dependent adenylate cyclase that raises intracellular cAMP, causing massive edema?', '["Edema factor","Lethal factor","Protective antigen","Toxin A","Toxin B"]'::jsonb, 'Edema factor', 'Edema factor is a calcium/calmodulin-dependent adenylate cyclase that raises intracellular cAMP and produces the massive edema of anthrax.'),
('0e863761-c80a-515f-a1a3-61f490289375'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which foodborne Gram-positive rod is an important cause of neonatal sepsis and meningitis transmitted transplacentally (granulomatosis infantiseptica)?', '["Listeria monocytogenes","Bacillus cereus","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pneumoniae"]'::jsonb, 'Listeria monocytogenes', 'L. monocytogenes crosses the placenta in pregnancy, causing neonatal sepsis and granulomatosis infantiseptica.'),
('5e92b671-4dc9-56b1-a429-662ed05644cd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Each of the following is a Gram-positive rod EXCEPT:', '["Staphylococcus aureus","Bacillus anthracis","Clostridium tetani","Listeria monocytogenes","Corynebacterium diphtheriae"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is a Gram-positive coccus; the other listed organisms are Gram-positive rods.'),
('c33f166f-0e3f-5849-a726-44283b80f8d1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Chronic suppurative swelling of the jaw with draining sinus tracts and sulfur granules after dental extraction (''lumpy jaw'') is caused by:', '["Actinomyces israelii","Bacillus anthracis","Nocardia asteroides","Clostridium perfringens","Clostridium tetani"]'::jsonb, 'Actinomyces israelii', 'Cervicofacial actinomycosis follows dental surgery; A. israelii causes chronic suppuration with sinus tracts and sulfur granules.'),
('7e1fbf26-323d-5851-aa00-41e98d4a2942'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Enteritis necroticans (pigbel) following a protein-rich pork feast is caused by which organism?', '["Bacillus cereus","Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Clostridium perfringens', 'Pigbel is caused by C. perfringens type C; its beta toxin produces segmental jejunal necrosis after a high-protein pork meal in malnourished individuals.'),
('1f269323-e87a-5bcf-ad40-706786408697'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin causes risus sardonicus and generalized muscle rigidity by blocking inhibitory spinal interneurons?', '["Clostridium perfringens","Bacillus anthracis","Clostridium tetani","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium tetani', 'Tetanospasmin of C. tetani blocks GABA/glycine release, causing risus sardonicus and generalized rigidity.'),
('40673656-2fa9-555d-9817-428aebc34429'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Opalescence on egg-yolk agar (Nagler reaction), inhibited by specific antitoxin, is characteristic of which organism''s lecithinase?', '["Clostridium botulinum","Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Bacillus cereus"]'::jsonb, 'Clostridium perfringens', 'The lecithinase (alpha toxin, phospholipase C) of C. perfringens opacifies egg-yolk agar; specific antitoxin halts the reaction.'),
('927c7832-0452-5602-bf46-0907050a7d78'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin includes lethal factor, a zinc metalloprotease that cleaves MAP kinase kinases?', '["Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'Lethal factor of B. anthracis is a zinc metalloprotease that cleaves MAP kinase kinases (MAPKK), producing cell death and systemic toxicity.'),
('d9028a4f-d35a-5963-9294-637937d13bb6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is responsible for ''floppy baby'' syndrome, in which ingested spores germinate and produce toxin within an infant''s intestine?', '["Clostridium tetani","Bacillus cereus","Bacillus anthracis","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Clostridium botulinum', 'In infant botulism, ingested C. botulinum spores germinate in the colon and produce toxin in vivo; ACh blockade causes the hypotonia of floppy baby syndrome.'),
('ed67be12-43cb-5cd6-adba-715e20547162'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Woolsorter''s disease, an inhalational illness of workers handling contaminated wool and hides, is caused by which organism?', '["Bacillus anthracis","Bacillus cereus","Clostridium perfringens","Clostridium tetani","Clostridium botulinum"]'::jsonb, 'Bacillus anthracis', 'Woolsorter''s disease is inhalational anthrax from airborne B. anthracis spores in contaminated wool, hair or hides, with mediastinal widening and hemorrhagic mediastinitis.'),
('1b3162d6-0418-5612-8797-62179ce3e7e4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces cranial nerve palsies followed by symmetric descending paralysis, with a normal cerebrospinal fluid examination?', '["Clostridium tetani","Bacillus cereus","Clostridium botulinum","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Clostridium botulinum', 'In botulism the CSF is normal and there is no sensory loss; the descending paralysis and cranial nerve palsies reflect ACh blockade by C. botulinum toxin.'),
('8a725fd6-0c50-5fd7-88cc-f4a5462f7e68'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Trismus (lockjaw) with risus sardonicus and opisthotonos is characteristic of intoxication caused by which organism''s toxin?', '["Bacillus anthracis","Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Clostridium tetani', 'Loss of inhibitory spinal transmission from tetanospasmin produces trismus, risus sardonicus and opisthotonos in tetanus.'),
('9fe5bb55-1f19-529c-b820-c909dffd086c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Listeriosis in a pregnant woman typically manifests as:', '["Flu-like febrile illness that can spread transplacentally to the fetus","Asymptomatic colonization of the colon accompanied by associated clinical symptoms","Pseudomembranous colitis mediated by specific receptor activation","Gas gangrene without affecting the primary tissue pathway","Ascending flaccid paralysis leading to subsequent cellular adaptation"]'::jsonb, 'Flu-like febrile illness that can spread transplacentally to the fetus', 'Maternal listeriosis is usually a mild flu-like febrile illness, but the organism crosses the placenta and can cause fetal loss, premature delivery or neonatal sepsis.'),
('e91d8207-324b-50b2-b807-10c1eb6e46d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism causes a fulminant post-traumatic or postsurgical endophthalmitis that requires urgent vitrectomy and intravitreal antibiotics?', '["Clostridium tetani","Bacillus cereus","Bacillus anthracis","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Bacillus cereus', 'B. cereus causes a fulminant panophthalmitis after penetrating trauma or intraocular surgery; urgent vitrectomy and intravitreal antibiotics are required.'),
('e4b2f67a-1ebe-521f-8a9d-ce14a16b1242'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Rapidly progressive myonecrosis with foul-smelling gas shadows on radiographs, developing within hours of deep trauma, is classic for:', '["Clostridium perfringens","Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium tetani"]'::jsonb, 'Clostridium perfringens', 'C. perfringens proliferates in anaerobic devascularized tissue, producing extensive myonecrosis with gas that tracks along fascial planes.'),
('80567564-4b03-5aff-bd44-62e137a22a29'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which foodborne, intracellular Gram-positive rod causes meningitis in immunocompromised hosts and the elderly and is classically associated with soft cheeses?', '["Listeria monocytogenes","Bacillus cereus","Clostridium perfringens","Corynebacterium diphtheriae","Erysipelothrix rhusiopathiae"]'::jsonb, 'Listeria monocytogenes', 'L. monocytogenes is a foodborne intracellular rod (unpasteurized dairy, soft cheese) causing meningitis in the immunocompromised, elderly and pregnant women.'),
('69749dff-4a02-5a76-a726-e97fb5e971a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The heat-stable emetic toxin cereulide is produced by which organism?', '["Bacillus anthracis","Clostridium tetani","Clostridium botulinum","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Bacillus cereus', 'Cereulide, the heat-stable emetic toxin, is produced by B. cereus in food held at room temperature for prolonged periods.'),
('41fe03ea-2a41-52a1-91c9-3528a9d36214'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which Gram-positive spore-former is non-hemolytic on blood agar and shows ''medusa head'' colonial morphology?', '["Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Bacillus anthracis', 'B. anthracis is non-hemolytic, non-motile and encapsulated, with characteristic ''medusa head''/''curled hair'' colony edges.'),
('56e8797a-5c3a-5f14-867c-88203e14a6a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which treatment approach is used for the enterotoxin-mediated disease of antibiotic-associated pseudomembranous colitis?', '["Oral vancomycin or metronidazole","Single-dose azithromycin","Ceftriaxone","Inhaled pentamidine","Oral nystatin"]'::jsonb, 'Oral vancomycin or metronidazole', 'C. difficile pseudomembranous colitis is treated with oral vancomycin (or fidaxomicin); oral metronidazole is used for mild disease.'),
('006deb61-b096-5cba-9383-255e8d389edd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is NOT a Clostridium species but shares the morphology of an anaerobic Gram-positive rod?', '["Actinomyces israelii","Clostridium tetani","Clostridium perfringens","Clostridium botulinum","Clostridioides difficile"]'::jsonb, 'Actinomyces israelii', 'Actinomyces israelii is an anaerobic Gram-positive branching rod (a separate genus), not a Clostridium species.'),
('aeb91ce8-dc25-57b3-8c90-36318b1efc40'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The Elek test is used to confirm in vitro toxigenicity of which organism?', '["Corynebacterium diphtheriae","Clostridium tetani","Bacillus anthracis","Clostridium botulinum","Streptococcus pyogenes"]'::jsonb, 'Corynebacterium diphtheriae', 'The Elek immunoprecipitation test detects diphtheria toxin production, confirming toxigenic C. diphtheriae.'),
('9fc59bfe-d85a-5db9-8229-a7921eeeb357'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces a toxin that is carried retrogradely to the CNS, where it blocks GABA and glycine release?', '["Clostridium botulinum","Bacillus cereus","Clostridium tetani","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Clostridium tetani', 'Tetanospasmin is transported retrogradely along motor axons to the CNS, where it blocks release of GABA and glycine from inhibitory neurons.'),
('9159ee42-7d10-5250-bc00-43dc2a6c7929'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Rice left warm for hours develops which organism''s heat-stable emetic toxin, which is not destroyed when the rice is reheated before serving?', '["Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus anthracis","Bacillus cereus"]'::jsonb, 'Bacillus cereus', 'Cereulide accumulates while cooked rice is held at room temperature; because it is heat-stable, refrying the rice before serving does not prevent the emetic syndrome.'),
('1987f5b4-6f42-5bf4-bee0-5ccee0d73499'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism caused ''floppy baby'' syndrome, with constipation and hypotonia from toxin produced by gut-germinated spores?', '["Clostridium botulinum","Bacillus anthracis","Clostridium tetani","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Clostridium botulinum', 'In infant botulism, C. botulinum spores germinate in the infant colon and produce toxin in vivo, causing constipation and hypotonia.'),
('96048f79-3a82-588e-8493-4dcf1bcfbdf2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is the primary target of trimethoprim-sulfamethoxazole and is partially acid-fast and filamentous on staining?', '["Nocardia asteroides","Actinomyces israelii","Clostridium perfringens","Bacillus anthracis","Clostridium tetani"]'::jsonb, 'Nocardia asteroides', 'Nocardia, a partially acid-fast branching filamentous rod, is treated with sulfonamides (trimethoprim-sulfamethoxazole).'),
('7aab4dd5-d9be-559d-a03c-7a1380770764'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is responsible for an emetic syndrome after rice dishes and a diarrheal syndrome after meat dishes, depending on which of two toxins is involved?', '["Bacillus anthracis","Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Bacillus cereus', 'B. cereus causes an emetic syndrome (heat-stable cereulide from rice) or a diarrheal syndrome (heat-labile enterotoxin from meats), depending on the toxin and food vehicle.'),
('9ea3de59-2007-5682-8f08-f510c2b72de7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Erysipeloid of the hand in fish handlers is caused by which non-spore-forming organism?', '["Erysipelothrix rhusiopathiae","Bacillus cereus","Clostridium perfringens","Listeria monocytogenes","Bacillus anthracis"]'::jsonb, 'Erysipelothrix rhusiopathiae', 'Erysipelothrix rhusiopathiae enters through hand abrasions from contaminated fish or meat, causing the violaceous lesion of erysipeloid.'),
('a6d963cd-3171-5ad3-a911-0c24cfd70c40'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A positive Nagler reaction on egg-yolk agar, in which specific antitoxin inhibits opalescence, identifies which organism''s alpha toxin?', '["Bacillus cereus","Clostridium tetani","Clostridium perfringens","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Clostridium perfringens', 'The Nagler reaction detects C. perfringens alpha toxin (lecithinase): opalescence on egg-yolk agar is inhibited by specific antitoxin.'),
('428a455e-0616-5176-88d5-4fea9ea0ee26'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which anaerobic foodborne pathogen''s preformed neurotoxin, when ingested, causes descending flaccid paralysis?', '["Clostridium botulinum","Bacillus anthracis","Clostridium tetani","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Clostridium botulinum', 'C. botulinum''s neurotoxin is preformed in anaerobic food; the ingested toxin blocks acetylcholine release, causing descending flaccid paralysis.'),
('2758724c-ca64-5585-b2a2-b646e0ab4cec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which rod is square-ended (''bamboo'' chains) with central, non-bulging spores and is entirely non-motile?', '["Clostridium tetani","Clostridium botulinum","Clostridium perfringens","Bacillus anthracis","Bacillus cereus"]'::jsonb, 'Bacillus anthracis', 'B. anthracis forms square-ended (''bamboo'') chains with central, non-bulging spores and is non-motile, unlike the motile B. cereus.'),
('33c451c5-4985-5ade-bebf-e4a8ba0cad0e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tumbling motility at room temperature is a laboratory feature used to identify which organism, a cause of sepsis and meningitis in the newborn and immunocompromised?', '["Listeria monocytogenes","Clostridium perfringens","Bacillus anthracis","Clostridium tetani","Corynebacterium diphtheriae"]'::jsonb, 'Listeria monocytogenes', 'L. monocytogenes shows tumbling end-over-end motility at 25 degrees C and causes neonatal and immunocompromised sepsis and meningitis.'),
('d3bded9e-469f-55f3-ab0f-1719e3a95c42'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Clostridial infections such as gas gangrene and tetanus are treated primarily with which agents?', '["Metronidazole or penicillin","Vancomycin or daptomycin","Ciprofloxacin or levofloxacin","Azithromycin or clarithromycin","Amikacin or gentamicin"]'::jsonb, 'Metronidazole or penicillin', 'Metronidazole or penicillin targets clostridia (perfringens, tetani), with surgical debridement for gas gangrene and antitoxin/TIG for toxin-mediated disease.'),
('dd37fceb-0136-5da9-9c8c-7fc54b59122c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The formalin-inactivated product used in active immunization against tetanus is the C. tetani:', '["Toxoid","Antitoxin","Capsule","IgG","Exotoxin"]'::jsonb, 'Toxoid', 'Tetanus toxoid is formalin-treated, non-toxic tetanospasmin that retains immunogenicity and induces protective antitoxin.'),
('d8101c4d-2dc9-58f0-ba9d-0c589d0b4492'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which Gram-positive spore-former shows non-hemolytic, non-motile colonies with ''medusa head'' edges and a ''string of pearls'' pattern in penicillin?', '["Clostridium tetani","Clostridium botulinum","Bacillus anthracis","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Bacillus anthracis', 'B. anthracis is non-hemolytic and non-motile, with ''medusa head'' colonies and a ''string of pearls'' reaction in penicillin-containing media.'),
('9b2a6de3-f455-559a-9ee9-a88a6b8da3a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism causes the sustained, simultaneous contraction of flexor and extensor muscles that produces arching of the back (opisthotonos)?', '["Clostridium perfringens","Bacillus anthracis","Clostridium tetani","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium tetani', 'By blocking GABA and glycine release, tetanospasmin produces simultaneous contraction of opposing muscles, causing the opisthotonos of tetanus.'),
('b3a45494-25cf-593a-8ec2-be7be04a3872'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism produces botulinum toxin?', '["Clostridium perfringens","Clostridium tetani","Bacillus cereus","Bacillus anthracis","Clostridium botulinum"]'::jsonb, 'Clostridium botulinum', 'Botulinum toxin comes from C. botulinum, a strictly anaerobic spore-forming rod.'),
('b3c3c84c-ab50-5ec2-8f7e-eb2f7c81e80e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which anaerobic foodborne pathogen''s neurotoxin production is confirmed by mouse bioassay and blocks acetylcholine release?', '["Bacillus cereus","Clostridium perfringens","Bacillus anthracis","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Clostridium botulinum', 'C. botulinum''s preformed neurotoxin in anaerobic food blocks ACh release; the mouse bioassay confirms botulism.'),
('1fe82b30-7596-5e70-87f0-0c3d48d83054'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which bacterial toxin, encoded on a lysogenic phage, ADP-ribosylates EF-2 and is expressed only by toxigenic strains?', '["Diphtheria toxin","Botulinum toxin","Tetanus toxin","Cereulide","Alpha toxin"]'::jsonb, 'Diphtheria toxin', 'Diphtheria toxin, encoded by the tox gene of a lysogenic beta-corynephage, ADP-ribosylates EF-2; only lysogenized strains are toxigenic.'),
('b44d75e3-751a-5f8a-bc01-69cf3c458bd9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Branching, beaded, partially acid-fast filaments in sputum from an immunocompromised host with cavitary pneumonia suggest which organism?', '["Nocardia asteroides","Actinomyces israelii","Mycobacterium tuberculosis","Clostridium perfringens","Streptococcus pneumoniae"]'::jsonb, 'Nocardia asteroides', 'Partially acid-fast branching filaments in an immunocompromised patient with pulmonary disease indicate Nocardia asteroides.'),
('5caf8578-502d-5a38-957f-18f70a0cb727'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which anaerobic organism gives ''stormy fermentation'' of litmus milk and produces abundant gas in culture within hours?', '["Bacillus anthracis","Clostridium tetani","Bacillus cereus","Clostridium botulinum","Clostridium perfringens"]'::jsonb, 'Clostridium perfringens', 'C. perfringens ferments lactose with production of gas and acid, giving ''stormy fermentation'' of litmus milk and rapid gas accumulation in culture.'),
('5cddda33-f028-5a50-a7c0-d8b8e6d31a9b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'What double zone of hemolysis identifies this gas-forming anaerobe?', '["Bacillus cereus","Clostridium perfringens","Bacillus anthracis","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Clostridium perfringens', 'C. perfringens gives a double zone of hemolysis on blood agar - an inner clear zone from theta toxin and an outer hazy zone from alpha toxin.'),
('bf1667be-181a-5740-a367-e39d62dbef4d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which non-hemolytic, non-motile Gram-positive spore-former has ''medusa head'' colony edges?', '["Clostridium tetani","Bacillus anthracis","Clostridium perfringens","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Bacillus anthracis', 'B. anthracis is non-hemolytic, non-motile and forms ''medusa head''/''curled hair'' colonies on blood agar.'),
('71d0512e-3136-5c74-a9de-e68aeae0b20f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which component of the B. anthracis toxin binds host cell receptors and delivers edema factor and lethal factor into cells?', '["Protective antigen","Lethal factor","Edema factor","Toxin A","Toxin B"]'::jsonb, 'Protective antigen', 'Protective antigen binds host receptors and mediates translocation of edema factor and lethal factor into host cells.'),
('4550eff8-bba1-50b5-b7ce-701e68bde09c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A strongly proteolytic clostridial species that is rarely toxigenic but contributes tissue destruction in gas gangrene is:', '["Clostridium histolyticum","Clostridium tetani","Bacillus cereus","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Clostridium histolyticum', 'C. histolyticum is a proteolytic histotoxic clostridium that contributes necrotizing soft-tissue infection but produces no major toxin.'),
('f0628990-636f-5ba0-899e-62ffcfad83de'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which strictly anaerobic, Gram-positive spore-former is associated with improperly canned foods and paralyzes muscle by cleaving SNARE proteins at the neuromuscular junction?', '["Bacillus cereus","Clostridium perfringens","Clostridium botulinum","Bacillus anthracis","Clostridium tetani"]'::jsonb, 'Clostridium botulinum', 'Botulinum toxin cleaves SNARE proteins (SNAP-25, VAMP) at the neuromuscular junction, so acetylcholine cannot be released and muscle becomes paralyzed.'),
('9aeccaff-af65-5785-bb21-128fecebb9f9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism, when its spores survive inadequate canning and germinate in anaerobic food, secretes a neurotoxin before the food is eaten?', '["Clostridium tetani","Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Bacillus anthracis"]'::jsonb, 'Clostridium botulinum', 'C. botulinum spores surviving inadequate canning germinate in anaerobic food; the preformed neurotoxin is ingested and blocks acetylcholine release.'),
('d89b4b98-f0c5-54da-96e8-574b44ba0fa8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Inhalational anthrax, a Category A bioterrorism disease with mediastinal hemorrhage, is caused by which organism?', '["Clostridium botulinum","Bacillus anthracis","Clostridium perfringens","Bacillus cereus","Clostridium tetani"]'::jsonb, 'Bacillus anthracis', 'Inhaled B. anthracis spores are transported to mediastinal nodes, where toxin causes hemorrhagic mediastinitis and widened mediastinum.'),
('38a791ea-60d3-5e60-9a1c-28156f2cf941'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which condition reliably destroys bacterial endospores, including B. anthracis and C. botulinum spores, making it the standard for sterilization?', '["Autoclaving at 121 degrees C, 15 psi for 15 minutes","Pasteurization at 63 degrees C for 30 minutes","Boiling at 100 degrees C for 10 minutes","Refrigeration at 4 degrees C","Ethanol 70% for 5 minutes"]'::jsonb, 'Autoclaving at 121 degrees C, 15 psi for 15 minutes', 'Steam under pressure at 121 degrees C kills endospores; boiling, pasteurization, refrigeration and alcohol do not inactivate spores.'),
('74bb3b87-1cf9-5ac1-8193-ee3fdff11847'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s self-limited, heat-stable emetic toxin causes vomiting 1-6 hours after reheated rice and requires no antibiotic therapy?', '["Bacillus cereus","Clostridium botulinum","Clostridium tetani","Clostridium perfringens","Bacillus anthracis"]'::jsonb, 'Bacillus cereus', 'B. cereus emetic food poisoning from heat-stable cereulide is self-limited and supportive, requiring no antibiotics.'),
('890b0b23-f326-54d9-b1fc-38c9a87ecbcf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A double zone of hemolysis on blood agar, from inner complete (theta) and outer partial (alpha) zones, identifies which organism?', '["Clostridium botulinum","Clostridium perfringens","Bacillus anthracis","Bacillus cereus","Clostridium tetani"]'::jsonb, 'Clostridium perfringens', 'The double-zone hemolysis of C. perfringens results from theta toxin (inner complete) plus alpha toxin (outer partial hemolysis).'),
('0f101a4e-c438-5ba2-868d-58926e8d4e0a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s protective antigen is the principal immunogen of the acellular anthrax vaccine and the key correlate of protection?', '["Bacillus anthracis","Clostridium botulinum","Bacillus cereus","Clostridium perfringens","Clostridium tetani"]'::jsonb, 'Bacillus anthracis', 'Anti-protective-antigen antibody is the correlate of protection from the acellular anthrax vaccine; it prevents lethal and edema factors entering host cells.'),
('f5a25b42-fde6-5507-8f59-46fee986e8dc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism, causing cervicofacial abscesses with sulfur granules, is treated with prolonged high-dose penicillin (months)?', '["Actinomyces israelii","Nocardia asteroides","Bacillus anthracis","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Actinomyces israelii', 'Actinomycosis requires prolonged high-dose penicillin (weeks to months) because the organisms form dense sulfur granules that resist penetration.'),
('cd5a28f5-e197-5661-adae-fd0efacf191f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Rapidly proliferating rods that turn a contaminated wound into spreading myonecrosis within hours are characteristic of which organism?', '["Clostridium perfringens","Clostridium botulinum","Bacillus cereus","Bacillus anthracis","Clostridium tetani"]'::jsonb, 'Clostridium perfringens', 'C. perfringens, with its rapid growth and alpha toxin, turns a contaminated devascularized wound into spreading myonecrosis within hours in anaerobic conditions.'),
('8247bf7d-3cb3-55b6-9c7e-520996442e28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin disables Renshaw cell-mediated inhibitory feedback on alpha motor neurons, thereby causing spasticity?', '["Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Clostridium tetani', 'Tetanospasmin disables Renshaw-cell recurrent inhibition of alpha motor neurons, so glycinergic negative feedback is lost and spasticity develops.'),
('d7b1d81b-88de-5ca9-b6a2-cd58881fe575'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Loeffler''s coagulated serum medium is used to isolate which organism?', '["Corynebacterium diphtheriae","Neisseria meningitidis","Bordetella pertussis","Vibrio cholerae","Mycobacterium tuberculosis"]'::jsonb, 'Corynebacterium diphtheriae', 'Loeffler''s medium enriches C. diphtheriae, and tellurite agar is used for selective isolation.'),
('c6c71f94-1c69-5d05-8987-0baa7e47a6b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A non-motile, non-hemolytic, encapsulated Gram-positive rod with ''medusa head'' colonies and a ''string of pearls'' penicillin effect is:', '["Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium perfringens","Clostridium botulinum"]'::jsonb, 'Bacillus anthracis', 'These features - non-motility, non-hemolysis, medusa-head colonies and the penicillin ''string of pearls'' - are specific for B. anthracis.'),
('06053536-3c76-5a83-85d8-949676b4f388'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The Schick test historically assessed susceptibility to which infection?', '["Diphtheria","Tetanus","Scarlet fever","Anthrax","Tuberculosis"]'::jsonb, 'Diphtheria', 'The Schick test used intradermal diphtheria toxin to detect lack of antitoxin (susceptibility to diphtheria).'),
('1d3d8d72-47f6-5440-8ded-5348e3bec795'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'All of the following are features of bacterial endospores EXCEPT:', '["Extreme resistance to heat and desiccation","Requirement of autoclaving for reliable destruction","Metabolically dormant state","Susceptible to routine boiling","Survival for decades in soil"]'::jsonb, 'Susceptible to routine boiling', 'Endospores survive boiling; routine boiling does not destroy them, which is why autoclaving at 121 degrees C is required.'),
('307b7fd9-9d10-56ab-9a0b-9fc760cc8456'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which anaerobic foodborne pathogen produces a preformed neurotoxin that causes descending flaccid paralysis?', '["Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Clostridium botulinum","Bacillus cereus"]'::jsonb, 'Clostridium botulinum', 'C. botulinum produces a preformed neurotoxin in anaerobic food; the absorbed toxin blocks acetylcholine release, causing descending flaccid paralysis.'),
('f3ee7e21-a5ea-503a-a6de-812157be3b04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'In which disease is the toxin formed by the vegetative bacillus inside contaminated anaerobic food BEFORE ingestion (so the meal itself is toxic)?', '["Botulism","Tetanus","Gas gangrene","Anthrax","Diphtheria"]'::jsonb, 'Botulism', 'In foodborne botulism, C. botulinum grows in improperly processed anaerobic food and produces toxin before the food is consumed.'),
('791d2dec-5ade-5809-897a-49faa22874a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s toxin includes a calmodulin-dependent adenylate cyclase (edema factor) and a zinc metalloprotease that cleaves MAP kinase kinase (lethal factor)?', '["Clostridium botulinum","Bacillus anthracis","Clostridium perfringens","Bacillus cereus","Clostridium tetani"]'::jsonb, 'Bacillus anthracis', 'The B. anthracis toxin pairs an adenylate-cyclase edema factor with a zinc-metalloprotease lethal factor, both delivered by protective antigen.'),
('f222396e-b66c-5214-b76a-15a022d7eda9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Toxins A and B are produced by which cause of antibiotic-associated colitis?', '["Clostridioides difficile","Clostridium perfringens","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Clostridioides difficile', 'C. difficile (Clostridioides difficile) produces toxins A (enterotoxin) and B (cytotoxin), the cause of antibiotic-associated pseudomembranous colitis.'),
('c837de2b-5a5e-52b1-a59a-ff3b006e0c7e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which toxin is encoded by the tox gene on a lysogenic beta-corynephage?', '["Diphtheria toxin","Botulinum toxin","Tetanus toxin","Alpha toxin","Cereulide"]'::jsonb, 'Diphtheria toxin', 'The tox gene of the lysogenic beta-corynephage encodes diphtheria toxin, so only lysogenized C. diphtheriae strains are toxigenic.'),
('05135ceb-2618-5330-8a3e-6d115254cf5a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The systemic effects of diphtheria (myocarditis, neuritis) result from the toxin''s ADP-ribosylation of which host target?', '["Elongation factor 2","RNA polymerase","DNA gyrase","70S ribosome","Tubulin"]'::jsonb, 'Elongation factor 2', 'Diphtheria toxin ADP-ribosylates elongation factor 2, blocking protein synthesis and producing the systemic cardiac and neural toxicity of diphtheria.'),
('7e58579a-8b56-5bac-99d4-4ba42d877066'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism shows ''stormy fermentation'' of litmus milk and double-zone hemolysis on anaerobic blood agar?', '["Bacillus anthracis","Clostridium tetani","Clostridium botulinum","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Clostridium perfringens', 'Stormy fermentation of litmus milk and double-zone hemolysis are classic laboratory features of the gas-forming anaerobe C. perfringens.'),
('faf0728f-4a11-5095-a30c-6a24234a8125'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s spores are used as a biological indicator to validate autoclave sterilization?', '["Geobacillus stearothermophilus","Bacillus anthracis","Bacillus cereus","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Geobacillus stearothermophilus', 'Geobacillus (formerly Bacillus) stearothermophilus spores are the biological indicator that verifies effective steam sterilization.'),
('afd7e0fa-f7f0-5a43-8801-1dc9148bc637'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Pulmonary infection with branching, partially acid-fast filamentous forms in an immunocompromised patient is caused by which organism (NOT a spore-former)?', '["Nocardia asteroides","Bacillus anthracis","Clostridium tetani","Clostridium perfringens","Bacillus cereus"]'::jsonb, 'Nocardia asteroides', 'Nocardia asteroides is a partially acid-fast, branching filamentous non-spore-former causing pulmonary nocardiosis in the immunocompromised.'),
('96fff6cf-0535-566f-a54a-98d8314d4bce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s heat-stable toxin tolerates brief reheating, so leftover refried rice still produces vomiting 1-6 hours after it is served?', '["Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Bacillus anthracis","Clostridium tetani"]'::jsonb, 'Bacillus cereus', 'Cereulide tolerates brief reheating, so leftover refried rice still produces the emetic syndrome of B. cereus 1-6 hours after serving.'),
('f6ef6c9e-3595-55a3-85c4-06c4fc89e399'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which toxin component is a calmodulin-dependent adenylate cyclase that causes massive local edema in anthrax?', '["Edema factor","Lethal factor","Protective antigen","Botulinum toxin","Tetanospasmin"]'::jsonb, 'Edema factor', 'Edema factor is the calmodulin-dependent adenylate cyclase of the B. anthracis toxin that raises cAMP and causes massive edema.'),
('f3305fe6-aed1-5e14-9362-5322b4e61108'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive rod that is non-motile, encapsulated and seen in ''boxcar'' pairs is:', '["Clostridium perfringens","Clostridium tetani","Bacillus anthracis","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium perfringens', 'C. perfringens is non-motile and encapsulated with boxcar (rectangular-ended) Gram-positive rods in pairs.'),
('3e27b6ef-3978-506c-bd21-f7acee4e5261'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Watery diarrhea beginning 8-16 hours after reheated meat or vegetable dishes, without vomiting or fever, is caused by the heat-labile enterotoxin of:', '["Bacillus cereus","Clostridium perfringens","Clostridium botulinum","Clostridium tetani","Bacillus anthracis"]'::jsonb, 'Bacillus cereus', 'The diarrheal form of B. cereus food poisoning is caused by a heat-labile enterotoxin with an incubation of 8-16 hours and watery stool.'),
('98e09f01-5bf9-5862-8e9b-96e3b57eb615'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A Gram-positive bacillus with a drumstick appearance on Gram stain identifies:', '["Bacillus cereus","Clostridium tetani","Clostridium botulinum","Bacillus anthracis","Clostridium perfringens"]'::jsonb, 'Clostridium tetani', 'C. tetani carries a large spherical terminal spore, giving the Gram-positive rod a drumstick (tennis-racket) appearance.'),
('478e5b73-96cf-51ae-b5d3-1c6b713e26a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'After a shared meal of home-preserved food, several people develop symmetric descending paralysis beginning 12-36 hours later. Which organism is implicated?', '["Clostridium tetani","Bacillus anthracis","Clostridium perfringens","Bacillus cereus","Clostridium botulinum"]'::jsonb, 'Clostridium botulinum', 'A shared meal and 12-36 hour incubation point to preformed toxin; C. botulinum toxin cleaves SNAREs and produces symmetric descending paralysis.'),
('e50a0df8-fbf7-54ff-bc7f-487e2531d0a0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism''s alpha toxin (phospholipase C) and theta toxin together produce the double zone of hemolysis classically seen on blood agar?', '["Clostridium tetani","Clostridium botulinum","Bacillus anthracis","Bacillus cereus","Clostridium perfringens"]'::jsonb, 'Clostridium perfringens', 'C. perfringens alpha toxin (phospholipase C/lecithinase) and theta toxin together generate the outer and inner zones of the classic double-zone hemolysis.'),
('5d83ac87-6594-57b3-b318-951bc129c750'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Buffet-meal outbreaks of clostridial food poisoning, with watery diarrhea and cramps, are most commonly caused by which organism?', '["Clostridium perfringens","Clostridium botulinum","Clostridium tetani","Bacillus cereus","Bacillus anthracis"]'::jsonb, 'Clostridium perfringens', 'C. perfringens type A is the common cause of clostridial food poisoning after bulk-prepared meat dishes; spores germinate during slow cooling and release a heat-labile enterotoxin.'),
('9bf1c50f-7be3-52a6-864b-94aeca31fe91'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which non-motile, encapsulated, boxcar-shaped Gram-positive rod generates gas that dissects along fascial planes during anaerobic myonecrosis?', '["Bacillus cereus","Clostridium botulinum","Bacillus anthracis","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Clostridium perfringens', 'C. perfringens is non-motile, encapsulated and boxcar-shaped; in anaerobic wounds its metabolic activity generates gas that dissects along fascial planes.'),
('390589f2-8ba2-585c-ad4d-8357725c76b6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'A gardener who stepped on a rusty nail develops trismus within two weeks even though the wound appears healed. Which organism is implicated?', '["Bacillus anthracis","Clostridium perfringens","Bacillus cereus","Clostridium botulinum","Clostridium tetani"]'::jsonb, 'Clostridium tetani', 'C. tetani is a strict anaerobe whose spores, introduced by a penetrating injury, germinate even in a small or apparently healed wound; tetanospasmin then produces trismus.'),
('9b2a587e-5f95-52c3-b0ae-d3d14bbda0b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tellurite-containing selective media are used to isolate and characterize which organism?', '["Corynebacterium diphtheriae","Clostridium perfringens","Bacillus anthracis","Neisseria meningitidis","Haemophilus influenzae"]'::jsonb, 'Corynebacterium diphtheriae', 'Tellurite agar selects C. diphtheriae, which reduces tellurite intracellularly to form black colonies.'),
('fc17db36-172f-59bc-b325-745d93294713'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism is transmitted through contaminated wounds and via the cut umbilical stump, causing generalized spastic paralysis in non-immune victims?', '["Bacillus cereus","Clostridium perfringens","Bacillus anthracis","Clostridium tetani","Clostridium botulinum"]'::jsonb, 'Clostridium tetani', 'C. tetani is transmitted by wound and umbilical-stump contamination; tetanospasmin reaches the CNS to block inhibitory transmission, causing generalized spastic paralysis.'),
('f74ea612-d917-5de2-bcb2-5c5263ea140d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which organism causes pseudomembranous colitis following broad-spectrum antibiotics and is diagnosed by toxin A/B enzyme immunoassay?', '["Clostridioides difficile","Bacillus anthracis","Bacillus cereus","Clostridium tetani","Clostridium perfringens"]'::jsonb, 'Clostridioides difficile', 'C. difficile (Clostridioides difficile) causes antibiotic-associated pseudomembranous colitis, diagnosed by EIA for toxins A and B.'),
('a445a7c2-69bd-5db4-9f3a-a0821dfe518d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Bacillus anthracis is best classified as a(n):', '["Gram-positive spore-forming rod","Gram-negative rod","Gram-positive coccus","Acid-fast bacillus","Spiral bacterium"]'::jsonb, 'Gram-positive spore-forming rod', 'B. anthracis is a large Gram-positive rod that forms endospores; it is non-motile and non-hemolytic.'),
('9a77efef-1c1e-538f-afe1-d57e4407980d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Bacillus anthracis is a(n):', '["Gram-positive coccus","Gram-positive spore-forming rod","Gram-negative rod","Spiral bacterium","Acid-fast bacillus"]'::jsonb, 'Gram-positive spore-forming rod', 'B. anthracis is a Gram-positive spore-forming rod that is non-motile and encapsulated.'),
('d7ec61c5-661d-5136-83eb-c81121be716a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The bacterial class of Bacillus anthracis is:', '["Acid-fast bacillus","Gram-positive coccus","Gram-positive spore-forming rod","Spiral bacterium","Gram-negative rod"]'::jsonb, 'Gram-positive spore-forming rod', 'B. anthracis is a Gram-positive, spore-forming, rod-shaped bacterium.'),
('2585f414-7bfd-5a29-bf28-5e6302bf742d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which description best matches Bacillus anthracis?', '["Spiral bacterium","Gram-positive spore-forming rod","Gram-positive coccus","Acid-fast bacillus","Gram-negative rod"]'::jsonb, 'Gram-positive spore-forming rod', 'B. anthracis is a Gram-positive spore-forming rod, distinguishable from the non-spore-forming Gram-positive rods.'),
('aee4ffcc-97a9-56f2-8d63-2e92a42ba046'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Bacillus anthracis belongs to which morphologic category?', '["Gram-negative rod","Gram-positive spore-forming rod","Acid-fast bacillus","Gram-positive coccus","Spiral bacterium"]'::jsonb, 'Gram-positive spore-forming rod', 'B. anthracis is a Gram-positive endospore-forming rod and the etiologic agent of anthrax.'),
('ab2874d0-d4ed-52b9-987a-4bf90e7f160a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Cutaneous anthrax is characterized by:', '["Painless black eschar","Painful ulcer","Vesicular rash","Necrotizing fasciitis","Petechial rash"]'::jsonb, 'Painless black eschar', 'The cutaneous anthrax lesion is a painless papule that becomes a black necrotic eschar with surrounding edema.'),
('979de10b-0dba-504f-8e5c-dc256fcd68bd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The classic feature of cutaneous anthrax is a:', '["Painful ulcer","Painless black eschar","Necrotizing fasciitis","Vesicular rash","Petechial rash"]'::jsonb, 'Painless black eschar', 'Edena and necrosis in cutaneous anthrax produce a painless eschar, the most distinctive clinical feature.'),
('6f6ae22b-71a0-50fe-a6d4-62ba6bf0712c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which lesion is typical of cutaneous anthrax?', '["Petechial rash","Painless black eschar","Painful ulcer","Necrotizing fasciitis","Vesicular rash"]'::jsonb, 'Painless black eschar', 'Cutaneous anthrax at the inoculation site evolves into a painless black eschar (malignant pustule).'),
('190f19df-6e11-51d7-9176-1c9256ee1952'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The hallmark of cutaneous anthrax infection is:', '["Vesicular rash","Painful ulcer","Petechial rash","Painless black eschar","Necrotizing fasciitis"]'::jsonb, 'Painless black eschar', 'A painless papule progressing to a black eschar with edema is pathognomonic of cutaneous anthrax caused by B. anthracis.'),
('b1ee0541-3db0-5735-8de9-75062b481271'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which finding accompanies the skin lesion of cutaneous anthrax?', '["Necrotizing fasciitis","Painless black eschar","Petechial rash","Painful ulcer","Vesicular rash"]'::jsonb, 'Painless black eschar', 'Cutaneous anthrax produces a painless eschar (''malignant pustule'') that is notably lacking in tenderness.'),
('6c11a0a3-297d-5448-b9de-94ff04be0739'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The emetic toxin of B. cereus is:', '["Heat-stable preformed toxin","Superantigen","Lipopolysaccharide","Neurotoxin","Heat-labile enterotoxin"]'::jsonb, 'Heat-stable preformed toxin', 'Cereulide is a heat-stable toxin preformed in food, so it is not destroyed by reheating and acts rapidly after ingestion.'),
('5416a246-ab33-5246-95ba-1c91bd4c16e9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which characterization of the B. cereus emetic toxin is correct?', '["Superantigen","Heat-stable preformed toxin","Lipopolysaccharide","Neurotoxin","Heat-labile enterotoxin"]'::jsonb, 'Heat-stable preformed toxin', 'The emetic toxin cereulide of B. cereus is heat-stable and preformed in the food before it is consumed.'),
('58829296-0fd5-5ee3-a856-4edef2a2cc49'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'B. cereus emetic toxin is best described as a(n):', '["Lipopolysaccharide","Superantigen","Heat-stable preformed toxin","Neurotoxin","Heat-labile enterotoxin"]'::jsonb, 'Heat-stable preformed toxin', 'B. cereus cereulide is a heat-stable toxin formed in the food, surviving reheating to cause vomiting within 1-6 hours.'),
('4f927da6-9151-50ca-bcfa-245ec2ff3990'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The heat-stable nature of which organism''s emetic toxin explains vomiting after reheated food?', '["Bacillus cereus : heat-stable preformed toxin","Clostridium botulinum : heat-labile toxin","Staphylococcus aureus : superantigen","Clostridium perfringens : heat-labile enterotoxin","Vibrio cholerae : heat-labile enterotoxin"]'::jsonb, 'Bacillus cereus : heat-stable preformed toxin', 'Cereulide is a heat-stable, preformed toxin, so reheating contaminated rice does not inactivate it and vomiting follows within hours.'),
('7188c368-8218-534f-9504-3999d1103016'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'The B. cereus emetic toxin differs from the diarrheal toxin because it is:', '["Heat-stable and preformed","Heat-labile and formed in vivo","A zinc metalloprotease","An ADP-ribosylating enzyme","A superantigen"]'::jsonb, 'Heat-stable and preformed', 'Unlike the heat-labile diarrheal enterotoxin, the emetic toxin cereulide is heat-stable and preformed in the food, causing vomiting within 1-6 hours.'),
('d2191180-460f-56d3-ba62-f365bda726f1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Which type of toxin is the B. cereus emetic toxin?', '["Neurotoxin","Lipopolysaccharide","Heat-stable preformed toxin","Superantigen","Heat-labile enterotoxin"]'::jsonb, 'Heat-stable preformed toxin', 'The B. cereus emetic toxin (cereulide) is heat-stable and is produced in the food before ingestion.'),
('93b21a99-74a5-5df9-8cdc-ca27f8c78fb3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'Tetanus toxin is carried to the CNS via:', '["Retrograde axonal transport","Hematogenous route","Direct extension","Lymphatic spread","Across the blood-brain barrier"]'::jsonb, 'Retrograde axonal transport', 'Tetanospasmin binds presynaptic terminals at the neuromuscular junction and is transported retrogradely along motor axons to the CNS.'),
('cbc117f8-ea76-58aa-a303-f76ae63af4b7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Bacilli', 'How does tetanus toxin reach the central nervous system?', '["Hematogenous route","Retrograde axonal transport","Lymphatic spread","Direct tissue extension","Crossing the blood-brain barrier"]'::jsonb, 'Retrograde axonal transport', 'Tetanus toxin travels retrogradely within motor axons from the neuromuscular junction to the spinal cord and brainstem.'),
('f443a719-2a3b-513d-88b9-5168acc845b4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Toxic shock syndrome toxin-1 (TSST-1) produced by Staphylococcus aureus causes disease by acting as which of the following?', '["Superantigen","Heat-stable enterotoxin","Exfoliative toxin","Cytotoxin","Hemolysin"]'::jsonb, 'Superantigen', 'TSST-1 bypasses normal antigen processing by cross-linking MHC class II molecules on antigen-presenting cells with the V-beta region of the T-cell receptor, triggering massive polyclonal T-cell activation and a cytokine storm.'),
('857265f1-e34e-505b-afb6-5caa06dadce6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Staphylococcus aureus is distinguished from the other staphylococci by which laboratory result?', '["Catalase production","Optochin sensitivity","Novobiocin sensitivity","Coagulase production","Bacitracin sensitivity"]'::jsonb, 'Coagulase production', 'Only S. aureus produces coagulase, which converts fibrinogen to fibrin and causes plasma to clot; the other staphylococci are coagulase-negative.'),
('52443283-3aee-5d7f-b6f6-ba0ac17e691c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Staphylococcus aureus produces all of the following EXCEPT:', '["Exotoxin A","Coagulase","DNase","Protein A","Catalase"]'::jsonb, 'Exotoxin A', 'Exotoxin A, an ADP-ribosylating toxin, is a product of Pseudomonas aeruginosa, whereas S. aureus produces coagulase, DNase, protein A and catalase.'),
('40e58fcf-9f42-557b-81de-4c012ad890f0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Protein A, a major surface protein of Staphylococcus aureus, impairs opsonization and phagocytosis by binding which host structure?', '["Fc region of IgG","CD4 receptors","Fab region of IgG","Complement C3b","Mannose receptors"]'::jsonb, 'Fc region of IgG', 'Protein A binds the Fc region of IgG non-specifically, so bound antibody cannot engage Fc receptors on phagocytes, impairing opsonization and complement-mediated phagocytosis.'),
('77cbaef2-8df2-5e0e-a468-16393de888cb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 20-year-old woman using vaginal tampons develops high fever, a diffuse erythematous rash, hypotension and later palmar desquamation. Which syndrome caused by Staphylococcus aureus does this represent?', '["Toxic shock syndrome","Endocarditis","Scalded skin syndrome","Impetigo","Food poisoning"]'::jsonb, 'Toxic shock syndrome', 'Tampon-associated toxic shock syndrome is caused by S. aureus elaborating TSST-1, a superantigen that produces fever, hypotension, an erythematous rash and characteristic desquamation of the palms and soles.'),
('742722c9-480c-5014-b423-524aef22eab1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Toxic shock syndrome toxin (TSST-1) acts as which of the following?', '["Leukocidin","Superantigen","Cytotoxin","Hemolysin","Enterotoxin"]'::jsonb, 'Superantigen', 'TSST-1 is a superantigen that cross-links class II MHC molecules to the V-beta region of T-cell receptors, driving polyclonal T-cell activation and massive cytokine release.'),
('bc2162d7-444e-501f-8540-a3e0d7e52a14'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A picnic-goer develops violent vomiting and watery diarrhea 3 hours after eating potato salad that had been cooked but left unrefrigerated and then reheated. Which toxin is responsible?', '["Enterotoxin (heat-stable preformed toxin)","Exfoliative toxin accompanied by associated clinical symptoms","TSST-1 mediated by specific receptor activation","Panton-Valentine leukocidin without affecting the primary tissue pathway","Hemolysin leading to subsequent cellular adaptation"]'::jsonb, 'Enterotoxin (heat-stable preformed toxin)', 'Staphylococcal enterotoxins are heat-stable and preformed in the food before ingestion, so the 1-6 hour onset indicates intoxication by the preformed toxin rather than infection.'),
('6f2e57a5-bea2-540d-9831-dc5dedb8e836'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following is caused by the exfoliative (epidermolytic) toxin of Staphylococcus aureus?', '["Scalded skin syndrome","Endocarditis","Impetigo","Toxic shock syndrome","Food poisoning"]'::jsonb, 'Scalded skin syndrome', 'The exfoliative toxin of S. aureus cleaves desmoglein-1 in the stratum granulosum, producing the widespread bullous desquamation characteristic of scalded skin syndrome.'),
('74015f52-e398-58ce-a2af-2d3e7cc007e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Panton-Valentine leukocidin (PVL) is associated with which of the following?', '["Food poisoning","Scalded skin syndrome","Toxic shock syndrome","Osteomyelitis","Necrotizing pneumonia and skin abscesses"]'::jsonb, 'Necrotizing pneumonia and skin abscesses', 'PVL is a pore-forming bicomponent leukocidin, characteristically produced by community-acquired MRSA, that causes severe necrotizing pneumonia and recurrent skin abscesses and furuncles.'),
('5418e418-95b1-56e6-ad39-862172b5d8ae'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Methicillin resistance in Staphylococcus aureus (MRSA) is mediated primarily by which mechanism?', '["Modified PBP (PBP2a) encoded by mecA","Porin loss","Efflux pump","Target modification of ribosome","Beta-lactamase"]'::jsonb, 'Modified PBP (PBP2a) encoded by mecA', 'MRSA carries the mecA gene encoding an altered penicillin-binding protein (PBP2a) with low affinity for beta-lactams; beta-lactamase production is a separate and less important mechanism.'),
('f4c61492-c0e6-53b5-b13b-2df94801059d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Vancomycin is the drug of choice for which of the following?', '["MSSA","MRSA","VRE","Penicillin-resistant pneumococci","ESBL-producing organisms"]'::jsonb, 'MRSA', 'MRSA is resistant to all beta-lactams, and vancomycin remains the treatment of choice for serious infections such as MRSA endocarditis.'),
('ba36b560-a4fd-5724-b8ec-84863809d957'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'S. epidermidis is a common cause of which of the following?', '["Toxic shock syndrome resulting in decreased functional activity","Food poisoning accompanied by associated clinical symptoms","Infective endocarditis on prosthetic valves","Pneumonia without affecting the primary tissue pathway","Impetigo leading to subsequent cellular adaptation"]'::jsonb, 'Infective endocarditis on prosthetic valves', 'S. epidermidis is the most common cause of prosthetic valve endocarditis, colonizing the artificial material through biofilm formation.'),
('5b33a542-9b5c-5cb8-b01a-b3c695cdc0cb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'S. saprophyticus is a common cause of which of the following?', '["Meningitis resulting in decreased functional activity","Endocarditis accompanied by associated clinical symptoms","Pneumonia mediated by specific receptor activation","Urinary tract infections in young women","Osteomyelitis leading to subsequent cellular adaptation"]'::jsonb, 'Urinary tract infections in young women', 'S. saprophyticus is a leading cause of acute urinary tract infection in young, sexually active women and is distinguished by its resistance to novobiocin.'),
('e3f7f766-e0d4-53f8-9daf-44307b4d170d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'On mannitol salt agar, which organism ferments mannitol, producing yellow colonies, while the other staphylococci do not?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus aureus', 'Mannitol salt agar is both selective (high salt inhibits most organisms) and differential; S. aureus ferments mannitol with acid production, turning the pH indicator yellow, whereas S. epidermidis does not.'),
('99c203a0-8677-53b2-a9e3-c1e277942239'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'S. pyogenes isolated from a throat swab is placed in Lancefield group A on the basis of which cell-wall structure?', '["Group-specific C-carbohydrate polysaccharide antigen","M protein accompanied by associated clinical symptoms","Lipoteichoic acid mediated by specific receptor activation","Peptidoglycan backbone without affecting the primary tissue pathway","Hyaluronic acid capsule leading to subsequent cellular adaptation"]'::jsonb, 'Group-specific C-carbohydrate polysaccharide antigen', 'The Lancefield system classifies beta-hemolytic streptococci by their group-specific cell-wall C-carbohydrate polysaccharide antigens; S. pyogenes carries the group A carbohydrate.'),
('a538370d-060e-5597-b1a3-fced8507fe9c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Group A streptococcus (S. pyogenes) is identified by which laboratory property?', '["Novobiocin-resistant","Bacitracin-sensitive","Bile-soluble","Catalase-positive","Optochin-sensitive"]'::jsonb, 'Bacitracin-sensitive', 'S. pyogenes is the beta-hemolytic streptococcus that is uniquely sensitive to a low-potency bacitracin disk, which separates it from group B and other beta-hemolytic streptococci.'),
('de58b932-acf3-5b4d-9dbb-b28a9475a78e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Group B streptococcus (S. agalactiae) is associated with which of the following?', '["Infective endocarditis","Rheumatic fever","Pharyngitis","Neonatal sepsis and meningitis","Dental caries"]'::jsonb, 'Neonatal sepsis and meningitis', 'S. agalactiae (group B) colonizes the maternal genital tract and is the leading cause of early-onset neonatal sepsis and meningitis acquired during delivery.'),
('db77128a-d3c7-511a-a843-684bace91c4f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which pair of laboratory tests is used to separate Streptococcus pneumoniae from the viridans group streptococci?', '["Optochin sensitivity and bile solubility","Bacitracin sensitivity","Catalase production","Novobiocin resistance","Coagulase production"]'::jsonb, 'Optochin sensitivity and bile solubility', 'S. pneumoniae and the viridans group are both alpha-hemolytic; pneumococci are distinguished by being inhibited by optochin and lysed (solubilized) by bile salts.'),
('c5fb32f3-5379-5ccf-af5b-e6af9f8c6aa4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Viridans group streptococci recovered from a patient with subacute endocarditis produce which pattern of hemolysis on blood agar?', '["Partial hemolysis (green discoloration)","Complete hemolysis (clear zone)","No hemolysis (gamma)","Beta hemolysis with double zone","Alpha-prime hemolysis with wide clear zone"]'::jsonb, 'Partial hemolysis (green discoloration)', 'Viridans streptococci are alpha-hemolytic: partial lysis oxidizes hemoglobin to methemoglobin, producing a greenish discoloration around the colonies on blood agar.'),
('94321389-5c89-519d-94f7-616a5100e5cb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Streptococcus pyogenes produces which pattern of hemolysis on sheep blood agar?', '["Clear zone of complete hemolysis","Green discoloration (alpha hemolysis)","No hemolysis (gamma)","Greenish-brown discoloration","Double zone of hemolysis"]'::jsonb, 'Clear zone of complete hemolysis', 'S. pyogenes is beta-hemolytic: streptolysins O and S cause complete lysis of red cells, yielding a clear, colorless zone around colonies on blood agar.'),
('8598fe7f-9b63-5edf-b7bd-3b165dc8ae66'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Virulence factors of S. pyogenes include all of the following EXCEPT:', '["DNase B","Protein A","Hyaluronidase","M protein","Streptolysin O"]'::jsonb, 'Protein A', 'Protein A is a cell-wall product of S. aureus that binds the Fc of IgG; S. pyogenes elaborates M protein, hyaluronidase, DNase B and streptolysin O.'),
('171cf207-f7e1-5969-a406-a8c2a874a19c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which surface protein of Streptococcus pyogenes is both an adhesin and the major antiphagocytic factor (resists opsonization)?', '["M protein","Streptolysin O","DNase B","Hyaluronidase","Pyrogenic exotoxin"]'::jsonb, 'M protein', 'M protein is a fibrillar surface antigen of S. pyogenes that resists phagocytosis by inhibiting complement deposition and C3b opsonization, and also mediates adherence to host cells.'),
('fe19f3dc-abca-5be9-bfb4-0dd5c89fc906'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A diabetic patient develops a purulent surgical wound infection 7 days after surgery. Which Gram-positive coccus is the most common cause?', '["Staphylococcus aureus","Streptococcus pneumoniae","Enterococcus faecalis","Streptococcus pyogenes","Streptococcus agalactiae"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the most frequent cause of postoperative wound infections and other purulent hospital-acquired (nosocomial) infections.'),
('76c87a31-4c1d-54ad-8ecc-926a89a0091d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Acute post-streptococcal glomerulonephritis with hematuria and hypertension classically follows pyoderma or pharyngitis caused by which of the following?', '["S. aureus resulting in decreased functional activity","S. pyogenes (nephritogenic strains)","S. epidermidis mediated by specific receptor activation","S. pneumoniae without affecting the primary tissue pathway","S. agalactiae leading to subsequent cellular adaptation"]'::jsonb, 'S. pyogenes (nephritogenic strains)', 'Only certain nephritogenic M-protein serotypes of S. pyogenes (e.g., type 12) cause acute post-streptococcal glomerulonephritis, typically 1-3 weeks after infection.'),
('ec7ea905-2130-5443-a1e2-700f127c88c4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which culture medium is selective for staphylococci by virtue of its high salt concentration?', '["Mannitol salt agar","MacConkey agar","Chocolate agar","Thayer-Martin agar","Lowenstein-Jensen medium"]'::jsonb, 'Mannitol salt agar', 'Mannitol salt agar contains 7.5% NaCl, which inhibits most other organisms, allowing selective isolation of salt-tolerant staphylococci; it is also differential for mannitol fermentation.'),
('cf9db56f-c388-5c9a-9b19-98403545d0fd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following conditions associated with Streptococcus pyogenes is a late nonsuppurative immunologic sequela rather than a direct pyogenic infection?', '["Erysipelas","Impetigo","Necrotizing fasciitis","Rheumatic fever","Scarlet fever"]'::jsonb, 'Rheumatic fever', 'Rheumatic fever is an autoimmune, nonsuppurative sequela of group A streptococcal pharyngitis; erysipelas, impetigo and necrotizing fasciitis are direct pyogenic infections and scarlet fever is toxin-mediated.'),
('59b708da-7030-5db7-a68a-96c20f25657d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'S. pneumoniae is the most common cause of which of the following?', '["Pharyngitis","Community-acquired pneumonia","Urinary tract infection","Wound infection","Neonatal sepsis"]'::jsonb, 'Community-acquired pneumonia', 'S. pneumoniae is the leading cause of community-acquired pneumonia, producing classic lobar consolidation, and is also a major cause of meningitis and otitis media.'),
('d44a0142-5310-5b65-832f-2f4a013403a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The virulence of S. pneumoniae depends primarily on which of the following?', '["M protein","Flagella","Exotoxin","Polysaccharide capsule","Protein A"]'::jsonb, 'Polysaccharide capsule', 'The polysaccharide capsule is the principal virulence factor of S. pneumoniae, allowing it to resist phagocytosis; unencapsulated variants are avirulent.'),
('623a1d9e-8935-532e-81e7-628866c7930a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The CAMP test, in which the organism enlarges the zone of beta-hemolysis around a Staphylococcus aureus streak, presumptively identifies which organism?', '["Streptococcus agalactiae","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Streptococcus agalactiae', 'S. agalactiae (group B) produces the CAMP factor, a diffusible protein that causes arrowhead enhancement of staphylococcal beta-hemolysis, giving presumptive identification of GBS.'),
('8ffc2bdf-d644-5076-aed5-cdfa7f10450a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Enterococci (Lancefield group D) are intrinsically resistant to which of the following?', '["Aminoglycosides","Tetracyclines","Penicillin","Vancomycin","Cephalosporins"]'::jsonb, 'Cephalosporins', 'Enterococci are intrinsically resistant to cephalosporins and have low-level resistance to penicillins, so enterococcal infections are usually treated with a penicillin combined with an aminoglycoside for synergy.'),
('4005c1e0-08ac-5a9f-9328-92fd87c37564'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Viridans group streptococci are most commonly associated with which of the following?', '["Subacute bacterial endocarditis","Pharyngitis accompanied by associated clinical symptoms","Pneumonia mediated by specific receptor activation","UTI without affecting the primary tissue pathway","Meningitis leading to subsequent cellular adaptation"]'::jsonb, 'Subacute bacterial endocarditis', 'Viridans group streptococci (e.g., S. mutans, S. sanguinis) are the most common cause of subacute infective endocarditis on damaged native valves, typically following dental procedures.'),
('c8f0087c-b7db-5200-8d56-7c0fe2944c7a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The S. milleri (anginosus) group is associated with which of the following?', '["UTI resulting in decreased functional activity","Abscess formation in internal organs","Rheumatic fever mediated by specific receptor activation","Neonatal sepsis without affecting the primary tissue pathway","Dental caries leading to subsequent cellular adaptation"]'::jsonb, 'Abscess formation in internal organs', 'The S. milleri group has a striking propensity to form abscesses with pus in internal organs (liver, brain, lung) and in the oral and abdominal cavities.'),
('e1f749ae-1f50-5685-82f1-8ae9d56c636d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Scarlet fever is caused by which of the following?', '["Enterococcus resulting in decreased functional activity","S. pneumoniae accompanied by associated clinical symptoms","S. aureus mediated by specific receptor activation","S. pyogenes producing erythrogenic toxin","S. agalactiae leading to subsequent cellular adaptation"]'::jsonb, 'S. pyogenes producing erythrogenic toxin', 'Scarlet fever follows pharyngeal infection with a lysogenized strain of S. pyogenes that produces the pyrogenic (erythrogenic) exotoxin responsible for the rash.'),
('36ea4873-88c3-597b-bca3-ec7e5785eba8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Erysipelas, a characteristic skin infection caused by Streptococcus pyogenes, is best described by which of the following?', '["Impetigo resulting in decreased functional activity","Superficial skin infection with raised borders","Necrotizing fasciitis mediated by specific receptor activation","Deep soft tissue infection without affecting the primary tissue pathway","Wound abscess leading to subsequent cellular adaptation"]'::jsonb, 'Superficial skin infection with raised borders', 'Erysipelas is a superficial infection of the skin and upper subcutis with a sharp, raised, well-demarcated advancing border, characteristic of group A streptococcal infection.'),
('e2ef050d-4015-50b0-a8d7-9e13592b13d9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Impetigo, a superficial blistering skin infection, may be caused by which of the following?', '["Both S. aureus and S. pyogenes","S. pyogenes","S. pneumoniae","S. epidermidis","S. aureus"]'::jsonb, 'Both S. aureus and S. pyogenes', 'Impetigo, with its honey-colored crusted lesions, is caused by S. aureus and S. pyogenes, either alone or together; the other options name only a single species.'),
('8901ab72-784f-5839-a82c-80be906002fd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Cellulitis and necrotizing fasciitis due to Streptococcus pyogenes spread rapidly along tissue planes because the organism produces which enzyme?', '["Hyaluronidase","Coagulase","Catalase","Beta-lactamase","Protein A"]'::jsonb, 'Hyaluronidase', 'Hyaluronidase is the ''spreading factor'' of S. pyogenes: it depolymerizes hyaluronic acid in connective tissue ground substance, allowing rapid extension along fascial planes.'),
('fd807bd8-5bb1-5f9d-9941-8ed89427f1d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which pair of organisms is best separated in the laboratory by optochin susceptibility and bile solubility testing?', '["S. saprophyticus from S. epidermidis","S. pneumoniae from other alpha-hemolytic streptococci","S. aureus from S. epidermidis","Enterococcus from Streptococcus","S. pyogenes from S. agalactiae"]'::jsonb, 'S. pneumoniae from other alpha-hemolytic streptococci', 'S. pneumoniae is alpha-hemolytic like the viridans group, from which it is distinguished by being optochin-sensitive and bile-soluble; viridans streptococci are optochin-resistant and bile-insoluble.'),
('73b4daab-4f32-58f5-96f4-7e49fbad3fd7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following is a leading cause of community-acquired pneumonia?', '["S. pyogenes","Enterococcus","S. pneumoniae","S. agalactiae","Viridans streptococci"]'::jsonb, 'S. pneumoniae', 'S. pneumoniae is the leading cause of community-acquired pneumonia and an important cause of bacterial meningitis and otitis media.'),
('8b9d5530-56fc-5706-ac3b-90a4c5e025e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A term neonate develops early-onset sepsis and meningitis within the first hours of life. Which organism is most likely responsible?', '["S. pneumoniae","S. agalactiae (Group B)","S. pyogenes (Group A)","Enterococcus","S. aureus"]'::jsonb, 'S. agalactiae (Group B)', 'S. agalactiae (group B) is the leading cause of neonatal sepsis and meningitis, acquired from the maternal genital tract during delivery; it is identified by the CAMP and hippurate tests.'),
('1f44871e-4022-50cc-ba4c-36ec36c0b664'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The hippurate hydrolysis test is positive for which of the following?', '["S. epidermidis","S. pneumoniae","S. aureus","S. agalactiae","S. pyogenes"]'::jsonb, 'S. agalactiae', 'S. agalactiae (group B) hydrolyzes sodium hippurate to glycine and benzoic acid, a biochemical test that helps differentiate it from group A streptococcus.'),
('73a8b373-01b3-5d90-b8e5-f692571cdeeb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Novobiocin resistance is a laboratory test that identifies which of the following?', '["S. saprophyticus","S. aureus","S. epidermidis","S. pneumoniae","S. pyogenes"]'::jsonb, 'S. saprophyticus', 'S. saprophyticus is the coagulase-negative staphylococcus that is resistant to novobiocin, whereas S. epidermidis is novobiocin-sensitive.'),
('9a5aec6e-039e-5736-8f03-bf048cb4ce63'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The Lancefield system classifies beta-hemolytic streptococci into serologic groups (A, B, C, D) on the basis of which of the following?', '["Cell-wall C-carbohydrate (polysaccharide) antigens","Flagellar proteins","Peptidoglycan cross-linking peptides","Outer-membrane lipopolysaccharide","Capsular type-specific polysaccharides"]'::jsonb, 'Cell-wall C-carbohydrate (polysaccharide) antigens', 'Lancefield grouping is based on group-specific cell-wall polysaccharide (C-carbohydrate) antigens; group A is S. pyogenes and group B is S. agalactiae.'),
('2e0106d3-95c3-5550-b22d-ba60cc790f0c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The peptidoglycan of Gram-positive bacteria is which of the following?', '["Is thick with many layers of NAM-NAG","Has outer membrane","Is thin with one to two layers","Contains porins","Contains lipid A"]'::jsonb, 'Is thick with many layers of NAM-NAG', 'The Gram-positive cell wall is a thick layer of many peptidoglycan sheets (repeating N-acetylmuramic acid and N-acetylglucosamine subunits) that retains crystal violet during decolorization.'),
('1be4e88e-e840-5c9b-8b59-a08dee5c219a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Catalase production is positive for which of the following?', '["Streptococci","Lactobacilli","Staphylococci","Clostridia","Enterococci"]'::jsonb, 'Staphylococci', 'Staphylococci are catalase-positive, whereas all true streptococci and enterococci are catalase-negative; the catalase test is the first step separating the two.'),
('fc6b8659-d39b-5640-a84c-c9ba314d0989'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Among the staphylococci, the coagulase test is used to distinguish which of the following?', '["Enterococci from streptococci","S. epidermidis from S. saprophyticus","Staphylococci from streptococci","S. aureus (positive) from other staphylococci","S. pneumoniae from viridans"]'::jsonb, 'S. aureus (positive) from other staphylococci', 'The coagulase test is the key separation step among staphylococci: S. aureus is coagulase-positive whereas S. epidermidis and S. saprophyticus are coagulase-negative.'),
('d898e230-696e-5009-9b8f-75d27b3f68c9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following organisms hydrolyze L-pyrrolidonyl-beta-naphthylamide (PYR) and are therefore PYR positive?', '["S. agalactiae","S. pyogenes and Enterococcus","S. aureus","S. epidermidis","S. pneumoniae"]'::jsonb, 'S. pyogenes and Enterococcus', 'Both S. pyogenes (group A) and enterococci hydrolyze PYR to pyrrolidone and are PYR positive; the other species listed are PYR negative.'),
('36db872f-20ee-510e-940f-2a57c4ee01aa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Staphylococcal food poisoning has an incubation period (time to onset) of which of the following?', '["3-5 days","24-48 hours","7-10 days","1-6 hours","12-24 hours"]'::jsonb, '1-6 hours', 'Staphylococcal food poisoning is an intoxication caused by preformed heat-stable enterotoxin, giving rapid-onset vomiting and diarrhea within 1-6 hours of ingestion.'),
('1127fba9-49f0-5b20-9f42-aacdc9de12cc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Infective endocarditis caused by methicillin-resistant Staphylococcus aureus is best treated with which antibiotic?', '["Vancomycin","Penicillin G","Clindamycin","Cefazolin","Erythromycin"]'::jsonb, 'Vancomycin', 'MRSA is resistant to all beta-lactams including cefazolin, so vancomycin is the treatment of choice for MRSA endocarditis; nafcillin or oxacillin is preferred for MSSA.'),
('e8ee6fa5-7aa2-5643-919a-bff7f657cc96'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Bacitracin sensitivity (0.04-unit disk) is characteristic of which of the following?', '["S. agalactiae (Group B)","S. pneumoniae","Enterococcus","S. pyogenes (Group A)","S. aureus"]'::jsonb, 'S. pyogenes (Group A)', 'S. pyogenes (group A) is the beta-hemolytic streptococcus that is susceptible to the low-potency bacitracin disk, separating it from group B and other beta-hemolytic streptococci.'),
('c2243a93-34b5-5d00-9a50-a24cad9fcc46'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Resistance to trimethoprim-sulfamethoxazole (SXT) is characteristic of which of the following?', '["S. pneumoniae","S. aureus","Enterococcus","S. agalactiae","S. pyogenes"]'::jsonb, 'S. pyogenes', 'S. pyogenes is intrinsically resistant to trimethoprim-sulfamethoxazole, which is therefore not used for group A streptococcal pharyngitis.'),
('3b18f164-111f-5bfc-af2c-c4e94dbb388c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The CAMP test provides presumptive identification of which organism?', '["Streptococcus agalactiae","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus agalactiae', 'Production of the CAMP factor, seen as arrowhead enhancement of staphylococcal beta-hemolysis on blood agar, is used to presumptively identify group B streptococcus (S. agalactiae).'),
('c23f5d5e-ca0d-5632-8fa0-e31c70f61104'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A patient develops fever and a new regurgitant murmur 8 months after mechanical aortic valve replacement. Which organism is most likely responsible?', '["Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most common cause of prosthetic valve endocarditis within the first year after valve surgery, owing to its ability to form biofilm on the foreign material.'),
('48545bad-28e0-5d6e-b915-281fea0bb668'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Methicillin-resistant Staphylococcus aureus (MRSA) is resistant to beta-lactam antibiotics because of the production of which of the following?', '["An altered penicillin-binding protein (PBP2a) encoded by mecA","An extended-spectrum beta-lactamase","Loss of outer-membrane porins","Enhanced efflux pumps","Hyperproduction of penicillinase only"]'::jsonb, 'An altered penicillin-binding protein (PBP2a) encoded by mecA', 'In MRSA, mecA encodes PBP2a, which has low affinity for beta-lactams, so these drugs cannot inhibit peptidoglycan cross-linking; beta-lactamase production is a separate, clinically distinct mechanism.'),
('d943141a-997b-5a4d-8987-864b7d7d8ad8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism carries the Lancefield group B (C-carbohydrate) antigen and is a cause of neonatal sepsis?', '["Streptococcus agalactiae","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus pyogenes"]'::jsonb, 'Streptococcus agalactiae', 'S. agalactiae bears the group BC-carbohydrate antigen and is the leading cause of early-onset neonatal sepsis and meningitis.'),
('2e78981b-2ae5-5f48-b3c1-32312ee68859'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is classified as the Lancefield group A streptococcus?', '["Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecalis"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes carries the Lancefield group A cell-wall C-carbohydrate antigen and is therefore classified as the group A streptococcus.'),
('cd7d8ec5-5230-5f25-bf73-bca3fe27019a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which culture medium is used for the optimal isolation of Streptococcus pneumoniae from clinical specimens?', '["Blood agar","MacConkey agar","Lowenstein-Jensen medium","Thayer-Martin agar","Selenite F broth"]'::jsonb, 'Blood agar', 'S. pneumoniae requires blood-enriched media (5% sheep blood agar), on which it grows as alpha-hemolytic, mucoid, capsule-forming colonies; the other media select for different organisms.'),
('eccd0761-2cbd-5d44-a827-455f85e976d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Enterococcus faecalis appears on Gram stain as which of the following?', '["Gram-positive cocci in pairs and short chains","Gram-negative rods","Gram-positive rods with spores","Gram-negative diplococci","Gram-positive cocci in clusters"]'::jsonb, 'Gram-positive cocci in pairs and short chains', 'Enterococci are Gram-positive cocci that typically occur singly, in pairs (diplococci) or in short chains, morphologically similar to streptococci.'),
('39e7643d-0a9b-5666-a62b-8f74c1528a69'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which enterococcus is a common cause of urinary tract and endocardial infections?', '["Streptococcus pyogenes","Staphylococcus aureus","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is the enterococcal species most commonly implicated in urinary tract infections and infective endocarditis, especially after urologic or gastrointestinal instrumentation.'),
('561934a9-23ad-5613-aeee-e1ea6f2ede10'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which antibiotic is the drug of choice for community-acquired pneumonia caused by penicillin-susceptible Streptococcus pneumoniae?', '["Penicillin (amoxicillin)","Vancomycin","Metronidazole","Gentamicin monotherapy","Caspofungin"]'::jsonb, 'Penicillin (amoxicillin)', 'Penicillin (amoxicillin) remains the treatment of choice for penicillin-susceptible pneumococcal pneumonia; vancomycin is reserved for resistant strains or severe central nervous system infection.'),
('9831a7e5-3f26-5cc9-a9ff-372357fe8ed2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A coagulase-negative Gram-positive coccus that is a component of normal skin flora causes clinically significant infection when prosthetic material is present. Which organism is it?', '["Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus aureus","Staphylococcus epidermidis","Enterococcus faecalis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is a coagulase-negative, catalase-positive skin commensal that causes infection mainly in the presence of indwelling prosthetic devices, through biofilm formation.'),
('8f9ce2a1-fcc9-5ce7-bf7d-4176e4bc0c07'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most frequent cause of bloodstream infection complicating indwelling central venous catheters?', '["Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most frequent cause of central line-associated bloodstream infection, adhering to the catheter surfaces by producing extracellular biofilm.'),
('e5a430b1-d3d3-5638-b41c-84102bcf4bf7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Susceptibility to a 0.04-unit bacitracin disk is used to presumptively identify which organism?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'Group A streptococcus (S. pyogenes) is the beta-hemolytic streptococcus uniquely sensitive to low-potency bacitracin, whereas group B and other beta-hemolytic streptococci are resistant.'),
('f7b706f4-8600-5bca-85d5-762e475d8f53'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A beta-hemolytic, catalase-negative coccus that is sensitive to a 0.04-unit bacitracin disk and gives a positive PYR test is most likely which organism?', '["Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes is beta-hemolytic, catalase-negative, bacitracin-sensitive and PYR positive; its major antiphagocytic virulence factor is the M protein.'),
('cb57b32d-a2f7-56ae-8adb-e53888eada81'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms is identified by its ability to hydrolyze esculin in the presence of bile and to grow in 6.5% NaCl broth?', '["Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Staphylococcus epidermidis"]'::jsonb, 'Enterococcus faecalis', 'Enterococci (E. faecalis) hydrolyze bile-esculin and grow in 6.5% NaCl broth, features that distinguish them from the other Gram-positive cocci listed.'),
('fa16a4ce-d804-547f-b848-fb771e761107'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'All of the following organisms may be vancomycin resistant EXCEPT:', '["Streptococcus pneumoniae","Enterococcus faecalis (VRE)","Enterococcus faecium (VRE)","Staphylococcus aureus (VRSA)","Enterococcus gallinarum (vanC)"]'::jsonb, 'Streptococcus pneumoniae', 'Vancomycin resistance occurs in enterococci (vanA/vanB, VRE), in staphylococci (VRSA) and in vanC enterococci; S. pneumoniae remains fully vancomycin-susceptible, the drug being used for pneumococcal meningitis.'),
('38fbb0a7-b2bf-5ff5-a34d-c5d6abc706d9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A middle-aged man develops lobar pneumonia with rusty sputum; the sputum Gram stain shows Gram-positive lancet-shaped diplococci that are optochin-sensitive and bile-soluble. Which organism is it?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the classic cause of lobar pneumonia; it is an optochin-sensitive, bile-soluble, alpha-hemolytic lancet-shaped diplococcus with a polysaccharide capsule.'),
('b57808fc-28d0-516f-ade8-88c0ec66f999'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The coagulase test, in which the organism causes plasma to clot, is positive for which organism?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus aureus', 'S. aureus produces free and bound coagulase, which convert soluble fibrinogen to fibrin and cause plasma to clot; this is the cardinal test separating it from the coagulase-negative staphylococci.'),
('386bb946-8652-5717-bb04-eb5f6b0cdc16'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Acute post-streptococcal glomerulonephritis characteristically follows infection with which organism?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Streptococcus pyogenes', 'Nephritogenic M-protein serotypes of S. pyogenes cause immune-complex glomerulonephritis 1-3 weeks after pharyngitis or pyoderma, with hematuria, edema and hypertension.'),
('04629d3c-407a-5019-a04b-2eb528e354e6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A beta-hemolytic, bacitracin-sensitive coccus causes pharyngitis that is later complicated by acute rheumatic fever. Which organism is responsible?', '["Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes (group A) causes exudative pharyngitis and is the antecedent infection for acute rheumatic fever and post-streptococcal glomerulonephritis.'),
('78981f7e-d870-5368-92b0-8db73b273656'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 60-year-old man with prostatic hypertrophy undergoes repeated urinary catheterization and subsequently develops infective endocarditis. Which organism is most likely?', '["Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is the common enterococcal cause of urinary tract infection and infective endocarditis, especially after urologic manipulation or instrumentation.'),
('b1238eeb-a077-5515-ae95-fb227eeb8b0b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following is a normal skin commensal that is the most common cause of endocarditis on prosthetic heart valves within the first year after surgery?', '["Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most common cause of early prosthetic valve endocarditis, a biofilm-mediated infection of the artificial valve material.'),
('36daa0e0-be52-5ff8-a4bf-ac0cdb017c78'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Streptolysin O, the antigen against which the ASO antibody is measured, is produced by which organism?', '["Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus aureus","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes elaborates streptolysin O (oxygen-labile) and streptolysin S; the antistreptolysin O (ASO) titer detects antibody to streptolysin O as evidence of recent group A streptococcal infection.'),
('05efe3b3-b95b-5e7b-aa76-1e09bba7731a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Hydrolysis of sodium hippurate is a laboratory test that identifies which organism?', '["Streptococcus agalactiae","Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Streptococcus agalactiae', 'S. agalactiae (group B) hydrolyzes hippurate to glycine and benzoic acid, a test that helps differentiate it from S. pyogenes (group A), which is hippurate negative.'),
('74e664c4-f5c7-58ac-bd05-c9a9f4c3cc1d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A beta-hemolytic colony that is bacitracin-sensitive and PYR positive is presumptively identified as which organism?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus aureus"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes is PYR positive and bacitracin-sensitive; enterococci are also PYR positive but differ by being bile-esculin positive with growth in 6.5% NaCl.'),
('c26c97d6-80b6-5039-a11d-ec623d3fb92b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Vancomycin-resistant enterococci responsible for many nosocomial outbreaks are most often which species?', '["Enterococcus faecium","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes","Enterococcus durans"]'::jsonb, 'Enterococcus faecium', 'E. faecium is the species most frequently responsible for VRE outbreaks; the vanA/vanB gene clusters confer high-level resistance and the organism is usually also ampicillin-resistant.'),
('8e154155-7398-5ec5-ae14-655e54c3548b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism characteristically produces surface slime (biofilm) that allows it to adhere to and persist on intravascular catheters and cerebrospinal fluid shunts?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis characteristically produces extracellular slime (biofilm) that enables persistent colonization of intravascular catheters, shunts and other artificial devices.'),
('a92ac09c-ea43-5359-baa6-dad0b9ff9a4a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Resistance to novobiocin is a laboratory test that identifies which organism?', '["Staphylococcus saprophyticus","Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Staphylococcus saprophyticus', 'S. saprophyticus is the coagulase-negative staphylococcus that is novobiocin-resistant, separating it from S. epidermidis, which is novobiocin-sensitive.'),
('69ff0eb4-d05e-50f7-97f9-9547ca5f112e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The clear zone of complete (beta) hemolysis produced by group A streptococci on blood agar is due to which products?', '["Streptolysins O and S","Capsular polysaccharide","M protein","Protein A","Coagulase"]'::jsonb, 'Streptolysins O and S', 'S. pyogenes produces streptolysin O (oxygen-labile) and streptolysin S (oxygen-stable), both of which lyse red blood cells to produce complete (beta) hemolysis.'),
('07ccfa24-834a-5970-ae0d-457f48301e05'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most common bacterial cause of acute otitis media and community-acquired pneumonia requiring invasive pneumococcal disease prevention in children?', '["Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the most common bacterial cause of acute otitis media, sinusitis and community-acquired pneumonia in children, and is covered by the conjugate vaccine PCV13.'),
('dc93d691-e159-5a51-abe7-08b1a6860051'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism owes its virulence largely to a polysaccharide capsule with more than 90 serotypes, and is the target of PCV13 and PPSV23 vaccines?', '["Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae expresses an antiphagocytic polysaccharide capsule with more than 90 serotypes; PCV13 and PPSV23 target these capsular polysaccharides.'),
('1f2b1cac-e7b8-532b-865c-5a0bc3514324'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An elevated antistreptolysin O (ASO) titer most commonly reflects recent infection with which organism?', '["Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis"]'::jsonb, 'Streptococcus pyogenes', 'The ASO titer measures antibody against the streptolysin O of S. pyogenes; a rising titer is evidence of recent group A streptococcal infection, e.g., preceding rheumatic fever.'),
('d9bf8a35-6ebf-534e-83b8-bfc85762a119'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A diabetic patient develops acute onset of fever, bone pain and tenderness at the lower lumbar spine. Which organism is the most common cause of acute hematogenous osteomyelitis in adults?', '["Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the most common cause of acute hematogenous osteomyelitis and septic arthritis in both adults and children because of its propensity to seed bone.'),
('ce08319a-2a7c-53db-9f5e-ae1edf963010'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'First-line antibiotic therapy for acute group A streptococcal pharyngitis is which of the following?', '["Penicillin","Vancomycin","Metronidazole","Amphotericin B","Caspofungin"]'::jsonb, 'Penicillin', 'Penicillin (oral penicillin V or intramuscular benzathine penicillin) remains the drug of choice for group A streptococcal pharyngitis and reliably prevents acute rheumatic fever.'),
('86f7a4bf-7af0-501b-a6df-56e5222a22ea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The vanA gene cluster, which confers high-level vancomycin and teicoplanin resistance, is carried by which organisms?', '["Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus agalactiae"]'::jsonb, 'Enterococcus faecalis', 'The vanA gene cluster, usually plasmid- or transposon-mediated, confers high-level inducible resistance to vancomycin and teicoplanin in enterococci (VRE), particularly E. faecium and E. faecalis.'),
('6736936e-dbf7-572c-a6ea-b553a6a67231'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Elevated anti-DNase B titers are evidence of recent infection with which organism?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'DNase B is an extracellular product of S. pyogenes; anti-DNase B titers document recent group A streptococcal infection and are particularly useful when the ASO titer is not elevated, as after skin infection.'),
('659b7e08-3dda-5d02-82ee-6532bdb19ded'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A child with superficial pustular skin lesions develops widespread bullae followed by peeling of the skin. The causative organism produces an exfoliative toxin. Which organism is it?', '["Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae","Staphylococcus aureus","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'S. aureus produces exfoliative toxins A and B, which cleave desmoglein-1 and produce the widespread bullous desquamation of scalded skin syndrome.'),
('4410b368-ab8c-54fb-ba0d-ee3d2db8b486'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A schoolchild develops pharyngitis, fever and a sandpaper-like erythematous rash. The eruptive illness is caused by the erythrogenic toxin of which organism?', '["Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes produces the pyrogenic (erythrogenic) exotoxin that causes the diffuse erythematous rash, strawberry tongue and desquamation of scarlet fever.'),
('01563423-9b7b-5468-b517-1dd150389b39'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms is a non-spore-forming Gram-positive coccus carrying the Lancefield group D antigen and frequently colonizing the gastrointestinal tract?', '["Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus aureus","Staphylococcus epidermidis"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is a Gram-positive coccus carrying the Lancefield group D antigen, colonizes the gastrointestinal tract, and causes nosocomial urinary tract and intra-abdominal infections.'),
('51d43977-0fe2-5226-a38c-345a125e73a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 65-year-old with a recent cerebrospinal fluid leak develops bacterial meningitis. Which organism should be strongly suspected?', '["Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is a classic cause of recurrent bacterial meningitis in patients with cerebrospinal fluid leak, and of meningitis in older adults and splenectomized patients.'),
('8c8c7852-26b2-5898-ad9a-1fdc9fbedf78'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'PPSV23, the 23-valent pneumococcal polysaccharide vaccine, provides protection against disease caused by which organism?', '["Streptococcus pneumoniae","Staphylococcus aureus","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes"]'::jsonb, 'Streptococcus pneumoniae', 'PPSV23 contains capsular polysaccharides from the 23 most prevalent pneumococcal serotypes and is recommended for adults aged 65 years or older and high-risk groups to prevent invasive pneumococcal disease.'),
('72b74d6f-061d-5ebf-ad99-05ccc2b15e65'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An alpha-hemolytic, optochin-susceptible, bile-soluble Gram-positive diplococcus recovered from blood cultures is most likely which organism?', '["Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the alpha-hemolytic, optochin-sensitive, bile-soluble Gram-positive diplococcus characteristically recovered from blood or cerebrospinal fluid.'),
('17fd2100-6673-5a89-b607-c46675399217'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The mecA gene, encoding the altered penicillin-binding protein PBP2a, confers methicillin resistance on which organism?', '["Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'mecA, carried on the SCCmec element, encodes PBP2a in S. aureus (MRSA), giving resistance to all beta-lactams including methicillin, nafcillin and cephalosporins.'),
('79a87f46-9470-5ea3-8aea-3b0b4555f14b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 25-year-old male presents with fever, productive cough and lobar consolidation. Which organism is the most likely cause of this community-acquired pneumonia?', '["Streptococcus pneumoniae","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus aureus","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the leading cause of community-acquired lobar pneumonia in previously healthy adults.'),
('8b524d84-66c7-5f5d-917c-21f9c8922805'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Rapid spread of group A streptococcal cellulitis along tissue planes is promoted by which of the following?', '["Hyaluronidase","Coagulase","Protein A","Catalase","Streptokinase"]'::jsonb, 'Hyaluronidase', 'Hyaluronidase degrades hyaluronic acid in the ground substance of connective tissue, acting as a spreading factor that facilitates rapid extension of group A streptococcal cellulitis and fasciitis.'),
('135bf486-af2b-54ff-9bf2-d19db2fbcb57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Beta-hemolysis of group A streptococci on blood agar is caused by which agents?', '["Streptolysins O and S","Capsular polysaccharide","M protein","Protein A","Coagulase"]'::jsonb, 'Streptolysins O and S', 'Streptolysin O (oxygen-labile) and streptolysin S (oxygen-stable) lyse red blood cells completely, producing the clear zones of beta-hemolysis characteristic of S. pyogenes.'),
('9ab7c59e-701b-5cd4-aab5-38dca4d2a980'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A Gram-positive coccus in grape-like clusters that is catalase positive belongs most likely to which group before further identification?', '["Staphylococci","Streptococci","Enterococci","Pneumococci","Viridans streptococci"]'::jsonb, 'Staphylococci', 'Grape-cluster Gram-positive cocci with positive catalase indicate staphylococci; all true streptococci and enterococci are catalase-negative.'),
('a8b8c756-859b-591a-a5fe-7c9745499711'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'PBP2a, the low-affinity penicillin-binding protein responsible for methicillin resistance, is expressed by which organism?', '["Staphylococcus aureus (MRSA)","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus aureus (MRSA)', 'In MRSA, the mecA gene encodes PBP2a, which has low affinity for beta-lactams, allowing continued peptidoglycan synthesis and resistance to methicillin, nafcillin and cephalosporins.'),
('7d2f6184-3ad7-57ff-b385-b229aaa8a858'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Group B streptococcus (S. agalactiae) is presumptively identified by which combination of test results?', '["CAMP positive and hippurate positive","Bacitracin sensitive and PYR positive","Optochin sensitive and bile soluble","Catalase positive and coagulase positive","Novobiocin resistant"]'::jsonb, 'CAMP positive and hippurate positive', 'S. agalactiae produces the CAMP factor and hydrolyzes sodium hippurate, both of which presumptively identify group B streptococcus and differentiate it from group A.'),
('cbc7abe2-97c8-57bc-8f74-98b11a0dcafe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The antiphagocytic polysaccharide capsule, the basis of the serotypes covered by pneumococcal vaccines, is the principal virulence factor of which organism?', '["Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Streptococcus pneumoniae', 'The pneumococcal capsule resists phagocytosis and its more than 90 serotypes form the basis of the PCV13 and PPSV23 vaccines; unencapsulated pneumococci are avirulent.'),
('518bbbc5-1cdc-5254-bc93-17c5a7fe6376'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism typically forms golden-yellow colonies on blood agar and is catalase positive, coagulase positive and a mannitol fermenter?', '["Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus forms golden-yellow colonies and is catalase positive, coagulase positive, DNase positive and a mannitol fermenter, features that separate it from the other species listed.'),
('43b88fc4-e95a-5945-af37-3fbe7190164a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most common cause of infective endocarditis in intravenous drug users?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the leading cause of infective endocarditis in intravenous drug users, typically involving the tricuspid valve.'),
('88e096d7-1480-507a-b03e-ec6a724473f0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A previously healthy young adult develops sudden fever, productive cough and lobar consolidation on chest radiograph. Which organism is the most likely cause?', '["Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the leading cause of community-acquired lobar pneumonia in previously healthy adults.'),
('fe6057ba-bb54-56b4-9936-78a2b4ab43dc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most frequent cause of pyogenic infections such as boils, carbuncles, abscesses and wound infections?', '["Streptococcus pneumoniae","Staphylococcus aureus","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the predominant pyogenic Gram-positive coccus, causing boils, carbuncles, abscesses, wound infections and bone and joint infections.'),
('b7f9de72-4af4-5ea6-af35-fc2906b8f8e4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which antibiotic is combined with a penicillin (e.g., ampicillin) to achieve bactericidal synergy in the treatment of enterococcal endocarditis?', '["Gentamicin","Clindamycin","Doxycycline","Ceftriaxone","Azithromycin"]'::jsonb, 'Gentamicin', 'Aminoglycosides such as gentamicin penetrate enterococci poorly when used alone, but combined with ampicillin they provide bactericidal synergy essential for enterococcal endocarditis.'),
('80743b82-830d-5cd1-902b-b145a83c38d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'All of the following are classic causes of community-acquired bacterial meningitis EXCEPT:', '["Staphylococcus epidermidis","Streptococcus pneumoniae","Neisseria meningitidis","Haemophilus influenzae type b","Streptococcus agalactiae"]'::jsonb, 'Staphylococcus epidermidis', 'S. pneumoniae, N. meningitidis, H. influenzae type b and group B streptococci are classic causes of bacterial meningitis; S. epidermidis chiefly causes shunt- or device-associated meningitis.'),
('bde2bbd2-4857-5e80-8637-c14da189d865'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Subacute infective endocarditis that follows dental procedures is classically caused by which organism?', '["Viridans group streptococci","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Viridans group streptococci', 'Viridans streptococci (e.g., S. mutans, S. sanguinis) are the most common cause of subacute infective endocarditis on damaged native valves, seeded during transient bacteremia from dental work.'),
('0e7f7738-f7cd-53f3-a8cb-559e3e6af913'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which description correctly characterizes Staphylococcus epidermidis?', '["Coagulase-negative coccus that causes infections of prosthetic devices","Coagulase-positive coccus that causes boils","Beta-hemolytic group A streptococcus","Alpha-hemolytic diplococcus with a capsule","Catalase-negative intestinal coccus"]'::jsonb, 'Coagulase-negative coccus that causes infections of prosthetic devices', 'S. epidermidis is a coagulase-negative, catalase-positive staphylococcus that causes infection mainly in the presence of prosthetic or indwelling devices, through biofilm formation.'),
('90581845-d457-5756-b47d-73ea6d20272b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most commonly encountered blood culture contaminant, frequently yielding false-positive results in the laboratory?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most common blood culture contaminant because it is a ubiquitous skin commensal present at the venipuncture site.'),
('a40bfc09-5248-5c6a-8af8-0a251c89ffc3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which toxin of Staphylococcus aureus causes rapid-onset (1-6 hours) food poisoning?', '["Heat-stable enterotoxin","Exfoliative toxin","TSST-1","Panton-Valentine leukocidin","Streptolysin O"]'::jsonb, 'Heat-stable enterotoxin', 'The heat-stable enterotoxins of S. aureus are preformed in food, survive reheating, and stimulate the vomiting reflex, producing acute food poisoning within 1-6 hours.'),
('1fc2c19d-ecbb-557c-a737-09aacbd721be'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Optochin (ethylhydrocupreine) disk susceptibility is a laboratory test that identifies which organism?', '["Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is inhibited by optochin, which separates it from the optochin-resistant viridans group streptococci.'),
('30cbffdf-bfa2-525a-b26a-3bcd2511a9ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is identified by its resistance to novobiocin and its association with acute urinary tract infection in young, sexually active women?', '["Staphylococcus saprophyticus","Staphylococcus epidermidis","Streptococcus agalactiae","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Staphylococcus saprophyticus', 'S. saprophyticus is the novobiocin-resistant coagulase-negative staphylococcus that is a leading cause of cystitis in young women.'),
('aacdd3a5-d5b2-5c43-8f74-048c3589f57e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The Panton-Valentine leukocidin, a pore-forming cytotoxin that destroys leukocytes, is associated with which clinical picture in community-acquired MRSA?', '["Necrotizing pneumonia and recurrent skin abscesses","Food poisoning accompanied by associated clinical symptoms","Scalded skin syndrome mediated by specific receptor activation","Toxic shock syndrome without affecting the primary tissue pathway","Pseudomembranous colitis leading to subsequent cellular adaptation"]'::jsonb, 'Necrotizing pneumonia and recurrent skin abscesses', 'PVL-producing community-acquired MRSA causes severe necrotizing (hemorrhagic) pneumonia and recurrent furuncles and skin abscesses.'),
('18d9ae4b-b3da-5d59-ac83-6f656501df59'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Erysipelas, a painful skin infection with a sharply demarcated raised border, is classically caused by which organism?', '["Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Streptococcus pyogenes', 'Erysipelas, a superficial infection of the skin with a sharply demarcated raised border, is the classic manifestation of group A streptococcal (S. pyogenes) infection.'),
('7f6d0c9f-eb14-5b48-92bf-9a4a1e2f3e2e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A patient develops a rapidly progressive necrotizing soft tissue infection spreading along fascial planes. Which organism is the classic cause?', '["Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes (group A) is the classic ''flesh-eating'' organism causing necrotizing fasciitis, a rapidly destructive infection of the deep fascia.'),
('916a9c4f-c50e-5a94-9791-f6f758e0fa59'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The heat-stable enterotoxin that causes staphylococcal food poisoning is produced by which organism?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus elaborates heat-stable enterotoxins that act on the gut to produce acute vomiting and diarrhea, and cause food poisoning when preformed in contaminated food.'),
('0c5f5b5d-550c-5e6d-90d8-8c63a146ad04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'TSST-1, the toxin responsible for toxic shock syndrome, is produced by which organism?', '["Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'Toxic shock syndrome toxin-1 (TSST-1), a superantigen, is produced by toxigenic strains of S. aureus, classically in tampon-associated and wound-associated disease.'),
('bbc420d8-e6ab-5bd1-9f9e-63b5114e093c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The vanB gene cluster, which confers vancomycin resistance, is characteristically found in which organisms?', '["Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus epidermidis"]'::jsonb, 'Enterococcus faecalis', 'The vanB gene cluster mediates inducible, moderate-level vancomycin resistance (without teicoplanin resistance) in enterococci (VRE), especially E. faecalis and E. faecium.'),
('993803c8-1c23-5d46-9e6d-4c92da2664cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Vancomycin exerts its bactericidal action against Gram-positive cocci by which mechanism?', '["Binding D-alanyl-D-alanine and inhibiting peptidoglycan cross-linking","Binding the 50S ribosomal subunit to inhibit protein synthesis","Inhibiting DNA gyrase","Disrupting the cytoplasmic membrane","Inhibiting folic acid synthesis"]'::jsonb, 'Binding D-alanyl-D-alanine and inhibiting peptidoglycan cross-linking', 'Vancomycin binds the D-alanyl-D-alanine terminus of peptidoglycan precursors, blocking transpeptidation and cell-wall cross-linking in Gram-positive bacteria.'),
('7c5fc088-fdcd-583a-ad70-6213dd1148b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Lipoteichoic acid, a surface polymer of Staphylococcus aureus, contributes to virulence chiefly by which mechanism?', '["Mediating adherence to host cells and mucosal surfaces","Cleaving IgA accompanied by associated clinical symptoms","Lysing red blood cells mediated by specific receptor activation","Clotting plasma without affecting the primary tissue pathway","Inhibiting neutrophil chemotaxis leading to subsequent cellular adaptation"]'::jsonb, 'Mediating adherence to host cells and mucosal surfaces', 'Lipoteichoic acid anchors the cell wall and mediates adherence of Gram-positive cocci such as S. aureus to host cells and artificial surfaces, an early step in colonization.'),
('6475498e-42d2-59f2-9c5f-0e2e8786c4dc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A young menstruating woman using a vaginal tampon develops fever, diffuse erythema, myalgia and hypotension. Which organism is most likely responsible?', '["Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus aureus', 'S. aureus elaborates TSST-1, a superantigen causing toxic shock syndrome, classically associated with prolonged vaginal tampon use.'),
('f6341dd9-566a-5309-9259-1fd5c483fee1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is an opportunistic pathogen that most often causes nosocomial bacteremia in neonates and immunocompromised patients with indwelling catheters?', '["Staphylococcus epidermidis","Streptococcus pneumoniae","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis causes nosocomial bacteremia mainly in neonates and immunocompromised patients, where indwelling vascular catheters provide the portal of entry.'),
('b99a9637-e031-5a05-8f90-cafcadb8c848'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Streptococcus agalactiae (group B) is the leading cause of which infection in newborns?', '["Early-onset neonatal sepsis and meningitis","Pharyngitis","Dental caries","Prosthetic valve endocarditis in adults","Toxic shock syndrome"]'::jsonb, 'Early-onset neonatal sepsis and meningitis', 'S. agalactiae colonizes the maternal genital tract and is the leading cause of early-onset neonatal sepsis and meningitis acquired during passage through the birth canal.'),
('2518ef26-8c36-5daf-b970-ff8e2902b687'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Protein A, which binds the Fc region of IgG and impairs opsonization, is a cell-wall component of which organism?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'Protein A on the S. aureus surface binds the Fc portion of IgG, preventing Fc receptor-mediated opsonophagocytosis by neutrophils.'),
('87363474-0e59-596d-a9a5-a3c8b61b647d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Measurement of the antistreptolysin O (ASO) titer is used in which clinical setting?', '["Documenting recent group A streptococcal infection","Diagnosing acute osteomyelitis","Screening for MRSA carriage","Monitoring vancomycin levels","Diagnosing pneumococcal pneumonia"]'::jsonb, 'Documenting recent group A streptococcal infection', 'ASO antibodies are directed against the streptolysin O of S. pyogenes; a rising titer is used to document recent group A streptococcal infection, e.g., in suspected rheumatic fever.'),
('ebf7ddaa-abd6-5449-b80d-cead3160ebef'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A sputum isolate shows capsular swelling (Quellung reaction) when mixed with antipneumococcal capsular antiserum. Which organism is most likely?', '["Staphylococcus epidermidis","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is identified by the Quellung reaction, in which type-specific capsular antiserum produces visible swelling of the capsule.'),
('89ac4854-004b-5868-8b54-dd220701b2a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms is the coagulase-negative staphylococcus that adheres to plastic surfaces and causes infection in the presence of prosthetic devices?', '["Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the coagulase-negative staphylococcus that adheres to plastic surfaces and causes infection on prosthetic devices through biofilm formation.'),
('9daa1d87-397e-584c-9a3d-79859c9f77d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'All of the following are TRUE of MRSA (methicillin-resistant Staphylococcus aureus) EXCEPT:', '["Resistance mediated by PBP2a encoded by mecA","Resistance to all beta-lactams including nafcillin and cephalosporins","Common cause of nosocomial and community-acquired infections","Susceptible to vancomycin","Resistance due to beta-lactamase production alone"]'::jsonb, 'Resistance due to beta-lactamase production alone', 'MRSA resistance results from the altered penicillin-binding protein PBP2a encoded by mecA, not from beta-lactamase; the blaZ beta-lactamase is a separate mechanism producing penicillin (not methicillin) resistance.'),
('138fb505-7836-5cbc-9e96-cff5650aa980'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A positive CAMP test is interpreted as presumptive evidence that the organism is which of the following?', '["Group B streptococcus (S. agalactiae)","Group A streptococcus","Staphylococcus aureus","Enterococcus","Streptococcus pneumoniae"]'::jsonb, 'Group B streptococcus (S. agalactiae)', 'The CAMP factor produced by S. agalactiae causes arrowhead enhancement of staphylococcal beta-hemolysis; a positive CAMP test presumptively identifies group B streptococcus.'),
('45d5438c-e201-52d6-8fb4-52eeb3c03d54'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The Streptococcus anginosus (milleri) group is classically associated with which clinical syndrome?', '["Deep abscess formation in internal organs","Neonatal sepsis","Subacute bacterial endocarditis","Urinary tract infection","Dental caries"]'::jsonb, 'Deep abscess formation in internal organs', 'The S. milleri (anginosus) group characteristically forms abscesses with pus in internal organs such as the liver, brain, lung and abdominal cavity.'),
('8f154b77-92f3-5ac7-839a-a5952d4c1ca8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A PYR-positive, bile-esculin-positive Gram-positive coccus that usually causes nosocomial urinary tract infections is most likely which organism?', '["Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is PYR positive and bile-esculin positive and is the common enterococcal cause of nosocomial urinary tract infection.'),
('a9b80035-aeca-5754-b62c-a6366da12dfd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A patient develops a tender, fluctuant skin abscess after minor trauma. Which organism is the most common cause?', '["Streptococcus pneumoniae","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the predominant cause of suppurative skin abscesses and is the most common pathogen recovered from a fluctuant skin lesion.'),
('53667de0-d121-57b0-8f15-f29cc240500c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'In the bile solubility test, Streptococcus pneumoniae is lysed because bile salts do which of the following?', '["Activate the organism''s autolysin, degrading the cell wall","Denature surface M protein","Neutralize the polysaccharide capsule","Block protein synthesis","Inhibit folate synthesis"]'::jsonb, 'Activate the organism''s autolysin, degrading the cell wall', 'Bile salts activate the pneumococcal autolysin LytA, which degrades the cell wall and causes lysis; viridans streptococci lack this bile solubility.'),
('0b72392d-acb7-5091-a824-0007de101b33'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is lysed by bile salts (bile-soluble), a reaction that separates it from the viridans group streptococci?', '["Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is bile-soluble (lysed by bile salts), which together with optochin sensitivity separates it from the bile-insoluble viridans streptococci.'),
('03043406-c01e-5841-8882-84df608d4ff3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Necrotizing fasciitis and streptococcal toxic shock-like syndrome are rapidly progressive invasive infections caused by which organism?', '["Streptococcus pyogenes","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes (group A) is the classic cause of necrotizing fasciitis and may be complicated by streptococcal toxic shock syndrome, both rapidly progressive and life-threatening.'),
('3dc25c08-db51-5d8a-9db3-38128d730463'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A beta-hemolytic colony that is sensitive to bacitracin and positive for PYR is presumptively identified as which organism?', '["Streptococcus pyogenes","Streptococcus agalactiae","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes (group A) is beta-hemolytic, bacitracin-sensitive and PYR positive; group B streptococci are bacitracin-resistant and PYR negative.'),
('9a990778-078f-54de-8601-c7c56b336fa7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Mannitol salt agar is selective and differential for which organisms?', '["Staphylococci (S. aureus ferments mannitol)","Streptococci accompanied by associated clinical symptoms","Enterococci mediated by specific receptor activation","Gram-negative bacilli without affecting the primary tissue pathway","Anaerobes leading to subsequent cellular adaptation"]'::jsonb, 'Staphylococci (S. aureus ferments mannitol)', 'The high salt content (7.5% NaCl) inhibits most organisms, selecting staphylococci; S. aureus ferments mannitol, turning the indicator yellow, while S. epidermidis does not.'),
('fd1664b6-3a90-524a-a63f-25046c155471'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Absence of hemolysis (gamma or non-hemolysis), or only partial (alpha) hemolysis on blood agar, is characteristic of which of the following?', '["Enterococci","S. pyogenes","S. pneumoniae","S. aureus","Most viridans streptococci on blood agar"]'::jsonb, 'Enterococci', 'Enterococci are usually alpha-hemolytic or non-hemolytic (gamma) on blood agar, in contrast to the beta-hemolytic S. pyogenes; the pneumococcus is alpha-hemolytic.'),
('cea4386d-6d5a-5972-9374-bbd389ddf06a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Acquired, clinically significant vancomycin resistance in enterococci is most often mediated by which gene cluster?', '["vanA","mecA","blaZ","ermB","tetM"]'::jsonb, 'vanA', 'vanA, typically plasmid or transposon mediated, is the most common mechanism of acquired high-level vancomycin resistance in enterococci (VRE); mecA confers methicillin resistance in S. aureus.'),
('9528f374-0065-5dff-a25f-c9636c6f1275'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Panton-Valentine leukocidin (PVL), associated with severe necrotizing pneumonia and skin abscesses, is a toxin of which organism?', '["Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'PVL is a bicomponent pore-forming toxin produced by community strains of S. aureus (especially CA-MRSA) and causes leukocyte destruction, necrotizing pneumonia and furunculosis.'),
('d3be390e-7d8b-52ef-99f3-b0a31af99367'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A positive coagulase test, in which the organism causes plasma to clot, is used to identify which organism?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus epidermidis","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'Coagulase converts fibrinogen to fibrin, clotting plasma; this test is positive only for S. aureus among the staphylococci.'),
('a33843a3-d270-57d0-ab6f-b860f30a7cf5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A child develops hematuria, hypertension and edema 2 weeks after streptococcal pharyngitis. Which organism caused the antecedent infection?', '["Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes"]'::jsonb, 'Streptococcus pyogenes', 'Acute post-streptococcal glomerulonephritis typically follows pharyngitis or pyoderma caused by nephritogenic strains of S. pyogenes.'),
('c928fa24-7bd2-5b93-808e-69ca7b21bf11'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'In the catalase test, the rapid production of gas bubbles on addition of hydrogen peroxide is characteristic of which group?', '["Staphylococci (catalase-positive)","Streptococci (catalase-negative)","Enterococci","Pneumococci","Lactobacilli"]'::jsonb, 'Staphylococci (catalase-positive)', 'Catalase decomposes hydrogen peroxide into water and oxygen, producing bubbles; staphylococci are catalase-positive, whereas streptococci, enterococci and pneumococci are catalase-negative.'),
('c76fe101-ffe8-575a-be65-984c688e7b67'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'M protein, which resists phagocytosis and is the basis of serotyping, is a surface protein of which organism?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus epidermidis","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Streptococcus pyogenes', 'M protein is the major antiphagocytic surface antigen of S. pyogenes; antibodies to it confer type-specific immunity and it is the basis of serotyping.'),
('e4e75d7c-d17f-5715-9b05-29aff47af44d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most common cause of septic arthritis in adults?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the most common cause of septic arthritis in adults, producing acute, destructive joint infection with purulent joint fluid.'),
('d34aef94-a781-5c91-971e-bcd2eb66a87b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Streptolysin S, an oxygen-stable hemolysin, is produced by which organism?', '["Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes produces both streptolysin O (oxygen-labile, antigenic) and streptolysin S (oxygen-stable, non-antigenic), which together cause beta-hemolysis.'),
('203fe1af-2038-5249-81b9-0e6ebad89947'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A positive PYR (pyrrolidonyl arylamidase) reaction identifies which of the following?', '["Streptococcus pyogenes and enterococci","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus agalactiae"]'::jsonb, 'Streptococcus pyogenes and enterococci', 'Both S. pyogenes (group A) and enterococci are PYR positive; they are separated among themselves by bile-esculin, salt tolerance and Lancefield grouping.'),
('784e43bc-aa30-5a6b-bb61-7bd10f15aacf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A child with acute pharyngitis develops fever, a strawberry tongue and a generalized erythematous rash with subsequent desquamation. Which organism is the cause?', '["Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'Scarlet fever is caused by S. pyogenes producing the pyrogenic (erythrogenic) exotoxin, giving the erythematous rash and later desquamation.'),
('7f414062-c04a-5681-9aa8-8f6de2b77f56'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is a leading cause of pneumonia in the elderly and is particularly severe in patients with hyposplenism or chronic lung disease?', '["Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is a leading cause of pneumonia in the elderly and is especially severe in asplenic patients and those with chronic lung disease.'),
('8e1b9d9e-93fd-5e94-b5f9-f8a6100f05d3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Acute rheumatic fever following group A streptococcal pharyngitis is mediated by immune cross-reactivity with tissue antigens. Which organism triggers this complication?', '["Enterococcus faecalis","Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'Acute rheumatic fever is triggered by certain M-protein serotypes of S. pyogenes that elicit antibodies cross-reactive with cardiac, joint and subcutaneous tissue.'),
('ac202155-8f54-5533-834c-08914d6ca50e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'PCV13, the 13-valent pneumococcal conjugate vaccine, protects against invasive disease caused by which organism?', '["Enterococcus faecalis","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus pyogenes"]'::jsonb, 'Streptococcus pneumoniae', 'PCV13 contains capsular polysaccharides of the 13 most common pneumococcal serotypes conjugated to a carrier protein, protecting mainly children against invasive pneumococcal disease.'),
('b5073667-b703-54d5-8530-c4b118f60f4e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which combination of laboratory characteristics identifies vancomycin-resistant enterococci (VRE)?', '["Growth in 6.5% NaCl, bile-esculin positivity, and vancomycin resistance (vanA/vanB)","Sensitivity to optochin and bile solubility","Beta-hemolysis and bacitracin sensitivity","Catalase positivity and coagulase production","Mannitol fermentation and novobiocin resistance"]'::jsonb, 'Growth in 6.5% NaCl, bile-esculin positivity, and vancomycin resistance (vanA/vanB)', 'VRE are enterococci (bile-esculin positive, growing in 6.5% NaCl) that have acquired vanA/vanB gene clusters conferring vancomycin resistance.'),
('6b0a6173-7834-5dac-a17f-3c27821894bb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A raised antistreptolysin O (ASO) titer would be expected after infection with which organism?', '["Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Streptococcus pyogenes', 'ASO antibodies are formed against the streptolysin O of S. pyogenes; elevated or rising titers indicate recent group A streptococcal infection.'),
('8da30a1e-1cb9-5586-86bc-512084c3a774'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Coagulase is the key enzyme that distinguishes which organism as positive among the staphylococci?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'Coagulase is positive only for S. aureus; S. epidermidis and S. saprophyticus are coagulase-negative.'),
('6a97ee6f-70b7-582f-9064-7527a76406ec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the group A streptococcus?', '["Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes is the group A streptococcus, identified by its group-specific cell-wall C-carbohydrate antigen and its unique sensitivity to bacitracin.'),
('eb2225c5-0fb5-599a-ad38-f720d26e2a7e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 10-year-old develops acute fever and bone pain localized to the distal femur. Which organism is the most common cause of acute hematogenous osteomyelitis in this age group?', '["Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the most common cause of acute hematogenous osteomyelitis in children, typically involving the metaphysis of long bones such as the distal femur.'),
('5b73816c-5fb4-535f-8937-832ad964db1b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A child presents with honey-colored crusted lesions around the nose and mouth. Which organism is the most likely cause of this impetigo?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'Non-bullous impetigo with honey-colored crusted lesions is caused by S. pyogenes (group A), often with S. aureus acting together.'),
('04ee3a45-0924-5542-893c-24feaf64e029'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'In the laboratory, differentiation of S. aureus from S. epidermidis is best achieved by which test?', '["Coagulase test","Optochin susceptibility","Bile solubility","Bacitracin sensitivity","CAMP test"]'::jsonb, 'Coagulase test', 'S. aureus is coagulase-positive, whereas S. epidermidis is coagulase-negative; this is the definitive separation between the two species.'),
('4abcd27c-66be-55db-9ae7-29d25df778de'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The acute vomiting and diarrhea of staphylococcal food poisoning result from which mechanism?', '["Heat-stable enterotoxin acting as a superantigen on the gut","An exfoliative toxin accompanied by associated clinical symptoms","Invasion of the intestinal mucosa mediated by specific receptor activation","TSST-1 via the bloodstream without affecting the primary tissue pathway","Panton-Valentine leukocidin leading to subsequent cellular adaptation"]'::jsonb, 'Heat-stable enterotoxin acting as a superantigen on the gut', 'S. aureus produces heat-stable enterotoxins that are ingested preformed in food and stimulate the emetic reflex and intestinal secretion, producing rapid-onset food poisoning.'),
('071752a9-230d-5acf-86b9-2ed16b01e548'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'PPSV23 is indicated to prevent invasive disease caused by which organism in adults aged 65 years or older and in high-risk groups?', '["Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus aureus","Streptococcus pyogenes"]'::jsonb, 'Streptococcus pneumoniae', 'PPSV23, the 23-valent pneumococcal capsular polysaccharide vaccine, prevents invasive pneumococcal disease and is recommended for older adults and high-risk patients.'),
('97b9d727-aee3-573b-a916-cbfd2ea8e366'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism produces a heat-stable enterotoxin that, when preformed in food, causes acute vomiting and diarrhea within hours of ingestion?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'S. aureus elaborates heat-stable enterotoxins that resist reheating; ingestion of the preformed toxin causes vomiting and diarrhea within 1-6 hours.'),
('f63df65c-8970-50f6-a7ee-17e1b9444cdc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A previously healthy patient develops rapidly spreading necrosis of the deep fascia after minor skin trauma, with severe systemic toxicity. Which organism is the classic etiologic agent?', '["Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes (group A) is the classic ''flesh-eating'' organism causing necrotizing fasciitis with extensive fascial destruction and toxic shock-like features.'),
('fc7247cf-dbda-5d09-8738-56ab9e50ec47'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism characteristically produces an extracellular polysaccharide slime (biofilm) that enables adherence to and persistence on indwelling devices?', '["Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis produces extracellular polymeric slime (biofilm) that allows it to adhere to and persist on catheters, shunts and prosthetic devices.'),
('fef13650-d0db-5fba-aa62-eec77945d291'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism most commonly infects prosthetic joints and vascular grafts shortly after implantation, owing to its ability to form biofilms?', '["Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis forms biofilms on implanted prostheses, making it the most common cause of prosthetic joint and vascular graft infection.'),
('6ac5ff3e-dade-5782-87a9-2b5c6dc8c131'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'On which culture medium is the hemolytic pattern (alpha, beta or gamma) of Gram-positive cocci best assessed?', '["Blood agar","MacConkey agar","Mannitol salt agar","Thayer-Martin agar","Lowenstein-Jensen medium"]'::jsonb, 'Blood agar', 'Blood agar containing 5% sheep blood demonstrates the hemolytic reactions (alpha, beta, gamma) that are fundamental to classifying streptococci and staphylococci.'),
('50319df2-cbf3-5671-b47d-d121469a8b79'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which Gram-positive coccus is the most common cause of bacterial meningitis in adults and a leading cause of otitis media, sinusitis and community-acquired pneumonia?', '["Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the leading cause of community-acquired pneumonia and of bacterial meningitis in adults, and a major cause of otitis media and sinusitis.'),
('c94b42a1-28bf-5e49-b843-151e5e172f0d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 35-year-old presents with a tender, fluctuant skin abscess. Which organism is the most likely cause?', '["Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the most common cause of suppurative skin abscesses, presenting as a tender, fluctuant, well-circumscribed lesion.'),
('98110b82-bd75-5035-b944-396fe8dd754e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Bacteriocins (enterocins), antibacterial peptides that inhibit other Gram-positive organisms, are characteristically produced by which organism?', '["Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Enterococcus faecalis', 'Enterococci, including E. faecalis, produce antibacterial peptides termed enterocins (bacteriocins) that inhibit the growth of other Gram-positive bacteria.'),
('eb9e822b-2660-5dc1-bf84-f24c9bf762e4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Gram-positive organisms arranged in lancet-shaped pairs observed in purulent sputum are most consistent with which of the following?', '["Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the lancet-shaped, Gram-positive diplococcus classically seen in pairs in purulent sputum from patients with pneumococcal pneumonia.'),
('994be5ee-dce6-5e23-9480-478cbd3634dd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Superantigens such as TSST-1 and the pyrogenic exotoxins cause massive nonspecific T-cell activation. Which Gram-positive coccal species are their principal producers?', '["S. aureus and S. pyogenes","S. epidermidis","S. pneumoniae","Enterococcus faecalis","S. agalactiae"]'::jsonb, 'S. aureus and S. pyogenes', 'TSST-1 and staphylococcal enterotoxins come from S. aureus, and the pyrogenic (erythrogenic) exotoxins come from S. pyogenes; both are superantigens causing toxic shock and rash.'),
('67638c5c-4fc0-59b7-aa7d-212dc13a83b5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Staphylococcus aureus is correctly characterized by which statement?', '["Catalase-positive and coagulase-positive","Catalase-negative and coagulase-negative","Optochin-sensitive","Bile-soluble","CAMP positive"]'::jsonb, 'Catalase-positive and coagulase-positive', 'S. aureus is the only catalase-positive, coagulase-positive Gram-positive coccus among the staphylococci, distinguishing it from streptococci and the coagulase-negative staphylococci.'),
('a7f9e9ae-a6ba-50fd-bd95-1e5f7aaec5d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The sandpaper-like erythematous rash with desquamation of scarlet fever is caused by which toxin of Streptococcus pyogenes?', '["Pyrogenic (erythrogenic) exotoxin","Exfoliative toxin","Heat-stable enterotoxin","Panton-Valentine leukocidin","Streptolysin O"]'::jsonb, 'Pyrogenic (erythrogenic) exotoxin', 'Scarlet fever follows pharyngeal infection with a lysogenized strain of S. pyogenes producing the pyrogenic (erythrogenic) exotoxin responsible for the rash and desquamation.'),
('b043bd74-e237-5814-9284-7e781ad0d78e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms grows in 6.5% NaCl broth and hydrolyzes esculin in the presence of bile, features used to differentiate it from streptococci?', '["Staphylococcus aureus","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis grows in 6.5% NaCl broth and hydrolyzes bile-esculin, which differentiates enterococci from the other streptococci.'),
('10979740-5da6-59f1-8bf6-b42feed68dd4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which method is used to visualize the capsule of Streptococcus pneumoniae in the laboratory?', '["India ink (negative staining) or capsular staining","Ziehl-Neelsen stain accompanied by associated clinical symptoms","Gram stain only mediated by specific receptor activation","Gimenez stain without affecting the primary tissue pathway","Wright stain leading to subsequent cellular adaptation"]'::jsonb, 'India ink (negative staining) or capsular staining', 'The pneumococcal capsule is demonstrated by negative staining with India ink or by capsular stains that show a clear halo around the organism.'),
('be064749-488b-5808-b674-1d1dedef3e01'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Growth in 6.5% NaCl broth is characteristically positive for which Gram-positive coccus?', '["Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Streptococcus agalactiae"]'::jsonb, 'Enterococcus faecalis', 'Salt tolerance, demonstrated by growth in 6.5% NaCl broth, is a classic feature used to identify enterococci such as E. faecalis.'),
('2ff4463d-5cdf-53c3-99b3-d629f7708da6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is distinguished from Staphylococcus aureus by being coagulase-negative and mannitol non-fermenting on mannitol salt agar?', '["Streptococcus pyogenes","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is coagulase-negative and does not ferment mannitol, separating it from S. aureus on mannitol salt agar.'),
('b0c1c9da-f3e1-5b39-801a-9ce9b2f075dd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which characteristic is used to distinguish S. epidermidis from S. aureus?', '["Coagulase negative and mannitol non-fermenter","Coagulase positive accompanied by associated clinical symptoms","Optochin sensitive mediated by specific receptor activation","Bile soluble without affecting the primary tissue pathway","Bacitracin sensitive leading to subsequent cellular adaptation"]'::jsonb, 'Coagulase negative and mannitol non-fermenter', 'S. epidermidis is coagulase-negative and does not ferment mannitol, whereas S. aureus is coagulase-positive and ferments mannitol.'),
('e6d3dc9b-f786-5ea6-b413-d3b42819d4e9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which alpha-hemolytic organism is identified by its susceptibility to optochin and its solubility in bile salts?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the alpha-hemolytic organism identified by optochin susceptibility and bile solubility, which distinguish it from the viridans streptococci.'),
('7492aa44-07fb-5249-aa41-742a9c2aac41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A hospitalized patient on prolonged vancomycin therapy develops bacteremia with a Gram-positive coccus that is vancomycin resistant. Which organism is the most likely isolate?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Enterococcus faecalis', 'Enterococci acquire vanA/vanB gene clusters conferring vancomycin resistance (VRE), especially under prolonged selective vancomycin pressure in hospitalized patients.'),
('0591b35b-e117-540a-92ab-97657b01ec91'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 60-year-old female in the ICU presents with fever, hypotension and elevated lactate. Which Gram-positive coccus is a leading etiologic agent of this septic picture?', '["Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is a leading cause of severe sepsis and bacteremia in hospitalized patients, presenting with fever, hypotension and organ dysfunction.'),
('b905c4c6-9c9a-5859-9d52-c5c90a791d7c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Pneumolysin, a cholesterol-dependent pore-forming cytolysin that damages host cells and activates complement, is produced by which organism?', '["Streptococcus pneumoniae","Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pneumoniae', 'Pneumolysin is the pneumococcal cytolysin that lyses host cells and activates complement, contributing to the tissue injury of pneumococcal pneumonia.'),
('22276b5f-6b55-535f-b7cf-44cec704a752'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The thick peptidoglycan cell wall that retains crystal violet and imparts the violet stain in the Gram reaction is characteristic of which organisms?', '["Gram-positive cocci such as the staphylococci","Gram-negative bacilli accompanied by associated clinical symptoms","Mycobacteria mediated by specific receptor activation","Spirochetes without affecting the primary tissue pathway","Mycoplasmas leading to subsequent cellular adaptation"]'::jsonb, 'Gram-positive cocci such as the staphylococci', 'Gram-positive bacteria possess a thick peptidoglycan layer that retains the crystal violet-iodine complex during decolorization; Gram-negative organisms have a thin layer and pink counterstain.'),
('bb05e3d5-687c-50ff-b99a-4b1d7e6b3254'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism, a commensal of human skin, causes opportunistic infection predominantly when prosthetic or indwelling devices are present?', '["Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is a commensal of human skin that causes opportunistic infection of prosthetic and indwelling devices, chiefly by biofilm formation.'),
('88604a46-b7ce-52ce-bfb2-de69662fc07e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Toxic shock syndrome is caused by the superantigen TSST-1 produced by which organism?', '["Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'TSST-1, the toxic shock syndrome superantigen, is produced by toxigenic strains of S. aureus, classically in tampon-associated and wound-associated cases.'),
('09f218b6-4c9d-5b0b-975c-00decbd70107'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The vanB gene mediates vancomycin resistance by altering cell-wall peptidoglycan precursor synthesis in which organism?', '["Staphylococcus aureus","Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Enterococcus faecalis', 'vanB alters the peptidoglycan precursor (D-Ala-D-Lac) to confer inducible, moderate-level vancomycin resistance in enterococci (VRE) such as E. faecalis and E. faecium.'),
('f05c9ff6-cc8f-5725-8ad8-3e2ff3be0e77'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The primary antibacterial mechanism of vancomycin is which of the following?', '["Inhibition of peptidoglycan cross-linking by binding D-alanyl-D-alanine","Inhibition of protein synthesis at the 50S ribosomal subunit","Inhibition of DNA synthesis","Disruption of the cytoplasmic membrane","Inhibition of folic acid synthesis"]'::jsonb, 'Inhibition of peptidoglycan cross-linking by binding D-alanyl-D-alanine', 'Vancomycin binds the D-alanyl-D-alanine terminus of peptidoglycan precursors, blocking transpeptidation and cell-wall cross-linking in Gram-positive organisms.'),
('b80d7468-df35-54b6-bf6b-f79a8afdc738'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most frequent cause of infection of permanently implanted pacemaker leads due to surface biofilm formation?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most common cause of infection of permanently implanted pacemaker leads and other devices, mediated by surface biofilm.'),
('9553479c-5662-5405-a4d6-07059a5db690'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism remains the most common cause of community-acquired pneumonia in adults and is covered by the conjugate pneumococcal vaccine?', '["Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae remains the most common cause of community-acquired pneumonia in adults and is the target of the conjugate pneumococcal vaccine (PCV13).'),
('5e59e59f-07fa-5ee5-9838-480a83fe8fd2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which Gram-positive coccus causes bullous impetigo through the action of its exfoliative toxin?', '["Staphylococcus aureus","Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'Bullous impetigo is caused by S. aureus strains producing exfoliative toxin that cleaves desmoglein-1, whereas non-bullous impetigo is caused by S. aureus and/or S. pyogenes.'),
('47871c3d-c131-5cd1-93be-12f63bb98edc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the leading cause of early-onset neonatal sepsis and meningitis?', '["Streptococcus agalactiae","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Streptococcus agalactiae', 'S. agalactiae (group B) colonizes the maternal genital tract and is the leading cause of early-onset neonatal sepsis and meningitis.'),
('43940d50-3514-534e-a01f-4b776083ff47'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'In the laboratory, Staphylococcus saprophyticus is distinguished from S. epidermidis by its resistance to which antibiotic disk?', '["Novobiocin","Bacitracin","Optochin","Vancomycin","Methicillin"]'::jsonb, 'Novobiocin', 'S. saprophyticus is novobiocin-resistant while S. epidermidis is novobiocin-sensitive; this test separates the two coagulase-negative staphylococci.'),
('00b4a5b8-3a50-5126-9f24-7e3ead4b1042'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed Gram-positive cocci is uniquely coagulase positive, a property that separates it from the other species listed?', '["Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the only coagulase-positive species among the options; coagulase is used to separate it from the coagulase-negative staphylococci.'),
('26c4e2b2-58aa-56b0-b0d5-5e071b935d78'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 3-year-old develops bullous impetigo with honey-colored crusting around the nose. Which organism is most likely responsible?', '["Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'Bullous impetigo is caused by exfoliative toxin-producing S. aureus; the honey-colored crusted and blistering lesions localize around the nose and mouth.'),
('bbec74ec-200c-5fb3-bae0-a440fb9c77b1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The CAMP test, showing arrowhead enhancement of staphylococcal beta-hemolysis, provides presumptive identification of which organism?', '["Streptococcus agalactiae","Streptococcus pyogenes","Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus agalactiae', 'The CAMP factor produced by S. agalactiae (group B) causes arrowhead enlargement of the beta-hemolysis of S. aureus, giving presumptive identification of GBS.'),
('28b125d9-452f-5973-baeb-074b63ed6fbc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism carries the mecA gene encoding penicillin-binding protein 2a and is therefore resistant to nafcillin and other beta-lactams?', '["Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'MRSA strains of S. aureus carry mecA, which encodes PBP2a, a penicillin-binding protein with low affinity for beta-lactams, conferring nafcillin and methicillin resistance.'),
('515fd55d-97ed-56f8-a1ae-e5cf874784f0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The mecA gene, which confers methicillin resistance by producing the altered PBP2a, is most commonly found in which of the following?', '["Staphylococcus aureus (MRSA)","Staphylococcus epidermidis","Staphylococcus saprophyticus","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus aureus (MRSA)', 'mecA, carried on the SCCmec element, is the genetic determinant of methicillin resistance in S. aureus (MRSA), encoding the low-affinity penicillin-binding protein PBP2a.'),
('02f0d34d-c6d9-55a0-9fec-e1dfd079f8e1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which test is positive for Streptococcus agalactiae (group B) but negative for S. pyogenes (group A)?', '["Hippurate hydrolysis (and CAMP)","Bacitracin sensitivity","PYR test","Optochin sensitivity","Bile solubility"]'::jsonb, 'Hippurate hydrolysis (and CAMP)', 'S. agalactiae hydrolyzes hippurate and is CAMP positive, while S. pyogenes is hippurate negative and CAMP negative; the reverse holds for bacitracin sensitivity and PYR.'),
('e126d972-e308-5027-b661-2a14de8e0f28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which laboratory test separates the viridans group streptococci from Streptococcus pneumoniae?', '["Optochin sensitivity and bile solubility","Coagulase test","Catalase test","Bacitracin sensitivity","Novobiocin sensitivity"]'::jsonb, 'Optochin sensitivity and bile solubility', 'Both are alpha-hemolytic; S. pneumoniae is optochin-sensitive and bile-soluble, whereas the viridans streptococci are optochin-resistant and bile-insoluble.'),
('894a5fdc-524a-59d8-adf8-4b9ff276c1b1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Pneumococcal pneumonia is characteristically associated with which clinical feature?', '["Lobar consolidation with rusty sputum","Honey-colored crusted skin lesions","Vesicular rash in a dermatome","Painless genital ulcer","Cervical lymphadenopathy"]'::jsonb, 'Lobar consolidation with rusty sputum', 'Pneumococcal pneumonia typically produces lobar consolidation and cough with rusty-colored sputum, reflecting intra-alveolar exudate and hemorrhage.'),
('050722ec-5a0d-53ae-9d42-ca0f37c58af8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An elderly catheterized patient develops a urinary tract infection and later bacteremia originating from the urinary tract. Which organism is most likely?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus aureus"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is a common cause of nosocomial urinary tract infection and enterococcal bacteremia originating from the urinary or gastrointestinal tract.'),
('c470de66-e86d-5860-b7e7-09a4bc094c95'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Lancefield grouping of beta-hemolytic streptococci is based on which cell-wall antigen?', '["Group-specific C-carbohydrate polysaccharide","M protein accompanied by associated clinical symptoms","Peptidoglycan backbone mediated by specific receptor activation","Lipoteichoic acid without affecting the primary tissue pathway","Hyaluronic acid capsule leading to subsequent cellular adaptation"]'::jsonb, 'Group-specific C-carbohydrate polysaccharide', 'The Lancefield system groups beta-hemolytic streptococci by their group-specific cell-wall polysaccharide (C-carbohydrate) antigens; for example, group A is S. pyogenes.'),
('eda9f6ba-75d5-564c-91f5-9d99649f3b08'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Viridans group streptococci differ from Streptococcus pneumoniae by being which of the following?', '["Optochin-resistant and bile-insoluble","Optochin-sensitive","Bile-soluble","Catalase positive","Coagulase positive"]'::jsonb, 'Optochin-resistant and bile-insoluble', 'The viridans streptococci, unlike S. pneumoniae, are resistant to optochin and are not lysed by bile salts; both groups are alpha-hemolytic.'),
('ab8dce25-69e8-5f37-872b-06fcbf8f3960'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Necrotizing fasciitis caused by Streptococcus pyogenes is best treated initially with which regimen?', '["Penicillin plus clindamycin (with surgical debridement)","Vancomycin alone accompanied by associated clinical symptoms","Metronidazole alone mediated by specific receptor activation","Oral doxycycline alone without affecting the primary tissue pathway","Ceftriaxone plus vancomycin alone leading to subsequent cellular adaptation"]'::jsonb, 'Penicillin plus clindamycin (with surgical debridement)', 'High-dose penicillin G combined with clindamycin (which suppresses toxin production) plus early surgical debridement is the standard treatment for group A streptococcal necrotizing fasciitis.'),
('1a17209d-25f9-5c34-bf67-1fbcc6a59ee4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms tests positive with the bile-esculin test, a key step in identifying enterococci?', '["Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is bile-esculin positive, hydrolyzing esculin to esculetin in the presence of bile, the definitive laboratory step in identifying enterococci.'),
('ea953ee6-c724-5144-97d3-b3e05af5aa09'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Enterococci are characteristically distinguished from nonenterococcal group D streptococci (e.g., Streptococcus bovis) by which feature?', '["Growth in 6.5% NaCl broth","Bacitracin sensitivity","Optochin sensitivity","CAMP positivity","Bile solubility"]'::jsonb, 'Growth in 6.5% NaCl broth', 'Enterococci tolerate and grow in 6.5% NaCl broth, whereas nonenterococcal group D streptococci such as S. bovis do not; this salt tolerance is the classic distinguishing test.'),
('6e88a95a-8697-5da5-9c85-b99e1967f313'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which statement correctly describes the vanA type of vancomycin resistance among enterococci?', '["vanA is transferable and confers high-level resistance to vancomycin and teicoplanin","vanA confers resistance only to teicoplanin","Vancomycin resistance is intrinsic and nontransferable in enterococci","Enterococci are inherently vancomycin resistant at all times","VRE are susceptible to all cephalosporins"]'::jsonb, 'vanA is transferable and confers high-level resistance to vancomycin and teicoplanin', 'vanA, usually plasmid or transposon mediated and therefore transferable, replaces the peptidoglycan precursor with D-Ala-D-Lac, causing high-level resistance to both vancomycin and teicoplanin.'),
('ab934e67-2cc7-56c8-bd7b-f6b927f50798'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Post-streptococcal glomerulonephritis is characteristically caused by which of the following?', '["Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Streptococcus pyogenes', 'Post-streptococcal glomerulonephritis follows infection with nephritogenic M-protein serotypes of S. pyogenes, typically 1-3 weeks after pharyngitis or pyoderma.'),
('b47924a7-4c1e-5a07-81b9-639d52c9f571'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The slide (bound coagulase or clumping factor) test is positive for which organism?', '["Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'Bound coagulase (clumping factor) on the S. aureus surface binds fibrinogen and causes rapid clumping in the slide test, which is positive only for S. aureus.'),
('a94046ce-94fd-5c6b-8322-76921ca024e7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A farm worker develops recurrent boils and a subcutaneous abscess that yields thick pus. Which organism is the most likely cause?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Enterococcus faecalis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the classic cause of recurrent boils (furuncles) and subcutaneous abscesses in otherwise healthy individuals.'),
('d153b483-641d-5628-996f-5cb3342848df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'In the catalase test, the organism that vigorously decomposes hydrogen peroxide into water and oxygen bubbles is which of the following?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'Staphylococci including S. aureus are catalase-positive, producing gas bubbles from hydrogen peroxide; the test separates them from the catalase-negative streptococci and enterococci.'),
('bf4bb810-8982-535a-8676-4bcd46a84f52'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Staphylococcus aureus evades opsonophagocytic killing because its surface protein A binds the Fc region of immunoglobulin G. Which organism possesses this mechanism?', '["Enterococcus faecalis","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'Protein A of S. aureus non-specifically binds the Fc region of IgG, so the antibody cannot engage Fc receptors on phagocytes, impairing opsonophagocytosis.'),
('2bcf2a38-1a66-5ac7-9bf3-b0905cfb89a4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 35-year-old presents with sore throat, fever and tonsillar exudate. Which organism is the most likely cause of acute bacterial pharyngitis?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus aureus","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes (group A) is the most important bacterial cause of acute exudative pharyngitis with fever and tonsillar exudate, and can trigger rheumatic fever if untreated.'),
('0225f50e-3eec-59e9-94c0-42d647d63a6f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which combination of test results would you expect from a strain of Staphylococcus aureus?', '["Catalase positive, coagulase positive, DNase positive","Catalase negative, coagulase negative, DNase negative","Optochin sensitive, bile soluble","Bacitracin sensitive, PYR positive","Bile-esculin positive, growth in 6.5% NaCl"]'::jsonb, 'Catalase positive, coagulase positive, DNase positive', 'S. aureus is catalase positive, coagulase positive and DNase positive; the DNase test further separates it from the coagulase-negative staphylococci.'),
('867a3217-34cc-5cfb-aceb-b367686b95f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which statement about Enterococcus faecium is correct?', '["It is often resistant to ampicillin and vancomycin, complicating therapy","It is among the most antibiotic-susceptible enterococcal species accompanied by associated clinical symptoms","It is catalase positive mediated by specific receptor activation","It causes rheumatic fever without affecting the primary tissue pathway","It is bile-soluble leading to subsequent cellular adaptation"]'::jsonb, 'It is often resistant to ampicillin and vancomycin, complicating therapy', 'E. faecium is frequently ampicillin-resistant and is the species most often responsible for vancomycin-resistant enterococcal (VRE) infections, making therapy difficult.'),
('e8f469b3-7c09-53b7-b103-3d8783d27eb9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms is an intestinal commensal that may produce bacteriocins (enterocins) and cause bacteremia in biliary tract disease?', '["Staphylococcus aureus","Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is an intestinal commensal that produces bacteriocins (enterocins) and is a frequent cause of bacteremia and endocarditis in biliary and urinary tract disease.'),
('a7cf61b5-1af8-52b3-8a87-2b356a58061c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'On blood agar, Streptococcus pyogenes produces which pattern of hemolysis?', '["Beta (complete) hemolysis","Alpha (partial, green) hemolysis","Gamma (no) hemolysis","Double-zone hemolysis","Alpha-prime (wide zone) hemolysis"]'::jsonb, 'Beta (complete) hemolysis', 'S. pyogenes produces streptolysins O and S, which completely lyse red cells and give a clear zone (beta-hemolysis) around colonies on blood agar.'),
('68576236-e1ac-5e65-9b62-11b162141beb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'PCV13 is particularly indicated in infants because it prevents which common infection caused by Streptococcus pneumoniae?', '["Acute otitis media and invasive pneumococcal disease","Urinary tract infection","Honey-colored crusted impetigo","Toxic shock syndrome","Streptococcal pharyngitis"]'::jsonb, 'Acute otitis media and invasive pneumococcal disease', 'S. pneumoniae is the most common cause of acute otitis media in infants and children, and PCV13 reduces both otitis and invasive pneumococcal disease.'),
('e9f11a39-dc3e-516e-a453-9ec3a0270407'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'All of the following are TRUE of vancomycin-resistant enterococci (VRE) EXCEPT:', '["Susceptible to cephalosporins","Resistance mediated by vanA/vanB gene clusters","Bile-esculin positive and growth in 6.5% NaCl","Frequent cause of nosocomial urinary tract infection","Treatment options include linezolid or daptomycin"]'::jsonb, 'Susceptible to cephalosporins', 'Enterococci, VRE included, are intrinsically resistant to cephalosporins and are not susceptible to them; VRE treatment uses agents such as linezolid or daptomycin.'),
('3e873c84-29e0-5424-8e20-eb360c4fc753'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A neonate develops widespread superficial bullae that rupture, leaving large areas of denuded skin. Which toxin-producing organism is responsible for this scalded skin syndrome?', '["Enterococcus faecalis","Streptococcus pneumoniae","Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'S. aureus elaborates exfoliative toxin, which cleaves desmoglein-1 and produces the bullous peeling of scalded skin syndrome in neonates.'),
('3aec3a5d-adfe-5660-b340-7d1ea3853d33'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A previously healthy young adult develops rapidly progressive necrotizing pneumonia with hemoptysis and leukopenia following influenza. Which organism is implicated?', '["Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'Community-acquired MRSA producing Panton-Valentine leukocidin causes necrotizing hemorrhagic pneumonia with hemoptysis and leukopenia, typically following influenza.'),
('e88e3a71-6a84-538c-af4e-17a298ce5324'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Group A streptococcus (S. pyogenes) is identified in culture by which combination of features?', '["Beta-hemolysis, bacitracin sensitivity, PYR positive","Alpha-hemolysis, optochin sensitivity","Catalase positive, coagulase positive","Novobiocin resistance","CAMP positive and hippurate positive"]'::jsonb, 'Beta-hemolysis, bacitracin sensitivity, PYR positive', 'S. pyogenes is beta-hemolytic, sensitive to the bacitracin disk and PYR positive; group B streptococci differ by being bacitracin-resistant, CAMP and hippurate positive.'),
('e2b2bf25-350c-5a6d-9608-4fbd1537cbe8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Elevated anti-DNase B antibody titers indicate recent infection with which organism?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'DNase B is an extracellular product of S. pyogenes; anti-DNase B titers document recent group A streptococcal infection, being particularly useful after skin infection.'),
('58e0af75-3d2d-5bb1-8fcc-2739d7b66978'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The DNase (deoxyribonuclease) test is positive for which organism, and is used to separate it from the other staphylococci?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus aureus', 'S. aureus produces extracellular DNase (positive DNase test), whereas the coagulase-negative staphylococci such as S. epidermidis are DNase negative.'),
('120d8a25-e119-5e3a-b9d8-066429a1f4f8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A patient develops infective endocarditis shortly after genitourinary instrumentation. Which organism, originating from the intestinal or genitourinary tract, is most likely responsible?', '["Enterococcus faecalis","Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Enterococcus faecalis', 'Enterococci are normal flora of the gastrointestinal and genitourinary tracts; genitourinary instrumentation provides the portal of entry for E. faecalis endocarditis.'),
('9020a648-9af9-5d0b-b9c5-01d5d0f3341f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 19-year-old menstruating woman using a hyperabsorbent tampon develops shock, high fever and a diffuse erythematous rash followed by desquamation. Which organism is most likely responsible?', '["Staphylococcus aureus","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'S. aureus produces TSST-1, the superantigen that causes tampon-associated toxic shock syndrome with fever, rash, hypotension and desquamation.'),
('4bea7f6a-1bee-5be3-be0d-59c8be552dd3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Among the listed Gram-positive cocci, which one is catalase positive and also coagulase positive?', '["Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus aureus","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the only organism among the options that is both catalase positive and coagulase positive.'),
('85255726-a95e-5557-94fe-cc59b8f046cd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the described organisms grows in 6.5% NaCl broth and is PYR positive, distinguishing enterococci from the other species listed?', '["Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes"]'::jsonb, 'Enterococcus faecalis', 'Enterococci (E. faecalis) grow in 6.5% NaCl broth and are PYR positive, distinguishing them from the true streptococci.'),
('0c967efc-a97b-5336-a92c-55ad9538dbeb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The mecA gene, which encodes PBP2a, is the molecular basis of methicillin resistance in which organism?', '["Streptococcus pyogenes","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'mecA encodes the altered penicillin-binding protein PBP2a of S. aureus (MRSA), producing resistance to methicillin and all beta-lactams.'),
('c2f02cfb-3de2-5e2c-a41e-e66da7ed387a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 40-year-old presents with sore throat, fever and pharyngeal exudate. Which organism is the most likely cause?', '["Streptococcus pneumoniae","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes (group A) is the classic cause of acute exudative bacterial pharyngitis, and its treatment with penicillin prevents acute rheumatic fever.'),
('0b10210f-4125-5379-b7bc-d214634f0b12'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the leading cause of infection of cerebrospinal fluid shunts in patients with hydrocephalus?', '["Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most common cause of cerebrospinal fluid shunt infection because it colonizes the shunt tubing with biofilm.'),
('9ec86a1f-6c96-58b0-b45f-6f758b6de3d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The exfoliative toxin, which cleaves desmoglein-1 and causes superficial epidermal separation, is produced by which organism?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus aureus', 'Exfoliative toxins A and B of S. aureus are serine proteases that cleave desmoglein-1, producing bullous impetigo and scalded skin syndrome.'),
('e4be4bed-e4a3-5cf9-985f-384357047dbb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'In the Gram stain, the thick peptidoglycan layer of Gram-positive cocci such as Staphylococcus aureus does which of the following?', '["Retains the crystal violet-iodine complex during decolorization, appearing violet","Readily loses the dye during decolorization, appearing pink accompanied by associated clinical symptoms","Is dissolved by the safranin counterstain mediated by specific receptor activation","Contains endotoxin without affecting the primary tissue pathway","Gives a negative counterstain leading to subsequent cellular adaptation"]'::jsonb, 'Retains the crystal violet-iodine complex during decolorization, appearing violet', 'The thick, cross-linked peptidoglycan of Gram-positive bacteria retains the crystal violet-iodine complex that cannot be removed by alcohol decolorization, so the cells appear violet.'),
('3880ecfa-e9ca-5152-8325-94edfe0c3791'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A patient develops fever, new-onset murmur and embolic phenomena 4 months after prosthetic mitral valve replacement. Which organism is most likely cultured?', '["Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most common cause of prosthetic valve endocarditis within the first year after surgery, producing biofilm on the valve sewing ring.'),
('53cc87f1-1eab-5a81-9961-572e81f17e96'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An elderly diabetic woman presents with a tender, fluctuant skin abscess. Which organism is the most common cause?', '["Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the most common cause of suppurative skin abscesses regardless of age or diabetic status.'),
('c0e94b7f-3647-57b9-aad5-28c26ad866a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A man develops infective endocarditis two weeks after urologic instrumentation. Which organism, originating from the gastrointestinal or genitourinary tract, is the likely cause?', '["Streptococcus pyogenes","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is a normal inhabitant of the gastrointestinal and genitourinary tracts and causes infective endocarditis that frequently follows genitourinary instrumentation.'),
('70e2022c-ba6f-5ce8-931f-2e78615ccacc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The polysaccharide capsule, which resists phagocytosis, is the principal virulence factor of which organism?', '["Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pneumoniae', 'The capsular polysaccharide of S. pneumoniae is antiphagocytic and its more than 90 serotypes form the basis of the pneumococcal vaccines.'),
('e4053909-61bf-5880-a734-54be6a42c479'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following diseases is mediated by a superantigen rather than by direct tissue invasion?', '["Toxic shock syndrome","Lobar pneumonia","Impetigo","Osteomyelitis","Pyelonephritis"]'::jsonb, 'Toxic shock syndrome', 'Toxic shock syndrome results from the superantigens TSST-1 or pyrogenic exotoxins, which cause massive polyclonal T-cell activation and a cytokine storm rather than direct tissue destruction.'),
('521c2301-68ac-541e-8cf0-c2ce4814d0a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Scarlet fever is caused by a strain of Streptococcus pyogenes that produces which toxin?', '["Pyrogenic (erythrogenic) exotoxin","Exfoliative toxin","Heat-stable enterotoxin","Panton-Valentine leukocidin","Streptolysin O"]'::jsonb, 'Pyrogenic (erythrogenic) exotoxin', 'The pyrogenic (erythrogenic) exotoxin of S. pyogenes causes the erythematous rash, strawberry tongue and desquamation that define scarlet fever.'),
('e8df5f51-6d94-5fef-a43d-cacccdc8bdfe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Hydrolysis of sodium hippurate, a test used to identify group B streptococci, is positive for which organism?', '["Streptococcus agalactiae","Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Streptococcus agalactiae', 'S. agalactiae (group B) hydrolyzes hippurate to glycine and benzoic acid, a biochemical test that differentiates it from group A streptococcus.'),
('3c2696ef-8d8e-5f52-83a0-023abc356125'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 30-year-old presents with fever, productive cough and lobar consolidation. Which organism is the most likely cause of this pneumonia?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the most common cause of community-acquired pneumonia in adults, presenting with lobar consolidation.'),
('469dfb7b-0d77-5b2b-95ba-5586b7e805b8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 45-year-old develops acute bacterial meningitis with fever and nuchal rigidity. Among the Gram-positive cocci, which organism is the most important cause?', '["Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the most common cause of bacterial meningitis in adults and the most important Gram-positive cause; it requires rapid antibiotic therapy.'),
('3493728d-be95-5c23-9b14-573fa3786164'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism produces exfoliative toxins A and B that split the stratum granulosum and cause bullous exfoliation characteristic of scalded skin syndrome in infants?', '["Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'S. aureus produces exfoliative toxins A and B that cleave desmoglein-1, causing the generalized bullous exfoliation of scalded skin syndrome.'),
('d8b5dfdc-bae7-57a9-981f-5ef51e0f41a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An adult develops lobar pneumonia several days after an influenza-like illness. The sputum shows Gram-positive diplococci with a polysaccharide capsule. Which organism is it?', '["Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae causes classic lobar pneumonia, often as a superinfection after influenza, and appears as encapsulated Gram-positive diplococci in sputum.'),
('c541ef59-f4ab-568c-b501-d79d82f22bfe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which pair correctly matches a Gram-positive coccus with its characteristic toxin-mediated disease?', '["S. aureus - toxic shock syndrome","S. epidermidis - lobar pneumonia","S. pneumoniae - impetigo","S. pyogenes - urinary tract infection","Enterococcus - rheumatic fever"]'::jsonb, 'S. aureus - toxic shock syndrome', 'S. aureus produces the TSST-1 superantigen that causes toxic shock syndrome; the other pairings are incorrect (e.g., S. epidermidis does not cause lobar pneumonia).'),
('b1350d4e-0d7a-5c69-8a01-e5f62686f500'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism resists phagocytosis through its antiphagocytic polysaccharide capsule, of which more than 90 serotypes exist, forming the basis for capsular vaccines?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumoniae","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae resists phagocytosis via an antiphagocytic polysaccharide capsule with more than 90 serotypes, the basis of the PCV13 and PPSV23 vaccines.'),
('a8c6311d-14e9-5e95-8c6e-08ea295a7a9a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The diffuse erythematous rash that accompanies group A streptococcal pharyngitis (scarlet fever) is caused by which organism producing a pyrogenic erythrogenic exotoxin?', '["Staphylococcus aureus","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes produces the pyrogenic (erythrogenic) exotoxin whose rash with subsequent desquamation defines scarlet fever.'),
('2cbd6e12-b235-5909-9d23-50ed77c63f0a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Acute rheumatic fever following pharyngitis is a classic immunologic complication of infection with which organism?', '["Staphylococcus aureus","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'Rheumatic fever is an autoimmune sequelae of pharyngitis due to S. pyogenes (group A), mediated by antibodies cross-reactive with cardiac and other tissues.'),
('fe5ff966-df3e-5fcd-b302-ec61de181fc8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Toxic shock syndrome is caused by the superantigen TSST-1, a product of which organism?', '["Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus epidermidis","Staphylococcus aureus"]'::jsonb, 'Staphylococcus aureus', 'TSST-1, the toxic shock syndrome superantigen, is produced by toxigenic strains of S. aureus, classically in tampon-associated and postoperative cases.'),
('f6dfb9b2-844a-5a4a-a806-8af03bf026a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The vanB gene cluster, which mediates moderate-level vancomycin resistance (without teicoplanin resistance), is characteristic of which organism?', '["Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis","Enterococcus faecalis","Staphylococcus aureus"]'::jsonb, 'Enterococcus faecalis', 'vanB confers inducible moderate-level vancomycin resistance (teicoplanin susceptible) in enterococci (VRE), including E. faecalis and E. faecium.'),
('1564a639-c68c-5c40-814c-ca03d8ffd66e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An ICU patient on broad-spectrum vancomycin develops a vancomycin-resistant Gram-positive coccus in blood cultures. Which organism is the most likely source?', '["Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Enterococcus faecalis', 'Enterococci carrying vanA/vanB resistance genes are the classic vancomycin-resistant (VRE) isolates that emerge under broad-spectrum vancomycin pressure.'),
('87d674f1-a53d-51e1-8114-c5442f446107'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Streptococcus pyogenes (group A) is best characterized by which of the following?', '["Beta-hemolytic, bacitracin-sensitive, catalase-negative","Alpha-hemolytic, optochin-sensitive","Catalase-positive, coagulase-positive","Bile-esculin positive, PYR positive","Novobiocin-resistant"]'::jsonb, 'Beta-hemolytic, bacitracin-sensitive, catalase-negative', 'S. pyogenes is a catalase-negative, beta-hemolytic coccus sensitive to the bacitracin disk; these features identify the group A streptococcus.'),
('14c2667d-25a7-5153-a139-d72bef90e6d6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Non-bullous impetigo with honey-colored crusts is most often caused by which organisms?', '["Staphylococcus aureus and Streptococcus pyogenes","Staphylococcus epidermidis alone","Streptococcus pneumoniae alone","Enterococcus faecalis","Streptococcus agalactiae"]'::jsonb, 'Staphylococcus aureus and Streptococcus pyogenes', 'Non-bullous impetigo is caused by S. aureus and S. pyogenes, either alone or together; bullous impetigo is specifically due to exfoliative toxin-producing S. aureus.'),
('94ccde39-e788-55e4-9a35-b39aa88c3f69'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Streptococcus agalactiae (group B) is presumptively identified by which combination of test results?', '["CAMP positive, hippurate positive, bacitracin resistant","Bacitracin sensitive and PYR positive","Optochin sensitive and bile soluble","Catalase positive and coagulase positive","Novobiocin resistant"]'::jsonb, 'CAMP positive, hippurate positive, bacitracin resistant', 'S. agalactiae is CAMP positive and hippurate positive and resistant to bacitracin, whereas group A (S. pyogenes) is bacitracin sensitive and PYR positive.'),
('0d3d344c-74d7-5779-a711-672b49cf9815'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Staphylococcus bovis (gallolyticus), a nonenterococcal group D streptococcus, is associated with which clinical condition?', '["Colorectal carcinoma and infective endocarditis","Neonatal sepsis accompanied by associated clinical symptoms","Dental caries mediated by specific receptor activation","Toxic shock syndrome without affecting the primary tissue pathway","Scarlet fever leading to subsequent cellular adaptation"]'::jsonb, 'Colorectal carcinoma and infective endocarditis', 'S. bovis (S. gallolyticus) bacteremia and endocarditis are strongly associated with colorectal carcinoma, and colonoscopy is indicated in affected patients.'),
('d254d2de-1b60-56a8-b4d8-541b297d6cf2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A patient develops a painful, well-demarcated, raised erythematous lesion with a sharp border on the cheek. Which organism is the classic cause of this erysipelas?', '["Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pyogenes","Staphylococcus aureus","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'Erysipelas, a superficial infection of the skin with a sharply demarcated raised border, is the classic manifestation of S. pyogenes infection.'),
('5aebc4d0-6b8d-5b9c-a93d-5415d33fe446'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Streptococcus pyogenes is correctly matched with which of the following sequelae?', '["Acute rheumatic fever following pharyngitis","Pyelonephritis in young women","Prosthetic valve endocarditis","Catheter-related bacteremia","Scalded skin syndrome"]'::jsonb, 'Acute rheumatic fever following pharyngitis', 'Acute rheumatic fever is the classic nonsuppurative immunologic sequelae of S. pyogenes (group A) pharyngitis; the other conditions are not caused by this organism.'),
('9975e03f-d24b-52af-8f4c-425271c047a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which statement about enterococcal infections is correct?', '["Enterococci are intrinsically resistant to cephalosporins","Enterococci are highly susceptible to cephalosporins","Enterococci produce TSST-1","Enterococci are catalase positive","Enterococci are bile-soluble"]'::jsonb, 'Enterococci are intrinsically resistant to cephalosporins', 'Enterococci are intrinsically resistant to cephalosporins and have low-level penicillin resistance; reliably bactericidal therapy requires ampicillin combined with an aminoglycoside.'),
('b044d46c-1899-5c2c-baa0-d530d7072875'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'MRSA is resistant to methicillin, nafcillin and all beta-lactams because of which mechanism?', '["Production of PBP2a encoded by mecA","Production of an extended-spectrum beta-lactamase","Decreased outer-membrane permeability","Active efflux pumps","Target-site modification of ribosomes"]'::jsonb, 'Production of PBP2a encoded by mecA', 'The mecA gene encodes PBP2a, a penicillin-binding protein with low affinity for beta-lactams, which permits cell-wall synthesis despite the presence of these drugs.'),
('96222592-bce8-5ecc-8b65-a18c3067f094'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Treatment of group A streptococcal pharyngitis with penicillin primarily serves to prevent which complication?', '["Acute rheumatic fever","Post-streptococcal glomerulonephritis","Septic arthritis","Meningitis","Brain abscess"]'::jsonb, 'Acute rheumatic fever', 'Antibiotic therapy for GAS pharyngitis reliably prevents acute rheumatic fever; it does not reliably prevent post-streptococcal glomerulonephritis.'),
('c775ce75-9e16-5be1-ae2f-f8f1800b2b05'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism is the most common cause of acute bacterial endocarditis on native heart valves?', '["Streptococcus pyogenes","Staphylococcus epidermidis","Streptococcus pneumoniae","Staphylococcus aureus","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus is the most common cause of acute native-valve infective endocarditis, particularly in intravenous drug users and patients with bacteremia.'),
('ba5a8ef3-1817-5910-9b82-43e311068d24'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms hydrolyzes esculin in the presence of bile (bile-esculin positive)?', '["Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes","Streptococcus pneumoniae","Staphylococcus aureus"]'::jsonb, 'Enterococcus faecalis', 'Enterococci (E. faecalis) hydrolyze esculin in the presence of bile and therefore give a positive bile-esculin test.'),
('9d11d7b8-01c3-5bbd-81ce-46b116be9ae6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following organisms is correctly paired with the laboratory test used to identify it?', '["S. agalactiae - CAMP and hippurate positive","S. pyogenes - optochin sensitive","S. pneumoniae - bacitracin sensitive","S. aureus - bile soluble","S. epidermidis - coagulase positive"]'::jsonb, 'S. agalactiae - CAMP and hippurate positive', 'S. agalactiae (group B) is CAMP positive and hippurate positive; the other pairings are incorrect (e.g., S. pneumoniae is optochin-sensitive, not S. pyogenes).'),
('bdf174b6-9244-56d5-b339-15e54693ec87'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An alpha-hemolytic diplococcus that is bile-soluble and optochin-sensitive is identified as which organism?', '["Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus aureus"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the alpha-hemolytic diplococcus distinguished from the viridans streptococci by being bile-soluble and optochin-sensitive.'),
('7e40eb97-533a-5d78-9e52-b9ccc4c72834'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'An ICU patient with a central venous catheter develops repeated positive blood cultures. Which organism is the most likely cause of this catheter-related infection?', '["Streptococcus pyogenes","Enterococcus faecalis","Staphylococcus epidermidis","Streptococcus pneumoniae","Staphylococcus aureus"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the most common cause of catheter-related bloodstream infection, adhering to the catheter lumen by biofilm formation.'),
('09b13886-eb24-517c-8fa4-7ede1cab9a28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A child presents with acute onset of sore throat, fever, cervical lymphadenopathy and exudative pharyngitis. Which organism is the most likely cause?', '["Enterococcus faecalis","Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae"]'::jsonb, 'Streptococcus pyogenes', 'S. pyogenes is the classic cause of exudative bacterial pharyngitis with fever, cervical lymphadenopathy and tonsillar exudate in children.'),
('927a164f-52b4-507a-ab47-4fbf99f7f075'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed organisms is the enterococcal species most often responsible for urinary tract infections and infective endocarditis?', '["Staphylococcus aureus","Enterococcus faecalis","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Enterococcus faecalis', 'E. faecalis is the enterococcal species most often responsible for urinary tract infections and infective endocarditis.'),
('478b43c4-0e4e-5a9a-b387-d25a4e84122b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Enterococci such as E. faecalis typically produce which pattern of hemolysis on blood agar?', '["Alpha or gamma (non)hemolysis","Beta hemolysis","Double-zone hemolysis","CAMP-enhanced hemolysis","Optochin-sensitive hemolysis"]'::jsonb, 'Alpha or gamma (non)hemolysis', 'Enterococci are usually alpha-hemolytic or non-hemolytic (gamma) on blood agar, in contrast to the beta-hemolytic group A streptococci.'),
('faf49251-b27e-51cd-83d0-7a90c56445c5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism forms an extracellular biofilm (slime) that enables it to persist on prosthetic heart valves and intravascular catheters?', '["Streptococcus pneumoniae","Enterococcus faecalis","Streptococcus pyogenes","Staphylococcus aureus","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis produces an extracellular biofilm slime that allows it to persist on prosthetic valves, catheters and other implanted devices.'),
('ba79df9e-efc3-5022-80d3-3cd9fa72b936'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'All of the following are TRUE of Panton-Valentine leukocidin (PVL) EXCEPT:', '["It causes scalded skin syndrome","It is a pore-forming toxin that lyses neutrophils","It is associated with community-acquired MRSA skin abscesses","It is associated with necrotizing pneumonia","It is associated with furunculosis and recurrent boils"]'::jsonb, 'It causes scalded skin syndrome', 'Scalded skin syndrome is caused by the exfoliative toxin of S. aureus, not by PVL; PVL is a pore-forming leukocidin linked to necrotizing pneumonia and skin abscesses.'),
('e6b44495-dac1-5452-93b4-50f02f2dc7e8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The tube coagulase test, in which the organism causes plasma to clot, is positive for which organism?', '["Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Enterococcus faecalis","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'Free coagulase secreted by S. aureus reacts with plasma coagulase-reacting factor to convert fibrinogen to fibrin, clotting plasma in the tube test.'),
('312a2b96-190a-5d83-9660-2470781d2538'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A 3-year-old with recurrent acute otitis media develops ear pain and fever. Uncomplicated infection most commonly involves which organism?', '["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis"]'::jsonb, 'Streptococcus pneumoniae', 'S. pneumoniae is the most common bacterial cause of acute otitis media in children and may lead to mastoiditis if inadequately treated.'),
('3510aa4a-ac41-5335-b467-8ce9b2274a5f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'A woman using a hyperabsorbent tampon presents with high fever, hypotension, diffuse erythema and later desquamation of the palms. Which organism and its toxin are responsible?', '["Enterococcus faecalis","Staphylococcus epidermidis","Staphylococcus aureus","Streptococcus pneumoniae","Streptococcus pyogenes"]'::jsonb, 'Staphylococcus aureus', 'Tampon-associated toxic shock syndrome is caused by S. aureus producing TSST-1, a superantigen, followed by characteristic palmar desquamation.'),
('70f62aa0-8200-50c1-b71d-3b20d64b377d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'M protein, whose antibodies confer type-specific immunity, is the major antiphagocytic factor of which organism?', '["Staphylococcus aureus","Streptococcus pyogenes","Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus epidermidis"]'::jsonb, 'Streptococcus pyogenes', 'M protein is the fibrillar antiphagocytic surface antigen of S. pyogenes; antibodies against it confer type-specific immunity.'),
('c6d1cd86-c072-50b9-b143-c34fe721ad69'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the listed Gram-positive cocci is coagulase negative and catalase positive, and is the most frequent isolate in catheter-related bacteremia?', '["Streptococcus pneumoniae","Enterococcus faecalis","Staphylococcus aureus","Streptococcus pyogenes","Staphylococcus epidermidis"]'::jsonb, 'Staphylococcus epidermidis', 'S. epidermidis is the coagulase-negative, catalase-positive coccus most frequently isolated from catheter-related bacteremia.'),
('ee8983f8-5c0c-5088-a7a3-e13a762f4465'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which of the following best distinguishes Staphylococcus aureus from S. epidermidis?', '["Catalase production","Optochin sensitivity","Novobiocin sensitivity","Coagulase production","Bacitracin sensitivity"]'::jsonb, 'Coagulase production', 'S. aureus is coagulase-positive, whereas S. epidermidis is coagulase-negative; both are catalase positive, so catalase does not distinguish them.'),
('3bfdbb42-97f7-5f76-8e15-15c61018283c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Novobiocin is used in the laboratory to distinguish which pair of organisms?', '["S. saprophyticus (resistant) from S. epidermidis (sensitive)","S. aureus from S. epidermidis","S. pneumoniae from the viridans group","S. pyogenes from S. agalactiae","Enterococci from streptococci"]'::jsonb, 'S. saprophyticus (resistant) from S. epidermidis (sensitive)', 'S. saprophyticus is resistant to novobiocin, while S. epidermidis is sensitive; this separates the two common coagulase-negative staphylococci.'),
('59755d19-8497-5d29-9149-854a577b8d6a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which staphylococcal species is novobiocin-resistant and a common cause of urinary tract infection in young women?', '["Staphylococcus saprophyticus","Staphylococcus aureus","Staphylococcus epidermidis","Micrococcus","Staphylococcus haemolyticus"]'::jsonb, 'Staphylococcus saprophyticus', 'S. saprophyticus, a coagulase-negative staphylococcus distinguished by novobiocin resistance, causes acute urinary tract infection in young women.'),
('5b49dde0-ed5e-51ec-b980-f6feb7173493'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which organism commonly produces golden-yellow pigment, coagulase and protein A?', '["Staphylococcus aureus","Staphylococcus epidermidis","Staphylococcus saprophyticus","Streptococcus pyogenes","Enterococcus faecalis"]'::jsonb, 'Staphylococcus aureus', 'S. aureus characteristically forms golden-yellow colonies and produces coagulase and protein A, features not shared by S. epidermidis or S. saprophyticus.'),
('a775a86e-da3f-5162-a75e-81b6cf2c3cff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The two major groups into which staphylococci are divided are based on which enzyme test?', '["Coagulase (positive versus negative)","Catalase accompanied by associated clinical symptoms","Oxidase mediated by specific receptor activation","Urease without affecting the primary tissue pathway","DNase leading to subsequent cellular adaptation"]'::jsonb, 'Coagulase (positive versus negative)', 'Staphylococci are divided into S. aureus (coagulase-positive) and the coagulase-negative staphylococci (S. epidermidis, S. saprophyticus) on the basis of the coagulase test.'),
('d1505598-5601-57b4-8394-94a20fe02ba2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Staphylococcal food poisoning is an intoxication caused by which toxin?', '["Heat-stable enterotoxin","Exfoliative toxin","TSST-1","Panton-Valentine leukocidin","Alpha-hemolysin"]'::jsonb, 'Heat-stable enterotoxin', 'S. aureus produces heat-stable enterotoxins that are preformed in food and stimulate the emetic reflex, causing rapid-onset food poisoning.'),
('9e0ab9ee-5085-5358-b630-d40894aaf585'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which disease is caused by the exfoliative toxin of Staphylococcus aureus?', '["Scalded skin syndrome","Food poisoning","Toxic shock syndrome","Necrotizing pneumonia","Osteomyelitis"]'::jsonb, 'Scalded skin syndrome', 'The exfoliative toxin of S. aureus cleaves desmoglein-1 in the stratum granulosum, causing the widespread bullous desquamation of scalded skin syndrome.'),
('bca8c90a-eff0-5dbe-94fa-e7a50eebe3dc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Tampon-associated toxic shock syndrome is caused by which product of Staphylococcus aureus?', '["TSST-1 superantigen","Exfoliative toxin","Heat-stable enterotoxin","Panton-Valentine leukocidin","Coagulase"]'::jsonb, 'TSST-1 superantigen', 'Tampon-associated toxic shock syndrome is caused by the TSST-1 superantigen of S. aureus, which triggers massive T-cell activation and cytokine release.'),
('6d297afc-1322-551a-8bb9-ba23af77c304'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Which population has the highest risk of Staphylococcus aureus tricuspid valve endocarditis?', '["Intravenous drug users","Patients after dental extraction","Neonates with omphalitis","Patients with prosthetic valves","Elderly patients with enterococcal bacteremia"]'::jsonb, 'Intravenous drug users', 'Intravenous drug users have the highest risk of S. aureus endocarditis, typically affecting the tricuspid valve.'),
('f7e6460e-cc9d-5ef9-949f-29d9c5d58d8d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Community-acquired MRSA necrotizing pneumonia is associated with which toxin?', '["Panton-Valentine leukocidin","TSST-1","Exfoliative toxin","Heat-stable enterotoxin","Streptolysin O"]'::jsonb, 'Panton-Valentine leukocidin', 'PVL-producing community-acquired MRSA causes severe necrotizing (hemorrhagic) pneumonia, classically after influenza, with hemoptysis and leukopenia.'),
('ef435a4d-e339-5eeb-8196-91f3f31e849c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Panton-Valentine leukocidin (PVL) is associated with which of the following clinical syndromes?', '["Food poisoning","Scalded skin syndrome","Toxic shock syndrome","Osteomyelitis","Necrotizing pneumonia and skin abscesses"]'::jsonb, 'Necrotizing pneumonia and skin abscesses', 'PVL is a bicomponent leukocidin of community-acquired MRSA associated with severe necrotizing pneumonia and recurrent skin abscesses.'),
('26258184-dc95-5f1b-a9e6-28097a2e7dfc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'PVL-producing community-acquired Staphylococcus aureus is characteristically associated with which condition?', '["Necrotizing pneumonia","Scalded skin syndrome","Food poisoning","Toxic shock syndrome","Prosthetic valve endocarditis"]'::jsonb, 'Necrotizing pneumonia', 'PVL-positive CA-MRSA causes necrotizing hemorrhagic pneumonia, particularly in young immunocompetent patients after influenza.'),
('c579d31b-c216-5bcc-93e4-62135227ea85'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'PVL is characteristically associated with which clinical presentation?', '["Recurrent skin abscesses or furuncles and necrotizing pneumonia","Neonatal sepsis and meningitis","Subacute endocarditis after dental work","Acute glomerulonephritis","Prosthetic joint infection"]'::jsonb, 'Recurrent skin abscesses or furuncles and necrotizing pneumonia', 'PVL-producing S. aureus causes recurrent furuncles and skin abscesses as well as severe necrotizing pneumonia, the hallmark syndromes of CA-MRSA.'),
('197d83b2-2b76-5a5a-85d6-3769bf13196b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'The leukocidin that lyses neutrophils and is linked to community-acquired MRSA skin infections is which of the following?', '["Panton-Valentine leukocidin","Exfoliative toxin","TSST-1","Streptolysin O","Heat-stable enterotoxin"]'::jsonb, 'Panton-Valentine leukocidin', 'PVL is a bicomponent pore-forming toxin that destroys leukocytes (neutrophils) and is a marker of community-acquired MRSA strains causing skin abscesses.'),
('d54f9174-f243-512c-8489-bb02898c0840'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Positive - Gram Positive Cocci', 'Furuncles and recurrent skin abscesses in otherwise healthy individuals, typical of community-acquired MRSA, are associated with which toxin?', '["Panton-Valentine leukocidin","Exfoliative toxin A","TSST-1","Enterotoxin B","Hyaluronidase"]'::jsonb, 'Panton-Valentine leukocidin', 'PVL-producing community-acquired MRSA causes recurrent furunculosis and skin abscesses; exfoliative toxin A, in contrast, causes bullous impetigo and scalded skin syndrome.'),
('3ee55e19-1964-5426-b37b-e910a086655e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Enterobacteriaceae are:', '["Gram-negative rods that ferment glucose","Gram-positive cocci","Acid-fast bacilli","Gram-negative cocci","Spore-forming rods"]'::jsonb, 'Gram-negative rods that ferment glucose', 'The Enterobacteriaceae are oxidase-negative, facultatively anaerobic Gram-negative rods that ferment glucose and reduce nitrate to nitrite.'),
('7baf0169-f366-5049-8d21-ed1bce657a29'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which heat-stable component of the outer membrane of Gram-negative bacilli, released in large amounts when the bacteria lyse, produces fever, hypotension and disseminated intravascular coagulation?', '["Exotoxin","Enterotoxin","Endotoxin","Neurotoxin","Cytotoxin"]'::jsonb, 'Endotoxin', 'Endotoxin is the lipopolysaccharide of the Gram-negative outer membrane; its lipid A moiety, shed at bacterial lysis, activates TLR4 and drives pyrexia, vasodilatory shock and coagulopathy.'),
('7e59a42f-a68a-574e-8a7c-d87d574311e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Lipid A of LPS is responsible for:', '["Adhesion","Motility","Capsule formation","Endotoxic (toxic) activity","Antigenicity"]'::jsonb, 'Endotoxic (toxic) activity', 'Lipid A is the toxic component of lipopolysaccharide; when released from lysed Gram-negative bacilli it triggers endotoxic shock, fever and disseminated intravascular coagulation.'),
('2968fcd3-6f71-54a0-bf81-973eaaa482df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Escherichia coli is differentiated from other Enterobacteriaceae by:', '["Catalase production","Urease production","Lactose fermentation on MacConkey agar","Oxidase production","Coagulase production"]'::jsonb, 'Lactose fermentation on MacConkey agar', 'E. coli ferments lactose and produces pink colonies on MacConkey agar, whereas non-lactose-fermenting enterics such as Salmonella and Shigella grow as pale colonies.'),
('9d31832d-14bf-5ae9-9953-5e6c678affb8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'E. coli O157:H7 produces which toxin?', '["Exotoxin A","Hemolysin","Heat-labile enterotoxin","Shiga-like toxin (verotoxin)","Heat-stable enterotoxin"]'::jsonb, 'Shiga-like toxin (verotoxin)', 'E. coli O157:H7 elaborates Shiga-like (verocyto)toxin, an AB toxin that injures colonic and renal endothelium, causing bloody diarrhea and hemolytic-uremic syndrome.'),
('8c24bbc5-2005-5b38-9c00-7c0d8b0e74ee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Enterotoxigenic E. coli (ETEC) causes:', '["Traveler''s diarrhea","Cystitis","Hemolytic uremic syndrome","Lobar pneumonia","Bloody dysentery"]'::jsonb, 'Traveler''s diarrhea', 'ETEC colonizes the small intestine via fimbrial adhesins and secretes heat-labile (LT) and heat-stable (ST) enterotoxins that drive chloride and water secretion, producing watery traveler''s diarrhea.'),
('7885652f-9876-5df0-aee7-118cbfbcf4bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Enteropathogenic E. coli (EPEC) causes:', '["Neonatal meningitis resulting in decreased functional activity","Cystitis accompanied by associated clinical symptoms","Traveler''s diarrhea mediated by specific receptor activation","Attaching and effacing lesions of the small bowel","Bloody colitis leading to subsequent cellular adaptation"]'::jsonb, 'Attaching and effacing lesions of the small bowel', 'EPEC uses bundle-forming pili and intimin to cup enterocytes and efface brush-border microvilli, producing attaching-and-effacing lesions and watery diarrhea, chiefly in infants.'),
('bc965ab6-2fe5-503c-9daf-e1523845f51f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A child develops bloody diarrhea followed by acute renal failure, thrombocytopenia and microangiopathic hemolytic anemia after eating undercooked ground beef. Which E. coli serotype is classically responsible for this hemolytic-uremic syndrome?', '["Enterotoxigenic E. coli","Enteroinvasive E. coli","Enteropathogenic E. coli","Enterohemorrhagic E. coli O157:H7","Enteroaggregative E. coli"]'::jsonb, 'Enterohemorrhagic E. coli O157:H7', 'Enterohemorrhagic E. coli, especially O157:H7, produces Shiga-like toxin that damages intestinal and renal endothelium, causing bloody diarrhea, HUS with renal failure and thrombocytopenia after contaminated meat.'),
('74bd76e2-26ff-54fb-a9c4-68d77e790308'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Salmonella typhi causes:', '["Lobar pneumonia","Neonatal sepsis","Self-limited gastroenteritis","Typhoid fever (enteric fever)","Wound infection"]'::jsonb, 'Typhoid fever (enteric fever)', 'Salmonella typhi invades gut-associated lymphoid tissue and multiplies within macrophages, producing sustained enteric (typhoid) fever with step-ladder pyrexia, rose spots and splenomegaly.'),
('0a1536dd-d145-5cd8-9efa-c6627f9a9efa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which surface component of Salmonella typhi is a capsular polysaccharide that masks the O antigen and is targeted by serology to identify chronic carriers?', '["Somatic O antigen","Flagellar H antigen","Heat-labile enterotoxin","Vi capsular polysaccharide","Shiga toxin"]'::jsonb, 'Vi capsular polysaccharide', 'The Vi antigen is a polysaccharide capsule of S. typhi that masks surface O antigen, resists phagocytosis and complement, and is detected serologically to identify chronic gallbladder carriers.'),
('ee00e63b-fc0b-50c8-bb75-9b58a6f3e0a6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Typhoid fever is transmitted via:', '["Respiratory droplets resulting in decreased functional activity","Fecal-oral route (contaminated food and water)","Blood transfusion mediated by specific receptor activation","Sexual contact without affecting the primary tissue pathway","Arthropod vector leading to subsequent cellular adaptation"]'::jsonb, 'Fecal-oral route (contaminated food and water)', 'S. typhi is spread by ingestion of food or water contaminated with feces from an infected person or chronic carrier (fecal-oral transmission).'),
('2baf10af-bf5a-5210-97f2-4b85b2173102'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The Widal test detects antibodies against:', '["Leptospiral antigens","Meningococcal polysaccharide","Brucella antigens","Paratyphoid bacilli","Salmonella typhi O and H antigens"]'::jsonb, 'Salmonella typhi O and H antigens', 'The Widal agglutination test measures rising titers of agglutinins against the somatic O and flagellar H antigens of S. typhi, becoming positive from the second week of enteric fever.'),
('a6b47e0e-4726-54b4-95cf-a4f91dfea024'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A patient with blood-culture-proven typhoid fever requires antimicrobial therapy. Which agent is an appropriate first-line option for uncomplicated disease?', '["Erythromycin","Metronidazole","Gentamicin","Ceftriaxone","Penicillin G"]'::jsonb, 'Ceftriaxone', 'Ceftriaxone (a third-generation cephalosporin) and azithromycin are reliable first-line agents for uncomplicated typhoid fever; fluoroquinolones are used where resistance is low.'),
('9c33363e-bda2-5dd3-8879-c39fd16bbc16'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Salmonella paratyphi causes:', '["Osteomyelitis","Paratyphoid fever (milder enteric fever)","Vascular graft infection","Gastroenteritis","Neonatal sepsis"]'::jsonb, 'Paratyphoid fever (milder enteric fever)', 'S. paratyphi A, B and C cause paratyphoid fever, an enteric fever clinically similar to typhoid but with a shorter incubation period and generally milder course.'),
('4677c614-6ee1-5d63-a01d-780a79115004'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'In an immunocompetent adult, non-typhoidal Salmonella species typically cause which self-limited syndrome that usually resolves without antimicrobial therapy?', '["Gastroenteritis (self-limited)","Typhoid fever","Paratyphoid fever","Pseudomembranous colitis","Hemolytic-uremic syndrome"]'::jsonb, 'Gastroenteritis (self-limited)', 'Non-typhoidal salmonellae cause acute gastroenteritis with fever, abdominal cramps and watery diarrhea that resolves on its own in healthy hosts; antibiotics are reserved for infants, the elderly and the immunocompromised.'),
('af860d93-f694-511b-b4fa-c3ee7fc51e04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'On MacConkey agar, which colony characteristic distinguishes Salmonella, Shigella and Vibrio from lactose-fermenting E. coli and Klebsiella?', '["Swarming colonial growth","Non-lactose fermenting (pale) colonies","Oxidase positivity","Pink lactose-fermenting colonies","Urease positivity"]'::jsonb, 'Non-lactose fermenting (pale) colonies', 'Salmonella, Shigella and Vibrio do not ferment lactose and produce pale, colorless colonies on MacConkey agar, whereas E. coli and Klebsiella produce pink colonies.'),
('714c62a5-5dd3-50c1-aab4-76b9b7f63f3f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Shigella dysenteriae produces:', '["Cholera toxin resulting in decreased functional activity","Shiga toxin (enterotoxic and neurotoxic)","Exotoxin A mediated by specific receptor activation","Heat-stable ST toxin without affecting the primary tissue pathway","Heat-labile LT toxin leading to subsequent cellular adaptation"]'::jsonb, 'Shiga toxin (enterotoxic and neurotoxic)', 'S. dysenteriae type 1 produces Shiga toxin, an AB exotoxin whose A subunit cleaves adenine from 28S rRNA of the 60S ribosomal subunit; it has enterotoxic, cytotoxic and neurotoxic activity.'),
('faaae4f1-9321-5569-a16d-67ede7e17a9a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Bacillary dysentery (shigellosis) is characterized by:', '["Constipation","Profuse watery diarrhea","Steatorrhea","Blood and mucus in stool with tenesmus","Rice-water stools"]'::jsonb, 'Blood and mucus in stool with tenesmus', 'Shigella invades the colonic mucosa, causing bloody, mucoid stools with cramping and tenesmus, the hallmark of bacillary dysentery.'),
('b1ef5c3b-101e-5cc6-8000-394782951ac4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'After recovery from acute typhoid fever, a patient continues to shed Salmonella typhi in stool for many months. Which condition classically underlies this chronic carrier state?', '["Cholelithiasis (gallstones)","Nephrolithiasis","Meckel diverticulum","Appendiceal fibrosis","Hepatic cirrhosis"]'::jsonb, 'Cholelithiasis (gallstones)', 'S. typhi persists in the gallbladder, usually associated with gallstones, so chronic carriers harbor and excrete the organism in stool; Vi serology helps identify them.'),
('f336c8f8-f645-55e3-ac21-33541eaa4121'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Klebsiella pneumoniae is a common cause of:', '["Gastroenteritis resulting in decreased functional activity","Wound sepsis in burns accompanied by associated clinical symptoms","Community-acquired lobar pneumonia in alcoholics","Neonatal meningitis without affecting the primary tissue pathway","Scarlet fever leading to subsequent cellular adaptation"]'::jsonb, 'Community-acquired lobar pneumonia in alcoholics', 'Klebsiella pneumoniae, an encapsulated, lactose-fermenting bacillus, classically causes destructive lobar pneumonia in alcoholics and diabetics, with ''currant-jelly'' sputum.'),
('a24e115b-1782-55bb-b05f-393bbf0de2e0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Irregular concentric waves of growth spreading across the entire surface of blood agar are characteristic of which genus?', '["Spore formation","Green pigment production","Oxidase production","Capsule formation","Proteus"]'::jsonb, 'Proteus', 'Proteus species are peritrichously flagellated and swarm in wavelike sheets over moist agar; this swarming motility is used to identify the genus.'),
('958933d4-3621-5c70-8a85-0128fdbaa5c0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enzyme produced by Proteus mirabilis splits urea into ammonia, alkalinizes urine and predisposes to struvite kidney stones?', '["Urease","DNase","Coagulase","Hemolysin","Beta-lactamase"]'::jsonb, 'Urease', 'Urease hydrolyzes urea to ammonia, raising urinary pH; the alkalinity favors precipitation of magnesium-ammonium-phosphate (struvite, triple-phosphate) stones.'),
('3abb4445-8b27-582d-8dd8-71a64c86466c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A 70-year-old woman intubated for 5 days develops new fever and infiltrates; the tracheal aspirate Gram stain shows Gram-negative bacilli. Which pathogen is among the most common causes of late-onset ventilator-associated pneumonia?', '["Pseudomonas aeruginosa","Streptococcus pneumoniae","Haemophilus influenzae","Chlamydia pneumoniae","Mycoplasma pneumoniae"]'::jsonb, 'Pseudomonas aeruginosa', 'Late-onset ventilator-associated pneumonia is frequently caused by multidrug-resistant Gram-negative rods, above all Pseudomonas aeruginosa.'),
('3c40de4f-8f2b-571e-81cf-8ee38a81fb3d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Pseudomonas aeruginosa produces:', '["Teichoic acid resulting in decreased functional activity","Pyocyanin (blue-green pigment)","Protein A mediated by specific receptor activation","Coagulase without affecting the primary tissue pathway","M protein leading to subsequent cellular adaptation"]'::jsonb, 'Pyocyanin (blue-green pigment)', 'P. aeruginosa produces pyocyanin, the blue-green phenazine pigment that imparts the characteristic color and grape-like odor to infected wounds, sputum and cultures.'),
('bb9ad3fe-d88e-5b6c-bc59-ac5cb994992e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Pseudomonas aeruginosa chronically colonizes the airways and causes recurrent, ultimately fatal pulmonary infections in which patient group?', '["Pregnant women","Healthy young adults","Neonates","Cystic fibrosis patients","Long-distance swimmers"]'::jsonb, 'Cystic fibrosis patients', 'P. aeruginosa colonizes cystic fibrosis airways, forming mucoid alginate biofilms, and is the leading cause of chronic lung infection and death in these patients.'),
('7ab32ec7-fe6f-5fe8-a7cf-97affdfd9f21'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Pseudomonas aeruginosa exotoxin A damages host cells by which mechanism?', '["Blocking acetylcholine release","Blocking GABA receptors","ADP-ribosylating elongation factor EF-2","Cleaving SNARE proteins","Activating adenylate cyclase"]'::jsonb, 'ADP-ribosylating elongation factor EF-2', 'Exotoxin A ADP-ribosylates elongation factor-2, halting host-cell protein synthesis, precisely the mechanism used by diphtheria toxin.'),
('7a1e6cee-1a24-5f1c-8883-1454b239a3be'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A patient develops a painful, swollen inguinal lymph node (bubo) with high fever after exposure to infected fleas and rodents. The flea-borne zoonosis is:', '["Bacillary dysentery","Brucellosis","Cholera","Typhoid fever","Plague"]'::jsonb, 'Plague', 'Yersinia pestis, transmitted by the rat flea Xenopsylla cheopis, causes bubonic plague; the painful bubo is the hallmark and may progress to septicemic or pneumonic plague.'),
('56ecbfda-a187-5301-bfe8-24380d7cf05d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A child has fever, abdominal pain and right-lower-quadrant tenderness mimicking appendicitis after eating undercooked pork; a Gram-negative bacillus grows from the mesenteric node. The clinical disorder is:', '["Lobar pneumonia","Burns wound infection","Urinary tract infection","Bacterial meningitis","Enterocolitis with mesenteric lymphadenitis"]'::jsonb, 'Enterocolitis with mesenteric lymphadenitis', 'Yersinia enterocolitica causes enterocolitis with mesenteric lymphadenitis that mimics appendicitis (''pseudoappendicitis''); transmission follows contaminated pork or milk.'),
('bc5d9773-1213-58d8-a154-c319e2a80659'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-stain morphology best characterizes Vibrio cholerae and Campylobacter jejuni?', '["Acid-fast bacillus","Spiral bacterium","Gram-negative curved (comma-shaped) rod","Gram-positive coccus","Gram-negative coccus"]'::jsonb, 'Gram-negative curved (comma-shaped) rod', 'Vibrio and Campylobacter are slender, curved ''comma-shaped'' Gram-negative rods with a single sheathed polar flagellum; this curved morphology is characteristic.'),
('fba37ccd-421b-514b-8d7d-14ba80e40c38'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Cholera toxin (CT) acts by:', '["Blocking acetylcholine release resulting in decreased functional activity","Blocking protein synthesis accompanied by associated clinical symptoms","Activating phospholipase C mediated by specific receptor activation","Activating guanylate cyclase without affecting the primary tissue pathway","ADP-ribosylating the Gs protein to activate adenylate cyclase"]'::jsonb, 'ADP-ribosylating the Gs protein to activate adenylate cyclase', 'The A1 subunit of cholera toxin ADP-ribosylates the alpha subunit of Gs, locking adenylate cyclase ''on'', so cAMP rises and massive chloride and water secretion follows.'),
('aa66d04e-7e06-5316-a35c-17502cfcbd57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A patient develops profuse watery ''rice-water'' stools with severe isotonic dehydration hours after drinking contaminated water during an outbreak. The clinical syndrome is:', '["Cholera","Typhoid fever","E. coli O157:H7 colitis","Shigellosis","Campylobacter enteritis"]'::jsonb, 'Cholera', 'Vibrio cholerae O1 or O139 produces cholera toxin, which drives massive chloride and water secretion, producing the ''rice-water'' diarrhea of cholera.'),
('4cef7f14-5049-58cf-8a32-1dd5a6c96984'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A Gram-stained smear shows slender, deeply curved rods with polar flagella. This morphology is typical of which enteric group?', '["Gram-positive coccus","Gram-negative coccus","Spore-forming rod","Gram-negative curved rod","Acid-fast bacillus"]'::jsonb, 'Gram-negative curved rod', 'Curved, comma-shaped Gram-negative rods with polar flagella are characteristic of Vibrio and Campylobacter among the enteric bacteria.'),
('493aebea-7990-55c3-9f4c-4a92c3bbdf81'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Campylobacter jejuni is a common cause of:', '["Typhoid fever","Urinary tract infection","Lobar pneumonia","Acute gastroenteritis","Bacterial meningitis"]'::jsonb, 'Acute gastroenteritis', 'C. jejuni is among the most common bacterial causes of acute gastroenteritis worldwide, typically from undercooked poultry.'),
('eab6b1c5-76e0-5e39-8b89-2e5ad0f961f8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Campylobacter jejuni enteritis is a recognized antecedent of which post-infectious neurologic syndrome?', '["Hemolytic-uremic syndrome","Guillain-Barre syndrome","Rheumatic fever","Hashimoto thyroiditis","Reactive arthritis of the knee"]'::jsonb, 'Guillain-Barre syndrome', 'Molecular mimicry between C. jejuni lipooligosaccharide and peripheral nerve gangliosides underlies post-Campylobacter Guillain-Barre syndrome.'),
('61e42410-5f75-5963-a8b4-3baf62e4598f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which combination of Gram-stain morphology and biochemical activity best characterizes Helicobacter pylori?', '["Budding yeast cell","Gram-positive coccus","Gram-positive rod","Gram-negative coccus","Gram-negative curved rod producing urease"]'::jsonb, 'Gram-negative curved rod producing urease', 'H. pylori is a spiral or curved Gram-negative rod that is strongly urease-positive, the property exploited by the CLO biopsy test and urea breath test.'),
('902497c4-6fd4-5df3-aaec-11f5bec8f12c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'H. pylori is associated with all EXCEPT:', '["Chronic gastritis","Gastric adenocarcinoma","Esophageal varices","Gastric MALT lymphoma","Duodenal ulcer"]'::jsonb, 'Esophageal varices', 'H. pylori causes chronic gastritis, peptic ulcer, gastric adenocarcinoma and MALT lymphoma; esophageal varices reflect portal hypertension, not H. pylori.'),
('5e1d3f8e-407e-5236-98a5-b7a0dc9f994b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A patient with epigastric pain has a duodenal ulcer and a positive rapid urease (CLO) test on antral biopsy. The relevant chronic infection is:', '["Typhoid fever","Tuberculosis","Brucellosis","Cholera","Helicobacter pylori"]'::jsonb, 'Helicobacter pylori', 'H. pylori colonizes the gastric antrum, produces urease, catalase, oxidase and the vacuolating cytotoxin VacA, and is the principal cause of duodenal ulcer disease.'),
('06c29ca9-0705-5a94-9fd2-055a56048d08'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which biochemical property of Klebsiella, Proteus and Providencia separates them from E. coli and Salmonella within the Enterobacteriaceae?', '["Lactose fermentation","Urease positivity","Coagulase production","Oxidase positivity","Motility"]'::jsonb, 'Urease positivity', 'Klebsiella (often) and Proteus (strongly) split urea to ammonia and are urease-positive, whereas E. coli and Salmonella are urease-negative.'),
('4dc225b9-31a5-5a33-8b57-bbbc6ad3afb5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A heavily encapsulated, lactose-fermenting Gram-negative bacillus is a leading cause of hospital-acquired urinary infection, wound sepsis and pneumonia. With which group of infections is it most associated?', '["UTIs and nosocomial infections","Gastroenteritis","Typhoid fever","Cholera","Bacillary dysentery"]'::jsonb, 'UTIs and nosocomial infections', 'Klebsiella pneumoniae is a classic nosocomial pathogen whose large polysaccharide capsule resists phagocytosis; it causes hospital-acquired UTI, pneumonia and wound sepsis, often multidrug-resistant.'),
('1dd8a4b0-b3ad-523f-8d5c-9b10afb619ce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'An organism that alkalinizes urine and predisposes to struvite renal calculi is identified in the laboratory by which biochemical reaction?', '["Urease positivity","Oxidase positivity","Coagulase positivity","DNase positivity","H2S negativity"]'::jsonb, 'Urease positivity', 'Proteus mirabilis is intensely urease-positive; the urease reaction hydrolyzes urea to ammonia, alkalinizing urine and precipitating struvite stones.'),
('4af68b53-43c0-573c-83eb-b5a04111a7c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A Gram-negative enteric bacillus is repeatedly isolated from the urine of a patient with a long-term indwelling urinary catheter. With which clinical syndrome is this infection most associated?', '["Catheter-associated UTI","Bacterial meningitis","Community-acquired pneumonia","Infective endocarditis","Septic arthritis"]'::jsonb, 'Catheter-associated UTI', 'Enterobacter and Klebsiella colonize and form biofilms on indwelling urinary catheters, making catheter-associated UTI the signature clinical syndrome.'),
('a27dad71-f85c-59c3-88c0-1bd26fb478d3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Facultatively intracellular enteric pathogens such as Salmonella are controlled principally by which pattern of the host cellular immune response?', '["Neutrophil response alone","Th2 response only","Humoral immunity only","Th1 and Th17 responses","NK cell response only"]'::jsonb, 'Th1 and Th17 responses', 'Control of intracellular enteric pathogens depends on CD4 Th1 (macrophage-activating IFN-gamma) and Th17 (neutrophil-recruiting IL-17) responses; impaired cell-mediated immunity predisposes to invasive disease.'),
('34db9a93-66b6-5e7a-9c5f-25c72a049399'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which two Vibrio cholerae serogroups cause epidemic and pandemic cholera?', '["O1 and O139","O2 and O3","O8 and O9","O6 and O7","O4 and O5"]'::jsonb, 'O1 and O139', 'Epidemic and pandemic cholera is caused by V. cholerae serogroups O1 (classic and El Tor) and O139; other serogroups rarely cause epidemic disease.'),
('00fd53c4-6a28-564e-8d7d-329c5371af20'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Yersinia pestis is transmitted by:', '["Flea bite (Xenopsylla cheopis)","Sandfly bite accompanied by associated clinical symptoms","Mosquito bite mediated by specific receptor activation","Louse bite without affecting the primary tissue pathway","Tick bite leading to subsequent cellular adaptation"]'::jsonb, 'Flea bite (Xenopsylla cheopis)', 'Y. pestis is transmitted between rodents and to humans by the rat flea Xenopsylla cheopis, causing bubonic plague.'),
('b37577ae-28ae-5486-a3e5-de52ef2ecf69'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative organism is the most common cause of neonatal meningitis?', '["E. coli (K1 capsular type)","Listeria monocytogenes","Group B Streptococcus","Haemophilus influenzae type b","Neisseria meningitidis"]'::jsonb, 'E. coli (K1 capsular type)', 'Among Gram-negative bacteria, E. coli bearing the K1 capsular polysaccharide is the leading cause of neonatal meningitis (overall, Group B Streptococcus remains the single most common agent).'),
('1cf03f10-7bc6-565f-99a0-44f60a827243'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which pair of enteric Gram-negative bacilli is the most common source of extended-spectrum beta-lactamase (ESBL)-producing nosocomial infections, particularly urinary infections?', '["Clostridium difficile","Staphylococcus aureus","Pseudomonas aeruginosa","Streptococcus pneumoniae","E. coli and Klebsiella pneumoniae"]'::jsonb, 'E. coli and Klebsiella pneumoniae', 'ESBLs (chiefly CTX-M, TEM and SHV types) are carried by E. coli and K. pneumoniae, making them the leading sources of resistant hospital-acquired urinary infections.'),
('0801556a-47fc-59be-be11-d52e40efda0a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'NDM-1 (New Delhi metallo-beta-lactamase) confers resistance to:', '["Aminoglycosides","Tetracyclines","Vancomycin","Carbapenems","Macrolides"]'::jsonb, 'Carbapenems', 'NDM-1 inactivates virtually all beta-lactams, including carbapenems (imipenem, meropenem, ertapenem), leaving very limited therapeutic options.'),
('7e25f566-57a0-5698-9f37-37e04b6ef315'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Salmonella typhi is cultured on:', '["Lowenstein-Jensen medium","Thayer-Martin agar","MacConkey agar and blood culture","Sabouraud dextrose agar","Cetrimide agar"]'::jsonb, 'MacConkey agar and blood culture', 'Acute typhoid fever is best confirmed by blood culture in the first week; MacConkey agar isolates the non-lactose-fermenting bacillus from blood and stool later.'),
('60a52eac-ea35-50f1-adcd-4314882c9a3c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Shigella species are distinguished from Salmonella by being:', '["Urease producers resulting in decreased functional activity","Motile accompanied by associated clinical symptoms","Oxidase positive mediated by specific receptor activation","H2S producers without affecting the primary tissue pathway","Lactose non-fermenters that are non-motile"]'::jsonb, 'Lactose non-fermenters that are non-motile', 'Shigella is non-motile and produces no H2S, unlike the motile, H2S-positive salmonellae, though both are non-lactose-fermenting.'),
('e58f0969-db78-5a57-a91b-585de0aff448'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The most common infectious antecedent of Guillain-Barre syndrome is which enteric pathogen?', '["Salmonella typhi","Klebsiella pneumoniae","Pseudomonas aeruginosa","Shigella dysenteriae","Campylobacter jejuni"]'::jsonb, 'Campylobacter jejuni', 'C. jejuni is the most frequently identified infectious trigger of Guillain-Barre syndrome through molecular mimicry with nerve gangliosides.'),
('6fd5f6e1-6b8f-515b-94e3-de08220df7b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which laboratory finding best detects an extended-spectrum beta-lactamase (ESBL) in an enteric Gram-negative rod?', '["Resistance to ceftazidime reversed by clavulanic acid (double-disc synergy)","Lactose fermentation on MacConkey agar accompanied by associated clinical symptoms","Positive oxidase reaction mediated by specific receptor activation","Swarming motility on blood agar without affecting the primary tissue pathway","Pyocyanin production leading to subsequent cellular adaptation"]'::jsonb, 'Resistance to ceftazidime reversed by clavulanic acid (double-disc synergy)', 'ESBLs hydrolyze oxyimino-cephalosporins such as ceftazidime; restored susceptibility when clavulanic acid is added is the double-disc synergy test for ESBL.'),
('d77af142-8bca-58aa-8094-2c7378df069c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enteric bacillus characteristically forms large mucoid, string-test-positive colonies on MacConkey agar?', '["Shigella dysenteriae","Salmonella typhi","Pseudomonas aeruginosa","Escherichia coli","Klebsiella pneumoniae"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella''s thick capsular polysaccharide yields glistening mucoid colonies; a mucus strand can be lifted with a loop, the positive string test.'),
('7212ca8a-c75e-5656-b284-eed888a36806'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which non-motile, non-lactose-fermenting bacillus invades the colonic mucosa and causes bacillary dysentery with blood and mucus in the stools?', '["Shigella dysenteriae","Escherichia coli","Pseudomonas aeruginosa","Salmonella typhi","Klebsiella pneumoniae"]'::jsonb, 'Shigella dysenteriae', 'S. dysenteriae is a non-motile, non-lactose-fermenting, oxidase-negative bacillus that invades colonic epithelium; its Shiga toxin produces bloody mucoid dysentery with a very low infectious dose.'),
('4c620a57-c590-5f85-9801-e7adea15e8f8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Providencia stuartii, a urease-positive, indole-positive member of the Enterobacteriaceae, most characteristically causes:', '["Catheter-associated urinary tract infection","Typhoid fever accompanied by associated clinical symptoms","Bacillary dysentery mediated by specific receptor activation","Cholera without affecting the primary tissue pathway","Peptic ulcer disease leading to subsequent cellular adaptation"]'::jsonb, 'Catheter-associated urinary tract infection', 'P. stuartii is a multiply resistant opportunist of long-term catheterized patients and is a frequent cause of nosocomial UTI.'),
('d966697b-3ccb-5335-afb8-d33c198d1606'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative rod is the most common cause of community-acquired urinary tract infection?', '["Klebsiella pneumoniae","Pseudomonas aeruginosa","Escherichia coli","Salmonella typhi","Shigella dysenteriae"]'::jsonb, 'Escherichia coli', 'E. coli accounts for about 80% of community-acquired urinary tract infections, facilitated by P and type-1 fimbriae.'),
('0595165b-cf57-5985-b845-a669887a57f1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative bacillus produces Shiga toxin, an exotoxin with enterotoxic and neurotoxic activity, and is the classic agent of bacillary (bloody) dysentery?', '["Salmonella typhi","Escherichia coli","Klebsiella pneumoniae","Pseudomonas aeruginosa","Shigella dysenteriae"]'::jsonb, 'Shigella dysenteriae', 'S. dysenteriae invades colonic mucosa and produces Shiga toxin (enterotoxic and neurotoxic), giving the crampy bloody diarrhea of bacillary dysentery.'),
('0c4749b9-dff4-561d-89c2-7b8c84d37e10'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism produces cholera toxin and carries the O1 serogroup that causes epidemic cholera?', '["Escherichia coli","Klebsiella pneumoniae","Salmonella typhi","Shigella dysenteriae","Vibrio cholerae"]'::jsonb, 'Vibrio cholerae', 'V. cholerae O1 (and O139) elaborates cholera toxin, an AB toxin that ADP-ribosylates Gs and drives massive secretory diarrhea.'),
('15efd417-d3d2-5d4b-bd97-9aa32303443b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Lipid A, the hydrophobic anchor of lipopolysaccharide, is responsible for which property?', '["Adhesion to enterocytes","Motility","Capsule formation","Endotoxic activity causing fever and shock","Antigenic specificity of O chains"]'::jsonb, 'Endotoxic activity causing fever and shock', 'Lipid A triggers TLR4-driven cytokine release and produces the endotoxic fever, hypotension and coagulopathy of Gram-negative sepsis.'),
('405ee03c-f9cf-5fc2-97f3-866c3bda55d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Exotoxin A, which ADP-ribosylates elongation factor-2 and blocks protein synthesis, is produced by which organism?', '["Klebsiella pneumoniae","Shigella dysenteriae","Salmonella typhi","Pseudomonas aeruginosa","Escherichia coli"]'::jsonb, 'Pseudomonas aeruginosa', 'Exotoxin A is a major virulence protein of P. aeruginosa; it ADP-ribosylates EF-2, inhibiting host-cell protein synthesis and promoting tissue invasion.'),
('19f0a9ed-1b48-5a62-a85a-33ecf532086a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism causes paratyphoid fever, an enteric fever clinically similar to but usually milder than typhoid?', '["Salmonella paratyphi A, B and C","Vibrio cholerae","Shigella dysenteriae","Escherichia coli O157:H7","Campylobacter jejuni"]'::jsonb, 'Salmonella paratyphi A, B and C', 'S. paratyphi serotypes A, B and C cause paratyphoid fever, an enteric fever resembling typhoid but with a shorter incubation period and milder course.'),
('092f9e80-c26d-5c70-b408-990a3a4832c1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Edwardsiella tarda, a H2S-producing member of the Enterobacteriaceae linked to freshwater fish and reptiles, most commonly causes:', '["Gastroenteritis after freshwater or animal contact","Typhoid fever accompanied by associated clinical symptoms","Bacillary dysentery mediated by specific receptor activation","Cholera without affecting the primary tissue pathway","Peptic ulcer leading to subsequent cellular adaptation"]'::jsonb, 'Gastroenteritis after freshwater or animal contact', 'E. tarda inhabits aquatic animals and causes gastroenteritis and wound infections in people exposed to contaminated fish, snakes or water.'),
('d9c4867b-30ed-52b3-af6d-94277027a0c5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enteric pathogen causes typhoid (enteric) fever manifested by step-ladder pyrexia, relative bradycardia, rose spots on the trunk and splenomegaly?', '["Escherichia coli","Pseudomonas aeruginosa","Salmonella typhi","Shigella dysenteriae","Klebsiella pneumoniae"]'::jsonb, 'Salmonella typhi', 'S. typhi is a motile, H2S-producing, non-lactose-fermenting bacillus causing enteric fever; the Widal test detects agglutinins against its O and H antigens.'),
('9131af8e-edef-56d0-9d59-9685c9b0f936'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which heavily encapsulated, lactose-fermenting, urease-positive bacillus is classically associated with ''currant-jelly'' sputum lobar pneumonia in alcoholics, and with UTIs and nosocomial sepsis?', '["Pseudomonas aeruginosa","Shigella dysenteriae","Salmonella typhi","Escherichia coli","Klebsiella pneumoniae"]'::jsonb, 'Klebsiella pneumoniae', 'K. pneumoniae is encapsulated, lactose-fermenting, urease-positive and non-motile; its capsule produces mucoid colonies and predisposes to destructive lobar pneumonia in alcoholics and diabetics.'),
('af8b2d5c-5ec4-5ada-b83b-4f25870b82d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism needs an extremely low infectious dose, does not ferment lactose, produces no H2S and is non-motile, features that distinguish it from Salmonella and Proteus?', '["Escherichia coli","Salmonella typhi","Pseudomonas aeruginosa","Shigella dysenteriae","Klebsiella pneumoniae"]'::jsonb, 'Shigella dysenteriae', 'Shigella is non-motile, H2S-negative and non-lactose-fermenting, and as few as 10-100 organisms cause disease, much lower than the inoculum needed by Salmonella.'),
('291426db-93f3-5ce0-a3a8-3df36fe1483e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Pale, colorless colonies on MacConkey agar are characteristic of which pathogen?', '["Pseudomonas aeruginosa","Shigella dysenteriae","Escherichia coli","Klebsiella pneumoniae","Enterobacter cloacae"]'::jsonb, 'Shigella dysenteriae', 'As a non-lactose fermenter, Shigella fails to acidify MacConkey agar and forms pale colonies, whereas E. coli and Klebsiella appear pink.'),
('20860952-827b-5b7f-a9cc-bb3c49ffecac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Proteus mirabilis is identified in the laboratory by which combination of features?', '["Swarming motility with strong urease and H2S production","Oxidase positivity and pyocyanin pigment","Lactose fermentation and mucoid colonies","Non-motility and absent urease","Catalase negativity"]'::jsonb, 'Swarming motility with strong urease and H2S production', 'Proteus swarms in concentric waves on agar and is classically strongly urease-positive and H2S-positive.'),
('1e09a92d-61c2-5189-a8d4-890595f1cdce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which non-motile enteric pathogen invades only the colonic mucosa and produces a bloody diarrheal illness that antimotility drugs may aggravate?', '["Pseudomonas aeruginosa","Klebsiella pneumoniae","Shigella dysenteriae","Escherichia coli","Salmonella typhi"]'::jsonb, 'Shigella dysenteriae', 'Shigella invades colonic epithelium; antimotility agents prolong and aggravate the bloody dysentery, so they are contraindicated.'),
('d63c9027-c945-52e2-9d83-c1c7983af59f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Vibrio vulnificus, a halophilic marine vibrio, classically causes which clinical syndrome?', '["Necrotizing wound infection and primary septicemia","Typhoid fever accompanied by associated clinical symptoms","Bacillary dysentery mediated by specific receptor activation","Rice-water diarrhea without affecting the primary tissue pathway","Peptic ulcer leading to subsequent cellular adaptation"]'::jsonb, 'Necrotizing wound infection and primary septicemia', 'V. vulnificus enters through wounds exposed to seawater or via raw oysters, causing rapid necrotizing fasciitis and primary septicemia, especially in liver disease and iron overload.'),
('2bd6490f-0cc0-56a8-923f-0444a0ab09d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A Gram-negative rod produces pink, lactose-fermenting colonies on MacConkey agar and is the most common cause of community-acquired UTI. Which organism is it?', '["E. coli","Klebsiella pneumoniae","Salmonella typhi","Pseudomonas aeruginosa","Shigella dysenteriae"]'::jsonb, 'E. coli', 'The lactose-fermenting, oxidase-negative E. coli is the prototype Enterobacteriaceae and the leading cause of community-acquired UTI and Gram-negative sepsis.'),
('8f517afe-275e-54d9-a9de-6e10222c178d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Citrobacter koseri is a notorious cause of which neonatal infection?', '["Meningitis complicated by brain abscess","Typhoid fever accompanied by associated clinical symptoms","Cholera mediated by specific receptor activation","Gastritis without affecting the primary tissue pathway","Shigellosis leading to subsequent cellular adaptation"]'::jsonb, 'Meningitis complicated by brain abscess', 'C. koseri causes neonatal meningitis with a high incidence of cerebral abscess, a rare but devastating infection of the newborn.'),
('2589fce2-bd37-5bb0-a47a-0a2ec5dc68ac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Chronic gastritis, duodenal ulcers, gastric adenocarcinoma and gastric MALT lymphoma are associated with which organism?', '["Helicobacter pylori","Salmonella typhi","Escherichia coli","Klebsiella pneumoniae","Pseudomonas aeruginosa"]'::jsonb, 'Helicobacter pylori', 'H. pylori is the principal cause of chronic gastritis and peptic ulcer and is a class I gastric carcinogen causing adenocarcinoma and MALT lymphoma.'),
('4fccd365-7c85-5e3d-b272-3b4707645e68'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Stool culture yields pale, non-lactose-fermenting, non-motile colonies on XLD or SS agar. Which pathogen is most likely?', '["Shigella dysenteriae","Escherichia coli","Klebsiella pneumoniae","Salmonella typhi","Pseudomonas aeruginosa"]'::jsonb, 'Shigella dysenteriae', 'Shigella forms pale non-lactose-fermenting colonies, is non-motile and H2S-negative, distinguishing it from salmonellae.'),
('402d34a7-8da1-5450-8ec2-2e83082e195a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enteric pathogen is a non-motile, non-lactose-fermenting bacillus that invades the colonic mucosa and causes bacillary dysentery with blood and mucus in the stools?', '["Pseudomonas aeruginosa","Shigella dysenteriae","Salmonella typhi","Klebsiella pneumoniae","Escherichia coli"]'::jsonb, 'Shigella dysenteriae', 'Mucosal invasion plus Shiga toxin underlies the crampy, bloody mucoid diarrhea; unlike Salmonella, Shigella usually does not invade beyond the gut mucosa.'),
('7393e960-9355-51ac-9c3a-e6badd551674'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism causes typhoid fever?', '["Salmonella typhi","Klebsiella pneumoniae","Escherichia coli","Pseudomonas aeruginosa","Shigella dysenteriae"]'::jsonb, 'Salmonella typhi', 'Typhoid (enteric) fever is caused by S. typhi, a motile, H2S-producing bacillus that multiplies within macrophages and spreads systemically from Peyer patches.'),
('82799cd0-eae3-503a-9726-4f35e567f105'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative rod is oxidase-positive, non-lactose-fermenting, produces blue-green pyocyanin, and characteristically infects burn wounds and cystic fibrosis airways?', '["Shigella dysenteriae","Salmonella typhi","Escherichia coli","Pseudomonas aeruginosa","Klebsiella pneumoniae"]'::jsonb, 'Pseudomonas aeruginosa', 'P. aeruginosa is oxidase-positive and non-lactose-fermenting; its pyocyanin, fruity odor and intrinsic multi-resistance identify it as the classic opportunist of burns and cystic fibrosis.'),
('eb826c94-96fa-5607-bcbd-acba135bd8a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Vibrio cholerae O139 is an established cause of which disease?', '["Cholera","Typhoid fever","Bacillary dysentery","Plague","Peptic ulcer"]'::jsonb, 'Cholera', 'O139 is aV. cholerae serogroup distinct from O1 that also produces cholera toxin and causes epidemic cholera.'),
('a24bd2ae-4729-50ee-a547-ce28cfc152a2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism causes profuse watery diarrhea by secreting a heat-labile toxin (LT) that activates adenylate cyclase and a heat-stable toxin (ST) that activates guanylate cyclase?', '["Enterotoxigenic E. coli (ETEC)","Enterohemorrhagic E. coli (EHEC)","Salmonella typhi","Shigella dysenteriae","Vibrio parahaemolyticus"]'::jsonb, 'Enterotoxigenic E. coli (ETEC)', 'ETEC produces LT and ST enterotoxins that drive chloride and water secretion in the small intestine, the classic mechanism of traveler''s diarrhea.'),
('35dc7c74-ef77-5784-a996-b346889c7933'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative enteric bacillus is the most common cause of community-acquired urinary tract infection and a leading cause of neonatal meningitis and Gram-negative sepsis?', '["Salmonella typhi","Klebsiella pneumoniae","Shigella dysenteriae","Escherichia coli","Pseudomonas aeruginosa"]'::jsonb, 'Escherichia coli', 'E. coli is the archetypal lactose-fermenting, oxidase-negative enteric bacillus and the most common cause of community UTI; K1-encapsulated strains cause neonatal meningitis.'),
('4f64ab20-2916-5118-a1ba-3d88d39206db'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Enteroaggregative E. coli, which adheres to enterocytes in a ''stacked-brick'' aggregate pattern, classically causes:', '["Persistent watery diarrhea in children","Bloody diarrhea with hemolytic-uremic syndrome","Traveler''s diarrhea","Necrotizing skin infection","Typhoid fever"]'::jsonb, 'Persistent watery diarrhea in children', 'EAEC forms aggregative fimbriae giving a stacked-brick adhesion pattern and causes persistent watery diarrhea in children and immunocompromised patients.'),
('f2d94f56-62c7-50b4-9e44-68d88ba2ef1e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which non-motile enteric bacillus characteristically produces large mucoid, string-test-positive colonies on MacConkey agar and is a leading cause of Friedlander pneumonia?', '["Salmonella typhi","Escherichia coli","Klebsiella pneumoniae","Shigella dysenteriae","Pseudomonas aeruginosa"]'::jsonb, 'Klebsiella pneumoniae', 'K. pneumoniae''s thick polysaccharide capsule resists phagocytosis, gives string-test-positive mucoid colonies, and is the classic cause of Friedlander (currant-jelly) pneumonia.'),
('b5993997-2eb4-54e1-a866-a2b99458e051'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about E. coli O157:H7 is TRUE?', '["It produces Shiga-like toxin and causes bloody diarrhea that can progress to HUS","It produces heat-labile toxin causing watery traveler''s diarrhea","It causes attaching-effacing lesions confined to infants","It is a non-motile, lactose-negative rod","It is a leading cause of neonatal meningitis"]'::jsonb, 'It produces Shiga-like toxin and causes bloody diarrhea that can progress to HUS', 'The O157:H7 serotype produces Shiga-like (verocyto)toxin, causing hemorrhagic colitis complicated by hemolytic-uremic syndrome, classically after undercooked ground beef.'),
('09145ae0-0cd4-561e-b00f-d5c83a104157'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which medium is used to isolate non-typhoidal Salmonella from stool?', '["XLD or SS agar (pale colonies with black H2S-positive centers)","Lowenstein-Jensen medium accompanied by associated clinical symptoms","Thayer-Martin agar mediated by specific receptor activation","Cetrimide agar without affecting the primary tissue pathway","TCBS agar leading to subsequent cellular adaptation"]'::jsonb, 'XLD or SS agar (pale colonies with black H2S-positive centers)', 'Salmonella is a non-lactose fermenter that produces H2S, giving pale colonies with black centers on XLD or SS agar.'),
('d86db979-461b-5e25-9884-4674a1931bbe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which lactose-fermenting, oxidase-negative bacillus, the prototype of the Enterobacteriaceae, is the single most frequent cause of uncomplicated UTI in women?', '["Shigella dysenteriae","Pseudomonas aeruginosa","Klebsiella pneumoniae","Salmonella typhi","Escherichia coli"]'::jsonb, 'Escherichia coli', 'E. coli is the prototype Enterobacteriaceae and the most frequent isolate in both Gram-negative sepsis and uncomplicated urinary tract infection.'),
('5280f39f-32e1-5231-a8fa-dbf1756a4bcb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Klebsiella pneumoniae is classically associated with which clinical setting?', '["Urinary tract infection and hospital-acquired pneumonia (often multidrug-resistant)","Typhoid fever accompanied by associated clinical symptoms","Cholera mediated by specific receptor activation","Bacillary dysentery without affecting the primary tissue pathway","Peptic ulcer disease leading to subsequent cellular adaptation"]'::jsonb, 'Urinary tract infection and hospital-acquired pneumonia (often multidrug-resistant)', 'Klebsiella is an important nosocomial pathogen causing UTI, wound sepsis and pneumonia, and is frequently multidrug-resistant via ESBLs and carbapenemases.'),
('88df4938-a921-5cdf-8c2d-739f581c4879'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which of the following Gram-negative rods is oxidase-negative?', '["E. coli","Pseudomonas aeruginosa","Vibrio cholerae","Campylobacter jejuni","Neisseria meningitidis"]'::jsonb, 'E. coli', 'Enterobacteriaceae including E. coli are oxidase-negative, whereas Pseudomonas, Vibrio, Campylobacter and Neisseria are oxidase-positive.'),
('740021ca-539f-5e30-a21e-db3f8d3340b5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'An alcoholic with fever, productive cough and lobar consolidation produces ''currant-jelly'' sputum. Which Gram-negative enteric bacillus is the classic cause?', '["Klebsiella pneumoniae","Salmonella typhi","Shigella dysenteriae","Enterobacter cloacae","Proteus mirabilis"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella causes destructive lobar pneumonia in alcoholics and diabetics; the mucoid encapsulated colonies and currant-jelly sputum are characteristic.'),
('8068b4c9-ce2b-5a36-9681-bdec2c58ff2f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'EHEC (E. coli O157:H7) fails to ferment sorbitol and is detected on which medium?', '["Sorbitol-MacConkey agar","Lowenstein-Jensen medium","Thayer-Martin agar","Cetrimide agar","TCBS agar"]'::jsonb, 'Sorbitol-MacConkey agar', 'O157:H7 is sorbitol-negative and forms colorless colonies on sorbitol-MacConkey agar, unlike the pink sorbitol-fermenting E. coli.'),
('b2e03ca6-62f4-549e-aa41-6944524b67c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism needs an extremely low infectious dose, does not ferment lactose, produces no H2S and shows no motility, distinguishing it from Salmonella and Proteus?', '["Shigella dysenteriae","Escherichia coli","Salmonella typhi","Pseudomonas aeruginosa","Klebsiella pneumoniae"]'::jsonb, 'Shigella dysenteriae', 'S. dysenteriae is non-motile, non-lactose-fermenting and H2S-negative, and survives gastric acid because as few as 10-100 organisms cause disease.'),
('f7b411c8-2753-51e4-8a17-30734060fb07'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative rod, a prominent ESBL and KPC carbapenemase producer, is a frequent cause of multidrug-resistant hospital-acquired pneumonia and UTI?', '["Klebsiella pneumoniae","Salmonella typhi","Pseudomonas aeruginosa","Shigella dysenteriae","Escherichia coli"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella is a prominent ESBL- and KPC-carbapenemase-producing Enterobacteriaceae member and a leading agent of multidrug-resistant hospital pneumonia and UTI.'),
('4c015888-3cd8-5838-9ee2-5f51567a0868'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which property of Plesiomonas shigelloides distinguishes it from the true enteric pathogens of the Enterobacteriaceae?', '["Oxidase positivity","Non-motility","Lactose fermentation","Urease production","Spore formation"]'::jsonb, 'Oxidase positivity', 'Plesiomonas is an oxidase-positive member of the Vibrionaceae, whereas all Enterobacteriaceae such as E. coli and Salmonella are oxidase-negative.'),
('b1c45e27-9bae-562d-9a17-3498e4905749'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which capsulated, lactose-fermenting Enterobacteriaceae member (non-motile) is a classic cause of lobar pneumonia in alcoholics and diabetics?', '["Shigella dysenteriae","Pseudomonas aeruginosa","Salmonella typhi","Escherichia coli","Klebsiella pneumoniae"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella is encapsulated, lactose-fermenting, urease-positive and non-motile; its capsule produces mucoid colonies and predisposes to lobar pneumonia in alcoholics and diabetics.'),
('7fded930-31b4-5f88-adc4-5d32ceef7751'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Chronic antral gastritis is most strongly associated with which organism?', '["Pseudomonas aeruginosa","Escherichia coli","Salmonella typhi","Shigella dysenteriae","Helicobacter pylori"]'::jsonb, 'Helicobacter pylori', 'H. pylori colonizes the gastric antrum and causes chronic (type B) gastritis, progressing to peptic ulcer and gastric malignancy.'),
('3dd2cc1c-3cd7-5be2-bf59-a7a49a0837bc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism is isolated from blood and stool in a patient with sustained fever and rose spots in whom the Widal test shows rising O and H agglutinin titers?', '["Shigella dysenteriae","Escherichia coli","Klebsiella pneumoniae","Salmonella typhi","Pseudomonas aeruginosa"]'::jsonb, 'Salmonella typhi', 'S. typhi enters via Peyer patches, multiplies in macrophages and produces sustained enteric fever with rose spots; chronic carriers harbor it in the gallbladder.'),
('a93fa645-2fca-55fa-bd13-15d81576764a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about endotoxin (LPS) is TRUE?', '["It is the lipid A component of the Gram-negative outer membrane released on lysis, causing fever and shock","It is a heat-labile protein secreted by Vibrio cholerae accompanied by associated clinical symptoms","It is the Shiga toxin of S. dysenteriae mediated by specific receptor activation","It is a structural protein of Gram-positive cell walls without affecting the primary tissue pathway","It is an exotoxin neutralized by formalin leading to subsequent cellular adaptation"]'::jsonb, 'It is the lipid A component of the Gram-negative outer membrane released on lysis, causing fever and shock', 'Endotoxin is lipopolysaccharide whose lipid A, released at bacterial lysis, triggers the pyrexia, vasodilatation and coagulopathy of Gram-negative sepsis.'),
('27452053-ecf4-5117-a023-9a67a4aa9431'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which non-fermenting, oxidase-positive bacillus is a leading cause of ventilator-associated pneumonia and sepsis in neutropenic patients, thriving in moist hospital devices and water?', '["Shigella dysenteriae","Klebsiella pneumoniae","Pseudomonas aeruginosa","Escherichia coli","Salmonella typhi"]'::jsonb, 'Pseudomonas aeruginosa', 'P. aeruginosa thrives in moist environments, chronically colonizes cystic fibrosis lungs (mucoid biofilms) and causes burn and ventilator-associated infections, especially in neutropenic hosts.'),
('3caed037-c4d7-5709-8058-94ce36333025'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which of the following is NOT a member of the Enterobacteriaceae?', '["Vibrio cholerae","Escherichia coli","Klebsiella pneumoniae","Salmonella typhi","Shigella dysenteriae"]'::jsonb, 'Vibrio cholerae', 'Vibrio belongs to the Vibrionaceae; the Enterobacteriaceae include E. coli, Klebsiella, Salmonella and Shigella.'),
('ce5a5fff-28a7-5688-826c-82d550161b17'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A positive urea breath test is diagnostic of infection with:', '["Helicobacter pylori","Escherichia coli","Klebsiella pneumoniae","Shigella dysenteriae","Pseudomonas aeruginosa"]'::jsonb, 'Helicobacter pylori', 'H. pylori is strongly urease-positive; ingested labeled urea is split to CO2, which is detected in the exhaled breath.'),
('81aa1ca5-7762-5b49-b602-8db8de4d3f3c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Aeromonas species, oxidase-positive motile rods acquired from aquatic environments, most commonly cause:', '["Gastroenteritis and wound infections after water exposure","Typhoid fever accompanied by associated clinical symptoms","Bacillary dysentery mediated by specific receptor activation","Cholera without affecting the primary tissue pathway","Peptic ulcer leading to subsequent cellular adaptation"]'::jsonb, 'Gastroenteritis and wound infections after water exposure', 'Aeromonas is an aquatic, oxidase-positive genus causing self-limited gastroenteritis and soft-tissue wound infections after freshwater exposure.'),
('d529e2f1-26bb-5dc2-8d3b-16af7e7e8df3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Pseudomonas aeruginosa is TRUE?', '["It is oxidase-positive, produces pyocyanin and grows on cetrimide agar","It is a lactose-fermenting member of the Enterobacteriaceae","It is non-motile and highly dependent on its capsule","It is a strictly anaerobic bowel commensal","It is oxidase-negative"]'::jsonb, 'It is oxidase-positive, produces pyocyanin and grows on cetrimide agar', 'P. aeruginosa is oxidase-positive, motile, pyocyanin-producing and selectively grows on cetrimide agar; it is nutritionally versatile and intrinsically antibiotic resistant.'),
('f390c076-9f88-50dd-9d2c-96f9d34025a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism, intrinsically resistant to most beta-lactams and aminoglycosides, elaborates exotoxin A that ADP-ribosylates elongation factor-2?', '["Pseudomonas aeruginosa","Shigella dysenteriae","Escherichia coli","Salmonella typhi","Klebsiella pneumoniae"]'::jsonb, 'Pseudomonas aeruginosa', 'Oxidase-positivity separates P. aeruginosa from the Enterobacteriaceae; inducible AmpC, efflux pumps and membrane impermeability render it intrinsically resistant to many standard antibiotics.'),
('b5e53b1a-5db0-530f-9631-ac18f18e96db'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which oxidase-positive, motile Gram-negative bacillus grows on cetrimide agar and is the paradigm opportunist of burns, cystic fibrosis and neutropenic sepsis?', '["Shigella dysenteriae","Klebsiella pneumoniae","Escherichia coli","Pseudomonas aeruginosa","Salmonella typhi"]'::jsonb, 'Pseudomonas aeruginosa', 'Cetrimide agar is selective for P. aeruginosa, the oxidase-positive opportunist of burns, ventilators and cystic fibrosis.'),
('9c9c3d32-d9a0-5e19-b69b-d4ebc2979fdd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative rod is oxidase-positive and commonly causes infections in burns?', '["Klebsiella pneumoniae","Pseudomonas aeruginosa","Shigella dysenteriae","Escherichia coli","Salmonella typhi"]'::jsonb, 'Pseudomonas aeruginosa', 'P. aeruginosa is oxidase-positive and thrives in the moist devascularized eschar of burns, causing blue-green invasive wound infection.'),
('6b899fef-fd3f-5080-a191-f8e8cede5822'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism causes chronic, ultimately fatal pulmonary infections in cystic fibrosis patients?', '["Pseudomonas aeruginosa","Klebsiella pneumoniae","Escherichia coli","Salmonella typhi","Shigella dysenteriae"]'::jsonb, 'Pseudomonas aeruginosa', 'P. aeruginosa colonizes cystic fibrosis airways as mucoid alginate-embedded biofilms and is the leading cause of chronic lung infection and death in these patients.'),
('f1df8860-e2de-5189-b76e-7b3601ba60df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Profuse ''rice-water'' stools reflect disease caused by:', '["Vibrio cholerae","Escherichia coli","Klebsiella pneumoniae","Shigella dysenteriae","Salmonella typhi"]'::jsonb, 'Vibrio cholerae', 'Cholera toxin drives massive chloride and water secretion producing ''rice-water'' stools, the hallmark of V. cholerae infection.'),
('2b05558f-dc1e-573c-9b32-1e562d9bf4fc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which heavily encapsulated, lactose-fermenting bacillus causes ''currant-jelly'' sputum lobar pneumonia in alcoholics, and UTIs and nosocomial sepsis?', '["Shigella dysenteriae","Pseudomonas aeruginosa","Klebsiella pneumoniae","Escherichia coli","Salmonella typhi"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella''s capsule produces mucoid colonies and pathogenic lobar pneumonia in alcoholics and diabetics plus hospital-acquired UTI and sepsis.'),
('b942eb52-ab8b-5793-b0be-c31b46b7e210'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Arcobacter, a curved Gram-negative rod closely related to Campylobacter, most commonly causes:', '["Gastroenteritis","Typhoid fever","Cholera","Bacillary dysentery","Plague"]'::jsonb, 'Gastroenteritis', 'Arcobacter species of the Campylobacteraceae cause enteritis, generally milder than Campylobacter, acquired from contaminated food and water.'),
('ddd3a23e-a641-560b-b297-4c1984c5655b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A nosocomial Gram-negative rod forms red pigment (prodigiosin) at room temperature. Which organism is this?', '["Serratia marcescens","Klebsiella pneumoniae","Escherichia coli","Proteus mirabilis","Pseudomonas aeruginosa"]'::jsonb, 'Serratia marcescens', 'S. marcescens produces the red pigment prodigiosin and is an important opportunistic, increasingly carbapenem-resistant nosocomial pathogen.'),
('c8a0d87e-7f63-577c-968e-58c5ef83fa5e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'NDM-1 (New Delhi metallo-beta-lactamase), which inactivates carbapenems, is most commonly carried by which organisms?', '["Klebsiella pneumoniae and E. coli","Salmonella typhi","Shigella dysenteriae","Vibrio cholerae","Yersinia pestis"]'::jsonb, 'Klebsiella pneumoniae and E. coli', 'blaNDM-1 is spread on plasmids among Enterobacteriaceae, especially K. pneumoniae and E. coli, causing carbapenem-resistant hospital outbreaks.'),
('2a1761df-5163-5ef4-bcf3-db61b260c625'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Morganella morganii, a urease- and indole-positive enteric rod, most commonly causes:', '["Urinary tract infection","Typhoid fever","Bacillary dysentery","Cholera","Peptic ulcer"]'::jsonb, 'Urinary tract infection', 'Morganella is an opportunistic urease-positive enteric rod of elderly and hospitalized patients, mainly causing urinary tract infection.'),
('5b3aa6f7-e70f-5a56-8f6e-7e8422773914'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which oxidase-positive, non-lactose-fermenting rod produces blue-green pyocyanin and characteristically infects burn wounds and cystic fibrosis airways?', '["Escherichia coli","Salmonella typhi","Shigella dysenteriae","Klebsiella pneumoniae","Pseudomonas aeruginosa"]'::jsonb, 'Pseudomonas aeruginosa', 'P. aeruginosa is oxidase-positive, non-lactose-fermenting and pyocyanin-producing, and dominates burns, ventilators and cystic fibrosis lungs.'),
('7f612fdd-3b3e-5e1c-8544-ce79a24ecf0d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Hafnia alvei, a member of the Enterobacteriaceae, is best characterized by which feature?', '["Motile, lactose-nonfermenting, H2S-negative rod","Non-motile dysentery bacillus","Curved, oxidase-positive vibrio","Acid-fast bacillus","Gram-positive coccus"]'::jsonb, 'Motile, lactose-nonfermenting, H2S-negative rod', 'Hafnia alvei is a facultative, motile, oxidase-negative rod that does not ferment lactose; it is isolated from stool and occasionally causes opportunistic infection.'),
('59ae9774-05ee-5780-98bf-2c8b8813b636'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism is an obligate anaerobe, in contrast to the facultatively anaerobic enteric bacilli?', '["Bacteroides fragilis","Escherichia coli","Klebsiella pneumoniae","Salmonella typhi","Proteus mirabilis"]'::jsonb, 'Bacteroides fragilis', 'Bacteroides fragilis is an obligate anaerobe and the most common anaerobe of the colonic flora and intra-abdominal abscesses, unlike the facultative enterics.'),
('52118efd-f547-5365-9c23-abbaaf234049'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enteric bacillus, whose K1 capsular polysaccharide is a key determinant of neonatal meningitis, also possesses diarrheagenic and uropathogenic profiles?', '["Salmonella typhi","Shigella dysenteriae","Klebsiella pneumoniae","Pseudomonas aeruginosa","Escherichia coli"]'::jsonb, 'Escherichia coli', 'E. coli K1 strains resist serum and cause neonatal meningitis; E. coli also causes UTI and is the basis of the diarrheagenic pathotypes.'),
('14306112-76eb-5071-b889-13ca8b92f3dd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Enterobacter species differ from Klebsiella pneumoniae chiefly by being:', '["Motile","Non-motile","Oxidase positive","Lactose negative","Indole positive"]'::jsonb, 'Motile', 'Klebsiella is characteristically non-motile and heavily capsulated, whereas Enterobacter is motile; both are lactose-fermenting Enterobacteriaceae.'),
('24520c83-26ed-5a1f-9892-bcd70dc377ea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The Vi capsular polysaccharide antigen is characteristic of which organism?', '["Salmonella typhi","Pseudomonas aeruginosa","Klebsiella pneumoniae","Escherichia coli","Shigella dysenteriae"]'::jsonb, 'Salmonella typhi', 'S. typhi expresses the Vi capsular polysaccharide that masks O antigen, resists phagocytosis and is the target of carrier-detection serology.'),
('df9895a3-22c2-54a6-a488-99317928708a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which combination of biochemical features identifies Shigella species?', '["Non-motile, non-lactose-fermenting, no H2S production","Motile with H2S production","Oxidase-positive curved rod","Lactose-fermenting, motile rod","Urease-positive swarming rod"]'::jsonb, 'Non-motile, non-lactose-fermenting, no H2S production', 'Shigella is a non-motile, non-lactose-fermenting, H2S-negative, oxidase-negative rod; serologic agglutination confirms the species.'),
('f1a263fe-577f-57a5-829b-e577214dbca4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Providencia species are urease-positive, multiply resistant enteric rods that classically cause:', '["Catheter-associated UTI","Typhoid fever","Cholera","Bacillary dysentery","Peptic ulcer"]'::jsonb, 'Catheter-associated UTI', 'Providencia thrives in long-term urinary catheters and causes multiply resistant nosocomial UTI.'),
('e9c62389-f406-5ca8-ba13-6ea95f8c1b86'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Pneumonic plague, a rapidly fatal Yersinia pestis infection, is treated with which antimicrobial class?', '["Aminoglycosides (streptomycin or gentamicin)","Erythromycin accompanied by associated clinical symptoms","Metronidazole mediated by specific receptor activation","Vancomycin without affecting the primary tissue pathway","Clindamycin leading to subsequent cellular adaptation"]'::jsonb, 'Aminoglycosides (streptomycin or gentamicin)', 'Streptomycin or gentamicin are first-line for plague; doxycycline is an alternative, giving aminoglycosides as the key initial therapy.'),
('37a75c44-e8e8-5612-8cbe-42d8d8027dfa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Rising O and H agglutinin titers on the Widal test support a diagnosis of:', '["Typhoid fever","Cholera","Bacillary dysentery","Plague","Peptic ulcer"]'::jsonb, 'Typhoid fever', 'The Widal test measures agglutinins against the somatic O and flagellar H antigens of S. typhi, supporting enteric (typhoid) fever.'),
('73fa59ba-44b8-51cc-9c0d-adb8c98820c1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about ESBL-producing Enterobacteriaceae is TRUE?', '["They hydrolyze third-generation cephalosporins; carbapenems are used for serious infection","They respond reliably to penicillin V","They are exclusively Gram-positive organisms","They are detected by the oxidase reaction","They remain susceptible to first-generation cephalosporins"]'::jsonb, 'They hydrolyze third-generation cephalosporins; carbapenems are used for serious infection', 'ESBLs (CTX-M, TEM, SHV) hydrolyze penicillins and cephalosporins including oxyimino compounds; carbapenems are the drugs of choice for serious infection.'),
('8a47061e-e131-5034-ba41-a2864d041182'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative rod causes typhoid fever with rose spots?', '["Salmonella typhi","Klebsiella pneumoniae","Shigella dysenteriae","Escherichia coli","Pseudomonas aeruginosa"]'::jsonb, 'Salmonella typhi', 'S. typhi causes enteric fever; rose spots are faint erythematous maculopapular lesions appearing in crops on the trunk during the first week.'),
('8308d784-f57f-50bf-b3fc-49ee971332dd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative enteric organism is the most common cause of ascending cholangitis?', '["Escherichia coli","Salmonella typhi","Vibrio cholerae","Shigella dysenteriae","Pseudomonas aeruginosa"]'::jsonb, 'Escherichia coli', 'Among biliary infections, E. coli (with Klebsiella and enterococci) is the most frequent isolate in ascending cholangitis.'),
('d33d1c5c-7577-5483-9dd2-6aed88e60f00'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Lipid A released from lysed Gram-negative bacilli mediates which effects?', '["Fever, hypotension and disseminated intravascular coagulation","Secretory watery diarrhea accompanied by associated clinical symptoms","Flaccid paralysis mediated by specific receptor activation","Stimulation of adenylate cyclase without affecting the primary tissue pathway","Bacteriocin production leading to subsequent cellular adaptation"]'::jsonb, 'Fever, hypotension and disseminated intravascular coagulation', 'Lipid A of LPS triggers TLR4-driven cytokine release producing the fever, vasodilatory shock and coagulopathy of endotoxemia.'),
('c3af865b-dbc9-5c02-8e4a-3ccd3e6b7541'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Pseudomonas aeruginosa exotoxin A damages host cells by:', '["ADP-ribosylating elongation factor-2, blocking protein synthesis","Activating adenylate cyclase in enterocytes","Inactivating the 60S ribosomal subunit","Cleaving SNARE proteins","Blocking GABA release"]'::jsonb, 'ADP-ribosylating elongation factor-2, blocking protein synthesis', 'Exotoxin A ADP-ribosylates EF-2, halting host protein synthesis, analogous to diphtheria toxin.'),
('5f7f5bb8-2b7a-52f0-a7a7-65f04009c5ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative bacillus produces Shiga toxin, an exotoxin with enterotoxic and neurotoxic activity, and is the classic agent of bacillary dysentery?', '["Klebsiella pneumoniae","Shigella dysenteriae","Escherichia coli","Pseudomonas aeruginosa","Salmonella typhi"]'::jsonb, 'Shigella dysenteriae', 'S. dysenteriae type 1 produces Shiga toxin; mucosal invasion plus this toxin produce the crampy, bloody dysentery.'),
('c1712401-091c-5a2e-99b0-80f3f69b28b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A heat-labile enterotoxin (LT) that activates adenylate cyclase is a major virulence factor of:', '["Enterotoxigenic E. coli (ETEC)","Salmonella typhi","Shigella dysenteriae","Pseudomonas aeruginosa","Yersinia pestis"]'::jsonb, 'Enterotoxigenic E. coli (ETEC)', 'ETEC produces LT (adenylate cyclase-activating) and ST (guanylate cyclase-activating) enterotoxins producing watery traveler''s diarrhea.'),
('7024d034-b18f-52ab-b6f9-3bda67e24b58'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The blue-green pigment pyocyanin is characteristically produced by:', '["Pseudomonas aeruginosa","Escherichia coli","Klebsiella pneumoniae","Shigella dysenteriae","Salmonella typhi"]'::jsonb, 'Pseudomonas aeruginosa', 'Pyocyanin is a phenazine pigment unique to P. aeruginosa, giving infected wounds, sputum and pus a blue-green color.'),
('68580496-32cf-5f65-bf98-9875739b6f8d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Proteus mirabilis promotes which classic renal complication?', '["Struvite (triple-phosphate) stones due to urease","Typhoid fever accompanied by associated clinical symptoms","Cholera mediated by specific receptor activation","Peptic ulcer without affecting the primary tissue pathway","Bacillary dysentery leading to subsequent cellular adaptation"]'::jsonb, 'Struvite (triple-phosphate) stones due to urease', 'Proteus urease alkalinizes urine by splitting urea to ammonia, precipitating struvite (triple-phosphate) renal stones.'),
('5025e4f3-2854-5148-ab4b-e6f310697788'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Lipopolysaccharide (LPS) is a constituent of the outer membrane of which organisms?', '["All Gram-negative bacilli","Gram-positive cocci","Acid-fast bacilli","Viruses","Fungi"]'::jsonb, 'All Gram-negative bacilli', 'LPS (lipid A, core, O-chain) is unique to the outer membrane of Gram-negative bacilli, which is why all of them possess endotoxin.'),
('53e51d01-2bf4-5ee8-8a35-d241b49a750d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Vibrio vulnificus, a halophilic marine vibrio, classically causes:', '["Necrotizing wound infection and primary septicemia","Typhoid fever accompanied by associated clinical symptoms","Bacillary dysentery mediated by specific receptor activation","Cholera without affecting the primary tissue pathway","Peptic ulcer leading to subsequent cellular adaptation"]'::jsonb, 'Necrotizing wound infection and primary septicemia', 'V. vulnificus causes necrotizing fasciitis after seawater wound exposure and primary septicemia after raw oysters, particularly with cirrhosis or iron overload.'),
('05009df4-c2cd-56a8-b4aa-9503f3005bca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism needs an extremely low infectious dose, does not ferment lactose, produces no H2S and shows no motility?', '["Salmonella typhi","Shigella dysenteriae","Pseudomonas aeruginosa","Escherichia coli","Klebsiella pneumoniae"]'::jsonb, 'Shigella dysenteriae', 'Shigella is non-motile, H2S-negative and non-lactose-fermenting; as few as 10-100 organisms cause dysentery because it resists gastric acid.'),
('15dd4040-4294-5d3c-a1b8-92c48938ed75'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'KPC (Klebsiella pneumoniae carbapenemase) inactivates which drug class?', '["Carbapenems (and most other beta-lactams)","Aminoglycosides accompanied by associated clinical symptoms","Tetracyclines mediated by specific receptor activation","Macrolides without affecting the primary tissue pathway","Glycopeptides leading to subsequent cellular adaptation"]'::jsonb, 'Carbapenems (and most other beta-lactams)', 'KPC is a serine carbapenemase of K. pneumoniae hydrolyzing carbapenems and most other beta-lactams, causing carbapenem-resistant Enterobacteriaceae.'),
('1bc8e4f5-aa7f-5f7c-a11b-0ae9d7cc50c9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Culture of blood-tinged stool yields pale, non-lactose-fermenting, non-motile colonies on MacConkey agar. This supports which diagnosis?', '["Shigellosis (bacillary dysentery)","Typhoid fever accompanied by associated clinical symptoms","Cholera mediated by specific receptor activation","Plague without affecting the primary tissue pathway","Peptic ulcer leading to subsequent cellular adaptation"]'::jsonb, 'Shigellosis (bacillary dysentery)', 'Shigella produces pale non-lactose-fermenting, non-motile colonies and causes the bloody mucoid stools of bacillary dysentery.'),
('c5109be8-f725-5aed-ba3c-2c0da0d4ba9c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Blood and mucus in stools with tenesmus and a very low infectious inoculum characterize infection with:', '["Shigella species","Salmonella typhi","Vibrio cholerae","Campylobacter jejuni","Yersinia enterocolitica"]'::jsonb, 'Shigella species', 'Shigella invades the colonic mucosa causing bloody mucoid stools and tenesmus; only 10-100 organisms are needed to cause disease.'),
('b1ef2f52-319b-529f-80fe-b94bf9933e52'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which capsulated, lactose-fermenting Enterobacteriaceae member (non-motile) is a classic cause of lobar pneumonia in diabetics and alcoholics?', '["Pseudomonas aeruginosa","Klebsiella pneumoniae","Shigella dysenteriae","Escherichia coli","Salmonella typhi"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella is encapsulated, lactose-fermenting and non-motile, and classically causes lobar pneumonia in alcoholics and diabetics.'),
('6332dcf0-5480-5b09-917d-0095630f3927'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Bubonic plague is caused by which flea-transmitted organism?', '["Yersinia pestis","Salmonella typhi","Klebsiella pneumoniae","Brucella melitensis","Francisella tularensis"]'::jsonb, 'Yersinia pestis', 'Y. pestis, transmitted by the rat flea, causes bubonic plague with painful necrotic lymphadenopathy (bubo).'),
('3a4d76e0-7852-596a-8fde-51166ba81f5c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Pink, lactose-fermenting colonies on MacConkey agar are produced by:', '["E. coli and Klebsiella","Salmonella and Shigella","Vibrio and Campylobacter","Pseudomonas and Acinetobacter","Bacteroides"]'::jsonb, 'E. coli and Klebsiella', 'Lactose-positive enterics acidify MacConkey agar and take up neutral red, producing pink colonies; Salmonella, Shigella and Vibrio remain pale.'),
('8c352a74-5e8d-585f-8cca-cff4de3e1f93'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A painful, necrotic inguinal lymph node (bubo) after rat-flea exposure is the hallmark of:', '["Bubonic plague","Typhoid fever","Cholera","Bacillary dysentery","Anthrax"]'::jsonb, 'Bubonic plague', 'Y. pestis, acquired by flea bite, drains to regional lymph nodes producing the painful bubo characteristic of bubonic plague.'),
('8e3f4304-88e3-5b57-8445-53f60434a59d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A motile, H2S-producing, non-lactose-fermenting bacillus that chronically colonizes the gallbladder and causes enteric fever is:', '["Pseudomonas aeruginosa","Klebsiella pneumoniae","Salmonella typhi","Shigella dysenteriae","Escherichia coli"]'::jsonb, 'Salmonella typhi', 'S. typhi uses its Vi capsular polysaccharide to resist complement; it persists in the gallbladder of carriers and causes enteric fever.'),
('5f6343e5-f069-5abc-91a7-f8764ffd32f0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Bloody diarrhea complicated by acute renal failure, thrombocytopenia and microangiopathic hemolysis is classically caused by:', '["Shiga toxin-producing E. coli (EHEC, e.g. O157:H7)","Enterotoxigenic E. coli (ETEC)","Enteropathogenic E. coli (EPEC)","Enteroaggregative E. coli (EAEC)","Uropathogenic E. coli"]'::jsonb, 'Shiga toxin-producing E. coli (EHEC, e.g. O157:H7)', 'EHEC''s Shiga-like toxin damages renal and intestinal endothelium, causing hemorrhagic colitis and hemolytic-uremic syndrome in children.'),
('672b1860-7537-5d92-bee4-6c3da098bcac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enteric Gram-negative rod, present with peritrichous flagella and pili, is the most common cause of cystitis, pyelonephritis and Gram-negative bacteremia?', '["Shigella dysenteriae","Pseudomonas aeruginosa","Salmonella typhi","Escherichia coli","Klebsiella pneumoniae"]'::jsonb, 'Escherichia coli', 'E. coli is the most common cause of cystitis, pyelonephritis and Gram-negative bacteremia, with P fimbriae driving uropathogenesis.'),
('05404e0c-a4c9-5664-ac5d-45025f00aa09'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which heavily encapsulated, lactose-fermenting, urease-positive bacillus causes ''currant-jelly'' lobar pneumonia in alcoholics and UTIs and nosocomial sepsis?', '["Salmonella typhi","Klebsiella pneumoniae","Shigella dysenteriae","Escherichia coli","Pseudomonas aeruginosa"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella is a prominent ESBL- and KPC-carbapenemase-producing Enterobacteriaceae member and the classic cause of currant-jelly pneumonia.'),
('3145b0f4-966d-5008-87ad-bff39cacf78a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'On Triple Sugar Iron (TSI) agar, which organism produces an alkaline slant and acid butt with H2S blackening, distinguishing it from lactose-fermenting E. coli?', '["Salmonella typhi","Klebsiella pneumoniae","Enterobacter cloacae","Proteus mirabilis","Citrobacter freundii"]'::jsonb, 'Salmonella typhi', 'S. typhi ferments glucose but not lactose or sucrose, giving an alkaline slant and acid butt, and produces H2S causing blackening of the medium.'),
('fd9b078c-63a7-5a17-bf29-35653ca8f8d3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative enteric bacillus is the most common cause of community-acquired UTI and a leading cause of neonatal meningitis and Gram-negative sepsis?', '["Escherichia coli","Salmonella typhi","Klebsiella pneumoniae","Shigella dysenteriae","Pseudomonas aeruginosa"]'::jsonb, 'Escherichia coli', 'E. coli is the prototype Enterobacteriaceae and the most frequent isolate in Gram-negative sepsis and UTI; K1 strains cause neonatal meningitis.'),
('865112c4-e50c-5660-8d56-36168f3f20cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Chronic gastritis is associated with which organism?', '["E. coli","Pseudomonas aeruginosa","Klebsiella pneumoniae","Shigella dysenteriae","Helicobacter pylori"]'::jsonb, 'Helicobacter pylori', 'H. pylori colonizes the gastric antrum causing chronic (type B) gastritis and predisposes to ulcer and gastric cancer.'),
('a00a382b-4213-5e95-8e3c-00c76e8abe2f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Shiga (verocyto)toxin is classically produced by:', '["Shigella dysenteriae and Shiga toxin-producing E. coli","Salmonella typhi accompanied by associated clinical symptoms","Vibrio cholerae mediated by specific receptor activation","Pseudomonas aeruginosa without affecting the primary tissue pathway","Klebsiella pneumoniae leading to subsequent cellular adaptation"]'::jsonb, 'Shigella dysenteriae and Shiga toxin-producing E. coli', 'Shiga toxin is made by S. dysenteriae type 1 and by STEC (EHEC), both causing hemorrhagic colitis and HUS.'),
('07715198-beb2-571e-9587-c7f3d1f2ffe6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which of the following distinguishes endotoxin from exotoxin?', '["Endotoxin is lipopolysaccharide causing toxemia, whereas exotoxins are proteins with specific enzymatic targets","Endotoxin is a secreted heat-labile protein accompanied by associated clinical symptoms","Endotoxin is produced only by Gram-positive organisms mediated by specific receptor activation","Endotoxin is neutralized by formaldehyde toxoiding without affecting the primary tissue pathway","Endotoxin activates only the GABA receptor leading to subsequent cellular adaptation"]'::jsonb, 'Endotoxin is lipopolysaccharide causing toxemia, whereas exotoxins are proteins with specific enzymatic targets', 'Endotoxin (LPS) is a structural component of the Gram-negative outer membrane released on lysis, while exotoxins are secreted proteins with specific mechanisms of action.'),
('f091ec08-b925-5f4c-b757-095ac5d4fac3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Campylobacter jejuni enteritis is the most common antecedent of which post-infectious neuropathy?', '["Guillain-Barre syndrome","Hemolytic-uremic syndrome","Rheumatic fever","Peptic ulcer","Typhoid fever"]'::jsonb, 'Guillain-Barre syndrome', 'C. jejuni lipooligosaccharide mimics peripheral nerve gangliosides, so its infection is the most common bacterial trigger of Guillain-Barre syndrome.'),
('88097ffc-ea4d-5b54-b04a-703d99fd75d3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'All members of the Enterobacteriaceae share which set of characteristics?', '["Oxidase-negative, glucose-fermenting rods","Oxidase-positive curved rods","Acid-fast staining rods","Strictly anaerobic spore-forming rods","Gram-positive cocci in pairs"]'::jsonb, 'Oxidase-negative, glucose-fermenting rods', 'Enterobacteriaceae are oxidase-negative, facultatively anaerobic Gram-negative rods that ferment glucose and reduce nitrate.'),
('ae817ce0-b05a-50d7-9ceb-2e2f96dc86af'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enteric bacillus, whose K1 capsular polysaccharide is a key determinant of neonatal meningitis, also possesses diarrheagenic and uropathogenic disease profiles?', '["Salmonella typhi","Klebsiella pneumoniae","Shigella dysenteriae","Escherichia coli","Pseudomonas aeruginosa"]'::jsonb, 'Escherichia coli', 'E. coli is the leading community UTI pathogen; K1-encapsulated strains cause neonatal meningitis and various pathotypes cause diarrhea.'),
('97327bb8-e082-5a23-a64d-0a77b4ca8b0a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Late-onset ventilator-associated pneumonia caused by a non-fermenting, oxidase-positive, multidrug-resistant rod is most likely due to:', '["Pseudomonas aeruginosa","Salmonella typhi","Escherichia coli","Shigella dysenteriae","Klebsiella pneumoniae"]'::jsonb, 'Pseudomonas aeruginosa', 'P. aeruginosa is a non-fermenting, oxidase-positive, intrinsically resistant rod and a leading cause of late-onset ventilator-associated pneumonia.'),
('b046dce0-0eab-5b12-8952-bfc9aef3f08d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Concentric ''wave'' growth spreading over blood agar (swarming motility) is characteristic of which genus?', '["Proteus","Shigella","Klebsiella","Yersinia","Vibrio"]'::jsonb, 'Proteus', 'Proteus species are peritrichously flagellated and swarm in wavelike sheets over moist agar, a distinctive identifying feature.'),
('ce8754a5-3895-5cae-a58c-8a12b7cbc806'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Nosocomial sepsis traced to contaminated intravenous fluids or indwelling catheters is classically caused by which motile enteric rod?', '["Enterobacter cloacae","Klebsiella pneumoniae","Salmonella typhi","Shigella dysenteriae","Proteus mirabilis"]'::jsonb, 'Enterobacter cloacae', 'Enterobacter, a motile, hardy lactose-fermenter, causes nosocomial outbreaks including sepsis from contaminated intravenous fluids and catheters.'),
('eef92823-3785-50a6-af2b-579c7275215e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Bacteroides fragilis, a leading cause of intra-abdominal abscess, is best described as:', '["An obligate anaerobe that is bile-resistant and encapsulated","A spore-forming facultative aerobe accompanied by associated clinical symptoms","An oxidase-positive curved rod mediated by specific receptor activation","An acid-fast bacillus without affecting the primary tissue pathway","A Gram-positive coccus leading to subsequent cellular adaptation"]'::jsonb, 'An obligate anaerobe that is bile-resistant and encapsulated', 'B. fragilis is an obligately anaerobic, bile-resistant, encapsulated Gram-negative rod and the most common anaerobe in intra-abdominal abscesses.');
insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('3ad97c3b-a1ad-54f1-b3d9-063f7c9c5215'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Gastric MALT (mucosa-associated lymphoid tissue) lymphoma is a long-term complication of chronic infection with:', '["Helicobacter pylori","Salmonella typhi","Shigella dysenteriae","Campylobacter jejuni","Vibrio cholerae"]'::jsonb, 'Helicobacter pylori', 'Chronic H. pylori gastritis drives gastric MALT lymphoma, which may regress after H. pylori eradication.'),
('0603b9e0-2cfb-578d-b2fc-fe3bb0e4b132'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Detection of the Vi capsular polysaccharide is used to identify which organism, particularly its chronic carrier state?', '["Salmonella typhi","Pseudomonas aeruginosa","Klebsiella pneumoniae","Escherichia coli","Shigella dysenteriae"]'::jsonb, 'Salmonella typhi', 'Vi antigen is unique to S. typhi; Vi serology and elevated titers help identify chronic carriers who shed the bacillus in stool.'),
('09c9aafb-cd22-584c-a987-e7e90953041b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Shigella is TRUE?', '["It is non-motile and can cause infection with as few as 100 organisms","It is motile and H2S-positive accompanied by associated clinical symptoms","It produces cholera toxin mediated by specific receptor activation","It requires a large inoculum to cause disease without affecting the primary tissue pathway","It is a harmless bowel commensal leading to subsequent cellular adaptation"]'::jsonb, 'It is non-motile and can cause infection with as few as 100 organisms', 'Shigella is non-motile and has one of the lowest infectious doses of any enteric pathogen (10-100 organisms), causing bloody dysentery.'),
('49c0c347-261e-506a-a0bb-9ad1d0e47bcb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Struvite (triple-phosphate) renal stones are most commonly associated with which urease-producing organism?', '["Proteus mirabilis","Escherichia coli","Salmonella typhi","Shigella dysenteriae","Vibrio cholerae"]'::jsonb, 'Proteus mirabilis', 'P. mirabilis urease hydrolyzes urea to ammonia, alkalinizes urine and precipitates magnesium-ammonium-phosphate (struvite) stones.'),
('ccc1fdb1-f154-5d81-8f77-98b22dff3c2a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Traveler''s diarrhea from ETEC is mediated by which toxins?', '["Heat-labile (LT) and heat-stable (ST) enterotoxins","Shiga toxin accompanied by associated clinical symptoms","Cholera toxin mediated by specific receptor activation","Exotoxin A without affecting the primary tissue pathway","Neurotoxin leading to subsequent cellular adaptation"]'::jsonb, 'Heat-labile (LT) and heat-stable (ST) enterotoxins', 'ETEC produces LT (adenylate cyclase-activating) and ST (guanylate cyclase-activating) enterotoxins, causing watery traveler''s diarrhea.'),
('2edcad9d-e91e-58d0-a42b-94a8bbec3dc9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The Widal test, detecting anti-O and anti-H agglutinins, aids diagnosis of:', '["Typhoid fever","Cholera","Bacillary dysentery","Plague","Peptic ulcer"]'::jsonb, 'Typhoid fever', 'The Widal test measures antibodies against the somatic O and flagellar H antigens of S. typhi, aiding the diagnosis of enteric (typhoid) fever.'),
('2e3464d8-4aa0-5409-a983-436a342c2a64'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which enteric infection most commonly precedes Guillain-Barre syndrome?', '["Campylobacter jejuni","Klebsiella pneumoniae","Escherichia coli","Salmonella typhi","Shigella dysenteriae"]'::jsonb, 'Campylobacter jejuni', 'C. jejuni is the most common infectious antecedent of Guillain-Barre syndrome, mediated by molecular mimicry with nerve gangliosides.'),
('7d409ed1-82ab-5200-9a90-f608aab1fadb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'For serious infection caused by an ESBL-producing enteric Gram-negative rod, the preferred agents are:', '["Carbapenems","Penicillin G","Cephalexin","Ampicillin","Vancomycin"]'::jsonb, 'Carbapenems', 'ESBLs hydrolyze penicillins and cephalosporins, so carbapenems are the drugs of choice for serious infections caused by ESBL producers.'),
('64672152-6f49-529a-93d0-bad3d01600e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Large mucoid, string-test-positive colonies reflect abundant capsular polysaccharide, characteristic of:', '["Klebsiella pneumoniae","Escherichia coli","Salmonella typhi","Pseudomonas aeruginosa","Shigella dysenteriae"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella''s thick capsular polysaccharide produces the glistening mucoid, string-test-positive colonies and resists phagocytosis.'),
('845b0513-f92f-58ee-b337-9faa4c0c8fa9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Providencia stuartii, a urease-positive, indole-positive enteric rod, classically causes which nosocomial infection?', '["Catheter-associated UTI","Typhoid fever","Cholera","Bacillary dysentery","Peptic ulcer"]'::jsonb, 'Catheter-associated UTI', 'P. stuartii thrives in long-term urinary catheters and is a multiply resistant cause of nosocomial UTI.'),
('d7c34404-f852-513a-8c6f-64be10dac181'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement best describes the Vi antigen?', '["A capsular polysaccharide of S. typhi that masks O antigen and resists phagocytosis","A flagellar H-protein accompanied by associated clinical symptoms","A fimbrial adhesin mediated by specific receptor activation","A Shiga-like toxin without affecting the primary tissue pathway","A heat-labile enterotoxin leading to subsequent cellular adaptation"]'::jsonb, 'A capsular polysaccharide of S. typhi that masks O antigen and resists phagocytosis', 'The Vi antigen is a polysaccharide capsule of S. typhi that masks surface O antigen, resists phagocytosis and is the target of carrier-detection serology.'),
('1ccc4e32-7d02-5df8-a0e8-a66b8bb29549'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Shiga toxin injures cells by which mechanism?', '["Cleaving an adenine from 28S rRNA of the 60S ribosomal subunit, blocking protein synthesis","ADP-ribosylating the Gs protein accompanied by associated clinical symptoms","ADP-ribosylating elongation factor-2 mediated by specific receptor activation","Cleaving SNARE proteins without affecting the primary tissue pathway","Blocking GABA receptors leading to subsequent cellular adaptation"]'::jsonb, 'Cleaving an adenine from 28S rRNA of the 60S ribosomal subunit, blocking protein synthesis', 'Shiga toxin is an AB toxin whose A subunit removes an adenine from 28S rRNA of the 60S ribosomal subunit, irreversibly blocking protein synthesis.'),
('12332105-e9d2-5b6b-a159-e768ba1c5f01'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Lipid A of LPS is recognized chiefly by which host receptor to trigger the inflammatory cascade?', '["TLR4","TLR2","TLR5","TLR3","CD28"]'::jsonb, 'TLR4', 'Lipid A is the ligand for TLR4 on macrophages and endothelial cells, initiating the cytokine cascade responsible for endotoxic shock.'),
('3144eb77-a2bc-5627-b392-1f8e0ccfe08c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Blue-green, ''grape-like''-smelling wound discharge indicates infection with:', '["Pseudomonas aeruginosa","Escherichia coli","Klebsiella pneumoniae","Salmonella typhi","Shigella dysenteriae"]'::jsonb, 'Pseudomonas aeruginosa', 'P. aeruginosa produces pyocyanin (blue-green) and a characteristic grape-like odor, distinguishing it among the Gram-negative wound pathogens.'),
('7dcf2d2b-be25-5e1d-854d-6f7753ee9145'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Proteus mirabilis is associated with all EXCEPT:', '["Typhoid fever","Struvite stones","Swarming growth","Urinary tract infection","Urease production"]'::jsonb, 'Typhoid fever', 'Proteus causes UTI, struvite stones and swarming growth via urease; typhoid fever is caused by S. typhi, not Proteus.'),
('599647a0-5dfb-5782-98ef-eed23897c3bd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Vibrio vulnificus is TRUE?', '["It is a halophilic marine vibrio causing septicemia in raw-oyster eaters with liver disease","It is a freshwater non-halophilic organism accompanied by associated clinical symptoms","It causes typhoid fever mediated by specific receptor activation","It causes bacillary dysentery without affecting the primary tissue pathway","It causes peptic ulcer disease leading to subsequent cellular adaptation"]'::jsonb, 'It is a halophilic marine vibrio causing septicemia in raw-oyster eaters with liver disease', 'V. vulnificus is halophilic, requires seawater or shellfish for infection, and causes primary septicemia in patients with cirrhosis or iron overload.'),
('6df18eeb-b742-50aa-96a1-7e95bc879d62'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Escherichia coli is readily recognized on which medium by pink, lactose-fermenting colonies?', '["MacConkey agar","Lowenstein-Jensen medium","TCBS agar","Sabouraud agar","Cetrimide agar"]'::jsonb, 'MacConkey agar', 'E. coli ferments lactose, acidifying MacConkey agar to produce pink colonies, in contrast to pale non-lactose-fermenting enterics.'),
('7ef74c99-06b3-5634-9530-642572191bdc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A Gram-negative rod bearing the Vi capsular antigen, H2S-positive and non-lactose-fermenting, causing enteric fever, is:', '["Salmonella typhi","Pseudomonas aeruginosa","Shigella dysenteriae","Klebsiella pneumoniae","Escherichia coli"]'::jsonb, 'Salmonella typhi', 'S. typhi is non-lactose-fermenting, H2S-positive, motile and bears the Vi capsular polysaccharide; it is the agent of enteric (typhoid) fever.'),
('882ad72e-17da-5a29-9abe-a1d7bbc508f9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The O139 serogroup antigen is carried by which organism?', '["Vibrio cholerae","Salmonella typhi","Shigella dysenteriae","Escherichia coli","Klebsiella pneumoniae"]'::jsonb, 'Vibrio cholerae', 'O139 is aV. cholerae serogroup that, with O1, causes epidemic cholera.'),
('d05227d7-ce3e-5f13-8083-e0d68a598864'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'For chemoprophylaxis of close contacts of a plague case, which oral agent is used?', '["Doxycycline","Penicillin V","Metronidazole","Cefalexin","Colistin"]'::jsonb, 'Doxycycline', 'Oral doxycycline (or a fluoroquinolone) is used for post-exposure prophylaxis of close contacts of Yersinia pestis infection.'),
('cf9b4aac-124a-5a89-8fb3-c5a05d6b5875'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism is a lactose NON-fermenter on MacConkey agar?', '["Salmonella typhi","E. coli","Klebsiella pneumoniae","Enterobacter species","Citrobacter freundii"]'::jsonb, 'Salmonella typhi', 'S. typhi does not ferment lactose and forms pale, colorless colonies on MacConkey agar, unlike the pink colonies of E. coli and Klebsiella.'),
('2bae76c5-1e8d-5de9-bd2c-be15ea71877f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Yersinia pestis is correct?', '["Transmitted by the rat flea, it causes bubonic, septicemic and pneumonic plague","It is mosquito-borne and causes a dengue-like illness accompanied by associated clinical symptoms","It causes typhoid fever mediated by specific receptor activation","It causes cholera without affecting the primary tissue pathway","It causes bacillary dysentery leading to subsequent cellular adaptation"]'::jsonb, 'Transmitted by the rat flea, it causes bubonic, septicemic and pneumonic plague', 'Y. pestis is transmitted by the rat flea and produces bubonic, septicemic and pneumonic plague, the last being transmissible by droplets.'),
('99dc0403-8065-58e9-8259-18cc2f85cace'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Carbapenem-resistant Enterobacteriaceae (CRE) causing hospital outbreaks are most frequently which organisms?', '["Klebsiella pneumoniae and E. coli","Salmonella typhi","Vibrio cholerae","Shigella dysenteriae","Helicobacter pylori"]'::jsonb, 'Klebsiella pneumoniae and E. coli', 'Carbapenemases (KPC, NDM) among Enterobacteriaceae are chiefly carried by K. pneumoniae and E. coli, the major CRE causing nosocomial outbreaks.'),
('531e2c0b-9da9-5bed-9237-a91033887b7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Klebsiella pneumoniae is identified by which combination of features?', '["Non-motile, lactose-fermenting, capsulated with mucoid colonies, urease-positive","Motile, lactose-negative rod accompanied by associated clinical symptoms","Curved, oxidase-positive rod mediated by specific receptor activation","Acid-fast bacillus without affecting the primary tissue pathway","Spore-forming rod leading to subsequent cellular adaptation"]'::jsonb, 'Non-motile, lactose-fermenting, capsulated with mucoid colonies, urease-positive', 'Klebsiella is non-motile, capsulated, lactose-fermenting and usually urease-positive, producing mucoid string-test-positive colonies.'),
('4afef1f5-d31e-5aec-889a-bd2a6319ae6d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A 70-year-old alcoholic with fever, productive cough and upper-lobe lobar consolidation most likely has pneumonia due to:', '["Klebsiella pneumoniae","Salmonella typhi","Shigella dysenteriae","Escherichia coli","Vibrio cholerae"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella classically causes destructive lobar pneumonia with currant-jelly sputum in alcoholics; the upper lobes are often involved.'),
('a5e3a716-237c-5fb8-b65c-c24eccdc6656'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Enteroinvasive E. coli (EIEC), which causes dysentery-like illness, is biochemically and pathogenetically most similar to:', '["Shigella species","Vibrio cholerae","Klebsiella pneumoniae","Pseudomonas aeruginosa","Lactose-positive salmonellae"]'::jsonb, 'Shigella species', 'EIEC is non-motile, non-lactose-fermenting and invades colonic mucosa like Shigella, causing bloody dysentery.'),
('a46f6c5e-b006-5553-a51e-dd8b791bd331'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Escherichia coli is distinguished from Proteus and Shigella by which laboratory feature?', '["Lactose fermentation and subsequent acid production on MacConkey agar","Presence of peritrichous flagella accompanied by associated clinical symptoms","Non-motility mediated by specific receptor activation","Indole negativity without affecting the primary tissue pathway","H2S production leading to subsequent cellular adaptation"]'::jsonb, 'Lactose fermentation and subsequent acid production on MacConkey agar', 'E. coli ferments lactose to acid, giving pink colonies on MacConkey agar; this differentiates it from non-lactose-fermenting Proteus and Shigella.'),
('5dd81cac-6552-5d6d-8763-840dc5ba2787'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The agglutination test based on LPS of Gram-negative bacteria used in the serotyping of enterobacteriaceae is:', '["Agglutination by anti-O (somatic) antisera","Agglutination by sheep RBCs","Agglutination with anti-H flagellar antisera","Precipitin ring test","Complement fixation"]'::jsonb, 'Agglutination by anti-O (somatic) antisera', 'Heat-stable O (somatic LPS) antigens are serotyped by agglutination with anti-O antisera, while heat-labile H flagellar antigens identify the flagellar type.'),
('7d61df92-2b1f-5634-aa19-6824acf3707a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which laboratory feature is characteristic of Pseudomonas aeruginosa?', '["Blue-green pyocyanin production with a grape-like odor","Acid-fast staining accompanied by associated clinical symptoms","Lactose fermentation mediated by specific receptor activation","Spore formation without affecting the primary tissue pathway","Gram-positive staining leading to subsequent cellular adaptation"]'::jsonb, 'Blue-green pyocyanin production with a grape-like odor', 'P. aeruginosa characteristically produces the blue-green pigment pyocyanin, gives colonies a grape-like odor and is oxidase-positive and non-lactose-fermenting.'),
('5fe98bb7-5bf9-58e5-8607-432991d1f72d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A patient with severe, prolonged watery diarrhea and vomiting after eating contaminated food develops hypovolemic shock; stool microscopy shows darting ''shooting star'' rapid motility organisms. The cause is most likely:', '["Vibrio cholerae","Salmonella typhi","Shigella dysenteriae","Klebsiella pneumoniae","Enteropathogenic E. coli"]'::jsonb, 'Vibrio cholerae', 'V. cholerae is the curving, darting, oxidase-positive comma-shaped rod whose cholera toxin causes rice-water diarrhea and massive fluid loss.'),
('de8f6088-bf17-51bc-aa63-ae702fd91149'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The characteristic resemblance of mucoid, hemolytic colonies to an enterococcus on blood agar belongs to:', '["Lecithinase activity","Peritrichous flagella","Metachromatic granules","Grape-like odor and pyocyanin","H2S production"]'::jsonb, 'Grape-like odor and pyocyanin', 'P. aeruginosa colonies are mucoid and hemolytic, resembling enterococci, but pyocyanin pigmentation and the grape-like fruity odor identify them.'),
('b445dfc6-00b2-5612-92ee-d819129d43f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about H antigen is correct?', '["It is a flagellar, heat-labile protein antigen of motile enteric bacilli","It is a heat-stable capsular polysaccharide accompanied by associated clinical symptoms","It is the somatic LPS antigen mediated by specific receptor activation","It is an enzyme without affecting the primary tissue pathway","It is a DNA marker leading to subsequent cellular adaptation"]'::jsonb, 'It is a flagellar, heat-labile protein antigen of motile enteric bacilli', 'The H antigen is the heat-labile, flagellar protein antigen of motile Gram-negative rods, destroyed by boiling and used alongside O and K antigens in serotyping.'),
('1ddc60fc-1ae1-57a6-92fa-93710d740397'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which congenital infection, typified by the O:157 serotype, produces bloody diarrhea, non-bloody diarrhea and HUS, and is a cause of acute renal failure in children?', '["E. coli O157:H7 infection","Cholera","Typhoid fever","Pseudomonas sepsis","Shigella carrier state"]'::jsonb, 'E. coli O157:H7 infection', 'EHEC O157:H7 produces Shiga-like toxins causing bloody diarrhea and hemolytic-uremic syndrome, a leading cause of acute renal failure in children.'),
('b5f0c00b-20eb-514a-a6af-7e352dc99f98'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Swarming growth on culture plate by Proteus is due to:', '["Peritrichous flagella","Capsular antiphagocytic material","Undergoing conjugation","Adhesins","Production of a neurotoxin"]'::jsonb, 'Peritrichous flagella', 'Peritrichous flagella enable Proteus to swarm in wavelike sheets over moist culture media, its classic identifying feature.'),
('e54e6ce6-aded-543f-bd63-2b00484c6df4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism is identified by its non-motility, capsular polysaccharide (string-positive mucoid colonies) and the associated bluish-green metallic sheen on EMB agar?', '["Klebsiella pneumoniae","Escherichia coli","Shigella dysenteriae","Salmonella typhi","Pseudomonas aeruginosa"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella shows mucoid string-positive colonies due to its capsule; a metallic sheen on EMB agar is characteristic of E. coli.'),
('56af9742-9339-5712-97d4-b041d26d3be8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Cholera toxin is composed of which subunit structure, and acts on which target?', '["One A subunit, five B subunits; ADP-ribosylates the Gs protein, raising cAMP in enterocytes","Five A and one B subunit, used only on nerve endings accompanied by associated clinical symptoms","An S and L chain, cleaving rRNA mediated by specific receptor activation","A and B subunits acting on GABA receptors without affecting the primary tissue pathway","A single hydrophobic amphiphilic subunit leading to subsequent cellular adaptation"]'::jsonb, 'One A subunit, five B subunits; ADP-ribosylates the Gs protein, raising cAMP in enterocytes', 'Cholera toxin B pentamers bind GM1 ganglioside; the A1 fragment ribosylates Gs, locks adenylate cyclase ''on'' and massively raises cAMP to cause rice-water diarrhea.'),
('359d2caa-7148-5775-a229-30cf07dc60c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which group of organisms is identifiable by a bell-shaped motion in hanging drop and the associated cell inclusions, now mainly medically relevant through LPS relevant to sepsis?', '["Aeromonas, Klebsiella, Vibrio and Salmonella, all examined by dark-field microscopy","Amazonian amoebae and Entamoeba histolytica accompanied by associated clinical symptoms","Gram-positive cocci colony morphology mediated by specific receptor activation","Yeast in unstained films without affecting the primary tissue pathway","Proteus in spore smears leading to subsequent cellular adaptation"]'::jsonb, 'Aeromonas, Klebsiella, Vibrio and Salmonella, all examined by dark-field microscopy', 'These actively motile Gram-negative rods exhibit darting or bell-shaped (''shooting star'') movement; dark-field or hanging-drop examination reveals intrinsic motility.'),
('b6756710-163f-5a90-b9cf-40ec69a3f927'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which test demonstrates flagellar H antigen by agglutination and is used in the diagnosis, epidemiological typing and carrier detection of typhoid fever?', '["Widal agglutination test","Ziehl-Neelsen stain","Oxidase test","String test","Indole test"]'::jsonb, 'Widal agglutination test', 'The Widal test detects agglutinating anti-O and anti-H antibodies to S. typhi, aiding diagnosis and chronic carrier detection in typhoid fever.'),
('68440f75-eb77-55e1-b22d-5df0b81c8f52'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Escherichial uropathogenic adhesion to uroepithelial cells is helped by:', '["Type-1 fimbriae mannose-sensitive and P fimbriae (papG)","Capsular K1 polysaccharide accompanied by associated clinical symptoms","Beta-lactamase secretion mediated by specific receptor activation","Urease without affecting the primary tissue pathway","Enterotoxin leading to subsequent cellular adaptation"]'::jsonb, 'Type-1 fimbriae mannose-sensitive and P fimbriae (papG)', 'Type-1 fimbriae bind mannose residues while P fimbriae bind Gal-Gal residues of uroepithelial glycolipids; P fimbriae are associated with pyelonephritis.'),
('f0a415e2-15f9-5214-86c6-5d0cd3649361'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Bacillary dysentery can be distinguished from cholera by which feature?', '["Scanty, bloody mucoid stools with abdominal cramps, tenesmus and fever","Profuse rice-water diarrhea with no fever accompanied by associated clinical symptoms","Currant-jelly mucoid stools mediated by specific receptor activation","Foul-smelling fatty stools without affecting the primary tissue pathway","Green watery diarrhea leading to subsequent cellular adaptation"]'::jsonb, 'Scanty, bloody mucoid stools with abdominal cramps, tenesmus and fever', 'Shigella and other invasive colonic pathogens cause scanty bloody mucoid stools with tenesmus and fever, whereas cholera causes profuse afebrile rice-water diarrhea.'),
('6e56261b-0c05-508c-afe8-eaea66b805be'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A normal equilibrium of intestinal flora is maintained by several mechanisms EXCEPT:', '["Intubating the host intestinal microflora enterotoxigenically","Indigenous anaerobic bacteria occupy the host-specific substrates and prevent the growth of others","Peristalsis and the secretion of mucus, IgA and bile","Gastric acid","Expression of the short-chain fatty acids that suppress the growth of competitors"]'::jsonb, 'Intubating the host intestinal microflora enterotoxigenically', 'Commensal anaerobes, peristalsis, gastric acid and secreted mucus/IgA/bile limiting colonization are normal defenses; enterotoxigenic intubation is not.'),
('179f337b-8eeb-5a75-9c1f-738429402ee8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which of the following pathogens is not motile?', '["Shigella dysenteriae","Vibrio cholerae","Salmonella typhi","Proteus mirabilis","Helicobacter pylori"]'::jsonb, 'Shigella dysenteriae', 'Shigella species are uniquely non-motile among enteric invasive rods; Vibrio, Salmonella, Proteus and Helicobacter are all motile.'),
('8176b2ec-3ce2-5128-9153-c67a2fb44786'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which of the following medium pairs correctly identifies P. aeruginosa on Cetrimide agar and E. coli on EMB agar?', '["Blue-green pigmented colonies on Cetrimide agar; green metallic sheen colonies on EMB agar","Tall pink colonies on Cetrimide; mucoid colonies on EMB","No growth on Cetrimide; clear colonies on EMB","Black colonies on Cetrimide; H2S on EMB","Pale yellow colonies on Cetrimide; colorless colonies on EMB"]'::jsonb, 'Blue-green pigmented colonies on Cetrimide agar; green metallic sheen colonies on EMB agar', 'Cetrimide agar is selective for P. aeruginosa (blue-green pyocyanin), while strong lactose fermentation in E. coli confers the green metallic sheen on EMB agar.'),
('0848d654-d375-535f-ad8d-3647de472b17'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Stool culture of a patient with bloodstream typhoid-like infection shows a non-lactose-fermenting, H2S-positive, motile bacillus. The organism is likely:', '["Salmonella enterica subspecies enterica serovar Typhi","E. coli O157:H7 accompanied by associated clinical symptoms","Shigella dysenteriae mediated by specific receptor activation","Klebsiella pneumoniae without affecting the primary tissue pathway","Pseudomonas aeruginosa leading to subsequent cellular adaptation"]'::jsonb, 'Salmonella enterica subspecies enterica serovar Typhi', 'S. Typhi is non-lactose-fermenting, blackens H2S medium and is motile, distinguishing it from non-motile Shigella and lactose-fermenting E. coli.'),
('c470993a-2e35-5402-8801-bf8319ea8ddf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Enterobacteriaceae member is oxidase-NEGATIVE, lactose-fermenting, H2S-negative, and the leading cause of urosepsis and central-line Gram-negative bacteremia?', '["Escherichia coli","Pseudomonas aeruginosa","Salmonella typhi","Vibrio cholerae","Campylobacter jejuni"]'::jsonb, 'Escherichia coli', 'E. coli is an oxidase-negative, lactose-fermenting member of the Enterobacteriaceae and the most common cause of urosepsis and Gram-negative bacteremia.'),
('0fcaef07-808c-551f-9634-c332d084fee3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A hospitalized burn patient develops eethyma gangrenosum with isolation of a blue-green, grape-odored, oxidase-positive bacillus. The most appropriate anti-pseudomonal therapy paired effectively is:', '["Piperacillin-tazobactam with an aminoglycoside or antipseudomonal fluoroquinolone","Penicillin G alone accompanied by associated clinical symptoms","Trimethoprim alone mediated by specific receptor activation","Azithromycin alone without affecting the primary tissue pathway","Vancomycin alone leading to subsequent cellular adaptation"]'::jsonb, 'Piperacillin-tazobactam with an aminoglycoside or antipseudomonal fluoroquinolone', 'Systemic pseudomonal sepsis requires antipseudomonal beta-lactams such as piperacillin-tazobactam combined with an aminoglycoside or a fluoroquinolone because of high intrinsic resistance.'),
('9caeada9-5908-575d-a882-b6b3e2a3b7a0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Typhoid vaccines are of what type?', '["Vi capsular polysaccharide (parenteral), Ty21a live-attenuated oral, and Vi conjugate","Live-attenuated polio vaccine accompanied by associated clinical symptoms","Toxoid vaccine mediated by specific receptor activation","mRNA vaccine without affecting the primary tissue pathway","Whole killed cholera vaccine leading to subsequent cellular adaptation"]'::jsonb, 'Vi capsular polysaccharide (parenteral), Ty21a live-attenuated oral, and Vi conjugate', 'Available typhoid vaccines are the parenteral Vi capsular polysaccharide, the oral live-attenuated Ty21a, and newer Vi-conjugate vaccines.'),
('9c52a5b5-b63f-5997-801c-b8992a82d491'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which antibiotic acts by inhibiting bacterial DNA gyrase and is a key agent against typhoid fever?', '["Ciprofloxacin","Penicillin G","Erythromycin","Metronidazole","Vancomycin"]'::jsonb, 'Ciprofloxacin', 'Fluoroquinolones such as ciprofloxacin inhibit DNA gyrase and, with third-generation cephalosporins, are first-line for typhoid fever.'),
('0ec32b8e-1bd4-5d3a-9219-d2da052b10f5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Yersinia enterocolitica is TRUE?', '["Causes mesenteric adenitis and terminal ileitis mimicking appendicitis, septis arthritis sequelae","Causes typhoid fever accompanied by associated clinical symptoms","Causes cholera mediated by specific receptor activation","Causes bacillary dysentery without affecting the primary tissue pathway","Causes peptic ulcer disease leading to subsequent cellular adaptation"]'::jsonb, 'Causes mesenteric adenitis and terminal ileitis mimicking appendicitis, septis arthritis sequelae', 'Y. enterocolitica of the terminal ileum and mesenteric nodes mimics appendicitis in older children and may be followed by reactive arthritis.'),
('3f47beeb-178e-540c-9dff-582127631e56'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which capsule-antigen-bearing organism resists phagocytosis, masks the O antigen, is associated with chronic biliary carrier state, and is identified by the Vi antigen?', '["Salmonella typhi","Pseudomonas aeruginosa","Klebsiella pneumoniae","Escherichia coli","Shigella dysenteriae"]'::jsonb, 'Salmonella typhi', 'The Vi capsular polysaccharide of S. typhi masks the somatic O antigen, resists complement/phagocytosis and identifies chronic biliary carriers.'),
('5a59151d-b9af-5585-a7a8-b42320e27670'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Enterobacteriaceae species is a prominent ESBL and KPC carbapenemase producer, is non-motile and heavily capsulated, and causes UTIs, pneumonia and nosocomial sepsis?', '["Klebsiella pneumoniae","Pseudomonas aeruginosa","Salmonella typhi","Shigella dysenteriae","Escherichia coli"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella is non-motile, capsulated and a major source of ESBL and KPC carbapenemases causing multidrug-resistant nosocomial UTI, pneumonia and sepsis.'),
('64daa5de-9638-5813-9101-cb0a78176d7a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism, associated with neonatal meningitis (K1), hemolytic-uremic syndrome (O157:H7), and traveler''s diarrhea (ETEC), also ferments lactose and is the archetypal Enterobacteriaceae member?', '["Escherichia coli","Klebsiella pneumoniae","Salmonella typhi","Pseudomonas aeruginosa","Shigella dysenteriae"]'::jsonb, 'Escherichia coli', 'E. coli''s K1 capsule causes neonatal meningitis, EHEC O157:H7 causes HUS, ETEC causes traveler''s diarrhea, and lactose fermentation is archetypal.'),
('54687799-95b1-58bd-93ba-4b1ab5851ad8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about the action of Lipid A is TRUE?', '["It activates macrophages and endothelial cells via TLR4 to release TNF-alpha and IL-1, causing endotoxic shock","It binds to beta-2 adrenergic receptors accompanied by associated clinical symptoms","It blocks protein synthesis directly mediated by specific receptor activation","It is harmless and immunologically silent without affecting the primary tissue pathway","It acts as a neurotoxin leading to subsequent cellular adaptation"]'::jsonb, 'It activates macrophages and endothelial cells via TLR4 to release TNF-alpha and IL-1, causing endotoxic shock', 'Lipid A is recognized by TLR4 and triggers TNF-alpha and IL-1 release from macrophages and endothelium, producing the systemic effects of endotoxic shock.'),
('b5ae0270-ac9f-525e-aba7-d314ae78f5df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which rod is classically implicated in the ''currant-jelly'' sputum of lobar pneumonia in alcoholics?', '["Pseudomonas aeruginosa","Klebsiella pneumoniae","Escherichia coli","Salmonella typhi","Shigella dysenteriae"]'::jsonb, 'Klebsiella pneumoniae', 'Klebsiella causes necrotizing, upper-lobe, often bilateral lobar pneumonia with currant-jelly sputum in alcoholics and diabetics.'),
('104500a2-1df0-5821-ad33-4e3a941ad7c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Proteus mirabilis is TRUE?', '["It produces urease which alkalinizes urine and is associated with struvite stones","It is non-motile accompanied by associated clinical symptoms","It ferments lactose mediated by specific receptor activation","It is oxidase-positive without affecting the primary tissue pathway","It causes cholera leading to subsequent cellular adaptation"]'::jsonb, 'It produces urease which alkalinizes urine and is associated with struvite stones', 'P. mirabilis hydrolyzes urea by urease to ammonia, raising urinary pH and precipitating triple-phosphate (struvite) stones.'),
('25cc7700-f5b3-532f-985f-ba089d3fa6c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which genus, a lactose-fermenting Enterobacteriaceae member with mucoid colonies and non-motility, commonly carries KPC carbapenemase causing hospital outbreaks?', '["Klebsiella","Salmonella","Shigella","Proteus","Vibrio"]'::jsonb, 'Klebsiella', 'Klebsiella pneumoniae x ryopneumoniae, heavily capsulated and non-motile, is a major carrier of KPC carbapenemases driving multidrug-resistant hospital outbreaks.'),
('3386a468-ec46-5cdb-b980-e9c7205da8c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which Gram-negative non-lactose-fermenting, H2S-positive, motile bacillus is responsible for typhoid fever?', '["Salmonella typhi","E. coli","Proteus mirabilis","Pseudomonas aeruginosa","Shigella dysenteriae"]'::jsonb, 'Salmonella typhi', 'S. typhi does not ferment lactose, produces H2S and is motile with peritrichous flagella, typical of the typhoid fever agent.'),
('d5ea2948-494e-558f-9b2f-2be3cf292e73'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Salmonella species in invasive infection is correct?', '["Enteric fever and bacteremia result from invasion of Peyer patches with intracellular survival in macrophages","Salmonella is non-motile and non-invasive accompanied by associated clinical symptoms","Salmonella produces cholera toxin mediated by specific receptor activation","Salmonella is confined to the large intestine without affecting the primary tissue pathway","Salmonella invades the central nervous system exclusively leading to subsequent cellular adaptation"]'::jsonb, 'Enteric fever and bacteremia result from invasion of Peyer patches with intracellular survival in macrophages', 'Salmonella invades the terminal ileal Peyer''s patches, survives within tissue macrophages, and disseminates via the bloodstream to cause enteric fever.'),
('8291463c-f74a-5ba1-a27d-7025788ce3cb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which fat pigment is produced by Pseudomonas?', '["Pyocyanin","Pyoverdin","Pyorubin","Pyomelanin","Pyocyanine and fluorescent pyoverdin"]'::jsonb, 'Pyocyanin', 'Pyocyanin is the characteristic blue-green phenazine pigment of P. aeruginosa; its production and fruity odor identify the organism.'),
('58138418-22f2-5bfd-bce4-25614b79e393'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which antimicrobial mechanism is mediated by the Shiga toxin?', '["Cleaving an adenine from 28S rRNA, blocking protein synthesis","ADP-ribosylating elongation factor 2 accompanied by associated clinical symptoms","Releasing lipases mediated by specific receptor activation","Fusing with host membranes without affecting the primary tissue pathway","Blocking cell wall synthesis leading to subsequent cellular adaptation"]'::jsonb, 'Cleaving an adenine from 28S rRNA, blocking protein synthesis', 'Shiga toxin''sA subunit cleaves an adenine from 28S rRNA of the 60S ribosome, halting protein synthesis and causing cell death.'),
('49c4a2c0-ba20-5781-b75c-b1f0807937d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which of the following is the correct Widal agglutination concept?', '["O antigen is heat-stable (somatic) and H antigen is heat-labile (flagellar), agglutinated in separate tube tests","O and H antigens are both heat-labile accompanied by associated clinical symptoms","H agglutination represents the capsular polysaccharide mediated by specific receptor activation","The Widal test detects cholera toxin without affecting the primary tissue pathway","The Widal test is specific for UTI leading to subsequent cellular adaptation"]'::jsonb, 'O antigen is heat-stable (somatic) and H antigen is heat-labile (flagellar), agglutinated in separate tube tests', 'In the Widal test, heat-stable somatic O and heat-labile flagellar H antibodies are separately detected; rising titers support typhoid fever.'),
('af0666fd-9b74-5892-b313-9ab8b4c3779b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which organism, antigenically O1 or O139, is a non-invasive, oxidase-positive, curved bacillus arranged like a comma?', '["Salmonella typhi","Vibrio cholerae","Klebsiella pneumoniae","Pseudomonas aeruginosa","Escherichia coli"]'::jsonb, 'Vibrio cholerae', 'V. cholerae is a curved, oxidase-positive, darting-motile, comma-shaped rod; O1 and O139 serogroups cause epidemic cholera.'),
('5c3cb1ff-e4b5-59dd-8189-0c4a22b60296'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which microbe may cause a febrile illness with mesenteric adenitis mimicking appendicitis, transmitted by pork or contaminated milk?', '["Yersinia enterocolitica","Salmonella typhi","Vibrio cholerae","Shigella dysenteriae","Campylobacter jejuni"]'::jsonb, 'Yersinia enterocolitica', 'Y. enterocolitica from undercooked pork or contaminated milk causes enterocolitis, mesenteric adenitis and terminal ileitis resembling appendicitis.'),
('a04e7248-2853-5b2d-bfa4-3b978379ecc8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Cholera vaccine is best described as:', '["An oral killed whole-cell or killed whole-cell plus recombinant B subunit vaccine","A parenteral attenuated oral vaccine accompanied by associated clinical symptoms","A live nasal aerosol vaccine mediated by specific receptor activation","A DNA-based vaccine without affecting the primary tissue pathway","A toxoid vaccine with all group protection leading to subsequent cellular adaptation"]'::jsonb, 'An oral killed whole-cell or killed whole-cell plus recombinant B subunit vaccine', 'Modern cholera vaccines are oral killed whole-cell with or without recombinant B subunit, and the live attenuated CVD 103-HgR is also oral.'),
('5afff902-8ec7-589a-baf6-ae2d0d2dc9da'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'What is the main mode of transmission of E. coli O157:H7?', '["Undercooked ground beef","Contaminated water alone","Airborne droplets","Mosquito bites","Sexual contact"]'::jsonb, 'Undercooked ground beef', 'EHEC O157:H7 is transmitted chiefly through undercooked ground (minced) beef, contaminated produce, and food or water contaminated by cattle feces.'),
('7001455b-8298-5332-8d9f-253b4e52cd1e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Moxifloxacin use in typhoid is correct?', '["It is not a first-line agent for typhoid fever","It is the single most effective prokinetic in typhoid","It is given intravenously as a vaccine","It is a macrolide","It acts by blocking ribosomes"]'::jsonb, 'It is not a first-line agent for typhoid fever', 'Moxifloxacin is not first-line for typhoid; ciprofloxacin, ceftriaxone or azithromycin are preferred depending on resistance patterns.'),
('3264003e-fe2f-51bf-85ed-a35d175c49c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Nalidixic acid and Salmonella is true?', '["Nalidixic acid resistance is a surrogate marker of fluoroquinolone-resistant typhoid Salmonella","Nalidixic acid is a beta-lactam","Nalidixic acid is universally bacteriostatic against anaerobes","Nalidixic acid is the causative agent of cholera","Nalidixic acid has no in-vitro effect on Salmonella"]'::jsonb, 'Nalidixic acid resistance is a surrogate marker of fluoroquinolone-resistant typhoid Salmonella', 'Nalidixic acid resistance predicts reduced ciprofloxacin susceptibility in S. typhi, an important determinant of treatment failure in enteric fever.'),
('c2043c1a-a2d4-5f87-b80c-e4ac9b7ad6bd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The S. typhi chromosome carries genes encoding which factors that allow attachment and invasion of intestinal epithelium?', '["Fimbrial adhesins and type III secretion system delivering effector proteins","Cholera toxin B subunit accompanied by associated clinical symptoms","Neurotoxin mediated by specific receptor activation","Superantigen without affecting the primary tissue pathway","Urease leading to subsequent cellular adaptation"]'::jsonb, 'Fimbrial adhesins and type III secretion system delivering effector proteins', 'Salmonella pathogenicity islands encode fimbriae and a type III secretion apparatus that injects effectors to drive uptake into intestinal M-cells of Peyer''s patches.'),
('5846dd32-accd-5e8f-a7a0-80f63335e9ff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Salmonella typhi blood culture is true?', '["Blood cultures are most often positive in the first week of typhoid fever before antibiotics","Blood culture is always negative in typhoid accompanied by associated clinical symptoms","Stool culture is positive in the first week mediated by specific receptor activation","Urine culture is most sensitive in the first week without affecting the primary tissue pathway","Culture is the only way to diagnose carriers leading to subsequent cellular adaptation"]'::jsonb, 'Blood cultures are most often positive in the first week of typhoid fever before antibiotics', 'Bacteremia peaks in the first week of typhoid fever, so blood culture has the highest yield then; stool and urine cultures become positive from the second and third weeks.'),
('401315e0-e3c9-520c-b177-fdfedc885d3a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about typhoid carriers is true?', '["Chronic carriers harbor the organism in the gallbladder and shed it intermittently in stool","Chronic carriers harbor the organism in the prostate","Carriers are usually identified by blood culture","Carriers cannot excrete the bacteria in urine","Carriage is impossible without cholelithiasis"]'::jsonb, 'Chronic carriers harbor the organism in the gallbladder and shed it intermittently in stool', 'Chronic typhoid carriers, often with gallstones, harbor S. typhi in the gallbladder and intermittently excrete it in stool; Vi serology helps identify them.'),
('47290673-ae78-5094-b07b-e384f91cd5de'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about coliform (Enterobacteriaceae) characteristics is correct?', '["E. coli ferments lactose with acid and gas; Citrobacter, Klebsiella and Enterobacter also ferment lactose","All coliforms are non-motile accompanied by associated clinical symptoms","All coliforms are oxidase-positive mediated by specific receptor activation","Coliforms never cause UTI without affecting the primary tissue pathway","Coliforms do not produce gas leading to subsequent cellular adaptation"]'::jsonb, 'E. coli ferments lactose with acid and gas; Citrobacter, Klebsiella and Enterobacter also ferment lactose', 'Coliform, or lactose-fermenter, classification in the Enterobacteriaceae is keyed to rapid lactose fermentation with acid and gas production.'),
('e7ca0064-737d-5b3a-8129-debaa8710e04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The flagellar H antigen and somatic O antigen of S. typhi can be detected by which separate tests?', '["Agglutination with anti-H and anti-O antisera in the Widal test","Acid-fast stain accompanied by associated clinical symptoms","Oxidase test mediated by specific receptor activation","Catalase test without affecting the primary tissue pathway","String test leading to subsequent cellular adaptation"]'::jsonb, 'Agglutination with anti-H and anti-O antisera in the Widal test', 'The Widal test uses separate tube agglutination for anti-H (flagellar) and anti-O (somatic) antibodies, key to typhoid serodiagnosis.'),
('400cd520-8b87-5fcb-b18c-15d12eca4cea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Bacteria of a febrile patient with rose spots, hepatosplenomegaly and relative bradycardia, whose blood culture grew a non-lactose-fermenting rod, are best treated with:', '["Ceftriaxone or a fluoroquinolone","Penicillin G","Metronidazole","Vancomycin","Nitrofurantoin"]'::jsonb, 'Ceftriaxone or a fluoroquinolone', 'Typhoid fever is treated with a third-generation cephalosporin (e.g., ceftriaxone) or a fluoroquinolone where susceptible, or azithromycin.'),
('3b0e51fc-dc37-57fb-afdc-7a271a772d9d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which medium is used for the cultivation of Vibrio cholerae?', '["Thiosulfate-citrate-bile salts-sucrose (TCBS) agar","Lowenstein-Jensen medium accompanied by associated clinical symptoms","Loeffler medium mediated by specific receptor activation","Sabouraud dextrose agar without affecting the primary tissue pathway","Blood agar leading to subsequent cellular adaptation"]'::jsonb, 'Thiosulfate-citrate-bile salts-sucrose (TCBS) agar', 'TCBS is the selective medium for V. cholerae, which appears as large yellow (sucrose-fermenting) colonies.'),
('2a4e4710-5819-5780-bf38-d15321c146a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about Klebsiella pneumoniae is correct?', '["It is non-motile and encapsulated, and its capsule resists phagocytosis","It is motile with peritrichous flagella accompanied by associated clinical symptoms","It is oxidase-positive mediated by specific receptor activation","It is lactose-negative on MacConkey agar without affecting the primary tissue pathway","It produces cholera toxin leading to subsequent cellular adaptation"]'::jsonb, 'It is non-motile and encapsulated, and its capsule resists phagocytosis', 'Klebsiella is non-motile and heavily capsulated; its capsular polysaccharide resists phagocytosis and yields string-positive mucoid colonies.'),
('0c928924-4996-5189-8d3d-3aad3f9d1e52'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'The hallmark characteristic of EHEC is:', '["Production of Shiga-like toxins causing bloody diarrhea and hemolytic-uremic syndrome","Production of cholera toxin accompanied by associated clinical symptoms","Lactose negativity mediated by specific receptor activation","Absence of flagella without affecting the primary tissue pathway","Resistance to polymyxin leading to subsequent cellular adaptation"]'::jsonb, 'Production of Shiga-like toxins causing bloody diarrhea and hemolytic-uremic syndrome', 'EHEC O157:H7 produces Shiga-like (verocyto)toxins that cause bloody diarrhea and hemolytic-uremic syndrome, especially in children.'),
('66aff977-d2ec-5e1e-884c-6d29d143f80b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'A patient with acute cystitis has a urine culture growing a Gram-negative rod that is lactose-positive, oxidase-negative, and gives a positive indole test. The likely organism is:', '["Escherichia coli","Pseudomonas aeruginosa","Klebsiella pneumoniae","Salmonella typhi","Proteus mirabilis"]'::jsonb, 'Escherichia coli', 'Lactose fermentation, oxidase negativity and a positive indole test identify E. coli, the leading cause of acute cystitis.'),
('e5fed21e-4bfb-5d59-9360-dda27c38d023'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which statement about V. cholerae rice-water stool is true?', '["It is a gray, turbid, odorless fluid with mucus flecks full of vibrios","It contains gross blood and pus accompanied by associated clinical symptoms","It is thick and black mediated by specific receptor activation","It is yellow and fatty without affecting the primary tissue pathway","It contains no vibrios leading to subsequent cellular adaptation"]'::jsonb, 'It is a gray, turbid, odorless fluid with mucus flecks full of vibrios', 'The rice-water stool of cholera is a gray turbid odorless fluid containing mucus flecks and enormous numbers of vibrios, reflecting secretory fluid loss.'),
('1c47a6de-7d03-5e30-ab87-939034ed76cb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Gram Negative Enteric', 'Which causative agent is associated with the origin and dissemination of the enteric fever ''rose spot'' lesions?', '["Salmonella typhi","Shigella dysenteriae","Escherichia coli","Pseudomonas aeruginosa","Klebsiella pneumoniae"]'::jsonb, 'Salmonella typhi', 'Rose spots are caused by S. typhi as infected mononuclear cells embolize dermal capillaries early in typhoid fever.'),
('dbef9de2-6d6b-5c98-ab43-0ed510e8244c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella is transmitted:', '["Unpasteurized milk","Direct contact with infected animal tissue","Inhalation of infectious aerosols","Ingestion of raw goat cheese","All of the above"]'::jsonb, 'All of the above', 'Brucella is acquired by ingestion of unpasteurized milk or dairy products, direct contact with infected animal tissues, and inhalation of contaminated aerosols in abattoirs or laboratories; person-to-person spread essentially does not occur.'),
('3220966e-2bec-515a-add1-57a699684f3e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pneumonic plague is best described as:', '["A chronic infection lasting several months","Highly contagious — spread person to person via respiratory droplets","A self-limited illness in healthy adults","Not transmissible between humans","A mild febrile illness requiring no precautions"]'::jsonb, 'Highly contagious — spread person to person via respiratory droplets', 'Pneumonic plague is spread person to person by inhalation of infectious respiratory droplets, unlike bubonic plague which requires a flea bite; it is therefore highly contagious and requires droplet isolation.'),
('6a7f4a80-4f48-54f0-998e-65c23fd4227c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Legionella pneumophila is transmitted:', '["Sexual contact resulting in decreased functional activity","Blood transfusion accompanied by associated clinical symptoms","Person-to-person spread mediated by specific receptor activation","Ingestion of contaminated food without affecting the primary tissue pathway","Inhalation of contaminated water aerosols (air conditioners, showers)"]'::jsonb, 'Inhalation of contaminated water aerosols (air conditioners, showers)', 'Legionella pneumophila is transmitted by inhalation of contaminated water aerosols generated by air conditioners, showers and cooling towers; person-to-person spread does not occur.'),
('0f14bed8-f2fa-53ac-ae8c-1de7c51b36a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which combination of virulence factors is central to the pathogenicity of Yersinia pestis?', '["Protein A resulting in decreased functional activity","Cord factor accompanied by associated clinical symptoms","Exotoxin A mediated by specific receptor activation","M protein without affecting the primary tissue pathway","F1 capsule, V antigen and Yops"]'::jsonb, 'F1 capsule, V antigen and Yops', 'Yersinia pestis expresses the F1 capsular antigen and the V antigen, which resist phagocytosis, and secretes Yop effectors through a type III secretion system to suppress the host immune response.'),
('fc512d9d-719d-5c9d-9023-a6168f115a94'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which growth requirement is characteristic of Francisella tularensis in culture?', '["Routine enteric media","Cysteine-enriched media","Media containing cholesterol","Anaerobic jars without CO2","Media containing bile salts"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and grows only on enriched media supplemented with cysteine, such as cysteine heart agar or enriched chocolate agar; it does not grow on routine enteric agar.'),
('ca97ca8d-142e-5492-86da-b37302da60f0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'A patient develops pneumonic plague after close contact with a bubonic plague case. Which statement best describes pneumonic plague?', '["Highly contagious via droplets","Chronic accompanied by associated clinical symptoms","Self-limited mediated by specific receptor activation","Not transmissible without affecting the primary tissue pathway","Mild leading to subsequent cellular adaptation"]'::jsonb, 'Highly contagious via droplets', 'Pneumonic plague is spread person to person by inhalation of infectious respiratory droplets, unlike bubonic plague which requires a flea bite; it is therefore highly contagious and requires droplet isolation.'),
('96e8f7ac-0c9d-5400-aa75-26a869623811'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which laboratory test is most useful for the diagnosis of pertussis, particularly within the first few weeks of illness?', '["Stool culture","Blood culture","NP swab PCR","Serology","Urine antigen"]'::jsonb, 'NP swab PCR', 'PCR on a nasopharyngeal swab or aspirate is the most sensitive method for diagnosing pertussis, especially within the first 3 weeks of illness, before antibiotics are given and the bacterial load declines.'),
('bfff8c32-2e7b-5647-8c39-6377761b89d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pasteurella multocida is:', '["Spirochete","Acid-fast","Gram-positive rod","Gram-positive coccus","Gram-negative coccobacillus"]'::jsonb, 'Gram-negative coccobacillus', 'Pasteurella multocida is a short gram-negative coccobacillus, often showing bipolar accentuation of staining.'),
('424c9e19-6589-5ea5-90bb-b35f35b1695b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'For how long can Acinetobacter baumannii survive on dry inanimate surfaces?', '["Cannot survive","Days only","Minutes","Weeks to months","Hours"]'::jsonb, 'Weeks to months', 'Acinetobacter baumannii tolerates desiccation and persists for weeks to months on dry inanimate surfaces, a major factor in its nosocomial transmission.'),
('2e4535dd-7fb3-5c51-89ed-d41edd801265'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii is:', '["Gram-positive coccus","Gram-positive rod","Acid-fast","Gram-negative coccobacillus","Spirochete"]'::jsonb, 'Gram-negative coccobacillus', 'Acinetobacter baumannii is a gram-negative coccobacillus that stains poorly and appears as short rods or cocci; it is a leading nosocomial pathogen.'),
('afa88a2c-7140-5176-80ef-9311a75ec1e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which set of virulence determinants is responsible for the pathogenicity of Yersinia pestis?', '["M protein resulting in decreased functional activity","Cord factor accompanied by associated clinical symptoms","Exotoxin A mediated by specific receptor activation","F1 capsule, V antigen and Yops","Protein A leading to subsequent cellular adaptation"]'::jsonb, 'F1 capsule, V antigen and Yops', 'Yersinia pestis uses its F1 capsular antigen and V antigen to resist phagocytosis and a type III secretion system to inject Yop effectors, suppressing the host immune response.'),
('e36ee690-2b87-5b4c-8b06-33db1f44462d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which morphologic description best fits Legionella pneumophila?', '["Acid-fast","Fungus","Spirochete","Gram-positive coccus","Gram-negative rod (fastidious)"]'::jsonb, 'Gram-negative rod (fastidious)', 'Legionella pneumophila is a fastidious gram-negative rod that fails to grow on routine media because it needs L-cysteine and iron; it also stains poorly with the Gram stain.'),
('c3ac9f30-a55c-5392-aa46-986898af2e06'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa is motile by which flagellar arrangement?', '["Peritrichous","Lophotrichous","Monotrichous (polar)","Amphitrichous","None"]'::jsonb, 'Monotrichous (polar)', 'Pseudomonas aeruginosa is motile by means of a single polar flagellum, i.e., monotrichous flagellation, a classic identifying feature.'),
('3942643e-a119-5544-9700-8ab714724932'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which agar is selective for the isolation of Pseudomonas aeruginosa?', '["Blood agar","Cetrimide agar","Chocolate agar","MacConkey agar","LJ medium"]'::jsonb, 'Cetrimide agar', 'Cetrimide agar is selective for Pseudomonas aeruginosa: cetyltrimethylammonium bromide inhibits most other bacteria, while P. aeruginosa grows and often produces blue-green pyocyanin pigment.'),
('b5e7f6c6-4b68-5932-91b3-bd94e88718d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which organism is the aetiologic agent of whooping cough?', '["B. bronchiseptica","B. parapertussis","B. pertussis","H. influenzae","Mycoplasma pneumoniae"]'::jsonb, 'B. pertussis', 'Bordetella pertussis is the etiologic agent of whooping cough, characterized by severe paroxysmal coughing with an inspiratory whoop and post-tussive vomiting in young children.'),
('b0ec09a6-46e0-5400-97d2-d0c96df3c1cc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which clinical feature is the hallmark of bubonic plague?', '["Pneumonia resulting in decreased functional activity","Rash accompanied by associated clinical symptoms","Painful swollen lymph nodes (buboes)","Meningitis without affecting the primary tissue pathway","Hepatitis leading to subsequent cellular adaptation"]'::jsonb, 'Painful swollen lymph nodes (buboes)', 'Bubonic plague is characterized by painful, swollen regional lymph nodes (buboes) that develop after Yersinia pestis is inoculated by a flea bite and drains to the regional nodes.'),
('0569ae85-04ed-510d-892d-91f94ff46e26'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'By what mechanism does pertussis toxin exert its effect on host cells?', '["Blocks cell wall","ADP-ribosylates Gi protein","Cleaves IgA","Activates adenylyl cyclase directly","Inhibits protein synthesis"]'::jsonb, 'ADP-ribosylates Gi protein', 'Pertussis toxin ADP-ribosylates the inhibitory Gi protein, inactivating it; adenylyl cyclase then remains activated, raising intracellular cAMP in the host cell.'),
('be75949d-3778-5988-a62f-53d1b3efd865'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pontiac fever is best described as:', '["Severe pneumonia","Self-limited flu-like illness","Rash","Hemorrhagic fever","Meningitis"]'::jsonb, 'Self-limited flu-like illness', 'Pontiac fever is the non-pneumonic, self-limited, flu-like illness caused by Legionella pneumophila: fever, myalgia and headache that resolve spontaneously within a few days without pneumonia.'),
('896da6eb-38b9-5603-92f0-fb7e2b934af2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which drug is preferred for the treatment of pertussis?', '["Ceftriaxone","Azithromycin","Vancomycin","Metronidazole","Penicillin"]'::jsonb, 'Azithromycin', 'A macrolide such as azithromycin is the preferred treatment for pertussis; it eradicates Bordetella pertussis and can reduce transmission when started in the catarrhal stage.'),
('28102d52-643d-51d2-8ec0-093a2e309b3b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which pigment imparts the blue-green color to cultures of Pseudomonas aeruginosa?', '["Carotenoid","Melanin","Violacein","Pyocyanin (blue-green)","Prodigiosin"]'::jsonb, 'Pyocyanin (blue-green)', 'Pseudomonas aeruginosa produces pyocyanin, a phenazine pigment that gives its colonies and the surrounding medium the characteristic blue-green color.'),
('1f0c9521-3d3a-5db0-876d-543344c5df0d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which agents constitute the treatment of choice for tularemia?', '["Vancomycin","Ceftriaxone","Penicillin","Clindamycin","Streptomycin or gentamicin"]'::jsonb, 'Streptomycin or gentamicin', 'Aminoglycosides such as streptomycin or gentamicin are the treatment of choice for tularemia; penicillins and cephalosporins are not effective against Francisella tularensis.'),
('b2e3e92c-0843-5034-82bd-0d9b1af98ed4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which morphologic form does Pasteurella multocida take?', '["Pleomorphic","Short GN coccobacillus","Long rod","Coccus","Spiral"]'::jsonb, 'Short GN coccobacillus', 'Pasteurella multocida is a short gram-negative coccobacillus, often showing bipolar accentuation of staining.'),
('2ca4d5a5-0a5e-56ef-8a3c-504bc44f858f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Infection with Pasteurella multocida most characteristically follows which exposure?', '["Blood transfusion","Mosquito bite","Dog/cat bites","Ingestion","Inhalation"]'::jsonb, 'Dog/cat bites', 'Pasteurella multocida is a commensal of the oral cavity of dogs and cats; infection follows animal bites or scratches and manifests as rapidly progressive cellulitis and abscess formation.'),
('10d8f0ab-e272-5c92-bdaf-774de51fba47'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'How does Acinetobacter baumannii move?', '["Gliding","Flagellar swimming","Completely non-motile","Corkscrew motion","Twitching (type IV pili)"]'::jsonb, 'Twitching (type IV pili)', 'Acinetobacter baumannii is non-motile by flagella but shows twitching motility mediated by type IV pili, which also contribute to adherence and biofilm formation.'),
('ec98e2bd-15e2-5a56-8fef-be228f978542'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The tracheal cytotoxin of Bordetella pertussis produces which effect?', '["Hypoglycemia","Systemic toxicity","Lymphocytosis","Directly induces bronchitis","Damages ciliated epithelium"]'::jsonb, 'Damages ciliated epithelium', 'Tracheal cytotoxin of Bordetella pertussis destroys the ciliated respiratory epithelial cells, impairing mucus clearance and contributing to the paroxysmal cough of pertussis.'),
('4e2154ae-338e-5fba-a3b6-5e6d1d610b41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which morphologic description best fits Bordetella pertussis?', '["Gram-negative coccobacillus","Gram-positive rod","Gram-positive coccus","Acid-fast","Spirochete"]'::jsonb, 'Gram-negative coccobacillus', 'Bordetella pertussis is a small, encapsulated gram-negative coccobacillus, the characteristic morphology seen on microscopy of respiratory specimens.'),
('6bc3e6f6-2de7-55e6-b0c3-c6f3ce7164c5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'To which group of multidrug-resistant nosocomial pathogens does Acinetobacter baumannii belong?', '["Vibrionaceae","Bacillaceae","HACEK group","Enterobacteriaceae","ESKAPE group"]'::jsonb, 'ESKAPE group', 'Acinetobacter baumannii is one of the ESKAPE pathogens, a group of multidrug-resistant nosocomial bacteria that escape the action of conventional antibiotics.'),
('46237ea5-b749-5301-b32b-7efefde01058'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which staining feature is characteristic of Yersinia pestis?', '["Gram-positive rod resulting in decreased functional activity","GN coccobacillus with bipolar stain","Acid-fast mediated by specific receptor activation","Fungus without affecting the primary tissue pathway","Gram-positive coccus leading to subsequent cellular adaptation"]'::jsonb, 'GN coccobacillus with bipolar stain', 'Yersinia pestis is a gram-negative coccobacillus that characteristically shows bipolar (''safety pin'') accentuation with Giemsa, Wayson or polychrome methylene blue staining.'),
('7cfb4e3e-5005-51d9-a51c-a045b65eeed9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'On Gram staining, Bordetella pertussis appears as a:', '["Spirochete","Acid-fast bacillus","Gram-negative coccobacillus","Gram-positive rod","Gram-positive coccus"]'::jsonb, 'Gram-negative coccobacillus', 'Bordetella pertussis is a small, encapsulated gram-negative coccobacillus, the characteristic morphology seen on microscopy of respiratory specimens.'),
('e6568b09-3d30-50b7-b194-2cbb71d22ca9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which combination of infections is classically associated with Haemophilus influenzae type b in unvaccinated children?', '["Gastroenteritis resulting in decreased functional activity","Wound infection accompanied by associated clinical symptoms","Meningitis, epiglottitis, pneumonia","UTI without affecting the primary tissue pathway","Osteomyelitis leading to subsequent cellular adaptation"]'::jsonb, 'Meningitis, epiglottitis, pneumonia', 'Haemophilus influenzae type b causes invasive disease in unvaccinated children, most importantly meningitis, acute epiglottitis and pneumonia, in addition to septic arthritis and cellulitis.'),
('31f1d3b9-7578-55e5-b348-688bdd4a95fd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pasteurella multocida is sensitive to:', '["Vancomycin","Fusidic acid","Clindamycin","Penicillin","Metronidazole"]'::jsonb, 'Penicillin', 'Pasteurella multocida is highly susceptible to penicillin and amoxicillin, which are the drugs of choice for animal-bite infections caused by this organism.'),
('02d1626a-e5da-55b2-a4a2-a6abe8c3bc12'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa is intrinsically resistant to:', '["Piperacillin","Ciprofloxacin","Meropenem","Penicillin G","Ceftazidime"]'::jsonb, 'Penicillin G', 'Pseudomonas aeruginosa is intrinsically resistant to penicillin G because of limited outer-membrane permeability and inducible beta-lactamase, so penicillin G is inactive against this organism.'),
('44501312-52ff-5037-9f46-1f4c5bf23197'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pontiac fever:', '["Severe pneumonia","Meningitis","Self-limited flu-like illness","Rash","Hemorrhagic fever"]'::jsonb, 'Self-limited flu-like illness', 'Pontiac fever is the non-pneumonic, self-limited, flu-like illness caused by Legionella pneumophila: fever, myalgia and headache that resolve spontaneously within a few days without pneumonia.'),
('6c3519d0-601e-5046-bb7e-c4d2f0c5c6ef'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii commonly causes:', '["UTI","Community meningitis in children","Ventilator-associated pneumonia","Trachoma","Bacteremia in neonates"]'::jsonb, 'Ventilator-associated pneumonia', 'Acinetobacter baumannii is a leading cause of ventilator-associated pneumonia and other nosocomial infections in critically ill patients in the intensive care unit.'),
('e4d57e05-740a-5192-a17b-f9c1014dcce8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The most sensitive laboratory method for diagnosing pertussis in the first few weeks of illness is:', '["Serology","Stool culture","Blood culture","NP swab PCR","Urine antigen"]'::jsonb, 'NP swab PCR', 'PCR on a nasopharyngeal swab or aspirate is the most sensitive method for diagnosing pertussis, especially within the first 3 weeks of illness, before antibiotics are given and the bacterial load declines.'),
('8b243dea-f20a-53d5-a35c-ec9d09d625bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which drug combination is standard first-line therapy for brucellosis?', '["Azithromycin","Vancomycin","Penicillin","Doxycycline + rifampin","Ceftriaxone"]'::jsonb, 'Doxycycline + rifampin', 'Brucellosis is treated with doxycycline combined with rifampin (or an aminoglycoside such as gentamicin) for several weeks; combination therapy prevents the high rate of relapse.'),
('ff3dcfd1-0753-5bb9-978d-430b93f34b7b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis grows on which of the following media?', '["Chocolate resulting in decreased functional activity","BCYE accompanied by associated clinical symptoms","MacConkey and blood agar","Bordet-Gengou without affecting the primary tissue pathway","LJ leading to subsequent cellular adaptation"]'::jsonb, 'MacConkey and blood agar', 'Yersinia pestis is non-fastidious and grows on routine media such as MacConkey agar and blood agar.'),
('347246ad-8efc-50ac-99a1-7f5c06abe9e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa is what type of organism?', '["Gram-positive rod","Spirochete","Acid-fast","Gram-positive coccus","Gram-negative rod"]'::jsonb, 'Gram-negative rod', 'Pseudomonas aeruginosa is a strictly aerobic, oxidase-positive gram-negative rod, consistent with the common cause of ventilator-associated pneumonia in the ICU.'),
('450a2d27-be8a-5866-bd18-76dc6090af82'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae type b causes which constellation of infections?', '["Gastroenteritis resulting in decreased functional activity","UTI accompanied by associated clinical symptoms","Meningitis, epiglottitis, pneumonia","Osteomyelitis alone without affecting the primary tissue pathway","Wound infection leading to subsequent cellular adaptation"]'::jsonb, 'Meningitis, epiglottitis, pneumonia', 'Haemophilus influenzae type b causes invasive disease in unvaccinated children, most importantly meningitis, acute epiglottitis and pneumonia, in addition to septic arthritis and cellulitis.'),
('775cffb2-7da7-5844-a0a8-61d4c655e7e3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii shows which form of motility?', '["Twitching (type IV pili)","Flagellar swimming","Completely non-motile","Gliding","Corkscrew motion"]'::jsonb, 'Twitching (type IV pili)', 'Acinetobacter baumannii is non-motile by flagella but shows twitching motility mediated by type IV pili, which also contribute to adherence and biofilm formation.'),
('93ed24aa-1a87-5b1b-aa19-bd14757938d3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii survives on dry surfaces for:', '["Minutes","Weeks to months","Hours","Days only","Cannot survive"]'::jsonb, 'Weeks to months', 'Acinetobacter baumannii tolerates desiccation and persists for weeks to months on dry inanimate surfaces, a major factor in its nosocomial transmission.'),
('8c04b63c-3a17-52a5-9e1d-c7a3c5ceaafe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which epidemiologic property of Francisella tularensis makes it a dangerous agent?', '["Moderately infectious","Low infectivity","Unknown infectivity","Not infectious","Highly infectious (10 CFU)"]'::jsonb, 'Highly infectious (10 CFU)', 'Francisella tularensis is extremely infectious: as few as 10 organisms (CFU) can cause disease after inhalation or inoculation, which underlies its potential as a bioterror agent.'),
('bf2386cb-bdb6-5623-9158-0075ef269a13'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which components are contained in the acellular pertussis vaccine?', '["Toxoid only","Live bacteria","Inactivated PT, FHA, pertactin","Polysaccharide capsule","Whole killed cells"]'::jsonb, 'Inactivated PT, FHA, pertactin', 'The acellular pertussis vaccine contains inactivated pertussis toxin plus the adhesins filamentous hemagglutinin (FHA), pertactin and fimbriae, providing protection with fewer side effects than whole-cell vaccines.'),
('b5a9f0f7-3ad8-5591-909f-25f7cd03d607'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis is classified by the CDC as:', '["Category B","Category C","Category A bioterrorism agent","Not a bioterror agent","Category D"]'::jsonb, 'Category A bioterrorism agent', 'Francisella tularensis is a CDC Category A bioterrorism agent because of its extremely low infective dose, ease of dissemination and potential for severe, often fatal, disease.'),
('4293dd36-d416-5ea8-83f3-c963a466fa12'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Diagnosis of pertussis is best made early in the illness by:', '["Blood culture","NP swab PCR","Serology","Urine antigen","Stool culture"]'::jsonb, 'NP swab PCR', 'PCR on a nasopharyngeal swab or aspirate is the most sensitive method for diagnosing pertussis, especially within the first 3 weeks of illness, before antibiotics are given and the bacterial load declines.'),
('d3b07b74-144f-5b84-9adc-d7242c719aa1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae type b most characteristically causes which of the following?', '["Bone infection resulting in decreased functional activity","Wound infection accompanied by associated clinical symptoms","UTI mediated by specific receptor activation","Gastroenteritis without affecting the primary tissue pathway","Meningitis, epiglottitis, pneumonia"]'::jsonb, 'Meningitis, epiglottitis, pneumonia', 'Haemophilus influenzae type b causes invasive disease in unvaccinated children, most importantly meningitis, acute epiglottitis and pneumonia, in addition to septic arthritis and cellulitis.'),
('59e67f00-b1f2-5b92-8ab8-dff4c7530b47'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Non-typeable Haemophilus influenzae (NTHi) characteristically causes:', '["Septic arthritis","Epiglottitis","Otitis media and COPD exacerbations","Purpuric rash","Meningitis in older adults"]'::jsonb, 'Otitis media and COPD exacerbations', 'Non-typeable Haemophilus influenzae (NTHi) lacks a capsule and causes mucosal infections such as otitis media, sinusitis and exacerbations of COPD, rather than invasive disease.'),
('6b18e785-5872-556c-b61d-03efd9ad391c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The capsule of Haemophilus influenzae type b is composed of:', '["Teichoic acid","Peptidoglycan","Polyribosylribitol phosphate","Generic capsular polysaccharide","Hyaluronic acid"]'::jsonb, 'Polyribosylribitol phosphate', 'The Haemophilus influenzae type b capsule is composed of the polysaccharide polyribosylribitol phosphate (PRP); anti-PRP antibody is protective and is the target of the conjugate vaccine.'),
('1db29a96-baaf-5ec7-96dd-ac73247f7a98'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis is also called:', '["Pasteurella pestis","Brucella pestis","Y. pseudotuberculosis","Y. enterocolitica","Bacillus pestis"]'::jsonb, 'Pasteurella pestis', 'Yersinia pestis, the cause of plague, was formerly classified in the genus Pasteurella and is still referred to as Pasteurella pestis in older literature.'),
('9627f8fd-c6c4-5a59-9b3d-1f6440419e87'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which animals are the principal reservoir of Brucella melitensis?', '["Pigs","Cattle","Horses","Goats and sheep","Dogs"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('c6af6914-751f-53a3-9ed8-a4e322192efe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucellosis is also known as:', '["Trench fever","Undulant fever / Malta fever","Relapsing fever","Typhoid fever","Q fever"]'::jsonb, 'Undulant fever / Malta fever', 'Brucellosis is also known as undulant fever or Malta fever because of its characteristic undulating, relapsing fever pattern.'),
('70d11e36-3d1b-5884-932e-64586bf2bf1d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Legionella pneumophila is:', '["Gram-positive coccus","Fungus","Acid-fast","Gram-negative rod (fastidious)","Spirochete"]'::jsonb, 'Gram-negative rod (fastidious)', 'Legionella pneumophila is a fastidious gram-negative rod that fails to grow on routine media because it needs L-cysteine and iron; it also stains poorly with the Gram stain.'),
('f6d2ab58-1cf6-5dbd-ba3f-8a35d4b5e5bc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis requires which type of culture medium?', '["Cysteine-enriched media","MacConkey agar","Plain chocolate agar without cysteine","Routine blood agar","LJ medium"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and requires a medium enriched with cysteine for growth, such as cysteine heart agar or chocolate agar supplemented with cysteine.'),
('b0d26780-da8e-5755-8171-5307b48633b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The important virulence factors of Yersinia pestis consist of:', '["F1 capsule, V antigen, Yops","Protein A","M protein","Cord factor","Exotoxin A"]'::jsonb, 'F1 capsule, V antigen, Yops', 'Yersinia pestis expresses the F1 capsular antigen and the V antigen, which resist phagocytosis, and secretes Yop effectors through a type III secretion system to suppress the host immune response.'),
('176b7424-21f2-5ec9-a28b-f85dec18036d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pasteurella multocida appears as which of the following morphologically?', '["Spiral","Long rod","Pleomorphic","Short GN coccobacillus","Coccus"]'::jsonb, 'Short GN coccobacillus', 'Pasteurella multocida is a short gram-negative coccobacillus, often showing bipolar accentuation of staining.'),
('7fddf351-3661-5f52-9858-d5b133154d8c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which clinical presentation is typical of Legionnaires'' disease?', '["Meningitis","Nephritis","Severe atypical pneumonia","Hepatitis","Mild flu-like illness"]'::jsonb, 'Severe atypical pneumonia', 'Legionella pneumophila causes Legionnaires'' disease, a severe atypical pneumonia with high fever, relative bradycardia, and extrapulmonary features such as diarrhea and confusion.'),
('e165aa0c-3dcf-5363-aee6-202dee5d332a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which morphologic form is characteristic of Pasteurella multocida?', '["Coccus","Pleomorphic","Long rod","Spiral","Short GN coccobacillus"]'::jsonb, 'Short GN coccobacillus', 'Pasteurella multocida is a short gram-negative coccobacillus, often showing bipolar accentuation of staining.'),
('80dd8f19-0f13-5e62-bad2-fa621ccf0461'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus ducreyi causes:', '["Chancroid (soft chancre)","LGV","Granuloma inguinale","Primary syphilis","Genital herpes"]'::jsonb, 'Chancroid (soft chancre)', 'Haemophilus ducreyi causes chancroid (soft chancre), a painful genital ulcer with tender inguinal lymphadenopathy, in contrast to the painless ulcer of primary syphilis.'),
('f5c0839b-3639-50f4-9682-3008aa8f725d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Dot/Icm apparatus of Legionella pneumophila is an example of which system?', '["Quorum sensing","Type III secretion","Two-component regulator","Flagellar export","Type IV secretion"]'::jsonb, 'Type IV secretion', 'The Dot/Icm apparatus of Legionella pneumophila is a type IV secretion system that injects effector proteins into host cells to establish the replicative vacuole inside macrophages.'),
('6ba0b8c6-3d26-51e2-81d7-ae410a81bf53'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis causes:', '["Tularemia (rabbit fever)","Glanders","Plague","Brucellosis","Melioidosis"]'::jsonb, 'Tularemia (rabbit fever)', 'Francisella tularensis causes tularemia (rabbit fever), a zoonosis acquired from rabbits and other mammals by handling infected animal tissues, ingestion of contaminated meat or water, or arthropod bites.'),
('1dc88cba-5ebc-5f82-b3c4-e8632db8a95d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'By which nickname is Acinetobacter baumannii also known?', '["Serratia","Klebsiella","Proteus","E. coli","Iraqibacter"]'::jsonb, 'Iraqibacter', 'Acinetobacter baumannii is nicknamed ''Iraqibacter'' because of the high incidence of severe infections, particularly ventilator-associated pneumonia, among soldiers wounded in Iraq.'),
('63c64d98-d43e-5cf6-8a23-d682185c4ef1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which morphologic description fits Haemophilus influenzae?', '["Spirochete","Gram-negative coccobacillus","Acid-fast","Gram-positive coccus","Gram-positive rod"]'::jsonb, 'Gram-negative coccobacillus', 'Haemophilus influenzae is a small gram-negative coccobacillus, a pleomorphic organism that requires X factor (hemin) and V factor (NAD) for growth.'),
('f5349484-1e89-52dd-a31f-3b430311655a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae requires which growth factors?', '["X (hemin) and V (NAD)","Only X","Only V","Cholesterol","None"]'::jsonb, 'X (hemin) and V (NAD)', 'Haemophilus influenzae requires both X factor (hemin) and V factor (NAD) for growth; chocolate agar supplies both, and satellite growth around S. aureus supplies V factor on blood agar.'),
('d46e4b24-cd9d-5968-9eb0-562b03bf2445'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella survives and replicates inside which host cell type?', '["RBCs","Macrophages","T cells","B cells","Neutrophils"]'::jsonb, 'Macrophages', 'Brucella is an intracellular pathogen that survives and replicates within macrophages, where it persists in the reticuloendothelial system and causes relapsing infection.'),
('3b9f3b47-7da8-5df8-89e2-449202543fd8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii is also called:', '["Proteus","Klebsiella","Iraqibacter","E. coli","Serratia"]'::jsonb, 'Iraqibacter', 'Acinetobacter baumannii is nicknamed ''Iraqibacter'' because of the high incidence of severe infections, particularly ventilator-associated pneumonia, among soldiers wounded in Iraq.'),
('7950027a-0c06-502f-b970-cf059fb1d662'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which bacterium requires L-cysteine and iron and is grown on buffered charcoal-yeast extract (BCYE) agar?', '["Legionella","Mycobacterium","Chlamydia","Rickettsia","Fungi"]'::jsonb, 'Legionella', 'Among the listed organisms only Legionella pneumophila is a fastidious intracellular bacterium that requires L-cysteine and iron and is recovered on buffered charcoal-yeast extract (BCYE) agar.'),
('fff4289f-a993-5e4a-8f73-019c9d62dea9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Hib vaccine is best described as:', '["Toxoid","Live attenuated","Whole killed","PRP conjugate vaccine","Recombinant protein"]'::jsonb, 'PRP conjugate vaccine', 'The Hib vaccine is a conjugate vaccine in which the capsular polysaccharide polyribosylribitol phosphate (PRP) is coupled to a carrier protein, making it T-cell-dependent and immunogenic in infants.'),
('6d4b0a98-fe8a-585d-b4b2-bf825eb7762e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa is best isolated on:', '["Blood agar","Chocolate agar","MacConkey agar","LJ medium","Cetrimide agar"]'::jsonb, 'Cetrimide agar', 'Cetrimide agar is the selective medium for Pseudomonas aeruginosa; cetyltrimethylammonium bromide inhibits most other bacteria while the organism grows and produces blue-green pigment.'),
('686506be-0741-5408-a4b7-c1f7f335cfa9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Patients with pertussis are most infectious during which stage?', '["All stages equally","Catarrhal","Paroxysmal","Convalescent","Late paroxysmal"]'::jsonb, 'Catarrhal', 'Patients with pertussis are most infectious during the catarrhal stage, before the paroxysmal coughing phase; macrolide therapy in this stage reduces transmission.'),
('fd6a5a68-af41-54b3-9082-f0e7f825fe73'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Infection with Brucella species is best classified as which type of infection?', '["Anthroponotic","Commensal","Saprophytic","Zoonotic","Plant pathogen"]'::jsonb, 'Zoonotic', 'Brucellosis is a zoonosis, acquired from infected animals or their products (unpasteurized milk, contact with livestock), rather than through person-to-person transmission.'),
('90055709-0e88-5791-8814-73e4674f00a5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which stain best demonstrates Legionella pneumophila in tissue sections?', '["India ink","ZN stain","Gram stain","Giemsa","Dieterle silver stain"]'::jsonb, 'Dieterle silver stain', 'Legionella pneumophila stains very poorly with the Gram stain; in tissue, it is best demonstrated with the Dieterle silver impregnation stain (or Warthin-Starry stain).'),
('42dadf6a-089a-561c-a77f-648a28d10bed'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa is best categorized morphologically as a:', '["Spirochete","Gram-positive coccus","Gram-positive rod","Acid-fast bacillus","Gram-negative rod"]'::jsonb, 'Gram-negative rod', 'Pseudomonas aeruginosa is a strictly aerobic, oxidase-positive gram-negative rod, consistent with the common cause of ventilator-associated pneumonia in the ICU.'),
('227465aa-1902-5dc7-8225-51faabba8bec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which feature contributes most to the designation of Francisella tularensis as a dangerous agent?', '["Not infectious","Unknown infectivity","Moderately infectious","Low infectivity","Highly infectious (10 CFU)"]'::jsonb, 'Highly infectious (10 CFU)', 'Francisella tularensis is highly infectious, with as few as 10 organisms (CFU) able to cause disease after inhalation or inoculation, accounting for its potential as a bioweapon.'),
('2a4fd1f8-1bde-53b1-8ac8-edde71a839c2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis grows on:', '["LJ medium","Chocolate agar","MacConkey and blood agar","Bordet-Gengou agar","BCYE agar"]'::jsonb, 'MacConkey and blood agar', 'Yersinia pestis is non-fastidious and grows on routine media such as MacConkey agar and blood agar.'),
('26a3a32d-62ca-55e2-aa31-bb0c2d623867'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae type b causes:', '["Meningitis, epiglottitis, pneumonia","Gastroenteritis accompanied by associated clinical symptoms","Osteomyelitis alone mediated by specific receptor activation","UTI without affecting the primary tissue pathway","Wound infection leading to subsequent cellular adaptation"]'::jsonb, 'Meningitis, epiglottitis, pneumonia', 'Haemophilus influenzae type b causes invasive disease in unvaccinated children, most importantly meningitis, acute epiglottitis and pneumonia, in addition to septic arthritis and cellulitis.'),
('3eaf94d3-a283-5a70-9e30-d0c61dc6f821'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which nutrients are required for the growth of Legionella pneumophila?', '["Blood","Cholesterol","Glucose","Cysteine and iron","X and V factors"]'::jsonb, 'Cysteine and iron', 'Legionella pneumophila specifically requires L-cysteine and iron salts for growth and is cultured on buffered charcoal-yeast extract (BCYE) agar.'),
('5c388a4d-4923-5345-99dd-99e4cbf6d5b4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella species are:', '["Gram-positive rods","Gram-negative coccobacilli","Gram-positive cocci","Acid-fast","Spirochetes"]'::jsonb, 'Gram-negative coccobacilli', 'Brucella species are small gram-negative coccobacilli that grow slowly and require enriched media with added CO2.'),
('013ec477-bf9f-5053-bef1-28dc9005d0cd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The vector of Yersinia pestis (bubonic plague) is:', '["Sandfly resulting in decreased functional activity","Tick accompanied by associated clinical symptoms","Flea (Xenopsylla cheopis)","Mosquito without affecting the primary tissue pathway","Body louse leading to subsequent cellular adaptation"]'::jsonb, 'Flea (Xenopsylla cheopis)', 'Bubonic plague is transmitted by the oriental rat flea, Xenopsylla cheopis; the flea becomes blocked and regurgitates Yersinia pestis into the bite wound while feeding on the host.'),
('363118d6-b2e5-5fc1-8768-bc9abe9f644c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which set of virulence factors is characteristic of Yersinia pestis?', '["M protein","Cord factor","F1 capsule, V antigen, Yops","Protein A","Exotoxin A"]'::jsonb, 'F1 capsule, V antigen, Yops', 'Yersinia pestis expresses the F1 capsular antigen and V antigen to resist phagocytosis and secretes Yop effectors through a type III secretion system to suppress immunity.'),
('4835d472-1df9-5d1c-ac58-b8c178707094'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa is best described as which type of organism?', '["Gram-positive rod","Gram-negative rod","Gram-positive coccus","Spirochete","Acid-fast"]'::jsonb, 'Gram-negative rod', 'Pseudomonas aeruginosa is a strictly aerobic, oxidase-positive gram-negative rod, consistent with the common cause of ventilator-associated pneumonia in the ICU.'),
('0dd50e58-1d5a-5fc7-968d-9166fcfc942f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Dot/Icm machinery of Legionella pneumophila represents a:', '["Flagellar motor","Two-component regulator","Quorum-sensing circuit","Type III secretion system","Type IV secretion system"]'::jsonb, 'Type IV secretion system', 'The Dot/Icm apparatus of Legionella pneumophila is a type IV secretion system that injects effector proteins into host cells to establish the replicative vacuole inside macrophages.'),
('fb5026fd-4673-5cc7-8f37-9e422d280838'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pneumonic plague is characterized by:', '["Chronic illness","Mild symptoms","Self-limited course","Highly contagious spread via respiratory droplets","Absence of person-to-person transmission"]'::jsonb, 'Highly contagious spread via respiratory droplets', 'Pneumonic plague is spread person to person by inhalation of infectious respiratory droplets, unlike bubonic plague which requires a flea bite; it is therefore highly contagious and requires droplet isolation.'),
('f5dc3413-961f-5a26-917c-9573c0be1134'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Carbapenem resistance in Acinetobacter baumannii is most often mediated by which mechanism?', '["KPC resulting in decreased functional activity","IMP accompanied by associated clinical symptoms","NDM-1 mediated by specific receptor activation","VIM without affecting the primary tissue pathway","OXA-type carbapenemases"]'::jsonb, 'OXA-type carbapenemases', 'Carbapenem resistance in Acinetobacter baumannii is mediated largely by acquired OXA-type (class D) beta-lactamases, including OXA-23, OXA-24/40, OXA-51 and OXA-58.'),
('08b43e98-64e3-5d8a-9950-60d363dabf92'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which medium is used for the culture of Bordetella pertussis?', '["Chocolate agar","Bordet-Gengou agar","Blood agar","MacConkey agar","LJ medium"]'::jsonb, 'Bordet-Gengou agar', 'Bordetella pertussis is cultured on Bordet-Gengou (potato glycerol blood) agar or the more sensitive Regan-Lowe medium; growth is slow, over several days.'),
('6c7257ab-3a33-5052-8c8c-8d44742dfb5c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which combination of findings characterizes ulceroglandular tularemia?', '["Rash","Hepatitis","Meningitis only","Skin ulcer + lymphadenopathy","Pneumonia only"]'::jsonb, 'Skin ulcer + lymphadenopathy', 'Ulceroglandular tularemia, the most common form, begins with a painful skin ulcer at the inoculation site accompanied by regional lymphadenopathy.'),
('cbc806e2-333d-5c9c-9e6d-1ef486c4b704'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which constellation of infections is classically caused by Haemophilus influenzae type b?', '["Wound infection resulting in decreased functional activity","Gastroenteritis accompanied by associated clinical symptoms","Meningitis, epiglottitis, pneumonia","Osteomyelitis alone without affecting the primary tissue pathway","UTI leading to subsequent cellular adaptation"]'::jsonb, 'Meningitis, epiglottitis, pneumonia', 'Haemophilus influenzae type b causes invasive disease in unvaccinated children, most importantly meningitis, acute epiglottitis and pneumonia, in addition to septic arthritis and cellulitis.'),
('fafe1c46-ecf0-59df-b268-579cc667e61a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Whooping cough is caused by:', '["B. parapertussis","H. influenzae","B. pertussis","B. bronchiseptica","Mycoplasma pneumoniae"]'::jsonb, 'B. pertussis', 'Bordetella pertussis is the etiologic agent of whooping cough, which presents with paroxysmal coughing, an inspiratory whoop and post-tussive vomiting in young children.'),
('4983f64a-8ae0-5b2e-9ba4-bd56fd3e5151'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The diagnosis of pertussis in the first weeks of illness is best confirmed by:', '["Serology","Blood culture","NP swab PCR","Urine antigen","Stool culture"]'::jsonb, 'NP swab PCR', 'PCR on a nasopharyngeal swab or aspirate is the most sensitive method for diagnosing pertussis, especially within the first 3 weeks of illness, before antibiotics are given and the bacterial load declines.'),
('eface94c-bbfb-5de9-b5de-c0b455a2f5a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'On which medium does Haemophilus influenzae grow?', '["LJ medium","MacConkey agar","Chocolate agar","Blood agar","Sabouraud agar"]'::jsonb, 'Chocolate agar', 'Haemophilus influenzae grows on chocolate agar, where heat-lysed red cells provide both X factor (hemin) and V factor (NAD); it does not grow on plain blood agar.'),
('234bbee6-6eae-5d2e-9144-083a28de8e72'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella melitensis is transmitted to humans mainly from which animal hosts?', '["Horses","Goats and sheep","Cattle","Dogs","Pigs"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('737e1cfc-4153-5b6f-ac34-84203fd832b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The oxidase test result of Pseudomonas aeruginosa is:', '["Positive","Negative","Variable","Not tested","Unknown"]'::jsonb, 'Positive', 'Pseudomonas aeruginosa is oxidase positive, an important biochemical feature that distinguishes it from the oxidase-negative members of the Enterobacteriaceae.'),
('ef816448-9616-56ee-b073-fc0517ee1e85'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The acronym CRAB denotes:', '["Carbapenem-resistant Acinetobacter baumannii","Ceftriaxone-resistant Acinetobacter baumannii","Carbapenem-resistant Enterobacteriaceae","Colistin-resistant Acinetobacter baumannii","Community-acquired Acinetobacter pneumonia"]'::jsonb, 'Carbapenem-resistant Acinetobacter baumannii', 'CRAB is the standard acronym for carbapenem-resistant Acinetobacter baumannii, a leading multidrug-resistant pathogen causing ventilator-associated pneumonia in ICUs.'),
('a53cb139-36fb-5c3b-bc7f-492e073b5676'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Legionella pneumophila is best classified as a(n):', '["Surface commensal","Strictly extracellular organism","Obligate anaerobe","Environmental saprophyte only","Intracellular pathogen"]'::jsonb, 'Intracellular pathogen', 'Legionella pneumophila is a facultative intracellular pathogen that replicates within alveolar macrophages (and within amoebae in water), evading killing by phagocytes.'),
('dafdc6e8-a0e8-5c33-be75-15a95b994e72'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which pigment is responsible for the blue-green discoloration of Pseudomonas aeruginosa cultures?', '["Prodigiosin","Violacein","Pyocyanin (blue-green)","Melanin","Carotenoid"]'::jsonb, 'Pyocyanin (blue-green)', 'Pseudomonas aeruginosa produces pyocyanin, a phenazine pigment that gives its colonies and the surrounding medium the characteristic blue-green color.'),
('dcd65793-7713-5e69-bb98-787b6ddb6994'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae is:', '["Acid-fast","Gram-positive coccus","Gram-negative coccobacillus","Spirochete","Gram-positive rod"]'::jsonb, 'Gram-negative coccobacillus', 'Haemophilus influenzae is a small gram-negative coccobacillus, a pleomorphic organism that requires X factor (hemin) and V factor (NAD) for growth.'),
('7a03f131-ae44-5473-8902-be1860f33179'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Quorum sensing in Pseudomonas aeruginosa is mediated by which systems?', '["Com system","Two-component regulator only","LasI/LasR and RhlI/RhlR","LuxS system","Agr system"]'::jsonb, 'LasI/LasR and RhlI/RhlR', 'Pseudomonas aeruginosa uses the acyl-homoserine-lactone quorum-sensing systems LasI/LasR and RhlI/RhlR to coordinate biofilm formation and expression of virulence factors.'),
('b66f0468-ced8-507e-831b-c81cf7addf5e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The acellular pertussis vaccine contains:', '["Polysaccharide","Toxoid only","Live organisms","Whole killed cells","Inactivated PT, FHA, pertactin"]'::jsonb, 'Inactivated PT, FHA, pertactin', 'The acellular pertussis vaccine contains inactivated pertussis toxin plus the adhesins filamentous hemagglutinin (FHA), pertactin and fimbriae, providing protection with fewer side effects than whole-cell vaccines.'),
('dd8b6da7-c270-57f6-bd33-4b2705397502'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Wayson staining of Yersinia pestis characteristically shows:', '["Gram-positive reaction","Beaded appearance","Bipolar staining","Acid-fast","Uniform staining"]'::jsonb, 'Bipolar staining', 'Yersinia pestis shows a bipolar (''safety pin'') pattern of staining with Giemsa, Wayson or polychrome methylene blue, a rapid aid to suspecting plague.'),
('70a6072c-1381-58c3-ae7d-17423d9f2749'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pertussis toxin acts on host cells by:', '["Blocks cell wall","Activates adenylyl cyclase directly","ADP-ribosylates Gi protein","Cleaves IgA","Inhibits protein synthesis"]'::jsonb, 'ADP-ribosylates Gi protein', 'Pertussis toxin ADP-ribosylates the inhibitory Gi protein, inactivating it; adenylyl cyclase then remains activated, raising intracellular cAMP in the host cell.'),
('aff38866-9a12-5cd3-bc9b-05afcff3e38c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis requires which growth medium?', '["LJ medium","MacConkey agar","Plain chocolate agar without cysteine","Cysteine-enriched media","Routine blood agar"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and requires a medium enriched with cysteine for growth, such as cysteine heart agar or chocolate agar supplemented with cysteine.'),
('c4dd42ad-81ca-5c39-a09e-407f4b413e95'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The main action of the tracheal cytotoxin of Bordetella pertussis is:', '["Lymphocytosis","Damages ciliated epithelium","Hypoglycemia","Systemic toxicity","Bronchospasm alone"]'::jsonb, 'Damages ciliated epithelium', 'Tracheal cytotoxin of Bordetella pertussis destroys the ciliated respiratory epithelial cells, impairing mucus clearance and contributing to the paroxysmal cough of pertussis.'),
('de038521-4ee0-5209-963f-3a8994d32515'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Culture medium used for Bordetella pertussis includes:', '["Bordet-Gengou agar","Chocolate agar","LJ medium","MacConkey agar","Routine blood agar"]'::jsonb, 'Bordet-Gengou agar', 'Bordetella pertussis is cultured on Bordet-Gengou (potato glycerol blood) agar or the more sensitive Regan-Lowe medium; growth is slow, over several days.'),
('3fe975c2-fc83-5ec3-92a2-975e41921dfd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'B. melitensis is the Brucella species found in:', '["Pigs","Horses","Cattle","Goats and sheep","Dogs"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('9be556d9-a721-5b0e-adf2-c8340fbab4a0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The principal reservoir of Brucella melitensis is:', '["Cattle","Goats and sheep","Horses","Pigs","Dogs"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('75132b66-c0d5-537f-98fd-47e7627c7b1d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'A rapidly progressive cellulitis that develops within hours of an animal bite suggests which route of acquisition?', '["Blood transfusion","Mosquito bite","Dog/cat bites","Ingestion","Inhalation"]'::jsonb, 'Dog/cat bites', 'Pasteurella multocida is a commensal of the oral cavity of dogs and cats; infection follows animal bites or scratches and manifests as rapidly progressive cellulitis and abscess formation.'),
('1bc9fb60-e17e-5827-be25-bf921fa8dc4d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Microscopy of a smear of Bordetella pertussis shows which morphology?', '["Gram-positive rod","Gram-negative coccobacillus","Gram-positive coccus","Acid-fast","Spirochete"]'::jsonb, 'Gram-negative coccobacillus', 'Bordetella pertussis is a small, encapsulated gram-negative coccobacillus, the characteristic morphology seen on microscopy of respiratory specimens.'),
('f412b38c-0615-5a60-a972-8ed6c16461b1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis is the cause of:', '["Brucellosis","Tularemia (rabbit fever)","Melioidosis","Plague","Glanders"]'::jsonb, 'Tularemia (rabbit fever)', 'Francisella tularensis causes tularemia (rabbit fever), a zoonosis acquired from rabbits and other mammals by handling infected animal tissues, ingestion of contaminated meat or water, or arthropod bites.'),
('7f872e96-7336-5c22-8c1c-26bab5a7e0a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which combination of virulence determinants is unique to Yersinia pestis among the listed pathogens?', '["Protein A","Cord factor","Exotoxin A","M protein","F1 capsule, V antigen, Yops"]'::jsonb, 'F1 capsule, V antigen, Yops', 'Yersinia pestis expresses the F1 capsular antigen and V antigen, which resist phagocytosis, and secretes Yop effectors through a type III secretion system to suppress the host immune response.'),
('01197cd5-16f7-53eb-b5a1-e059f630b474'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The oculoglandular form of tularemia consists of:', '["Skin ulcer resulting in decreased functional activity","Hepatitis accompanied by associated clinical symptoms","Meningitis mediated by specific receptor activation","Conjunctival infection + preauricular LN","Pneumonia leading to subsequent cellular adaptation"]'::jsonb, 'Conjunctival infection + preauricular LN', 'Oculoglandular tularemia follows inoculation of the conjunctiva and consists of a purulent conjunctivitis together with ipsilateral preauricular lymphadenopathy.'),
('da9d367b-dd75-5f58-ab52-a2418a824e7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which medium supports the growth of Bordetella pertussis?', '["MacConkey agar","Routine blood agar","Bordet-Gengou agar","LJ medium","Chocolate agar"]'::jsonb, 'Bordet-Gengou agar', 'Bordetella pertussis is cultured on Bordet-Gengou (potato glycerol blood) agar or the more sensitive Regan-Lowe medium; growth is slow, over several days.'),
('9a43dd3d-4f29-5d57-8a3f-ac7a3e276214'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis is best described as a:', '["Gram-positive rod resulting in decreased functional activity","Fungus accompanied by associated clinical symptoms","Gram-positive coccus mediated by specific receptor activation","GN coccobacillus with bipolar stain","Acid-fast leading to subsequent cellular adaptation"]'::jsonb, 'GN coccobacillus with bipolar stain', 'Yersinia pestis is a gram-negative coccobacillus that characteristically shows bipolar (''safety pin'') accentuation with Giemsa, Wayson or polychrome methylene blue staining.'),
('e4490702-465a-51b9-986f-a7d88b67c15d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Dot/Icm apparatus of Legionella pneumophila is an example of a:', '["Type III secretion system","Quorum-sensing circuit","Flagellar export machinery","Two-component regulator","Type IV secretion system"]'::jsonb, 'Type IV secretion system', 'The Dot/Icm apparatus of Legionella pneumophila is a type IV secretion system that injects effector proteins into host cells to establish the replicative vacuole inside macrophages.'),
('63149839-355e-526b-ab11-49c3701bc063'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis is notable for being:', '["Of low infectivity","Moderately infectious","Not infectious","Of unknown infectivity","Highly infectious (10 CFU)"]'::jsonb, 'Highly infectious (10 CFU)', 'Francisella tularensis is extremely infectious: as few as 10 organisms (CFU) can cause disease after inhalation or inoculation, which underlies its potential as a bioterror agent.'),
('a8b81262-d5fb-5359-b732-5c6531e92596'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The recommended treatment of brucellosis is:', '["Azithromycin","Penicillin","Vancomycin","Doxycycline + rifampin","Ceftriaxone"]'::jsonb, 'Doxycycline + rifampin', 'Brucellosis is treated with doxycycline combined with rifampin (or an aminoglycoside such as gentamicin) for several weeks; combination therapy prevents the high rate of relapse.'),
('5ab88345-8e47-5104-b3d1-4a00be9e623b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Protection against Haemophilus influenzae type b is provided by which type of vaccine?', '["PRP conjugate vaccine","Recombinant protein vaccine","Toxoid vaccine","Live attenuated vaccine","Whole killed vaccine"]'::jsonb, 'PRP conjugate vaccine', 'The Hib vaccine is a conjugate vaccine in which the capsular polysaccharide polyribosylribitol phosphate (PRP) is coupled to a carrier protein, making it T-cell-dependent and immunogenic in infants.'),
('97321a26-b8c4-5303-9165-2d4881e292be'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii characteristically shows resistance to:', '["Macrolides only","Carbapenems (CRAB)","Penicillin only","Clindamycin only","Fusidic acid only"]'::jsonb, 'Carbapenems (CRAB)', 'Carbapenem-resistant Acinetobacter baumannii (CRAB) is a leading multidrug-resistant nosocomial pathogen, with carbapenem resistance mediated chiefly by OXA-type beta-lactamases.'),
('4f784c89-726d-5fbe-a134-05f3476a3c40'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Ulceroglandular tularemia is characterized by:', '["Meningitis only","Hepatitis","Pneumonia only","Rash","Skin ulcer + lymphadenopathy"]'::jsonb, 'Skin ulcer + lymphadenopathy', 'Ulceroglandular tularemia, the most common form, begins with a painful skin ulcer at the inoculation site accompanied by regional lymphadenopathy.'),
('86ca1bfc-bfa4-5a67-888a-b01fbbde9540'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which formulation is used in the acellular pertussis vaccine?', '["Whole cells","Polysaccharide","Toxoid only","Live organisms","Inactivated PT, FHA, pertactin"]'::jsonb, 'Inactivated PT, FHA, pertactin', 'The acellular pertussis vaccine contains inactivated pertussis toxin plus the adhesins filamentous hemagglutinin (FHA), pertactin and fimbriae, providing protection with fewer side effects than whole-cell vaccines.'),
('fe5431b0-2de2-5432-8e27-09ffd152eba5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which fastidious gram-negative rod is a common cause of atypical pneumonia?', '["Fungus","Gram-positive coccus","Gram-negative rod (fastidious)","Spirochete","Acid-fast"]'::jsonb, 'Gram-negative rod (fastidious)', 'Legionella pneumophila is a fastidious gram-negative rod that fails to grow on routine media because it needs L-cysteine and iron; it also stains poorly with the Gram stain.'),
('bb16b1dc-afe8-5a31-b467-e4b353e7c28b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The oculoglandular form of Francisella tularensis infection manifests as:', '["Hepatitis resulting in decreased functional activity","Conjunctival infection + preauricular LN","Skin ulcer mediated by specific receptor activation","Pneumonia without affecting the primary tissue pathway","Meningitis leading to subsequent cellular adaptation"]'::jsonb, 'Conjunctival infection + preauricular LN', 'Oculoglandular tularemia follows inoculation of the conjunctiva and consists of a purulent conjunctivitis together with ipsilateral preauricular lymphadenopathy.'),
('a35428ff-ad92-5079-9a9e-cd02b3c395de'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae is cultured on which agar?', '["LJ medium","Sabouraud agar","Chocolate agar","MacConkey agar","Blood agar"]'::jsonb, 'Chocolate agar', 'Haemophilus influenzae grows on chocolate agar, where heat-lysed red cells provide both X factor (hemin) and V factor (NAD); it does not grow on plain blood agar.'),
('3c09078a-3d4f-59ad-b8a3-4c4c6c05228d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which statement best describes pneumonic plague?', '["Self-limited resulting in decreased functional activity","Chronic accompanied by associated clinical symptoms","Mild mediated by specific receptor activation","Highly contagious via droplets","Not transmissible leading to subsequent cellular adaptation"]'::jsonb, 'Highly contagious via droplets', 'Pneumonic plague is spread person to person by inhalation of infectious respiratory droplets, unlike bubonic plague which requires a flea bite; it is therefore highly contagious and requires droplet isolation.'),
('d9d873e4-2ae2-5731-b8d5-a6a39c2e7ff7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Legionella pneumophila is transmitted to humans chiefly by which route?', '["Person-to-person","Blood transfusion","Water aerosols (AC, showers)","Sexual contact","Ingestion"]'::jsonb, 'Water aerosols (AC, showers)', 'Legionella pneumophila is transmitted by inhalation of contaminated water aerosols generated by air conditioners, showers and cooling towers; person-to-person spread does not occur.'),
('7fe3cb93-4a04-5e95-af0d-715c66d1e10e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Non-typeable Haemophilus influenzae (NTHi) most typically causes:', '["Otitis media and COPD exacerbations","Septic arthritis","Epiglottitis","Purpuric rash","Meningitis in infants"]'::jsonb, 'Otitis media and COPD exacerbations', 'Non-typeable Haemophilus influenzae (NTHi) lacks a capsule and causes mucosal infections such as otitis media, sinusitis and exacerbations of COPD, rather than invasive disease.'),
('b798c05e-b147-52b9-a487-5b874babb510'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis grows in culture only on:', '["Cysteine-enriched media","Fastidious media without supplements","Routine enteric media","Variable media","Media with bile salts"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and grows only on enriched media supplemented with cysteine (e.g., cysteine heart or enriched chocolate agar); it does not grow on routine enteric agar.'),
('c95dc203-58d9-53cb-8d15-cd4c76fa275f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Rapidly progressive cellulitis with abscess formation within 12-24 hours of a dog bite is most characteristic of:', '["Pasteurella multocida infection after animal bites","Erysipelothrix rhusiopathiae","Capnocytophaga canimorsus","Staphylococcus aureus","Streptococcus pyogenes"]'::jsonb, 'Pasteurella multocida infection after animal bites', 'Pasteurella multocida is a commensal of the oral cavity of dogs and cats; infection follows animal bites or scratches and manifests as rapidly progressive cellulitis and abscess formation.'),
('d9b60587-3ea4-5cf8-827d-6a81a86d8009'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella melitensis is characteristically found in:', '["Cattle","Horses","Pigs","Goats and sheep","Dogs"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('5a2bb2dc-5673-535d-be7e-3d5f7852cac1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii moves by:', '["Flagella","Swimming","Gliding","Completely non-motile","Twitching (type IV pili)"]'::jsonb, 'Twitching (type IV pili)', 'Acinetobacter baumannii is non-motile by flagella but shows twitching motility mediated by type IV pili, which also contribute to adherence and biofilm formation.'),
('a73b2da0-3f91-5952-938b-9084094b81ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which regimen is recommended for the treatment of brucellosis?', '["Doxycycline + rifampin","Azithromycin","Ceftriaxone","Vancomycin","Penicillin"]'::jsonb, 'Doxycycline + rifampin', 'Brucellosis is treated with doxycycline combined with rifampin (or an aminoglycoside such as gentamicin) for several weeks; combination therapy prevents the high rate of relapse.'),
('8d43efcc-53ac-5d95-9027-bba52bc4646c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which zoonotic disease is caused by Francisella tularensis?', '["Brucellosis","Glanders","Plague","Melioidosis","Tularemia (rabbit fever)"]'::jsonb, 'Tularemia (rabbit fever)', 'Francisella tularensis causes tularemia (rabbit fever), a zoonosis acquired from rabbits and other mammals by handling infected animal tissues, ingestion of contaminated meat or water, or arthropod bites.'),
('e7bf287b-eb21-5b8d-a07a-c4b28433a845'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Legionnaires'' disease is best described as:', '["Hepatitis","Severe atypical pneumonia","Meningitis","Mild flu-like illness","Nephritis"]'::jsonb, 'Severe atypical pneumonia', 'Legionella pneumophila causes Legionnaires'' disease, a severe atypical pneumonia with high fever, relative bradycardia, and extrapulmonary features such as diarrhea and confusion.'),
('9ce0414d-a432-55d9-892c-3b9ba4950b4b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which infections are classically caused by non-typeable Haemophilus influenzae?', '["Purpuric rash","Otitis media and COPD exacerbations","Septic arthritis","Epiglottitis","Meningitis in infants"]'::jsonb, 'Otitis media and COPD exacerbations', 'Non-typeable Haemophilus influenzae (NTHi) lacks a capsule and causes mucosal infections such as otitis media, sinusitis and exacerbations of COPD, rather than invasive disease.'),
('47e9a159-8917-5be5-baf4-5451e4f7d27e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Contaminated water from which source is the principal vehicle of Legionella pneumophila infection?', '["Sexual contact","Blood products","Water aerosols (AC, showers)","Person-to-person contact","Food ingestion"]'::jsonb, 'Water aerosols (AC, showers)', 'Legionella pneumophila is transmitted by inhalation of contaminated water aerosols generated by air conditioners, showers and cooling towers; person-to-person spread does not occur.'),
('db17408d-ad12-590a-a8af-43caddfbcffb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'On which media does Yersinia pestis grow?', '["Bordet-Gengou agar","Chocolate agar","MacConkey and blood agar","LJ medium","BCYE agar"]'::jsonb, 'MacConkey and blood agar', 'Yersinia pestis is non-fastidious and grows on routine media such as MacConkey agar and blood agar.'),
('d884a3e4-7c2f-5c07-b564-1bf15cb187ef'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Hib vaccine is a:', '["Whole killed vaccine","Live attenuated vaccine","Toxoid vaccine","Recombinant vaccine","PRP conjugate vaccine"]'::jsonb, 'PRP conjugate vaccine', 'The Hib vaccine is a conjugate vaccine in which the capsular polysaccharide polyribosylribitol phosphate (PRP) is coupled to a carrier protein, making it T-cell-dependent and immunogenic in infants.'),
('f36da1f6-3c20-5c26-9629-fb2ce6f77595'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which antibiotic is intrinsically inactive against Pseudomonas aeruginosa?', '["Piperacillin","Ceftazidime","Penicillin G","Ciprofloxacin","Meropenem"]'::jsonb, 'Penicillin G', 'Pseudomonas aeruginosa is intrinsically resistant to penicillin G because of limited outer-membrane permeability and inducible beta-lactamase, so penicillin G is inactive against this organism.'),
('a636195a-4bc1-5d8e-8023-6fe7b9b5f5b6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The best stain for demonstrating Legionella pneumophila in tissue is:', '["India ink","Gram stain","Giemsa","Dieterle silver stain","ZN stain"]'::jsonb, 'Dieterle silver stain', 'Legionella pneumophila stains very poorly with the Gram stain; in tissue, it is best demonstrated with the Dieterle silver impregnation stain (or Warthin-Starry stain).'),
('6e82f83f-b029-578b-9835-9979eb0476aa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The drugs of choice for the treatment of tularemia are:', '["Penicillin","Streptomycin or gentamicin","Clindamycin","Vancomycin","Ceftriaxone"]'::jsonb, 'Streptomycin or gentamicin', 'Aminoglycosides (streptomycin or gentamicin) are the treatment of choice for tularemia; penicillins and cephalosporins are not effective against Francisella tularensis.'),
('e466fb8f-37d4-5faa-9567-84fcb5025e7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Legionella pneumophila is transmitted via:', '["Blood","Person-to-person contact","Sexual contact","Ingestion","Water aerosols (AC, showers)"]'::jsonb, 'Water aerosols (AC, showers)', 'Legionella pneumophila is transmitted by inhalation of contaminated water aerosols generated by air conditioners, showers and cooling towers; person-to-person spread does not occur.'),
('173dbf06-7788-5e15-9021-940610dc06d5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which of the following is true of pneumonic plague?', '["Self-limited resulting in decreased functional activity","Mild accompanied by associated clinical symptoms","Chronic mediated by specific receptor activation","Not transmissible without affecting the primary tissue pathway","Highly contagious via droplets"]'::jsonb, 'Highly contagious via droplets', 'Pneumonic plague is spread person to person by inhalation of infectious respiratory droplets, unlike bubonic plague which requires a flea bite; it is therefore highly contagious and requires droplet isolation.'),
('4a811420-37d4-5ec2-bda6-d2afe5577f1e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii is grouped among which set of pathogens?', '["ESKAPE group","Enterobacteriaceae","HACEK group","Bacillaceae","Vibrionaceae"]'::jsonb, 'ESKAPE group', 'Acinetobacter baumannii is one of the ESKAPE pathogens, a group of multidrug-resistant nosocomial bacteria that escape the action of conventional antibiotics.'),
('366192b2-7196-5bdb-b25a-191e3785fb76'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The virulence of Yersinia pestis depends primarily on:', '["Protein A","Cord factor","F1 capsule, V antigen, Yops","M protein","Exotoxin A"]'::jsonb, 'F1 capsule, V antigen, Yops', 'Yersinia pestis expresses the F1 capsular antigen and V antigen to resist phagocytosis and secretes Yop effectors through a type III secretion system to suppress the host immune response.'),
('cab12345-9b28-5229-b236-6e90dd53e8d1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii survives on inanimate dry surfaces for:', '["Minutes","Hours","Days only","Cannot survive","Weeks to months"]'::jsonb, 'Weeks to months', 'Acinetobacter baumannii tolerates desiccation and persists for weeks to months on dry inanimate surfaces, a major factor in its nosocomial transmission.'),
('947bc093-d879-5674-ab7e-ddee9f7e6436'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'For growth, Legionella pneumophila requires:', '["X and V factors","Glucose","Cysteine and iron","Blood","Cholesterol"]'::jsonb, 'Cysteine and iron', 'Legionella pneumophila specifically requires L-cysteine and iron salts for growth and is cultured on buffered charcoal-yeast extract (BCYE) agar.'),
('05b7ed53-fc06-5aa3-acb1-1ce4e5c57266'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The satelliting phenomenon refers to:', '["Pseudomonas growing around a staphylococcal streak","S. aureus inhibiting neighboring H. influenzae","E. coli satelliting around Proteus","A zone of hemolysis around S. aureus","H. influenzae growing as satellite colonies around S. aureus on blood agar"]'::jsonb, 'H. influenzae growing as satellite colonies around S. aureus on blood agar', 'On blood agar, Haemophilus influenzae grows as satellite colonies around Staphylococcus aureus, which releases the V factor (NAD) that H. influenzae cannot synthesize.'),
('bc9d4427-098a-5ee4-af2d-c6ce39e13813'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Tularemia that presents with conjunctivitis and preauricular lymphadenopathy is the:', '["Conjunctival infection + preauricular LN","Ulceroglandular form with rash","Pneumonic form","Glandular form of hepatitis","Meningitic form"]'::jsonb, 'Conjunctival infection + preauricular LN', 'Oculoglandular tularemia follows inoculation of the conjunctiva and consists of a purulent conjunctivitis together with ipsilateral preauricular lymphadenopathy.'),
('ef411733-2bbc-54d1-b6f6-944e43f9295e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Bordetella pertussis appears on Gram staining as:', '["Gram-negative coccobacillus","Gram-positive coccus","Spirochete","Gram-positive rod","Acid-fast"]'::jsonb, 'Gram-negative coccobacillus', 'Bordetella pertussis is a small, encapsulated gram-negative coccobacillus, the characteristic morphology seen on microscopy of respiratory specimens.'),
('9df19fe2-031e-5a22-96d2-b4de3ad776cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The capsule of Haemophilus influenzae type b is:', '["Peptidoglycan","Polyribosylribitol phosphate","Teichoic acid","Hyaluronic acid","A generic capsular polysaccharide"]'::jsonb, 'Polyribosylribitol phosphate', 'The Haemophilus influenzae type b capsule is composed of the polysaccharide polyribosylribitol phosphate (PRP); anti-PRP antibody is protective and is the target of the conjugate vaccine.'),
('849484d9-7e54-5d84-a01e-d3e0d49c7147'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa is intrinsically resistant to which antibiotic?', '["Piperacillin","Ciprofloxacin","Meropenem","Penicillin G","Ceftazidime"]'::jsonb, 'Penicillin G', 'Pseudomonas aeruginosa is intrinsically resistant to penicillin G because of limited outer-membrane permeability and inducible beta-lactamase, so penicillin G is inactive against this organism.'),
('a350fca5-b3dc-5c65-b8af-75a769356265'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The most infectious stage of pertussis is the:', '["All stages equally","Paroxysmal stage","Convalescent stage","Catarrhal stage","Late paroxysmal stage"]'::jsonb, 'Catarrhal stage', 'Patients with pertussis are most infectious during the catarrhal stage, before the paroxysmal coughing phase; macrolide therapy in this stage reduces transmission.'),
('8791f3ca-9fea-55f3-a78a-1c9f9bf7bf30'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella species are morphologically:', '["Spirochetes","Gram-positive cocci","Gram-positive rods","Acid-fast","Gram-negative coccobacilli"]'::jsonb, 'Gram-negative coccobacilli', 'Brucella species are small gram-negative coccobacilli that grow slowly and require enriched media with added CO2.'),
('57ddc04e-d556-5fb1-aac7-76d9d4ffcc07'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis is also known as:', '["Y. enterocolitica","Bacillus pestis","Pasteurella pestis","Y. pseudotuberculosis","Brucella pestis"]'::jsonb, 'Pasteurella pestis', 'Yersinia pestis, the cause of plague, was formerly classified in the genus Pasteurella and is still referred to as Pasteurella pestis in older literature.'),
('a5caab75-fae6-5b18-b3ff-6ca498369da4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pasteurella multocida is a normal part of:', '["Soil resulting in decreased functional activity","Feline and canine oral flora","Contaminated food mediated by specific receptor activation","Human skin without affecting the primary tissue pathway","Water leading to subsequent cellular adaptation"]'::jsonb, 'Feline and canine oral flora', 'Pasteurella multocida is part of the normal oropharyngeal flora of cats and dogs; bites and scratches from these animals introduce the organisms into soft tissue.'),
('324c4a22-e16b-50ba-b5cd-b1d99c5fe1af'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pasteurella multocida is morphologically:', '["Long rod","Short GN coccobacillus","Pleomorphic","Spiral","Coccus"]'::jsonb, 'Short GN coccobacillus', 'Pasteurella multocida is a short gram-negative coccobacillus, often showing bipolar accentuation of staining.'),
('726e453b-bb01-51ba-b66c-3f7567acbdce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which nutritional requirements are characteristic of Legionella pneumophila?', '["Glucose","X and V factors","Cysteine and iron","Cholesterol","Blood"]'::jsonb, 'Cysteine and iron', 'Legionella pneumophila specifically requires L-cysteine and iron salts for growth and is cultured on buffered charcoal-yeast extract (BCYE) agar.'),
('779356b9-4cc6-51c1-909e-796ed38a0e24'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which illness is the mild, self-limited form of Legionella pneumophila infection?', '["Rash","Severe pneumonia","Hemorrhagic fever","Self-limited flu-like illness","Meningitis"]'::jsonb, 'Self-limited flu-like illness', 'Pontiac fever is the non-pneumonic, self-limited, flu-like illness caused by Legionella pneumophila: fever, myalgia and headache that resolve spontaneously within a few days without pneumonia.'),
('3a81eba9-3823-5295-9c81-7d919ab63c85'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which organism causes whooping cough?', '["Mycoplasma pneumoniae","B. bronchiseptica","B. pertussis","B. parapertussis","H. influenzae"]'::jsonb, 'B. pertussis', 'Bordetella pertussis is the etiologic agent of whooping cough, which presents with paroxysmal coughing, an inspiratory whoop and post-tussive vomiting in young children.'),
('cbe6b811-1f43-5f1e-ae2c-742284b5849b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa gives which result in the oxidase test?', '["Positive","Variable","Negative","Not tested","Unknown"]'::jsonb, 'Positive', 'Pseudomonas aeruginosa is oxidase positive, an important biochemical feature that distinguishes it from the oxidase-negative members of the Enterobacteriaceae.'),
('009262ed-bd4a-5b3a-bdca-d948e141d7da'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The bacterium that requires buffered charcoal-yeast extract agar for growth is best described as:', '["Spirochete","Gram-positive coccus","Fungus","Acid-fast","Gram-negative rod (fastidious)"]'::jsonb, 'Gram-negative rod (fastidious)', 'Legionella pneumophila is a fastidious gram-negative rod that fails to grow on routine media because it needs L-cysteine and iron; it also stains poorly with the Gram stain.'),
('f0ed714a-89c7-5baf-af4e-84f1e85acb20'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The tracheal cytotoxin of Bordetella pertussis acts principally on which structure?', '["Systemic circulation","Ciliated respiratory epithelium","Pancreatic beta cells","Peripheral nerves","Renal tubules"]'::jsonb, 'Ciliated respiratory epithelium', 'Tracheal cytotoxin of Bordetella pertussis destroys the ciliated respiratory epithelial cells, impairing mucus clearance and contributing to the paroxysmal cough of pertussis.'),
('c9f37392-52a5-502a-8f56-f0d31187da77'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus ducreyi is the cause of which genital infection?', '["LGV","Primary syphilis","Genital herpes","Chancroid (soft chancre)","Granuloma inguinale"]'::jsonb, 'Chancroid (soft chancre)', 'Haemophilus ducreyi causes chancroid (soft chancre), a painful genital ulcer with tender inguinal lymphadenopathy, in contrast to the painless ulcer of primary syphilis.'),
('b10fa8f3-0cc8-5bd9-a3a7-49a94ce5be8a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which pigment does Pseudomonas aeruginosa produce?', '["Melanin","Prodigiosin","Carotenoid","Violacein","Pyocyanin (blue-green)"]'::jsonb, 'Pyocyanin (blue-green)', 'Pseudomonas aeruginosa produces pyocyanin, a phenazine pigment that gives its colonies and the surrounding medium the characteristic blue-green color.'),
('9852cba0-bba0-599d-bd57-d5f5a4d2ac17'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which antibiotic combination is used to treat brucellosis?', '["Azithromycin","Vancomycin","Penicillin","Ceftriaxone","Doxycycline + rifampin"]'::jsonb, 'Doxycycline + rifampin', 'Brucellosis is treated with doxycycline combined with rifampin (or an aminoglycoside such as gentamicin) for several weeks; combination therapy prevents the high rate of relapse.'),
('f0f19f85-195e-50ed-bf37-5d5de4d4298b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which group of diseases is caused by Haemophilus influenzae type b?', '["Gastroenteritis resulting in decreased functional activity","Osteomyelitis alone accompanied by associated clinical symptoms","Meningitis, epiglottitis, pneumonia","UTI without affecting the primary tissue pathway","Wound infection leading to subsequent cellular adaptation"]'::jsonb, 'Meningitis, epiglottitis, pneumonia', 'Haemophilus influenzae type b causes invasive disease in unvaccinated children, most importantly meningitis, acute epiglottitis and pneumonia, in addition to septic arthritis and cellulitis.'),
('bdb5f1ce-bbce-5434-a5ea-8c1a6b5e934c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii frequently exhibits resistance to:', '["Penicillin only","Fusidic acid only","Macrolides only","Clindamycin only","Carbapenems (CRAB)"]'::jsonb, 'Carbapenems (CRAB)', 'Carbapenem-resistant Acinetobacter baumannii (CRAB) is a leading multidrug-resistant nosocomial pathogen, with carbapenem resistance mediated chiefly by OXA-type beta-lactamases.'),
('afa45095-a564-5d21-844b-35a43a9bb40e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis is classified by the CDC as which type of agent?', '["Unknown","Category A bioterrorism agent","Not a bioterror agent","Category C","Category B"]'::jsonb, 'Category A bioterrorism agent', 'Francisella tularensis is a CDC Category A bioterrorism agent because of its extremely low infective dose, ease of dissemination and potential for severe, often fatal, disease.'),
('420ea8f1-3094-52dc-9d4d-7ed261c55060'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which is the correct classification of Pseudomonas aeruginosa?', '["Acid-fast","Gram-negative rod","Spirochete","Gram-positive rod","Gram-positive coccus"]'::jsonb, 'Gram-negative rod', 'Pseudomonas aeruginosa is a strictly aerobic, oxidase-positive gram-negative rod, consistent with the common cause of ventilator-associated pneumonia in the ICU.'),
('a5b6f244-51df-59fd-8d83-859f5faab717'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The modern acellular vaccine against pertussis contains:', '["Whole cells","Polysaccharide","Inactivated PT, FHA, pertactin","Toxoid only","Live organisms"]'::jsonb, 'Inactivated PT, FHA, pertactin', 'The acellular pertussis vaccine contains inactivated pertussis toxin plus the adhesins filamentous hemagglutinin (FHA), pertactin and fimbriae, providing protection with fewer side effects than whole-cell vaccines.'),
('9ba4f412-5ba2-555a-a8be-0399a9cbbe39'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis is the cause of which disease?', '["Brucellosis resulting in decreased functional activity","Melioidosis accompanied by associated clinical symptoms","Tularemia mediated by specific receptor activation","Glanders without affecting the primary tissue pathway","Plague (bubonic/pneumonic/septicemic)"]'::jsonb, 'Plague (bubonic/pneumonic/septicemic)', 'Yersinia pestis causes plague, which occurs as bubonic, septicemic or pneumonic forms depending on whether the bacteria are introduced by a flea bite, into blood, or by inhalation.'),
('79c9cb5c-1104-57ac-9c0d-955bee052182'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella melitensis is found in:', '["Goats and sheep","Dogs","Pigs","Cattle","Horses"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('011b6e87-22b6-5ad7-99f1-a045977d81bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which pigment diffuses into the agar and imparts a blue-green colour to cultures of Pseudomonas aeruginosa?', '["Carotenoid","Violacein","Pyocyanin (blue-green)","Prodigiosin","Melanin"]'::jsonb, 'Pyocyanin (blue-green)', 'Pseudomonas aeruginosa produces pyocyanin, a phenazine pigment that gives its colonies and the surrounding medium the characteristic blue-green color.'),
('34165ca5-4167-55f5-ae5d-d661e72ffc06'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pertussis toxin damages host cells by which mechanism?', '["Blocks cell wall","Activates adenylyl cyclase directly","Cleaves IgA","Inhibits protein synthesis","ADP-ribosylates Gi protein"]'::jsonb, 'ADP-ribosylates Gi protein', 'Pertussis toxin ADP-ribosylates the inhibitory Gi protein, inactivating it; adenylyl cyclase then remains activated, raising intracellular cAMP in the host cell.'),
('1f971cbf-ec72-526a-8531-b03f6b054366'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii is resistant to which class of drugs?', '["Clindamycin only","Macrolides only","Carbapenems (CRAB)","Penicillin only","Fusidic acid only"]'::jsonb, 'Carbapenems (CRAB)', 'Carbapenem-resistant Acinetobacter baumannii (CRAB) is a leading multidrug-resistant nosocomial pathogen, with carbapenem resistance mediated chiefly by OXA-type beta-lactamases.'),
('3307419e-1f28-5067-970d-8865e994c036'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The tracheal cytotoxin of Bordetella pertussis:', '["Damages ciliated epithelium","Causes systemic toxicity","Causes hypoglycemia","Directly induces bronchospasm","Causes lymphocytosis"]'::jsonb, 'Damages ciliated epithelium', 'Tracheal cytotoxin of Bordetella pertussis destroys the ciliated respiratory epithelial cells, impairing mucus clearance and contributing to the paroxysmal cough of pertussis.'),
('302fe01c-1597-5d4c-96de-cc81d91f075f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis causes:', '["Melioidosis resulting in decreased functional activity","Plague (bubonic/pneumonic/septicemic)","Tularemia mediated by specific receptor activation","Brucellosis without affecting the primary tissue pathway","Glanders leading to subsequent cellular adaptation"]'::jsonb, 'Plague (bubonic/pneumonic/septicemic)', 'Yersinia pestis causes plague, which occurs as bubonic, septicemic or pneumonic forms depending on whether the bacteria are introduced by a flea bite, into blood, or by inhalation.'),
('af8da17f-aeac-5ae3-be29-ab4a713e2666'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which flagellar arrangement is found in Pseudomonas aeruginosa?', '["Peritrichous","Monotrichous (polar)","Lophotrichous","None","Amphitrichous"]'::jsonb, 'Monotrichous (polar)', 'Pseudomonas aeruginosa is motile by means of a single polar flagellum, i.e., monotrichous flagellation, a classic identifying feature.'),
('e12577de-683f-586b-b371-9f50f342790e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella species are oxidase:', '["Variable","Unknown","Not tested","Positive","Negative"]'::jsonb, 'Positive', 'Brucella species are oxidase positive, a biochemical feature shared with several other gram-negative coccobacilli encountered in the laboratory.'),
('25973cf6-8bbe-5bd5-9648-3b231eb0e1e6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The disease caused by Yersinia pestis is:', '["Melioidosis resulting in decreased functional activity","Plague (bubonic/pneumonic/septicemic)","Tularemia mediated by specific receptor activation","Brucellosis without affecting the primary tissue pathway","Glanders leading to subsequent cellular adaptation"]'::jsonb, 'Plague (bubonic/pneumonic/septicemic)', 'Yersinia pestis causes plague, which occurs as bubonic, septicemic or pneumonic forms depending on whether the bacteria are introduced by a flea bite, into blood, or by inhalation.'),
('d5fcb332-a188-5232-b808-95ffb955604d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa has what flagellar arrangement?', '["Peritrichous","Amphitrichous","None","Monotrichous (polar)","Lophotrichous"]'::jsonb, 'Monotrichous (polar)', 'Pseudomonas aeruginosa is motile by means of a single polar flagellum, i.e., monotrichous flagellation, a classic identifying feature.'),
('ffbdb4ff-8c1c-5852-8727-9116beb1daa5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which morphology best describes Brucella species?', '["Acid-fast","Gram-negative coccobacilli","Gram-positive cocci","Gram-positive rods","Spirochetes"]'::jsonb, 'Gram-negative coccobacilli', 'Brucella species are small gram-negative coccobacilli that grow slowly and require enriched media with added CO2.'),
('11e19fb6-d016-5d62-8dbd-223c0bebecde'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which antibiotic is preferred for infection following a cat bite that is caused by Pasteurella multocida?', '["Vancomycin","Amoxicillin-clavulanate","Clindamycin","Metronidazole","Azithromycin"]'::jsonb, 'Amoxicillin-clavulanate', 'Pasteurella multocida is highly penicillin-susceptible; for animal-bite infections, amoxicillin-clavulanate is preferred because it also covers the mixed oral flora of the wound.'),
('143b42ad-36f6-505b-a627-5faaff529ed2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pasteurella multocida treatment of choice is:', '["Amoxicillin-clavulanate","Clindamycin","Metronidazole","Vancomycin","Azithromycin"]'::jsonb, 'Amoxicillin-clavulanate', 'Pasteurella multocida is highly penicillin-susceptible; for animal-bite infections, amoxicillin-clavulanate is preferred because it also covers the mixed oral flora of the wound.'),
('be626251-f1e0-5521-86da-4d9572ff0c9f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The agent that causes whooping cough is best described morphologically as:', '["Gram-positive rod","Gram-negative coccobacillus","Gram-positive coccus","Spirochete","Acid-fast"]'::jsonb, 'Gram-negative coccobacillus', 'Bordetella pertussis is a small, encapsulated gram-negative coccobacillus, the characteristic morphology seen on microscopy of respiratory specimens.'),
('0074b9e6-c511-53be-9c2f-f3ba4ba80cf3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Dot/Icm apparatus of Legionella pneumophila is a:', '["Flagellar export system","Type IV secretion system","Quorum-sensing circuit","Two-component regulator","Type III secretion system"]'::jsonb, 'Type IV secretion system', 'The Dot/Icm apparatus of Legionella pneumophila is a type IV secretion system that injects effector proteins into host cells to establish the replicative vacuole inside macrophages.'),
('18271183-ad62-57cc-88e7-b4fa6963daf5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella abortus is characteristically found in:', '["Sheep","Dogs","Pigs","Goats","Cattle"]'::jsonb, 'Cattle', 'Brucella abortus is chiefly associated with cattle, whereas B. melitensis (goats and sheep), B. suis (pigs) and B. canis (dogs) predominate in their respective reservoirs.'),
('6f4e5596-d013-5480-885b-9f0fc88d734f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The treatment of choice for Legionnaires'' disease is:', '["Vancomycin","Cephalosporins","Metronidazole","Azithromycin or levofloxacin","Penicillin"]'::jsonb, 'Azithromycin or levofloxacin', 'Legionnaires'' disease is treated with a macrolide (azithromycin) or a respiratory fluoroquinolone (levofloxacin); beta-lactams are ineffective because the organism survives intracellularly.'),
('6824d17b-072d-59b3-ad65-2eb767700f50'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which finding constitutes the classic feature of bubonic plague?', '["Hepatitis resulting in decreased functional activity","Rash accompanied by associated clinical symptoms","Pneumonia mediated by specific receptor activation","Painful swollen lymph nodes (buboes)","Meningitis leading to subsequent cellular adaptation"]'::jsonb, 'Painful swollen lymph nodes (buboes)', 'Bubonic plague is characterized by painful, swollen regional lymph nodes (buboes) that develop after Yersinia pestis is inoculated by a flea bite and drains to the regional nodes.'),
('ede87e85-ce13-5642-9594-17e394f51934'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which agent is often the only remaining option for extensively drug-resistant (XDR) Acinetobacter baumannii?', '["Colistin (polymyxin E)","Ciprofloxacin","Ceftriaxone","Gentamicin","Vancomycin"]'::jsonb, 'Colistin (polymyxin E)', 'For extensively drug-resistant (XDR) Acinetobacter baumannii, colistin (polymyxin E) is often the only active agent available, despite the risk of nephrotoxicity.'),
('2a855e04-edc5-5e3c-a261-17cd4141194a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella species are best categorized as which type of pathogen?', '["Anthroponotic","Plant pathogen","Saprophytic","Zoonotic","Commensal"]'::jsonb, 'Zoonotic', 'Brucellosis is a zoonosis, acquired from infected animals or their products (unpasteurized milk, contact with livestock), rather than through person-to-person transmission.'),
('9feabb10-b615-5fb5-b413-e2dfb16cd9ca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which result does Pseudomonas aeruginosa give on the oxidase test?', '["Not tested","Positive","Variable","Negative","Unknown"]'::jsonb, 'Positive', 'Pseudomonas aeruginosa is oxidase positive, an important biochemical feature that distinguishes it from the oxidase-negative members of the Enterobacteriaceae.'),
('1f1c670e-3e98-5bc6-ac9a-337a611147ad'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'For the culture of pertussis, which medium is used?', '["Bordet-Gengou agar","Chocolate agar","LJ medium","Routine blood agar","MacConkey agar"]'::jsonb, 'Bordet-Gengou agar', 'Bordetella pertussis is cultured on Bordet-Gengou (potato glycerol blood) agar or the more sensitive Regan-Lowe medium; growth is slow, over several days.'),
('18149761-582e-5a29-97a5-3b81978d3b5f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which animal exposure typically precedes infection with Pasteurella multocida?', '["Inhalation","Blood transfusion","Dog/cat bites","Ingestion","Mosquito bite"]'::jsonb, 'Dog/cat bites', 'Pasteurella multocida is a commensal of the oral cavity of dogs and cats; infection follows animal bites or scratches and manifests as rapidly progressive cellulitis and abscess formation.'),
('f6eff142-e4cd-59af-9abe-c9bd0e702150'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella abortus is characteristically associated with:', '["Cattle","Goats","Sheep","Pigs","Dogs"]'::jsonb, 'Cattle', 'Brucella abortus is chiefly associated with cattle, whereas B. melitensis (goats and sheep), B. suis (pigs) and B. canis (dogs) predominate in their respective reservoirs.'),
('86a77def-96dc-5baf-a282-77b96f6c14bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The acellular pertussis vaccine consists of:', '["Polysaccharide","Toxoid only","Inactivated PT, FHA, pertactin","Whole killed cells","Live organisms"]'::jsonb, 'Inactivated PT, FHA, pertactin', 'The acellular pertussis vaccine contains inactivated pertussis toxin plus the adhesins filamentous hemagglutinin (FHA), pertactin and fimbriae, providing protection with fewer side effects than whole-cell vaccines.'),
('0d7e78c8-bace-5f6a-9893-576a69f77ba0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Biofilm formation and coordinated expression of virulence factors in Pseudomonas aeruginosa are regulated by which quorum-sensing systems?', '["Com system","LasI/LasR and RhlI/RhlR","LuxS system","Agr system","Two-component regulator only"]'::jsonb, 'LasI/LasR and RhlI/RhlR', 'Pseudomonas aeruginosa uses the acyl-homoserine-lactone quorum-sensing systems LasI/LasR and RhlI/RhlR to coordinate biofilm formation and expression of virulence factors.'),
('326c3683-5949-50d7-832d-9351f6198f01'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The stage of pertussis associated with the greatest contagion is:', '["Prodromal","All stages equally","Catarrhal","Paroxysmal","Convalescent"]'::jsonb, 'Catarrhal', 'Patients with pertussis are most infectious during the catarrhal stage, before the paroxysmal coughing phase; macrolide therapy in this stage reduces transmission.'),
('156b9ee5-ab90-50d7-9f6a-fc1b69b99366'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae type b classically causes:', '["Gastroenteritis resulting in decreased functional activity","Meningitis, epiglottitis, pneumonia","Osteomyelitis alone mediated by specific receptor activation","UTI without affecting the primary tissue pathway","Wound infection leading to subsequent cellular adaptation"]'::jsonb, 'Meningitis, epiglottitis, pneumonia', 'Haemophilus influenzae type b causes invasive disease in unvaccinated children, most importantly meningitis, acute epiglottitis and pneumonia, in addition to septic arthritis and cellulitis.'),
('a2eb43a3-638c-5730-b4d2-962ece356f6b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which epidemiologic label is correct for brucellosis?', '["Zoonotic","Plant pathogen","Saprophytic","Anthroponotic","Commensal"]'::jsonb, 'Zoonotic', 'Brucellosis is a zoonosis, acquired from infected animals or their products (unpasteurized milk, contact with livestock), rather than through person-to-person transmission.'),
('11de9066-81de-5462-a477-fdf6f35fbe34'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii persists on dry surfaces for how long?', '["Hours","Cannot survive","Weeks to months","Days only","Minutes"]'::jsonb, 'Weeks to months', 'Acinetobacter baumannii tolerates desiccation and persists for weeks to months on dry inanimate surfaces, a major factor in its nosocomial transmission.'),
('37eb8ed6-4945-5390-8417-8e2558a056f7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which infection is most commonly caused by Acinetobacter baumannii in the intensive care unit?', '["Ventilator-associated pneumonia","Surgical site infection","Meningitis in children","UTI","Neonatal conjunctivitis"]'::jsonb, 'Ventilator-associated pneumonia', 'Acinetobacter baumannii is a leading cause of ventilator-associated pneumonia and other nosocomial infections in critically ill patients in the intensive care unit.'),
('7504b869-484a-5752-9349-dd5191cc2555'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which organism is recovered on buffered charcoal-yeast extract (BCYE) agar?', '["Legionella","Rickettsia","Fungi","Mycobacterium","Chlamydia"]'::jsonb, 'Legionella', 'Among the listed organisms only Legionella pneumophila is a fastidious intracellular bacterium that requires L-cysteine and iron and is recovered on buffered charcoal-yeast extract (BCYE) agar.'),
('187203fa-1bcf-5c73-b849-2e67714b453a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'On dry inanimate surfaces, Acinetobacter baumannii survives for:', '["Days only","Minutes","Hours","Weeks to months","Cannot survive"]'::jsonb, 'Weeks to months', 'Acinetobacter baumannii tolerates desiccation and persists for weeks to months on dry inanimate surfaces, a major factor in its nosocomial transmission.'),
('e3cf3359-52db-5eb4-9571-294f0ffbfda9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The main reservoir of Brucella melitensis is:', '["Pigs","Goats and sheep","Cattle","Dogs","Horses"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('2a427e66-dd08-5ce0-a926-4060cc64cb41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella species appear on Gram stain as which morphology?', '["Acid-fast","Gram-negative coccobacilli","Spirochetes","Gram-positive rods","Gram-positive cocci"]'::jsonb, 'Gram-negative coccobacilli', 'Brucella species are small gram-negative coccobacilli that may be confused with other coccobacillary organisms; they grow only slowly and require enriched media with CO2.'),
('fc7d2641-f982-5d4b-aaa1-94e1b299b2bd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis requires which medium for growth?', '["Blood agar","MacConkey agar","LJ medium","Cysteine-enriched media","Plain chocolate agar"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and requires a medium enriched with cysteine for growth, such as cysteine heart agar or chocolate agar supplemented with cysteine.'),
('6ac97e8c-ef75-5054-83cc-9d9f5ef23461'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii is also known as:', '["E. coli","Klebsiella","Proteus","Serratia","Iraqibacter"]'::jsonb, 'Iraqibacter', 'Acinetobacter baumannii is nicknamed ''Iraqibacter'' because of the high incidence of severe infections, particularly ventilator-associated pneumonia, among soldiers wounded in Iraq.'),
('63e67ed6-acfc-5e0d-b2a9-967bcebf8976'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pneumonic plague is:', '["Mild resulting in decreased functional activity","Highly contagious via droplets","Self-limited mediated by specific receptor activation","Not transmissible without affecting the primary tissue pathway","Chronic leading to subsequent cellular adaptation"]'::jsonb, 'Highly contagious via droplets', 'Pneumonic plague is spread person to person by inhalation of infectious respiratory droplets, unlike bubonic plague which requires a flea bite; it is therefore highly contagious and requires droplet isolation.'),
('d55cf732-c70c-5d32-818f-7186353766eb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The preferred treatment for a Pasteurella multocida bite-wound infection is:', '["Metronidazole","Vancomycin","Amoxicillin-clavulanate","Clindamycin","Azithromycin"]'::jsonb, 'Amoxicillin-clavulanate', 'Pasteurella multocida is highly penicillin-susceptible; for animal-bite infections, amoxicillin-clavulanate is preferred because it also covers the mixed oral flora of the wound.'),
('4574fb88-8f85-53e4-a15b-8b9c45a11ec7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Bordetella pertussis is morphologically a:', '["Gram-negative coccobacillus","Gram-positive coccus","Gram-positive rod","Spirochete","Acid-fast"]'::jsonb, 'Gram-negative coccobacillus', 'Bordetella pertussis is a small, encapsulated gram-negative coccobacillus, the characteristic morphology seen on microscopy of respiratory specimens.'),
('52a57b54-63b3-53bf-bc21-557c7b47b643'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which growth factors are required by Haemophilus influenzae?', '["Only X","Chocolate only","X (hemin) and V (NAD)","Only V","None"]'::jsonb, 'X (hemin) and V (NAD)', 'Haemophilus influenzae requires both X factor (hemin) and V factor (NAD) for growth; chocolate agar supplies both, and satellite growth around S. aureus supplies V factor on blood agar.'),
('1026a59f-09ea-542c-ab24-22707fba0c66'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis grows on which type of medium?', '["Plain chocolate agar","Cysteine-enriched media","Blood agar","MacConkey agar","LJ medium"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and requires a medium enriched with cysteine for growth, such as cysteine heart agar or chocolate agar supplemented with cysteine.'),
('22419cc2-46d4-537d-b154-8920e44a28dd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which clinical term is synonymous with brucellosis?', '["Undulant fever / Malta fever","Typhoid fever","Trench fever","Relapsing fever","Q fever"]'::jsonb, 'Undulant fever / Malta fever', 'Brucellosis is also known as undulant fever or Malta fever because of its characteristic undulating, relapsing fever pattern.'),
('dbc6eb6c-889d-541c-8064-cd3207ad90a7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa quorum sensing is mediated by:', '["Agr system","LuxS system","LasI/LasR and RhlI/RhlR","Com system","Two-component regulator only"]'::jsonb, 'LasI/LasR and RhlI/RhlR', 'Pseudomonas aeruginosa uses the acyl-homoserine-lactone quorum-sensing systems LasI/LasR and RhlI/RhlR to coordinate biofilm formation and expression of virulence factors.'),
('f44dfc01-cad4-5f7d-aac8-f735af5081e3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which chronic pulmonary disease is classically complicated by chronic Pseudomonas aeruginosa infection?', '["Asthma","COPD","Cystic fibrosis","Sarcoidosis","Tuberculosis"]'::jsonb, 'Cystic fibrosis', 'Pseudomonas aeruginosa is the predominant chronic airway pathogen in cystic fibrosis, where it persists as mucoid, alginate-producing biofilms that resist clearance and antibiotics.'),
('bfb0d4ab-b901-5321-a8e3-c8ba6433e761'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which animals serve as the main reservoir of Brucella melitensis?', '["Dogs","Goats and sheep","Cattle","Pigs","Horses"]'::jsonb, 'Goats and sheep', 'Brucella melitensis is maintained in goats and sheep, and unpasteurized dairy products from these animals are the main source of human brucellosis in endemic regions.'),
('6f7718cb-c292-5851-9c2b-8fb548407a43'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which organism is responsible for whooping cough?', '["B. pertussis","H. influenzae","B. bronchiseptica","B. parapertussis","Mycoplasma pneumoniae"]'::jsonb, 'B. pertussis', 'Bordetella pertussis is the etiologic agent of whooping cough, characterized by severe paroxysmal coughing with an inspiratory whoop and post-tussive vomiting in young children.'),
('2533184c-ffe7-50ee-acb7-1c34dd577027'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which flagellar arrangement is seen in Pseudomonas aeruginosa?', '["Monotrichous (polar)","Amphitrichous","Lophotrichous","Peritrichous","None"]'::jsonb, 'Monotrichous (polar)', 'Pseudomonas aeruginosa is motile by means of a single polar flagellum, i.e., monotrichous flagellation, a classic identifying feature.'),
('0540d1a9-77a5-5f2d-a6a5-5ad7fd5f2785'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis is a:', '["Unknown class","Not a bioterror agent","Category C agent","Category B agent","Category A bioterrorism agent"]'::jsonb, 'Category A bioterrorism agent', 'Francisella tularensis is a CDC Category A bioterrorism agent because of its extremely low infective dose, ease of dissemination and potential for severe, often fatal, disease.'),
('313af0f4-b386-5070-a64e-b51de7dde173'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Inhalation of infectious respiratory droplets from a case of bubonic plague produces which form of plague?', '["Bubonic","Septicemic","Pneumonic","Meningitic","Cutaneous"]'::jsonb, 'Pneumonic', 'Pneumonic plague follows inhalation of Yersinia pestis, often as a secondary complication of bubonic plague; it is then the only form spread person to person via respiratory droplets.'),
('87defb9f-2d70-5423-8f03-5665380b5492'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Carbapenem resistance in Acinetobacter baumannii is mediated predominantly by:', '["KPC resulting in decreased functional activity","NDM-1 accompanied by associated clinical symptoms","VIM mediated by specific receptor activation","IMP without affecting the primary tissue pathway","OXA-type carbapenemases"]'::jsonb, 'OXA-type carbapenemases', 'Carbapenem resistance in Acinetobacter baumannii is mediated largely by acquired OXA-type (class D) beta-lactamases, including OXA-23, OXA-24/40, OXA-51 and OXA-58.'),
('615add8a-34b6-5c61-ad4c-457c70fe8a80'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus ducreyi is the cause of:', '["LGV","Genital herpes","Chancroid (soft chancre)","Granuloma inguinale","Primary syphilis"]'::jsonb, 'Chancroid (soft chancre)', 'Haemophilus ducreyi causes chancroid (soft chancre), a painful genital ulcer with tender inguinal lymphadenopathy, in contrast to the painless ulcer of primary syphilis.'),
('c0b66255-4e06-5b30-b176-33f571735660'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Dot/Icm apparatus of Legionella pneumophila belongs to which secretory system?', '["Quorum sensing","Type IV secretion","Type III secretion","Two-component regulator","Flagellar export"]'::jsonb, 'Type IV secretion', 'The Dot/Icm apparatus of Legionella pneumophila is a type IV secretion system that injects effector proteins into host cells to establish the replicative vacuole inside macrophages.'),
('478f2447-c1e9-523f-a6ab-d466de39eddf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which medium is used for the selective isolation of Pseudomonas aeruginosa?', '["MacConkey agar","Chocolate agar","Blood agar","LJ medium","Cetrimide agar"]'::jsonb, 'Cetrimide agar', 'Cetrimide agar is the selective medium for Pseudomonas aeruginosa; cetyltrimethylammonium bromide inhibits most other bacteria while the organism grows and produces blue-green pigment.'),
('8ff75ce1-96ca-5abf-8d61-354b67407b44'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'H. ducreyi is the etiologic agent of:', '["Granuloma inguinale","Genital herpes","Primary syphilis","LGV","Chancroid (soft chancre)"]'::jsonb, 'Chancroid (soft chancre)', 'Haemophilus ducreyi causes chancroid (soft chancre), a painful genital ulcer with tender inguinal lymphadenopathy, in contrast to the painless ulcer of primary syphilis.'),
('98a64e31-ced6-5f68-b04a-78b66c8d5769'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The mechanism of action of pertussis toxin involves:', '["ADP-ribosylates Gi protein","Cleaves IgA","Inhibits protein synthesis","Blocks cell wall","Activates adenylyl cyclase directly"]'::jsonb, 'ADP-ribosylates Gi protein', 'Pertussis toxin ADP-ribosylates the inhibitory Gi protein, inactivating it; adenylyl cyclase then remains activated, raising intracellular cAMP in the host cell.'),
('f70cd70e-e99c-5e99-9f0e-5bb4e928f5e2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which characteristic of Francisella tularensis underlies its value as a bioweapon?', '["Low infectivity","Not infectious","Moderately infectious","Highly infectious (10 CFU)","Unknown infectivity"]'::jsonb, 'Highly infectious (10 CFU)', 'Francisella tularensis is highly infectious, with as few as 10 organisms (CFU) able to cause disease after inhalation or inoculation, accounting for its potential as a bioweapon.'),
('d909bc58-d387-5813-a59f-291dd2e0bd19'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis is:', '["Acid-fast resulting in decreased functional activity","Gram-positive coccus accompanied by associated clinical symptoms","Gram-positive rod mediated by specific receptor activation","Fungus without affecting the primary tissue pathway","GN coccobacillus with bipolar stain"]'::jsonb, 'GN coccobacillus with bipolar stain', 'Yersinia pestis is a gram-negative coccobacillus that characteristically shows bipolar (''safety pin'') accentuation with Giemsa, Wayson or polychrome methylene blue staining.'),
('0cb02f7f-7788-57aa-bc15-197d0a62eccd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Non-typeable Haemophilus influenzae most commonly causes:', '["Septic arthritis","Otitis media and COPD exacerbations","Epiglottitis","Purpuric rash","Meningitis in infants"]'::jsonb, 'Otitis media and COPD exacerbations', 'Non-typeable Haemophilus influenzae (NTHi) lacks a capsule and causes mucosal infections such as otitis media, sinusitis and exacerbations of COPD, rather than invasive disease.'),
('d59d936e-32f9-56a7-884d-34730cf30c1e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii is grouped with which multidrug-resistant pathogens?', '["Bacillaceae","Enterobacteriaceae","ESKAPE group","Vibrionaceae","HACEK group"]'::jsonb, 'ESKAPE group', 'Acinetobacter baumannii is one of the ESKAPE pathogens, a group of multidrug-resistant nosocomial bacteria that escape the action of conventional antibiotics.'),
('6c5e8ad8-74c9-58d2-a001-a2948de3947a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which staining pattern is characteristic of Yersinia pestis?', '["Bipolar staining","Uniform staining","Beaded appearance","Acid-fast","Gram-positive reaction"]'::jsonb, 'Bipolar staining', 'Yersinia pestis shows a bipolar (''safety pin'') pattern of staining with Giemsa, Wayson or polychrome methylene blue, a rapid aid to suspecting plague.'),
('3311bc7f-ed7c-5e38-a314-b9ae7dbf93ed'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which nutrients are essential for the growth of Legionella pneumophila?', '["Blood","X and V factors","Glucose","Cysteine and iron","Cholesterol"]'::jsonb, 'Cysteine and iron', 'Legionella pneumophila specifically requires L-cysteine and iron salts for growth and is cultured on buffered charcoal-yeast extract (BCYE) agar.'),
('3e49ec8a-8ab0-5908-8db5-45026defad5d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which clinical feature is characteristic of bubonic plague?', '["Rash resulting in decreased functional activity","Hepatitis accompanied by associated clinical symptoms","Painful swollen lymph nodes (buboes)","Meningitis without affecting the primary tissue pathway","Pneumonia leading to subsequent cellular adaptation"]'::jsonb, 'Painful swollen lymph nodes (buboes)', 'Bubonic plague is characterized by painful, swollen regional lymph nodes (buboes) that develop after Yersinia pestis is inoculated by a flea bite and drains to the regional nodes.'),
('61f8b212-0d3f-5d85-85e6-30cf53ac2dd5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which group of nosocomial pathogens includes Acinetobacter baumannii?', '["Vibrionaceae","Enterobacteriaceae","Bacillaceae","ESKAPE group","HACEK group"]'::jsonb, 'ESKAPE group', 'Acinetobacter baumannii is one of the ESKAPE pathogens, a group of multidrug-resistant nosocomial bacteria that escape the action of conventional antibiotics.'),
('54183735-bc7b-5024-ba91-e4157e2fafa0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which systems mediate quorum sensing in Pseudomonas aeruginosa?', '["Agr system","LasI/LasR and RhlI/RhlR","LuxS system","Two-component regulator only","Com system"]'::jsonb, 'LasI/LasR and RhlI/RhlR', 'Pseudomonas aeruginosa uses the acyl-homoserine-lactone quorum-sensing systems LasI/LasR and RhlI/RhlR to coordinate biofilm formation and expression of virulence factors.'),
('66c06bf3-8dc5-5b15-879e-1ea0b8766fe3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella abortus is classically found in:', '["Dogs","Sheep","Pigs","Cattle","Goats"]'::jsonb, 'Cattle', 'Brucella abortus is chiefly associated with cattle, whereas B. melitensis (goats and sheep), B. suis (pigs) and B. canis (dogs) predominate in their respective reservoirs.'),
('a8452f29-439d-5d98-b6f4-c83a7b8c418a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Carbapenem resistance in Acinetobacter baumannii:', '["VIM resulting in decreased functional activity","KPC accompanied by associated clinical symptoms","NDM-1 mediated by specific receptor activation","IMP without affecting the primary tissue pathway","OXA-type carbapenemases"]'::jsonb, 'OXA-type carbapenemases', 'Carbapenem resistance in Acinetobacter baumannii is mediated largely by acquired OXA-type (class D) beta-lactamases, including OXA-23, OXA-24/40, OXA-51 and OXA-58.'),
('113eec18-5454-5fd8-aefb-01b4a0f9e843'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella is transmitted by:', '["Ingestion of raw milk","Direct contact with aborted animal products","Aerosol inhalation in abattoirs","Unpasteurized soft cheese","All of the above"]'::jsonb, 'All of the above', 'Brucella reaches humans by ingestion of raw milk or unpasteurized cheese, direct contact with aborted animal placentas, and aerosol inhalation in abattoirs or laboratories.'),
('cdfb631b-a466-5534-8dd2-c68fdc497a28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'A bite wound infected with Pasteurella multocida is best treated with:', '["Clindamycin","Vancomycin","Amoxicillin-clavulanate","Metronidazole","Azithromycin"]'::jsonb, 'Amoxicillin-clavulanate', 'Pasteurella multocida is highly penicillin-susceptible; for animal-bite infections, amoxicillin-clavulanate is preferred because it also covers the mixed oral flora of the wound.'),
('2645bdc2-8ae3-5839-8808-c541f7f44460'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae requires which factors for growth?', '["Only V","X (hemin) and V (NAD)","Only X","None","Cholesterol"]'::jsonb, 'X (hemin) and V (NAD)', 'Haemophilus influenzae requires both X factor (hemin) and V factor (NAD) for growth; chocolate agar supplies both, and satellite growth around S. aureus supplies V factor on blood agar.'),
('77e204af-6775-57e9-9282-0c63f775c877'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis is most commonly transmitted to humans by:', '["Flea bite resulting in decreased functional activity","Body louse bite accompanied by associated clinical symptoms","Tick bite / handling infected animal tissues","Human sexual contact without affecting the primary tissue pathway","Mosquito bite leading to subsequent cellular adaptation"]'::jsonb, 'Tick bite / handling infected animal tissues', 'Francisella tularensis is acquired by tick or deerfly bite, by handling infected wild animals such as rabbits, or by inhaling or ingesting contaminated material.'),
('33d44dcb-8de8-58b3-8fe7-5a8691c7d283'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Chancroid (soft chancre) is caused by:', '["Haemophilus ducreyi","Haemophilus influenzae","Treponema pallidum","Chlamydia trachomatis","Klebsiella granulomatis"]'::jsonb, 'Haemophilus ducreyi', 'Haemophilus ducreyi causes chancroid (soft chancre), a painful genital ulcer with tender inguinal lymphadenopathy, in contrast to the painless ulcer of primary syphilis.'),
('3524afcc-d078-5c1c-91cc-98b3f46c0605'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'What is the oxidase reaction of Pseudomonas aeruginosa?', '["Positive","Variable","Unknown","Negative","Not tested"]'::jsonb, 'Positive', 'Pseudomonas aeruginosa is oxidase positive, an important biochemical feature that distinguishes it from the oxidase-negative members of the Enterobacteriaceae.'),
('8a465557-1b91-5019-a00e-8e36dbb14bcf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which clinical form of tularemia presents with conjunctivitis and ipsilateral preauricular lymphadenopathy?', '["Meningitic resulting in decreased functional activity","Conjunctival infection + preauricular LN","Hepatic mediated by specific receptor activation","Pneumonic without affecting the primary tissue pathway","Cutaneous ulcer leading to subsequent cellular adaptation"]'::jsonb, 'Conjunctival infection + preauricular LN', 'Oculoglandular tularemia follows inoculation of the conjunctiva and consists of a purulent conjunctivitis together with ipsilateral preauricular lymphadenopathy.'),
('f120a4e1-0fd5-5ae3-bc46-ac1295f9ec5c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which morphology is shared by Brucella species?', '["Acid-fast","Gram-negative coccobacilli","Spirochetes","Gram-positive cocci","Gram-positive rods"]'::jsonb, 'Gram-negative coccobacilli', 'Brucella species are small gram-negative coccobacilli that grow slowly and require enriched media with added CO2.'),
('3c29d1b8-0b0e-5171-8a96-2aad3f2aa736'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis requires:', '["Cysteine-enriched media","LJ medium","Blood agar","MacConkey agar","Plain chocolate agar"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and requires a medium enriched with cysteine for growth, such as cysteine heart agar or chocolate agar supplemented with cysteine.'),
('31070503-1a5f-5807-b876-2604419c9b68'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'For extensively drug-resistant Acinetobacter baumannii, the remaining therapeutic option is often:', '["Gentamicin","Vancomycin","Colistin (polymyxin E)","Ciprofloxacin","Ceftriaxone"]'::jsonb, 'Colistin (polymyxin E)', 'For extensively drug-resistant (XDR) Acinetobacter baumannii, colistin (polymyxin E) is often the only active agent available, despite the risk of nephrotoxicity.'),
('35311e6e-60c3-571c-b253-a87cd3d1a3f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pasteurella multocida causes infection after:', '["Ingestion","Blood transfusion","Mosquito bite","Inhalation","Dog/cat bites"]'::jsonb, 'Dog/cat bites', 'Pasteurella multocida is a commensal of the oral cavity of dogs and cats; infection follows animal bites or scratches and manifests as rapidly progressive cellulitis and abscess formation.'),
('9b05ed57-dde3-5c81-87ac-961502f9a1ae'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Yersinia pestis is transmitted by the bite of which vector?', '["Tick resulting in decreased functional activity","Body louse accompanied by associated clinical symptoms","Flea (Xenopsylla cheopis)","Mosquito without affecting the primary tissue pathway","Sandfly leading to subsequent cellular adaptation"]'::jsonb, 'Flea (Xenopsylla cheopis)', 'Bubonic plague is transmitted by the oriental rat flea, Xenopsylla cheopis; the flea becomes blocked and regurgitates Yersinia pestis into the bite wound while feeding on the host.'),
('5284fc69-9f96-59da-a52d-d613044e279c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii is resistant to:', '["Clindamycin only","Carbapenems (CRAB)","Fusidic acid only","Penicillin only","Macrolides only"]'::jsonb, 'Carbapenems (CRAB)', 'Carbapenem-resistant Acinetobacter baumannii (CRAB) is a leading multidrug-resistant nosocomial pathogen, with carbapenem resistance mediated chiefly by OXA-type beta-lactamases.'),
('12f68db2-4aea-5c11-90a1-de0555586622'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Bordetella pertussis causes tissue damage largely through a tracheal cytotoxin that:', '["Causes lymphocytosis","Causes systemic toxicity","Damages ciliated epithelium","Causes hypoglycemia","Directly induces bronchospasm"]'::jsonb, 'Damages ciliated epithelium', 'Tracheal cytotoxin of Bordetella pertussis destroys the ciliated respiratory epithelial cells, impairing mucus clearance and contributing to the paroxysmal cough of pertussis.'),
('6e299a60-7d4a-5bdf-b49b-ad68ebb874c4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which drug is used for the treatment of extensively drug-resistant Acinetobacter baumannii?', '["Gentamicin","Ciprofloxacin","Vancomycin","Ceftriaxone","Colistin (polymyxin E)"]'::jsonb, 'Colistin (polymyxin E)', 'For extensively drug-resistant (XDR) Acinetobacter baumannii, colistin (polymyxin E) is often the only active agent available, despite the risk of nephrotoxicity.'),
('3fa5b90d-dcbf-57c7-909d-33b0bc44150b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'A cat scratch wound that becomes painful and swollen within 24 hours is most likely due to:', '["Pasteurella multocida","Capnocytophaga canimorsus","Bartonella henselae","Clostridium tetani","Staphylococcus epidermidis"]'::jsonb, 'Pasteurella multocida', 'Pasteurella multocida is a commensal of the feline oral cavity; cat bites and scratches rapidly introduce it into soft tissue, producing painful cellulitis within 12-24 hours.'),
('0fcee127-4783-55c9-88cc-3767964404ec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pseudomonas aeruginosa belongs to which morphologic category?', '["Gram-positive coccus","Acid-fast","Spirochete","Gram-positive rod","Gram-negative rod"]'::jsonb, 'Gram-negative rod', 'Pseudomonas aeruginosa is a strictly aerobic, oxidase-positive gram-negative rod, consistent with the common cause of ventilator-associated pneumonia in the ICU.'),
('2134457c-9ab3-574a-a307-915807b05834'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Necrotic, black-crusted cutaneous lesions with surrounding erythema in a neutropenic patient with Pseudomonas aeruginosa bacteremia most likely represent:', '["Ecthyma gangrenosum","Necrotizing fasciitis","Cellulitis","Erysipelas","Impetigo"]'::jsonb, 'Ecthyma gangrenosum', 'Ecthyma gangrenosum - a necrotic, black-crusted skin lesion with surrounding erythema - is the characteristic cutaneous lesion of Pseudomonas aeruginosa bacteremia, classically in neutropenic patients.'),
('4ef98427-f187-57f3-ba4b-7b2ed5b8bf77'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Pertussis toxin:', '["Cleaves IgA","Blocks cell wall","Activates adenylyl cyclase directly","Inhibits protein synthesis","ADP-ribosylates Gi protein"]'::jsonb, 'ADP-ribosylates Gi protein', 'Pertussis toxin ADP-ribosylates the inhibitory Gi protein, inactivating it; adenylyl cyclase then remains activated, raising intracellular cAMP in the host cell.'),
('b6eba155-c8c6-52bf-8f95-2f598edf3131'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The preferred treatment for pertussis is:', '["Azithromycin","Metronidazole","Penicillin","Vancomycin","Ceftriaxone"]'::jsonb, 'Azithromycin', 'A macrolide such as azithromycin is the preferred treatment for pertussis; it eradicates Bordetella pertussis and can reduce transmission when started in the catarrhal stage.'),
('01d3efe8-f286-5532-8114-7ad6e8b64c36'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Chronic, mucoid, alginate-producing pulmonary infection with Pseudomonas aeruginosa is the hallmark of:', '["COPD","Sarcoidosis","Tuberculosis","Cystic fibrosis","Asthma"]'::jsonb, 'Cystic fibrosis', 'Pseudomonas aeruginosa is the predominant chronic airway pathogen in cystic fibrosis, where it persists as mucoid, alginate-producing biofilms that resist clearance and antibiotics.'),
('d311d393-9569-5c04-9985-e509ad978935'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Within which host cell type does Legionella pneumophila principally replicate?', '["RBCs","T cells","Neutrophils","B cells","Macrophages"]'::jsonb, 'Macrophages', 'Legionella pneumophila is a facultative intracellular pathogen that replicates within alveolar macrophages (and within amoebae in water), evading killing by phagocytes.'),
('c1b3d9fd-ecde-5f9c-a4cc-36287bbaa55c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which antibiotics constitute first-line treatment for tularemia?', '["Streptomycin or gentamicin","Penicillin","Vancomycin","Ceftriaxone","Clindamycin"]'::jsonb, 'Streptomycin or gentamicin', 'Aminoglycosides (streptomycin or gentamicin) are the treatment of choice for tularemia; penicillins and cephalosporins are not effective against Francisella tularensis.'),
('4d8fbc4f-bfe2-5b9a-8cfd-c01c6154ecf8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which regimen provides standard therapy for brucellosis?', '["Doxycycline + rifampin","Azithromycin","Ceftriaxone","Penicillin","Vancomycin"]'::jsonb, 'Doxycycline + rifampin', 'Brucellosis is treated with doxycycline combined with rifampin (or an aminoglycoside such as gentamicin) for several weeks; combination therapy prevents the high rate of relapse.'),
('0054351f-947c-566d-a759-2489044a99be'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis is the causative agent of which zoonotic disease?', '["Brucellosis","Plague","Melioidosis","Glanders","Tularemia (rabbit fever)"]'::jsonb, 'Tularemia (rabbit fever)', 'Francisella tularensis causes tularemia (rabbit fever), a zoonosis acquired from rabbits and other mammals by handling infected animal tissues, ingestion of contaminated meat or water, or arthropod bites.'),
('af924cb1-e5ee-5706-9e94-e4489a4420a7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Bubonic plague is characterized by:', '["Hepatitis resulting in decreased functional activity","Pneumonia accompanied by associated clinical symptoms","Rash mediated by specific receptor activation","Painful swollen lymph nodes (buboes)","Meningitis leading to subsequent cellular adaptation"]'::jsonb, 'Painful swollen lymph nodes (buboes)', 'Bubonic plague is characterized by painful, swollen regional lymph nodes (buboes) that develop after Yersinia pestis is inoculated by a flea bite and drains to the regional nodes.'),
('c32b5406-d6cc-59a2-aa93-08ed1ea4461b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Acinetobacter baumannii belongs to:', '["HACEK group","ESKAPE group","Bacillaceae","Enterobacteriaceae","Vibrionaceae"]'::jsonb, 'ESKAPE group', 'Acinetobacter baumannii is one of the ESKAPE pathogens, a group of multidrug-resistant nosocomial bacteria that escape the action of conventional antibiotics.'),
('de25f1ba-3ace-5955-a37b-2223fbf7719c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Francisella tularensis grows on which specialized culture medium?', '["Plain chocolate agar","LJ medium","MacConkey agar","Blood agar","Cysteine-enriched media"]'::jsonb, 'Cysteine-enriched media', 'Francisella tularensis is fastidious and requires a medium enriched with cysteine for growth, such as cysteine heart agar or chocolate agar supplemented with cysteine.'),
('63591954-d0bb-50bf-bc7b-aa44a26e00bd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Brucella species give a result of:', '["Oxidase variable","Oxidase not tested","Oxidase negative","Oxidase unknown","Oxidase positive"]'::jsonb, 'Oxidase positive', 'Brucella species are oxidase positive, a biochemical feature shared with several other gram-negative coccobacilli encountered in the laboratory.'),
('9cbd44f5-82aa-56e0-9d15-7042f0bdbcaf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Haemophilus influenzae grows on:', '["Chocolate agar","LJ medium","Blood agar","MacConkey agar","Sabouraud agar"]'::jsonb, 'Chocolate agar', 'Haemophilus influenzae grows on chocolate agar, where heat-lysed red cells provide both X factor (hemin) and V factor (NAD); it does not grow on plain blood agar.'),
('635413fa-07ec-5873-b423-c1d7fddd9f9c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which selective agar is employed for the isolation and presumptive identification of Pseudomonas aeruginosa?', '["Chocolate agar","LJ medium","MacConkey agar","Cetrimide agar","Blood agar"]'::jsonb, 'Cetrimide agar', 'Cetrimide agar is the selective medium for Pseudomonas aeruginosa; cetyltrimethylammonium bromide inhibits most other bacteria while the organism grows and produces blue-green pigment.'),
('76fbbfb8-0b65-55a5-8491-8120cf7b6659'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'The Dot/Icm system of Legionella pneumophila is classified as:', '["Type III secretion","Type IV secretion","Flagellar export","Two-component regulator","Quorum sensing"]'::jsonb, 'Type IV secretion', 'The Dot/Icm apparatus of Legionella pneumophila is a type IV secretion system that injects effector proteins into host cells to establish the replicative vacuole inside macrophages.'),
('3624bae5-e1df-5fdd-803a-10ac78340bc6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which condition is the mild, non-pneumonic, self-resolving illness caused by Legionella pneumophila?', '["Severe pneumonia","Hemorrhagic fever","Meningitis","Rash","Self-limited flu-like illness"]'::jsonb, 'Self-limited flu-like illness', 'Pontiac fever is the non-pneumonic, self-limited, flu-like illness caused by Legionella pneumophila: fever, myalgia and headache that resolve spontaneously within a few days without pneumonia.'),
('73806b9b-6071-593c-9a90-eda66f52f305'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which statement about transmission of Brucella is most accurate?', '["Unpasteurized milk is the classic source","Occupational contact in livestock handlers transmits it","Inhalation of laboratory aerosols is a recognized route","Ingestion of contaminated dairy products transmits it","All of the above"]'::jsonb, 'All of the above', 'Brucella is transmitted by ingestion of unpasteurized milk and dairy products, direct occupational contact with infected animals, and inhalation of aerosols in slaughterhouses or laboratories.'),
('4240db03-7c9a-5627-a065-11086f032fb5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Gram Negative - Other Gram Negative', 'Which is the most accurate statement about Brucella transmission?', '["Raw milk consumption transmits it","Contact with infected animal carcasses transmits it","Inhalational exposure in slaughterhouses transmits it","Unpasteurized dairy products transmit it","All of the above"]'::jsonb, 'All of the above', 'Human brucellosis follows ingestion of raw milk or unpasteurized dairy products, contact with infected animal carcasses or tissues, and inhalation of contaminated aerosols in abattoirs or laboratories.'),
('d7839ff4-9fef-5c6a-97e0-4df9255440c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Rapidly growing mycobacteria produce visible colonies within:', '["2-8 weeks","8-12 weeks","6 months","1 year","Less than 7 days"]'::jsonb, 'Less than 7 days', 'Runyon group IV organisms such as M. fortuitum and M. abscessus grow within 7 days or less, unlike the slow growers that require weeks.'),
('515aeaab-4a4e-5586-98d2-55c22bfadb39'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The recommended sputum sampling strategy for diagnosing smear-positive pulmonary TB is:', '["Two specimens at any time of day","Five urine specimens","A single bronchoalveolar lavage","Three consecutive early-morning specimens","A single midday specimen"]'::jsonb, 'Three consecutive early-morning specimens', 'Three consecutive early-morning sputum specimens, with good cough specimens, optimize the yield of smear and culture in pulmonary tuberculosis.'),
('6390a7bc-0f66-5121-92e5-39ac87dfbe45'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Multidrug-resistant tuberculosis (MDR-TB) is defined as resistance to:', '["Pyrazinamide and ethambutol","Streptomycin and kanamycin","Both isoniazid and rifampin","Isoniazid alone","Rifampin and ethambutol"]'::jsonb, 'Both isoniazid and rifampin', 'MDR-TB means the isolate is resistant to at least the two most potent first-line drugs, isoniazid and rifampin, requiring a longer regimen of second-line agents.'),
('790c2cae-2296-50a6-8955-84a3c2ed00f6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The initial (intensive) phase of the standard WHO short-course regimen for drug-sensitive TB is:', '["3 months of pyrazinamide and ethambutol","2 months of isoniazid, rifampin, pyrazinamide and ethambutol","6 months of isoniazid alone","4 months of rifampin and ethambutol","2 weeks of streptomycin only"]'::jsonb, '2 months of isoniazid, rifampin, pyrazinamide and ethambutol', 'Standard therapy uses a 2-month intensive phase of four drugs (isoniazid, rifampin, pyrazinamide, ethambutol) followed by a 4-month continuation phase of isoniazid and rifampin.'),
('1a9a9433-d729-55b0-b482-074246cc1cac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Where does reactivation (secondary) pulmonary tuberculosis most typically occur?', '["Apical and posterior segments of upper lobes","Lower lobe bases accompanied by associated clinical symptoms","Lingula only mediated by specific receptor activation","Middle lobe only without affecting the primary tissue pathway","Pericardial surface leading to subsequent cellular adaptation"]'::jsonb, 'Apical and posterior segments of upper lobes', 'Reactivation TB, in which dormant bacilli multiply years later, classically produces disease in the well-oxygenated apical and posterior segments of the upper lobes, often cavitating.'),
('ce6d7316-6a0c-5181-975e-7519a1620f0c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Pott disease refers to:', '["Tuberculous meningitis","Tuberculosis of the kidney","Tuberculous pericarditis","Tuberculosis of the ankle joint","Tuberculosis of the spine (vertebral bodies)"]'::jsonb, 'Tuberculosis of the spine (vertebral bodies)', 'Pott disease is tuberculous spondylitis; destruction of vertebral bodies with anterior wedging causes angular kyphosis (gibbus) and may form a paraspinal ''cold'' abscess.'),
('2b34927a-759c-50fb-b07b-c0ff8c9f216e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Miliary tuberculosis results from:', '["Lymphatic spread confined to hilar nodes","Aspiration of bacilli into the lower lobe","Spread along the subarachnoid space only","Hematogenous dissemination with small granulomas in many organs","Direct bronchial spread to the opposite lung"]'::jsonb, 'Hematogenous dissemination with small granulomas in many organs', 'Miliary TB follows blood-stream dissemination of the bacillus, producing numerous 1-3 mm granulomata (''millet seeds'') in the lungs, liver, spleen, bone marrow and meninges.'),
('570d4adb-8b7a-5f6a-9c37-9f3dff88dfe9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The Ghon complex of primary tuberculosis consists of:', '["Large pleural effusion","Calcified pericardium","Parenchymal focus with draining hilar lymph node","Apical cavity with fibrosis","Miliary nodules in both lungs"]'::jsonb, 'Parenchymal focus with draining hilar lymph node', 'The Ghon complex comprises the primary parenchymal (subpleural) focus together with the involved draining hilar/mediastinal lymph nodes; both usually undergo fibrosis and calcification.'),
('51d6da6c-90a4-53cb-964d-4be033720d29'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which mycobacterium is a tap-water scotochromogen that is usually only a contaminant?', '["M. fortuitum complex","M. gordonae","M. kansasii","M. marinum","M. ulcerans"]'::jsonb, 'M. gordonae', 'M. gordonae, a scotochromogen commonly found in tap water, is rarely if ever a pathogen and is typically disregarded as a laboratory contaminant.'),
('0a46072e-be35-5213-a7a8-274b1c0373c7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. leprae is the causative agent of:', '["Leprosy (Hansen disease)","Buruli ulcer","Lymphogranuloma venereum","Chancroid","Tinea corporis"]'::jsonb, 'Leprosy (Hansen disease)', 'M. leprae causes leprosy (Hansen disease), a chronic granulomatous infection chiefly affecting the skin and peripheral nerves.'),
('fe3e2d85-c244-506e-9836-bfc9860a6c12'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. fortuitum most characteristically produces:', '["Fish tank granuloma resulting in decreased functional activity","Buruli ulcer accompanied by associated clinical symptoms","Leprosy mediated by specific receptor activation","Tuberculous meningitis without affecting the primary tissue pathway","Post-surgical wound and soft-tissue infections"]'::jsonb, 'Post-surgical wound and soft-tissue infections', 'M. fortuitum, an environmental rapid grower, contaminates surgical wounds and prosthetic devices, causing indolent post-operative wound infections and cellulitis.'),
('6a1a7784-54b1-521d-9d41-b82b686af0cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. chelonae most often causes:', '["Buruli ulcer","Cervical lymphadenitis in infants","Disseminated disease in AIDS","Post-surgical and indwelling catheter infections","Cavitary lung disease in young smokers"]'::jsonb, 'Post-surgical and indwelling catheter infections', 'M. chelonae, a rapid grower, produces indolent post-surgical wound infections and infections of indwelling central venous catheters.'),
('30947f4d-66bb-5206-8dec-a519a1b00df4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. scrofulaceum most characteristically causes:', '["Disseminated disease in AIDS","Peripheral neuritis","Cervical lymphadenitis (scrofula) in children","Pulmonary cavitation","Buruli ulcer"]'::jsonb, 'Cervical lymphadenitis (scrofula) in children', 'M. scrofulaceum typically causes unilateral, painless cervical lymphadenitis (scrofula) in young children following oral exposure to environmental sources.'),
('203675c1-cbe2-5e75-b80b-e7d0d02abbaa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which strategy is recommended for the treatment of M. ulcerans (Buruli ulcer)?', '["Observational management only resulting in decreased functional activity","Rifampin plus streptomycin (or clarithromycin) combined with surgery","Isoniazid monotherapy mediated by specific receptor activation","Penicillin alone without affecting the primary tissue pathway","Dapsone alone leading to subsequent cellular adaptation"]'::jsonb, 'Rifampin plus streptomycin (or clarithromycin) combined with surgery', 'Buruli ulcer is treated with an 8-week regimen of rifampin plus streptomycin (clarithromycin is an alternative) combined with surgical excision/debridement of necrotic tissue.'),
('58fd863f-884e-51ee-af9c-bd037a2eee96'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. ulcerans causes which clinical condition?', '["Buruli ulcer (necrotizing skin ulcer)","Swimming pool granuloma","Scrofula","Miliary tuberculosis","Chronic otitis media"]'::jsonb, 'Buruli ulcer (necrotizing skin ulcer)', 'M. ulcerans elaborates mycolactone, a necrotizing toxin that produces the progressive, painless, undermining skin ulcers of Buruli ulcer in tropical regions.'),
('e484abef-04e1-5381-9b82-24ae929f0910'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which Runyon group is correct for a mycobacterium that forms visible colonies in under 7 days?', '["Group I (photochromogen)","Group II (scotochromogen)","Group III (nonchromogen)","Group V (slow grower)","Group IV (rapid grower)"]'::jsonb, 'Group IV (rapid grower)', 'Runyon group IV comprises the rapid growers, exemplified by M. abscessus, M. chelonae and M. fortuitum, with colony formation in under 7 days.'),
('4010c89a-13cd-52fe-b8f0-183bc0e53f14'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which disease manifestations are characteristic of M. abscessus infection?', '["Tuberculous meningitis in children resulting in decreased functional activity","Scrofula in children accompanied by associated clinical symptoms","Genitourinary ulcers mediated by specific receptor activation","Chronic pulmonary infection and skin/soft-tissue abscesses","Buruli ulcer leading to subsequent cellular adaptation"]'::jsonb, 'Chronic pulmonary infection and skin/soft-tissue abscesses', 'M. abscessus causes chronic suppurative pulmonary disease, particularly in cystic fibrosis, and skin and soft-tissue abscesses following trauma or surgery.'),
('f347813f-5e17-5db3-a454-be8e4957b46f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'What is the most characteristic clinical disease caused by M. kansasii?', '["Disseminated disease in AIDS resulting in decreased functional activity","Lepromatous leprosy accompanied by associated clinical symptoms","Chronic cavitary pulmonary disease resembling tuberculosis","Buruli ulcer without affecting the primary tissue pathway","Fish tank granuloma leading to subsequent cellular adaptation"]'::jsonb, 'Chronic cavitary pulmonary disease resembling tuberculosis', 'M. kansasii causes chronic cavitary pulmonary infection usually indistinguishable from tuberculosis, especially in middle-aged men with chronic lung disease or immunosuppression.'),
('f23fb38d-0575-52d0-95b2-cb6216970686'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Infection with M. marinum classically produces:', '["Tuberculous meningitis","Skin granuloma from fish tank or swimming pool exposure","Pulmonary cavitation","Buruli ulcer on the legs","Cervical lymphadenitis in children"]'::jsonb, 'Skin granuloma from fish tank or swimming pool exposure', 'M. marinum, acquired from contaminated water (fish tanks, swimming pools), causes chronic granulomatous skin nodules of the hands, also called fish tank or swimming pool granuloma.'),
('586b74be-7f0b-5c9c-9758-b700ee7e499f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. avium complex belongs to which Runyon group?', '["Group III (nonchromogen)","Group I (photochromogen)","Group II (scotochromogen)","Group IV (rapid grower)","None; it is not classified"]'::jsonb, 'Group III (nonchromogen)', 'MAC is a slow-growing, non-pigmented (nonchromogenic) organism, i.e., Runyon group III.'),
('ab91ec85-f2d3-597d-8d69-39ee6b4ea3bb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Disseminated M. avium complex (MAC) infection is classically seen in:', '["Healthy young adults resulting in decreased functional activity","Post-partum women accompanied by associated clinical symptoms","Patients with rheumatoid arthritis mediated by specific receptor activation","Tubal ligation without affecting the primary tissue pathway","Advanced AIDS with CD4 counts below 50 cells/microliter"]'::jsonb, 'Advanced AIDS with CD4 counts below 50 cells/microliter', 'Disseminated MAC disease occurs when CD4 counts fall below 50 cells/microliter in AIDS, causing fever, weight loss, anemia, diarrhea and hepatosplenomegaly.'),
('860dfafb-6cf0-5a3a-a933-715e28a6735e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Interferon-gamma release assays (IGRAs) detect TB infection by measuring:', '["Antigen-antibody complexes resulting in decreased functional activity","Interferon-alpha levels accompanied by associated clinical symptoms","Complement fixation titers mediated by specific receptor activation","IFN-gamma released by T cells stimulated with ESAT-6 and CFP-10","Serum antibodies against M. tuberculosis leading to subsequent cellular adaptation"]'::jsonb, 'IFN-gamma released by T cells stimulated with ESAT-6 and CFP-10', 'IGRAs (e.g., QuantiFERON, T-SPOT.TB) measure interferon-gamma released from sensitized T cells after stimulation with ESAT-6 and CFP-10, proteins absent from BCG and most NTM.'),
('6fc6418c-5d2e-59de-a297-c0ed8eb4abf7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The tuberculin (Mantoux/PPD) skin test reaction is best characterized as:', '["A type III Arthus reaction","A complement-mediated reaction","A type IV (delayed-type) hypersensitivity reaction","An immediate type I anaphylactic reaction","A type II cytotoxic reaction"]'::jsonb, 'A type IV (delayed-type) hypersensitivity reaction', 'The tuberculin reaction is a delayed-type (type IV) hypersensitivity mediated by sensitized T lymphocytes; induration peaks at 48-72 hours after intradermal PPD injection.'),
('0558f39e-8aaf-5987-9007-af546c11842d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The BCG vaccine consists of:', '["Recombinant M. leprae","Live attenuated Mycobacterium bovis","Killed M. tuberculosis","Purified protein derivative","Inactivated M. bovis"]'::jsonb, 'Live attenuated Mycobacterium bovis', 'BCG (Bacille Calmette-Guerin) is a live attenuated strain of Mycobacterium bovis that induces partial cell-mediated immunity against tuberculosis.'),
('27d57b5f-d4ef-51f9-bf8a-d9a40091bdd5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. tuberculosis is best characterized as:', '["Acid-fast bacillus","Gram-negative rod","Gram-positive coccus","Fungus","Spirochete"]'::jsonb, 'Acid-fast bacillus', 'M. tuberculosis is a slender, non-motile acid-fast bacillus whose cell wall is rich in mycolic acid, which is responsible for its acid-fast staining property.'),
('286d0d74-c45e-58a1-92f3-b39479caecb0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which biochemical test is characteristically positive for M. tuberculosis but negative for M. bovis?', '["Urease production","Nitrate not determined","Esculin hydrolysis","Voges-Proskauer reaction","Niacin (nicotinic acid) accumulation"]'::jsonb, 'Niacin (nicotinic acid) accumulation', 'M. tuberculosis accumulates excess niacin in culture medium (niacin-positive), which distinguishes it from M. bovis and most other mycobacteria.'),
('b1e7fc15-fa58-5578-8a94-b8ff15c56194'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. scrofulaceum and M. gordonae belong to which Runyon group?', '["Group III (nonchromogens)","Group IV (rapid growers)","No group","Group II (scotochromogens)","Group I (photochromogens)"]'::jsonb, 'Group II (scotochromogens)', 'M. scrofulaceum and M. gordonae produce yellow-orange pigment even in the dark, defining them as Runyon group II scotochromogens.'),
('7cc78cee-7e51-554a-9858-b008b334b6c5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The tuberculin skin test should be read at what time after intradermal injection?', '["7 days","Immediately after injection","48-72 hours","15 minutes","6 hours"]'::jsonb, '48-72 hours', 'The Mantoux test is interpreted at 48-72 hours by measuring the induration (not erythema); a delayed reading falsely reduces sensitivity.'),
('ff141f62-ce95-55ee-b32a-878509524b78'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A patient in an endemic area has hypopigmented anesthetic skin patches with thickened, palpably enlarged peripheral nerves. The diagnosis is:', '["Scabies","Leprosy (Hansen disease)","Lichen planus","Psoriasis","Vitiligo"]'::jsonb, 'Leprosy (Hansen disease)', 'Anesthetic hypopigmented patches plus thickened peripheral nerves are diagnostic of leprosy, reflecting M. leprae invasion of dermal nerves.'),
('8d9d71ff-b649-514e-8f2d-d86629bb14ee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which species are classified as Runyon group IV (rapid growers)?', '["M. fortuitum, M. chelonae and M. abscessus","M. kansasii and M. marinum","M. tuberculosis and M. bovis","M. avium and M. intracellulare","M. leprae and M. ulcerans"]'::jsonb, 'M. fortuitum, M. chelonae and M. abscessus', 'Runyon group IV includes the rapidly growing mycobacteria that form visible colonies in under 7 days, notably the M. fortuitum and M. chelonae-abscessus complexes.'),
('3b2ef2f4-01dd-50ca-a6f8-c033ad115f8b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which statement regarding nontuberculous mycobacteria (NTM) is correct?', '["They are always transmitted airborne from person to person resulting in decreased functional activity","They are exclusively human pathogens accompanied by associated clinical symptoms","They require insect vectors mediated by specific receptor activation","They never cause pulmonary disease without affecting the primary tissue pathway","They are ubiquitous environmental organisms and are not transmitted from person to person"]'::jsonb, 'They are ubiquitous environmental organisms and are not transmitted from person to person', 'NTM are environmental organisms of soil and water; unlike M. tuberculosis they are generally not transmitted person-to-person, and disease arises from environmental exposure in susceptible hosts.'),
('00e64571-92d2-5e33-ab33-f289feb44fd5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In the Ziehl-Neelsen technique the carbol fuchsin is applied:', '["After acid-alcohol decolorization","Only as a counterstain","As an aqueous solution only","With heat to drive the dye into the waxy wall","Cold without any heating"]'::jsonb, 'With heat to drive the dye into the waxy wall', 'Moderate heating (steaming) drives carbol fuchsin into the mycolic acid-rich cell wall; hot staining is the essential step of the classic Ziehl-Neelsen method.'),
('e5bd5581-6703-5dd8-8a7e-13c8f24be47e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which site involvement in TB is highly infectious?', '["TB of the kidney","Tuberculous arthritis","Tuberculous laryngitis","Tuberculous epididymitis","Pott disease"]'::jsonb, 'Tuberculous laryngitis', 'Tuberculous laryngitis is highly infectious because laryngeal lesions generate abundant droplet nuclei during speech and coughing.'),
('f23be809-27c7-527f-a78c-abd38c1d4db4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which dye is the primary stain in the Ziehl-Neelsen method for AFB?', '["Lugol''s iodine","Carbol fuchsin","Crystal violet","Safranin","Malachite green"]'::jsonb, 'Carbol fuchsin', 'The Ziehl-Neelsen stain applies hot carbol fuchsin as the primary dye; mycobacteria retain it against acid-alcohol decolorization and appear red against the methylene blue counterstain.'),
('07aed515-7791-567e-a3cd-3efcd93e5dbb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In infants, primary tuberculosis presenting as severe pneumonia with generalized spread is termed:', '["Progressive (primary) tuberculosis","Adult-type apical disease","Post-primary reinfection","Latent infection","Scrofula"]'::jsonb, 'Progressive (primary) tuberculosis', 'When the primary complex fails to heal, often in infants or the immunodeficient, progressive primary TB with bronchogenic and hematogenous spread may be fatal.'),
('a8ad5153-7a3c-563c-83d0-d28962d10700'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Isoniazid exerts its antimycobacterial action by inhibiting synthesis of:', '["Folic acid","DNA gyrase","Ribosomal protein 30S subunit","Cell-wall peptidoglycan","Mycolic acids"]'::jsonb, 'Mycolic acids', 'Isoniazid blocks the mycolic acid synthesis pathway essential to the mycobacterial cell wall; this explains its selective activity against mycobacteria and resistance to host cells.'),
('f0fba06c-24e4-57df-aeca-3e5aa9bcdd0b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which of the following is NOT a first-line antituberculous drug?', '["Rifampin","Pyrazinamide","Ethambutol","Clofazimine","Isoniazid"]'::jsonb, 'Clofazimine', 'Clofazimine is used in leprosy and second-line TB regimens; the first-line TB drugs are isoniazid, rifampin, pyrazinamide and ethambutol (plus streptomycin).'),
('d67bf7dd-2d8f-5242-8a61-2223f2972296'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A patient with tuberculous spondylitis is most likely to develop which spinal deformity?', '["Lordosis","Ankylosis of the sacroiliac joints","Angular kyphosis (gibbus)","Lateral scoliosis","Opisthotonos"]'::jsonb, 'Angular kyphosis (gibbus)', 'Vertebral body destruction in Pott disease produces anterior wedging and collapse, giving the characteristic angular kyphosis or gibbus deformity.'),
('6443ef18-6a83-5e02-a09c-5327ef80154a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. chelonae and M. abscessus are classified as:', '["Runyon group I photochromogens","Runyon group II scotochromogens","Runyon group III nonchromogens","Non-culturable mycobacteria","Runyon group IV rapid growers"]'::jsonb, 'Runyon group IV rapid growers', 'Both M. chelonae and M. abscessus grow rapidly and form colonies within a week, the hallmark of Runyon group IV.'),
('3abbbc1e-1295-5744-a935-f70e3965e608'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which three cardinal features suggest leprosy?', '["Lymphadenopathy, splenomegaly and rash","Polyuria and polydipsia","Arthritis, uveitis and urethritis","Anesthetic skin patches, thickened nerves, AFB in skin smears","Koplik spots, fever and cough"]'::jsonb, 'Anesthetic skin patches, thickened nerves, AFB in skin smears', 'Hypopigmented anesthetic patches, thickened peripheral nerves and demonstrable acid-fast bacilli in slit-skin smears are the cardinal diagnostic features of leprosy.'),
('464017f1-4178-50fe-b295-6bd7252cba50'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A child presents with a chronic, painless, matted mass of cervical lymph nodes and no systemic symptoms. The most likely diagnosis is:', '["Lymphoma resulting in decreased functional activity","Scrofula (tuberculous or NTM cervical lymphadenitis)","Acute parotitis mediated by specific receptor activation","Thyroglossal cyst without affecting the primary tissue pathway","Branchial cyst leading to subsequent cellular adaptation"]'::jsonb, 'Scrofula (tuberculous or NTM cervical lymphadenitis)', 'Chronic painless cervical lymphadenopathy, often with matting, in a child is scrofula, which may be tuberculous or caused by nontuberculous mycobacteria such as M. scrofulaceum.'),
('edf3fa94-8919-5b64-9067-e053b4c7d88f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'An HIV-positive patient with CD4 count of 25 cells/microliter has daily fevers, profound weight loss, anemia and diarrhea. The most likely pathogen is:', '["Mycobacterium avium complex","M. tuberculosis","Streptococcus pneumoniae","Chlamydia trachomatis","M. leprae"]'::jsonb, 'Mycobacterium avium complex', 'Fever, wasting, anemia and diarrhea with CD4 count below 50 cells/microliter indicate disseminated M. avium complex, the classic opportunistic mycobacteriosis of advanced AIDS.'),
('135806d3-5e87-5032-a507-328bcda36d81'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Tuberculous pleural effusion characteristically is:', '["A neutophilic transudate resulting in decreased functional activity","A blood-stained chylous fluid accompanied by associated clinical symptoms","A low-protein transudate mediated by specific receptor activation","A sterile serous transudate without affecting the primary tissue pathway","A lymphocytic exudate with high adenosine deaminase (ADA)"]'::jsonb, 'A lymphocytic exudate with high adenosine deaminase (ADA)', 'TB pleurisy produces an exudative effusion with a lymphocytic predominance, high protein, and elevated adenosine deaminase (ADA), often appearing as reactivation to the pleura during primary infection.'),
('46a5144a-097e-5c45-b0fa-02600fd43063'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which regimen is preferred for latent TB infection in most low-prevalence settings?', '["Pyrazinamide monotherapy resulting in decreased functional activity","Ethambutol for 1 year accompanied by associated clinical symptoms","Dapsone mediated by specific receptor activation","Short-course rifampin or rifamycin-based regimens","Streptomycin for 6 months leading to subsequent cellular adaptation"]'::jsonb, 'Short-course rifampin or rifamycin-based regimens', 'Short-course latent TB regimens using rifampin (4 months) or rifapentine-isoniazid (3 months) are preferred where feasible because of shorter duration and better completion.'),
('4fbfcece-43c0-5cc6-8a0f-96d49b872319'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which of the following is appropriate treatment for M. marinum infection?', '["Isoniazid alone","Metronidazole","Doxycycline or clarithromycin","Penicillin V","Dapsone alone"]'::jsonb, 'Doxycycline or clarithromycin', 'M. marinum is rarely resistant to doxycycline/minocycline or clarithromycin and responds to these oral agents, often combined with rifampin or ethambutol in refractory cases.'),
('2726b421-e70e-5072-9fe0-5be4b2ce9679'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which mycobacteria are classified as Runyon group I (photochromogens)?', '["M. leprae and M. tuberculosis","M. kansasii and M. marinum","M. scrofulaceum and M. gordonae","M. avium and M. ulcerans","M. fortuitum and M. chelonae"]'::jsonb, 'M. kansasii and M. marinum', 'Runyon group I photochromogens (M. kansasii, M. marinum) are slow growers that produce pigment only after exposure to light.'),
('0dc44ea4-7702-5741-bb46-63226b079483'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which toxicity is classically associated with streptomycin?', '["Ototoxicity and nephrotoxicity","Optic neuritis","Peripheral neuropathy","Hyperuricemia","Bone-marrow suppression"]'::jsonb, 'Ototoxicity and nephrotoxicity', 'Streptomycin, an aminoglycoside, is toxic to the eighth cranial nerve (vestibulocochlear) and kidneys, which limits its use in the continuation phase of TB therapy.'),
('df87174e-2422-5986-9bdd-f06a313ad100'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which finding suggests tuberculous infection of the kidney?', '["Heavy proteinuria resulting in decreased functional activity","Calcium oxalate crystals accompanied by associated clinical symptoms","Gram-negative bacilli in urine mediated by specific receptor activation","Hyaline casts only without affecting the primary tissue pathway","Sterile pyuria (pus cells with no routine organisms)"]'::jsonb, 'Sterile pyuria (pus cells with no routine organisms)', 'Renal TB classically produces sterile pyuria, i.e., abundant pus cells in urine that fails to grow routine organisms by standard culture, with hematuria and impaired renal function.'),
('05a88568-dabb-58c9-abe9-d8cf8c3ff7cf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which adverse effect is characteristic of ethambutol?', '["Deafness and tinnitus","Acute gouty arthritis","Orange discoloration of urine","Optic neuritis and red-green color blindness","Peripheral neuropathy"]'::jsonb, 'Optic neuritis and red-green color blindness', 'Ethambutol causes dose-related optic neuritis with loss of visual acuity and impaired red-green color discrimination; visual acuity and color vision should be monitored during therapy.'),
('62ef96bb-a1a6-5b2b-8787-290438bd6667'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A patient with cystic fibrosis develops worsening chronic pulmonary infection associated with a multidrug-resistant rapid grower. The most likely organism is:', '["Nocardia goodfellowii","M. scrofulaceum","M. abscessus","M. tuberculosis","M. leprae"]'::jsonb, 'M. abscessus', 'M. abscessus is a rapidly growing, highly drug-resistant mycobacterium that chronically colonizes and infects the airways of patients with cystic fibrosis.'),
('81e9f1e6-a7cc-5fd4-8e63-f010d7f3a619'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which regimen is recommended for treatment of M. avium complex infection?', '["Cefoxitin alone resulting in decreased functional activity","Clarithromycin plus ethambutol (with or without rifabutin)","Isoniazid and pyrazinamide mediated by specific receptor activation","Dapsone and clofazimine without affecting the primary tissue pathway","Penicillin and gentamicin leading to subsequent cellular adaptation"]'::jsonb, 'Clarithromycin plus ethambutol (with or without rifabutin)', 'MAC is treated with a macrolide (clarithromycin or azithromycin) plus ethambutol, often with rifabutin or a fluoroquinolone; rifabutin is preferred over rifampin in patients on antiretrovirals.'),
('12f0ee36-8afd-5274-9d68-b4af47a07ef6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A 40-year-old man has chronic cough, hemoptysis, evening fevers and night sweats; CXR shows a cavitary lesion in the right upper lobe. The most likely diagnosis is:', '["Reactivation (secondary) pulmonary tuberculosis","Lung abscess due to anaerobes","Bronchiectasis","Pulmonary embolism","Empyema secondary to pneumonia"]'::jsonb, 'Reactivation (secondary) pulmonary tuberculosis', 'Cavitation in the upper lobe with hemoptysis, fever and night sweats in a young adult is the classic presentation of reactivation (secondary) pulmonary tuberculosis.'),
('dee8fa97-d546-58da-9845-522b6ca3bbde'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which experimental system is classically used to propagate M. leprae?', '["Embryonated hen''s egg","Cell-free broth culture","Guinea pig peritoneum","Sabouraud dextrose agar","Nine-banded armadillo and mouse footpad"]'::jsonb, 'Nine-banded armadillo and mouse footpad', 'Because M. leprae resists all attempts at in vitro cultivation, it is maintained in the footpads of mice and in the nine-banded armadillo.'),
('de1f3493-9f8a-5730-aae0-5b02d06623d6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The definitive laboratory diagnosis of tuberculosis is established by:', '["Elevated ESR alone","Chest X-ray alone","History of BCG vaccination","Culture and identification of M. tuberculosis","A positive tuberculin test alone"]'::jsonb, 'Culture and identification of M. tuberculosis', 'Culture isolation with species identification (or au approved nucleic-acid amplification test) is required for definitive diagnosis, since smear and imaging are non-specific.'),
('e012d505-eab3-58b0-934e-ff6f51a52990'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. leprae differs from most mycobacteria in that it:', '["Can be grown on Lowenstein-Jensen agar","Forms spores","Cannot be cultured on artificial laboratory media","Is rapidly growing","Is a photochromogen"]'::jsonb, 'Cannot be cultured on artificial laboratory media', 'M. leprae cannot be cultivated on artificial media; it is propagated experimentally in the mouse footpad and the nine-banded armadillo.'),
('0d5dd735-ded8-54ff-9bff-845d559f19ef'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Rifampin is notable for which drug interaction characteristic?', '["Poor oral absorption","Potent hepatic enzyme induction (CYP450)","Enzyme inhibition only","No interaction with oral contraceptives","Exclusive renal excretion"]'::jsonb, 'Potent hepatic enzyme induction (CYP450)', 'Rifampin is a potent inducer of the cytochrome P-450 system, accelerating the metabolism of oral contraceptives, warfarin, methadone and antiretrovirals.'),
('883d3f8b-c7c8-5f27-a341-94830091b9dc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A diagnosis of leprosy is most reliably confirmed by:', '["Demonstrating AFB in slit-skin smears and histology","A positive tuberculin test accompanied by associated clinical symptoms","Serum VDRL titer mediated by specific receptor activation","Chest X-ray without affecting the primary tissue pathway","Positive BCG scar leading to subsequent cellular adaptation"]'::jsonb, 'Demonstrating AFB in slit-skin smears and histology', 'Demonstration of acid-fast bacilli in skin smears/biopsies (Fite stain) with suggestive clinical features confirms leprosy; lepromin and serology are adjunctive.'),
('c50a426b-1b88-501b-81de-ee4ed081fd42'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The BCG vaccine is normally administered by which route?', '["Intramuscular injection","Subcutaneous injection","Intranasal spray","Oral capsule","Intradermal injection"]'::jsonb, 'Intradermal injection', 'BCG is given by intradermal injection, typically over the deltoid, producing a characteristic small papule, pustule, and residual scar.'),
('c97d317e-046b-5234-8678-5faba606b32c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which staining procedure is used to screen sputum specimens for tubercle bacilli?', '["India ink","Grocott methenamine silver","Periodic acid-Schiff","Ziehl-Neelsen (acid-fast) stain","Gram stain"]'::jsonb, 'Ziehl-Neelsen (acid-fast) stain', 'The Ziehl-Neelsen acid-fast stain demonstrates pink-red AFB on a blue background and is the standard screening stain for mycobacteria in sputum.'),
('431efc08-6b6c-5431-8760-5bcba4bb8183'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A healthy nurse with a positive IGRA but a normal chest radiograph and no symptoms has:', '["Tuberculous meningitis","No infection","Latent tuberculosis infection","Active miliary tuberculosis","Acute tuberculous pneumonia"]'::jsonb, 'Latent tuberculosis infection', 'A positive IGRA with no clinical illness and a normal chest film indicates latent TB infection, which warrants chemoprophylaxis but is not transmissible.'),
('aaad6721-e117-5b35-8bae-25a83b34ad5f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A photochromogen differs from a scotochromogen in that a photochromogen:', '["Requires blood for growth","Produces pigment only after exposure to light","Pigments only in the dark","Never produces pigment","Grows within 24 hours"]'::jsonb, 'Produces pigment only after exposure to light', 'Photochromogens become pigmented only after light exposure; scotochromogens form pigment even when incubated in the dark, and nonchromogens do not pigment at all.'),
('086355ee-81c2-55d3-af40-cf5462f98db4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which statement about the infectivity of M. leprae is correct?', '["Only patients with untreated multibacillary disease are significantly infectious","All patients are highly infectious by droplet accompanied by associated clinical symptoms","It is transmitted mainly by sexual contact mediated by specific receptor activation","It is transmitted by mosquito bite without affecting the primary tissue pathway","There is no human reservoir leading to subsequent cellular adaptation"]'::jsonb, 'Only patients with untreated multibacillary disease are significantly infectious', 'Untreated lepromatous (multibacillary) leprosy sheds enormous numbers of bacilli from the nasal mucosa and skin, representing the main source of infection; tuberculoid patients are negligible source.'),
('933f8e4c-bacd-57fb-bb32-f9a1368fafef'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which species is a typical Runyon group IV (rapid grower)?', '["M. kansasii","M. marinum","M. avium","M. ulcerans","M. fortuitum"]'::jsonb, 'M. fortuitum', 'M. fortuitum is a rapidly growing mycobacterium that produces colonies in fewer than seven days, characteristic of Runyon group IV.'),
('a1c3ff18-8fe0-59f6-9f73-dc6aa74c5977'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A patient who handles aquaria develops chronic nodular skin lesions on the fingers. The most likely organism is:', '["M. kansasii","M. scrofulaceum","M. leprae","M. marinum","M. ulcerans"]'::jsonb, 'M. marinum', 'Exposure to fish tanks and swimming pools points to M. marinum, the cause of fish tank granuloma of the hands and arms.'),
('ab3a70d4-269f-5134-bc32-75fc62309019'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In the Ziehl-Neelsen stain, the decolorizing agent used is:', '["Ethyl acetate","Sodium hypochlorite","Acid-alcohol (3% HCl in 95% ethanol)","Acetone alone","Distilled water"]'::jsonb, 'Acid-alcohol (3% HCl in 95% ethanol)', 'After carbol fuchsin, smears are decolorized with acid-alcohol; only acid-fast organisms (which retain the dye) remain pink, while other bacteria and debris are decolorized.'),
('233301de-f635-54bf-a064-fdc7b020ccbd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The ''cord factor'' of virulent M. tuberculosis is chemically:', '["Cholesterol ester","Trehalose 6,6''-dimycolate","Lipopolysaccharide","Teichoic acid","Peptidoglycan"]'::jsonb, 'Trehalose 6,6''-dimycolate', 'Cord factor is the glycolipid trehalose 6,6''-dimycolate; it is toxic and promotes serpentine (''cord'') growth of virulent mycobacteria and contributes to granuloma formation.'),
('f80e6a2f-17cb-5ea1-ad5b-723954ef6625'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The most common extrapulmonary form of TB in young children is:', '["Cervical lymphadenitis (scrofula)","Tuberculous peritonitis","Renal tuberculosis","Urogenital tuberculosis","Tuberculous osteomyelitis of long bones"]'::jsonb, 'Cervical lymphadenitis (scrofula)', 'Cervical lymphadenitis (scrofula), usually from ingestion of the organism, is the most common extrapulmonary manifestation of tuberculosis in children.'),
('b2e447b9-4785-58eb-ae1b-17779d7e5aff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'On Lowenstein-Jensen medium, visible colonies of M. tuberculosis appear after approximately:', '["18-24 hours","2-3 days","18-24 weeks","8-12 months","2-8 weeks"]'::jsonb, '2-8 weeks', 'M. tuberculosis has a generation time of roughly 15-20 hours, so visible colonies on Lowenstein-Jensen medium take 2-8 weeks to appear, much longer than most bacteria.'),
('033d42f6-7dbb-53c9-939c-0380cec9162a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The peptides ESAT-6 and CFP-10 used in IGRA are:', '["Toxin fragments resulting in decreased functional activity","Ribosomal proteins of all mycobacteria accompanied by associated clinical symptoms","Viral antigens mediated by specific receptor activation","Secreted proteins present in M. tuberculosis but absent from BCG","Cell-wall lipids unique to M. leprae leading to subsequent cellular adaptation"]'::jsonb, 'Secreted proteins present in M. tuberculosis but absent from BCG', 'ESAT-6 and CFP-10 are RD1-region secreted proteins of M. tuberculosis complex; their absence from BCG and most environmental mycobacteria gives IGRAs their specificity.'),
('f1ec21b4-93c3-577d-9f58-a6662f297587'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which surface/virulence factor of M. tuberculosis prevents phagolysosome fusion inside macrophages?', '["Catalase-peroxidase","Urease","Sulfatides (sulfolipids)","Capsular hyaluronidase","Lipase"]'::jsonb, 'Sulfatides (sulfolipids)', 'Virulent strains produce sulfatides (sulfolipids) that inhibit fusion of lysosomes with the phagosome, allowing M. tuberculosis to survive and multiply within the macrophage.'),
('ead6896d-7fdd-5611-a29b-f6210a1b40c9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A slow-growing mycobacterium that produces no pigment and requires weeks to grow is:', '["A rapid grower","Runyon group III (nonchromogen)","Runyon group I","Runyon group II","Runyon group IV"]'::jsonb, 'Runyon group III (nonchromogen)', 'Non-pigmented, slowly growing mycobacteria such as M. avium complex and M. ulcerans belong to Runyon group III.'),
('f45afe2f-3305-5593-8ecd-3f4daca4870d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'According to the WHO, the standard multidrug therapy for multibacillary leprosy includes:', '["Dapsone, rifampin and clofazimine","Rifampin, isoniazid and ethambutol","Dapsone, pyrazinamide and streptomycin","Clarithromycin and ethambutol","Isoniazid alone"]'::jsonb, 'Dapsone, rifampin and clofazimine', 'WHO multidrug therapy for leprosy combines dapsone, rifampin and clofazimine, with duration determined by whether the patient is paucibacillary or multibacillary.'),
('0edd6595-3882-521e-bfb6-4a739b0c5171'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'An elderly patient presents with fever, weight loss and dyspnea; CXR shows diffuse bilateral 1-3 mm micro-nodules. The most likely diagnosis is:', '["Lobar pneumonia","Pulmonary embolism","Pneumothorax","Bronchial asthma","Miliary tuberculosis"]'::jsonb, 'Miliary tuberculosis', 'Diffuse millet-sized nodular shadowing with constitutional symptoms indicates hematogenous miliary tuberculosis, more likely in the elderly and immunocompromised.'),
('e2446d09-2cb7-58fe-a468-2a9d4e949dc7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which counterstain is used in the Ziehl-Neelsen method?', '["Congo red","Giemsa","Malachite green","Methylene blue","Safranin"]'::jsonb, 'Methylene blue', 'Methylene blue is the standard counterstain in the Ziehl-Neelsen procedure, staining the background blue while acid-fast bacilli remain red.'),
('47cf1f13-277f-507f-91ca-9b3cac506473'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'To which Runyon group does M. marinum belong?', '["Group II scotochromogens","An unclassified group","Group I photochromogens","Group III nonchromogens","Group IV rapid growers"]'::jsonb, 'Group I photochromogens', 'M. marinum is a slowly growing mycobacterium whose colonies turn bright yellow only after exposure to light, the photochromogen behavior of Runyon group I.'),
('f00fbb55-2102-5976-919e-1fbb378a536c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The chest X-ray of miliary tuberculosis typically shows:', '["Unilateral pleural effusion","Diffuse bilateral small (1-3 mm) millet-seed nodules","Single apical cavity","Lobar consolidation with air bronchogram","Eggshell hilar calcification"]'::jsonb, 'Diffuse bilateral small (1-3 mm) millet-seed nodules', 'Miliary TB produces a characteristic radiographic pattern of diffuse, uniformly small millet-seed nodules scattered throughout both lung fields due to hematogenous seeding.'),
('a5155ae0-e201-5c1b-8343-fc0b6f5c515a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Acid-fastness of mycobacteria is due primarily to:', '["Mycolic acid in the cell wall","Peptidoglycan cross-linking","Outer membrane porins","Capsular polysaccharide","Teichoic acid in the wall"]'::jsonb, 'Mycolic acid in the cell wall', 'The waxy mycolic acid layer of the mycobacterial cell wall resists entry of dyes and their removal by acid-alcohol, giving the acid-fast staining property.'),
('6f650dbb-86b0-5cd6-9261-922aab7264d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which condition most strongly increases the risk of reactivation of latent tuberculosis?', '["Pregnancy","Diabetes of short duration","Peptic ulcer disease","Gout","HIV infection"]'::jsonb, 'HIV infection', 'HIV-induced loss of CD4 T cells greatly increases the risk of reactivation of latent TB; TNF-alpha inhibitors, organ transplantation and other immunodeficiencies also raise the risk.'),
('ce7a1634-1fca-5f2c-b782-c1e32da2976b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In an immunocompetent host, the most common outcome of primary tuberculosis is:', '["Progressive cavitation resulting in decreased functional activity","Tuberculous meningitis accompanied by associated clinical symptoms","Death from respiratory failure mediated by specific receptor activation","Healing with fibrosis and calcification (latent infection)","Immediate miliary spread leading to subsequent cellular adaptation"]'::jsonb, 'Healing with fibrosis and calcification (latent infection)', 'Most primary TB infections in immunocompetent people are contained, healing with fibrosis and calcification and persisting as a latent infection that may reactivate later.'),
('355d2549-6357-5e8f-9f1f-396292872368'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which stain/smear offers the most sensitive rapid screening for AFB in sputum?', '["Wright stain","Auramine-rhodamine fluorescent stain","Gram stain only","India ink preparation","Giemsa stain"]'::jsonb, 'Auramine-rhodamine fluorescent stain', 'Fluorescent auramine-rhodamine (or auramine O) staining of concentrated smears is the most sensitive rapid screening method, although the Ziehl-Neelsen stain confirms morphology.'),
('1e08f5d5-2233-5c88-93ac-ec83085417eb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Use of which class of drug is associated with reactivation of latent tuberculosis?', '["TNF-alpha inhibitors (e.g., infliximab)","Beta-blockers accompanied by associated clinical symptoms","Statins mediated by specific receptor activation","Proton pump inhibitors without affecting the primary tissue pathway","Oral contraceptives leading to subsequent cellular adaptation"]'::jsonb, 'TNF-alpha inhibitors (e.g., infliximab)', 'TNF-alpha plays a central role in containing TB; TNF-alpha inhibitors such as infliximab are well documented to cause reactivation of latent tuberculosis, so screening is mandatory before use.'),
('6ea0e179-f6ac-588a-9adf-a8513c729308'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. avium complex and M. ulcerans belong to which Runyon category?', '["Group I (photochromogens)","Group II (scotochromogens)","Group IV (rapid growers)","Group V (no classification)","Group III (nonchromogens)"]'::jsonb, 'Group III (nonchromogens)', 'Runyon group III includes slowly growing, non-pigmented mycobacteria such as M. avium complex, M. ulcerans, M. haemophilum and M. malmoense.'),
('dd3915fa-4d44-504d-aba0-ed6aeb9dda61'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which staining technique is preferred to demonstrate M. leprae in tissue smears?', '["India ink resulting in decreased functional activity","Giemsa stain accompanied by associated clinical symptoms","PAS stain mediated by specific receptor activation","Modified acid-fast (Fite/Wade-Fite) stain","Gram stain leading to subsequent cellular adaptation"]'::jsonb, 'Modified acid-fast (Fite/Wade-Fite) stain', 'M. leprae is only weakly acid-fast; the modified Fite (Fite-Faraco) staining procedure, which avoids the harsher acid decolorization, is used to demonstrate it in smears and biopsies.'),
('43da8409-5add-514f-92c2-5e884e0b81f5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The preferred first-line chemoprophylaxis regimen for latent TB infection in most adults is:', '["Cefotaxime resulting in decreased functional activity","Fluconazole accompanied by associated clinical symptoms","Isoniazid (with rifampin in short-course regimens)","Dapsone monotherapy without affecting the primary tissue pathway","Clofazimine leading to subsequent cellular adaptation"]'::jsonb, 'Isoniazid (with rifampin in short-course regimens)', 'Latent TB infection is treated with isoniazid monotherapy for 6-9 months or the shorter rifampin/isoniazid or rifapentine-based regimens preferred in many settings.'),
('96c1bfbb-0114-5750-9fce-93b99eac1052'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In developing countries, the most commonly used test for rapid diagnosis of pulmonary TB is:', '["Lumbar puncture","Direct sputum smear microscopy for AFB","CT-guided biopsy","Serologic antibody testing","BCG challenge"]'::jsonb, 'Direct sputum smear microscopy for AFB', 'Direct Ziehl-Neelsen (or fluorescence) smear microscopy of sputum is the rapid, inexpensive first-line test used widely in TB-endemic settings.'),
('bb31a698-98c8-5c89-890e-7f245bab04a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The hallmark histologic lesion of tuberculosis is:', '["Caseating granuloma with Langhans giant cells","Microabscess with neutrophils","Foreign-body giant cell granuloma","Lipogranuloma with cholesterol clefts","Malakoplakia"]'::jsonb, 'Caseating granuloma with Langhans giant cells', 'TB produces granulomas with central caseous (cheese-like) necrosis surrounded by epithelioid cells, lymphocytes and multinucleated Langhans giant cells.'),
('a31474a9-29e3-5a92-8077-4be908c61b2e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Tuberculous osteomyelitis most classically affects:', '["Skull vault","Distal phalanges only","Ribs only in adults","Sternoclavicular joints","Spine and large joints (hip, knee)"]'::jsonb, 'Spine and large joints (hip, knee)', 'TB of bones and joints most often involves the spine (Pott disease) and large weight-bearing joints such as the hip and knee, producing a monoarthritis or gibbus.'),
('b965c7e8-35e2-52e1-b56a-22d64c9d2246'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Standard antimicrobial therapy for Buruli ulcer consists of:', '["Clofazimine plus dapsone for 6 months","Azithromycin alone","Metronidazole for 2 weeks","Rifampin and streptomycin for 8 weeks","Isoniazid and ethambutol for 1 year"]'::jsonb, 'Rifampin and streptomycin for 8 weeks', 'WHO recommends oral rifampin plus parenteral streptomycin daily for 8 weeks for M. ulcerans infection, with surgery added for advanced lesions.'),
('22840b75-39e8-5e8a-a926-561054be08a1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Rifampin acts against mycobacteria by:', '["Inhibiting protein synthesis at the 30S subunit","Inhibiting DNA gyrase","Inhibiting DNA-dependent RNA polymerase","Inhibiting cell-wall synthesis","Blocking folate synthesis"]'::jsonb, 'Inhibiting DNA-dependent RNA polymerase', 'Rifampin binds the beta subunit of bacterial DNA-dependent RNA polymerase and blocks transcription, which also underlies its broad interactions with drug-metabolizing enzymes.'),
('3f766f13-9c9e-5a7b-a12e-20e5e9527df1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The Ridley-Jopling classification of leprosy distinguishes patients by:', '["HLA alleles only","Cell-mediated immunity and bacterial load","Serum antibody titer only","Sputum smear count","Chest X-ray pattern"]'::jsonb, 'Cell-mediated immunity and bacterial load', 'The Ridley-Jopling spectrum ranges from tuberculoid (strong cell-mediated immunity, few bacilli) to lepromatous (anergic, heavily bacillated) poles based on host immunity.'),
('c5bc7d82-21fe-5129-8483-4dfc559fd8a6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Upgrading of skin lesions and nerve damage in borderline leprosy after starting treatment is termed:', '["Type 1 (reversal) lepra reaction","Erythema nodosum leprosum","Lucio phenomenon","Type 4 hypersensitivity","Jarisch-Herxheimer reaction"]'::jsonb, 'Type 1 (reversal) lepra reaction', 'Type 1 reversal reactions reflect an increase in cell-mediated immunity to M. leprae during treatment, causing inflammation and often painful nerve swelling.'),
('d4967420-846c-5e32-b9bf-13c4c9acedc4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which regimen is appropriate for M. fortuitum infection?', '["Isoniazid and rifampin resulting in decreased functional activity","Dapsone and clofazimine accompanied by associated clinical symptoms","Penicillin monotherapy mediated by specific receptor activation","Ethambutol alone without affecting the primary tissue pathway","Amikacin plus a fluoroquinolone such as ciprofloxacin"]'::jsonb, 'Amikacin plus a fluoroquinolone such as ciprofloxacin', 'M. fortuitum is intrinsically resistant to the standard antituberculous drugs and is treated with amikacin combined with a fluoroquinolone (or a macrolide/trimethoprim-sulfamethoxazole per susceptibility).'),
('d314aef0-f2f6-58d5-8e7a-ba0decd64cd6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Tuberculous pleurisy most often occurs:', '["Exclusively in lepromatous leprosy resulting in decreased functional activity","After BCG vaccination accompanied by associated clinical symptoms","As a sequel of influenza mediated by specific receptor activation","As a delayed hypersensitivity reaction during primary infection","Only in advanced cavitary disease leading to subsequent cellular adaptation"]'::jsonb, 'As a delayed hypersensitivity reaction during primary infection', 'TB pleurisy typically develops as a delayed hypersensitivity response to pleural-seeded bacilli, appearing within the first year after primary infection, often with a large effusion.'),
('edf41c77-bc6a-5314-92dd-b43fd7c0c30b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. bovis differs from M. tuberculosis by being intrinsically resistant to:', '["Ethambutol","Streptomycin","Pyrazinamide","Isoniazid","Rifampin"]'::jsonb, 'Pyrazinamide', 'M. bovis possesses pyrazinamidase deficiency and is naturally resistant to pyrazinamide; it is also niacin-negative, unlike M. tuberculosis.'),
('a117f913-f63c-59f2-a39f-da70efde32ce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which disease is caused by Mycobacterium leprae?', '["Kartagener syndrome","Hansen disease (leprosy)","Scrofula","Pott disease","Buruli ulcer"]'::jsonb, 'Hansen disease (leprosy)', 'Mycobacterium leprae is the obligate intracellular pathogen responsible for leprosy, which primarily damages the skin and peripheral nerves.'),
('bbaf982d-be00-5260-9ffa-b45b6b70f696'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The historic term ''consumption'' refers to:', '["Pulmonary tuberculosis","Diabetes mellitus","Cirrhosis","Nephrotic syndrome","Emphysema"]'::jsonb, 'Pulmonary tuberculosis', 'Consumption, the wasting and progressive respiratory illness with fever and hemoptysis, is the historic name for pulmonary tuberculosis.'),
('d3bb3280-91bf-58c4-80f1-6749e6e161c6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A patient has persistent sterile pyuria and hematuria with a history of fevers. The most likely diagnosis is:', '["Escherichia coli pyelonephritis","Schistosomiasis only","Cystitis","Staghorn calculus","Renal tuberculosis"]'::jsonb, 'Renal tuberculosis', 'Sterile pyuria, i.e., abundant pus cells without routine organisms on culture, is the classic hallmark of renal tuberculosis.'),
('a0fb3b87-20a4-5add-b110-afcaf165a40d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which of the following is a common extrapulmonary form of tuberculosis?', '["Lepromatous infiltration","Candidal meningitis","Tonsillar plague","Lymph node tuberculosis (lymphadenitis)","Nocardia brain abscess"]'::jsonb, 'Lymph node tuberculosis (lymphadenitis)', 'Lymph node tuberculosis (scrofula) is among the most frequent extrapulmonary manifestations, followed by pleural, genitourinary, bone/joint and meningeal disease.'),
('00b75794-7cf2-593f-b0ff-00587c84586e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In lepromatous (LL) leprosy, which finding is characteristic?', '["Positive tuberculin test","High CD4 counts","Lepromin test negative with abundant bacilli","Strong cell-mediated immunity","Few bacilli in skin smears"]'::jsonb, 'Lepromin test negative with abundant bacilli', 'Lepromatous leprosy reflects defective cell-mediated immunity against M. leprae; the lepromin reaction is negative and bacilli are numerous in tissues and skin smears.'),
('4aaa6df7-d11f-50c4-9cc4-bab838cdde92'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which supplement prevents the peripheral neuropathy caused by isoniazid?', '["Vitamin K","Pyridoxine (vitamin B6)","Folic acid","Vitamin B12","Niacin"]'::jsonb, 'Pyridoxine (vitamin B6)', 'Isoniazid causes pyridoxine (vitamin B6) deficiency, producing peripheral neuropathy; co-administration of pyridoxine prevents this complication.'),
('39fa5128-e6fb-5cf6-acdd-e7a455e7bc4d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Extensively drug-resistant TB (XDR-TB) is MDR-TB that is additionally resistant to:', '["A fluoroquinolone and at least one injectable second-line drug","Ethambutol and pyrazinamide accompanied by associated clinical symptoms","Streptomycin only mediated by specific receptor activation","Clofazimine and dapsone without affecting the primary tissue pathway","Clarithromycin and amikacin leading to subsequent cellular adaptation"]'::jsonb, 'A fluoroquinolone and at least one injectable second-line drug', 'XDR-TB is MDR-TB plus resistance to any fluoroquinolone and to at least one of the injectable second-line drugs (amikacin, kanamycin or capreomycin), leaving few treatment options.'),
('53cdec44-f8fe-504e-81b1-01471a97f6ed'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Prophylaxis against disseminated MAC in HIV is indicated when the CD4 count falls below:', '["500 cells/microliter","200 cells/microliter","1000 cells/microliter","10 cells/microliter","50 cells/microliter"]'::jsonb, '50 cells/microliter', 'Primary prophylaxis with azithromycin (or clarithromycin) is given to HIV patients with CD4 counts <50 cells/microliter to prevent disseminated M. avium complex disease.'),
('7a1e1f17-9f30-5801-9e70-367d477be949'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In lepromatous leprosy, the serum antibody response to M. leprae is:', '["Typical only of tuberculoid disease","Confined to IgE","Never detectable","High, despite defective cell-mediated immunity","Absent in all cases"]'::jsonb, 'High, despite defective cell-mediated immunity', 'Lepromatous leprosy produces a vigorous humoral (IgG/IgM) antibody response despite profound deficiency of cell-mediated immunity, mirroring the host''s inability to control intracellular bacilli.'),
('f52d600a-e2de-5dc1-9532-2507e820eda1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Bilateral caseating lesions of the adrenals causing Addison disease in a patient with tuberculosis suggest:', '["Cushing syndrome","Congenital adrenal hyperplasia","Hematogenous (miliary) spread to the adrenals","Ectopic ACTH","Adrenal vein thrombosis"]'::jsonb, 'Hematogenous (miliary) spread to the adrenals', 'AFB seed the cortices hematogenously, and progressive bilateral adrenal destruction leads to Addison disease with hypotension and hyperpigmentation.'),
('ea8c1beb-288a-59ed-9688-0d9bc73a5843'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which Runyon category applies to M. kansasii?', '["A rapidly growing nonchromogen","Group I (photochromogen)","Group II (scotochromogen)","Group III (nonchromogen)","Group IV (rapid grower)"]'::jsonb, 'Group I (photochromogen)', 'M. kansasii is a photochromogen (pigment after light exposure) and slow grower, placing it in Runyon group I.'),
('f1e59079-22eb-561a-aa4c-0dcf97917eea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Miliary tuberculosis most often complicates which form of the disease?', '["Primary or hematogenous dissemination","Chronic cavitary apical disease with healing","Skin tuberculosis","Tuberculosis of the ear","Tuberculous laryngitis"]'::jsonb, 'Primary or hematogenous dissemination', 'Miliary TB follows blood-stream dissemination, typically during early primary infection or with immunosuppression, producing multiorgan millet-seed granulomas.'),
('6e0a79c3-59e1-5b21-a991-a64c89831439'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Rapidly growing mycobacteria contaminating surgical wounds and prosthetic material are best exemplified by:', '["M. kansasii","M. gordonae","M. ulcerans","M. leprae","M. fortuitum complex"]'::jsonb, 'M. fortuitum complex', 'The M. fortuitum complex flourishes in soil and water and is notorious for contaminating wounds, catheters and implants, causing chronic post-surgical infections.'),
('cacfaea8-c534-5027-9d62-87ad6cbe08ec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Massive hemoptysis in chronic cavitary pulmonary TB most commonly results from:', '["Tuberculous bronchitis only","Coagulopathy alone","Inhalation of foreign body","Erosion of a cavity wall into a pulmonary artery","Rupture of mediastinal nodes"]'::jsonb, 'Erosion of a cavity wall into a pulmonary artery', 'In chronic TB, erosion of a cavity into an adjacent pulmonary artery branch (Rasmussen aneurysm) can cause catastrophic, often fatal hemoptysis.'),
('5f626950-afe3-51fa-9e68-9a33c2c6c95b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A ''cold abscess'' in tuberculosis refers to:', '["A hot tender fluctuant swelling resulting in decreased functional activity","An abscess over the scalp accompanied by associated clinical symptoms","A collection of pus with little acute inflammation, often from spine lymph nodes","An abscess caused by Staphylococcus without affecting the primary tissue pathway","An abscess requiring immediate drainage leading to subsequent cellular adaptation"]'::jsonb, 'A collection of pus with little acute inflammation, often from spine lymph nodes', 'Cold abscesses of TB, typically paravertebral from Pott disease, accumulate necrotic material and pus with minimal acute inflammatory signs; they may track along tissue planes.'),
('33cc0100-cead-58b4-88a3-3a8e90fdc780'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The toxin responsible for the necrotizing skin ulceration of M. ulcerans infection is:', '["Mycolactone","Cord factor","Trehalose dimycolate","Hemolysin","Botulinum toxin"]'::jsonb, 'Mycolactone', 'Mycolactone, a macrolide toxin, is the key virulence factor of M. ulcerans and causes the painless, necrotic ulceration typical of Buruli ulcer.'),
('762257c9-b760-5a1b-9293-9bc18872ef70'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A positive AFB smear of sputum:', '["Confirms M. tuberculosis specifically","Confirms NTM infection","Is specific for M. leprae","Rules out tuberculosis","Does not differentiate M. tuberculosis from NTM"]'::jsonb, 'Does not differentiate M. tuberculosis from NTM', 'All mycobacteria (and some nocardiae) are acid-fast, so a positive smear is non-specific; species confirmation requires culture and genetic probes.'),
('1236bd30-ae0e-5e22-a631-5c5d08fa65b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which organ is a frequent site of miliary tuberculous seeding?', '["Auricular cartilage","Cornified epithelium","Liver","Quadriceps muscle","Spleen capsule only"]'::jsonb, 'Liver', 'Hematogenous TB spreads to the liver, spleen, bone marrow, kidneys and meninges; hepatic involvement shows miliary granulomas on biopsy.'),
('60fad5f8-2267-5d8d-a2e1-cfc3954ae5b6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which drug combination defines the standard 6-month category I WHO regimen for new smear-positive pulmonary TB?', '["9H","2HRZE/4HR","6HR","2HRE/6HR","1HRZE/5HRE"]'::jsonb, '2HRZE/4HR', 'The standard short-course regimen is 2 months of isoniazid, rifampin, pyrazinamide and ethambutol followed by 4 months of isoniazid and rifampin (2HRZE/4HR).'),
('e7c68725-6e06-55fd-b953-d69f00b59b3c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A 3-year-old child has a painless unilateral enlarged cervical node, no fever, and no pulmonary symptoms. The most likely cause is:', '["M. scrofulaceum lymphadenitis","Infectious mononucleosis","Acute bacterial tonsillitis","Mumps","Tetanus"]'::jsonb, 'M. scrofulaceum lymphadenitis', 'Chronic painless cervical lymphadenopathy in early childhood without systemic illness is the classic presentation of NTM lymphadenitis, most often due to M. scrofulaceum.'),
('910c533f-1033-5af5-95ad-1e3af634d302'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'BCG vaccination provides the greatest protection against which forms of TB in children?', '["Renal tuberculosis","Upper lobe influenza","Tuberculous pleurisy in the elderly","Miliary TB and tuberculous meningitis","Rapidly fatal pneumonia"]'::jsonb, 'Miliary TB and tuberculous meningitis', 'BCG affords substantial protection against severe disseminated childhood TB, namely miliary disease and tuberculous meningitis, though it does not reliably prevent adult reactivation TB.'),
('f76f3c4b-a2d2-5d1c-bdb5-81fa72532b04'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which drug is recommended for primary prophylaxis of disseminated MAC infection?', '["Penicillin","Ciprofloxacin","Azithromycin","Isoniazid","Dapsone"]'::jsonb, 'Azithromycin', 'Azithromycin (or clarithromycin) is used for primary prophylaxis of MAC in patients with advanced immunosuppression, i.e., CD4 count <50 cells/microliter.'),
('44828c51-ae08-56e2-a7fe-4764997c259a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which organism is used to prepare the BCG vaccine?', '["M. avium complex","Live attenuated M. bovis","Heat-killed M. tuberculosis","Live M. bovis BCG only in children","Purified M. tuberculosis proteins"]'::jsonb, 'Live attenuated M. bovis', 'BCG is prepared by attenuation of Mycobacterium bovis; the vaccine strain is avirulent in immunocompetent recipients.'),
('3758667d-6579-51a7-b0c8-fd29d8753c75'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which nontuberculous mycobacterium requires iron-containing factor (hemin) for growth?', '["M. haemophilum","M. gordonae","M. kansasii","M. scrofulaceum","M. marinum"]'::jsonb, 'M. haemophilum', 'M. haemophilum requires X factor (hemin) in the medium and grows best at low temperatures; it causes skin, joint and disseminated infection in immunocompromised hosts.'),
('efcc0c89-8087-54f9-9f36-1a35ec83d128'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The treatment of choice for M. scrofulaceum cervical lymphadenitis is:', '["High-dose penicillin resulting in decreased functional activity","Long-term dapsone accompanied by associated clinical symptoms","Isoniazid monotherapy mediated by specific receptor activation","Radiotherapy without affecting the primary tissue pathway","Complete surgical excision of the lymph node"]'::jsonb, 'Complete surgical excision of the lymph node', 'NTM cervical lymphadenitis (M. scrofulaceum and others) responds poorly to antituberculous drugs; complete excision of the involved nodes is the preferred therapy.'),
('4d383d12-f94d-5850-865c-dcccd4ca9eeb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A major advantage of IGRAs over the tuberculin skin test is that they:', '["Can detect active disease rapidly","Differentiate pulmonary from extrapulmonary TB","Distinguish MDR-TB from drug-sensitive TB","Are not affected by prior BCG vaccination","Do not require a blood sample"]'::jsonb, 'Are not affected by prior BCG vaccination', 'Because IGRAs use antigens (ESAT-6, CFP-10) that are absent from M. bovis BCG and most nontuberculous mycobacteria, they avoid the false positives caused by BCG vaccination.'),
('995d8fe0-33f7-554f-bb48-ed2c20195fa2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Nucleic acid amplification tests (e.g., GeneXpert MTB/RIF) on sputum simultaneously provide:', '["Quantitative antibody titers","Complement fixation results","Detection of M. tuberculosis and rifampin resistance","Assessment of viral load","A lepromin test result"]'::jsonb, 'Detection of M. tuberculosis and rifampin resistance', 'GeneXpert amplifies M. tuberculosis DNA and probes for mutations that confer rifampin resistance, giving rapid molecular confirmation and a surrogate for MDR-TB.'),
('4c58f0ec-c106-56a5-9ef9-a1948241c921'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A young man with suspected tuberculosis develops back pain and a gibbus deformity of the thoracic spine. This combination most strongly suggests:', '["Lumbar disc prolapse","Pott disease (tuberculous spondylitis)","Ankylosing spondylitis","Vertebral metastasis","Scheuermann disease"]'::jsonb, 'Pott disease (tuberculous spondylitis)', 'Back pain with progressive angular kyphosis in a patient with TB is Pott disease; vertebral body destruction causes the gibbus and may cause cord compression.'),
('fe63b419-de12-50b2-9050-39ae2491558e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which Runyon group contains M. avium complex and M. ulcerans?', '["Group III (nonchromogen)","Group I (photochromogen)","Group II (scotochromogen)","Group IV (rapid grower)","Group V organisms"]'::jsonb, 'Group III (nonchromogen)', 'Slowly growing, non-pigmented mycobacteria such as M. avium complex, M. ulcerans and M. haemophilum are assigned to Runyon group III.'),
('a7fc85f5-5c0a-5868-a534-c158c48743c9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'The earliest functional deficit in leprosy is usually:', '["Upper motor neuron weakness resulting in decreased functional activity","Loss of taste accompanied by associated clinical symptoms","Deafness mediated by specific receptor activation","Cerebellar ataxia without affecting the primary tissue pathway","Sensory loss (anesthesia) in affected skin areas"]'::jsonb, 'Sensory loss (anesthesia) in affected skin areas', 'M. leprae damages cutaneous sensory nerves, so hypopigmented patches with diminished sensation to pain and temperature are the earliest and most typical findings.'),
('c46d5ef8-2fde-5225-b5ad-b854290f22b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Pyridoxine is co-administered with isoniazid mainly to prevent:', '["Nephrotoxicity","Hyperuricemia","Orange body fluids","Peripheral neuropathy","Optic neuritis"]'::jsonb, 'Peripheral neuropathy', 'Isoniazid depletes pyridoxine by increasing its excretion, causing a sensory-motor peripheral neuropathy; supplemental pyridoxine prevents this unless the patient has a seizure disorder on phenytoin.'),
('18446468-4eab-5550-8f1b-d6d203628e41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Adjunctive corticosteroid therapy is of proven benefit in which form of TB?', '["Tuberculous lymphadenitis with allergy","Skin TB with adequate immunity","Tuberculous meningitis","Pulmonary cavities without symptoms","Asymptomatic primary complex"]'::jsonb, 'Tuberculous meningitis', 'Corticosteroids reduce mortality and neurologic sequelae in tuberculous meningitis (and relieve constriction in pericarditis), where the host inflammatory response is damaging.'),
('c4f34ae8-5382-5c1e-96b7-79fcd9017131'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'On Ziehl-Neelsen staining of a sputum smear, M. tuberculosis appears as:', '["Brown spore-forming rods","Red/pink bacilli against a blue background","Blue bacilli against a pink background","Green fluorescent rods","Purple diplococci"]'::jsonb, 'Red/pink bacilli against a blue background', 'Acid-fast bacilli that retain carbol fuchsin appear red or pink; the methylene blue counterstain gives the background a blue appearance.'),
('898a0cf6-c4c9-5092-851d-2516cb7c1dd9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In tuberculoid (TT) leprosy, which feature is typical?', '["Lepromin test positive with a paucity of bacilli","Diffuse infiltration with numerous bacilli","Lepromin-negative with florid nodules","Gross anergy to all antigens","Negative on Fite stain"]'::jsonb, 'Lepromin test positive with a paucity of bacilli', 'Tuberculoid leprosy is the resistant pole with strong cell-mediated immunity: the lepromin test is positive and very few bacilli are demonstrable in lesions.'),
('5addf183-9cf0-52eb-91f3-56fb000ede2d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. leprae characteristically multiplies best at:', '["Core body temperature 37°C resulting in decreased functional activity","56°C for long periods accompanied by associated clinical symptoms","4°C only mediated by specific receptor activation","-20°C storage without affecting the primary tissue pathway","Lower temperatures (about 27-30°C) in cooler body sites"]'::jsonb, 'Lower temperatures (about 27-30°C) in cooler body sites', 'M. leprae grows optimally at cooler temperatures, which is why lesions favor the nose, ears, hands and feet; visceral and warmer sites are relatively spared.'),
('9d3c3aab-9619-5837-baff-51ce1748f278'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Severe painful erythematous nodules and vasculitis in a patient with lepromatous leprosy on multidrug therapy represent:', '["Lepromatous infiltration resulting in decreased functional activity","Secondary syphilis accompanied by associated clinical symptoms","Herpes zoster mediated by specific receptor activation","Erythema nodosum leprosum (type 2 lepra reaction)","Type 1 reversal reaction only leading to subsequent cellular adaptation"]'::jsonb, 'Erythema nodosum leprosum (type 2 lepra reaction)', 'Erythema nodosum leprosum is a type 2 lepra reaction with immune-complex-mediated erythematous nodules, fever and neuritis, treated with thalidomide and steroids.'),
('c6ff4268-1ca9-533f-9475-8da793514243'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which regimen is standard for M. kansasii infection?', '["Cefoxitin and doxycycline","High-dose pyrazinamide","Rifampin plus isoniazid and ethambutol","Dapsone and clofazimine","Clarithromycin plus amikacin alone"]'::jsonb, 'Rifampin plus isoniazid and ethambutol', 'M. kansasii requires a rifampin-based regimen (rifampin, isoniazid, ethambutol); rifampin is the key drug, and its withdrawal commonly causes relapse.'),
('734d023f-0342-5e1c-8d3b-d6a5aa4f8fad'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Tuberculous meningitis is characterized by an exudate located mainly:', '["In the subdural space","Over the base of the brain","Over the cerebral convexities","In the lateral ventricles","Within the spinal cord only"]'::jsonb, 'Over the base of the brain', 'TB meningitis produces a thick basal (basilar) exudate with cranial nerve palsies and hydrocephalus, typically complicating miliary or disseminated TB, often in children.'),
('32990caf-b40f-512c-bd76-e3f51b906845'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A patient with diffuse skin infiltration, nodules, madarosis and lepromin-test negativity most likely has:', '["Tuberculoid leprosy","Borderline lepromatous leprosy only in children","Reactional tuberculosis","Pokiloderma","Lepromatous leprosy"]'::jsonb, 'Lepromatous leprosy', 'Diffuse infiltration, nodular lesions and a negative lepromin test with abundant bacilli define the anergic lepromatous (multibacillary) pole of leprosy.'),
('96dfe337-e887-5b19-8131-91eb955baec9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Infection of an indwelling central venous catheter line with an environmental rapid grower is most likely due to:', '["M. gordonae","M. ulcerans","M. avium","M. chelonae","M. kansasii"]'::jsonb, 'M. chelonae', 'M. chelonae is a rapidly growing species that flourishes in water and is a recognized cause of line-related and post-operative infections in immunocompromised and hospitalized patients.'),
('c85d5e40-03fd-5d92-adc0-f0d2a01fd0c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which extrapulmonary site of TB can present with Addison disease?', '["Epididymis","Fallopian tubes","Adrenal glands","Pericardium","Meninges"]'::jsonb, 'Adrenal glands', 'Hematogenous spread of TB to the adrenal glands causes bilateral adrenal destruction and primary adrenal insufficiency (Addison disease) in developed countries and increasingly TB.'),
('0cd6f4bc-e0f6-5e5a-98c1-9156724b6b7e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which constellation typifies miliary tuberculosis?', '["Hematuria with back pain resulting in decreased functional activity","Fever, hepatosplenomegaly, anemia and pulmonary nodules","Painless leg ulcers mediated by specific receptor activation","Vesicular rash without affecting the primary tissue pathway","Joint swelling only leading to subsequent cellular adaptation"]'::jsonb, 'Fever, hepatosplenomegaly, anemia and pulmonary nodules', 'Miliary TB presents with high fevers, wasting, anemia, hepatosplenomegaly and diffuse millet-seed nodules; choroidal tubercles may be seen on fundoscopy.'),
('2f19ecbe-95c2-5c4d-9ecb-7d4c78e75190'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A positive tuberculin skin test indicates that the person:', '["Has been infected with M. tuberculosis (may be latent)","Always has active infectious TB","Is immune to TB for life","Has never been exposed to mycobacteria","Has received BCG immunity exclusively"]'::jsonb, 'Has been infected with M. tuberculosis (may be latent)', 'A positive PPD merely indicates prior infection or a reactive cellular immune response; it does not discriminate latent infection from active disease, which requires clinical and radiologic evaluation.'),
('a9080763-62cc-525b-8e5e-33ee64289245'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which describes the microscopic appearance of M. tuberculosis?', '["Encapsulated cocci on Gram stain","Filamentous branching rods","Broad-based budding yeast","Helical spirochetes","Acid-fast (pink) bacilli on Ziehl-Neelsen stain"]'::jsonb, 'Acid-fast (pink) bacilli on Ziehl-Neelsen stain', 'Mycobacteria resist decolorization with acid-alcohol because of the mycolic acid-rich wall, so M. tuberculosis stains pink/red in the Ziehl-Neelsen procedure.'),
('4797c667-393f-5300-afea-1763b237b9ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which features define Runyon group II (scotochromogens)?', '["Never produce pigment","Grow in less than 7 days","Are nonculturable","Produce pigment when grown in the dark","Require light to produce pigment"]'::jsonb, 'Produce pigment when grown in the dark', 'Scotochromogens such as M. scrofulaceum and M. gordonae synthesize yellow-orange pigment even when incubated in the dark.'),
('84f0bcb9-4a8c-5216-aa4e-0f14c3fca709'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which combination is used to treat M. chelonae infection?', '["Dapsone alone resulting in decreased functional activity","Rifampin alone accompanied by associated clinical symptoms","Clarithromycin plus tobramycin (or amikacin)","Isoniazid and ethambutol without affecting the primary tissue pathway","High-dose penicillin leading to subsequent cellular adaptation"]'::jsonb, 'Clarithromycin plus tobramycin (or amikacin)', 'M. chelonae is intrinsically resistant to the standard anti-TB drugs; clarithromycin combined with an aminoglycoside such as tobramycin/amikacin (per susceptibility) is the standard approach.'),
('99df91c4-27c0-5aa8-879c-146fd352c0d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which medium is the standard for culture of M. tuberculosis?', '["Lowenstein-Jensen (egg-based) medium","Blood agar","MacConkey agar","Sabouraud dextrose agar","Thayer-Martin agar"]'::jsonb, 'Lowenstein-Jensen (egg-based) medium', 'M. tuberculosis is cultured on Lowenstein-Jensen (egg-based) medium; colonies of the slowly growing organism appear only after several weeks.'),
('4bde0c4f-12dd-529a-a824-ffc0910f04ca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. abscessus is classified as a Runyon group:', '["I (photochromogen)","II (scotochromogen)","III (nonchromogen)","A nonculturable species","IV (rapid grower)"]'::jsonb, 'IV (rapid grower)', 'M. abscessus is a rapidly growing mycobacterium (Runyon group IV) characterized by resistance to many first-line agents.'),
('8d54ef6b-48dd-56c3-a2f8-ff88ae6bcc5e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A child exposed to a sputum-smear-positive adult with TB has a primary complex. Which statement is correct?', '["The Ghon complex never heals","Cavitation always develops immediately","The child is usually not infectious to others","The child should not receive chemoprophylaxis","BCG is contraindicated"]'::jsonb, 'The child is usually not infectious to others', 'Primary TB in a child is typically paucibacillary and non-infectious; the Ghon complex usually heals, and chemoprophylaxis or treatment is given according to the protocol.'),
('57c5a8ef-ae2b-57b3-8033-8da8796a42ca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'MAC most commonly causes which syndrome in patients with advanced AIDS?', '["Lepromatous infiltration","Disseminated infection with bacteremia","Post-surgical wound abscess","Fish tank granuloma","Cervical lymphadenitis in a child"]'::jsonb, 'Disseminated infection with bacteremia', 'In advanced AIDS (CD4 <50 cells/microliter), M. avium complex disseminates with sustained bacteremia, fever, night sweats, weight loss and multiorgan involvement.'),
('1347f214-141a-5c37-a392-a9fe238b0ca5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which is the principal mode of transmission of M. tuberculosis?', '["Inhalation of airborne droplet nuclei","Fecal-oral contamination","Mosquito bite","Sexual contact","Transfusion of infected blood"]'::jsonb, 'Inhalation of airborne droplet nuclei', 'M. tuberculosis is spread by inhalation of small (<5 micrometer) droplet nuclei generated when a patient with pulmonary or laryngeal TB coughs or sneezes; the bacillus then lodges in the alveoli.'),
('f553893d-05c6-5c23-b8f4-7a7e50fff503'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In primary pulmonary tuberculosis the parenchymal focus most characteristically lies in:', '["Extreme lung apex","Perihilar region only","Diaphragmatic surface","Anterior mediastinum","Lower or middle lung zones (subpleural)"]'::jsonb, 'Lower or middle lung zones (subpleural)', 'The primary (Ghon) focus of TB is usually subpleural in the lower or middle zones of the lung, which are the best-ventilated areas that receive the inhaled bacilli.'),
('12de5f8d-17d2-596f-a62a-b3869708f056'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which regimen is typically used for M. abscessus infection?', '["Dapsone and clofazimine","Penicillin and gentamicin","Fluconazole monotherapy","Macrolide plus amikacin and cefoxitin","Isoniazid, rifampin and ethambutol"]'::jsonb, 'Macrolide plus amikacin and cefoxitin', 'Because M. abscessus is resistant to standard anti-TB drugs, therapy combines a macrolide (clarithromycin/azithromycin) with parenteral agents such as amikacin and cefoxitin, guided by susceptibility testing.'),
('af00664f-26a4-50fd-af8a-53afc719cddb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which classification is correct for M. ulcerans?', '["Runyon group IV (rapid grower)","Non-culturable species","Runyon group III (nonchromogen)","Runyon group I (photochromogen)","Runyon group II (scotochromogen)"]'::jsonb, 'Runyon group III (nonchromogen)', 'M. ulcerans is a slowly growing, non-pigmented mycobacterium, i.e., a Runyon group III (nonchromogen) organism.'),
('afee1893-0932-579a-8d3f-b0e2b1ead8bc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which adverse effect is most characteristic of pyrazinamide?', '["Hyperuricemia (gouty arthritis)","Optic neuritis","Peripheral neuropathy","Reddish-orange body fluids","Hearing loss"]'::jsonb, 'Hyperuricemia (gouty arthritis)', 'Pyrazinamide inhibits uric acid excretion, causing hyperuricemia that may precipitate gouty arthritis; it is also hepatotoxic at higher doses.'),
('3af55e4a-5647-5c4f-a8fa-de9af5ce193e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A patient with culture-proven TB but repeatedly smear-negative sputum is most likely to have:', '["MDR-TB always resulting in decreased functional activity","Lepromatous leprosy accompanied by associated clinical symptoms","Infection with M. leprae mediated by specific receptor activation","A fungal infection without affecting the primary tissue pathway","Extrapulmonary or smear-negative pulmonary TB"]'::jsonb, 'Extrapulmonary or smear-negative pulmonary TB', 'Smear-negative, culture-positive (or PCR-positive) pulmonary TB is common, especially with minimal disease or extrapulmonary involvement; treatment should be started on clinical grounds.'),
('993dde79-d8a2-578c-be2e-6d934745788b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In an otherwise healthy adult without risk factors, a positive tuberculin test is an induration of at least:', '["3 mm","15 mm","20 mm","10 mm","1 mm"]'::jsonb, '10 mm', 'Induration of >=10 mm is generally considered positive in healthy persons without special risk factors; the threshold is lowered to 5 mm in HIV, close contacts and immunosuppressed patients.'),
('35289530-4613-5ff7-a1c7-0932e7d30a4b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which clinical feature is characteristic of leprosy?', '["Painful vesicular rash","Myalgia with rhabdomyolysis","Thickened peripheral nerves with anesthetic skin lesions","Ascending flaccid paralysis","Cranial polyneuritis at onset"]'::jsonb, 'Thickened peripheral nerves with anesthetic skin lesions', 'M. leprae invades Schwann cells of peripheral nerves, causing palpable nerve thickening, anesthesia and trophic changes in the affected skin; nerve damage is the hallmark disability of leprosy.'),
('3614c6e0-fc1f-5fc3-9eb4-663ff0189168'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. ulcerans is classified in which Runyon group?', '["Group I (photochromogen)","Group II (scotochromogen)","Group IV (rapid grower)","It cannot be classified","Group III (nonchromogen)"]'::jsonb, 'Group III (nonchromogen)', 'M. ulcerans is a slowly growing, non-pigmented mycobacterium, that is, a Runyon group III (nonchromogen) organism.'),
('04577d07-bedc-5cfd-9ff8-8c5eccfef119'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. fortuitum belongs to which Runyon group?', '["Group III (nonchromogen)","Group V (slow grower)","Group IV (rapid grower)","Group I (photochromogen)","Group II (scotochromogen)"]'::jsonb, 'Group IV (rapid grower)', 'M. fortuitum is a rapidly growing mycobacterium (Runyon group IV) that yields colonies in fewer than 7 days.'),
('dbe2b437-751c-57bd-98d3-5d9437848c10'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'A rapidly growing, intrinsically multidrug-resistant mycobacterium causing skin abscesses is best treated with:', '["Ethambutol plus pyrazinamide","Dapsone monotherapy","Penicillin V","Clarithromycin, amikacin and cefoxitin","Isoniazid alone"]'::jsonb, 'Clarithromycin, amikacin and cefoxitin', 'M. abscessus is one of the most antimicrobial-resistant mycobacteria and requires combination therapy with a macrolide plus intravenous amikacin, cefoxitin or imipenem.'),
('de576d41-f70b-5370-8669-3227bb1da34b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. scrofulaceum is best classified as a Runyon group:', '["IV (rapid grower)","No group is applicable","II (scotochromogen)","I (photochromogen)","III (nonchromogen)"]'::jsonb, 'II (scotochromogen)', 'M. scrofulaceum is a slowly growing scotochromogen (Runyon group II) that produces yellow-orange pigment even in the dark.'),
('f57c2d1e-bb70-5c1d-8c50-fc1bbad7dcfa'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. marinum belongs to which Runyon group?', '["It is not a mycobacterium","Group I (photochromogen)","Group II (scotochromogen)","Group III (nonchromogen)","Group IV (rapid grower)"]'::jsonb, 'Group I (photochromogen)', 'M. marinum is a slowly growing photochromogen (Runyon group I) that acquires yellow pigment on light exposure.'),
('3d729794-5250-54a8-af1d-40562e6d274a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'M. chelonae is a Runyon group:', '["I (photochromogen)","II (scotochromogen)","III (nonchromogen)","Non-culturable organism","IV (rapid grower)"]'::jsonb, 'IV (rapid grower)', 'M. chelonae is a rapidly growing mycobacterium (Runyon group IV) with colonies forming within 7 days.'),
('f2715c01-61a6-57b5-83e0-22fa5c23c517'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which cell-wall glycolipid produces serpentine cord formation in virulent M. tuberculosis?', '["Lipoarabinomannan","Sulfolipid","Wax D","Muramyl dipeptide","Trehalose dimycolate"]'::jsonb, 'Trehalose dimycolate', 'Cord factor (trehalose 6,6''-dimycolate) causes the bacteria to grow in parallel serpentine cords and is a major virulence factor of M. tuberculosis.'),
('9ea463e9-89cb-579b-b2cb-65c886272c3c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'Which drug is essential to prevent relapse in M. kansasii treatment?', '["Clofazimine","Fluoroquinolone","Rifampin","Ethionamide","Dapsone"]'::jsonb, 'Rifampin', 'Rifampin is the cornerstone of M. kansasii therapy; regimens omitting or discontinuing rifampin are associated with a high relapse rate.'),
('a5fa5657-c95c-50a4-b726-a4aa734d2474'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Mycobacteria Atypical - Mycobacteria', 'In an AIDS patient taking protease inhibitors, which rifamycin is preferred for M. avium complex therapy?', '["Rifampin only","No rifamycin needed","Rifapentine daily","Rifampin half dose","Rifabutin instead of rifampin"]'::jsonb, 'Rifabutin instead of rifampin', 'Rifabutin is substituted for rifampin because rifampin is a potent enzyme inducer that accelerates clearance of protease inhibitors, whereas rifabutin interacts less.'),
('f1c46e0d-e3cb-5345-a1c6-4b8e38987c83'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Vincent angina (trench mouth), a painful acute necrotizing ulcerative gingivitis, is classically caused by fusospirochetal organisms; the fusiform bacillus most often implicated is:', '["Fusobacterium","Clostridium","Staphylococcus","Streptococcus","Bacteroides"]'::jsonb, 'Fusobacterium', 'Vincent angina results from the synergistic overgrowth of fusiform bacilli (Fusobacterium nucleatum) and anaerobic oral spirochetes (Borrelia vincentii), producing a necrotizing gingival lesion with a foul odor and gray pseudomembrane.'),
('355f191b-06cb-5e89-b181-ff067adef737'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium tetani is best characterized as a:', '["GP spore-forming rod","Spirochete","Acid-fast","GP coccus","GN rod"]'::jsonb, 'GP spore-forming rod', 'Clostridium tetani is a gram-positive, strictly anaerobic rod with a terminal spore (drumstick appearance); its tetanospasmin toxin produces spastic paralysis.'),
('4d7040be-7192-549f-a7f4-7b2c23d86304'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Peptostreptococcus is best classified as a:', '["GP rod","GN coccus","GP anaerobic coccus","Spirochete","GN rod"]'::jsonb, 'GP anaerobic coccus', 'Peptostreptococcus is a gram-positive anaerobic coccus that is part of the normal flora of the gut, female genital tract and oral cavity, causing mixed anaerobic infections.'),
('238a89e6-474d-5c1f-8372-d03606e525b5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Fusobacterium is best classified as:', '["GP coccus","Spirochete","GN aerobic rod","GN anaerobic rod","GP rod"]'::jsonb, 'GN anaerobic rod', 'Fusobacterium is a gram-negative anaerobic spindle-shaped rod of the oral and intestinal flora, classically associated with Vincent angina and Lemierre syndrome.'),
('2ea345c4-eba2-5a29-8bef-c07cb825af32'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Porphyromonas is best classified as:', '["Acid-fast","Spirochete","Aerobic","GN anaerobic rod","GP coccus"]'::jsonb, 'GN anaerobic rod', 'Porphyromonas is a black-pigmented gram-negative anaerobic rod of the oral cavity, strongly associated with chronic periodontitis.'),
('36d7dbc1-3562-538f-82e1-7060d8d7ea16'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Borrelia recurrentis is the causative agent of:', '["Leptospirosis","Lyme disease","Syphilis","Relapsing fever","Yaws"]'::jsonb, 'Relapsing fever', 'Borrelia recurrentis causes epidemic louse-borne relapsing fever, with recurring febrile episodes produced by antigenic variation of its surface proteins.'),
('9686b084-2c8b-5f21-beb3-ec047bef47cc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Antibiotic-associated pseudomembranous colitis is classically caused by Clostridioides difficile; the resulting disease is:', '["Botulism","Tetanus","Pseudomembranous colitis","Food poisoning","Gas gangrene"]'::jsonb, 'Pseudomembranous colitis', 'Clostridioides difficile elaborates toxins A and B that damage the colonic mucosa after broad-spectrum antibiotics, producing characteristic yellow-white pseudomembranes.'),
('ff825e3b-444b-50ee-9809-4394b82fd089'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Penicillin is the preferred antimicrobial for syphilis because it is:', '["Second-line therapy","DOC for all stages","Congenital syphilis only","Primary syphilis only","Reserved for penicillin-allergic patients"]'::jsonb, 'DOC for all stages', 'Parenteral penicillin G is the drug of choice for all stages of syphilis, including congenital and neurosyphilis; doxycycline or ceftriaxone are alternatives only in penicillin allergy.'),
('eb28d345-8f73-5500-bb0c-f4a7d7d466d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis, the dominant anaerobe of the colon, is best classified as a:', '["GP rod","GN aerobic rod","Spirochete","GP anaerobic coccus","GN anaerobic rod"]'::jsonb, 'GN anaerobic rod', 'Bacteroides species are the most abundant obligate anaerobes of the colon and are classified as gram-negative anaerobic rods.'),
('023d8d2a-8fed-520a-a944-c7c1c426bd41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which disease is characterized by descending symmetric flaccid paralysis due to blockade of acetylcholine release at the neuromuscular junction?', '["Food poisoning","Pseudomembranous colitis","Tetanus","Gas gangrene","Botulism (flaccid paralysis)"]'::jsonb, 'Botulism (flaccid paralysis)', 'Botulinum toxin cleaves SNARE proteins, blocking presynaptic acetylcholine release and producing a descending symmetric flaccid paralysis without fever.'),
('bb691e69-4d6a-529b-b45e-83610b048c9b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The diagnostic hallmark of actinomycosis, a chronic suppurative infection, is the presence of:', '["Granuloma","Sulfur granules in pus","Cavitation","Caseation","Abscess"]'::jsonb, 'Sulfur granules in pus', 'Actinomycosis drains purulent sinus tracts containing yellow ''sulfur granules'', macroscopic clumps of tangled gram-positive branching filaments.'),
('cc8316e5-a531-5a72-a4a9-bfffd3468630'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella is best classified as a:', '["GN anaerobic coccus","GP coccus","GN rod","GP rod","Spirochete"]'::jsonb, 'GN anaerobic coccus', 'Veillonella is a gram-negative anaerobic coccus and the most common coccus of the oral cavity, also found in the intestinal flora.'),
('20571ede-b9d1-51a4-a955-5f4c20edf1e7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which of the following is a recognized risk factor for Clostridioides difficile infection?', '["Antibiotic use (clindamycin)","PPI use","Surgery","All of the above","Hospitalization"]'::jsonb, 'All of the above', 'Antibiotic exposure (especially clindamycin), proton-pump inhibition, hospitalization and gastrointestinal surgery all predispose to Clostridioides difficile overgrowth.'),
('56f75752-4ef1-58c3-90c6-476f3a07aa59'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'A chronic suppurative infection that characteristically discharges yellow grainy sulfur granules in pus is caused by:', '["Granuloma","Cavitation","Abscess","Caseation","Sulfur granules in pus"]'::jsonb, 'Sulfur granules in pus', 'The presence of sulfur granules in draining pus is the classic diagnostic clue to actinomycosis, the chronic infection caused by Actinomyces species.'),
('47567cce-c143-50b8-8b80-0bd68b5d231d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Botulinum toxin produces its paralytic effect by:', '["Enterotoxin","Cytotoxin","Blocks glycine","Blocks ACh release (flaccid)","Lecithinase"]'::jsonb, 'Blocks ACh release (flaccid)', 'Botulinum toxin is a zinc endopeptidase that cleaves SNARE proteins, preventing acetylcholine exocytosis at the neuromuscular junction and causing flaccid paralysis; blocking glycine release is the spastic mechanism of tetanospasmin.'),
('2dc3c3b1-8d61-5690-96af-7205158b5215'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium tetani belongs to which morphologic and staining group?', '["Spirochete","GP coccus","GP spore-forming rod","GN rod","Acid-fast"]'::jsonb, 'GP spore-forming rod', 'Clostridium tetani is a gram-positive anaerobic, terminal spore-forming rod; spores germinate in contaminated wounds and release tetanospasmin.'),
('2e69f7ef-f397-5c38-9f5f-51805cb49fef'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Human leptospirosis is transmitted most commonly through contact with:', '["Urine of infected animals","Tick bite accompanied by associated clinical symptoms","Mosquito mediated by specific receptor activation","Sexual without affecting the primary tissue pathway","Blood leading to subsequent cellular adaptation"]'::jsonb, 'Urine of infected animals', 'Leptospira are shed in the urine of chronically infected rodents, cattle and dogs; humans acquire infection through contaminated water or soil via skin or mucosa.'),
('81dba19e-3025-5f82-bc75-69dfa4378d58'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Lyme disease is transmitted by the bite of the:', '["Dermacentor","Mosquito","Ixodes tick","Flea","Amblyomma"]'::jsonb, 'Ixodes tick', 'Borrelia burgdorferi, the agent of Lyme disease, is transmitted by Ixodes (deer) ticks; Amblyomma and Dermacentor transmit other borelial and rickettsial diseases.'),
('f18b004f-11b3-5fa0-a2ca-d1a801d52952'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella, a black-pigmented anaerobic bacillus of the oral and vaginal flora, is best classified as a:', '["Acid-fast","Aerobic","Spirochete","GN anaerobic rod","GP coccus"]'::jsonb, 'GN anaerobic rod', 'Prevotella is a gram-negative anaerobic rod, saccharolytic and black-pigmented, that causes periodontal and pelvic infections among others.'),
('378e0f19-e965-5c7d-ba7d-2ade378ca5f1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The major exotoxin of Clostridium perfringens responsible for the tissue destruction of gas gangrene is:', '["Lecithinase (phospholipase C)","Botulinum toxin","Neurotoxin","Enterotoxin","Tetanospasmin"]'::jsonb, 'Lecithinase (phospholipase C)', 'The alpha-toxin (lecithinase, phospholipase C) of C. perfringens disrupts cell membranes, causing hemolysis and the rapid myonecrosis characteristic of gas gangrene.'),
('ae381af8-835f-578c-8d4e-2ead5b937492'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Cutibacterium (Propionibacterium) acnes, a gram-positive anaerobic rod of the skin, is classically associated with:', '["Acne vulgaris","Meningitis","Pneumonia","UTI","Osteomyelitis"]'::jsonb, 'Acne vulgaris', 'Cutibacterium acnes colonizes sebaceous follicles, hydrolyzes sebum to free fatty acids, and drives the inflammation of acne vulgaris.'),
('2f66b4e0-79ba-59d8-91bb-4e37a1314c12'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The skin commensal Cutibacterium (Propionibacterium) acnes is best known for its role in:', '["Pneumonia","Meningitis","Acne vulgaris","UTI","Osteomyelitis"]'::jsonb, 'Acne vulgaris', 'Cutibacterium acnes is the organism classically implicated in acne vulgaris through follicular colonization, lipase generation of free fatty acids and inflammation.'),
('1661c5ef-9555-558c-8f3e-7edbf7d1c199'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Porphyromonas gingivalis is best classified as a:', '["Acid-fast","Spirochete","GN anaerobic rod","Aerobic","GP coccus"]'::jsonb, 'GN anaerobic rod', 'Porphyromonas gingivalis is a black-pigmented gram-negative anaerobic rod of the subgingival flora and a major agent of adult periodontitis.'),
('df57b638-5470-5094-a530-b9f39b1be868'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridioides difficile causes colitis primarily through the action of:', '["Lecithinase resulting in decreased functional activity","Toxin A (enterotoxin) and B (cytotoxin)","Tetanospasmin mediated by specific receptor activation","Neurotoxin without affecting the primary tissue pathway","Botulinum toxin leading to subsequent cellular adaptation"]'::jsonb, 'Toxin A (enterotoxin) and B (cytotoxin)', 'C. difficile toxins A (enterotoxin) and B (cytotoxin) glucosylate Rho GTPases, disrupting the gut epithelium and producing the pseudomembranes of pseudomembranous colitis.'),
('43473565-5419-5d29-8604-67e9514ae66f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The spirochete responsible for Weil disease, the severe icteric form of leptospirosis, belongs to the species:', '["Leptospira interrogans","Borrelia recurrentis","Treponema pallidum","Borrelia burgdorferi","Leptospira biflexa"]'::jsonb, 'Leptospira interrogans', 'Pathogenic leptospires are classified under Leptospira interrogans sensu lato; Weil disease is their severe form with jaundice, renal failure and hemorrhage, while Leptospira biflexa is saprophytic.'),
('02b819fc-51e3-5f9d-a574-905f9cdd8406'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella species, a gram-negative anaerobic coccus, are characteristically found in the:', '["Skin resulting in decreased functional activity","Air accompanied by associated clinical symptoms","Water mediated by specific receptor activation","Oral and gut flora","Soil leading to subsequent cellular adaptation"]'::jsonb, 'Oral and gut flora', 'Veillonella is a normal commensal of the human oral cavity and gastrointestinal tract.'),
('9e18f03b-7ffe-5088-9b0d-722449b80e73'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides species, the most abundant bacteria of the normal colon, are best classified as:', '["GN aerobic rod","Spirochete","GP rod","GP coccus","GN anaerobic rod"]'::jsonb, 'GN anaerobic rod', 'Bacteroides, especially B. fragilis, are the predominant obligate anaerobes of the colon and are gram-negative anaerobic rods.'),
('9de146a3-a019-5660-8d91-cd2a5d5ffb65'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Morphologically, Clostridium tetani is best described as a:', '["GP spore-forming rod","Acid-fast","Spirochete","GP coccus","GN rod"]'::jsonb, 'GP spore-forming rod', 'C. tetani is a gram-positive anaerobic rod with a terminal, drumstick-shaped spore; it does not survive prolonged oxygen exposure and is never acid-fast.'),
('4b7aa6e4-3719-5677-8e28-c91945adb226'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Tetanospasmin produces spastic paralysis by blocking the release of which inhibitory neurotransmitters at the spinal cord?', '["Glycine and GABA","Acetylcholine","Norepinephrine","Dopamine","Serotonin"]'::jsonb, 'Glycine and GABA', 'Tetanospasmin cleaves vesicular SNARE proteins in inhibitory Renshaw neurons, blocking release of glycine and GABA and leaving motor reflexes unopposed, producing lockjaw and generalized spasticity.'),
('a4745e7c-45e2-5bd4-830e-019eff93a1f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The treatment of choice for leptospirosis is:', '["Clindamycin","Azithromycin","Penicillin or doxycycline","Vancomycin","Metronidazole"]'::jsonb, 'Penicillin or doxycycline', 'Leptospirosis responds to penicillin G or doxycycline given early in the illness; doxycycline is also used for chemoprophylaxis after high-risk exposure.'),
('de2f68be-9982-5d1a-8c94-35c557244574'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Yaws, a nonvenereal treponemal disease of childhood, characteristically produces:', '["Cardiovascular resulting in decreased functional activity","STD accompanied by associated clinical symptoms","Congenital mediated by specific receptor activation","Neurologic without affecting the primary tissue pathway","Skin papilloma and bone lesions"]'::jsonb, 'Skin papilloma and bone lesions', 'Yaws is caused by Treponema pertenue and produces skin papillomas (mother yaw) and destructive bone and periosteal lesions, usually without cardiovascular or nervous system involvement.'),
('6ff86b6a-0fa9-54d2-8cd6-4133e55bbe12'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which molecular technique amplifies specific DNA sequences and can distinguish the treponemal subspecies causing yaws from Treponema pallidum?', '["FTA-ABS","VDRL","Culture","PCR","Dark-field microscopy"]'::jsonb, 'PCR', 'PCR amplifies species- and subspecies-specific treponemal DNA, permitting confirmation of yaws and its distinction from syphilis, which is not possible with serologic tests.'),
('8f0c481f-960e-5f81-9819-93db05bccf9e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Double-zone hemolysis on blood agar is a characteristic finding of:', '["C. tetani","C. difficile","C. perfringens on blood agar","C. botulinum","B. fragilis"]'::jsonb, 'C. perfringens on blood agar', 'C. perfringens shows double-zone hemolysis: an inner complete zone from theta-toxin (perfringolysin O) and an outer incomplete zone, an important clue to its identification.'),
('04aa1f72-2811-576d-9d74-0fbecfe57318'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The first-line treatment of nocardiosis is:', '["Vancomycin","Sulfonamides (TMP-SMX)","Doxycycline","Metronidazole","Penicillin"]'::jsonb, 'Sulfonamides (TMP-SMX)', 'Sulfonamides, usually as TMP-SMX, are the drugs of choice for nocardiosis; treatment is prolonged because of the tendency to relapse.'),
('540c27da-36aa-513d-9284-1d5c40cfaa6b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella, the most abundant coccus of the oral cavity, is best classified as a:', '["GN anaerobic coccus","GP coccus","GP rod","Spirochete","GN rod"]'::jsonb, 'GN anaerobic coccus', 'Veillonella is a small gram-negative coccus that grows only under anaerobic conditions and is a normal member of the oral and intestinal flora.'),
('13eea26f-e0a6-5082-acaa-76565326998e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella, a gram-negative anaerobic coccus, is a normal inhabitant of the:', '["Skin resulting in decreased functional activity","Soil accompanied by associated clinical symptoms","Water mediated by specific receptor activation","Air without affecting the primary tissue pathway","Oral and gut flora"]'::jsonb, 'Oral and gut flora', 'Veillonella species are normal commensals of the human mouth and lower gastrointestinal tract.'),
('d19b8163-4b4c-54c2-9ef9-6654fb27cc5e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which organism is the principal microbial pathogen of chronic adult periodontitis?', '["Porphyromonas gingivalis","Clostridium difficile","Streptococcus mutans","Candida albicans","Escherichia coli"]'::jsonb, 'Porphyromonas gingivalis', 'Porphyromonas gingivalis, a black-pigmented gram-negative anaerobic rod, is the key pathogen of chronic periodontitis; its proteases destroy gingival connective tissue and alveolar bone.'),
('a74185ec-c646-5b33-9b89-ed2d39583002'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The treatment of choice for actinomycosis is:', '["Metronidazole","Penicillin G","Carbapenems","Clindamycin","Azithromycin"]'::jsonb, 'Penicillin G', 'High-dose parenteral penicillin G is the treatment of choice for actinomycosis; Actinomyces species are generally resistant to metronidazole.'),
('480f758d-097a-52b0-8ead-16669b349ace'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Weil disease, the syndrome of jaundice, renal failure and hemorrhage, is the classic presentation of:', '["Meningitis","Pneumonia","Icteric leptospirosis","Anicteric","Hepatitis"]'::jsonb, 'Icteric leptospirosis', 'Weil disease is the icteric, severe form of leptospirosis, characterized clinically by fever, jaundice, acute renal failure and hemorrhagic diathesis.'),
('e91af9f1-4f50-5197-b86c-b5350dca8f3a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Nocardia can be distinguished from the morphologically similar Actinomyces by which staining property?', '["Fungus","Spirochete","GP branching filamentous (anaerobe)","Acid-fast (partial)","GN rod"]'::jsonb, 'Acid-fast (partial)', 'Nocardia is partially acid-fast on modified Kinyoun stain and is aerobic, whereas Actinomyces is not acid-fast and is an obligate anaerobe.'),
('6786e87c-1ade-5cb8-b6b2-b01a6158e6b3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The bacterial species classically recognized by double-zone hemolysis on blood agar is:', '["C. tetani","C. perfringens on blood agar","C. botulinum","B. fragilis","C. difficile"]'::jsonb, 'C. perfringens on blood agar', 'C. perfringens produces a distinctive double-zone of hemolysis on blood agar, a rapid and useful clue to its identification in clinical specimens.'),
('ad2f60c2-a5d2-52a1-9048-a6f49f910e89'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridia, including C. tetani, C. perfringens and C. botulinum, are best classified morphologically as:', '["Spirochete","GN rod","GP anaerobic rod","GP coccus","GN coccus"]'::jsonb, 'GP anaerobic rod', 'Clostridia are gram-positive anaerobic spore-forming rods; among anaerobic cocci, Peptostreptococcus is gram-positive and Veillonella is gram-negative.'),
('e02274e1-70f6-5d16-9178-e40b349e3fd9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Actinomyces is best characterized as a:', '["Fungus resulting in decreased functional activity","GP branching filamentous (anaerobe)","Acid-fast mediated by specific receptor activation","Spirochete without affecting the primary tissue pathway","GN rod leading to subsequent cellular adaptation"]'::jsonb, 'GP branching filamentous (anaerobe)', 'Actinomyces is a gram-positive branching filamentous bacterium that is an obligate anaerobe, causing chronic suppurative actinomycosis with sulfur granules.'),
('7a51f1de-7c3d-5891-91c8-ad7868c350d3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium tetani is the cause of:', '["Pseudomembranous colitis","Botulism","Gas gangrene","Food poisoning","Tetanus (lockjaw)"]'::jsonb, 'Tetanus (lockjaw)', 'C. tetani elaborates tetanospasmin, which blocks inhibitory neurotransmitter release and causes tetanus with trismus (lockjaw), risus sardonicus and generalized spasticity.'),
('d61d4189-fb6b-5bf1-baf5-01bf4521055f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Louse-borne relapsing fever is transmitted by the:', '["Sandfly resulting in decreased functional activity","Flea accompanied by associated clinical symptoms","Tick mediated by specific receptor activation","Mosquito without affecting the primary tissue pathway","Body louse (Pediculus)"]'::jsonb, 'Body louse (Pediculus)', 'Borrelia recurrentis, the agent of epidemic louse-borne relapsing fever, is transmitted by the body louse Pediculus humanus corporis; tick-borne forms are transmitted by soft ticks.'),
('170fe8c4-ee7c-519e-9204-416bd7edf4d1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which disease among the following is caused by Borrelia recurrentis?', '["Yaws","Relapsing fever","Syphilis","Leptospirosis","Lyme disease"]'::jsonb, 'Relapsing fever', 'Borrelia recurrentis causes relapsing fever, marked by recurring febrile paroxysms due to antigenic variation; yaws and syphilis are treponemal diseases.'),
('32b2dd3c-e5b8-573c-8f44-37bca858a2a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The classic dietary source implicated in infant botulism (floppy baby) is:', '["Honey","Canned vegetables","Contaminated meat","Unpasteurized milk","Raw eggs"]'::jsonb, 'Honey', 'Infant botulism follows ingestion of Clostridium botulinum spores, classically from honey; the spores germinate in the immature infant gut and release toxin, causing the ''floppy baby'' syndrome.'),
('fccf3a30-40c0-5af8-aa14-f661256c9c11'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Descending symmetric flaccid paralysis following ingestion of a preformed toxin is the hallmark of:', '["Gas gangrene","Botulism (flaccid paralysis)","Anthrax","Pseudomembranous colitis","Tetanus"]'::jsonb, 'Botulism (flaccid paralysis)', 'Ingestion of preformed botulinum toxin blocks acetylcholine release, causing descending symmetric flaccid paralysis with early cranial nerve palsies and without fever.'),
('13c4366f-3e63-5fea-872e-360286e58982'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'In addition to acne, Cutibacterium (Propionibacterium) acnes is an important cause of:', '["Botulism","Prosthetic joint infection","Gas gangrene","Tetanus","Dental caries"]'::jsonb, 'Prosthetic joint infection', 'Cutibacterium acnes contaminates implanted hardware during surgery and is a well-recognized cause of indolent prosthetic joint infections, especially of the shoulder.'),
('fa4804ee-9fea-5d75-97ad-cb092da3288b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The clostridial myonecrosis that follows deep penetrating wounds contaminated with soil is known as:', '["Botulism","Tetanus","Anthrax","Gas gangrene (myonecrosis)","Pseudomembranous colitis"]'::jsonb, 'Gas gangrene (myonecrosis)', 'C. perfringens and its alpha-toxin cause gas gangrene, a fulminant spreading myonecrosis with gas formation (crepitus) and systemic toxemia.'),
('b50e1236-d2fa-5948-a1ea-e1650acc06b9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Infections caused by Bacteroides fragilis are best treated with:', '["Azithromycin","Vancomycin","Doxycycline","Penicillin","Metronidazole or carbapenem"]'::jsonb, 'Metronidazole or carbapenem', 'B. fragilis produces beta-lactamases, so it is resistant to penicillin; anaerobically active agents such as metronidazole or carbapenems are the treatment of choice.'),
('e9b1aac3-d175-5c8a-9f27-981eb2882e88'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The arthritis of late Lyme disease characteristically involves the:', '["Small joints","Hip","Shoulder","Knee oligoarticular","Spine"]'::jsonb, 'Knee oligoarticular', 'Late Lyme disease classically produces a mono- or oligoarticular arthritis, most often of the knee, which may be recurrent and is culture-negative.'),
('d9548cd0-9d03-51ae-b0b0-4a50a8717697'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Fusobacterium, involved in dental abscesses and Lemierre syndrome, is best classified as:', '["GN aerobic rod","GP rod","GN anaerobic rod","Spirochete","GP coccus"]'::jsonb, 'GN anaerobic rod', 'Fusobacterium is a gram-negative anaerobic rod; Fusobacterium nucleatum is a key component of dental plaque and F. necrophorum causes postanginal septicemia (Lemierre syndrome).'),
('de16ede3-2297-54cb-bf3c-9a8ac23e0b72'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which organism is the most important etiologic agent of chronic adult periodontitis?', '["Porphyromonas gingivalis","Clostridium difficile","Streptococcus mutans","Candida albicans","Escherichia coli"]'::jsonb, 'Porphyromonas gingivalis', 'Porphyromonas gingivalis is the principal agent of chronic adult periodontitis, elaborating proteases that destroy the gingival attachment and alveolar bone.'),
('68b8f6d6-d1ed-5839-8c87-64977096a864'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The bacterium chiefly responsible for the deep pockets and alveolar bone loss of chronic adult periodontitis is:', '["Streptococcus mutans","Porphyromonas gingivalis","Escherichia coli","Candida albicans","Clostridium difficile"]'::jsonb, 'Porphyromonas gingivalis', 'Porphyromonas gingivalis, a black-pigmented gram-negative anaerobic rod, is the key pathogen of chronic adult periodontitis.'),
('22a5d403-d1ba-5cab-829b-66f8ec6a6e7d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The drug of choice for nocardiosis is:', '["Vancomycin","Sulfonamides (TMP-SMX)","Penicillin","Metronidazole","Doxycycline"]'::jsonb, 'Sulfonamides (TMP-SMX)', 'Sulfonamides, usually combined with trimethoprim (TMP-SMX), remain the treatment of choice for nocardiosis and are given for a prolonged course.'),
('bf2f11b1-f23b-54bc-b90a-456ce6039b8d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The mainstay of medical therapy for actinomycosis is:', '["Metronidazole","Vancomycin","Doxycycline","Azithromycin","Penicillin G (long term)"]'::jsonb, 'Penicillin G (long term)', 'Actinomycosis requires prolonged high-dose penicillin G, continued for weeks to months because of the dense fibrotic nature of the lesions; surgical drainage supplements antibiotics.'),
('9c0e430a-7d91-516b-afa6-4ecc4d99eec5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Anaerobic bacteria aspirated from the oropharyngeal flora are characteristically involved in which of the following?', '["Granuloma","Pulmonary and brain abscess","Acute meningitis","Endocarditis","Urinary tract infection"]'::jsonb, 'Pulmonary and brain abscess', 'Aspiration of oropharyngeal anaerobes (Prevotella, Fusobacterium, Peptostreptococcus) causes necrotizing pneumonia and lung abscess, and anaerobic species such as Fusobacterium are leading causes of brain abscess.'),
('f4cd08b7-c18a-5493-a16b-91828cae6e21'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Moderate-to-severe Clostridioides difficile infection is best treated with:', '["Azithromycin","Oral vancomycin or fidaxomicin","Ciprofloxacin","Metronidazole","Penicillin"]'::jsonb, 'Oral vancomycin or fidaxomicin', 'Oral vancomycin or fidaxomicin is preferred for moderate-to-severe C. difficile infection; oral metronidazole is reserved for mild disease or when other agents are unavailable.'),
('f1e1b80a-adac-550f-ad47-c72d3186783f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The first-line antimicrobial for nocardiosis is:', '["Penicillin","Doxycycline","Sulfonamides (TMP-SMX)","Vancomycin","Metronidazole"]'::jsonb, 'Sulfonamides (TMP-SMX)', 'Sulfonamides, usually as TMP-SMX, are the mainstay of treatment and long-term suppression in nocardiosis.'),
('6e7c67b5-ab54-52b0-9d8f-80511900576a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Borrelia burgdorferi is the causative agent of:', '["Relapsing fever","Syphilis","Lyme disease","Yaws","Leptospirosis"]'::jsonb, 'Lyme disease', 'Borrelia burgdorferi, transmitted by Ixodes ticks, causes Lyme disease, which progresses from erythema migrans to cardiac and neurologic disease and then arthritis.'),
('30f84579-da4b-54e7-ae88-4e7cc075b804'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'A gram-positive branching filamentous bacterium that is an obligate anaerobe and forms sulfur granules is:', '["Spirochete resulting in decreased functional activity","Fungus accompanied by associated clinical symptoms","GP branching filamentous (anaerobe)","GN rod without affecting the primary tissue pathway","Acid-fast leading to subsequent cellular adaptation"]'::jsonb, 'GP branching filamentous (anaerobe)', 'Actinomyces is the gram-positive branching filamentous anaerobe whose chronic infections (actinomycosis) contain sulfur granules; it is not acid-fast.'),
('440235d9-4b3c-582d-ad3c-727ca15ed76f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The syndrome of jaundice, acute renal failure and bleeding in leptospirosis is known as:', '["Weil disease","Relapsing fever","Yaws","Lyme","Syphilis"]'::jsonb, 'Weil disease', 'Weil disease is the severe icteric form of leptospirosis, with hepatic and renal failure and hemorrhagic manifestations.'),
('15ed19df-cc3a-5987-8d60-4ea26d8663b2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Treponema pertenue, a nonvenereal spirochete acquired by skin-to-skin contact in children, causes:', '["Lyme","Syphilis","Leptospirosis","Yaws","Relapsing fever"]'::jsonb, 'Yaws', 'Treponema pertenue causes yaws, a nonvenereal treponematosis producing skin papillomas and bone-periosteal lesions without cardiovascular or neurologic involvement.'),
('e4381767-da92-5f91-bc9f-46ecf9bdba0c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'An expanding annular erythematous ''bullseye'' skin lesion at the site of a tick bite is characteristic of:', '["Bullseye rash (Lyme)","Vesicles","Pustules","Petechiae","Macules"]'::jsonb, 'Bullseye rash (Lyme)', 'Erythema migrans, an enlarging red ring with central clearing (bullseye) at the tick-bite site, is the hallmark of early localized Lyme disease.'),
('6dcbd6c0-86ac-5ce2-ac2d-f81d1b37eb3a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Secondary syphilis classically presents with:', '["Aortitis resulting in decreased functional activity","Chancre accompanied by associated clinical symptoms","Rash palms/soles + condyloma lata","Gumma without affecting the primary tissue pathway","Neurosyphilis leading to subsequent cellular adaptation"]'::jsonb, 'Rash palms/soles + condyloma lata', 'Secondary syphilis produces a diffuse maculopapular rash that characteristically involves the palms and soles, together with condyloma lata and mucous patches, weeks to months after the chancre.'),
('c484dd58-64f7-5064-a0ab-0b3c399d2f53'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which tick transmits Borrelia burgdorferi, the agent of Lyme disease?', '["Mosquito","Flea","Amblyomma","Ixodes tick","Dermacentor"]'::jsonb, 'Ixodes tick', 'Lyme disease is transmitted by the Ixodes (deer) tick; in North America this is Ixodes scapularis.'),
('91774f90-259f-5e76-8873-639ad8f93e3b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which nonvenereal treponematosis is caused by Treponema pertenue?', '["Yaws","Relapsing fever","Lyme","Leptospirosis","Syphilis"]'::jsonb, 'Yaws', 'Yaws is the nonvenereal treponematosis caused by Treponema pertenue, spread by direct contact and characterized by papillomatous skin and bone lesions.'),
('7e7eaf80-d718-5c18-a7e8-8b802cace8bf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Apart from acne, Cutibacterium (Propionibacterium) acnes is classically associated with infection of:', '["Prosthetic joint infection","Gas gangrene","Dental caries","Tetanus","Botulism"]'::jsonb, 'Prosthetic joint infection', 'Cutibacterium acnes contaminates surgical implants, particularly shoulder prostheses and CSF shunts, and causes indolent prosthetic joint infections.'),
('b5f49d49-ed81-5130-a519-9b6ea10b3f39'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Yaws, the nonvenereal treponematosis of childhood, characteristically produces:', '["Cardiovascular resulting in decreased functional activity","Skin papilloma and bone lesions","Congenital mediated by specific receptor activation","Neurologic without affecting the primary tissue pathway","STD leading to subsequent cellular adaptation"]'::jsonb, 'Skin papilloma and bone lesions', 'Yaws produces skin papillomas (mother yaw and daughter yaws) and osteoperiosteal lesions, without the cardiovascular or neurologic disease seen in tertiary syphilis.'),
('d93724c7-c816-5478-b368-4c5e775fbcff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which anaerobic organism is the most important pathogen of chronic adult periodontitis?', '["Porphyromonas gingivalis","Veillonella parvula","Streptococcus mutans","Bacteroides fragilis","Corynebacterium diphtheriae"]'::jsonb, 'Porphyromonas gingivalis', 'Porphyromonas gingivalis, a black-pigmented gram-negative anaerobic rod, is the dominant pathogen in chronic adult periodontitis, causing progressive gingival and bone destruction.'),
('bc19a933-446a-5092-b6ab-d8281440c5c6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Treatment of actinomycosis consists of prolonged high-dose therapy with:', '["Azithromycin","Metronidazole","Penicillin G (long term)","Doxycycline","Vancomycin"]'::jsonb, 'Penicillin G (long term)', 'Actinomycosis is treated with prolonged high-dose penicillin G; the extended course is needed because of the chronic, fibrotic nature of the infection.'),
('4e3255af-d1bf-5964-8e20-6f1fcbbe2f1d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella species, anaerobic gram-negative rods of the gingival sulcus, are commonly implicated in:', '["Periodontal infection and abscess","Pneumonia accompanied by associated clinical symptoms","Bacteremia mediated by specific receptor activation","Meningitis without affecting the primary tissue pathway","UTI leading to subsequent cellular adaptation"]'::jsonb, 'Periodontal infection and abscess', 'Prevotella is a black-pigmented gram-negative anaerobic rod of the oral flora that commonly causes periodontal infections and dental abscesses.'),
('5ad2fdd3-c6ae-5d51-bce1-80818ef9c2b9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Borrelia recurrentis is the etiologic agent of:', '["Syphilis","Lyme disease","Relapsing fever","Yaws","Leptospirosis"]'::jsonb, 'Relapsing fever', 'Borrelia recurrentis causes louse-borne relapsing fever, with recurring fever spikes due to antigenic variation of its surface antigens.'),
('c0cbeed9-979d-5299-ab26-d0a37f994418'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridioides difficile is the principal cause of:', '["Tetanus","Botulism","Gas gangrene","Pseudomembranous colitis","Food poisoning"]'::jsonb, 'Pseudomembranous colitis', 'C. difficile, selected out by antibiotics, produces toxins A and B that cause pseudomembranous colitis with characteristic plaque-like colonic lesions.'),
('45cc51bf-12fc-5efc-af41-3ed56dd1df20'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis characteristically shows intrinsic resistance to which antibiotic?', '["Clindamycin","Carbapenems","Metronidazole","Ciprofloxacin","Penicillin G"]'::jsonb, 'Penicillin G', 'B. fragilis produces beta-lactamase and is therefore intrinsically resistant to penicillin G; infections are treated with metronidazole or carbapenems.'),
('3fb9a243-1a96-50db-863d-ad4e957d2a06'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Leptospirosis is transmitted to humans through direct or indirect contact with:', '["Urine of infected animals","Blood accompanied by associated clinical symptoms","Tick bite mediated by specific receptor activation","Mosquito without affecting the primary tissue pathway","Sexual leading to subsequent cellular adaptation"]'::jsonb, 'Urine of infected animals', 'Leptospira are shed in the urine of reservoir animals (rodents, cattle, dogs); human infection occurs through contaminated water or soil entering skin or mucous membranes.'),
('3c287a5d-905d-57c7-b025-c5ef3bce2d7b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Tetanus immunoprophylaxis is based on administration of which type of vaccine?', '["Polysaccharide","Toxoid (DTaP/Tdap)","Live attenuated","Recombinant","Killed whole"]'::jsonb, 'Toxoid (DTaP/Tdap)', 'The tetanus vaccine is a toxoid (formaldehyde-inactivated toxin) and is given combined as DTaP/Tdap, with Td boosters every ten years.'),
('ebedae60-f672-5aa0-b17c-ed80cb46f98f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Cutibacterium (Propionibacterium) acnes is best classified as a:', '["GP anaerobic rod","GN rod","GP coccus","Spirochete","GN coccus"]'::jsonb, 'GP anaerobic rod', 'Cutibacterium acnes is a gram-positive anaerobic, non-spore-forming rod that is a predominant commensal of the pilosebaceous skin flora.'),
('3f928670-3dc3-5b73-8299-baa0c4ec8d05'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which disease is produced by Borrelia recurrentis?', '["Lyme disease","Syphilis","Leptospirosis","Yaws","Relapsing fever"]'::jsonb, 'Relapsing fever', 'Borrelia recurrentis causes relapsing fever; the spirochetes are demonstrable in blood smears taken during a febrile paroxysm.'),
('7a6194fe-912d-5afa-985f-961d8e18eea4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella, a member of the oral, vaginal and intestinal flora, is best classified as:', '["Aerobic","Spirochete","Acid-fast","GN anaerobic rod","GP coccus"]'::jsonb, 'GN anaerobic rod', 'Prevotella is a gram-negative anaerobic rod, commonly black-pigmented, found in the oral, vaginal and intestinal flora.'),
('cba82d0c-f6fe-5a18-a262-40e64b25c28c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis, the most frequently isolated anaerobe in clinical specimens, is best classified as a:', '["GN aerobic rod","GP anaerobic coccus","GP rod","GN anaerobic rod","Spirochete"]'::jsonb, 'GN anaerobic rod', 'Bacteroides fragilis is a gram-negative anaerobic rod and the most commonly isolated anaerobe from clinical infections.'),
('c97e8e3d-e8d1-5ec0-b0d4-db8159ae727e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium tetani, an anaerobic spore-forming rod, is the cause of:', '["Tetanus (lockjaw)","Food poisoning","Pseudomembranous colitis","Gas gangrene","Botulism"]'::jsonb, 'Tetanus (lockjaw)', 'C. tetani causes tetanus, presenting with trismus (lockjaw) and generalized spastic paralysis because tetanospasmin blocks release of the inhibitory neurotransmitters GABA and glycine.'),
('bb63a39c-d6c1-5af4-a81a-8943be2da1be'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Weil disease is the classic severe form of which condition?', '["Anicteric","Pneumonia","Icteric leptospirosis","Meningitis","Hepatitis"]'::jsonb, 'Icteric leptospirosis', 'Weil disease is the icteric (severe) presentation of leptospirosis, combining fever, jaundice, renal failure and bleeding.'),
('a764ba45-c67d-5ccd-8db4-86e829cfd7fe'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'A gram-positive branching filamentous anaerobe that forms sulfur granules in chronic suppurative lesions is:', '["Spirochete resulting in decreased functional activity","Acid-fast accompanied by associated clinical symptoms","Fungus mediated by specific receptor activation","GP branching filamentous (anaerobe)","GN rod leading to subsequent cellular adaptation"]'::jsonb, 'GP branching filamentous (anaerobe)', 'Actinomyces is the gram-positive branching filamentous anaerobe of chronic actinomycosis; the sulfur granules in pus contain its tangled filaments.'),
('cee7fe54-b53e-57c3-819e-cec671a5b080'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The established treatment for actinomycosis is:', '["Metronidazole","Vancomycin","Azithromycin","Doxycycline","Penicillin G (long term)"]'::jsonb, 'Penicillin G (long term)', 'Long-term high-dose penicillin G is the established therapy for actinomycosis, often combined with surgical drainage of abscesses and sinus tracts.'),
('928f9ddb-c6f3-5817-93cd-d2e2d59e82c2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Vincent angina (trench mouth) is a necrotizing gingival infection classically caused by the fusospirochetal organism:', '["Fusobacterium","Clostridium","Staphylococcus","Streptococcus","Bacteroides"]'::jsonb, 'Fusobacterium', 'Vincent angina is an acute necrotizing ulcerative gingivitis from synergistic overgrowth of fusiform bacilli (Fusobacterium nucleatum) and oral spirochetes.'),
('b02c5dca-1c69-5aff-9918-e21df716a6d7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Treponema pallidum, the agent of syphilis, is best described as:', '["GN rod","GP coccus","Virus","A spirochete","Acid-fast"]'::jsonb, 'A spirochete', 'Treponema pallidum is a thin, motile, helically coiled spirochete seen by dark-field microscopy; it cannot be cultured in vitro.'),
('dafa6fd4-702b-535c-b8f4-b100d42bfa57'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Molecular confirmation of yaws, distinguishing Treponema pertenue from Treponema pallidum, is best achieved by:', '["Dark-field microscopy","Culture","PCR","FTA-ABS","VDRL"]'::jsonb, 'PCR', 'Species- and subspecies-specific PCR amplifies treponemal DNA and differentiates the yaws agent from T. pallidum, which cross-reactive serologic tests cannot do.'),
('759cb1c9-1edc-59d0-b66b-e0912c0f95e4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which of the following is the most important anaerobic pathogen of chronic adult periodontitis?', '["Porphyromonas gingivalis","Escherichia coli","Streptococcus mutans","Candida albicans","Clostridium difficile"]'::jsonb, 'Porphyromonas gingivalis', 'Porphyromonas gingivalis, a black-pigmented gram-negative anaerobic rod, is the principal anaerobic pathogen of chronic adult periodontitis causing deep pockets and bone loss.'),
('271add6a-fde8-5f03-a73a-16fb54005375'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Leptospira is transmitted to humans chiefly through:', '["Tick bite resulting in decreased functional activity","Blood accompanied by associated clinical symptoms","Urine of infected animals","Sexual without affecting the primary tissue pathway","Mosquito leading to subsequent cellular adaptation"]'::jsonb, 'Urine of infected animals', 'Leptospira infection follows exposure to the urine of infected rodents and other animals, typically through contaminated water or soil.'),
('f5272a71-7e38-571b-842a-f8f7277f0527'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The characteristic lesion of primary syphilis is a:', '["Painless chancre","Painful ulcer","Condyloma lata","Gumma","Rash"]'::jsonb, 'Painless chancre', 'Primary syphilis presents with a single indurated, painless chancre with painless regional lymphadenopathy that heals spontaneously within weeks.'),
('769a1a34-0f60-5fce-810a-656f1ce5198b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella, a small coccus that is the predominant anaerobe of the oral cavity, belongs to which group?', '["GP coccus","GP rod","GN anaerobic coccus","Spirochete","GN rod"]'::jsonb, 'GN anaerobic coccus', 'Veillonella is a gram-negative anaerobic coccus and the most abundant coccus of the oral flora.'),
('7f8ff879-251c-5efe-82a9-0e637b6522a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Cutibacterium (Propionibacterium) acnes, a gram-positive anaerobic skin commensal, is an important cause of infection of:', '["Prosthetic joint infection","Gas gangrene","Tetanus","Botulism","Dental caries"]'::jsonb, 'Prosthetic joint infection', 'Cutibacterium acnes, which colonizes skin and contaminates the operative field, is an important cause of prosthetic joint infections and infections of CSF and cardiac devices.'),
('622f391f-967d-58e2-b48e-5f893c61bed2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The combination of Hutchinson teeth, saddle nose and eighth nerve deafness is a classic manifestation of:', '["Gumma resulting in decreased functional activity","Hutchinson teeth, saddle nose, deafness","Rash mediated by specific receptor activation","Generalized lymphadenopathy without affecting the primary tissue pathway","Chancres leading to subsequent cellular adaptation"]'::jsonb, 'Hutchinson teeth, saddle nose, deafness', 'Late congenital syphilis produces the Hutchinson triad (notched Hutchinson teeth, interstitial keratitis and eighth nerve deafness) plus saddle nose and saber shins; chancres and rash belong to acquired syphilis.'),
('a4afd364-3ad6-56b2-a5bc-5b57e013d2eb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella, a normal anaerobic commensal of the mouth and gut, is best classified as:', '["GN anaerobic coccus","GN rod","GP coccus","GP rod","Spirochete"]'::jsonb, 'GN anaerobic coccus', 'Veillonella is a gram-negative anaerobic coccus, a characteristic member of the oral and gastrointestinal flora.'),
('8e226c35-27e8-538b-afc8-b8b4c4a84eb0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Yaws, a nonvenereal treponematosis, is characterized by:', '["Skin papilloma and bone lesions","STD accompanied by associated clinical symptoms","Neurologic mediated by specific receptor activation","Congenital without affecting the primary tissue pathway","Cardiovascular leading to subsequent cellular adaptation"]'::jsonb, 'Skin papilloma and bone lesions', 'Yaws is caused by Treponema pallidum subsp. pertenue, transmitted by skin-to-skin contact. It causes chronic skin papillomas and, if untreated, destructive bone and cartilage lesions while sparing the cardiovascular and central nervous systems.'),
('7f267a14-b481-5df4-9953-900cccab33a7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which antibiotic is the drug of choice for early localized Lyme disease?', '["Doxycycline","Penicillin G","Metronidazole","Vancomycin","Azithromycin"]'::jsonb, 'Doxycycline', 'Doxycycline is the drug of choice for erythema migrans in adults and children over 8 years. Amoxicillin and cefuroxime axetil are alternatives and azithromycin is only second line.'),
('53edc886-7057-5c8f-83ea-83d5350246d6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Primary syphilis is characterized by:', '["Painless chancre","Gumma","Painful ulcer","Condyloma lata","Rash"]'::jsonb, 'Painless chancre', 'Primary syphilis classically presents 3-90 days after exposure with a painless, indurated chancre at the site of inoculation. The lesion heals spontaneously even without treatment.'),
('bf457000-1f88-5d85-9736-19936c6ab6a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. perfringens food poisoning is caused by:', '["Enterotoxin (cramps, diarrhea)","Paralysis accompanied by associated clinical symptoms","Fever mediated by specific receptor activation","Colitis without affecting the primary tissue pathway","Trismus leading to subsequent cellular adaptation"]'::jsonb, 'Enterotoxin (cramps, diarrhea)', 'C. perfringens type A produces an enterotoxin that acts on the small bowel, causing watery diarrhea and crampy abdominal pain 8-16 hours after ingestion. Fever and vomiting are usually absent.'),
('e44e8074-e802-5997-b11f-31af63b9b895'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The treatment of botulism includes:', '["Antitoxin + supportive care","Metronidazole","Penicillin","Surgery","Vancomycin"]'::jsonb, 'Antitoxin + supportive care', 'Management relies on botulinum antitoxin to neutralize circulating toxin plus supportive care including mechanical ventilation. Antibiotics do not reverse the effects of the preformed toxin.'),
('8c7d2b25-6829-51a0-b8cf-b7b8ae252684'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Botulinum toxin acts by:', '["Lecithinase","Blocks glycine","Cytotoxin","Enterotoxin","Blocks ACh release (flaccid)"]'::jsonb, 'Blocks ACh release (flaccid)', 'Botulinum toxin irreversibly blocks presynaptic release of acetylcholine at the neuromuscular junction, producing flaccid paralysis. Tetanus toxin, in contrast, blocks central inhibitory glycine release, causing spastic paralysis.'),
('67042cdc-c0f2-5278-b57d-d99efd4346a0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Actinomyces is best described as:', '["Spirochete resulting in decreased functional activity","Acid-fast accompanied by associated clinical symptoms","Fungus mediated by specific receptor activation","GP branching filamentous (anaerobe)","GN rod leading to subsequent cellular adaptation"]'::jsonb, 'GP branching filamentous (anaerobe)', 'Actinomyces organisms are Gram-positive, branching, filamentous anaerobes. They are not acid-fast (unlike Nocardia) and are not fungi despite the name.'),
('d78700b8-b05b-5448-9a9d-f6ad30dffd6c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Established risk factors for Clostridioides difficile infection include:', '["Antibiotic use (clindamycin)","Surgery","PPI use","Hospitalization","All of the above"]'::jsonb, 'All of the above', 'Antibiotic exposure (especially clindamycin), proton-pump inhibitors, hospitalization, and surgery all predispose to C. difficile infection. Disruption of the normal colonic flora is the common underlying mechanism.'),
('0f4e5098-5da4-5a29-8c5d-73217be37ffc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Weil disease, the severe form of leptospirosis, is best described as:', '["Hepatitis","Icteric leptospirosis","Meningitis","Anicteric","Pneumonia"]'::jsonb, 'Icteric leptospirosis', 'Weil disease is icteric leptospirosis with jaundice, renal failure, and hemorrhage. Anicteric leptospirosis is the more common and far milder form.'),
('016ce653-989c-52df-9eb7-8b42a616a6c7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which feature best distinguishes Nocardia from Actinomyces?', '["Acid-fast (partial)","GP branching filamentous (aerobic)","Spirochete","Fungus","GN rod"]'::jsonb, 'Acid-fast (partial)', 'Nocardia is partially acid-fast on modified Kinyoun staining, whereas Actinomyces is not acid-fast. Both are Gram-positive branching filamentous organisms.'),
('63e23791-3220-59d2-a6e6-99d0b3f29bdd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The alpha toxin of C. perfringens is responsible for:', '["Tetanus","Gas gangrene (myonecrosis)","Botulism","Pseudomembranous colitis","Food poisoning"]'::jsonb, 'Gas gangrene (myonecrosis)', 'C. perfringens alpha toxin (lecithinase) degrades cell membranes and is the major mediator of gas gangrene (clostridial myonecrosis). Its food-poisoning syndrome is produced by a separate enterotoxin.'),
('5c71aed9-4bda-5a46-a638-e988e552652f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'FTA-ABS is best classified as which type of serologic test?', '["Treponemal confirmatory","Non-treponemal","PCR-based","Culture-based","Rapid screening"]'::jsonb, 'Treponemal confirmatory', 'FTA-ABS detects antibodies against T. pallidum antigens and is used as a confirmatory treponemal test, remaining positive for life. Non-treponemal tests such as RPR and VDRL are used for screening and monitoring response to therapy.'),
('7d39aa51-0a35-576f-b518-45996c3fd769'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Yaws is characterized by:', '["Cardiovascular resulting in decreased functional activity","Neurologic accompanied by associated clinical symptoms","Skin papilloma and bone lesions","Congenital without affecting the primary tissue pathway","STD leading to subsequent cellular adaptation"]'::jsonb, 'Skin papilloma and bone lesions', 'Yaws (T. pallidum subsp. pertenue) affects skin and bone, producing papillomatous lesions and destructive bone disease. Unlike syphilis it is nonvenereal and does not cause cardiovascular or neurosyphilis.'),
('0deab009-ca90-5d22-9709-0b401ed1f283'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella is best described as:', '["GP coccus","GN rod","GN anaerobic coccus","GP rod","Spirochete"]'::jsonb, 'GN anaerobic coccus', 'Veillonella is a Gram-negative anaerobic coccus that is a normal commensal of the oral cavity and gut. Most other clinically relevant anaerobic cocci (e.g., Peptostreptococcus) are Gram-positive.'),
('bee6f9af-9528-5858-bc3c-d0f4aafaa58d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Relapsing fever is characterized by:', '["Repeated febrile episodes","A single self-limited fever","Continuous fever","Chronic low-grade fever","No febrile episodes"]'::jsonb, 'Repeated febrile episodes', 'Relapsing fever (Borrelia recurrentis or Borrelia hermsii) produces repeated febrile episodes separated by afebrile intervals. This results from antigenic variation of surface proteins that allows the organism to evade each antibody response.'),
('23482496-51f7-588c-8ca2-31d3e53e00b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Oral anaerobic spirochetes such as Treponema denticola are strongly associated with:', '["Periodontitis","Pneumonia","Gingivitis","Abscess","UTI"]'::jsonb, 'Periodontitis', 'T. denticola and other oral spirochetes flourish in deep periodontal pockets and are key players in the pathogenesis of periodontitis. Gingivitis involves a different, less destructive host response.'),
('1161d03d-1eb4-528f-ac6f-8089fecf3e44'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Anaerobic bacteria such as Bacteroides species belong to the normal flora of which site?', '["Water resulting in decreased functional activity","Soil accompanied by associated clinical symptoms","Oral and gut flora","Skin without affecting the primary tissue pathway","Air leading to subsequent cellular adaptation"]'::jsonb, 'Oral and gut flora', 'Bacteroides species are dominant members of the normal colonic and oral flora. Being strictly anaerobic, they cannot survive in aerobic environments such as air or water.'),
('6877261f-a843-5642-bc9e-fc7ffbb8f20a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Peptostreptococcus species commonly cause:', '["UTI resulting in decreased functional activity","Pneumonia accompanied by associated clinical symptoms","Diarrhea mediated by specific receptor activation","Meningitis without affecting the primary tissue pathway","Brain and dental abscess"]'::jsonb, 'Brain and dental abscess', 'Peptostreptococci are anaerobic Gram-positive cocci frequently isolated from brain abscesses and dental (odontogenic) infections. They are also found in aspiration pneumonia and intra-abdominal infections.'),
('22705f13-daa6-5dab-bb20-7447c4bdeb21'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'MAT (microscopic agglutination test) is the reference serologic method for the laboratory diagnosis of:', '["Leptospirosis","Lyme disease","Q fever","Brucellosis","Syphilis"]'::jsonb, 'Leptospirosis', 'The microscopic agglutination test (MAT) detects agglutinating antibodies to leptospires and is the reference serologic method for leptospirosis. The other listed diseases use different serologies, e.g., FTA-ABS for syphilis.'),
('b1aeba0d-5c65-5203-8f9a-d2090b3e1bd4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Neuroborreliosis most commonly presents with:', '["Seizures","Dementia","Stroke","Facial nerve palsy","Parkinsonism"]'::jsonb, 'Facial nerve palsy', 'Lymphocytic meningitis with unilateral or bilateral facial nerve palsy is the hallmark of neuroborreliosis (early disseminated Lyme disease). Seizures, dementia, and parkinsonism are not characteristic.'),
('bfb8b82e-70f2-50b7-a2b6-82831944019d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis is the anaerobe most commonly isolated in which condition?', '["UTI","Meningitis","Intra-abdominal abscess","Endocarditis","Pneumonia"]'::jsonb, 'Intra-abdominal abscess', 'B. fragilis is the anaerobe most frequently cultured from intra-abdominal abscesses, typically following bowel perforation or surgery. Its capsular polysaccharide promotes abscess formation.'),
('629d860d-4ba1-535c-a702-44b5120e1f74'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The microscopic agglutination test (MAT) is the serologic reference standard for which infection?', '["Leptospirosis","Syphilis","Q fever","Brucellosis","Lyme disease"]'::jsonb, 'Leptospirosis', 'MAT detects agglutinating antibodies against leptospires and is the reference serologic test for leptospirosis. Paired acute and convalescent sera are needed for reliable interpretation.'),
('725849d4-917a-5d66-8fd3-ceff6c7757d7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Porphyromonas gingivalis is a major pathogen in:', '["UTI","Gingivitis","Periodontitis","Pneumonia","Abscess"]'::jsonb, 'Periodontitis', 'P. gingivalis is a keystone pathogen in chronic periodontitis, evading host defenses and driving alveolar bone loss. Gingivitis is primarily plaque related and involves less specific organisms.'),
('19836a0f-e4b1-59b0-bb19-f520d2725e23'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Fick''s law states that the rate of diffusion is proportional to:', '["Surface area x concentration gradient / thickness","Molecular weight x concentration accompanied by associated clinical symptoms","Protein binding x pH mediated by specific receptor activation","Vd x clearance without affecting the primary tissue pathway","Ionisation x pKa leading to subsequent cellular adaptation"]'::jsonb, 'Surface area x concentration gradient / thickness', 'Rate of diffusion = Dx surface area x concentration gradient / membrane thickness. Larger surface area and steeper gradient increase flux, whereas a thicker membrane slows diffusion.'),
('7074aafe-519d-5cd2-965d-ab41ac3fbcac'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which molecular diagnostic method can detect Treponema pallidum DNA in clinical specimens?', '["Culture","PCR","VDRL","FTA-ABS","Dark-field microscopy"]'::jsonb, 'PCR', 'PCR amplifies T. pallidum DNA and is useful in CSF and early genital lesions because T. pallidum cannot be grown on artificial media. Dark-field microscopy directly visualizes the organism without DNA amplification.'),
('8c53f261-744b-5ca9-8854-56b49aef6f79'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The vector of Borrelia recurrentis (epidemic relapsing fever) is:', '["Tick resulting in decreased functional activity","Sandfly accompanied by associated clinical symptoms","Mosquito mediated by specific receptor activation","Body louse (Pediculus)","Flea leading to subsequent cellular adaptation"]'::jsonb, 'Body louse (Pediculus)', 'B. recurrentis is transmitted by the human body louse (Pediculus humanus corporis). Endemic tick-borne relapsing fever is transmitted by Ornithodoros soft ticks.'),
('dd9b14f1-d8ed-5b56-82ca-04db2ecc0f13'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. perfringens food poisoning results from the action of:', '["Enterotoxin (cramps, diarrhea)","Trismus accompanied by associated clinical symptoms","Paralysis mediated by specific receptor activation","Fever without affecting the primary tissue pathway","Colitis leading to subsequent cellular adaptation"]'::jsonb, 'Enterotoxin (cramps, diarrhea)', 'Spores surviving cooking germinate in the gut and release an enterotoxin that causes self-limited watery diarrhea and cramps about 8-16 hours after eating contaminated meat. Fever and paralysis are not part of this syndrome.'),
('b3cb3a3e-e97d-5bd4-a999-76545cb94782'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The tetanus vaccine is formulated as a:', '["Killed whole","Polysaccharide","Recombinant","Toxoid (DTaP/Tdap)","Live attenuated"]'::jsonb, 'Toxoid (DTaP/Tdap)', 'Tetanus toxoid is formalin-inactivated toxin given as DTaP/Tdap. Antibodies to tetanospasmin neutralize the toxin, and the toxoid itself cannot cause disease.'),
('2b9f6f89-a9b4-5090-aa74-6a1e6b1b4855'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella is best described as a:', '["Aerobic","Spirochete","GN anaerobic rod","GP coccus","Acid-fast"]'::jsonb, 'GN anaerobic rod', 'Prevotella species are Gram-negative anaerobic rods that are part of the normal oral flora. They are implicated in periodontal and odontogenic abscess infections.'),
('ec1d0848-eb33-5dd0-9b6f-d803454766a2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The pathogenicity of C. difficile is attributed to:', '["Botulinum toxin resulting in decreased functional activity","Tetanospasmin accompanied by associated clinical symptoms","Toxin A (enterotoxin) and B (cytotoxin)","Lecithinase without affecting the primary tissue pathway","Neurotoxin leading to subsequent cellular adaptation"]'::jsonb, 'Toxin A (enterotoxin) and B (cytotoxin)', 'Toxin A is an enterotoxin causing fluid secretion and inflammation, while toxin B is a cytotoxin that damages colonic epithelium. Together they produce pseudomembranous colitis.'),
('ad949d12-5d28-50dd-b8d7-1c67ba063223'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Nocardiosis most characteristically produces:', '["Sulfur granules","Cavitation","Effusion","Pulmonary and brain abscess","Granuloma"]'::jsonb, 'Pulmonary and brain abscess', 'Nocardia causes pulmonary infection followed by hematogenous spread to the brain, resulting in abscesses. Sulfur granules are characteristic of Actinomyces, not Nocardia.'),
('d6686e9b-f84c-5f8f-ac95-a723220a5c7c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. botulinum is the etiologic agent of:', '["Gas gangrene","Pseudomembranous colitis","Food poisoning","Botulism (flaccid paralysis)","Tetanus"]'::jsonb, 'Botulism (flaccid paralysis)', 'Preformed botulinum toxin blocks acetylcholine release, producing symmetric descending flaccid paralysis. It is acquired through contaminated food, wounds, or infantile intestinal colonization.'),
('ea43bf0b-e0ea-589a-a32d-902def11d178'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Leptospira is most commonly transmitted by:', '["Blood resulting in decreased functional activity","Tick bite accompanied by associated clinical symptoms","Sexual mediated by specific receptor activation","Urine of infected animals","Mosquito leading to subsequent cellular adaptation"]'::jsonb, 'Urine of infected animals', 'Leptospires persist in the renal tubules of rodents and livestock, and humans acquire infection through contact with urine-contaminated water or soil. The organism enters through broken skin or mucous membranes.'),
('eb6506c2-f422-52f6-9aff-17cb12de3bcb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella species are associated with which clinical syndrome?', '["Periodontal infection and abscess","Pneumonia accompanied by associated clinical symptoms","Meningitis mediated by specific receptor activation","UTI without affecting the primary tissue pathway","Bacteremia leading to subsequent cellular adaptation"]'::jsonb, 'Periodontal infection and abscess', 'Prevotella, a normal oral anaerobe, is frequently isolated from periodontal infections, dental abscesses, and odontogenic infections. Pneumonia and meningitis are not typical primary presentations.'),
('71a1464c-cac9-5f4b-b9d2-5e7c392b7887'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The tetanus vaccine is a:', '["Recombinant","Polysaccharide","Live attenuated","Toxoid (DTaP/Tdap)","Killed whole"]'::jsonb, 'Toxoid (DTaP/Tdap)', 'The vaccine is an inactivated toxoid prepared from tetanospasmin and delivered as DTaP, Tdap, or Td. It elicits neutralizing antitoxin without the risk of tetanus.'),
('10eb56fa-7494-5433-aaa3-75724b5b3e0e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. difficile causes:', '["Tetanus","Food poisoning","Gas gangrene","Pseudomembranous colitis","Botulism"]'::jsonb, 'Pseudomembranous colitis', 'Toxins A and B of C. difficile cause pseudomembranous colitis, typically after antibiotic use. Fibrinous plaques (pseudomembranes) overlie an inflamed colonic mucosa.'),
('191203cd-f473-5c57-b375-ea8e60b0dc28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The alpha toxin of C. perfringens is best described as:', '["Botulinum toxin","Tetanospasmin","Neurotoxin","Enterotoxin","Lecithinase (phospholipase C)"]'::jsonb, 'Lecithinase (phospholipase C)', 'Alpha toxin is a phospholipase C (lecithinase) that degrades lecithin in cell membranes and is the key toxin in gas gangrene. Its reaction on egg-yolk (Nagler) agar supports laboratory identification.'),
('ca116c88-115f-5e8c-ab6b-82c7e9d6c04f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis is best described as a:', '["GN anaerobic rod","GN aerobic rod","GP rod","Spirochete","GP anaerobic coccus"]'::jsonb, 'GN anaerobic rod', 'B. fragilis is an anaerobic, Gram-negative, non-spore-forming rod and the most clinically important anaerobe. It produces beta-lactamase, conferring resistance to penicillin G.'),
('a76fef88-feb9-551c-9751-e276048a35fd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Risk factors for C. difficile infection include:', '["Hospitalization","PPI use","Surgery","All of the above","Antibiotic use (clindamycin)"]'::jsonb, 'All of the above', 'Antibiotics, proton-pump inhibitors, hospitalization, and surgery all predispose to C. difficile infection by disrupting the normal colonic microbiome or promoting institutional exposure.'),
('09c7ee1d-ec95-50ad-99e0-172f1d4f3a84'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Porphyromonas is best described as a:', '["GP coccus","Spirochete","GN anaerobic rod","Aerobic","Acid-fast"]'::jsonb, 'GN anaerobic rod', 'Porphyromonas species (e.g., P. gingivalis) are Gram-negative anaerobic rods of the oral flora. They are principal pathogens in chronic periodontitis.'),
('f988191b-38f7-58d8-8f0e-33d211c4d209'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'For an initial episode of C. difficile infection, the preferred treatment is:', '["Oral vancomycin or fidaxomicin","Azithromycin","Ciprofloxacin","Penicillin","Metronidazole"]'::jsonb, 'Oral vancomycin or fidaxomicin', 'Oral vancomycin and fidaxomicin are the first-line agents for an initial episode of C. difficile infection. Metronidazole is no longer preferred, and fluoroquinolones or penicillins have no role.'),
('fef40bce-c370-521c-bda8-5b30341418a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Actinomycosis is classically associated with:', '["Sulfur granules in pus","Abscess","Cavitation","Granuloma","Caseation"]'::jsonb, 'Sulfur granules in pus', 'Actinomycosis drains through sinus tracts discharging pus that contains yellow sulfur granules, which are clusters of branching filaments. True caseation and granulomas are not characteristic.'),
('d75c5155-5a91-590f-8d3c-00e231bd1442'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Drug efficacy is best defined as:', '["Ability to produce maximal response","Dose for effect accompanied by associated clinical symptoms","Absorption rate mediated by specific receptor activation","Duration without affecting the primary tissue pathway","Safety leading to subsequent cellular adaptation"]'::jsonb, 'Ability to produce maximal response', 'Efficacy (Emax) is the maximum response a drug can produce and is determined by the drug-receptor relationship, not by dose. Potency, in contrast, refers to the dose needed for a given effect.'),
('2d043422-e1bc-52a6-95ec-ed0f8882a375'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Fusobacterium is best described as a:', '["GP rod","GN anaerobic rod","GP coccus","GN aerobic rod","Spirochete"]'::jsonb, 'GN anaerobic rod', 'Fusobacterium species (e.g., F. necrophorum, F. nucleatum) are Gram-negative anaerobic fusiform rods. F. necrophorum causes Lemierre syndrome, and F. nucleatum is implicated in periodontal disease.'),
('cae1038b-b541-56cf-9b74-349df1139474'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Peptostreptococcus is best described as a:', '["GP anaerobic coccus","GN coccus","Spirochete","GN rod","GP rod"]'::jsonb, 'GP anaerobic coccus', 'Peptostreptococci are anaerobic, Gram-positive cocci that are normal flora of the oral cavity, gut, and skin. They frequently cause abscesses and aspiration pneumonia.'),
('35c0f2a2-128e-562a-9703-07cd0f07fd27'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Nocardiosis most characteristically presents with:', '["Cavitation","Granuloma","Sulfur granules","Effusion","Pulmonary and brain abscess"]'::jsonb, 'Pulmonary and brain abscess', 'Nocardia typically produces a pulmonary infection that spreads hematogenously to the brain, giving abscesses. Sulfur granules indicate actinomycosis, not nocardiosis.'),
('92442833-9edc-58f6-8fe3-4e1276a184ae'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Erythema migrans, the hallmark lesion of Lyme disease, is best described as:', '["Petechiae","Vesicles","Bullseye rash (Lyme)","Pustules","Macules"]'::jsonb, 'Bullseye rash (Lyme)', 'Erythema migrans is an expanding annular rash with central clearing (bullseye) at the tick-bite site, appearing 3-30 days after infection with Borrelia burgdorferi. Petechiae and pustules point to other diagnoses.'),
('404c6de2-255f-5122-9036-3228b146cc70'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'FTA-ABS is best classified as a:', '["Non-treponemal","PCR","Treponemal confirmatory","Culture","Screening"]'::jsonb, 'Treponemal confirmatory', 'FTA-ABS detects antibodies to T. pallidum antigens and is a treponemal confirmatory test. Because it stays positive for life, it cannot monitor treatment response; non-treponemal tests are used for that purpose.'),
('9c8ef01c-c6ec-5f73-9dc2-0109b831d504'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Cutibacterium (Propionibacterium) acnes is associated with:', '["Osteomyelitis","UTI","Acne vulgaris","Pneumonia","Meningitis"]'::jsonb, 'Acne vulgaris', 'C. acnes thrives in sebum-rich pilosebaceous follicles and contributes to acne vulgaris by driving follicular inflammation. It also causes prosthetic joint and foreign-body infections.'),
('09d1ab76-4b6b-581d-a0ec-2ae385e62d7c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis characteristically is resistant to which antibiotic?', '["Carbapenems","Penicillin G","Metronidazole","Clindamycin","Vancomycin"]'::jsonb, 'Penicillin G', 'B. fragilis produces beta-lactamases that inactivate penicillins, making penicillin G unreliable. Metronidazole and carbapenems are the preferred agents against this organism.'),
('00c5e7e7-4353-5a78-9cee-4db56f68feda'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Fusobacterium nucleatum is best described as a:', '["Aerobic","Spirochete","GN anaerobic rod","Acid-fast","GP coccus"]'::jsonb, 'GN anaerobic rod', 'F. nucleatum is a Gram-negative anaerobic fusiform rod that is part of the normal oral flora. It contributes to periodontal disease and can cause invasive infections.'),
('7cbf7c2d-ab90-5107-8cfa-155773b772cd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis infections are best treated with:', '["Azithromycin","Metronidazole or carbapenem","Penicillin","Doxycycline","Vancomycin"]'::jsonb, 'Metronidazole or carbapenem', 'B. fragilis is reliably susceptible to metronidazole and carbapenems, the preferred agents for anaerobic intra-abdominal infections. Penicillin is ineffective because of beta-lactamase production.'),
('3913f0ad-fbf7-533b-bed2-c1b324ac7ed9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Botulism is best managed by:', '["Surgery","Antitoxin + supportive care","Vancomycin","Penicillin","Metronidazole"]'::jsonb, 'Antitoxin + supportive care', 'Management consists of antitoxin to neutralize circulating toxin plus supportive care including mechanical ventilation. Recovery follows regeneration of new nerve terminals rather than antibiotic action.'),
('524c4aa8-e3d2-5464-9292-9953c704c8cc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Treponema pallidum is best described as:', '["GP coccus","Acid-fast","GN rod","Virus","A spirochete"]'::jsonb, 'A spirochete', 'T. pallidum is a thin, coiled spirochete that cannot be grown on artificial media. It is visualized by dark-field microscopy and diagnosed serologically.'),
('813b1ede-a476-5a8b-8fcb-204482b88520'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella species commonly cause:', '["UTI resulting in decreased functional activity","Bacteremia accompanied by associated clinical symptoms","Pneumonia mediated by specific receptor activation","Meningitis without affecting the primary tissue pathway","Periodontal infection and abscess"]'::jsonb, 'Periodontal infection and abscess', 'Prevotella, the Gram-negative anaerobic rod predominant in the oral cavity, commonly causes periodontal infection and odontogenic abscess. It rarely causes meningitis or UTI.'),
('1ca65f0e-8405-54da-9aaf-1082d7863eb3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Cutibacterium acnes is a recognized cause of:', '["Dental caries","Prosthetic joint infection","Botulism","Tetanus","Gas gangrene"]'::jsonb, 'Prosthetic joint infection', 'C. acnes is a common cause of prosthetic joint and other device-associated infections, especially in the shoulder. It grows slowly and is easily overlooked as a skin contaminant.'),
('7533703e-385c-58d1-b064-ae38c5d7db91'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. perfringens food poisoning produces:', '["Trismus resulting in decreased functional activity","Enterotoxin (cramps, diarrhea)","Paralysis mediated by specific receptor activation","Colitis without affecting the primary tissue pathway","Fever leading to subsequent cellular adaptation"]'::jsonb, 'Enterotoxin (cramps, diarrhea)', 'Ingestion of C. perfringens type A leads to enterotoxin release in the small intestine, causing cramps and watery diarrhea without fever. Trismus and paralysis belong to tetanus and botulism, respectively.'),
('90bcf9c1-c43c-53d6-974c-97f9a3a6e5c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Nocardiosis classically produces:', '["Granuloma","Pulmonary and brain abscess","Sulfur granules","Cavitation","Effusion"]'::jsonb, 'Pulmonary and brain abscess', 'Nocardia infection starts in the lung and frequently disseminates to the brain, forming abscesses. Sulfur granules are the hallmark of actinomycosis rather than nocardiosis.'),
('f2b81662-34ed-57b2-9415-ac74e34c2a6e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Two-tier serologic testing for Lyme disease consists of:', '["PCR resulting in decreased functional activity","MAT accompanied by associated clinical symptoms","ELISA + Western blot","FTA-ABS without affecting the primary tissue pathway","VDRL leading to subsequent cellular adaptation"]'::jsonb, 'ELISA + Western blot', 'Lyme disease is confirmed by an ELISA or immunoassay followed by a confirmatory Western blot (IgM and IgG). Two-tier testing increases specificity and reduces false-positive results.'),
('cc3cc8ed-32f3-53f8-8ff7-1df0a2713e60'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. tetani is the etiologic agent of:', '["Gas gangrene","Food poisoning","Pseudomembranous colitis","Botulism","Tetanus (lockjaw)"]'::jsonb, 'Tetanus (lockjaw)', 'Tetanospasmin produced by C. tetani blocks inhibitory glycine release, causing generalized spastic paralysis and trismus (lockjaw). The organism enters through contaminated wounds.'),
('090be49a-2513-5cfe-b04b-40a0bda8a473'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Weil disease is caused by:', '["Leptospira interrogans","Treponema pallidum","Borrelia burgdorferi","Borrelia recurrentis","Treponema pertenue"]'::jsonb, 'Leptospira interrogans', 'Weil disease is the more severe icteric form of leptospirosis caused by Leptospira interrogans. It presents with jaundice, renal failure, and hemorrhage, unlike the anicteric form.'),
('9ea44179-3e31-5e8f-906e-696b242df051'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which organism classically produces a double zone of hemolysis on blood agar?', '["C. perfringens","C. difficile","B. fragilis","C. tetani","C. botulinum"]'::jsonb, 'C. perfringens', 'C. perfringens shows a narrow inner zone of complete hemolysis surrounded by a wider zone of partial hemolysis, the classic double-zone pattern. It also gives a positive Nagler reaction on egg-yolk agar.'),
('1c04851e-6a2a-578f-b0ad-e407b6d83cdc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella species are commensals of:', '["Skin resulting in decreased functional activity","Water accompanied by associated clinical symptoms","Air mediated by specific receptor activation","Soil without affecting the primary tissue pathway","Oral and gut flora"]'::jsonb, 'Oral and gut flora', 'Veillonella, Gram-negative anaerobic cocci, are normal inhabitants of the oral cavity and gastrointestinal tract. They rarely cause disease but can be found in mixed anaerobic infections.'),
('dddc3a7b-5cdc-5c7e-b0a5-1346011b0730'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Erythema migrans is best described as:', '["Vesicles","Pustules","Bullseye rash (Lyme)","Petechiae","Macules"]'::jsonb, 'Bullseye rash (Lyme)', 'Erythema migrans is the expanding annular erythema with central clearing typical of early Lyme disease. It appears days to weeks after a bite by an infected Ixodes tick.'),
('e2cc0967-706c-5643-80f4-19b3b1ab0faf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Human tetanus immunoglobulin (HTIG) is administered for:', '["Wound prophylaxis (passive immunization)","Long-term active immunization","Antibiotic therapy for established tetanus","Antipyretic therapy","No role in tetanus"]'::jsonb, 'Wound prophylaxis (passive immunization)', 'HTIG provides immediate neutralizing antibody against tetanospasmin and is given with wound debridement in individuals with high-risk wounds and unknown or inadequate vaccination. Active immunization with toxoid is started at the same visit.'),
('100f3a5f-e80a-5a06-96f0-8d3466bbe0a2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. perfringens is best described as a:', '["GP spore-forming rod","GP coccus","Acid-fast","Spirochete","GN rod"]'::jsonb, 'GP spore-forming rod', 'C. perfringens is a large Gram-positive, encapsulated, spore-forming anaerobic rod. It causes gas gangrene, food poisoning, and other clostridial infections.'),
('c925bd1d-64a9-5bfd-94d3-1a9fc73f6882'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella species are best described as:', '["Aerobic","GN anaerobic rod","Acid-fast","Spirochete","GP coccus"]'::jsonb, 'GN anaerobic rod', 'Prevotella organisms are Gram-negative anaerobic rods that dominate the oral flora and cause periodontal and odontogenic abscesses. They are neither aerobic, acid-fast, nor spirochetes.'),
('cfcfcb0f-bca9-5960-9fa8-a3c2dca2ddcb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Peptostreptococcus species are a common cause of which condition?', '["Brain and dental abscess","UTI accompanied by associated clinical symptoms","Pneumonia mediated by specific receptor activation","Diarrhea without affecting the primary tissue pathway","Meningitis leading to subsequent cellular adaptation"]'::jsonb, 'Brain and dental abscess', 'Peptostreptococcus, an anaerobic Gram-positive coccus, is a frequent isolate in brain abscesses and dental abscesses. It is not a recognized cause of diarrhea or primary UTI.'),
('a6f75dab-48c7-5c81-90d1-f5d28ade6446'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which molecular diagnostic can detect Treponema pallidum DNA in clinical specimens?', '["Dark-field microscopy","FTA-ABS","VDRL","PCR","Culture"]'::jsonb, 'PCR', 'PCR amplifies T. pallidum DNA from lesions, blood, or CSF and is especially useful in congenital and neurosyphilis. T. pallidum cannot be cultivated on artificial media, ruling out culture.'),
('51917162-24be-5acf-a616-5283baa3026c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Botulinum toxin produces its characteristic effect by:', '["Enterotoxin","Cytotoxin","Blocks glycine","Blocks ACh release (flaccid)","Lecithinase"]'::jsonb, 'Blocks ACh release (flaccid)', 'Botulinum toxin blocks presynaptic acetylcholine release at motor end-plates, causing symmetric flaccid paralysis. Blockade of glycine release instead underlies tetanus spastic paralysis.'),
('786d4441-35e8-5f16-b2f5-02fd10945a2e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Weil disease, the most severe form of leptospirosis, is best described as:', '["Anicteric","Icteric leptospirosis","Meningitis","Hepatitis","Pneumonia"]'::jsonb, 'Icteric leptospirosis', 'Weil disease is icteric leptospirosis marked by jaundice, acute renal failure, and hemorrhagic manifestations. The anicteric form of leptospirosis is much more common and mild.'),
('88ca9f62-a578-54dc-9224-cab498b0e70a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Fusobacterium necrophorum is best described as:', '["Spirochete","GN aerobic rod","GP coccus","GP rod","GN anaerobic rod"]'::jsonb, 'GN anaerobic rod', 'F. necrophorum is a Gram-negative anaerobic fusiform rod and the classic cause of Lemierre syndrome (postanginal septicemia with thrombophlebitis of the internal jugular vein). It is part of the normal oropharyngeal flora.'),
('55d122f3-61a3-5a9a-85c7-291afa179dfd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Cutibacterium (Propionibacterium) acnes is classically associated with:', '["Acne vulgaris","Pneumonia","Osteomyelitis","UTI","Meningitis"]'::jsonb, 'Acne vulgaris', 'Cutibacterium acnes is an anaerobic lipophilic rod that colonises sebaceous follicles and drives the inflammatory lesions of acne vulgaris.'),
('82dff4ae-2fb4-5983-8a27-4f29e73c9dd7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which clostridial species characteristically produces a double zone of hemolysis on blood agar?', '["B. fragilis","C. tetani","C. botulinum","C. perfringens","C. difficile"]'::jsonb, 'C. perfringens', 'C. perfringens shows a wide double zone of hemolysis on blood agar, produced by theta toxin (complete inner zone) and alpha toxin lecithinase (outer zone).'),
('e8bb6cc4-e11f-598b-8570-d8fa585f90ea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis is a principal cause of which infection after bowel surgery or perforation?', '["Intra-abdominal abscess","Meningitis","Pneumonia","UTI","Endocarditis"]'::jsonb, 'Intra-abdominal abscess', 'B. fragilis, the most aerotolerant Bacteroides, is the commonest anaerobe isolated from intra-abdominal abscesses after colonic contamination of the peritoneum; its capsule promotes abscess formation.'),
('f81cb13e-5053-5cf5-a220-5283bab423d3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The tetanus vaccine is best described as a:', '["Live attenuated","Recombinant","Toxoid (DTaP/Tdap)","Polysaccharide","Killed whole"]'::jsonb, 'Toxoid (DTaP/Tdap)', 'Tetanus vaccine is a formalin-inactivated toxoid of tetanospasmin, administered as DTaP, Tdap or Td, which stimulates protective antitoxin antibodies.'),
('8d71a90c-5f38-557a-bd3c-892a856b7c6c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium perfringens causes:', '["Pseudomembranous colitis","Gas gangrene (myonecrosis)","Tetanus","Food poisoning","Botulism"]'::jsonb, 'Gas gangrene (myonecrosis)', 'C. perfringens type A is the chief cause of gas gangrene (clostridial myonecrosis): alpha toxin (lecithinase) destroys muscle and evolving gas; its enterotoxin separately causes food poisoning.'),
('d522907a-1e5a-5840-9b78-494b54629e68'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Borrelia burgdorferi causes:', '["Relapsing fever","Leptospirosis","Yaws","Syphilis","Lyme disease"]'::jsonb, 'Lyme disease', 'B. burgdorferi is the tick-borne spirochete that causes Lyme disease, with erythema migrans, arthritis, and neurologic and cardiac manifestations.'),
('41b4fbdc-5d77-5bef-bb83-34575c83d83e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Veillonella is best described as a:', '["GN anaerobic coccus","GP coccus","Spirochete","GN rod","GP rod"]'::jsonb, 'GN anaerobic coccus', 'Veillonella are small Gram-negative anaerobic cocci that are part of the normal oral, gastrointestinal, and vaginal flora and occasional opportunists.'),
('ae4bf553-12af-55a6-8882-bb9c7358c25b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis is most commonly associated with:', '["Intra-abdominal abscess","UTI","Meningitis","Pneumonia","Endocarditis"]'::jsonb, 'Intra-abdominal abscess', 'The capsular polysaccharide of B. fragilis promotes abscess formation in the peritoneal cavity after colonic surgery or perforation.'),
('4fa1f4cb-69a8-522f-be2f-29f6a30c7585'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis is classified as a:', '["GP rod","GN anaerobic rod","GN aerobic rod","GP coccus","Spirochete"]'::jsonb, 'GN anaerobic rod', 'Bacteroides are Gram-negative obligate anaerobic rods that constitute the major anaerobes of the normal colonic flora.'),
('f8607a13-7677-5e95-8152-d2cdd3a93e3b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Nocardia is distinguished from Actinomyces by which property?', '["Acid-fast (partial)","Spirochete","GP branching filamentous (aerobic)","Fungus","GN rod"]'::jsonb, 'Acid-fast (partial)', 'Both Nocardia and Actinomyces are Gram-positive branching filamentous bacteria, but only Nocardia is partially acid-fast on the modified Kinyoun stain.'),
('e8b36a11-4524-5295-8708-d6ecdd9a7aea'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella is best classified as a:', '["Spirochete","GP coccus","GN anaerobic rod","Acid-fast","Aerobic"]'::jsonb, 'GN anaerobic rod', 'Prevotella species are Gram-negative obligate anaerobic rods of the oral cavity and gut that cause periodontal and mixed anaerobic infections.'),
('e1d7d890-0da5-582a-a0e7-20f2dd80de7f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Lemierre syndrome (postanginal septicemia) is classically caused by:', '["Clostridium","B. fragilis","Prevotella","F. necrophorum","Actinomyces"]'::jsonb, 'F. necrophorum', 'Fusobacterium necrophorum causes Lemierre syndrome: pharyngitis followed by septic thrombophlebitis of the internal jugular vein and metastatic abscesses, mainly in young adults.'),
('2bcdaa39-8ba4-54d1-91b2-09ae77a7e05a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium tetani causes:', '["Pseudomembranous colitis","Food poisoning","Gas gangrene","Botulism","Tetanus (lockjaw)"]'::jsonb, 'Tetanus (lockjaw)', 'C. tetani produces tetanospasmin, a neurotoxin that blocks inhibitory spinal interneurons, causing generalized spastic paralysis with trismus or lockjaw.'),
('fdf0885a-979b-56c0-acf2-3ddc559baff0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium difficile causes pseudomembranous colitis mainly through:', '["Tetanospasmin resulting in decreased functional activity","Lecithinase accompanied by associated clinical symptoms","Botulinum toxin mediated by specific receptor activation","Neurotoxin without affecting the primary tissue pathway","Toxin A (enterotoxin) and B (cytotoxin)"]'::jsonb, 'Toxin A (enterotoxin) and B (cytotoxin)', 'C. difficile elaborates toxin A, an enterotoxin that damages the colonic mucosa, and toxin B, a potent cytotoxin; together they drive pseudomembranous colitis.'),
('0c056eb5-bb66-5dda-84c7-024ee81628e9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Infant botulism is classically linked to which vehicle?', '["Honey source (floppy baby)","All accompanied by associated clinical symptoms","Food source mediated by specific receptor activation","Unknown without affecting the primary tissue pathway","Wound source leading to subsequent cellular adaptation"]'::jsonb, 'Honey source (floppy baby)', 'Infant botulism follows ingestion of C. botulinum spores, classically from honey, that germinate in the immature gut and produce toxin, causing the floppy-baby syndrome.'),
('e8e4fde7-0ad8-582f-b75d-b345af927f36'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Relapsing fever is characterised by:', '["Repeated febrile episodes","Continuous fever","Single febrile episode","Low-grade evening fever","Persistent remittent fever"]'::jsonb, 'Repeated febrile episodes', 'Relapsing fever presents with recurring febrile paroxysms separated by afebrile intervals; each relapse reflects antigenic variation of Borrelia surface proteins.'),
('4460d574-c97d-56d5-93aa-81f938c41717'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Tertiary syphilis is characterised by:', '["Gumma, aortitis, and neurosyphilis","Painless chancre","Secondary rash","Condyloma lata","Mucous patches"]'::jsonb, 'Gumma, aortitis, and neurosyphilis', 'Late (tertiary) syphilis, appearing years after untreated infection, manifests as gummatous lesions, cardiovascular syphilis (ascending aortitis), and neurosyphilis.'),
('3a35a6b0-ef2b-5df2-b2b7-7b10cc65f8e3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The severe icteric form of leptospirosis is termed:', '["Weil disease","Yaws","Relapsing fever","Syphilis","Lyme disease"]'::jsonb, 'Weil disease', 'Weil disease is the severe icteric form of leptospirosis, combining jaundice, acute renal failure, and hemorrhage, with substantial mortality.'),
('cfd9b82d-b056-5500-ace5-065ac31d0eed'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella is an important cause of:', '["Pneumonia resulting in decreased functional activity","Periodontal infection and abscess","Meningitis mediated by specific receptor activation","Bacteremia without affecting the primary tissue pathway","UTI leading to subsequent cellular adaptation"]'::jsonb, 'Periodontal infection and abscess', 'Prevotella species, including P. intermedia, are periodontal pathogens causing gingivitis, periodontitis, and dental abscesses as part of the mixed anaerobic flora.'),
('310b5a57-e873-5fa5-8608-2c42db28d69b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Yaws is characterised by:', '["Skin papilloma and bone lesions","Congenital accompanied by associated clinical symptoms","Neurologic mediated by specific receptor activation","Cardiovascular without affecting the primary tissue pathway","STD leading to subsequent cellular adaptation"]'::jsonb, 'Skin papilloma and bone lesions', 'Yaws, caused by T. pallidum subsp. pertenue, is a non-venereal tropical treponematosis of childhood producing papillomatous skin lesions and later bone deformities.'),
('b17cf893-916e-5d79-9c0a-288d8150a8c3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium species are best described as:', '["Acid-fast","Spirochete","GP spore-forming rod","GN rod","GP coccus"]'::jsonb, 'GP spore-forming rod', 'Clostridia are Gram-positive, strictly anaerobic, spore-forming rods; spore formation underlies their persistence in soil and the environment.'),
('537888d3-1f9a-54a2-9183-089f2abd75f4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The major tissue-destructive toxin of Clostridium perfringens is:', '["Tetanospasmin","Neurotoxin","Botulinum toxin","Enterotoxin","Lecithinase (phospholipase C)"]'::jsonb, 'Lecithinase (phospholipase C)', 'The alpha toxin of C. perfringens is a lecithinase (phospholipase C) that degrades cell membranes, driving the myonecrosis of gas gangrene.'),
('319f36f6-c79e-5f58-835e-c36b2cdab9bd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'T. pallidum subsp. pertenue causes:', '["Leptospirosis","Relapsing fever","Lyme disease","Syphilis","Yaws"]'::jsonb, 'Yaws', 'Treponema pallidum subsp. pertenue causes yaws, a chronic non-venereal treponematosis transmitted by direct skin contact in tropical regions.'),
('57c9d405-cabf-57e8-bb96-099d44c5c346'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'For early localized Lyme disease (erythema migrans), doxycycline is best described as the:', '["DOC for early Lyme disease","Prophylaxis-only agent","Reserved for late disease","Second-line alternative","Ineffective oral agent"]'::jsonb, 'DOC for early Lyme disease', 'Doxycycline is the drug of choice for early localized Lyme disease in adults; amoxicillin and cefuroxime axetil are alternatives.'),
('701c73c3-6427-5c0f-8149-487def7ad6fd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which regimen is preferred for the treatment of B. fragilis infections?', '["Vancomycin","Doxycycline","Azithromycin","Penicillin","Metronidazole or carbapenem"]'::jsonb, 'Metronidazole or carbapenem', 'B. fragilis produces beta-lactamase and is resistant to penicillins; metronidazole or a carbapenem (e.g., meropenem, ertapenem) is the preferred agent.'),
('5995cd03-68ee-50da-84c2-9143394e5a9e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Porphyromonas gingivalis is a key cause of:', '["Periodontitis","Pneumonia","Gingivitis","UTI","Abscess"]'::jsonb, 'Periodontitis', 'P. gingivalis is a black-pigmented anaerobic rod central to the pathogenesis of chronic periodontitis and periodontal tissue destruction.'),
('1779272b-2809-5d11-83d4-168c6602fde4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The maintenance dose of a drug depends primarily on its:', '["Clearance","Volume of distribution","Half-life","Bioavailability","Protein binding"]'::jsonb, 'Clearance', 'At steady state the rate of drug administration equals the rate of elimination, so the maintenance dose (CL x Css x tau / F) is determined chiefly by clearance.'),
('897f2e18-b767-54a7-96c4-25f03b53d92d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella is associated with which clinical entity?', '["UTI resulting in decreased functional activity","Periodontal infection and abscess","Bacteremia mediated by specific receptor activation","Pneumonia without affecting the primary tissue pathway","Meningitis leading to subsequent cellular adaptation"]'::jsonb, 'Periodontal infection and abscess', 'Prevotella are major components of the oral anaerobic flora and frequent isolates from periodontal pockets and dental abscesses.'),
('cbc4872b-0e8d-5c44-9e68-cc3db1fb7d8c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Nocardiosis is classically associated with:', '["Pulmonary and brain abscess","Sulfur granules in pus","Granuloma","Cavitation","Pleural effusion"]'::jsonb, 'Pulmonary and brain abscess', 'Nocardia asteroides complex causes necrotizing pneumonia with abscess formation and hematogenous spread to the brain, giving brain abscesses especially in immunocompromised hosts.'),
('91dbf7fd-dbc6-55ae-b6a9-aa6d669e35ae'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Peptostreptococcus is commonly isolated from:', '["Brain and dental abscess","Meningitis accompanied by associated clinical symptoms","Pneumonia mediated by specific receptor activation","Diarrhea without affecting the primary tissue pathway","UTI leading to subsequent cellular adaptation"]'::jsonb, 'Brain and dental abscess', 'Peptostreptococcus, a Gram-positive anaerobic coccus of the oral flora, is commonly recovered along with other anaerobes from brain and dental abscesses.'),
('7a8852f4-feb7-5db8-9826-d736e7013417'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which organism classically causes Lemierre syndrome (septic jugular thrombophlebitis after pharyngitis)?', '["B. fragilis","Actinomyces","Prevotella","F. necrophorum","Clostridium"]'::jsonb, 'F. necrophorum', 'Fusobacterium necrophorum causes Lemierre syndrome, in which septic emboli from jugular vein thrombosis shower the lungs and joints after oropharyngeal infection.'),
('892306a8-226a-58f4-b03f-ed7a8b9b82b7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Penicillin G is best described as the treatment for syphilis:', '["DOC for all stages","Only in primary","Only in congenital","Second-line","Reserved for penicillin-allergic patients"]'::jsonb, 'DOC for all stages', 'Benzathine penicillin G remains the drug of choice for every stage of syphilis and is the only regimen acceptable in pregnancy unless there is anaphylaxis risk.'),
('2dc5e270-2daf-5a47-a352-9beccc864e41'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Late congenital syphilis classically manifests with:', '["Hutchinson teeth, saddle nose, and deafness","Painless chancre accompanied by associated clinical symptoms","Gumma mediated by specific receptor activation","Secondary rash without affecting the primary tissue pathway","Condyloma lata leading to subsequent cellular adaptation"]'::jsonb, 'Hutchinson teeth, saddle nose, and deafness', 'Late stigmata of congenital syphilis include Hutchinson teeth, saddle nose, interstitial keratitis, and eighth-nerve deafness.'),
('f398718c-27e0-549b-8c82-2cdddd8f704c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Weil disease refers to which clinical form of leptospirosis?', '["Anicteric leptospirosis","Aseptic meningitis","Hepatitis","Pneumonia","Icteric leptospirosis"]'::jsonb, 'Icteric leptospirosis', 'Weil disease is the severe icteric form of leptospirosis, with jaundice, acute renal failure, and hemorrhage due to generalized vasculitis.'),
('64c23c6a-30c9-5f70-8977-55350181423e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Cutibacterium (Propionibacterium) acnes can cause:', '["Gas gangrene","Dental caries","Botulism","Tetanus","Prosthetic joint infection"]'::jsonb, 'Prosthetic joint infection', 'C. acnes, a slow-growing anaerobe of the skin, is increasingly recognized as a cause of indolent prosthetic joint infections, especially of the shoulder.'),
('f94ca799-8afd-5bc5-982b-ed8e446f230b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The microscopic agglutination test (MAT) is the serologic reference standard for the:', '["Diagnosis of leptospirosis","Diagnosis of syphilis","Diagnosis of Lyme disease","Diagnosis of Q fever","Diagnosis of brucellosis"]'::jsonb, 'Diagnosis of leptospirosis', 'MAT detects agglutinating antibodies against leptospires and is the reference serologic test for the diagnosis of leptospirosis.'),
('b17d9f55-d18a-5c26-9722-6444be34f6df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which regimen is the treatment of choice for leptospirosis?', '["Clindamycin","Metronidazole","Vancomycin","Azithromycin","Penicillin or doxycycline"]'::jsonb, 'Penicillin or doxycycline', 'Mild leptospirosis is treated with doxycycline and severe disease with intravenous penicillin G; both shorten the illness when started early.'),
('142958c1-f812-5eb9-acc7-73dc95cf1668'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The pus of actinomycosis characteristically contains:', '["Sulfur granules in pus","Abscess","Cavitation","Caseation","Granuloma"]'::jsonb, 'Sulfur granules in pus', 'Actinomycotic abscesses contain yellow sulfur granules, which are conglomerates of branching Actinomyces filaments enmeshed with host protein.'),
('6335c0ae-9947-52be-a0c2-39c684361ff1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The classic anaerobic pathogen of Lemierre syndrome is:', '["Actinomyces","B. fragilis","Clostridium","F. necrophorum","Prevotella"]'::jsonb, 'F. necrophorum', 'Fusobacterium necrophorum is the classic pathogen of Lemierre syndrome, following tonsillar infection in adolescents and young adults.'),
('a379e61f-bd6a-5d1e-a503-16abe9828a5b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Primary syphilis is characterised by:', '["Condyloma lata","Gumma","Painless chancre","Painful ulcer","Macular rash"]'::jsonb, 'Painless chancre', 'Primary syphilis begins with a painless, indurated chancre at the inoculation site about three weeks after exposure, with regional lymphadenopathy.'),
('5f06aa8d-d252-50cc-aa56-033e8965d265'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Human tetanus immunoglobulin (HTIG) is used for:', '["HTIG for wound prophylaxis in incompletely immunized patients","Active immunization accompanied by associated clinical symptoms","Antibiotic therapy for tetanus mediated by specific receptor activation","Routine childhood vaccination without affecting the primary tissue pathway","Treatment of botulism leading to subsequent cellular adaptation"]'::jsonb, 'HTIG for wound prophylaxis in incompletely immunized patients', 'HTIG provides immediate passive antitoxin and is given at the time of wound management when the patient''s tetanus immunization is incomplete or unknown.'),
('2980c7fc-a44f-5581-891b-c91e990ba5de'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides species are best classified as:', '["GN anaerobic rod","Spirochete","GP rod","GP coccus","GN aerobic rod"]'::jsonb, 'GN anaerobic rod', 'Bacteroides are Gram-negative obligate anaerobic rods that dominate the anaerobic flora of the colon and cause mixed abdominal infections.'),
('65b2a587-ea0b-5d39-9a2e-e8b99e1664c7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella and Bacteroides are both classified as:', '["Aerobic","GP coccus","Spirochete","Acid-fast","GN anaerobic rod"]'::jsonb, 'GN anaerobic rod', 'Both genera are Gram-negative obligate anaerobic rods that dominate the anaerobic flora of the gut and oral cavity.'),
('cf2abe4e-0882-5c19-a795-93fde3705848'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which method detects Treponema pallidum DNA directly from clinical specimens?', '["PCR","VDRL","FTA-ABS","Culture","Dark-field microscopy"]'::jsonb, 'PCR', 'T. pallidum cannot be cultured on artificial media; nucleic acid amplification (PCR) detects its DNA directly from lesions, placenta, or cerebrospinal fluid.'),
('b2713325-2f60-5b29-9ff7-f9f64de598e5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Human tetanus immunoglobulin (HTIG) is indicated for:', '["HTIG for wound prophylaxis in unimmunized patients","Antibiotic accompanied by associated clinical symptoms","Vaccine mediated by specific receptor activation","Treatment of established tetanus without affecting the primary tissue pathway","Antitoxin for botulism leading to subsequent cellular adaptation"]'::jsonb, 'HTIG for wound prophylaxis in unimmunized patients', 'HTIG is given together with the first tetanus toxoid dose at wound care so that passive protection bridges the time until active immunity develops.'),
('2e6f1b04-f29c-54d6-9e53-177fb00a54a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Postanginal septicemia with jugular vein thrombosis (Lemierre syndrome) is caused by:', '["Actinomyces","Clostridium","Prevotella","F. necrophorum","B. fragilis"]'::jsonb, 'F. necrophorum', 'Fusobacterium necrophorum causes postanginal septicemia and internal jugular vein thrombophlebitis with metastatic abscess formation.'),
('64eaf619-e040-5146-8f77-d44eb07b8c08'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Vincent angina (necrotizing ulcerative gingivitis) is caused by infection with:', '["Treponema","Fusobacterium","Clostridium","Leptospira","Borrelia"]'::jsonb, 'Fusobacterium', 'Vincent angina is a fusospirochetal infection combining Fusobacterium nucleatum with oral spirochetes such as Borrelia vincentii.'),
('fb1370b7-15e4-5251-ad0b-aa10d3de5f7d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'In untreated Lyme disease, arthritis most often involves the:', '["Knee oligoarticular","Shoulder","Small joints","Hip","Spine"]'::jsonb, 'Knee oligoarticular', 'Lyme arthritis causes recurrent, asymmetric oligoarticular swelling, most often of one or both knees, months after the initial infection.'),
('d0a41c22-c4c7-5f50-a0ee-33656d85e284'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'St. John''s Wort is a potent inducer of:', '["CYP3A4 and P-gp","CYP2D6","CYP2C9","CYP1A2","CYP2C19"]'::jsonb, 'CYP3A4 and P-gp', 'St. John''s Wort induces CYP3A4 and P-glycoprotein, lowering plasma levels of drugs such as warfarin, cyclosporine, and oral contraceptives.'),
('f19473b5-e679-5146-9a01-cabe78a5cd6b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The classic stigmata of late congenital syphilis include:', '["Hutchinson teeth, saddle nose, and deafness","Rash accompanied by associated clinical symptoms","Painless chancre mediated by specific receptor activation","Gumma without affecting the primary tissue pathway","Condyloma lata leading to subsequent cellular adaptation"]'::jsonb, 'Hutchinson teeth, saddle nose, and deafness', 'Late congenital syphilis stigmata include Hutchinson teeth, saddle nose deformity, interstitial keratitis, and eighth-nerve deafness.'),
('6339f1d1-251f-5191-82d9-5debeee5dd0f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Porphyromonas gingivalis is a major pathogen of:', '["Pneumonia","Abscess","Periodontitis","UTI","Gingivitis"]'::jsonb, 'Periodontitis', 'P. gingivalis, a black-pigmented anaerobic rod, is a major pathogen of periodontitis, driving gingival inflammation and alveolar bone loss.'),
('50400be2-313b-54c6-8698-602a478d1d2d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis causes:', '["Intra-abdominal abscess","Meningitis","Endocarditis","UTI","Pneumonia"]'::jsonb, 'Intra-abdominal abscess', 'B. fragilis is the anaerobe most frequently recovered from intra-abdominal abscesses, which complicate bowel perforation or surgery.'),
('64de923d-7c14-5d68-afe0-e23947e96b20'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The fusospirochetal organism classically implicated in Vincent angina is:', '["Leptospira","Treponema","Clostridium","Borrelia","Fusobacterium"]'::jsonb, 'Fusobacterium', 'Vincent angina is a fusospirochetal infection in which Fusobacterium (fusiform bacilli) acts together with oral spirochetes.'),
('61385797-ce23-54d8-a724-c4913abd12d0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Recommended two-tier serologic testing for Lyme disease involves:', '["ELISA + Western blot","MAT accompanied by associated clinical symptoms","FTA-ABS mediated by specific receptor activation","PCR without affecting the primary tissue pathway","VDRL leading to subsequent cellular adaptation"]'::jsonb, 'ELISA + Western blot', 'Lyme disease is confirmed by a sensitive ELISA screen followed by Western blot, the two-tier strategy that reduces false-positive results.'),
('8d4ab8f7-71e0-5264-9d58-1e46ee3122a4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Botulism is treated with:', '["Antitoxin + supportive care","Penicillin","Vancomycin","Metronidazole","Surgical debridement"]'::jsonb, 'Antitoxin + supportive care', 'Treatment of botulism relies on passive antitoxin and intensive supportive care, especially ventilator support; antibiotics do not reverse the paralysis.'),
('47bb6808-e25e-5a87-b612-e0df66b83991'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium species are classified as:', '["GP spore-forming rod","GP coccus","Spirochete","GN rod","Acid-fast"]'::jsonb, 'GP spore-forming rod', 'Clostridia are Gram-positive obligate anaerobes that form subterminal or terminal spores, a property central to their identification.'),
('a2182fd8-f224-58b1-8eb0-bdc6de3c5fd7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'On modified acid-fast (Kinyoun) staining, Nocardia typically appears:', '["Acid-fast (partial)","Spirochete","GN rod","Fungus","GP branching filamentous (aerobic)"]'::jsonb, 'Acid-fast (partial)', 'Nocardia is partially acid-fast, staining pink on the modified Kinyoun method, which distinguishes it from Actinomyces.'),
('8041e344-2b00-550b-8830-e65db67e7ec1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The presence of sulfur granules in pus is characteristic of:', '["Sulfur granules in pus","Caseation","Granuloma","Abscess","Cavitation"]'::jsonb, 'Sulfur granules in pus', 'Sulfur granules are tangled filaments of Actinomyces embedded in pus and protein, the microscopic hallmark of actinomycosis.'),
('65f0a24e-b15d-5256-8047-8c6e44814332'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Congenital syphilis is classically associated with:', '["Hutchinson teeth, saddle nose, and deafness","Gumma accompanied by associated clinical symptoms","Rash mediated by specific receptor activation","Chancres without affecting the primary tissue pathway","Condyloma lata leading to subsequent cellular adaptation"]'::jsonb, 'Hutchinson teeth, saddle nose, and deafness', 'Transplacental infection of the fetus produces stigmata such as Hutchinson teeth, saddle nose, interstitial keratitis, and deafness.'),
('964425f9-e244-5300-b5ca-685a00228cdf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Actinomyces is best classified as a:', '["GP coccus","GN coccus","GN rod","GP anaerobic rod","Spirochete"]'::jsonb, 'GP anaerobic rod', 'Actinomyces is a Gram-positive branching anaerobic rod (branching filamentous bacillus) that causes slowly progressive abscesses with sulfur granules.'),
('79ed7cab-66f3-5767-b17e-647d8b8cc499'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Weak acids are trapped (ionised) in:', '["Alkaline urine","Acidic stomach","Blood pH 7.4","Duodenum","Jejunum"]'::jsonb, 'Alkaline urine', 'Weak acids remain non-ionized in acidic urine and are reabsorbed; in alkaline urine they are ionized and cannot cross membranes, so they are trapped and excreted.'),
('84710f85-61af-53d4-88c6-5d0405716f66'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Actinomycosis is characterised by:', '["Sulfur granules in pus","Abscess","Cavitation","Granuloma","Caseation"]'::jsonb, 'Sulfur granules in pus', 'Actinomycosis is marked by chronic suppuration with draining sinuses and the presence of yellow sulfur granules in the pus.'),
('b48107cf-c433-545e-9652-53819a4b3894'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'The treatment of choice for B. fragilis infection is:', '["Doxycycline","Azithromycin","Penicillin","Metronidazole or carbapenem","Vancomycin"]'::jsonb, 'Metronidazole or carbapenem', 'Because B. fragilis produces beta-lactamase, metronidazole or a carbapenem (meropenem, ertapenem) is used; penicillin is ineffective.'),
('1c961c25-1772-5e99-8126-51964a41a563'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Borrelia recurrentis causes:', '["Yaws","Syphilis","Lyme disease","Relapsing fever","Leptospirosis"]'::jsonb, 'Relapsing fever', 'B. recurrentis, transmitted by the human body louse, causes louse-borne (epidemic) relapsing fever.'),
('048e3a35-620b-5d0b-973f-21695dcd6774'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Porphyromonas gingivalis is associated with:', '["Periodontitis","Gingivitis","Abscess","UTI","Pneumonia"]'::jsonb, 'Periodontitis', 'P. gingivalis is a black-pigmented anaerobic rod tightly linked to chronic periodontitis and tooth loss.'),
('4ddfecd6-3ccc-55a7-b7be-6521d1502518'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Peptostreptococcus causes:', '["UTI resulting in decreased functional activity","Brain and dental abscess","Pneumonia mediated by specific receptor activation","Diarrhea without affecting the primary tissue pathway","Meningitis leading to subsequent cellular adaptation"]'::jsonb, 'Brain and dental abscess', 'Peptostreptococcus, a member of the oral and gut flora, is often recovered from polymicrobial brain and dental abscesses.'),
('1d711076-6c46-5f2a-84ec-4d408c656e58'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which device-associated infection is classically caused by Cutibacterium (Propionibacterium) acnes?', '["Gas gangrene","Prosthetic joint infection","Dental caries","Botulism","Tetanus"]'::jsonb, 'Prosthetic joint infection', 'C. acnes is a classic cause of slow, indolent prosthetic joint infections, particularly of the shoulder.'),
('be89267f-7fcd-5059-abd0-4f1fb423c884'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Tetanospasmin causes spastic paralysis by:', '["Blocking glycine release (disinhibition)","Blocking ACh release","Enterotoxin","Lecithinase","Activating adenylate cyclase"]'::jsonb, 'Blocking glycine release (disinhibition)', 'Tetanospasmin blocks the release of inhibitory neurotransmitters (glycine and GABA) in the spinal cord, yielding unopposed motor neuron firing and spasticity.'),
('5bdeb636-ed39-5d7d-880f-2d0a340dc085'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'On modified Kinyoun staining, Nocardia appears:', '["Acid-fast (partial)","Spirochete","GN rod","Fungus","GP branching filamentous (aerobic)"]'::jsonb, 'Acid-fast (partial)', 'Nocardia is partially acid-fast on modified Kinyoun staining, an important distinguishing feature from other branching organisms.'),
('96f23921-92fa-5c71-955e-e47c25b07d28'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which of the following is a recognised risk factor for Clostridium difficile infection?', '["Hospitalization","PPI use","Antibiotic use (clindamycin)","Surgery","All of the above"]'::jsonb, 'All of the above', 'Hospitalization, proton pump inhibitors, surgery, and especially antibiotic use (e.g., clindamycin) all predispose to C. difficile infection.'),
('d889040b-c858-56a7-ad4d-968252e7b836'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Lemierre syndrome is most often caused by:', '["Actinomyces","Clostridium","B. fragilis","Prevotella","F. necrophorum"]'::jsonb, 'F. necrophorum', 'Fusobacterium necrophorum is the cause of Lemierre syndrome, a complication of pharyngitis with internal jugular septic thrombophlebitis.'),
('053d2d99-b3e7-566c-85d6-96ad5814b7d1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Prevotella species are important in which infection?', '["Meningitis resulting in decreased functional activity","Pneumonia accompanied by associated clinical symptoms","Periodontal infection and abscess","Bacteremia without affecting the primary tissue pathway","UTI leading to subsequent cellular adaptation"]'::jsonb, 'Periodontal infection and abscess', 'Prevotella are oral anaerobic rods that dominate periodontal pockets and are common in dental abscesses.'),
('142b2844-5125-5ba1-8cbc-dc69d8634fd4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Peptostreptococcus is commonly recovered from which site of infection?', '["UTI resulting in decreased functional activity","Pneumonia accompanied by associated clinical symptoms","Brain and dental abscess","Meningitis without affecting the primary tissue pathway","Diarrhea leading to subsequent cellular adaptation"]'::jsonb, 'Brain and dental abscess', 'As a commensal of the mouth and gut, Peptostreptococcus frequently participates in polymicrobial brain and dental abscesses.'),
('3c2e9571-6b87-5bf7-9f12-f1a7f9604bcb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Botulinum toxin produces which clinical picture?', '["Botulism (flaccid paralysis)","Tetanus (spastic paralysis)","Food poisoning","Pseudomembranous colitis","Gas gangrene"]'::jsonb, 'Botulism (flaccid paralysis)', 'By blocking presynaptic acetylcholine release, botulinum toxin causes symmetric descending flaccid paralysis without sensory loss.'),
('83f6176e-d908-5e1c-8f4e-966c47b48a74'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'S-warfarin, the more potent enantiomer, is chiefly metabolised by:', '["CYP2C9","CYP3A4","CYP2D6","CYP2C19","CYP1A2"]'::jsonb, 'CYP2C9', 'S-warfarin is mainly hydroxylated by CYP2C9; genetic variants or inhibitors of this enzyme markedly increase the anticoagulant effect.'),
('f636e636-468f-5e55-9451-ef68471c7c63'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Bacteroides fragilis is a:', '["GN anaerobic rod","Acid-fast","GP coccus","Spirochete","Aerobic organism"]'::jsonb, 'GN anaerobic rod', 'Bacteroides fragilis is a Gram-negative obligate anaerobic rod and the principal anaerobe of the colonic flora.'),
('0a96e56e-042f-53c9-b72f-08e3e3841f99'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Erythema migrans is best described as a:', '["Bullseye rash (Lyme)","Vesicles","Pustules","Petechiae","Macules"]'::jsonb, 'Bullseye rash (Lyme)', 'Erythema migrans is the annular red bullseye rash that expands outward from the tick bite in early localized Lyme disease.'),
('983c8331-6ab2-54ba-b49e-895f3691273d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Infant botulism is classically transmitted by which vehicle?', '["Honey source (floppy baby)","Wound source","Food source (canned goods)","All of the above","Unknown source"]'::jsonb, 'Honey source (floppy baby)', 'Infant botulism follows ingestion of C. botulinum spores, classically from honey, that germinate in the immature colon and produce toxin, causing floppy-baby hypotonia.'),
('4a96f915-60e1-552a-b057-78d4e95e2f0d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Vincent angina is a fusospirochetal infection in which the main bacterial partner is:', '["Fusobacterium","Borrelia","Clostridium","Treponema","Leptospira"]'::jsonb, 'Fusobacterium', 'Vincent angina (acute necrotizing ulcerative gingivitis) involves a synergistic fusospirochetal infection, chiefly with Fusobacterium nucleatum.'),
('adb3a27c-08d6-5089-b626-c7cd052f23db'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Epidemic relapsing fever (B. recurrentis) is transmitted by the:', '["Body louse (Pediculus humanus)","Tick accompanied by associated clinical symptoms","Flea mediated by specific receptor activation","Mosquito without affecting the primary tissue pathway","Sandfly leading to subsequent cellular adaptation"]'::jsonb, 'Body louse (Pediculus humanus)', 'B. recurrentis is transmitted by the human body louse (Pediculus humanus); endemic tick-borne relapsing fever is caused by Borrelia hermsii.'),
('6762ae1c-b790-5cf0-8567-65493d1e6fe0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'C. tetani infection produces:', '["Tetanus (lockjaw)","Gas gangrene","Pseudomembranous colitis","Food poisoning","Botulism"]'::jsonb, 'Tetanus (lockjaw)', 'Tetanospasmin from C. tetani blocks inhibitory spinal transmission, causing spastic paralysis with trismus or lockjaw.'),
('5af95cd3-b063-5f72-9c0e-3dd8589bf8b1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium tetani is best classified as a:', '["GP spore-forming rod","Spirochete","Acid-fast","GP coccus","GN rod"]'::jsonb, 'GP spore-forming rod', 'C. tetani is a Gram-positive, strictly anaerobic spore-forming rod; its exotoxin tetanospasmin produces tetanus.'),
('7906ce41-b6f1-5c0d-902b-9b35e424da31'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Which option correctly describes Clostridium tetani?', '["GP spore-forming rod","Spirochete","Acid-fast","GP coccus","GN rod"]'::jsonb, 'GP spore-forming rod', 'C. tetani is a Gram-positive anaerobic spore-forming rod found in soil and the gut; terminal spores give it a drumstick appearance.'),
('ce63ece3-8452-561a-94a7-30493094e209'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Microbiology Anaerobic Spirochetes - Anaerobic Spirochetes', 'Clostridium tetani is best described as a:', '["GP spore-forming rod","Spirochete","Acid-fast","GP coccus","GN rod"]'::jsonb, 'GP spore-forming rod', 'C. tetani is a Gram-positive rod forming terminal spores and producing tetanospasmin, the cause of spastic paralysis in tetanus.'),
('b5ae00c2-2a4c-5953-9244-ebd9e49f3cce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV is a:', '["DNA virus","Hepadnavirus","Picornavirus","Retrovirus","Flavivirus"]'::jsonb, 'Picornavirus', 'HAV is a Picornavirus (small, non-enveloped, ssRNA positive-sense).'),
('727787cc-6650-5a61-b4c8-38e8bfd37091'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV belongs to which family:', '["Flaviviridae","Picornaviridae","Retroviridae","Hepadnaviridae","Coronaviridae"]'::jsonb, 'Picornaviridae', 'HAV belongs to Picornaviridae family.'),
('52a3037e-a081-5810-ab90-5547384ad681'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV genome is:', '["dsDNA","ssDNA","dsRNA","ssRNA+ (positive sense)","ssRNA- (negative sense)"]'::jsonb, 'ssRNA+ (positive sense)', 'HAV has a positive-sense single-stranded RNA genome.'),
('7208744a-1d6e-5a46-aa1e-f6a7de541b9c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV transmission is primarily:', '["Sexual","Vertical","Blood/products","Fecal-oral","Respiratory"]'::jsonb, 'Fecal-oral', 'HAV is transmitted via fecal-oral route, often through contaminated food/water.'),
('8ccee85b-a9a1-5935-9eef-8053b70b74ba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV has an incubation period of:', '["1-2 weeks","2-4 weeks","4-6 weeks","6-8 weeks","8-12 weeks"]'::jsonb, '2-4 weeks', 'HAV incubation period is typically 2-4 weeks (average 28 days).'),
('685046bd-a0e7-5d9b-9092-df019b7ac104'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV clinical course is typically:', '["Chronic in 80%","Fulminant in 50%","Self-limited","Asymptomatic always","Progressive liver failure"]'::jsonb, 'Self-limited', 'HAV causes acute self-limited hepatitis; chronic infection does not occur.'),
('fd013223-0dab-59d3-9839-54c4aeba5953'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV chronic carrier state:', '["Common (20%)","Rare but occurs","Does not occur","Only in children","Only in immunocompromised"]'::jsonb, 'Does not occur', 'HAV does NOT cause chronic infection or carrier state.'),
('5f9ad84a-6050-5cbd-b27c-d7ba81394ce6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV vaccine type is:', '["Live attenuated","Inactivated (killed)","Subunit","mRNA","DNA"]'::jsonb, 'Inactivated (killed)', 'HAV vaccine is an inactivated (killed) virus vaccine.'),
('303023d7-2dd8-58d2-8e05-6fb05d91e71b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV vaccine schedule:', '["Single dose","2 doses (0, 6-12 months)","3 doses (0, 1, 6 months)","3 doses (0, 2, 6 months)","Annual boosters"]'::jsonb, '2 doses (0, 6-12 months)', 'HAV vaccine is given as 2 doses, 6-12 months apart.'),
('0d739427-3e4e-5b79-98fd-d9d15dcae4f5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV diagnosis is confirmed by:', '["HAV IgM antibodies","HAV IgG antibodies","HAV RNA PCR","Liver biopsy","HAV antigen"]'::jsonb, 'HAV IgM antibodies', 'HAV IgM antibodies indicate acute/current infection.'),
('1b834343-66da-5c71-82b8-0d557cf10574'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV IgG antibodies indicate:', '["Acute infection","Past infection or vaccination","Chronic infection","Fulminant hepatitis","Carrier state"]'::jsonb, 'Past infection or vaccination', 'HAV IgG indicates immunity from past infection or vaccination.'),
('2c7b0e6d-4870-5c05-ab56-2b120b3194c0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV does NOT cause:', '["Acute hepatitis","Fulminant hepatitis","Chronic hepatitis","Jaundice","Fever"]'::jsonb, 'Chronic hepatitis', 'HAV only causes acute hepatitis; it does NOT cause chronic hepatitis.'),
('17f33b92-1a10-5922-973c-c2e3c33e1ba9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV is most dangerous in:', '["Young adults","Children","Elderly","Pregnant women (elderly)","Immunocompetent"]'::jsonb, 'Elderly', 'HAV mortality is highest in elderly patients (>1% in those >50 years).'),
('9e5825ac-44b4-59fe-9b04-7f4fd1d0d9a8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV outbreaks are associated with:', '["Person-to-person contact only","Contaminated food/water","Blood transfusion","Sexual contact only","Needle sharing"]'::jsonb, 'Contaminated food/water', 'HAV outbreaks often result from contaminated food or water.'),
('2fdcf8ab-e5ca-5fae-a3ff-b0e4bac5c949'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV serology window period:', '["IgM appears before symptoms","IgM appears after symptoms","IgG appears before IgM","No window period","IgM never appears"]'::jsonb, 'IgM appears before symptoms', 'HAV IgM may be detectable before clinical symptoms appear.'),
('f6b92e1d-d2ce-5537-b91b-382ce25ca43f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV prevention in contacts:', '["Antivirals only","Vaccine or IG within 2 weeks","Antibiotics","No prevention needed","Isolation only"]'::jsonb, 'Vaccine or IG within 2 weeks', 'Post-exposure prophylaxis with vaccine or immunoglobulin within 2 weeks.'),
('08c5a7a6-369c-56de-9b45-8e10471e8810'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV in children is typically:', '["Severe with jaundice","Asymptomatic or mild","Fulminant","Chronic","Fatal"]'::jsonb, 'Asymptomatic or mild', 'Most HAV infections in children are asymptomatic or mild.'),
('b16a08b0-15cb-578e-9185-90b00655d14c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV fulminant hepatitis rate:', '["10-20%","5-10%","1-2%","<0.1%","50%"]'::jsonb, '<0.1%', 'Fulminant hepatitis from HAV is rare (<0.1%).'),
('f9172b82-ef2c-50a1-ae7d-fbbe3a9f48b9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV is an enveloped virus:', '["Yes","No","Sometimes","Only in liver cells","Only in blood"]'::jsonb, 'No', 'HAV is a non-enveloped virus.'),
('a7f76b31-0b3b-5ff6-93ac-f10276536dcf'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV mortality rate in developed countries:', '["5-10%","1-5%","0.1-0.3%","10-20%","0%"]'::jsonb, '0.1-0.3%', 'HAV mortality in developed countries is approximately 0.1-0.3%.'),
('3b18334a-7529-57a0-bd89-012314a5f867'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV is endemic in:', '["Developed countries only","Developing countries with poor sanitation","Tropical rainforests only","Arctic regions","All countries equally"]'::jsonb, 'Developing countries with poor sanitation', 'HAV is endemic in areas with poor sanitation and hygiene.'),
('254dd87d-c213-59f1-af2d-acf49d2996ce'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV peak incidence occurs in:', '["Infants","Children (1-9 years)","Young adults (15-25)","Middle-aged (40-50)","Elderly (>60)"]'::jsonb, 'Children (1-9 years)', 'In endemic areas, most infections occur in childhood.'),
('acf56b34-d9f4-5713-afcf-5078a350a17d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV jaundice onset after exposure:', '["1 week","2 weeks","3-4 weeks","6-8 weeks","3 months"]'::jsonb, '3-4 weeks', 'Jaundice typically appears 3-4 weeks after exposure.'),
('c720687f-7227-568a-bac3-4de8f68a20df'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV ALT elevation pattern:', '["Gradual rise over months","Rapid rise then gradual decline","Persistent elevation","No ALT elevation","Only slightly elevated"]'::jsonb, 'Rapid rise then gradual decline', 'ALT rises rapidly, peaks, then gradually returns to normal.'),
('a688bf0e-0edc-5ba4-a34f-eb9a5ace1c3e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV does NOT progress to:', '["Acute hepatitis","Chronic hepatitis","Cirrhosis","Liver failure","Both B and C"]'::jsonb, 'Both B and C', 'HAV does NOT cause chronic hepatitis or cirrhosis.'),
('aa968e9e-c32f-5d51-a32b-680999715193'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV vaccine contraindication:', '["Pregnancy","Previous HAV infection","Elderly","Children","None of the above"]'::jsonb, 'Previous HAV infection', 'HAV vaccine is not indicated for those with prior HAV infection (already immune).'),
('3b7f2908-ef45-5c7a-919e-59659daa1084'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV IgM positivity duration:', '["1-2 weeks","4-8 weeks","3-6 months","1 year","Lifetime"]'::jsonb, '3-6 months', 'HAV IgM typically persists for 3-6 months after acute infection.'),
('648d15a0-ace0-5b7d-9218-9b6cc0cad2e1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV RNA detection method:', '["ELISA","Western blot","RT-PCR","Culture","Microscopy"]'::jsonb, 'RT-PCR', 'HAV RNA is detected by RT-PCR, useful in early infection.'),
('96662db2-0826-5726-9f74-7ed8694b007a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV survival on surfaces:', '["Hours","Days to weeks","Months","Dies immediately","Years"]'::jsonb, 'Days to weeks', 'HAV can survive on surfaces for days to weeks.'),
('f1d66998-9600-5ba6-b43d-5d577ddfb61d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV in immunocompromised patients:', '["Always asymptomatic","May have prolonged viremia","Never causes disease","Only causes chronic infection","Self-limited like in normal hosts"]'::jsonb, 'May have prolonged viremia', 'Immunocompromised patients may have prolonged viremia and viral shedding.'),
('f23093d1-3a13-5c99-9935-5f6d14a216b1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV food handler screening:', '["Required by law","Not routinely recommended","Only if symptomatic","Every 6 months","Only for child care workers"]'::jsonb, 'Only if symptomatic', 'Routine screening of food handlers is not recommended; test only if symptomatic.'),
('f024c3b0-18cc-5e80-bab0-ce71a450b623'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV vaccine efficacy:', '["50-60%","70-80%","80-90%","95-100%","30-40%"]'::jsonb, '95-100%', 'HAV vaccine has >95% efficacy after 2 doses.'),
('a4ccd829-3b15-56bf-bd18-f079e558db44'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV superinfection in chronic HBV:', '["Mild course","No effect on HBV","May cause fulminant hepatitis","Always fatal","Chronic HAV infection"]'::jsonb, 'May cause fulminant hepatitis', 'HAV superinfection in chronic HBV patients may cause fulminant hepatitis.'),
('1faae816-f92a-556c-aac8-9c5630a4fba4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HAV is most infectious:', '["Before symptom onset","After jaundice appears","During convalescence","1 week after symptoms","Never infectious"]'::jsonb, 'Before symptom onset', 'HAV is most infectious in the week before symptom onset.'),
('2e560a94-b429-500c-90b0-a5a32a6bf449'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV is a:', '["Flavivirus resulting in decreased functional activity","Hepadnavirus (partially dsDNA)","DNA linear mediated by specific receptor activation","Picornavirus without affecting the primary tissue pathway","Retrovirus leading to subsequent cellular adaptation"]'::jsonb, 'Hepadnavirus (partially dsDNA)', 'HBV is a Hepadnavirus with partially double-stranded circular DNA.'),
('097b7a99-a2ae-52a1-83a6-3a91139bc1d9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV genome is:', '["ssRNA+ resulting in decreased functional activity","ssRNA- accompanied by associated clinical symptoms","dsRNA mediated by specific receptor activation","Partially dsDNA (relaxed circular)","ssDNA leading to subsequent cellular adaptation"]'::jsonb, 'Partially dsDNA (relaxed circular)', 'HBV has a partially double-stranded circular DNA genome.'),
('71b5ed34-617f-5ef3-a923-b17a4ae230c8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV replication involves:', '["RNA-dependent RNA polymerase","Reverse transcriptase (RNA->DNA)","DNA-dependent DNA polymerase only","No polymerase needed","RNA polymerase only"]'::jsonb, 'Reverse transcriptase (RNA->DNA)', 'HBV uses reverse transcriptase to convert pregenomic RNA to DNA.'),
('aa163504-5d00-576d-ba0e-c01588baa85d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBsAg indicates:', '["Vaccination","Recovery","Past infection","Immunity","Current infection"]'::jsonb, 'Current infection', 'HBsAg positivity indicates current HBV infection (acute or chronic).'),
('165ba899-6f9e-56ec-8dc3-bae588079fb9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBsAg positivity for >6 months indicates:', '["Acute infection","Chronic infection","Resolution","Immunity","Carrier only"]'::jsonb, 'Chronic infection', 'HBsAg persistence >6 months defines chronic HBV infection.'),
('e38d491a-13fc-53c0-a032-a7671b0fa91c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBeAg indicates:', '["Recovery","Past infection","Active replication","Carrier","Vaccination"]'::jsonb, 'Active replication', 'HBeAg indicates active viral replication and high infectivity.'),
('55945401-2548-5a39-a233-f2a35ee9c9f8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Anti-HBe indicates:', '["Active replication","Seroconversion (lower replication)","Acute infection","Vaccination","No infection"]'::jsonb, 'Seroconversion (lower replication)', 'Anti-HBe seroconversion indicates decreased viral replication.'),
('d7d0d8ca-67ab-5951-b031-19ab7f44cf8b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Anti-HBs indicates:', '["High infectivity resulting in decreased functional activity","Active infection accompanied by associated clinical symptoms","Chronic mediated by specific receptor activation","Immunity (recovery/vaccination)","None leading to subsequent cellular adaptation"]'::jsonb, 'Immunity (recovery/vaccination)', 'Anti-HBs indicates immunity from recovery or vaccination.'),
('080f429a-b97d-5783-b289-9576dd6228e7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Anti-HBc IgM indicates:', '["Chronic infection","Past infection","Acute infection","Vaccination","Immunity"]'::jsonb, 'Acute infection', 'Anti-HBc IgM is the marker of acute HBV infection.'),
('139bb003-d31e-5ce2-8639-465be1237512'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Anti-HBc total (IgM + IgG) indicates:', '["Acute infection only","Past or current infection","Vaccination","Immunity only","No infection"]'::jsonb, 'Past or current infection', 'Anti-HBc total indicates exposure to HBV (past or current).'),
('b64e81e1-7e22-572b-9c1b-87492ed4212e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Dane particle is:', '["Core only","Non-infectious particle","HBsAg only","Complete HBV (42 nm)","Envelope only"]'::jsonb, 'Complete HBV (42 nm)', 'Dane particle is the complete infectious HBV virion (42 nm).'),
('a99224d4-2c49-58e6-bc8c-72dd7a4f41fb'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV vaccine contains:', '["Whole inactivated virus","Live attenuated virus","Recombinant HBsAg","HBV DNA","Virus-like particle"]'::jsonb, 'Recombinant HBsAg', 'HBV vaccine is recombinant HBsAg (surface antigen).'),
('330b81bc-da83-5469-82ab-395ef356cec7'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV vaccine schedule (adults):', '["Single dose","2 doses","3 doses (0, 1, 6 months)","4 doses","Annual boosters"]'::jsonb, '3 doses (0, 1, 6 months)', 'HBV vaccine is given as 3 doses: 0, 1, and 6 months.'),
('8059b2f5-6b80-505e-9ce9-ac300f2e051d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Chronic HBV treatment first-line:', '["Ribavirin","Interferon only","Acyclovir","Tenofovir or entecavir","No treatment available"]'::jsonb, 'Tenofovir or entecavir', 'Nucleos(t)ide analogues (tenofovir/entecavir) are first-line for chronic HBV.'),
('df97200e-b85c-504c-8ee0-f96c743f866d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV is transmitted by:', '["Fecal-oral","Blood/products, sexual, vertical","Respiratory","Mosquito bite","Food contamination"]'::jsonb, 'Blood/products, sexual, vertical', 'HBV is transmitted via blood, sexual contact, and perinatally.'),
('5a13d90f-ec0d-55b6-a06f-0832257b43ca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV incubation period:', '["1-2 weeks","2-4 weeks","6 weeks to 6 months","6-12 months","1-2 years"]'::jsonb, '6 weeks to 6 months', 'HBV incubation period is 6 weeks to 6 months (average 2-3 months).'),
('272de1fe-21fb-55ac-8b07-c3f65c734a07'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV does NOT cause:', '["Acute hepatitis","Chronic hepatitis","Cirrhosis","Hepatocellular carcinoma","Pancreatitis"]'::jsonb, 'Pancreatitis', 'HBV does not cause pancreatitis; it affects the liver.'),
('0cee3e32-054e-5b09-a20a-b23c4bb41bdd'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HBV associated with hepatocellular carcinoma:', '["No association","Weak association","Strong association","Only in alcoholics","Only in children"]'::jsonb, 'Strong association', 'HBV is a major cause of hepatocellular carcinoma (HCC).'),
