('4cf21f94-325a-5591-a459-5206d0526fa9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV NNRTIs mechanism:', '["Bind to active site of RT","Bind to allosteric site of RT","Inhibit protease","Inhibit integrase","Block viral entry"]'::jsonb, 'Bind to allosteric site of RT', 'NNRTIs bind to allosteric site of reverse transcriptase.'),
('98c96234-025a-56ac-b5e7-e4914d13b3c2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV INSTIs mechanism:', '["Inhibit reverse transcriptase resulting in decreased functional activity","Inhibit viral protease accompanied by associated clinical symptoms","Block integration of viral DNA into host chromosome","Block viral entry without affecting the primary tissue pathway","Inhibit viral release leading to subsequent cellular adaptation"]'::jsonb, 'Block integration of viral DNA into host chromosome', 'INSTIs block integrase-mediated integration of viral DNA.'),
