('3a3e76f8-5185-5da4-8f4b-9a7c879ba4c5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV window period (4th gen ELISA):', '["1-2 weeks","2-4 weeks","3-4 weeks","2-3 months","6 months"]'::jsonb, '3-4 weeks', '4th generation ELISA can detect infection 3-4 weeks after exposure.'),
('a3334fb0-5cbd-5d19-ac76-1607e5df990b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV p24 antigen appears:', '["After antibodies","Before antibodies (1-2 weeks)","Simultaneously with antibodies","Never","Only in AIDS"]'::jsonb, 'Before antibodies (1-2 weeks)', 'p24 antigen appears 1-2 weeks after infection, before antibodies.'),
('9febf96b-de0c-572b-bd9d-ca391395c413'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV Western blot detects:', '["Viral RNA resulting in decreased functional activity","Viral DNA accompanied by associated clinical symptoms","Antibodies to viral proteins","p24 antigen without affecting the primary tissue pathway","CD4 count leading to subsequent cellular adaptation"]'::jsonb, 'Antibodies to viral proteins', 'Western blot detects antibodies to specific HIV proteins.'),
('38f793e2-4c55-5fbd-971b-ef424173aa65'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV elite controllers:', '["Require treatment resulting in decreased functional activity","Spontaneously control viral load without treatment","Progress rapidly mediated by specific receptor activation","Never develop antibodies without affecting the primary tissue pathway","Have high viral load leading to subsequent cellular adaptation"]'::jsonb, 'Spontaneously control viral load without treatment', 'Elite controllers maintain undetectable viral load without ART.'),
('fd315b79-5ebd-5d75-b66b-e7dd491ea799'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV viral set point:', '["Immediate after infection","Stable viral load after acute phase","Only in AIDS","After treatment","During window period"]'::jsonb, 'Stable viral load after acute phase', 'Set point is the stable viral load reached after acute infection.'),
('1e45e197-29af-5076-8364-aa906697eaff'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV acute retroviral syndrome:', '["Always asymptomatic resulting in decreased functional activity","Flu-like illness 2-4 weeks after exposure","Only in AIDS mediated by specific receptor activation","Never occurs without affecting the primary tissue pathway","Only in children leading to subsequent cellular adaptation"]'::jsonb, 'Flu-like illness 2-4 weeks after exposure', 'Acute retroviral syndrome presents with fever, rash, lymphadenopathy.'),
('d869e8f7-944f-51ce-8292-338dfb807e1b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV clinical latency period:', '["1-2 weeks resulting in decreased functional activity","2-4 weeks accompanied by associated clinical symptoms","8-10 years (without treatment)","1-2 years without affecting the primary tissue pathway","Lifetime leading to subsequent cellular adaptation"]'::jsonb, '8-10 years (without treatment)', 'Clinical latency averages 8-10 years without treatment.'),
('3ae9b48e-7817-56b3-b33d-45720f257461'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV AIDS-defining illnesses include:', '["PCP pneumonia","Kaposi sarcoma","Toxoplasmosis","All of the above","Common cold"]'::jsonb, 'All of the above', 'PCP, KS, toxoplasmosis are AIDS-defining illnesses.'),
('bedcb038-e148-5f6e-aa13-2c8ccd661ac3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV wasting syndrome:', '["Weight loss >10% + chronic diarrhea/fever","Weight gain accompanied by associated clinical symptoms","Only in treated patients mediated by specific receptor activation","Never occurs without affecting the primary tissue pathway","Only in children leading to subsequent cellular adaptation"]'::jsonb, 'Weight loss >10% + chronic diarrhea/fever', 'Wasting syndrome: >10% weight loss with chronic diarrhea or fever.'),
('ed29edc8-02d1-59e4-b76e-f77c8c2594e3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV dementia (HAD):', '["Never occurs","Progressive dementia in advanced HIV","Only in children","Only with treatment","Mild and reversible"]'::jsonb, 'Progressive dementia in advanced HIV', 'HIV-associated dementia occurs in advanced HIV disease.'),
('cfa723f8-1afe-575e-8d8e-9a2ac59dca6e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and tuberculosis co-infection:', '["TB risk increases with lower CD4","TB is most common OI worldwide in HIV","ART should be started in all co-infected","All of the above","No interaction"]'::jsonb, 'All of the above', 'TB is the most common OI in HIV; risk increases with immunosuppression.'),
('2c355889-d5df-5468-b012-1416c0dcb376'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV treatment goal:', '["Cure HIV resulting in decreased functional activity","Undetectable viral load + immune reconstitution","CD4 >500 only mediated by specific receptor activation","Symptom control only without affecting the primary tissue pathway","Prevent transmission only leading to subsequent cellular adaptation"]'::jsonb, 'Undetectable viral load + immune reconstitution', 'ART goals: viral suppression, immune reconstitution, prevent transmission.'),
('0491d376-c767-52ba-b8fb-c8e96cc01ab9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV undetectable = untransmittable (U=U):', '["False resulting in decreased functional activity","True - sustained undetectable viral load prevents sexual transmission","Only for heterosexual mediated by specific receptor activation","Only for MSM without affecting the primary tissue pathway","Only with condoms leading to subsequent cellular adaptation"]'::jsonb, 'True - sustained undetectable viral load prevents sexual transmission', 'U=U: sustained undetectable viral load effectively prevents sexual transmission.'),
('9dd7f205-3036-50c6-b831-d939d6da6ac0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV drug resistance testing:', '["Not available","Genotypic resistance testing","Phenotypic resistance testing","Both B and C","Not needed"]'::jsonb, 'Both B and C', 'Both genotypic and phenotypic resistance testing are available.'),
('1acfe6f8-4d68-5c35-8c90-07dd661e95a3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV pre-exposure prophylaxis for serodiscordant couples:', '["Not recommended","Recommended for HIV-negative partner","Only for the positive partner","Only during pregnancy","Only for MSM"]'::jsonb, 'Recommended for HIV-negative partner', 'PrEP is recommended for HIV-negative partner in serodiscordant couples.'),
('0101b5ab-5bb7-5fd9-9460-ef1e2c2a0446'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and pregnancy:', '["ART reduces vertical transmission to <1%","Cesarean always required","Breastfeeding contraindicated","No treatment during pregnancy","Vertical transmission 100%"]'::jsonb, 'ART reduces vertical transmission to <1%', 'With proper ART, vertical transmission rate is <1%.'),
('8696efb8-f771-5218-a82b-16ee8b7e1724'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and breastfeeding:', '["Always contraindicated","Recommended in resource-limited settings with ART","Only formula feeding","Only in developed countries","No risk of transmission"]'::jsonb, 'Recommended in resource-limited settings with ART', 'In resource-limited settings, breastfeeding with ART is recommended.'),
('0366701f-fe64-5c96-b90f-6b1b897d5998'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV elite controller percentage:', '["10-15%","5-10%","<5% (<1%)","50%","0%"]'::jsonb, '<5% (<1%)', 'Elite controllers represent <5% (likely <1%) of HIV-infected individuals.'),
('21afe3e8-d392-5527-b9cf-6c0a8af37274'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and hepatitis coinfection:', '["No interaction","HIV accelerates HBV/HCV progression","Higher risk of cirrhosis","All of the above","HBV/HCV worsens HIV"]'::jsonb, 'All of the above', 'HIV accelerates HBV/HCV progression and increases cirrhosis risk.'),
('eb8e8c7c-6410-54af-b741-e225422a0858'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and HPV-related cancers:', '["No increased risk","Increased risk of cervical/anal cancer","Only in women","Only with CD4 >200","Only with treatment"]'::jsonb, 'Increased risk of cervical/anal cancer', 'HIV increases risk of HPV-related cancers (cervical, anal, oropharyngeal).'),
('bbe2b50b-246b-5ea3-a5d9-602cd6a41adc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV viral blip:', '["Treatment failure resulting in decreased functional activity","Transient low-level viremia in treated patients","Always significant mediated by specific receptor activation","Requires treatment change without affecting the primary tissue pathway","Only with NNRTIs leading to subsequent cellular adaptation"]'::jsonb, 'Transient low-level viremia in treated patients', 'Viral blips are transient increases that often self-resolve.'),
('dc183639-7ece-56a2-ae69-a933253e596d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV CD4/CD8 ratio inversion:', '["Normal resulting in decreased functional activity","Indicates immune activation/dysfunction","Only in AIDS mediated by specific receptor activation","Only with treatment without affecting the primary tissue pathway","Never occurs leading to subsequent cellular adaptation"]'::jsonb, 'Indicates immune activation/dysfunction', 'CD4/CD8 inversion (<1) indicates immune activation/dysfunction.'),
('5469f6e2-9afa-56a4-ad6e-29673db87c32'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV treatment simplification:', '["Not recommended","Single-tablet regimens improve adherence","Only for treatment-naive","Only for treatment-experienced","Not available"]'::jsonb, 'Single-tablet regimens improve adherence', 'Single-tablet regimens improve adherence and outcomes.'),
('0d10d5ca-2e6b-5dfb-8859-470aee6f8457'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV tenofovir renal toxicity:', '["Never occurs","Rare, monitor renal function","Common","Only with old formulation","Only in elderly"]'::jsonb, 'Rare, monitor renal function', 'Tenofovir can cause renal toxicity; monitor renal function.'),
('f7801ee7-54d5-5f93-8127-1bb38dcfb218'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV abacavir hypersensitivity:', '["Common (10%)","HLA-B*5701 associated","Only in Africans","Mild","Never occurs"]'::jsonb, 'HLA-B*5701 associated', 'Abacavir hypersensitivity is associated with HLA-B*5701 allele.'),
('47e94596-f085-536f-9290-b2aeb7d87ad2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and bone density:', '["No effect resulting in decreased functional activity","Increased risk of osteopenia/osteoporosis","Only with TDF mediated by specific receptor activation","Only with PIs without affecting the primary tissue pathway","Only in elderly leading to subsequent cellular adaptation"]'::jsonb, 'Increased risk of osteopenia/osteoporosis', 'HIV and some ART drugs increase risk of bone density loss.'),
('5a293499-c07a-5bb6-a587-c703f52604bc'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and cardiovascular risk:', '["No increased risk resulting in decreased functional activity","Increased risk of cardiovascular disease","Only with PIs mediated by specific receptor activation","Only with NRTIs without affecting the primary tissue pathway","Only in elderly leading to subsequent cellular adaptation"]'::jsonb, 'Increased risk of cardiovascular disease', 'HIV infection and some ART drugs increase cardiovascular risk.'),
('76e529a4-d8af-5ec1-bf8b-d98a44fdb1ec'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and neurocognitive disorder:', '["Never occurs","Common even with suppressed viral load","Only with CD4 <200","Only without treatment","Only in elderly"]'::jsonb, 'Common even with suppressed viral load', 'HIV-associated neurocognitive disorders can occur despite viral suppression.'),
('22d3970a-c4b0-5a23-996d-471a0328cb07'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and metabolic syndrome:', '["No association","Increased risk with ART","Only with PIs","Only with NRTIs","Only in obese"]'::jsonb, 'Increased risk with ART', 'ART is associated with increased metabolic syndrome risk.'),
('22c8f06b-46e3-5cf6-ae9e-d4596716d156'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and immune reconstitution inflammatory syndrome (IRIS):', '["Never occurs resulting in decreased functional activity","Paradoxical worsening after starting ART","Only with TB mediated by specific receptor activation","Only with CMV without affecting the primary tissue pathway","Only in advanced AIDS leading to subsequent cellular adaptation"]'::jsonb, 'Paradoxical worsening after starting ART', 'IRIS is paradoxical clinical worsening after ART initiation.'),
('5dab3691-e2a3-54f5-89cb-8ba6de7c6bca'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and Kaposi sarcoma:', '["No association","HHV-8 associated, common in AIDS","Only with CD4 >200","Only in women","Only with treatment"]'::jsonb, 'HHV-8 associated, common in AIDS', 'KS is caused by HHV-8 and is an AIDS-defining illness.'),
('d4450907-1f86-505c-9965-283da028a048'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and cryptococcal meningitis:', '["Common with CD4 <100","Only in children","Only in elderly","Only with treatment","Never occurs"]'::jsonb, 'Common with CD4 <100', 'Cryptococcal meningitis is common when CD4 <100 cells/mm3.'),
('1a70123b-1dc6-57a1-9b23-39b92cd7e00a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV and PML (progressive multifocal leukoencephalopathy):', '["Never occurs resulting in decreased functional activity","JC virus reactivation in immunosuppressed","Only with CD4 >200 mediated by specific receptor activation","Only in elderly without affecting the primary tissue pathway","Only with treatment leading to subsequent cellular adaptation"]'::jsonb, 'JC virus reactivation in immunosuppressed', 'PML is caused by JC virus reactivation in severely immunosuppressed.'),
('5a49459a-b8ce-5e2f-a6a3-97ee34e1ce3e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HIV wasting syndrome criteria:', '["Weight loss <5% resulting in decreased functional activity","Weight loss >10% + chronic diarrhea/fever","Weight gain mediated by specific receptor activation","Only with treatment without affecting the primary tissue pathway","Never occurs leading to subsequent cellular adaptation"]'::jsonb, 'Weight loss >10% + chronic diarrhea/fever', 'Wasting syndrome: involuntary weight loss >10% with chronic diarrhea or fever.'),
('3a84ad33-41a7-5862-8c13-e895c76fc42f'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HSV encephalitis treated with:', '["Oral acyclovir","High-dose IV acyclovir","Ganciclovir","Foscarnet","Cidofovir"]'::jsonb, 'High-dose IV acyclovir', 'HSV encephalitis is a medical emergency requiring high-dose IV acyclovir.'),
('29d1b5c6-94c8-5e83-935f-325449217100'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HSV-1 primary infection treated with:', '["Ribavirin","Acyclovir","Ganciclovir","Foscarnet","Cidofovir"]'::jsonb, 'Acyclovir', 'Acyclovir is first-line for HSV-1 and HSV-2 infections.'),
('0e8e81fb-9b48-5129-a295-6edd98ad9c9b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HSV-2 primarily causes:', '["Oral herpes","Genital herpes","Encephalitis","Chickenpox","Shingles"]'::jsonb, 'Genital herpes', 'HSV-2 primarily causes genital herpes.'),
('d4a8c89c-f40d-55be-beaa-36b943a3465b'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HSV latency site:', '["Spinal cord","Sensory ganglia","Brain","Blood","Liver"]'::jsonb, 'Sensory ganglia', 'HSV establishes latency in sensory ganglia (trigeminal for HSV-1, sacral for HSV-2).'),
('2b156738-94df-5b38-a4f4-7b153c789aba'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HSV encephalitis typically affects:', '["Cerebellum","Brainstem","Temporal lobe","Occipital lobe","Spinal cord"]'::jsonb, 'Temporal lobe', 'HSV encephalitis typically affects the temporal lobe.'),
('5455a3fe-b316-542f-8b04-e1c25c626cd1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'VZV (chickenpox) treated with:', '["Ribavirin","Ganciclovir","Acyclovir","Foscarnet","Cidofovir"]'::jsonb, 'Acyclovir', 'Acyclovir is first-line for VZV infections.'),
('4a402b10-1375-5377-ba3d-7444906e1fb2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'VZV vaccine type:', '["Inactivated resulting in decreased functional activity","Subunit accompanied by associated clinical symptoms","Live attenuated varicella","mRNA without affecting the primary tissue pathway","DNA leading to subsequent cellular adaptation"]'::jsonb, 'Live attenuated varicella', 'VZV vaccine (Varivax) is a live attenuated vaccine.'),
('dbcbf1ea-2bda-5ede-80ee-0d51f0de0879'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'VZV causes:', '["Oral herpes","Genital herpes","Chickenpox + zoster","Mononucleosis","CMV disease"]'::jsonb, 'Chickenpox + zoster', 'VZV causes chickenpox (primary) and shingles (reactivation).'),
('bb22e83e-187a-5cf8-a6c6-0a6ebdbc685d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Herpes zoster (shingles) treated with:', '["Ribavirin","Ganciclovir","Foscarnet","Acyclovir or valacyclovir","Cidofovir"]'::jsonb, 'Acyclovir or valacyclovir', 'Acyclovir or valacyclovir; start within 72 hours for best results.'),
('a0cbca87-9702-587c-8ab4-cfe19eb57e6e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Ramsay Hunt syndrome:', '["HHV-6","HSV encephalitis","CMV retinitis","VZV geniculate ganglion","EBV mono"]'::jsonb, 'VZV geniculate ganglion', 'Ramsay Hunt is caused by VZV reactivation in geniculate ganglion.'),
('f6167e7f-50af-56f8-a202-c0bcb76629a9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'CMV treatment:', '["Acyclovir","Ganciclovir","Ribavirin","Oseltamivir","Amantadine"]'::jsonb, 'Ganciclovir', 'Ganciclovir is first-line for CMV disease.');
insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('cf11d29c-f79c-5127-8aa7-4fcb01e3d016'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'CMV retinitis occurs at CD4:', '["<200 cells/mm3","<100 cells/mm3","<50 cells/mm3","<350 cells/mm3","<500 cells/mm3"]'::jsonb, '<50 cells/mm3', 'CMV retinitis occurs with severe immunosuppression (CD4 <50).'),
('4927e8d3-6d13-5ffc-8479-587d63dbaec4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'CMV causes:', '["Chickenpox resulting in decreased functional activity","Oral herpes accompanied by associated clinical symptoms","Congenital infection, retinitis","Genital herpes without affecting the primary tissue pathway","Mono leading to subsequent cellular adaptation"]'::jsonb, 'Congenital infection, retinitis', 'CMV causes congenital infection and retinitis in immunocompromised.'),
('f6505680-09ca-5cd9-a877-35db3c302aee'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Ganciclovir first-line for:', '["HSV encephalitis resulting in decreased functional activity","CMV disease (retinitis, pneumonitis)","VZV infections mediated by specific receptor activation","EBV infections without affecting the primary tissue pathway","HHV-6 leading to subsequent cellular adaptation"]'::jsonb, 'CMV disease (retinitis, pneumonitis)', 'Ganciclovir is first-line for CMV disease in immunocompromised.'),
('3db63e03-eb7b-511d-ae89-15890fcd63e1'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Acyclovir activated by:', '["Cellular thymidine kinase","Viral thymidine kinase","Viral DNA polymerase","Alkaline phosphatase","HIV protease"]'::jsonb, 'Viral thymidine kinase', 'Acyclovir requires viral thymidine kinase for initial phosphorylation.'),
('7d7093b6-1083-59db-b400-58b90e304d43'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Valacyclovir advantage over acyclovir:', '["Broader spectrum","Less nephrotoxicity","Prodrug with better oral bioavailability","Longer half-life only","IV available"]'::jsonb, 'Prodrug with better oral bioavailability', 'Valacyclovir is a prodrug with 55% bioavailability vs 15-30% for acyclovir.'),
('06246e86-4b3b-538d-b6d7-f8c05930ed58'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'EBV causes:', '["Chickenpox","Genital herpes","Infectious mononucleosis","CMV retinitis","Roseola"]'::jsonb, 'Infectious mononucleosis', 'EBV is the primary cause of infectious mononucleosis.'),
('a81d9433-a0e5-5718-8e26-606d2d88381d'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'EBV-associated cancers:', '["Cervical, KS","HCC, Glioma","Burkitt, NPC, PTLD","Breast, Lung","Prostate, Colon"]'::jsonb, 'Burkitt, NPC, PTLD', 'EBV is associated with Burkitt lymphoma, NPC, and PTLD.'),
('93a4e354-83bf-5cc3-8bde-2f50bb82153a'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Monospot test detects:', '["EBV PCR","CXR","Heterophile antibody","Serology","Culture"]'::jsonb, 'Heterophile antibody', 'Monospot detects heterophile antibodies in infectious mononucleosis.'),
('89d13d2c-0a27-57a7-824c-2568d119c937'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HHV-6 causes:', '["Genital herpes resulting in decreased functional activity","CMV accompanied by associated clinical symptoms","Mono mediated by specific receptor activation","Roseola infantum (exanthem subitum)","Chickenpox leading to subsequent cellular adaptation"]'::jsonb, 'Roseola infantum (exanthem subitum)', 'HHV-6 is the primary cause of roseola infantum.'),
('1916ea46-53c4-5cc7-8e52-769f183728da'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Roseola presentation:', '["Rash then fever","High fever then rash","Continuous fever","Rash only","Fever only"]'::jsonb, 'High fever then rash', 'Roseola: high fever for 3-5 days, then rash appears as fever resolves.'),
('918891b3-1423-5d9d-9900-ad3fb51cd319'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HHV-8 causes:', '["Roseola","Mono","Chickenpox","Kaposi sarcoma","Genital herpes"]'::jsonb, 'Kaposi sarcoma', 'HHV-8 is the causative agent of Kaposi sarcoma.'),
('6da81f2f-030a-5494-b6d3-bd07cf952cb2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HHV-7 is associated with:', '["Genital herpes only","Mono only","Chickenpox only","Roseola (also HHV-6)","KS only"]'::jsonb, 'Roseola (also HHV-6)', 'HHV-7, like HHV-6, is associated with roseola.'),
('58c1699d-f1d6-5ca0-ada7-2112dcb550a6'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Kaposi sarcoma is caused by:', '["HSV resulting in decreased functional activity","EBV accompanied by associated clinical symptoms","CMV mediated by specific receptor activation","HHV-8 in AIDS/transplant","VZV leading to subsequent cellular adaptation"]'::jsonb, 'HHV-8 in AIDS/transplant', 'KS is caused by HHV-8, especially in AIDS and transplant patients.'),
('35c0be3a-17d5-59a7-9667-17a2328817b0'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'CMV in transplant recipients:', '["No risk","Major cause of morbidity/mortality","Only in bone marrow transplant","Only in kidney transplant","Only in liver transplant"]'::jsonb, 'Major cause of morbidity/mortality', 'CMV is a major cause of morbidity and mortality in transplant recipients.'),
('aecec68e-5e79-5766-b091-e1fd499574e3'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'HSV-1 oral herpes recurrent episodes:', '["Always severe","Usually milder than primary","Same as primary","Never recur","Only in immunocompromised"]'::jsonb, 'Usually milder than primary', 'Recurrent HSV-1 oral herpes is usually milder than primary infection.'),
('ca5188e3-ffdf-542e-ad39-7841c37a7d5c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'VZV reactivation (shingles) risk factors:', '["Age >50","Immunosuppression","Stress","All of the above","None"]'::jsonb, 'All of the above', 'Risk factors include age, immunosuppression, and stress.'),
('732b59e0-5343-5a71-a900-c3cd9a9ba19e'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Shingrix vaccine type:', '["Live attenuated","Inactivated","Recombinant zoster vaccine","Subunit","mRNA"]'::jsonb, 'Recombinant zoster vaccine', 'Shingrix is a recombinant zoster vaccine (non-live).'),
('529e2ed0-2dba-5227-a959-8605b371f2b9'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'CMV congenital infection:', '["Always symptomatic","Most commonly asymptomatic","Always fatal","Only in first trimester","Only in third trimester"]'::jsonb, 'Most commonly asymptomatic', 'Most congenital CMV infections are asymptomatic.'),
('f04b6d00-56ee-5212-9422-f507de513bc5'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'CMV mononucleosis vs EBV mononucleosis:', '["Identical presentation","Heterophile antibody positive in CMV","Heterophile antibody negative in CMV","CMV causes jaundice, EBV does not","EBV causes rash, CMV does not"]'::jsonb, 'Heterophile antibody negative in CMV', 'CMV mononucleosis is heterophile-negative; EBV is heterophile-positive.'),
('996f5144-0183-5d35-9a24-0788fb0801b8'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 1', 'Acyclovir mechanism of action:', '["Inhibits viral entry","Inhibits viral DNA polymerase (chain terminator)","Inhibits viral RNA polymerase","Inhibits viral protease","Inhibits viral release"]'::jsonb, 'Inhibits viral DNA polymerase (chain terminator)', 'Acyclovir triphosphate inhibits viral DNA polymerase and acts as chain terminator.'),
