('db039d0a-fc3a-53fe-97d2-48c5ba1d7e7c'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'COVID-19 long COVID:', '["Never occurs resulting in decreased functional activity","Persistent symptoms >4 weeks after acute infection","Only in severe cases mediated by specific receptor activation","Only in elderly without affecting the primary tissue pathway","Only in unvaccinated leading to subsequent cellular adaptation"]'::jsonb, 'Persistent symptoms >4 weeks after acute infection', 'Long COVID: persistent symptoms lasting weeks to months.'),
('007b08cf-9202-529f-9d46-8ae7624543d2'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'Regarding clinical cases in Virology Pt2: HCV in IV drug users chronicity rate:', '["10%","30%","50%","70-85%","100%"]'::jsonb, '70-85%', 'IV drug users have similar chronicity rates to general population.'),
