('1d268581-76b1-55b7-a226-494f33604401'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'COVID-19 testing window period:', '["1 day","3-5 days after exposure","2 weeks","1 month","No window period"]'::jsonb, '3-5 days after exposure', 'RT-PCR positive 3-5 days after exposure; antigen tests 5-7 days.'),
('70e85fea-eb45-54c4-bb54-392dd72a6909'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'COVID-19 RT-PCR Ct value:', '["Higher Ct = higher viral load","Lower Ct = higher viral load","No correlation","Not important","Same for all patients"]'::jsonb, 'Lower Ct = higher viral load', 'Lower Ct value indicates higher viral load.'),
