('e2e8baeb-0ae4-5cee-bbc8-2748b6cd0517'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'Influenza HA highly pathogenic:', '["Multiple basic amino acids at cleavage site","Single basic amino acid accompanied by associated clinical symptoms","No cleavage site mediated by specific receptor activation","Only in H5N1 without affecting the primary tissue pathway","Only in H7N9 leading to subsequent cellular adaptation"]'::jsonb, 'Multiple basic amino acids at cleavage site', 'HPAI strains have polybasic cleavage site cleaved by furin.'),
('7213fb42-06ca-5339-b8a7-f0ceeb81f3d4'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'Influenza NS1 protein:', '["Structural protein resulting in decreased functional activity","Antagonizes host interferon response","Hemagglutinin mediated by specific receptor activation","Neuraminidase without affecting the primary tissue pathway","Polymerase leading to subsequent cellular adaptation"]'::jsonb, 'Antagonizes host interferon response', 'NS1 counteracts host antiviral interferon response.'),
('ea0232dc-e45a-55cb-bc7e-04937b47b007'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'Influenza M1 protein:', '["Surface glycoprotein","Matrix protein (structural)","Polymerase","Protease","Integrase"]'::jsonb, 'Matrix protein (structural)', 'M1 is the matrix protein lining the viral envelope.'),
('09e33d90-c3af-52b2-bef5-22eb2e419c18'::uuid, 'General Pathology Microbiology Immunology (Paper 2)', 'Virology - Virology Part 2', 'Influenza NEP/NS2 protein:', '["Hemagglutinin resulting in decreased functional activity","Nuclear export protein (vRNP export)","Neuraminidase mediated by specific receptor activation","Protease without affecting the primary tissue pathway","Integrase leading to subsequent cellular adaptation"]'::jsonb, 'Nuclear export protein (vRNP export)', 'NEP/NS2 mediates nuclear export of viral ribonucleoproteins.'),
